window.STORY_BANK = [{"level": "A1", "genre": "neutral", "title": "A Quiet Morning", "paragraphs": ["Ana wakes up early. She opens the window. The sun is bright.", "She drinks tea and eats bread. The kitchen is small and clean. She likes her quiet morning.", "Ana walks to work. The street is calm. She feels happy today."], "paragraphs_pt": ["Ana acorda cedo. Ela abre a janela. O sol está forte.", "Ela toma chá e come pão. A cozinha é pequena e limpa. Ela gosta da manhã tranquila.", "Ana caminha para o trabalho. A rua está calma. Ela se sente feliz hoje."], "hard_words": ["bright", "calm", "quiet"], "vocab": [{"word": "wake up", "meaning": "acordar", "note": ""}, {"word": "window", "meaning": "janela", "note": ""}, {"word": "sun", "meaning": "sol", "note": ""}, {"word": "tea", "meaning": "chá", "note": ""}, {"word": "bread", "meaning": "pão", "note": ""}, {"word": "kitchen", "meaning": "cozinha", "note": ""}, {"word": "street", "meaning": "rua", "note": ""}, {"word": "happy", "meaning": "feliz", "note": ""}], "word_meanings": [{"word": "bright", "meaning": "forte/brilhante", "note": "usado aqui para a luz do sol"}, {"word": "calm", "meaning": "calma", "note": ""}, {"word": "quiet", "meaning": "tranquila", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present - to be", "explanation_pt": "Usamos 'is' com he/she/it, como em 'The sun is bright'."}], "multiple_choice": [{"question": "When does Ana wake up?", "options": ["Late at night", "Early", "At noon", "In the afternoon"], "correct_index": 1, "explanation": "O texto diz 'Ana wakes up early'."}, {"question": "What does Ana drink?", "options": ["Coffee", "Juice", "Tea", "Milk"], "correct_index": 2, "explanation": "Ela toma chá (tea)."}, {"question": "How is the kitchen?", "options": ["Big and dirty", "Small and clean", "Cold and dark", "Old and ugly"], "correct_index": 1, "explanation": "A cozinha é pequena e limpa."}, {"question": "How is the street?", "options": ["Noisy", "Busy", "Calm", "Dangerous"], "correct_index": 2, "explanation": "A rua está calma."}, {"question": "How does Ana feel today?", "options": ["Sad", "Tired", "Angry", "Happy"], "correct_index": 3, "explanation": "Ela se sente feliz hoje."}], "open_questions": [{"question": "What do you usually do in the morning?", "key_points_pt": ["descrever a rotina", "usar verbos no presente"]}, {"question": "Do you like quiet mornings? Why?", "key_points_pt": ["dar uma opinião simples", "usar 'because' se possível"]}]}}, {"level": "A1", "genre": "humor", "title": "The Funny Dog", "paragraphs": ["Max is a big dog. He always makes funny faces. He jumps on the sofa every day.", "Today Max steals a sock. He runs around the house. The family laughs a lot.", "Max hides the sock under the bed. Everyone looks for it. In the end, they laugh together."], "paragraphs_pt": ["Max é um cachorro grande. Ele sempre faz caras engraçadas. Ele pula no sofá todos os dias.", "Hoje Max rouba uma meia. Ele corre pela casa. A família ri muito.", "Max esconde a meia embaixo da cama. Todos procuram por ela. No final, eles riem juntos."], "hard_words": ["steals", "hides", "sofa"], "vocab": [{"word": "dog", "meaning": "cachorro", "note": ""}, {"word": "funny", "meaning": "engraçado", "note": ""}, {"word": "jump", "meaning": "pular", "note": ""}, {"word": "sofa", "meaning": "sofá", "note": ""}, {"word": "steal", "meaning": "roubar", "note": ""}, {"word": "sock", "meaning": "meia", "note": ""}, {"word": "laugh", "meaning": "rir", "note": ""}, {"word": "hide", "meaning": "esconder", "note": ""}], "word_meanings": [{"word": "steals", "meaning": "rouba", "note": "verbo 'steal' na 3ª pessoa"}, {"word": "hides", "meaning": "esconde", "note": "verbo 'hide' na 3ª pessoa"}, {"word": "sofa", "meaning": "sofá", "note": ""}, {"word": "look for", "meaning": "procurar", "note": "phrasal verb"}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": [], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present (3rd person)", "explanation_pt": "Com he/she/it, o verbo recebe -s, como em 'Max steals a sock'."}], "multiple_choice": [{"question": "What kind of dog is Max?", "options": ["Small", "Big", "Old", "Sick"], "correct_index": 1, "explanation": "O texto diz 'Max is a big dog'."}, {"question": "Where does Max jump?", "options": ["On the bed", "On the table", "On the sofa", "On the chair"], "correct_index": 2, "explanation": "Ele pula no sofá."}, {"question": "What does Max steal?", "options": ["A shoe", "A sock", "A ball", "A hat"], "correct_index": 1, "explanation": "Max rouba uma meia."}, {"question": "Where does Max hide the sock?", "options": ["Under the bed", "In the kitchen", "In the garden", "Under the sofa"], "correct_index": 0, "explanation": "Ele esconde a meia embaixo da cama."}, {"question": "How does the family feel at the end?", "options": ["Angry", "Sad", "They laugh", "Worried"], "correct_index": 2, "explanation": "No final, eles riem juntos."}], "open_questions": [{"question": "Do you have a funny pet? Describe it.", "key_points_pt": ["descrever um animal", "usar adjetivos simples"]}, {"question": "What do you do when you lose something?", "key_points_pt": ["falar sobre procurar objetos", "usar 'look for'"]}]}}, {"level": "A1", "genre": "fairytale", "title": "The Little Star", "paragraphs": ["Once upon a time, a little star lives in the sky. She is small and shy. She wants to shine bright.", "One night, she meets the moon. The moon says, \"You are special.\" The little star smiles.", "Now the little star shines every night. Children look up and smile. She is happy in the sky."], "paragraphs_pt": ["Era uma vez uma estrelinha que vive no céu. Ela é pequena e tímida. Ela quer brilhar forte.", "Uma noite, ela encontra a lua. A lua diz: \"Você é especial.\" A estrelinha sorri.", "Agora a estrelinha brilha todas as noites. As crianças olham para cima e sorriem. Ela é feliz no céu."], "hard_words": ["shy", "shine", "special"], "vocab": [{"word": "star", "meaning": "estrela", "note": ""}, {"word": "sky", "meaning": "céu", "note": ""}, {"word": "moon", "meaning": "lua", "note": ""}, {"word": "night", "meaning": "noite", "note": ""}, {"word": "smile", "meaning": "sorrir", "note": ""}, {"word": "shine", "meaning": "brilhar", "note": ""}, {"word": "special", "meaning": "especial", "note": ""}, {"word": "children", "meaning": "crianças", "note": ""}], "word_meanings": [{"word": "shy", "meaning": "tímida", "note": ""}, {"word": "shine", "meaning": "brilhar", "note": ""}, {"word": "special", "meaning": "especial", "note": ""}, {"word": "look up", "meaning": "olhar para cima", "note": "phrasal verb"}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": ["look up"], "wh": [], "connectors": [], "comparative": []}, "exercises": {"grammar": [{"point": "Adjectives with to be", "explanation_pt": "Usamos 'is/are' + adjetivo, como em 'She is small and shy'."}], "multiple_choice": [{"question": "Where does the little star live?", "options": ["In the sea", "In the sky", "In a cave", "In a forest"], "correct_index": 1, "explanation": "A estrelinha vive no céu."}, {"question": "How is the little star at first?", "options": ["Big and loud", "Small and shy", "Angry", "Sad"], "correct_index": 1, "explanation": "Ela é pequena e tímida."}, {"question": "Who does the star meet at night?", "options": ["The sun", "A bird", "The moon", "A cloud"], "correct_index": 2, "explanation": "Ela encontra a lua."}, {"question": "What does the moon say?", "options": ["\"Go away\"", "\"You are special\"", "\"You are sad\"", "\"Be quiet\""], "correct_index": 1, "explanation": "A lua diz que ela é especial."}, {"question": "Who looks up and smiles?", "options": ["Children", "Birds", "Dogs", "Fish"], "correct_index": 0, "explanation": "As crianças olham para cima e sorriem."}], "open_questions": [{"question": "Do you like to look at the sky at night? Why?", "key_points_pt": ["dar opinião", "falar sobre o céu"]}, {"question": "What makes you feel special?", "key_points_pt": ["falar de sentimentos simples", "usar 'because'"]}]}}, {"level": "A1", "genre": "fable", "title": "The Ant and the Leaf", "paragraphs": ["A small ant walks near a river. The water is fast. The ant falls into the water.", "A bird sees the ant. The bird drops a leaf into the water. The ant climbs onto the leaf and swims to land.", "Later, a hunter tries to catch the bird. The ant bites the hunter's foot. The bird flies away safely."], "paragraphs_pt": ["Uma formiguinha caminha perto de um rio. A água está rápida. A formiga cai na água.", "Um pássaro vê a formiga. O pássaro deixa cair uma folha na água. A formiga sobe na folha e nada até a terra.", "Mais tarde, um caçador tenta pegar o pássaro. A formiga morde o pé do caçador. O pássaro voa para longe em segurança."], "hard_words": ["hunter", "bites", "safely"], "vocab": [{"word": "ant", "meaning": "formiga", "note": ""}, {"word": "river", "meaning": "rio", "note": ""}, {"word": "bird", "meaning": "pássaro", "note": ""}, {"word": "leaf", "meaning": "folha", "note": ""}, {"word": "swim", "meaning": "nadar", "note": ""}, {"word": "hunter", "meaning": "caçador", "note": ""}, {"word": "land", "meaning": "terra", "note": ""}, {"word": "friend", "meaning": "amigo", "note": ""}], "word_meanings": [{"word": "hunter", "meaning": "caçador", "note": ""}, {"word": "bites", "meaning": "morde", "note": "verbo 'bite' na 3ª pessoa"}, {"word": "safely", "meaning": "em segurança", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present for stories", "explanation_pt": "A fábula usa o presente simples para narrar, como em 'The ant falls into the water'."}], "multiple_choice": [{"question": "Where does the ant walk?", "options": ["Near a river", "Near a house", "Near a road", "Near a school"], "correct_index": 0, "explanation": "A formiga caminha perto de um rio."}, {"question": "What does the bird drop into the water?", "options": ["A stick", "A leaf", "A stone", "A flower"], "correct_index": 1, "explanation": "O pássaro deixa cair uma folha."}, {"question": "Who tries to catch the bird?", "options": ["A cat", "A hunter", "A fox", "A snake"], "correct_index": 1, "explanation": "Um caçador tenta pegar o pássaro."}, {"question": "What does the ant do to help the bird?", "options": ["It sings", "It hides", "It bites the hunter", "It flies away"], "correct_index": 2, "explanation": "A formiga morde o pé do caçador."}, {"question": "What is the lesson of the fable?", "options": ["Sleep a lot", "Friends help each other", "Never swim", "Birds are dangerous"], "correct_index": 1, "explanation": "Bons amigos se ajudam."}], "open_questions": [{"question": "How did the ant help the bird?", "key_points_pt": ["a formiga morde o caçador", "o pássaro escapa"]}, {"question": "Why is it good to help friends?", "key_points_pt": ["dar uma razão simples", "relacionar com a história"]}]}}, {"level": "A1", "genre": "adventure", "title": "The Small Boat", "paragraphs": ["Tom has a small boat. He sails to a new island. The sea is calm and blue.", "On the island, he finds a cave. Inside, there are old coins. Tom is very excited.", "He takes one coin home. He tells his friends about the island. They want to go too."], "paragraphs_pt": ["Tom tem um barquinho. Ele navega até uma ilha nova. O mar está calmo e azul.", "Na ilha, ele encontra uma caverna. Dentro, há moedas antigas. Tom está muito animado.", "Ele leva uma moeda para casa. Ele conta aos amigos sobre a ilha. Eles também querem ir."], "hard_words": ["sails", "cave", "coins"], "vocab": [{"word": "boat", "meaning": "barco", "note": ""}, {"word": "sail", "meaning": "navegar", "note": ""}, {"word": "island", "meaning": "ilha", "note": ""}, {"word": "sea", "meaning": "mar", "note": ""}, {"word": "cave", "meaning": "caverna", "note": ""}, {"word": "coin", "meaning": "moeda", "note": ""}, {"word": "excited", "meaning": "animado", "note": ""}, {"word": "friend", "meaning": "amigo", "note": ""}], "word_meanings": [{"word": "sails", "meaning": "navega", "note": "verbo 'sail' na 3ª pessoa"}, {"word": "cave", "meaning": "caverna", "note": ""}, {"word": "coins", "meaning": "moedas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "exercises": {"grammar": [{"point": "There is / There are", "explanation_pt": "Usamos 'there are' para falar de coisas no plural, como em 'there are old coins'."}], "multiple_choice": [{"question": "What does Tom have?", "options": ["A car", "A small boat", "A bike", "A map"], "correct_index": 1, "explanation": "Tom tem um barquinho."}, {"question": "How is the sea?", "options": ["Calm and blue", "Rough and grey", "Cold and dark", "Dirty"], "correct_index": 0, "explanation": "O mar está calmo e azul."}, {"question": "What does Tom find on the island?", "options": ["A house", "A cave", "A shop", "A garden"], "correct_index": 1, "explanation": "Ele encontra uma caverna."}, {"question": "What is inside the cave?", "options": ["Books", "Old coins", "Toys", "Clothes"], "correct_index": 1, "explanation": "Há moedas antigas dentro."}, {"question": "How does Tom feel about the island?", "options": ["Bored", "Excited", "Scared", "Angry"], "correct_index": 1, "explanation": "Tom está muito animado."}], "open_questions": [{"question": "Would you like to explore an island? Why?", "key_points_pt": ["dar uma opinião", "usar 'because'"]}, {"question": "What would you like to find in a cave?", "key_points_pt": ["imaginar um objeto", "descrever de forma simples"]}]}}, {"level": "A1", "genre": "travel", "title": "A Trip to the Beach", "paragraphs": ["Maria and her family go to the beach. They travel by car. The trip takes two hours.", "At the beach, the children swim in the sea. Maria reads a book under an umbrella. The sand is warm.", "In the evening, they eat fruit and watch the sunset. Everyone is tired but happy."], "paragraphs_pt": ["Maria e sua família vão à praia. Eles viajam de carro. A viagem dura duas horas.", "Na praia, as crianças nadam no mar. Maria lê um livro debaixo de um guarda-sol. A areia está quente.", "À noite, eles comem frutas e assistem ao pôr do sol. Todos estão cansados, mas felizes."], "hard_words": ["umbrella", "sunset", "tired"], "vocab": [{"word": "beach", "meaning": "praia", "note": ""}, {"word": "travel", "meaning": "viajar", "note": ""}, {"word": "swim", "meaning": "nadar", "note": ""}, {"word": "sand", "meaning": "areia", "note": ""}, {"word": "umbrella", "meaning": "guarda-sol", "note": ""}, {"word": "sunset", "meaning": "pôr do sol", "note": ""}, {"word": "tired", "meaning": "cansado", "note": ""}, {"word": "family", "meaning": "família", "note": ""}], "word_meanings": [{"word": "umbrella", "meaning": "guarda-sol", "note": ""}, {"word": "sunset", "meaning": "pôr do sol", "note": ""}, {"word": "tired", "meaning": "cansado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["but"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present for routines", "explanation_pt": "Usamos o presente simples para ações do dia a dia, como em 'They travel by car'."}], "multiple_choice": [{"question": "How does the family travel?", "options": ["By bus", "By car", "By plane", "By boat"], "correct_index": 1, "explanation": "Eles viajam de carro."}, {"question": "How long does the trip take?", "options": ["One hour", "Two hours", "Five hours", "Ten hours"], "correct_index": 1, "explanation": "A viagem dura duas horas."}, {"question": "What do the children do at the beach?", "options": ["They read", "They sleep", "They swim", "They cook"], "correct_index": 2, "explanation": "As crianças nadam no mar."}, {"question": "What does Maria do under the umbrella?", "options": ["She sleeps", "She reads a book", "She swims", "She eats"], "correct_index": 1, "explanation": "Maria lê um livro."}, {"question": "How do they feel in the evening?", "options": ["Tired but happy", "Angry", "Bored", "Cold"], "correct_index": 0, "explanation": "Todos estão cansados, mas felizes."}], "open_questions": [{"question": "Do you like the beach? Why?", "key_points_pt": ["dar opinião pessoal", "usar 'because'"]}, {"question": "What do you do on a family trip?", "key_points_pt": ["descrever atividades simples", "usar presente simples"]}]}}, {"level": "A1", "genre": "cooking", "title": "Making Soup", "paragraphs": ["Grandma makes soup every Sunday. She cuts carrots and potatoes. The kitchen smells wonderful.", "She puts the vegetables in a big pot. She adds water and salt. The soup cooks slowly.", "The family sits at the table. Everyone eats a warm bowl of soup. Grandma smiles because they love her food."], "paragraphs_pt": ["A vovó faz sopa todo domingo. Ela corta cenouras e batatas. A cozinha cheira maravilhosamente.", "Ela coloca os legumes em uma panela grande. Ela adiciona água e sal. A sopa cozinha devagar.", "A família se senta à mesa. Todos comem uma tigela de sopa quente. A vovó sorri porque eles amam a comida dela."], "hard_words": ["wonderful", "pot", "slowly"], "vocab": [{"word": "soup", "meaning": "sopa", "note": ""}, {"word": "carrot", "meaning": "cenoura", "note": ""}, {"word": "potato", "meaning": "batata", "note": ""}, {"word": "pot", "meaning": "panela", "note": ""}, {"word": "salt", "meaning": "sal", "note": ""}, {"word": "cook", "meaning": "cozinhar", "note": ""}, {"word": "bowl", "meaning": "tigela", "note": ""}, {"word": "table", "meaning": "mesa", "note": ""}], "word_meanings": [{"word": "wonderful", "meaning": "maravilhoso", "note": ""}, {"word": "pot", "meaning": "panela", "note": ""}, {"word": "slowly", "meaning": "devagar", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "because"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present (3rd person -s)", "explanation_pt": "Verbos com he/she recebem -s, como em 'Grandma makes soup'."}], "multiple_choice": [{"question": "When does Grandma make soup?", "options": ["Every Monday", "Every Sunday", "Every Friday", "Every day"], "correct_index": 1, "explanation": "Ela faz sopa todo domingo."}, {"question": "What does she cut?", "options": ["Apples and bread", "Carrots and potatoes", "Meat and rice", "Onions and eggs"], "correct_index": 1, "explanation": "Ela corta cenouras e batatas."}, {"question": "Where does she put the vegetables?", "options": ["In a bag", "In a big pot", "On the table", "In the oven"], "correct_index": 1, "explanation": "Ela coloca os legumes em uma panela grande."}, {"question": "How does the soup cook?", "options": ["Quickly", "Slowly", "Badly", "Loudly"], "correct_index": 1, "explanation": "A sopa cozinha devagar."}, {"question": "Why does Grandma smile?", "options": ["Because it is hot", "Because they love her food", "Because she is tired", "Because it is Sunday"], "correct_index": 1, "explanation": "Ela sorri porque eles amam a comida dela."}], "open_questions": [{"question": "What food do you like to cook?", "key_points_pt": ["nomear um prato simples", "usar 'I like to cook'"]}, {"question": "Who cooks in your family?", "key_points_pt": ["falar sobre a família", "usar presente simples"]}]}}, {"level": "A1", "genre": "sports", "title": "The Big Race", "paragraphs": ["Leo loves to run. Every morning, he trains in the park. He wants to win the big race.", "On race day, many runners stand at the start line. Leo is nervous but ready. The whistle blows and everyone runs fast.", "Leo runs hard and reaches the finish line first. His friends cheer and give him a medal."], "paragraphs_pt": ["Leo adora correr. Toda manhã, ele treina no parque. Ele quer ganhar a corrida grande.", "No dia da corrida, muitos corredores ficam na linha de partida. Leo está nervoso, mas pronto. O apito toca e todos correm rápido.", "Leo corre com força e chega à linha de chegada primeiro. Seus amigos torcem e dão a ele uma medalha."], "hard_words": ["nervous", "whistle", "medal"], "vocab": [{"word": "run", "meaning": "correr", "note": ""}, {"word": "train", "meaning": "treinar", "note": ""}, {"word": "race", "meaning": "corrida", "note": ""}, {"word": "start", "meaning": "início", "note": ""}, {"word": "finish", "meaning": "fim", "note": ""}, {"word": "medal", "meaning": "medalha", "note": ""}, {"word": "cheer", "meaning": "torcer", "note": ""}, {"word": "nervous", "meaning": "nervoso", "note": ""}], "word_meanings": [{"word": "nervous", "meaning": "nervoso", "note": ""}, {"word": "whistle", "meaning": "apito", "note": ""}, {"word": "medal", "meaning": "medalha", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["but", "and"], "comparative": []}, "exercises": {"grammar": [{"point": "want + to + verb", "explanation_pt": "Usamos 'want to' + verbo, como em 'He wants to win the big race'."}], "multiple_choice": [{"question": "What does Leo love to do?", "options": ["Swim", "Run", "Read", "Cook"], "correct_index": 1, "explanation": "Leo adora correr."}, {"question": "Where does Leo train?", "options": ["At home", "In the park", "At school", "At the beach"], "correct_index": 1, "explanation": "Ele treina no parque."}, {"question": "How does Leo feel before the race?", "options": ["Bored", "Nervous but ready", "Angry", "Sleepy"], "correct_index": 1, "explanation": "Ele está nervoso, mas pronto."}, {"question": "What happens when the whistle blows?", "options": ["Everyone sits down", "Everyone runs fast", "Everyone eats", "Everyone sleeps"], "correct_index": 1, "explanation": "O apito toca e todos correm rápido."}, {"question": "What do his friends give him?", "options": ["A book", "A medal", "A hat", "Money"], "correct_index": 1, "explanation": "Seus amigos dão a ele uma medalha."}], "open_questions": [{"question": "Do you like sports? Which one?", "key_points_pt": ["nomear um esporte", "dar uma razão simples"]}, {"question": "How do you feel before a competition?", "key_points_pt": ["descrever sentimentos", "usar adjetivos simples"]}]}}, {"level": "A1", "genre": "slice", "title": "A Day at the Park", "paragraphs": ["Sofia goes to the park after school. She sits on a bench with her book. Birds sing in the trees.", "Her little brother plays with a ball. He laughs and runs around the grass. Sofia watches him and smiles.", "When the sun goes down, they walk home together. Sofia feels calm and happy."], "paragraphs_pt": ["Sofia vai ao parque depois da escola. Ela senta em um banco com seu livro. Os pássaros cantam nas árvores.", "Seu irmãozinho brinca com uma bola. Ele ri e corre pela grama. Sofia o observa e sorri.", "Quando o sol se põe, eles caminham juntos para casa. Sofia se sente calma e feliz."], "hard_words": ["bench", "grass", "calm"], "vocab": [{"word": "park", "meaning": "parque", "note": ""}, {"word": "bench", "meaning": "banco", "note": ""}, {"word": "bird", "meaning": "pássaro", "note": ""}, {"word": "tree", "meaning": "árvore", "note": ""}, {"word": "brother", "meaning": "irmão", "note": ""}, {"word": "ball", "meaning": "bola", "note": ""}, {"word": "grass", "meaning": "grama", "note": ""}, {"word": "calm", "meaning": "calma", "note": ""}], "word_meanings": [{"word": "bench", "meaning": "banco", "note": ""}, {"word": "grass", "meaning": "grama", "note": ""}, {"word": "calm", "meaning": "calma", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": [], "phrasal": [], "wh": ["When"], "connectors": ["and"], "comparative": []}, "exercises": {"grammar": [{"point": "Present continuous with -ing actions described in present simple", "explanation_pt": "O texto usa presente simples para ações do dia, como em 'He laughs and runs around the grass'."}], "multiple_choice": [{"question": "Where does Sofia go after school?", "options": ["To the beach", "To the park", "To the market", "To a friend's house"], "correct_index": 1, "explanation": "Ela vai ao parque."}, {"question": "What does Sofia bring to the park?", "options": ["A ball", "A book", "A bag", "A phone"], "correct_index": 1, "explanation": "Ela senta com seu livro."}, {"question": "What does her brother play with?", "options": ["A dog", "A ball", "A bike", "A kite"], "correct_index": 1, "explanation": "Ele brinca com uma bola."}, {"question": "Where does the brother run?", "options": ["On the grass", "On the street", "In the water", "Up a tree"], "correct_index": 0, "explanation": "Ele corre pela grama."}, {"question": "How does Sofia feel at the end?", "options": ["Angry", "Calm and happy", "Tired and sad", "Worried"], "correct_index": 1, "explanation": "Sofia se sente calma e feliz."}], "open_questions": [{"question": "What do you do after school?", "key_points_pt": ["descrever uma rotina simples", "usar presente simples"]}, {"question": "Do you like parks? Why?", "key_points_pt": ["dar opinião", "usar 'because'"]}]}}, {"level": "A1", "genre": "dialogue", "title": "Two Friends Talk", "paragraphs": ["Ben meets his friend Lucy at the park. \"Hi Lucy! How are you today?\" he asks. \"I am fine, thank you,\" she says.", "\"Do you want to play soccer with me?\" Ben asks. \"Yes, I love soccer!\" Lucy answers. They run to get the ball.", "After the game, Lucy says, \"That was fun!\" Ben smiles and says, \"Let's play again tomorrow.\" They both agree happily."], "paragraphs_pt": ["Ben encontra sua amiga Lucy no parque. \"Oi Lucy! Como você está hoje?\" ele pergunta. \"Estou bem, obrigada,\" ela diz.", "\"Você quer jogar futebol comigo?\" Ben pergunta. \"Sim, eu amo futebol!\" Lucy responde. Eles correm para pegar a bola.", "Depois do jogo, Lucy diz: \"Isso foi divertido!\" Ben sorri e diz: \"Vamos jogar de novo amanhã.\" Os dois concordam felizes."], "hard_words": ["agree", "answers", "fun"], "vocab": [{"word": "friend", "meaning": "amigo", "note": ""}, {"word": "ask", "meaning": "perguntar", "note": ""}, {"word": "answer", "meaning": "responder", "note": ""}, {"word": "soccer", "meaning": "futebol", "note": ""}, {"word": "play", "meaning": "jogar", "note": ""}, {"word": "fun", "meaning": "divertido", "note": ""}, {"word": "tomorrow", "meaning": "amanhã", "note": ""}, {"word": "agree", "meaning": "concordar", "note": ""}], "word_meanings": [{"word": "agree", "meaning": "concordar", "note": ""}, {"word": "answers", "meaning": "responde", "note": "verbo 'answer' na 3ª pessoa"}, {"word": "fun", "meaning": "divertido", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "am"], "irregular": [], "phrasal": [], "wh": ["How"], "connectors": [], "comparative": []}, "exercises": {"grammar": [{"point": "Wh-questions with how", "explanation_pt": "Usamos 'how' para perguntar sobre estado ou condição, como em 'How are you today?'."}], "multiple_choice": [{"question": "Where does Ben meet Lucy?", "options": ["At school", "At the park", "At home", "At the beach"], "correct_index": 1, "explanation": "Ben encontra Lucy no parque."}, {"question": "What does Ben ask Lucy to play?", "options": ["Basketball", "Soccer", "Tennis", "Chess"], "correct_index": 1, "explanation": "Ele pergunta se ela quer jogar futebol."}, {"question": "Does Lucy like soccer?", "options": ["No, she doesn't", "Yes, she loves it", "She doesn't know", "She hates it"], "correct_index": 1, "explanation": "Ela diz 'I love soccer!'."}, {"question": "What does Lucy say after the game?", "options": ["\"That was boring\"", "\"That was fun\"", "\"I am tired\"", "\"I am angry\""], "correct_index": 1, "explanation": "Ela diz que foi divertido."}, {"question": "What do they plan to do tomorrow?", "options": ["Study", "Play again", "Sleep", "Travel"], "correct_index": 1, "explanation": "Eles combinam jogar de novo amanhã."}], "open_questions": [{"question": "What do you say when you meet a friend?", "key_points_pt": ["usar cumprimentos simples", "'Hi, how are you?'"]}, {"question": "What games do you like to play with friends?", "key_points_pt": ["nomear um jogo", "usar 'I like to play'"]}]}}, {"level": "A1", "genre": "diary", "title": "My Diary", "paragraphs": ["Monday. Today I wake up late. I eat breakfast fast and go to school. My classes are boring but okay.", "Tuesday. I meet my best friend after school. We walk in the park and talk about music. I feel happy.", "Wednesday. Tonight I write in my diary. I think about my nice week. Tomorrow, I want to study hard."], "paragraphs_pt": ["Segunda-feira. Hoje eu acordo tarde. Eu tomo café da manhã rápido e vou para a escola. Minhas aulas são chatas, mas ok.", "Terça-feira. Eu encontro minha melhor amiga depois da escola. Nós caminhamos no parque e conversamos sobre música. Eu me sinto feliz.", "Quarta-feira. Hoje à noite eu escrevo no meu diário. Eu penso sobre minha semana legal. Amanhã, eu quero estudar bastante."], "hard_words": ["boring", "diary", "tonight"], "vocab": [{"word": "diary", "meaning": "diário", "note": ""}, {"word": "wake up", "meaning": "acordar", "note": ""}, {"word": "breakfast", "meaning": "café da manhã", "note": ""}, {"word": "boring", "meaning": "chato", "note": ""}, {"word": "friend", "meaning": "amigo", "note": ""}, {"word": "music", "meaning": "música", "note": ""}, {"word": "week", "meaning": "semana", "note": ""}, {"word": "study", "meaning": "estudar", "note": ""}], "word_meanings": [{"word": "boring", "meaning": "chato", "note": ""}, {"word": "diary", "meaning": "diário", "note": ""}, {"word": "tonight", "meaning": "hoje à noite", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "but"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple present with I", "explanation_pt": "Com 'I' o verbo fica na forma base, como em 'I eat breakfast fast'."}], "multiple_choice": [{"question": "What happens on Monday?", "options": ["She wakes up early", "She wakes up late", "She sleeps all day", "She goes to the park"], "correct_index": 1, "explanation": "Ela acorda tarde na segunda-feira."}, {"question": "How are her classes?", "options": ["Fun", "Boring but okay", "Very hard", "Easy"], "correct_index": 1, "explanation": "As aulas são chatas, mas ok."}, {"question": "Who does she meet on Tuesday?", "options": ["Her teacher", "Her best friend", "Her brother", "Her mother"], "correct_index": 1, "explanation": "Ela encontra sua melhor amiga."}, {"question": "What do they talk about in the park?", "options": ["School", "Music", "Sports", "Food"], "correct_index": 1, "explanation": "Elas conversam sobre música."}, {"question": "What does she want to do tomorrow?", "options": ["Sleep all day", "Study hard", "Travel", "Cook"], "correct_index": 1, "explanation": "Amanhã ela quer estudar bastante."}], "open_questions": [{"question": "Do you write a diary? Why or why not?", "key_points_pt": ["dar opinião simples", "usar 'because'"]}, {"question": "What did you do this week?", "key_points_pt": ["descrever atividades", "usar frases curtas"]}]}}, {"level": "A1", "genre": "romance", "title": "A Sweet Letter", "paragraphs": ["Paulo likes Julia very much. Every day, he sees her at the bus stop. He wants to talk to her but he is shy.", "One day, Paulo writes Julia a small letter. He gives it to her with a flower. Julia reads it and smiles.", "Julia says, \"I like you too.\" Paulo is very happy. Now they walk to the bus stop together every day."], "paragraphs_pt": ["Paulo gosta muito de Julia. Todos os dias, ele a vê no ponto de ônibus. Ele quer falar com ela, mas é tímido.", "Um dia, Paulo escreve um bilhete pequeno para Julia. Ele dá o bilhete a ela com uma flor. Julia lê e sorri.", "Julia diz: \"Eu também gosto de você.\" Paulo fica muito feliz. Agora eles caminham juntos para o ponto de ônibus todos os dias."], "hard_words": ["shy", "letter", "flower"], "vocab": [{"word": "like", "meaning": "gostar", "note": ""}, {"word": "bus stop", "meaning": "ponto de ônibus", "note": ""}, {"word": "shy", "meaning": "tímido", "note": ""}, {"word": "letter", "meaning": "carta/bilhete", "note": ""}, {"word": "flower", "meaning": "flor", "note": ""}, {"word": "smile", "meaning": "sorrir", "note": ""}, {"word": "happy", "meaning": "feliz", "note": ""}, {"word": "together", "meaning": "juntos", "note": ""}], "word_meanings": [{"word": "shy", "meaning": "tímido", "note": ""}, {"word": "letter", "meaning": "carta/bilhete", "note": ""}, {"word": "flower", "meaning": "flor", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["but", "and"], "comparative": []}, "exercises": {"grammar": [{"point": "want to / like to + verb", "explanation_pt": "Usamos 'want to' e 'like' + verbo, como em 'He wants to talk to her'."}], "multiple_choice": [{"question": "Where does Paulo see Julia every day?", "options": ["At school", "At the bus stop", "At the park", "At home"], "correct_index": 1, "explanation": "Ele a vê no ponto de ônibus."}, {"question": "Why doesn't Paulo talk to Julia at first?", "options": ["He is angry", "He is shy", "He is busy", "He is tired"], "correct_index": 1, "explanation": "Ele é tímido."}, {"question": "What does Paulo give Julia?", "options": ["A book", "A letter and a flower", "A phone", "A ball"], "correct_index": 1, "explanation": "Ele dá um bilhete e uma flor."}, {"question": "What does Julia say?", "options": ["\"I don't like you\"", "\"I like you too\"", "\"Go away\"", "\"I am busy\""], "correct_index": 1, "explanation": "Ela diz que também gosta dele."}, {"question": "What do they do every day now?", "options": ["They avoid each other", "They walk together", "They argue", "They study"], "correct_index": 1, "explanation": "Eles caminham juntos todos os dias."}], "open_questions": [{"question": "Do you think Paulo's letter was a good idea? Why?", "key_points_pt": ["dar opinião simples", "usar 'because'"]}, {"question": "How do you show someone you like them?", "key_points_pt": ["descrever um gesto simples", "usar vocabulário básico"]}]}}, {"level": "A2", "genre": "neutral", "title": "A Quiet Morning", "paragraphs": ["Maria woke up early and opened the window. The sky was blue and the air was fresh. She made coffee and sat in the kitchen.", "After breakfast, Maria walked to the park near her house. She saw some birds and a man who was reading a book on a bench. She smiled and kept walking.", "When she got home, Maria cleaned the house and listened to music. It was a simple day, but she felt happy and calm."], "paragraphs_pt": ["Maria acordou cedo e abriu a janela. O céu estava azul e o ar estava fresco. Ela fez café e sentou na cozinha.", "Depois do café da manhã, Maria caminhou até o parque perto da casa dela. Ela viu alguns pássaros e um homem que estava lendo um livro em um banco. Ela sorriu e continuou caminhando.", "Quando chegou em casa, Maria limpou a casa e ouviu música. Foi um dia simples, mas ela se sentiu feliz e calma."], "hard_words": ["fresh", "bench", "calm"], "vocab": [{"word": "wake up", "meaning": "acordar", "note": "phrasal verb comum"}, {"word": "fresh", "meaning": "fresco", "note": ""}, {"word": "breakfast", "meaning": "café da manhã", "note": ""}, {"word": "bench", "meaning": "banco (de praça)", "note": ""}, {"word": "clean", "meaning": "limpar", "note": ""}, {"word": "calm", "meaning": "calmo(a)", "note": ""}, {"word": "simple", "meaning": "simples", "note": ""}], "word_meanings": [{"word": "fresh", "meaning": "fresco", "note": ""}, {"word": "bench", "meaning": "banco (de praça)", "note": ""}, {"word": "calm", "meaning": "calmo(a)", "note": ""}, {"word": "was", "meaning": "estava/foi (forma passada de is)", "note": ""}, {"word": "woke up", "meaning": "acordou", "note": "passado de wake up"}, {"word": "made", "meaning": "fez", "note": "passado irregular de make"}, {"word": "sat", "meaning": "sentou", "note": "passado irregular de sit"}, {"word": "walked", "meaning": "caminhou", "note": "passado regular"}, {"word": "saw", "meaning": "viu", "note": "passado irregular de see"}, {"word": "smiled", "meaning": "sorriu", "note": ""}, {"word": "kept", "meaning": "continuou/manteve", "note": "passado irregular de keep"}, {"word": "got", "meaning": "chegou/ficou", "note": "passado irregular de get"}, {"word": "cleaned", "meaning": "limpou", "note": ""}, {"word": "listened", "meaning": "ouviu/escutou", "note": ""}, {"word": "felt", "meaning": "sentiu", "note": "passado irregular de feel"}, {"word": "who", "meaning": "quem/que", "note": ""}, {"word": "when", "meaning": "quando", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["woke up", "made", "sat", "walked", "saw", "smiled", "kept", "got", "cleaned", "listened", "felt"], "phrasal": ["woke up"], "wh": ["who", "when"], "connectors": ["and", "but"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple past", "explanation_pt": "Usamos o passado simples para ações terminadas, como em 'Maria woke up early' e 'she made coffee'."}], "multiple_choice": [{"question": "What did Maria do first in the morning?", "options": ["She cleaned the house", "She opened the window", "She walked to the park", "She read a book"], "correct_index": 1, "explanation": "No primeiro parágrafo, Maria abriu a janela primeiro."}, {"question": "Where did Maria walk after breakfast?", "options": ["To the market", "To a friend's house", "To the park", "To school"], "correct_index": 2, "explanation": "O texto diz que ela caminhou até o parque."}, {"question": "Who was reading a book?", "options": ["Maria", "A child", "A man", "A woman"], "correct_index": 2, "explanation": "Um homem estava lendo um livro no banco."}, {"question": "What did Maria do at home in the afternoon?", "options": ["She slept", "She cooked", "She cleaned and listened to music", "She watched TV"], "correct_index": 2, "explanation": "No último parágrafo, ela limpou a casa e ouviu música."}, {"question": "How did Maria feel at the end of the day?", "options": ["Tired", "Angry", "Happy and calm", "Sad"], "correct_index": 2, "explanation": "O texto diz que ela se sentiu feliz e calma."}], "open_questions": [{"question": "Do you like quiet mornings like Maria's? Why or why not?", "key_points_pt": ["Falar se gosta de manhãs calmas", "Explicar o motivo com um exemplo pessoal"]}, {"question": "What do you usually do after breakfast?", "key_points_pt": ["Descrever uma rotina simples", "Usar verbos no presente ou passado"]}]}}, {"level": "A2", "genre": "humor", "title": "The Wrong Cat", "paragraphs": ["Tom lived next to Mrs. Silva. One evening, a small gray cat came into his kitchen through the open window. Tom thought it was his cat, Pepper, so he gave it milk and food.", "The cat ate everything and then jumped on the sofa. Tom laughed and said, 'You are very hungry today, Pepper!' But the cat looked at him strangely and did not answer, of course.", "Later, Mrs. Silva knocked on the door and asked, 'Have you seen my cat, Bolinha?' Tom looked at the gray cat and understood his funny mistake. He laughed and gave Bolinha back to Mrs. Silva."], "paragraphs_pt": ["Tom morava ao lado da Sra. Silva. Uma noite, um gatinho cinza entrou na cozinha dele pela janela aberta. Tom achou que era o gato dele, Pepper, então deu leite e comida ao gato.", "O gato comeu tudo e depois pulou no sofá. Tom riu e disse: 'Você está com muita fome hoje, Pepper!' Mas o gato olhou para ele de um jeito estranho e, claro, não respondeu.", "Mais tarde, a Sra. Silva bateu na porta e perguntou: 'Você viu meu gato, o Bolinha?' Tom olhou para o gato cinza e entendeu o engraçado engano dele. Ele riu e devolveu o Bolinha para a Sra. Silva."], "hard_words": ["strangely", "knocked", "mistake"], "vocab": [{"word": "next to", "meaning": "ao lado de", "note": ""}, {"word": "gray", "meaning": "cinza", "note": ""}, {"word": "hungry", "meaning": "com fome", "note": ""}, {"word": "sofa", "meaning": "sofá", "note": ""}, {"word": "strangely", "meaning": "estranhamente", "note": ""}, {"word": "knocked", "meaning": "bateu (na porta)", "note": ""}, {"word": "mistake", "meaning": "erro/engano", "note": ""}], "word_meanings": [{"word": "strangely", "meaning": "estranhamente", "note": ""}, {"word": "knocked", "meaning": "bateu (na porta)", "note": ""}, {"word": "mistake", "meaning": "erro/engano", "note": ""}, {"word": "lived", "meaning": "morava/morou", "note": ""}, {"word": "came", "meaning": "veio", "note": "passado irregular de come"}, {"word": "thought", "meaning": "pensou/achou", "note": "passado irregular de think"}, {"word": "gave", "meaning": "deu", "note": "passado irregular de give"}, {"word": "ate", "meaning": "comeu", "note": "passado irregular de eat"}, {"word": "jumped", "meaning": "pulou", "note": ""}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "said", "meaning": "disse", "note": "passado irregular de say"}, {"word": "looked", "meaning": "olhou", "note": ""}, {"word": "asked", "meaning": "perguntou", "note": ""}, {"word": "understood", "meaning": "entendeu", "note": "passado irregular de understand"}, {"word": "gave back", "meaning": "devolveu", "note": "phrasal verb"}, {"word": "so", "meaning": "então/por isso", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["lived", "came", "thought", "gave", "ate", "jumped", "laughed", "said", "looked", "asked", "understood"], "phrasal": [], "wh": [], "connectors": ["so", "but"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple past with irregular verbs", "explanation_pt": "Verbos irregulares mudam de forma, como 'came' (came) e 'ate' (comeu), diferente do padrão -ed."}], "multiple_choice": [{"question": "How did the cat get into Tom's kitchen?", "options": ["Through the door", "Through the open window", "Tom carried it", "It climbed the wall"], "correct_index": 1, "explanation": "O gato entrou pela janela aberta."}, {"question": "Who did Tom think the cat was?", "options": ["A neighbor's dog", "His own cat, Pepper", "A wild animal", "Mrs. Silva's cat"], "correct_index": 1, "explanation": "Tom achou que era o gato dele, Pepper."}, {"question": "What did the cat do after eating?", "options": ["It ran away", "It jumped on the sofa", "It slept in the kitchen", "It went back outside"], "correct_index": 1, "explanation": "O gato pulou no sofá depois de comer."}, {"question": "Who knocked on Tom's door?", "options": ["Pepper's owner", "A police officer", "Mrs. Silva", "A delivery man"], "correct_index": 2, "explanation": "A Sra. Silva bateu na porta."}, {"question": "What was the cat's real name?", "options": ["Pepper", "Bolinha", "Gray", "Tom"], "correct_index": 1, "explanation": "O nome real do gato era Bolinha."}], "open_questions": [{"question": "Have you ever made a funny mistake like Tom? What happened?", "key_points_pt": ["Contar um engano engraçado", "Explicar como resolveu a situação"]}, {"question": "Do you think Tom should be more careful next time? Why?", "key_points_pt": ["Dar opinião pessoal", "Justificar com um argumento simples"]}]}}, {"level": "A2", "genre": "suspense", "title": "The Locked Room", "paragraphs": ["Ana worked late at the old library. When she tried to leave, she found that the front door was locked. She heard a strange noise from the next room and stopped walking.", "Slowly, Ana walked toward the noise with her phone light. She opened the door and saw a window that was open. The wind was moving the curtains, and a book had fallen on the floor.", "Ana laughed with relief because it was only the wind. She picked up the book, closed the window, and finally found the back door, which was open. She went home quickly and locked her own door that night."], "paragraphs_pt": ["Ana trabalhou até tarde na biblioteca antiga. Quando tentou sair, descobriu que a porta da frente estava trancada. Ela ouviu um barulho estranho vindo da sala ao lado e parou de andar.", "Devagar, Ana caminhou em direção ao barulho com a luz do celular. Ela abriu a porta e viu uma janela aberta. O vento estava movendo as cortinas, e um livro tinha caído no chão.", "Ana riu de alívio porque era só o vento. Ela pegou o livro, fechou a janela e finalmente encontrou a porta dos fundos, que estava aberta. Ela foi para casa rapidamente e trancou a própria porta naquela noite."], "hard_words": ["locked", "curtains", "relief"], "vocab": [{"word": "locked", "meaning": "trancado(a)", "note": ""}, {"word": "noise", "meaning": "barulho", "note": ""}, {"word": "curtains", "meaning": "cortinas", "note": ""}, {"word": "fallen", "meaning": "caído", "note": "particípio de fall"}, {"word": "relief", "meaning": "alívio", "note": ""}, {"word": "picked up", "meaning": "pegou/recolheu", "note": "phrasal verb"}, {"word": "quickly", "meaning": "rapidamente", "note": ""}], "word_meanings": [{"word": "locked", "meaning": "trancado(a)", "note": ""}, {"word": "curtains", "meaning": "cortinas", "note": ""}, {"word": "relief", "meaning": "alívio", "note": ""}, {"word": "worked", "meaning": "trabalhou", "note": ""}, {"word": "tried", "meaning": "tentou", "note": ""}, {"word": "found", "meaning": "encontrou/descobriu", "note": "passado irregular de find"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular de hear"}, {"word": "stopped", "meaning": "parou", "note": ""}, {"word": "walked", "meaning": "caminhou", "note": ""}, {"word": "opened", "meaning": "abriu", "note": ""}, {"word": "saw", "meaning": "viu", "note": "passado irregular de see"}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "picked up", "meaning": "pegou/recolheu", "note": "phrasal verb"}, {"word": "closed", "meaning": "fechou", "note": ""}, {"word": "went", "meaning": "foi", "note": "passado irregular de go"}, {"word": "because", "meaning": "porque", "note": ""}, {"word": "and", "meaning": "e", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["worked", "tried", "found", "heard", "stopped", "walked", "opened", "saw", "laughed", "picked up", "closed", "went"], "phrasal": ["picked up"], "wh": [], "connectors": ["because", "and"], "comparative": []}, "exercises": {"grammar": [{"point": "Past continuous", "explanation_pt": "Usamos o passado contínuo para uma ação em progresso, como em 'The wind was moving the curtains'."}], "multiple_choice": [{"question": "What did Ana find when she tried to leave?", "options": ["The lights were off", "The front door was locked", "The library was full of people", "A window was broken"], "correct_index": 1, "explanation": "A porta da frente estava trancada."}, {"question": "What did Ana use to see in the dark?", "options": ["A candle", "Her phone light", "A flashlight", "The library lamp"], "correct_index": 1, "explanation": "Ela usou a luz do celular."}, {"question": "What was making the noise?", "options": ["A cat", "Another person", "The wind and an open window", "A machine"], "correct_index": 2, "explanation": "O vento estava movendo as cortinas pela janela aberta."}, {"question": "How did Ana feel when she understood the noise?", "options": ["Scared", "Relieved", "Angry", "Confused"], "correct_index": 1, "explanation": "Ela riu de alívio."}, {"question": "How did Ana finally leave the library?", "options": ["Through a window", "Through the front door", "Through the back door", "She called for help"], "correct_index": 2, "explanation": "Ela encontrou a porta dos fundos aberta."}], "open_questions": [{"question": "Would you be scared in Ana's situation? Why or why not?", "key_points_pt": ["Falar se teria medo", "Justificar a resposta"]}, {"question": "What do you do when you hear a strange noise at home?", "key_points_pt": ["Descrever uma reação pessoal", "Usar vocabulário simples de ação"]}]}}, {"level": "A2", "genre": "fairytale", "title": "The Silver Key", "paragraphs": ["Once upon a time, a poor girl named Lila found a small silver key near a river. The key was old, but it shone brightly in the sun. Lila kept it in her pocket and walked home.", "That night, Lila dreamed about a hidden door in the forest. The next morning, she went to the forest and found a wooden door between two big trees. She used the silver key, and the door slowly opened.", "Inside, there was a beautiful garden full of golden flowers. A kind old woman lived there and gave Lila a basket of flowers as a gift. Lila thanked her and returned home, happier than ever before."], "paragraphs_pt": ["Era uma vez uma garota pobre chamada Lila que encontrou uma pequena chave de prata perto de um rio. A chave era antiga, mas brilhava sob o sol. Lila guardou a chave no bolso e caminhou até em casa.", "Naquela noite, Lila sonhou com uma porta escondida na floresta. Na manhã seguinte, ela foi até a floresta e encontrou uma porta de madeira entre duas árvores grandes. Ela usou a chave de prata, e a porta abriu devagar.", "Lá dentro, havia um jardim lindo cheio de flores douradas. Uma senhora bondosa morava ali e deu a Lila uma cesta de flores como presente. Lila agradeceu e voltou para casa, mais feliz do que nunca."], "hard_words": ["shone", "hidden", "golden"], "vocab": [{"word": "once upon a time", "meaning": "era uma vez", "note": "expressão de contos de fadas"}, {"word": "shone", "meaning": "brilhou", "note": "passado irregular de shine"}, {"word": "hidden", "meaning": "escondido(a)", "note": ""}, {"word": "wooden", "meaning": "de madeira", "note": ""}, {"word": "golden", "meaning": "dourado(a)", "note": ""}, {"word": "kind", "meaning": "gentil/bondoso(a)", "note": ""}, {"word": "gift", "meaning": "presente", "note": ""}, {"word": "happier", "meaning": "mais feliz", "note": "comparativo de happy"}], "word_meanings": [{"word": "shone", "meaning": "brilhou", "note": "passado irregular de shine"}, {"word": "hidden", "meaning": "escondido(a)", "note": ""}, {"word": "golden", "meaning": "dourado(a)", "note": ""}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "found", "meaning": "encontrou", "note": "passado irregular de find"}, {"word": "kept", "meaning": "guardou", "note": "passado irregular de keep"}, {"word": "walked", "meaning": "caminhou", "note": ""}, {"word": "dreamed", "meaning": "sonhou", "note": ""}, {"word": "went", "meaning": "foi", "note": "passado irregular de go"}, {"word": "used", "meaning": "usou", "note": ""}, {"word": "opened", "meaning": "abriu", "note": ""}, {"word": "lived", "meaning": "morava", "note": ""}, {"word": "gave", "meaning": "deu", "note": "passado irregular de give"}, {"word": "thanked", "meaning": "agradeceu", "note": ""}, {"word": "returned", "meaning": "voltou", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "happier", "meaning": "mais feliz", "note": "comparativo de happy"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["found", "kept", "walked", "dreamed", "went", "used", "opened", "lived", "gave", "thanked", "returned"], "phrasal": [], "wh": [], "connectors": ["but", "and"], "comparative": ["happier"]}, "exercises": {"grammar": [{"point": "Comparatives", "explanation_pt": "Usamos '-er' para comparar coisas, como em 'happier than ever before' (mais feliz do que nunca)."}], "multiple_choice": [{"question": "Where did Lila find the silver key?", "options": ["In the forest", "Near a river", "In her garden", "In a shop"], "correct_index": 1, "explanation": "Ela encontrou a chave perto de um rio."}, {"question": "What did Lila dream about?", "options": ["A silver key", "A hidden door in the forest", "A garden of flowers", "An old woman"], "correct_index": 1, "explanation": "Ela sonhou com uma porta escondida na floresta."}, {"question": "Where was the wooden door?", "options": ["Near the river", "Between two big trees", "Inside her house", "On top of a hill"], "correct_index": 1, "explanation": "A porta ficava entre duas árvores grandes."}, {"question": "What did Lila find inside the door?", "options": ["A castle", "A beautiful garden", "A treasure box", "An empty room"], "correct_index": 1, "explanation": "Ela encontrou um jardim lindo cheio de flores douradas."}, {"question": "What gift did the old woman give Lila?", "options": ["A silver key", "A basket of flowers", "A new dress", "A book"], "correct_index": 1, "explanation": "A senhora deu a Lila uma cesta de flores."}], "open_questions": [{"question": "What do you think the old woman's garden looked like?", "key_points_pt": ["Descrever o jardim com imaginação", "Usar adjetivos simples"]}, {"question": "If you found a magic key, where would you use it?", "key_points_pt": ["Dar uma resposta imaginativa", "Justificar a escolha"]}]}}, {"level": "A2", "genre": "fable", "title": "The Ant and the Butterfly", "paragraphs": ["A little ant worked hard every day. She carried food to her home under the ground. A beautiful butterfly flew around the garden and laughed at the ant because she never stopped to rest.", "'Why do you work so much?' asked the butterfly. 'Come and fly with me!' But the ant said, 'Winter is coming, and I must be ready.' The butterfly did not listen and kept flying happily.", "When winter came, it was cold and there were no flowers. The butterfly had no food, but the ant had a lot of food in her home. The kind ant shared her food with the butterfly, who learned an important lesson about planning ahead."], "paragraphs_pt": ["Uma formiguinha trabalhava duro todos os dias. Ela carregava comida para a casa dela embaixo da terra. Uma linda borboleta voava pelo jardim e ria da formiga porque ela nunca parava para descansar.", "'Por que você trabalha tanto?' perguntou a borboleta. 'Venha voar comigo!' Mas a formiga disse: 'O inverno está chegando, e eu preciso estar pronta.' A borboleta não ouviu e continuou voando alegremente.", "Quando o inverno chegou, estava frio e não havia flores. A borboleta não tinha comida, mas a formiga tinha muita comida em casa. A formiga gentil dividiu a comida dela com a borboleta, que aprendeu uma lição importante sobre se planejar."], "hard_words": ["carried", "rest", "ahead"], "vocab": [{"word": "ant", "meaning": "formiga", "note": ""}, {"word": "carried", "meaning": "carregou/carregava", "note": ""}, {"word": "rest", "meaning": "descansar", "note": ""}, {"word": "ready", "meaning": "pronto(a)", "note": ""}, {"word": "shared", "meaning": "dividiu/compartilhou", "note": ""}, {"word": "lesson", "meaning": "lição", "note": ""}, {"word": "ahead", "meaning": "com antecedência/à frente", "note": ""}], "word_meanings": [{"word": "carried", "meaning": "carregou/carregava", "note": ""}, {"word": "rest", "meaning": "descansar", "note": ""}, {"word": "ahead", "meaning": "com antecedência/à frente", "note": ""}, {"word": "was", "meaning": "estava", "note": ""}, {"word": "worked", "meaning": "trabalhava", "note": ""}, {"word": "flew", "meaning": "voou/voava", "note": "passado irregular de fly"}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "stopped", "meaning": "parou", "note": ""}, {"word": "asked", "meaning": "perguntou", "note": ""}, {"word": "said", "meaning": "disse", "note": "passado irregular de say"}, {"word": "kept", "meaning": "continuou", "note": "passado irregular de keep"}, {"word": "came", "meaning": "chegou/veio", "note": "passado irregular de come"}, {"word": "had", "meaning": "tinha", "note": "passado irregular de have"}, {"word": "shared", "meaning": "dividiu", "note": ""}, {"word": "learned", "meaning": "aprendeu", "note": ""}, {"word": "why", "meaning": "por que", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "because", "meaning": "porque", "note": ""}, {"word": "and", "meaning": "e", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["worked", "flew", "laughed", "stopped", "asked", "said", "kept", "came", "had", "shared", "learned"], "phrasal": [], "wh": ["why"], "connectors": ["but", "because", "and"], "comparative": []}, "exercises": {"grammar": [{"point": "Simple past vs present continuous", "explanation_pt": "A fábula mistura o passado simples da narrativa com uma frase no presente contínuo, 'Winter is coming', para dar urgência."}], "multiple_choice": [{"question": "What did the ant do every day?", "options": ["She slept a lot", "She worked and carried food", "She flew around", "She talked to flowers"], "correct_index": 1, "explanation": "A formiga trabalhava e carregava comida todos os dias."}, {"question": "Why did the butterfly laugh at the ant?", "options": ["Because the ant was slow", "Because the ant never stopped to rest", "Because the ant was small", "Because the ant could not fly"], "correct_index": 1, "explanation": "A borboleta ria porque a formiga nunca parava para descansar."}, {"question": "What did the ant say about winter?", "options": ["It was far away", "It was coming, so she must be ready", "It would never come", "It was already there"], "correct_index": 1, "explanation": "A formiga disse que o inverno estava chegando e que precisava estar pronta."}, {"question": "What happened to the butterfly in winter?", "options": ["She found a lot of food", "She had no food", "She flew away", "She slept all winter"], "correct_index": 1, "explanation": "A borboleta não tinha comida no inverno."}, {"question": "What did the ant do for the butterfly?", "options": ["She ignored her", "She shared her food", "She sent her away", "She gave her a house"], "correct_index": 1, "explanation": "A formiga dividiu sua comida com a borboleta."}], "open_questions": [{"question": "What lesson does this fable teach us?", "key_points_pt": ["Falar sobre a importância de se planejar", "Comparar trabalho e diversão"]}, {"question": "Are you more like the ant or the butterfly? Why?", "key_points_pt": ["Dar uma opinião pessoal", "Justificar com um exemplo"]}]}}, {"level": "A2", "genre": "adventure", "title": "The Lost Map", "paragraphs": ["Sam and his sister Beth found an old map in their grandfather's box. The map showed a path through the mountains to a hidden cave. They decided to explore it during their summer vacation.", "The next day, they walked up the mountain for three hours. It was difficult, but they helped each other. Finally, they found the cave behind some big rocks, just like the map showed.", "Inside the cave, they discovered old coins and a wooden box. They were not rich, but they were very excited. Sam and Beth took some coins home and told their grandfather about their amazing adventure."], "paragraphs_pt": ["Sam e sua irmã Beth encontraram um mapa antigo na caixa do avô deles. O mapa mostrava um caminho pelas montanhas até uma caverna escondida. Eles decidiram explorar o lugar durante as férias de verão.", "No dia seguinte, eles caminharam montanha acima por três horas. Foi difícil, mas eles se ajudaram um ao outro. Finalmente, encontraram a caverna atrás de umas pedras grandes, exatamente como o mapa mostrava.", "Dentro da caverna, eles descobriram moedas antigas e uma caixa de madeira. Eles não ficaram ricos, mas ficaram muito animados. Sam e Beth levaram algumas moedas para casa e contaram ao avô sobre a aventura incrível deles."], "hard_words": ["cave", "coins", "discovered"], "vocab": [{"word": "map", "meaning": "mapa", "note": ""}, {"word": "path", "meaning": "caminho/trilha", "note": ""}, {"word": "cave", "meaning": "caverna", "note": ""}, {"word": "explore", "meaning": "explorar", "note": ""}, {"word": "discovered", "meaning": "descobriram", "note": ""}, {"word": "coins", "meaning": "moedas", "note": ""}, {"word": "excited", "meaning": "animado(a)/empolgado(a)", "note": ""}], "word_meanings": [{"word": "cave", "meaning": "caverna", "note": ""}, {"word": "coins", "meaning": "moedas", "note": ""}, {"word": "discovered", "meaning": "descobriram", "note": ""}, {"word": "was", "meaning": "estava/foi", "note": ""}, {"word": "were", "meaning": "estavam/eram", "note": ""}, {"word": "found", "meaning": "encontraram", "note": "passado irregular de find"}, {"word": "showed", "meaning": "mostrava", "note": ""}, {"word": "decided", "meaning": "decidiram", "note": ""}, {"word": "walked", "meaning": "caminharam", "note": ""}, {"word": "helped", "meaning": "ajudaram", "note": ""}, {"word": "took", "meaning": "levaram/pegaram", "note": "passado irregular de take"}, {"word": "told", "meaning": "contaram", "note": "passado irregular de tell"}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "finally", "meaning": "finalmente", "note": ""}, {"word": "harder", "meaning": "mais difícil", "note": "comparativo de hard"}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["found", "showed", "decided", "walked", "helped", "took", "told"], "phrasal": [], "wh": [], "connectors": ["but", "finally"], "comparative": []}, "exercises": {"grammar": [{"point": "Sequencing with time words", "explanation_pt": "Palavras como 'the next day' e 'finally' ajudam a organizar a ordem dos eventos na história."}], "multiple_choice": [{"question": "Where did Sam and Beth find the map?", "options": ["In a book", "In their grandfather's box", "At school", "In the mountains"], "correct_index": 1, "explanation": "Eles encontraram o mapa na caixa do avô."}, {"question": "What did the map show?", "options": ["A path to a city", "A path to a hidden cave", "A path to the beach", "A path to a lake"], "correct_index": 1, "explanation": "O mapa mostrava um caminho até uma caverna escondida."}, {"question": "How long did they walk up the mountain?", "options": ["One hour", "Two hours", "Three hours", "All day"], "correct_index": 2, "explanation": "Eles caminharam por três horas."}, {"question": "Where did they find the cave?", "options": ["Near a river", "Behind some big rocks", "Under a tree", "Next to a lake"], "correct_index": 1, "explanation": "Eles encontraram a caverna atrás de umas pedras grandes."}, {"question": "What did they discover inside the cave?", "options": ["Old books", "Coins and a wooden box", "Animals", "Nothing"], "correct_index": 1, "explanation": "Eles descobriram moedas antigas e uma caixa de madeira."}], "open_questions": [{"question": "Would you like to go on an adventure like Sam and Beth? Why?", "key_points_pt": ["Dar opinião pessoal", "Explicar o motivo"]}, {"question": "What do you think was inside the wooden box?", "key_points_pt": ["Usar a imaginação", "Descrever com palavras simples"]}]}}, {"level": "A2", "genre": "travel", "title": "A Trip to the Mountains", "paragraphs": ["Last July, Carla traveled to a small town in the mountains with her family. They took a bus for five hours, and Carla looked out the window at the green hills the whole time.", "In the town, they stayed in a small hotel with a beautiful view. Every morning, they walked in the mountains and visited local markets. Carla tried new food and bought a colorful scarf for her mother.", "On the last day, Carla climbed a small hill with her father and watched the sunset. It was more beautiful than any picture she had seen before. She promised to return to the mountains again someday."], "paragraphs_pt": ["Em julho passado, Carla viajou para uma cidade pequena nas montanhas com a família dela. Eles pegaram um ônibus por cinco horas, e Carla olhou pela janela para as colinas verdes o tempo todo.", "Na cidade, eles ficaram em um hotel pequeno com uma vista linda. Todas as manhãs, eles caminhavam nas montanhas e visitavam mercados locais. Carla experimentou comidas novas e comprou um lenço colorido para a mãe dela.", "No último dia, Carla subiu uma pequena colina com o pai e assistiu ao pôr do sol. Foi mais bonito do que qualquer foto que ela já tinha visto antes. Ela prometeu voltar para as montanhas de novo algum dia."], "hard_words": ["hills", "scarf", "sunset"], "vocab": [{"word": "traveled", "meaning": "viajou", "note": ""}, {"word": "hills", "meaning": "colinas", "note": ""}, {"word": "view", "meaning": "vista", "note": ""}, {"word": "local", "meaning": "local", "note": ""}, {"word": "scarf", "meaning": "lenço/cachecol", "note": ""}, {"word": "sunset", "meaning": "pôr do sol", "note": ""}, {"word": "promised", "meaning": "prometeu", "note": ""}], "word_meanings": [{"word": "hills", "meaning": "colinas", "note": ""}, {"word": "scarf", "meaning": "lenço/cachecol", "note": ""}, {"word": "sunset", "meaning": "pôr do sol", "note": ""}, {"word": "took", "meaning": "pegaram", "note": "passado irregular de take"}, {"word": "looked", "meaning": "olhou", "note": ""}, {"word": "stayed", "meaning": "ficaram", "note": ""}, {"word": "walked", "meaning": "caminhavam", "note": ""}, {"word": "visited", "meaning": "visitavam", "note": ""}, {"word": "tried", "meaning": "experimentou", "note": ""}, {"word": "bought", "meaning": "comprou", "note": "passado irregular de buy"}, {"word": "climbed", "meaning": "subiu", "note": ""}, {"word": "watched", "meaning": "assistiu", "note": ""}, {"word": "promised", "meaning": "prometeu", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "more beautiful", "meaning": "mais bonito(a)", "note": "comparativo"}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["took", "looked", "stayed", "walked", "visited", "tried", "bought", "climbed", "watched", "promised"], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": ["more beautiful"]}, "exercises": {"grammar": [{"point": "Comparatives with 'more'", "explanation_pt": "Para adjetivos longos, usamos 'more' antes do adjetivo, como em 'more beautiful than any picture'."}], "multiple_choice": [{"question": "How did Carla's family travel to the mountains?", "options": ["By car", "By train", "By bus", "By plane"], "correct_index": 2, "explanation": "Eles pegaram um ônibus por cinco horas."}, {"question": "What did they do every morning in the town?", "options": ["They slept late", "They walked and visited markets", "They stayed at the hotel", "They watched TV"], "correct_index": 1, "explanation": "Todas as manhãs eles caminhavam e visitavam mercados locais."}, {"question": "What did Carla buy for her mother?", "options": ["A hat", "A colorful scarf", "Shoes", "A book"], "correct_index": 1, "explanation": "Ela comprou um lenço colorido para a mãe."}, {"question": "Who did Carla climb the hill with?", "options": ["Her mother", "Her father", "Her friend", "Alone"], "correct_index": 1, "explanation": "Ela subiu a colina com o pai."}, {"question": "What did Carla promise at the end of the trip?", "options": ["To never travel again", "To return to the mountains someday", "To move to the town", "To buy a house there"], "correct_index": 1, "explanation": "Ela prometeu voltar para as montanhas algum dia."}], "open_questions": [{"question": "What is your favorite place to travel? Why?", "key_points_pt": ["Descrever um lugar", "Explicar o motivo da preferência"]}, {"question": "Do you prefer the mountains or the beach for vacation? Why?", "key_points_pt": ["Dar uma opinião", "Comparar as duas opções"]}]}}, {"level": "A2", "genre": "cooking", "title": "Grandma's Recipe", "paragraphs": ["Every Sunday, Paulo visited his grandmother and helped her cook lunch. Last Sunday, she taught him how to make her famous rice and beans with fresh vegetables from her garden.", "First, Paulo washed the vegetables and cut them into small pieces. Then, his grandmother added the rice, beans, and some spices to the pot. They cooked everything slowly and talked about her childhood.", "When the food was ready, the whole family sat at the table together. Everyone said the food was more delicious than usual. Paulo felt proud because he helped cook the meal, and he asked his grandmother for the recipe."], "paragraphs_pt": ["Todo domingo, Paulo visitava a avó dele e ajudava a cozinhar o almoço. No domingo passado, ela ensinou a ele como fazer o famoso arroz e feijão dela com legumes frescos do jardim dela.", "Primeiro, Paulo lavou os legumes e os cortou em pedaços pequenos. Depois, a avó dele adicionou o arroz, o feijão e alguns temperos na panela. Eles cozinharam tudo devagar e conversaram sobre a infância dela.", "Quando a comida ficou pronta, a família toda sentou à mesa junta. Todo mundo disse que a comida estava mais deliciosa do que de costume. Paulo se sentiu orgulhoso porque ajudou a cozinhar a refeição, e pediu a receita para a avó."], "hard_words": ["spices", "pot", "proud"], "vocab": [{"word": "taught", "meaning": "ensinou", "note": "passado irregular de teach"}, {"word": "vegetables", "meaning": "legumes/vegetais", "note": ""}, {"word": "spices", "meaning": "temperos/especiarias", "note": ""}, {"word": "pot", "meaning": "panela", "note": ""}, {"word": "childhood", "meaning": "infância", "note": ""}, {"word": "delicious", "meaning": "delicioso(a)", "note": ""}, {"word": "proud", "meaning": "orgulhoso(a)", "note": ""}, {"word": "recipe", "meaning": "receita", "note": ""}], "word_meanings": [{"word": "spices", "meaning": "temperos/especiarias", "note": ""}, {"word": "pot", "meaning": "panela", "note": ""}, {"word": "proud", "meaning": "orgulhoso(a)", "note": ""}, {"word": "was", "meaning": "estava/ficou", "note": ""}, {"word": "visited", "meaning": "visitava", "note": ""}, {"word": "helped", "meaning": "ajudava/ajudou", "note": ""}, {"word": "taught", "meaning": "ensinou", "note": "passado irregular de teach"}, {"word": "washed", "meaning": "lavou", "note": ""}, {"word": "cut", "meaning": "cortou", "note": "passado irregular de cut (mesma forma)"}, {"word": "added", "meaning": "adicionou", "note": ""}, {"word": "cooked", "meaning": "cozinharam", "note": ""}, {"word": "talked", "meaning": "conversaram", "note": ""}, {"word": "sat", "meaning": "sentou", "note": "passado irregular de sit"}, {"word": "said", "meaning": "disse", "note": "passado irregular de say"}, {"word": "felt", "meaning": "sentiu", "note": "passado irregular de feel"}, {"word": "asked", "meaning": "pediu/perguntou", "note": ""}, {"word": "first", "meaning": "primeiro", "note": ""}, {"word": "then", "meaning": "depois/então", "note": ""}, {"word": "because", "meaning": "porque", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "more delicious", "meaning": "mais delicioso(a)", "note": "comparativo"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["visited", "helped", "taught", "washed", "cut", "added", "cooked", "talked", "sat", "said", "felt", "asked"], "phrasal": [], "wh": [], "connectors": ["first", "then", "because", "and"], "comparative": ["more delicious"]}, "exercises": {"grammar": [{"point": "Sequence connectors", "explanation_pt": "Palavras como 'first' e 'then' ajudam a explicar a ordem dos passos de uma receita."}], "multiple_choice": [{"question": "What did Paulo's grandmother teach him to make?", "options": ["A cake", "Rice and beans with vegetables", "Soup", "Bread"], "correct_index": 1, "explanation": "Ela ensinou a fazer arroz e feijão com legumes."}, {"question": "What did Paulo do first?", "options": ["He cut the vegetables", "He washed the vegetables", "He cooked the rice", "He set the table"], "correct_index": 1, "explanation": "Primeiro, Paulo lavou os legumes."}, {"question": "What did they talk about while cooking?", "options": ["The weather", "Her childhood", "School", "Music"], "correct_index": 1, "explanation": "Eles conversaram sobre a infância da avó."}, {"question": "How did the family describe the food?", "options": ["Too spicy", "More delicious than usual", "Cold", "Simple"], "correct_index": 1, "explanation": "Todos disseram que a comida estava mais deliciosa do que de costume."}, {"question": "How did Paulo feel at the end?", "options": ["Tired", "Bored", "Proud", "Confused"], "correct_index": 2, "explanation": "Paulo se sentiu orgulhoso por ajudar a cozinhar."}], "open_questions": [{"question": "What is a special recipe in your family? Describe it.", "key_points_pt": ["Descrever uma receita de família", "Usar vocabulário de comida"]}, {"question": "Do you enjoy cooking with your family? Why or why not?", "key_points_pt": ["Dar opinião pessoal", "Explicar o motivo"]}]}}, {"level": "A2", "genre": "sports", "title": "The Final Match", "paragraphs": ["Diego played soccer for his school team. Before the final match, he was very nervous because his team needed to win to become champions. His coach told him, 'Believe in yourself and play with your heart.'", "During the match, the game was difficult and the other team was strong. In the second half, Diego ran fast and scored a beautiful goal. His teammates ran to him and celebrated with big smiles.", "At the end, Diego's team won the match two to one. Everyone was happier than ever, and the coach gave Diego a small trophy for the best player. Diego learned that hard work and teamwork always help."], "paragraphs_pt": ["Diego jogava futebol pelo time da escola dele. Antes da partida final, ele estava muito nervoso porque o time dele precisava vencer para se tornar campeão. O técnico dele disse: 'Acredite em si mesmo e jogue com o coração.'", "Durante a partida, o jogo estava difícil e o outro time era forte. No segundo tempo, Diego correu rápido e marcou um golaço. Os companheiros de time correram até ele e comemoraram com grandes sorrisos.", "No final, o time de Diego venceu a partida por dois a um. Todo mundo estava mais feliz do que nunca, e o técnico deu a Diego um pequeno troféu de melhor jogador. Diego aprendeu que o trabalho duro e o trabalho em equipe sempre ajudam."], "hard_words": ["nervous", "scored", "teamwork"], "vocab": [{"word": "coach", "meaning": "técnico(a)", "note": ""}, {"word": "nervous", "meaning": "nervoso(a)", "note": ""}, {"word": "scored", "meaning": "marcou (um gol)", "note": ""}, {"word": "teammates", "meaning": "companheiros de time", "note": ""}, {"word": "celebrated", "meaning": "comemoraram", "note": ""}, {"word": "trophy", "meaning": "troféu", "note": ""}, {"word": "teamwork", "meaning": "trabalho em equipe", "note": ""}], "word_meanings": [{"word": "nervous", "meaning": "nervoso(a)", "note": ""}, {"word": "scored", "meaning": "marcou (um gol)", "note": ""}, {"word": "teamwork", "meaning": "trabalho em equipe", "note": ""}, {"word": "was", "meaning": "estava/era", "note": ""}, {"word": "played", "meaning": "jogava", "note": ""}, {"word": "needed", "meaning": "precisava", "note": ""}, {"word": "told", "meaning": "disse", "note": "passado irregular de tell"}, {"word": "ran", "meaning": "correu", "note": "passado irregular de run"}, {"word": "celebrated", "meaning": "comemoraram", "note": ""}, {"word": "won", "meaning": "venceu/ganhou", "note": "passado irregular de win"}, {"word": "gave", "meaning": "deu", "note": "passado irregular de give"}, {"word": "learned", "meaning": "aprendeu", "note": ""}, {"word": "because", "meaning": "porque", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "happier", "meaning": "mais feliz", "note": "comparativo de happy"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["played", "needed", "told", "ran", "celebrated", "won", "gave", "learned"], "phrasal": [], "wh": [], "connectors": ["because", "and"], "comparative": ["happier"]}, "exercises": {"grammar": [{"point": "Simple past for a series of events", "explanation_pt": "A história narra eventos em ordem usando verbos no passado, como 'ran', 'scored' e 'won'."}], "multiple_choice": [{"question": "Why was Diego nervous before the match?", "options": ["He was sick", "His team needed to win to become champions", "He forgot his shoes", "It was raining"], "correct_index": 1, "explanation": "Ele estava nervoso porque o time precisava vencer para ser campeão."}, {"question": "What did the coach tell Diego?", "options": ["To rest more", "To believe in himself and play with his heart", "To stay on the bench", "To change teams"], "correct_index": 1, "explanation": "O técnico disse para acreditar em si mesmo e jogar com o coração."}, {"question": "What did Diego do in the second half?", "options": ["He got injured", "He scored a goal", "He left the game", "He talked to the coach"], "correct_index": 1, "explanation": "No segundo tempo, Diego marcou um golaço."}, {"question": "What was the final score of the match?", "options": ["One to one", "Two to one", "Three to zero", "Zero to zero"], "correct_index": 1, "explanation": "O time de Diego venceu por dois a um."}, {"question": "What did Diego receive at the end?", "options": ["A new ball", "A trophy for the best player", "A medal for participation", "Nothing"], "correct_index": 1, "explanation": "O técnico deu a ele um troféu de melhor jogador."}], "open_questions": [{"question": "Do you play any sports? Which ones?", "key_points_pt": ["Falar sobre esportes praticados", "Descrever com frases simples"]}, {"question": "Why is teamwork important in sports?", "key_points_pt": ["Explicar a importância do trabalho em equipe", "Dar um exemplo"]}]}}, {"level": "A2", "genre": "slice", "title": "A Busy Afternoon", "paragraphs": ["After school, Julia picked up her little brother, Davi, from his classroom. They walked home together and talked about their day. Davi was excited because he drew a picture of a dinosaur.", "At home, Julia helped Davi with his homework while their mother cooked dinner. Davi asked many questions, and Julia answered them patiently. Then, they watched a short cartoon together before dinner.", "During dinner, the family talked about their day and laughed at Davi's funny stories. It was an ordinary afternoon, but Julia felt grateful for these simple moments with her family."], "paragraphs_pt": ["Depois da escola, Julia buscou o irmãozinho dela, Davi, na sala de aula. Eles caminharam juntos até em casa e conversaram sobre o dia deles. Davi estava animado porque desenhou um dinossauro.", "Em casa, Julia ajudou Davi com o dever de casa enquanto a mãe deles cozinhava o jantar. Davi fez muitas perguntas, e Julia respondeu com paciência. Depois, eles assistiram a um desenho animado curto antes do jantar.", "Durante o jantar, a família conversou sobre o dia deles e riu das histórias engraçadas de Davi. Foi uma tarde comum, mas Julia se sentiu grata por esses momentos simples com a família."], "hard_words": ["picked up", "patiently", "grateful"], "vocab": [{"word": "picked up", "meaning": "buscou/pegou", "note": "phrasal verb"}, {"word": "homework", "meaning": "dever de casa", "note": ""}, {"word": "patiently", "meaning": "com paciência", "note": ""}, {"word": "cartoon", "meaning": "desenho animado", "note": ""}, {"word": "laughed", "meaning": "riram", "note": ""}, {"word": "ordinary", "meaning": "comum/normal", "note": ""}, {"word": "grateful", "meaning": "grato(a)", "note": ""}], "word_meanings": [{"word": "picked up", "meaning": "buscou/pegou", "note": "phrasal verb"}, {"word": "patiently", "meaning": "com paciência", "note": ""}, {"word": "grateful", "meaning": "grato(a)", "note": ""}, {"word": "was", "meaning": "estava", "note": ""}, {"word": "walked", "meaning": "caminharam", "note": ""}, {"word": "talked", "meaning": "conversaram", "note": ""}, {"word": "drew", "meaning": "desenhou", "note": "passado irregular de draw"}, {"word": "helped", "meaning": "ajudou", "note": ""}, {"word": "cooked", "meaning": "cozinhava", "note": ""}, {"word": "asked", "meaning": "fez (perguntas)", "note": ""}, {"word": "answered", "meaning": "respondeu", "note": ""}, {"word": "watched", "meaning": "assistiram", "note": ""}, {"word": "laughed", "meaning": "riram", "note": ""}, {"word": "felt", "meaning": "se sentiu", "note": "passado irregular de feel"}, {"word": "while", "meaning": "enquanto", "note": ""}, {"word": "then", "meaning": "depois/então", "note": ""}, {"word": "because", "meaning": "porque", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "and", "meaning": "e", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["walked", "talked", "drew", "helped", "cooked", "asked", "answered", "watched", "laughed", "felt"], "phrasal": ["picked up"], "wh": [], "connectors": ["while", "then", "because", "but", "and"], "comparative": []}, "exercises": {"grammar": [{"point": "Connectors of time and contrast", "explanation_pt": "A palavra 'while' mostra duas ações ao mesmo tempo, e 'but' mostra contraste, como em 'ordinary afternoon, but... grateful'."}], "multiple_choice": [{"question": "Who did Julia pick up after school?", "options": ["Her friend", "Her little brother, Davi", "Her mother", "Her classmate"], "correct_index": 1, "explanation": "Julia buscou o irmãozinho dela, Davi."}, {"question": "Why was Davi excited?", "options": ["He got a new toy", "He drew a picture of a dinosaur", "He finished his homework", "He watched a movie"], "correct_index": 1, "explanation": "Ele estava animado porque desenhou um dinossauro."}, {"question": "What was their mother doing at home?", "options": ["Cleaning the house", "Cooking dinner", "Watching TV", "Reading a book"], "correct_index": 1, "explanation": "A mãe deles estava cozinhando o jantar."}, {"question": "What did Julia and Davi do before dinner?", "options": ["They played outside", "They watched a short cartoon", "They went shopping", "They slept"], "correct_index": 1, "explanation": "Eles assistiram a um desenho animado curto antes do jantar."}, {"question": "How did Julia feel about the afternoon?", "options": ["Bored", "Grateful", "Angry", "Confused"], "correct_index": 1, "explanation": "Julia se sentiu grata pelos momentos simples com a família."}], "open_questions": [{"question": "Describe a normal afternoon in your life.", "key_points_pt": ["Descrever uma rotina simples", "Usar conectores de tempo"]}, {"question": "Why are simple family moments important?", "key_points_pt": ["Dar opinião pessoal", "Explicar com um exemplo"]}]}}, {"level": "A2", "genre": "diary", "title": "My First Week at Work", "paragraphs": ["Dear diary, today was my first day at the new office. I felt nervous, but everyone was friendly. My boss showed me my desk and explained my new tasks carefully.", "On Wednesday, I met my coworkers during lunch. We talked about our hobbies, and I learned that two of them also like to play the guitar. I felt more comfortable after that conversation.", "Today is Friday, and my first week is finally over. It was tiring, but I am proud of myself. I hope next week will be even better, and I already feel like part of the team."], "paragraphs_pt": ["Querido diário, hoje foi meu primeiro dia no escritório novo. Eu me senti nervoso, mas todo mundo foi simpático. Meu chefe me mostrou minha mesa e explicou minhas novas tarefas com cuidado.", "Na quarta-feira, conheci meus colegas de trabalho durante o almoço. Conversamos sobre nossos hobbies, e eu descobri que dois deles também gostam de tocar violão. Eu me senti mais à vontade depois daquela conversa.", "Hoje é sexta-feira, e minha primeira semana finalmente terminou. Foi cansativo, mas estou orgulhoso de mim mesmo. Espero que a próxima semana seja ainda melhor, e eu já me sinto parte da equipe."], "hard_words": ["coworkers", "tiring", "comfortable"], "vocab": [{"word": "office", "meaning": "escritório", "note": ""}, {"word": "boss", "meaning": "chefe", "note": ""}, {"word": "tasks", "meaning": "tarefas", "note": ""}, {"word": "coworkers", "meaning": "colegas de trabalho", "note": ""}, {"word": "comfortable", "meaning": "confortável/à vontade", "note": ""}, {"word": "tiring", "meaning": "cansativo(a)", "note": ""}, {"word": "proud", "meaning": "orgulhoso(a)", "note": ""}], "word_meanings": [{"word": "coworkers", "meaning": "colegas de trabalho", "note": ""}, {"word": "tiring", "meaning": "cansativo(a)", "note": ""}, {"word": "comfortable", "meaning": "confortável/à vontade", "note": ""}, {"word": "was", "meaning": "foi/estava", "note": ""}, {"word": "is", "meaning": "é", "note": ""}, {"word": "am", "meaning": "estou", "note": ""}, {"word": "felt", "meaning": "senti", "note": "passado irregular de feel"}, {"word": "showed", "meaning": "mostrou", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "met", "meaning": "conheci", "note": "passado irregular de meet"}, {"word": "talked", "meaning": "conversamos", "note": ""}, {"word": "learned", "meaning": "descobri/aprendi", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "and", "meaning": "e", "note": ""}, {"word": "more comfortable", "meaning": "mais confortável/à vontade", "note": "comparativo"}, {"word": "better", "meaning": "melhor", "note": "comparativo irregular de good"}], "grammar_words": {"cognates": [], "tobe": ["was", "is", "am"], "irregular": ["felt", "showed", "explained", "met", "talked", "learned"], "phrasal": [], "wh": [], "connectors": ["but", "and"], "comparative": ["more comfortable", "better"]}, "exercises": {"grammar": [{"point": "Diary style with present and past", "explanation_pt": "Diários usam o passado para contar o que aconteceu e o presente para o dia atual, como em 'Today is Friday'."}], "multiple_choice": [{"question": "How did the writer feel on the first day?", "options": ["Bored", "Nervous", "Angry", "Confident"], "correct_index": 1, "explanation": "O escritor se sentiu nervoso no primeiro dia."}, {"question": "Who showed the writer their desk?", "options": ["A coworker", "The boss", "A friend", "The receptionist"], "correct_index": 1, "explanation": "O chefe mostrou a mesa para o escritor."}, {"question": "When did the writer meet coworkers?", "options": ["On Monday", "During lunch on Wednesday", "On the weekend", "After work"], "correct_index": 1, "explanation": "O escritor conheceu os colegas durante o almoço na quarta-feira."}, {"question": "What hobby did some coworkers share?", "options": ["Cooking", "Playing the guitar", "Painting", "Running"], "correct_index": 1, "explanation": "Dois colegas também gostavam de tocar violão."}, {"question": "How did the writer feel at the end of the week?", "options": ["Sad and tired", "Proud, although tired", "Angry", "Bored"], "correct_index": 1, "explanation": "O escritor estava cansado, mas orgulhoso de si mesmo."}], "open_questions": [{"question": "How did you feel on your first day at a new job or school?", "key_points_pt": ["Descrever sentimentos pessoais", "Usar o passado simples"]}, {"question": "What makes you feel comfortable with new people?", "key_points_pt": ["Dar exemplos pessoais", "Explicar o motivo"]}]}}, {"level": "A2", "genre": "superhero", "title": "The Quiet Hero", "paragraphs": ["In the city of Rivera, a young woman named Sofia had a secret power: she could move very fast, faster than any car. At night, she became Flash Girl and helped people who needed her.", "One evening, Sofia heard that a bridge was going to collapse. She ran to the bridge faster than the wind and helped everyone cross safely before it broke. The people did not know who saved them.", "The next day, Sofia went to work like a normal person. Nobody knew her secret, but she felt proud of her night adventure. She smiled quietly, ready to help again whenever the city needed Flash Girl."], "paragraphs_pt": ["Na cidade de Rivera, uma jovem chamada Sofia tinha um poder secreto: ela conseguia se mover muito rápido, mais rápido do que qualquer carro. À noite, ela se tornava a Garota Relâmpago e ajudava pessoas que precisavam dela.", "Certa noite, Sofia ouviu que uma ponte ia desabar. Ela correu até a ponte mais rápido do que o vento e ajudou todo mundo a atravessar em segurança antes que a ponte quebrasse. As pessoas não sabiam quem as salvou.", "No dia seguinte, Sofia foi trabalhar como uma pessoa normal. Ninguém sabia o segredo dela, mas ela se sentiu orgulhosa da aventura noturna dela. Ela sorriu discretamente, pronta para ajudar de novo sempre que a cidade precisasse da Garota Relâmpago."], "hard_words": ["collapse", "safely", "quietly"], "vocab": [{"word": "secret", "meaning": "secreto(a)/segredo", "note": ""}, {"word": "power", "meaning": "poder", "note": ""}, {"word": "bridge", "meaning": "ponte", "note": ""}, {"word": "collapse", "meaning": "desabar", "note": ""}, {"word": "safely", "meaning": "com segurança", "note": ""}, {"word": "saved", "meaning": "salvou", "note": ""}, {"word": "quietly", "meaning": "discretamente/silenciosamente", "note": ""}], "word_meanings": [{"word": "collapse", "meaning": "desabar", "note": ""}, {"word": "safely", "meaning": "com segurança", "note": ""}, {"word": "quietly", "meaning": "discretamente/silenciosamente", "note": ""}, {"word": "had", "meaning": "tinha", "note": "passado irregular de have"}, {"word": "became", "meaning": "se tornou/se tornava", "note": "passado irregular de become"}, {"word": "helped", "meaning": "ajudava/ajudou", "note": ""}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular de hear"}, {"word": "ran", "meaning": "correu", "note": "passado irregular de run"}, {"word": "broke", "meaning": "quebrou", "note": "passado irregular de break"}, {"word": "saved", "meaning": "salvou", "note": ""}, {"word": "went", "meaning": "foi", "note": "passado irregular de go"}, {"word": "knew", "meaning": "sabia", "note": "passado irregular de know"}, {"word": "felt", "meaning": "sentiu", "note": "passado irregular de feel"}, {"word": "smiled", "meaning": "sorriu", "note": ""}, {"word": "who", "meaning": "quem", "note": ""}, {"word": "but", "meaning": "mas", "note": ""}, {"word": "before", "meaning": "antes", "note": ""}, {"word": "faster", "meaning": "mais rápido(a)", "note": "comparativo de fast"}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["had", "became", "helped", "heard", "ran", "broke", "saved", "went", "knew", "felt", "smiled"], "phrasal": [], "wh": ["who"], "connectors": ["but", "before"], "comparative": ["faster"]}, "exercises": {"grammar": [{"point": "Comparative 'faster than'", "explanation_pt": "Usamos 'faster than' para comparar velocidade, como em 'faster than any car'."}], "multiple_choice": [{"question": "What was Sofia's secret power?", "options": ["She could fly", "She could move very fast", "She was very strong", "She could become invisible"], "correct_index": 1, "explanation": "O poder secreto de Sofia era se mover muito rápido."}, {"question": "What name did Sofia use at night?", "options": ["Super Sofia", "Flash Girl", "The Runner", "Night Hero"], "correct_index": 1, "explanation": "À noite, ela se tornava a Flash Girl."}, {"question": "What was going to happen to the bridge?", "options": ["It was going to be painted", "It was going to collapse", "It was going to open", "It was going to close for repairs"], "correct_index": 1, "explanation": "A ponte ia desabar."}, {"question": "Did the people know who saved them?", "options": ["Yes, everyone knew", "No, they did not know", "Only the children knew", "Only one person knew"], "correct_index": 1, "explanation": "As pessoas não sabiam quem as salvou."}, {"question": "How did Sofia feel the next day?", "options": ["Sad", "Proud", "Angry", "Bored"], "correct_index": 1, "explanation": "Ela se sentiu orgulhosa da aventura noturna dela."}], "open_questions": [{"question": "If you had a superpower, what would it be?", "key_points_pt": ["Descrever um superpoder imaginado", "Explicar como usaria o poder"]}, {"question": "Why do you think Sofia kept her power a secret?", "key_points_pt": ["Dar uma opinião", "Justificar com um argumento simples"]}]}}, {"level": "B1", "genre": "neutral", "title": "The New Neighbor", "paragraphs": ["Marta lived alone in a small apartment on the third floor. She liked her quiet life, but last month a new neighbor moved into the flat next door. His name was Diego, and he had two loud dogs and a lot of boxes.", "At first, Marta was annoyed by the noise. However, one evening Diego knocked on her door. He explained that he was sorry for the mess and offered her some homemade bread. Marta was surprised, but she accepted it politely.", "Over the next few weeks, they started talking whenever they met in the hallway. Diego told her about his job as a teacher, and Marta talked about her garden on the balcony. Although they were very different people, they slowly became friends.", "By the end of the year, Marta no longer minded the dogs barking. In fact, she often walked them when Diego worked late. She realized that a new neighbor could change her life in a good way, and she was thankful for that."], "paragraphs_pt": ["Marta morava sozinha em um pequeno apartamento no terceiro andar. Ela gostava da sua vida tranquila, mas no mês passado um novo vizinho se mudou para o apartamento ao lado. O nome dele era Diego, e ele tinha dois cachorros barulhentos e muitas caixas.", "No início, Marta ficou incomodada com o barulho. No entanto, numa noite Diego bateu na porta dela. Ele explicou que sentia muito pela bagunça e ofereceu a ela um pão caseiro. Marta ficou surpresa, mas aceitou educadamente.", "Nas semanas seguintes, eles começaram a conversar sempre que se encontravam no corredor. Diego contou sobre seu trabalho como professor, e Marta falou sobre seu jardim na varanda. Embora fossem pessoas muito diferentes, aos poucos se tornaram amigos.", "No final do ano, Marta já não se incomodava mais com os cachorros latindo. Na verdade, ela muitas vezes os passeava quando Diego trabalhava até tarde. Ela percebeu que um novo vizinho podia mudar sua vida para melhor, e ela era grata por isso."], "hard_words": ["annoyed", "mess", "hallway", "thankful"], "vocab": [{"word": "neighbor", "meaning": "vizinho(a)", "note": ""}, {"word": "quiet", "meaning": "tranquilo, silencioso", "note": ""}, {"word": "knocked on", "meaning": "bateu na (porta)", "note": ""}, {"word": "homemade", "meaning": "caseiro", "note": ""}, {"word": "hallway", "meaning": "corredor", "note": ""}, {"word": "barking", "meaning": "latindo", "note": ""}, {"word": "thankful", "meaning": "grato(a)", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["lived", "moved", "explained", "offered", "accepted", "started", "told", "became", "realized"], "phrasal": ["moved into"], "wh": ["whenever"], "connectors": ["but", "However", "Although", "and"], "comparative": []}, "word_meanings": [{"word": "annoyed", "meaning": "incomodado(a), irritado(a)", "note": ""}, {"word": "mess", "meaning": "bagunça", "note": ""}, {"word": "hallway", "meaning": "corredor", "note": ""}, {"word": "thankful", "meaning": "grato(a)", "note": ""}, {"word": "realize", "meaning": "perceber, se dar conta", "note": "falso cognato: não é 'realizar' (fazer)"}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato: não é 'atualmente'"}, {"word": "lived", "meaning": "morou/morava", "note": ""}, {"word": "moved", "meaning": "mudou-se", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "offered", "meaning": "ofereceu", "note": ""}, {"word": "accepted", "meaning": "aceitou", "note": ""}, {"word": "started", "meaning": "começou", "note": ""}, {"word": "told", "meaning": "contou", "note": "passado de tell"}, {"word": "became", "meaning": "tornou-se", "note": "passado de become"}, {"word": "realized", "meaning": "percebeu", "note": ""}, {"word": "moved into", "meaning": "mudou-se para", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Simple past", "explanation_pt": "Usamos o passado simples para ações concluídas: 'Diego knocked on her door' (Diego bateu na porta dela)."}, {"point": "Although / However", "explanation_pt": "Mostram contraste. Exemplo: 'Although they were very different people, they slowly became friends.'"}], "multiple_choice": [{"question": "What did Diego bring to Marta's door?", "options": ["Flowers", "Homemade bread", "A dog", "A box"], "correct_index": 1, "explanation": "Diego trouxe pão caseiro para se desculpar."}, {"question": "Why was Marta annoyed at first?", "options": ["Diego was rude", "The dogs were loud", "The rent was high", "The apartment was small"], "correct_index": 1, "explanation": "Os cachorros de Diego eram barulhentos."}, {"question": "What is Diego's job?", "options": ["Doctor", "Teacher", "Cook", "Driver"], "correct_index": 1, "explanation": "Diego trabalha como professor."}, {"question": "Where does Marta have a garden?", "options": ["In the yard", "On the balcony", "In the park", "At Diego's house"], "correct_index": 1, "explanation": "O jardim de Marta fica na varanda."}, {"question": "How did Marta feel about Diego by the end of the year?", "options": ["Angry", "Indifferent", "Thankful", "Scared"], "correct_index": 2, "explanation": "No final, Marta ficou grata pela amizade."}], "open_questions": [{"question": "Do you think it is easy to become friends with a neighbor? Why or why not?", "key_points_pt": ["Depende da personalidade e da rotina de cada um", "Pequenos gestos ajudam a criar confiança"]}, {"question": "Describe a time when a first impression of someone changed over time.", "key_points_pt": ["Falar sobre a primeira impressão", "Explicar o que mudou essa opinião"]}]}}, {"level": "B1", "genre": "humor", "title": "The Wrong Suitcase", "paragraphs": ["Pedro was in a hurry at the airport, so he grabbed his suitcase and ran to the gate. He didn't check the tag, and when he opened it at the hotel, he found women's dresses, a pink hairbrush, and a teddy bear instead of his clothes.", "He called the airline immediately, and they told him the real owner, a woman named Sofia, had his suitcase too. Pedro imagined Sofia opening his bag and finding his old socks and a bag of chips he forgot to eat.", "The next day, they met at the airport to switch the suitcases back. Sofia laughed so hard that she could barely speak. \"I actually wore one of your t-shirts to sleep,\" she admitted, and Pedro turned bright red with embarrassment.", "In the end, they exchanged phone numbers and later became good friends. Pedro still jokes that losing his suitcase was the best mistake of his trip, because it gave him a funny story and a new friend."], "paragraphs_pt": ["Pedro estava com pressa no aeroporto, então pegou sua mala e correu para o portão. Ele não conferiu a etiqueta, e quando a abriu no hotel, encontrou vestidos femininos, uma escova de cabelo rosa e um ursinho de pelúcia em vez das suas roupas.", "Ele ligou para a companhia aérea imediatamente, e eles disseram que a verdadeira dona, uma mulher chamada Sofia, também estava com a mala dele. Pedro imaginou Sofia abrindo sua mala e encontrando suas meias velhas e um pacote de batatas fritas que ele esqueceu de comer.", "No dia seguinte, eles se encontraram no aeroporto para trocar as malas de volta. Sofia riu tanto que mal conseguia falar. \"Na verdade, eu usei uma das suas camisetas para dormir\", ela admitiu, e Pedro ficou vermelho de vergonha.", "No final, eles trocaram números de telefone e depois se tornaram bons amigos. Pedro ainda brinca que perder a mala foi o melhor erro da viagem, porque lhe deu uma história engraçada e um novo amigo."], "hard_words": ["suitcase", "tag", "hairbrush", "embarrassment"], "vocab": [{"word": "in a hurry", "meaning": "com pressa", "note": ""}, {"word": "grabbed", "meaning": "pegou (rapidamente)", "note": ""}, {"word": "teddy bear", "meaning": "ursinho de pelúcia", "note": ""}, {"word": "switch", "meaning": "trocar", "note": ""}, {"word": "barely", "meaning": "mal, quase não", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "turned red", "meaning": "ficou vermelho(a)", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["was"], "irregular": ["grabbed", "ran", "opened", "found", "called", "told", "imagined", "met", "laughed", "admitted", "turned", "exchanged", "became"], "phrasal": [], "wh": [], "connectors": ["so", "and", "because"], "comparative": ["the best mistake"]}, "word_meanings": [{"word": "suitcase", "meaning": "mala", "note": ""}, {"word": "tag", "meaning": "etiqueta", "note": ""}, {"word": "hairbrush", "meaning": "escova de cabelo", "note": ""}, {"word": "embarrassment", "meaning": "vergonha, constrangimento", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "grabbed", "meaning": "pegou", "note": ""}, {"word": "ran", "meaning": "correu", "note": "passado de run"}, {"word": "opened", "meaning": "abriu", "note": ""}, {"word": "found", "meaning": "encontrou", "note": "passado de find"}, {"word": "called", "meaning": "ligou", "note": ""}, {"word": "told", "meaning": "disse/contou", "note": ""}, {"word": "imagined", "meaning": "imaginou", "note": ""}, {"word": "met", "meaning": "encontrou-se", "note": "passado de meet"}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "turned", "meaning": "ficou (mudou)", "note": ""}, {"word": "exchanged", "meaning": "trocaram", "note": ""}, {"word": "became", "meaning": "tornaram-se", "note": ""}, {"word": "switch back", "meaning": "trocar de volta", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Simple past narration", "explanation_pt": "O passado simples conta eventos em sequência: 'Pedro called the airline immediately.'"}, {"point": "Direct speech", "explanation_pt": "Usamos aspas para reproduzir a fala: '\"I actually wore one of your t-shirts to sleep,\" she admitted.'"}], "multiple_choice": [{"question": "What did Pedro find in the wrong suitcase?", "options": ["Books", "Women's dresses", "Shoes", "Tools"], "correct_index": 1, "explanation": "Ele encontrou vestidos femininos."}, {"question": "Who had Pedro's suitcase?", "options": ["The airline", "Sofia", "A hotel worker", "No one"], "correct_index": 1, "explanation": "Sofia estava com a mala de Pedro."}, {"question": "What did Sofia wear to sleep?", "options": ["Her own pajamas", "A hotel robe", "One of Pedro's t-shirts", "Nothing special"], "correct_index": 2, "explanation": "Ela admitiu ter usado uma camiseta de Pedro."}, {"question": "How did Pedro react when Sofia told him this?", "options": ["He got angry", "He turned red", "He left immediately", "He didn't believe her"], "correct_index": 1, "explanation": "Pedro ficou vermelho de vergonha."}, {"question": "What happened between Pedro and Sofia in the end?", "options": ["They never spoke again", "They became friends", "They argued", "They lost the suitcases again"], "correct_index": 1, "explanation": "Eles se tornaram amigos."}], "open_questions": [{"question": "Have you ever made a funny mistake while traveling? What happened?", "key_points_pt": ["Descrever a situação e o erro cometido", "Explicar como terminou"]}, {"question": "Do you think mistakes can sometimes lead to good things? Give an example.", "key_points_pt": ["Comentar sobre erros que trazem resultados positivos", "Usar exemplo pessoal ou da história"]}]}}, {"level": "B1", "genre": "suspense", "title": "The Locked Room", "paragraphs": ["Ana worked late at the museum, cataloging old paintings. Around midnight, she heard a strange noise coming from the storage room, a room that was always locked. Her heart began to beat faster, and she slowly walked toward the door.", "The door was slightly open, although she was sure she had locked it herself that morning. Inside, a single lamp was on, and papers were scattered across the floor. Someone had clearly been searching for something.", "Ana looked for her phone to call security, but it wasn't in her pocket. Then she noticed a shadow move behind a large painting. She froze, unsure whether to run or to find out who was hiding there.", "Finally, a security guard stepped out from behind the painting, looking embarrassed. He explained that he had lost his keys and was searching for them quietly so he wouldn't wake the other staff. Ana let out a long breath of relief, though her hands were still shaking."], "paragraphs_pt": ["Ana trabalhava até tarde no museu, catalogando pinturas antigas. Por volta da meia-noite, ela ouviu um barulho estranho vindo da sala de armazenamento, uma sala que estava sempre trancada. Seu coração começou a bater mais rápido, e ela caminhou devagar em direção à porta.", "A porta estava levemente aberta, embora ela tivesse certeza de que a havia trancado ela mesma naquela manhã. Lá dentro, uma única lâmpada estava acesa, e papéis estavam espalhados pelo chão. Alguém claramente estivera procurando por algo.", "Ana procurou o celular para chamar a segurança, mas ele não estava no bolso. Então ela notou uma sombra se mover atrás de um grande quadro. Ela congelou, sem saber se corria ou descobria quem estava se escondendo ali.", "Finalmente, um segurança saiu de trás do quadro, parecendo envergonhado. Ele explicou que havia perdido as chaves e estava procurando por elas em silêncio para não acordar os outros funcionários. Ana soltou um longo suspiro de alívio, embora suas mãos ainda estivessem tremendo."], "hard_words": ["cataloging", "scattered", "froze", "shaking"], "vocab": [{"word": "storage room", "meaning": "sala de armazenamento/depósito", "note": ""}, {"word": "heart began to beat faster", "meaning": "coração começou a bater mais rápido", "note": ""}, {"word": "shadow", "meaning": "sombra", "note": ""}, {"word": "froze", "meaning": "congelou (de medo)", "note": "passado de freeze"}, {"word": "find out", "meaning": "descobrir", "note": ""}, {"word": "let out a breath", "meaning": "soltou um suspiro", "note": ""}, {"word": "relief", "meaning": "alívio", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "wasn't"], "irregular": ["worked", "heard", "began", "walked", "was", "noticed", "froze", "stepped", "explained", "lost", "let"], "phrasal": ["find out"], "wh": ["who", "whether"], "connectors": ["although", "but", "Then", "So", "though"], "comparative": ["faster"]}, "word_meanings": [{"word": "cataloging", "meaning": "catalogando", "note": ""}, {"word": "scattered", "meaning": "espalhados", "note": ""}, {"word": "froze", "meaning": "congelou", "note": ""}, {"word": "shaking", "meaning": "tremendo", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "worked", "meaning": "trabalhou", "note": ""}, {"word": "heard", "meaning": "ouviu", "note": "passado de hear"}, {"word": "began", "meaning": "começou", "note": "passado de begin"}, {"word": "walked", "meaning": "caminhou", "note": ""}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "stepped", "meaning": "deu um passo/saiu", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "lost", "meaning": "perdeu", "note": ""}, {"word": "let", "meaning": "deixou/soltou", "note": ""}, {"word": "find out", "meaning": "descobrir", "note": "phrasal verb"}, {"word": "step out", "meaning": "sair", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Past continuous vs simple past", "explanation_pt": "O passado contínuo descreve uma ação em progresso: 'Someone had clearly been searching for something' mostra ação anterior contínua."}, {"point": "Whether", "explanation_pt": "'Whether' introduz uma dúvida entre duas opções: 'unsure whether to run or to find out'."}], "multiple_choice": [{"question": "What time did Ana hear the strange noise?", "options": ["Morning", "Afternoon", "Midnight", "Evening"], "correct_index": 2, "explanation": "O barulho aconteceu por volta da meia-noite."}, {"question": "What did Ana find on the floor of the storage room?", "options": ["Broken glass", "Scattered papers", "Water", "Money"], "correct_index": 1, "explanation": "Havia papéis espalhados pelo chão."}, {"question": "Why couldn't Ana call security right away?", "options": ["The phone was broken", "She didn't have her phone", "Security didn't answer", "There was no signal"], "correct_index": 1, "explanation": "Seu celular não estava no bolso."}, {"question": "Who was hiding behind the painting?", "options": ["A thief", "Another curator", "A security guard", "No one"], "correct_index": 2, "explanation": "Era um segurança procurando suas chaves."}, {"question": "Why was the guard searching quietly?", "options": ["He was stealing something", "He didn't want to wake the staff", "He was testing the alarm", "He was hiding from Ana"], "correct_index": 1, "explanation": "Ele não queria acordar os outros funcionários."}], "open_questions": [{"question": "How would you have reacted if you were in Ana's position?", "key_points_pt": ["Falar sobre medo ou coragem", "Comparar com a reação de Ana"]}, {"question": "Why do you think suspense stories often end with a simple explanation?", "key_points_pt": ["Discutir tensão seguida de alívio", "Comentar o efeito na história"]}]}}, {"level": "B1", "genre": "detective", "title": "The Missing Necklace", "paragraphs": ["Detective Silva arrived at the mansion after the owner reported that a diamond necklace had disappeared from her bedroom. Five people had been in the house that night: the maid, the cook, the gardener, the owner's nephew, and a family friend.", "Silva questioned each person carefully, and he noticed that the gardener's hands were shaking. However, he decided not to jump to conclusions. Instead, he examined the bedroom window, which was unlocked despite the cold weather outside.", "He found a small piece of fabric caught on the window frame. It matched the nephew's jacket exactly. When Silva confronted him, the nephew finally confessed that he had taken the necklace because he needed money to pay off a debt.", "The owner was relieved to get her necklace back, although she was sad to learn that her own nephew had stolen it. Silva reminded her that people sometimes make bad choices when they feel desperate, but that didn't make the theft acceptable."], "paragraphs_pt": ["O detetive Silva chegou à mansão depois que a dona relatou que um colar de diamantes havia desaparecido do seu quarto. Cinco pessoas estiveram na casa naquela noite: a empregada, a cozinheira, o jardineiro, o sobrinho da dona e um amigo da família.", "Silva interrogou cada pessoa com cuidado, e notou que as mãos do jardineiro estavam tremendo. No entanto, ele decidiu não tirar conclusões precipitadas. Em vez disso, examinou a janela do quarto, que estava destrancada apesar do frio lá fora.", "Ele encontrou um pequeno pedaço de tecido preso na moldura da janela. Combinava exatamente com o casaco do sobrinho. Quando Silva o confrontou, o sobrinho finalmente confessou que havia pegado o colar porque precisava de dinheiro para pagar uma dívida.", "A dona ficou aliviada por recuperar o colar, embora tenha ficado triste ao saber que seu próprio sobrinho o havia roubado. Silva lembrou a ela que as pessoas às vezes fazem escolhas erradas quando se sentem desesperadas, mas isso não tornava o roubo aceitável."], "hard_words": ["mansion", "fabric", "confessed", "desperate"], "vocab": [{"word": "necklace", "meaning": "colar", "note": ""}, {"word": "maid", "meaning": "empregada", "note": ""}, {"word": "jump to conclusions", "meaning": "tirar conclusões precipitadas", "note": ""}, {"word": "unlocked", "meaning": "destrancado", "note": ""}, {"word": "caught on", "meaning": "preso em", "note": ""}, {"word": "confronted", "meaning": "confrontou", "note": ""}, {"word": "pay off a debt", "meaning": "pagar uma dívida", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["arrived", "reported", "questioned", "noticed", "decided", "examined", "found", "confronted", "confessed", "reminded"], "phrasal": ["jump to", "pay off"], "wh": ["which"], "connectors": ["However", "Instead", "although", "but", "because"], "comparative": []}, "word_meanings": [{"word": "mansion", "meaning": "mansão", "note": ""}, {"word": "fabric", "meaning": "tecido", "note": ""}, {"word": "confessed", "meaning": "confessou", "note": ""}, {"word": "desperate", "meaning": "desesperado(a)", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "arrived", "meaning": "chegou", "note": ""}, {"word": "reported", "meaning": "relatou", "note": ""}, {"word": "questioned", "meaning": "interrogou", "note": ""}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "decided", "meaning": "decidiu", "note": ""}, {"word": "examined", "meaning": "examinou", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "confronted", "meaning": "confrontou", "note": ""}, {"word": "took", "meaning": "pegou", "note": "passado de take"}, {"word": "learned", "meaning": "soube/aprendeu", "note": ""}, {"word": "reminded", "meaning": "lembrou", "note": ""}, {"word": "felt", "meaning": "sentiu", "note": "passado de feel"}, {"word": "jump to", "meaning": "tirar (conclusões) precipitadamente", "note": "phrasal verb"}, {"word": "pay off", "meaning": "quitar, pagar totalmente", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "Usamos o past perfect para uma ação anterior a outra no passado: 'a diamond necklace had disappeared' (o colar já havia desaparecido antes da chegada de Silva)."}, {"point": "Despite", "explanation_pt": "'Despite' + substantivo mostra contraste: 'unlocked despite the cold weather' (destrancada apesar do frio)."}], "multiple_choice": [{"question": "What went missing from the bedroom?", "options": ["A ring", "A diamond necklace", "A watch", "Money"], "correct_index": 1, "explanation": "Um colar de diamantes desapareceu."}, {"question": "Who did Silva notice was shaking?", "options": ["The maid", "The cook", "The gardener", "The nephew"], "correct_index": 2, "explanation": "As mãos do jardineiro estavam tremendo, mas isso não o tornava culpado."}, {"question": "Where did Silva find a piece of fabric?", "options": ["On the door", "On the window frame", "On the floor", "In the garden"], "correct_index": 1, "explanation": "O tecido estava preso na moldura da janela."}, {"question": "Who had taken the necklace?", "options": ["The gardener", "The maid", "The nephew", "The cook"], "correct_index": 2, "explanation": "O sobrinho confessou ter pegado o colar."}, {"question": "Why did the nephew take the necklace?", "options": ["He wanted to sell it as art", "He needed money for a debt", "He was angry at his aunt", "He wanted to hide it"], "correct_index": 1, "explanation": "Ele precisava de dinheiro para pagar uma dívida."}], "open_questions": [{"question": "Do you think Silva was right not to suspect the gardener immediately? Why?", "key_points_pt": ["Discutir a importância de evidências antes de acusar alguém", "Comentar sobre julgar por aparências"]}, {"question": "Do you agree with Silva that desperation doesn't excuse stealing? Why or why not?", "key_points_pt": ["Expressar opinião pessoal sobre ética e necessidade", "Considerar diferentes pontos de vista"]}]}}, {"level": "B1", "genre": "romance", "title": "Letters from the Train", "paragraphs": ["Every Monday, Lucas took the same train to work, and every Monday, he saw the same woman reading a book by the window. He never spoke to her, but he always wondered what she was reading and what her name was.", "One rainy morning, she accidentally left her book on the seat when she got off the train. Lucas picked it up and found a small note inside with her name, Camila, and a line from her favorite poem. He decided to write her a short letter and leave it at the same seat the next Monday.", "To his surprise, Camila found the letter and wrote back the following week. For two months, they exchanged letters through the same book, sharing thoughts about life, music, and their dreams, although they had still never spoken face to face.", "Finally, one Monday, Camila sat down next to Lucas instead of by the window. \"I think it's time we actually talked,\" she said with a smile. Lucas laughed nervously, and from that day, they never needed to write letters again because they simply talked every morning on the train."], "paragraphs_pt": ["Toda segunda-feira, Lucas pegava o mesmo trem para o trabalho, e toda segunda-feira via a mesma mulher lendo um livro perto da janela. Ele nunca falou com ela, mas sempre se perguntava o que ela estava lendo e qual era o nome dela.", "Numa manhã chuvosa, ela acidentalmente esqueceu o livro no banco quando desceu do trem. Lucas o pegou e encontrou um pequeno bilhete dentro com o nome dela, Camila, e um verso do poema favorito dela. Ele decidiu escrever um bilhete curto para ela e deixá-lo no mesmo banco na segunda-feira seguinte.", "Para sua surpresa, Camila encontrou o bilhete e respondeu na semana seguinte. Por dois meses, eles trocaram bilhetes através do mesmo livro, compartilhando pensamentos sobre a vida, música e seus sonhos, embora ainda nunca tivessem se falado pessoalmente.", "Finalmente, numa segunda-feira, Camila sentou-se ao lado de Lucas em vez de perto da janela. \"Acho que é hora de a gente realmente conversar\", ela disse com um sorriso. Lucas riu nervosamente, e a partir daquele dia, eles nunca mais precisaram escrever bilhetes, porque simplesmente conversavam toda manhã no trem."], "hard_words": ["accidentally", "note", "poem", "nervously"], "vocab": [{"word": "wondered", "meaning": "perguntava-se, imaginava", "note": ""}, {"word": "got off", "meaning": "desceu (de um veículo)", "note": ""}, {"word": "picked it up", "meaning": "pegou", "note": ""}, {"word": "to his surprise", "meaning": "para sua surpresa", "note": ""}, {"word": "wrote back", "meaning": "respondeu por escrito", "note": ""}, {"word": "face to face", "meaning": "cara a cara, pessoalmente", "note": ""}, {"word": "smile", "meaning": "sorriso", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["was"], "irregular": ["took", "saw", "spoke", "wondered", "left", "got", "found", "decided", "wrote", "exchanged", "sat", "said", "laughed"], "phrasal": ["got off"], "wh": ["what"], "connectors": ["but", "although", "because"], "comparative": []}, "word_meanings": [{"word": "accidentally", "meaning": "acidentalmente", "note": ""}, {"word": "note", "meaning": "bilhete", "note": ""}, {"word": "poem", "meaning": "poema", "note": ""}, {"word": "nervously", "meaning": "nervosamente", "note": ""}, {"word": "actually", "meaning": "na verdade, de fato", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "took", "meaning": "pegou/tomou", "note": ""}, {"word": "saw", "meaning": "viu", "note": "passado de see"}, {"word": "spoke", "meaning": "falou", "note": "passado de speak"}, {"word": "wondered", "meaning": "perguntava-se", "note": ""}, {"word": "left", "meaning": "deixou", "note": "passado de leave"}, {"word": "got", "meaning": "ficou/obteve", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "decided", "meaning": "decidiu", "note": ""}, {"word": "wrote", "meaning": "escreveu", "note": "passado de write"}, {"word": "exchanged", "meaning": "trocaram", "note": ""}, {"word": "sat", "meaning": "sentou-se", "note": "passado de sit"}, {"word": "said", "meaning": "disse", "note": "passado de say"}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "got off", "meaning": "desceu", "note": "phrasal verb"}, {"word": "picked up", "meaning": "pegou", "note": "phrasal verb"}, {"word": "write back", "meaning": "responder por escrito", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Simple past for a routine broken by an event", "explanation_pt": "'Every Monday' descreve rotina, mas 'One rainy morning, she accidentally left her book' mostra um evento específico no passado simples."}, {"point": "Instead of + gerúndio", "explanation_pt": "'Instead of' é seguido de verbo com -ing ou substantivo: 'sat down next to Lucas instead of by the window'."}], "multiple_choice": [{"question": "What did Lucas notice about the woman every Monday?", "options": ["She talked loudly", "She read a book", "She slept", "She listened to music"], "correct_index": 1, "explanation": "Ela lia um livro toda segunda-feira."}, {"question": "What did Camila leave behind on the train?", "options": ["Her phone", "Her umbrella", "Her book", "Her bag"], "correct_index": 2, "explanation": "Ela esqueceu o livro no banco."}, {"question": "What did Lucas find inside the book?", "options": ["Money", "A photo", "A note with her name", "A ticket"], "correct_index": 2, "explanation": "Havia um bilhete com o nome dela, Camila."}, {"question": "How long did they exchange letters before speaking?", "options": ["One week", "Two months", "One year", "They never wrote letters"], "correct_index": 1, "explanation": "Eles trocaram bilhetes por dois meses."}, {"question": "What did Camila do on the final Monday in the story?", "options": ["She stopped taking the train", "She sat next to Lucas", "She left another note", "She moved away"], "correct_index": 1, "explanation": "Ela sentou-se ao lado de Lucas em vez da janela."}], "open_questions": [{"question": "Do you think writing letters is a romantic way to get to know someone? Why?", "key_points_pt": ["Comparar comunicação escrita e conversa direta", "Falar sobre vantagens e desvantagens de cada uma"]}, {"question": "Have you ever had a memorable moment with a stranger? Describe it.", "key_points_pt": ["Descrever brevemente a situação", "Explicar por que foi memorável"]}]}}, {"level": "B1", "genre": "scifi", "title": "The Last Signal", "paragraphs": ["In the year 2185, Captain Rina flew a small research ship near the edge of known space. Her mission was simple: find the source of a strange radio signal that scientists on Earth had been receiving for months. No one knew if it came from a machine or something alive.", "As her ship approached a quiet, gray planet, the signal grew louder. Rina landed carefully and walked outside in her heavy suit. She found an old satellite, broken and covered in dust, still sending its weak signal into space after decades of silence.", "Inside the satellite's memory, she discovered recorded messages from a human colony that had lived on the planet many years earlier. The colony had run out of resources and had to leave, but they left the satellite behind so that someone, someday, might find their story.", "Rina sat quietly for a moment, thinking about the people who had once called this cold planet home. She recorded a new message for anyone who might come after her, then returned to her ship, carrying a piece of history that connected the past to the future."], "paragraphs_pt": ["No ano de 2185, a capitã Rina pilotava uma pequena nave de pesquisa perto do limite do espaço conhecido. Sua missão era simples: encontrar a origem de um sinal de rádio estranho que os cientistas na Terra vinham recebendo havia meses. Ninguém sabia se vinha de uma máquina ou de algo vivo.", "Enquanto sua nave se aproximava de um planeta cinza e silencioso, o sinal ficava mais forte. Rina pousou com cuidado e caminhou lá fora com seu traje pesado. Ela encontrou um satélite antigo, quebrado e coberto de poeira, ainda enviando seu sinal fraco para o espaço depois de décadas de silêncio.", "Dentro da memória do satélite, ela descobriu mensagens gravadas de uma colônia humana que havia vivido no planeta muitos anos antes. A colônia havia ficado sem recursos e teve que partir, mas deixaram o satélite para trás para que alguém, algum dia, pudesse encontrar a história deles.", "Rina ficou sentada em silêncio por um momento, pensando nas pessoas que um dia chamaram aquele planeta frio de lar. Ela gravou uma nova mensagem para quem viesse depois dela, e então voltou para sua nave, carregando um pedaço de história que conectava o passado ao futuro."], "hard_words": ["signal", "satellite", "decades", "colony"], "vocab": [{"word": "research ship", "meaning": "nave de pesquisa", "note": ""}, {"word": "source", "meaning": "origem, fonte", "note": ""}, {"word": "approached", "meaning": "aproximou-se", "note": ""}, {"word": "covered in dust", "meaning": "coberto de poeira", "note": ""}, {"word": "run out of", "meaning": "ficar sem (algo)", "note": ""}, {"word": "leave behind", "meaning": "deixar para trás", "note": ""}, {"word": "call home", "meaning": "chamar de lar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["flew", "knew", "grew", "landed", "walked", "found", "discovered", "had", "left", "sat", "recorded", "returned"], "phrasal": ["run out of"], "wh": ["who"], "connectors": ["but", "so that", "then"], "comparative": ["louder", "the past to the future"]}, "word_meanings": [{"word": "signal", "meaning": "sinal", "note": ""}, {"word": "satellite", "meaning": "satélite", "note": ""}, {"word": "decades", "meaning": "décadas", "note": ""}, {"word": "colony", "meaning": "colônia", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "flew", "meaning": "pilotou/voou", "note": "passado de fly"}, {"word": "knew", "meaning": "sabia", "note": "passado de know"}, {"word": "grew", "meaning": "cresceu/ficou", "note": "passado de grow"}, {"word": "landed", "meaning": "pousou", "note": ""}, {"word": "walked", "meaning": "caminhou", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "discovered", "meaning": "descobriu", "note": ""}, {"word": "had", "meaning": "tinha", "note": ""}, {"word": "left", "meaning": "partiu/deixou", "note": ""}, {"word": "sat", "meaning": "sentou-se", "note": ""}, {"word": "recorded", "meaning": "gravou", "note": ""}, {"word": "returned", "meaning": "voltou", "note": ""}, {"word": "run out of", "meaning": "ficar sem", "note": "phrasal verb"}, {"word": "leave behind", "meaning": "deixar para trás", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Past perfect for background events", "explanation_pt": "Usamos past perfect para eventos anteriores a outros no passado: 'scientists had been receiving' e 'a colony that had lived on the planet' mostram ações anteriores à chegada de Rina."}, {"point": "So that + purpose", "explanation_pt": "'So that' explica um propósito: 'they left the satellite behind so that someone might find their story'."}], "multiple_choice": [{"question": "What was Rina's mission?", "options": ["To find the source of a radio signal", "To build a new colony", "To repair her ship", "To meet aliens"], "correct_index": 0, "explanation": "Sua missão era encontrar a origem do sinal."}, {"question": "What did Rina find on the planet?", "options": ["A living alien", "An old satellite", "A new colony", "Nothing at all"], "correct_index": 1, "explanation": "Ela encontrou um satélite antigo e quebrado."}, {"question": "Why did the colony leave the planet?", "options": ["They were attacked", "They found a better planet", "They ran out of resources", "They wanted to return to Earth"], "correct_index": 2, "explanation": "A colônia ficou sem recursos."}, {"question": "Why did the colony leave the satellite behind?", "options": ["It was too heavy to carry", "So someone might find their story", "They forgot about it", "It stopped working"], "correct_index": 1, "explanation": "Para que alguém pudesse encontrar a história deles."}, {"question": "What did Rina do before returning to her ship?", "options": ["She repaired the satellite", "She destroyed the satellite", "She recorded a new message", "She called Earth"], "correct_index": 2, "explanation": "Ela gravou uma nova mensagem."}], "open_questions": [{"question": "Why do you think the colony wanted to leave a message for the future?", "key_points_pt": ["Discutir o desejo humano de deixar um legado", "Comentar sobre a importância da memória e história"]}, {"question": "If you found an old message from the past, what would you want it to say?", "key_points_pt": ["Imaginar o conteúdo de uma mensagem pessoal ou histórica", "Justificar a escolha"]}]}}, {"level": "B1", "genre": "fantasy", "title": "The Silver Forest", "paragraphs": ["In the kingdom of Ardyn, there was a forest where the trees glowed silver at night. Villagers believed the forest was cursed, so no one dared to enter it after sunset. A young girl named Wren, however, had always been curious rather than afraid.", "One night, her little brother wandered into the forest chasing a rabbit and didn't come back. Wren grabbed a torch and ran after him, ignoring the warnings of the villagers. Inside, the trees whispered softly, and strange lights floated between the branches like tiny stars.", "She found her brother sitting calmly beside an old spirit made of silver light, who explained that the forest protected lost children rather than harming them. The spirit had simply been waiting for someone brave enough to learn the truth and break the old, false legend.", "Wren carried her brother home and told the villagers what she had discovered. Although some people still doubted her story, others slowly began to walk through the forest during the day. Over time, the silver forest became a peaceful place instead of a frightening one."], "paragraphs_pt": ["No reino de Ardyn, havia uma floresta onde as árvores brilhavam prateadas à noite. Os moradores acreditavam que a floresta era amaldiçoada, então ninguém ousava entrar nela depois do pôr do sol. Uma jovem chamada Wren, no entanto, sempre foi curiosa em vez de medrosa.", "Numa noite, seu irmãozinho vagou pela floresta perseguindo um coelho e não voltou. Wren pegou uma tocha e correu atrás dele, ignorando os avisos dos moradores. Lá dentro, as árvores sussurravam suavemente, e luzes estranhas flutuavam entre os galhos como pequenas estrelas.", "Ela encontrou o irmão sentado calmamente ao lado de um velho espírito feito de luz prateada, que explicou que a floresta protegia crianças perdidas em vez de machucá-las. O espírito estivera simplesmente esperando por alguém corajoso o bastante para descobrir a verdade e quebrar a antiga e falsa lenda.", "Wren carregou o irmão para casa e contou aos moradores o que havia descoberto. Embora algumas pessoas ainda duvidassem de sua história, outras aos poucos começaram a caminhar pela floresta durante o dia. Com o tempo, a floresta prateada se tornou um lugar tranquilo em vez de assustador."], "hard_words": ["cursed", "dared", "wandered", "whispered"], "vocab": [{"word": "kingdom", "meaning": "reino", "note": ""}, {"word": "glowed", "meaning": "brilhava", "note": ""}, {"word": "villagers", "meaning": "moradores da vila", "note": ""}, {"word": "torch", "meaning": "tocha", "note": ""}, {"word": "branches", "meaning": "galhos", "note": ""}, {"word": "spirit", "meaning": "espírito", "note": ""}, {"word": "legend", "meaning": "lenda", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["was", "believed", "wandered", "grabbed", "ran", "found", "explained", "carried", "told", "began", "became"], "phrasal": ["ran after"], "wh": ["who"], "connectors": ["so", "however", "Although", "instead of"], "comparative": []}, "word_meanings": [{"word": "cursed", "meaning": "amaldiçoado(a)", "note": ""}, {"word": "dared", "meaning": "ousava", "note": ""}, {"word": "wandered", "meaning": "vagou", "note": ""}, {"word": "whispered", "meaning": "sussurravam", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "believed", "meaning": "acreditavam", "note": ""}, {"word": "grabbed", "meaning": "pegou", "note": ""}, {"word": "ran", "meaning": "correu", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "carried", "meaning": "carregou", "note": ""}, {"word": "told", "meaning": "contou", "note": ""}, {"word": "began", "meaning": "começaram", "note": ""}, {"word": "became", "meaning": "tornou-se", "note": ""}, {"word": "ran after", "meaning": "correu atrás de", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Rather than", "explanation_pt": "'Rather than' compara duas opções, preferindo uma: 'curious rather than afraid' (curiosa em vez de medrosa)."}, {"point": "Past perfect continuous", "explanation_pt": "'had simply been waiting' mostra uma ação contínua que aconteceu antes de outro momento no passado."}], "multiple_choice": [{"question": "Why didn't villagers enter the forest at night?", "options": ["They believed it was cursed", "It was too dark", "There were wild animals", "It was against the law"], "correct_index": 0, "explanation": "Eles acreditavam que a floresta era amaldiçoada."}, {"question": "Why did Wren's brother go into the forest?", "options": ["He was lost", "He was chasing a rabbit", "He wanted to see the lights", "He was running from someone"], "correct_index": 1, "explanation": "Ele perseguia um coelho."}, {"question": "Who did Wren find with her brother?", "options": ["Another villager", "A wolf", "A silver spirit", "No one"], "correct_index": 2, "explanation": "Ela encontrou um espírito feito de luz prateada."}, {"question": "What did the spirit actually do to lost children?", "options": ["It scared them away", "It protected them", "It ignored them", "It turned them to silver"], "correct_index": 1, "explanation": "O espírito protegia as crianças perdidas."}, {"question": "What happened to the forest's reputation by the end?", "options": ["It became more dangerous", "It stayed frightening", "It became peaceful for the villagers", "It disappeared"], "correct_index": 2, "explanation": "Com o tempo, tornou-se um lugar tranquilo."}], "open_questions": [{"question": "Why do you think people often fear things they don't understand?", "key_points_pt": ["Falar sobre medo do desconhecido", "Relacionar com a lenda da floresta"]}, {"question": "What lesson can we learn from Wren's story?", "key_points_pt": ["Comentar sobre coragem e curiosidade", "Falar sobre questionar crenças antigas"]}]}}, {"level": "B1", "genre": "adventure", "title": "The River Crossing", "paragraphs": ["Tomas and his two friends decided to hike through the mountains to reach a hidden waterfall that locals had talked about for years. The trail was long and difficult, but they carried enough food and water for three days.", "On the second day, they reached a wide river with strong currents. The old wooden bridge that used to cross it had collapsed years earlier, so they had to find another way across. Tomas suggested that they build a small raft using fallen branches and rope.", "It took them several hours, but they finally built a raft strong enough to hold their bags. Although the current pushed them further downstream than they expected, they made it safely to the other side, soaked but excited.", "When they finally reached the waterfall the next morning, they understood why people talked about it so much. The water fell from an incredible height into a clear pool below. Tired but proud, they agreed it was the best trip they had ever taken together."], "paragraphs_pt": ["Tomas e seus dois amigos decidiram fazer uma trilha pelas montanhas para chegar a uma cachoeira escondida sobre a qual os moradores locais falavam havia anos. A trilha era longa e difícil, mas eles carregavam comida e água suficientes para três dias.", "No segundo dia, chegaram a um rio largo com correntes fortes. A velha ponte de madeira que costumava cruzá-lo havia desabado anos antes, então tiveram que encontrar outra forma de atravessar. Tomas sugeriu que construíssem uma pequena jangada usando galhos caídos e corda.", "Levou várias horas, mas finalmente construíram uma jangada forte o bastante para carregar suas mochilas. Embora a correnteza os tenha empurrado mais rio abaixo do que esperavam, eles chegaram em segurança ao outro lado, encharcados mas animados.", "Quando finalmente chegaram à cachoeira na manhã seguinte, entenderam por que as pessoas falavam tanto sobre ela. A água caía de uma altura incrível em uma piscina clara abaixo. Cansados mas orgulhosos, concordaram que era a melhor viagem que já haviam feito juntos."], "hard_words": ["currents", "collapsed", "raft", "downstream"], "vocab": [{"word": "hike", "meaning": "caminhada, trilha", "note": ""}, {"word": "waterfall", "meaning": "cachoeira", "note": ""}, {"word": "trail", "meaning": "trilha", "note": ""}, {"word": "rope", "meaning": "corda", "note": ""}, {"word": "soaked", "meaning": "encharcado(a)", "note": ""}, {"word": "pool", "meaning": "piscina natural, poça", "note": ""}, {"word": "proud", "meaning": "orgulhoso(a)", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["decided", "carried", "reached", "collapsed", "had", "suggested", "took", "built", "pushed", "made", "understood", "fell", "agreed"], "phrasal": [], "wh": ["why"], "connectors": ["but", "so", "Although"], "comparative": ["further downstream", "the best trip"]}, "word_meanings": [{"word": "currents", "meaning": "correntezas", "note": ""}, {"word": "collapsed", "meaning": "desabou", "note": ""}, {"word": "raft", "meaning": "jangada", "note": ""}, {"word": "downstream", "meaning": "rio abaixo", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "decided", "meaning": "decidiram", "note": ""}, {"word": "carried", "meaning": "carregavam", "note": ""}, {"word": "reached", "meaning": "chegaram", "note": ""}, {"word": "had", "meaning": "tiveram/tinham", "note": ""}, {"word": "suggested", "meaning": "sugeriu", "note": ""}, {"word": "took", "meaning": "levou", "note": ""}, {"word": "built", "meaning": "construíram", "note": "passado de build"}, {"word": "pushed", "meaning": "empurrou", "note": ""}, {"word": "made", "meaning": "fizeram/conseguiram", "note": "passado de make"}, {"word": "understood", "meaning": "entenderam", "note": "passado de understand"}, {"word": "fell", "meaning": "caía", "note": "passado de fall"}, {"word": "agreed", "meaning": "concordaram", "note": ""}], "exercises": {"grammar": [{"point": "Used to", "explanation_pt": "'Used to' descreve um hábito ou estado do passado que não existe mais: 'The old wooden bridge that used to cross it had collapsed' (A ponte que costumava cruzá-lo havia desabado)."}, {"point": "Enough + adjetivo/substantivo", "explanation_pt": "'Strong enough to hold their bags' significa 'forte o suficiente para carregar as mochilas'."}], "multiple_choice": [{"question": "What was the group's destination?", "options": ["A hidden waterfall", "A cave", "A mountain peak", "A lake"], "correct_index": 0, "explanation": "Eles queriam chegar a uma cachoeira escondida."}, {"question": "What had happened to the old bridge?", "options": ["It was never built", "It had collapsed", "It was too small", "It was blocked"], "correct_index": 1, "explanation": "A ponte havia desabado anos antes."}, {"question": "What did Tomas suggest they build?", "options": ["A boat", "A new bridge", "A raft", "A tent"], "correct_index": 2, "explanation": "Ele sugeriu construir uma jangada."}, {"question": "How did they feel after crossing the river?", "options": ["Angry and tired", "Soaked but excited", "Bored", "Scared and confused"], "correct_index": 1, "explanation": "Ficaram encharcados mas animados."}, {"question": "How did the group describe the trip at the end?", "options": ["Not worth it", "Disappointing", "The best trip they had ever taken", "Too dangerous"], "correct_index": 2, "explanation": "Concordaram que foi a melhor viagem que já haviam feito."}], "open_questions": [{"question": "What would you do if you faced an obstacle like the broken bridge during a trip?", "key_points_pt": ["Propor soluções criativas", "Falar sobre trabalho em equipe"]}, {"question": "Do you enjoy adventurous trips, or do you prefer relaxing vacations? Why?", "key_points_pt": ["Expressar preferência pessoal", "Justificar com exemplos"]}]}}, {"level": "B1", "genre": "travel", "title": "A Wrong Turn in Lisbon", "paragraphs": ["Beatriz visited Lisbon for the first time last summer, and she decided to explore the old neighborhoods without using her phone's map. She wanted to feel like a real local, walking through narrow streets and discovering things by chance.", "After an hour, however, she realized she had taken a wrong turn and had no idea where her hotel was. Instead of panicking, she sat down at a small square and asked an elderly man for directions. He didn't speak much English, but he kindly drew a map on a napkin.", "Following his drawing, Beatriz walked past colorful buildings, a small church, and a viewpoint with an amazing view of the river. She stopped there for twenty minutes, just enjoying the wind and the orange rooftops below her.", "By the time she finally found her hotel, she had walked much farther than planned, and her feet hurt badly. Still, she said it was one of the best afternoons of her trip because getting lost had shown her parts of the city she never would have found otherwise."], "paragraphs_pt": ["Beatriz visitou Lisboa pela primeira vez no verão passado, e decidiu explorar os bairros antigos sem usar o mapa do celular. Ela queria se sentir como uma moradora local, caminhando por ruas estreitas e descobrindo coisas por acaso.", "Depois de uma hora, porém, ela percebeu que havia pegado o caminho errado e não fazia ideia de onde ficava o hotel. Em vez de entrar em pânico, ela se sentou em uma pequena praça e pediu informações a um senhor idoso. Ele não falava muito inglês, mas gentilmente desenhou um mapa em um guardanapo.", "Seguindo o desenho dele, Beatriz passou por prédios coloridos, uma pequena igreja e um mirante com uma vista incrível do rio. Ela parou ali por vinte minutos, apenas aproveitando o vento e os telhados alaranjados abaixo dela.", "Quando finalmente encontrou o hotel, ela havia caminhado muito mais do que planejado, e os pés doíam muito. Ainda assim, ela disse que foi uma das melhores tardes da viagem, porque se perder havia mostrado partes da cidade que ela nunca teria encontrado de outra forma."], "hard_words": ["neighborhoods", "napkin", "viewpoint", "rooftops"], "vocab": [{"word": "by chance", "meaning": "por acaso", "note": ""}, {"word": "took a wrong turn", "meaning": "pegou o caminho errado", "note": ""}, {"word": "panicking", "meaning": "entrando em pânico", "note": ""}, {"word": "asked for directions", "meaning": "pediu informações (de rota)", "note": ""}, {"word": "farther", "meaning": "mais longe", "note": ""}, {"word": "got lost", "meaning": "se perdeu", "note": ""}, {"word": "otherwise", "meaning": "de outra forma", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["visited", "decided", "wanted", "had", "sat", "drew", "walked", "stopped", "found", "hurt", "said", "shown"], "phrasal": [], "wh": ["where"], "connectors": ["however", "Instead of", "but", "because", "Still"], "comparative": ["farther", "the best afternoons"]}, "word_meanings": [{"word": "neighborhoods", "meaning": "bairros", "note": ""}, {"word": "napkin", "meaning": "guardanapo", "note": ""}, {"word": "viewpoint", "meaning": "mirante", "note": ""}, {"word": "rooftops", "meaning": "telhados", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "visited", "meaning": "visitou", "note": ""}, {"word": "decided", "meaning": "decidiu", "note": ""}, {"word": "wanted", "meaning": "queria", "note": ""}, {"word": "took", "meaning": "pegou", "note": ""}, {"word": "had", "meaning": "tinha", "note": ""}, {"word": "sat", "meaning": "sentou-se", "note": ""}, {"word": "drew", "meaning": "desenhou", "note": "passado de draw"}, {"word": "walked", "meaning": "caminhou", "note": ""}, {"word": "stopped", "meaning": "parou", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "hurt", "meaning": "doíam", "note": "passado de hurt (mesma forma)"}, {"word": "said", "meaning": "disse", "note": ""}, {"word": "shown", "meaning": "mostrado", "note": "particípio de show"}], "exercises": {"grammar": [{"point": "Conditional (would have)", "explanation_pt": "'She never would have found otherwise' expressa um resultado imaginário no passado: se não tivesse se perdido, nunca teria encontrado esses lugares."}, {"point": "Instead of + gerúndio", "explanation_pt": "'Instead of panicking, she sat down' mostra uma ação alternativa: em vez de entrar em pânico."}], "multiple_choice": [{"question": "Why didn't Beatriz use her phone's map?", "options": ["It was broken", "She wanted to feel like a local", "She had no signal", "She forgot her phone"], "correct_index": 1, "explanation": "Ela queria se sentir como uma moradora local."}, {"question": "Who helped Beatriz with directions?", "options": ["A police officer", "An elderly man", "A tour guide", "A hotel worker"], "correct_index": 1, "explanation": "Um senhor idoso desenhou um mapa para ela."}, {"question": "What did the man draw the map on?", "options": ["A piece of paper", "His hand", "A napkin", "A postcard"], "correct_index": 2, "explanation": "Ele desenhou o mapa em um guardanapo."}, {"question": "What did Beatriz see from the viewpoint?", "options": ["The airport", "A view of the river", "A museum", "The train station"], "correct_index": 1, "explanation": "Ela viu uma vista incrível do rio."}, {"question": "How did Beatriz feel about getting lost by the end of the day?", "options": ["Angry", "Regretful", "Positive about the experience", "Indifferent"], "correct_index": 2, "explanation": "Ela achou que foi uma das melhores tardes da viagem."}], "open_questions": [{"question": "Do you prefer traveling with a map/app or exploring without one? Why?", "key_points_pt": ["Expressar preferência pessoal sobre planejamento de viagens", "Justificar com vantagens e desvantagens"]}, {"question": "Tell about a time you got lost somewhere. What happened?", "key_points_pt": ["Descrever a situação pessoal", "Explicar como se resolveu"]}]}}, {"level": "B1", "genre": "corporate", "title": "The Failed Product Launch", "paragraphs": ["Claudia had worked for six months on a new app for her company, and the launch day finally arrived. She and her team gathered in the meeting room, nervous but excited, waiting for the download numbers to appear on the screen.", "Unfortunately, the numbers were much lower than expected. Worse, users began posting complaints because the app crashed every time someone tried to upload a photo. Claudia's manager called an emergency meeting and asked her to explain what had gone wrong.", "Instead of making excuses, Claudia admitted the mistake honestly. She explained that the testing team hadn't had enough time before the deadline, and she suggested a plan to fix the bug within 48 hours. Her manager appreciated her honesty and agreed to give the team more time.", "The team worked through the weekend and released an update that solved the problem. Although the launch hadn't gone as planned, Claudia learned that admitting a mistake quickly and offering a solution was far more valuable than pretending everything was fine."], "paragraphs_pt": ["Claudia havia trabalhado seis meses em um novo aplicativo para sua empresa, e o dia do lançamento finalmente chegou. Ela e sua equipe se reuniram na sala de reuniões, nervosos mas animados, esperando os números de downloads aparecerem na tela.", "Infelizmente, os números foram muito menores do que o esperado. Pior, os usuários começaram a postar reclamações porque o aplicativo travava toda vez que alguém tentava enviar uma foto. O gerente de Claudia convocou uma reunião de emergência e pediu que ela explicasse o que havia dado errado.", "Em vez de arranjar desculpas, Claudia admitiu o erro honestamente. Ela explicou que a equipe de testes não havia tido tempo suficiente antes do prazo, e sugeriu um plano para corrigir o problema em 48 horas. Seu gerente valorizou sua honestidade e concordou em dar mais tempo à equipe.", "A equipe trabalhou durante o fim de semana e lançou uma atualização que resolveu o problema. Embora o lançamento não tivesse saído como planejado, Claudia aprendeu que admitir um erro rapidamente e oferecer uma solução era muito mais valioso do que fingir que tudo estava bem."], "hard_words": ["launch", "crashed", "deadline", "pretending"], "vocab": [{"word": "gathered", "meaning": "reuniram-se", "note": ""}, {"word": "complaints", "meaning": "reclamações", "note": ""}, {"word": "upload", "meaning": "enviar, fazer upload", "note": ""}, {"word": "emergency meeting", "meaning": "reunião de emergência", "note": ""}, {"word": "make excuses", "meaning": "arranjar desculpas", "note": ""}, {"word": "bug", "meaning": "erro (de software)", "note": ""}, {"word": "honesty", "meaning": "honestidade", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["worked", "arrived", "gathered", "began", "called", "asked", "admitted", "explained", "suggested", "agreed", "released", "solved", "learned"], "phrasal": [], "wh": ["what"], "connectors": ["but", "Unfortunately", "Instead of", "Although", "because"], "comparative": ["lower", "Worse", "more valuable", "far more valuable"]}, "word_meanings": [{"word": "launch", "meaning": "lançamento", "note": ""}, {"word": "crashed", "meaning": "travava/falhava", "note": ""}, {"word": "deadline", "meaning": "prazo final", "note": ""}, {"word": "pretending", "meaning": "fingindo", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "attend", "meaning": "comparecer, participar", "note": "falso cognato: não é 'atender'"}, {"word": "eventually", "meaning": "finalmente, no final", "note": "falso cognato: não é 'eventualmente'"}, {"word": "push", "meaning": "empurrar", "note": "falso cognato: não é 'puxar'"}, {"word": "parents", "meaning": "pais (mãe e pai)", "note": "falso cognato: não é 'parentes'"}, {"word": "worked", "meaning": "trabalhou", "note": ""}, {"word": "arrived", "meaning": "chegou", "note": ""}, {"word": "gathered", "meaning": "reuniram-se", "note": ""}, {"word": "began", "meaning": "começaram", "note": ""}, {"word": "called", "meaning": "convocou", "note": ""}, {"word": "asked", "meaning": "pediu", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "suggested", "meaning": "sugeriu", "note": ""}, {"word": "agreed", "meaning": "concordou", "note": ""}, {"word": "released", "meaning": "lançou", "note": ""}, {"word": "solved", "meaning": "resolveu", "note": ""}, {"word": "learned", "meaning": "aprendeu", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect for explanations", "explanation_pt": "'the testing team hadn't had enough time' usa past perfect para explicar a causa de um problema anterior ao lançamento."}, {"point": "Comparatives of value", "explanation_pt": "'far more valuable than pretending' compara duas atitudes, mostrando qual é melhor."}], "multiple_choice": [{"question": "How long had Claudia worked on the app?", "options": ["Two weeks", "Six months", "One year", "Three days"], "correct_index": 1, "explanation": "Ela trabalhou seis meses no aplicativo."}, {"question": "Why did users complain about the app?", "options": ["It was too expensive", "It crashed when uploading photos", "It had no features", "It was too slow to download"], "correct_index": 1, "explanation": "O aplicativo travava ao enviar fotos."}, {"question": "What did Claudia do when her manager asked what went wrong?", "options": ["She blamed her team", "She admitted the mistake honestly", "She said nothing", "She quit her job"], "correct_index": 1, "explanation": "Ela admitiu o erro honestamente."}, {"question": "How long did Claudia say the team needed to fix the bug?", "options": ["24 hours", "48 hours", "One week", "One month"], "correct_index": 1, "explanation": "Ela sugeriu um prazo de 48 horas."}, {"question": "What did Claudia learn from this experience?", "options": ["To hide mistakes", "To blame others", "That honesty and solutions matter more than excuses", "To quit when things go wrong"], "correct_index": 2, "explanation": "Ela aprendeu que admitir o erro e oferecer solução é mais valioso."}], "open_questions": [{"question": "Do you think it is always better to admit mistakes at work? Why or why not?", "key_points_pt": ["Discutir os riscos e benefícios de admitir erros", "Relacionar com confiança e reputação profissional"]}, {"question": "How would you have reacted if you were Claudia's manager?", "key_points_pt": ["Imaginar-se no papel de gestor", "Explicar como lidaria com a situação"]}]}}, {"level": "B1", "genre": "dialogue", "title": "Choosing a Restaurant", "paragraphs": ["\"Where do you want to eat tonight?\" asked Bruno, scrolling through his phone. \"I really don't mind,\" replied Carla, \"but I don't want anything too heavy. We ate a huge lunch, remember?\" Bruno laughed and said, \"Right, I forgot about that enormous pizza.\"", "\"What about that new Thai place downtown?\" Carla suggested. \"I've heard the food is amazing, and it's not too far from here.\" Bruno hesitated. \"Honestly, spicy food isn't really my thing. Could we find something a little milder?\" \"Sure,\" Carla answered, \"how about the Italian restaurant instead? They have pasta that isn't spicy at all.\"", "\"That sounds better,\" Bruno agreed, \"although we go there quite often. Let's try something we've never had before.\" After a few more minutes of searching, they finally found a small Japanese restaurant with great reviews. \"This looks perfect,\" Carla said. \"Should I make a reservation?\"", "\"Yes, please,\" Bruno answered, smiling. \"And this time, let's actually stick to appetizers so we're not too full afterward.\" Carla laughed. \"You always say that, and we always order dessert anyway.\" They both laughed, grabbed their coats, and headed out the door."], "paragraphs_pt": ["\"Onde você quer comer hoje à noite?\", perguntou Bruno, rolando a tela do celular. \"Eu realmente não me importo\", respondeu Carla, \"mas não quero nada muito pesado. Comemos um almoço enorme, lembra?\" Bruno riu e disse: \"É verdade, esqueci daquela pizza enorme.\"", "\"Que tal aquele novo lugar tailandês no centro?\", sugeriu Carla. \"Ouvi dizer que a comida é incrível, e não é muito longe daqui.\" Bruno hesitou. \"Sinceramente, comida apimentada não é muito a minha praia. Poderíamos encontrar algo um pouco mais suave?\" \"Claro\", respondeu Carla, \"que tal o restaurante italiano então? Eles têm massas que não são nada apimentadas.\"", "\"Isso parece melhor\", Bruno concordou, \"embora a gente vá lá com bastante frequência. Vamos tentar algo que nunca comemos antes.\" Depois de mais alguns minutos procurando, finalmente encontraram um pequeno restaurante japonês com ótimas avaliações. \"Esse parece perfeito\", disse Carla. \"Eu faço a reserva?\"", "\"Sim, por favor\", respondeu Bruno, sorrindo. \"E dessa vez, vamos realmente nos limitar às entradas para não ficarmos muito cheios depois.\" Carla riu. \"Você sempre fala isso, e a gente sempre pede sobremesa mesmo assim.\" Os dois riram, pegaram os casacos e saíram pela porta."], "hard_words": ["scrolling", "hesitated", "appetizers", "reservation"], "vocab": [{"word": "I don't mind", "meaning": "não me importo", "note": ""}, {"word": "heavy (food)", "meaning": "pesado(a)", "note": ""}, {"word": "downtown", "meaning": "no centro (da cidade)", "note": ""}, {"word": "milder", "meaning": "mais suave", "note": ""}, {"word": "stick to", "meaning": "se limitar a", "note": ""}, {"word": "reservation", "meaning": "reserva", "note": ""}, {"word": "headed out", "meaning": "saíram", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["isn't"], "irregular": ["asked", "replied", "said", "laughed", "forgot", "suggested", "heard", "answered", "agreed", "found", "grabbed"], "phrasal": ["stick to"], "wh": ["Where", "What", "how"], "connectors": ["but", "although", "so", "and"], "comparative": ["milder", "better"]}, "word_meanings": [{"word": "scrolling", "meaning": "rolando a tela", "note": ""}, {"word": "hesitated", "meaning": "hesitou", "note": ""}, {"word": "appetizers", "meaning": "entradas, aperitivos", "note": ""}, {"word": "reservation", "meaning": "reserva", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "asked", "meaning": "perguntou", "note": ""}, {"word": "replied", "meaning": "respondeu", "note": ""}, {"word": "said", "meaning": "disse", "note": ""}, {"word": "laughed", "meaning": "riu", "note": ""}, {"word": "forgot", "meaning": "esqueceu", "note": "passado de forget"}, {"word": "suggested", "meaning": "sugeriu", "note": ""}, {"word": "heard", "meaning": "ouviu", "note": ""}, {"word": "answered", "meaning": "respondeu", "note": ""}, {"word": "agreed", "meaning": "concordou", "note": ""}, {"word": "found", "meaning": "encontraram", "note": ""}, {"word": "grabbed", "meaning": "pegaram", "note": ""}, {"word": "stick to", "meaning": "se limitar a", "note": "phrasal verb"}, {"word": "head out", "meaning": "sair", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Reported vs direct speech in dialogue", "explanation_pt": "Em diálogos usamos aspas para o discurso direto: '\"Where do you want to eat tonight?\" asked Bruno.' Verbos como 'asked', 'replied', 'suggested' introduzem a fala."}, {"point": "Present perfect with ever/never", "explanation_pt": "'something we've never had before' usa present perfect para experiências até agora, sem tempo específico."}], "multiple_choice": [{"question": "Why didn't Carla want anything too heavy?", "options": ["She was on a diet", "They had eaten a huge lunch", "She didn't like the restaurant", "She wasn't hungry"], "correct_index": 1, "explanation": "Eles tinham comido um almoço enorme."}, {"question": "Why didn't Bruno want to go to the Thai restaurant?", "options": ["It was too expensive", "He doesn't like spicy food", "It was closed", "It was too far"], "correct_index": 1, "explanation": "Comida apimentada não é a praia dele."}, {"question": "Why did they decide not to go to the Italian restaurant?", "options": ["It was closed", "They go there often", "It was too spicy", "It was too expensive"], "correct_index": 1, "explanation": "Eles já vão lá com frequência e queriam algo novo."}, {"question": "What type of restaurant did they finally choose?", "options": ["Thai", "Italian", "Japanese", "Mexican"], "correct_index": 2, "explanation": "Eles escolheram um restaurante japonês."}, {"question": "What does Carla say they always do despite Bruno's plan?", "options": ["Arrive late", "Order dessert anyway", "Forget the reservation", "Argue about the menu"], "correct_index": 1, "explanation": "Eles sempre acabam pedindo sobremesa mesmo assim."}], "open_questions": [{"question": "How do you usually decide where to eat with friends or family?", "key_points_pt": ["Descrever o processo de decisão em grupo", "Comentar sobre preferências alimentares"]}, {"question": "Do you prefer trying new restaurants or going to familiar ones? Why?", "key_points_pt": ["Expressar preferência pessoal", "Justificar com exemplos"]}]}}, {"level": "B1", "genre": "horror", "title": "The Attic Door", "paragraphs": ["When Julia and her husband bought the old farmhouse, the real estate agent mentioned that the attic door should stay locked because the wood was weak and unsafe. For the first few weeks, they simply forgot about it and focused on unpacking.", "One night, Julia woke up because she heard slow, heavy footsteps directly above the bedroom ceiling. She told herself it was probably just an animal that had gotten into the attic through a crack in the roof, although the sound seemed far too heavy for that.", "The footsteps continued every night for a week, always starting around the same time. Finally, unable to sleep, Julia decided to check the attic herself. When she reached the top of the stairs, she found the locked door standing wide open, even though the key was still in her husband's drawer downstairs.", "She never found out what had opened the door, and no animal was ever found inside. Julia and her husband eventually sold the house to another family, and they never mentioned the attic door again, though neither of them ever forgot the sound of those heavy footsteps."], "paragraphs_pt": ["Quando Julia e o marido compraram a antiga fazenda, o corretor de imóveis mencionou que a porta do sótão deveria ficar trancada porque a madeira estava fraca e insegura. Nas primeiras semanas, eles simplesmente se esqueceram disso e se concentraram em desfazer as malas.", "Numa noite, Julia acordou porque ouviu passos lentos e pesados bem acima do teto do quarto. Ela disse a si mesma que provavelmente era apenas um animal que havia entrado no sótão por uma fresta no telhado, embora o som parecesse pesado demais para isso.", "Os passos continuaram todas as noites durante uma semana, sempre começando por volta do mesmo horário. Finalmente, incapaz de dormir, Julia decidiu verificar o sótão sozinha. Quando chegou ao topo da escada, encontrou a porta trancada bem aberta, mesmo com a chave ainda na gaveta do marido, lá embaixo.", "Ela nunca descobriu o que havia aberto a porta, e nenhum animal foi encontrado lá dentro. Julia e o marido acabaram vendendo a casa para outra família, e nunca mais mencionaram a porta do sótão, embora nenhum dos dois jamais tenha esquecido o som daqueles passos pesados."], "hard_words": ["attic", "footsteps", "ceiling", "crack"], "vocab": [{"word": "farmhouse", "meaning": "casa de fazenda", "note": ""}, {"word": "real estate agent", "meaning": "corretor de imóveis", "note": ""}, {"word": "unpacking", "meaning": "desfazendo as malas", "note": ""}, {"word": "woke up", "meaning": "acordou", "note": ""}, {"word": "unable to", "meaning": "incapaz de", "note": ""}, {"word": "drawer", "meaning": "gaveta", "note": ""}, {"word": "found out", "meaning": "descobriu", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["bought", "mentioned", "forgot", "woke", "heard", "told", "gotten", "continued", "decided", "reached", "found", "sold"], "phrasal": [], "wh": ["what"], "connectors": ["because", "although", "though"], "comparative": ["too heavy"]}, "word_meanings": [{"word": "attic", "meaning": "sótão", "note": ""}, {"word": "footsteps", "meaning": "passos", "note": ""}, {"word": "ceiling", "meaning": "teto", "note": ""}, {"word": "crack", "meaning": "fresta, fenda", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato"}, {"word": "bought", "meaning": "compraram", "note": "passado de buy"}, {"word": "mentioned", "meaning": "mencionou", "note": ""}, {"word": "forgot", "meaning": "esqueceram", "note": ""}, {"word": "woke", "meaning": "acordou", "note": "passado de wake"}, {"word": "heard", "meaning": "ouviu", "note": ""}, {"word": "told", "meaning": "disse", "note": ""}, {"word": "gotten", "meaning": "entrado (particípio de get)", "note": ""}, {"word": "continued", "meaning": "continuaram", "note": ""}, {"word": "decided", "meaning": "decidiu", "note": ""}, {"word": "reached", "meaning": "chegou", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "sold", "meaning": "venderam", "note": "passado de sell"}, {"word": "find out", "meaning": "descobrir", "note": "phrasal verb"}, {"word": "get into", "meaning": "entrar em", "note": "phrasal verb"}], "exercises": {"grammar": [{"point": "Past perfect for unexplained events", "explanation_pt": "'what had opened the door' usa past perfect para um evento misterioso anterior à descoberta, o que aumenta a tensão da história."}, {"point": "Even though / Though", "explanation_pt": "'even though the key was still in her husband's drawer' mostra um contraste surpreendente: apesar de a chave estar guardada, a porta estava aberta."}], "multiple_choice": [{"question": "What did the real estate agent say about the attic door?", "options": ["It should stay open", "It should stay locked", "It led to another house", "It was already broken"], "correct_index": 1, "explanation": "Ele disse que a porta deveria ficar trancada."}, {"question": "What woke Julia up one night?", "options": ["A phone call", "Heavy footsteps above the ceiling", "A storm", "Her husband snoring"], "correct_index": 1, "explanation": "Ela ouviu passos pesados acima do teto."}, {"question": "What did Julia find when she reached the attic?", "options": ["An animal", "The door wide open", "Nothing unusual", "Her husband"], "correct_index": 1, "explanation": "Ela encontrou a porta trancada bem aberta."}, {"question": "Where was the key while the door was open?", "options": ["In the lock", "Lost", "In her husband's drawer downstairs", "In Julia's pocket"], "correct_index": 2, "explanation": "A chave estava na gaveta do marido, lá embaixo."}, {"question": "What happened to Julia and her husband in the end?", "options": ["They stayed in the house forever", "They sold the house", "They found the source of the noise", "They called the police"], "correct_index": 1, "explanation": "Eles acabaram vendendo a casa."}], "open_questions": [{"question": "What do you think opened the attic door?", "key_points_pt": ["Especular livremente sobre a causa", "Não há resposta certa, incentivar a imaginação"]}, {"question": "Would you have gone to check the attic alone like Julia did? Why or why not?", "key_points_pt": ["Refletir sobre coragem versus medo", "Justificar a decisão pessoal"]}]}}, {"level": "B2", "genre": "neutral", "title": "The Last Seat on the Train", "paragraphs": ["Marta had been standing on the platform for almost an hour, and the delay was starting to wear her down. She checked her phone again, hoping for an update, but the app simply said the train was still running late. Around her, other passengers were growing restless, shifting their bags from one shoulder to the other and glancing anxiously at the empty tracks.", "When the train finally pulled in, everyone rushed forward at once, and Marta found herself caught in a wave of elbows and suitcases. She managed to squeeze through the doors just before they closed, only to discover that the carriage was already packed. Every seat seemed to be taken, and she resigned herself to standing for the entire journey.", "Then she noticed an elderly man waving at her from a row near the window. He explained that he had saved the seat next to him for his granddaughter, but she had missed the train because of the same delay. Grateful, Marta sat down and thanked him, and the two of them ended up talking for the rest of the trip, swapping stories about their families and their jobs.", "By the time the train reached the final station, Marta realized she had barely noticed the journey pass. What had started as an incredibly frustrating morning had turned, quite unexpectedly, into one of the most pleasant conversations she had had in months. She said goodbye to the old man, wished him luck finding his granddaughter, and stepped off the train with a small, genuine smile."], "paragraphs_pt": ["Marta estava na plataforma havia quase uma hora, e o atraso começava a esgotá-la. Ela checou o celular de novo, esperando uma atualização, mas o aplicativo apenas dizia que o trem continuava atrasado. Ao seu redor, os outros passageiros ficavam cada vez mais impacientes, trocando as bolsas de ombro e olhando ansiosamente para os trilhos vazios.", "Quando o trem finalmente chegou, todo mundo avançou de uma vez, e Marta se viu presa em uma onda de cotovelos e malas. Ela conseguiu se espremer pelas portas bem antes de fecharem, só para descobrir que o vagão já estava lotado. Todos os assentos pareciam ocupados, e ela se resignou a ficar em pé durante toda a viagem.", "Então ela percebeu um senhor idoso acenando para ela em uma fileira perto da janela. Ele explicou que tinha guardado o lugar ao lado para a neta, mas ela havia perdido o trem por causa do mesmo atraso. Agradecida, Marta se sentou e o agradeceu, e os dois acabaram conversando pelo resto da viagem, trocando histórias sobre suas famílias e seus empregos.", "Quando o trem chegou à estação final, Marta percebeu que mal tinha notado a viagem passar. O que havia começado como uma manhã extremamente frustrante havia se transformado, de forma bem inesperada, em uma das conversas mais agradáveis que ela tivera em meses. Ela se despediu do senhor, desejou sorte para ele encontrar a neta e desceu do trem com um sorriso pequeno e sincero."], "hard_words": ["wear her down", "resigned herself", "squeeze", "restless"], "vocab": [{"word": "platform", "meaning": "plataforma", "note": ""}, {"word": "delay", "meaning": "atraso", "note": ""}, {"word": "restless", "meaning": "inquieto, impaciente", "note": ""}, {"word": "wear (someone) down", "meaning": "desgastar, esgotar aos poucos", "note": "phrasal verb"}, {"word": "squeeze through", "meaning": "espremer-se por", "note": "phrasal verb"}, {"word": "resign oneself to", "meaning": "resignar-se a", "note": ""}, {"word": "grateful", "meaning": "grato", "note": ""}, {"word": "genuine", "meaning": "sincero, autêntico", "note": ""}], "word_meanings": [{"word": "wear her down", "meaning": "esgotá-la aos poucos", "note": ""}, {"word": "resigned herself", "meaning": "se resignou", "note": ""}, {"word": "squeeze", "meaning": "espremer-se", "note": ""}, {"word": "restless", "meaning": "inquieto, impaciente", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "não significa 'atualmente'"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato de 'realizar'"}, {"word": "had been standing", "meaning": "estava em pé (passado perfeito contínuo)", "note": ""}, {"word": "pulled in", "meaning": "chegou, entrou (na estação)", "note": "phrasal verb"}, {"word": "squeeze through", "meaning": "espremer-se por", "note": "phrasal verb"}, {"word": "ended up", "meaning": "acabou, terminou fazendo algo", "note": "phrasal verb"}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "stepped off", "meaning": "desceu", "note": ""}, {"word": "managed", "meaning": "conseguiu", "note": ""}, {"word": "checked", "meaning": "checou", "note": ""}, {"word": "said", "meaning": "disse", "note": ""}, {"word": "discovered", "meaning": "descobriu", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["had been standing", "checked", "said", "pulled in", "found", "managed", "noticed"], "phrasal": ["pulled in", "squeeze through", "ended up", "stepped off"], "wh": ["what"], "connectors": ["and", "but", "then", "only to"], "comparative": ["one of the most pleasant"]}, "exercises": {"grammar": [{"point": "Past perfect continuous", "explanation_pt": "Usamos 'had been standing' para mostrar uma ação contínua que aconteceu antes de outro momento no passado, como em 'Marta had been standing on the platform for almost an hour'."}, {"point": "Phrasal verbs de movimento", "explanation_pt": "Verbos como 'pulled in' e 'stepped off' descrevem a chegada e a saída do trem; é útil memorizá-los juntos, pois aparecem com frequência em textos sobre viagens."}], "multiple_choice": [{"question": "Why was Marta waiting on the platform for so long?", "options": ["The train was delayed", "The train was cancelled", "She arrived too early", "She missed the previous train"], "correct_index": 0, "explanation": "O texto diz que o trem estava atrasado (delayed)."}, {"question": "What happened when the train arrived?", "options": ["Marta got on easily", "Passengers pushed forward all at once", "Nobody else wanted to board", "The doors stayed open for a long time"], "correct_index": 1, "explanation": "Todos avançaram de uma vez, causando confusão."}, {"question": "Why had the old man saved a seat?", "options": ["For a friend", "For his wife", "For his granddaughter", "For no one"], "correct_index": 2, "explanation": "Ele guardou o assento para a neta."}, {"question": "Why couldn't the granddaughter use the seat?", "options": ["She changed her mind", "She sat somewhere else", "She never planned to travel", "She missed the train because of the delay"], "correct_index": 3, "explanation": "Ela também perdeu o trem por causa do atraso."}, {"question": "How did Marta feel by the end of the journey?", "options": ["Pleasantly surprised", "Still frustrated", "Bored", "Angry at the old man"], "correct_index": 0, "explanation": "A viagem se tornou uma das conversas mais agradáveis que ela teve em meses."}], "open_questions": [{"question": "Do you think small, unplanned conversations with strangers can change your day? Why or why not?", "key_points_pt": ["Mencionar experiências pessoais com estranhos", "Comparar expectativa versus realidade da viagem"]}, {"question": "How would you have reacted if you were in Marta's situation on the crowded train?", "key_points_pt": ["Descrever reação à demora e à lotação", "Explicar se aceitaria ou recusaria o convite do senhor"]}]}}, {"level": "B2", "genre": "humor", "title": "The Cat Who Ran the Meeting", "paragraphs": ["Diego worked from home, and his cat, Waffles, had developed a strange habit of walking across the keyboard during every video call. At first it was mildly annoying, but Diego had learned to mute himself quickly whenever Waffles approached. Unfortunately, on the day of the company's most important meeting, he forgot.", "Halfway through his presentation about quarterly sales, Waffles leapt onto the desk, sat directly in front of the camera, and began grooming himself with total confidence. Diego tried to nudge him away, but the cat refused to move, staring at the screen as if he, too, had opinions about the sales figures. His colleagues, rather than being annoyed, burst out laughing.", "To make matters worse, Waffles' tail brushed against the keyboard and accidentally shared Diego's screen full of vacation photos instead of the sales chart. The room went silent for a moment, then erupted into even louder laughter. Diego, red-faced, apologized repeatedly while trying to regain control of both his cat and his presentation.", "In the end, the meeting turned out to be surprisingly memorable, and Diego's boss admitted it was the most entertaining quarterly review she had ever attended. From then on, colleagues jokingly asked whether Waffles would be joining every call, and Diego, despite the embarrassment, couldn't help but agree that his cat deserved a promotion."], "paragraphs_pt": ["Diego trabalhava de casa, e seu gato, Waffles, tinha desenvolvido o estranho hábito de andar sobre o teclado durante toda videochamada. No começo era levemente irritante, mas Diego tinha aprendido a se silenciar rapidamente sempre que Waffles se aproximava. Infelizmente, no dia da reunião mais importante da empresa, ele esqueceu.", "No meio da apresentação sobre as vendas trimestrais, Waffles pulou sobre a mesa, sentou-se bem na frente da câmera e começou a se limpar com total confiança. Diego tentou empurrá-lo delicadamente para longe, mas o gato se recusou a sair, encarando a tela como se ele também tivesse opiniões sobre os números de vendas. Os colegas, em vez de ficarem irritados, caíram na gargalhada.", "Para piorar, o rabo de Waffles esbarrou no teclado e compartilhou sem querer a tela de Diego cheia de fotos de férias em vez do gráfico de vendas. A sala ficou em silêncio por um instante, e então explodiu em uma risada ainda mais alta. Diego, com o rosto vermelho, pediu desculpas repetidamente enquanto tentava retomar o controle do gato e da apresentação.", "No final, a reunião acabou sendo surpreendentemente memorável, e a chefe de Diego admitiu que aquela foi a revisão trimestral mais divertida que ela já tinha assistido. Dali em diante, os colegas perguntavam de brincadeira se Waffles participaria de todas as chamadas, e Diego, apesar do constrangimento, não pôde deixar de concordar que seu gato merecia uma promoção."], "hard_words": ["grooming", "nudge", "erupted", "red-faced"], "vocab": [{"word": "mute", "meaning": "silenciar, mudo", "note": ""}, {"word": "groom oneself", "meaning": "se limpar/arrumar (animal)", "note": ""}, {"word": "nudge", "meaning": "empurrar de leve, cutucar", "note": ""}, {"word": "burst out laughing", "meaning": "cair na gargalhada", "note": "expressão"}, {"word": "brush against", "meaning": "esbarrar em", "note": ""}, {"word": "erupt", "meaning": "explodir, estourar", "note": ""}, {"word": "regain control", "meaning": "retomar o controle", "note": ""}, {"word": "couldn't help but", "meaning": "não pôde deixar de", "note": "expressão"}], "word_meanings": [{"word": "grooming", "meaning": "se limpando/arrumando", "note": ""}, {"word": "nudge", "meaning": "empurrar de leve", "note": ""}, {"word": "erupted", "meaning": "explodiu", "note": ""}, {"word": "red-faced", "meaning": "com o rosto vermelho (envergonhado)", "note": ""}, {"word": "college", "meaning": "faculdade", "note": "falso cognato de 'colégio'"}, {"word": "eventually", "meaning": "finalmente, por fim", "note": "falso cognato de 'eventualmente'"}, {"word": "leapt", "meaning": "pulou", "note": ""}, {"word": "refused", "meaning": "recusou", "note": ""}, {"word": "burst out laughing", "meaning": "caiu na gargalhada", "note": ""}, {"word": "brushed against", "meaning": "esbarrou em", "note": ""}, {"word": "erupted into", "meaning": "explodiu em", "note": ""}, {"word": "apologized", "meaning": "pediu desculpas", "note": ""}, {"word": "turned out to be", "meaning": "acabou sendo", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "brush against", "meaning": "esbarrar em", "note": ""}, {"word": "regain control", "meaning": "retomar o controle", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being"], "irregular": ["leapt", "refused", "erupted", "apologized", "admitted"], "phrasal": ["burst out laughing", "regain control"], "wh": ["whether"], "connectors": ["but", "and", "then"], "comparative": ["most entertaining", "louder"]}, "exercises": {"grammar": [{"point": "Superlativo com 'most'", "explanation_pt": "Para adjetivos longos usamos 'the most' + adjetivo, como em 'the most entertaining quarterly review'."}, {"point": "'couldn't help but' + verbo", "explanation_pt": "Essa estrutura indica algo inevitável: 'Diego couldn't help but agree' significa que ele não conseguiu evitar concordar."}], "multiple_choice": [{"question": "What habit did Waffles have during video calls?", "options": ["Walking across the keyboard", "Meowing loudly", "Sleeping under the desk", "Scratching the chair"], "correct_index": 0, "explanation": "O texto diz que Waffles andava sobre o teclado."}, {"question": "What did Waffles do during the important meeting?", "options": ["Hid under the sofa", "Sat in front of the camera", "Knocked over a plant", "Left the room"], "correct_index": 1, "explanation": "Ele se sentou na frente da câmera."}, {"question": "What accidentally happened because of the cat's tail?", "options": ["The call disconnected", "The microphone turned off", "Vacation photos were shared instead of the chart", "The screen went black"], "correct_index": 2, "explanation": "O rabo do gato compartilhou as fotos de férias sem querer."}, {"question": "How did Diego's colleagues react?", "options": ["They complained to HR", "They left the call", "They ignored it completely", "They laughed"], "correct_index": 3, "explanation": "Eles caíram na gargalhada."}, {"question": "What did Diego's boss think of the meeting afterward?", "options": ["It was the most entertaining review she'd attended", "It was unprofessional", "It should never happen again", "She didn't notice anything"], "correct_index": 0, "explanation": "Ela admitiu que foi a revisão mais divertida que já assistiu."}], "open_questions": [{"question": "Have you ever had an embarrassing moment during an online call or meeting? What happened?", "key_points_pt": ["Descrever a situação", "Explicar como reagiu"]}, {"question": "Do you think pets appearing in work calls makes meetings more human, or is it unprofessional? Explain your view.", "key_points_pt": ["Dar opinião com justificativa", "Considerar contexto profissional versus informal"]}]}}, {"level": "B2", "genre": "detective", "title": "The Missing Painting", "paragraphs": ["Detective Ruiz arrived at the gallery just after midnight, when the alarm had gone off but no one could explain why. The famous painting, a portrait worth millions, had vanished from its frame, leaving only an empty rectangle on the wall. The curator, pale and visibly shaken, insisted that the security system had never failed before.", "Ruiz examined the room carefully, looking for anything that seemed out of place. She noticed that the window latch had been tampered with, though it was still locked from the inside, which struck her as odd. Furthermore, the security footage showed static for exactly six minutes, right when the theft must have occurred, suggesting the thief had inside knowledge of the system.", "As she questioned the staff, one guard kept avoiding eye contact and fidgeting with his keys. Ruiz decided to check his locker and, although he protested loudly, she found a rolled-up canvas hidden beneath his uniform. The guard finally broke down and admitted he had been paid to disable the cameras for a few minutes, never realizing his accomplice intended to steal the painting outright.", "By dawn, the painting had been recovered undamaged, and the guard was arrested along with the mastermind behind the plan, a former employee with access to old security codes. Ruiz filed her report, satisfied that justice had been served, though she couldn't help wondering how many other thefts had gone unnoticed because of similarly clever tricks."], "paragraphs_pt": ["A detetive Ruiz chegou à galeria logo depois da meia-noite, quando o alarme tinha disparado, mas ninguém conseguia explicar o motivo. A famosa pintura, um retrato que valia milhões, tinha desaparecido da moldura, deixando apenas um retângulo vazio na parede. O curador, pálido e visivelmente abalado, insistia que o sistema de segurança nunca tinha falhado antes.", "Ruiz examinou a sala com cuidado, procurando qualquer coisa fora do lugar. Ela notou que a trava da janela tinha sido violada, embora ainda estivesse trancada por dentro, o que lhe pareceu estranho. Além disso, as imagens de segurança mostravam apenas estática durante exatamente seis minutos, bem no momento em que o roubo deve ter acontecido, sugerindo que o ladrão tinha conhecimento interno do sistema.", "Enquanto interrogava os funcionários, um segurança evitava contato visual e mexia nervosamente nas chaves. Ruiz decidiu verificar o armário dele e, apesar de ele protestar em voz alta, encontrou uma tela enrolada escondida sob o uniforme. O segurança finalmente se entregou e admitiu que tinha sido pago para desativar as câmeras por alguns minutos, sem nunca imaginar que seu cúmplice pretendia simplesmente roubar a pintura.", "Ao amanhecer, a pintura já tinha sido recuperada intacta, e o segurança foi preso junto com o mentor do plano, um ex-funcionário que tinha acesso aos códigos antigos de segurança. Ruiz arquivou seu relatório, satisfeita por ver a justiça feita, embora não pudesse deixar de se perguntar quantos outros roubos tinham passado despercebidos por causa de truques igualmente espertos."], "hard_words": ["tampered with", "fidgeting", "outright", "mastermind"], "vocab": [{"word": "vanish", "meaning": "desaparecer", "note": ""}, {"word": "curator", "meaning": "curador (de museu/galeria)", "note": ""}, {"word": "tamper with", "meaning": "adulterar, mexer indevidamente", "note": "phrasal verb"}, {"word": "fidget", "meaning": "mexer-se nervosamente", "note": ""}, {"word": "break down", "meaning": "desmoronar, ceder emocionalmente", "note": "phrasal verb"}, {"word": "accomplice", "meaning": "cúmplice", "note": ""}, {"word": "mastermind", "meaning": "mentor, cérebro do plano", "note": ""}, {"word": "go unnoticed", "meaning": "passar despercebido", "note": ""}], "word_meanings": [{"word": "tampered with", "meaning": "adulterada, violada", "note": ""}, {"word": "fidgeting", "meaning": "mexendo nervosamente", "note": ""}, {"word": "outright", "meaning": "completamente, simplesmente", "note": ""}, {"word": "mastermind", "meaning": "mentor do plano", "note": ""}, {"word": "realize", "meaning": "perceber", "note": "falso cognato de 'realizar'"}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "arrived", "meaning": "chegou", "note": ""}, {"word": "went off", "meaning": "disparou (alarme)", "note": "phrasal verb"}, {"word": "vanished", "meaning": "desapareceu", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "broke down", "meaning": "se entregou/desmoronou", "note": "phrasal verb"}, {"word": "check", "meaning": "verificar", "note": ""}, {"word": "had vanished", "meaning": "tinha desaparecido", "note": ""}, {"word": "could", "meaning": "conseguia/podia", "note": ""}, {"word": "had gone off", "meaning": "tinha disparado", "note": ""}, {"word": "go unnoticed", "meaning": "passar despercebido", "note": ""}, {"word": "tamper with", "meaning": "adulterar, mexer indevidamente", "note": ""}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "insisted", "meaning": "insistiu", "note": ""}, {"word": "examined", "meaning": "examinou", "note": ""}, {"word": "break down", "meaning": "desmoronar, ceder emocionalmente", "note": ""}, {"word": "had never failed", "meaning": "nunca tinha falhado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "had been"], "irregular": ["arrived", "had gone off", "could", "had vanished", "insisted", "had never failed", "examined", "noticed"], "phrasal": [], "wh": ["why", "how"], "connectors": ["but", "though", "furthermore", "although", "because"], "comparative": ["similarly clever"]}, "exercises": {"grammar": [{"point": "Passado perfeito (had + particípio)", "explanation_pt": "Usamos o past perfect para mostrar que uma ação aconteceu antes de outra no passado, como em 'the painting had vanished' antes da chegada da detetive."}, {"point": "Modal 'must have' para dedução", "explanation_pt": "'must have occurred' expressa uma conclusão lógica sobre o passado, muito comum em histórias de investigação."}], "multiple_choice": [{"question": "What had happened to the painting when Ruiz arrived?", "options": ["It had disappeared", "It was damaged", "It had been sold", "It had been moved to another room"], "correct_index": 0, "explanation": "A pintura tinha desaparecido da moldura."}, {"question": "What seemed odd about the window?", "options": ["It was broken", "It was tampered with but still locked", "It was open", "It had no latch"], "correct_index": 1, "explanation": "A trava tinha sido violada, mas a janela continuava trancada."}, {"question": "What did Ruiz find in the guard's locker?", "options": ["A weapon", "Money", "The rolled-up painting", "A key to the gallery"], "correct_index": 2, "explanation": "Ela encontrou a tela enrolada escondida."}, {"question": "What had the guard been paid to do?", "options": ["Steal the painting himself", "Open the window", "Warn the thief", "Disable the cameras"], "correct_index": 3, "explanation": "Ele foi pago para desativar as câmeras."}, {"question": "Who turned out to be the mastermind?", "options": ["A former employee", "The curator", "A current employee", "Ruiz's colleague"], "correct_index": 0, "explanation": "Um ex-funcionário com acesso aos códigos antigos."}], "open_questions": [{"question": "What clues helped Ruiz realize the guard was involved?", "key_points_pt": ["Mencionar o comportamento nervoso", "Mencionar a decisão de checar o armário"]}, {"question": "Do you think the guard deserved the same punishment as the mastermind? Why or why not?", "key_points_pt": ["Justificar opinião", "Comparar responsabilidades dos dois personagens"]}]}}, {"level": "B2", "genre": "romance", "title": "Letters from the Lighthouse", "paragraphs": ["Every summer, Clara spent two weeks at her grandmother's cottage near the lighthouse, and every summer she wrote a letter she never sent to the boy who ran the small bookshop in town. Tomás, for his part, had noticed her from the very first year, always browsing the poetry section, always leaving without buying anything.", "This particular summer, however, something shifted. Clara walked in, soaked from an unexpected storm, and Tomás handed her a towel before she even asked. They ended up talking for hours about books neither of them had actually read, both too nervous to admit it, laughing at how ridiculous their opinions sounded once spoken aloud.", "Over the following days, Clara found excuses to visit the shop, and Tomás found excuses to close early so they could walk along the cliffs together. Neither mentioned the letters Clara had written over the years, though she sometimes wondered whether he suspected. When he finally confessed that he had saved a poem she once left behind by accident, she realized he had cared far longer than she imagined.", "On her last evening before returning home, they climbed the lighthouse together and watched the sun disappear into the sea. Tomás admitted he had been dreading this moment all summer, afraid she would simply vanish again until next year. Clara smiled and promised that, this time, she would leave with his address instead of another unsent letter."], "paragraphs_pt": ["Todo verão, Clara passava duas semanas na casa de campo da avó perto do farol, e todo verão escrevia uma carta que nunca enviava para o rapaz que trabalhava na pequena livraria da cidade. Tomás, por sua vez, tinha reparado nela desde o primeiro ano, sempre folheando a seção de poesia, sempre saindo sem comprar nada.", "Naquele verão específico, porém, algo mudou. Clara entrou encharcada por uma tempestade inesperada, e Tomás lhe entregou uma toalha antes mesmo que ela pedisse. Eles acabaram conversando por horas sobre livros que nenhum dos dois tinha lido de verdade, ambos nervosos demais para admitir isso, rindo de como suas opiniões soavam ridículas ao serem ditas em voz alta.", "Nos dias seguintes, Clara encontrava desculpas para visitar a livraria, e Tomás encontrava desculpas para fechar mais cedo para poderem caminhar juntos pelos penhascos. Nenhum dos dois mencionou as cartas que Clara tinha escrito ao longo dos anos, embora ela às vezes se perguntasse se ele suspeitava. Quando ele finalmente confessou que tinha guardado um poema que ela deixara por acidente, ela percebeu que ele se importava havia muito mais tempo do que imaginava.", "Na última noite antes de voltar para casa, eles subiram juntos ao farol e observaram o sol desaparecer no mar. Tomás admitiu que temia esse momento durante todo o verão, com medo de que ela simplesmente sumisse de novo até o ano seguinte. Clara sorriu e prometeu que, dessa vez, partiria com o endereço dele em vez de mais uma carta não enviada."], "hard_words": ["browsing", "soaked", "dreading", "cliffs"], "vocab": [{"word": "cottage", "meaning": "casa de campo, chalé", "note": ""}, {"word": "browse", "meaning": "folhear, dar uma olhada", "note": ""}, {"word": "soaked", "meaning": "encharcado", "note": ""}, {"word": "cliff", "meaning": "penhasco", "note": ""}, {"word": "confess", "meaning": "confessar", "note": ""}, {"word": "dread", "meaning": "temer profundamente", "note": ""}, {"word": "vanish", "meaning": "sumir, desaparecer", "note": ""}, {"word": "unsent", "meaning": "não enviado", "note": ""}], "word_meanings": [{"word": "browsing", "meaning": "folheando", "note": ""}, {"word": "soaked", "meaning": "encharcada", "note": ""}, {"word": "dreading", "meaning": "temendo", "note": ""}, {"word": "cliffs", "meaning": "penhascos", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realized", "meaning": "percebeu", "note": ""}, {"word": "spent", "meaning": "passou (tempo)", "note": ""}, {"word": "wrote", "meaning": "escreveu", "note": ""}, {"word": "had noticed", "meaning": "tinha reparado", "note": ""}, {"word": "walked in", "meaning": "entrou", "note": "phrasal verb"}, {"word": "handed", "meaning": "entregou", "note": ""}, {"word": "ended up", "meaning": "acabou", "note": "phrasal verb"}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "confessed", "meaning": "confessou", "note": ""}, {"word": "left behind", "meaning": "deixou para trás", "note": "phrasal verb"}], "grammar_words": {"cognates": ["actually", "realized"], "tobe": ["been"], "irregular": ["spent", "wrote", "had noticed", "walked in", "handed", "ended up", "found", "confessed", "left behind", "realized"], "phrasal": ["walked in", "ended up", "left behind"], "wh": ["whether", "how"], "connectors": ["however", "though", "and", "so"], "comparative": ["far longer"]}, "exercises": {"grammar": [{"point": "Uso de 'far' para intensificar comparativos", "explanation_pt": "'far longer' intensifica a comparação, mostrando uma diferença grande, como em 'he had cared far longer than she imagined'."}, {"point": "Past perfect para eventos anteriores", "explanation_pt": "'she had written over the years' mostra uma ação que já vinha acontecendo antes do momento principal da história."}], "multiple_choice": [{"question": "What did Clara do every summer before this particular one?", "options": ["She wrote letters but never sent them", "She sent letters to Tomás", "She avoided the bookshop", "She worked at the lighthouse"], "correct_index": 0, "explanation": "Ela escrevia cartas que nunca enviava."}, {"question": "How did Clara and Tomás's conversation start this summer?", "options": ["At a party", "When she entered the shop soaked from a storm", "On the beach", "During a poetry reading"], "correct_index": 1, "explanation": "Ela entrou encharcada por causa da tempestade."}, {"question": "What had Tomás secretly kept?", "options": ["A photo of Clara", "One of her letters", "A poem she left behind by accident", "A book she bought"], "correct_index": 2, "explanation": "Ele guardou um poema que ela deixou por acidente."}, {"question": "Where did they watch the sunset on Clara's last evening?", "options": ["On the beach", "At the bookshop", "On a boat", "At the lighthouse"], "correct_index": 3, "explanation": "Eles subiram ao farol juntos."}, {"question": "What did Clara promise before leaving?", "options": ["To leave with his address", "To return next week", "To write more letters", "To move to the town"], "correct_index": 0, "explanation": "Ela prometeu deixar o endereço dele em vez de outra carta não enviada."}], "open_questions": [{"question": "Why do you think Clara never sent her letters to Tomás in previous years?", "key_points_pt": ["Falar sobre medo de rejeição ou timidez", "Relacionar com a mudança de comportamento nesse verão"]}, {"question": "Do you believe small coincidences, like a sudden storm, can change the course of a relationship? Share an example.", "key_points_pt": ["Dar opinião pessoal", "Citar exemplo próprio ou hipotético"]}]}}, {"level": "B2", "genre": "scifi", "title": "The Last Signal from Kepler Station", "paragraphs": ["Commander Ines had been monitoring the same silence for three days when the signal finally flickered back to life. Kepler Station, orbiting a distant moon, had gone dark after an unexplained power surge, and Mission Control had feared the worst. Now, a faint transmission crackled through the speakers, barely audible above the static.", "The voice belonged to Dr. Okafor, the station's only remaining crew member, who explained that the surge had fried most of the ship's systems and knocked out life support in two of the three modules. He had spent the last seventy-two hours rerouting power manually, sealing himself into the smallest module to conserve oxygen while he worked.", "Ines coordinated a rescue shuttle immediately, though she knew it would take almost a week to arrive, far longer than Okafor's remaining oxygen supply would normally allow. Fortunately, he had discovered an overlooked reserve tank hidden behind a maintenance panel, something the original engineers had installed decades earlier as an emergency backup nobody remembered.", "When the shuttle finally docked, the crew found Okafor exhausted but alive, having rationed both oxygen and hope in equal measure. Back on Earth, his account of the ordeal became required reading for every new astronaut, a reminder that even the most advanced technology could fail, and that sometimes survival depended on nothing more than patience and a forgotten tank of air."], "paragraphs_pt": ["A comandante Ines já vinha monitorando o mesmo silêncio havia três dias quando o sinal finalmente voltou a piscar. A Estação Kepler, orbitando uma lua distante, tinha ficado às escuras depois de um pico de energia inexplicável, e o Controle da Missão temia o pior. Agora, uma transmissão fraca chiava pelos alto-falantes, mal audível em meio à estática.", "A voz pertencia ao Dr. Okafor, o único tripulante restante da estação, que explicou que o pico havia queimado a maior parte dos sistemas da nave e desligado o suporte de vida em dois dos três módulos. Ele tinha passado as últimas setenta e duas horas redirecionando energia manualmente, isolando-se no menor módulo para economizar oxigênio enquanto trabalhava.", "Ines coordenou um resgate imediatamente, embora soubesse que levaria quase uma semana para chegar, muito mais tempo do que o oxigênio restante de Okafor normalmente permitiria. Felizmente, ele tinha descoberto um tanque de reserva esquecido, escondido atrás de um painel de manutenção, algo que os engenheiros originais tinham instalado décadas antes como um backup de emergência que ninguém mais lembrava.", "Quando a nave de resgate finalmente atracou, a tripulação encontrou Okafor exausto, mas vivo, tendo racionado tanto oxigênio quanto esperança em igual medida. De volta à Terra, o relato dele sobre a provação se tornou leitura obrigatória para todo novo astronauta, um lembrete de que até a tecnologia mais avançada podia falhar, e que às vezes a sobrevivência dependia de nada mais do que paciência e um tanque de ar esquecido."], "hard_words": ["flickered", "fried", "rerouting", "ordeal"], "vocab": [{"word": "power surge", "meaning": "pico de energia", "note": ""}, {"word": "flicker", "meaning": "piscar, tremeluzir", "note": ""}, {"word": "fry (systems)", "meaning": "queimar (circuitos)", "note": "uso informal"}, {"word": "reroute", "meaning": "redirecionar", "note": ""}, {"word": "conserve", "meaning": "economizar, conservar", "note": ""}, {"word": "dock", "meaning": "atracar", "note": ""}, {"word": "ration", "meaning": "racionar", "note": ""}, {"word": "ordeal", "meaning": "provação, experiência difícil", "note": ""}], "word_meanings": [{"word": "flickered", "meaning": "piscou, tremeluziu", "note": ""}, {"word": "fried", "meaning": "queimou (circuitos)", "note": ""}, {"word": "rerouting", "meaning": "redirecionando", "note": ""}, {"word": "ordeal", "meaning": "provação", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "had been monitoring", "meaning": "vinha monitorando", "note": ""}, {"word": "had gone dark", "meaning": "tinha ficado às escuras", "note": ""}, {"word": "explained", "meaning": "explicou", "note": ""}, {"word": "knocked out", "meaning": "desligou, derrubou", "note": "phrasal verb"}, {"word": "had spent", "meaning": "tinha passado (tempo)", "note": ""}, {"word": "coordinated", "meaning": "coordenou", "note": ""}, {"word": "discovered", "meaning": "descobriu", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "became", "meaning": "se tornou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["had been"], "irregular": ["had been monitoring", "flickered", "had gone dark", "explained", "knocked out", "had spent", "coordinated", "found", "became"], "phrasal": ["knocked out"], "wh": ["who"], "connectors": ["though", "and", "but", "while", "fortunately"], "comparative": ["far longer", "most advanced", "smallest"]}, "exercises": {"grammar": [{"point": "Past perfect continuous", "explanation_pt": "'had been monitoring' mostra uma ação contínua antes de outro evento passado, criando tensão narrativa desde a primeira frase."}, {"point": "Superlativos irregulares e com 'most'", "explanation_pt": "'the smallest module' e 'the most advanced technology' mostram as duas formas de superlativo em inglês, curta e com 'most'."}], "multiple_choice": [{"question": "Why had Kepler Station gone silent?", "options": ["An unexplained power surge", "A meteor strike", "A communication error on Earth", "The crew abandoned it"], "correct_index": 0, "explanation": "Um pico de energia inexplicável causou o silêncio."}, {"question": "What did Dr. Okafor do to conserve oxygen?", "options": ["He left the station", "He sealed himself in the smallest module", "He turned off all communication", "He slept for three days"], "correct_index": 1, "explanation": "Ele se isolou no menor módulo."}, {"question": "What allowed Okafor to survive longer than expected?", "options": ["A second rescue shuttle", "Help from another station", "An overlooked reserve oxygen tank", "Reduced gravity"], "correct_index": 2, "explanation": "Ele encontrou um tanque de reserva esquecido."}, {"question": "How long did the rescue shuttle take to arrive?", "options": ["A few hours", "Three days", "A month", "Almost a week"], "correct_index": 3, "explanation": "O texto diz que levaria quase uma semana."}, {"question": "What lesson did new astronauts learn from Okafor's story?", "options": ["Patience can matter as much as technology", "Technology never fails", "Rescue missions are always fast", "Space stations don't need backups"], "correct_index": 0, "explanation": "O relato virou leitura obrigatória sobre paciência e sobrevivência."}], "open_questions": [{"question": "What personal qualities do you think helped Dr. Okafor survive alone for so long?", "key_points_pt": ["Mencionar paciência, disciplina, criatividade", "Justificar com exemplos do texto"]}, {"question": "Would you be willing to work on a space mission with this level of risk? Why or why not?", "key_points_pt": ["Expressar opinião pessoal", "Justificar considerando riscos e recompensas"]}]}}, {"level": "B2", "genre": "medieval", "title": "The Blacksmith's Apprentice", "paragraphs": ["Aldric had served as the village blacksmith's apprentice for three years, though he still felt clumsy every time he lifted the heavy hammer. The old smith, Master Cedric, rarely praised anyone, and Aldric had grown used to silent nods being the highest compliment he could expect. Still, he dreamed of forging a blade worthy of the knights who occasionally passed through the village.", "One autumn evening, a wounded knight arrived at the forge, his sword shattered after a skirmish near the border. He needed a new blade before dawn, when he was expected to ride to the capital and warn the king of an approaching threat. Master Cedric, exhausted from a long day's work, reluctantly allowed Aldric to attempt the forging himself, watching closely but saying nothing.", "Aldric worked through the night, hammering the glowing steel again and again, adjusting the balance until his arms ached beyond feeling. He thought of every lesson Cedric had ever given him, however brief, and poured all of it into the blade. As dawn approached, he plunged the finished sword into water, and the hiss of steam filled the forge like a held breath finally released.", "The knight tested the blade, swinging it twice before nodding with clear approval, and rode off toward the capital without another word. Master Cedric, watching him disappear over the hill, finally turned to Aldric and said simply that the sword had been well made. It was the longest sentence of praise Aldric had ever received, and he treasured it far more than any coin."], "paragraphs_pt": ["Aldric era aprendiz do ferreiro da vila havia três anos, embora ainda se sentisse desajeitado toda vez que erguia o martelo pesado. O velho ferreiro, Mestre Cedric, raramente elogiava alguém, e Aldric tinha se acostumado a considerar acenos silenciosos como o maior elogio que podia esperar. Ainda assim, ele sonhava em forjar uma lâmina digna dos cavaleiros que ocasionalmente passavam pela vila.", "Numa noite de outono, um cavaleiro ferido chegou à forja, com a espada estilhaçada depois de uma escaramuça perto da fronteira. Ele precisava de uma lâmina nova antes do amanhecer, quando era esperado que cavalgasse até a capital para avisar o rei sobre uma ameaça se aproximando. Mestre Cedric, exausto depois de um longo dia de trabalho, relutantemente permitiu que Aldric tentasse forjá-la sozinho, observando de perto, mas sem dizer nada.", "Aldric trabalhou a noite toda, martelando o aço incandescente repetidas vezes, ajustando o equilíbrio até seus braços doerem além do suportável. Ele pensou em cada lição que Cedric já lhe tinha dado, por mais breve que fosse, e colocou tudo isso na lâmina. Quando o amanhecer se aproximava, ele mergulhou a espada pronta na água, e o silvo do vapor encheu a forja como uma respiração presa finalmente solta.", "O cavaleiro testou a lâmina, brandindo-a duas vezes antes de acenar com clara aprovação, e partiu rumo à capital sem mais palavras. Mestre Cedric, observando-o desaparecer sobre a colina, finalmente se virou para Aldric e disse simplesmente que a espada tinha sido bem feita. Foi a frase de elogio mais longa que Aldric já tinha recebido, e ele a guardou como um tesouro muito maior do que qualquer moeda."], "hard_words": ["clumsy", "skirmish", "reluctantly", "plunged"], "vocab": [{"word": "blacksmith", "meaning": "ferreiro", "note": ""}, {"word": "apprentice", "meaning": "aprendiz", "note": ""}, {"word": "forge (verb/noun)", "meaning": "forjar / forja", "note": ""}, {"word": "skirmish", "meaning": "escaramuça, combate curto", "note": ""}, {"word": "reluctantly", "meaning": "relutantemente", "note": ""}, {"word": "plunge", "meaning": "mergulhar", "note": ""}, {"word": "hiss", "meaning": "silvo, chiado", "note": ""}, {"word": "treasure (verb)", "meaning": "valorizar muito, guardar como tesouro", "note": ""}], "word_meanings": [{"word": "clumsy", "meaning": "desajeitado", "note": ""}, {"word": "skirmish", "meaning": "escaramuça", "note": ""}, {"word": "reluctantly", "meaning": "relutantemente", "note": ""}, {"word": "plunged", "meaning": "mergulhou", "note": ""}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "had served", "meaning": "tinha servido/era", "note": ""}, {"word": "felt", "meaning": "sentiu/sentia", "note": ""}, {"word": "had grown used to", "meaning": "tinha se acostumado a", "note": ""}, {"word": "arrived", "meaning": "chegou", "note": ""}, {"word": "allowed", "meaning": "permitiu", "note": ""}, {"word": "worked through", "meaning": "trabalhou durante", "note": "phrasal verb"}, {"word": "poured into", "meaning": "colocou tudo em", "note": "phrasal verb"}, {"word": "rode off", "meaning": "partiu cavalgando", "note": "phrasal verb"}, {"word": "treasured", "meaning": "valorizou/guardou como tesouro", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["had served", "was", "being"], "irregular": ["had served", "felt", "arrived", "allowed", "plunged", "rode off", "treasured"], "phrasal": ["worked through", "rode off"], "wh": ["when", "who"], "connectors": ["though", "still", "however", "and", "but", "as"], "comparative": ["longest", "far more"]}, "exercises": {"grammar": [{"point": "Past perfect para dar contexto", "explanation_pt": "'had grown used to' mostra um hábito formado antes do momento principal da história, algo comum em narrativas no passado."}, {"point": "Superlativo 'longest' e comparativo 'far more'", "explanation_pt": "'the longest sentence of praise' e 'far more than any coin' mostram formas diferentes de comparação em inglês."}], "multiple_choice": [{"question": "How long had Aldric been the blacksmith's apprentice?", "options": ["Three years", "One year", "Five years", "Ten years"], "correct_index": 0, "explanation": "O texto diz três anos."}, {"question": "Why did the wounded knight need a new sword?", "options": ["His sword was stolen", "His sword shattered in a skirmish", "He wanted a gift for the king", "He lost a bet"], "correct_index": 1, "explanation": "A espada dele estilhaçou numa escaramuça."}, {"question": "Who actually forged the new sword?", "options": ["Master Cedric", "The knight himself", "Aldric", "A traveling merchant"], "correct_index": 2, "explanation": "Cedric permitiu que Aldric forjasse a espada."}, {"question": "What did the knight do after testing the blade?", "options": ["He complained about it", "He paid double the price", "He stayed in the village", "He rode off toward the capital"], "correct_index": 3, "explanation": "Ele partiu rumo à capital sem mais palavras."}, {"question": "How did Aldric feel about Cedric's final words?", "options": ["He treasured them deeply", "Disappointed", "Indifferent", "Confused"], "correct_index": 0, "explanation": "Ele guardou aquelas palavras como um tesouro."}], "open_questions": [{"question": "Why do you think Master Cedric rarely praised his apprentice before this event?", "key_points_pt": ["Discutir estilo de ensino rigoroso", "Relacionar com valorização do elogio raro"]}, {"question": "Describe a moment when a small amount of recognition or praise meant a lot to you.", "key_points_pt": ["Compartilhar experiência pessoal", "Explicar por que aquele elogio foi significativo"]}]}}, {"level": "B2", "genre": "mythology", "title": "The Weaver Who Outwitted the River God", "paragraphs": ["In the village beside the great river, everyone knew better than to insult the river god, who was said to flood the fields whenever his pride was wounded. Yet Sana, the village's finest weaver, had grown tired of the yearly tribute demanded in exchange for calm waters, a tribute that left her neighbors with barely enough grain to survive winter.", "One evening, Sana wove a cloak so beautiful that it seemed to shimmer like moving water itself, and she left it folded on the riverbank as an offering. The river god, vain and easily flattered, emerged to claim it, delighted by his own reflection in the shifting fabric. He declared that no mortal had ever created anything so magnificent, and he wrapped the cloak around his shoulders at once.", "What the god failed to notice, however, was that the cloak had been woven from threads soaked in river clay, threads that grew heavier the longer they touched water. As he admired himself, the cloak slowly pulled him toward the muddy bank, anchoring him just long enough for Sana to strike a bargain: he would lower the yearly tribute permanently, or she would leave him stuck in the mud until the next full moon.", "Furious but trapped, the river god agreed to her terms, and from that day forward the village paid only a fraction of what it once had. Sana never boasted about her trick, though the villagers whispered the story for generations, calling her the woman clever enough to out-weave a god."], "paragraphs_pt": ["Na vila ao lado do grande rio, todos sabiam que era melhor não insultar o deus do rio, que dizia-se inundar os campos sempre que seu orgulho fosse ferido. Ainda assim, Sana, a melhor tecelã da vila, tinha se cansado do tributo anual exigido em troca de águas calmas, um tributo que deixava seus vizinhos com grãos mal suficientes para sobreviver ao inverno.", "Certa noite, Sana teceu um manto tão bonito que parecia brilhar como a própria água em movimento, e o deixou dobrado na margem do rio como oferenda. O deus do rio, vaidoso e facilmente lisonjeado, emergiu para reivindicá-lo, encantado com seu próprio reflexo no tecido cambiante. Ele declarou que nenhum mortal jamais tinha criado algo tão magnífico, e envolveu o manto em seus ombros imediatamente.", "O que o deus não percebeu, porém, foi que o manto tinha sido tecido com fios embebidos em argila do rio, fios que ficavam mais pesados quanto mais tempo tocavam a água. Enquanto ele se admirava, o manto lentamente o puxava em direção à margem lamacenta, prendendo-o tempo suficiente para Sana fechar um acordo: ele reduziria o tributo anual permanentemente, ou ela o deixaria preso na lama até a próxima lua cheia.", "Furioso, mas preso, o deus do rio aceitou os termos dela, e a partir daquele dia a vila pagava apenas uma fração do que pagava antes. Sana nunca se gabou de seu truque, embora os aldeões sussurrassem a história por gerações, chamando-a de a mulher esperta o bastante para superar um deus tecendo."], "hard_words": ["shimmer", "flattered", "anchoring", "boasted"], "vocab": [{"word": "tribute", "meaning": "tributo", "note": ""}, {"word": "weave / wove / woven", "meaning": "tecer / teceu / tecido", "note": "verbo irregular"}, {"word": "shimmer", "meaning": "brilhar, cintilar", "note": ""}, {"word": "flatter", "meaning": "lisonjear", "note": ""}, {"word": "anchor (verb)", "meaning": "prender, ancorar", "note": ""}, {"word": "strike a bargain", "meaning": "fechar um acordo", "note": "expressão"}, {"word": "boast", "meaning": "gabar-se", "note": ""}, {"word": "out-weave", "meaning": "superar tecendo", "note": "palavra inventada no texto, com prefixo 'out-'"}], "word_meanings": [{"word": "shimmer", "meaning": "brilhar, cintilar", "note": ""}, {"word": "flattered", "meaning": "lisonjeado", "note": ""}, {"word": "anchoring", "meaning": "prendendo", "note": ""}, {"word": "boasted", "meaning": "se gabou", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "knew", "meaning": "sabiam", "note": ""}, {"word": "had grown tired", "meaning": "tinha se cansado", "note": ""}, {"word": "wove", "meaning": "teceu", "note": ""}, {"word": "left", "meaning": "deixou", "note": ""}, {"word": "emerged", "meaning": "emergiu", "note": ""}, {"word": "declared", "meaning": "declarou", "note": ""}, {"word": "wrapped", "meaning": "envolveu", "note": ""}, {"word": "failed to notice", "meaning": "não percebeu", "note": ""}, {"word": "grew", "meaning": "cresciam/ficavam", "note": ""}, {"word": "agreed", "meaning": "concordou", "note": ""}, {"word": "strike a bargain", "meaning": "fechar um acordo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["knew", "had grown tired", "left", "wove", "emerged", "declared", "wrapped", "grew", "agreed", "boasted"], "phrasal": ["strike a bargain"], "wh": ["whenever", "who"], "connectors": ["yet", "however", "though", "and", "but", "or"], "comparative": ["so magnificent", "heavier", "clever enough"]}, "exercises": {"grammar": [{"point": "Voz passiva com 'had been woven'", "explanation_pt": "A voz passiva no past perfect, 'had been woven from threads soaked in river clay', esconde quem fez a ação e enfatiza o objeto, comum em mitos e lendas."}, {"point": "'so...that' para consequência", "explanation_pt": "'so beautiful that it seemed to shimmer' liga uma qualidade extrema a uma consequência, estrutura muito usada em narrativas."}], "multiple_choice": [{"question": "Why was Sana tired of the yearly tribute?", "options": ["It left villagers with barely enough grain", "She didn't believe in the god", "She wanted to be famous", "The god never accepted it"], "correct_index": 0, "explanation": "O tributo deixava os vizinhos com grãos mal suficientes."}, {"question": "What did Sana leave on the riverbank?", "options": ["A basket of food", "A beautiful woven cloak", "A letter", "A statue"], "correct_index": 1, "explanation": "Ela deixou um manto tecido lindamente."}, {"question": "Why was the river god vulnerable to the trick?", "options": ["He was blind", "He was asleep", "He was vain and easily flattered", "He didn't like gifts"], "correct_index": 2, "explanation": "Ele era vaidoso e facilmente lisonjeado."}, {"question": "What made the cloak dangerous to the god?", "options": ["It was cursed", "It was too small", "It caught fire", "It grew heavier when wet, from clay threads"], "correct_index": 3, "explanation": "Os fios embebidos em argila ficavam mais pesados com a água."}, {"question": "What did the river god agree to do in the end?", "options": ["Lower the tribute permanently", "Leave the village forever", "Give Sana his powers", "Flood the fields once more"], "correct_index": 0, "explanation": "Ele concordou em reduzir o tributo anual permanentemente."}], "open_questions": [{"question": "What does this myth suggest about cleverness versus brute strength or power?", "key_points_pt": ["Comparar esperteza e poder físico/divino", "Relacionar com o desfecho da história"]}, {"question": "Do you know a story or myth from Brazilian folklore with a similarly clever trickster character? Describe it briefly.", "key_points_pt": ["Citar personagem do folclore brasileiro (ex: Saci, Curupira)", "Fazer comparação com a história lida"]}]}}, {"level": "B2", "genre": "western", "title": "The Debt at Crescent Ridge", "paragraphs": ["Sheriff Colton rode into Crescent Ridge just as the sun dipped below the mesa, kicking up dust that clung to his worn boots. He had been tracking a gang of cattle thieves for nearly two weeks, and every lead had pointed toward this dusty little town. What he hadn't expected was to find his old friend Wade running the local saloon.", "Wade insisted he had left his outlaw days behind, but Colton noticed the nervous way his friend's eyes darted toward the back room whenever a stranger walked in. Still, loyalty ran deep between them, and Colton decided to give Wade a chance to explain before jumping to conclusions, even as the evidence quietly piled up against him.", "That night, the gang's leader stormed into the saloon demanding Wade hand over the stolen cattle he had apparently been hiding for a cut of the profit. Colton stepped out from the shadows, revealing his badge, and gave Wade one last choice: stand with the law or stand with the thieves. After a long, tense silence, Wade knocked the leader's gun aside and sided with his old friend.", "The gang scattered once they realized they were outnumbered, and by morning most had been rounded up and locked away. Wade, shaken but relieved, admitted he had gotten involved out of desperation rather than greed, and Colton, choosing mercy over strict justice, gave him one chance to start over far from Crescent Ridge, on the condition that he never touched another man's cattle again."], "paragraphs_pt": ["O xerife Colton chegou a Crescent Ridge bem quando o sol se punha atrás da mesa rochosa, levantando poeira que grudava em suas botas gastas. Ele vinha rastreando uma quadrilha de ladrões de gado havia quase duas semanas, e toda pista apontava para aquela cidadezinha empoeirada. O que ele não esperava era encontrar seu velho amigo Wade administrando o saloon local.", "Wade insistiu que tinha deixado seus dias de fora da lei para trás, mas Colton notou o jeito nervoso como os olhos do amigo desviavam para os fundos sempre que um estranho entrava. Ainda assim, a lealdade entre eles era profunda, e Colton decidiu dar a Wade a chance de se explicar antes de tirar conclusões precipitadas, mesmo enquanto as evidências se acumulavam silenciosamente contra ele.", "Naquela noite, o líder da quadrilha invadiu o saloon exigindo que Wade entregasse o gado roubado que aparentemente vinha escondendo em troca de uma parte do lucro. Colton saiu das sombras, revelando seu distintivo, e deu a Wade uma última escolha: ficar do lado da lei ou do lado dos ladrões. Depois de um longo e tenso silêncio, Wade derrubou a arma do líder e ficou ao lado do velho amigo.", "A quadrilha se espalhou ao perceber que estava em desvantagem numérica, e pela manhã a maioria já tinha sido capturada e presa. Wade, abalado mas aliviado, admitiu que tinha se envolvido por desespero, e não por ganância, e Colton, escolhendo a misericórdia em vez da justiça rígida, deu a ele uma chance de recomeçar longe de Crescent Ridge, com a condição de nunca mais tocar no gado de outro homem."], "hard_words": ["mesa", "darted", "stormed", "scattered"], "vocab": [{"word": "saloon", "meaning": "bar/taverna do velho oeste", "note": ""}, {"word": "outlaw", "meaning": "fora da lei", "note": ""}, {"word": "dart (eyes)", "meaning": "desviar rapidamente (olhar)", "note": ""}, {"word": "storm in", "meaning": "entrar irrompendo, furioso", "note": "phrasal verb"}, {"word": "hand over", "meaning": "entregar", "note": "phrasal verb"}, {"word": "outnumbered", "meaning": "em desvantagem numérica", "note": ""}, {"word": "round up", "meaning": "capturar, reunir (à força)", "note": "phrasal verb"}, {"word": "greed", "meaning": "ganância", "note": ""}], "word_meanings": [{"word": "mesa", "meaning": "platô rochoso (formação geológica)", "note": ""}, {"word": "darted", "meaning": "desviaram rapidamente", "note": ""}, {"word": "stormed", "meaning": "invadiu furiosamente", "note": ""}, {"word": "scattered", "meaning": "se espalhou", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "rode", "meaning": "cavalgou", "note": ""}, {"word": "had been tracking", "meaning": "vinha rastreando", "note": ""}, {"word": "hadn't expected", "meaning": "não esperava", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "insisted", "meaning": "insistiu", "note": ""}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "decided", "meaning": "decidiu", "note": ""}, {"word": "gave", "meaning": "deu", "note": ""}, {"word": "knocked aside", "meaning": "derrubou/afastou com um golpe", "note": "phrasal verb"}, {"word": "sided with", "meaning": "ficou do lado de", "note": ""}, {"word": "realized", "meaning": "perceberam", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "storm in", "meaning": "entrar irrompendo, furioso", "note": ""}, {"word": "round up", "meaning": "capturar, reunir à força", "note": ""}, {"word": "hand over", "meaning": "entregar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["rode", "had been tracking", "hadn't expected", "insisted", "noticed", "darted", "decided", "gave", "stormed"], "phrasal": ["hand over", "sided with"], "wh": ["what", "whenever"], "connectors": ["but", "still", "even as", "and", "or", "rather than"], "comparative": ["nearly two weeks"]}, "exercises": {"grammar": [{"point": "Past perfect continuous para ações prolongadas", "explanation_pt": "'had been tracking' mostra uma ação contínua que já durava antes do momento presente da história, dando ideia de esforço prolongado."}, {"point": "Phrasal verbs de ação e conflito", "explanation_pt": "Expressões como 'storm in', 'hand over' e 'round up' são comuns em histórias de ação e ajudam a descrever eventos rápidos."}], "multiple_choice": [{"question": "Why had Colton come to Crescent Ridge?", "options": ["To track a gang of cattle thieves", "To visit Wade", "To retire", "To open a saloon"], "correct_index": 0, "explanation": "Ele vinha rastreando ladrões de gado."}, {"question": "What made Colton suspicious of Wade?", "options": ["Wade's clothes", "Wade's nervous glances toward the back room", "Wade's accent", "Wade's new horse"], "correct_index": 1, "explanation": "Os olhos de Wade desviavam nervosamente para os fundos."}, {"question": "What did the gang leader demand from Wade?", "options": ["Money", "A place to sleep", "The stolen cattle Wade had been hiding", "Information about Colton"], "correct_index": 2, "explanation": "Ele exigiu o gado roubado que Wade escondia."}, {"question": "What choice did Wade ultimately make?", "options": ["He ran away", "He sided with the gang", "He stayed neutral", "He sided with Colton and the law"], "correct_index": 3, "explanation": "Ele derrubou a arma do líder e ficou do lado de Colton."}, {"question": "How did Colton treat Wade in the end?", "options": ["He gave him a chance to start over", "He arrested him anyway", "He ignored him completely", "He exiled him publicly"], "correct_index": 0, "explanation": "Colton escolheu misericórdia e deu a ele uma chance de recomeçar."}], "open_questions": [{"question": "Do you think Colton was right to give Wade a second chance instead of arresting him? Why or why not?", "key_points_pt": ["Discutir justiça versus lealdade", "Justificar opinião com base na história"]}, {"question": "What would you have done if you discovered an old friend was secretly involved in a crime?", "key_points_pt": ["Refletir sobre lealdade pessoal versus princípios", "Dar exemplo hipotético"]}]}}, {"level": "B2", "genre": "spy", "title": "The Courier's Umbrella", "paragraphs": ["Agent Voss had memorized every detail of the meeting: a rainy afternoon, a crowded train station, and an umbrella with a chipped wooden handle that would identify the courier. What she hadn't anticipated was that three people in the terminal would be carrying nearly identical umbrellas, each one innocently unaware of the chaos their fashion choice was about to cause.", "She approached the first man cautiously, murmuring the agreed-upon phrase about the weather in Lisbon. He simply looked at her, confused, and hurried away, clearly just an ordinary commuter. The second attempt went slightly better, until the man laughed and explained he had bought the umbrella that same morning at a shop down the street, utterly unaware of any secret meaning behind it.", "Running out of time, Voss noticed a woman standing unusually still near the ticket booth, watching the crowd rather than checking the departure board like everyone else. When Voss repeated the phrase, the woman's expression barely changed, but she tilted her umbrella just enough to reveal a small folded note taped beneath the handle. The exchange took less than four seconds.", "Only once she was safely on a departing train did Voss allow herself to unfold the note, which contained coordinates for a shipment far more dangerous than anyone at headquarters had suspected. She realized, not for the first time, that the most difficult part of espionage was rarely the danger itself, but the sheer amount of patience required to sort chance from design in a crowd of ordinary strangers."], "paragraphs_pt": ["A agente Voss tinha memorizado cada detalhe do encontro: uma tarde chuvosa, uma estação de trem lotada e um guarda-chuva com o cabo de madeira lascado que identificaria a correio. O que ela não tinha previsto era que três pessoas no terminal estariam carregando guarda-chuvas quase idênticos, cada uma inocentemente alheia ao caos que sua escolha de acessório estava prestes a causar.", "Ela se aproximou do primeiro homem com cautela, murmurando a frase combinada sobre o tempo em Lisboa. Ele apenas olhou para ela, confuso, e se afastou apressado, claramente apenas um passageiro comum. A segunda tentativa foi um pouco melhor, até o homem rir e explicar que tinha comprado o guarda-chuva naquela mesma manhã numa loja perto dali, completamente alheio a qualquer significado secreto por trás dele.", "Sem tempo a perder, Voss notou uma mulher parada de forma incomumente imóvel perto da bilheteria, observando a multidão em vez de checar o painel de partidas como todo mundo. Quando Voss repetiu a frase, a expressão da mulher quase não mudou, mas ela inclinou o guarda-chuva o suficiente para revelar um pequeno bilhete dobrado colado sob o cabo. A troca durou menos de quatro segundos.", "Só depois de estar em segurança num trem já partindo é que Voss se permitiu desdobrar o bilhete, que continha coordenadas de um carregamento muito mais perigoso do que qualquer pessoa na sede tinha suspeitado. Ela percebeu, não pela primeira vez, que a parte mais difícil da espionagem raramente era o perigo em si, mas a enorme quantidade de paciência necessária para separar o acaso do plano em meio a uma multidão de estranhos comuns."], "hard_words": ["chipped", "murmuring", "commuter", "espionage"], "vocab": [{"word": "courier", "meaning": "correio, mensageiro", "note": ""}, {"word": "chipped", "meaning": "lascado", "note": ""}, {"word": "murmur", "meaning": "murmurar", "note": ""}, {"word": "commuter", "meaning": "passageiro que viaja regularmente", "note": ""}, {"word": "utterly", "meaning": "completamente", "note": ""}, {"word": "ticket booth", "meaning": "bilheteria", "note": ""}, {"word": "tilt", "meaning": "inclinar", "note": ""}, {"word": "espionage", "meaning": "espionagem", "note": ""}], "word_meanings": [{"word": "chipped", "meaning": "lascado", "note": ""}, {"word": "murmuring", "meaning": "murmurando", "note": ""}, {"word": "commuter", "meaning": "passageiro regular", "note": ""}, {"word": "espionage", "meaning": "espionagem", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato de 'realizar'"}, {"word": "had memorized", "meaning": "tinha memorizado", "note": ""}, {"word": "hadn't anticipated", "meaning": "não tinha previsto", "note": ""}, {"word": "approached", "meaning": "se aproximou", "note": ""}, {"word": "hurried away", "meaning": "se afastou apressado", "note": "phrasal verb"}, {"word": "found out", "meaning": "descobriu", "note": "phrasal verb (não usada no texto mas relevante)"}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "realized", "meaning": "percebeu", "note": ""}, {"word": "sort", "meaning": "separar, classificar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["had memorized", "hadn't anticipated", "approached", "murmuring", "hurried away", "noticed", "realized"], "phrasal": ["hurried away"], "wh": ["what"], "connectors": ["but", "until", "rather than"], "comparative": ["slightly better", "far more dangerous", "most difficult"]}, "exercises": {"grammar": [{"point": "Past perfect para expectativas frustradas", "explanation_pt": "'What she hadn't anticipated was...' mostra uma expectativa que não se confirmou, técnica comum em histórias de suspense."}, {"point": "Comparativos de grau variado", "explanation_pt": "'slightly better' e 'far more dangerous' mostram como advérbios como 'slightly' e 'far' ajustam a intensidade da comparação."}], "multiple_choice": [{"question": "What object would identify the courier?", "options": ["An umbrella with a chipped handle", "A red scarf", "A newspaper", "A specific hat"], "correct_index": 0, "explanation": "Um guarda-chuva com o cabo lascado identificaria a correio."}, {"question": "Why did the first attempt fail?", "options": ["The man ran away in fear", "He was just an ordinary commuter", "He recognized Voss", "He didn't speak the language"], "correct_index": 1, "explanation": "Ele era apenas um passageiro comum, confuso com a frase."}, {"question": "What made the woman near the ticket booth suspicious?", "options": ["Her clothing", "She was talking loudly", "She stood still, watching the crowd", "She was running"], "correct_index": 2, "explanation": "Ela observava a multidão em vez de checar o painel."}, {"question": "How was the note hidden?", "options": ["Inside a book", "In a pocket", "Under a hat", "Taped beneath the umbrella handle"], "correct_index": 3, "explanation": "O bilhete estava colado sob o cabo do guarda-chuva."}, {"question": "What did Voss conclude about espionage at the end?", "options": ["It mostly requires patience to sort chance from design", "It is mostly about danger", "It requires no planning", "It is easy once you memorize details"], "correct_index": 0, "explanation": "Ela percebeu que a parte mais difícil era a paciência necessária."}], "open_questions": [{"question": "Why do you think the mission relied on such a simple and everyday object like an umbrella?", "key_points_pt": ["Discutir discrição e disfarce em missões secretas", "Relacionar com o risco de confusão"]}, {"question": "Have you ever mistaken a stranger for someone you were expecting to meet? Describe what happened.", "key_points_pt": ["Compartilhar experiência pessoal", "Comparar com a confusão da história"]}]}}, {"level": "B2", "genre": "timetravel", "title": "Thirty Years Too Soon", "paragraphs": ["When the machine finally hummed to life, Priya expected fireworks, or at least a dramatic flash of light. Instead, the lab around her simply flickered, and when it steadied again, the equipment looked older, dustier, and strangely familiar. She checked the calibration panel and realized, with a jolt of panic, that she had traveled thirty years into the past rather than the future she had intended.", "Careful not to interact with anyone who might recognize her, Priya wandered the university halls, astonished to see her own mentor, Professor Liu, decades younger and full of an energy she barely remembered him having. She resisted the urge to speak to him, terrified of disrupting events that had already shaped the future she came from, though the temptation grew stronger with every familiar hallway she passed.", "Her plan to quietly repair the machine and return unnoticed fell apart when she overheard Professor Liu discussing an experiment that, in her own timeline, had famously failed and set the entire field back a decade. Torn between scientific ethics and a desperate wish to prevent years of wasted research, she finally left an anonymous note pointing out a flaw she knew, from hindsight, would doom the experiment.", "Back in her own present, Priya found the timeline eerily unchanged in most respects, except for one small detail: Professor Liu's award now included a line thanking an anonymous colleague whose insight had saved his career. She never told anyone what she had done, but she kept that framed award clipping on her desk as a quiet reminder that even a whisper across time could matter."], "paragraphs_pt": ["Quando a máquina finalmente zumbiu e entrou em funcionamento, Priya esperava fogos de artifício, ou pelo menos um flash dramático de luz. Em vez disso, o laboratório ao seu redor simplesmente tremeluziu, e quando se estabilizou de novo, o equipamento parecia mais antigo, empoeirado e estranhamente familiar. Ela checou o painel de calibração e percebeu, com um susto de pânico, que tinha viajado trinta anos para o passado, em vez do futuro que pretendia.", "Cuidadosa para não interagir com ninguém que pudesse reconhecê-la, Priya vagou pelos corredores da universidade, espantada ao ver seu próprio mentor, o Professor Liu, décadas mais jovem e cheio de uma energia que ela mal lembrava ele ter tido. Ela resistiu ao impulso de falar com ele, apavorada com a ideia de atrapalhar eventos que já tinham moldado o futuro de onde ela vinha, embora a tentação crescesse a cada corredor familiar que ela passava.", "Seu plano de consertar a máquina discretamente e voltar sem ser notada desmoronou quando ela ouviu por acaso o Professor Liu discutindo um experimento que, em sua própria linha do tempo, tinha famosamente fracassado e atrasado toda a área em uma década. Dividida entre a ética científica e o desejo desesperado de evitar anos de pesquisa desperdiçada, ela finalmente deixou um bilhete anônimo apontando uma falha que ela sabia, em retrospecto, que condenaria o experimento.", "De volta ao seu próprio presente, Priya encontrou a linha do tempo assustadoramente inalterada na maioria dos aspectos, exceto por um pequeno detalhe: o prêmio do Professor Liu agora incluía uma linha agradecendo a um colega anônimo cuja perspicácia tinha salvado sua carreira. Ela nunca contou a ninguém o que tinha feito, mas guardou aquele recorte emoldurado do prêmio em sua mesa como um lembrete silencioso de que até um sussurro através do tempo podia importar."], "hard_words": ["hummed", "jolt", "hindsight", "eerily"], "vocab": [{"word": "hum (verb)", "meaning": "zumbir", "note": ""}, {"word": "jolt", "meaning": "susto, choque repentino", "note": ""}, {"word": "astonished", "meaning": "espantado", "note": ""}, {"word": "overhear", "meaning": "ouvir por acaso", "note": ""}, {"word": "hindsight", "meaning": "retrospecto, visão retrospectiva", "note": ""}, {"word": "doom (verb)", "meaning": "condenar, sentenciar ao fracasso", "note": ""}, {"word": "eerily", "meaning": "de forma assustadora/estranha", "note": ""}, {"word": "insight", "meaning": "perspicácia, percepção profunda", "note": ""}], "word_meanings": [{"word": "hummed", "meaning": "zumbiu", "note": ""}, {"word": "jolt", "meaning": "susto repentino", "note": ""}, {"word": "hindsight", "meaning": "retrospecto", "note": ""}, {"word": "eerily", "meaning": "de forma estranha/assustadora", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "realize", "meaning": "perceber", "note": "falso cognato de 'realizar'"}, {"word": "expected", "meaning": "esperava", "note": ""}, {"word": "flickered", "meaning": "tremeluziu", "note": ""}, {"word": "checked", "meaning": "checou", "note": ""}, {"word": "realized", "meaning": "percebeu", "note": ""}, {"word": "had traveled", "meaning": "tinha viajado", "note": ""}, {"word": "wandered", "meaning": "vagou", "note": ""}, {"word": "resisted", "meaning": "resistiu", "note": ""}, {"word": "fell apart", "meaning": "desmoronou", "note": "phrasal verb"}, {"word": "overheard", "meaning": "ouviu por acaso", "note": ""}, {"word": "left", "meaning": "deixou", "note": ""}, {"word": "found", "meaning": "encontrou", "note": ""}, {"word": "kept", "meaning": "guardou", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["hummed", "expected", "flickered", "checked", "realized", "had traveled", "wandered", "resisted", "fell apart", "overheard"], "phrasal": ["fell apart"], "wh": ["who", "what"], "connectors": ["instead", "though", "but", "except"], "comparative": ["older", "younger", "stronger"]}, "exercises": {"grammar": [{"point": "Past perfect para eventos antes da viagem no tempo", "explanation_pt": "'she had traveled thirty years into the past' mostra uma ação concluída antes do momento em que ela percebe o erro, típico de histórias de viagem no tempo."}, {"point": "Comparativos simples com '-er'", "explanation_pt": "'older', 'younger' e 'stronger' são comparativos formados com o sufixo '-er', comuns em adjetivos curtos."}], "multiple_choice": [{"question": "What did Priya expect when the machine activated?", "options": ["Fireworks or a dramatic flash", "Nothing at all", "A loud alarm", "An explosion"], "correct_index": 0, "explanation": "Ela esperava fogos de artifício ou um flash dramático."}, {"question": "What mistake did Priya realize she had made?", "options": ["She traveled to the wrong city", "She traveled into the past instead of the future", "She broke the machine completely", "She brought the wrong equipment"], "correct_index": 1, "explanation": "Ela tinha viajado para o passado em vez do futuro pretendido."}, {"question": "Why didn't Priya speak to young Professor Liu?", "options": ["She didn't recognize him", "He didn't speak her language", "She was afraid of disrupting the future", "She had no time"], "correct_index": 2, "explanation": "Ela temia atrapalhar eventos que moldaram o futuro."}, {"question": "What did Priya do about the failed experiment she knew about?", "options": ["She ignored it completely", "She told Professor Liu directly", "She destroyed his notes", "She left an anonymous note about the flaw"], "correct_index": 3, "explanation": "Ela deixou um bilhete anônimo apontando a falha."}, {"question": "What changed when Priya returned to her present?", "options": ["The professor's award mentioned an anonymous colleague", "Nothing changed", "She lost her job", "The machine disappeared"], "correct_index": 0, "explanation": "O prêmio passou a agradecer a um colega anônimo."}], "open_questions": [{"question": "Do you think Priya was right to leave the anonymous note, even though it meant interfering with the past? Why or why not?", "key_points_pt": ["Discutir ética da interferência no tempo", "Justificar opinião"]}, {"question": "If you could travel thirty years into the past, what is one thing you would be tempted to change, and why?", "key_points_pt": ["Compartilhar ideia pessoal", "Explicar motivo e possíveis consequências"]}]}}, {"level": "B2", "genre": "news", "title": "City Council Approves Controversial Park Redesign", "paragraphs": ["After nearly eight months of heated public debate, the city council voted 6-3 on Tuesday night to approve a controversial redesign of Fairview Park, one of the oldest green spaces in the city. The plan, first proposed last winter, replaces several aging playground structures and adds a new community garden, but critics argue that it also removes a significant number of mature trees.", "Supporters of the redesign, including several local business owners, claim the changes will attract more families and boost foot traffic to nearby shops, which have struggled since a nearby mall opened five years ago. \"This park has been neglected for far too long,\" said council member Diane Foster during the meeting. \"We finally have a plan that balances recreation, accessibility, and community input.\"", "Opponents, however, remain unconvinced. A grassroots group called Save Fairview Trees collected over four thousand signatures opposing the removal of what they describe as irreplaceable century-old oaks. \"You cannot simply replant a hundred years of shade,\" argued group spokesperson Marcus Bell outside city hall. \"Once these trees are gone, this neighborhood loses something it can never fully get back.\"", "Construction is expected to begin in early spring and take roughly fourteen months to complete, according to city planners. The council has promised additional public meetings throughout the process to address ongoing concerns, though it remains unclear whether any further changes to the original plan are still possible at this stage."], "paragraphs_pt": ["Depois de quase oito meses de acalorado debate público, a câmara municipal votou 6 a 3 na terça-feira à noite para aprovar uma polêmica reforma do Parque Fairview, um dos espaços verdes mais antigos da cidade. O plano, proposto pela primeira vez no inverno passado, substitui diversas estruturas de playground envelhecidas e acrescenta uma nova horta comunitária, mas críticos argumentam que também remove um número significativo de árvores maduras.", "Apoiadores da reforma, incluindo diversos comerciantes locais, afirmam que as mudanças vão atrair mais famílias e aumentar o movimento de pedestres nas lojas próximas, que enfrentam dificuldades desde que um shopping próximo abriu há cinco anos. \"Esse parque foi negligenciado por tempo demais\", disse a vereadora Diane Foster durante a reunião. \"Finalmente temos um plano que equilibra recreação, acessibilidade e participação da comunidade.\"", "Os opositores, porém, continuam sem se convencer. Um grupo de base chamado Save Fairview Trees coletou mais de quatro mil assinaturas se opondo à remoção do que descrevem como carvalhos centenários insubstituíveis. \"Você não pode simplesmente replantar cem anos de sombra\", argumentou o porta-voz do grupo, Marcus Bell, do lado de fora da prefeitura. \"Assim que essas árvores desaparecerem, esse bairro perde algo que nunca vai recuperar totalmente.\"", "A construção deve começar no início da primavera e levar aproximadamente quatorze meses para ser concluída, segundo os planejadores da cidade. A câmara prometeu reuniões públicas adicionais ao longo do processo para tratar das preocupações contínuas, embora ainda não esteja claro se mais alguma mudança no plano original ainda é possível nesta etapa."], "hard_words": ["grassroots", "spokesperson", "neglected", "irreplaceable"], "vocab": [{"word": "council", "meaning": "câmara, conselho municipal", "note": ""}, {"word": "controversial", "meaning": "polêmico", "note": ""}, {"word": "boost", "meaning": "impulsionar, aumentar", "note": ""}, {"word": "grassroots", "meaning": "de base, popular", "note": ""}, {"word": "spokesperson", "meaning": "porta-voz", "note": ""}, {"word": "neglected", "meaning": "negligenciado", "note": ""}, {"word": "irreplaceable", "meaning": "insubstituível", "note": ""}, {"word": "ongoing", "meaning": "contínuo, em andamento", "note": ""}], "word_meanings": [{"word": "grassroots", "meaning": "de base, popular", "note": ""}, {"word": "spokesperson", "meaning": "porta-voz", "note": ""}, {"word": "neglected", "meaning": "negligenciado", "note": ""}, {"word": "irreplaceable", "meaning": "insubstituível", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "voted", "meaning": "votou", "note": ""}, {"word": "proposed", "meaning": "proposto", "note": ""}, {"word": "argue", "meaning": "argumentar", "note": ""}, {"word": "claim", "meaning": "afirmar", "note": ""}, {"word": "struggled", "meaning": "enfrentaram dificuldades", "note": ""}, {"word": "said", "meaning": "disse", "note": ""}, {"word": "collected", "meaning": "coletou", "note": ""}, {"word": "describe", "meaning": "descrever", "note": ""}, {"word": "is expected", "meaning": "espera-se que", "note": ""}, {"word": "promised", "meaning": "prometeu", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "has been"], "irregular": ["voted", "argue", "claim", "said", "collected", "describe", "is expected"], "phrasal": [], "wh": ["whether", "what"], "connectors": ["but", "however", "though", "since"], "comparative": ["oldest", "more families", "far too long"]}, "exercises": {"grammar": [{"point": "Presente perfeito com relevância no presente", "explanation_pt": "'has been neglected' e 'has promised' conectam ações passadas com a situação atual, comum em textos jornalísticos."}, {"point": "Discurso direto em reportagens", "explanation_pt": "Aspas com falas exatas, como '\"This park has been neglected for far too long,\" said council member Diane Foster', são típicas do gênero notícia para dar credibilidade."}], "multiple_choice": [{"question": "How did the city council vote on the park redesign?", "options": ["6-3 in favor", "Unanimously in favor", "5-4 against", "The vote was postponed"], "correct_index": 0, "explanation": "O texto diz que a votação foi 6 a 3."}, {"question": "What do critics say the redesign removes?", "options": ["Parking spaces", "A significant number of mature trees", "The community garden", "The playground entirely"], "correct_index": 1, "explanation": "Críticos dizem que remove árvores maduras."}, {"question": "Why do supporters believe the redesign will help local businesses?", "options": ["It lowers taxes", "It removes the mall", "It will attract more families and foot traffic", "It creates parking lots"], "correct_index": 2, "explanation": "Eles acreditam que vai atrair mais famílias e movimento."}, {"question": "What did the group Save Fairview Trees do?", "options": ["Filed a lawsuit", "Organized a protest march", "Met with the mayor privately", "Collected over four thousand signatures"], "correct_index": 3, "explanation": "O grupo coletou mais de quatro mil assinaturas."}, {"question": "When is construction expected to begin?", "options": ["In early spring", "Immediately", "Next winter", "In two years"], "correct_index": 0, "explanation": "A construção deve começar no início da primavera."}], "open_questions": [{"question": "Do you agree with the council's decision to prioritize new facilities over preserving old trees? Explain your reasoning.", "key_points_pt": ["Ponderar valor ambiental versus infraestrutura nova", "Justificar opinião pessoal"]}, {"question": "How could the city have handled the disagreement between supporters and opponents differently?", "key_points_pt": ["Sugerir formas de diálogo ou compromisso", "Considerar interesses de ambos os lados"]}]}}, {"level": "B2", "genre": "interview", "title": "A Conversation with a Marathon Runner Who Started at 50", "paragraphs": ["Q: You didn't start running until you were fifty. What finally pushed you to try it? A: Honestly, it was almost an accident. My doctor suggested I walk more after a routine check-up, and one day I just started jogging the last block home instead of walking it. It felt ridiculous at first, but something about it stuck with me, and I kept adding a little more distance each week.", "Q: Was it difficult to keep going, especially in the beginning? A: Incredibly difficult, yes. My knees ached, I was embarrassingly slow, and I remember feeling self-conscious whenever younger runners passed me. But I told myself that comparing my pace to theirs was pointless; I was competing against the version of myself from the week before, not against anyone else.", "Q: What was the turning point that made you consider running an actual marathon? A: I think it was finishing my first ten-kilometer race without stopping. I crossed that line and just started crying, which surprised me completely. I realized I had spent decades assuming certain things were simply not for me, and that assumption had quietly limited everything I attempted.", "Q: What would you say to someone who thinks it's too late to start something like this? A: I would say the only thing you actually lose by starting late is the years you already spent not starting. Those years are gone either way. The only real question left is whether you're going to spend the next ones on the sidelines or not, and honestly, that answer is completely up to you."], "paragraphs_pt": ["P: Você só começou a correr aos cinquenta anos. O que finalmente te motivou a tentar? R: Sinceramente, foi quase um acidente. Meu médico sugeriu que eu andasse mais depois de um check-up de rotina, e um dia eu simplesmente comecei a trotar o último quarteirão até em casa em vez de andar. Pareceu ridículo no começo, mas algo naquilo ficou comigo, e fui acrescentando um pouco mais de distância a cada semana.", "P: Foi difícil continuar, especialmente no início? R: Incrivelmente difícil, sim. Meus joelhos doíam, eu era constrangedoramente lenta, e me lembro de me sentir insegura sempre que corredores mais jovens me ultrapassavam. Mas eu dizia a mim mesma que comparar meu ritmo com o deles não fazia sentido; eu estava competindo com a versão de mim mesma da semana anterior, não com ninguém mais.", "P: Qual foi o ponto de virada que fez você considerar correr uma maratona de verdade? R: Acho que foi terminar minha primeira prova de dez quilômetros sem parar. Cruzei aquela linha e simplesmente comecei a chorar, o que me surpreendeu completamente. Percebi que tinha passado décadas presumindo que certas coisas simplesmente não eram para mim, e essa suposição tinha limitado silenciosamente tudo o que eu tentava.", "P: O que você diria para alguém que acha que é tarde demais para começar algo assim? R: Eu diria que a única coisa que você realmente perde ao começar tarde são os anos que você já passou sem começar. Esses anos já se foram de qualquer jeito. A única pergunta real que resta é se você vai passar os próximos anos na plateia ou não, e sinceramente, essa resposta é totalmente sua."], "hard_words": ["self-conscious", "pointless", "sidelines", "assuming"], "vocab": [{"word": "routine check-up", "meaning": "check-up de rotina", "note": ""}, {"word": "self-conscious", "meaning": "inseguro, constrangido", "note": ""}, {"word": "pointless", "meaning": "sem sentido, inútil", "note": ""}, {"word": "turning point", "meaning": "ponto de virada", "note": ""}, {"word": "assume", "meaning": "presumir, supor", "note": ""}, {"word": "sidelines", "meaning": "à margem, de fora (não participando)", "note": ""}, {"word": "up to you", "meaning": "depende de você", "note": "expressão"}, {"word": "stuck with", "meaning": "ficou marcado/gravado", "note": "phrasal verb"}], "word_meanings": [{"word": "self-conscious", "meaning": "inseguro, constrangido", "note": ""}, {"word": "pointless", "meaning": "sem sentido", "note": ""}, {"word": "sidelines", "meaning": "à margem", "note": ""}, {"word": "assuming", "meaning": "presumindo", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente", "note": "falso cognato"}, {"word": "started", "meaning": "começou", "note": ""}, {"word": "suggested", "meaning": "sugeriu", "note": ""}, {"word": "felt", "meaning": "pareceu/sentiu", "note": ""}, {"word": "stuck with", "meaning": "ficou marcado com", "note": "phrasal verb"}, {"word": "kept adding", "meaning": "continuou acrescentando", "note": ""}, {"word": "ached", "meaning": "doíam", "note": ""}, {"word": "told", "meaning": "disse", "note": ""}, {"word": "crossed", "meaning": "cruzou", "note": ""}, {"word": "realized", "meaning": "percebeu", "note": ""}, {"word": "had spent", "meaning": "tinha passado", "note": ""}, {"word": "had limited", "meaning": "tinha limitado", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["was", "were", "is"], "irregular": ["suggested", "started", "felt", "stuck with", "kept adding", "ached", "told", "crossed", "started", "realized"], "phrasal": ["stuck with"], "wh": ["what", "who", "whether"], "connectors": ["but", "and", "either way", "honestly"], "comparative": ["more distance", "younger"]}, "exercises": {"grammar": [{"point": "Perguntas e respostas em formato de entrevista", "explanation_pt": "Note como as perguntas usam inversão sujeito-verbo ('What finally pushed you...') enquanto as respostas usam frases mais longas e conectores para explicar o raciocínio."}, {"point": "Present perfect e past perfect combinados", "explanation_pt": "'I had spent decades assuming' usa o past perfect para mostrar algo anterior à percepção descrita, um padrão comum em relatos pessoais."}], "multiple_choice": [{"question": "What motivated the runner to start jogging?", "options": ["A doctor's suggestion to walk more", "A friend's challenge", "A marathon advertisement", "A weight-loss goal"], "correct_index": 0, "explanation": "O médico sugeriu que ela andasse mais."}, {"question": "How did she deal with feeling slower than younger runners?", "options": ["She stopped running", "She compared herself only to her past self", "She trained harder to beat them", "She avoided running near others"], "correct_index": 1, "explanation": "Ela competia com a versão de si mesma da semana anterior."}, {"question": "What was her turning point toward running a marathon?", "options": ["Winning a local race", "Watching a marathon on TV", "Finishing her first ten-kilometer race without stopping", "A conversation with her doctor"], "correct_index": 2, "explanation": "Foi terminar os dez quilômetros sem parar."}, {"question": "What realization did she have after that race?", "options": ["She should quit running", "She needed a coach", "She was too old to continue", "She had wrongly assumed some things weren't for her"], "correct_index": 3, "explanation": "Ela percebeu que tinha presumido erroneamente que certas coisas não eram para ela."}, {"question": "What does she say people actually lose by starting late?", "options": ["Only the years already spent not starting", "Nothing at all", "Their health", "Their confidence"], "correct_index": 0, "explanation": "Ela diz que só se perde os anos já passados sem começar."}], "open_questions": [{"question": "Do you agree that it's never too late to start something new? Why or why not?", "key_points_pt": ["Dar opinião justificada", "Citar exemplo pessoal ou de terceiros"]}, {"question": "Is there something you have been putting off starting because you think you're 'too old' or 'too late' for it? What is it?", "key_points_pt": ["Refletir sobre experiência pessoal", "Explicar o que impede de começar"]}]}}, {"level": "C1", "genre": "neutral", "title": "The Last Ferry", "paragraphs": ["Every evening, Marta caught the last ferry across the bay, even though a faster bus route had opened the previous year. She could have shaved twenty minutes off her commute, but she preferred the slow rhythm of the water and the way the city lights blurred into gold as the boat pulled away from the dock.", "One rainy Thursday, the ferry was delayed, and she ended up sitting beside an elderly man who claimed to have crossed that same bay for forty years. He spoke with a quiet confidence, recounting storms he had survived and passengers he had befriended, and Marta realized, somewhat sheepishly, that she had never once struck up a conversation with a stranger on board.", "By the time the boat docked, the rain had eased, and the old man handed her a folded paper crane before disembarking. He said it was a habit he had picked up decades ago, a small gesture to remind fellow travelers that the journey itself was worth savoring, not merely the destination.", "Marta kept the crane on her desk for years afterward. Whenever deadlines piled up and she felt tempted to abandon the ferry for the sake of efficiency, she glanced at the little paper bird and chose, instead, to slow down."], "paragraphs_pt": ["Todas as noites, Marta pegava a última balsa para atravessar a baía, mesmo com uma rota de ônibus mais rápida que tinha sido inaugurada no ano anterior. Ela poderia ter economizado vinte minutos no trajeto, mas preferia o ritmo lento da água e o jeito como as luzes da cidade se misturavam num tom dourado quando o barco se afastava do cais.", "Numa quinta-feira chuvosa, a balsa atrasou, e ela acabou sentando ao lado de um senhor idoso que dizia atravessar aquela mesma baía havia quarenta anos. Ele falava com uma calma confiante, contando tempestades que tinha sobrevivido e passageiros com quem tinha feito amizade, e Marta percebeu, um tanto encabulada, que nunca havia puxado conversa com um desconhecido a bordo.", "Quando o barco atracou, a chuva já tinha diminuído, e o velho lhe entregou um origami de tsuru antes de desembarcar. Ele disse que era um hábito adquirido décadas atrás, um pequeno gesto para lembrar aos outros viajantes que a própria jornada valia a pena ser apreciada, não só o destino.", "Marta guardou o origami na mesa dela por anos. Sempre que os prazos se acumulavam e ela sentia vontade de abandonar a balsa em nome da eficiência, ela olhava para o passarinho de papel e, em vez disso, escolhia desacelerar."], "hard_words": ["shaved", "sheepishly", "disembarking", "savoring"], "vocab": [{"word": "commute", "meaning": "trajeto diário (casa-trabalho)", "note": ""}, {"word": "struck up a conversation", "meaning": "puxar conversa", "note": "expressão idiomática"}, {"word": "quiet confidence", "meaning": "confiança tranquila", "note": ""}, {"word": "handed her", "meaning": "entregou a ela", "note": ""}, {"word": "worth savoring", "meaning": "que vale a pena apreciar", "note": ""}, {"word": "piled up", "meaning": "se acumularam", "note": "phrasal verb"}, {"word": "for the sake of", "meaning": "em nome de, por causa de", "note": ""}, {"word": "slow down", "meaning": "desacelerar", "note": "phrasal verb"}], "word_meanings": [{"word": "shaved", "meaning": "reduzido/cortado (tempo)", "note": ""}, {"word": "sheepishly", "meaning": "com timidez/encabulado", "note": ""}, {"word": "disembarking", "meaning": "desembarcando", "note": ""}, {"word": "savoring", "meaning": "saboreando/apreciando", "note": ""}, {"word": "struck up", "meaning": "iniciar (uma conversa)", "note": "phrasal verb"}, {"word": "piled up", "meaning": "acumularam-se", "note": "phrasal verb"}, {"word": "opened", "meaning": "abriu/inaugurou", "note": "passado simples"}, {"word": "caught", "meaning": "pegou", "note": "passado irregular"}, {"word": "spoke", "meaning": "falou", "note": "passado irregular"}, {"word": "handed", "meaning": "entregou", "note": "passado regular"}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "felt", "meaning": "sentiu", "note": "passado irregular"}, {"word": "kept", "meaning": "manteve/continuou", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["caught", "spoke", "handed", "opened", "kept", "felt"], "phrasal": ["struck up", "piled up"], "wh": [], "connectors": ["even though", "but", "and", "instead"], "comparative": ["faster"]}, "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "Usamos o past perfect para uma ação anterior a outra no passado: 'a faster bus route had opened the previous year' aconteceu antes do hábito de Marta continuar."}, {"point": "Simple past narrativo", "explanation_pt": "A história usa o simple past para narrar eventos em sequência, como em 'the old man handed her a folded paper crane before disembarking'."}], "multiple_choice": [{"question": "Why did Marta keep taking the ferry instead of the bus?", "options": ["She enjoyed the slow pace and the view", "It was cheaper", "The bus was unsafe", "She had no other option"], "correct_index": 0, "explanation": "Ela preferia o ritmo lento e a vista da balsa."}, {"question": "What happened one rainy Thursday?", "options": ["The ferry sank", "The ferry was delayed", "Marta missed the ferry", "The old man got lost"], "correct_index": 1, "explanation": "A balsa atrasou naquele dia."}, {"question": "How long had the old man been crossing the bay?", "options": ["Ten years", "Twenty years", "Forty years", "His whole life"], "correct_index": 2, "explanation": "Ele dizia atravessar havia quarenta anos."}, {"question": "What did the old man give Marta?", "options": ["A book", "A photograph", "A ticket", "A paper crane"], "correct_index": 3, "explanation": "Ele deu um origami em forma de pássaro (tsuru)."}, {"question": "What did Marta do whenever she felt tempted to skip the ferry?", "options": ["She looked at the paper crane and slowed down", "She called the old man", "She took the bus anyway", "She quit her job"], "correct_index": 0, "explanation": "Ela olhava para o origami e escolhia desacelerar."}], "open_questions": [{"question": "Do you think small rituals like Marta's ferry ride matter in daily life? Why or why not?", "key_points_pt": ["mencionar o valor de rituais pessoais", "conectar com exemplos da própria rotina"]}, {"question": "What lesson did the old man's gift teach Marta about efficiency versus enjoyment?", "key_points_pt": ["explicar a ideia de valorizar o percurso, não só o destino", "citar o hábito do origami"]}]}}, {"level": "C1", "genre": "suspense", "title": "The Sound Upstairs", "paragraphs": ["Renata had lived alone in the old apartment for three years, and she had grown accustomed to its creaks, its groaning pipes, and the occasional shudder of the elevator shaft. So when she heard footsteps directly above her ceiling at two in the morning, she told herself it was nothing, since the flat upstairs had been vacant since the previous tenant moved out.", "The footsteps returned the following night, slower this time, pausing right above her bedroom before dragging toward the far wall. Renata lay rigid beneath the blanket, straining to convince herself that pipes could not possibly account for such a deliberate, measured pace, yet she was too unsettled to switch on the light.", "On the third night, she finally worked up the nerve to knock on the building superintendent's door. He admitted, almost reluctantly, that a contractor had been given a spare key to inspect the empty unit for a leak, but insisted the man only worked during the day. Renata's stomach tightened as she realized that whoever paced above her at night was not authorized to be there at all.", "She reported it to the police, who found the upstairs window pried open and a sleeping bag tucked behind the water tank; someone had apparently been squatting there for weeks, careful enough to leave during daylight hours. Though the intruder was never caught, Renata moved out within the month, unable to shake the memory of those slow, deliberate footsteps pacing above her bed."], "paragraphs_pt": ["Renata morava sozinha naquele apartamento antigo havia três anos e já tinha se acostumado com os rangidos, os canos que gemiam e o estremecimento ocasional do poço do elevador. Então, quando ouviu passos bem acima do teto às duas da manhã, disse a si mesma que não era nada, já que o apartamento de cima estava vazio desde que o inquilino anterior tinha se mudado.", "Os passos voltaram na noite seguinte, mais lentos dessa vez, parando bem acima do quarto dela antes de se arrastar em direção à parede do fundo. Renata ficou rígida debaixo do cobertor, se esforçando para se convencer de que canos não poderiam explicar um ritmo tão deliberado e medido, mas estava perturbada demais para acender a luz.", "Na terceira noite, ela finalmente criou coragem para bater na porta do zelador do prédio. Ele admitiu, quase a contragosto, que um empreiteiro tinha recebido uma cópia da chave para inspecionar o apartamento vazio por causa de um vazamento, mas garantiu que o homem só trabalhava durante o dia. O estômago de Renata se apertou ao perceber que quem andava de um lado para o outro à noite ali em cima não tinha autorização nenhuma para estar lá.", "Ela denunciou o caso à polícia, que encontrou a janela do andar de cima arrombada e um saco de dormir escondido atrás da caixa d'água; alguém aparentemente estava morando ali às escondidas fazia semanas, cuidadoso o bastante para sair durante o dia. Embora o intruso nunca tenha sido pego, Renata se mudou dentro de um mês, incapaz de esquecer aqueles passos lentos e deliberados andando acima da cama dela."], "hard_words": ["shudder", "rigid", "reluctantly", "pried", "squatting"], "vocab": [{"word": "grown accustomed to", "meaning": "se acostumado com", "note": ""}, {"word": "worked up the nerve", "meaning": "criar coragem", "note": "expressão idiomática"}, {"word": "spare key", "meaning": "chave reserva", "note": ""}, {"word": "her stomach tightened", "meaning": "o estômago se apertou (de medo)", "note": ""}, {"word": "pried open", "meaning": "arrombada/forçada", "note": ""}, {"word": "tucked behind", "meaning": "escondido atrás de", "note": ""}, {"word": "unable to shake", "meaning": "incapaz de esquecer/se livrar de", "note": ""}], "word_meanings": [{"word": "shudder", "meaning": "estremecimento", "note": ""}, {"word": "rigid", "meaning": "rígida, dura", "note": ""}, {"word": "reluctantly", "meaning": "a contragosto", "note": ""}, {"word": "pried", "meaning": "arrombou/forçou", "note": ""}, {"word": "squatting", "meaning": "morando ilegalmente/ocupando sem permissão", "note": ""}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente, com o tempo (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/estava", "note": "to be"}, {"word": "were", "meaning": "eram/estavam", "note": "to be"}, {"word": "moved", "meaning": "mudou-se", "note": "passado regular"}, {"word": "found", "meaning": "encontrou", "note": "passado irregular"}, {"word": "worked up", "meaning": "criou (coragem)", "note": "phrasal verb"}, {"word": "switch on", "meaning": "acender/ligar", "note": "phrasal verb"}, {"word": "whoever", "meaning": "quem quer que", "note": "wh-word"}, {"word": "lay", "meaning": "estava deitado(a)", "note": "passado irregular"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular"}, {"word": "told", "meaning": "disse/contou", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["moved", "found", "heard", "told", "lay"], "phrasal": ["worked up", "switch on"], "wh": ["whoever"], "connectors": ["since", "so", "yet", "though"], "comparative": ["slower"]}, "exercises": {"grammar": [{"point": "Past continuous vs simple past", "explanation_pt": "Usamos o passado contínuo para uma ação em andamento interrompida por outra: 'she heard footsteps' (simples) enquanto algo acontecia acima dela."}, {"point": "Modal 'could not possibly'", "explanation_pt": "Expressa impossibilidade forte, como em 'pipes could not possibly account for such a deliberate pace'."}], "multiple_choice": [{"question": "Why did Renata initially ignore the footsteps?", "options": ["She thought the apartment above was empty", "She was not home", "She was used to loud neighbors", "She could not hear well"], "correct_index": 0, "explanation": "Ela achava que o apartamento de cima estava vazio."}, {"question": "What did the superintendent say about the contractor?", "options": ["He worked only at night", "He worked only during the day", "He had never been given a key", "He no longer worked there"], "correct_index": 1, "explanation": "O contratado só trabalhava de dia, segundo o zelador."}, {"question": "What did the police find in the empty apartment?", "options": ["A broken pipe", "Nothing unusual", "A sleeping bag and a pried-open window", "A missing person"], "correct_index": 2, "explanation": "Encontraram a janela arrombada e um saco de dormir."}, {"question": "What can be inferred about the intruder?", "options": ["They were caught immediately", "They were a former tenant", "They were the superintendent", "They were careful to avoid being seen during the day"], "correct_index": 3, "explanation": "O intruso saía durante o dia para não ser visto."}, {"question": "What did Renata ultimately decide to do?", "options": ["Move out of the apartment", "Install cameras", "Confront the intruder herself", "Ignore the situation"], "correct_index": 0, "explanation": "Ela se mudou dentro de um mês."}], "open_questions": [{"question": "How does the author build suspense before revealing the truth about the footsteps?", "key_points_pt": ["mencionar os detalhes sensoriais e o ritmo lento da revelação", "citar a reação física de Renata"]}, {"question": "Would you have reacted the same way Renata did? What would you have done differently?", "key_points_pt": ["dar opinião pessoal", "justificar com exemplo do texto ou experiência própria"]}]}}, {"level": "C1", "genre": "detective", "title": "The Vanishing Signature", "paragraphs": ["Detective Alves had seen plenty of forged paintings during her career, but none had been quite as brazen as the one hanging in the Coutinho gallery. The insurance company suspected fraud the moment the claimed value tripled overnight, and they called her in to determine whether the celebrated seascape was genuine or an elaborate hoax.", "She began, as she always did, by interrogating the least obvious suspect: the gallery's soft-spoken restorer, who insisted he had merely cleaned the varnish. Alves noticed, however, that his hands trembled whenever she mentioned the artist's signature, a telltale sign that something did not quite add up.", "Under ultraviolet light, the signature revealed a faint discrepancy: the ink beneath it was decades newer than the paint surrounding it, meaning someone had painstakingly added the artist's name long after the canvas had dried. The restorer finally confessed, explaining that the gallery owner had pressured him into signing an unattributed painting to inflate its resale value.", "Alves handed the case over to the fraud unit, though she took a quiet satisfaction in having outsmarted a scheme so meticulously disguised. As she left the gallery, she reflected that forgers rarely failed at the brushwork; it was almost always the smallest, most overlooked detail, like a signature, that gave them away."], "paragraphs_pt": ["A detetive Alves já tinha visto muitas pinturas falsificadas ao longo da carreira, mas nenhuma fora tão descarada quanto aquela pendurada na galeria Coutinho. A seguradora suspeitou de fraude assim que o valor declarado triplicou da noite para o dia, e a chamaram para determinar se a célebre marinha era autêntica ou uma farsa elaborada.", "Ela começou, como sempre fazia, interrogando o suspeito menos óbvio: o restaurador discreto da galeria, que insistia ter apenas limpado o verniz. Alves notou, porém, que as mãos dele tremiam sempre que ela mencionava a assinatura do artista, um sinal revelador de que algo não batia.", "Sob luz ultravioleta, a assinatura revelou uma discrepância sutil: a tinta por baixo dela era décadas mais nova do que a tinta ao redor, o que significava que alguém tinha acrescentado cuidadosamente o nome do artista muito depois de a tela já estar seca. O restaurador finalmente confessou, explicando que o dono da galeria o havia pressionado a assinar uma pintura sem autoria para inflar o valor de revenda.", "Alves entregou o caso à unidade de fraudes, embora sentisse uma satisfação silenciosa por ter sido mais esperta que um esquema tão meticulosamente disfarçado. Ao sair da galeria, refletiu que falsificadores raramente erravam nas pinceladas; era quase sempre o detalhe menor e mais negligenciado, como uma assinatura, que os denunciava."], "hard_words": ["brazen", "hoax", "telltale", "painstakingly", "meticulously"], "vocab": [{"word": "called her in", "meaning": "a chamaram (para o caso)", "note": "phrasal verb"}, {"word": "something did not quite add up", "meaning": "algo não batia/fazia sentido", "note": "expressão idiomática"}, {"word": "gave them away", "meaning": "os denunciou/entregou", "note": "phrasal verb"}, {"word": "inflate", "meaning": "inflar/aumentar artificialmente", "note": ""}, {"word": "outsmarted", "meaning": "foi mais esperto(a) que", "note": ""}, {"word": "resale value", "meaning": "valor de revenda", "note": ""}, {"word": "handed over", "meaning": "entregou/repassou", "note": "phrasal verb"}], "word_meanings": [{"word": "brazen", "meaning": "descarado, ousado", "note": ""}, {"word": "hoax", "meaning": "farsa, embuste", "note": ""}, {"word": "telltale", "meaning": "revelador, denunciador", "note": ""}, {"word": "painstakingly", "meaning": "cuidadosamente, com esmero", "note": ""}, {"word": "meticulously", "meaning": "meticulosamente", "note": ""}, {"word": "called in", "meaning": "chamada/convocada", "note": "phrasal verb"}, {"word": "add up", "meaning": "fazer sentido", "note": "phrasal verb"}, {"word": "gave away", "meaning": "denunciou", "note": "phrasal verb"}, {"word": "handed over", "meaning": "entregou", "note": "phrasal verb"}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "began", "meaning": "começou", "note": "passado irregular"}, {"word": "confessed", "meaning": "confessou", "note": "passado regular"}, {"word": "left", "meaning": "deixou", "note": "passado irregular"}, {"word": "handed", "meaning": "entregou", "note": "passado irregular"}, {"word": "noticed", "meaning": "notou", "note": "passado irregular"}, {"word": "took", "meaning": "levou/pegou", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["had been", "was"], "irregular": ["began", "noticed", "confessed", "left", "took", "handed"], "phrasal": ["add up"], "wh": ["whether", "who"], "connectors": ["but", "however", "though", "as"], "comparative": ["newer", "smallest", "most overlooked"]}, "exercises": {"grammar": [{"point": "Past perfect para eventos anteriores", "explanation_pt": "Usamos o past perfect para algo que aconteceu antes de outro evento passado: 'someone had painstakingly added the artist's name long after the canvas had dried'."}, {"point": "Comparativos e superlativos", "explanation_pt": "A história usa formas como 'newer' e 'the smallest, most overlooked detail' para comparar elementos da investigação."}], "multiple_choice": [{"question": "Why did the insurance company get suspicious?", "options": ["The claimed value tripled overnight", "The painting disappeared", "The gallery closed", "The artist complained"], "correct_index": 0, "explanation": "O valor declarado triplicou de repente."}, {"question": "Who did Alves interrogate first?", "options": ["The gallery owner", "The restorer", "The artist", "A random visitor"], "correct_index": 1, "explanation": "Ela começou pelo restaurador, o suspeito menos óbvio."}, {"question": "What did the ultraviolet light reveal?", "options": ["A hidden painting underneath", "Fingerprints", "That the signature's ink was newer than the paint", "Nothing unusual"], "correct_index": 2, "explanation": "A tinta da assinatura era mais nova que a tinta ao redor."}, {"question": "Why did the restorer add the signature?", "options": ["He wanted fame", "He made a mistake", "He was the real artist", "The gallery owner pressured him to inflate the price"], "correct_index": 3, "explanation": "O dono da galeria o pressionou para aumentar o valor de revenda."}, {"question": "What lesson does Alves draw at the end of the story?", "options": ["Small overlooked details usually expose forgers", "Forgers are always caught quickly", "Paintings should never be restored", "Insurance companies are always wrong"], "correct_index": 0, "explanation": "Ela reflete que o menor detalhe costuma denunciar o falsificador."}], "open_questions": [{"question": "What details in the story hinted that the restorer was involved before he confessed?", "key_points_pt": ["mencionar as mãos trêmulas e outros sinais sutis", "explicar como esses sinais levaram à suspeita"]}, {"question": "Do you think the gallery owner deserves a harsher punishment than the restorer? Why?", "key_points_pt": ["dar opinião justificada", "considerar quem pressionou quem no esquema"]}]}}, {"level": "C1", "genre": "romance", "title": "Two Left Shoes", "paragraphs": ["Luiza had sworn off blind dates after a string of awkward dinners, yet she found herself, against her better judgment, agreeing to meet a friend of a friend at a dance studio downtown. She arrived ten minutes early, only to discover that she had grabbed two left shoes in her rush out the door, a mismatch that left her hobbling comically across the polished floor.", "Thiago, the man she was supposed to meet, spotted her struggling and offered, without a trace of mockery, to swap one of his own shoes for hers. It was an absurd sight, the two of them dancing a clumsy tango in mismatched pairs, but the laughter it provoked dissolved whatever awkwardness might otherwise have hung over their first conversation.", "Over the following weeks, they kept finding excuses to see each other again, each date more effortless than the last, as though the initial shoe mishap had somehow granted them permission to be unguarded with one another. Luiza, who had always approached romance with a certain wary detachment, was startled to notice how readily she looked forward to his messages.", "A year later, when Thiago proposed, he did so kneeling in the very same dance studio, holding up a single left shoe as a quiet joke only the two of them would understand. Luiza laughed until she cried, then said yes before he had even finished the question."], "paragraphs_pt": ["Luiza havia jurado nunca mais aceitar encontros às cegas depois de uma sequência de jantares constrangedores, mas se viu, contra o próprio bom senso, concordando em conhecer o amigo de uma amiga numa academia de dança no centro. Ela chegou dez minutos adiantada, só para descobrir que tinha pegado dois sapatos esquerdos na correria para sair de casa, um erro que a deixou mancando de forma cômica pelo piso encerado.", "Thiago, o homem que ela deveria encontrar, percebeu que ela estava tendo dificuldade e se ofereceu, sem nenhum sinal de deboche, para trocar um dos próprios sapatos pelo dela. Foi uma cena absurda, os dois dançando um tango desajeitado com pares trocados, mas a risada que isso provocou dissolveu qualquer constrangimento que pudesse pairar sobre a primeira conversa deles.", "Nas semanas seguintes, eles continuavam inventando desculpas para se ver de novo, cada encontro mais natural que o anterior, como se o incidente inicial dos sapatos tivesse de alguma forma lhes dado permissão para serem despretensiosos um com o outro. Luiza, que sempre tinha encarado o romance com certo distanciamento cauteloso, ficou surpresa ao perceber com que facilidade passou a esperar pelas mensagens dele.", "Um ano depois, quando Thiago pediu-a em casamento, ele o fez ajoelhado naquela mesma academia de dança, segurando um único sapato esquerdo como uma piada silenciosa que só os dois entenderiam. Luiza riu até chorar, e disse sim antes mesmo de ele terminar a pergunta."], "hard_words": ["sworn off", "hobbling", "mismatch", "unguarded", "wary"], "vocab": [{"word": "against her better judgment", "meaning": "contra o próprio bom senso", "note": "expressão idiomática"}, {"word": "without a trace of mockery", "meaning": "sem nenhum sinal de deboche", "note": ""}, {"word": "hung over", "meaning": "pairado sobre (uma situação)", "note": "phrasal verb"}, {"word": "kept finding excuses", "meaning": "continuavam inventando desculpas", "note": ""}, {"word": "looked forward to", "meaning": "aguardar com expectativa", "note": "phrasal verb"}, {"word": "kneeling", "meaning": "ajoelhado", "note": ""}, {"word": "swap", "meaning": "trocar", "note": ""}], "word_meanings": [{"word": "sworn off", "meaning": "jurado abandonar/nunca mais fazer", "note": ""}, {"word": "hobbling", "meaning": "mancando", "note": ""}, {"word": "mismatch", "meaning": "combinação errada, par desencontrado", "note": ""}, {"word": "unguarded", "meaning": "desprevenido, sem defesas, espontâneo", "note": ""}, {"word": "wary", "meaning": "cauteloso, desconfiado", "note": ""}, {"word": "hung over", "meaning": "pairou sobre", "note": "phrasal verb"}, {"word": "looked forward to", "meaning": "esperava ansiosamente por", "note": "phrasal verb"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/estava", "note": "to be"}, {"word": "were", "meaning": "eram/estavam", "note": "to be"}, {"word": "spotted", "meaning": "avistou", "note": "passado regular"}, {"word": "proposed", "meaning": "pediu em casamento", "note": "passado regular"}, {"word": "found", "meaning": "encontrou", "note": "passado irregular"}, {"word": "held", "meaning": "segurou", "note": "passado irregular"}, {"word": "kept", "meaning": "manteve/continuou", "note": "passado irregular"}, {"word": "said", "meaning": "disse", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["found", "spotted", "kept", "said"], "phrasal": ["hung over", "looked forward to"], "wh": [], "connectors": ["yet", "but", "as though", "so"], "comparative": ["more effortless", "the last"]}, "exercises": {"grammar": [{"point": "Comparativos progressivos", "explanation_pt": "A frase 'each date more effortless than the last' mostra uma comparação progressiva entre os encontros."}, {"point": "'As though' + passado", "explanation_pt": "Usamos 'as though' com verbo no passado para expressar uma situação hipotética: 'as though the initial shoe mishap had somehow granted them permission'."}], "multiple_choice": [{"question": "Why was Luiza hobbling at the dance studio?", "options": ["She was wearing two left shoes", "She hurt her foot", "Her shoes were too tight", "She had never danced before"], "correct_index": 0, "explanation": "Ela pegou dois sapatos esquerdos sem perceber."}, {"question": "How did Thiago react to Luiza's shoe problem?", "options": ["He laughed at her", "He offered to swap one of his shoes", "He left immediately", "He ignored it"], "correct_index": 1, "explanation": "Ele se ofereceu para trocar um dos sapatos com ela."}, {"question": "How did Luiza usually approach romance before meeting Thiago?", "options": ["Very enthusiastically", "She never dated", "With wary detachment", "She always fell in love quickly"], "correct_index": 2, "explanation": "Ela costumava ser cautelosa e reservada com relacionamentos."}, {"question": "Where did Thiago propose to Luiza?", "options": ["At a restaurant", "At her house", "On a trip", "At the dance studio"], "correct_index": 3, "explanation": "Ele pediu-a em casamento na mesma academia de dança."}, {"question": "What object did Thiago hold up during the proposal?", "options": ["A single left shoe", "A ring box", "A photograph", "Dance shoes for both"], "correct_index": 0, "explanation": "Ele segurou um único sapato esquerdo como piada."}], "open_questions": [{"question": "How did the awkward beginning of the story end up bringing Luiza and Thiago closer together?", "key_points_pt": ["explicar como o erro dos sapatos gerou risada e conexão", "relacionar com a ideia de vulnerabilidade compartilhada"]}, {"question": "Do you believe small, embarrassing moments can sometimes strengthen a relationship? Why?", "key_points_pt": ["dar opinião pessoal", "usar o exemplo da história ou experiência própria"]}]}}, {"level": "C1", "genre": "scifi", "title": "The Memory Archivist", "paragraphs": ["In the year 2184, Dr. Yuki Tanaka's job was to preserve dying languages by digitizing the memories of their last living speakers, a process that involved threading a neural filament through the subject's temporal lobe while a quantum archive recorded every association a word carried. Most sessions were routine, but the one scheduled with a hundred-and-twelve-year-old man named Elias, the final fluent speaker of a nearly extinct dialect, felt different from the moment he sat down.", "As the filament activated, Yuki expected to retrieve tidy definitions, yet what flooded the archive instead were entire scenes: a childhood kitchen thick with the smell of bread, an argument between parents that had shaped how the boy later spoke of anger, a wedding song sung slightly off-key. She realized, with a jolt of unease, that a language could not be separated from the life that had spoken it, no matter how sophisticated the recording technology became.", "Midway through the extraction, the archive's stabilizers flickered, warning that Elias's neural patterns were destabilizing under the strain; continuing risked erasing the very memories she was meant to save. Yuki faced an impossible choice between completing the historic archive and protecting the fragile old man in front of her, and after a long, agonizing pause, she withdrew the filament, letting the recording remain forever incomplete.", "The institute reprimanded her for abandoning a project decades in the making, but Elias, breathing easier once the device was removed, thanked her quietly for choosing him over the archive. Yuki never regretted the decision; she had learned, in that single afternoon, that some knowledge was never meant to survive its keeper, and that preserving a voice sometimes meant knowing when to let it rest."], "paragraphs_pt": ["No ano de 2184, o trabalho da Dra. Yuki Tanaka era preservar línguas moribundas digitalizando as memórias de seus últimos falantes vivos, um processo que envolvia inserir um filamento neural pelo lobo temporal do sujeito enquanto um arquivo quântico registrava cada associação carregada por uma palavra. A maioria das sessões era rotineira, mas a que estava marcada com um homem de cento e doze anos chamado Elias, o último falante fluente de um dialeto quase extinto, pareceu diferente desde o momento em que ele se sentou.", "Quando o filamento foi ativado, Yuki esperava recuperar definições organizadas, mas o que inundou o arquivo, em vez disso, foram cenas inteiras: uma cozinha de infância impregnada do cheiro de pão, uma discussão entre os pais que tinha moldado a forma como o menino mais tarde falava sobre raiva, uma canção de casamento cantada levemente desafinada. Ela percebeu, com um sobressalto de inquietação, que uma língua não podia ser separada da vida que a havia falado, por mais sofisticada que a tecnologia de gravação se tornasse.", "No meio da extração, os estabilizadores do arquivo oscilaram, avisando que os padrões neurais de Elias estavam se desestabilizando sob a tensão; continuar arriscava apagar justamente as memórias que ela deveria salvar. Yuki se viu diante de uma escolha impossível entre concluir o arquivo histórico e proteger o senhor frágil à sua frente, e depois de uma longa e angustiante pausa, ela retirou o filamento, deixando a gravação para sempre incompleta.", "O instituto a repreendeu por abandonar um projeto décadas em construção, mas Elias, respirando mais aliviado assim que o aparelho foi removido, agradeceu-lhe em voz baixa por tê-lo escolhido em vez do arquivo. Yuki nunca se arrependeu da decisão; ela tinha aprendido, naquela única tarde, que certos conhecimentos nunca deveriam sobreviver a quem os guardava, e que preservar uma voz às vezes significava saber a hora de deixá-la descansar."], "hard_words": ["filament", "temporal lobe", "flooded", "destabilizing", "reprimanded"], "vocab": [{"word": "dying languages", "meaning": "línguas em extinção", "note": ""}, {"word": "a jolt of unease", "meaning": "um sobressalto de inquietação", "note": ""}, {"word": "midway through", "meaning": "no meio de, na metade de", "note": ""}, {"word": "agonizing pause", "meaning": "pausa angustiante", "note": ""}, {"word": "breathing easier", "meaning": "respirando mais aliviado", "note": ""}, {"word": "let it rest", "meaning": "deixar descansar/em paz", "note": "expressão idiomática"}, {"word": "no matter how", "meaning": "não importa o quão", "note": ""}], "word_meanings": [{"word": "filament", "meaning": "filamento", "note": ""}, {"word": "temporal lobe", "meaning": "lobo temporal", "note": ""}, {"word": "flooded", "meaning": "inundou", "note": ""}, {"word": "destabilizing", "meaning": "se desestabilizando", "note": ""}, {"word": "reprimanded", "meaning": "repreendeu", "note": ""}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era", "note": "to be"}, {"word": "were", "meaning": "eram/estavam", "note": "to be"}, {"word": "withdrew", "meaning": "retirou", "note": "passado irregular"}, {"word": "learned", "meaning": "aprendeu", "note": "passado regular"}, {"word": "faced", "meaning": "enfrentou/se deparou com", "note": "passado regular"}, {"word": "felt", "meaning": "sentiu", "note": "passado irregular"}, {"word": "sat", "meaning": "sentou", "note": "passado irregular"}, {"word": "thanked", "meaning": "agradeceu", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["withdrew", "faced", "learned", "sat", "felt", "thanked"], "phrasal": [], "wh": [], "connectors": ["yet", "but", "no matter how", "and"], "comparative": ["easier"]}, "exercises": {"grammar": [{"point": "Cláusulas concessivas com 'no matter how'", "explanation_pt": "'no matter how sophisticated the recording technology became' expressa que, mesmo com tecnologia avançada, o resultado não mudava."}, {"point": "Passivo com 'was meant to'", "explanation_pt": "'the very memories she was meant to save' indica o propósito original da ação, usando a construção passiva 'be meant to'."}], "multiple_choice": [{"question": "What was Dr. Yuki Tanaka's profession?", "options": ["An archivist who preserves dying languages", "A neurosurgeon", "A historian", "A translator"], "correct_index": 0, "explanation": "Ela preservava línguas moribundas digitalizando memórias."}, {"question": "What surprised Yuki about the recorded memories?", "options": ["They were empty", "They included whole life scenes, not just definitions", "They were in the wrong language", "They were corrupted"], "correct_index": 1, "explanation": "Vieram cenas inteiras de vida, não apenas definições."}, {"question": "What warning appeared during the extraction?", "options": ["The archive was full", "The filament broke", "Elias's neural patterns were destabilizing", "The power failed"], "correct_index": 2, "explanation": "Os padrões neurais de Elias estavam se desestabilizando."}, {"question": "What did Yuki decide to do?", "options": ["Continue despite the risk", "Call for backup", "Restart the process", "Withdraw the filament and leave the recording incomplete"], "correct_index": 3, "explanation": "Ela retirou o filamento para proteger Elias."}, {"question": "How did the institute react to her decision?", "options": ["They reprimanded her", "They praised her", "They fired her", "They ignored it"], "correct_index": 0, "explanation": "O instituto a repreendeu por abandonar o projeto."}], "open_questions": [{"question": "Do you agree with Yuki's choice to prioritize Elias's well-being over the archive? Why?", "key_points_pt": ["dar opinião justificada", "considerar o dilema ético entre ciência e cuidado humano"]}, {"question": "What does this story suggest about the relationship between language and personal memory?", "key_points_pt": ["mencionar que a língua carrega experiências pessoais, não só palavras", "citar exemplos do texto"]}]}}, {"level": "C1", "genre": "fantasy", "title": "The Weight of the Crown", "paragraphs": ["When Princess Iselda's father died without a male heir, the council reluctantly crowned her, though many nobles muttered that the enchanted crown itself would reject her, since legend held that it recognized only the truest ruler's blood. To everyone's astonishment, the crown settled on her brow without so much as a flicker, yet within days she began hearing faint whispers whenever she wore it, as though the crown itself were alive and unwilling to stay silent.", "The whispers grew bolder, warning her of a famine brewing in the eastern provinces long before any messenger arrived with the news, and cautioning her against a treaty her advisors had urged her to sign, one that would have secretly ceded half the kingdom's mines to a rival lord. Iselda began to suspect that every monarch before her had heard these same warnings and had simply chosen, out of pride or fear, not to listen.", "Determined not to repeat their mistakes, she convened her council and revealed the crown's counsel openly, risking ridicule from nobles who already doubted a young queen's judgment. Several lords scoffed, insisting she was inventing voices to justify her own decisions, but when the famine struck precisely where the crown had predicted, their scorn curdled into uneasy respect.", "Years later, historians would debate whether the crown had truly been enchanted or whether Iselda had simply trusted her own instincts and attributed them to something greater than herself. Iselda never bothered to correct them; what mattered, she often said, was not where wisdom came from, but whether a ruler was humble enough to listen to it."], "paragraphs_pt": ["Quando o pai da princesa Iselda morreu sem deixar um herdeiro homem, o conselho a coroou a contragosto, embora muitos nobres murmurassem que a própria coroa encantada a rejeitaria, já que a lenda dizia que ela reconhecia apenas o sangue do verdadeiro governante. Para espanto de todos, a coroa se assentou em sua testa sem sequer vacilar, mas em poucos dias ela começou a ouvir sussurros fracos sempre que a usava, como se a própria coroa estivesse viva e não quisesse ficar em silêncio.", "Os sussurros ficaram mais ousados, avisando-a de uma fome que se formava nas províncias do leste muito antes de qualquer mensageiro chegar com a notícia, e alertando-a contra um tratado que seus conselheiros a pressionavam a assinar, um que teria cedido secretamente metade das minas do reino a um senhor rival. Iselda começou a suspeitar que todos os monarcas antes dela tinham ouvido esses mesmos avisos e simplesmente escolhido, por orgulho ou medo, não escutá-los.", "Decidida a não repetir os erros deles, ela convocou o conselho e revelou abertamente os conselhos da coroa, arriscando o ridículo de nobres que já duvidavam do julgamento de uma rainha jovem. Vários senhores zombaram, insistindo que ela inventava vozes para justificar as próprias decisões, mas quando a fome atingiu exatamente onde a coroa tinha previsto, o escárnio deles se transformou em um respeito incômodo.", "Anos depois, historiadores debateriam se a coroa realmente fora encantada ou se Iselda simplesmente confiara nos próprios instintos e os atribuíra a algo maior do que ela mesma. Iselda nunca se importou em corrigi-los; o que importava, ela costumava dizer, não era de onde vinha a sabedoria, mas se um governante era humilde o bastante para escutá-la."], "hard_words": ["muttered", "brow", "ceded", "scoffed", "curdled"], "vocab": [{"word": "without so much as a flicker", "meaning": "sem sequer vacilar", "note": "expressão idiomática"}, {"word": "brewing", "meaning": "se formando/gestando", "note": ""}, {"word": "convened her council", "meaning": "convocou o conselho", "note": ""}, {"word": "scorn", "meaning": "desprezo", "note": ""}, {"word": "uneasy respect", "meaning": "respeito incômodo", "note": ""}, {"word": "bothered to", "meaning": "se importou/deu-se ao trabalho de", "note": ""}, {"word": "humble", "meaning": "humilde", "note": ""}], "word_meanings": [{"word": "muttered", "meaning": "murmuraram", "note": ""}, {"word": "brow", "meaning": "testa", "note": ""}, {"word": "ceded", "meaning": "cedido", "note": ""}, {"word": "scoffed", "meaning": "zombaram", "note": ""}, {"word": "curdled", "meaning": "se transformou/azedou (fig.)", "note": ""}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram/estavam", "note": "to be"}, {"word": "began", "meaning": "começou", "note": "passado irregular"}, {"word": "struck", "meaning": "atingiu", "note": "passado irregular"}, {"word": "convened", "meaning": "convocou", "note": "passado regular"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular"}, {"word": "chose", "meaning": "escolheu", "note": "passado irregular"}, {"word": "grew", "meaning": "cresceu/ficou", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["began", "struck", "grew", "heard"], "phrasal": [], "wh": ["whether"], "connectors": ["though", "since", "yet", "but", "as though"], "comparative": ["bolder", "greater"]}, "exercises": {"grammar": [{"point": "'As though' + past subjunctive", "explanation_pt": "'as though the crown itself were alive' usa o passado subjuntivo para descrever uma situação irreal ou hipotética."}, {"point": "Discurso indireto com 'whether'", "explanation_pt": "'historians would debate whether the crown had truly been enchanted' introduz uma dúvida indireta usando 'whether'."}], "multiple_choice": [{"question": "Why were the nobles surprised when Iselda was crowned?", "options": ["They expected the crown to reject her", "She refused the crown", "She was too young", "The crown was stolen"], "correct_index": 0, "explanation": "A lenda dizia que a coroa reconheceria só o verdadeiro governante."}, {"question": "What did the crown's whispers warn Iselda about?", "options": ["A war", "A famine and a bad treaty", "A betrayal by her family", "Nothing important"], "correct_index": 1, "explanation": "Avisaram sobre uma fome e um tratado prejudicial."}, {"question": "How did the nobles initially react when Iselda revealed the crown's warnings?", "options": ["They believed her immediately", "They exiled her", "They scoffed at her", "They crowned someone else"], "correct_index": 2, "explanation": "Vários nobres zombaram, achando que ela inventava."}, {"question": "What changed the nobles' attitude toward Iselda?", "options": ["A royal decree", "A war victory", "Her marriage", "The famine happening exactly as predicted"], "correct_index": 3, "explanation": "A fome ocorreu exatamente onde a coroa previra."}, {"question": "What did Iselda believe mattered most about wisdom?", "options": ["Whether a ruler was humble enough to listen to it", "Its magical origin", "How old the ruler was", "How powerful the ruler was"], "correct_index": 0, "explanation": "Ela dizia que importava a humildade de escutar, não a origem da sabedoria."}], "open_questions": [{"question": "Do you think the crown was truly magical, or was Iselda simply trusting her own instincts? Explain your view.", "key_points_pt": ["discutir a ambiguidade proposital da história", "justificar com base no texto"]}, {"question": "What does this story suggest about leadership and the willingness to listen to advice?", "key_points_pt": ["mencionar a diferença entre orgulho e humildade nos governantes anteriores e Iselda", "conectar com exemplos de liderança reais ou fictícios"]}]}}, {"level": "C1", "genre": "dystopia", "title": "The Silence Quota", "paragraphs": ["In the district of Meridian, every citizen was allotted exactly two hundred words of unmonitored speech per day; anything beyond the quota was flagged, transcribed, and reviewed by the Ministry of Cohesion, whose official mandate was to prevent the kind of unchecked rhetoric that had, decades earlier, plunged the region into civil unrest. Nadia had learned, like everyone else, to ration her sentences carefully, saving her quota for what genuinely mattered and communicating the rest through gestures, half-smiles, and silences that the monitors could not quantify.", "Her grandmother, who remembered the years before the quota system, used to say that the government had not so much silenced dissent as trained people to silence themselves, since fear of exceeding the limit made citizens second-guess even harmless remarks. Nadia dismissed this at first as nostalgic exaggeration, until she noticed how rarely she now finished an argument or asked a difficult question, having grown accustomed to abandoning sentences the instant they threatened to run long.", "The turning point came when her closest friend was detained for three days after a routine audit revealed she had been lending unused portions of her quota to neighbors through an illegal word-sharing network, a practice the Ministry classified as unauthorized speech redistribution. Watching her friend released, shaken and reluctant to speak even within her own allotted limit, Nadia finally understood what her grandmother had meant: the quota's true purpose was never merely to prevent unrest, but to make people forget how to trust their own voices.", "Quietly, deliberately, Nadia began spending her entire quota each day on one uncomfortable truth after another, small acts of resistance too minor to prosecute yet too consistent to ignore. She had no illusions that her words alone would dismantle the system, but she had decided, at last, that silence bought at the cost of her own convictions was a currency she was no longer willing to spend."], "paragraphs_pt": ["No distrito de Meridian, cada cidadão recebia exatamente duzentas palavras de fala não monitorada por dia; qualquer coisa além da cota era sinalizada, transcrita e revisada pelo Ministério da Coesão, cujo mandato oficial era prevenir o tipo de retórica descontrolada que, décadas antes, havia mergulhado a região em uma revolta civil. Nadia tinha aprendido, como todo mundo, a racionar as frases com cuidado, guardando a cota para o que realmente importava e comunicando o resto por gestos, meios-sorrisos e silêncios que os monitores não conseguiam quantificar.", "A avó dela, que se lembrava dos anos antes do sistema de cotas, costumava dizer que o governo não tinha exatamente silenciado a dissidência, mas treinado as pessoas a se silenciarem sozinhas, já que o medo de ultrapassar o limite fazia os cidadãos questionarem até os comentários mais inofensivos. Nadia descartou isso a princípio como exagero nostálgico, até perceber com que raridade agora terminava um argumento ou fazia uma pergunta difícil, tendo se acostumado a abandonar frases no instante em que ameaçavam se alongar.", "O ponto de virada veio quando sua amiga mais próxima foi detida por três dias depois que uma auditoria de rotina revelou que ela vinha emprestando porções não usadas da própria cota a vizinhos por meio de uma rede ilegal de compartilhamento de palavras, uma prática que o Ministério classificava como redistribuição não autorizada de fala. Ao ver a amiga ser solta, abalada e relutante em falar até mesmo dentro do próprio limite permitido, Nadia finalmente entendeu o que a avó quisera dizer: o verdadeiro propósito da cota nunca fora apenas prevenir revoltas, mas fazer as pessoas esquecerem como confiar na própria voz.", "Silenciosa e deliberadamente, Nadia começou a gastar toda a cota diária dizendo uma verdade incômoda atrás da outra, pequenos atos de resistência demais insignificantes para serem processados, mas consistentes demais para serem ignorados. Ela não tinha ilusões de que suas palavras sozinhas desmantelariam o sistema, mas tinha decidido, finalmente, que o silêncio comprado às custas das próprias convicções era uma moeda que ela não estava mais disposta a gastar."], "hard_words": ["allotted", "quota", "rhetoric", "ration", "dismantle"], "vocab": [{"word": "unmonitored speech", "meaning": "fala não monitorada", "note": ""}, {"word": "second-guess", "meaning": "questionar/duvidar de si mesmo", "note": ""}, {"word": "turning point", "meaning": "ponto de virada", "note": ""}, {"word": "grown accustomed to", "meaning": "se acostumado a", "note": ""}, {"word": "no illusions", "meaning": "sem ilusões", "note": ""}, {"word": "at the cost of", "meaning": "às custas de", "note": ""}, {"word": "willing to", "meaning": "disposto(a) a", "note": ""}], "word_meanings": [{"word": "allotted", "meaning": "concedida/atribuída (cota)", "note": ""}, {"word": "quota", "meaning": "cota", "note": ""}, {"word": "rhetoric", "meaning": "retórica", "note": ""}, {"word": "ration", "meaning": "racionar", "note": ""}, {"word": "dismantle", "meaning": "desmantelar", "note": ""}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram", "note": "to be"}, {"word": "began", "meaning": "começou", "note": "passado irregular"}, {"word": "understood", "meaning": "entendeu", "note": "passado irregular"}, {"word": "dismissed", "meaning": "descartou", "note": "passado regular"}, {"word": "had", "meaning": "tinha/teve", "note": "passado irregular"}, {"word": "came", "meaning": "veio", "note": "passado irregular"}, {"word": "grew", "meaning": "cresceu/ficou", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["began", "understood", "came", "had"], "phrasal": [], "wh": [], "connectors": ["since", "but", "yet", "until", "so"], "comparative": []}, "exercises": {"grammar": [{"point": "Not so much... but", "explanation_pt": "'the government had not so much silenced dissent as trained people to silence themselves' compara duas ideias, destacando a segunda como a mais precisa."}, {"point": "Gerúndio após preposição", "explanation_pt": "'the instant they threatened to run long' e 'a currency she was no longer willing to spend' mostram estruturas com infinitivo/gerúndio típicas do nível C1."}], "multiple_choice": [{"question": "What was the daily word quota in Meridian?", "options": ["Two hundred words", "One hundred words", "Five hundred words", "There was no limit"], "correct_index": 0, "explanation": "Cada cidadão tinha duzentas palavras de fala não monitorada por dia."}, {"question": "According to Nadia's grandmother, what was the quota's real effect?", "options": ["It improved communication", "It trained people to silence themselves", "It had no effect", "It increased civil unrest"], "correct_index": 1, "explanation": "O sistema treinava as pessoas a se autocensurarem."}, {"question": "Why was Nadia's friend detained?", "options": ["She insulted the Ministry", "She exceeded her quota once", "She shared her unused quota with neighbors", "She refused to speak"], "correct_index": 2, "explanation": "Ela compartilhava a cota não usada por meio de uma rede ilegal."}, {"question": "What did Nadia decide to do after her friend's detention?", "options": ["Stop speaking entirely", "Leave the district", "Report her grandmother", "Spend her whole quota on uncomfortable truths"], "correct_index": 3, "explanation": "Ela passou a gastar toda a cota dizendo verdades incômodas."}, {"question": "What did Nadia conclude was the quota system's true purpose?", "options": ["To make people forget how to trust their own voices", "To save resources", "To improve education", "To reward loyal citizens"], "correct_index": 0, "explanation": "Ela concluiu que o objetivo era fazer as pessoas desconfiarem da própria voz."}], "open_questions": [{"question": "What parallels, if any, do you see between the word quota and forms of self-censorship in the real world?", "key_points_pt": ["discutir autocensura, redes sociais ou vigilância", "relacionar com o sistema descrito na história"]}, {"question": "Do you think Nadia's small act of resistance can make a real difference? Why or why not?", "key_points_pt": ["dar opinião justificada", "considerar o poder de pequenos atos coletivos"]}]}}, {"level": "C1", "genre": "postapoc", "title": "Seeds in the Ash", "paragraphs": ["Ten years after the ash clouds had blotted out the sun for what survivors still called the Grey Winter, Coren led scavenging parties through the ruined outskirts of what had once been a thriving agricultural valley, searching not for food or fuel but for something far rarer: uncontaminated seeds. Most of the old seed banks had been looted or destroyed in the chaotic years immediately following the collapse, and the settlement's soil, though slowly recovering, remained too depleted to sustain anything beyond the hardiest weeds.", "On the seventh day of an expedition that had yielded little but disappointment, Coren's team stumbled upon a collapsed farmhouse whose cellar, sealed by fallen beams, had somehow kept its contents dry and undisturbed. Inside, wrapped in wax paper that had brittled with age but not crumbled, lay dozens of carefully labeled envelopes, a farmer's private collection preserved by nothing more than sheer, improbable luck.", "Word of the discovery spread through the settlement faster than Coren could organize a proper inventory, and within days, arguments broke out over who deserved priority access to the seeds, some insisting they belonged to whoever had the strongest claim to farming experience, others arguing they should be rationed equally regardless of skill. Coren, exhausted by the infighting, finally proposed a compromise that satisfied almost no one entirely: a communal plot, tended collectively, whose harvest would belong to the settlement as a whole rather than to any single family.", "The first tomatoes ripened months later, small and imperfect, yet undeniably real, and the settlement gathered to share them in portions barely larger than a mouthful each. Coren, watching children taste an actual vegetable for the first time in their short lives, understood that the true harvest was not the fruit itself but the fragile, hard-won agreement that had made growing it possible at all."], "paragraphs_pt": ["Dez anos depois de as nuvens de cinzas terem obscurecido o sol naquilo que os sobreviventes ainda chamavam de Inverno Cinzento, Coren liderava grupos de busca pelos arredores arruinados do que fora outrora um vale agrícola próspero, procurando não por comida ou combustível, mas por algo bem mais raro: sementes não contaminadas. A maioria dos antigos bancos de sementes tinha sido saqueada ou destruída nos caóticos anos imediatamente após o colapso, e o solo do assentamento, embora se recuperando lentamente, ainda estava esgotado demais para sustentar qualquer coisa além das ervas daninhas mais resistentes.", "No sétimo dia de uma expedição que tinha rendido pouco além de decepção, a equipe de Coren deu de cara com uma casa de fazenda desmoronada cujo porão, lacrado por vigas caídas, de alguma forma tinha mantido o conteúdo seco e intocado. Dentro, embrulhados em papel encerado que tinha ficado quebradiço com o tempo mas não se esfarelara, havia dezenas de envelopes cuidadosamente etiquetados, a coleção particular de um fazendeiro preservada por nada além de pura e improvável sorte.", "A notícia da descoberta se espalhou pelo assentamento mais rápido do que Coren conseguia organizar um inventário adequado, e em poucos dias surgiram discussões sobre quem merecia acesso prioritário às sementes, alguns insistindo que elas pertenciam a quem tivesse a experiência agrícola mais sólida, outros argumentando que deveriam ser racionadas igualmente, independentemente da habilidade. Coren, esgotado pelas brigas internas, finalmente propôs um meio-termo que não satisfez ninguém completamente: um terreno comunitário, cultivado coletivamente, cuja colheita pertenceria ao assentamento como um todo, e não a nenhuma família isoladamente.", "Os primeiros tomates amadureceram meses depois, pequenos e imperfeitos, mas inegavelmente reais, e o assentamento se reuniu para compartilhá-los em porções mal maiores que uma bocada cada. Coren, observando crianças provarem um vegetal de verdade pela primeira vez em suas curtas vidas, entendeu que a verdadeira colheita não era o fruto em si, mas o acordo frágil e duramente conquistado que tinha tornado o cultivo possível."], "hard_words": ["blotted out", "depleted", "brittled", "crumbled", "infighting"], "vocab": [{"word": "scavenging parties", "meaning": "grupos de busca/catação", "note": ""}, {"word": "stumbled upon", "meaning": "deu de cara com, encontrou por acaso", "note": "phrasal verb"}, {"word": "sheer luck", "meaning": "pura sorte", "note": ""}, {"word": "broke out", "meaning": "estourou/começou (conflito)", "note": "phrasal verb"}, {"word": "regardless of", "meaning": "independentemente de", "note": ""}, {"word": "hard-won", "meaning": "duramente conquistado", "note": ""}, {"word": "a mouthful", "meaning": "uma bocada", "note": ""}], "word_meanings": [{"word": "blotted out", "meaning": "obscureceram/encobriram", "note": "phrasal verb"}, {"word": "depleted", "meaning": "esgotado", "note": ""}, {"word": "brittled", "meaning": "ficou quebradiço", "note": ""}, {"word": "crumbled", "meaning": "se esfarelou", "note": ""}, {"word": "infighting", "meaning": "brigas internas", "note": ""}, {"word": "stumbled upon", "meaning": "encontrou por acaso", "note": "phrasal verb"}, {"word": "broke out", "meaning": "estourou", "note": "phrasal verb"}, {"word": "realize", "meaning": "perceber (não 'realizar')", "note": "falso cognato"}, {"word": "actual", "meaning": "real/verdadeiro (não 'atual')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram", "note": "to be"}, {"word": "led", "meaning": "liderou", "note": "passado irregular"}, {"word": "understood", "meaning": "entendeu", "note": "passado irregular"}, {"word": "grew", "meaning": "cresceu/ficou", "note": "passado irregular"}, {"word": "lay", "meaning": "estava deitado(a)", "note": "passado irregular"}, {"word": "spread", "meaning": "se espalhou", "note": "passado irregular"}], "grammar_words": {"cognates": ["actual"], "tobe": ["was"], "irregular": ["led", "understood", "spread", "lay"], "phrasal": ["stumbled upon", "broke out"], "wh": ["who"], "connectors": ["though", "yet", "and", "rather than"], "comparative": ["rarer", "faster", "larger"]}, "exercises": {"grammar": [{"point": "'Not X but Y'", "explanation_pt": "'searching not for food or fuel but for something far rarer' contrasta duas ideias, dando ênfase à segunda opção."}, {"point": "Comparativo com 'far'", "explanation_pt": "'far rarer' intensifica o comparativo, indicando uma diferença grande entre as opções comparadas."}], "multiple_choice": [{"question": "What was Coren searching for during the expeditions?", "options": ["Uncontaminated seeds", "Fuel", "Weapons", "Survivors"], "correct_index": 0, "explanation": "Ele procurava sementes não contaminadas."}, {"question": "Where did the team find the preserved seeds?", "options": ["In an underground bunker", "In a collapsed farmhouse's cellar", "In an abandoned store", "Buried in the ash"], "correct_index": 1, "explanation": "Encontraram no porão de uma casa de fazenda desmoronada."}, {"question": "What caused arguments in the settlement after the discovery?", "options": ["Who should lead the expedition", "Where to store the seeds", "Who deserved priority access to the seeds", "Whether the seeds were real"], "correct_index": 2, "explanation": "Discutiram sobre quem merecia acesso prioritário às sementes."}, {"question": "What compromise did Coren propose?", "options": ["Selling the seeds", "Giving all seeds to the most experienced farmer", "Destroying the extra seeds", "A communal plot with shared harvest"], "correct_index": 3, "explanation": "Ele propôs um terreno comunitário com colheita compartilhada."}, {"question": "What did Coren realize while watching children eat the tomatoes?", "options": ["The true harvest was the agreement that made it possible", "The harvest was too small", "Farming was too difficult", "The seeds should be sold"], "correct_index": 0, "explanation": "Ele entendeu que o verdadeiro valor era o acordo coletivo, não só o fruto."}], "open_questions": [{"question": "Why do you think Coren's compromise satisfied 'almost no one entirely,' yet still worked?", "key_points_pt": ["discutir a ideia de meio-termo em situações de escassez", "relacionar com cooperação versus interesse individual"]}, {"question": "In a post-apocalyptic scenario, how might scarce resources be fairly distributed? Give your own idea.", "key_points_pt": ["propor um critério de distribuição justo", "justificar com base em equidade ou necessidade"]}]}}, {"level": "C1", "genre": "spy", "title": "The Cellist's Signal", "paragraphs": ["For six months, Ivana had posed as a visiting cellist with the national orchestra, a cover meticulously constructed to grant her access to a diplomat suspected of funneling classified shipping routes to a rival intelligence service. Her tradecraft depended on a single, unglamorous ritual: after each rehearsal, she left her instrument case in a specific corner of the green room, its clasps arranged in a pattern that signaled, to anyone trained to notice, whether a meeting was safe to proceed.", "The diplomat, a courteous man who lingered after concerts to discuss Brahms with an enthusiasm Ivana suspected was genuine, had no idea that their conversations about tempo and phrasing were, for her, an elaborate exercise in extracting fragments of information he let slip without realizing it. She found herself, uncomfortably, growing fond of him, a complication her handler had warned her about but that she had dismissed as a risk reserved for less disciplined agents.", "Everything unraveled the night her case's clasps were discovered rearranged by someone other than herself, a silent warning that her cover had been compromised and that continuing the operation would place her, and possibly the diplomat, in immediate danger. Rather than fleeing immediately, as protocol demanded, Ivana lingered long enough to leave him an anonymous note hidden inside his music stand, a small act of mercy that violated every rule she had been trained to follow.", "She was extracted within the hour, bundled onto a cargo plane before dawn, and never learned whether the diplomat had heeded her warning or dismissed it as an admirer's strange gesture. Years later, reading a brief intelligence report noting that he had quietly defected and requested asylum, Ivana allowed herself, for the first time since the operation, a small and complicated satisfaction."], "paragraphs_pt": ["Por seis meses, Ivana se passou por uma violoncelista visitante da orquestra nacional, uma fachada meticulosamente construída para lhe dar acesso a um diplomata suspeito de repassar rotas marítimas classificadas a um serviço de inteligência rival. Sua técnica de espionagem dependia de um único e nada glamouroso ritual: depois de cada ensaio, ela deixava o estojo do instrumento num canto específico da sala verde, com os fechos arranjados num padrão que sinalizava, para quem estivesse treinado a notar, se um encontro era seguro para prosseguir.", "O diplomata, um homem cortês que ficava depois dos concertos para discutir Brahms com um entusiasmo que Ivana suspeitava ser genuíno, não fazia ideia de que as conversas sobre andamento e fraseado eram, para ela, um exercício elaborado de extrair fragmentos de informação que ele deixava escapar sem perceber. Ela se percebeu, desconfortavelmente, se afeiçoando a ele, uma complicação sobre a qual sua superiora a tinha alertado, mas que ela havia descartado como um risco reservado a agentes menos disciplinados.", "Tudo desmoronou na noite em que os fechos do estojo foram encontrados rearranjados por alguém que não ela mesma, um aviso silencioso de que sua fachada tinha sido comprometida e que continuar a operação a colocaria, e possivelmente ao diplomata, em perigo imediato. Em vez de fugir imediatamente, como o protocolo exigia, Ivana demorou o suficiente para deixar-lhe um bilhete anônimo escondido dentro da estante de partituras dele, um pequeno ato de misericórdia que violava toda regra que ela tinha sido treinada a seguir.", "Ela foi extraída em menos de uma hora, colocada às pressas num avião de carga antes do amanhecer, e nunca soube se o diplomata tinha atendido ao aviso dela ou o descartado como um gesto estranho de uma admiradora. Anos depois, lendo um breve relatório de inteligência que mencionava que ele desertara discretamente e pedira asilo, Ivana permitiu-se, pela primeira vez desde a operação, uma satisfação pequena e complicada."], "hard_words": ["funneling", "clasps", "unraveled", "heeded", "defected"], "vocab": [{"word": "cover", "meaning": "fachada/disfarce (espionagem)", "note": ""}, {"word": "let slip", "meaning": "deixar escapar (informação)", "note": "expressão idiomática"}, {"word": "growing fond of", "meaning": "se afeiçoando a", "note": ""}, {"word": "compromised", "meaning": "comprometida", "note": ""}, {"word": "act of mercy", "meaning": "ato de misericórdia", "note": ""}, {"word": "extracted", "meaning": "retirada/resgatada (operação)", "note": ""}, {"word": "asylum", "meaning": "asilo", "note": ""}], "word_meanings": [{"word": "funneling", "meaning": "repassando/canalizando", "note": ""}, {"word": "clasps", "meaning": "fechos", "note": ""}, {"word": "unraveled", "meaning": "desmoronou/se desfez", "note": ""}, {"word": "heeded", "meaning": "atendeu/deu ouvidos a", "note": ""}, {"word": "defected", "meaning": "desertou", "note": ""}, {"word": "realizing", "meaning": "percebendo (não 'realizando')", "note": "falso cognato"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram/foram", "note": "to be"}, {"word": "left", "meaning": "deixou", "note": "passado irregular"}, {"word": "found", "meaning": "encontrou/percebeu", "note": "passado irregular"}, {"word": "lingered", "meaning": "demorou-se", "note": "passado regular"}, {"word": "let slip", "meaning": "deixou escapar", "note": "phrasal verb"}, {"word": "had", "meaning": "tinha/teve", "note": "passado irregular"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular"}, {"word": "grew", "meaning": "cresceu/ficou", "note": "passado irregular"}], "grammar_words": {"cognates": ["realizing"], "tobe": ["was", "were"], "irregular": ["left", "found", "had"], "phrasal": ["let slip"], "wh": ["whether"], "connectors": ["rather than", "but", "and", "since"], "comparative": ["less disciplined"]}, "exercises": {"grammar": [{"point": "Gerúndio após preposição", "explanation_pt": "'without realizing it' e 'growing fond of him' mostram o uso do gerúndio depois de preposições, comum em inglês avançado."}, {"point": "Discurso indireto com 'whether'", "explanation_pt": "'never learned whether the diplomat had heeded her warning' introduz uma incerteza usando 'whether' + past perfect."}], "multiple_choice": [{"question": "What was Ivana's cover identity?", "options": ["A visiting cellist", "A journalist", "A diplomat's assistant", "A music teacher"], "correct_index": 0, "explanation": "Ela se passava por uma violoncelista visitante."}, {"question": "How did Ivana signal whether a meeting was safe?", "options": ["A coded phone call", "The arrangement of her instrument case's clasps", "A specific song she played", "A note under a chair"], "correct_index": 1, "explanation": "O padrão dos fechos do estojo sinalizava a segurança do encontro."}, {"question": "What complication did Ivana's handler warn her about?", "options": ["Getting caught by police", "Losing her cello", "Growing fond of the diplomat", "Missing rehearsals"], "correct_index": 2, "explanation": "A superiora a alertou sobre o risco de se afeiçoar ao alvo."}, {"question": "What did Ivana do despite the danger, before being extracted?", "options": ["She confronted the diplomat directly", "She destroyed all evidence", "She called her handler", "She left him an anonymous warning note"], "correct_index": 3, "explanation": "Ela deixou um bilhete anônimo escondido na estante de partituras."}, {"question": "What did Ivana eventually learn about the diplomat?", "options": ["He quietly defected and requested asylum", "He was arrested", "He never found the note", "He continued working for the rival service"], "correct_index": 0, "explanation": "Anos depois, ela leu que ele desertara e pedira asilo."}], "open_questions": [{"question": "Why do you think Ivana risked breaking protocol to warn the diplomat?", "key_points_pt": ["discutir o conflito entre dever profissional e afeto pessoal", "citar a decisão dela de deixar o bilhete"]}, {"question": "Do you think spies can maintain emotional detachment from the people they investigate? Why or why not?", "key_points_pt": ["dar opinião pessoal", "relacionar com o exemplo de Ivana"]}]}}, {"level": "C1", "genre": "corporate", "title": "The Quiet Resignation", "paragraphs": ["When Renato was passed over for the regional director position for the third consecutive year, in favor of a candidate who had joined the firm eighteen months earlier, he did not storm into his manager's office or fire off an indignant email, as several colleagues privately expected. Instead, he spent a weekend drafting a resignation letter so measured and professional that his manager later admitted it made her far more uneasy than any outburst could have.", "The letter thanked the company for a decade of opportunities while noting, without a trace of bitterness, that promotion decisions had consistently rewarded visibility over substance, and that he no longer wished to compete in a system where self-promotion mattered more than results. Word of the letter circulated quietly through the office, and several colleagues confided that they had drafted similar letters themselves, though none had found the nerve to actually submit one.", "Senior leadership, alarmed at the prospect of losing someone whose departure might expose uncomfortable truths about the promotion process, offered Renato a counteroffer that included the very title he had been denied, along with a hastily arranged apology from the executive who had overlooked him. He turned it down politely, explaining that accepting would only validate the assumption that leaving, rather than merit, was what finally got people heard.", "Renato's departure prompted an internal review of the promotion criteria, a change he never witnessed firsthand since he had already moved to a competitor by the time the new policy was announced. He later joked, with the same restraint that had defined his resignation letter, that quitting gracefully had accomplished more for his former colleagues than years of diligent, uncomplaining work ever had."], "paragraphs_pt": ["Quando Renato foi preterido para o cargo de diretor regional pelo terceiro ano consecutivo, em favor de um candidato que tinha entrado na empresa apenas dezoito meses antes, ele não invadiu a sala da gerente nem disparou um e-mail indignado, como vários colegas esperavam em particular. Em vez disso, passou um fim de semana redigindo uma carta de demissão tão ponderada e profissional que sua gerente depois admitiu que isso a deixou muito mais incomodada do que qualquer explosão de raiva poderia ter deixado.", "A carta agradecia à empresa por uma década de oportunidades enquanto observava, sem nenhum traço de amargura, que as decisões de promoção tinham recompensado consistentemente a visibilidade em vez da substância, e que ele não desejava mais competir num sistema em que autopromoção importava mais do que resultados. A notícia da carta circulou discretamente pelo escritório, e vários colegas confidenciaram que também tinham redigido cartas parecidas, embora nenhum tivesse tido coragem de realmente entregá-las.", "A alta liderança, alarmada com a perspectiva de perder alguém cuja saída poderia expor verdades incômodas sobre o processo de promoção, ofereceu a Renato uma contraproposta que incluía exatamente o cargo que lhe tinha sido negado, junto com um pedido de desculpas apressado do executivo que o tinha ignorado. Ele recusou educadamente, explicando que aceitar apenas validaria a suposição de que sair, e não o mérito, era o que finalmente fazia as pessoas serem ouvidas.", "A saída de Renato provocou uma revisão interna dos critérios de promoção, uma mudança que ele nunca testemunhou pessoalmente, já que já tinha ido para um concorrente quando a nova política foi anunciada. Ele depois brincou, com a mesma contenção que tinha marcado sua carta de demissão, que sair com elegância tinha conseguido mais para seus antigos colegas do que anos de trabalho diligente e sem reclamações jamais haviam conseguido."], "hard_words": ["passed over", "outburst", "bitterness", "counteroffer", "restraint"], "vocab": [{"word": "passed over for", "meaning": "preterido para (um cargo)", "note": "expressão de trabalho"}, {"word": "storm into", "meaning": "invadir (com raiva)", "note": ""}, {"word": "fire off", "meaning": "disparar (um e-mail, com raiva)", "note": "phrasal verb"}, {"word": "found the nerve", "meaning": "teve coragem", "note": "expressão idiomática"}, {"word": "turned it down", "meaning": "recusou", "note": "phrasal verb"}, {"word": "firsthand", "meaning": "em primeira mão/pessoalmente", "note": ""}, {"word": "gracefully", "meaning": "com elegância", "note": ""}], "word_meanings": [{"word": "passed over", "meaning": "preterido", "note": ""}, {"word": "outburst", "meaning": "explosão (de raiva)", "note": ""}, {"word": "bitterness", "meaning": "amargura", "note": ""}, {"word": "counteroffer", "meaning": "contraproposta", "note": ""}, {"word": "restraint", "meaning": "contenção, comedimento", "note": ""}, {"word": "fire off", "meaning": "disparar", "note": "phrasal verb"}, {"word": "turned down", "meaning": "recusou", "note": "phrasal verb"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram", "note": "to be"}, {"word": "spent", "meaning": "passou (tempo)", "note": "passado irregular"}, {"word": "offered", "meaning": "ofereceu", "note": "passado regular"}, {"word": "had", "meaning": "tinha/teve", "note": "passado irregular"}, {"word": "took", "meaning": "levou/pegou", "note": "passado irregular"}], "grammar_words": {"cognates": ["actually"], "tobe": ["was"], "irregular": ["spent", "offered", "had"], "phrasal": ["fire off"], "wh": [], "connectors": ["instead", "though", "since", "rather than", "while"], "comparative": ["far more uneasy", "more than"]}, "exercises": {"grammar": [{"point": "Comparativos enfáticos com 'far'", "explanation_pt": "'far more uneasy than any outburst could have' usa 'far' para intensificar o comparativo, mostrando um contraste forte."}, {"point": "Cláusulas com 'rather than'", "explanation_pt": "'leaving, rather than merit, was what finally got people heard' contrasta duas causas possíveis usando 'rather than'."}], "multiple_choice": [{"question": "How many times was Renato passed over for the director position?", "options": ["Three times", "Once", "Twice", "Four times"], "correct_index": 0, "explanation": "Ele foi preterido pelo terceiro ano consecutivo."}, {"question": "How did Renato react to being passed over again?", "options": ["He shouted at his manager", "He wrote a calm, professional resignation letter", "He immediately quit without notice", "He complained publicly"], "correct_index": 1, "explanation": "Ele escreveu uma carta de demissão ponderada e profissional."}, {"question": "What did the resignation letter criticize?", "options": ["The company's salaries", "The office location", "The promotion system rewarding visibility over substance", "His manager's personality"], "correct_index": 2, "explanation": "A carta criticava um sistema que recompensava visibilidade em vez de substância."}, {"question": "Why did Renato refuse the counteroffer?", "options": ["The salary was too low", "He had already accepted another job", "He disliked the new title", "Accepting would validate that leaving mattered more than merit"], "correct_index": 3, "explanation": "Ele não queria validar a ideia de que sair era o que fazia as pessoas serem ouvidas."}, {"question": "What happened after Renato's departure?", "options": ["The promotion criteria were reviewed", "The company collapsed", "Nothing changed", "He was rehired immediately"], "correct_index": 0, "explanation": "A empresa fez uma revisão interna dos critérios de promoção."}], "open_questions": [{"question": "Do you think Renato's calm approach was more effective than an angry confrontation would have been? Why?", "key_points_pt": ["discutir a eficácia de uma saída educada versus uma reação impulsiva", "citar o impacto que a carta teve na empresa"]}, {"question": "Have you or someone you know ever left a job or situation on principle? What happened?", "key_points_pt": ["compartilhar exemplo pessoal ou hipotético", "relacionar com a decisão de Renato"]}]}}, {"level": "C1", "genre": "diary", "title": "March Entries", "paragraphs": ["March 3rd. I keep putting off writing about the diagnosis, as though avoiding the page might somehow delay the reality it describes, but tonight I finally forced myself to sit down and admit, at least to this notebook, that Mom's doctors are no longer speaking in terms of treatment but of comfort. I don't know how to hold both truths at once: that she seems entirely herself at dinner, cracking the same dry jokes she always has, and that the prognosis in the folder on the kitchen counter says otherwise.", "March 11th. Today she asked me, out of nowhere, whether I remembered the summer we got lost driving to the coast and ended up, three hours late, at a beach nobody else wanted because the tide pools smelled faintly of rotten eggs. I said of course I remembered, and she smiled in that way that made me suspect she was cataloguing memories on purpose now, handing them to me deliberately before she loses the chance.", "March 19th. I caught myself, for the first time, rehearsing what I might say at a funeral that hasn't happened yet, and I hated myself a little for it, as though preparing were a kind of betrayal, a way of giving up on her before she has given up on herself. And yet some pragmatic, exhausted part of me knows that grief postponed is still grief, and that I am only trying to spread mine out so it doesn't arrive all at once.", "March 27th. She had a good day today, good enough that we sat on the porch for an hour without either of us mentioning doctors or prognoses at all, just the weather and a neighbor's ridiculous new dog. I am learning, slowly and imperfectly, that loving someone through this means holding the ordinary and the unbearable in the same hand, and setting neither of them down."], "paragraphs_pt": ["3 de março. Continuo adiando escrever sobre o diagnóstico, como se evitar a página pudesse de algum modo atrasar a realidade que ela descreve, mas hoje à noite finalmente me obriguei a sentar e admitir, ao menos para este caderno, que os médicos da mamãe não falam mais em termos de tratamento, e sim de conforto. Não sei como segurar as duas verdades ao mesmo tempo: que ela parece completamente ela mesma no jantar, soltando as mesmas piadas secas de sempre, e que o prognóstico na pasta sobre a bancada da cozinha diz o contrário.", "11 de março. Hoje ela me perguntou, do nada, se eu me lembrava do verão em que nos perdemos indo para o litoral e acabamos, três horas atrasados, numa praia que ninguém mais queria porque as poças de maré tinham um leve cheiro de ovo podre. Eu disse que claro que lembrava, e ela sorriu daquele jeito que me fez desconfiar que estava catalogando memórias de propósito agora, entregando-as a mim deliberadamente antes de perder a chance.", "19 de março. Me peguei, pela primeira vez, ensaiando o que poderia dizer num funeral que ainda não aconteceu, e me odiei um pouco por isso, como se me preparar fosse uma espécie de traição, uma forma de desistir dela antes de ela desistir de si mesma. E, no entanto, alguma parte pragmática e exausta em mim sabe que luto adiado ainda é luto, e que só estou tentando espalhar o meu para que ele não chegue de uma vez só.", "27 de março. Ela teve um bom dia hoje, bom o suficiente para ficarmos sentadas na varanda por uma hora sem nenhuma de nós mencionar médicos ou prognósticos, só o tempo e o cachorro novo e ridículo de um vizinho. Estou aprendendo, devagar e de forma imperfeita, que amar alguém através disso significa segurar o comum e o insuportável na mesma mão, sem largar nenhum dos dois."], "hard_words": ["putting off", "prognosis", "cataloguing", "rehearsing", "unbearable"], "vocab": [{"word": "putting off", "meaning": "adiando", "note": "phrasal verb"}, {"word": "out of nowhere", "meaning": "do nada", "note": "expressão idiomática"}, {"word": "on purpose", "meaning": "de propósito", "note": ""}, {"word": "caught myself", "meaning": "me peguei (fazendo algo)", "note": ""}, {"word": "giving up on", "meaning": "desistir de", "note": "phrasal verb"}, {"word": "all at once", "meaning": "de uma vez só", "note": ""}, {"word": "setting neither down", "meaning": "sem largar nenhum dos dois", "note": ""}], "word_meanings": [{"word": "putting off", "meaning": "adiando", "note": "phrasal verb"}, {"word": "prognosis", "meaning": "prognóstico", "note": ""}, {"word": "cataloguing", "meaning": "catalogando", "note": ""}, {"word": "rehearsing", "meaning": "ensaiando", "note": ""}, {"word": "unbearable", "meaning": "insuportável", "note": ""}, {"word": "giving up on", "meaning": "desistindo de", "note": "phrasal verb"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/estava", "note": "to be"}, {"word": "were", "meaning": "eram/estavam", "note": "to be"}, {"word": "caught", "meaning": "pegou", "note": "passado irregular"}, {"word": "said", "meaning": "disse", "note": "passado irregular"}, {"word": "knew", "meaning": "sabia", "note": "passado irregular"}, {"word": "had", "meaning": "tinha/teve", "note": "passado irregular"}, {"word": "lose", "meaning": "perder", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["caught", "said", "had"], "phrasal": ["putting off", "giving up on"], "wh": ["whether"], "connectors": ["but", "as though", "and yet", "so", "because"], "comparative": ["good enough"]}, "exercises": {"grammar": [{"point": "'As though' com passado", "explanation_pt": "'as though avoiding the page might somehow delay the reality' expressa uma ideia hipotética ou irreal usando 'as though' + modal no passado."}, {"point": "Gerúndio como sujeito", "explanation_pt": "'Loving someone through this means holding the ordinary and the unbearable' usa o gerúndio ('loving', 'holding') como sujeito e complemento da frase."}], "multiple_choice": [{"question": "What difficult truth does the narrator admit on March 3rd?", "options": ["Mom's doctors are focusing on comfort, not treatment", "Mom is fully recovering", "Mom refuses to see doctors", "The narrator is also sick"], "correct_index": 0, "explanation": "Os médicos passaram a falar em conforto, não tratamento."}, {"question": "What memory does Mom bring up on March 11th?", "options": ["A wedding", "Getting lost driving to the coast", "A birthday party", "Moving to a new house"], "correct_index": 1, "explanation": "Ela lembra do dia em que se perderam indo para o litoral."}, {"question": "Why does the narrator feel guilty on March 19th?", "options": ["She forgot Mom's birthday", "She argued with Mom", "She caught herself rehearsing a funeral speech", "She missed a doctor's appointment"], "correct_index": 2, "explanation": "Ela se pegou ensaiando o que diria num funeral."}, {"question": "What happened on March 27th?", "options": ["Mom went to the hospital", "The narrator moved away", "Mom got worse", "They had a peaceful day without mentioning the illness"], "correct_index": 3, "explanation": "Elas tiveram um bom dia sem falar de médicos ou prognósticos."}, {"question": "What does the narrator learn about loving someone who is dying?", "options": ["It means holding both the ordinary and the unbearable together", "It means avoiding difficult topics entirely", "It means preparing only for the worst", "It means pretending everything is fine"], "correct_index": 0, "explanation": "Ela aprende a segurar o comum e o insuportável ao mesmo tempo."}], "open_questions": [{"question": "Why might writing in a diary help someone process a painful situation like this one?", "key_points_pt": ["discutir o papel da escrita como forma de processar emoções", "citar exemplos das entradas do diário"]}, {"question": "Do you think it is wrong to prepare emotionally for a loss before it happens? Why or why not?", "key_points_pt": ["dar opinião pessoal", "considerar a culpa da narradora e a ideia de luto antecipado"]}]}}, {"level": "C1", "genre": "news", "title": "City Council Reverses Course on Riverside Development", "paragraphs": ["The city council voted unanimously on Tuesday to withdraw approval for the long-contested Riverside Commons development, reversing a decision it had upheld as recently as February despite mounting opposition from environmental groups and residents of the adjacent Alameda neighborhood. The reversal follows the release of an independent hydrological survey indicating that the proposed twelve-story complex would have significantly worsened flood risk downstream, a finding the developer's own consultants had reportedly downplayed in earlier filings.", "Councilwoman Priya Deshmukh, who had cast the deciding vote in favor of the project last year, acknowledged during Tuesday's session that she had relied too heavily on assurances from the developer rather than commissioning an independent assessment sooner. \"We owe residents an apology for how long this took,\" she said, adding that the council would introduce stricter disclosure requirements for future large-scale developments near the floodplain.", "Representatives for Meridian Property Group, the firm behind the project, expressed disappointment with the decision but stopped short of confirming whether they would pursue legal action, noting only that they were \"reviewing all available options.\" Residents who had spent nearly two years organizing petitions and attending council meetings described the vote as long overdue, though several cautioned that similar developments elsewhere in the city still lack comparable scrutiny.", "The council has asked city planners to draft updated floodplain guidelines within ninety days, a timeline environmental advocates called ambitious but necessary given projections of increasingly severe seasonal flooding. For now, the Riverside Commons site remains undeveloped, its future uncertain, though residents say Tuesday's vote has at least restored some of their confidence that public concerns can still outweigh a well-funded developer's plans."], "paragraphs_pt": ["O conselho municipal votou por unanimidade na terça-feira para retirar a aprovação do contestado empreendimento Riverside Commons, revertendo uma decisão que havia mantido ainda em fevereiro apesar da crescente oposição de grupos ambientais e moradores do bairro vizinho de Alameda. A reversão vem após a divulgação de um estudo hidrológico independente indicando que o complexo proposto, de doze andares, teria piorado significativamente o risco de enchentes rio abaixo, uma constatação que os próprios consultores da construtora teriam minimizado em relatórios anteriores.", "A vereadora Priya Deshmukh, que havia dado o voto decisivo a favor do projeto no ano passado, reconheceu durante a sessão de terça-feira que havia confiado demais nas garantias da construtora em vez de encomendar uma avaliação independente mais cedo. \"Devemos um pedido de desculpas aos moradores pelo tempo que isso levou\", disse ela, acrescentando que o conselho introduziria exigências de divulgação mais rígidas para futuros empreendimentos de grande porte perto da planície de inundação.", "Representantes do Meridian Property Group, a empresa por trás do projeto, expressaram decepção com a decisão, mas evitaram confirmar se entrariam com ação judicial, observando apenas que estavam \"analisando todas as opções disponíveis\". Moradores que passaram quase dois anos organizando abaixo-assinados e comparecendo a reuniões do conselho descreveram a votação como atrasada havia muito tempo, embora vários tenham alertado que empreendimentos semelhantes em outras partes da cidade ainda carecem de fiscalização comparável.", "O conselho pediu que os urbanistas municipais elaborem diretrizes atualizadas para a planície de inundação em até noventa dias, um prazo que defensores do meio ambiente classificaram como ambicioso, mas necessário, diante das projeções de enchentes sazonais cada vez mais severas. Por enquanto, o terreno do Riverside Commons continua sem construção, com futuro incerto, embora os moradores digam que a votação de terça-feira ao menos restaurou parte da confiança de que preocupações públicas ainda podem se sobrepor aos planos de uma construtora bem financiada."], "hard_words": ["hydrological", "downplayed", "floodplain", "overdue", "scrutiny"], "vocab": [{"word": "withdraw approval", "meaning": "retirar a aprovação", "note": ""}, {"word": "mounting opposition", "meaning": "oposição crescente", "note": ""}, {"word": "cast the deciding vote", "meaning": "dar o voto decisivo", "note": ""}, {"word": "stopped short of", "meaning": "evitaram/não chegaram a fazer algo", "note": "expressão idiomática"}, {"word": "long overdue", "meaning": "atrasado(a) havia muito tempo", "note": ""}, {"word": "outweigh", "meaning": "sobrepor-se a, pesar mais que", "note": ""}, {"word": "well-funded", "meaning": "bem financiado(a)", "note": ""}], "word_meanings": [{"word": "hydrological", "meaning": "hidrológico", "note": ""}, {"word": "downplayed", "meaning": "minimizaram", "note": ""}, {"word": "floodplain", "meaning": "planície de inundação", "note": ""}, {"word": "overdue", "meaning": "atrasado, pendente há tempo", "note": ""}, {"word": "scrutiny", "meaning": "fiscalização, escrutínio", "note": ""}, {"word": "stopped short of", "meaning": "evitaram fazer", "note": "expressão idiomática"}, {"word": "actually", "meaning": "na verdade (não 'atualmente')", "note": "falso cognato"}, {"word": "eventually", "meaning": "finalmente (não 'eventualmente')", "note": "falso cognato"}, {"word": "was", "meaning": "era/foi", "note": "to be"}, {"word": "were", "meaning": "eram/foram", "note": "to be"}, {"word": "voted", "meaning": "votou", "note": "passado regular"}, {"word": "acknowledged", "meaning": "reconheceu", "note": "passado regular"}, {"word": "spent", "meaning": "passou/gastou", "note": "passado irregular"}, {"word": "had", "meaning": "tinha/teve", "note": "passado irregular"}, {"word": "did", "meaning": "fez", "note": "passado irregular"}, {"word": "said", "meaning": "disse", "note": "passado irregular"}, {"word": "cast", "meaning": "lançou/deu (voto)", "note": "passado irregular"}], "grammar_words": {"cognates": [], "tobe": ["were"], "irregular": ["cast", "said", "spent", "had"], "phrasal": ["stopped short of"], "wh": ["whether"], "connectors": ["despite", "though", "but", "rather than", "given"], "comparative": ["stricter", "increasingly severe"]}, "exercises": {"grammar": [{"point": "Voz passiva em contexto jornalístico", "explanation_pt": "'a finding the developer's own consultants had reportedly downplayed' usa a voz passiva/reportada, comum em notícias para atribuir informação sem confirmar diretamente."}, {"point": "Cláusulas concessivas com 'despite' e 'though'", "explanation_pt": "'despite mounting opposition' e 'though several cautioned' introduzem ideias contrastantes dentro da mesma frase."}], "multiple_choice": [{"question": "What did the city council decide on Tuesday?", "options": ["To withdraw approval for the development", "To approve the development", "To postpone the vote", "To fund the development further"], "correct_index": 0, "explanation": "O conselho votou para retirar a aprovação do empreendimento."}, {"question": "What prompted the reversal of the earlier decision?", "options": ["A public protest", "An independent hydrological survey on flood risk", "A change in city leadership", "A lawsuit"], "correct_index": 1, "explanation": "Um estudo hidrológico independente indicou risco elevado de enchentes."}, {"question": "What did Councilwoman Deshmukh acknowledge?", "options": ["She had never supported the project", "She wanted to resign", "She had relied too heavily on the developer's assurances", "She disagreed with the reversal"], "correct_index": 2, "explanation": "Ela reconheceu ter confiado demais nas garantias da construtora."}, {"question": "How did Meridian Property Group respond to the decision?", "options": ["They immediately filed a lawsuit", "They agreed with the council fully", "They withdrew from the city entirely", "They expressed disappointment but did not confirm legal action"], "correct_index": 3, "explanation": "Expressaram decepção, mas não confirmaram ação judicial."}, {"question": "What did the council ask city planners to do?", "options": ["Draft updated floodplain guidelines within ninety days", "Cancel all future developments", "Approve a new developer", "Reduce the building height only"], "correct_index": 0, "explanation": "Pediram diretrizes atualizadas para a planície de inundação em noventa dias."}], "open_questions": [{"question": "Why might independent studies be important before approving large development projects?", "key_points_pt": ["discutir a importância de avaliações imparciais", "citar o exemplo do estudo hidrológico"]}, {"question": "Do you think the council's apology was sufficient given how long the process took? Why or why not?", "key_points_pt": ["dar opinião justificada", "considerar o impacto sobre os moradores durante o período de espera"]}]}}, {"level": "C2", "genre": "neutral", "title": "The Weight of Silence", "paragraphs": ["Eleanor had spent thirty-one years restoring manuscripts, and she still marveled at how a single water stain could obliterate a sentence someone had labored over for hours. The letter before her, brittle and the color of weak tea, belonged to a merchant who had written to his estranged daughter in 1863, pleading for reconciliation he would never receive. She worked with tweezers and a magnifying lens, coaxing the fibers back into alignment, as though patience alone could undo the decades of neglect that had nearly reduced the page to dust.", "What struck her most, after all this time, was not the content of such letters but their futility. The merchant had died within the year, and the daughter, according to the archive's notes, never opened the envelope at all; it had been found sealed among her belongings, its wax seal unbroken. Eleanor wondered whether the woman had recognized the handwriting and simply refused to relive an old wound, or whether grief had rendered the letter irrelevant long before it arrived. Either way, the silence between them had outlasted both correspondents.", "She thought of her own sister, from whom she had been estranged for nearly a decade over a dispute so trivial that she could no longer reconstruct its origins with any confidence. Pride, she supposed, was a peculiarly durable substance, more resistant to erosion than the paper fibers she spent her days repairing. It occurred to her, not for the first time, that she was devoting her career to preserving the remnants of other people's unfinished conversations while conspicuously neglecting her own.", "That evening, rather than driving straight home, Eleanor stopped at a stationer's shop and bought a single sheet of cream-colored paper, the kind she would never have used on an actual restoration. She sat at her kitchen table for a long while before writing anything, acutely aware of the irony of her hesitation. Eventually she wrote only a few lines, nothing elaborate, an invitation rather than an apology, and sealed the envelope before she could talk herself out of sending it.", "Whether her sister would open it immediately, delay for years, or leave it sealed forever, as the merchant's daughter had done, was entirely beyond her control. Eleanor understood this now with a clarity that her profession had quietly taught her: preservation was never a guarantee of resolution, only of possibility. She dropped the letter into the mailbox on the corner and walked home slowly, feeling, for the first time in a long while, that she had done something irrevocable and necessary."], "paragraphs_pt": ["Eleanor havia passado trinta e um anos restaurando manuscritos, e ainda se maravilhava com o modo como uma simples mancha de água podia obliterar uma frase em que alguém trabalhara arduamente por horas. A carta diante dela, quebradiça e da cor de chá fraco, pertencia a um comerciante que escrevera à filha, de quem estava afastado, em 1863, implorando por uma reconciliação que jamais receberia. Ela trabalhava com pinças e uma lente de aumento, realinhando as fibras do papel, como se apenas a paciência pudesse desfazer as décadas de descaso que quase haviam reduzido a página a pó.", "O que mais a impressionava, depois de tanto tempo, não era o conteúdo dessas cartas, mas a sua inutilidade. O comerciante morrera dentro daquele mesmo ano, e a filha, segundo as anotações do arquivo, nunca chegara a abrir o envelope; ele fora encontrado lacrado entre seus pertences, o selo de cera intacto. Eleanor se perguntava se a mulher reconhecera a caligrafia e simplesmente se recusara a reviver uma velha ferida, ou se o luto tornara a carta irrelevante muito antes de ela chegar. De qualquer forma, o silêncio entre os dois havia sobrevivido a ambos os correspondentes.", "Ela pensou na própria irmã, de quem estava afastada havia quase uma década por uma discussão tão trivial que já não conseguia reconstruir sua origem com confiança. O orgulho, ela supunha, era uma substância peculiarmente duradoura, mais resistente à erosão do que as fibras de papel que ela passava os dias consertando. Ocorreu-lhe, não pela primeira vez, que dedicava a carreira a preservar os vestígios de conversas alheias inacabadas enquanto negligenciava, de forma flagrante, a sua própria.", "Naquela noite, em vez de ir direto para casa, Eleanor parou numa papelaria e comprou uma única folha de papel cor de creme, do tipo que jamais usaria numa restauração de verdade. Sentou-se à mesa da cozinha por um bom tempo antes de escrever qualquer coisa, plenamente consciente da ironia de sua hesitação. Por fim, escreveu apenas algumas linhas, nada elaborado, um convite em vez de um pedido de desculpas, e lacrou o envelope antes que pudesse se convencer a não enviá-lo.", "Se a irmã abriria a carta imediatamente, adiaria por anos, ou a deixaria lacrada para sempre, como fizera a filha do comerciante, estava inteiramente fora de seu controle. Eleanor compreendia isso agora com uma clareza que sua profissão lhe ensinara silenciosamente: a preservação nunca era garantia de resolução, apenas de possibilidade. Ela deixou a carta na caixa de correio da esquina e voltou para casa devagar, sentindo, pela primeira vez em muito tempo, que havia feito algo irrevogável e necessário."], "hard_words": ["obliterate", "estranged", "futility", "reconciliation", "erosion", "irrevocable"], "vocab": [{"word": "brittle", "meaning": "quebradiço, frágil", "note": "usado para papel, ossos, materiais que quebram facilmente"}, {"word": "estranged", "meaning": "afastado, distanciado (de um familiar)", "note": ""}, {"word": "futility", "meaning": "inutilidade, futilidade (no sentido de ser em vão)", "note": "falso cognato parcial: não é 'futilidade' frívola"}, {"word": "coax", "meaning": "persuadir suavemente, manejar com cuidado", "note": ""}, {"word": "outlast", "meaning": "durar mais que, sobreviver a", "note": ""}, {"word": "erosion", "meaning": "erosão, desgaste gradual", "note": ""}, {"word": "irrevocable", "meaning": "irrevogável", "note": ""}, {"word": "reconciliation", "meaning": "reconciliação", "note": ""}], "word_meanings": [{"word": "obliterate", "meaning": "obliterar, apagar completamente", "note": ""}, {"word": "estranged", "meaning": "afastado, distanciado (de um familiar)", "note": ""}, {"word": "futility", "meaning": "inutilidade", "note": ""}, {"word": "reconciliation", "meaning": "reconciliação", "note": ""}, {"word": "erosion", "meaning": "erosão, desgaste gradual", "note": ""}, {"word": "irrevocable", "meaning": "irrevogável", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo: não é 'atualmente'"}, {"word": "eventually", "meaning": "finalmente, por fim", "note": "falso amigo: não é 'eventualmente'"}, {"word": "was", "meaning": "era/estava (passado de 'to be')", "note": ""}, {"word": "were", "meaning": "eram/estavam (passado de 'to be')", "note": ""}, {"word": "worked", "meaning": "trabalhou", "note": ""}, {"word": "belonged", "meaning": "pertenceu", "note": ""}, {"word": "wrote", "meaning": "escreveu", "note": "passado irregular de write"}, {"word": "found", "meaning": "encontrado/encontrou", "note": "passado irregular de find"}, {"word": "talk herself out of", "meaning": "convencer-se a não fazer algo", "note": ""}, {"word": "who", "meaning": "quem/que", "note": ""}, {"word": "whom", "meaning": "quem (objeto)", "note": ""}, {"word": "whether", "meaning": "se (indicando dúvida)", "note": ""}, {"word": "rather than", "meaning": "em vez de", "note": ""}], "grammar_words": {"cognates": ["eventually"], "tobe": ["was"], "irregular": ["worked", "belonged", "wrote", "found"], "phrasal": ["talk herself out of"], "wh": ["who", "whom", "whether"], "connectors": ["rather than"], "comparative": []}, "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "Usa-se o past perfect (had + particípio) para indicar uma ação anterior a outra no passado, como em 'the daughter... never opened the envelope' e 'it had been found sealed', mostrando que o lacre já existia antes da descoberta."}], "multiple_choice": [{"question": "What did the merchant write to his daughter?", "options": ["A letter pleading for reconciliation", "A business proposal", "An invitation to a wedding", "A complaint"], "correct_index": 0, "explanation": "O texto diz que ele escreveu 'pleading for reconciliation'."}, {"question": "What happened to the merchant's letter?", "options": ["It was answered", "It was never opened", "It was destroyed", "It was lost in the mail"], "correct_index": 1, "explanation": "A carta foi encontrada lacrada, nunca aberta."}, {"question": "Why is Eleanor estranged from her sister?", "options": ["A serious betrayal", "Money problems", "A trivial dispute she barely remembers", "A disagreement about work"], "correct_index": 2, "explanation": "O texto descreve a disputa como trivial e quase esquecida."}, {"question": "What does Eleanor do at the end of the story?", "options": ["She calls her sister", "She visits the archive again", "She ignores her feelings", "She writes and sends a letter to her sister"], "correct_index": 3, "explanation": "Ela escreve poucas linhas e envia a carta pelo correio."}, {"question": "What is Eleanor's profession?", "options": ["Historian", "Manuscript restorer", "Postal worker", "Novelist"], "correct_index": 1, "explanation": "Ela restaura manuscritos há 31 anos."}], "open_questions": [{"question": "Why do you think the merchant's daughter never opened the letter?", "key_points_pt": ["Pode ter reconhecido a caligrafia e evitado reviver a dor", "O luto pode ter tornado a carta irrelevante"]}, {"question": "Do you think Eleanor's decision to send the letter was brave? Why or why not?", "key_points_pt": ["Envolve vulnerabilidade e risco de rejeição", "Ela age apesar da incerteza sobre o resultado"]}]}}, {"level": "C2", "genre": "humor", "title": "A Masterclass in Overconfidence", "paragraphs": ["Dennis had never assembled furniture in his life, yet he approached the flat-pack wardrobe with the swagger of a man who had built cathedrals. He tossed the instruction booklet aside almost contemptuously, muttering something about how pictograms were for people who lacked spatial intuition, and began sorting the screws into piles based on a classification system comprehensible only to himself. His girlfriend, Priya, watched from the doorway with the resigned expression of someone who had witnessed this particular brand of self-sabotage before.", "Forty minutes in, the wardrobe bore an unsettling resemblance to a Cubist interpretation of a wardrobe rather than an actual one. One door hung at an angle that suggested it had opinions of its own, and a shelf, inexplicably, protruded from the side panel like a diving board. Dennis, undeterred, declared that this was simply 'an alternative configuration' and that the manufacturers had clearly underestimated the market for asymmetry. Priya offered, not for the first time, to retrieve the instructions from the recycling bin, and was again politely rebuffed.", "The turning point arrived when Dennis, attempting to lever the crooked door into submission with a butter knife, sent the entire structure listing sideways with a groan that seemed almost sentient. He leapt backward with a yelp that startled the cat, who had been observing the proceedings from a safe distance with what could only be described as professional interest. The wardrobe settled into a diagonal repose against the wall, magnificently, irreparably wrong, and Dennis stood surveying the wreckage with the crestfallen dignity of a general accepting defeat.", "Priya, mercifully, resisted the urge to say 'I told you so' aloud, though her eyebrows communicated the sentiment with considerable eloquence. She retrieved the instruction booklet, smoothed its slightly damp pages, and sat down cross-legged beside the ruins, patting the floor beside her. Dennis, deflated but not entirely without humor, admitted that perhaps pictograms existed for a reason, possibly several reasons, and possibly all of them applied to him specifically.", "It took the two of them barely twenty minutes, working from the actual diagrams, to disassemble Dennis's improvised masterpiece and rebuild it correctly. The finished wardrobe stood perfectly upright, doors aligned, shelf exactly where the manufacturer had intended, and thoroughly, infuriatingly unremarkable. Dennis regarded it for a long moment before conceding, with the air of a man making a great personal sacrifice, that competence was occasionally underrated."], "paragraphs_pt": ["Dennis nunca havia montado móvel algum na vida, mas se aproximou do guarda-roupa desmontável com a arrogância de quem já havia construído catedrais. Jogou o manual de instruções de lado, quase com desprezo, resmungando algo sobre como pictogramas eram para pessoas sem intuição espacial, e começou a separar os parafusos em pilhas segundo um sistema de classificação compreensível apenas para ele mesmo. A namorada, Priya, observava da porta com a expressão resignada de quem já havia testemunhado esse tipo específico de autossabotagem antes.", "Quarenta minutos depois, o guarda-roupa apresentava uma semelhança inquietante com uma interpretação cubista de um guarda-roupa, em vez de um de verdade. Uma porta pendia em um ângulo que sugeria ter opiniões próprias, e uma prateleira, inexplicavelmente, projetava-se do painel lateral como um trampolim. Dennis, impassível, declarou que aquilo era simplesmente 'uma configuração alternativa' e que os fabricantes claramente haviam subestimado o mercado para a assimetria. Priya se ofereceu, não pela primeira vez, para resgatar as instruções da lixeira de reciclagem, e foi mais uma vez gentilmente recusada.", "O ponto de virada chegou quando Dennis, tentando alavancar a porta torta com uma faca de manteiga, fez toda a estrutura inclinar-se para o lado com um gemido quase senciente. Ele saltou para trás com um grito que assustou o gato, que vinha observando o processo a uma distância segura com o que só poderia ser descrito como interesse profissional. O guarda-roupa se acomodou numa posição diagonal contra a parede, magnificamente e irreparavelmente errado, e Dennis ficou contemplando os destroços com a dignidade abatida de um general aceitando a derrota.", "Priya, misericordiosamente, resistiu ao impulso de dizer 'eu te avisei' em voz alta, embora suas sobrancelhas comunicassem o sentimento com considerável eloquência. Ela pegou o manual de instruções, alisou as páginas ligeiramente úmidas, e sentou-se de pernas cruzadas ao lado das ruínas, batendo de leve no chão ao seu lado. Dennis, desanimado mas não totalmente sem senso de humor, admitiu que talvez pictogramas existissem por um motivo, possivelmente vários motivos, e possivelmente todos se aplicassem especificamente a ele.", "Levou pouco menos de vinte minutos, trabalhando com os diagramas reais, para os dois desmontarem a obra-prima improvisada de Dennis e reconstruí-la corretamente. O guarda-roupa pronto ficou perfeitamente reto, as portas alinhadas, a prateleira exatamente onde o fabricante havia planejado, e completa, irritantemente comum. Dennis o contemplou por um longo momento antes de admitir, com o ar de quem faz um grande sacrifício pessoal, que competência era, ocasionalmente, subestimada."], "hard_words": ["swagger", "contemptuously", "asymmetry", "undeterred", "rebuffed", "crestfallen"], "vocab": [{"word": "flat-pack", "meaning": "móvel desmontável, vendido em caixa plana", "note": ""}, {"word": "swagger", "meaning": "andar/atitude arrogante e confiante", "note": ""}, {"word": "undeterred", "meaning": "sem se deixar dissuadir", "note": ""}, {"word": "rebuffed", "meaning": "recusado, rejeitado", "note": ""}, {"word": "crestfallen", "meaning": "abatido, desanimado", "note": ""}, {"word": "listing sideways", "meaning": "inclinando-se para o lado", "note": "termo náutico usado figurativamente"}, {"word": "underrated", "meaning": "subestimado", "note": ""}, {"word": "deflated", "meaning": "desanimado, murcho (fig.)", "note": ""}], "word_meanings": [{"word": "swagger", "meaning": "andar/atitude arrogante e confiante", "note": ""}, {"word": "contemptuously", "meaning": "com desprezo", "note": ""}, {"word": "asymmetry", "meaning": "assimetria", "note": ""}, {"word": "undeterred", "meaning": "sem se deixar dissuadir", "note": ""}, {"word": "rebuffed", "meaning": "recusado, rejeitado", "note": ""}, {"word": "crestfallen", "meaning": "abatido, desanimado", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "falso amigo"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "tossed", "meaning": "jogou", "note": ""}, {"word": "began", "meaning": "começou", "note": "passado irregular de begin"}, {"word": "sent", "meaning": "enviou/fez (aqui: causou)", "note": "passado irregular de send"}, {"word": "leapt", "meaning": "saltou", "note": "passado irregular de leap"}, {"word": "stood", "meaning": "ficou de pé", "note": "passado irregular de stand"}, {"word": "took", "meaning": "levou/tomou", "note": "passado irregular de take"}, {"word": "told", "meaning": "disse/contou", "note": "passado irregular de tell"}, {"word": "gave up", "meaning": "desistiu", "note": "conceito relacionado (não está no texto literalmente, usado como referência)"}, {"word": "leveled off", "meaning": "estabilizou", "note": ""}, {"word": "however", "meaning": "porém, no entanto", "note": ""}, {"word": "though", "meaning": "embora", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["tossed", "began", "sent", "leapt", "stood", "took", "told"], "phrasal": [], "wh": [], "connectors": ["though"], "comparative": []}, "exercises": {"grammar": [{"point": "Past continuous vs simple past", "explanation_pt": "O past continuous descreve uma ação em progresso interrompida por outra no simple past, como em 'the cat, who had been observing the proceedings' (ação contínua) versus 'Dennis leapt backward' (ação pontual)."}], "multiple_choice": [{"question": "What did Dennis do with the instruction booklet at first?", "options": ["He read it carefully", "He tossed it aside", "He gave it to Priya", "He memorized it"], "correct_index": 1, "explanation": "Ele jogou o manual de lado com desprezo."}, {"question": "What was wrong with the wardrobe after forty minutes?", "options": ["A door hung crooked and a shelf stuck out", "It was perfect", "It was too small", "It had missing screws"], "correct_index": 0, "explanation": "A porta estava torta e a prateleira se projetava para fora."}, {"question": "What caused the wardrobe to collapse sideways?", "options": ["A strong wind", "The cat jumped on it", "Priya pushed it", "Dennis using a butter knife on the door"], "correct_index": 3, "explanation": "Ele tentou forçar a porta com uma faca de manteiga."}, {"question": "How did Priya react to the disaster?", "options": ["She yelled at Dennis", "She left the room", "She calmly got the instructions and sat down to fix it", "She called a professional"], "correct_index": 2, "explanation": "Ela pegou o manual e sentou-se para consertar com calma."}, {"question": "What did Dennis finally admit at the end?", "options": ["That competence is occasionally underrated", "That Priya was better at everything", "That the wardrobe was defective", "That he needed a new cat"], "correct_index": 0, "explanation": "Ele admite que competência é, às vezes, subestimada."}], "open_questions": [{"question": "Why do you think Dennis refused to use the instructions at first?", "key_points_pt": ["Excesso de autoconfiança", "Orgulho de não parecer incompetente"]}, {"question": "Have you ever tried to do something without instructions and failed? What happened?", "key_points_pt": ["Resposta pessoal livre", "Pode mencionar consequências e aprendizado"]}]}}, {"level": "C2", "genre": "suspense", "title": "The 11:47 to Ashgrove", "paragraphs": ["The carriage was nearly empty when the man sat down across the aisle from Marta, close enough that she could hear the faint rustle of his coat but not so close as to seem overtly threatening, which she found, on reflection, more unsettling than if he had. He said nothing, offered no apologetic nod for choosing a seat when so many others stood vacant, and simply stared at the window as though the darkened glass held something worth studying. Marta returned to her book, or pretended to, her eyes tracking the same paragraph without absorbing a single word of it.", "At the second stop, nobody boarded, and nobody left. The man's reflection in the window, she noticed, was watching her rather than the scenery, a discrepancy so faint she might have imagined it, except that she hadn't, and some animal part of her brain insisted on the distinction. She shifted her bag onto her lap, a movement she told herself was mere comfort, though she was quietly calculating the distance to the emergency cord and rehearsing, with mounting absurdity, what she would actually say if she pulled it and nothing was wrong.", "Between the third and fourth stops, the lights flickered, dimmed, and the train slowed without the customary announcement. In the sudden near-darkness, she heard him shift in his seat, and every rational explanation she had constructed evaporated at once. Her hand found the cord before conscious thought caught up with instinct, and she pulled it just as the lights stuttered back on, flooding the carriage with an ordinary, faintly embarrassing brightness.", "The train halted with a lurch that sent a paperback sliding off an empty seat, and a conductor appeared almost immediately, visibly unimpressed, demanding to know who had triggered the alarm. Marta, mortified, began to explain, then stopped, because the man across the aisle was no longer merely watching the window; he was pointing, urgently, wordlessly, at something beneath his own seat, a small case with wires just visible through a gap in the fabric.", "It transpired, in the chaos of evacuation and the arrival of a bomb disposal unit some forty minutes later, that the device had been inert, a hoax left by someone the police would spend weeks trying to identify, but Marta never learned to distinguish, afterward, between the two versions of that night: the one in which her instincts had saved a carriage full of strangers, and the one in which she had simply panicked over a man who, in the end, had been trying to warn her the entire time."], "paragraphs_pt": ["O vagão estava quase vazio quando o homem se sentou do outro lado do corredor, perto o suficiente de Marta para que ela ouvisse o leve farfalhar de seu casaco, mas não tão perto a ponto de parecer abertamente ameaçador, o que ela achou, pensando bem, ainda mais perturbador do que se tivesse sido. Ele não disse nada, não fez nenhum aceno de desculpa por escolher aquele assento quando tantos outros estavam vazios, e simplesmente fitou a janela como se o vidro escurecido guardasse algo digno de estudo. Marta voltou ao livro, ou fingiu voltar, os olhos percorrendo o mesmo parágrafo sem absorver uma única palavra.", "Na segunda parada, ninguém embarcou e ninguém desceu. O reflexo do homem na janela, ela notou, a observava em vez de observar a paisagem, uma discrepância tão sutil que ela poderia tê-la imaginado, exceto que não imaginara, e alguma parte animal do seu cérebro insistia na distinção. Ela ajeitou a bolsa no colo, um movimento que dizia a si mesma ser mero conforto, embora estivesse calculando silenciosamente a distância até o cordão de emergência e ensaiando, com crescente absurdo, o que diria de fato se o puxasse e nada estivesse errado.", "Entre a terceira e a quarta parada, as luzes piscaram, escureceram, e o trem desacelerou sem o costumeiro anúncio. Na súbita quase escuridão, ela o ouviu se mexer no assento, e toda explicação racional que havia construído se evaporou de uma vez. Sua mão encontrou o cordão antes que o pensamento consciente alcançasse o instinto, e ela o puxou bem quando as luzes voltaram a piscar e se firmaram, inundando o vagão com uma claridade comum, levemente constrangedora.", "O trem parou com um solavanco que fez um livro de bolso deslizar de um assento vazio, e um fiscal apareceu quase imediatamente, visivelmente contrariado, exigindo saber quem havia acionado o alarme. Marta, mortificada, começou a explicar, então parou, porque o homem do outro lado do corredor já não apenas observava a janela; ele apontava, com urgência, sem palavras, para algo sob o próprio assento, uma pequena maleta com fios visíveis por uma fresta no tecido.", "Veio à tona, no caos da evacuação e na chegada de uma unidade de desativação de bombas cerca de quarenta minutos depois, que o dispositivo era inerte, um trote deixado por alguém que a polícia levaria semanas para tentar identificar, mas Marta nunca conseguiu, depois daquilo, distinguir entre as duas versões daquela noite: aquela em que seus instintos haviam salvado um vagão cheio de estranhos, e aquela em que ela simplesmente entrara em pânico por causa de um homem que, no fim, estivera o tempo todo tentando avisá-la."], "hard_words": ["discrepancy", "mortified", "transpired", "inert", "hoax", "lurch"], "vocab": [{"word": "rustle", "meaning": "farfalhar, som suave de tecido/papel", "note": ""}, {"word": "discrepancy", "meaning": "discrepância, inconsistência", "note": ""}, {"word": "mortified", "meaning": "extremamente envergonhado", "note": ""}, {"word": "transpired", "meaning": "veio à tona, revelou-se (que)", "note": ""}, {"word": "inert", "meaning": "inerte, inativo", "note": ""}, {"word": "hoax", "meaning": "trote, farsa", "note": ""}, {"word": "lurch", "meaning": "solavanco, movimento brusco", "note": ""}, {"word": "flicker", "meaning": "piscar, tremeluzir (luz)", "note": ""}], "word_meanings": [{"word": "discrepancy", "meaning": "discrepância", "note": ""}, {"word": "mortified", "meaning": "extremamente envergonhado", "note": ""}, {"word": "transpired", "meaning": "veio à tona, revelou-se", "note": ""}, {"word": "inert", "meaning": "inerte", "note": ""}, {"word": "hoax", "meaning": "trote, farsa", "note": ""}, {"word": "lurch", "meaning": "solavanco", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "não usado literalmente aqui mas incluído por padrão de lista"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "sat", "meaning": "sentou", "note": "passado irregular de sit"}, {"word": "said", "meaning": "disse", "note": "passado irregular de say"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular de hear"}, {"word": "found", "meaning": "encontrou", "note": "passado irregular de find"}, {"word": "pulled", "meaning": "puxou", "note": ""}, {"word": "appeared", "meaning": "apareceu", "note": ""}, {"word": "caught up with", "meaning": "alcançou, colocou-se em dia com", "note": ""}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "except that", "meaning": "exceto que", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["was"], "irregular": ["sat", "said", "heard", "found", "pulled", "appeared"], "phrasal": ["caught up with"], "wh": [], "connectors": ["though", "except that"], "comparative": []}, "exercises": {"grammar": [{"point": "Past perfect for background events", "explanation_pt": "O past perfect ('had constructed', 'had saved') é usado para eventos anteriores a outro ponto do passado, criando camadas temporais, como em 'every rational explanation she had constructed evaporated at once'."}], "multiple_choice": [{"question": "Where did the man sit in relation to Marta?", "options": ["Right next to her", "Behind her", "Across the aisle", "In another carriage"], "correct_index": 2, "explanation": "Ele se sentou do outro lado do corredor."}, {"question": "What made Marta suspicious of the man?", "options": ["He spoke to her rudely", "He took her bag", "He was shouting", "His reflection seemed to be watching her"], "correct_index": 3, "explanation": "O reflexo dele na janela parecia observá-la."}, {"question": "What did Marta do when the lights flickered and the train slowed?", "options": ["She pulled the emergency cord", "She fell asleep", "She called the police", "She moved to another seat"], "correct_index": 0, "explanation": "Ela puxou o cordão de emergência."}, {"question": "What was the man actually pointing at?", "options": ["A lost phone", "A suspicious case under his own seat", "The conductor", "The window"], "correct_index": 1, "explanation": "Ele apontava para uma maleta com fios sob seu assento."}, {"question": "What turned out to be true about the device?", "options": ["It was a real bomb", "It was never found", "It belonged to Marta", "It was inert, a hoax"], "correct_index": 3, "explanation": "O dispositivo era inerte, um trote."}], "open_questions": [{"question": "Do you think Marta's instincts were right to be suspicious, even though the device was a hoax?", "key_points_pt": ["A intuição pode ser válida mesmo sem confirmação posterior", "Segurança pessoal justifica cautela"]}, {"question": "How do you think the story would have been different if the man had spoken to Marta earlier?", "key_points_pt": ["Poderia ter evitado o mal-entendido", "Mudaria a tensão e o suspense da narrativa"]}]}}, {"level": "C2", "genre": "detective", "title": "The Vanishing Violinist", "paragraphs": ["Inspector Halloway had interrogated liars of every conceivable variety, but the orchestra's principal cellist, Mr. Arnaud, possessed a particular species of composure that struck him as almost professionally rehearsed. The missing violinist, Elise Renard, had disappeared after the gala rehearsal, leaving behind an empty case, a half-finished glass of wine, and no discernible sign of struggle, which was, in Halloway's considerable experience, more suspicious than chaos would have been. Arnaud claimed he had left the concert hall before anyone else, a claim the ledger at the stage door flatly contradicted.", "The theater itself yielded little; its acoustics, ironically, made it nearly impossible to determine who had been where, since sound traveled in ways that confounded every witness's account of footsteps and voices. Halloway found himself instead scrutinizing the mundane: a torn concert program, a receipt for two coffees when only one musician admitted to buying anything, and a peculiar burn mark on the conductor's podium that nobody could adequately explain. He had learned, over two decades of investigation, that the truth rarely announced itself; it accumulated, almost imperceptibly, in the discrepancies people assumed were too trivial to matter.", "It was the receipt that eventually unraveled everything. The second coffee, purchased twenty minutes after Elise was last seen, had been bought by the conductor's assistant, a mild, unremarkable young man named Petrov who had, until that moment, barely registered as a suspect at all. Confronted, Petrov's composure fractured almost instantly, revealing not a murderer but a co-conspirator: Elise had staged her own disappearance to escape a controlling patron who had, unbeknownst to the rest of the orchestra, been financially coercing her into an engagement she despised.", "Halloway found her three days later, in a modest boarding house two towns over, rehearsing scales on a borrowed violin with an expression of relief so profound it was almost indistinguishable from grief. She had not anticipated, she admitted, quite how thoroughly her absence would be investigated, nor how readily suspicion would fall on colleagues who had done nothing more sinister than help her vanish. The patron, confronted with evidence of coercion rather than kidnapping, was quietly prosecuted for a lesser charge, and the case closed with the particular anticlimax that Halloway had come to associate with cases where nobody, in the end, had actually meant any harm.", "What lingered with him afterward was not the resolution itself but Arnaud's composure, which he eventually understood as simple loyalty rather than guilt; the cellist had known the truth from the beginning and had lied, convincingly, to protect a friend. Halloway closed the file with a grudging respect he rarely extended to people who had obstructed his investigation, reflecting that the most difficult cases were seldom the ones involving genuine villainy, but rather the ones where every party involved had been, in their own compromised way, trying to do right by someone else."], "paragraphs_pt": ["O inspetor Halloway já havia interrogado mentirosos de todo tipo concebível, mas o violoncelista principal da orquestra, o senhor Arnaud, possuía uma espécie particular de compostura que lhe pareceu quase ensaiada profissionalmente. A violinista desaparecida, Elise Renard, sumira após o ensaio da gala, deixando para trás um estojo vazio, uma taça de vinho pela metade e nenhum sinal perceptível de luta, o que, na considerável experiência de Halloway, era mais suspeito do que o caos teria sido. Arnaud afirmava ter deixado a sala de concertos antes de todos os outros, afirmação que o livro de registro da porta dos artistas contradizia categoricamente.", "O próprio teatro rendeu pouco; sua acústica, ironicamente, tornava quase impossível determinar quem estivera onde, já que o som viajava de maneiras que confundiam o relato de cada testemunha sobre passos e vozes. Halloway se viu, em vez disso, examinando o banal: um programa de concerto rasgado, um recibo de dois cafés quando apenas um músico admitira ter comprado algo, e uma marca de queimadura peculiar no pódio do regente que ninguém conseguia explicar adequadamente. Ele aprendera, em duas décadas de investigação, que a verdade raramente se anunciava; ela se acumulava, quase imperceptivelmente, nas discrepâncias que as pessoas presumiam ser triviais demais para importar.", "Foi o recibo que, por fim, desvendou tudo. O segundo café, comprado vinte minutos depois da última vez que Elise fora vista, havia sido comprado pelo assistente do regente, um jovem discreto e nada notável chamado Petrov que, até aquele momento, mal havia sido considerado suspeito. Confrontado, o autocontrole de Petrov se rompeu quase instantaneamente, revelando não um assassino, mas um cúmplice: Elise havia forjado o próprio desaparecimento para escapar de um patrono controlador que, sem que o resto da orquestra soubesse, vinha coagindo-a financeiramente a um noivado que ela detestava.", "Halloway a encontrou três dias depois, numa modesta pensão a duas cidades de distância, ensaiando escalas num violino emprestado com uma expressão de alívio tão profunda que era quase indistinguível de luto. Ela não havia previsto, admitiu, o quão minuciosamente sua ausência seria investigada, nem o quão prontamente a suspeita recairia sobre colegas que não haviam feito nada mais grave do que ajudá-la a sumir. O patrono, confrontado com evidências de coação em vez de sequestro, foi discretamente processado por uma acusação menor, e o caso se encerrou com o anticlímax particular que Halloway passara a associar a casos em que, no fim, ninguém de fato pretendera causar mal.", "O que permaneceu com ele depois não foi a resolução em si, mas a compostura de Arnaud, que ele finalmente entendeu como simples lealdade, e não culpa; o violoncelista sabia a verdade desde o início e mentira, de forma convincente, para proteger uma amiga. Halloway fechou o arquivo com um respeito relutante que raramente concedia a pessoas que haviam obstruído sua investigação, refletindo que os casos mais difíceis raramente eram os que envolviam vilania genuína, mas sim aqueles em que todas as partes envolvidas haviam, cada uma à sua maneira comprometida, tentado fazer o bem por outra pessoa."], "hard_words": ["composure", "discernible", "confounded", "unraveled", "unbeknownst", "anticlimax"], "vocab": [{"word": "composure", "meaning": "compostura, calma", "note": ""}, {"word": "discernible", "meaning": "perceptível, discernível", "note": ""}, {"word": "confounded", "meaning": "confundiu, desconcertou", "note": ""}, {"word": "unraveled", "meaning": "desvendou, desenrolou", "note": ""}, {"word": "unbeknownst", "meaning": "sem o conhecimento de", "note": "expressão formal/literária"}, {"word": "anticlimax", "meaning": "anticlímax", "note": ""}, {"word": "grudging", "meaning": "relutante, dado a contragosto", "note": ""}, {"word": "coercing", "meaning": "coagindo", "note": ""}], "word_meanings": [{"word": "composure", "meaning": "compostura, calma", "note": ""}, {"word": "discernible", "meaning": "perceptível", "note": ""}, {"word": "confounded", "meaning": "confundiu", "note": ""}, {"word": "unraveled", "meaning": "desvendou", "note": ""}, {"word": "unbeknownst", "meaning": "sem o conhecimento de", "note": ""}, {"word": "anticlimax", "meaning": "anticlímax", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "falso amigo"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "found", "meaning": "encontrou", "note": "passado irregular de find"}, {"word": "left", "meaning": "deixou/saiu", "note": "passado irregular de leave"}, {"word": "bought", "meaning": "comprou", "note": "passado irregular de buy"}, {"word": "knew", "meaning": "sabia", "note": "passado irregular de know"}, {"word": "closed", "meaning": "fechou/encerrou", "note": ""}, {"word": "fell on", "meaning": "recaiu sobre", "note": "phrasal verb: fall on"}, {"word": "who", "meaning": "quem/que", "note": ""}, {"word": "which", "meaning": "que/o qual", "note": ""}, {"word": "rather than", "meaning": "em vez de", "note": ""}], "grammar_words": {"cognates": ["actually", "eventually"], "tobe": ["was", "were"], "irregular": ["found", "left", "bought", "closed"], "phrasal": [], "wh": ["who", "which"], "connectors": ["rather than"], "comparative": []}, "exercises": {"grammar": [{"point": "Reported/embedded clauses with 'that'", "explanation_pt": "Orações subordinadas iniciadas por 'that' relatam afirmações ou fatos, como em 'a claim the ledger... flatly contradicted' e 'He had learned... that the truth rarely announced itself', comuns em narrativas investigativas formais."}], "multiple_choice": [{"question": "What did Halloway find suspicious about the crime scene?", "options": ["Signs of a violent struggle", "A ransom note", "Broken windows", "The lack of any struggle"], "correct_index": 3, "explanation": "A ausência de sinais de luta era mais suspeita, segundo Halloway."}, {"question": "What clue eventually broke the case open?", "options": ["A torn program", "A burn mark", "A coffee receipt", "A witness statement"], "correct_index": 2, "explanation": "O recibo dos dois cafés levou à descoberta."}, {"question": "Why did Elise Renard disappear?", "options": ["She was kidnapped", "She staged it to escape a controlling patron", "She had amnesia", "She quit music"], "correct_index": 1, "explanation": "Ela forjou o desaparecimento para escapar da coação do patrono."}, {"question": "Why did Arnaud lie to Halloway?", "options": ["He was protecting Elise out of loyalty", "He was guilty of the crime", "He wanted money", "He hated the police"], "correct_index": 0, "explanation": "Ele mentiu por lealdade, para proteger a amiga."}, {"question": "What happened to the patron in the end?", "options": ["He was released with no charge", "He disappeared too", "He was prosecuted for a lesser charge", "He became the conductor"], "correct_index": 2, "explanation": "Ele foi processado por uma acusação menor de coação."}], "open_questions": [{"question": "Do you think Arnaud was right to lie to protect Elise? Why or why not?", "key_points_pt": ["Lealdade versus obstrução da justiça", "Depende da gravidade da mentira e da intenção"]}, {"question": "What does this story suggest about the nature of 'difficult' criminal cases?", "key_points_pt": ["Nem todo caso envolve vilania genuína", "Pessoas boas podem cometer erros tentando proteger outras"]}]}}, {"level": "C2", "genre": "romance", "title": "Letters to Nowhere in Particular", "paragraphs": ["For eleven months, Noah had been corresponding with someone he knew only as 'R,' an anonymous pen pal assigned to him through a literacy charity's letter-exchange program, and he had grown embarrassingly attached to a person whose handwriting he could recognize instantly but whose face remained a complete mystery. R wrote with a wit that consistently undercut its own melancholy, describing a job she disliked and a city she loved with equal, exasperated affection, and Noah found himself rereading her letters far more often than the program's coordinators presumably intended.", "He had considered, more than once, requesting her actual identity, a request the program discouraged but did not strictly forbid, yet something about the anonymity felt essential to whatever this correspondence had become. There was an honesty in writing to someone who couldn't yet judge you by your face or your circumstances, an intimacy that felt, paradoxically, easier to sustain precisely because it remained incomplete. He wondered, occasionally, whether R felt the same reluctance, or whether she simply hadn't considered him worth the trouble of unmasking.", "The charity's annual gathering, an event Noah had previously dismissed as an unnecessary formality, suddenly acquired an unbearable significance once he learned that pen pals were, this year, encouraged to attend and identify themselves if they wished. He spent an embarrassing amount of time deciding what to wear, second-guessing the decision entirely, and arriving twenty minutes late specifically so that he wouldn't be standing awkwardly alone when other people's reunions began.", "He recognized her before she recognized him, though he couldn't afterward explain how, given that he had no photograph and no description beyond his own imagination; something in the way she stood, slightly apart from the crowd, holding her drink like it was a prop rather than a beverage, matched some instinct he hadn't known he possessed. When he finally introduced himself, stammering through a joke he had rehearsed and immediately mangled, she laughed, the exact laugh he had imagined from her letters, and admitted she had spotted him twenty minutes earlier and had been too nervous to approach.", "They stayed at that gathering far longer than either had intended, talking with the specific ease of people who had already exchanged their most honest selves on paper and were now simply attaching faces and voices to something that had existed, quite thoroughly, before either of them arrived. Walking her to her train afterward, Noah realized that he no longer wanted to call her 'R'; he wanted her actual name, which she gave him, laughing, as though it were the most unnecessary formality in a friendship that had never really needed one."], "paragraphs_pt": ["Por onze meses, Noah trocara cartas com alguém que conhecia apenas como 'R', uma correspondente anônima designada a ele por um programa de troca de cartas de uma instituição de alfabetização, e ele havia se apegado, de forma embaraçosa, a uma pessoa cuja caligrafia reconhecia instantaneamente, mas cujo rosto permanecia um completo mistério. R escrevia com um humor que constantemente contrariava sua própria melancolia, descrevendo um emprego de que não gostava e uma cidade que amava com igual afeto, exasperado, e Noah se via relendo as cartas dela com muito mais frequência do que os coordenadores do programa presumivelmente pretendiam.", "Ele já havia considerado, mais de uma vez, pedir a identidade real dela, um pedido que o programa desencorajava, mas não proibia estritamente, mas algo no anonimato parecia essencial para o que aquela correspondência havia se tornado. Havia uma honestidade em escrever para alguém que ainda não podia julgá-lo pelo rosto ou pelas circunstâncias, uma intimidade que parecia, paradoxalmente, mais fácil de sustentar justamente por permanecer incompleta. Ele se perguntava, ocasionalmente, se R sentia a mesma relutância, ou se simplesmente não o considerava digno do trabalho de se revelar.", "O encontro anual da instituição, um evento que Noah antes considerava uma formalidade desnecessária, adquiriu de repente uma importância insuportável quando ele soube que, naquele ano, os correspondentes eram incentivados a comparecer e se identificar, se assim desejassem. Ele passou um tempo embaraçoso decidindo o que vestir, questionando totalmente a decisão, e chegou vinte minutos atrasado justamente para não ficar sozinho, sem jeito, enquanto os reencontros de outras pessoas aconteciam.", "Ele a reconheceu antes que ela o reconhecesse, embora não conseguisse explicar depois como, já que não tinha fotografia nem descrição além da própria imaginação; algo no jeito como ela ficava, ligeiramente afastada da multidão, segurando a bebida como se fosse um adereço em vez de uma bebida, correspondia a um instinto que ele nem sabia possuir. Quando finalmente se apresentou, gaguejando uma piada que havia ensaiado e imediatamente estragou, ela riu, exatamente a risada que ele havia imaginado a partir das cartas, e admitiu que o notara vinte minutos antes e estivera nervosa demais para se aproximar.", "Eles ficaram naquele encontro muito mais tempo do que qualquer um dos dois pretendia, conversando com a naturalidade específica de pessoas que já haviam trocado seus eus mais sinceros no papel e agora simplesmente atribuíam rostos e vozes a algo que já existia, bastante consolidado, antes mesmo de qualquer um dos dois chegar. Ao acompanhá-la até o trem depois, Noah percebeu que não queria mais chamá-la de 'R'; queria o nome verdadeiro dela, que ela lhe deu, rindo, como se fosse a formalidade mais desnecessária numa amizade que nunca havia precisado de uma."], "hard_words": ["undercut", "melancholy", "unmasking", "mangled", "stammering", "exasperated"], "vocab": [{"word": "undercut", "meaning": "contrariar, minar (sutilmente)", "note": ""}, {"word": "melancholy", "meaning": "melancolia", "note": ""}, {"word": "unmasking", "meaning": "desmascarar, revelar identidade", "note": ""}, {"word": "mangled", "meaning": "estragou, bagunçou (fig.)", "note": ""}, {"word": "stammering", "meaning": "gaguejando", "note": ""}, {"word": "exasperated", "meaning": "exasperado", "note": "falso amigo: não é 'exasperado' no sentido de raiva forte apenas, mas frustração intensa"}, {"word": "prop", "meaning": "adereço, objeto de cena", "note": ""}, {"word": "spotted", "meaning": "avistou, notou", "note": ""}], "word_meanings": [{"word": "undercut", "meaning": "contrariar, minar", "note": ""}, {"word": "melancholy", "meaning": "melancolia", "note": ""}, {"word": "unmasking", "meaning": "desmascarar", "note": ""}, {"word": "mangled", "meaning": "estragou", "note": ""}, {"word": "stammering", "meaning": "gaguejando", "note": ""}, {"word": "exasperated", "meaning": "exasperado, frustrado", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "não aparece literalmente, mas listado por padrão de cognato comum"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "knew", "meaning": "sabia/conhecia", "note": "passado irregular de know"}, {"word": "grew", "meaning": "cresceu, tornou-se", "note": "passado irregular de grow"}, {"word": "gave", "meaning": "deu", "note": "passado irregular de give"}, {"word": "held", "meaning": "segurou", "note": "passado irregular de hold"}, {"word": "spotted", "meaning": "avistou", "note": ""}, {"word": "found himself", "meaning": "se via/se percebia", "note": "expressão idiomática"}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "whether", "meaning": "se (dúvida)", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["knew", "gave", "spotted"], "phrasal": ["found himself"], "wh": ["whether"], "connectors": ["though"], "comparative": []}, "exercises": {"grammar": [{"point": "Cleft-like emphasis with 'It was... that'", "explanation_pt": "Estruturas como 'something about the anonymity felt essential' usam o sujeito abstrato para enfatizar uma ideia central, comum em prosa reflexiva sofisticada de nível C2."}], "multiple_choice": [{"question": "How did Noah and R first start communicating?", "options": ["Through a literacy charity's pen pal program", "Through social media", "At work", "At school"], "correct_index": 0, "explanation": "Eles se conheceram por meio de um programa de troca de cartas de uma instituição de alfabetização."}, {"question": "Why didn't Noah ask for R's identity earlier?", "options": ["It was strictly forbidden", "He wasn't interested", "The anonymity felt essential to their connection", "He forgot"], "correct_index": 2, "explanation": "O anonimato parecia essencial ao que a correspondência havia se tornado."}, {"question": "Why did Noah arrive twenty minutes late to the gathering?", "options": ["He got lost", "So he wouldn't stand alone during other reunions", "His train was delayed", "He changed his mind about going"], "correct_index": 1, "explanation": "Ele chegou atrasado de propósito para não ficar sozinho e sem jeito."}, {"question": "How did Noah recognize R at the event?", "options": ["She wore a name tag", "A friend pointed her out", "She called his name", "By an instinct about how she stood and held her drink"], "correct_index": 3, "explanation": "Algo no jeito dela ficar de pé correspondeu a um instinto que ele possuía."}, {"question": "What did Noah want at the end of the story?", "options": ["To know her real name", "To stop writing to her", "To leave without talking to her", "To join a different program"], "correct_index": 0, "explanation": "Ele percebeu que queria o nome verdadeiro dela."}], "open_questions": [{"question": "Why do you think anonymity made Noah and R's relationship feel more honest?", "key_points_pt": ["Sem julgamento baseado na aparência", "Foco no conteúdo emocional das cartas"]}, {"question": "Would you participate in an anonymous pen pal program? Why or why not?", "key_points_pt": ["Resposta pessoal livre", "Pode mencionar curiosidade, insegurança ou desejo de conexão genuína"]}]}}, {"level": "C2", "genre": "scifi", "title": "The Last Signal", "paragraphs": ["Commander Isolde Reyes had rehearsed this transmission a hundred times in her head, yet standing before the console with Earth's reply finally decrypting on the screen, every carefully composed sentence evaporated. The colony ship Meridian had drifted beyond reliable contact eleven years earlier, a consequence of a navigational error nobody had fully explained, and the crew had long since stopped expecting any response at all, treating their daily logs as messages to a future that might never read them. Now, impossibly, Earth was answering, though the delay meant the words on her screen had been sent before her own daughter was born.", "The message itself was maddeningly bureaucratic, a status update from a mission control staffed by people whose grandparents had likely written the original launch protocols, informing the Meridian that Earth's own situation had changed considerably and that reunion, should it ever occur, would happen on terms nobody aboard the ship had been trained to anticipate. Isolde read the technical appendices twice before the implication settled: the technology Earth now possessed made the Meridian's entire eleven-year voyage almost irrelevant, a slower, costlier path to a destination that faster ships had since reached and, in some cases, already begun to colonize.", "She gathered the crew in the observation deck rather than announcing it over the intercom, feeling that news capable of unmaking an entire mission's sense of purpose deserved to be delivered to faces rather than speakers. The reactions varied more than she expected: relief from those who had quietly dreaded the isolation for years, indignation from those who had built their identities around being first, and a peculiar, weary amusement from the ship's eldest engineer, who observed that humanity's compulsion to declare things obsolete the moment something newer existed was, if anything, reassuringly familiar.", "What the message did not resolve, and what occupied Isolde far more than questions of technological obsolescence, was what the Meridian's mission had actually meant if its practical purpose had already been superseded elsewhere. She found herself, over the following days, returning to the ship's accumulated logs, eleven years of small observations, minor disputes, births, one death, an entire community that had built something real regardless of whether anyone on Earth would ever consider it necessary.", "In her eventual reply, transmitted knowing it would not be received for over a decade, Isolde chose not to dwell on obsolescence at all. She wrote instead about the community the Meridian had become, the systems they had improvised, the children who had never known any world but the ship's corridors and considered them entirely ordinary, and closed by noting that a mission's worth was never really determined by whoever arrived first, but by what its people had managed to build along the way, a sentiment she suspected Earth's mission control, eleven years and several technological generations removed, might no longer be equipped to fully understand."], "paragraphs_pt": ["A comandante Isolde Reyes havia ensaiado aquela transmissão cem vezes na cabeça, mas, diante do console com a resposta da Terra finalmente sendo decodificada na tela, cada frase cuidadosamente composta se evaporou. A nave colonizadora Meridian havia se afastado de um contato confiável onze anos antes, consequência de um erro de navegação que ninguém explicara por completo, e a tripulação já havia deixado de esperar qualquer resposta, tratando seus registros diários como mensagens para um futuro que talvez nunca as lesse. Agora, incrivelmente, a Terra respondia, embora o atraso significasse que as palavras na tela haviam sido enviadas antes mesmo de sua própria filha nascer.", "A mensagem em si era irritantemente burocrática, uma atualização de status vinda de um controle de missão formado por pessoas cujos avós provavelmente haviam escrito os protocolos originais de lançamento, informando à Meridian que a situação da Terra havia mudado consideravelmente e que o reencontro, caso viesse a ocorrer, aconteceria em termos para os quais ninguém a bordo da nave fora treinado. Isolde leu os anexos técnicos duas vezes antes que a implicação se assentasse: a tecnologia que a Terra agora possuía tornava toda a viagem de onze anos da Meridian quase irrelevante, um caminho mais lento e mais caro até um destino que naves mais rápidas já haviam alcançado e, em alguns casos, já começado a colonizar.", "Ela reuniu a tripulação no convés de observação em vez de anunciar pelo interfone, sentindo que uma notícia capaz de desfazer o sentido de propósito de toda uma missão merecia ser entregue a rostos, e não a alto-falantes. As reações variaram mais do que ela esperava: alívio dos que temiam silenciosamente o isolamento havia anos, indignação dos que haviam construído suas identidades em torno de serem os primeiros, e uma diversão peculiar e cansada do engenheiro mais velho da nave, que observou que a compulsão da humanidade em declarar as coisas obsoletas assim que algo mais novo surgia era, na verdade, reconfortantemente familiar.", "O que a mensagem não resolvia, e o que ocupava Isolde muito mais do que questões de obsolescência tecnológica, era o que a missão da Meridian de fato havia significado, se seu propósito prático já fora superado em outro lugar. Ela se viu, nos dias seguintes, voltando aos registros acumulados da nave, onze anos de pequenas observações, disputas menores, nascimentos, uma morte, uma comunidade inteira que havia construído algo real, independentemente de alguém na Terra algum dia considerar isso necessário.", "Em sua resposta final, transmitida sabendo que não seria recebida por mais de uma década, Isolde optou por não se deter na obsolescência. Escreveu, em vez disso, sobre a comunidade em que a Meridian se tornara, os sistemas que haviam improvisado, as crianças que nunca conheceram outro mundo além dos corredores da nave e os consideravam inteiramente normais, e encerrou observando que o valor de uma missão nunca era realmente determinado por quem chegava primeiro, mas pelo que seu povo conseguira construir pelo caminho, um sentimento que ela suspeitava que o controle de missão da Terra, onze anos e várias gerações tecnológicas distante, talvez já não estivesse equipado para compreender plenamente."], "hard_words": ["decrypting", "obsolescence", "superseded", "indignation", "compulsion", "maddeningly"], "vocab": [{"word": "decrypting", "meaning": "decodificando, descriptografando", "note": ""}, {"word": "obsolescence", "meaning": "obsolescência", "note": ""}, {"word": "superseded", "meaning": "substituído, superado", "note": ""}, {"word": "indignation", "meaning": "indignação", "note": ""}, {"word": "compulsion", "meaning": "compulsão, impulso incontrolável", "note": ""}, {"word": "maddeningly", "meaning": "de forma enlouquecedora/irritante", "note": ""}, {"word": "dwell on", "meaning": "se deter em, insistir em (um assunto)", "note": ""}, {"word": "weary", "meaning": "cansado, fatigado", "note": ""}], "word_meanings": [{"word": "decrypting", "meaning": "decodificando", "note": ""}, {"word": "obsolescence", "meaning": "obsolescência", "note": ""}, {"word": "superseded", "meaning": "substituído, superado", "note": ""}, {"word": "indignation", "meaning": "indignação", "note": ""}, {"word": "compulsion", "meaning": "compulsão", "note": ""}, {"word": "maddeningly", "meaning": "de forma enlouquecedora", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "falso amigo"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "read", "meaning": "leu", "note": "passado irregular de read (pronúncia muda)"}, {"word": "wrote", "meaning": "escreveu", "note": "passado irregular de write"}, {"word": "chose", "meaning": "escolheu", "note": "passado irregular de choose"}, {"word": "gathered", "meaning": "reuniu", "note": ""}, {"word": "dwell on", "meaning": "se deter em", "note": ""}, {"word": "should it ever occur", "meaning": "caso isso algum dia ocorresse", "note": "inversão condicional formal"}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "regardless of whether", "meaning": "independentemente de", "note": ""}], "grammar_words": {"cognates": ["actually"], "tobe": ["was"], "irregular": ["read", "wrote", "chose", "gathered"], "phrasal": ["dwell on"], "wh": ["whether"], "connectors": ["though", "regardless of whether"], "comparative": []}, "exercises": {"grammar": [{"point": "Inverted conditionals (formal register)", "explanation_pt": "Em registros formais, condicionais podem ser invertidos sem 'if', como em 'should it ever occur' (= if it ever occurred), estrutura típica de textos técnicos ou institucionais em nível C2."}], "multiple_choice": [{"question": "Why had the Meridian lost contact with Earth?", "options": ["A navigational error", "A deliberate decision", "An attack", "Equipment theft"], "correct_index": 0, "explanation": "Foi consequência de um erro de navegação não totalmente explicado."}, {"question": "What did Earth's message reveal about technology?", "options": ["Earth had lost all technology", "Faster ships had already reached and colonized the destination", "The Meridian was the fastest ship ever built", "Earth no longer had space travel"], "correct_index": 1, "explanation": "Naves mais rápidas já haviam alcançado e colonizado o destino."}, {"question": "Where did Isolde choose to share the news with the crew?", "options": ["Over the intercom", "In a written memo", "In the observation deck, face to face", "She didn't tell them"], "correct_index": 2, "explanation": "Ela reuniu a tripulação pessoalmente no convés de observação."}, {"question": "How did the ship's eldest engineer react to the news?", "options": ["With anger", "With panic", "With complete indifference", "With weary amusement"], "correct_index": 3, "explanation": "Ele reagiu com uma diversão peculiar e cansada."}, {"question": "What did Isolde focus on in her final reply to Earth?", "options": ["Complaints about being forgotten", "The community and life the crew had built", "A request for rescue", "Technical specifications"], "correct_index": 1, "explanation": "Ela escreveu sobre a comunidade que a tripulação havia construído."}], "open_questions": [{"question": "Do you agree with Isolde that a mission's worth isn't determined by who arrives first? Why or why not?", "key_points_pt": ["Valor pode estar no processo, não apenas no resultado", "Comunidade e experiência humana como valores em si"]}, {"question": "How do you think the crew members who felt indignation might respond to Isolde's message?", "key_points_pt": ["Podem discordar e sentir que seu sacrifício foi em vão", "Podem eventualmente aceitar a perspectiva dela"]}]}}, {"level": "C2", "genre": "medieval", "title": "The Falconer's Oath", "paragraphs": ["Aldric had served the castle's mews for eleven years before the new steward arrived, a man whose contempt for falconry as a discipline was matched only by his conviction that the birds existed purely to impress visiting dignitaries. When the steward demanded that Sable, Aldric's finest gyrfalcon, be flown at a banquet despite a wing injury the bird had not yet fully recovered from, Aldric refused, quietly but unmistakably, an act of defiance that in lesser households might have earned him a flogging rather than a reprimand.", "The steward, unaccustomed to being contradicted by a man of Aldric's modest station, threatened to have the falconer dismissed and the bird sold to a merchant with less regard for her welfare. Aldric, weighing eleven years of devotion against the very real prospect of losing both his position and the creature he had raised from an eyas, chose instead to appeal directly to the baroness, a woman rumored to possess more sense than her steward and considerably less patience for cruelty conducted in her name.", "The baroness received him in the solar, listening without interruption as Aldric explained, with a bluntness that startled even himself, that a wounded bird forced to fly for spectacle would likely reinjure herself beyond recovery, and that no banquet was worth the loss of a falcon that had, on three separate occasions, brought down game that had fed half the castle through a lean winter. She asked a single question, whether he would stake his position on the truth of his assessment, and Aldric answered without hesitation that he would.", "The baroness overruled her steward that same evening, decreeing that Sable would remain in the mews until fully healed and that any future decisions regarding the hawks would require Aldric's counsel, a ruling the steward received with poorly disguised resentment but did not dare contest openly. Word of the exchange traveled through the household with the particular swiftness reserved for stories in which the powerful are seen to yield to the merely competent, and Aldric found himself regarded, for the first time in over a decade, as someone whose judgment carried genuine weight within those walls.", "Sable recovered fully within the month and, some weeks later, took a heron in a flight so precise that even the steward, watching from the battlements with an expression he clearly wished had gone unnoticed, permitted himself a single, grudging nod of approval. Aldric never learned whether the gesture constituted an apology, and he found, to his own mild surprise, that he no longer particularly needed it to."], "paragraphs_pt": ["Aldric servira na falcoaria do castelo por onze anos antes de o novo mordomo chegar, um homem cujo desprezo pela falcoaria como disciplina só era igualado por sua convicção de que as aves existiam unicamente para impressionar dignitários visitantes. Quando o mordomo exigiu que Sable, o melhor girifalte de Aldric, fosse posto para voar num banquete apesar de um ferimento na asa do qual a ave ainda não havia se recuperado por completo, Aldric se recusou, de forma discreta mas inconfundível, um ato de desafio que em casas menos tolerantes poderia lhe ter rendido açoites em vez de uma simples repreensão.", "O mordomo, pouco acostumado a ser contrariado por um homem da posição modesta de Aldric, ameaçou tê-lo demitido e a ave vendida a um mercador com menos consideração pelo bem-estar dela. Aldric, pesando onze anos de dedicação contra a possibilidade muito real de perder tanto seu posto quanto a criatura que criara desde filhote, optou em vez disso por apelar diretamente à baronesa, uma mulher que se dizia possuir mais bom senso que seu mordomo e consideravelmente menos paciência para crueldade praticada em seu nome.", "A baronesa o recebeu na sala de estar, ouvindo sem interromper enquanto Aldric explicava, com uma franqueza que surpreendeu até a ele mesmo, que uma ave ferida forçada a voar para espetáculo provavelmente se machucaria além de qualquer recuperação, e que nenhum banquete valia a perda de uma falcoa que, em três ocasiões distintas, havia abatido caça que alimentara metade do castelo durante um inverno de escassez. Ela fez uma única pergunta, se ele apostaria seu cargo na veracidade de sua avaliação, e Aldric respondeu sem hesitar que sim.", "A baronesa contrariou seu mordomo naquela mesma noite, decretando que Sable permaneceria na falcoaria até estar completamente curada e que quaisquer decisões futuras a respeito dos falcões exigiriam o parecer de Aldric, uma decisão que o mordomo recebeu com um ressentimento mal disfarçado, mas que não ousou contestar abertamente. A notícia da troca de palavras percorreu a casa com a rapidez particular reservada a histórias em que os poderosos são vistos cedendo aos simplesmente competentes, e Aldric se viu considerado, pela primeira vez em mais de uma década, alguém cujo julgamento tinha peso genuíno dentro daquelas muralhas.", "Sable se recuperou por completo dentro de um mês e, algumas semanas depois, abateu uma garça num voo tão preciso que até o mordomo, observando das ameias com uma expressão que claramente desejava que ninguém notasse, permitiu-se um único e relutante aceno de aprovação. Aldric nunca chegou a saber se aquele gesto constituía um pedido de desculpas, e descobriu, para sua própria surpresa moderada, que já não precisava particularmente dele."], "hard_words": ["gyrfalcon", "flogging", "reprimand", "eyas", "decreeing", "battlements"], "vocab": [{"word": "mews", "meaning": "falcoaria, local onde se mantêm falcões", "note": ""}, {"word": "flogging", "meaning": "açoitamento, castigo físico", "note": ""}, {"word": "reprimand", "meaning": "repreensão", "note": ""}, {"word": "eyas", "meaning": "filhote de ave de rapina ainda não voou", "note": "termo técnico de falcoaria"}, {"word": "decreeing", "meaning": "decretando", "note": ""}, {"word": "battlements", "meaning": "ameias (parte superior do castelo)", "note": ""}, {"word": "stake", "meaning": "apostar, arriscar", "note": ""}, {"word": "grudging", "meaning": "relutante, dado a contragosto", "note": ""}], "word_meanings": [{"word": "gyrfalcon", "meaning": "girifalte (ave de rapina)", "note": ""}, {"word": "flogging", "meaning": "açoitamento", "note": ""}, {"word": "reprimand", "meaning": "repreensão", "note": ""}, {"word": "eyas", "meaning": "filhote de ave de rapina", "note": ""}, {"word": "decreeing", "meaning": "decretando", "note": ""}, {"word": "battlements", "meaning": "ameias", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "não aparece literalmente no texto, mas listado como cognato de referência"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "chose", "meaning": "escolheu", "note": "passado irregular de choose"}, {"word": "received", "meaning": "recebeu", "note": ""}, {"word": "answered", "meaning": "respondeu", "note": ""}, {"word": "took", "meaning": "tomou/abateu", "note": "passado irregular de take"}, {"word": "found himself", "meaning": "se viu/se percebeu", "note": "expressão idiomática"}, {"word": "whether", "meaning": "se (dúvida)", "note": ""}, {"word": "despite", "meaning": "apesar de", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["chose", "received", "answered", "took"], "phrasal": ["found himself"], "wh": ["whether"], "connectors": ["despite"], "comparative": []}, "exercises": {"grammar": [{"point": "Subjunctive-like formal structures", "explanation_pt": "Estruturas formais como 'demanded that Sable... be flown' usam o subjuntivo (sem -s na terceira pessoa) após verbos como 'demand', típico de registro elevado em inglês C2."}], "multiple_choice": [{"question": "Why did Aldric refuse the steward's order?", "options": ["He disliked the steward personally", "Sable had an unhealed wing injury", "He wanted more pay", "He was too tired"], "correct_index": 1, "explanation": "Sable ainda não havia se recuperado completamente de um ferimento na asa."}, {"question": "What did Aldric risk by appealing to the baroness?", "options": ["His position and possibly the falcon", "Nothing at all", "His life", "His family's land"], "correct_index": 0, "explanation": "Ele arriscava perder o cargo e a ave."}, {"question": "What question did the baroness ask Aldric?", "options": ["Whether he wanted a raise", "Whether he liked the steward", "Whether Sable was for sale", "Whether he would stake his position on his assessment"], "correct_index": 3, "explanation": "Ela perguntou se ele apostaria o cargo na veracidade de sua avaliação."}, {"question": "What did the baroness decide?", "options": ["To dismiss Aldric", "To sell Sable", "That Sable would stay until healed and Aldric's counsel would be required", "To fire the steward immediately"], "correct_index": 2, "explanation": "Ela decretou que Sable ficaria até curar-se e que o parecer de Aldric seria necessário."}, {"question": "How did the steward react when Sable flew perfectly weeks later?", "options": ["With a grudging nod of approval", "With fury", "He left the castle", "He apologized publicly"], "correct_index": 0, "explanation": "Ele permitiu-se um relutante aceno de aprovação."}], "open_questions": [{"question": "Why do you think Aldric was willing to risk his position for Sable?", "key_points_pt": ["Vínculo profundo com a ave criada desde filhote", "Convicção profissional e ética sobre o bem-estar animal"]}, {"question": "What does the baroness's decision reveal about her character as a leader?", "key_points_pt": ["Ela valoriza competência sobre hierarquia", "Está disposta a corrigir decisões injustas de subordinados"]}]}}, {"level": "C2", "genre": "mythology", "title": "The Weaver of Fates", "paragraphs": ["Among the lesser deities who attended the great loom of destiny, none was so resented as Perenna, whose task it was to weave the single thread representing every mortal's final year, a duty the other weavers considered beneath them and that Perenna alone seemed to regard with anything resembling tenderness. She alone insisted on learning something of each mortal before cutting their thread, a practice her fellow weavers dismissed as sentimental inefficiency, arguing that fate required no such intimacy, only precision.", "It was during the weaving of a particularly obstinate thread, belonging to a fisherman who had survived three shipwrecks through what appeared to be nothing but stubborn refusal to drown, that Perenna first hesitated. The pattern the other threads suggested for him was unambiguous, a fourth and final wreck within the month, yet something in the weave itself seemed to resist her shears, as though the thread had absorbed some of the man's own obstinacy and intended to outlast her judgment. She set the shears aside, an act unprecedented among weavers, and resolved to observe him a while longer before proceeding.", "The elder weavers, upon discovering her hesitation, convened to reprimand her, insisting that a single exception would unravel the entire tapestry's coherence, that fate could not be selectively delayed without consequence to threads interwoven with his own. Perenna, unmoved by an argument she had heard rehearsed for centuries, pointed out that the fisherman's thread was tangled inextricably with dozens of others, a wife's, a daughter's, an entire village's fragile economy, and that his premature ending would fray far more than it resolved. She proposed, instead of severance, a reweaving, a longer thread bought at the cost of her own diminished influence among the other deities.", "The elders, more troubled by precedent than by cruelty, ultimately permitted the exception, partly because Perenna's argument was sound and partly because none among them wished to be responsible for the discord her removal from the looms would cause. The fisherman lived another eleven years, long enough to teach his craft to a grandson who would, generations later, become the ancestor of a line of shipbuilders whose vessels would carry entire villages safely through storms that, in the original weave, would have claimed them.", "Perenna never spoke of the incident again, though the other weavers noticed, in the years that followed, a subtle change in how they approached their own shears: a fraction more hesitation, a fraction more curiosity about the lives interrupted by their blades. She had not overturned fate, precisely, only demonstrated, quietly and at considerable personal cost, that even the most rigid pattern occasionally tolerated the intervention of someone willing to look closely enough to notice it mattered."], "paragraphs_pt": ["Entre as divindades menores que atendiam ao grande tear do destino, nenhuma era tão malquista quanto Perenna, cuja tarefa era tecer o fio único que representava o último ano de vida de cada mortal, um dever que as outras tecelãs consideravam indigno delas e que somente Perenna parecia encarar com algo parecido com ternura. Só ela insistia em conhecer algo sobre cada mortal antes de cortar seu fio, prática que suas colegas tecelãs descartavam como ineficiência sentimental, argumentando que o destino não exigia tal intimidade, apenas precisão.", "Foi durante a tecelagem de um fio particularmente obstinado, pertencente a um pescador que sobrevivera a três naufrágios aparentemente por pura recusa teimosa em se afogar, que Perenna hesitou pela primeira vez. O padrão que os outros fios sugeriam para ele era inequívoco, um quarto e último naufrágio dentro daquele mês, mas algo na própria trama parecia resistir à sua tesoura, como se o fio tivesse absorvido um pouco da própria teimosia do homem e pretendesse sobreviver ao seu julgamento. Ela pôs a tesoura de lado, ato sem precedentes entre as tecelãs, e decidiu observá-lo por mais algum tempo antes de prosseguir.", "As tecelãs mais antigas, ao descobrirem sua hesitação, reuniram-se para repreendê-la, insistindo que uma única exceção desfaria a coerência de toda a tapeçaria, que o destino não podia ser seletivamente adiado sem consequências para os fios entrelaçados ao dele. Perenna, impassível diante de um argumento que ouvira repetido havia séculos, apontou que o fio do pescador estava emaranhado de forma inextricável a dezenas de outros, o de uma esposa, o de uma filha, a frágil economia de toda uma vila, e que seu fim prematuro desfiaria muito mais do que resolveria. Ela propôs, em vez do corte, uma retecelagem, um fio mais longo comprado ao custo de sua própria influência diminuída entre as outras divindades.", "As anciãs, mais incomodadas com o precedente do que com a crueldade em si, por fim permitiram a exceção, em parte porque o argumento de Perenna era sólido e em parte porque nenhuma delas queria ser responsável pela discórdia que sua remoção dos teares causaria. O pescador viveu mais onze anos, tempo suficiente para ensinar seu ofício a um neto que, gerações depois, se tornaria o ancestral de uma linhagem de construtores de navios cujos barcos levariam vilas inteiras a salvo por tempestades que, na trama original, as teriam ceifado.", "Perenna nunca mais falou do incidente, embora as outras tecelãs tenham notado, nos anos seguintes, uma sutil mudança na maneira como manejavam suas próprias tesouras: uma fração a mais de hesitação, uma fração a mais de curiosidade sobre as vidas interrompidas por suas lâminas. Ela não havia revertido o destino, precisamente, apenas demonstrado, silenciosamente e a um custo pessoal considerável, que até o padrão mais rígido às vezes tolerava a intervenção de alguém disposto a olhar de perto o suficiente para perceber que aquilo importava."], "hard_words": ["obstinate", "shears", "inextricably", "fray", "severance", "precedent"], "vocab": [{"word": "loom", "meaning": "tear (instrumento de tecelagem)", "note": ""}, {"word": "obstinate", "meaning": "obstinado, teimoso", "note": ""}, {"word": "shears", "meaning": "tesoura grande", "note": ""}, {"word": "inextricably", "meaning": "inextricavelmente, de forma inseparável", "note": ""}, {"word": "fray", "meaning": "desfiar, desgastar", "note": ""}, {"word": "severance", "meaning": "corte, separação", "note": ""}, {"word": "precedent", "meaning": "precedente", "note": ""}, {"word": "unprecedented", "meaning": "sem precedentes, inédito", "note": ""}], "word_meanings": [{"word": "obstinate", "meaning": "obstinado, teimoso", "note": ""}, {"word": "shears", "meaning": "tesoura grande", "note": ""}, {"word": "inextricably", "meaning": "inextricavelmente", "note": ""}, {"word": "fray", "meaning": "desfiar, desgastar", "note": ""}, {"word": "severance", "meaning": "corte, separação", "note": ""}, {"word": "precedent", "meaning": "precedente", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": "falso amigo, listado como referência de cognato"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "set aside", "meaning": "pôs de lado", "note": "phrasal verb"}, {"word": "lived", "meaning": "viveu", "note": ""}, {"word": "spoke", "meaning": "falou", "note": "passado irregular de speak"}, {"word": "proposed", "meaning": "propôs", "note": ""}, {"word": "resolved", "meaning": "decidiu, resolveu", "note": ""}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "yet", "meaning": "porém, contudo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["lived", "spoke", "proposed", "resolved"], "phrasal": [], "wh": [], "connectors": ["though", "yet"], "comparative": []}, "exercises": {"grammar": [{"point": "Cleft sentences with 'It was... that'", "explanation_pt": "A frase 'It was during the weaving... that Perenna first hesitated' usa a estrutura clivada para enfatizar o momento exato do evento, recurso estilístico comum em narrativas elevadas de nível C2."}], "multiple_choice": [{"question": "What was Perenna's task among the weavers?", "options": ["Weaving the threads of the gods", "Guarding the loom", "Weaving each mortal's final year", "Cutting the elders' threads"], "correct_index": 2, "explanation": "Sua tarefa era tecer o fio do último ano de vida de cada mortal."}, {"question": "Why did Perenna hesitate over the fisherman's thread?", "options": ["She lost the shears", "The elders ordered her to stop", "She was tired", "Something in the weave seemed to resist her shears"], "correct_index": 3, "explanation": "Algo na trama parecia resistir à tesoura dela."}, {"question": "What argument did Perenna use to convince the elders?", "options": ["His thread was tangled with many others whose lives depended on his", "The fisherman was a god in disguise", "She simply refused to explain", "The elders owed her a favor"], "correct_index": 0, "explanation": "Ela argumentou que o fio dele estava emaranhado com muitos outros."}, {"question": "What did the fisherman's extra years lead to?", "options": ["Nothing significant", "A line of shipbuilders who later saved villages from storms", "His own death anyway", "A war"], "correct_index": 1, "explanation": "Ele teve tempo de formar uma linhagem de construtores de navios que salvaram vilas."}, {"question": "What changed among the other weavers after the incident?", "options": ["Nothing at all", "They banned Perenna from the looms", "They stopped weaving completely", "They became slightly more hesitant and curious about mortals' lives"], "correct_index": 3, "explanation": "Elas passaram a hesitar e se interessar um pouco mais pelas vidas dos mortais."}], "open_questions": [{"question": "Do you think Perenna was right to intervene in the fisherman's fate? Why or why not?", "key_points_pt": ["Considerar o impacto em outras vidas conectadas", "Refletir sobre compaixão versus ordem estabelecida"]}, {"question": "What does this myth suggest about the relationship between fate and individual choice?", "key_points_pt": ["Mesmo sistemas rígidos podem ter espaço para exceções", "Pequenos atos de cuidado podem ter grandes consequências"]}]}}, {"level": "C2", "genre": "timetravel", "title": "The Photograph That Wasn't", "paragraphs": ["When Theo inherited his grandmother's belongings, he expected sentimental clutter, not a photograph of himself standing beside her at what was unmistakably her twenty-fifth birthday party, a celebration that had occurred, according to every family record, four decades before he was born. He turned the photograph over repeatedly, half convinced it was some elaborate joke his cousins had engineered, though the sepia tone and the particular brittleness of the paper argued persuasively against forgery, as did his grandmother's unmistakably younger face, unlined in a way he had never once seen in life.", "The attic yielded further evidence, reluctantly: a journal, in handwriting he recognized as his own despite having no memory of writing it, describing a device his grandmother had apparently built in her youth and later dismantled, convinced that the risks of tampering with sequence outweighed any curiosity it might satisfy. The journal's final entry, dated some sixty years earlier, noted only that she intended to use it once more, deliberately, to attend her own birthday accompanied by a grandson not yet conceived, a decision she described as selfish and worth it in equal measure.", "Theo spent a disorienting week reconciling the plain fact of his own existence with a memory that did not exist, a day he had apparently lived that he could not recall living, and arrived eventually at an uneasy peace with the paradox by accepting that some experiences perhaps only became memories the second time they were lived, a theory he had no way of testing and every reason to suspect was simply his mind's attempt to impose order on the impossible.", "He found the device itself in a locked drawer, inert and clearly non-functional, its components corroded well past any hope of repair, exactly as the journal had described. Whether his grandmother had told the truth about dismantling it deliberately, or whether it had simply failed with age the way most instruments eventually do, Theo found he could not determine, and, more surprisingly, found he did not especially want to; some mysteries, he suspected, existed precisely so that families might have something to wonder about together across generations.", "He kept the photograph, framed, on his own mantelpiece, not as proof of anything he could explain to a skeptical relative, but as a private acknowledgment that his grandmother had, in some genuinely inexplicable way, chosen him before he existed, had traveled decades out of sequence specifically to stand beside a grandson she would not otherwise meet for half a century, and had apparently considered that impossible afternoon worth every risk it must have carried."], "paragraphs_pt": ["Quando Theo herdou os pertences da avó, esperava tralha sentimental, não uma fotografia de si mesmo ao lado dela na festa de vinte e cinco anos que, segundo todos os registros da família, acontecera quatro décadas antes de ele nascer. Ele virou a fotografia repetidas vezes, meio convencido de que se tratava de alguma brincadeira elaborada arquitetada pelos primos, embora o tom sépia e a fragilidade particular do papel argumentassem persuasivamente contra a falsificação, assim como o rosto inconfundivelmente mais jovem da avó, sem uma única ruga, de um jeito que ele nunca havia visto em vida.", "O sótão rendeu evidências adicionais, relutantemente: um diário, com uma caligrafia que ele reconheceu como sua própria apesar de não ter memória alguma de tê-lo escrito, descrevendo um dispositivo que sua avó aparentemente construíra na juventude e depois desmontara, convencida de que os riscos de mexer na sequência do tempo superavam qualquer curiosidade que pudessem satisfazer. A última anotação do diário, datada de cerca de sessenta anos antes, registrava apenas que ela pretendia usá-lo mais uma vez, deliberadamente, para comparecer ao próprio aniversário acompanhada de um neto ainda não concebido, decisão que ela descrevia como egoísta e válida em igual medida.", "Theo passou uma semana desorientadora conciliando o simples fato de sua própria existência com uma lembrança que não existia, um dia que ele aparentemente vivera mas não conseguia recordar ter vivido, e chegou, por fim, a uma paz incômoda com o paradoxo ao aceitar que algumas experiências talvez só se tornassem memórias na segunda vez em que eram vividas, uma teoria que ele não tinha como testar e todo motivo para suspeitar que fosse apenas a tentativa da própria mente de impor ordem ao impossível.", "Ele encontrou o próprio dispositivo numa gaveta trancada, inerte e claramente sem funcionar, os componentes corroídos além de qualquer esperança de reparo, exatamente como o diário descrevera. Se a avó dissera a verdade sobre tê-lo desmontado deliberadamente, ou se ele simplesmente falhara com o tempo como a maioria dos instrumentos acaba fazendo, Theo descobriu que não conseguia determinar, e, mais surpreendentemente, descobriu que não fazia questão especial de determinar; algumas coisas misteriosas, ele suspeitava, existiam precisamente para que famílias tivessem algo sobre o que se perguntar juntas ao longo das gerações.", "Ele guardou a fotografia, emoldurada, na própria lareira, não como prova de algo que pudesse explicar a um parente cético, mas como um reconhecimento particular de que sua avó havia, de alguma forma genuinamente inexplicável, escolhido a ele antes mesmo de ele existir, viajara décadas fora de sequência especificamente para ficar ao lado de um neto que, de outro modo, só conheceria meio século depois, e aparentemente considerara aquela tarde impossível válida por qualquer risco que deve ter carregado."], "hard_words": ["sepia", "brittleness", "dismantled", "corroded", "reconciling", "mantelpiece"], "vocab": [{"word": "sepia", "meaning": "sépia (tom marrom-alaranjado de fotos antigas)", "note": ""}, {"word": "brittleness", "meaning": "fragilidade, tendência a quebrar", "note": ""}, {"word": "dismantled", "meaning": "desmontou, desmantelou", "note": ""}, {"word": "corroded", "meaning": "corroído", "note": ""}, {"word": "reconciling", "meaning": "conciliando", "note": ""}, {"word": "mantelpiece", "meaning": "prateleira da lareira", "note": ""}, {"word": "tampering with", "meaning": "mexer indevidamente em, adulterar", "note": ""}, {"word": "uneasy", "meaning": "inquieto, desconfortável", "note": ""}], "word_meanings": [{"word": "sepia", "meaning": "sépia", "note": ""}, {"word": "brittleness", "meaning": "fragilidade", "note": ""}, {"word": "dismantled", "meaning": "desmontou", "note": ""}, {"word": "corroded", "meaning": "corroído", "note": ""}, {"word": "reconciling", "meaning": "conciliando", "note": ""}, {"word": "mantelpiece", "meaning": "prateleira da lareira", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": ""}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "found", "meaning": "encontrou", "note": "passado irregular de find"}, {"word": "kept", "meaning": "guardou/manteve", "note": "passado irregular de keep"}, {"word": "spent", "meaning": "passou (tempo)", "note": "passado irregular de spend"}, {"word": "turned", "meaning": "virou", "note": ""}, {"word": "tampering with", "meaning": "mexer indevidamente em", "note": "phrasal-like verb"}, {"word": "whether", "meaning": "se (dúvida)", "note": ""}, {"word": "though", "meaning": "embora", "note": ""}], "grammar_words": {"cognates": ["eventually"], "tobe": ["was", "were"], "irregular": ["found", "kept", "spent", "turned"], "phrasal": ["tampering with"], "wh": ["whether"], "connectors": ["though"], "comparative": []}, "exercises": {"grammar": [{"point": "Mixed conditionals and hypothetical past", "explanation_pt": "A narrativa usa estruturas hipotéticas complexas, como 'a grandson not yet conceived', combinando tempos para expressar situações logicamente impossíveis, típico de textos sofisticados em nível C2."}], "multiple_choice": [{"question": "What did Theo find among his grandmother's belongings?", "options": ["A love letter", "Old money", "A map", "A photograph of himself at her 25th birthday, decades before he was born"], "correct_index": 3, "explanation": "Ele encontrou uma foto de si mesmo na festa de 25 anos da avó."}, {"question": "What did the journal in the attic describe?", "options": ["A recipe book", "A family tree", "A time-travel device his grandmother built and later dismantled", "A diary of her childhood"], "correct_index": 2, "explanation": "O diário descrevia um dispositivo de viagem no tempo."}, {"question": "How did Theo come to terms with the impossible memory?", "options": ["He ignored it completely", "He accepted a theory that some experiences become memories only the second time they're lived", "He destroyed the photograph", "He asked his grandmother directly"], "correct_index": 1, "explanation": "Ele aceitou a teoria de que algumas experiências só viram memória na segunda vez."}, {"question": "What condition was the device in when Theo found it?", "options": ["Inert and corroded beyond repair", "Fully functional", "Missing entirely", "Brand new"], "correct_index": 0, "explanation": "O dispositivo estava inerte e corroído."}, {"question": "What did Theo do with the photograph in the end?", "options": ["He threw it away", "He sold it", "He framed it and kept it on his mantelpiece", "He gave it to a museum"], "correct_index": 2, "explanation": "Ele a emoldurou e a manteve na lareira."}], "open_questions": [{"question": "Why do you think Theo's grandmother described her choice as 'selfish and worth it in equal measure'?", "key_points_pt": ["Ela alterou a sequência do tempo por motivos pessoais e emocionais", "Reconhece o risco, mas valoriza a conexão com o neto"]}, {"question": "If you had a device like this, would you use it to meet a future family member? Why or why not?", "key_points_pt": ["Resposta pessoal livre", "Pode considerar riscos, ética e curiosidade"]}]}}, {"level": "C2", "genre": "slice", "title": "Sunday Mending", "paragraphs": ["Every Sunday for as long as her children could remember, Ines set up her sewing basket on the porch and mended whatever had accumulated during the week, a habit that had long since outlived any strict financial necessity but persisted regardless, partly out of thrift and partly, she suspected, because the repetitive motion of needle through fabric emptied her mind in a way meditation apps had repeatedly failed to achieve. Her son, now grown and visiting for the weekend with his own small daughter in tow, found the ritual almost anachronistic, the sort of domestic patience that his own generation had largely outsourced to convenience.", "The granddaughter, four years old and instinctively drawn to anything her grandmother did with such evident absorption, planted herself on the porch steps and demanded, with the imperious confidence unique to small children, to be taught. Ines, secretly delighted though she would never have admitted it outright, produced a spare needle, threaded it with exaggerated patience, and guided small fingers through a stitch clumsy enough to unravel within the hour, though neither of them seemed particularly troubled by its impermanence.", "Her son watched from the doorway with an expression Ines recognized, a mixture of nostalgia and mild guilt, the particular look of someone realizing he had let a skill lapse that his own mother still practiced weekly without complaint. He admitted, somewhat sheepishly, that he generally just replaced torn clothing rather than mending it, a confession Ines received without judgment, having long ago decided that criticizing her children's practical choices accomplished considerably less than simply modeling her own.", "By late afternoon, the granddaughter had produced a wildly uneven line of stitches across a handkerchief destined for no practical purpose whatsoever, and had declared, with the absolute conviction of the very young, that she intended to sew every Sunday for the rest of her life, a promise Ines received with the fond skepticism of someone who had heard equally passionate four-year-old declarations dissolve by the following weekend.", "Still, as she packed the sewing basket away that evening, Ines found herself thinking less about whether the habit would survive her granddaughter's shifting enthusiasms and more about the simple fact of the afternoon itself, three generations arranged loosely around a porch, needle and thread passing quite literally from one pair of hands to another, regardless of what, if anything, would ultimately be made of it."], "paragraphs_pt": ["Todo domingo, desde que seus filhos conseguiam se lembrar, Ines montava a cesta de costura na varanda e consertava o que se acumulara durante a semana, um hábito que havia muito superara qualquer necessidade financeira estrita, mas persistia mesmo assim, em parte por economia e em parte, ela suspeitava, porque o movimento repetitivo da agulha atravessando o tecido esvaziava sua mente de um jeito que aplicativos de meditação repetidamente não conseguiam alcançar. O filho, já adulto e visitando no fim de semana com a própria filha pequena, achava o ritual quase anacrônico, o tipo de paciência doméstica que sua própria geração em grande parte terceirizara em nome da conveniência.", "A neta, de quatro anos e instintivamente atraída por qualquer coisa que a avó fizesse com tamanha absorção evidente, plantou-se nos degraus da varanda e exigiu, com a confiança imperiosa peculiar das crianças pequenas, ser ensinada. Ines, secretamente encantada, embora jamais fosse admitir isso abertamente, tirou uma agulha sobressalente, enfiou a linha com paciência exagerada, e guiou os dedinhos por um ponto desajeitado o suficiente para se desfazer dentro de uma hora, embora nenhuma das duas parecesse particularmente incomodada com sua impermanência.", "O filho observava da porta com uma expressão que Ines reconheceu, uma mistura de nostalgia e leve culpa, o olhar particular de alguém percebendo que deixara uma habilidade se perder que a própria mãe ainda praticava semanalmente sem reclamar. Ele admitiu, um tanto encabulado, que geralmente apenas substituía roupas rasgadas em vez de consertá-las, uma confissão que Ines recebeu sem julgamento, tendo decidido havia muito tempo que criticar as escolhas práticas dos filhos realizava consideravelmente menos do que simplesmente modelar as próprias.", "No fim da tarde, a neta havia produzido uma linha de pontos extremamente irregular num lenço destinado a propósito prático nenhum, e declarara, com a convicção absoluta dos muito jovens, que pretendia costurar todo domingo pelo resto da vida, promessa que Ines recebeu com o ceticismo carinhoso de quem já ouvira declarações igualmente apaixonadas de crianças de quatro anos se dissolverem antes do fim de semana seguinte.", "Ainda assim, ao guardar a cesta de costura naquela noite, Ines se viu pensando menos sobre se o hábito sobreviveria aos entusiasmos mutáveis da neta e mais sobre o simples fato daquela tarde em si, três gerações reunidas frouxamente numa varanda, agulha e linha passando bem literalmente de um par de mãos para outro, independentemente do que, se é que algo, viesse a ser feito com aquilo no fim."], "hard_words": ["anachronistic", "imperious", "sheepishly", "lapse", "impermanence", "skepticism"], "vocab": [{"word": "thrift", "meaning": "economia, poupança", "note": ""}, {"word": "anachronistic", "meaning": "anacrônico, fora de época", "note": ""}, {"word": "imperious", "meaning": "imperioso, autoritário", "note": ""}, {"word": "sheepishly", "meaning": "encabuladamente, timidamente", "note": ""}, {"word": "lapse", "meaning": "deixar cair em desuso, lapso", "note": ""}, {"word": "impermanence", "meaning": "impermanência", "note": ""}, {"word": "skepticism", "meaning": "ceticismo", "note": ""}, {"word": "loosely", "meaning": "frouxamente, de forma solta", "note": ""}], "word_meanings": [{"word": "anachronistic", "meaning": "anacrônico", "note": ""}, {"word": "imperious", "meaning": "imperioso", "note": ""}, {"word": "sheepishly", "meaning": "encabuladamente", "note": ""}, {"word": "lapse", "meaning": "deixar cair em desuso", "note": ""}, {"word": "impermanence", "meaning": "impermanência", "note": ""}, {"word": "skepticism", "meaning": "ceticismo", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo, listado como referência"}, {"word": "eventually", "meaning": "finalmente", "note": "falso amigo, listado como referência"}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "set up", "meaning": "montou, organizou", "note": "phrasal verb"}, {"word": "found herself", "meaning": "se viu/se percebeu", "note": "expressão idiomática"}, {"word": "produced", "meaning": "produziu", "note": ""}, {"word": "admitted", "meaning": "admitiu", "note": ""}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "regardless of", "meaning": "independentemente de", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["set up", "found herself", "produced", "admitted"], "phrasal": ["set up", "found herself"], "wh": [], "connectors": ["though", "regardless of"], "comparative": []}, "exercises": {"grammar": [{"point": "Present participle clauses for background action", "explanation_pt": "Orações reduzidas com gerúndio, como 'having long ago decided', condensam informação de fundo sem criar uma nova oração completa, recurso típico de prosa elegante em nível C2."}], "multiple_choice": [{"question": "What does Ines do every Sunday?", "options": ["Mends clothes on the porch", "Bakes bread", "Goes to church", "Cleans the house"], "correct_index": 0, "explanation": "Ela conserta roupas na varanda todo domingo."}, {"question": "Why does Ines continue this habit even though it isn't financially necessary?", "options": ["She has no other hobbies", "Her family demands it", "The repetitive motion calms her mind", "She sells the mended clothes"], "correct_index": 2, "explanation": "O movimento repetitivo esvazia sua mente de um jeito que meditação não conseguia."}, {"question": "What does the granddaughter ask to be taught?", "options": ["Cooking", "Sewing", "Reading", "Gardening"], "correct_index": 1, "explanation": "Ela pede para ser ensinada a costurar."}, {"question": "What does Ines's son admit about his own habits?", "options": ["He mends everything himself", "He never wears torn clothes", "He hates sewing", "He usually just replaces torn clothing instead of mending it"], "correct_index": 3, "explanation": "Ele admite que geralmente só substitui roupas rasgadas."}, {"question": "What does Ines mainly reflect on at the end of the story?", "options": ["The moment itself, three generations together", "Whether the habit will survive", "Her financial situation", "Her son's career"], "correct_index": 0, "explanation": "Ela pensa principalmente no momento em si, com três gerações reunidas."}], "open_questions": [{"question": "Why do you think Ines doesn't criticize her son for not mending his own clothes?", "key_points_pt": ["Ela prefere modelar comportamentos a criticar escolhas alheias", "Reconhece que gerações diferentes têm hábitos diferentes"]}, {"question": "Do you have a habit or skill passed down from an older family member? Describe it.", "key_points_pt": ["Resposta pessoal livre", "Pode mencionar tradições familiares e seu valor emocional"]}]}}, {"level": "C2", "genre": "interview", "title": "Questions Worth Asking", "paragraphs": ["By the time Farid reached his ninth interview for the same fellowship, he had grown so accustomed to reciting his qualifications that he could recite them, he suspected, in his sleep, a fluency that had somehow curdled into a kind of hollow rehearsedness he worried interviewers could detect immediately. The panel that afternoon consisted of three researchers whose published work he had studied obsessively, and he entered the room bracing himself for the same predictable sequence of questions about strengths, weaknesses, and long-term goals that had, in eight prior attempts, yielded eight polite rejections.", "The interview began conventionally enough, though the youngest panelist, rather than asking about his greatest weakness, asked instead what question he wished interviewers would stop asking, a query so unexpected that Farid's rehearsed composure faltered entirely, and he found himself answering honestly rather than strategically for what felt like the first time in months. He admitted, somewhat to his own surprise, that he was tired of being asked to quantify passion, as though genuine intellectual curiosity could be reduced to a percentage without becoming something else entirely, something hollowed out and unrecognizable.", "The panel exchanged a brief, unreadable glance that Farid initially interpreted as disapproval, bracing himself for the interview's premature and awkward conclusion, but the senior researcher instead leaned forward with what he eventually recognized as genuine interest and asked him to elaborate, an invitation that led, over the following twenty minutes, to the most substantive conversation Farid had had in any interview that year, ranging unpredictably from his actual research interests to a shared frustration with how academic funding incentivized exactly the wrong qualities in early-career researchers.", "He left the building uncertain, as always, whether he had secured the fellowship, but aware of something he hadn't anticipated feeling after any of his previous attempts: a distinct sense of having been genuinely seen rather than merely evaluated, regardless of the outcome. The rehearsed answers he had polished for months suddenly felt, in retrospect, like armor he had been wearing unnecessarily, protecting a version of himself considerably less interesting than the one the interview had eventually allowed to surface.", "The offer arrived nine days later, accompanied by a brief note from the senior researcher remarking that the committee had, for once, been more persuaded by an honest complaint than by any rehearsed enthusiasm, a comment Farid read several times, slowly coming to understand that the questions worth answering honestly were rarely the ones he had spent months preparing for, but the ones that caught him, deliberately or not, off guard."], "paragraphs_pt": ["Quando Farid chegou à sua nona entrevista para a mesma bolsa, já estava tão acostumado a recitar suas qualificações que suspeitava conseguir fazê-lo até dormindo, uma fluência que de alguma forma azedara numa espécie de ensaio oco que ele temia que os entrevistadores detectassem imediatamente. A banca daquela tarde era composta por três pesquisadores cujos trabalhos publicados ele estudara obsessivamente, e ele entrou na sala se preparando para a mesma sequência previsível de perguntas sobre pontos fortes, pontos fracos e objetivos de longo prazo que, em oito tentativas anteriores, haviam rendido oito recusas educadas.", "A entrevista começou de forma bastante convencional, embora a integrante mais jovem da banca, em vez de perguntar sobre seu maior ponto fraco, perguntasse qual pergunta ele gostaria que os entrevistadores parassem de fazer, uma pergunta tão inesperada que a compostura ensaiada de Farid falhou completamente, e ele se viu respondendo com honestidade, em vez de estrategicamente, pela primeira vez em meses, pelo menos era o que sentia. Ele admitiu, para sua própria surpresa, que estava cansado de ser solicitado a quantificar paixão, como se a curiosidade intelectual genuína pudesse ser reduzida a uma porcentagem sem se tornar algo completamente diferente, algo esvaziado e irreconhecível.", "A banca trocou um breve olhar indecifrável que Farid a princípio interpretou como reprovação, preparando-se para o fim prematuro e constrangedor da entrevista, mas o pesquisador sênior, em vez disso, inclinou-se para a frente com o que ele acabou reconhecendo como interesse genuíno e pediu que elaborasse melhor, um convite que levou, ao longo dos vinte minutos seguintes, à conversa mais substancial que Farid tivera em qualquer entrevista naquele ano, passando de forma imprevisível de seus verdadeiros interesses de pesquisa a uma frustração compartilhada sobre como o financiamento acadêmico incentivava exatamente as qualidades erradas em pesquisadores no início de carreira.", "Ele saiu do prédio incerto, como sempre, se conseguira a bolsa, mas consciente de algo que não esperava sentir depois de nenhuma de suas tentativas anteriores: uma nítida sensação de ter sido genuinamente visto, em vez de meramente avaliado, independentemente do resultado. As respostas ensaiadas que polira durante meses de repente pareceram, em retrospecto, uma armadura que ele vinha usando desnecessariamente, protegendo uma versão de si mesmo consideravelmente menos interessante do que aquela que a entrevista finalmente permitira emergir.", "A proposta chegou nove dias depois, acompanhada de um bilhete breve do pesquisador sênior observando que o comitê havia, por uma vez, se deixado convencer mais por uma reclamação honesta do que por qualquer entusiasmo ensaiado, comentário que Farid releu várias vezes, compreendendo aos poucos que as perguntas que valia a pena responder com honestidade raramente eram aquelas para as quais ele passara meses se preparando, mas sim aquelas que o pegavam, deliberadamente ou não, desprevenido."], "hard_words": ["curdled", "faltered", "unreadable", "substantive", "retrospect", "unrecognizable"], "vocab": [{"word": "curdled", "meaning": "azedou, talhou (fig.: degenerou)", "note": ""}, {"word": "faltered", "meaning": "vacilou, falhou", "note": ""}, {"word": "unreadable", "meaning": "indecifrável", "note": ""}, {"word": "substantive", "meaning": "substancial, significativo", "note": ""}, {"word": "retrospect", "meaning": "retrospecto, olhando para trás", "note": ""}, {"word": "off guard", "meaning": "desprevenido, de surpresa", "note": ""}, {"word": "bracing himself", "meaning": "se preparando (para algo difícil)", "note": ""}, {"word": "quantify", "meaning": "quantificar", "note": ""}], "word_meanings": [{"word": "curdled", "meaning": "azedou, degenerou", "note": ""}, {"word": "faltered", "meaning": "vacilou", "note": ""}, {"word": "unreadable", "meaning": "indecifrável", "note": ""}, {"word": "substantive", "meaning": "substancial", "note": ""}, {"word": "retrospect", "meaning": "retrospecto", "note": ""}, {"word": "unrecognizable", "meaning": "irreconhecível", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": ""}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "began", "meaning": "começou", "note": "passado irregular de begin"}, {"word": "left", "meaning": "saiu/deixou", "note": "passado irregular de leave"}, {"word": "arrived", "meaning": "chegou", "note": ""}, {"word": "found himself", "meaning": "se viu/se percebeu", "note": "expressão idiomática"}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "regardless of", "meaning": "independentemente de", "note": ""}], "grammar_words": {"cognates": ["eventually"], "tobe": ["was", "were"], "irregular": ["began", "left", "arrived", "found himself"], "phrasal": ["found himself"], "wh": [], "connectors": ["though", "regardless of"], "comparative": []}, "exercises": {"grammar": [{"point": "Reduced relative and participle clauses", "explanation_pt": "Frases como 'a query so unexpected that Farid's composure faltered' e 'protecting a version of himself' usam construções reduzidas para adicionar informação de forma compacta, típicas de escrita sofisticada em C2."}], "multiple_choice": [{"question": "How many interviews had Farid attended before this one for the same fellowship?", "options": ["Eight", "Five", "Nine", "Two"], "correct_index": 0, "explanation": "Esta era sua nona entrevista, então havia tido oito anteriores."}, {"question": "What unusual question did the youngest panelist ask?", "options": ["About his weaknesses", "What question he wished interviewers would stop asking", "About his salary expectations", "About his hobbies"], "correct_index": 1, "explanation": "Ela perguntou qual pergunta ele gostaria que parassem de fazer."}, {"question": "What was Farid's honest complaint about?", "options": ["Low pay in academia", "Too many interviews", "Being asked to quantify passion", "Difficult panelists"], "correct_index": 2, "explanation": "Ele reclamou de ser solicitado a quantificar paixão."}, {"question": "How did the senior researcher react to Farid's honest answer?", "options": ["With visible disapproval", "By ending the interview early", "By ignoring it", "With genuine interest, asking him to elaborate"], "correct_index": 3, "explanation": "O pesquisador sênior mostrou interesse genuíno e pediu que ele elaborasse."}, {"question": "What did the committee's note say about their decision?", "options": ["They were unimpressed by him", "They were more persuaded by his honest complaint than by rehearsed enthusiasm", "They chose him randomly", "They needed more interviews"], "correct_index": 1, "explanation": "A nota dizia que se convenceram mais por uma reclamação honesta."}], "open_questions": [{"question": "Why do you think Farid's honest answer worked better than his rehearsed ones?", "key_points_pt": ["Autenticidade pode se destacar mais que respostas decoradas", "Mostra personalidade real ao entrevistador"]}, {"question": "What is a question you wish interviewers would stop asking, and why?", "key_points_pt": ["Resposta pessoal livre", "Pode mencionar perguntas clichês ou pouco reveladoras"]}]}}, {"level": "C2", "genre": "horror", "title": "The Attic Door", "paragraphs": ["The previous owners had mentioned the attic door only in passing, an offhand remark about a warped frame that occasionally stuck, and Marcus had dismissed it as the sort of minor inconvenience every old house accumulated, the kind of detail realtors buried in disclosures precisely because it seemed too trivial to alarm anyone. It was only in his third week in the house that he noticed the door never stuck when he approached it during the day, only ever after dark, and only when he was, as far as he could determine, entirely alone.", "He told himself, with the particular insistence of someone trying to out-argue his own unease, that the discrepancy was almost certainly a matter of temperature, wood contracting and expanding as the house cooled overnight, a perfectly reasonable explanation that nonetheless failed to account for the sound he occasionally heard afterward, a faint, deliberate scraping from above that ceased the instant he paused to listen for it, as though whatever produced it understood the difference between being heard and being caught listening.", "Curiosity, or perhaps simple exhaustion with his own escalating imagination, eventually drove him to force the door open one evening despite its resistance, flashlight in hand, bracing himself for something he couldn't quite name and privately hoping to find nothing more sinister than a family of raccoons that had taken up unauthorized residence. The attic was empty, unremarkable, thick with the ordinary dust of decades, save for a single detail that took him considerably longer to notice than it should have: a narrow, unbroken path swept clean through that dust, leading directly from the door to the far wall, where nothing visible stood to explain its destination.", "He told himself, walking that path with his flashlight trembling more than he cared to admit, that dust settled unevenly all the time, that drafts and old insulation could produce a hundred mundane explanations he simply hadn't considered yet, a litany of reassurance that dissolved entirely the moment his light caught a section of the far wall subtly discolored in the precise outline of a doorway that, according to every plan of the house he had reviewed before purchase, did not exist.", "Marcus did not investigate the discolored wall that night, nor, he told himself firmly, would he investigate it the following morning, a resolution he maintained with reasonable success until roughly four in the afternoon, when he found himself standing before it anyway, hammer in hand, unable to fully articulate why leaving a swept path and an outlined door unexamined felt, on reflection, considerably more frightening than whatever he might actually find behind it."], "paragraphs_pt": ["Os antigos donos haviam mencionado a porta do sótão apenas de passagem, um comentário casual sobre um caixilho empenado que às vezes emperrava, e Marcus descartara aquilo como o tipo de inconveniente menor que toda casa velha acumula, o tipo de detalhe que corretores enterram em divulgações justamente por parecer trivial demais para alarmar alguém. Foi só na terceira semana na casa que ele notou que a porta nunca emperrava quando ele se aproximava durante o dia, só depois de escurecer, e só quando ele estava, até onde conseguia determinar, completamente sozinho.", "Ele dizia a si mesmo, com a insistência particular de quem tenta argumentar contra o próprio desconforto, que a discrepância era quase certamente uma questão de temperatura, a madeira se contraindo e se expandindo enquanto a casa esfriava durante a noite, uma explicação perfeitamente razoável que, no entanto, não dava conta do som que ele às vezes ouvia depois, um raspado fraco e deliberado vindo de cima, que cessava no instante em que ele parava para prestar atenção, como se o que quer que o produzisse compreendesse a diferença entre ser ouvido e ser flagrado escutando.", "Curiosidade, ou talvez simples exaustão com a própria imaginação em escalada, por fim o levou a forçar a porta certa noite, apesar da resistência dela, lanterna em mãos, preparando-se para algo que não conseguia nomear direito e torcendo em segredo para não encontrar nada mais sinistro que uma família de guaxinins morando ali sem autorização. O sótão estava vazio, nada notável, coberto pela poeira comum de décadas, exceto por um único detalhe que ele demorou bem mais do que deveria para notar: um caminho estreito e ininterrupto varrido através daquela poeira, indo direto da porta até a parede do fundo, onde nada visível explicava seu destino.", "Ele dizia a si mesmo, caminhando por aquele trajeto com a lanterna tremendo mais do que gostaria de admitir, que a poeira se acumulava de forma irregular o tempo todo, que correntes de ar e isolamento velho podiam produzir uma centena de explicações banais que ele simplesmente ainda não havia considerado, uma litania de consolo que se dissolveu por completo no instante em que sua luz revelou uma seção da parede do fundo sutilmente descolorida no contorno preciso de uma porta que, segundo toda planta da casa que ele revisara antes da compra, não existia.", "Marcus não investigou a parede descolorida naquela noite, nem, disse a si mesmo com firmeza, a investigaria na manhã seguinte, resolução que manteve com razoável sucesso até por volta das quatro da tarde, quando se viu parado diante dela mesmo assim, martelo em mãos, incapaz de articular plenamente por que deixar um caminho varrido e uma porta contornada sem investigação parecia, pensando bem, consideravelmente mais assustador do que qualquer coisa que pudesse realmente encontrar atrás dela."], "hard_words": ["warped", "discrepancy", "scraping", "litany", "discolored", "unremarkable"], "vocab": [{"word": "warped", "meaning": "empenado, deformado", "note": ""}, {"word": "discrepancy", "meaning": "discrepância", "note": ""}, {"word": "scraping", "meaning": "raspado, som de arranhão", "note": ""}, {"word": "litany", "meaning": "litania (fig.: lista repetitiva)", "note": ""}, {"word": "discolored", "meaning": "descolorido, manchado", "note": ""}, {"word": "unremarkable", "meaning": "nada notável, comum", "note": ""}, {"word": "bracing himself", "meaning": "se preparando (para algo difícil)", "note": ""}, {"word": "take up residence", "meaning": "fixar residência, se instalar", "note": ""}], "word_meanings": [{"word": "warped", "meaning": "empenado", "note": ""}, {"word": "discrepancy", "meaning": "discrepância", "note": ""}, {"word": "scraping", "meaning": "raspado", "note": ""}, {"word": "litany", "meaning": "litania, lista repetitiva", "note": ""}, {"word": "discolored", "meaning": "descolorido", "note": ""}, {"word": "unremarkable", "meaning": "nada notável", "note": ""}, {"word": "actually", "meaning": "na verdade", "note": "falso amigo"}, {"word": "eventually", "meaning": "finalmente", "note": ""}, {"word": "was", "meaning": "era/estava", "note": ""}, {"word": "were", "meaning": "eram/estavam", "note": ""}, {"word": "told", "meaning": "disse/contou", "note": "passado irregular de tell"}, {"word": "heard", "meaning": "ouviu", "note": "passado irregular de hear"}, {"word": "found himself", "meaning": "se viu/se percebeu", "note": "expressão idiomática"}, {"word": "drove", "meaning": "levou/dirigiu (fig.: impeliu)", "note": "passado irregular de drive"}, {"word": "though", "meaning": "embora", "note": ""}, {"word": "as though", "meaning": "como se", "note": ""}, {"word": "take up residence", "meaning": "fixar residência, se instalar", "note": ""}], "grammar_words": {"cognates": ["actually", "eventually"], "tobe": ["was"], "irregular": ["told", "heard", "found himself", "drove"], "phrasal": ["found himself"], "wh": [], "connectors": ["though", "as though"], "comparative": []}, "exercises": {"grammar": [{"point": "'As though' + past simple for hypothetical comparison", "explanation_pt": "A estrutura 'as though whatever produced it understood' usa o passado simples após 'as though' para expressar uma comparação hipotética não real, recurso comum em narrativas de suspense/horror em nível C2."}], "multiple_choice": [{"question": "When did the attic door only stick, according to Marcus's observation?", "options": ["Only during the day", "Only after dark, when he was alone", "Only on weekends", "Only in winter"], "correct_index": 1, "explanation": "A porta só emperrava depois de escurecer e quando ele estava sozinho."}, {"question": "What sound did Marcus sometimes hear?", "options": ["A faint, deliberate scraping that stopped when he listened", "Music", "Voices", "Footsteps outside"], "correct_index": 0, "explanation": "Ele ouvia um raspado fraco que cessava quando ele parava para escutar."}, {"question": "What did Marcus find in the attic dust?", "options": ["Animal tracks", "Old furniture", "Nothing unusual", "A narrow swept path leading to the far wall"], "correct_index": 3, "explanation": "Ele encontrou um caminho estreito varrido na poeira."}, {"question": "What did Marcus notice on the far wall?", "options": ["A window", "A painting", "A discolored outline of a doorway that shouldn't exist", "Nothing at all"], "correct_index": 2, "explanation": "Ele notou o contorno de uma porta descolorida que não constava nas plantas da casa."}, {"question": "What did Marcus do at the end of the story?", "options": ["He found himself standing before the wall with a hammer", "He called the police", "He moved out immediately", "He ignored it forever"], "correct_index": 0, "explanation": "Ele se viu diante da parede com um martelo na mão."}], "open_questions": [{"question": "Why do you think Marcus felt more afraid of ignoring the mystery than of investigating it?", "key_points_pt": ["O desconhecido não resolvido pode ser mais perturbador que o confronto direto", "A curiosidade humana muitas vezes supera o medo"]}, {"question": "What do you think Marcus will find behind the discolored wall? Why?", "key_points_pt": ["Resposta pessoal livre e especulativa", "Pode basear-se nas pistas de suspense do texto"]}]}}, {"level": "A1", "genre": "adventure", "title": "The Red Kite", "paragraphs": ["Leo has a red kite. It is big and beautiful. He goes to the hill with his sister Mia.", "The wind is strong today. Leo runs and the kite goes up, up, up. Mia laughs and claps her hands.", "Then the wind stops. The kite falls into a tree. Leo is sad, but Mia climbs the tree and gets it. They are happy again."], "paragraphs_pt": ["Leo tem uma pipa vermelha. Ela é grande e bonita. Ele vai ao morro com a irmã, Mia.", "O vento está forte hoje. Leo corre e a pipa sobe, sobe, sobe. Mia ri e bate palmas.", "Então o vento para. A pipa cai numa árvore. Leo fica triste, mas Mia sobe na árvore e pega a pipa. Eles ficam felizes de novo."], "hard_words": ["kite", "hill", "wind", "climbs"], "vocab": [{"word": "kite", "meaning": "pipa", "note": ""}, {"word": "hill", "meaning": "morro", "note": ""}, {"word": "wind", "meaning": "vento", "note": ""}, {"word": "strong", "meaning": "forte", "note": ""}, {"word": "laughs", "meaning": "ri", "note": ""}, {"word": "claps", "meaning": "bate palmas", "note": ""}, {"word": "falls", "meaning": "cai", "note": ""}, {"word": "tree", "meaning": "árvore", "note": ""}, {"word": "climbs", "meaning": "sobe (escala)", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "but", "then"], "comparative": []}, "word_meanings": [{"word": "kite", "meaning": "pipa", "note": ""}, {"word": "hill", "meaning": "morro", "note": ""}, {"word": "wind", "meaning": "vento", "note": ""}, {"word": "strong", "meaning": "forte", "note": ""}, {"word": "laughs", "meaning": "ri", "note": ""}, {"word": "claps", "meaning": "bate palmas", "note": ""}, {"word": "falls", "meaning": "cai", "note": ""}, {"word": "tree", "meaning": "árvore", "note": ""}, {"word": "climbs", "meaning": "sobe (escala)", "note": ""}], "exercises": {"grammar": [{"point": "Present simple (he/she)", "explanation_pt": "Com he/she/it o verbo ganha -s: 'Leo runs', 'Mia laughs', 'she climbs'."}], "multiple_choice": [{"question": "What color is Leo's kite?", "options": ["Red", "Green", "Yellow", "Blue"], "correct_index": 0, "explanation": "A pipa de Leo é vermelha."}, {"question": "Who goes to the hill with Leo?", "options": ["His sister Mia", "His mother", "His friend Tom", "His dog"], "correct_index": 0, "explanation": "Leo vai com a irmã, Mia."}, {"question": "What does the wind do at the end?", "options": ["It gets stronger", "It stops", "It brings rain", "It takes Mia away"], "correct_index": 1, "explanation": "No fim o vento para."}, {"question": "Where does the kite fall?", "options": ["Into a tree", "Into a river", "On the road", "On a house"], "correct_index": 0, "explanation": "A pipa cai numa árvore."}, {"question": "Who gets the kite?", "options": ["Leo", "A boy", "A bird", "Mia"], "correct_index": 3, "explanation": "Mia sobe na árvore e pega a pipa."}], "open_questions": [{"question": "Do you like to play outside? What do you do?", "key_points_pt": ["citar uma atividade ao ar livre", "usar frases curtas no presente"]}, {"question": "Is Mia a good sister? Why?", "key_points_pt": ["dizer que sim e explicar que ela ajuda Leo", "usar 'she' + verbo com -s"]}]}}, {"level": "A1", "genre": "adventure", "title": "A Day in the Forest", "paragraphs": ["Sam and his dad go to the forest. They have a map, water and sandwiches. The forest is quiet and green.", "They walk on a small path. Sam sees a rabbit and a bird. \"Look, Dad!\" he says. His dad takes a photo.", "At noon they sit by a river. They eat their sandwiches and drink water. Sam says, \"This is the best day!\""], "paragraphs_pt": ["Sam e o pai vão à floresta. Eles têm um mapa, água e sanduíches. A floresta é silenciosa e verde.", "Eles andam por uma trilha pequena. Sam vê um coelho e um pássaro. \"Olha, pai!\", ele diz. O pai tira uma foto.", "Ao meio-dia eles sentam perto de um rio. Comem os sanduíches e bebem água. Sam diz: \"Este é o melhor dia!\""], "hard_words": ["forest", "path", "rabbit", "noon"], "vocab": [{"word": "forest", "meaning": "floresta", "note": ""}, {"word": "map", "meaning": "mapa", "note": ""}, {"word": "path", "meaning": "trilha, caminho", "note": ""}, {"word": "rabbit", "meaning": "coelho", "note": ""}, {"word": "bird", "meaning": "pássaro", "note": ""}, {"word": "river", "meaning": "rio", "note": ""}, {"word": "noon", "meaning": "meio-dia", "note": ""}, {"word": "quiet", "meaning": "silencioso", "note": ""}, {"word": "photo", "meaning": "foto", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "forest", "meaning": "floresta", "note": ""}, {"word": "map", "meaning": "mapa", "note": ""}, {"word": "path", "meaning": "trilha, caminho", "note": ""}, {"word": "rabbit", "meaning": "coelho", "note": ""}, {"word": "bird", "meaning": "pássaro", "note": ""}, {"word": "river", "meaning": "rio", "note": ""}, {"word": "noon", "meaning": "meio-dia", "note": ""}, {"word": "quiet", "meaning": "silencioso", "note": ""}, {"word": "photo", "meaning": "foto", "note": ""}], "exercises": {"grammar": [{"point": "There is / They have", "explanation_pt": "'They have a map' mostra posse no plural: I/you/we/they + have. Com he/she/it usamos has."}], "multiple_choice": [{"question": "Where do Sam and his dad go?", "options": ["To the forest", "To school", "To the city", "To the beach"], "correct_index": 0, "explanation": "Eles vão à floresta."}, {"question": "What do they have?", "options": ["A dog and a ball", "A car and a phone", "A tent and a boat", "A map, water and sandwiches"], "correct_index": 3, "explanation": "Eles levam mapa, água e sanduíches."}, {"question": "What animals does Sam see?", "options": ["A rabbit and a bird", "A fish and a cat", "A bear and a wolf", "A horse and a cow"], "correct_index": 0, "explanation": "Ele vê um coelho e um pássaro."}, {"question": "What does Dad do?", "options": ["He sings a song", "He sleeps", "He takes a photo", "He reads a book"], "correct_index": 2, "explanation": "O pai tira uma foto."}, {"question": "Where do they eat?", "options": ["In a restaurant", "In a car", "By a river", "At home"], "correct_index": 2, "explanation": "Eles comem perto de um rio."}], "open_questions": [{"question": "What do you take on a trip to the forest?", "key_points_pt": ["citar itens como água, comida, mapa", "usar 'I take'"]}, {"question": "Do you like quiet places? Why?", "key_points_pt": ["responder com 'I like' ou 'I don't like' e um motivo simples"]}]}}, {"level": "A2", "genre": "adventure", "title": "Lost in the Mountains", "paragraphs": ["Carla and her friend Jon decided to walk to a lake in the mountains. The morning was sunny, so they took only a small bag with water, apples and a map.", "After two hours, the sky became grey and it started to rain. They tried to go back, but the path was covered with mud and they took a wrong turn. Soon they were lost.", "Carla stayed calm. She remembered that her father always said, \"If you are lost, stay in one place.\" They sat under a big rock and waited.", "An hour later, they heard a whistle. A park guide was walking along the path with a lamp. \"You are safe now,\" he said with a smile. Carla and Jon were tired and wet, but very happy."], "paragraphs_pt": ["Carla e seu amigo Jon decidiram caminhar até um lago nas montanhas. A manhã estava ensolarada, então levaram só uma mochila pequena com água, maçãs e um mapa.", "Depois de duas horas, o céu ficou cinza e começou a chover. Eles tentaram voltar, mas a trilha estava coberta de lama e eles pegaram o caminho errado. Logo estavam perdidos.", "Carla ficou calma. Ela lembrou que o pai sempre dizia: \"Se você estiver perdido, fique em um lugar.\" Eles sentaram embaixo de uma pedra grande e esperaram.", "Uma hora depois, ouviram um apito. Um guia do parque caminhava pela trilha com uma lanterna. \"Vocês estão seguros agora\", disse ele com um sorriso. Carla e Jon estavam cansados e molhados, mas muito felizes."], "hard_words": ["mud", "whistle", "guide", "calm"], "vocab": [{"word": "lake", "meaning": "lago", "note": ""}, {"word": "mud", "meaning": "lama", "note": ""}, {"word": "wrong turn", "meaning": "curva errada", "note": ""}, {"word": "lost", "meaning": "perdido", "note": ""}, {"word": "calm", "meaning": "calmo", "note": ""}, {"word": "rock", "meaning": "pedra, rocha", "note": ""}, {"word": "whistle", "meaning": "apito", "note": ""}, {"word": "guide", "meaning": "guia", "note": ""}, {"word": "lamp", "meaning": "lanterna, lampião", "note": ""}, {"word": "safe", "meaning": "seguro", "note": ""}, {"word": "wet", "meaning": "molhado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "are"], "irregular": ["decided", "took", "became", "started", "tried", "covered", "lost", "stayed", "remembered", "said", "sat", "waited", "heard", "tired"], "phrasal": ["go back", "stayed calm"], "wh": [], "connectors": ["and", "but", "so", "after", "if"], "comparative": []}, "word_meanings": [{"word": "lake", "meaning": "lago", "note": ""}, {"word": "mud", "meaning": "lama", "note": ""}, {"word": "wrong turn", "meaning": "curva errada", "note": ""}, {"word": "lost", "meaning": "perdido", "note": ""}, {"word": "calm", "meaning": "calmo", "note": ""}, {"word": "rock", "meaning": "pedra, rocha", "note": ""}, {"word": "whistle", "meaning": "apito", "note": ""}, {"word": "guide", "meaning": "guia", "note": ""}, {"word": "lamp", "meaning": "lanterna, lampião", "note": ""}, {"word": "safe", "meaning": "seguro", "note": ""}, {"word": "wet", "meaning": "molhado", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "Usamos o passado simples para ações terminadas: 'they took a wrong turn', 'they heard a whistle'. Os verbos regulares terminam em -ed; os irregulares mudam (take → took)."}, {"point": "Because / so", "explanation_pt": "'so' mostra resultado: 'The morning was sunny, so they took only a small bag.'"}], "multiple_choice": [{"question": "Where did Carla and Jon want to go?", "options": ["To a beach", "To a village", "To a lake", "To a hotel"], "correct_index": 2, "explanation": "Eles queriam ir a um lago nas montanhas."}, {"question": "What happened after two hours?", "options": ["They ate lunch", "They found the lake", "They met a guide", "It started to rain"], "correct_index": 3, "explanation": "O céu ficou cinza e começou a chover."}, {"question": "Why did they get lost?", "options": ["They slept too long", "They lost the map", "They took a wrong turn", "They ran very fast"], "correct_index": 2, "explanation": "A trilha estava coberta de lama e eles pegaram a curva errada."}, {"question": "What did Carla remember?", "options": ["A phone number", "Her father's advice", "A story", "A song"], "correct_index": 1, "explanation": "Ela lembrou do conselho do pai: ficar em um lugar."}, {"question": "Who found them?", "options": ["Carla's father", "A farmer", "Some tourists", "A park guide"], "correct_index": 3, "explanation": "Um guia do parque ouviu e encontrou os dois."}], "open_questions": [{"question": "What do you do when you are lost?", "key_points_pt": ["citar ficar calmo, pedir ajuda ou usar o celular", "usar vocabulário de lugar"]}, {"question": "Would you go on a mountain walk? Why or why not?", "key_points_pt": ["dar opinião com um motivo", "usar 'I would' ou 'I wouldn't'"]}]}}, {"level": "B1", "genre": "adventure", "title": "Rafting on the Green River", "paragraphs": ["Tom had never tried rafting before, so he felt both excited and nervous when he arrived at the river camp. A guide named Rosa gave everyone a helmet and a life jacket and explained the basic rules. \"When I shout 'paddle', you paddle together,\" she said.", "The first hour was easy. The water was calm and the group enjoyed the green hills on both sides. But around noon the river became narrow, and the raft began to move much faster. Tom's heart was beating so fast that he could hear it.", "Suddenly, a big wave hit the raft and Tom fell into the water. For a few seconds he panicked, but he remembered Rosa's advice: keep your feet up and let the river carry you. A teammate pulled him back into the raft.", "By the end of the afternoon, everyone was wet, tired and laughing. Tom realized that the scariest moment had also been the best one. He promised himself that he would come back next summer."], "paragraphs_pt": ["Tom nunca tinha feito rafting, então se sentiu animado e nervoso ao chegar ao acampamento no rio. Uma guia chamada Rosa deu capacete e colete salva-vidas a todos e explicou as regras básicas. \"Quando eu gritar 'paddle', vocês remam juntos\", disse ela.", "A primeira hora foi fácil. A água estava calma e o grupo curtiu as colinas verdes dos dois lados. Mas por volta do meio-dia o rio ficou estreito e o bote começou a andar muito mais rápido. O coração de Tom batia tão forte que ele podia ouvi-lo.", "De repente, uma onda grande atingiu o bote e Tom caiu na água. Por alguns segundos ele entrou em pânico, mas lembrou do conselho de Rosa: mantenha os pés para cima e deixe o rio levar você. Um colega o puxou de volta para o bote.", "No fim da tarde, todos estavam molhados, cansados e rindo. Tom percebeu que o momento mais assustador também tinha sido o melhor. Ele prometeu a si mesmo que voltaria no próximo verão."], "hard_words": ["nervous", "narrow", "panicked", "scariest"], "vocab": [{"word": "rafting", "meaning": "rafting (descida de rio de bote)", "note": ""}, {"word": "nervous", "meaning": "nervoso", "note": ""}, {"word": "life jacket", "meaning": "colete salva-vidas", "note": ""}, {"word": "paddle", "meaning": "remar", "note": ""}, {"word": "narrow", "meaning": "estreito", "note": ""}, {"word": "raft", "meaning": "bote inflável", "note": ""}, {"word": "wave", "meaning": "onda", "note": ""}, {"word": "panicked", "meaning": "entrou em pânico", "note": ""}, {"word": "teammate", "meaning": "colega de equipe", "note": ""}, {"word": "scariest", "meaning": "mais assustador", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been"], "irregular": ["had", "tried", "felt", "excited", "arrived", "named", "gave", "explained", "said", "enjoyed", "became", "began", "could", "fell", "panicked", "remembered", "pulled", "tired", "realized", "promised", "would"], "phrasal": ["pulled him back"], "wh": ["when"], "connectors": ["and", "but", "so", "before", "when", "also", "suddenly"], "comparative": ["faster", "scariest"]}, "word_meanings": [{"word": "rafting", "meaning": "rafting (descida de rio de bote)", "note": ""}, {"word": "nervous", "meaning": "nervoso", "note": ""}, {"word": "life jacket", "meaning": "colete salva-vidas", "note": ""}, {"word": "paddle", "meaning": "remar", "note": ""}, {"word": "narrow", "meaning": "estreito", "note": ""}, {"word": "raft", "meaning": "bote inflável", "note": ""}, {"word": "wave", "meaning": "onda", "note": ""}, {"word": "panicked", "meaning": "entrou em pânico", "note": ""}, {"word": "teammate", "meaning": "colega de equipe", "note": ""}, {"word": "scariest", "meaning": "mais assustador", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Tom had never tried rafting' usa had + particípio para dizer que algo não aconteceu antes de outro momento do passado."}, {"point": "Comparativos e superlativos", "explanation_pt": "'faster' compara velocidades; 'the scariest moment' indica o mais assustador de todos."}], "multiple_choice": [{"question": "Why was Tom nervous at the start?", "options": ["He forgot his helmet", "He had never tried rafting", "He was afraid of Rosa", "He was late"], "correct_index": 1, "explanation": "Ele nunca tinha feito rafting antes."}, {"question": "What did Rosa say about 'paddle'?", "options": ["Everyone jumps", "Everyone paddles together when she shouts it", "Everyone sings", "Everyone stops"], "correct_index": 1, "explanation": "Quando ela gritava 'paddle', todos remavam juntos."}, {"question": "What changed around noon?", "options": ["The raft broke", "The river became narrow and fast", "It started to snow", "The guide left"], "correct_index": 1, "explanation": "O rio estreitou e o bote ficou mais rápido."}, {"question": "What advice helped Tom in the water?", "options": ["Close your eyes", "Swim against the river", "Keep your feet up", "Shout for help"], "correct_index": 2, "explanation": "Ele lembrou de manter os pés para cima."}, {"question": "How did Tom feel at the end?", "options": ["He was angry at his friends", "He wanted to come back", "He felt bored", "He never wanted to see a river again"], "correct_index": 1, "explanation": "Ele prometeu voltar no próximo verão."}], "open_questions": [{"question": "Have you ever tried a sport that scared you? What happened?", "key_points_pt": ["contar uma experiência", "usar passado simples e present perfect"]}, {"question": "Why can the scariest moment also be the best one?", "key_points_pt": ["explicar a sensação de superar o medo", "dar um exemplo pessoal"]}]}}, {"level": "B2", "genre": "adventure", "title": "Crossing the Namib", "paragraphs": ["Mara had been planning the trip for almost a year, yet nothing prepared her for the silence of the Namib Desert. Her small group of four, led by an experienced guide named Elias, was supposed to walk across the dunes in six days, carrying only what they could fit in their backpacks.", "On the third day, the wind rose without warning. Sand filled the air so thickly that the dunes disappeared, and Elias ordered everyone to stop and tie themselves together with a rope. They sat back to back for nearly two hours, covering their faces with scarves.", "When the storm finally passed, they discovered that their water supply was lower than expected: one of the bottles had cracked and leaked into the sand. Rather than panic, Elias recalculated the route and led them toward a dry riverbed where, according to his old maps, a well might still exist.", "It took them a full day to reach it. The well was almost empty, but a thin layer of cold water lay at the bottom, enough for the four of them to drink carefully. Mara noticed that nobody spoke while they shared it. Later she wrote in her notebook that the desert had not defeated them; it had taught them how little they truly needed."], "paragraphs_pt": ["Mara planejava a viagem havia quase um ano, mas nada a preparou para o silêncio do deserto da Namíbia. Seu pequeno grupo de quatro pessoas, liderado por um guia experiente chamado Elias, deveria atravessar as dunas em seis dias, levando apenas o que coubesse nas mochilas.", "No terceiro dia, o vento aumentou sem aviso. A areia encheu o ar de forma tão densa que as dunas desapareceram, e Elias mandou todos pararem e se amarrarem com uma corda. Eles ficaram sentados de costas uns para os outros por quase duas horas, cobrindo o rosto com lenços.", "Quando a tempestade finalmente passou, descobriram que o estoque de água estava menor do que o esperado: uma das garrafas havia rachado e vazado na areia. Em vez de entrar em pânico, Elias recalculou a rota e os levou a um leito de rio seco onde, segundo seus mapas antigos, ainda poderia existir um poço.", "Levaram um dia inteiro para chegar. O poço estava quase vazio, mas uma camada fina de água fria ficava no fundo, o suficiente para os quatro beberem com cuidado. Mara notou que ninguém falou enquanto dividiam a água. Mais tarde, ela escreveu no caderno que o deserto não os havia derrotado; havia ensinado como pouco eles realmente precisavam."], "hard_words": ["dunes", "leaked", "riverbed", "recalculated"], "vocab": [{"word": "dunes", "meaning": "dunas", "note": ""}, {"word": "backpacks", "meaning": "mochilas", "note": ""}, {"word": "without warning", "meaning": "sem aviso", "note": ""}, {"word": "scarves", "meaning": "lenços", "note": ""}, {"word": "cracked", "meaning": "rachou", "note": ""}, {"word": "leaked", "meaning": "vazou", "note": ""}, {"word": "riverbed", "meaning": "leito do rio", "note": ""}, {"word": "well", "meaning": "poço", "note": ""}, {"word": "recalculated", "meaning": "recalculou", "note": ""}, {"word": "defeated", "meaning": "derrotou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was"], "irregular": ["had", "prepared", "led", "experienced", "named", "supposed", "could", "rose", "filled", "disappeared", "ordered", "sat", "passed", "discovered", "expected", "cracked", "leaked", "might", "took", "lay", "noticed", "spoke", "shared", "wrote", "defeated", "taught", "needed"], "phrasal": ["tie themselves together"], "wh": ["what", "where", "when", "how"], "connectors": ["and", "but", "so", "while", "when", "yet", "finally", "still"], "comparative": []}, "word_meanings": [{"word": "dunes", "meaning": "dunas", "note": ""}, {"word": "backpacks", "meaning": "mochilas", "note": ""}, {"word": "without warning", "meaning": "sem aviso", "note": ""}, {"word": "scarves", "meaning": "lenços", "note": ""}, {"word": "cracked", "meaning": "rachou", "note": ""}, {"word": "leaked", "meaning": "vazou", "note": ""}, {"word": "riverbed", "meaning": "leito do rio", "note": ""}, {"word": "well", "meaning": "poço", "note": ""}, {"word": "recalculated", "meaning": "recalculou", "note": ""}, {"word": "defeated", "meaning": "derrotou", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect continuous", "explanation_pt": "'Mara had been planning the trip' mostra uma ação que vinha acontecendo por um tempo antes de outro momento do passado."}, {"point": "Rather than + verbo", "explanation_pt": "'Rather than panic' significa 'em vez de entrar em pânico', e é seguido do verbo base."}], "multiple_choice": [{"question": "How long had Mara been planning the trip?", "options": ["One month", "Six days", "Almost a year", "Two hours"], "correct_index": 2, "explanation": "Ela planejava havia quase um ano."}, {"question": "What did Elias order when the wind rose?", "options": ["Everyone to stop and tie themselves together", "Everyone to climb a dune", "Everyone to run", "Everyone to eat"], "correct_index": 0, "explanation": "Ele mandou parar e se amarrar com uma corda."}, {"question": "What problem did they discover after the storm?", "options": ["Elias was hurt", "They lost their map", "One water bottle had cracked", "Their tent was gone"], "correct_index": 2, "explanation": "Uma garrafa rachou e a água vazou."}, {"question": "Where did Elias lead them?", "options": ["To the sea", "To a dry riverbed with a possible well", "To a village", "Back to the camp"], "correct_index": 1, "explanation": "Ele os levou a um leito seco onde podia haver um poço."}, {"question": "What lesson did Mara write in her notebook?", "options": ["They needed very little to survive", "They should have stayed home", "The desert was cruel", "Maps are useless"], "correct_index": 0, "explanation": "O deserto ensinou como pouco eles precisavam."}], "open_questions": [{"question": "Why is a good guide important in an extreme trip?", "key_points_pt": ["falar de experiência, calma e decisões sob pressão", "usar exemplos da história"]}, {"question": "What is the smallest amount of things you could live with for a week?", "key_points_pt": ["listar itens essenciais", "justificar a escolha"]}]}}, {"level": "B2", "genre": "adventure", "title": "Storm Over the Aegean", "paragraphs": ["Daniel had always wanted to sail alone, and on a clear morning in June he finally left the harbor in a small wooden boat he had restored over three winters. The forecast promised light winds, so he planned to reach a distant island by sunset.", "By early afternoon, however, the sky had turned the color of lead. The wind shifted suddenly, and waves began to slap against the hull with increasing force. Daniel lowered the sail, tied himself to the mast and tried to keep the bow pointed into the weather, just as his old instructor had taught him.", "For four exhausting hours the boat rose and fell on enormous waves. Twice the radio crackled with a distant voice that he could not understand, and he realized that no one could reach him in time. Whatever happened next depended entirely on his own decisions.", "Near dusk, the storm weakened as quickly as it had arrived. Daniel found himself drifting beside a tiny, unnamed rock covered with gulls. He dropped anchor, wrapped himself in a blanket and watched the first stars appear. He had not reached his island, but he had never felt more alive."], "paragraphs_pt": ["Daniel sempre quis navegar sozinho e, numa manhã clara de junho, finalmente deixou o porto num pequeno barco de madeira que ele havia restaurado ao longo de três invernos. A previsão prometia ventos fracos, então ele planejou chegar a uma ilha distante ao pôr do sol.", "No início da tarde, porém, o céu tinha ficado da cor do chumbo. O vento mudou de repente e as ondas começaram a bater no casco com força crescente. Daniel baixou a vela, amarrou-se ao mastro e tentou manter a proa apontada contra o mau tempo, exatamente como seu antigo instrutor havia ensinado.", "Durante quatro horas exaustivas o barco subiu e desceu em ondas enormes. Duas vezes o rádio chiou com uma voz distante que ele não conseguia entender, e ele percebeu que ninguém poderia alcançá-lo a tempo. O que quer que acontecesse a seguir dependia inteiramente de suas próprias decisões.", "Perto do anoitecer, a tempestade enfraqueceu tão rápido quanto chegou. Daniel se viu à deriva ao lado de uma rocha minúscula, sem nome, coberta de gaivotas. Ele lançou a âncora, enrolou-se num cobertor e viu as primeiras estrelas aparecerem. Não tinha chegado à sua ilha, mas nunca se sentira tão vivo."], "hard_words": ["forecast", "hull", "crackled", "drifting"], "vocab": [{"word": "harbor", "meaning": "porto", "note": ""}, {"word": "restored", "meaning": "restaurou", "note": ""}, {"word": "forecast", "meaning": "previsão (do tempo)", "note": ""}, {"word": "hull", "meaning": "casco", "note": ""}, {"word": "mast", "meaning": "mastro", "note": ""}, {"word": "bow", "meaning": "proa", "note": ""}, {"word": "crackled", "meaning": "chiou", "note": ""}, {"word": "drifting", "meaning": "à deriva", "note": ""}, {"word": "gulls", "meaning": "gaivotas", "note": ""}, {"word": "anchor", "meaning": "âncora", "note": ""}], "grammar_words": {"cognates": [], "tobe": [], "irregular": ["had", "wanted", "left", "restored", "promised", "planned", "turned", "shifted", "began", "lowered", "tied", "tried", "pointed", "taught", "rose", "fell", "crackled", "could", "realized", "happened", "depended", "weakened", "arrived", "found", "covered", "dropped", "wrapped", "watched", "reached", "felt"], "phrasal": ["tied himself to"], "wh": ["whatever"], "connectors": ["and", "but", "however", "so", "finally", "suddenly", "as"], "comparative": []}, "word_meanings": [{"word": "harbor", "meaning": "porto", "note": ""}, {"word": "restored", "meaning": "restaurou", "note": ""}, {"word": "forecast", "meaning": "previsão (do tempo)", "note": ""}, {"word": "hull", "meaning": "casco", "note": ""}, {"word": "mast", "meaning": "mastro", "note": ""}, {"word": "bow", "meaning": "proa", "note": ""}, {"word": "crackled", "meaning": "chiou", "note": ""}, {"word": "drifting", "meaning": "à deriva", "note": ""}, {"word": "gulls", "meaning": "gaivotas", "note": ""}, {"word": "anchor", "meaning": "âncora", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'a boat he had restored' mostra que o conserto aconteceu antes de ele sair do porto."}, {"point": "Whatever", "explanation_pt": "'Whatever happened next' significa 'o que quer que acontecesse'; é usado para algo que não se sabe."}], "multiple_choice": [{"question": "How long did Daniel take to restore his boat?", "options": ["Five years", "One summer", "Three winters", "Ten days"], "correct_index": 2, "explanation": "Ele restaurou o barco ao longo de três invernos."}, {"question": "What did the forecast promise?", "options": ["A big storm", "No wind at all", "Snow", "Light winds"], "correct_index": 3, "explanation": "A previsão prometia ventos fracos."}, {"question": "What did Daniel do when the waves grew stronger?", "options": ["He jumped into the sea", "He called a friend", "He lowered the sail and tied himself to the mast", "He turned on the engine"], "correct_index": 2, "explanation": "Ele baixou a vela e se amarrou ao mastro."}, {"question": "Why could nobody help him?", "options": ["They could not reach him in time", "He had no radio", "He did not want help", "The radio was broken"], "correct_index": 0, "explanation": "Ninguém poderia alcançá-lo a tempo."}, {"question": "How did Daniel feel at the end?", "options": ["Angry at the weather", "Ashamed", "Alive, even without reaching the island", "Bored"], "correct_index": 2, "explanation": "Ele nunca se sentira tão vivo."}], "open_questions": [{"question": "Is it better to plan every detail or to accept surprises on a trip?", "key_points_pt": ["defender uma posição com exemplos", "usar conectores de opinião"]}, {"question": "How do people prepare for risky adventures?", "key_points_pt": ["falar de equipamento, treino e previsão do tempo"]}]}}, {"level": "B2", "genre": "adventure", "title": "The Cave Below the Village", "paragraphs": ["Everyone in the village of San Ilario knew the story of the cave, but no one had entered it for decades. When Nora, a young geologist from the capital, arrived with a team of three assistants, the older residents shook their heads and warned her that the tunnels were unstable.", "The entrance was barely wide enough for one person. Inside, however, the passage opened into a hall so large that their headlamps could not reach the ceiling. Water dripped steadily from the rock, and the walls were covered with delicate crystals that glittered like frost.", "Nora was marking the route with small colored flags when she noticed something unusual: a line of faded red handprints on the wall, far older than any record of the village. She stopped, photographed them carefully and sent a message to a colleague, although the signal was weak.", "They stayed underground for nine hours. When they emerged, the villagers were waiting at the entrance with blankets and hot soup. Nora promised to return, not as an outsider with instruments, but as a guest who wanted to learn what the cave meant to the people who lived above it."], "paragraphs_pt": ["Todos na vila de San Ilario conheciam a história da caverna, mas ninguém entrava nela havia décadas. Quando Nora, uma jovem geóloga da capital, chegou com uma equipe de três assistentes, os moradores mais velhos balançaram a cabeça e avisaram que os túneis eram instáveis.", "A entrada mal tinha largura para uma pessoa. Lá dentro, porém, a passagem se abria num salão tão grande que as lanternas de cabeça não alcançavam o teto. A água pingava continuamente da rocha, e as paredes estavam cobertas de cristais delicados que brilhavam como geada.", "Nora estava marcando o caminho com pequenas bandeiras coloridas quando notou algo incomum: uma fileira de marcas de mãos vermelhas desbotadas na parede, muito mais antigas que qualquer registro da vila. Ela parou, fotografou com cuidado e enviou uma mensagem a um colega, embora o sinal fosse fraco.", "Ficaram nove horas no subsolo. Quando saíram, os moradores esperavam na entrada com cobertores e sopa quente. Nora prometeu voltar, não como uma estrangeira com instrumentos, mas como uma convidada que queria aprender o que a caverna significava para as pessoas que viviam acima dela."], "hard_words": ["unstable", "crystals", "faded", "outsider"], "vocab": [{"word": "geologist", "meaning": "geóloga", "note": ""}, {"word": "unstable", "meaning": "instável", "note": ""}, {"word": "headlamps", "meaning": "lanternas de cabeça", "note": ""}, {"word": "dripped", "meaning": "pingava", "note": ""}, {"word": "crystals", "meaning": "cristais", "note": ""}, {"word": "glittered", "meaning": "brilhavam", "note": ""}, {"word": "handprints", "meaning": "marcas de mãos", "note": ""}, {"word": "faded", "meaning": "desbotadas", "note": ""}, {"word": "emerged", "meaning": "saíram, emergiram", "note": ""}, {"word": "outsider", "meaning": "forasteiro", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was"], "irregular": ["knew", "had", "entered", "arrived", "shook", "warned", "opened", "could", "dripped", "covered", "glittered", "colored", "noticed", "faded", "stopped", "photographed", "sent", "stayed", "emerged", "promised", "wanted", "meant", "lived"], "phrasal": ["shook their heads"], "wh": ["who", "what", "when"], "connectors": ["and", "but", "however", "although", "so", "when", "as"], "comparative": []}, "word_meanings": [{"word": "geologist", "meaning": "geóloga", "note": ""}, {"word": "unstable", "meaning": "instável", "note": ""}, {"word": "headlamps", "meaning": "lanternas de cabeça", "note": ""}, {"word": "dripped", "meaning": "pingava", "note": ""}, {"word": "crystals", "meaning": "cristais", "note": ""}, {"word": "glittered", "meaning": "brilhavam", "note": ""}, {"word": "handprints", "meaning": "marcas de mãos", "note": ""}, {"word": "faded", "meaning": "desbotadas", "note": ""}, {"word": "emerged", "meaning": "saíram, emergiram", "note": ""}, {"word": "outsider", "meaning": "forasteiro", "note": ""}], "exercises": {"grammar": [{"point": "Past simple e past perfect", "explanation_pt": "'no one had entered it' (past perfect) vem antes do momento em que Nora chega (past simple)."}, {"point": "Although", "explanation_pt": "'although the signal was weak' mostra contraste e significa 'embora'."}], "multiple_choice": [{"question": "Why did the older residents warn Nora?", "options": ["The team was too small", "The cave was haunted", "The tunnels were unstable", "It was too cold"], "correct_index": 2, "explanation": "Eles diziam que os túneis eram instáveis."}, {"question": "What was Nora's job?", "options": ["Guide", "Teacher", "Journalist", "Geologist"], "correct_index": 3, "explanation": "Nora era geóloga."}, {"question": "What did Nora find on the wall?", "options": ["A treasure map", "A door", "A name", "Faded red handprints"], "correct_index": 3, "explanation": "Ela achou marcas de mãos vermelhas desbotadas."}, {"question": "How long did they stay underground?", "options": ["Nine hours", "Two days", "A week", "One hour"], "correct_index": 0, "explanation": "Ficaram nove horas no subsolo."}, {"question": "What did Nora promise the villagers?", "options": ["To sell the crystals", "To return as a guest to learn", "To write a book", "To close the cave"], "correct_index": 1, "explanation": "Ela prometeu voltar como convidada para aprender."}], "open_questions": [{"question": "Should explorers always ask local people for permission? Why?", "key_points_pt": ["defender respeito pela comunidade", "citar o exemplo da vila"]}, {"question": "What would you do if you found old marks in a cave?", "key_points_pt": ["descrever a reação", "usar condicional"]}]}}, {"level": "C1", "genre": "adventure", "title": "The Ice Between Us", "paragraphs": ["When the expedition finally reached the edge of the glacier, Ingrid understood that the maps they had studied for months described a place that no longer existed. Crevasses had opened where the survey showed solid ice, and a thin veil of fresh snow concealed many of them. Their leader, Henrik, insisted that they proceed slowly, roped together at ten-metre intervals.", "For three days the party advanced in near silence, conserving energy and breath. Ingrid, the youngest member, kept a private count of her steps, a habit she had developed as a child to calm herself during storms. It was this habit that saved them, because on the fourth morning she noticed that the number of paces between two markers had quietly changed. The ice itself was moving.", "She reported it immediately, and Henrik, who rarely admitted uncertainty, studied her figures before ordering a retreat to the previous camp. Within an hour a tower of ice the size of a house collapsed exactly where they would have been standing. Nobody celebrated; they simply sat in the tent, listening to the glacier groan beneath them.", "Months later, when journalists asked about the near-disaster, Henrik credited the team's experience. Ingrid said nothing, but in her notebook she wrote that expertise was valuable, whereas attention was priceless."], "paragraphs_pt": ["Quando a expedição finalmente chegou à borda da geleira, Ingrid entendeu que os mapas que haviam estudado por meses descreviam um lugar que já não existia. Fendas tinham se aberto onde o levantamento mostrava gelo sólido, e um véu fino de neve fresca escondia muitas delas. O líder, Henrik, insistiu que avançassem devagar, amarrados por cordas a intervalos de dez metros.", "Por três dias o grupo avançou em quase silêncio, poupando energia e fôlego. Ingrid, a integrante mais jovem, contava seus passos em segredo, um hábito que desenvolvera na infância para se acalmar durante tempestades. Foi esse hábito que os salvou, porque na quarta manhã ela notou que o número de passos entre duas marcas havia mudado discretamente. O próprio gelo estava se movendo.", "Ela avisou imediatamente, e Henrik, que raramente admitia incerteza, estudou os números dela antes de ordenar a retirada para o acampamento anterior. Em uma hora, uma torre de gelo do tamanho de uma casa desabou exatamente onde eles estariam. Ninguém comemorou; apenas ficaram na barraca, ouvindo a geleira gemer sob eles.", "Meses depois, quando jornalistas perguntaram sobre o quase desastre, Henrik atribuiu o mérito à experiência da equipe. Ingrid não disse nada, mas no caderno escreveu que a perícia era valiosa, enquanto a atenção não tinha preço."], "hard_words": ["concealed", "paces", "retreat", "priceless"], "vocab": [{"word": "glacier", "meaning": "geleira", "note": ""}, {"word": "crevasses", "meaning": "fendas (no gelo)", "note": ""}, {"word": "concealed", "meaning": "escondia", "note": ""}, {"word": "roped together", "meaning": "amarrados por corda", "note": ""}, {"word": "conserving", "meaning": "poupando", "note": ""}, {"word": "paces", "meaning": "passos", "note": ""}, {"word": "retreat", "meaning": "retirada", "note": ""}, {"word": "collapsed", "meaning": "desabou", "note": ""}, {"word": "groan", "meaning": "gemer", "note": ""}, {"word": "priceless", "meaning": "inestimável", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been"], "irregular": ["reached", "understood", "had", "studied", "described", "existed", "opened", "showed", "concealed", "insisted", "roped", "advanced", "kept", "developed", "saved", "noticed", "changed", "reported", "admitted", "collapsed", "would", "celebrated", "sat", "asked", "credited", "said", "wrote"], "phrasal": ["roped together"], "wh": ["who", "where", "when"], "connectors": ["and", "but", "because", "before", "when", "whereas", "finally", "as"], "comparative": []}, "word_meanings": [{"word": "glacier", "meaning": "geleira", "note": ""}, {"word": "crevasses", "meaning": "fendas (no gelo)", "note": ""}, {"word": "concealed", "meaning": "escondia", "note": ""}, {"word": "roped together", "meaning": "amarrados por corda", "note": ""}, {"word": "conserving", "meaning": "poupando", "note": ""}, {"word": "paces", "meaning": "passos", "note": ""}, {"word": "retreat", "meaning": "retirada", "note": ""}, {"word": "collapsed", "meaning": "desabou", "note": ""}, {"word": "groan", "meaning": "gemer", "note": ""}, {"word": "priceless", "meaning": "inestimável", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect e relative clauses", "explanation_pt": "'the maps they had studied' usa past perfect dentro de uma oração relativa para indicar algo anterior."}, {"point": "Whereas", "explanation_pt": "'whereas attention was priceless' contrasta duas ideias, como 'enquanto'."}], "multiple_choice": [{"question": "What did Ingrid realize about the maps?", "options": ["They were too old to read", "They were perfect", "They described a place that no longer existed", "They were in a different language"], "correct_index": 2, "explanation": "Os mapas descreviam um lugar que já não existia."}, {"question": "What habit did Ingrid have?", "options": ["Counting her steps", "Writing letters", "Drawing maps", "Singing"], "correct_index": 0, "explanation": "Ela contava os passos para se acalmar."}, {"question": "What did she notice on the fourth morning?", "options": ["The number of paces between markers had changed", "A storm", "A broken rope", "A new path"], "correct_index": 0, "explanation": "O gelo estava se movendo."}, {"question": "What happened an hour after the retreat?", "options": ["It started to snow", "A tower of ice collapsed", "A helicopter arrived", "The team found a cave"], "correct_index": 1, "explanation": "Uma torre de gelo desabou onde eles estariam."}, {"question": "Who did Henrik credit when journalists asked?", "options": ["Luck", "Ingrid", "The weather", "The team's experience"], "correct_index": 3, "explanation": "Ele atribuiu o mérito à experiência da equipe."}], "open_questions": [{"question": "Why do leaders sometimes fail to give credit to younger members?", "key_points_pt": ["discutir ego, hierarquia e reconhecimento", "usar o exemplo de Henrik"]}, {"question": "What small habits help you stay alert in stressful situations?", "key_points_pt": ["descrever hábitos pessoais", "relacionar à história"]}]}}, {"level": "C1", "genre": "adventure", "title": "A River Without a Name", "paragraphs": ["The guide's only instruction had been to follow the water, and for six days Clara and her brother Mateus had done precisely that, paddling a battered canoe through the Amazon basin with a sense of purpose that neither of them could have explained. They had no particular destination; they simply wished to see how far a river could take two people who had spent their adult lives indoors.", "On the seventh day they passed a settlement of stilt houses, where a woman waved from a doorway and, without a word, handed them a basket of grilled fish. The gesture moved Clara more than she expected. Back home, hospitality was something people performed; here it appeared to be as natural as breathing.", "That night, camped on a sandbank, they heard something moving in the shallows. Mateus, who had always been the cautious one, reached for the flashlight, but Clara stopped him. In the dark, the outline of a pink dolphin broke the surface, exhaled once and vanished, leaving ripples that shone like silver coins.", "When they finally returned to the city, friends asked whether they had been frightened. Clara considered the question for a moment. Frightened, she said, had not been the right word; humbled came closer. The river had never asked anything of them, and yet it had altered the way they measured their own lives."], "paragraphs_pt": ["A única instrução do guia tinha sido seguir a água, e por seis dias Clara e o irmão, Mateus, fizeram exatamente isso, remando numa canoa surrada pela bacia amazônica com um senso de propósito que nenhum dos dois saberia explicar. Eles não tinham destino definido; só queriam ver até onde um rio podia levar duas pessoas que haviam passado a vida adulta dentro de casa.", "No sétimo dia passaram por um povoado de casas sobre palafitas, onde uma mulher acenou da porta e, sem dizer uma palavra, lhes entregou uma cesta de peixe grelhado. O gesto comoveu Clara mais do que ela esperava. Em casa, hospitalidade era algo que as pessoas encenavam; ali parecia tão natural quanto respirar.", "Naquela noite, acampados num banco de areia, ouviram algo se mover na água rasa. Mateus, que sempre fora o cauteloso, pegou a lanterna, mas Clara o impediu. No escuro, o contorno de um boto-cor-de-rosa rompeu a superfície, soltou o ar uma vez e sumiu, deixando ondulações que brilhavam como moedas de prata.", "Quando finalmente voltaram à cidade, amigos perguntaram se haviam sentido medo. Clara pensou na pergunta por um instante. Medo, disse, não era a palavra certa; humildade chegava mais perto. O rio nunca lhes pedira nada e, ainda assim, mudara a maneira como mediam a própria vida."], "hard_words": ["battered", "hospitality", "ripples", "humbled"], "vocab": [{"word": "battered", "meaning": "surrado", "note": ""}, {"word": "basin", "meaning": "bacia (hidrográfica)", "note": ""}, {"word": "stilt houses", "meaning": "casas sobre palafitas", "note": ""}, {"word": "hospitality", "meaning": "hospitalidade", "note": ""}, {"word": "sandbank", "meaning": "banco de areia", "note": ""}, {"word": "shallows", "meaning": "águas rasas", "note": ""}, {"word": "exhaled", "meaning": "soltou o ar", "note": ""}, {"word": "ripples", "meaning": "ondulações", "note": ""}, {"word": "humbled", "meaning": "humilde, tocado pela humildade", "note": ""}, {"word": "altered", "meaning": "mudou, alterou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "be"], "irregular": ["had", "done", "battered", "could", "explained", "wished", "spent", "passed", "waved", "handed", "grilled", "moved", "expected", "performed", "appeared", "camped", "heard", "reached", "stopped", "broke", "exhaled", "vanished", "shone", "returned", "asked", "frightened", "considered", "said", "humbled", "came", "altered", "measured"], "phrasal": ["reached for"], "wh": ["who", "where", "when", "how"], "connectors": ["and", "but", "when", "yet", "finally", "once", "as"], "comparative": []}, "word_meanings": [{"word": "battered", "meaning": "surrado", "note": ""}, {"word": "basin", "meaning": "bacia (hidrográfica)", "note": ""}, {"word": "stilt houses", "meaning": "casas sobre palafitas", "note": ""}, {"word": "hospitality", "meaning": "hospitalidade", "note": ""}, {"word": "sandbank", "meaning": "banco de areia", "note": ""}, {"word": "shallows", "meaning": "águas rasas", "note": ""}, {"word": "exhaled", "meaning": "soltou o ar", "note": ""}, {"word": "ripples", "meaning": "ondulações", "note": ""}, {"word": "humbled", "meaning": "humilde, tocado pela humildade", "note": ""}, {"word": "altered", "meaning": "mudou, alterou", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'who had spent their adult lives indoors' indica algo anterior à viagem."}, {"point": "Inversão e ênfase com 'Frightened... had not been the right word'", "explanation_pt": "Colocar a palavra no início enfatiza o ponto, como em 'Frightened, she said, had not been the right word'."}], "multiple_choice": [{"question": "What was the guide's only instruction?", "options": ["Stay on the shore", "Follow the water", "Return in a week", "Avoid villages"], "correct_index": 1, "explanation": "A instrução era seguir a água."}, {"question": "How did the woman at the settlement help them?", "options": ["She gave them a map", "She gave them grilled fish", "She invited them to stay for a month", "She lent them a boat"], "correct_index": 1, "explanation": "Ela entregou uma cesta de peixe grelhado."}, {"question": "What did Clara prevent Mateus from doing?", "options": ["Paddling away", "Using the flashlight", "Eating the fish", "Waking the guide"], "correct_index": 1, "explanation": "Ela o impediu de usar a lanterna."}, {"question": "What appeared in the dark?", "options": ["A snake", "A fisherman", "A pink dolphin", "A jaguar"], "correct_index": 2, "explanation": "Um boto-cor-de-rosa rompeu a superfície."}, {"question": "Which word did Clara prefer to 'frightened'?", "options": ["Bored", "Humbled", "Tired", "Excited"], "correct_index": 1, "explanation": "Ela disse que humildade chegava mais perto."}], "open_questions": [{"question": "What can people learn from travelling without a fixed destination?", "key_points_pt": ["discutir flexibilidade e abertura", "usar exemplos"]}, {"question": "Why can small gestures of hospitality feel so powerful?", "key_points_pt": ["refletir sobre generosidade e cultura"]}]}}, {"level": "C1", "genre": "adventure", "title": "The Pass at Dawn", "paragraphs": ["The mountain rescue volunteers had a saying: nobody is lost until they stop walking. It was a comforting phrase, and Aiko had repeated it to herself throughout the night, even though she had not moved from the narrow ledge where the blizzard had trapped her. Her climbing partner, Rui, had gone down to find help and had been gone for nine hours.", "As the sky began to pale, she noticed that the wind had softened. She forced her stiff fingers to unzip her pack and discovered, wedged beneath a spare glove, a bar of chocolate she had forgotten about. She ate it slowly, aware that the sugar mattered less than the small act of choosing something.", "A distant whirr reached her just after sunrise. At first she assumed it was the wind, but the sound grew steadier, and then a helicopter rose above the ridge, painted a color so bright it seemed unreal. Rui was inside, pale but upright, waving through the window.", "Later, in the hospital, a nurse asked whether she had been afraid. Aiko thought about the long night, the cold and the chocolate. She had been terrified, she admitted, but fear had not been the loudest thing up there. Hope, stubborn and unreasonable, had been louder."], "paragraphs_pt": ["Os voluntários de resgate em montanha tinham um ditado: ninguém está perdido até parar de andar. Era uma frase reconfortante, e Aiko a repetira para si mesma a noite inteira, mesmo sem ter saído do estreito rebordo onde a nevasca a prendera. Seu parceiro de escalada, Rui, descera para buscar ajuda e estava fora havia nove horas.", "Quando o céu começou a clarear, ela notou que o vento havia diminuído. Forçou os dedos duros a abrirem a mochila e descobriu, preso embaixo de uma luva extra, uma barra de chocolate que havia esquecido. Comeu devagar, ciente de que o açúcar importava menos do que o pequeno ato de escolher algo.", "Um zumbido distante chegou a ela logo após o nascer do sol. De início achou que era o vento, mas o som ficou mais constante, e então um helicóptero surgiu acima da crista, pintado de uma cor tão viva que parecia irreal. Rui estava dentro, pálido mas de pé, acenando pela janela.", "Mais tarde, no hospital, uma enfermeira perguntou se ela sentira medo. Aiko pensou na noite longa, no frio e no chocolate. Estivera aterrorizada, admitiu, mas o medo não fora a coisa mais alta lá em cima. A esperança, teimosa e irracional, fora mais alta."], "hard_words": ["ledge", "wedged", "ridge", "stubborn"], "vocab": [{"word": "volunteers", "meaning": "voluntários", "note": ""}, {"word": "ledge", "meaning": "rebordo, saliência", "note": ""}, {"word": "blizzard", "meaning": "nevasca", "note": ""}, {"word": "trapped", "meaning": "prendeu", "note": ""}, {"word": "wedged", "meaning": "preso, encaixado", "note": ""}, {"word": "whirr", "meaning": "zumbido", "note": ""}, {"word": "ridge", "meaning": "crista (de montanha)", "note": ""}, {"word": "upright", "meaning": "de pé, ereto", "note": ""}, {"word": "terrified", "meaning": "aterrorizada", "note": ""}, {"word": "stubborn", "meaning": "teimosa", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was", "been"], "irregular": ["had", "lost", "repeated", "moved", "trapped", "gone", "began", "noticed", "softened", "forced", "discovered", "wedged", "forgotten", "ate", "mattered", "reached", "assumed", "grew", "rose", "painted", "seemed", "asked", "thought", "terrified", "admitted"], "phrasal": ["gone down", "unzip her pack"], "wh": ["where"], "connectors": ["even though", "and", "but", "so", "though", "then", "after", "until", "as"], "comparative": []}, "word_meanings": [{"word": "volunteers", "meaning": "voluntários", "note": ""}, {"word": "ledge", "meaning": "rebordo, saliência", "note": ""}, {"word": "blizzard", "meaning": "nevasca", "note": ""}, {"word": "trapped", "meaning": "prendeu", "note": ""}, {"word": "wedged", "meaning": "preso, encaixado", "note": ""}, {"word": "whirr", "meaning": "zumbido", "note": ""}, {"word": "ridge", "meaning": "crista (de montanha)", "note": ""}, {"word": "upright", "meaning": "de pé, ereto", "note": ""}, {"word": "terrified", "meaning": "aterrorizada", "note": ""}, {"word": "stubborn", "meaning": "teimosa", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect continuous e past perfect", "explanation_pt": "'had been gone for nine hours' mostra duração anterior ao momento principal da história."}, {"point": "Even though", "explanation_pt": "'even though she had not moved' enfatiza o contraste: 'mesmo que'."}], "multiple_choice": [{"question": "What was the volunteers' saying?", "options": ["Always carry chocolate", "Never climb alone", "Nobody is lost until they stop walking", "The mountain decides"], "correct_index": 2, "explanation": "Ninguém está perdido até parar de andar."}, {"question": "Where was Aiko trapped?", "options": ["On a narrow ledge", "In a cabin", "In a tent", "In a cave"], "correct_index": 0, "explanation": "A nevasca a prendeu num rebordo estreito."}, {"question": "What did she find in her pack?", "options": ["A rope", "A map", "A forgotten bar of chocolate", "A radio"], "correct_index": 2, "explanation": "Ela achou uma barra de chocolate esquecida."}, {"question": "What arrived after sunrise?", "options": ["A group of climbers", "A helicopter with Rui inside", "A dog", "A snowstorm"], "correct_index": 1, "explanation": "Um helicóptero com Rui chegou."}, {"question": "What was louder than fear, according to Aiko?", "options": ["Pain", "Hope", "Wind", "The helicopter"], "correct_index": 1, "explanation": "A esperança foi mais alta que o medo."}], "open_questions": [{"question": "Why do short sayings help people in dangerous situations?", "key_points_pt": ["falar de foco, rotina mental e esperança"]}, {"question": "What do you think is more important in an emergency: skill or calm?", "key_points_pt": ["defender uma ideia com exemplos"]}]}}, {"level": "C2", "genre": "adventure", "title": "The Weight of the Summit", "paragraphs": ["By the time Rafael reached the final ridge, he had been climbing for fourteen hours, and the thin air had stripped the world down to a handful of essentials: the next step, the next breath, the faint yellow glow of his companion's headlamp somewhere above. He had spent three years preparing for this mountain, selling his car and rearranging his working life around training schedules, and yet nothing in those preparations had suggested that the summit itself would feel so oddly like a question rather than an answer.", "Veronika, his guide, had been climbing these slopes since before he was born. She moved with an economy of effort that bordered on indifference, and she had warned him at the base camp that the mountain did not reward ambition, only judgment. He had nodded politely, privately convinced that judgment was a lesser virtue.", "At 8,400 metres, clouds began to gather in the west with an almost theatrical slowness. Veronika paused, studied the horizon for a long while and said, without turning, that they would have to descend. The summit was perhaps two hours away. Rafael felt a hot, irrational surge of anger, the kind that arrives when a long-held dream is threatened by a calm voice.", "He argued, of course. He listed the years, the money, the sacrifices. Veronika listened without interrupting, and when he had exhausted himself she simply replied that the mountain would still be there next year, whereas he might not be. It was neither unkind nor sentimental, only true.", "They began the descent in silence. Several hours later, as the storm broke over the ridge they had just left, Rafael understood, with a clarity that humbled him, that the greatest achievement of the expedition had not been reaching a height but accepting a limit. He never spoke of the summit he had failed to climb; instead, he told people about the day he had learned to turn around."], "paragraphs_pt": ["Quando Rafael chegou à crista final, escalava havia catorze horas, e o ar rarefeito havia reduzido o mundo a um punhado de essenciais: o próximo passo, a próxima respiração, o fraco brilho amarelo da lanterna de cabeça da companheira em algum ponto acima. Ele passara três anos se preparando para aquela montanha, vendendo o carro e reorganizando a vida profissional em torno de planos de treino, e mesmo assim nada naquela preparação sugerira que o cume em si pareceria tanto uma pergunta, e não uma resposta.", "Veronika, a guia, escalava aquelas encostas desde antes de ele nascer. Movia-se com uma economia de esforço que beirava a indiferença, e o avisara no acampamento-base de que a montanha não recompensava ambição, apenas discernimento. Ele assentira com educação, convencido em segredo de que discernimento era uma virtude menor.", "A 8.400 metros, nuvens começaram a se juntar a oeste com uma lentidão quase teatral. Veronika parou, estudou o horizonte por muito tempo e disse, sem se virar, que teriam de descer. O cume estava talvez a duas horas. Rafael sentiu uma onda quente e irracional de raiva, do tipo que surge quando um sonho antigo é ameaçado por uma voz calma.", "Ele discutiu, é claro. Listou os anos, o dinheiro, os sacrifícios. Veronika ouviu sem interromper e, quando ele se esgotou, respondeu apenas que a montanha ainda estaria ali no ano seguinte, enquanto ele talvez não. Não era cruel nem sentimental, apenas verdade.", "Começaram a descida em silêncio. Várias horas depois, quando a tempestade desabou sobre a crista que haviam acabado de deixar, Rafael compreendeu, com uma clareza que o humilhou, que a maior conquista da expedição não tinha sido alcançar uma altura, mas aceitar um limite. Nunca falou do cume que não escalou; em vez disso, contava às pessoas sobre o dia em que aprendeu a dar meia-volta."], "hard_words": ["stripped", "judgment", "surge", "clarity"], "vocab": [{"word": "thin air", "meaning": "ar rarefeito", "note": ""}, {"word": "stripped", "meaning": "reduziu, despiu", "note": ""}, {"word": "economy of effort", "meaning": "economia de esforço", "note": ""}, {"word": "judgment", "meaning": "discernimento, bom senso", "note": ""}, {"word": "theatrical", "meaning": "teatral", "note": ""}, {"word": "surge", "meaning": "onda, surto", "note": ""}, {"word": "exhausted", "meaning": "esgotou-se", "note": ""}, {"word": "sentimental", "meaning": "sentimental", "note": ""}, {"word": "clarity", "meaning": "clareza", "note": ""}, {"word": "limit", "meaning": "limite", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "is", "be"], "irregular": ["reached", "had", "stripped", "spent", "suggested", "would", "born", "moved", "bordered", "warned", "did", "nodded", "convinced", "began", "paused", "studied", "said", "felt", "held", "threatened", "argued", "listed", "listened", "exhausted", "replied", "might", "broke", "left", "understood", "humbled", "spoke", "failed", "told", "learned"], "phrasal": ["turn around", "gather in"], "wh": ["when"], "connectors": ["and", "but", "so", "while", "instead", "before", "when", "since", "whereas", "yet", "still", "as"], "comparative": []}, "word_meanings": [{"word": "thin air", "meaning": "ar rarefeito", "note": ""}, {"word": "stripped", "meaning": "reduziu, despiu", "note": ""}, {"word": "economy of effort", "meaning": "economia de esforço", "note": ""}, {"word": "judgment", "meaning": "discernimento, bom senso", "note": ""}, {"word": "theatrical", "meaning": "teatral", "note": ""}, {"word": "surge", "meaning": "onda, surto", "note": ""}, {"word": "exhausted", "meaning": "esgotou-se", "note": ""}, {"word": "sentimental", "meaning": "sentimental", "note": ""}, {"word": "clarity", "meaning": "clareza", "note": ""}, {"word": "limit", "meaning": "limite", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect e past perfect continuous", "explanation_pt": "'had been climbing for fourteen hours' mostra duração anterior ao momento em que ele chega à crista."}, {"point": "Whereas e contraste", "explanation_pt": "'whereas he might not be' contrasta duas situações: a montanha permanece, ele talvez não."}], "multiple_choice": [{"question": "How long had Rafael been climbing when he reached the final ridge?", "options": ["Three years", "Fourteen hours", "Two hours", "Eight days"], "correct_index": 1, "explanation": "Ele escalava havia catorze horas."}, {"question": "What did Veronika say about the mountain?", "options": ["It hates visitors", "It is always kind", "It rewards judgment, not ambition", "It rewards speed"], "correct_index": 2, "explanation": "Ela disse que a montanha recompensa discernimento, não ambição."}, {"question": "Why did Veronika decide to descend?", "options": ["Rafael was ill", "They lost the route", "Clouds were gathering in the west", "They ran out of food"], "correct_index": 2, "explanation": "Nuvens se formavam a oeste."}, {"question": "How did Rafael react at first?", "options": ["With relief", "With silence", "With anger", "With laughter"], "correct_index": 2, "explanation": "Ele sentiu raiva e discutiu."}, {"question": "What did Rafael later tell people about?", "options": ["His fear of heights", "The day he learned to turn around", "His guide's mistake", "The summit he reached"], "correct_index": 1, "explanation": "Ele contava sobre o dia em que aprendeu a dar meia-volta."}], "open_questions": [{"question": "Is turning back a failure or a success? Explain.", "key_points_pt": ["defender uma posição", "relacionar a limites e segurança"]}, {"question": "Describe a time when you had to give up on something you wanted.", "key_points_pt": ["contar uma experiência", "usar passado e conectores de contraste"]}]}}, {"level": "C2", "genre": "adventure", "title": "The Caravan and the Stranger", "paragraphs": ["In the old trading town of Taghaza, merchants still told the story of the caravan that had walked into the Sahara carrying salt and had returned carrying something harder to name. It began with a stranger, a thin, sun-darkened man who appeared at the well one evening and asked to join the journey north. No one could say where he had come from, and Idris, the caravan master, who trusted instinct more than paperwork, agreed on one condition: the stranger would carry his own water.", "For eleven days the camels plodded across a landscape so vast that conversation seemed an impertinence. The stranger said little, yet he possessed an uncanny gift for reading the sky. On the sixth night he warned that the wind would turn within hours, and when the sandstorm struck at dawn, the caravan, already sheltered between two dunes, lost nothing but sleep.", "After that, the traders began to seek him out. They asked about routes, omens and the habits of distant towns, and he answered with a gentleness that made the questions feel smaller than they had seemed. Idris watched all this with the wary pride of a man who suspects that his authority is being quietly redistributed.", "At the northern oasis the stranger left as inconspicuously as he had arrived, taking only his water skin and a handful of dates. Years later, Idris told his grandchildren that he had never learned the man's name, nor why he had travelled, nor what he had hoped to find. But he had come to believe that some people appear in our lives not to be understood but to make us understand ourselves."], "paragraphs_pt": ["Na antiga cidade comercial de Taghaza, os mercadores ainda contavam a história da caravana que entrara no Saara carregando sal e voltara carregando algo mais difícil de nomear. Tudo começou com um estranho, um homem magro e queimado de sol que apareceu no poço numa noite e pediu para se juntar à jornada rumo ao norte. Ninguém sabia dizer de onde viera, e Idris, o chefe da caravana, que confiava mais no instinto do que em papéis, concordou com uma condição: o estranho levaria a própria água.", "Por onze dias os camelos arrastaram-se por uma paisagem tão vasta que conversar parecia uma impertinência. O estranho falava pouco, mas tinha um dom incrível para ler o céu. Na sexta noite avisou que o vento mudaria em poucas horas, e quando a tempestade de areia veio ao amanhecer, a caravana, já abrigada entre duas dunas, não perdeu nada além de sono.", "Depois disso, os comerciantes passaram a procurá-lo. Perguntavam sobre rotas, presságios e os costumes de cidades distantes, e ele respondia com uma delicadeza que fazia as perguntas parecerem menores do que eram. Idris observava tudo com o orgulho cauteloso de quem suspeita que sua autoridade está sendo discretamente redistribuída.", "No oásis do norte o estranho partiu tão discretamente quanto chegara, levando apenas seu odre de água e um punhado de tâmaras. Anos depois, Idris contou aos netos que nunca soube o nome do homem, nem por que viajava, nem o que esperava encontrar. Mas passara a acreditar que algumas pessoas surgem em nossas vidas não para serem compreendidas, mas para nos fazer compreender a nós mesmos."], "hard_words": ["plodded", "uncanny", "wary", "inconspicuously"], "vocab": [{"word": "merchants", "meaning": "mercadores", "note": ""}, {"word": "caravan", "meaning": "caravana", "note": ""}, {"word": "plodded", "meaning": "arrastaram-se", "note": ""}, {"word": "impertinence", "meaning": "impertinência", "note": ""}, {"word": "uncanny", "meaning": "incrível, quase sobrenatural", "note": ""}, {"word": "omens", "meaning": "presságios", "note": ""}, {"word": "wary", "meaning": "cauteloso", "note": ""}, {"word": "redistributed", "meaning": "redistribuída", "note": ""}, {"word": "inconspicuously", "meaning": "discretamente", "note": ""}, {"word": "oasis", "meaning": "oásis", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "being", "be"], "irregular": ["told", "had", "walked", "returned", "began", "darkened", "appeared", "asked", "could", "trusted", "agreed", "would", "plodded", "seemed", "said", "possessed", "warned", "struck", "sheltered", "lost", "answered", "made", "watched", "redistributed", "left", "arrived", "learned", "travelled", "hoped", "understood"], "phrasal": ["seek him out", "asked to join"], "wh": ["who", "what", "where", "when", "why"], "connectors": ["and", "but", "so", "after", "when", "yet", "still", "as"], "comparative": []}, "word_meanings": [{"word": "merchants", "meaning": "mercadores", "note": ""}, {"word": "caravan", "meaning": "caravana", "note": ""}, {"word": "plodded", "meaning": "arrastaram-se", "note": ""}, {"word": "impertinence", "meaning": "impertinência", "note": ""}, {"word": "uncanny", "meaning": "incrível, quase sobrenatural", "note": ""}, {"word": "omens", "meaning": "presságios", "note": ""}, {"word": "wary", "meaning": "cauteloso", "note": ""}, {"word": "redistributed", "meaning": "redistribuída", "note": ""}, {"word": "inconspicuously", "meaning": "discretamente", "note": ""}, {"word": "oasis", "meaning": "oásis", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'the caravan that had walked into the Sahara' vem antes do momento em que a história é contada."}, {"point": "Not... but... (contraste)", "explanation_pt": "'not to be understood but to make us understand ourselves' contrasta duas finalidades."}], "multiple_choice": [{"question": "What condition did Idris set for the stranger?", "options": ["He had to pay in salt", "He had to stay silent", "He had to carry his own water", "He had to lead the camels"], "correct_index": 2, "explanation": "O estranho teria de levar a própria água."}, {"question": "What special gift did the stranger have?", "options": ["Speaking many languages", "Healing animals", "Finding gold", "Reading the sky"], "correct_index": 3, "explanation": "Ele lia o céu."}, {"question": "What did the stranger warn about on the sixth night?", "options": ["An attack", "A change in the wind", "A lack of water", "A thief"], "correct_index": 1, "explanation": "Ele avisou que o vento mudaria."}, {"question": "How did Idris feel about the traders seeking the stranger?", "options": ["Angry at the camels", "Indifferent", "Wary, as if his authority was being redistributed", "Delighted"], "correct_index": 2, "explanation": "Ele sentiu cautela por sua autoridade."}, {"question": "What did Idris believe about people like the stranger?", "options": ["They belong to the desert", "They appear to help us understand ourselves", "They are always spies", "They bring bad luck"], "correct_index": 1, "explanation": "Algumas pessoas surgem para nos fazer compreender a nós mesmos."}], "open_questions": [{"question": "Have you ever met someone who changed you without staying long?", "key_points_pt": ["contar uma experiência", "usar passado e reflexão"]}, {"question": "Why might a leader feel uneasy about a newcomer who is respected?", "key_points_pt": ["falar de autoridade, insegurança e ciúme"]}]}}, {"level": "C2", "genre": "adventure", "title": "An Inventory of Small Maps", "paragraphs": ["Inés had inherited her grandfather's habit of drawing maps of places he had never been. Over decades he had filled an entire trunk with them, charts of imaginary islands, rivers that flowed uphill and cities named after people who, as far as anyone knew, had never existed. When he died, the family treated the trunk as an eccentric relic; Inés, however, suspected that each drawing concealed an instruction.", "She spent a winter cataloguing them. At first the maps seemed arbitrary, but gradually she noticed that certain details recurred: a lighthouse painted in red, a bridge with seven arches, a village built around a single enormous tree. The more she cross-referenced them, the more she suspected that these were not inventions but memories, rearranged by a mind that preferred metaphor to confession.", "Intrigued, she began to look for the real places. It took three years, two borrowed cars and a surprising number of conversations with strangers, but she eventually found the village, high in the Pyrenees, with its ancient chestnut at the centre of the square. An elderly woman recognised her grandfather's surname and, without explanation, led her to a house whose walls were covered in faded charcoal sketches.", "Inés understood then that the maps had never been guides to unknown lands; they had been letters, composed by a man who could not bring himself to say where he had truly come from. She stayed in the village until spring, drawing her own map, and for the first time in her life she marked her name at the centre."], "paragraphs_pt": ["Inés herdara do avô o hábito de desenhar mapas de lugares onde ele nunca estivera. Ao longo de décadas ele enchera um baú inteiro deles: cartas de ilhas imaginárias, rios que corriam morro acima e cidades com nomes de pessoas que, até onde se sabia, nunca existiram. Quando ele morreu, a família tratou o baú como uma relíquia excêntrica; Inés, porém, suspeitava que cada desenho escondia uma instrução.", "Ela passou um inverno catalogando-os. De início os mapas pareciam arbitrários, mas aos poucos notou que certos detalhes se repetiam: um farol pintado de vermelho, uma ponte de sete arcos, uma aldeia construída em volta de uma única árvore enorme. Quanto mais cruzava as informações, mais suspeitava que não eram invenções, mas memórias, reorganizadas por uma mente que preferia a metáfora à confissão.", "Intrigada, começou a procurar os lugares reais. Levou três anos, dois carros emprestados e um número surpreendente de conversas com estranhos, mas por fim encontrou a aldeia, no alto dos Pireneus, com sua antiga castanheira no centro da praça. Uma senhora idosa reconheceu o sobrenome do avô e, sem explicar, a levou até uma casa cujas paredes eram cobertas de esboços desbotados a carvão.", "Inés compreendeu então que os mapas nunca foram guias para terras desconhecidas; eram cartas, escritas por um homem que não conseguia dizer de onde realmente viera. Ficou na aldeia até a primavera, desenhando seu próprio mapa, e pela primeira vez na vida marcou seu nome no centro."], "hard_words": ["eccentric", "arbitrary", "recurred", "metaphor"], "vocab": [{"word": "inherited", "meaning": "herdara", "note": ""}, {"word": "eccentric", "meaning": "excêntrico", "note": ""}, {"word": "relic", "meaning": "relíquia", "note": ""}, {"word": "cataloguing", "meaning": "catalogando", "note": ""}, {"word": "arbitrary", "meaning": "arbitrário", "note": ""}, {"word": "recurred", "meaning": "se repetiam", "note": ""}, {"word": "cross-referenced", "meaning": "cruzava informações", "note": ""}, {"word": "metaphor", "meaning": "metáfora", "note": ""}, {"word": "chestnut", "meaning": "castanheira", "note": ""}, {"word": "charcoal", "meaning": "carvão (de desenho)", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "were"], "irregular": ["had", "inherited", "filled", "flowed", "named", "knew", "existed", "died", "treated", "suspected", "concealed", "spent", "seemed", "noticed", "recurred", "painted", "built", "referenced", "rearranged", "preferred", "intrigued", "began", "took", "borrowed", "found", "recognised", "led", "covered", "faded", "understood", "composed", "could", "stayed", "marked"], "phrasal": ["led her to"], "wh": ["who", "where", "when", "whose"], "connectors": ["and", "but", "however", "then", "after", "when", "until", "as"], "comparative": []}, "word_meanings": [{"word": "inherited", "meaning": "herdara", "note": ""}, {"word": "eccentric", "meaning": "excêntrico", "note": ""}, {"word": "relic", "meaning": "relíquia", "note": ""}, {"word": "cataloguing", "meaning": "catalogando", "note": ""}, {"word": "arbitrary", "meaning": "arbitrário", "note": ""}, {"word": "recurred", "meaning": "se repetiam", "note": ""}, {"word": "cross-referenced", "meaning": "cruzava informações", "note": ""}, {"word": "metaphor", "meaning": "metáfora", "note": ""}, {"word": "chestnut", "meaning": "castanheira", "note": ""}, {"word": "charcoal", "meaning": "carvão (de desenho)", "note": ""}], "exercises": {"grammar": [{"point": "Comparativos correlatos", "explanation_pt": "'The more she cross-referenced them, the more she suspected...' mostra que duas coisas aumentam juntas: 'quanto mais..., mais...'."}, {"point": "Past perfect", "explanation_pt": "'places he had never been' indica algo anterior ao momento da história."}], "multiple_choice": [{"question": "What was the grandfather's habit?", "options": ["Drawing maps of places he had never been", "Teaching geography", "Selling maps", "Collecting old maps"], "correct_index": 0, "explanation": "Ele desenhava mapas de lugares que nunca visitara."}, {"question": "What did Inés notice about the maps?", "options": ["They were all of her town", "They were written in code", "They were all the same size", "Certain details recurred"], "correct_index": 3, "explanation": "Alguns detalhes se repetiam."}, {"question": "Where did she find the real village?", "options": ["By the sea", "In the Pyrenees", "In the desert", "In a big city"], "correct_index": 1, "explanation": "A aldeia ficava nos Pireneus."}, {"question": "Who recognised the grandfather's surname?", "options": ["A child", "A priest", "An elderly woman", "A policeman"], "correct_index": 2, "explanation": "Uma senhora idosa reconheceu o sobrenome."}, {"question": "What did Inés understand about the maps?", "options": ["They were gifts for tourists", "They were treasure maps", "They were school drawings", "They were letters about where he came from"], "correct_index": 3, "explanation": "Os mapas eram cartas sobre sua origem."}], "open_questions": [{"question": "Can drawings or objects tell a person's secrets better than words?", "key_points_pt": ["discutir símbolos e memória", "usar exemplos"]}, {"question": "What would you leave behind to tell your family who you were?", "key_points_pt": ["descrever objetos ou textos", "usar condicional"]}]}}, {"level": "A1", "genre": "cooking", "title": "Eggs for Breakfast", "paragraphs": ["Nina is hungry. It is seven o'clock in the morning. She goes to the kitchen and takes two eggs, some butter and a pan.", "She puts the pan on the stove. She adds the butter and the eggs. The kitchen smells good.", "Nina puts the eggs on a plate with a piece of bread. She sits down and eats. \"Mmm, delicious!\" she says."], "paragraphs_pt": ["Nina está com fome. São sete horas da manhã. Ela vai à cozinha e pega dois ovos, um pouco de manteiga e uma frigideira.", "Ela coloca a frigideira no fogão. Adiciona a manteiga e os ovos. A cozinha fica com cheiro bom.", "Nina coloca os ovos em um prato com um pedaço de pão. Ela senta e come. \"Hum, delicioso!\", diz."], "hard_words": ["hungry", "pan", "stove", "delicious"], "vocab": [{"word": "hungry", "meaning": "com fome", "note": ""}, {"word": "kitchen", "meaning": "cozinha", "note": ""}, {"word": "eggs", "meaning": "ovos", "note": ""}, {"word": "butter", "meaning": "manteiga", "note": ""}, {"word": "pan", "meaning": "frigideira", "note": ""}, {"word": "stove", "meaning": "fogão", "note": ""}, {"word": "smells", "meaning": "cheira", "note": ""}, {"word": "plate", "meaning": "prato", "note": ""}, {"word": "delicious", "meaning": "delicioso", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": ["stove"], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "hungry", "meaning": "com fome", "note": ""}, {"word": "kitchen", "meaning": "cozinha", "note": ""}, {"word": "eggs", "meaning": "ovos", "note": ""}, {"word": "butter", "meaning": "manteiga", "note": ""}, {"word": "pan", "meaning": "frigideira", "note": ""}, {"word": "stove", "meaning": "fogão", "note": ""}, {"word": "smells", "meaning": "cheira", "note": ""}, {"word": "plate", "meaning": "prato", "note": ""}, {"word": "delicious", "meaning": "delicioso", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "Usamos o presente simples para rotinas e ações comuns: 'She goes', 'She adds', 'She eats'."}], "multiple_choice": [{"question": "What time is it?", "options": ["Seven o'clock", "Midnight", "Noon", "Ten o'clock"], "correct_index": 0, "explanation": "São sete horas da manhã."}, {"question": "How many eggs does Nina take?", "options": ["One", "Two", "Four", "Six"], "correct_index": 1, "explanation": "Ela pega dois ovos."}, {"question": "Where does Nina cook?", "options": ["In a restaurant", "In the kitchen", "At school", "In the garden"], "correct_index": 1, "explanation": "Ela cozinha na cozinha de casa."}, {"question": "What does she eat with the eggs?", "options": ["Bread", "Fruit", "Rice", "Soup"], "correct_index": 0, "explanation": "Ela come os ovos com um pedaço de pão."}, {"question": "What does Nina say at the end?", "options": ["I am tired", "Good night", "Where is my phone?", "Mmm, delicious!"], "correct_index": 3, "explanation": "Ela diz que está delicioso."}], "open_questions": [{"question": "What do you eat for breakfast?", "key_points_pt": ["citar alimentos", "usar 'I eat'"]}, {"question": "Do you like to cook? Why?", "key_points_pt": ["responder com 'I like' ou 'I don't like'"]}]}}, {"level": "A1", "genre": "cooking", "title": "A Simple Salad", "paragraphs": ["Today Paulo makes a salad for lunch. He has tomatoes, lettuce, an onion and a cucumber.", "First, he washes the vegetables. Then he cuts them into small pieces. He puts them in a big bowl.", "Now he adds a little oil, salt and lemon. He mixes everything with a spoon. The salad is fresh and colorful. His mother says, \"It looks great!\""], "paragraphs_pt": ["Hoje Paulo faz uma salada para o almoço. Ele tem tomates, alface, uma cebola e um pepino.", "Primeiro, ele lava os legumes. Depois os corta em pedaços pequenos. Ele os coloca numa tigela grande.", "Agora ele adiciona um pouco de óleo, sal e limão. Mistura tudo com uma colher. A salada está fresca e colorida. A mãe dele diz: \"Está ótima!\""], "hard_words": ["lettuce", "cucumber", "bowl", "spoon"], "vocab": [{"word": "salad", "meaning": "salada", "note": ""}, {"word": "lettuce", "meaning": "alface", "note": ""}, {"word": "onion", "meaning": "cebola", "note": ""}, {"word": "cucumber", "meaning": "pepino", "note": ""}, {"word": "vegetables", "meaning": "legumes", "note": ""}, {"word": "bowl", "meaning": "tigela", "note": ""}, {"word": "oil", "meaning": "óleo", "note": ""}, {"word": "spoon", "meaning": "colher", "note": ""}, {"word": "fresh", "meaning": "fresco", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "then"], "comparative": []}, "word_meanings": [{"word": "salad", "meaning": "salada", "note": ""}, {"word": "lettuce", "meaning": "alface", "note": ""}, {"word": "onion", "meaning": "cebola", "note": ""}, {"word": "cucumber", "meaning": "pepino", "note": ""}, {"word": "vegetables", "meaning": "legumes", "note": ""}, {"word": "bowl", "meaning": "tigela", "note": ""}, {"word": "oil", "meaning": "óleo", "note": ""}, {"word": "spoon", "meaning": "colher", "note": ""}, {"word": "fresh", "meaning": "fresco", "note": ""}], "exercises": {"grammar": [{"point": "First, then, now", "explanation_pt": "Palavras de sequência organizam os passos: 'First, he washes... Then he cuts... Now he adds...'."}], "multiple_choice": [{"question": "What does Paulo make?", "options": ["A sandwich", "A soup", "A cake", "A salad"], "correct_index": 3, "explanation": "Ele faz uma salada."}, {"question": "Which vegetable is in the salad?", "options": ["Carrots", "Tomatoes", "Potatoes", "Beans"], "correct_index": 1, "explanation": "A salada tem tomates."}, {"question": "What does Paulo do first?", "options": ["He eats", "He adds salt", "He mixes everything", "He washes the vegetables"], "correct_index": 3, "explanation": "Primeiro ele lava os legumes."}, {"question": "What does he use to mix?", "options": ["A knife", "A fork", "His hands", "A spoon"], "correct_index": 3, "explanation": "Ele mistura com uma colher."}, {"question": "Who says the salad looks great?", "options": ["His teacher", "His sister", "A friend", "His mother"], "correct_index": 3, "explanation": "A mãe dele elogia a salada."}], "open_questions": [{"question": "What is your favorite salad?", "key_points_pt": ["citar ingredientes", "usar 'I like'"]}, {"question": "What do you do first when you cook?", "key_points_pt": ["usar First, Then", "descrever os passos"]}]}}, {"level": "A2", "genre": "cooking", "title": "Pancakes on Sunday", "paragraphs": ["Every Sunday, Lucas and his little sister Bia make pancakes for the family. They like to start early, before everybody wakes up.", "First, they mix flour, milk and two eggs in a big bowl. Lucas is careful with the eggs, but Bia always gets some flour on her nose. Then they heat a pan and pour a little batter into it.", "When the pancakes are ready, they put them on a plate and add honey, bananas or chocolate. Their parents come to the kitchen and smile. \"This is the best part of the week,\" says their father."], "paragraphs_pt": ["Todo domingo, Lucas e sua irmã mais nova, Bia, fazem panquecas para a família. Eles gostam de começar cedo, antes de todo mundo acordar.", "Primeiro, misturam farinha, leite e dois ovos numa tigela grande. Lucas tem cuidado com os ovos, mas Bia sempre fica com farinha no nariz. Depois aquecem uma frigideira e despejam um pouco de massa nela.", "Quando as panquecas ficam prontas, colocam num prato e adicionam mel, bananas ou chocolate. Os pais chegam à cozinha e sorriem. \"Esta é a melhor parte da semana\", diz o pai."], "hard_words": ["flour", "batter", "pour", "honey"], "vocab": [{"word": "pancakes", "meaning": "panquecas", "note": ""}, {"word": "flour", "meaning": "farinha", "note": ""}, {"word": "batter", "meaning": "massa (líquida)", "note": ""}, {"word": "pour", "meaning": "despejar", "note": ""}, {"word": "honey", "meaning": "mel", "note": ""}, {"word": "heat", "meaning": "aquecer", "note": ""}, {"word": "careful", "meaning": "cuidadoso", "note": ""}, {"word": "wakes up", "meaning": "acorda", "note": ""}, {"word": "ready", "meaning": "pronto", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": ["wakes up"], "wh": ["when"], "connectors": ["and", "but", "then", "before", "when", "or"], "comparative": []}, "word_meanings": [{"word": "pancakes", "meaning": "panquecas", "note": ""}, {"word": "flour", "meaning": "farinha", "note": ""}, {"word": "batter", "meaning": "massa (líquida)", "note": ""}, {"word": "pour", "meaning": "despejar", "note": ""}, {"word": "honey", "meaning": "mel", "note": ""}, {"word": "heat", "meaning": "aquecer", "note": ""}, {"word": "careful", "meaning": "cuidadoso", "note": ""}, {"word": "wakes up", "meaning": "acorda", "note": ""}, {"word": "ready", "meaning": "pronto", "note": ""}], "exercises": {"grammar": [{"point": "Present simple e frequência", "explanation_pt": "'Every Sunday', 'always' mostram hábito: 'Bia always gets some flour on her nose.'"}, {"point": "Palavras de sequência", "explanation_pt": "'First', 'Then' e 'When' organizam a receita."}], "multiple_choice": [{"question": "When do Lucas and Bia make pancakes?", "options": ["Once a year", "Every Sunday", "On Fridays", "Every morning"], "correct_index": 1, "explanation": "Eles fazem todo domingo."}, {"question": "What do they mix first?", "options": ["Honey and bananas", "Butter and sugar", "Flour, milk and eggs", "Rice and beans"], "correct_index": 2, "explanation": "Eles misturam farinha, leite e ovos."}, {"question": "Who always gets flour on her nose?", "options": ["Bia", "Their father", "Lucas", "Their mother"], "correct_index": 0, "explanation": "Bia sempre fica com farinha no nariz."}, {"question": "What can they add on top?", "options": ["Salt or pepper", "Cheese or ham", "Tomatoes", "Honey, bananas or chocolate"], "correct_index": 3, "explanation": "Eles colocam mel, bananas ou chocolate."}, {"question": "What does the father say?", "options": ["Where is the milk?", "This is the best part of the week", "I am hungry", "It is too hot"], "correct_index": 1, "explanation": "Ele diz que é a melhor parte da semana."}], "open_questions": [{"question": "Do you have a family food tradition?", "key_points_pt": ["descrever uma tradição", "usar presente simples"]}, {"question": "What toppings do you like on pancakes?", "key_points_pt": ["listar ingredientes e justificar"]}]}}, {"level": "A2", "genre": "cooking", "title": "The Birthday Cake", "paragraphs": ["Sara wants to make a cake for her mother's birthday. She does not cook very often, so she finds a recipe on the internet and goes to the supermarket. She buys sugar, butter, eggs, flour and strawberries.", "At home she follows the recipe step by step. She mixes the butter and the sugar, adds the eggs and then the flour. The kitchen is a mess, but she is happy. She puts the cake in the oven for forty minutes.", "While the cake is baking, she cuts the strawberries and makes a cream. When her mother comes home, the cake is on the table with a small candle. \"Happy birthday, Mom!\" says Sara. Her mother cries a little and gives her a big hug."], "paragraphs_pt": ["Sara quer fazer um bolo para o aniversário da mãe. Ela não cozinha com frequência, então acha uma receita na internet e vai ao supermercado. Compra açúcar, manteiga, ovos, farinha e morangos.", "Em casa ela segue a receita passo a passo. Mistura a manteiga e o açúcar, adiciona os ovos e depois a farinha. A cozinha fica uma bagunça, mas ela está feliz. Coloca o bolo no forno por quarenta minutos.", "Enquanto o bolo assa, ela corta os morangos e faz um creme. Quando a mãe chega em casa, o bolo está na mesa com uma velinha. \"Feliz aniversário, mamãe!\", diz Sara. A mãe chora um pouco e dá nela um grande abraço."], "hard_words": ["recipe", "oven", "candle", "hug"], "vocab": [{"word": "recipe", "meaning": "receita", "note": ""}, {"word": "supermarket", "meaning": "supermercado", "note": ""}, {"word": "sugar", "meaning": "açúcar", "note": ""}, {"word": "strawberries", "meaning": "morangos", "note": ""}, {"word": "step by step", "meaning": "passo a passo", "note": ""}, {"word": "oven", "meaning": "forno", "note": ""}, {"word": "mess", "meaning": "bagunça", "note": ""}, {"word": "candle", "meaning": "vela", "note": ""}, {"word": "hug", "meaning": "abraço", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": ["step by step"], "wh": ["when"], "connectors": ["and", "but", "so", "while", "then", "when"], "comparative": []}, "word_meanings": [{"word": "recipe", "meaning": "receita", "note": ""}, {"word": "supermarket", "meaning": "supermercado", "note": ""}, {"word": "sugar", "meaning": "açúcar", "note": ""}, {"word": "strawberries", "meaning": "morangos", "note": ""}, {"word": "step by step", "meaning": "passo a passo", "note": ""}, {"word": "oven", "meaning": "forno", "note": ""}, {"word": "mess", "meaning": "bagunça", "note": ""}, {"word": "candle", "meaning": "vela", "note": ""}, {"word": "hug", "meaning": "abraço", "note": ""}], "exercises": {"grammar": [{"point": "Present simple para instruções", "explanation_pt": "Ao contar os passos de uma receita, usamos o presente: 'She mixes', 'She adds', 'She puts'."}, {"point": "While", "explanation_pt": "'While the cake is baking' mostra duas ações ao mesmo tempo."}], "multiple_choice": [{"question": "Why does Sara make a cake?", "options": ["For her mother's birthday", "For a party at work", "For her school", "For her dog"], "correct_index": 0, "explanation": "O bolo é para o aniversário da mãe."}, {"question": "Where does Sara find the recipe?", "options": ["From her neighbor", "From her teacher", "In a book", "On the internet"], "correct_index": 3, "explanation": "Ela encontra a receita na internet."}, {"question": "How long is the cake in the oven?", "options": ["Two hours", "Forty minutes", "One hour", "Ten minutes"], "correct_index": 1, "explanation": "O bolo fica quarenta minutos no forno."}, {"question": "What does Sara do while the cake is baking?", "options": ["She watches TV", "She cuts strawberries and makes a cream", "She sleeps", "She goes shopping"], "correct_index": 1, "explanation": "Ela corta morangos e faz um creme."}, {"question": "How does the mother react?", "options": ["She goes to bed", "She laughs loudly", "She says nothing", "She cries a little and hugs Sara"], "correct_index": 3, "explanation": "A mãe chora um pouco e abraça Sara."}], "open_questions": [{"question": "Have you ever made a gift for someone? What was it?", "key_points_pt": ["descrever um presente", "usar passado"]}, {"question": "Why is it special to cook for someone?", "key_points_pt": ["explicar com exemplos pessoais"]}]}}, {"level": "B1", "genre": "cooking", "title": "Grandma's Pão de Queijo", "paragraphs": ["Every time Marina visits her grandmother in Minas Gerais, the first thing she smells is warm cheese bread coming from the kitchen. This year she decided that she was not going to leave without learning the recipe.", "Her grandmother laughed and said that the recipe was not written anywhere. \"You have to feel it,\" she explained, pushing a bowl of cassava starch toward Marina. Marina, who liked exact measurements, felt a little lost when she heard that.", "Together they mixed the starch with hot milk, oil and eggs, and then added a lot of grated cheese. The dough was sticky, and Marina's hands soon became a disaster. Her grandmother showed her how to roll small balls without letting them stick.", "When the first tray came out of the oven, the balls were golden, soft inside and slightly crunchy outside. Marina bit into one and burned her tongue, but she did not care. She took out her phone and wrote down every detail, not as measurements, but as feelings: \"dough should feel like earlobe.\""], "paragraphs_pt": ["Toda vez que Marina visita a avó em Minas Gerais, a primeira coisa que ela sente é o cheiro de pão de queijo quente vindo da cozinha. Este ano ela decidiu que não iria embora sem aprender a receita.", "A avó riu e disse que a receita não estava escrita em lugar nenhum. \"Você tem que sentir\", explicou, empurrando uma tigela de polvilho em direção a Marina. Marina, que gostava de medidas exatas, ficou um pouco perdida ao ouvir isso.", "Juntas, misturaram o polvilho com leite quente, óleo e ovos, e depois adicionaram bastante queijo ralado. A massa estava grudenta, e as mãos de Marina logo viraram um desastre. A avó mostrou como enrolar bolinhas sem deixar grudar.", "Quando a primeira assadeira saiu do forno, as bolinhas estavam douradas, macias por dentro e um pouco crocantes por fora. Marina deu uma mordida e queimou a língua, mas não se importou. Pegou o celular e anotou cada detalhe, não como medidas, mas como sensações: \"a massa deve parecer lóbulo de orelha.\""], "hard_words": ["measurements", "grated", "sticky", "crunchy"], "vocab": [{"word": "cheese bread", "meaning": "pão de queijo", "note": ""}, {"word": "cassava starch", "meaning": "polvilho (fécula de mandioca)", "note": ""}, {"word": "measurements", "meaning": "medidas", "note": ""}, {"word": "grated", "meaning": "ralado", "note": ""}, {"word": "dough", "meaning": "massa", "note": ""}, {"word": "sticky", "meaning": "grudenta", "note": ""}, {"word": "tray", "meaning": "assadeira", "note": ""}, {"word": "crunchy", "meaning": "crocante", "note": ""}, {"word": "burned", "meaning": "queimou", "note": ""}, {"word": "earlobe", "meaning": "lóbulo da orelha", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was", "were"], "irregular": ["decided", "laughed", "said", "written", "explained", "liked", "felt", "lost", "heard", "mixed", "added", "grated", "became", "showed", "came", "bit", "burned", "did", "took", "wrote", "should"], "phrasal": ["came out", "wrote down"], "wh": ["who", "when", "how"], "connectors": ["and", "but", "then", "when", "as"], "comparative": []}, "word_meanings": [{"word": "cheese bread", "meaning": "pão de queijo", "note": ""}, {"word": "cassava starch", "meaning": "polvilho (fécula de mandioca)", "note": ""}, {"word": "measurements", "meaning": "medidas", "note": ""}, {"word": "grated", "meaning": "ralado", "note": ""}, {"word": "dough", "meaning": "massa", "note": ""}, {"word": "sticky", "meaning": "grudenta", "note": ""}, {"word": "tray", "meaning": "assadeira", "note": ""}, {"word": "crunchy", "meaning": "crocante", "note": ""}, {"word": "burned", "meaning": "queimou", "note": ""}, {"word": "earlobe", "meaning": "lóbulo da orelha", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "A história usa o passado simples para ações terminadas: 'her grandmother laughed', 'they mixed the starch'."}, {"point": "Reported speech", "explanation_pt": "'She decided that she was not going to leave' relata um pensamento passado com 'was going to'."}], "multiple_choice": [{"question": "Where does Marina's grandmother live?", "options": ["In Bahia", "In Minas Gerais", "In São Paulo", "In Rio"], "correct_index": 1, "explanation": "A avó mora em Minas Gerais."}, {"question": "Why does Marina feel lost?", "options": ["The kitchen is dirty", "She does not like cheese", "The recipe is not written down", "She has no phone"], "correct_index": 2, "explanation": "A receita não estava escrita."}, {"question": "What do they add after the milk, oil and eggs?", "options": ["A lot of grated cheese", "Tomatoes", "Sugar", "Chocolate"], "correct_index": 0, "explanation": "Eles adicionam bastante queijo ralado."}, {"question": "What happens when Marina bites the first one?", "options": ["She drops it", "She burns her tongue", "She does not like it", "She gives it to her dog"], "correct_index": 1, "explanation": "Ela queima a língua, mas não se importa."}, {"question": "How does Marina write the recipe?", "options": ["As a video", "As a song", "As feelings, not measurements", "As a drawing"], "correct_index": 2, "explanation": "Ela anota as sensações, não medidas."}], "open_questions": [{"question": "Do you think recipes should always have exact measurements? Why?", "key_points_pt": ["comparar cozinhar por intuição e por medidas"]}, {"question": "What dish reminds you of someone in your family?", "key_points_pt": ["descrever o prato e a pessoa", "usar passado"]}]}}, {"level": "B1", "genre": "cooking", "title": "The Food Truck Experiment", "paragraphs": ["Daniel worked as an accountant, but every weekend he dreamed of a different life. He wanted to sell his famous street tacos from a small food truck. After months of saving money, he finally bought an old van and painted it bright orange.", "The first Saturday was a disaster. It started to rain, the gas ran out in the middle of the lunch rush, and he burned most of the meat. Only three customers came, and one of them was his sister, who ate her taco politely and told him it was \"interesting.\"", "Daniel almost gave up. However, on Sunday a man stopped by and asked for the sauce recipe. Daniel had spent two years perfecting that sauce, but instead of being nervous, he felt proud. The man bought six tacos and returned the next day with ten friends.", "After a month, there was a line in front of the truck every weekend. Daniel did not quit his accounting job, at least not yet, but he realized that failing on the first day had taught him more than any business book."], "paragraphs_pt": ["Daniel trabalhava como contador, mas todo fim de semana sonhava com outra vida. Queria vender seus famosos tacos de rua em um pequeno food truck. Depois de meses juntando dinheiro, ele finalmente comprou uma van velha e a pintou de laranja vivo.", "O primeiro sábado foi um desastre. Começou a chover, o gás acabou no meio da correria do almoço e ele queimou quase toda a carne. Só três clientes vieram, e um deles era sua irmã, que comeu o taco educadamente e disse que era \"interessante.\"", "Daniel quase desistiu. No entanto, no domingo um homem parou e pediu a receita do molho. Daniel passara dois anos aperfeiçoando aquele molho, mas, em vez de ficar nervoso, sentiu orgulho. O homem comprou seis tacos e voltou no dia seguinte com dez amigos.", "Depois de um mês, havia fila na frente do food truck todo fim de semana. Daniel não largou o emprego de contador, pelo menos ainda não, mas percebeu que falhar no primeiro dia lhe ensinara mais do que qualquer livro de negócios."], "hard_words": ["accountant", "rush", "perfecting", "sauce"], "vocab": [{"word": "accountant", "meaning": "contador", "note": ""}, {"word": "street tacos", "meaning": "tacos de rua", "note": ""}, {"word": "saving money", "meaning": "juntando dinheiro", "note": ""}, {"word": "van", "meaning": "van, furgão", "note": ""}, {"word": "rush", "meaning": "correria", "note": ""}, {"word": "customers", "meaning": "clientes", "note": ""}, {"word": "gave up", "meaning": "desistiu", "note": ""}, {"word": "sauce", "meaning": "molho", "note": ""}, {"word": "perfecting", "meaning": "aperfeiçoando", "note": ""}, {"word": "line", "meaning": "fila", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being"], "irregular": ["worked", "dreamed", "wanted", "bought", "painted", "started", "ran", "burned", "came", "ate", "told", "gave", "stopped", "asked", "had", "spent", "felt", "returned", "did", "realized", "taught"], "phrasal": ["ran out", "gave up", "stopped by"], "wh": ["who"], "connectors": ["and", "but", "however", "instead", "after", "yet", "finally", "as"], "comparative": []}, "word_meanings": [{"word": "accountant", "meaning": "contador", "note": ""}, {"word": "street tacos", "meaning": "tacos de rua", "note": ""}, {"word": "saving money", "meaning": "juntando dinheiro", "note": ""}, {"word": "van", "meaning": "van, furgão", "note": ""}, {"word": "rush", "meaning": "correria", "note": ""}, {"word": "customers", "meaning": "clientes", "note": ""}, {"word": "gave up", "meaning": "desistiu", "note": ""}, {"word": "sauce", "meaning": "molho", "note": ""}, {"word": "perfecting", "meaning": "aperfeiçoando", "note": ""}, {"word": "line", "meaning": "fila", "note": ""}], "exercises": {"grammar": [{"point": "Past simple e past perfect", "explanation_pt": "'Daniel had spent two years perfecting that sauce' mostra algo que aconteceu antes do momento principal."}, {"point": "However", "explanation_pt": "'However' introduz um contraste e vem no início da frase, seguido de vírgula."}], "multiple_choice": [{"question": "What was Daniel's regular job?", "options": ["Driver", "Cook", "Teacher", "Accountant"], "correct_index": 3, "explanation": "Ele era contador."}, {"question": "What went wrong on Saturday?", "options": ["Rain, no gas and burned meat", "He forgot the tacos", "The truck was stolen", "The police came"], "correct_index": 0, "explanation": "Choveu, o gás acabou e a carne queimou."}, {"question": "What did the man ask for on Sunday?", "options": ["The sauce recipe", "A job", "A photo", "A free taco"], "correct_index": 0, "explanation": "Ele pediu a receita do molho."}, {"question": "How many friends came with the man the next day?", "options": ["Ten", "None", "Two", "Six"], "correct_index": 0, "explanation": "Ele voltou com dez amigos."}, {"question": "What did Daniel learn from the first day?", "options": ["To use a bigger truck", "Failing taught him a lot", "Never to cook", "To sell cheaper"], "correct_index": 1, "explanation": "Ele aprendeu mais com o fracasso do que com livros."}], "open_questions": [{"question": "Would you leave a safe job to follow a dream? Why or why not?", "key_points_pt": ["defender uma decisão com motivos", "usar conectores"]}, {"question": "How can a failure become a good lesson?", "key_points_pt": ["dar exemplos pessoais"]}]}}, {"level": "B1", "genre": "cooking", "title": "The Cooking Class in Naples", "paragraphs": ["When Elena booked a week in Naples, she expected museums, beaches and a lot of walking. What she had not expected was to spend an entire morning in a tiny kitchen, learning to make pizza dough with a seventy-year-old chef named Gennaro.", "Gennaro spoke little English, but he did not need many words. He showed Elena how to knead the dough with the heel of her hand and how to stretch it gently until it became thin, almost transparent. \"Do not fight the dough,\" he said in slow English. \"Talk to it.\"", "Elena laughed, but after a few minutes she noticed that her movements really were calmer. The dough became soft and elastic, and for the first time she understood why people said that cooking could be a kind of meditation.", "At the end of the class, they ate the pizzas together on the street, standing next to a small table. Elena paid for the lesson and left a big tip, but what she remembered most was the moment when Gennaro put a hand on his heart and said, \"Now you are Neapolitan.\""], "paragraphs_pt": ["Quando Elena reservou uma semana em Nápoles, esperava museus, praias e muita caminhada. O que ela não esperava era passar uma manhã inteira numa cozinha minúscula, aprendendo a fazer massa de pizza com um chef de setenta anos chamado Gennaro.", "Gennaro falava pouco inglês, mas não precisava de muitas palavras. Mostrou a Elena como sovar a massa com a base da mão e como esticá-la com delicadeza até ficar fina, quase transparente. \"Não lute com a massa\", disse em inglês lento. \"Converse com ela.\"", "Elena riu, mas após alguns minutos notou que seus movimentos realmente estavam mais calmos. A massa ficou macia e elástica e, pela primeira vez, ela entendeu por que as pessoas diziam que cozinhar podia ser uma forma de meditação.", "No fim da aula, comeram as pizzas juntos na rua, em pé ao lado de uma mesinha. Elena pagou pela aula e deixou uma gorjeta generosa, mas o que mais lembrou foi o momento em que Gennaro pôs a mão no coração e disse: \"Agora você é napolitana.\""], "hard_words": ["knead", "transparent", "elastic", "meditation"], "vocab": [{"word": "booked", "meaning": "reservou", "note": ""}, {"word": "dough", "meaning": "massa", "note": ""}, {"word": "knead", "meaning": "sovar", "note": ""}, {"word": "stretch", "meaning": "esticar", "note": ""}, {"word": "transparent", "meaning": "transparente", "note": ""}, {"word": "elastic", "meaning": "elástica", "note": ""}, {"word": "meditation", "meaning": "meditação", "note": ""}, {"word": "tip", "meaning": "gorjeta", "note": ""}, {"word": "heart", "meaning": "coração", "note": ""}, {"word": "Neapolitan", "meaning": "napolitano", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "be", "are"], "irregular": ["booked", "expected", "had", "named", "spoke", "did", "showed", "became", "said", "laughed", "noticed", "understood", "could", "ate", "paid", "left", "remembered"], "phrasal": ["put a hand on"], "wh": ["what", "when", "why", "how"], "connectors": ["and", "but", "after", "when", "until"], "comparative": []}, "word_meanings": [{"word": "booked", "meaning": "reservou", "note": ""}, {"word": "dough", "meaning": "massa", "note": ""}, {"word": "knead", "meaning": "sovar", "note": ""}, {"word": "stretch", "meaning": "esticar", "note": ""}, {"word": "transparent", "meaning": "transparente", "note": ""}, {"word": "elastic", "meaning": "elástica", "note": ""}, {"word": "meditation", "meaning": "meditação", "note": ""}, {"word": "tip", "meaning": "gorjeta", "note": ""}, {"word": "heart", "meaning": "coração", "note": ""}, {"word": "Neapolitan", "meaning": "napolitano", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'What she had not expected' indica algo que não esperava antes de viver a experiência."}, {"point": "Comparação com 'more... than' e 'almost'", "explanation_pt": "'almost transparent' mostra quase um estado: 'quase transparente'."}], "multiple_choice": [{"question": "What did Elena expect from Naples?", "options": ["Only food", "Only work", "Only shopping", "Museums, beaches and walking"], "correct_index": 3, "explanation": "Ela esperava museus, praias e caminhadas."}, {"question": "Who was Gennaro?", "options": ["A museum guide", "A taxi driver", "A waiter", "A seventy-year-old chef"], "correct_index": 3, "explanation": "Gennaro era um chef de setenta anos."}, {"question": "What did Gennaro say about the dough?", "options": ["Talk to it", "Throw it", "Cut it", "Leave it"], "correct_index": 0, "explanation": "Ele pediu para conversar com a massa."}, {"question": "How did Elena feel after a few minutes?", "options": ["Sleepy", "Calmer", "Afraid", "Angry"], "correct_index": 1, "explanation": "Ela notou que estava mais calma."}, {"question": "What did Gennaro say at the end?", "options": ["Come back tomorrow", "You made a mistake", "You must pay more", "Now you are Neapolitan"], "correct_index": 3, "explanation": "Ele disse que agora ela era napolitana."}], "open_questions": [{"question": "Have you ever learned something from a person who did not speak your language?", "key_points_pt": ["contar uma experiência", "falar de gestos e comunicação"]}, {"question": "Why can cooking feel relaxing?", "key_points_pt": ["explicar concentração e rotina"]}]}}, {"level": "B2", "genre": "cooking", "title": "The Restaurant That Almost Closed", "paragraphs": ["When Helena inherited her father's small restaurant, it was losing money every month. The menu had not changed in twenty years, the paint was peeling off the walls and the only regular customers were a few retired men who ordered coffee and stayed for hours.", "Instead of firing the elderly cook, Mr. Aurélio, she sat with him one afternoon and asked about the dishes he had once been proud of. His eyes lit up. He described a fish stew his mother made on the coast, a dish he had stopped preparing because, in his words, \"nobody wants old-fashioned food.\"", "Helena persuaded him to cook it for a small group of friends. They loved it so much that two of them posted photos online, and within a week the restaurant was fully booked on Friday night. She slowly rebuilt the menu around Mr. Aurélio's memories, giving each dish a small card that told its story.", "A year later, a food critic wrote that the restaurant had managed to be both traditional and surprising. Helena kept the review on the wall, next to a photo of her father. She knew he would have been proud, but she also knew that the real credit belonged to an old cook who had been forgotten until someone finally asked him a question."], "paragraphs_pt": ["Quando Helena herdou o pequeno restaurante do pai, ele estava perdendo dinheiro todo mês. O cardápio não mudava havia vinte anos, a tinta descascava nas paredes e os únicos clientes fixos eram alguns aposentados que pediam café e ficavam horas.", "Em vez de demitir o cozinheiro idoso, o Sr. Aurélio, ela se sentou com ele numa tarde e perguntou sobre os pratos de que ele já se orgulhara. Os olhos dele se acenderam. Ele descreveu um ensopado de peixe que a mãe fazia no litoral, prato que parara de preparar porque, nas palavras dele, \"ninguém quer comida antiquada.\"", "Helena o convenceu a cozinhá-lo para um pequeno grupo de amigos. Eles gostaram tanto que dois postaram fotos na internet e, em uma semana, o restaurante estava lotado na sexta à noite. Aos poucos ela reconstruiu o cardápio em torno das memórias do Sr. Aurélio, dando a cada prato um cartão que contava sua história.", "Um ano depois, um crítico gastronômico escreveu que o restaurante conseguira ser tradicional e surpreendente ao mesmo tempo. Helena deixou a crítica na parede, ao lado de uma foto do pai. Sabia que ele teria ficado orgulhoso, mas também sabia que o verdadeiro mérito era de um velho cozinheiro que fora esquecido até que alguém finalmente lhe fizesse uma pergunta."], "hard_words": ["peeling", "stew", "persuaded", "credit"], "vocab": [{"word": "inherited", "meaning": "herdou", "note": ""}, {"word": "peeling", "meaning": "descascando", "note": ""}, {"word": "retired", "meaning": "aposentados", "note": ""}, {"word": "stew", "meaning": "ensopado", "note": ""}, {"word": "old-fashioned", "meaning": "antiquado", "note": ""}, {"word": "persuaded", "meaning": "convenceu", "note": ""}, {"word": "fully booked", "meaning": "lotado (reservado)", "note": ""}, {"word": "critic", "meaning": "crítico", "note": ""}, {"word": "credit", "meaning": "mérito, crédito", "note": ""}, {"word": "forgotten", "meaning": "esquecido", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been", "be"], "irregular": ["inherited", "had", "changed", "retired", "ordered", "stayed", "sat", "asked", "lit", "described", "made", "stopped", "fashioned", "persuaded", "loved", "posted", "booked", "rebuilt", "told", "wrote", "managed", "kept", "knew", "would", "belonged", "forgotten"], "phrasal": ["lit up", "stayed for hours"], "wh": ["who", "when"], "connectors": ["and", "but", "because", "so", "instead", "when", "until", "also", "finally", "once"], "comparative": []}, "word_meanings": [{"word": "inherited", "meaning": "herdou", "note": ""}, {"word": "peeling", "meaning": "descascando", "note": ""}, {"word": "retired", "meaning": "aposentados", "note": ""}, {"word": "stew", "meaning": "ensopado", "note": ""}, {"word": "old-fashioned", "meaning": "antiquado", "note": ""}, {"word": "persuaded", "meaning": "convenceu", "note": ""}, {"word": "fully booked", "meaning": "lotado (reservado)", "note": ""}, {"word": "critic", "meaning": "crítico", "note": ""}, {"word": "credit", "meaning": "mérito, crédito", "note": ""}, {"word": "forgotten", "meaning": "esquecido", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'he had once been proud of' e 'he had stopped preparing' indicam fatos anteriores ao momento da conversa."}, {"point": "Instead of + -ing", "explanation_pt": "'Instead of firing the cook' significa 'em vez de demitir o cozinheiro'."}], "multiple_choice": [{"question": "What was wrong with the restaurant at the start?", "options": ["It had no cook", "It was too big", "It was too noisy", "It was losing money"], "correct_index": 3, "explanation": "Ele perdia dinheiro todo mês."}, {"question": "What did Helena do instead of firing Mr. Aurélio?", "options": ["She hired a new cook", "She closed on Fridays", "She asked about his favorite dishes", "She changed the name"], "correct_index": 2, "explanation": "Ela perguntou sobre os pratos de que ele se orgulhava."}, {"question": "Why had Mr. Aurélio stopped making the fish stew?", "options": ["He had no fish", "He forgot the recipe", "He thought nobody wanted old-fashioned food", "It was too expensive"], "correct_index": 2, "explanation": "Ele achava que ninguém queria comida antiquada."}, {"question": "What helped fill the restaurant?", "options": ["A new chef", "A TV ad", "A discount", "Photos posted online"], "correct_index": 3, "explanation": "Fotos postadas na internet encheram o restaurante."}, {"question": "Who did Helena think deserved the real credit?", "options": ["The customers", "The old cook", "Her father", "The critic"], "correct_index": 1, "explanation": "O mérito era do velho cozinheiro."}], "open_questions": [{"question": "How can listening to older people help a business?", "key_points_pt": ["discutir memória, tradição e inovação"]}, {"question": "What makes a restaurant memorable for you?", "key_points_pt": ["citar comida, ambiente e atendimento"]}]}}, {"level": "B2", "genre": "cooking", "title": "Competing With a Sourdough Starter", "paragraphs": ["When the pandemic began, Tomás started a sourdough starter in a jar, mainly because he was bored. He named it Gerald, fed it every morning with flour and water, and waited for the first bubbles with the nervous excitement of a new parent.", "Weeks later, his first loaf looked more like a brick than bread, but he refused to give up. He watched videos, read forums and bought a small scale to measure everything precisely. By summer he was baking three loaves a week, and neighbors began to leave notes in his mailbox asking if there were any extras.", "The hobby slowly turned into an obsession. Tomás bought special flours, tested different temperatures and kept a detailed notebook. His girlfriend joked that the kitchen had become a laboratory, and she was not entirely wrong.", "Eventually, he entered a local baking contest, expecting nothing. He did not win, but a judge told him that his bread had an unusual depth of flavor. Tomás went home, fed Gerald and realized that the real prize had been something else: for the first time in years, he had found something that made him patient."], "paragraphs_pt": ["Quando a pandemia começou, Tomás iniciou um fermento natural num pote, principalmente porque estava entediado. Deu o nome de Gerald, alimentava-o toda manhã com farinha e água e esperava as primeiras bolhas com a ansiedade de um pai novo.", "Semanas depois, seu primeiro pão parecia mais um tijolo do que pão, mas ele se recusou a desistir. Assistiu a vídeos, leu fóruns e comprou uma balança pequena para medir tudo com precisão. No verão já assava três pães por semana, e os vizinhos começaram a deixar bilhetes na caixa de correio perguntando se havia algum sobrando.", "O hobby foi virando obsessão. Tomás comprou farinhas especiais, testou diferentes temperaturas e mantinha um caderno detalhado. A namorada brincava que a cozinha virara um laboratório, e não estava totalmente errada.", "Por fim, inscreveu-se num concurso local de panificação, sem esperar nada. Não ganhou, mas um jurado disse que o pão tinha uma profundidade de sabor incomum. Tomás voltou para casa, alimentou Gerald e percebeu que o verdadeiro prêmio era outro: pela primeira vez em anos, encontrara algo que o tornava paciente."], "hard_words": ["loaf", "obsession", "contest", "judge"], "vocab": [{"word": "sourdough starter", "meaning": "fermento natural", "note": ""}, {"word": "bored", "meaning": "entediado", "note": ""}, {"word": "loaf", "meaning": "pão (unidade)", "note": ""}, {"word": "brick", "meaning": "tijolo", "note": ""}, {"word": "scale", "meaning": "balança", "note": ""}, {"word": "extras", "meaning": "sobras", "note": ""}, {"word": "obsession", "meaning": "obsessão", "note": ""}, {"word": "laboratory", "meaning": "laboratório", "note": ""}, {"word": "contest", "meaning": "concurso", "note": ""}, {"word": "judge", "meaning": "jurado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been"], "irregular": ["began", "started", "bored", "named", "fed", "waited", "looked", "refused", "watched", "bought", "turned", "tested", "kept", "detailed", "joked", "had", "entered", "did", "told", "went", "realized", "found", "made"], "phrasal": ["give up", "turned into"], "wh": ["when"], "connectors": ["and", "but", "because", "when", "if"], "comparative": []}, "word_meanings": [{"word": "sourdough starter", "meaning": "fermento natural", "note": ""}, {"word": "bored", "meaning": "entediado", "note": ""}, {"word": "loaf", "meaning": "pão (unidade)", "note": ""}, {"word": "brick", "meaning": "tijolo", "note": ""}, {"word": "scale", "meaning": "balança", "note": ""}, {"word": "extras", "meaning": "sobras", "note": ""}, {"word": "obsession", "meaning": "obsessão", "note": ""}, {"word": "laboratory", "meaning": "laboratório", "note": ""}, {"word": "contest", "meaning": "concurso", "note": ""}, {"word": "judge", "meaning": "jurado", "note": ""}], "exercises": {"grammar": [{"point": "Past simple e past perfect", "explanation_pt": "'he had found something' indica algo conquistado antes do momento de reflexão."}, {"point": "Mais do que contraste com 'but'", "explanation_pt": "'but he refused to give up' mostra persistência apesar do fracasso."}], "multiple_choice": [{"question": "Why did Tomás start the sourdough starter?", "options": ["He was bored", "His mother asked him", "He lost his job", "He wanted to open a bakery"], "correct_index": 0, "explanation": "Ele estava entediado na pandemia."}, {"question": "How did his first loaf look?", "options": ["Perfect", "Very small", "Burned black", "More like a brick than bread"], "correct_index": 3, "explanation": "Parecia mais um tijolo."}, {"question": "What did neighbors leave in his mailbox?", "options": ["Complaints", "Flowers", "Notes asking for extras", "Money"], "correct_index": 2, "explanation": "Eles deixavam bilhetes pedindo pães sobrando."}, {"question": "What did the judge say?", "options": ["He should stop baking", "He won first prize", "The bread was too dry", "The bread had an unusual depth of flavor"], "correct_index": 3, "explanation": "O jurado elogiou a profundidade de sabor."}, {"question": "What was the real prize for Tomás?", "options": ["Becoming famous", "Moving away", "Making money", "Becoming patient"], "correct_index": 3, "explanation": "Ele ficou mais paciente."}], "open_questions": [{"question": "Can a simple hobby change a person's habits? Give an example.", "key_points_pt": ["discutir hobbies e paciência"]}, {"question": "Why do people start cooking projects during difficult times?", "key_points_pt": ["falar de rotina, controle e conforto"]}]}}, {"level": "B2", "genre": "cooking", "title": "The Spice Market Lesson", "paragraphs": ["Priya had lived in London for six years, yet she still felt nervous whenever her aunt asked her to cook the family curry. The recipes were never written down, and every attempt she made tasted vaguely wrong, as if a note were missing from a familiar song.", "On a trip to Mumbai, her aunt took her to a crowded spice market at dawn. Priya expected to be given a list, but instead the older woman simply walked from stall to stall, picking up seeds and powders, crushing them between her fingers and asking Priya to smell each one.", "By the end of the morning, Priya's head was spinning with fragrances: toasted cumin, sharp mustard seeds, sweet cardamom. Her aunt explained that spices were not supposed to be memorised, only recognised, the way one recognises a voice in a crowd.", "Back in London, Priya cooked the curry without a recipe, relying only on smell and memory. When her father tasted it, he fell silent for a moment, then said that it reminded him of his mother's kitchen. Priya smiled and understood that she had finally found the missing note."], "paragraphs_pt": ["Priya morava em Londres havia seis anos, mas ainda ficava nervosa sempre que a tia pedia que ela preparasse o curry da família. As receitas nunca eram escritas, e toda tentativa dela tinha um gosto vagamente errado, como se faltasse uma nota numa música conhecida.", "Numa viagem a Mumbai, a tia a levou a um mercado de especiarias lotado ao amanhecer. Priya esperava receber uma lista, mas a mulher mais velha simplesmente andou de banca em banca, pegando sementes e pós, esmagando-os entre os dedos e pedindo que Priya cheirasse cada um.", "No fim da manhã, a cabeça de Priya girava com fragrâncias: cominho tostado, sementes de mostarda fortes, cardamomo doce. A tia explicou que especiarias não deviam ser memorizadas, apenas reconhecidas, como se reconhece uma voz na multidão.", "De volta a Londres, Priya preparou o curry sem receita, confiando apenas no cheiro e na memória. Quando o pai provou, ficou em silêncio por um momento e disse que lembrava a cozinha da mãe dele. Priya sorriu e entendeu que finalmente encontrara a nota que faltava."], "hard_words": ["vaguely", "stall", "fragrances", "relying"], "vocab": [{"word": "fragrances", "meaning": "fragrâncias, aromas", "note": ""}, {"word": "curry", "meaning": "curry", "note": ""}, {"word": "vaguely", "meaning": "vagamente", "note": ""}, {"word": "spice market", "meaning": "mercado de especiarias", "note": ""}, {"word": "stall", "meaning": "banca, barraca", "note": ""}, {"word": "crushing", "meaning": "esmagando", "note": ""}, {"word": "spinning", "meaning": "girando", "note": ""}, {"word": "cumin", "meaning": "cominho", "note": ""}, {"word": "cardamom", "meaning": "cardamomo", "note": ""}, {"word": "relying", "meaning": "confiando", "note": ""}, {"word": "missing", "meaning": "que faltava", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "be", "was"], "irregular": ["had", "lived", "felt", "asked", "written", "made", "tasted", "took", "crowded", "expected", "given", "walked", "toasted", "explained", "supposed", "memorised", "recognised", "cooked", "fell", "said", "reminded", "smiled", "understood", "found"], "phrasal": ["written down", "fell silent"], "wh": ["when", "whenever"], "connectors": ["and", "but", "instead", "then", "when", "yet", "finally", "still", "if", "as", "whenever"], "comparative": []}, "word_meanings": [{"word": "fragrances", "meaning": "fragrâncias, aromas", "note": ""}, {"word": "curry", "meaning": "curry", "note": ""}, {"word": "vaguely", "meaning": "vagamente", "note": ""}, {"word": "spice market", "meaning": "mercado de especiarias", "note": ""}, {"word": "stall", "meaning": "banca, barraca", "note": ""}, {"word": "crushing", "meaning": "esmagando", "note": ""}, {"word": "spinning", "meaning": "girando", "note": ""}, {"word": "cumin", "meaning": "cominho", "note": ""}, {"word": "cardamom", "meaning": "cardamomo", "note": ""}, {"word": "relying", "meaning": "confiando", "note": ""}, {"word": "missing", "meaning": "que faltava", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect e present perfect", "explanation_pt": "'Priya had lived in London for six years' mostra duração anterior ao momento principal."}, {"point": "The way + oração", "explanation_pt": "'the way one recognises a voice' compara uma ideia com uma imagem familiar."}], "multiple_choice": [{"question": "How long had Priya lived in London?", "options": ["Two years", "Six years", "One year", "Ten years"], "correct_index": 1, "explanation": "Ela morava em Londres havia seis anos."}, {"question": "Why did her cooking taste wrong?", "options": ["She used old spices", "A note was missing, as in a song", "She had no oven", "She used too much salt"], "correct_index": 1, "explanation": "Era como uma nota que faltava em uma música."}, {"question": "What did her aunt ask her to do in the market?", "options": ["Count coins", "Buy a list", "Smell each spice", "Cook for strangers"], "correct_index": 2, "explanation": "Ela pediu que Priya cheirasse cada especiaria."}, {"question": "According to the aunt, how should spices be learned?", "options": ["Written in a notebook", "Bought online", "Recognised, not memorised", "Measured exactly"], "correct_index": 2, "explanation": "Elas devem ser reconhecidas, não memorizadas."}, {"question": "How did Priya's father react?", "options": ["He asked for a recipe", "He left the table", "He criticised the dish", "He remembered his mother's kitchen"], "correct_index": 3, "explanation": "O curry lembrou a cozinha da mãe dele."}], "open_questions": [{"question": "Can smell trigger strong memories? Share an example.", "key_points_pt": ["falar de lembranças ligadas a cheiros"]}, {"question": "Is a recipe more than a list of ingredients? Explain.", "key_points_pt": ["discutir tradição e intuição"]}]}}, {"level": "C1", "genre": "cooking", "title": "The Last Recipe Card", "paragraphs": ["Among the belongings of her late mother, Camila found a cracked wooden box filled with recipe cards, each one covered in a handwriting she knew better than her own. Most were predictable: lemon cake, bean stew, a pudding that had appeared at every birthday of her childhood. Yet at the very bottom lay a card she had never seen, titled simply \"For when you miss me.\"", "The instructions were deceptively plain: onions, garlic, tomatoes, a pinch of sugar, simmered for an hour. There was no mention of the dish's name, and nothing indicated what it was meant to accompany. Camila, who had not cooked seriously since the funeral, stood in the kitchen for a long time before she took out a knife.", "As the sauce thickened, a familiar scent filled the room and, with it, a flood of memories she had been carefully avoiding: Sunday afternoons, her mother humming off-key, the radio muttering in the background. She realised that the recipe was less about food than about permission, permission to remember without falling apart.", "She ate the sauce over plain rice, sitting on the kitchen floor, and cried more openly than she had in months. Afterwards she washed the pan, dried it carefully and added a line to the back of the card in her own handwriting: \"It worked.\""], "paragraphs_pt": ["Entre os pertences da mãe falecida, Camila encontrou uma caixa de madeira rachada cheia de fichas de receitas, todas cobertas por uma caligrafia que ela conhecia melhor do que a própria. A maioria era previsível: bolo de limão, ensopado de feijão, um pudim que aparecera em todos os aniversários da infância. Mas, bem no fundo, havia uma ficha que ela nunca vira, intitulada simplesmente \"Para quando você sentir minha falta.\"", "As instruções eram enganosamente simples: cebolas, alho, tomates, uma pitada de açúcar, cozidos em fogo baixo por uma hora. Não havia menção ao nome do prato, e nada indicava com o que devia ser servido. Camila, que não cozinhava a sério desde o funeral, ficou muito tempo na cozinha antes de pegar uma faca.", "Conforme o molho engrossava, um aroma familiar encheu o ambiente e, com ele, uma enxurrada de lembranças que ela vinha evitando com cuidado: tardes de domingo, a mãe cantarolando desafinada, o rádio murmurando ao fundo. Ela percebeu que a receita falava menos de comida do que de permissão, permissão para lembrar sem desmoronar.", "Comeu o molho com arroz branco, sentada no chão da cozinha, e chorou mais abertamente do que em meses. Depois lavou a panela, secou-a com cuidado e acrescentou uma linha no verso da ficha, com a própria letra: \"Funcionou.\""], "hard_words": ["deceptively", "simmered", "scent", "permission"], "vocab": [{"word": "belongings", "meaning": "pertences", "note": ""}, {"word": "cracked", "meaning": "rachada", "note": ""}, {"word": "handwriting", "meaning": "caligrafia", "note": ""}, {"word": "deceptively", "meaning": "enganosamente", "note": ""}, {"word": "simmered", "meaning": "cozidos em fogo baixo", "note": ""}, {"word": "scent", "meaning": "aroma", "note": ""}, {"word": "flood", "meaning": "enxurrada", "note": ""}, {"word": "humming", "meaning": "cantarolando", "note": ""}, {"word": "off-key", "meaning": "desafinada", "note": ""}, {"word": "permission", "meaning": "permissão", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was", "been"], "irregular": ["found", "cracked", "filled", "covered", "knew", "had", "appeared", "lay", "seen", "titled", "simmered", "indicated", "meant", "cooked", "stood", "took", "thickened", "realised", "ate", "cried", "washed", "dried", "added", "worked"], "phrasal": ["falling apart", "took out", "filled with"], "wh": ["who", "what", "when"], "connectors": ["and", "before", "when", "since", "yet", "as"], "comparative": []}, "word_meanings": [{"word": "belongings", "meaning": "pertences", "note": ""}, {"word": "cracked", "meaning": "rachada", "note": ""}, {"word": "handwriting", "meaning": "caligrafia", "note": ""}, {"word": "deceptively", "meaning": "enganosamente", "note": ""}, {"word": "simmered", "meaning": "cozidos em fogo baixo", "note": ""}, {"word": "scent", "meaning": "aroma", "note": ""}, {"word": "flood", "meaning": "enxurrada", "note": ""}, {"word": "humming", "meaning": "cantarolando", "note": ""}, {"word": "off-key", "meaning": "desafinada", "note": ""}, {"word": "permission", "meaning": "permissão", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'she had never seen' e 'she had been avoiding' indicam fatos anteriores ao momento principal."}, {"point": "Less ... than", "explanation_pt": "'less about food than about permission' compara dois aspectos e destaca o segundo."}], "multiple_choice": [{"question": "What did Camila find in the box?", "options": ["Old photographs", "Letters", "Recipe cards in her mother's handwriting", "Jewelry"], "correct_index": 2, "explanation": "Ela achou fichas de receitas da mãe."}, {"question": "What was special about the last card?", "options": ["It had no ingredients", "It was titled 'For when you miss me'", "It was torn in half", "It was in another language"], "correct_index": 1, "explanation": "O título era 'Para quando você sentir minha falta'."}, {"question": "Why did Camila hesitate to cook?", "options": ["She disliked sauces", "She was in a hurry", "She had no onions", "She had not cooked seriously since the funeral"], "correct_index": 3, "explanation": "Ela não cozinhava a sério desde o funeral."}, {"question": "What did she understand about the recipe?", "options": ["It was about saving money", "It was about losing weight", "It was about permission to remember", "It was about guests"], "correct_index": 2, "explanation": "A receita era sobre permissão para lembrar."}, {"question": "What did she write on the card?", "options": ["Never again", "It worked", "Too salty", "For Sunday"], "correct_index": 1, "explanation": "Ela escreveu 'Funcionou'."}], "open_questions": [{"question": "Can food help people deal with grief? Explain.", "key_points_pt": ["discutir luto, memória e rituais"]}, {"question": "What object of a loved one would be most precious to you?", "key_points_pt": ["descrever um objeto e explicar"]}]}}, {"level": "C1", "genre": "cooking", "title": "Fire, Salt and Patience", "paragraphs": ["Chef Oren had a rule that unnerved every apprentice who passed through his kitchen: no one touched the grill for the first month. Newcomers peeled potatoes, scrubbed pots and watched. Some resented the policy, interpreting it as hazing; others privately wondered whether the great man simply enjoyed his authority.", "Lucía, the newest recruit, chose to treat the month as an experiment. She learned to read the kitchen like a language: the rhythm of knives meant service was beginning, a sudden silence signalled that something had gone wrong, and the way Oren tasted a sauce, eyes closed for exactly three seconds, said more than any instruction could.", "When he finally allowed her near the grill, she was astonished to discover that she already understood it. She knew how long the embers needed to settle, how the smell changed when fat began to burn, how much salt a cut of meat could bear. Observation, it turned out, had been the real training.", "Months afterwards, Oren admitted over coffee that the rule had not been designed to test obedience. \"Everyone is eager to do,\" he said. \"Very few people learn to notice.\" Lucía thought about this for years, and when she opened her own restaurant, the first rule she wrote on the wall was nearly identical."], "paragraphs_pt": ["O chef Oren tinha uma regra que intimidava todo aprendiz que passava por sua cozinha: ninguém tocava na grelha no primeiro mês. Os novatos descascavam batatas, esfregavam panelas e observavam. Alguns ressentiam a política, interpretando-a como trote; outros se perguntavam em silêncio se o grande homem simplesmente gostava da própria autoridade.", "Lucía, a recruta mais nova, decidiu tratar o mês como um experimento. Aprendeu a ler a cozinha como uma língua: o ritmo das facas significava que o serviço estava começando, um silêncio súbito indicava que algo dera errado, e o jeito como Oren provava um molho, de olhos fechados por exatamente três segundos, dizia mais do que qualquer instrução.", "Quando ele finalmente a deixou chegar perto da grelha, ela se espantou ao descobrir que já a entendia. Sabia quanto tempo as brasas precisavam para assentar, como o cheiro mudava quando a gordura começava a queimar, quanto sal um corte de carne suportava. A observação, ao que parecia, havia sido o verdadeiro treinamento.", "Meses depois, Oren admitiu, tomando café, que a regra não fora criada para testar obediência. \"Todo mundo tem pressa de fazer\", disse. \"Pouquíssimas pessoas aprendem a perceber.\" Lucía pensou nisso por anos e, quando abriu o próprio restaurante, a primeira regra que escreveu na parede era quase idêntica."], "hard_words": ["unnerved", "embers", "astonished", "eager"], "vocab": [{"word": "unnerved", "meaning": "intimidou, deixou inquieto", "note": ""}, {"word": "apprentice", "meaning": "aprendiz", "note": ""}, {"word": "scrubbed", "meaning": "esfregaram", "note": ""}, {"word": "resented", "meaning": "ressentiam", "note": ""}, {"word": "hazing", "meaning": "trote, humilhação ritual", "note": ""}, {"word": "embers", "meaning": "brasas", "note": ""}, {"word": "astonished", "meaning": "espantada", "note": ""}, {"word": "obedience", "meaning": "obediência", "note": ""}, {"word": "eager", "meaning": "ansioso, empolgado", "note": ""}, {"word": "identical", "meaning": "idêntica", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "is"], "irregular": ["had", "unnerved", "passed", "touched", "peeled", "scrubbed", "watched", "resented", "wondered", "enjoyed", "chose", "learned", "meant", "signalled", "gone", "tasted", "closed", "said", "could", "allowed", "astonished", "understood", "knew", "needed", "changed", "began", "turned", "admitted", "designed", "thought", "opened", "wrote"], "phrasal": ["turned out", "passed through"], "wh": ["who", "when", "how"], "connectors": ["and", "when", "finally", "as"], "comparative": []}, "word_meanings": [{"word": "unnerved", "meaning": "intimidou, deixou inquieto", "note": ""}, {"word": "apprentice", "meaning": "aprendiz", "note": ""}, {"word": "scrubbed", "meaning": "esfregaram", "note": ""}, {"word": "resented", "meaning": "ressentiam", "note": ""}, {"word": "hazing", "meaning": "trote, humilhação ritual", "note": ""}, {"word": "embers", "meaning": "brasas", "note": ""}, {"word": "astonished", "meaning": "espantada", "note": ""}, {"word": "obedience", "meaning": "obediência", "note": ""}, {"word": "eager", "meaning": "ansioso, empolgado", "note": ""}, {"word": "identical", "meaning": "idêntica", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had been the real training' indica uma conclusão sobre algo que já tinha acontecido antes."}, {"point": "Contraste com 'Some... others...'", "explanation_pt": "'Some resented the policy; others wondered...' separa dois grupos com reações diferentes."}], "multiple_choice": [{"question": "What was Chef Oren's rule?", "options": ["No one spoke", "Everyone wore white", "Everyone cooked every day", "No one touched the grill for a month"], "correct_index": 3, "explanation": "Ninguém tocava na grelha no primeiro mês."}, {"question": "How did Lucía treat the first month?", "options": ["As a holiday", "As a mistake", "As an experiment", "As a punishment"], "correct_index": 2, "explanation": "Ela tratou o mês como um experimento."}, {"question": "What did silence in the kitchen signal?", "options": ["That the chef was angry", "That service was over", "That lunch was ready", "That something had gone wrong"], "correct_index": 3, "explanation": "O silêncio indicava que algo dera errado."}, {"question": "What was the real purpose of the rule?", "options": ["To save fuel", "To protect the grill", "To teach people to notice", "To test obedience"], "correct_index": 2, "explanation": "A regra servia para ensinar a perceber."}, {"question": "What did Lucía do years later?", "options": ["She quit cooking", "She sold the grill", "She wrote a book", "She opened a restaurant with a similar rule"], "correct_index": 3, "explanation": "Ela abriu um restaurante com regra parecida."}], "open_questions": [{"question": "Is learning by watching as valuable as learning by doing?", "key_points_pt": ["discutir observação e prática"]}, {"question": "Have you ever had a rule that seemed unfair but taught you something?", "key_points_pt": ["contar uma experiência"]}]}}, {"level": "C1", "genre": "cooking", "title": "Taste Memory", "paragraphs": ["The meal in question had cost almost nothing: rice, a fried egg, a few slices of tomato, served on a chipped plate in a roadside café outside Hanoi. Yet Ben, a restaurant critic who had eaten at some of the most celebrated tables in the world, found himself thinking about it for years afterwards, with a persistence that irritated him.", "He tried to explain the phenomenon in his column. Perhaps it was the exhaustion of travel, he suggested, or the novelty of being a stranger; perhaps hunger simply seasons everything. But none of these explanations quite satisfied him, because he had been hungry and tired in many other places without a comparable result.", "When an editor finally dared to ask the obvious question, he returned to Vietnam to retrace the journey. The café had closed; in its place stood a pharmacy. He ordered the same ingredients at another place, and the dish was entirely competent and entirely forgettable.", "Walking back to his hotel, Ben came to a conclusion that he did not publish. The flavour had never been in the food. It had been in a moment in which he was nobody's critic, unobserved and unburdened, and no recipe could reproduce that."], "paragraphs_pt": ["A refeição em questão custara quase nada: arroz, um ovo frito, algumas fatias de tomate, servidos num prato lascado em um café de beira de estrada perto de Hanói. Mesmo assim, Ben, um crítico gastronômico que comera em algumas das mesas mais celebradas do mundo, passou anos pensando nela, com uma persistência que o irritava.", "Ele tentou explicar o fenômeno em sua coluna. Talvez fosse o cansaço da viagem, sugeriu, ou a novidade de ser estrangeiro; talvez a fome simplesmente tempere tudo. Mas nenhuma dessas explicações o satisfazia de fato, porque ele já tivera fome e cansaço em muitos outros lugares sem resultado comparável.", "Quando um editor finalmente ousou fazer a pergunta óbvia, ele voltou ao Vietnã para refazer o percurso. O café havia fechado; no lugar havia uma farmácia. Pediu os mesmos ingredientes em outro lugar, e o prato era perfeitamente competente e perfeitamente esquecível.", "Voltando ao hotel, Ben chegou a uma conclusão que não publicou. O sabor nunca estivera na comida. Estivera num momento em que ele não era crítico de ninguém, sem ser observado e sem peso, e nenhuma receita seria capaz de reproduzir isso."], "hard_words": ["persistence", "novelty", "retrace", "unburdened"], "vocab": [{"word": "chipped", "meaning": "lascado", "note": ""}, {"word": "roadside", "meaning": "de beira de estrada", "note": ""}, {"word": "critic", "meaning": "crítico", "note": ""}, {"word": "persistence", "meaning": "persistência", "note": ""}, {"word": "novelty", "meaning": "novidade", "note": ""}, {"word": "seasons", "meaning": "tempera", "note": ""}, {"word": "retrace", "meaning": "refazer (percurso)", "note": ""}, {"word": "competent", "meaning": "competente", "note": ""}, {"word": "forgettable", "meaning": "esquecível", "note": ""}, {"word": "unburdened", "meaning": "sem peso, aliviado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being", "been"], "irregular": ["had", "fried", "served", "chipped", "eaten", "celebrated", "found", "irritated", "tried", "suggested", "satisfied", "tired", "dared", "returned", "closed", "stood", "ordered", "came", "did", "unburdened", "could"], "phrasal": ["came to a conclusion"], "wh": ["who", "when", "which"], "connectors": ["and", "but", "because", "when", "yet", "or", "finally"], "comparative": []}, "word_meanings": [{"word": "chipped", "meaning": "lascado", "note": ""}, {"word": "roadside", "meaning": "de beira de estrada", "note": ""}, {"word": "critic", "meaning": "crítico", "note": ""}, {"word": "persistence", "meaning": "persistência", "note": ""}, {"word": "novelty", "meaning": "novidade", "note": ""}, {"word": "seasons", "meaning": "tempera", "note": ""}, {"word": "retrace", "meaning": "refazer (percurso)", "note": ""}, {"word": "competent", "meaning": "competente", "note": ""}, {"word": "forgettable", "meaning": "esquecível", "note": ""}, {"word": "unburdened", "meaning": "sem peso, aliviado", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had eaten at some of the most celebrated tables' vem antes do momento da história."}, {"point": "Entirely competent and entirely forgettable", "explanation_pt": "A repetição de 'entirely' cria um contraste irônico entre duas ideias."}], "multiple_choice": [{"question": "What did the meal consist of?", "options": ["Rice, a fried egg and tomato", "Soup and bread", "Fish and noodles", "Pizza"], "correct_index": 0, "explanation": "Era arroz, ovo frito e tomate."}, {"question": "Why did the memory irritate Ben?", "options": ["He remembered it wrongly", "It was a bad meal", "He lost his notes", "It lasted for years"], "correct_index": 3, "explanation": "A persistência da lembrança o irritava."}, {"question": "What did Ben find when he returned?", "options": ["The owner remembered him", "The café was full", "The café had become a pharmacy", "The café was famous"], "correct_index": 2, "explanation": "O café fora trocado por uma farmácia."}, {"question": "How was the dish in another place?", "options": ["Better than before", "Competent but forgettable", "Terrible", "Too spicy"], "correct_index": 1, "explanation": "O prato era competente e esquecível."}, {"question": "What did Ben conclude privately?", "options": ["He was too old", "The flavour was in the moment, not the food", "Critics are always wrong", "The ingredients were special"], "correct_index": 1, "explanation": "O sabor estava no momento, não na comida."}], "open_questions": [{"question": "Why can the same food taste different in different situations?", "key_points_pt": ["discutir contexto, humor e memória"]}, {"question": "Describe a simple meal that you remember very well.", "key_points_pt": ["contar a lembrança", "usar passado"]}]}}, {"level": "C2", "genre": "cooking", "title": "The Ethics of a Perfect Plate", "paragraphs": ["At the age of thirty-four, Marguerite had achieved what most chefs spend their entire careers chasing: a second Michelin star, a waiting list that stretched into the next season and a reputation for sauces that critics described, without apparent embarrassment, as spiritual. Her kitchen was immaculate, her staff devoted and her dishes so precisely composed that diners sometimes hesitated to disturb them.", "It was a visit to a farm in the Auvergne that first unsettled her. She had gone to inspect a supplier, expecting to praise the quality of its cheese, but the farmer's wife, drying her hands on an apron, quietly asked whether Marguerite knew how many cheeses were discarded each week because they failed to resemble the photograph on her menu. The question was not hostile; it was simply a fact, delivered without decoration.", "Back in Paris, Marguerite began to count. The trimmings, the misshapen vegetables, the portions returned because a garnish had wilted: it all amounted to a quantity of food that made her feel faintly ill. She had spent her career believing that perfection was a form of respect, and now she suspected that it might also be a form of waste.", "The reform she proposed was modest in appearance but radical in implication. Imperfect ingredients would be used, openly and with pride, and the menu would acknowledge their origins. Several regulars cancelled their reservations, offended by what they considered a downgrade. Others, to her surprise, came back more often, and some brought their children to see how a crooked carrot could become something beautiful.", "Whether the experiment endangered her stars was a question Marguerite no longer found interesting. She had learned that a kitchen could be judged by what it served, but also by what it refused to throw away."], "paragraphs_pt": ["Aos trinta e quatro anos, Marguerite havia conquistado o que a maioria dos chefs passa a carreira inteira perseguindo: uma segunda estrela Michelin, uma lista de espera que se estendia até a próxima temporada e uma reputação por molhos que os críticos descreviam, sem constrangimento aparente, como espirituais. Sua cozinha era imaculada, a equipe dedicada e os pratos tão precisamente compostos que os clientes às vezes hesitavam em perturbá-los.", "Foi uma visita a uma fazenda em Auvérnia que a inquietou pela primeira vez. Ela fora inspecionar um fornecedor, esperando elogiar a qualidade do queijo, mas a esposa do fazendeiro, secando as mãos num avental, perguntou baixinho se Marguerite sabia quantos queijos eram descartados por semana porque não se pareciam com a foto do cardápio dela. A pergunta não era hostil; era apenas um fato, dito sem enfeite.", "De volta a Paris, Marguerite começou a contar. As aparas, os legumes disformes, as porções devolvidas porque uma guarnição murchara: tudo somava uma quantidade de comida que lhe dava um leve enjoo. Passara a carreira acreditando que perfeição era uma forma de respeito, e agora suspeitava que também pudesse ser uma forma de desperdício.", "A reforma que propôs era modesta na aparência, mas radical nas implicações. Ingredientes imperfeitos seriam usados, abertamente e com orgulho, e o cardápio reconheceria suas origens. Vários clientes habituais cancelaram reservas, ofendidos com o que consideravam um rebaixamento. Outros, para sua surpresa, voltaram com mais frequência, e alguns levaram os filhos para ver como uma cenoura torta podia virar algo bonito.", "Se o experimento colocava suas estrelas em risco era uma pergunta que Marguerite já não achava interessante. Aprendera que uma cozinha podia ser julgada pelo que servia, mas também pelo que se recusava a jogar fora."], "hard_words": ["immaculate", "discarded", "misshapen", "downgrade"], "vocab": [{"word": "immaculate", "meaning": "imaculada", "note": ""}, {"word": "devoted", "meaning": "dedicada", "note": ""}, {"word": "unsettled", "meaning": "inquietou", "note": ""}, {"word": "supplier", "meaning": "fornecedor", "note": ""}, {"word": "discarded", "meaning": "descartados", "note": ""}, {"word": "hostile", "meaning": "hostil", "note": ""}, {"word": "trimmings", "meaning": "aparas", "note": ""}, {"word": "misshapen", "meaning": "disforme", "note": ""}, {"word": "wilted", "meaning": "murchou", "note": ""}, {"word": "downgrade", "meaning": "rebaixamento", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "be"], "irregular": ["had", "achieved", "stretched", "described", "devoted", "composed", "hesitated", "unsettled", "gone", "asked", "knew", "discarded", "failed", "delivered", "began", "returned", "wilted", "amounted", "made", "spent", "suspected", "might", "proposed", "would", "used", "cancelled", "offended", "considered", "came", "brought", "crooked", "could", "endangered", "found", "learned", "judged", "served", "refused"], "phrasal": ["amounted to", "came back"], "wh": ["what", "how"], "connectors": ["and", "but", "because", "so", "also", "as"], "comparative": []}, "word_meanings": [{"word": "immaculate", "meaning": "imaculada", "note": ""}, {"word": "devoted", "meaning": "dedicada", "note": ""}, {"word": "unsettled", "meaning": "inquietou", "note": ""}, {"word": "supplier", "meaning": "fornecedor", "note": ""}, {"word": "discarded", "meaning": "descartados", "note": ""}, {"word": "hostile", "meaning": "hostil", "note": ""}, {"word": "trimmings", "meaning": "aparas", "note": ""}, {"word": "misshapen", "meaning": "disforme", "note": ""}, {"word": "wilted", "meaning": "murchou", "note": ""}, {"word": "downgrade", "meaning": "rebaixamento", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had achieved what most chefs spend their entire careers chasing' coloca a conquista antes do ponto da narração."}, {"point": "Whether + oração", "explanation_pt": "'Whether the experiment endangered her stars' funciona como sujeito e expressa dúvida: 'se o experimento colocava...'."}], "multiple_choice": [{"question": "What had Marguerite achieved at thirty-four?", "options": ["A book", "A second Michelin star", "A new restaurant chain", "A cooking show"], "correct_index": 1, "explanation": "Ela tinha uma segunda estrela Michelin."}, {"question": "What did the farmer's wife ask?", "options": ["If she wanted more", "Why the price was high", "How many cheeses were discarded each week", "Whether the cheese was good"], "correct_index": 2, "explanation": "Ela perguntou quantos queijos eram descartados por não parecerem a foto."}, {"question": "What did Marguerite begin to do in Paris?", "options": ["Fire her staff", "Close the kitchen", "Change suppliers", "Count the wasted food"], "correct_index": 3, "explanation": "Ela começou a contar o desperdício."}, {"question": "How did some regulars react to the reform?", "options": ["They paid more", "They cancelled their reservations", "They wrote reviews", "They became chefs"], "correct_index": 1, "explanation": "Alguns cancelaram, ofendidos."}, {"question": "What did Marguerite learn about a kitchen?", "options": ["It should serve only meat", "It should be silent", "It must be cheap", "It can be judged by what it refuses to throw away"], "correct_index": 3, "explanation": "Ela aprendeu a valorizar o que se recusa a jogar fora."}], "open_questions": [{"question": "Is perfection always a virtue in food or in other areas of life?", "key_points_pt": ["discutir padrões, desperdício e estética"]}, {"question": "What can restaurants do to reduce food waste?", "key_points_pt": ["listar ações práticas", "justificar"]}]}}, {"level": "C2", "genre": "cooking", "title": "The Cookbook Nobody Would Publish", "paragraphs": ["For eleven years, Teodor carried a manuscript from publisher to publisher: three hundred pages of recipes collected from his Bulgarian grandmother, annotated with anecdotes that wandered through war, migration and marriage. Rejection letters arrived with the regularity of seasons, politely observing that the project was charming but too niche, too personal or, in one memorable case, too sad for a cookbook.", "He might have abandoned it altogether had it not been for a casual remark from his daughter, who at fourteen possessed the ruthless clarity of her age. \"You write as if you are apologising,\" she said one evening. \"Grandma never apologised for anything.\" Teodor stared at her, then at the manuscript, and saw with discomfort that she was right. His prose was careful, hedged, anxious to please.", "He spent the following winter rewriting everything. The sentences grew shorter, the humour sharper, the grief less polite. Where he had once explained that his grandmother \"occasionally\" burned the bread, he now wrote that she burned it every Friday and blamed the oven with undiminished conviction.", "The revised book was accepted by the first small press he approached. It did not become a bestseller, but it found the readers who needed it: emigrants who recognised the smell of their own childhoods, and children who wanted to know where their parents had come from. At the launch, Teodor read aloud a passage about his grandmother's soup. Halfway through, his voice broke, and nobody in the room seemed to mind."], "paragraphs_pt": ["Por onze anos, Teodor carregou um manuscrito de editora em editora: trezentas páginas de receitas colhidas com sua avó búlgara, anotadas com anedotas que vagavam por guerra, migração e casamento. As cartas de recusa chegavam com a regularidade das estações, observando educadamente que o projeto era encantador, mas nichado demais, pessoal demais ou, num caso memorável, triste demais para um livro de culinária.", "Ele poderia tê-lo abandonado por completo se não fosse um comentário casual da filha, que aos catorze anos possuía a clareza implacável da idade. \"Você escreve como se estivesse pedindo desculpas\", disse uma noite. \"A vovó nunca pediu desculpas por nada.\" Teodor a encarou, depois olhou para o manuscrito, e viu com desconforto que ela tinha razão. Sua prosa era cuidadosa, cheia de ressalvas, ansiosa para agradar.", "Passou o inverno seguinte reescrevendo tudo. As frases ficaram mais curtas, o humor mais afiado, o luto menos educado. Onde antes explicara que a avó \"ocasionalmente\" queimava o pão, agora escrevia que ela o queimava toda sexta-feira e culpava o forno com convicção inabalável.", "O livro revisado foi aceito pela primeira editora pequena que ele procurou. Não virou best-seller, mas encontrou os leitores de que precisava: emigrantes que reconheciam o cheiro da própria infância e filhos que queriam saber de onde seus pais vinham. No lançamento, Teodor leu em voz alta um trecho sobre a sopa da avó. No meio, a voz falhou, e ninguém na sala pareceu se importar."], "hard_words": ["annotated", "ruthless", "hedged", "undiminished"], "vocab": [{"word": "manuscript", "meaning": "manuscrito", "note": ""}, {"word": "annotated", "meaning": "anotado", "note": ""}, {"word": "niche", "meaning": "nicho, de nicho", "note": ""}, {"word": "ruthless", "meaning": "implacável", "note": ""}, {"word": "hedged", "meaning": "cheio de ressalvas", "note": ""}, {"word": "prose", "meaning": "prosa", "note": ""}, {"word": "undiminished", "meaning": "inabalável, sem diminuir", "note": ""}, {"word": "conviction", "meaning": "convicção", "note": ""}, {"word": "emigrants", "meaning": "emigrantes", "note": ""}, {"word": "launch", "meaning": "lançamento", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "are"], "irregular": ["carried", "collected", "annotated", "wandered", "arrived", "might", "abandoned", "had", "possessed", "said", "apologised", "stared", "saw", "hedged", "spent", "grew", "explained", "burned", "wrote", "blamed", "revised", "accepted", "approached", "did", "found", "needed", "recognised", "wanted", "broke", "seemed"], "phrasal": ["read aloud", "come from"], "wh": ["who", "where"], "connectors": ["and", "but", "then", "or", "once", "if", "as"], "comparative": []}, "word_meanings": [{"word": "manuscript", "meaning": "manuscrito", "note": ""}, {"word": "annotated", "meaning": "anotado", "note": ""}, {"word": "niche", "meaning": "nicho, de nicho", "note": ""}, {"word": "ruthless", "meaning": "implacável", "note": ""}, {"word": "hedged", "meaning": "cheio de ressalvas", "note": ""}, {"word": "prose", "meaning": "prosa", "note": ""}, {"word": "undiminished", "meaning": "inabalável, sem diminuir", "note": ""}, {"word": "conviction", "meaning": "convicção", "note": ""}, {"word": "emigrants", "meaning": "emigrantes", "note": ""}, {"word": "launch", "meaning": "lançamento", "note": ""}], "exercises": {"grammar": [{"point": "Third conditional invertido", "explanation_pt": "'He might have abandoned it altogether had it not been for...' equivale a 'if it had not been for' e mostra uma situação hipotética no passado."}, {"point": "Past perfect", "explanation_pt": "'had once explained' indica algo anterior ao momento em que ele reescreve."}], "multiple_choice": [{"question": "How long did Teodor carry the manuscript around?", "options": ["Eleven years", "Two years", "Fourteen years", "One winter"], "correct_index": 0, "explanation": "Ele tentou por onze anos."}, {"question": "What was one reason for rejection?", "options": ["It was too expensive", "It was too sad for a cookbook", "It was too short", "It was in Bulgarian"], "correct_index": 1, "explanation": "Um editor disse que era triste demais."}, {"question": "What did his daughter notice?", "options": ["He wrote too fast", "He forgot the ingredients", "He copied recipes", "He wrote as if he was apologising"], "correct_index": 3, "explanation": "Ela disse que ele escrevia como quem pede desculpas."}, {"question": "What changed in the rewriting?", "options": ["The book became longer", "Sentences became shorter and sharper", "The recipes disappeared", "The title changed"], "correct_index": 1, "explanation": "As frases ficaram mais curtas e o humor mais afiado."}, {"question": "Who found the revised book valuable?", "options": ["Emigrants and children of emigrants", "Chefs", "Politicians", "Critics"], "correct_index": 0, "explanation": "Emigrantes reconheciam o cheiro da infância."}], "open_questions": [{"question": "Why can honest, personal writing be more powerful than polished writing?", "key_points_pt": ["discutir autenticidade e voz própria"]}, {"question": "Who in your family has stories worth writing down?", "key_points_pt": ["descrever uma pessoa e uma história"]}]}}, {"level": "C2", "genre": "cooking", "title": "A Table for the Unforgiven", "paragraphs": ["The restaurant opened on a rainy Tuesday in a converted laundry, with no sign above the door and a menu consisting of exactly one dish. Anyone could enter, but there was a single condition, explained by a handwritten note taped to the window: tell the person across from you something you have never forgiven.", "Its founder, Noor, was a former diplomat who had spent years mediating between parties who hated one another and who had become convinced that the great obstacles to peace were rarely strategic. They were meals interrupted, insults repeated at the wrong time, the absence of any shared ritual that would permit enemies to see each other's faces.", "Initially the venture attracted ridicule. Journalists called it a gimmick, a therapy session disguised as dinner. Yet something unexpected happened in that narrow room. Estranged brothers, ex-business partners and a mother and son who had not spoken for a decade sat down at the same table and, to the astonishment of the staff, ate in silence before speaking at all.", "Noor never claimed that the restaurant solved anything. She insisted that what it offered was an interval, a few hours in which resentment could be set beside a plate of food and examined without being fed. Some guests left angrier than they had arrived. Others left lighter, and a few, rare and unforgettable, left holding hands.", "When asked about the ethics of orchestrating such confrontations, she would smile and say that every dinner was, in some sense, an act of faith. You feed another person on the assumption that they will not harm you, and for the length of the meal, that assumption is usually justified."], "paragraphs_pt": ["O restaurante abriu numa terça-feira chuvosa, numa lavanderia reformada, sem placa sobre a porta e com um cardápio de exatamente um prato. Qualquer pessoa podia entrar, mas havia uma única condição, explicada por um bilhete manuscrito colado na vitrine: conte à pessoa à sua frente algo que você nunca perdoou.", "Sua fundadora, Noor, era uma ex-diplomata que passara anos mediando entre partes que se odiavam e se convencera de que os grandes obstáculos à paz raramente eram estratégicos. Eram refeições interrompidas, insultos repetidos na hora errada, a ausência de qualquer ritual compartilhado que permitisse a inimigos ver o rosto um do outro.", "De início, o empreendimento atraiu ridículo. Jornalistas o chamaram de golpe publicitário, uma sessão de terapia disfarçada de jantar. Mas algo inesperado aconteceu naquela sala estreita. Irmãos afastados, ex-sócios e uma mãe e um filho que não se falavam havia uma década sentaram à mesma mesa e, para espanto da equipe, comeram em silêncio antes de falar qualquer coisa.", "Noor nunca afirmou que o restaurante resolvia algo. Insistia que o que ele oferecia era um intervalo, algumas horas em que o ressentimento podia ser posto ao lado de um prato de comida e examinado sem ser alimentado. Alguns clientes saíam mais irritados do que chegaram. Outros saíam mais leves e uns poucos, raros e inesquecíveis, saíam de mãos dadas.", "Quando perguntavam sobre a ética de orquestrar tais confrontos, ela sorria e dizia que todo jantar era, em certo sentido, um ato de fé. Alimentamos outra pessoa supondo que ela não nos fará mal e, pela duração da refeição, essa suposição costuma ser justificada."], "hard_words": ["mediating", "gimmick", "estranged", "resentment"], "vocab": [{"word": "converted", "meaning": "reformada, convertida", "note": ""}, {"word": "mediating", "meaning": "mediando", "note": ""}, {"word": "obstacles", "meaning": "obstáculos", "note": ""}, {"word": "ridicule", "meaning": "ridículo", "note": ""}, {"word": "gimmick", "meaning": "golpe publicitário", "note": ""}, {"word": "estranged", "meaning": "afastados, rompidos", "note": ""}, {"word": "astonishment", "meaning": "espanto", "note": ""}, {"word": "resentment", "meaning": "ressentimento", "note": ""}, {"word": "confrontations", "meaning": "confrontos", "note": ""}, {"word": "faith", "meaning": "fé", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "be", "being", "is"], "irregular": ["opened", "converted", "could", "explained", "taped", "forgiven", "had", "spent", "hated", "convinced", "interrupted", "repeated", "shared", "would", "attracted", "called", "disguised", "happened", "estranged", "spoken", "sat", "ate", "claimed", "solved", "insisted", "offered", "examined", "fed", "left", "arrived", "asked", "feed", "justified"], "phrasal": ["sat down", "left holding"], "wh": ["who", "what", "when", "which"], "connectors": ["and", "but", "before", "when", "yet", "as"], "comparative": []}, "word_meanings": [{"word": "converted", "meaning": "reformada, convertida", "note": ""}, {"word": "mediating", "meaning": "mediando", "note": ""}, {"word": "obstacles", "meaning": "obstáculos", "note": ""}, {"word": "ridicule", "meaning": "ridículo", "note": ""}, {"word": "gimmick", "meaning": "golpe publicitário", "note": ""}, {"word": "estranged", "meaning": "afastados, rompidos", "note": ""}, {"word": "astonishment", "meaning": "espanto", "note": ""}, {"word": "resentment", "meaning": "ressentimento", "note": ""}, {"word": "confrontations", "meaning": "confrontos", "note": ""}, {"word": "faith", "meaning": "fé", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'a former diplomat who had spent years mediating' mostra experiência anterior ao tempo da história."}, {"point": "Relative clauses", "explanation_pt": "'who had not spoken for a decade' acrescenta informação sobre a mãe e o filho."}], "multiple_choice": [{"question": "What was the only condition to enter?", "options": ["Book online", "Bring a friend", "Pay in advance", "Tell the person across something you never forgave"], "correct_index": 3, "explanation": "Era preciso contar algo que nunca perdoou."}, {"question": "What was Noor's former job?", "options": ["Journalist", "Diplomat", "Judge", "Chef"], "correct_index": 1, "explanation": "Ela era ex-diplomata."}, {"question": "How did journalists describe the idea at first?", "options": ["As a school", "As a crime", "As a gimmick", "As a miracle"], "correct_index": 2, "explanation": "Chamaram de golpe publicitário."}, {"question": "What did guests often do before speaking?", "options": ["Take photos", "Eat in silence", "Pray", "Sing"], "correct_index": 1, "explanation": "Eles comiam em silêncio."}, {"question": "According to Noor, what is every dinner?", "options": ["An act of faith", "A business deal", "A secret", "A competition"], "correct_index": 0, "explanation": "Para ela, todo jantar é um ato de fé."}], "open_questions": [{"question": "Can sharing a meal help people solve conflicts? Why?", "key_points_pt": ["discutir ritual, confiança e diálogo"]}, {"question": "Would you go to a restaurant like this? Explain.", "key_points_pt": ["dar opinião com argumentos", "usar condicional"]}]}}, {"level": "A1", "genre": "corporate", "title": "My Office", "paragraphs": ["This is my office. It is small, but it is nice. I have a desk, a chair and a computer.", "My boss is Mrs. Lima. She is kind. We work from nine to five. At noon we eat lunch together.", "I like my job. I answer the phone and write emails. My team is friendly. I am happy at work."], "paragraphs_pt": ["Este é o meu escritório. É pequeno, mas é agradável. Tenho uma mesa, uma cadeira e um computador.", "Minha chefe é a Sra. Lima. Ela é gentil. Trabalhamos das nove às cinco. Ao meio-dia almoçamos juntos.", "Eu gosto do meu trabalho. Atendo o telefone e escrevo e-mails. Minha equipe é simpática. Estou feliz no trabalho."], "hard_words": ["desk", "boss", "noon", "team"], "vocab": [{"word": "office", "meaning": "escritório", "note": ""}, {"word": "desk", "meaning": "mesa de trabalho", "note": ""}, {"word": "boss", "meaning": "chefe", "note": ""}, {"word": "kind", "meaning": "gentil", "note": ""}, {"word": "noon", "meaning": "meio-dia", "note": ""}, {"word": "answer", "meaning": "atender, responder", "note": ""}, {"word": "emails", "meaning": "e-mails", "note": ""}, {"word": "team", "meaning": "equipe", "note": ""}, {"word": "friendly", "meaning": "simpático", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "am"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "office", "meaning": "escritório", "note": ""}, {"word": "desk", "meaning": "mesa de trabalho", "note": ""}, {"word": "boss", "meaning": "chefe", "note": ""}, {"word": "kind", "meaning": "gentil", "note": ""}, {"word": "noon", "meaning": "meio-dia", "note": ""}, {"word": "answer", "meaning": "atender, responder", "note": ""}, {"word": "emails", "meaning": "e-mails", "note": ""}, {"word": "team", "meaning": "equipe", "note": ""}, {"word": "friendly", "meaning": "simpático", "note": ""}], "exercises": {"grammar": [{"point": "To be e have", "explanation_pt": "Usamos 'am/is/are' para descrever e 'have' para posse: 'It is small', 'I have a desk'."}], "multiple_choice": [{"question": "Is the office big?", "options": ["It has no desk", "No, it is small", "Yes, it is very big", "It is in a house"], "correct_index": 1, "explanation": "O escritório é pequeno, mas agradável."}, {"question": "Who is Mrs. Lima?", "options": ["A friend", "A teacher", "A customer", "The boss"], "correct_index": 3, "explanation": "Ela é a chefe."}, {"question": "What time do they work?", "options": ["All night", "From nine to five", "From noon to night", "From six to ten"], "correct_index": 1, "explanation": "Trabalham das nove às cinco."}, {"question": "What does the person do at work?", "options": ["Drives a bus", "Answers the phone and writes emails", "Paints walls", "Cooks lunch"], "correct_index": 1, "explanation": "Atende o telefone e escreve e-mails."}, {"question": "How does the person feel?", "options": ["Sick", "Sad", "Angry", "Happy"], "correct_index": 3, "explanation": "A pessoa está feliz no trabalho."}], "open_questions": [{"question": "Where do you work or study?", "key_points_pt": ["dizer o lugar", "usar 'I work' ou 'I study'"]}, {"question": "Do you like your job or school? Why?", "key_points_pt": ["responder com 'I like' e um motivo"]}]}}, {"level": "A1", "genre": "corporate", "title": "The New Job", "paragraphs": ["Today is Ana's first day at a new job. She is nervous. She puts on a blue shirt and takes the bus to work.", "At the office, a woman says, \"Hello! I am Rita.\" Rita shows Ana her desk. There is a computer and a small plant on it.", "At lunch, Ana eats with the team. Everybody is nice. In the afternoon, her boss says, \"Welcome, Ana!\" Now she is not nervous. She is happy."], "paragraphs_pt": ["Hoje é o primeiro dia de Ana num emprego novo. Ela está nervosa. Veste uma camisa azul e pega o ônibus para o trabalho.", "No escritório, uma mulher diz: \"Olá! Eu sou a Rita.\" Rita mostra a mesa a Ana. Há um computador e uma plantinha sobre ela.", "No almoço, Ana come com a equipe. Todos são legais. À tarde, a chefe diz: \"Bem-vinda, Ana!\" Agora ela não está nervosa. Está feliz."], "hard_words": ["nervous", "shirt", "plant", "welcome"], "vocab": [{"word": "first day", "meaning": "primeiro dia", "note": ""}, {"word": "nervous", "meaning": "nervosa", "note": ""}, {"word": "shirt", "meaning": "camisa", "note": ""}, {"word": "bus", "meaning": "ônibus", "note": ""}, {"word": "shows", "meaning": "mostra", "note": ""}, {"word": "plant", "meaning": "planta", "note": ""}, {"word": "lunch", "meaning": "almoço", "note": ""}, {"word": "nice", "meaning": "legal, simpático", "note": ""}, {"word": "welcome", "meaning": "bem-vinda", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "am"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "first day", "meaning": "primeiro dia", "note": ""}, {"word": "nervous", "meaning": "nervosa", "note": ""}, {"word": "shirt", "meaning": "camisa", "note": ""}, {"word": "bus", "meaning": "ônibus", "note": ""}, {"word": "shows", "meaning": "mostra", "note": ""}, {"word": "plant", "meaning": "planta", "note": ""}, {"word": "lunch", "meaning": "almoço", "note": ""}, {"word": "nice", "meaning": "legal, simpático", "note": ""}, {"word": "welcome", "meaning": "bem-vinda", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "Para rotinas e fatos usamos o presente: 'She takes the bus', 'Rita shows Ana her desk'. Com he/she/it o verbo ganha -s."}], "multiple_choice": [{"question": "Whose first day is it?", "options": ["Sara's", "The boss's", "Rita's", "Ana's"], "correct_index": 3, "explanation": "É o primeiro dia de Ana."}, {"question": "How does Ana go to work?", "options": ["By car", "On foot", "By bus", "By bike"], "correct_index": 2, "explanation": "Ela pega o ônibus."}, {"question": "What is on Ana's desk?", "options": ["Nothing", "A computer and a plant", "A book and a lamp", "A phone and a cup"], "correct_index": 1, "explanation": "Há um computador e uma plantinha."}, {"question": "Who does Ana eat lunch with?", "options": ["Her mother", "Her dog", "A customer", "The team"], "correct_index": 3, "explanation": "Ela almoça com a equipe."}, {"question": "How does Ana feel at the end?", "options": ["Nervous", "Tired", "Angry", "Happy"], "correct_index": 3, "explanation": "Ao fim do dia ela está feliz."}], "open_questions": [{"question": "Do you remember your first day at a new place?", "key_points_pt": ["descrever como se sentiu", "usar 'I was' ou 'I felt'"]}, {"question": "How do people help a new person?", "key_points_pt": ["citar ações como mostrar, apresentar, convidar"]}]}}, {"level": "A1", "genre": "corporate", "title": "A Meeting at Ten", "paragraphs": ["There is a meeting at ten o'clock. Carlos goes to the meeting room with a notebook and a pen.", "Six people are in the room. The manager says, \"Good morning, everyone.\" She talks about a new project. Carlos writes some notes.", "After one hour, the meeting is over. Carlos says, \"Thank you!\" He goes back to his desk and writes an email to the team."], "paragraphs_pt": ["Há uma reunião às dez horas. Carlos vai à sala de reunião com um caderno e uma caneta.", "Seis pessoas estão na sala. A gerente diz: \"Bom dia, pessoal.\" Ela fala sobre um novo projeto. Carlos escreve algumas anotações.", "Depois de uma hora, a reunião termina. Carlos diz: \"Obrigado!\" Ele volta à sua mesa e escreve um e-mail para a equipe."], "hard_words": ["meeting", "manager", "project", "notes"], "vocab": [{"word": "meeting", "meaning": "reunião", "note": ""}, {"word": "meeting room", "meaning": "sala de reunião", "note": ""}, {"word": "notebook", "meaning": "caderno", "note": ""}, {"word": "manager", "meaning": "gerente", "note": ""}, {"word": "project", "meaning": "projeto", "note": ""}, {"word": "notes", "meaning": "anotações", "note": ""}, {"word": "over", "meaning": "terminada", "note": ""}, {"word": "hour", "meaning": "hora", "note": ""}, {"word": "thank you", "meaning": "obrigado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "after"], "comparative": []}, "word_meanings": [{"word": "meeting", "meaning": "reunião", "note": ""}, {"word": "meeting room", "meaning": "sala de reunião", "note": ""}, {"word": "notebook", "meaning": "caderno", "note": ""}, {"word": "manager", "meaning": "gerente", "note": ""}, {"word": "project", "meaning": "projeto", "note": ""}, {"word": "notes", "meaning": "anotações", "note": ""}, {"word": "over", "meaning": "terminada", "note": ""}, {"word": "hour", "meaning": "hora", "note": ""}, {"word": "thank you", "meaning": "obrigado", "note": ""}], "exercises": {"grammar": [{"point": "There is / There are", "explanation_pt": "'There is a meeting' (singular) e 'There are six people' (plural) indicam existência."}], "multiple_choice": [{"question": "What time is the meeting?", "options": ["At six o'clock", "At two o'clock", "At ten o'clock", "At midnight"], "correct_index": 2, "explanation": "A reunião é às dez."}, {"question": "What does Carlos take?", "options": ["A laptop and a phone", "A notebook and a pen", "A book", "A coffee"], "correct_index": 1, "explanation": "Ele leva caderno e caneta."}, {"question": "How many people are in the room?", "options": ["Twenty", "Two", "Ten", "Six"], "correct_index": 3, "explanation": "Há seis pessoas."}, {"question": "What does the manager talk about?", "options": ["Lunch", "A party", "A holiday", "A new project"], "correct_index": 3, "explanation": "Ela fala de um novo projeto."}, {"question": "What does Carlos do after the meeting?", "options": ["Sleeps", "Writes an email", "Goes home", "Plays a game"], "correct_index": 1, "explanation": "Ele escreve um e-mail para a equipe."}], "open_questions": [{"question": "Do you like meetings? Why or why not?", "key_points_pt": ["dar opinião simples"]}, {"question": "What do you write in a notebook?", "key_points_pt": ["citar usos do caderno"]}]}}, {"level": "A2", "genre": "corporate", "title": "A Busy Monday", "paragraphs": ["Monday is always the busiest day for Rafael. When he arrives at the office at eight thirty, there are already thirty new emails in his inbox. He makes a coffee and starts to answer the most important ones.", "At ten, he has a meeting with his team to plan the week. They talk about deadlines and decide who is going to do each task. Rafael has to finish a report by Wednesday, so he asks his colleague Julia for some help.", "At lunch he usually eats a sandwich at his desk because he has no time to go out. In the afternoon, a customer calls with a problem and Rafael needs two hours to solve it. When he finally leaves the office, he is tired but satisfied. \"Tomorrow will be easier,\" he thinks."], "paragraphs_pt": ["A segunda-feira é sempre o dia mais corrido para Rafael. Quando ele chega ao escritório às oito e meia, já há trinta e-mails novos na caixa de entrada. Ele faz um café e começa a responder os mais importantes.", "Às dez, tem uma reunião com a equipe para planejar a semana. Eles falam de prazos e decidem quem vai fazer cada tarefa. Rafael precisa terminar um relatório até quarta-feira, então pede ajuda à colega Julia.", "No almoço, ele costuma comer um sanduíche na mesa porque não tem tempo de sair. À tarde, um cliente liga com um problema e Rafael precisa de duas horas para resolvê-lo. Quando finalmente sai do escritório, está cansado, mas satisfeito. \"Amanhã será mais fácil\", pensa."], "hard_words": ["deadlines", "report", "colleague", "satisfied"], "vocab": [{"word": "busiest", "meaning": "mais ocupado", "note": ""}, {"word": "inbox", "meaning": "caixa de entrada", "note": ""}, {"word": "deadlines", "meaning": "prazos", "note": ""}, {"word": "task", "meaning": "tarefa", "note": ""}, {"word": "report", "meaning": "relatório", "note": ""}, {"word": "colleague", "meaning": "colega de trabalho", "note": ""}, {"word": "customer", "meaning": "cliente", "note": ""}, {"word": "solve", "meaning": "resolver", "note": ""}, {"word": "satisfied", "meaning": "satisfeito", "note": ""}, {"word": "tired", "meaning": "cansado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are", "be"], "irregular": ["tired", "satisfied"], "phrasal": ["plan the week", "go out"], "wh": ["who", "when"], "connectors": ["and", "but", "because", "so", "when", "finally"], "comparative": []}, "word_meanings": [{"word": "busiest", "meaning": "mais ocupado", "note": ""}, {"word": "inbox", "meaning": "caixa de entrada", "note": ""}, {"word": "deadlines", "meaning": "prazos", "note": ""}, {"word": "task", "meaning": "tarefa", "note": ""}, {"word": "report", "meaning": "relatório", "note": ""}, {"word": "colleague", "meaning": "colega de trabalho", "note": ""}, {"word": "customer", "meaning": "cliente", "note": ""}, {"word": "solve", "meaning": "resolver", "note": ""}, {"word": "satisfied", "meaning": "satisfeito", "note": ""}, {"word": "tired", "meaning": "cansado", "note": ""}], "exercises": {"grammar": [{"point": "Superlativo", "explanation_pt": "'the busiest day' compara um dia com todos os outros: adjetivo curto + -est."}, {"point": "Going to e will", "explanation_pt": "'who is going to do each task' fala de planos; 'Tomorrow will be easier' é uma previsão."}], "multiple_choice": [{"question": "Why is Monday busy for Rafael?", "options": ["Many emails and tasks", "He is late", "He is on holiday", "There is no work"], "correct_index": 0, "explanation": "Há muitos e-mails, reunião e problemas."}, {"question": "How many emails are in his inbox?", "options": ["Three hundred", "None", "Thirty", "Three"], "correct_index": 2, "explanation": "Há trinta e-mails novos."}, {"question": "What does the team do at ten?", "options": ["Play games", "Have lunch", "Visit a customer", "Plan the week"], "correct_index": 3, "explanation": "Eles planejam a semana."}, {"question": "Who does Rafael ask for help?", "options": ["A customer", "His boss", "Julia", "His father"], "correct_index": 2, "explanation": "Ele pede ajuda à colega Julia."}, {"question": "How does Rafael feel at the end?", "options": ["Angry", "Tired but satisfied", "Bored", "Sad"], "correct_index": 1, "explanation": "Ele sai cansado, mas satisfeito."}], "open_questions": [{"question": "What is your busiest day of the week? Why?", "key_points_pt": ["descrever uma rotina", "usar o superlativo"]}, {"question": "How do you organize your tasks?", "key_points_pt": ["citar listas, prazos e prioridades"]}]}}, {"level": "A2", "genre": "corporate", "title": "The Job Interview", "paragraphs": ["Yesterday, Beatriz had an interview for a job at a travel agency. She wore her best dress and arrived fifteen minutes early. She was very nervous, but she tried to smile.", "The interviewer, Mr. Costa, asked her many questions: \"Why do you want this job?\" and \"Can you work in a team?\" Beatriz answered honestly. She said that she loved travelling and that she was good at organizing things.", "At the end, Mr. Costa said, \"Thank you for coming. We will call you on Friday.\" Beatriz went home and waited. On Friday morning, her phone rang. \"Congratulations, Beatriz! You start on Monday,\" said Mr. Costa. She screamed with joy."], "paragraphs_pt": ["Ontem, Beatriz teve uma entrevista para uma vaga numa agência de viagens. Ela vestiu seu melhor vestido e chegou quinze minutos mais cedo. Estava muito nervosa, mas tentou sorrir.", "O entrevistador, Sr. Costa, fez muitas perguntas: \"Por que você quer este emprego?\" e \"Você consegue trabalhar em equipe?\" Beatriz respondeu com sinceridade. Disse que adorava viajar e que era boa em organizar as coisas.", "No fim, o Sr. Costa disse: \"Obrigado por vir. Vamos ligar para você na sexta.\" Beatriz foi para casa e esperou. Na sexta de manhã, o celular tocou. \"Parabéns, Beatriz! Você começa na segunda\", disse o Sr. Costa. Ela gritou de alegria."], "hard_words": ["interviewer", "honestly", "congratulations", "screamed"], "vocab": [{"word": "interview", "meaning": "entrevista", "note": ""}, {"word": "travel agency", "meaning": "agência de viagens", "note": ""}, {"word": "early", "meaning": "cedo", "note": ""}, {"word": "interviewer", "meaning": "entrevistador", "note": ""}, {"word": "honestly", "meaning": "com sinceridade", "note": ""}, {"word": "organizing", "meaning": "organizar", "note": ""}, {"word": "congratulations", "meaning": "parabéns", "note": ""}, {"word": "screamed", "meaning": "gritou", "note": ""}, {"word": "joy", "meaning": "alegria", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["had", "wore", "arrived", "tried", "asked", "answered", "said", "loved", "went", "waited", "rang", "screamed"], "phrasal": [], "wh": ["why"], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "interview", "meaning": "entrevista", "note": ""}, {"word": "travel agency", "meaning": "agência de viagens", "note": ""}, {"word": "early", "meaning": "cedo", "note": ""}, {"word": "interviewer", "meaning": "entrevistador", "note": ""}, {"word": "honestly", "meaning": "com sinceridade", "note": ""}, {"word": "organizing", "meaning": "organizar", "note": ""}, {"word": "congratulations", "meaning": "parabéns", "note": ""}, {"word": "screamed", "meaning": "gritou", "note": ""}, {"word": "joy", "meaning": "alegria", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "Usamos o passado simples para ações terminadas: 'She wore', 'asked', 'answered'. Alguns verbos são irregulares: wear → wore, go → went."}, {"point": "Can para habilidades", "explanation_pt": "'Can you work in a team?' pergunta sobre habilidade."}], "multiple_choice": [{"question": "What job did Beatriz want?", "options": ["A cook", "A driver", "A teacher", "A job at a travel agency"], "correct_index": 3, "explanation": "Era uma vaga numa agência de viagens."}, {"question": "When did she arrive?", "options": ["At noon", "One hour late", "Fifteen minutes early", "On time exactly"], "correct_index": 2, "explanation": "Chegou quinze minutos mais cedo."}, {"question": "What did Mr. Costa ask?", "options": ["What she ate", "Why she wanted the job", "How old she was", "Where she lived"], "correct_index": 1, "explanation": "Ele perguntou por que ela queria o emprego."}, {"question": "When did Mr. Costa say he would call?", "options": ["Yesterday", "On Friday", "On Monday", "Next year"], "correct_index": 1, "explanation": "Ele ligaria na sexta."}, {"question": "What happened on Friday morning?", "options": ["She traveled", "She got the job", "She lost her phone", "She went to a party"], "correct_index": 1, "explanation": "Ela foi aprovada e começa na segunda."}], "open_questions": [{"question": "How do you prepare for an interview?", "key_points_pt": ["citar roupa, perguntas, chegar cedo"]}, {"question": "What are you good at?", "key_points_pt": ["descrever qualidades usando 'I am good at'"]}]}}, {"level": "A2", "genre": "corporate", "title": "Working From Home", "paragraphs": ["Since March, Paulo works from home three days a week. He likes it because he does not need to take the bus, and he can drink coffee in his pajamas. But it is not always easy.", "His apartment is small, so his desk is in the living room. When his roommate watches TV, it is difficult to concentrate. Also, he misses his colleagues. Sometimes he talks to the wall, and he feels a little lonely.", "To solve this, Paulo made a plan. He wakes up at seven, takes a shower and gets dressed before work. He also calls a colleague every afternoon, just to talk about normal things. After two weeks, he feels better and more productive."], "paragraphs_pt": ["Desde março, Paulo trabalha de casa três dias por semana. Ele gosta porque não precisa pegar ônibus e pode tomar café de pijama. Mas nem sempre é fácil.", "O apartamento dele é pequeno, então a mesa fica na sala. Quando o colega de apartamento assiste à TV, é difícil se concentrar. Além disso, ele sente falta dos colegas. Às vezes fala com a parede e se sente um pouco solitário.", "Para resolver isso, Paulo fez um plano. Acorda às sete, toma banho e se veste antes do trabalho. Também liga para um colega toda tarde, só para conversar sobre coisas normais. Depois de duas semanas, ele se sente melhor e mais produtivo."], "hard_words": ["concentrate", "lonely", "productive", "roommate"], "vocab": [{"word": "works from home", "meaning": "trabalha de casa", "note": ""}, {"word": "pajamas", "meaning": "pijama", "note": ""}, {"word": "living room", "meaning": "sala de estar", "note": ""}, {"word": "roommate", "meaning": "colega de apartamento", "note": ""}, {"word": "concentrate", "meaning": "concentrar-se", "note": ""}, {"word": "misses", "meaning": "sente falta de", "note": ""}, {"word": "lonely", "meaning": "solitário", "note": ""}, {"word": "productive", "meaning": "produtivo", "note": ""}, {"word": "plan", "meaning": "plano", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": ["made", "dressed"], "phrasal": ["wakes up", "gets dressed"], "wh": ["when"], "connectors": ["and", "but", "because", "so", "after", "before", "when", "since", "also"], "comparative": []}, "word_meanings": [{"word": "works from home", "meaning": "trabalha de casa", "note": ""}, {"word": "pajamas", "meaning": "pijama", "note": ""}, {"word": "living room", "meaning": "sala de estar", "note": ""}, {"word": "roommate", "meaning": "colega de apartamento", "note": ""}, {"word": "concentrate", "meaning": "concentrar-se", "note": ""}, {"word": "misses", "meaning": "sente falta de", "note": ""}, {"word": "lonely", "meaning": "solitário", "note": ""}, {"word": "productive", "meaning": "produtivo", "note": ""}, {"word": "plan", "meaning": "plano", "note": ""}], "exercises": {"grammar": [{"point": "Present simple e present perfect simples de tempo", "explanation_pt": "'Since March' mostra desde quando algo acontece, mas aqui o presente é usado porque é uma rotina atual."}, {"point": "Comparativos", "explanation_pt": "'better and more productive' compara com a situação anterior."}], "multiple_choice": [{"question": "How many days a week does Paulo work from home?", "options": ["Five", "Three", "Seven", "One"], "correct_index": 1, "explanation": "Ele trabalha de casa três dias por semana."}, {"question": "What does he like about it?", "options": ["He does not need to take the bus", "The long meetings", "The big office", "The free lunch"], "correct_index": 0, "explanation": "Ele não precisa pegar ônibus."}, {"question": "What is a problem at home?", "options": ["The desk is too big", "He has no coffee", "The roommate watches TV", "He has no computer"], "correct_index": 2, "explanation": "O colega de apartamento assiste TV e atrapalha."}, {"question": "What does Paulo do every afternoon?", "options": ["Goes to the gym", "Sleeps", "Calls a colleague", "Plays music"], "correct_index": 2, "explanation": "Ele liga para um colega."}, {"question": "How does he feel after two weeks?", "options": ["Better and more productive", "Angrier", "Worse", "Sleepier"], "correct_index": 0, "explanation": "Ele se sente melhor e mais produtivo."}], "open_questions": [{"question": "Do you prefer working at home or at an office? Why?", "key_points_pt": ["dar opinião com motivos"]}, {"question": "What is difficult about working from home?", "key_points_pt": ["citar ruído, solidão, distrações"]}]}}, {"level": "B1", "genre": "corporate", "title": "The Presentation", "paragraphs": ["Fernanda had been preparing for the presentation for two weeks. She had checked every slide twice, practiced in front of the mirror and even recorded herself on her phone. Still, when she walked into the meeting room and saw twenty people looking at her, her hands began to shake.", "She took a deep breath and started. The first minutes were difficult, and she spoke too quickly. Then she noticed that her boss was nodding, and something relaxed inside her. She slowed down, looked at people's faces and began to enjoy herself.", "When a client asked an unexpected question about costs, Fernanda did not have the answer. Instead of pretending, she said, \"That is a good point. I will check the numbers and send you an email today.\" The client smiled.", "Afterwards, her boss told her that the honesty had impressed him more than the slides. Fernanda went home exhausted, but she realized that confidence did not mean knowing everything; it meant staying calm when you did not."], "paragraphs_pt": ["Fernanda se preparava para a apresentação havia duas semanas. Tinha conferido cada slide duas vezes, praticado diante do espelho e até se gravado no celular. Mesmo assim, quando entrou na sala de reunião e viu vinte pessoas olhando para ela, as mãos começaram a tremer.", "Ela respirou fundo e começou. Os primeiros minutos foram difíceis, e ela falou rápido demais. Então notou que o chefe estava concordando com a cabeça, e algo relaxou dentro dela. Desacelerou, olhou para os rostos e começou a se divertir.", "Quando um cliente fez uma pergunta inesperada sobre custos, Fernanda não tinha a resposta. Em vez de fingir, disse: \"Boa pergunta. Vou conferir os números e envio um e-mail hoje.\" O cliente sorriu.", "Depois, o chefe disse que a honestidade o impressionara mais do que os slides. Fernanda foi para casa exausta, mas percebeu que confiança não significava saber tudo; significava manter a calma quando não se sabia."], "hard_words": ["nodding", "pretending", "honesty", "exhausted"], "vocab": [{"word": "slide", "meaning": "slide", "note": ""}, {"word": "recorded", "meaning": "gravou", "note": ""}, {"word": "shake", "meaning": "tremer", "note": ""}, {"word": "deep breath", "meaning": "respiração profunda", "note": ""}, {"word": "nodding", "meaning": "concordando com a cabeça", "note": ""}, {"word": "client", "meaning": "cliente", "note": ""}, {"word": "pretending", "meaning": "fingindo", "note": ""}, {"word": "honesty", "meaning": "honestidade", "note": ""}, {"word": "impressed", "meaning": "impressionou", "note": ""}, {"word": "exhausted", "meaning": "exausta", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "were", "was", "is"], "irregular": ["had", "checked", "practiced", "recorded", "walked", "saw", "began", "took", "started", "spoke", "noticed", "relaxed", "slowed", "looked", "asked", "did", "said", "smiled", "told", "impressed", "went", "exhausted", "realized", "meant"], "phrasal": ["walked into", "slowed down"], "wh": ["when"], "connectors": ["and", "but", "instead", "then", "when", "still"], "comparative": []}, "word_meanings": [{"word": "slide", "meaning": "slide", "note": ""}, {"word": "recorded", "meaning": "gravou", "note": ""}, {"word": "shake", "meaning": "tremer", "note": ""}, {"word": "deep breath", "meaning": "respiração profunda", "note": ""}, {"word": "nodding", "meaning": "concordando com a cabeça", "note": ""}, {"word": "client", "meaning": "cliente", "note": ""}, {"word": "pretending", "meaning": "fingindo", "note": ""}, {"word": "honesty", "meaning": "honestidade", "note": ""}, {"word": "impressed", "meaning": "impressionou", "note": ""}, {"word": "exhausted", "meaning": "exausta", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect continuous", "explanation_pt": "'had been preparing for two weeks' mostra uma ação que durou até outro momento do passado."}, {"point": "Instead of + -ing", "explanation_pt": "'Instead of pretending' significa 'em vez de fingir'."}], "multiple_choice": [{"question": "How long had Fernanda been preparing?", "options": ["One hour", "Two days", "Two months", "Two weeks"], "correct_index": 3, "explanation": "Ela se preparava havia duas semanas."}, {"question": "Why did her hands shake?", "options": ["Twenty people were looking at her", "She was cold", "She forgot the slides", "She was ill"], "correct_index": 0, "explanation": "Vinte pessoas olhavam para ela."}, {"question": "What helped her relax?", "options": ["The lights went out", "She drank water", "Her boss was nodding", "The client left"], "correct_index": 2, "explanation": "O chefe concordava com a cabeça."}, {"question": "What did she say about the unexpected question?", "options": ["She would check and send an email", "She refused to answer", "She did not care", "She invented a number"], "correct_index": 0, "explanation": "Ela prometeu conferir e enviar um e-mail."}, {"question": "What did Fernanda learn?", "options": ["Never practice", "Slides are not important", "Confidence is staying calm when you do not know", "Clients are always right"], "correct_index": 2, "explanation": "Confiança é manter a calma."}], "open_questions": [{"question": "Is it better to admit you do not know something or to guess?", "key_points_pt": ["defender uma posição", "usar exemplos de trabalho"]}, {"question": "What helps you feel calm before speaking in public?", "key_points_pt": ["listar técnicas pessoais"]}]}}, {"level": "B1", "genre": "corporate", "title": "The Promotion", "paragraphs": ["When Ricardo heard that a manager position was open in his department, he felt a mixture of hope and fear. He had worked at the company for six years and he knew the job better than anyone, but he was also aware that he often avoided speaking in front of senior people.", "His colleague Teresa, who also wanted the position, seemed more confident. She talked constantly in meetings and always had an opinion. Ricardo began to doubt himself and almost decided not to apply.", "A week before the deadline, his mentor Mr. Almeida invited him for coffee. \"Do you think being loud is the same as being a leader?\" he asked. \"I have watched you for years. When people have a problem, they go to you, not to the person who talks the most.\"", "Ricardo applied. He did not get the position, because the company chose Teresa, but his boss told him that the interview had been excellent and that another role would open soon. For the first time, he felt that he was no longer invisible."], "paragraphs_pt": ["Quando Ricardo soube que havia uma vaga de gerente no seu departamento, sentiu uma mistura de esperança e medo. Trabalhava na empresa havia seis anos e conhecia o trabalho melhor do que ninguém, mas também sabia que muitas vezes evitava falar diante de pessoas mais seniores.", "Sua colega Teresa, que também queria a vaga, parecia mais confiante. Falava sem parar nas reuniões e sempre tinha uma opinião. Ricardo começou a duvidar de si e quase decidiu não se candidatar.", "Uma semana antes do prazo, o mentor dele, o Sr. Almeida, o convidou para um café. \"Você acha que falar alto é o mesmo que ser líder?\", perguntou. \"Eu observo você há anos. Quando as pessoas têm um problema, procuram você, não quem fala mais.\"", "Ricardo se candidatou. Não conseguiu a vaga, porque a empresa escolheu Teresa, mas o chefe disse que a entrevista tinha sido excelente e que outro cargo abriria em breve. Pela primeira vez, ele sentiu que já não era invisível."], "hard_words": ["mixture", "aware", "doubt", "invisible"], "vocab": [{"word": "position", "meaning": "cargo, vaga", "note": ""}, {"word": "mixture", "meaning": "mistura", "note": ""}, {"word": "aware", "meaning": "ciente", "note": ""}, {"word": "senior", "meaning": "mais experiente, sênior", "note": ""}, {"word": "confident", "meaning": "confiante", "note": ""}, {"word": "doubt", "meaning": "duvidar", "note": ""}, {"word": "apply", "meaning": "candidatar-se", "note": ""}, {"word": "deadline", "meaning": "prazo final", "note": ""}, {"word": "mentor", "meaning": "mentor", "note": ""}, {"word": "invisible", "meaning": "invisível", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being", "is", "been"], "irregular": ["heard", "felt", "had", "worked", "knew", "avoided", "wanted", "seemed", "talked", "began", "decided", "invited", "asked", "watched", "applied", "did", "chose", "told", "would"], "phrasal": ["go to"], "wh": ["who", "when"], "connectors": ["and", "but", "because", "before", "when", "also", "as"], "comparative": []}, "word_meanings": [{"word": "position", "meaning": "cargo, vaga", "note": ""}, {"word": "mixture", "meaning": "mistura", "note": ""}, {"word": "aware", "meaning": "ciente", "note": ""}, {"word": "senior", "meaning": "mais experiente, sênior", "note": ""}, {"word": "confident", "meaning": "confiante", "note": ""}, {"word": "doubt", "meaning": "duvidar", "note": ""}, {"word": "apply", "meaning": "candidatar-se", "note": ""}, {"word": "deadline", "meaning": "prazo final", "note": ""}, {"word": "mentor", "meaning": "mentor", "note": ""}, {"word": "invisible", "meaning": "invisível", "note": ""}], "exercises": {"grammar": [{"point": "Present perfect e past simple", "explanation_pt": "'He had worked at the company for six years' (past perfect) mostra tempo anterior ao momento em que ouviu a notícia."}, {"point": "Not the same as", "explanation_pt": "'Is being loud the same as being a leader?' compara duas ideias e questiona se são iguais."}], "multiple_choice": [{"question": "How long had Ricardo worked at the company?", "options": ["Twenty years", "Two years", "Six years", "Six months"], "correct_index": 2, "explanation": "Ele trabalhava lá havia seis anos."}, {"question": "Why did he almost not apply?", "options": ["He doubted himself", "He disliked the job", "He had no time", "He was moving"], "correct_index": 0, "explanation": "Ele duvidava de si ao se comparar com Teresa."}, {"question": "What did Mr. Almeida notice about Ricardo?", "options": ["People go to him with problems", "He is the loudest", "He is always late", "He is the oldest"], "correct_index": 0, "explanation": "As pessoas o procuram quando têm problemas."}, {"question": "Did Ricardo get the position?", "options": ["The job was cancelled", "No one did", "Yes, he did", "No, Teresa did"], "correct_index": 3, "explanation": "A empresa escolheu Teresa."}, {"question": "How did he feel in the end?", "options": ["No longer invisible", "Angry", "Defeated", "Lost"], "correct_index": 0, "explanation": "Ele sentiu que já não era invisível."}], "open_questions": [{"question": "Is a good leader always the loudest person? Explain.", "key_points_pt": ["contrastar liderança e comunicação"]}, {"question": "Have you ever doubted yourself before applying for something?", "key_points_pt": ["contar uma experiência"]}]}}, {"level": "B2", "genre": "corporate", "title": "The Reorganization", "paragraphs": ["The email arrived at 8:04 on a Thursday morning, and its subject line, \"An important update about our structure,\" made half the office pause in mid-sentence. Within ten minutes, rumors had spread to every floor. Some predicted layoffs; others insisted it was only a change in reporting lines.", "Mariana, a project coordinator who had survived two previous reorganizations, did what she always did: she observed. She noticed who was suddenly polite, who was avoiding eye contact in the corridor, and which managers had been called into closed-door meetings. By lunchtime she had a surprisingly accurate map of the situation.", "The official announcement, when it came, was less dramatic than the rumors but more consequential than the email suggested. Her department would be merged with another, and half of the existing roles would be redefined. Mariana's name appeared on a list of people who would be \"consulted,\" a word she had learned to read with suspicion.", "She spent the weekend updating her résumé, not because she wanted to leave, but because she wanted the freedom to choose. On Monday she asked for a meeting with her new manager and, instead of asking whether her job was safe, she described three projects she could lead. It was not a guarantee, but it changed the conversation from fear to value."], "paragraphs_pt": ["O e-mail chegou às 8h04 de uma quinta-feira, e o assunto, \"Uma atualização importante sobre nossa estrutura\", fez metade do escritório parar no meio da frase. Em dez minutos, os boatos já tinham se espalhado por todos os andares. Alguns previam demissões; outros insistiam que era só uma mudança nas linhas de subordinação.", "Mariana, coordenadora de projetos que sobrevivera a duas reorganizações anteriores, fez o que sempre fazia: observou. Notou quem de repente estava educado, quem evitava contato visual no corredor e quais gerentes haviam sido chamados a reuniões de portas fechadas. Na hora do almoço, já tinha um mapa surpreendentemente preciso da situação.", "O comunicado oficial, quando veio, foi menos dramático do que os boatos, mas mais consequente do que o e-mail sugeria. O departamento dela seria fundido a outro, e metade dos cargos existentes seria redefinida. O nome de Mariana apareceu numa lista de pessoas que seriam \"consultadas\", palavra que ela aprendera a ler com desconfiança.", "Passou o fim de semana atualizando o currículo, não porque quisesse sair, mas porque queria a liberdade de escolher. Na segunda, pediu uma reunião com a nova gestora e, em vez de perguntar se seu emprego estava seguro, descreveu três projetos que poderia liderar. Não era uma garantia, mas mudou a conversa do medo para o valor."], "hard_words": ["rumors", "layoffs", "merged", "suspicion"], "vocab": [{"word": "reorganization", "meaning": "reorganização", "note": ""}, {"word": "rumors", "meaning": "boatos", "note": ""}, {"word": "layoffs", "meaning": "demissões em massa", "note": ""}, {"word": "reporting lines", "meaning": "linhas de subordinação", "note": ""}, {"word": "eye contact", "meaning": "contato visual", "note": ""}, {"word": "consequential", "meaning": "importante, com consequências", "note": ""}, {"word": "merged", "meaning": "fundido", "note": ""}, {"word": "redefined", "meaning": "redefinidos", "note": ""}, {"word": "suspicion", "meaning": "desconfiança", "note": ""}, {"word": "résumé", "meaning": "currículo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "be"], "irregular": ["arrived", "made", "had", "predicted", "insisted", "survived", "did", "observed", "noticed", "called", "closed", "came", "suggested", "would", "merged", "redefined", "appeared", "consulted", "learned", "spent", "wanted", "asked", "described", "could", "changed"], "phrasal": ["pause in mid-sentence"], "wh": ["who", "what", "when", "which"], "connectors": ["and", "but", "because", "instead", "when", "suddenly"], "comparative": []}, "word_meanings": [{"word": "reorganization", "meaning": "reorganização", "note": ""}, {"word": "rumors", "meaning": "boatos", "note": ""}, {"word": "layoffs", "meaning": "demissões em massa", "note": ""}, {"word": "reporting lines", "meaning": "linhas de subordinação", "note": ""}, {"word": "eye contact", "meaning": "contato visual", "note": ""}, {"word": "consequential", "meaning": "importante, com consequências", "note": ""}, {"word": "merged", "meaning": "fundido", "note": ""}, {"word": "redefined", "meaning": "redefinidos", "note": ""}, {"word": "suspicion", "meaning": "desconfiança", "note": ""}, {"word": "résumé", "meaning": "currículo", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'who had survived two previous reorganizations' mostra experiência anterior ao dia da história."}, {"point": "Not because... but because", "explanation_pt": "'not because she wanted to leave, but because she wanted the freedom to choose' contrasta dois motivos."}], "multiple_choice": [{"question": "What made half the office pause?", "options": ["A loud meeting", "A phone call", "A fire alarm", "The subject line of an email"], "correct_index": 3, "explanation": "O assunto do e-mail parou metade do escritório."}, {"question": "What did Mariana do when she heard the news?", "options": ["She quit", "She went home", "She observed people", "She started a rumor"], "correct_index": 2, "explanation": "Ela observou o comportamento das pessoas."}, {"question": "What was the announcement about?", "options": ["A new product", "A holiday", "A merger of departments", "A price increase"], "correct_index": 2, "explanation": "O departamento seria fundido a outro."}, {"question": "How did Mariana read the word 'consulted'?", "options": ["With surprise", "With suspicion", "With pride", "With joy"], "correct_index": 1, "explanation": "Ela aprendeu a ler a palavra com desconfiança."}, {"question": "What did she do on Monday?", "options": ["She described projects she could lead", "She resigned", "She asked if her job was safe", "She cried"], "correct_index": 0, "explanation": "Ela mostrou valor em vez de perguntar sobre segurança."}], "open_questions": [{"question": "How can employees prepare for uncertainty at work?", "key_points_pt": ["citar networking, currículo, observação"]}, {"question": "Why do companies often communicate change badly?", "key_points_pt": ["discutir transparência, medo e boatos"]}]}}, {"level": "B2", "genre": "corporate", "title": "The Meeting That Should Have Been an Email", "paragraphs": ["Gabriel had a theory that most meetings could be replaced with a three-line email. He had spent the last year collecting evidence: a calendar full of back-to-back calls, two-hour discussions that ended with \"let's take this offline,\" and colleagues who answered messages while pretending to listen.", "One Friday, his manager invited the whole department to a ninety-minute session called \"Alignment on Priorities.\" Gabriel counted forty-one slides. By the thirtieth, a colleague was texting under the table, and the manager was reading a slide aloud word for word, which, he noticed, nobody had asked for.", "Instead of complaining, he sent a short message the next day: a proposal to try a \"meeting-free Wednesday\" for one month, with a shared document for updates. To his surprise, the manager agreed, perhaps because several people had already thanked Gabriel in private for saying what everybody was thinking.", "The experiment worked better than expected. Without constant interruptions, the team finished tasks faster, and the few meetings that remained became sharper and shorter. Gabriel never boasted about it. He simply deleted the spreadsheet where he had been counting wasted hours and replaced it with a new one called \"What we did with the time.\""], "paragraphs_pt": ["Gabriel tinha uma teoria de que a maioria das reuniões poderia ser substituída por um e-mail de três linhas. Passara o último ano colhendo provas: uma agenda cheia de chamadas seguidas, discussões de duas horas que terminavam com \"vamos resolver isso depois\" e colegas que respondiam mensagens fingindo ouvir.", "Numa sexta-feira, o gerente convidou todo o departamento para uma sessão de noventa minutos chamada \"Alinhamento de prioridades\". Gabriel contou quarenta e um slides. No trigésimo, um colega mandava mensagens embaixo da mesa, e o gerente lia um slide em voz alta, palavra por palavra, algo que, ele notou, ninguém pedira.", "Em vez de reclamar, ele mandou uma mensagem curta no dia seguinte: uma proposta de testar uma \"quarta sem reuniões\" por um mês, com um documento compartilhado para atualizações. Para sua surpresa, o gerente concordou, talvez porque várias pessoas já tinham agradecido a Gabriel em particular por dizer o que todos pensavam.", "O experimento funcionou melhor do que o esperado. Sem interrupções constantes, a equipe terminou tarefas mais rápido, e as poucas reuniões que restaram ficaram mais objetivas e curtas. Gabriel nunca se vangloriou. Apenas apagou a planilha em que contava as horas desperdiçadas e a substituiu por outra, chamada \"O que fizemos com o tempo.\""], "hard_words": ["alignment", "proposal", "boasted", "spreadsheet"], "vocab": [{"word": "back-to-back", "meaning": "seguidas, uma após a outra", "note": ""}, {"word": "offline", "meaning": "fora da reunião", "note": ""}, {"word": "alignment", "meaning": "alinhamento", "note": ""}, {"word": "priorities", "meaning": "prioridades", "note": ""}, {"word": "texting", "meaning": "mandando mensagens", "note": ""}, {"word": "proposal", "meaning": "proposta", "note": ""}, {"word": "interruptions", "meaning": "interrupções", "note": ""}, {"word": "boasted", "meaning": "se vangloriou", "note": ""}, {"word": "spreadsheet", "meaning": "planilha", "note": ""}, {"word": "wasted", "meaning": "desperdiçadas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "was", "been"], "irregular": ["had", "could", "replaced", "spent", "ended", "answered", "invited", "called", "counted", "noticed", "asked", "sent", "shared", "agreed", "thanked", "worked", "expected", "finished", "remained", "became", "boasted", "deleted", "wasted", "did"], "phrasal": ["take this offline"], "wh": ["who", "what", "where", "which"], "connectors": ["and", "because", "while", "instead"], "comparative": []}, "word_meanings": [{"word": "back-to-back", "meaning": "seguidas, uma após a outra", "note": ""}, {"word": "offline", "meaning": "fora da reunião", "note": ""}, {"word": "alignment", "meaning": "alinhamento", "note": ""}, {"word": "priorities", "meaning": "prioridades", "note": ""}, {"word": "texting", "meaning": "mandando mensagens", "note": ""}, {"word": "proposal", "meaning": "proposta", "note": ""}, {"word": "interruptions", "meaning": "interrupções", "note": ""}, {"word": "boasted", "meaning": "se vangloriou", "note": ""}, {"word": "spreadsheet", "meaning": "planilha", "note": ""}, {"word": "wasted", "meaning": "desperdiçadas", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'He had spent the last year collecting evidence' indica algo anterior à sexta-feira descrita."}, {"point": "Instead of + -ing", "explanation_pt": "'Instead of complaining' significa 'em vez de reclamar'."}], "multiple_choice": [{"question": "What was Gabriel's theory?", "options": ["Everyone should work at night", "Emails are useless", "Most meetings could be an email", "Meetings are fun"], "correct_index": 2, "explanation": "Ele achava que a maioria das reuniões podia ser um e-mail."}, {"question": "How many slides were in the Friday session?", "options": ["Four", "Ten", "Forty-one", "Ninety"], "correct_index": 2, "explanation": "Ele contou quarenta e um slides."}, {"question": "What did Gabriel propose?", "options": ["More meetings", "Working on weekends", "A meeting-free Wednesday", "A longer lunch"], "correct_index": 2, "explanation": "Ele propôs uma quarta sem reuniões."}, {"question": "What was the result of the experiment?", "options": ["The team quit", "Meetings got longer", "Nobody noticed", "Tasks were finished faster"], "correct_index": 3, "explanation": "A equipe terminou tarefas mais rápido."}, {"question": "What did Gabriel do with his spreadsheet?", "options": ["Sent it to the boss", "Replaced it with 'What we did with the time'", "Kept it secret", "Printed it"], "correct_index": 1, "explanation": "Ele a substituiu por outra planilha positiva."}], "open_questions": [{"question": "How can a company decide which meetings are necessary?", "key_points_pt": ["propor critérios claros"]}, {"question": "Is it a good idea to propose changes publicly or privately?", "key_points_pt": ["defender uma posição"]}]}}, {"level": "C1", "genre": "corporate", "title": "The Weight of Being Indispensable", "paragraphs": ["For nearly a decade, Leila had been the person to whom everything in the department flowed. Nobody knew precisely how the budget spreadsheets were structured, which client required which unspoken courtesy, or why the shared drive had its peculiar logic. She did, and for a long time that knowledge felt like a form of security.", "Then one spring she took three days of sick leave, and the department nearly came to a standstill. Deadlines slipped, a client was offended by an unintentional oversight, and somebody deleted a folder that took her a week to restore. When she returned, her manager thanked her warmly for being \"so crucial.\" Leila felt, unexpectedly, that she was being congratulated on a flaw.", "She began to understand that being indispensable was not the same as being valued. It meant that the organisation had quietly outsourced its memory to one person and had never examined the risk. Her colleagues, meanwhile, were deprived of the chance to learn, and her own career had stalled because nobody could imagine replacing her.", "Over the following months she did something that terrified her: she documented everything and trained others. By the autumn she could take a week's holiday without a single phone call, and, more surprisingly, she was offered a role in strategy. She came to see that the most generous thing she could do for her team was to make herself unnecessary."], "paragraphs_pt": ["Por quase uma década, Leila fora a pessoa para quem tudo no departamento convergia. Ninguém sabia exatamente como as planilhas de orçamento eram estruturadas, qual cliente exigia qual gentileza não dita, ou por que o drive compartilhado tinha aquela lógica peculiar. Ela sabia, e por muito tempo esse conhecimento pareceu uma forma de segurança.", "Então, numa primavera, ela tirou três dias de licença médica e o departamento quase parou. Prazos atrasaram, um cliente se ofendeu com um descuido involuntário e alguém apagou uma pasta que levou uma semana para ela restaurar. Quando voltou, o gerente a agradeceu calorosamente por ser \"tão crucial.\" Leila sentiu, inesperadamente, que estava sendo parabenizada por um defeito.", "Começou a entender que ser indispensável não era o mesmo que ser valorizada. Significava que a organização havia terceirizado discretamente sua memória a uma só pessoa e nunca examinara o risco. Os colegas, enquanto isso, eram privados da chance de aprender, e a própria carreira dela estagnara porque ninguém conseguia imaginar substituí-la.", "Nos meses seguintes ela fez algo que a aterrorizava: documentou tudo e treinou os outros. No outono, já podia tirar uma semana de férias sem uma única ligação e, o que foi mais surpreendente, recebeu a oferta de um cargo em estratégia. Chegou a ver que a coisa mais generosa que podia fazer pela equipe era tornar-se desnecessária."], "hard_words": ["indispensable", "standstill", "outsourced", "stalled"], "vocab": [{"word": "indispensable", "meaning": "indispensável", "note": ""}, {"word": "courtesy", "meaning": "gentileza, cortesia", "note": ""}, {"word": "standstill", "meaning": "paralisação", "note": ""}, {"word": "oversight", "meaning": "descuido", "note": ""}, {"word": "flaw", "meaning": "defeito", "note": ""}, {"word": "outsourced", "meaning": "terceirizou", "note": ""}, {"word": "deprived", "meaning": "privados", "note": ""}, {"word": "stalled", "meaning": "estagnou", "note": ""}, {"word": "documented", "meaning": "documentou", "note": ""}, {"word": "unnecessary", "meaning": "desnecessária", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "were", "was", "being"], "irregular": ["had", "flowed", "knew", "structured", "required", "shared", "did", "felt", "took", "came", "slipped", "offended", "deleted", "returned", "thanked", "congratulated", "began", "valued", "meant", "outsourced", "examined", "deprived", "stalled", "could", "terrified", "documented", "trained", "offered"], "phrasal": [], "wh": ["when", "why", "how", "which", "whom"], "connectors": ["and", "because", "so", "then", "when", "meanwhile", "or", "as"], "comparative": []}, "word_meanings": [{"word": "indispensable", "meaning": "indispensável", "note": ""}, {"word": "courtesy", "meaning": "gentileza, cortesia", "note": ""}, {"word": "standstill", "meaning": "paralisação", "note": ""}, {"word": "oversight", "meaning": "descuido", "note": ""}, {"word": "flaw", "meaning": "defeito", "note": ""}, {"word": "outsourced", "meaning": "terceirizou", "note": ""}, {"word": "deprived", "meaning": "privados", "note": ""}, {"word": "stalled", "meaning": "estagnou", "note": ""}, {"word": "documented", "meaning": "documentou", "note": ""}, {"word": "unnecessary", "meaning": "desnecessária", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Leila had been the person to whom everything flowed' descreve uma situação que vinha de antes da data central."}, {"point": "Not the same as", "explanation_pt": "'being indispensable was not the same as being valued' compara dois conceitos que parecem iguais."}], "multiple_choice": [{"question": "Why was Leila 'indispensable'?", "options": ["She was the oldest", "Only she knew how things worked", "She was the boss", "She worked at night"], "correct_index": 1, "explanation": "Só ela sabia como as coisas funcionavam."}, {"question": "What happened when she took sick leave?", "options": ["The boss was fired", "A new manager arrived", "The department nearly stopped", "Nothing"], "correct_index": 2, "explanation": "O departamento quase parou."}, {"question": "How did she feel about the manager's praise?", "options": ["Like being congratulated on a flaw", "Indifferent", "Angry", "Very proud"], "correct_index": 0, "explanation": "Ela sentiu que era elogiada por um defeito."}, {"question": "What did she do afterwards?", "options": ["Changed departments", "Documented everything and trained others", "Quit", "Asked for a raise"], "correct_index": 1, "explanation": "Ela documentou e treinou os colegas."}, {"question": "What was an unexpected result?", "options": ["She was fired", "She became boss of everyone", "She moved abroad", "She was offered a role in strategy"], "correct_index": 3, "explanation": "Ela recebeu a oferta de um cargo em estratégia."}], "open_questions": [{"question": "Why do some people avoid sharing knowledge at work?", "key_points_pt": ["discutir segurança, poder e medo"]}, {"question": "What are the risks for a company that depends on one person?", "key_points_pt": ["citar continuidade, aprendizado, estresse"]}]}}, {"level": "C1", "genre": "corporate", "title": "The Silent Spreadsheet", "paragraphs": ["Adrián had suspected for some time that the numbers did not add up, but it was only on a quiet Sunday evening, alone in the office to finish a report, that he found the pattern. Three invoices, issued to different suppliers, shared the same bank account. None of them was large enough to trigger an audit, yet together they described a slow, methodical leak.", "He closed the file, and then reopened it, as if the figures might rearrange themselves into innocence. The name that kept appearing in the approvals column belonged to Ms. Vidal, the finance director who had hired him and who had once covered for him after a serious mistake. Gratitude and suspicion made an uncomfortable combination.", "For two days he said nothing, tormented by the question of whether loyalty to a person could outweigh loyalty to an institution. On Tuesday he asked for a private conversation with Ms. Vidal and, trying to keep his voice level, described exactly what he had found, without accusation.", "Her silence lasted so long that he heard the clock on the wall. Eventually she said, very quietly, that she had been waiting for someone to notice. It was not a confession of innocence, and Adrián did not pretend it was. But as he walked out, he understood that integrity was rarely a dramatic act; more often it was the unglamorous decision to speak."], "paragraphs_pt": ["Adrián suspeitava havia algum tempo de que os números não fechavam, mas foi só numa tranquila noite de domingo, sozinho no escritório para terminar um relatório, que encontrou o padrão. Três notas fiscais, emitidas a fornecedores diferentes, tinham a mesma conta bancária. Nenhuma era grande o bastante para disparar uma auditoria, mas juntas descreviam um vazamento lento e metódico.", "Ele fechou o arquivo e o reabriu, como se os números pudessem se rearranjar em inocência. O nome que continuava aparecendo na coluna de aprovações pertencia à Sra. Vidal, a diretora financeira que o contratara e que uma vez o protegera após um erro grave. Gratidão e suspeita formavam uma combinação desconfortável.", "Por dois dias não disse nada, atormentado pela pergunta de se a lealdade a uma pessoa podia pesar mais que a lealdade a uma instituição. Na terça pediu uma conversa privada com a Sra. Vidal e, tentando manter a voz firme, descreveu exatamente o que encontrara, sem acusação.", "O silêncio dela durou tanto que ele ouviu o relógio na parede. Por fim, disse bem baixinho que esperava que alguém percebesse. Não era uma confissão de inocência, e Adrián não fingiu que era. Mas ao sair, compreendeu que integridade raramente era um ato dramático; mais frequentemente era a decisão pouco glamourosa de falar."], "hard_words": ["audit", "methodical", "tormented", "integrity"], "vocab": [{"word": "invoices", "meaning": "notas fiscais", "note": ""}, {"word": "suppliers", "meaning": "fornecedores", "note": ""}, {"word": "audit", "meaning": "auditoria", "note": ""}, {"word": "methodical", "meaning": "metódico", "note": ""}, {"word": "approvals", "meaning": "aprovações", "note": ""}, {"word": "gratitude", "meaning": "gratidão", "note": ""}, {"word": "tormented", "meaning": "atormentado", "note": ""}, {"word": "outweigh", "meaning": "pesar mais que", "note": ""}, {"word": "confession", "meaning": "confissão", "note": ""}, {"word": "integrity", "meaning": "integridade", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been"], "irregular": ["had", "suspected", "did", "found", "issued", "shared", "described", "closed", "reopened", "might", "kept", "belonged", "hired", "covered", "made", "said", "tormented", "could", "asked", "lasted", "heard", "walked", "understood"], "phrasal": ["add up", "covered for", "walked out"], "wh": ["who", "what"], "connectors": ["and", "but", "so", "then", "after", "yet", "once", "if", "as"], "comparative": []}, "word_meanings": [{"word": "invoices", "meaning": "notas fiscais", "note": ""}, {"word": "suppliers", "meaning": "fornecedores", "note": ""}, {"word": "audit", "meaning": "auditoria", "note": ""}, {"word": "methodical", "meaning": "metódico", "note": ""}, {"word": "approvals", "meaning": "aprovações", "note": ""}, {"word": "gratitude", "meaning": "gratidão", "note": ""}, {"word": "tormented", "meaning": "atormentado", "note": ""}, {"word": "outweigh", "meaning": "pesar mais que", "note": ""}, {"word": "confession", "meaning": "confissão", "note": ""}, {"word": "integrity", "meaning": "integridade", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Adrián had suspected for some time' vem antes do domingo em que ele encontra o padrão."}, {"point": "Whether... could...", "explanation_pt": "'whether loyalty to a person could outweigh loyalty to an institution' introduz uma dúvida como substantivo."}], "multiple_choice": [{"question": "What did Adrián find?", "options": ["A fake email", "A lost contract", "A missing laptop", "Three invoices linked to the same bank account"], "correct_index": 3, "explanation": "Três notas fiscais tinham a mesma conta."}, {"question": "Who approved the invoices?", "options": ["The CEO", "A supplier", "A client", "Ms. Vidal"], "correct_index": 3, "explanation": "O nome dela aparecia na coluna de aprovações."}, {"question": "Why was Adrián conflicted?", "options": ["She was his friend from school", "She was his sister", "She paid him more", "She had helped him in the past"], "correct_index": 3, "explanation": "Ela o contratou e o protegeu antes."}, {"question": "How did he talk to Ms. Vidal?", "options": ["Through a lawyer", "In a public meeting", "Privately and without accusation", "By email"], "correct_index": 2, "explanation": "Ele conversou em particular, sem acusar."}, {"question": "What did Adrián conclude about integrity?", "options": ["It is often an unglamorous decision to speak", "It is always dramatic", "It is easy", "It is only for managers"], "correct_index": 0, "explanation": "Integridade é frequentemente a decisão de falar."}], "open_questions": [{"question": "Would you report a colleague who helped you in the past? Why?", "key_points_pt": ["defender uma decisão ética"]}, {"question": "How should companies protect people who report problems?", "key_points_pt": ["discutir confidencialidade e confiança"]}]}}, {"level": "C2", "genre": "corporate", "title": "The Anatomy of a Merger", "paragraphs": ["The announcement was delivered at an all-hands meeting by a CEO whose smile, Irene thought, had been rehearsed in front of a mirror. The company would be acquired by a larger competitor, a transaction described, in the carefully sterilised vocabulary of such occasions, as a \"strategic partnership.\" Employees were assured that their roles were \"central to the vision.\" No one believed a word of it, and everyone applauded.", "In the months that followed, Irene watched the organisation reshape itself with the same fascinated horror with which one observes a slow-motion accident. Meetings multiplied; titles were quietly adjusted; a consulting firm arrived with slides that spoke of \"synergies\" and \"rationalisation,\" terms whose function seemed to be to render redundancy abstract. Colleagues who had shared jokes for years began to measure their sentences.", "What unsettled her most was not the uncertainty but its effect on character. Generous people grew possessive of their projects; the cynical became strangely protective of the old culture they had once mocked. A manager she had admired for her candour started to deploy euphemisms, and Irene realised that fear did not reveal who people were so much as who they were prepared to become.", "When her own position was eliminated, the news arrived in an anticlimactically courteous email. She felt, to her surprise, less anger than a kind of clarity. She had spent a decade identifying with an institution that had never reciprocated, and the severance package, however generous, could not compensate for that miscalculation. She took the money, left the building without ceremony and began, for the first time in years, to think about what she wanted."], "paragraphs_pt": ["O anúncio foi feito numa reunião geral por um CEO cujo sorriso, pensou Irene, fora ensaiado diante do espelho. A empresa seria adquirida por um concorrente maior, uma transação descrita, no vocabulário cuidadosamente esterilizado dessas ocasiões, como uma \"parceria estratégica\". Os funcionários receberam a garantia de que seus cargos eram \"centrais para a visão.\" Ninguém acreditou numa palavra, e todos aplaudiram.", "Nos meses seguintes, Irene viu a organização se remodelar com o mesmo horror fascinado com que se observa um acidente em câmera lenta. As reuniões se multiplicaram; os cargos foram discretamente ajustados; uma consultoria chegou com slides que falavam de \"sinergias\" e \"racionalização\", termos cuja função parecia ser tornar a demissão abstrata. Colegas que dividiam piadas havia anos passaram a medir as frases.", "O que mais a inquietava não era a incerteza, mas seu efeito no caráter. Pessoas generosas ficaram possessivas com seus projetos; os cínicos tornaram-se estranhamente protetores da antiga cultura que antes zombavam. Uma gerente que ela admirava pela franqueza passou a usar eufemismos, e Irene percebeu que o medo não revelava quem as pessoas eram tanto quanto quem estavam dispostas a se tornar.", "Quando seu cargo foi eliminado, a notícia chegou num e-mail anticlimaticamente cortês. Ela sentiu, para sua surpresa, menos raiva do que uma espécie de clareza. Passara uma década se identificando com uma instituição que nunca retribuíra, e o pacote de indenização, por mais generoso que fosse, não compensava aquele erro de cálculo. Pegou o dinheiro, saiu do prédio sem cerimônia e começou, pela primeira vez em anos, a pensar no que queria."], "hard_words": ["sterilised", "redundancy", "euphemisms", "severance"], "vocab": [{"word": "acquired", "meaning": "adquirida", "note": ""}, {"word": "sterilised", "meaning": "esterilizado, neutro", "note": ""}, {"word": "synergies", "meaning": "sinergias", "note": ""}, {"word": "rationalisation", "meaning": "racionalização", "note": ""}, {"word": "redundancy", "meaning": "demissão por corte de cargos", "note": ""}, {"word": "candour", "meaning": "franqueza", "note": ""}, {"word": "euphemisms", "meaning": "eufemismos", "note": ""}, {"word": "reciprocated", "meaning": "retribuiu", "note": ""}, {"word": "severance", "meaning": "indenização por demissão", "note": ""}, {"word": "compensate", "meaning": "compensar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "be", "were"], "irregular": ["delivered", "thought", "had", "rehearsed", "would", "acquired", "described", "sterilised", "assured", "believed", "applauded", "followed", "watched", "fascinated", "multiplied", "adjusted", "arrived", "spoke", "seemed", "shared", "began", "unsettled", "grew", "became", "mocked", "admired", "started", "realised", "did", "prepared", "eliminated", "felt", "spent", "reciprocated", "could", "took", "left", "wanted"], "phrasal": ["reshape itself", "measure their sentences"], "wh": ["who", "what", "when", "which", "whose"], "connectors": ["and", "but", "however", "so", "when", "once", "as"], "comparative": []}, "word_meanings": [{"word": "acquired", "meaning": "adquirida", "note": ""}, {"word": "sterilised", "meaning": "esterilizado, neutro", "note": ""}, {"word": "synergies", "meaning": "sinergias", "note": ""}, {"word": "rationalisation", "meaning": "racionalização", "note": ""}, {"word": "redundancy", "meaning": "demissão por corte de cargos", "note": ""}, {"word": "candour", "meaning": "franqueza", "note": ""}, {"word": "euphemisms", "meaning": "eufemismos", "note": ""}, {"word": "reciprocated", "meaning": "retribuiu", "note": ""}, {"word": "severance", "meaning": "indenização por demissão", "note": ""}, {"word": "compensate", "meaning": "compensar", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had been rehearsed' e 'had spent a decade' indicam fatos anteriores ao momento da narração."}, {"point": "Not so much... as", "explanation_pt": "'did not reveal who people were so much as who they were prepared to become' compara duas ideias e destaca a segunda."}], "multiple_choice": [{"question": "How was the merger described?", "options": ["As a strategic partnership", "As a closing", "As a sale", "As a failure"], "correct_index": 0, "explanation": "Foi descrita como parceria estratégica."}, {"question": "What did employees do after the announcement?", "options": ["Applauded without believing", "Asked questions", "Protested", "Left the room"], "correct_index": 0, "explanation": "Ninguém acreditou, mas todos aplaudiram."}, {"question": "What unsettled Irene most?", "options": ["The consultants", "The effect of uncertainty on character", "The loss of money", "The new office"], "correct_index": 1, "explanation": "Ela se inquietava com o efeito no caráter."}, {"question": "How did she learn about her dismissal?", "options": ["From a friend", "In a courteous email", "By phone", "In a meeting"], "correct_index": 1, "explanation": "Recebeu um e-mail cortês."}, {"question": "How did she feel afterwards?", "options": ["Nothing", "A kind of clarity", "Embarrassment", "Great anger"], "correct_index": 1, "explanation": "Sentiu clareza, mais que raiva."}], "open_questions": [{"question": "Why does corporate language often hide the real meaning?", "key_points_pt": ["discutir eufemismos e poder"]}, {"question": "How would you handle the news of losing a job after many years?", "key_points_pt": ["refletir sobre emoções e planos"]}]}}, {"level": "C2", "genre": "corporate", "title": "Ambition Without Applause", "paragraphs": ["In an industry that prized visibility above almost everything else, Hana had cultivated a reputation for being quietly effective, a phrase her appraisals invariably used and her career invariably failed to reward. Colleagues who delivered half her results, but announced them twice as loudly, were promoted with a regularity that she found both baffling and, in her less charitable moments, insulting.", "She tried, once, to imitate them. She circulated long emails about her accomplishments and spoke more assertively in meetings, but the effort felt like wearing someone else's coat. It did not fit, and she suspected that everyone could see the seams. Worse, the exercise made her lose the enjoyment of the work itself, which had always been the real source of her motivation.", "It was a retired mentor, over a long and rather indulgent lunch, who offered a different perspective. Recognition, he said, was a currency issued by other people, and no one could force the mint to print more. What she could control was the quality of the problems she chose to solve and the people she chose to help. Reputation would follow, or it would not, but the work would still be hers.", "Hana did not undergo a spectacular transformation. She kept her habits, declined to join the performance, and found, slowly, that a few influential people had noticed anyway. When the offer finally came, it arrived without fanfare: a quiet email from a director who wanted her on a difficult project. She accepted, aware that she had not won anything so much as stopped asking for permission."], "paragraphs_pt": ["Numa indústria que valorizava a visibilidade acima de quase tudo, Hana cultivara a reputação de ser discretamente eficaz, expressão que suas avaliações invariavelmente usavam e que sua carreira invariavelmente deixava de recompensar. Colegas que entregavam metade dos resultados dela, mas os anunciavam duas vezes mais alto, eram promovidos com uma regularidade que ela achava desconcertante e, nos momentos menos caridosos, insultuosa.", "Tentou, uma vez, imitá-los. Circulou e-mails longos sobre suas conquistas e falou com mais assertividade nas reuniões, mas o esforço pareceu vestir o casaco de outra pessoa. Não servia, e ela suspeitava que todos viam as costuras. Pior, o exercício a fez perder o prazer do trabalho em si, que sempre fora a verdadeira fonte de sua motivação.", "Foi um mentor aposentado, num almoço longo e bastante indulgente, quem ofereceu outra perspectiva. Reconhecimento, disse, era uma moeda emitida por outras pessoas, e ninguém podia obrigar a casa da moeda a imprimir mais. O que ela podia controlar era a qualidade dos problemas que escolhia resolver e das pessoas que escolhia ajudar. A reputação viria, ou não, mas o trabalho continuaria sendo dela.", "Hana não passou por uma transformação espetacular. Manteve seus hábitos, recusou-se a participar da encenação e descobriu, devagar, que algumas pessoas influentes tinham notado de qualquer modo. Quando a oferta finalmente veio, chegou sem alarde: um e-mail discreto de uma diretora que a queria num projeto difícil. Ela aceitou, ciente de que não havia ganhado nada tanto quanto deixado de pedir permissão."], "hard_words": ["appraisals", "baffling", "seams", "fanfare"], "vocab": [{"word": "cultivated", "meaning": "cultivara", "note": ""}, {"word": "appraisals", "meaning": "avaliações de desempenho", "note": ""}, {"word": "baffling", "meaning": "desconcertante", "note": ""}, {"word": "assertively", "meaning": "com assertividade", "note": ""}, {"word": "seams", "meaning": "costuras", "note": ""}, {"word": "indulgent", "meaning": "indulgente, prazeroso", "note": ""}, {"word": "currency", "meaning": "moeda", "note": ""}, {"word": "mint", "meaning": "casa da moeda", "note": ""}, {"word": "fanfare", "meaning": "alarde", "note": ""}, {"word": "permission", "meaning": "permissão", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["being", "were", "been", "was", "be"], "irregular": ["prized", "had", "cultivated", "used", "failed", "delivered", "announced", "promoted", "found", "tried", "circulated", "spoke", "felt", "did", "suspected", "could", "made", "retired", "offered", "said", "issued", "chose", "would", "kept", "declined", "noticed", "came", "arrived", "wanted", "accepted", "won", "stopped"], "phrasal": ["stopped asking"], "wh": ["who", "what", "when", "which"], "connectors": ["and", "but", "so", "when", "or", "finally", "still", "once", "as"], "comparative": []}, "word_meanings": [{"word": "cultivated", "meaning": "cultivara", "note": ""}, {"word": "appraisals", "meaning": "avaliações de desempenho", "note": ""}, {"word": "baffling", "meaning": "desconcertante", "note": ""}, {"word": "assertively", "meaning": "com assertividade", "note": ""}, {"word": "seams", "meaning": "costuras", "note": ""}, {"word": "indulgent", "meaning": "indulgente, prazeroso", "note": ""}, {"word": "currency", "meaning": "moeda", "note": ""}, {"word": "mint", "meaning": "casa da moeda", "note": ""}, {"word": "fanfare", "meaning": "alarde", "note": ""}, {"word": "permission", "meaning": "permissão", "note": ""}], "exercises": {"grammar": [{"point": "Relative clauses e past perfect", "explanation_pt": "'Colleagues who delivered half her results' identifica quais colegas; 'had cultivated' mostra algo anterior."}, {"point": "Not so much... as", "explanation_pt": "'had not won anything so much as stopped asking' compara e destaca a segunda ideia."}], "multiple_choice": [{"question": "What did Hana's appraisals say about her?", "options": ["She was new", "She was lazy", "She was quietly effective", "She was loud"], "correct_index": 2, "explanation": "As avaliações a descreviam como discretamente eficaz."}, {"question": "Why was she baffled?", "options": ["She was never paid", "She had no tasks", "The office was far", "Colleagues with fewer results were promoted"], "correct_index": 3, "explanation": "Colegas que entregavam menos eram promovidos."}, {"question": "What happened when she tried to imitate them?", "options": ["She became famous", "It felt like wearing someone else's coat", "She was promoted", "She was fired"], "correct_index": 1, "explanation": "Foi como vestir o casaco de outra pessoa."}, {"question": "What did the mentor say about recognition?", "options": ["It is always fair", "It is useless", "It is the only goal", "It is a currency issued by other people"], "correct_index": 3, "explanation": "Reconhecimento é uma moeda emitida pelos outros."}, {"question": "How did the offer finally arrive?", "options": ["On television", "By letter", "Without fanfare, in a quiet email", "In a big ceremony"], "correct_index": 2, "explanation": "Chegou por um e-mail discreto."}], "open_questions": [{"question": "Should hard work be enough to be recognised? Why or why not?", "key_points_pt": ["discutir visibilidade e mérito"]}, {"question": "How do you stay motivated when nobody notices your work?", "key_points_pt": ["citar motivação interna"]}]}}, {"level": "A1", "genre": "detective", "title": "Who Took the Cake?", "paragraphs": ["Detective Bruno is at a house. There is a problem. The birthday cake is not on the table.", "\"Who took the cake?\" he asks. He looks at the floor. There are small brown marks. They go to the garden.", "In the garden, Bruno sees the dog, Rex. Rex has chocolate on his nose. \"It was you, Rex!\" says Bruno. Rex is happy, but the family is not."], "paragraphs_pt": ["O detetive Bruno está numa casa. Há um problema. O bolo de aniversário não está na mesa.", "\"Quem pegou o bolo?\", ele pergunta. Olha para o chão. Há pequenas marcas marrons. Elas vão até o jardim.", "No jardim, Bruno vê o cachorro, Rex. Rex tem chocolate no nariz. \"Foi você, Rex!\", diz Bruno. Rex está feliz, mas a família não está."], "hard_words": ["detective", "marks", "garden", "nose"], "vocab": [{"word": "detective", "meaning": "detetive", "note": ""}, {"word": "problem", "meaning": "problema", "note": ""}, {"word": "birthday cake", "meaning": "bolo de aniversário", "note": ""}, {"word": "floor", "meaning": "chão", "note": ""}, {"word": "marks", "meaning": "marcas", "note": ""}, {"word": "garden", "meaning": "jardim", "note": ""}, {"word": "dog", "meaning": "cachorro", "note": ""}, {"word": "nose", "meaning": "nariz", "note": ""}, {"word": "family", "meaning": "família", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are", "was"], "irregular": ["took"], "phrasal": [], "wh": ["who"], "connectors": ["but"], "comparative": []}, "word_meanings": [{"word": "detective", "meaning": "detetive", "note": ""}, {"word": "problem", "meaning": "problema", "note": ""}, {"word": "birthday cake", "meaning": "bolo de aniversário", "note": ""}, {"word": "floor", "meaning": "chão", "note": ""}, {"word": "marks", "meaning": "marcas", "note": ""}, {"word": "garden", "meaning": "jardim", "note": ""}, {"word": "dog", "meaning": "cachorro", "note": ""}, {"word": "nose", "meaning": "nariz", "note": ""}, {"word": "family", "meaning": "família", "note": ""}], "exercises": {"grammar": [{"point": "There is / There are", "explanation_pt": "'There is a problem' e 'There are small marks' mostram o que existe: singular com 'is', plural com 'are'."}], "multiple_choice": [{"question": "What is missing?", "options": ["A book", "The birthday cake", "A phone", "A hat"], "correct_index": 1, "explanation": "O bolo de aniversário sumiu."}, {"question": "What does Bruno see on the floor?", "options": ["Small brown marks", "A key", "A letter", "Water"], "correct_index": 0, "explanation": "Ele vê pequenas marcas marrons."}, {"question": "Where do the marks go?", "options": ["To the garden", "To the kitchen", "To the bedroom", "To the street"], "correct_index": 0, "explanation": "As marcas vão até o jardim."}, {"question": "Who took the cake?", "options": ["Bruno", "The mother", "The cat", "The dog"], "correct_index": 3, "explanation": "Foi o cachorro, Rex."}, {"question": "What does Rex have on his nose?", "options": ["Paint", "Chocolate", "Water", "Flowers"], "correct_index": 1, "explanation": "Rex tem chocolate no nariz."}], "open_questions": [{"question": "Do you have a pet? What is it like?", "key_points_pt": ["descrever um animal usando frases simples"]}, {"question": "Who do you think takes food at home?", "key_points_pt": ["brincar com suspeitos", "usar 'I think'"]}]}}, {"level": "A1", "genre": "detective", "title": "The Lost Bag", "paragraphs": ["Mia is at the train station. She has no bag! It is a red bag with her phone and her keys. She is worried.", "A police officer asks, \"Where is your bag now?\" Mia says, \"I do not know.\" The officer looks at the cameras. He sees Mia with the bag at the café.", "They go to the café. The red bag is under a chair. \"Thank you!\" says Mia. She is happy again."], "paragraphs_pt": ["Mia está na estação de trem. Ela não tem a bolsa! É uma bolsa vermelha com o celular e as chaves dela. Ela está preocupada.", "Um policial pergunta: \"Onde está sua bolsa agora?\" Mia diz: \"Eu não sei.\" O policial olha as câmeras. Ele vê Mia com a bolsa no café.", "Eles vão ao café. A bolsa vermelha está embaixo de uma cadeira. \"Obrigada!\", diz Mia. Ela está feliz de novo."], "hard_words": ["station", "worried", "officer", "chair"], "vocab": [{"word": "train station", "meaning": "estação de trem", "note": ""}, {"word": "station", "meaning": "estação", "note": ""}, {"word": "bag", "meaning": "bolsa", "note": ""}, {"word": "phone", "meaning": "celular", "note": ""}, {"word": "keys", "meaning": "chaves", "note": ""}, {"word": "worried", "meaning": "preocupada", "note": ""}, {"word": "police officer", "meaning": "policial", "note": ""}, {"word": "officer", "meaning": "policial", "note": ""}, {"word": "cameras", "meaning": "câmeras", "note": ""}, {"word": "café", "meaning": "café", "note": ""}, {"word": "chair", "meaning": "cadeira", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": ["worried"], "phrasal": [], "wh": ["where"], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "train station", "meaning": "estação de trem", "note": ""}, {"word": "station", "meaning": "estação", "note": ""}, {"word": "bag", "meaning": "bolsa", "note": ""}, {"word": "phone", "meaning": "celular", "note": ""}, {"word": "keys", "meaning": "chaves", "note": ""}, {"word": "worried", "meaning": "preocupada", "note": ""}, {"word": "police officer", "meaning": "policial", "note": ""}, {"word": "officer", "meaning": "policial", "note": ""}, {"word": "cameras", "meaning": "câmeras", "note": ""}, {"word": "café", "meaning": "café", "note": ""}, {"word": "chair", "meaning": "cadeira", "note": ""}], "exercises": {"grammar": [{"point": "Where + to be", "explanation_pt": "'Where is your bag?' pergunta sobre lugar. Respondemos com preposições: 'under a chair', 'at the café'."}], "multiple_choice": [{"question": "Where is Mia at the start?", "options": ["At the beach", "At the train station", "At a hotel", "At school"], "correct_index": 1, "explanation": "Ela está na estação de trem."}, {"question": "What color is the bag?", "options": ["Black", "Green", "Red", "Blue"], "correct_index": 2, "explanation": "A bolsa é vermelha."}, {"question": "What is inside the bag?", "options": ["Food", "Money only", "A phone and keys", "Books"], "correct_index": 2, "explanation": "Há celular e chaves."}, {"question": "What does the officer look at?", "options": ["A book", "The cameras", "A map", "A letter"], "correct_index": 1, "explanation": "Ele olha as câmeras."}, {"question": "Where is the bag?", "options": ["At home", "On the train", "In a car", "Under a chair at the café"], "correct_index": 3, "explanation": "A bolsa está embaixo de uma cadeira no café."}], "open_questions": [{"question": "Do you lose things? What do you lose?", "key_points_pt": ["usar passado simples e vocabulário de objetos"]}, {"question": "Where do you keep your phone?", "key_points_pt": ["descrever lugares usando preposições"]}]}}, {"level": "A1", "genre": "detective", "title": "The Strange Noise", "paragraphs": ["It is night. Tom hears a noise in the kitchen. \"Who is there?\" he says. No one answers. He is afraid, but he takes a flashlight.", "Tom goes to the kitchen and opens the door. He looks around. The window is open. A small gray cat is on the table.", "\"Meow!\" says the cat. Tom laughs. \"You are the thief!\" He gives the cat some milk and closes the window. Then he goes back to bed."], "paragraphs_pt": ["É noite. Tom ouve um barulho na cozinha. \"Quem está aí?\", ele diz. Ninguém responde. Ele está com medo, mas pega uma lanterna.", "Tom vai à cozinha e abre a porta. Olha em volta. A janela está aberta. Um pequeno gato cinza está sobre a mesa.", "\"Miau!\", diz o gato. Tom ri. \"Você é o ladrão!\" Ele dá um pouco de leite ao gato e fecha a janela. Depois volta para a cama."], "hard_words": ["noise", "afraid", "flashlight", "thief"], "vocab": [{"word": "noise", "meaning": "barulho", "note": ""}, {"word": "kitchen", "meaning": "cozinha", "note": ""}, {"word": "afraid", "meaning": "com medo", "note": ""}, {"word": "flashlight", "meaning": "lanterna", "note": ""}, {"word": "window", "meaning": "janela", "note": ""}, {"word": "gray", "meaning": "cinza", "note": ""}, {"word": "table", "meaning": "mesa", "note": ""}, {"word": "thief", "meaning": "ladrão", "note": ""}, {"word": "milk", "meaning": "leite", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": ["who"], "connectors": ["and", "but", "then"], "comparative": []}, "word_meanings": [{"word": "noise", "meaning": "barulho", "note": ""}, {"word": "kitchen", "meaning": "cozinha", "note": ""}, {"word": "afraid", "meaning": "com medo", "note": ""}, {"word": "flashlight", "meaning": "lanterna", "note": ""}, {"word": "window", "meaning": "janela", "note": ""}, {"word": "gray", "meaning": "cinza", "note": ""}, {"word": "table", "meaning": "mesa", "note": ""}, {"word": "thief", "meaning": "ladrão", "note": ""}, {"word": "milk", "meaning": "leite", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "Para contar fatos e ações em sequência no presente: 'Tom hears', 'He opens', 'He looks'. Com he/she/it o verbo ganha -s."}], "multiple_choice": [{"question": "When does the story happen?", "options": ["In the morning", "At night", "At noon", "In the evening"], "correct_index": 1, "explanation": "A história acontece à noite."}, {"question": "Where does Tom hear the noise?", "options": ["In the garden", "In the kitchen", "In the bathroom", "In the street"], "correct_index": 1, "explanation": "Ele ouve o barulho na cozinha."}, {"question": "What does Tom take?", "options": ["A phone", "A flashlight", "A bag", "A knife"], "correct_index": 1, "explanation": "Ele pega uma lanterna."}, {"question": "What is on the table?", "options": ["A gray cat", "A dog", "A key", "A bird"], "correct_index": 0, "explanation": "Há um pequeno gato cinza."}, {"question": "What does Tom give the cat?", "options": ["Bread", "Some milk", "Fish", "Water"], "correct_index": 1, "explanation": "Ele dá leite ao gato."}], "open_questions": [{"question": "Are you afraid of noises at night? Why?", "key_points_pt": ["falar de medo", "usar 'I am afraid of'"]}, {"question": "What can make a noise in a house at night?", "key_points_pt": ["citar causas como vento, animais, objetos"]}]}}, {"level": "A2", "genre": "detective", "title": "The Missing Bicycle", "paragraphs": ["On Saturday morning, Daniel went to the garage and saw that his bicycle was not there. He was sure that he had locked it the night before. Worried and angry, he called his neighbor, Inspector Lopes, who was a retired detective.", "Inspector Lopes arrived in ten minutes. He walked around the garage slowly and looked at the ground. \"Look,\" he said. \"The door is not broken. Somebody opened it with a key.\" Daniel remembered that only three people had a key: his mother, his sister and his friend Hugo.", "They talked to each one. His mother was at the market, and his sister was at school. Hugo, however, looked nervous and did not want to answer. Finally, he said, \"I am sorry. I borrowed the bicycle because mine was broken. I wanted to ask you, but you were asleep.\" Daniel was a little angry, but he laughed. \"Next time, just send me a message,\" he said."], "paragraphs_pt": ["No sábado de manhã, Daniel foi à garagem e viu que sua bicicleta não estava lá. Ele tinha certeza de que a trancara na noite anterior. Preocupado e com raiva, ligou para o vizinho, o inspetor Lopes, que era um detetive aposentado.", "O inspetor Lopes chegou em dez minutos. Andou devagar pela garagem e olhou o chão. \"Olhe\", disse. \"A porta não está arrombada. Alguém a abriu com uma chave.\" Daniel lembrou que só três pessoas tinham uma chave: a mãe, a irmã e o amigo Hugo.", "Conversaram com cada um. A mãe estava no mercado e a irmã estava na escola. Hugo, porém, parecia nervoso e não quis responder. Por fim, disse: \"Desculpe. Peguei a bicicleta emprestada porque a minha estava quebrada. Queria te pedir, mas você estava dormindo.\" Daniel ficou um pouco bravo, mas riu. \"Da próxima vez, só mande uma mensagem\", disse."], "hard_words": ["garage", "locked", "retired", "borrowed"], "vocab": [{"word": "garage", "meaning": "garagem", "note": ""}, {"word": "locked", "meaning": "trancou", "note": ""}, {"word": "neighbor", "meaning": "vizinho", "note": ""}, {"word": "retired", "meaning": "aposentado", "note": ""}, {"word": "broken", "meaning": "arrombada, quebrada", "note": ""}, {"word": "key", "meaning": "chave", "note": ""}, {"word": "borrowed", "meaning": "pegou emprestado", "note": ""}, {"word": "nervous", "meaning": "nervoso", "note": ""}, {"word": "asleep", "meaning": "dormindo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is", "am", "were"], "irregular": ["went", "saw", "had", "locked", "worried", "called", "retired", "arrived", "walked", "looked", "ground", "said", "broken", "opened", "remembered", "talked", "did", "borrowed", "wanted", "laughed"], "phrasal": ["walked around"], "wh": ["who"], "connectors": ["and", "but", "however", "because", "before", "finally"], "comparative": []}, "word_meanings": [{"word": "garage", "meaning": "garagem", "note": ""}, {"word": "locked", "meaning": "trancou", "note": ""}, {"word": "neighbor", "meaning": "vizinho", "note": ""}, {"word": "retired", "meaning": "aposentado", "note": ""}, {"word": "broken", "meaning": "arrombada, quebrada", "note": ""}, {"word": "key", "meaning": "chave", "note": ""}, {"word": "borrowed", "meaning": "pegou emprestado", "note": ""}, {"word": "nervous", "meaning": "nervoso", "note": ""}, {"word": "asleep", "meaning": "dormindo", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'went', 'saw', 'called' mostram ações terminadas. Muitos verbos são irregulares: go → went, see → saw."}, {"point": "Only + número", "explanation_pt": "'only three people had a key' limita a quantidade."}], "multiple_choice": [{"question": "What was missing on Saturday?", "options": ["Daniel's bag", "Daniel's bicycle", "Daniel's dog", "Daniel's phone"], "correct_index": 1, "explanation": "A bicicleta de Daniel sumiu."}, {"question": "Who is Inspector Lopes?", "options": ["A police chief", "Daniel's teacher", "A retired detective and neighbor", "Daniel's uncle"], "correct_index": 2, "explanation": "Ele é um detetive aposentado e vizinho."}, {"question": "What did the inspector notice about the door?", "options": ["It was open", "It was red", "It was new", "It was not broken"], "correct_index": 3, "explanation": "A porta não estava arrombada."}, {"question": "How many people had a key?", "options": ["One", "Five", "Ten", "Three"], "correct_index": 3, "explanation": "Só três pessoas tinham chave."}, {"question": "Why did Hugo take the bicycle?", "options": ["He wanted to sell it", "He was angry", "He was lost", "His own bicycle was broken"], "correct_index": 3, "explanation": "A bicicleta dele estava quebrada."}], "open_questions": [{"question": "Have you ever borrowed something without asking?", "key_points_pt": ["contar uma experiência", "usar passado"]}, {"question": "What do you do when something goes missing?", "key_points_pt": ["citar passos como procurar e perguntar"]}]}}, {"level": "A2", "genre": "detective", "title": "The Café Thief", "paragraphs": ["Every afternoon at the Blue Café, a customer lost something: a wallet on Monday, sunglasses on Tuesday and a phone on Wednesday. The owner, Mrs. Silva, was tired of the problem and called Detective Ana.", "Ana sat in a corner with a cup of tea and watched everyone. On Thursday she noticed a man in a gray coat. He always sat near the door and looked at people's bags, not at his coffee. When a woman went to the toilet, he stood up and walked slowly toward her table.", "Ana followed him and said, \"Excuse me, sir. That bag is not yours.\" The man tried to run, but a waiter stopped him at the door. The police arrived five minutes later. Mrs. Silva was very happy, and Ana received a free cake for a year."], "paragraphs_pt": ["Toda tarde no Blue Café, um cliente perdia alguma coisa: uma carteira na segunda, óculos de sol na terça e um celular na quarta. A dona, a Sra. Silva, estava cansada do problema e chamou a detetive Ana.", "Ana sentou num canto com uma xícara de chá e observou todos. Na quinta ela notou um homem de casaco cinza. Ele sempre sentava perto da porta e olhava as bolsas das pessoas, não o café. Quando uma mulher foi ao banheiro, ele se levantou e andou devagar até a mesa dela.", "Ana o seguiu e disse: \"Com licença, senhor. Essa bolsa não é sua.\" O homem tentou correr, mas um garçom o impediu na porta. A polícia chegou cinco minutos depois. A Sra. Silva ficou muito feliz, e Ana ganhou um bolo grátis por um ano."], "hard_words": ["wallet", "owner", "noticed", "waiter"], "vocab": [{"word": "wallet", "meaning": "carteira", "note": ""}, {"word": "sunglasses", "meaning": "óculos de sol", "note": ""}, {"word": "owner", "meaning": "dona, proprietária", "note": ""}, {"word": "corner", "meaning": "canto", "note": ""}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "coat", "meaning": "casaco", "note": ""}, {"word": "stood up", "meaning": "levantou-se", "note": ""}, {"word": "followed", "meaning": "seguiu", "note": ""}, {"word": "waiter", "meaning": "garçom", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is"], "irregular": ["lost", "tired", "called", "sat", "watched", "noticed", "looked", "went", "stood", "walked", "followed", "said", "tried", "stopped", "arrived", "received"], "phrasal": ["stood up", "sat in"], "wh": ["when"], "connectors": ["and", "but", "when"], "comparative": []}, "word_meanings": [{"word": "wallet", "meaning": "carteira", "note": ""}, {"word": "sunglasses", "meaning": "óculos de sol", "note": ""}, {"word": "owner", "meaning": "dona, proprietária", "note": ""}, {"word": "corner", "meaning": "canto", "note": ""}, {"word": "noticed", "meaning": "notou", "note": ""}, {"word": "coat", "meaning": "casaco", "note": ""}, {"word": "stood up", "meaning": "levantou-se", "note": ""}, {"word": "followed", "meaning": "seguiu", "note": ""}, {"word": "waiter", "meaning": "garçom", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'lost', 'sat', 'noticed' mostram ações passadas. Os verbos irregulares mudam de forma: sit → sat, stand → stood."}, {"point": "Always e posição", "explanation_pt": "'always sat near the door' mostra um hábito do homem."}], "multiple_choice": [{"question": "What happened every afternoon at the café?", "options": ["There was a party", "The café closed", "A customer lost something", "The cook was ill"], "correct_index": 2, "explanation": "Todo dia um cliente perdia algo."}, {"question": "Who did Mrs. Silva call?", "options": ["The police", "Her son", "Detective Ana", "A waiter"], "correct_index": 2, "explanation": "Ela chamou a detetive Ana."}, {"question": "What did the man in the gray coat look at?", "options": ["His coffee", "The clock", "People's bags", "The menu"], "correct_index": 2, "explanation": "Ele olhava as bolsas."}, {"question": "Who stopped the man at the door?", "options": ["A waiter", "Ana", "Mrs. Silva", "A woman"], "correct_index": 0, "explanation": "Um garçom o impediu na porta."}, {"question": "What did Ana receive?", "options": ["A medal", "A job", "A free cake for a year", "Money"], "correct_index": 2, "explanation": "Ela ganhou um bolo grátis por um ano."}], "open_questions": [{"question": "How can people protect their things in public places?", "key_points_pt": ["dar dicas de segurança"]}, {"question": "Would you like to be a detective? Why?", "key_points_pt": ["dar opinião com motivos"]}]}}, {"level": "A2", "genre": "detective", "title": "The Strange Letter", "paragraphs": ["Laura found a strange letter in her mailbox. There was no name on the envelope. Inside, there was only one sentence: \"Look behind the old clock.\" She was curious, so she called her brother Marco.", "They went to the living room together. The old clock was on the wall, and behind it there was a small key taped to the wood. \"What does this key open?\" asked Marco. They searched the house for an hour. Finally, they found a small box in the attic with a lock that fit the key.", "Inside the box, there was a photograph of their grandfather as a young man and a note: \"Happy birthday, Laura. I hid this gift many years ago.\" Laura smiled. Her grandfather loved mysteries, and he had planned one more surprise for her."], "paragraphs_pt": ["Laura encontrou uma carta estranha na caixa de correio. Não havia nome no envelope. Dentro, havia só uma frase: \"Olhe atrás do relógio antigo.\" Ela ficou curiosa e ligou para o irmão, Marco.", "Foram juntos à sala. O relógio antigo estava na parede e, atrás dele, havia uma chavinha presa com fita na madeira. \"O que essa chave abre?\", perguntou Marco. Procuraram pela casa por uma hora. Finalmente acharam uma caixinha no sótão com uma fechadura que encaixava na chave.", "Dentro da caixa havia uma fotografia do avô deles quando jovem e um bilhete: \"Feliz aniversário, Laura. Escondi este presente há muitos anos.\" Laura sorriu. O avô adorava mistérios e planejara mais uma surpresa para ela."], "hard_words": ["envelope", "curious", "attic", "lock"], "vocab": [{"word": "mailbox", "meaning": "caixa de correio", "note": ""}, {"word": "envelope", "meaning": "envelope", "note": ""}, {"word": "curious", "meaning": "curiosa", "note": ""}, {"word": "clock", "meaning": "relógio de parede", "note": ""}, {"word": "taped", "meaning": "preso com fita", "note": ""}, {"word": "attic", "meaning": "sótão", "note": ""}, {"word": "lock", "meaning": "fechadura", "note": ""}, {"word": "fit", "meaning": "encaixar", "note": ""}, {"word": "hid", "meaning": "escondeu", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["found", "called", "went", "taped", "asked", "searched", "hid", "smiled", "loved", "had", "planned"], "phrasal": [], "wh": ["what"], "connectors": ["and", "so", "finally", "as"], "comparative": []}, "word_meanings": [{"word": "mailbox", "meaning": "caixa de correio", "note": ""}, {"word": "envelope", "meaning": "envelope", "note": ""}, {"word": "curious", "meaning": "curiosa", "note": ""}, {"word": "clock", "meaning": "relógio de parede", "note": ""}, {"word": "taped", "meaning": "preso com fita", "note": ""}, {"word": "attic", "meaning": "sótão", "note": ""}, {"word": "lock", "meaning": "fechadura", "note": ""}, {"word": "fit", "meaning": "encaixar", "note": ""}, {"word": "hid", "meaning": "escondeu", "note": ""}], "exercises": {"grammar": [{"point": "There was / There were", "explanation_pt": "'There was no name' e 'There was a small key' descrevem o que existia no passado."}, {"point": "Past perfect simples de contexto", "explanation_pt": "'he had planned one more surprise' mostra um plano anterior ao momento em que ela abre a caixa."}], "multiple_choice": [{"question": "What did Laura find in her mailbox?", "options": ["A gift", "A photograph", "A strange letter", "A bill"], "correct_index": 2, "explanation": "Ela achou uma carta estranha."}, {"question": "What did the sentence say?", "options": ["Go to the park", "Open the door", "Look behind the old clock", "Call me"], "correct_index": 2, "explanation": "Dizia para olhar atrás do relógio antigo."}, {"question": "What was behind the clock?", "options": ["A small key", "A coin", "A map", "A ring"], "correct_index": 0, "explanation": "Havia uma chave pequena."}, {"question": "Where did they find the box?", "options": ["In the attic", "In the kitchen", "In the garage", "In the garden"], "correct_index": 0, "explanation": "Eles acharam a caixa no sótão."}, {"question": "Who left the surprise?", "options": ["Their teacher", "A neighbor", "A stranger", "Their grandfather"], "correct_index": 3, "explanation": "Foi o avô deles."}], "open_questions": [{"question": "Do you like mysteries or surprises? Why?", "key_points_pt": ["dar opinião"]}, {"question": "What would you hide in a box for a family member?", "key_points_pt": ["descrever um presente", "usar 'I would'"]}]}}, {"level": "B1", "genre": "detective", "title": "The Empty Seat at Table Six", "paragraphs": ["Detective Okoye had been in the restaurant for only five minutes when the owner rushed to her table, pale and sweating. A wealthy customer, Mr. Falk, had disappeared from table six between the main course and dessert. His jacket was still on the chair, and his phone was ringing in his pocket.", "Okoye examined the scene. The chair was pushed back as if he had left in a hurry, and a glass of red wine was half full. One detail bothered her: Mr. Falk's napkin was folded neatly beside the plate, and people who leave in a panic rarely fold their napkins.", "She asked the waiters what they had seen. One of them remembered that a woman in a green dress had approached the table and whispered something into Mr. Falk's ear. A moment later, they had both walked toward the back door.", "Okoye followed the same route and found them in the courtyard, talking quietly. The woman was Mr. Falk's daughter, and she had come to tell him that his wife was in the hospital. There was no crime after all. Okoye apologized for the trouble, but privately she was pleased: the folded napkin had told her the truth."], "paragraphs_pt": ["A detetive Okoye estava no restaurante havia apenas cinco minutos quando o dono correu até a mesa dela, pálido e suando. Um cliente rico, o Sr. Falk, havia desaparecido da mesa seis entre o prato principal e a sobremesa. O paletó ainda estava na cadeira, e o celular tocava no bolso.", "Okoye examinou a cena. A cadeira estava empurrada para trás, como se ele tivesse saído com pressa, e uma taça de vinho tinto estava pela metade. Um detalhe a incomodava: o guardanapo do Sr. Falk estava dobrado com cuidado ao lado do prato, e quem sai em pânico raramente dobra o guardanapo.", "Ela perguntou aos garçons o que haviam visto. Um deles lembrou que uma mulher de vestido verde se aproximara da mesa e sussurrara algo no ouvido do Sr. Falk. Um momento depois, os dois tinham caminhado em direção à porta dos fundos.", "Okoye seguiu o mesmo caminho e os encontrou no pátio, conversando baixinho. A mulher era a filha do Sr. Falk e viera avisá-lo de que a esposa dele estava no hospital. Afinal, não havia crime. Okoye pediu desculpas pelo incômodo, mas em segredo ficou satisfeita: o guardanapo dobrado lhe dissera a verdade."], "hard_words": ["wealthy", "napkin", "whispered", "courtyard"], "vocab": [{"word": "wealthy", "meaning": "rico", "note": ""}, {"word": "disappeared", "meaning": "desapareceu", "note": ""}, {"word": "main course", "meaning": "prato principal", "note": ""}, {"word": "examined", "meaning": "examinou", "note": ""}, {"word": "bothered", "meaning": "incomodava", "note": ""}, {"word": "napkin", "meaning": "guardanapo", "note": ""}, {"word": "whispered", "meaning": "sussurrou", "note": ""}, {"word": "courtyard", "meaning": "pátio", "note": ""}, {"word": "apologized", "meaning": "pediu desculpas", "note": ""}, {"word": "privately", "meaning": "em segredo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was"], "irregular": ["had", "rushed", "disappeared", "examined", "pushed", "left", "bothered", "folded", "asked", "seen", "remembered", "approached", "whispered", "walked", "followed", "found", "apologized", "pleased", "told"], "phrasal": ["rushed to", "walked toward"], "wh": ["who", "what", "when"], "connectors": ["and", "but", "after", "when", "still", "if", "as"], "comparative": []}, "word_meanings": [{"word": "wealthy", "meaning": "rico", "note": ""}, {"word": "disappeared", "meaning": "desapareceu", "note": ""}, {"word": "main course", "meaning": "prato principal", "note": ""}, {"word": "examined", "meaning": "examinou", "note": ""}, {"word": "bothered", "meaning": "incomodava", "note": ""}, {"word": "napkin", "meaning": "guardanapo", "note": ""}, {"word": "whispered", "meaning": "sussurrou", "note": ""}, {"word": "courtyard", "meaning": "pátio", "note": ""}, {"word": "apologized", "meaning": "pediu desculpas", "note": ""}, {"word": "privately", "meaning": "em segredo", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'A customer had disappeared' mostra algo anterior à chegada da detetive à mesa."}, {"point": "Reported speech", "explanation_pt": "'She asked the waiters what they had seen' mostra uma pergunta indireta no passado."}], "multiple_choice": [{"question": "Who disappeared?", "options": ["A woman in green", "The owner", "A waiter", "Mr. Falk"], "correct_index": 3, "explanation": "O Sr. Falk sumiu da mesa seis."}, {"question": "What was strange about the table?", "options": ["The chair was broken", "The napkin was folded neatly", "The glass was empty", "The phone was missing"], "correct_index": 1, "explanation": "O guardanapo estava dobrado com cuidado."}, {"question": "What did a waiter remember?", "options": ["A woman whispered to Mr. Falk", "A loud noise", "A fire", "A fight"], "correct_index": 0, "explanation": "Uma mulher sussurrou algo ao ouvido dele."}, {"question": "Who was the woman?", "options": ["His daughter", "A waitress", "A thief", "His wife"], "correct_index": 0, "explanation": "Era a filha dele."}, {"question": "Was there a crime?", "options": ["Yes, a robbery", "No, his wife was in the hospital", "Yes, a kidnapping", "Yes, a fraud"], "correct_index": 1, "explanation": "Não havia crime; a esposa estava no hospital."}], "open_questions": [{"question": "Why are small details important for a detective?", "key_points_pt": ["explicar observação e raciocínio"]}, {"question": "Have you ever suspected something that turned out to be innocent?", "key_points_pt": ["contar uma experiência"]}]}}, {"level": "B1", "genre": "detective", "title": "The Gallery's Missing Light", "paragraphs": ["When the lights in the Alvarez Gallery went out for exactly four minutes during the Friday exhibition, nobody was injured, and nothing seemed to be missing. Yet the security manager insisted on calling a private investigator, a quiet man named Pedro, because he had the uneasy feeling that something was wrong.", "Pedro spent the evening examining the building. He learned that the blackout had affected only the east room, where an expensive sculpture was displayed. He also noticed that a small camera in the corner had been turned toward the wall, though nobody remembered touching it.", "Late at night, Pedro looked at the sculpture closely and realized that it was slightly lighter than the photographs in the catalogue. It was a copy. Somebody had used the four minutes of darkness to replace the original.", "The next morning, security video from the street showed a delivery van leaving the back door at 9:07 p.m. Pedro called the police and gave them the license plate. By Sunday, the original sculpture was back in the gallery, and the thieves were in jail, though the manager never found out how they had planned everything so carefully."], "paragraphs_pt": ["Quando as luzes da Galeria Alvarez se apagaram por exatamente quatro minutos durante a exposição de sexta-feira, ninguém se feriu e nada parecia faltar. Mesmo assim, o gerente de segurança insistiu em chamar um investigador particular, um homem calado chamado Pedro, porque tinha a sensação inquieta de que algo estava errado.", "Pedro passou a noite examinando o prédio. Descobriu que o apagão afetara apenas a sala leste, onde uma escultura cara estava exposta. Também notou que uma pequena câmera no canto fora virada para a parede, embora ninguém se lembrasse de tê-la tocado.", "Tarde da noite, Pedro olhou a escultura de perto e percebeu que ela era um pouco mais clara que as fotografias do catálogo. Era uma cópia. Alguém usara os quatro minutos de escuridão para trocar a original.", "Na manhã seguinte, o vídeo de segurança da rua mostrou uma van de entregas saindo pela porta dos fundos às 21h07. Pedro chamou a polícia e deu a placa. No domingo, a escultura original estava de volta à galeria e os ladrões estavam na cadeia, embora o gerente nunca tenha descoberto como eles planejaram tudo com tanto cuidado."], "hard_words": ["blackout", "sculpture", "replace", "uneasy"], "vocab": [{"word": "exhibition", "meaning": "exposição", "note": ""}, {"word": "injured", "meaning": "ferido", "note": ""}, {"word": "private investigator", "meaning": "investigador particular", "note": ""}, {"word": "uneasy", "meaning": "inquieto", "note": ""}, {"word": "blackout", "meaning": "apagão", "note": ""}, {"word": "sculpture", "meaning": "escultura", "note": ""}, {"word": "displayed", "meaning": "exposta", "note": ""}, {"word": "catalogue", "meaning": "catálogo", "note": ""}, {"word": "replace", "meaning": "substituir", "note": ""}, {"word": "license plate", "meaning": "placa de carro", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "been", "were"], "irregular": ["went", "injured", "seemed", "insisted", "named", "had", "spent", "learned", "affected", "displayed", "noticed", "turned", "remembered", "looked", "realized", "used", "showed", "called", "gave", "found", "planned"], "phrasal": ["went out", "found out"], "wh": ["where", "when", "how"], "connectors": ["and", "because", "so", "though", "when", "yet", "also"], "comparative": []}, "word_meanings": [{"word": "exhibition", "meaning": "exposição", "note": ""}, {"word": "injured", "meaning": "ferido", "note": ""}, {"word": "private investigator", "meaning": "investigador particular", "note": ""}, {"word": "uneasy", "meaning": "inquieto", "note": ""}, {"word": "blackout", "meaning": "apagão", "note": ""}, {"word": "sculpture", "meaning": "escultura", "note": ""}, {"word": "displayed", "meaning": "exposta", "note": ""}, {"word": "catalogue", "meaning": "catálogo", "note": ""}, {"word": "replace", "meaning": "substituir", "note": ""}, {"word": "license plate", "meaning": "placa de carro", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'a camera had been turned toward the wall' mostra algo feito antes de Pedro notar."}, {"point": "Passive voice", "explanation_pt": "'a sculpture was displayed' e 'the camera had been turned' focam no objeto, não em quem agiu."}], "multiple_choice": [{"question": "How long did the lights go out?", "options": ["Four minutes", "One hour", "Ten seconds", "All night"], "correct_index": 0, "explanation": "As luzes se apagaram por quatro minutos."}, {"question": "Which room was affected by the blackout?", "options": ["The office", "The east room", "The kitchen", "The basement"], "correct_index": 1, "explanation": "O apagão afetou a sala leste."}, {"question": "What did Pedro notice about the camera?", "options": ["It was stolen", "It was new", "It was turned toward the wall", "It was broken"], "correct_index": 2, "explanation": "A câmera estava virada para a parede."}, {"question": "What was wrong with the sculpture?", "options": ["It was dirty", "It was broken", "It was missing", "It was a copy"], "correct_index": 3, "explanation": "A escultura exposta era uma cópia."}, {"question": "How did the police find the thieves?", "options": ["By a letter", "Through a video and the license plate", "By a witness", "By luck"], "correct_index": 1, "explanation": "Pelo vídeo de segurança e pela placa da van."}], "open_questions": [{"question": "How can museums protect valuable art?", "key_points_pt": ["citar câmeras, alarmes, equipe"]}, {"question": "Why do you think people steal art?", "key_points_pt": ["dar opinião com argumentos"]}]}}, {"level": "B2", "genre": "detective", "title": "The Ledger in the Library", "paragraphs": ["Inspector Rao had been investigating the disappearance of Professor Haldane for nearly two weeks, and so far every lead had collapsed. The professor's office was undisturbed, his bank account untouched, and his colleagues, though visibly concerned, could offer no explanation. The only unusual detail was a small notebook found in his drawer, filled with page numbers and no words.", "It took Rao several days to understand that the numbers referred to a specific edition of an old encyclopedia in the university library. Turning to the indicated pages, he found faint pencil marks beneath certain letters. Assembled in order, they spelled out a short message: \"If I am gone, ask Hollis about the east wing.\"", "Hollis turned out to be the building's night caretaker, an elderly man who had worked there for thirty years. At first he denied knowing anything, but when Rao mentioned the professor's name, his hands began to tremble. He admitted that Haldane had discovered documents proving that the university had hidden funds from a donor, and that someone had threatened him to keep quiet.", "The professor was eventually found in a rented cabin two hundred kilometres away, safe and in hiding. He had chosen to disappear before the people involved could silence him. Rao closed the case with a strange feeling: he had solved the mystery, but the larger question of who had ordered the threats remained, for the moment, frustratingly open."], "paragraphs_pt": ["O inspetor Rao investigava o desaparecimento do professor Haldane havia quase duas semanas e, até agora, toda pista desmoronara. A sala do professor estava intacta, a conta bancária, intocada, e os colegas, embora visivelmente preocupados, não sabiam explicar. O único detalhe incomum era um pequeno caderno achado na gaveta, cheio de números de páginas e nenhuma palavra.", "Rao levou vários dias para entender que os números se referiam a uma edição específica de uma enciclopédia antiga na biblioteca da universidade. Ao abrir nas páginas indicadas, encontrou marcas fracas de lápis embaixo de certas letras. Reunidas em ordem, formavam uma mensagem curta: \"Se eu sumir, pergunte a Hollis sobre a ala leste.\"", "Hollis era o zelador noturno do prédio, um homem idoso que trabalhava lá havia trinta anos. De início negou saber de qualquer coisa, mas quando Rao mencionou o nome do professor, suas mãos começaram a tremer. Admitiu que Haldane descobrira documentos provando que a universidade escondera verbas de um doador e que alguém o ameaçara para que ficasse calado.", "O professor foi encontrado por fim numa cabana alugada a duzentos quilômetros dali, seguro e escondido. Escolhera desaparecer antes que os envolvidos pudessem silenciá-lo. Rao encerrou o caso com uma sensação estranha: resolvera o mistério, mas a pergunta maior, de quem ordenara as ameaças, permanecia, por ora, frustrantemente em aberto."], "hard_words": ["lead", "faint", "caretaker", "funds"], "vocab": [{"word": "disappearance", "meaning": "desaparecimento", "note": ""}, {"word": "lead", "meaning": "pista", "note": ""}, {"word": "undisturbed", "meaning": "intacto, sem mexer", "note": ""}, {"word": "drawer", "meaning": "gaveta", "note": ""}, {"word": "edition", "meaning": "edição", "note": ""}, {"word": "faint", "meaning": "fraco", "note": ""}, {"word": "caretaker", "meaning": "zelador", "note": ""}, {"word": "trembling", "meaning": "tremendo", "note": ""}, {"word": "funds", "meaning": "verbas, fundos", "note": ""}, {"word": "in hiding", "meaning": "escondido", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "am", "be"], "irregular": ["had", "collapsed", "concerned", "could", "found", "filled", "took", "referred", "indicated", "assembled", "spelled", "gone", "turned", "worked", "denied", "mentioned", "began", "admitted", "discovered", "hidden", "threatened", "rented", "chosen", "involved", "closed", "solved", "ordered", "remained"], "phrasal": ["turned out", "spelled out"], "wh": ["who", "when"], "connectors": ["and", "but", "so", "though", "before", "when", "if"], "comparative": []}, "word_meanings": [{"word": "disappearance", "meaning": "desaparecimento", "note": ""}, {"word": "lead", "meaning": "pista", "note": ""}, {"word": "undisturbed", "meaning": "intacto, sem mexer", "note": ""}, {"word": "drawer", "meaning": "gaveta", "note": ""}, {"word": "edition", "meaning": "edição", "note": ""}, {"word": "faint", "meaning": "fraco", "note": ""}, {"word": "caretaker", "meaning": "zelador", "note": ""}, {"word": "trembling", "meaning": "tremendo", "note": ""}, {"word": "funds", "meaning": "verbas, fundos", "note": ""}, {"word": "in hiding", "meaning": "escondido", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect continuous", "explanation_pt": "'had been investigating for nearly two weeks' mostra uma ação que durava até outro momento do passado."}, {"point": "Passive voice", "explanation_pt": "'a notebook found in his drawer' e 'The professor was found' focam no que aconteceu, não em quem agiu."}], "multiple_choice": [{"question": "How long had Rao been investigating?", "options": ["Nearly two weeks", "Two days", "Two years", "One night"], "correct_index": 0, "explanation": "Ele investigava havia quase duas semanas."}, {"question": "What was unusual about the notebook?", "options": ["It had only page numbers", "It was written in code of colors", "It was burned", "It was empty"], "correct_index": 0, "explanation": "Só tinha números de páginas."}, {"question": "What did the pencil marks form?", "options": ["A date", "A signature", "A message about Hollis", "A map"], "correct_index": 2, "explanation": "Formaram uma mensagem sobre Hollis."}, {"question": "What did Haldane discover?", "options": ["A fake diploma", "A secret room", "A stolen painting", "The university had hidden funds"], "correct_index": 3, "explanation": "A universidade escondera verbas de um doador."}, {"question": "Why did the professor disappear?", "options": ["To change jobs", "To take a vacation", "To avoid being silenced", "To write a book"], "correct_index": 2, "explanation": "Ele sumiu antes que o silenciassem."}], "open_questions": [{"question": "Why can a small unusual detail help solve a big case?", "key_points_pt": ["discutir pistas e raciocínio"]}, {"question": "Should whistleblowers be protected? Explain.", "key_points_pt": ["defender uma posição"]}]}}, {"level": "B2", "genre": "detective", "title": "A Tuesday Like Any Other", "paragraphs": ["Nothing in Clara's routine had suggested that the day would end with a police interview. She had caught the usual train, bought the usual coffee and arrived at the office at precisely 8:55. It was only when she opened her emails that she discovered someone had accessed her account from another country at three in the morning.", "The company's security specialist, a calm woman named Kemi, listened without interrupting while Clara described her habits. \"Did you click on any unusual links last week?\" Kemi asked. Clara hesitated. She remembered an email from a delivery company about a missing parcel, which she had opened without a second thought.", "Kemi examined the message and smiled grimly. The logo was convincing, the sender's address differed by a single letter, and the link led to a copy of a real website designed to collect passwords. \"Whoever did this was patient,\" she said. \"They counted on you being busy.\"", "Fortunately, the company caught the intrusion before any data was stolen. Clara was shaken, not because of the risk, but because the trap had worked on someone who considered herself careful. Since then she verifies every sender, and she sometimes reminds colleagues that a convincing lie is usually the most dangerous kind."], "paragraphs_pt": ["Nada na rotina de Clara sugeria que o dia terminaria com um interrogatório policial. Ela pegara o trem de sempre, comprara o café de sempre e chegara ao escritório exatamente às 8h55. Só ao abrir os e-mails descobriu que alguém acessara sua conta de outro país às três da manhã.", "A especialista em segurança da empresa, uma mulher calma chamada Kemi, ouviu sem interromper enquanto Clara descrevia seus hábitos. \"Você clicou em algum link estranho na semana passada?\", perguntou Kemi. Clara hesitou. Lembrou de um e-mail de uma empresa de entregas sobre uma encomenda perdida, que abrira sem pensar duas vezes.", "Kemi examinou a mensagem e sorriu com ar sombrio. O logotipo era convincente, o endereço do remetente diferia em uma única letra, e o link levava a uma cópia de um site verdadeiro feita para coletar senhas. \"Quem fez isso foi paciente\", disse. \"Contava com você estar ocupada.\"", "Felizmente, a empresa barrou a invasão antes que dados fossem roubados. Clara ficou abalada, não por causa do risco, mas porque a armadilha funcionara com alguém que se considerava cuidadosa. Desde então, ela confere todo remetente e às vezes lembra os colegas de que uma mentira convincente costuma ser a mais perigosa."], "hard_words": ["hesitated", "convincing", "sender", "intrusion"], "vocab": [{"word": "accessed", "meaning": "acessou", "note": ""}, {"word": "specialist", "meaning": "especialista", "note": ""}, {"word": "hesitated", "meaning": "hesitou", "note": ""}, {"word": "parcel", "meaning": "encomenda", "note": ""}, {"word": "grimly", "meaning": "com ar sombrio", "note": ""}, {"word": "convincing", "meaning": "convincente", "note": ""}, {"word": "sender", "meaning": "remetente", "note": ""}, {"word": "passwords", "meaning": "senhas", "note": ""}, {"word": "intrusion", "meaning": "invasão", "note": ""}, {"word": "shaken", "meaning": "abalada", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being", "is"], "irregular": ["had", "suggested", "would", "caught", "bought", "arrived", "opened", "discovered", "accessed", "named", "listened", "described", "did", "asked", "hesitated", "remembered", "thought", "examined", "smiled", "differed", "led", "designed", "said", "counted", "stolen", "shaken", "worked", "considered"], "phrasal": ["counted on", "led to"], "wh": ["who", "when", "which", "whoever"], "connectors": ["and", "but", "because", "while", "then", "before", "when", "since"], "comparative": []}, "word_meanings": [{"word": "accessed", "meaning": "acessou", "note": ""}, {"word": "specialist", "meaning": "especialista", "note": ""}, {"word": "hesitated", "meaning": "hesitou", "note": ""}, {"word": "parcel", "meaning": "encomenda", "note": ""}, {"word": "grimly", "meaning": "com ar sombrio", "note": ""}, {"word": "convincing", "meaning": "convincente", "note": ""}, {"word": "sender", "meaning": "remetente", "note": ""}, {"word": "passwords", "meaning": "senhas", "note": ""}, {"word": "intrusion", "meaning": "invasão", "note": ""}, {"word": "shaken", "meaning": "abalada", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Nothing in Clara's routine had suggested' indica algo anterior ao fim do dia."}, {"point": "Relative clauses", "explanation_pt": "'a copy of a real website designed to collect passwords' acrescenta informação sobre o site."}], "multiple_choice": [{"question": "What did Clara discover when she opened her emails?", "options": ["She was fired", "She won a prize", "Someone had accessed her account", "She lost her phone"], "correct_index": 2, "explanation": "Alguém acessara sua conta de outro país."}, {"question": "What did she remember?", "options": ["A strange visitor", "A delivery email she opened", "A phone call", "A letter"], "correct_index": 1, "explanation": "Ela lembrou de um e-mail de entrega."}, {"question": "How was the fake email different?", "options": ["It had no logo", "It was very long", "It was in another language", "The sender's address differed by one letter"], "correct_index": 3, "explanation": "O endereço do remetente diferia em uma letra."}, {"question": "What was the purpose of the link?", "options": ["To show a video", "To sell products", "To collect passwords", "To install a game"], "correct_index": 2, "explanation": "O link servia para coletar senhas."}, {"question": "What did Clara change afterwards?", "options": ["She verifies every sender", "She quit her job", "She stopped using email", "She moved"], "correct_index": 0, "explanation": "Ela passou a conferir cada remetente."}], "open_questions": [{"question": "How can people recognise a fake email?", "key_points_pt": ["citar remetente, erros, urgência"]}, {"question": "Why do careful people also fall for scams?", "key_points_pt": ["discutir pressa, confiança e hábitos"]}]}}, {"level": "C1", "genre": "detective", "title": "The Alibi of Rain", "paragraphs": ["When the body of the financier Gaspard Lenoir was discovered in his study at seven in the morning, the household presented an apparently flawless picture of grief. His wife, Odile, was inconsolable; his nephew, Julien, kept repeating that he had been at a conference in another city; and the housekeeper, Mme Perrin, insisted that nobody had entered or left the house during the night.", "Inspector Mercier, an unhurried man who distrusted tidy narratives, noticed something almost trivial. The garden path, which every witness claimed to have been avoiding, bore a single line of footprints, and the ground beneath them was perfectly dry. It had rained heavily from midnight until four. Whoever had crossed that path had done so before the storm.", "That detail dismantled the housekeeper's account, and the rest unravelled quickly. Mme Perrin had, in fact, let someone in at eleven, and had remained silent for a reason that took Mercier several hours of patient questioning to extract: she was afraid that the visitor, her own son, would be blamed for something he had not done.", "The real culprit proved to be the nephew, whose conference alibi collapsed once Mercier requested the hotel records. Yet what lingered in the inspector's mind was not the solution but the housekeeper's fear. Truth, he reflected, was rarely obstructed by cunning alone; far more often it was guarded by love."], "paragraphs_pt": ["Quando o corpo do financista Gaspard Lenoir foi descoberto no escritório às sete da manhã, a casa apresentava um quadro aparentemente impecável de luto. A esposa, Odile, estava inconsolável; o sobrinho, Julien, repetia que estivera numa conferência em outra cidade; e a governanta, Mme Perrin, insistia que ninguém entrara nem saíra da casa durante a noite.", "O inspetor Mercier, homem sem pressa que desconfiava de narrativas organizadas, notou algo quase trivial. O caminho do jardim, que todas as testemunhas diziam ter evitado, tinha uma única linha de pegadas, e o chão sob elas estava perfeitamente seco. Chovera forte da meia-noite às quatro. Quem cruzara aquele caminho o fizera antes da tempestade.", "Esse detalhe desmontou o relato da governanta, e o resto se desfez rápido. Mme Perrin, de fato, deixara alguém entrar às onze e se mantivera calada por um motivo que Mercier levou horas de interrogatório paciente para extrair: temia que o visitante, o próprio filho dela, fosse culpado de algo que não fizera.", "O verdadeiro culpado revelou-se ser o sobrinho, cujo álibi da conferência desmoronou quando Mercier requisitou os registros do hotel. Mas o que permaneceu na mente do inspetor não foi a solução, e sim o medo da governanta. A verdade, refletiu, raramente era obstruída apenas pela astúcia; com muito mais frequência era guardada pelo amor."], "hard_words": ["flawless", "footprints", "dismantled", "cunning"], "vocab": [{"word": "financier", "meaning": "financista", "note": ""}, {"word": "flawless", "meaning": "impecável", "note": ""}, {"word": "inconsolable", "meaning": "inconsolável", "note": ""}, {"word": "housekeeper", "meaning": "governanta", "note": ""}, {"word": "trivial", "meaning": "trivial, sem importância", "note": ""}, {"word": "footprints", "meaning": "pegadas", "note": ""}, {"word": "dismantled", "meaning": "desmontou", "note": ""}, {"word": "unravelled", "meaning": "se desfez", "note": ""}, {"word": "culprit", "meaning": "culpado", "note": ""}, {"word": "cunning", "meaning": "astúcia", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "be"], "irregular": ["discovered", "presented", "kept", "had", "insisted", "entered", "left", "distrusted", "noticed", "claimed", "bore", "ground", "rained", "crossed", "done", "dismantled", "unravelled", "remained", "took", "would", "blamed", "proved", "collapsed", "requested", "lingered", "reflected", "obstructed", "guarded"], "phrasal": ["let someone in"], "wh": ["who", "what", "when", "which", "whose", "whoever"], "connectors": ["and", "but", "so", "before", "when", "until", "yet", "or", "once"], "comparative": []}, "word_meanings": [{"word": "financier", "meaning": "financista", "note": ""}, {"word": "flawless", "meaning": "impecável", "note": ""}, {"word": "inconsolable", "meaning": "inconsolável", "note": ""}, {"word": "housekeeper", "meaning": "governanta", "note": ""}, {"word": "trivial", "meaning": "trivial, sem importância", "note": ""}, {"word": "footprints", "meaning": "pegadas", "note": ""}, {"word": "dismantled", "meaning": "desmontou", "note": ""}, {"word": "unravelled", "meaning": "se desfez", "note": ""}, {"word": "culprit", "meaning": "culpado", "note": ""}, {"word": "cunning", "meaning": "astúcia", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Julien kept repeating that he had been at a conference' é uma fala sobre algo anterior."}, {"point": "Whoever + oração", "explanation_pt": "'Whoever had crossed that path had done so before the storm' significa 'quem quer que tenha cruzado'."}], "multiple_choice": [{"question": "What did the housekeeper claim?", "options": ["She was away", "Nobody entered or left during the night", "She heard a scream", "She saw the nephew"], "correct_index": 1, "explanation": "Ela dizia que ninguém entrou nem saiu."}, {"question": "What did Mercier notice about the garden path?", "options": ["Footprints on dry ground", "Broken glass", "A lost key", "Wet footprints"], "correct_index": 0, "explanation": "Havia pegadas em chão seco, apesar da chuva."}, {"question": "Why had the housekeeper lied?", "options": ["She was afraid of Mercier", "To protect her son", "To hurt the nephew", "To get money"], "correct_index": 1, "explanation": "Ela queria proteger o filho."}, {"question": "Who was the culprit?", "options": ["The wife", "The housekeeper", "The nephew", "The inspector"], "correct_index": 2, "explanation": "O culpado era o sobrinho."}, {"question": "How did Mercier break the nephew's alibi?", "options": ["With a confession", "With a letter", "With hotel records", "With a photograph"], "correct_index": 2, "explanation": "Os registros do hotel desmontaram o álibi."}], "open_questions": [{"question": "Why might innocent people lie to the police?", "key_points_pt": ["discutir medo, amor e proteção"]}, {"question": "Is a tidy story always more believable? Explain.", "key_points_pt": ["discutir confiança em narrativas"]}]}}, {"level": "C1", "genre": "detective", "title": "The Translator's Silence", "paragraphs": ["Marta Szabo, a court interpreter with twenty years of experience, prided herself on invisibility. Her job was to convey every word without adding a nuance, and she had learned to treat a witness's testimony as a stream passing through her without leaving a trace. It was therefore disconcerting to discover, midway through a murder trial, that a single sentence was lodging in her mind.", "The defendant, an elderly fisherman speaking a regional dialect, had said something that she had rendered as \"I was at the harbour that night.\" But now, replaying the recording in her memory, she realised that the verb he used implied not presence but waiting. He had not been at the harbour; he had been waiting for someone, and the difference might be significant.", "Her professional code urged her to stay silent unless asked, yet a mistranslation, however subtle, could condemn a man. After a sleepless night she approached the prosecutor and, with considerable discomfort, requested permission to correct the record.", "The correction altered the shape of the trial. The prosecutor reconsidered the timeline, the defence found the person he had been waiting for, and the verdict changed. Marta received a reprimand for acting without authorisation, which she accepted calmly. Invisibility, she concluded, was an admirable ideal for a translator, but a poor excuse for a witness."], "paragraphs_pt": ["Marta Szabo, intérprete judicial com vinte anos de experiência, orgulhava-se da invisibilidade. Seu trabalho era transmitir cada palavra sem acrescentar nuance, e ela aprendera a tratar o testemunho como uma correnteza que passava por ela sem deixar rastro. Por isso foi desconcertante descobrir, no meio de um julgamento de assassinato, que uma única frase se alojava em sua mente.", "O réu, um pescador idoso que falava um dialeto regional, dissera algo que ela havia traduzido como \"Eu estava no porto naquela noite.\" Mas agora, repassando a gravação na memória, percebeu que o verbo que ele usara não implicava presença, e sim espera. Ele não estivera no porto; esperava por alguém, e a diferença podia ser significativa.", "Seu código profissional a instava a se calar, a menos que perguntassem, mas uma tradução errada, ainda que sutil, podia condenar um homem. Depois de uma noite sem dormir, ela procurou o promotor e, com considerável desconforto, pediu permissão para corrigir o registro.", "A correção alterou o rumo do julgamento. O promotor reconsiderou a cronologia, a defesa encontrou a pessoa que ele esperava e o veredicto mudou. Marta recebeu uma advertência por agir sem autorização, que aceitou com calma. Invisibilidade, concluiu, era um ideal admirável para uma tradutora, mas uma desculpa pobre para uma testemunha."], "hard_words": ["disconcerting", "defendant", "prosecutor", "reprimand"], "vocab": [{"word": "interpreter", "meaning": "intérprete", "note": ""}, {"word": "convey", "meaning": "transmitir", "note": ""}, {"word": "nuance", "meaning": "nuance, sutileza", "note": ""}, {"word": "disconcerting", "meaning": "desconcertante", "note": ""}, {"word": "lodging", "meaning": "alojando-se", "note": ""}, {"word": "defendant", "meaning": "réu", "note": ""}, {"word": "rendered", "meaning": "traduziu, verteu", "note": ""}, {"word": "prosecutor", "meaning": "promotor", "note": ""}, {"word": "reprimand", "meaning": "advertência", "note": ""}, {"word": "verdict", "meaning": "veredicto", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "be"], "irregular": ["prided", "had", "learned", "said", "rendered", "realised", "used", "implied", "might", "urged", "asked", "could", "approached", "requested", "altered", "reconsidered", "found", "changed", "received", "accepted", "concluded"], "phrasal": ["midway through", "approached the prosecutor"], "wh": ["which"], "connectors": ["and", "but", "however", "after", "therefore", "unless", "yet", "as"], "comparative": []}, "word_meanings": [{"word": "interpreter", "meaning": "intérprete", "note": ""}, {"word": "convey", "meaning": "transmitir", "note": ""}, {"word": "nuance", "meaning": "nuance, sutileza", "note": ""}, {"word": "disconcerting", "meaning": "desconcertante", "note": ""}, {"word": "lodging", "meaning": "alojando-se", "note": ""}, {"word": "defendant", "meaning": "réu", "note": ""}, {"word": "rendered", "meaning": "traduziu, verteu", "note": ""}, {"word": "prosecutor", "meaning": "promotor", "note": ""}, {"word": "reprimand", "meaning": "advertência", "note": ""}, {"word": "verdict", "meaning": "veredicto", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'she had learned to treat testimony as a stream' mostra um hábito formado antes do julgamento."}, {"point": "Not... but", "explanation_pt": "'implied not presence but waiting' contrasta dois significados."}], "multiple_choice": [{"question": "What was Marta's profession?", "options": ["Journalist", "Lawyer", "Court interpreter", "Detective"], "correct_index": 2, "explanation": "Ela era intérprete judicial."}, {"question": "What problem did she notice?", "options": ["A verb meant waiting, not presence", "A name was missing", "A witness lied", "A date was wrong"], "correct_index": 0, "explanation": "O verbo indicava espera, não presença."}, {"question": "Why was speaking up difficult?", "options": ["She had no proof", "She was afraid of the judge", "Her professional code urged silence", "She was sick"], "correct_index": 2, "explanation": "O código profissional a instava a ficar em silêncio."}, {"question": "What changed after the correction?", "options": ["The trial ended", "The judge left", "The witness disappeared", "The verdict changed"], "correct_index": 3, "explanation": "O veredicto mudou."}, {"question": "What did Marta conclude?", "options": ["Dialects are useless", "The law is perfect", "Translators should never speak", "Invisibility is a poor excuse for a witness"], "correct_index": 3, "explanation": "Invisibilidade é má desculpa para uma testemunha."}], "open_questions": [{"question": "When is it right to break a professional rule?", "key_points_pt": ["discutir ética e consequências"]}, {"question": "How can one word change the meaning of a testimony?", "key_points_pt": ["dar exemplos de ambiguidade"]}]}}, {"level": "C2", "genre": "detective", "title": "The Mathematics of Absence", "paragraphs": ["The disappearance of Dr. Eliza Brandt, a mathematician whose work on probability had quietly reshaped the way several banks assessed risk, attracted the sort of attention that bureaucracies reserve for embarrassment rather than concern. Detective Sutherland was assigned the case on a Thursday and told, in the unmistakable tone of superiors who wish to be informed of nothing, to resolve it discreetly.", "What the investigation lacked in evidence it made up for in paradox. Brandt's flat was spotless; her passport was in a drawer; her phone had been switched off at a precise hour, 11:17 on a Monday night, after which it never reconnected. Her colleagues described her as methodical to a fault, a person who would no more vanish on impulse than a clock would decide to run backwards.", "It was this very predictability that convinced Sutherland that the disappearance had been planned. People who live by pattern leave patterns, and over several evenings he assembled a calendar of Brandt's final months. Small anomalies emerged: a withdrawal of cash every second Friday, a train ticket to a coastal town she had never mentioned, a reservation under a name that turned out to be her grandmother's.", "When he finally reached the town, he found her in a rented room above a bakery, calmly working through a notebook of equations. She greeted him without alarm, as if she had been waiting for the question rather than the man. She had left, she explained, because she had discovered that her models were being used to disguise losses, and she needed solitude to prove it before anyone could stop her. Sutherland listened, and realised with unease that the most difficult part of the case had only just begun."], "paragraphs_pt": ["O desaparecimento da Dra. Eliza Brandt, matemática cujo trabalho sobre probabilidade silenciosamente remodelara a forma como vários bancos avaliavam risco, atraiu o tipo de atenção que as burocracias reservam ao constrangimento, não à preocupação. O detetive Sutherland recebeu o caso numa quinta-feira e foi instruído, no tom inconfundível de superiores que não querem ser informados de nada, a resolvê-lo com discrição.", "O que a investigação carecia em provas compensava em paradoxo. O apartamento de Brandt estava impecável; o passaporte, numa gaveta; o celular fora desligado numa hora precisa, 23h17 de uma segunda à noite, depois da qual nunca mais se reconectou. Os colegas a descreviam como metódica ao extremo, alguém que desapareceria por impulso tanto quanto um relógio decidiria andar para trás.", "Foi essa mesma previsibilidade que convenceu Sutherland de que o desaparecimento fora planejado. Quem vive por padrões deixa padrões, e ao longo de várias noites ele montou um calendário dos últimos meses de Brandt. Pequenas anomalias surgiram: uma retirada de dinheiro a cada duas sextas-feiras, uma passagem de trem para uma cidade litorânea que ela nunca mencionara, uma reserva em nome que se revelou ser o da avó.", "Quando finalmente chegou à cidade, encontrou-a num quarto alugado em cima de uma padaria, trabalhando calmamente num caderno de equações. Ela o cumprimentou sem alarme, como se esperasse a pergunta e não o homem. Partira, explicou, porque descobrira que seus modelos estavam sendo usados para disfarçar perdas, e precisava de solidão para prová-lo antes que alguém a impedisse. Sutherland ouviu e percebeu, com desconforto, que a parte mais difícil do caso apenas começara."], "hard_words": ["paradox", "predictability", "anomalies", "solitude"], "vocab": [{"word": "bureaucracies", "meaning": "burocracias", "note": ""}, {"word": "discreetly", "meaning": "com discrição", "note": ""}, {"word": "paradox", "meaning": "paradoxo", "note": ""}, {"word": "methodical", "meaning": "metódico", "note": ""}, {"word": "impulse", "meaning": "impulso", "note": ""}, {"word": "predictability", "meaning": "previsibilidade", "note": ""}, {"word": "anomalies", "meaning": "anomalias", "note": ""}, {"word": "withdrawal", "meaning": "retirada (de dinheiro)", "note": ""}, {"word": "equations", "meaning": "equações", "note": ""}, {"word": "solitude", "meaning": "solidão (isolamento)", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "been", "were", "being"], "irregular": ["had", "assessed", "attracted", "assigned", "told", "informed", "lacked", "made", "switched", "reconnected", "described", "would", "convinced", "planned", "assembled", "emerged", "mentioned", "turned", "reached", "found", "rented", "greeted", "left", "explained", "discovered", "used", "needed", "could", "listened", "realised", "begun"], "phrasal": ["made up for", "switched off"], "wh": ["who", "what", "when", "which", "whose"], "connectors": ["and", "because", "after", "before", "when", "finally", "if", "as"], "comparative": []}, "word_meanings": [{"word": "bureaucracies", "meaning": "burocracias", "note": ""}, {"word": "discreetly", "meaning": "com discrição", "note": ""}, {"word": "paradox", "meaning": "paradoxo", "note": ""}, {"word": "methodical", "meaning": "metódico", "note": ""}, {"word": "impulse", "meaning": "impulso", "note": ""}, {"word": "predictability", "meaning": "previsibilidade", "note": ""}, {"word": "anomalies", "meaning": "anomalias", "note": ""}, {"word": "withdrawal", "meaning": "retirada (de dinheiro)", "note": ""}, {"word": "equations", "meaning": "equações", "note": ""}, {"word": "solitude", "meaning": "solidão (isolamento)", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'her phone had been switched off' e 'she had discovered' indicam ações anteriores ao momento em que Sutherland investiga."}, {"point": "No more... than", "explanation_pt": "'would no more vanish on impulse than a clock would decide to run backwards' compara duas coisas igualmente improváveis."}], "multiple_choice": [{"question": "What was Dr. Brandt's field?", "options": ["History", "Mathematics and probability", "Medicine", "Law"], "correct_index": 1, "explanation": "Ela era matemática, especialista em probabilidade."}, {"question": "What did the colleagues say about her?", "options": ["She was lazy", "She was methodical to a fault", "She was secretive about money", "She was impulsive"], "correct_index": 1, "explanation": "Era metódica ao extremo."}, {"question": "What small anomaly did Sutherland find?", "options": ["A fake name on her door", "A missing passport", "A broken phone", "Cash withdrawals every second Friday"], "correct_index": 3, "explanation": "Retiradas de dinheiro a cada duas sextas."}, {"question": "Where did he find her?", "options": ["In a library", "In a hotel", "In a rented room above a bakery", "On a train"], "correct_index": 2, "explanation": "Ela estava num quarto alugado em cima de uma padaria."}, {"question": "Why had she left?", "options": ["She wanted to retire", "Her models were being used to disguise losses", "She lost her job", "She was ill"], "correct_index": 1, "explanation": "Seus modelos disfarçavam perdas."}], "open_questions": [{"question": "Is predictability a strength or a weakness for someone who wants to disappear?", "key_points_pt": ["discutir hábitos e rastros"]}, {"question": "What would you do if you discovered your work was being misused?", "key_points_pt": ["usar condicional", "discutir ética"]}]}}, {"level": "C2", "genre": "detective", "title": "The Perfect Witness", "paragraphs": ["Every detective eventually meets a witness who seems to have been designed by the universe to resolve the case, and Detective Imani Okafor had been warned about them. The sort of person who volunteers the licence plate, the time, the direction of travel and, if encouraged, the suspect's mother's maiden name. Such testimony, she had learned, was usually the first thing to distrust.", "Mr. Valdès, the witness in question, was irreproachable: a retired schoolteacher with a precise memory and an impressive talent for narrative. He described the robbery at the pharmacy in vivid detail, from the cold glint of the knife to the exact shade of the thief's scarf. Yet in four interviews, his account never deviated by a single word, and Okafor, who had spent decades listening to people remember, knew that memory is a restless reconstruction, not a recording.", "She tested him gently. In the fifth interview she introduced a minor error, asking about \"the green scarf\" when he had said it was blue. Mr. Valdès, without hesitation, agreed that it had been green. It was not a lie in the usual sense; he simply wished so strongly to be useful that his mind rearranged itself accordingly.", "The real thief was identified three weeks later by a security camera that had been dismissed as broken. Okafor visited Mr. Valdès and returned the notebook where he kept his statements. She did not reproach him, because she had understood that what he had offered was not deceit but loneliness, a longing to matter in a story larger than his own. She stayed for tea, which, she suspected, was the only testimony he had really wanted to give."], "paragraphs_pt": ["Todo detetive acaba encontrando uma testemunha que parece ter sido projetada pelo universo para resolver o caso, e a detetive Imani Okafor fora avisada sobre elas. O tipo de pessoa que se oferece para dar a placa, a hora, a direção da fuga e, se encorajada, o sobrenome de solteira da mãe do suspeito. Esse tipo de testemunho, ela aprendera, costumava ser a primeira coisa a desconfiar.", "O Sr. Valdès, a testemunha em questão, era irrepreensível: um professor aposentado com memória precisa e um talento impressionante para narrativa. Descreveu o assalto à farmácia com detalhes vívidos, do brilho frio da faca ao tom exato do cachecol do ladrão. Mas, em quatro entrevistas, seu relato nunca se desviou de uma única palavra, e Okafor, que passara décadas ouvindo gente lembrar, sabia que a memória é uma reconstrução inquieta, não uma gravação.", "Ela o testou com delicadeza. Na quinta entrevista, introduziu um pequeno erro, perguntando sobre \"o cachecol verde\" quando ele havia dito que era azul. O Sr. Valdès, sem hesitar, concordou que era verde. Não era mentira no sentido usual; ele simplesmente desejava tanto ser útil que sua mente se reorganizava de acordo.", "O verdadeiro ladrão foi identificado três semanas depois por uma câmera de segurança que fora descartada como quebrada. Okafor visitou o Sr. Valdès e devolveu o caderno onde ele guardava seus depoimentos. Não o recriminou, porque entendera que o que ele oferecera não era engano, mas solidão, um desejo de importar numa história maior que a própria. Ficou para o chá, que, suspeitava, era o único testemunho que ele realmente quisera dar."], "hard_words": ["irreproachable", "deviated", "restless", "longing"], "vocab": [{"word": "irreproachable", "meaning": "irrepreensível", "note": ""}, {"word": "vivid", "meaning": "vívido", "note": ""}, {"word": "glint", "meaning": "brilho", "note": ""}, {"word": "deviated", "meaning": "desviou", "note": ""}, {"word": "restless", "meaning": "inquieta", "note": ""}, {"word": "reconstruction", "meaning": "reconstrução", "note": ""}, {"word": "hesitation", "meaning": "hesitação", "note": ""}, {"word": "deceit", "meaning": "engano", "note": ""}, {"word": "longing", "meaning": "desejo, anseio", "note": ""}, {"word": "testimony", "meaning": "testemunho", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "is", "be"], "irregular": ["designed", "had", "warned", "encouraged", "learned", "retired", "described", "deviated", "spent", "knew", "tested", "introduced", "said", "agreed", "wished", "rearranged", "identified", "dismissed", "broken", "visited", "returned", "kept", "did", "understood", "offered", "stayed", "suspected", "wanted"], "phrasal": ["stayed for"], "wh": ["who", "what", "where", "when", "which"], "connectors": ["and", "but", "because", "so", "when", "yet", "if", "as"], "comparative": []}, "word_meanings": [{"word": "irreproachable", "meaning": "irrepreensível", "note": ""}, {"word": "vivid", "meaning": "vívido", "note": ""}, {"word": "glint", "meaning": "brilho", "note": ""}, {"word": "deviated", "meaning": "desviou", "note": ""}, {"word": "restless", "meaning": "inquieta", "note": ""}, {"word": "reconstruction", "meaning": "reconstrução", "note": ""}, {"word": "hesitation", "meaning": "hesitação", "note": ""}, {"word": "deceit", "meaning": "engano", "note": ""}, {"word": "longing", "meaning": "desejo, anseio", "note": ""}, {"word": "testimony", "meaning": "testemunho", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'she had learned' e 'she had understood' mostram aprendizados anteriores ao momento da narração."}, {"point": "Not... but", "explanation_pt": "'not deceit but loneliness' contrasta dois conceitos para mudar a interpretação."}], "multiple_choice": [{"question": "Why was Okafor suspicious of Mr. Valdès?", "options": ["He was a thief", "He was rude", "He missed interviews", "His story never changed"], "correct_index": 3, "explanation": "O relato dele nunca variava."}, {"question": "How did Okafor test him?", "options": ["She introduced a small error", "She threatened him", "She called his friends", "She recorded him"], "correct_index": 0, "explanation": "Ela citou um cachecol verde em vez de azul."}, {"question": "How did he react?", "options": ["He corrected her", "He agreed it had been green", "He left", "He became angry"], "correct_index": 1, "explanation": "Ele concordou que era verde."}, {"question": "Who found the real thief?", "options": ["Mr. Valdès", "A neighbour", "A dog", "A camera thought to be broken"], "correct_index": 3, "explanation": "Uma câmera descartada como quebrada."}, {"question": "What did Okafor understand about Mr. Valdès?", "options": ["He was paid", "He was lonely and wanted to matter", "He was a criminal", "He was a liar"], "correct_index": 1, "explanation": "Ele era solitário e queria importar."}], "open_questions": [{"question": "Why can memory be unreliable even when we are honest?", "key_points_pt": ["discutir memória e sugestão"]}, {"question": "How should investigators treat witnesses who want to help too much?", "key_points_pt": ["discutir cuidado e empatia"]}]}}, {"level": "A1", "genre": "dialogue", "title": "At the Bus Stop", "paragraphs": ["\"Excuse me, is this bus number 12?\" asks Lena. \"Yes, it is,\" says the driver. \"Where do you want to go?\"", "\"I want to go to the museum. How much is the ticket?\" \"It is two euros.\" Lena gives him the money. \"Thank you. Sit down, please.\"", "\"Is the museum far?\" \"No, it is ten minutes from here. I will tell you.\" Lena smiles and sits near the window. She is happy."], "paragraphs_pt": ["\"Com licença, este é o ônibus número 12?\", pergunta Lena. \"Sim, é\", diz o motorista. \"Aonde você quer ir?\"", "\"Quero ir ao museu. Quanto custa a passagem?\" \"São dois euros.\" Lena dá o dinheiro. \"Obrigado. Sente-se, por favor.\"", "\"O museu é longe?\" \"Não, fica a dez minutos daqui. Eu aviso.\" Lena sorri e senta perto da janela. Ela está feliz."], "hard_words": ["driver", "museum", "ticket", "far"], "vocab": [{"word": "bus", "meaning": "ônibus", "note": ""}, {"word": "driver", "meaning": "motorista", "note": ""}, {"word": "museum", "meaning": "museu", "note": ""}, {"word": "ticket", "meaning": "passagem", "note": ""}, {"word": "money", "meaning": "dinheiro", "note": ""}, {"word": "far", "meaning": "longe", "note": ""}, {"word": "window", "meaning": "janela", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": ["where", "how"], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "bus", "meaning": "ônibus", "note": ""}, {"word": "driver", "meaning": "motorista", "note": ""}, {"word": "museum", "meaning": "museu", "note": ""}, {"word": "ticket", "meaning": "passagem", "note": ""}, {"word": "money", "meaning": "dinheiro", "note": ""}, {"word": "far", "meaning": "longe", "note": ""}, {"word": "window", "meaning": "janela", "note": ""}], "exercises": {"grammar": [{"point": "Questions com is", "explanation_pt": "'Is this bus number 12?' e 'Is the museum far?' invertem is e o sujeito para perguntar."}], "multiple_choice": [{"question": "What number is the bus?", "options": ["20", "2", "10", "12"], "correct_index": 3, "explanation": "O ônibus é o número 12."}, {"question": "Where does Lena want to go?", "options": ["To the museum", "To the park", "To school", "To a bank"], "correct_index": 0, "explanation": "Ela quer ir ao museu."}, {"question": "How much is the ticket?", "options": ["Ten euros", "Five euros", "Two euros", "One euro"], "correct_index": 2, "explanation": "A passagem custa dois euros."}, {"question": "How far is the museum?", "options": ["One hour", "Ten minutes", "Two minutes", "Five hours"], "correct_index": 1, "explanation": "Fica a dez minutos."}, {"question": "Where does Lena sit?", "options": ["At the back", "On the floor", "Near the window", "Near the door"], "correct_index": 2, "explanation": "Ela senta perto da janela."}], "open_questions": [{"question": "How do you go to school or work?", "key_points_pt": ["falar de transporte"]}, {"question": "Do you like to sit near the window? Why?", "key_points_pt": ["dar uma opinião simples"]}]}}, {"level": "A1", "genre": "dialogue", "title": "A New Neighbor", "paragraphs": ["\"Hello! I am Sam. I live next door.\" \"Hi, Sam. I am Rita. I am your new neighbor.\" \"Nice to meet you, Rita! Where are you from?\"", "\"I am from Brazil. And you?\" \"I am from Canada. I have a dog. His name is Max.\" \"I love dogs! I have a cat.\" They laugh.", "\"Do you want some coffee?\" asks Sam. \"Yes, please!\" says Rita. They go to Sam's kitchen and talk for one hour."], "paragraphs_pt": ["\"Olá! Eu sou o Sam. Moro aqui ao lado.\" \"Oi, Sam. Eu sou a Rita. Sou sua nova vizinha.\" \"Prazer, Rita! De onde você é?\"", "\"Sou do Brasil. E você?\" \"Sou do Canadá. Tenho um cachorro. O nome dele é Max.\" \"Eu adoro cachorros! Tenho um gato.\" Eles riem.", "\"Quer um café?\", pergunta Sam. \"Sim, por favor!\", diz Rita. Vão à cozinha do Sam e conversam por uma hora."], "hard_words": ["neighbor", "next door", "coffee"], "vocab": [{"word": "neighbor", "meaning": "vizinho", "note": ""}, {"word": "next door", "meaning": "ao lado", "note": ""}, {"word": "nice to meet you", "meaning": "prazer em conhecer", "note": ""}, {"word": "from", "meaning": "de (origem)", "note": ""}, {"word": "dog", "meaning": "cachorro", "note": ""}, {"word": "cat", "meaning": "gato", "note": ""}, {"word": "coffee", "meaning": "café", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["am", "are", "is"], "irregular": [], "phrasal": [], "wh": ["where"], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "neighbor", "meaning": "vizinho", "note": ""}, {"word": "next door", "meaning": "ao lado", "note": ""}, {"word": "nice to meet you", "meaning": "prazer em conhecer", "note": ""}, {"word": "from", "meaning": "de (origem)", "note": ""}, {"word": "dog", "meaning": "cachorro", "note": ""}, {"word": "cat", "meaning": "gato", "note": ""}, {"word": "coffee", "meaning": "café", "note": ""}], "exercises": {"grammar": [{"point": "Where are you from?", "explanation_pt": "'I am from Brazil' responde sobre o país de origem. 'Where... from' pergunta a origem."}], "multiple_choice": [{"question": "Where does Sam live?", "options": ["Next door to Rita", "In Brazil", "In a hotel", "In a school"], "correct_index": 0, "explanation": "Ele mora ao lado."}, {"question": "Where is Rita from?", "options": ["Brazil", "Italy", "Spain", "Canada"], "correct_index": 0, "explanation": "Rita é do Brasil."}, {"question": "What is the dog's name?", "options": ["Leo", "Sam", "Max", "Rita"], "correct_index": 2, "explanation": "O cachorro se chama Max."}, {"question": "What pet does Sam have?", "options": ["A horse", "A bird", "A fish", "A cat"], "correct_index": 3, "explanation": "Sam tem um gato."}, {"question": "What do they have in the kitchen?", "options": ["Juice", "Pizza", "Soup", "Coffee"], "correct_index": 3, "explanation": "Eles tomam café."}], "open_questions": [{"question": "Where are you from?", "key_points_pt": ["responder com I am from"]}, {"question": "Do you know your neighbors?", "key_points_pt": ["falar sobre vizinhos"]}]}}, {"level": "A2", "genre": "dialogue", "title": "Returning a Jacket", "paragraphs": ["\"Good morning. I bought this jacket yesterday, but it is too small,\" says Hugo. \"I would like a bigger one.\"", "\"Of course,\" says the shop assistant. \"Do you have the receipt?\" \"Yes, here it is.\" \"Thank you. Let me check the size. Do you prefer the same color?\" \"Yes, black, please.\"", "\"I am sorry, we do not have a large black jacket today. We have a large blue one, or we can give you your money back.\" Hugo thinks for a minute. \"I like blue too. I will take it.\" \"Great! Please wait here, and I will bring it.\"", "A few minutes later, Hugo tries the jacket. It fits perfectly. He thanks the assistant and leaves the shop with a big smile."], "paragraphs_pt": ["\"Bom dia. Comprei esta jaqueta ontem, mas ela é pequena demais\", diz Hugo. \"Gostaria de uma maior.\"", "\"Claro\", diz a vendedora. \"Você tem o recibo?\" \"Sim, aqui está.\" \"Obrigada. Vou conferir o tamanho. Prefere a mesma cor?\" \"Sim, preta, por favor.\"", "\"Sinto muito, hoje não temos uma jaqueta preta grande. Temos uma azul grande, ou podemos devolver seu dinheiro.\" Hugo pensa por um minuto. \"Gosto de azul também. Vou levar.\" \"Ótimo! Espere aqui, que eu trago.\"", "Alguns minutos depois, Hugo experimenta a jaqueta. Fica perfeita. Ele agradece à vendedora e sai da loja com um grande sorriso."], "hard_words": ["receipt", "prefer", "fits"], "vocab": [{"word": "jacket", "meaning": "jaqueta", "note": ""}, {"word": "shop assistant", "meaning": "vendedor(a)", "note": ""}, {"word": "receipt", "meaning": "recibo", "note": ""}, {"word": "size", "meaning": "tamanho", "note": ""}, {"word": "prefer", "meaning": "preferir", "note": ""}, {"word": "money back", "meaning": "dinheiro de volta", "note": ""}, {"word": "fits", "meaning": "serve", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "am"], "irregular": ["bought", "would"], "phrasal": ["tries the jacket"], "wh": [], "connectors": ["and", "but", "or"], "comparative": []}, "word_meanings": [{"word": "jacket", "meaning": "jaqueta", "note": ""}, {"word": "shop assistant", "meaning": "vendedor(a)", "note": ""}, {"word": "receipt", "meaning": "recibo", "note": ""}, {"word": "size", "meaning": "tamanho", "note": ""}, {"word": "prefer", "meaning": "preferir", "note": ""}, {"word": "money back", "meaning": "dinheiro de volta", "note": ""}, {"word": "fits", "meaning": "serve", "note": ""}], "exercises": {"grammar": [{"point": "Would like", "explanation_pt": "'I would like a bigger one' é um jeito educado de pedir algo."}], "multiple_choice": [{"question": "Why does Hugo return the jacket?", "options": ["It is dirty", "It is old", "It is expensive", "It is too small"], "correct_index": 3, "explanation": "A jaqueta é pequena demais."}, {"question": "What does the assistant ask for?", "options": ["A phone number", "A card", "The receipt", "An address"], "correct_index": 2, "explanation": "Ela pede o recibo."}, {"question": "What color does Hugo want first?", "options": ["Blue", "Red", "Green", "Black"], "correct_index": 3, "explanation": "Ele quer preta primeiro."}, {"question": "What does the shop have?", "options": ["A large black jacket", "A small red jacket", "A large blue jacket", "No jackets"], "correct_index": 2, "explanation": "Eles têm uma azul grande."}, {"question": "How does the new jacket fit?", "options": ["Badly", "Too small", "Perfectly", "Too big"], "correct_index": 2, "explanation": "Fica perfeita."}], "open_questions": [{"question": "Have you ever returned something to a shop?", "key_points_pt": ["contar uma experiência"]}, {"question": "What is polite language in shops?", "key_points_pt": ["citar please, would like, thank you"]}]}}, {"level": "A2", "genre": "dialogue", "title": "Planning the Weekend", "paragraphs": ["\"What are you doing this weekend?\" asks Ana. \"I am not sure,\" says Beto. \"Maybe I will stay at home and watch a film.\" \"That sounds boring! Why don't we go to the beach?\"", "\"Good idea, but the weather is bad. It is going to rain on Saturday.\" \"Then let's go on Sunday. The forecast says it will be sunny.\" \"Perfect. Who else is coming?\"", "\"I will ask Carla and Davi. We can take sandwiches and a ball.\" \"Great! I will bring the drinks. What time shall we meet?\" \"At nine in front of the bus station.\"", "\"See you on Sunday, then!\" says Ana. Beto smiles. His weekend is not boring anymore."], "paragraphs_pt": ["\"O que você vai fazer no fim de semana?\", pergunta Ana. \"Não tenho certeza\", diz Beto. \"Talvez fique em casa e veja um filme.\" \"Que chato! Por que não vamos à praia?\"", "\"Boa ideia, mas o tempo está ruim. Vai chover no sábado.\" \"Então vamos no domingo. A previsão diz que fará sol.\" \"Perfeito. Quem mais vem?\"", "\"Vou chamar a Carla e o Davi. Podemos levar sanduíches e uma bola.\" \"Ótimo! Eu levo as bebidas. A que horas nos encontramos?\" \"Às nove, na frente da rodoviária.\"", "\"Até domingo, então!\", diz Ana. Beto sorri. O fim de semana dele não é mais chato."], "hard_words": ["weekend", "forecast", "sunny"], "vocab": [{"word": "weekend", "meaning": "fim de semana", "note": ""}, {"word": "boring", "meaning": "chato", "note": ""}, {"word": "beach", "meaning": "praia", "note": ""}, {"word": "weather", "meaning": "tempo (clima)", "note": ""}, {"word": "forecast", "meaning": "previsão", "note": ""}, {"word": "sunny", "meaning": "ensolarado", "note": ""}, {"word": "sandwiches", "meaning": "sanduíches", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "am", "is", "be"], "irregular": [], "phrasal": ["stay at home"], "wh": ["who", "what", "why"], "connectors": ["and", "but", "then"], "comparative": []}, "word_meanings": [{"word": "weekend", "meaning": "fim de semana", "note": ""}, {"word": "boring", "meaning": "chato", "note": ""}, {"word": "beach", "meaning": "praia", "note": ""}, {"word": "weather", "meaning": "tempo (clima)", "note": ""}, {"word": "forecast", "meaning": "previsão", "note": ""}, {"word": "sunny", "meaning": "ensolarado", "note": ""}, {"word": "sandwiches", "meaning": "sanduíches", "note": ""}], "exercises": {"grammar": [{"point": "Future com will e going to", "explanation_pt": "'It is going to rain' prevê algo pelo que se vê; 'I will ask Carla' é uma decisão no momento."}, {"point": "Why don't we", "explanation_pt": "'Why don't we go to the beach?' é uma sugestão."}], "multiple_choice": [{"question": "What does Beto plan at first?", "options": ["Stay at home", "Go to work", "Go to the beach", "Visit family"], "correct_index": 0, "explanation": "Ele pensa em ficar em casa."}, {"question": "What is the weather on Saturday?", "options": ["Wind", "Rain", "Sun", "Snow"], "correct_index": 1, "explanation": "Vai chover no sábado."}, {"question": "When will they go to the beach?", "options": ["On Friday", "On Saturday", "On Sunday", "On Monday"], "correct_index": 2, "explanation": "Eles vão no domingo."}, {"question": "What will Ana bring?", "options": ["Chairs", "Drinks", "Sandwiches", "A ball"], "correct_index": 1, "explanation": "Ana leva as bebidas."}, {"question": "Where will they meet?", "options": ["In front of the bus station", "At a cafe", "At the beach", "At school"], "correct_index": 0, "explanation": "Na frente da rodoviária."}], "open_questions": [{"question": "What do you usually do on weekends?", "key_points_pt": ["descrever rotina"]}, {"question": "Do you prefer sunny or rainy days?", "key_points_pt": ["dar uma preferência"]}]}}, {"level": "A2", "genre": "dialogue", "title": "The Wrong Order", "paragraphs": ["Customer: Excuse me, I ordered a vegetable pizza, but this one has meat.", "Waiter: Oh, I am so sorry! Let me check your order. ... You are right. It was our mistake.", "Customer: It's okay, but I am a vegetarian. I cannot eat it. Waiter: Of course. I will ask the kitchen to make a new pizza right away. It will take about fifteen minutes.", "Customer: That's fine. Waiter: Also, the drink is free today. Would you like water, juice or a soda? Customer: Juice, please. Thank you for your help."], "paragraphs_pt": ["Cliente: Com licença, pedi uma pizza de legumes, mas esta tem carne.", "Garçom: Ah, sinto muito! Deixe-me conferir seu pedido. ... Você tem razão. Foi um erro nosso.", "Cliente: Tudo bem, mas sou vegetariana. Não posso comê-la. Garçom: Claro. Vou pedir à cozinha uma pizza nova agora mesmo. Vai levar uns quinze minutos.", "Cliente: Tudo bem. Garçom: Além disso, a bebida é por conta da casa hoje. Quer água, suco ou refrigerante? Cliente: Suco, por favor. Obrigada pela ajuda."], "hard_words": ["mistake", "vegetarian", "free"], "vocab": [{"word": "ordered", "meaning": "pediu", "note": ""}, {"word": "vegetable", "meaning": "legume", "note": ""}, {"word": "meat", "meaning": "carne", "note": ""}, {"word": "mistake", "meaning": "erro", "note": ""}, {"word": "vegetarian", "meaning": "vegetariana", "note": ""}, {"word": "right away", "meaning": "agora mesmo", "note": ""}, {"word": "free", "meaning": "grátis", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["am", "are", "was", "is"], "irregular": ["ordered", "would"], "phrasal": [], "wh": [], "connectors": ["but", "so", "or", "also"], "comparative": []}, "word_meanings": [{"word": "ordered", "meaning": "pediu", "note": ""}, {"word": "vegetable", "meaning": "legume", "note": ""}, {"word": "meat", "meaning": "carne", "note": ""}, {"word": "mistake", "meaning": "erro", "note": ""}, {"word": "vegetarian", "meaning": "vegetariana", "note": ""}, {"word": "right away", "meaning": "agora mesmo", "note": ""}, {"word": "free", "meaning": "grátis", "note": ""}], "exercises": {"grammar": [{"point": "Would you like", "explanation_pt": "'Would you like water, juice or a soda?' oferece opções de maneira educada."}], "multiple_choice": [{"question": "What did the customer order?", "options": ["A vegetable pizza", "A salad", "A soup", "A meat pizza"], "correct_index": 0, "explanation": "Ela pediu pizza de legumes."}, {"question": "What was wrong?", "options": ["The pizza was small", "The pizza had meat", "The pizza was cold", "The pizza was late"], "correct_index": 1, "explanation": "A pizza veio com carne."}, {"question": "How long will the new pizza take?", "options": ["About fifteen minutes", "One hour", "Ten hours", "Two minutes"], "correct_index": 0, "explanation": "Cerca de quinze minutos."}, {"question": "What is free?", "options": ["The dessert", "The pizza", "The drink", "The bread"], "correct_index": 2, "explanation": "A bebida é grátis."}, {"question": "What does the customer choose?", "options": ["Water", "A soda", "Juice", "Tea"], "correct_index": 2, "explanation": "Ela escolhe suco."}], "open_questions": [{"question": "What can you do when a restaurant makes a mistake?", "key_points_pt": ["falar de reclamações educadas"]}, {"question": "Are you a vegetarian? What do you like to eat?", "key_points_pt": ["falar de alimentação"]}]}}, {"level": "B1", "genre": "dialogue", "title": "The Job Offer", "paragraphs": ["\"Congratulations!\" said Priya's friend Nate. \"I heard the company called you this morning.\" \"They did,\" Priya answered. \"They offered me the position, but I haven't accepted it yet. The salary is good, but I would have to move to another city.\"", "\"That is a big decision. What does your family think?\" \"My mother says I should go. She thinks it would be good for my career. My brother says it is too risky.\" Nate nodded. \"And what do you want?\"", "Priya sighed. \"That is the problem. I am excited about the work, but I am afraid of leaving my friends. If I stay, I will always wonder what could have happened.\"", "\"Then maybe you have already answered the question,\" said Nate. \"You said you would wonder. Nobody wonders about a choice they are happy not to make.\" Priya laughed. \"You should write advice columns.\" The next morning, she emailed the company and accepted the job."], "paragraphs_pt": ["\"Parabéns!\", disse o amigo de Priya, Nate. \"Soube que a empresa ligou para você hoje de manhã.\" \"Ligou\", respondeu Priya. \"Ofereceram-me o cargo, mas ainda não aceitei. O salário é bom, mas eu teria que me mudar para outra cidade.\"", "\"É uma grande decisão. O que sua família acha?\" \"Minha mãe diz que eu devo ir. Acha que seria bom para minha carreira. Meu irmão diz que é arriscado demais.\" Nate assentiu. \"E o que você quer?\"", "Priya suspirou. \"Esse é o problema. Estou animada com o trabalho, mas tenho medo de deixar meus amigos. Se eu ficar, sempre vou me perguntar o que poderia ter acontecido.\"", "\"Então talvez você já tenha respondido\", disse Nate. \"Você disse que ia se perguntar. Ninguém se pergunta sobre uma escolha que fica feliz em não fazer.\" Priya riu. \"Você devia escrever colunas de conselhos.\" Na manhã seguinte, ela escreveu à empresa e aceitou o emprego."], "hard_words": ["salary", "career", "risky", "wonder"], "vocab": [{"word": "congratulations", "meaning": "parabéns", "note": ""}, {"word": "position", "meaning": "cargo", "note": ""}, {"word": "salary", "meaning": "salário", "note": ""}, {"word": "decision", "meaning": "decisão", "note": ""}, {"word": "career", "meaning": "carreira", "note": ""}, {"word": "risky", "meaning": "arriscado", "note": ""}, {"word": "wonder", "meaning": "ficar se perguntando", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "be", "am", "are"], "irregular": ["said", "heard", "called", "did", "answered", "offered", "accepted", "would", "should", "nodded", "sighed", "excited", "could", "happened", "laughed", "emailed"], "phrasal": [], "wh": ["what"], "connectors": ["and", "but", "then", "yet", "if"], "comparative": []}, "word_meanings": [{"word": "congratulations", "meaning": "parabéns", "note": ""}, {"word": "position", "meaning": "cargo", "note": ""}, {"word": "salary", "meaning": "salário", "note": ""}, {"word": "decision", "meaning": "decisão", "note": ""}, {"word": "career", "meaning": "carreira", "note": ""}, {"word": "risky", "meaning": "arriscado", "note": ""}, {"word": "wonder", "meaning": "ficar se perguntando", "note": ""}], "exercises": {"grammar": [{"point": "Second conditional", "explanation_pt": "'I would have to move' e 'If I stay, I will always wonder' mostram possibilidades e consequências."}, {"point": "Reported speech", "explanation_pt": "'My mother says I should go' reproduz conselhos."}], "multiple_choice": [{"question": "What did the company offer Priya?", "options": ["A holiday", "A car", "A house", "A position"], "correct_index": 3, "explanation": "Ofereceram um cargo."}, {"question": "What is a problem with the job?", "options": ["The hours are long", "She hates it", "The salary is bad", "She would have to move"], "correct_index": 3, "explanation": "Teria que se mudar."}, {"question": "What does her mother think?", "options": ["She should wait", "She should stay", "She should study", "She should go"], "correct_index": 3, "explanation": "Ela acha que Priya deve ir."}, {"question": "What is Priya afraid of?", "options": ["Leaving her friends", "Her boss", "Losing money", "Being late"], "correct_index": 0, "explanation": "Medo de deixar os amigos."}, {"question": "What does Priya do next morning?", "options": ["Refuses the job", "Calls her mother", "Accepts the job", "Asks for more time"], "correct_index": 2, "explanation": "Ela aceita o emprego."}], "open_questions": [{"question": "How do you make big decisions?", "key_points_pt": ["descrever processos"]}, {"question": "Would you move to another city for work?", "key_points_pt": ["usar condicional"]}]}}, {"level": "B1", "genre": "dialogue", "title": "A Difficult Phone Call", "paragraphs": ["\"Hello, this is Marcus from the Internet Help Line. How can I help you?\" \"Finally!\" said Mrs. Duarte. \"I have been waiting for forty minutes. My Internet has not worked since Monday, and nobody has fixed it.\"", "\"I am very sorry, Mrs. Duarte. Let me see your account. ... I can see that a technician was supposed to visit on Tuesday, but the visit was cancelled by mistake.\" \"Cancelled? Nobody told me!\"", "\"I understand your frustration. I can send someone tomorrow morning between eight and ten. Would that work?\" \"I work from home, so that is fine, but I want a discount for the days without service.\"", "Marcus hesitated. \"I can give you a thirty percent discount this month.\" \"Fifty,\" said Mrs. Duarte. \"Forty,\" he replied. \"Done,\" she said, and the conversation ended with both of them smiling."], "paragraphs_pt": ["\"Olá, aqui é Marcus, da Central de Ajuda de Internet. Como posso ajudar?\" \"Finalmente!\", disse a Sra. Duarte. \"Estou esperando há quarenta minutos. Minha internet não funciona desde segunda e ninguém consertou.\"", "\"Sinto muito, Sra. Duarte. Deixe-me ver sua conta. ... Vejo que um técnico deveria visitá-la na terça, mas a visita foi cancelada por engano.\" \"Cancelada? Ninguém me avisou!\"", "\"Entendo sua frustração. Posso enviar alguém amanhã de manhã entre oito e dez. Serve?\" \"Trabalho em casa, então serve, mas quero um desconto pelos dias sem serviço.\"", "Marcus hesitou. \"Posso dar trinta por cento de desconto neste mês.\" \"Cinquenta\", disse a Sra. Duarte. \"Quarenta\", respondeu ele. \"Fechado\", disse ela, e a conversa terminou com os dois sorrindo."], "hard_words": ["technician", "cancelled", "frustration", "discount"], "vocab": [{"word": "help line", "meaning": "central de ajuda", "note": ""}, {"word": "account", "meaning": "conta", "note": ""}, {"word": "technician", "meaning": "técnico", "note": ""}, {"word": "cancelled", "meaning": "cancelada", "note": ""}, {"word": "frustration", "meaning": "frustração", "note": ""}, {"word": "discount", "meaning": "desconto", "note": ""}, {"word": "hesitated", "meaning": "hesitou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "been", "am", "was"], "irregular": ["said", "worked", "fixed", "supposed", "cancelled", "told", "would", "hesitated", "replied", "done", "ended"], "phrasal": ["work from home"], "wh": ["how"], "connectors": ["so that", "and", "but", "so", "since", "finally"], "comparative": []}, "word_meanings": [{"word": "help line", "meaning": "central de ajuda", "note": ""}, {"word": "account", "meaning": "conta", "note": ""}, {"word": "technician", "meaning": "técnico", "note": ""}, {"word": "cancelled", "meaning": "cancelada", "note": ""}, {"word": "frustration", "meaning": "frustração", "note": ""}, {"word": "discount", "meaning": "desconto", "note": ""}, {"word": "hesitated", "meaning": "hesitou", "note": ""}], "exercises": {"grammar": [{"point": "Present perfect continuous", "explanation_pt": "'I have been waiting for forty minutes' mostra uma ação que começou no passado e continua."}, {"point": "Was supposed to", "explanation_pt": "'a technician was supposed to visit' fala de uma expectativa que não aconteceu."}], "multiple_choice": [{"question": "How long has Mrs. Duarte been waiting?", "options": ["Forty minutes", "Ten minutes", "Four days", "Four hours"], "correct_index": 0, "explanation": "Ela espera há quarenta minutos."}, {"question": "When did the Internet stop working?", "options": ["On Friday", "On Sunday", "Today", "On Monday"], "correct_index": 3, "explanation": "Parou na segunda."}, {"question": "What happened to the visit?", "options": ["It was cancelled by mistake", "It was moved to Friday", "She refused", "The technician was late"], "correct_index": 0, "explanation": "A visita foi cancelada por engano."}, {"question": "When can someone come?", "options": ["Tomorrow morning", "Today", "Next week", "Tonight"], "correct_index": 0, "explanation": "Amanhã de manhã."}, {"question": "What discount do they agree on?", "options": ["Forty percent", "Fifty percent", "Thirty percent", "No discount"], "correct_index": 0, "explanation": "Chegam a quarenta por cento."}], "open_questions": [{"question": "What makes customer service good?", "key_points_pt": ["citar paciência e solução"]}, {"question": "Have you ever negotiated a price?", "key_points_pt": ["contar uma experiência"]}]}}, {"level": "B2", "genre": "dialogue", "title": "The Interview Question", "paragraphs": ["\"Tell me about a time you failed,\" said the interviewer, leaning back in her chair. Daniel had prepared for most questions, but not this one. For a moment he considered offering the usual answer, a harmless story about being too perfectionist.", "\"To be honest,\" he said, \"the most important failure I had was last year. I led a project to redesign our company's website, and I promised the client it would be ready in three months. I didn't consult my team, and we delivered it six weeks late.\"", "\"What did you learn?\" she asked. \"That a deadline is a promise made on behalf of other people. Now I never commit to a date without asking those who will do the work. And when something goes wrong, I tell the client immediately instead of hoping it will resolve itself.\"", "The interviewer smiled for the first time. \"Most candidates give me a polished answer that teaches me nothing. Yours was uncomfortable, and that is exactly why I believe it.\" Daniel left the room unsure if he had got the job, but certain that he had told the truth."], "paragraphs_pt": ["\"Conte-me sobre uma vez em que você fracassou\", disse a entrevistadora, recostando-se na cadeira. Daniel se preparara para a maioria das perguntas, mas não para essa. Por um momento, considerou dar a resposta de sempre, uma história inofensiva sobre ser perfeccionista demais.", "\"Para ser sincero\", disse, \"o fracasso mais importante que tive foi no ano passado. Liderei um projeto para redesenhar o site da empresa e prometi ao cliente que estaria pronto em três meses. Não consultei minha equipe e entregamos seis semanas atrasados.\"", "\"O que você aprendeu?\", perguntou ela. \"Que um prazo é uma promessa feita em nome de outras pessoas. Agora nunca me comprometo com uma data sem perguntar a quem vai fazer o trabalho. E, quando algo dá errado, aviso o cliente imediatamente em vez de esperar que se resolva sozinho.\"", "A entrevistadora sorriu pela primeira vez. \"A maioria dos candidatos me dá uma resposta polida que não me ensina nada. A sua foi desconfortável, e é exatamente por isso que acredito nela.\" Daniel saiu da sala sem saber se conseguira o emprego, mas certo de que dissera a verdade."], "hard_words": ["perfectionist", "deadline", "commit", "polished"], "vocab": [{"word": "interviewer", "meaning": "entrevistador(a)", "note": ""}, {"word": "perfectionist", "meaning": "perfeccionista", "note": ""}, {"word": "redesign", "meaning": "redesenhar", "note": ""}, {"word": "consult", "meaning": "consultar", "note": ""}, {"word": "deadline", "meaning": "prazo", "note": ""}, {"word": "commit", "meaning": "comprometer-se", "note": ""}, {"word": "polished", "meaning": "polida", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["being", "be", "was", "is"], "irregular": ["failed", "said", "had", "prepared", "considered", "led", "promised", "would", "delivered", "did", "asked", "made", "smiled", "polished", "left", "got", "told"], "phrasal": ["leaning back", "goes wrong"], "wh": ["who", "what", "when", "why"], "connectors": ["and", "but", "instead", "when", "if"], "comparative": []}, "word_meanings": [{"word": "interviewer", "meaning": "entrevistador(a)", "note": ""}, {"word": "perfectionist", "meaning": "perfeccionista", "note": ""}, {"word": "redesign", "meaning": "redesenhar", "note": ""}, {"word": "consult", "meaning": "consultar", "note": ""}, {"word": "deadline", "meaning": "prazo", "note": ""}, {"word": "commit", "meaning": "comprometer-se", "note": ""}, {"word": "polished", "meaning": "polida", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Daniel had prepared for most questions' indica uma preparação anterior à pergunta."}, {"point": "Instead of + ing", "explanation_pt": "'instead of hoping it will resolve itself' mostra o que se faz no lugar de outra coisa."}], "multiple_choice": [{"question": "What does the interviewer ask?", "options": ["About salary", "About his hobbies", "About his family", "About a failure"], "correct_index": 3, "explanation": "Ela pergunta sobre um fracasso."}, {"question": "What was Daniel's project?", "options": ["Opening a shop", "Writing a book", "Redesigning a website", "Building a house"], "correct_index": 2, "explanation": "Redesenhar o site da empresa."}, {"question": "What was his mistake?", "options": ["He lost the client", "He lied", "He quit", "He didn't consult his team"], "correct_index": 3, "explanation": "Não consultou a equipe."}, {"question": "What does he do now?", "options": ["Works alone", "Asks the team before promising a date", "Delays projects", "Avoids deadlines"], "correct_index": 1, "explanation": "Pergunta à equipe antes de prometer."}, {"question": "Why does the interviewer believe him?", "options": ["He was famous", "He was polished", "His answer was uncomfortable and honest", "He was funny"], "correct_index": 2, "explanation": "A resposta honesta foi desconfortável."}], "open_questions": [{"question": "How would you answer a question about failure?", "key_points_pt": ["planejar uma resposta honesta"]}, {"question": "Why is it hard to admit mistakes at work?", "key_points_pt": ["discutir medo e reputação"]}]}}, {"level": "B2", "genre": "dialogue", "title": "Moving Back Home", "paragraphs": ["\"I'm not saying you have to stay forever,\" said Rosa's father, folding the newspaper. \"I'm saying that nobody should pay that much rent for a room without a window.\" Rosa, twenty-seven, stood in the hallway with two suitcases and a feeling that she had failed.", "\"It's not failing, it's a pause,\" said her mother, appearing from the kitchen. \"Your room is exactly how you left it.\" \"That's what worries me,\" Rosa muttered. \"I'm an adult. I can't live among my old posters.\"", "\"Then take them down,\" her father said calmly. \"But there's one rule: if you stay here, you save the money you would have spent on rent. Six months, and you will have enough for a deposit on a proper apartment.\"", "Rosa considered the offer. It was practical and generous, and it required her to swallow her pride. \"Fine,\" she said finally. \"Six months. But I'm cooking on Sundays.\" Her mother raised her eyebrows. \"Are you sure? Your last dish set off the smoke alarm.\" They all laughed, and Rosa realised the suitcases felt lighter."], "paragraphs_pt": ["\"Não estou dizendo que você precisa ficar para sempre\", disse o pai de Rosa, dobrando o jornal. \"Estou dizendo que ninguém deveria pagar tanto aluguel por um quarto sem janela.\" Rosa, de vinte e sete anos, estava no corredor com duas malas e a sensação de ter fracassado.", "\"Não é fracassar, é uma pausa\", disse a mãe, aparecendo da cozinha. \"Seu quarto está exatamente como você deixou.\" \"É isso que me preocupa\", murmurou Rosa. \"Sou adulta. Não posso morar entre meus pôsteres antigos.\"", "\"Então tire-os\", disse o pai com calma. \"Mas há uma regra: se ficar aqui, guarda o dinheiro que gastaria com aluguel. Em seis meses, terá o suficiente para o depósito de um apartamento de verdade.\"", "Rosa considerou a oferta. Era prática e generosa, e exigia que ela engolisse o orgulho. \"Tudo bem\", disse por fim. \"Seis meses. Mas eu cozinho aos domingos.\" A mãe ergueu as sobrancelhas. \"Tem certeza? Seu último prato acionou o alarme de fumaça.\" Todos riram, e Rosa percebeu que as malas estavam mais leves."], "hard_words": ["hallway", "muttered", "deposit", "eyebrows"], "vocab": [{"word": "rent", "meaning": "aluguel", "note": ""}, {"word": "hallway", "meaning": "corredor", "note": ""}, {"word": "suitcases", "meaning": "malas", "note": ""}, {"word": "muttered", "meaning": "murmurou", "note": ""}, {"word": "deposit", "meaning": "depósito, caução", "note": ""}, {"word": "swallow her pride", "meaning": "engolir o orgulho", "note": ""}, {"word": "eyebrows", "meaning": "sobrancelhas", "note": ""}, {"word": "smoke alarm", "meaning": "alarme de fumaça", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was", "are"], "irregular": ["said", "should", "rent", "stood", "had", "failed", "left", "muttered", "would", "spent", "considered", "required", "raised", "laughed", "realised", "felt"], "phrasal": ["set off", "take them down"], "wh": ["what", "how"], "connectors": ["and", "but", "then", "finally", "if"], "comparative": []}, "word_meanings": [{"word": "rent", "meaning": "aluguel", "note": ""}, {"word": "hallway", "meaning": "corredor", "note": ""}, {"word": "suitcases", "meaning": "malas", "note": ""}, {"word": "muttered", "meaning": "murmurou", "note": ""}, {"word": "deposit", "meaning": "depósito, caução", "note": ""}, {"word": "swallow her pride", "meaning": "engolir o orgulho", "note": ""}, {"word": "eyebrows", "meaning": "sobrancelhas", "note": ""}, {"word": "smoke alarm", "meaning": "alarme de fumaça", "note": ""}], "exercises": {"grammar": [{"point": "Conditional zero e first", "explanation_pt": "'If you stay here, you save the money' estabelece uma regra e uma consequência."}, {"point": "Would have + particípio", "explanation_pt": "'the money you would have spent on rent' fala do que se gastaria em outra situação."}], "multiple_choice": [{"question": "Why does Rosa move home?", "options": ["She is sick", "Her rent is too high", "She is bored", "She lost her job"], "correct_index": 1, "explanation": "O aluguel era caro demais."}, {"question": "What does the mother call it?", "options": ["A failure", "A pause", "A holiday", "A mistake"], "correct_index": 1, "explanation": "Ela chama de uma pausa."}, {"question": "What is the father's rule?", "options": ["Pay rent to them", "Find a job fast", "Save the rent money", "Cook daily"], "correct_index": 2, "explanation": "Guardar o dinheiro do aluguel."}, {"question": "How long will Rosa stay?", "options": ["One month", "One week", "Six years", "Six months"], "correct_index": 3, "explanation": "Seis meses."}, {"question": "How does the scene end?", "options": ["With laughter", "With silence", "With an argument", "With tears"], "correct_index": 0, "explanation": "Terminam rindo."}], "open_questions": [{"question": "Is it easier to be independent today or in the past?", "key_points_pt": ["comparar gerações"]}, {"question": "How can families negotiate living together as adults?", "key_points_pt": ["dar sugestões"]}]}}, {"level": "B2", "genre": "dialogue", "title": "An Honest Review", "paragraphs": ["\"Be honest,\" said Tomás, passing his manuscript across the table. \"Is it any good?\" Ingrid had known him for fifteen years, and she knew that he did not want honesty; he wanted reassurance with a respectable disguise.", "\"The first fifty pages are brilliant,\" she said carefully. \"The setting feels alive, and your dialogue is the best I've read in a long time. But the middle drags, and the ending contradicts everything you've built.\"", "Tomás said nothing for a while. \"You hate it.\" \"I didn't say that. I said it can be better. If I didn't care about it, I would have told you it was wonderful and let you send it to agents.\" He smiled bitterly. \"That is exactly what my other friends did.\"", "\"Then they were kind,\" said Ingrid, \"and I'm trying to be useful. Those are different things.\" Weeks later, Tomás sent her a new version with a different ending and a note: \"Thank you for ruining my weekend. It was worth it.\""], "paragraphs_pt": ["\"Seja sincera\", disse Tomás, passando o manuscrito pela mesa. \"Está bom?\" Ingrid o conhecia havia quinze anos e sabia que ele não queria sinceridade; queria tranquilização com um disfarce respeitável.", "\"As primeiras cinquenta páginas são brilhantes\", disse ela com cuidado. \"O cenário parece vivo e seu diálogo é o melhor que li em muito tempo. Mas o meio se arrasta e o final contradiz tudo o que você construiu.\"", "Tomás ficou calado por um tempo. \"Você odiou.\" \"Não disse isso. Disse que pode ficar melhor. Se eu não me importasse, teria dito que estava maravilhoso e deixado você enviar a agentes.\" Ele sorriu com amargura. \"Foi exatamente o que meus outros amigos fizeram.\"", "\"Então foram gentis\", disse Ingrid, \"e eu estou tentando ser útil. São coisas diferentes.\" Semanas depois, Tomás enviou a ela uma nova versão com outro final e um bilhete: \"Obrigado por estragar meu fim de semana. Valeu a pena.\""], "hard_words": ["manuscript", "reassurance", "drags", "contradicts"], "vocab": [{"word": "manuscript", "meaning": "manuscrito", "note": ""}, {"word": "reassurance", "meaning": "tranquilização", "note": ""}, {"word": "disguise", "meaning": "disfarce", "note": ""}, {"word": "brilliant", "meaning": "brilhante", "note": ""}, {"word": "drags", "meaning": "se arrasta", "note": ""}, {"word": "contradicts", "meaning": "contradiz", "note": ""}, {"word": "bitterly", "meaning": "com amargura", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "is", "are", "was", "were"], "irregular": ["said", "had", "known", "knew", "did", "wanted", "built", "would", "told", "smiled", "sent"], "phrasal": [], "wh": ["what"], "connectors": ["and", "but", "while", "then", "if"], "comparative": []}, "word_meanings": [{"word": "manuscript", "meaning": "manuscrito", "note": ""}, {"word": "reassurance", "meaning": "tranquilização", "note": ""}, {"word": "disguise", "meaning": "disfarce", "note": ""}, {"word": "brilliant", "meaning": "brilhante", "note": ""}, {"word": "drags", "meaning": "se arrasta", "note": ""}, {"word": "contradicts", "meaning": "contradiz", "note": ""}, {"word": "bitterly", "meaning": "com amargura", "note": ""}], "exercises": {"grammar": [{"point": "Second and third conditionals", "explanation_pt": "'If I didn't care, I would have told you' mistura hipótese presente e consequência passada."}, {"point": "Contrastes com but", "explanation_pt": "'brilliant... But the middle drags' equilibra elogio e crítica."}], "multiple_choice": [{"question": "What does Tomás ask Ingrid?", "options": ["If his manuscript is good", "For money", "For a ride", "For a job"], "correct_index": 0, "explanation": "Ele pergunta se o manuscrito é bom."}, {"question": "What does Ingrid praise?", "options": ["The first pages and dialogue", "The title", "The cover", "The ending"], "correct_index": 0, "explanation": "Ela elogia as primeiras páginas e o diálogo."}, {"question": "What is wrong with the story?", "options": ["The middle drags and the ending contradicts it", "It is copied", "The characters are boring", "It is too short"], "correct_index": 0, "explanation": "O meio se arrasta e o final contradiz."}, {"question": "How did his other friends react?", "options": ["They did not read", "They said it was bad", "They said it was wonderful", "They were angry"], "correct_index": 2, "explanation": "Foram só gentis."}, {"question": "What does Tomás do in the end?", "options": ["Gives up", "Moves away", "Argues", "Writes a new ending"], "correct_index": 3, "explanation": "Escreve um final novo."}], "open_questions": [{"question": "Is honest feedback always better than kind feedback?", "key_points_pt": ["defender uma opinião"]}, {"question": "How do you give criticism without hurting someone?", "key_points_pt": ["sugerir técnicas"]}]}}, {"level": "C1", "genre": "dialogue", "title": "The Negotiation", "paragraphs": ["\"Let's be clear about what each of us wants,\" said Ms. Adeyemi, placing her pen on the table with deliberate care. \"Your company wants to acquire ours without raising the issue of layoffs. We want a guarantee that our staff will keep their positions for at least two years.\"", "Mr. Kessler leaned forward. \"A guarantee is a strong word. Markets shift. Surely you appreciate that no responsible executive can promise stability in perpetuity.\" \"I'm not asking for perpetuity,\" she replied. \"Two years is hardly a lifetime. If you're unwilling to commit to that, I begin to wonder whether you intend to honour any of it.\"", "The silence that followed was not hostile but calculating. Kessler had come expecting to bargain over price; he had not foreseen that his counterpart would treat the price as secondary. \"Suppose I offered eighteen months with a severance clause,\" he said. \"Suppose I accepted twenty-four months with the same clause,\" she countered.", "They shook hands an hour later, each convinced they had conceded the least. Only Ms. Adeyemi knew that the severance clause, which she had treated as a minor technicality, was the very safeguard she had come to obtain."], "paragraphs_pt": ["\"Sejamos claros sobre o que cada um quer\", disse a Sra. Adeyemi, pousando a caneta sobre a mesa com cuidado deliberado. \"Sua empresa quer adquirir a nossa sem levantar a questão das demissões. Queremos uma garantia de que nossos funcionários manterão os cargos por pelo menos dois anos.\"", "O Sr. Kessler inclinou-se para a frente. \"Garantia é uma palavra forte. Os mercados mudam. Certamente a senhora entende que nenhum executivo responsável pode prometer estabilidade perpétua.\" \"Não peço perpetuidade\", respondeu ela. \"Dois anos mal são uma vida. Se o senhor não quer se comprometer com isso, começo a me perguntar se pretende honrar algo.\"", "O silêncio que se seguiu não era hostil, mas calculista. Kessler viera esperando negociar o preço; não previra que sua interlocutora trataria o preço como secundário. \"Suponha que eu oferecesse dezoito meses com uma cláusula de rescisão\", disse. \"Suponha que eu aceitasse vinte e quatro meses com a mesma cláusula\", rebateu ela.", "Apertaram as mãos uma hora depois, cada um convencido de ter cedido menos. Só a Sra. Adeyemi sabia que a cláusula de rescisão, que ela tratara como detalhe técnico, era exatamente a salvaguarda que viera obter."], "hard_words": ["acquire", "perpetuity", "calculating", "safeguard"], "vocab": [{"word": "acquire", "meaning": "adquirir", "note": ""}, {"word": "layoffs", "meaning": "demissões", "note": ""}, {"word": "perpetuity", "meaning": "perpetuidade", "note": ""}, {"word": "hostile", "meaning": "hostil", "note": ""}, {"word": "calculating", "meaning": "calculista", "note": ""}, {"word": "counterpart", "meaning": "interlocutor, contraparte", "note": ""}, {"word": "severance", "meaning": "rescisão, indenização", "note": ""}, {"word": "safeguard", "meaning": "salvaguarda", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "is", "was"], "irregular": ["said", "leaned", "replied", "followed", "had", "foreseen", "would", "offered", "accepted", "countered", "shook", "convinced", "conceded", "knew", "treated"], "phrasal": ["leaned forward", "shook hands"], "wh": ["what", "which"], "connectors": ["but", "if", "as"], "comparative": []}, "word_meanings": [{"word": "acquire", "meaning": "adquirir", "note": ""}, {"word": "layoffs", "meaning": "demissões", "note": ""}, {"word": "perpetuity", "meaning": "perpetuidade", "note": ""}, {"word": "hostile", "meaning": "hostil", "note": ""}, {"word": "calculating", "meaning": "calculista", "note": ""}, {"word": "counterpart", "meaning": "interlocutor, contraparte", "note": ""}, {"word": "severance", "meaning": "rescisão, indenização", "note": ""}, {"word": "safeguard", "meaning": "salvaguarda", "note": ""}], "exercises": {"grammar": [{"point": "Suppose + passado", "explanation_pt": "'Suppose I offered eighteen months' apresenta uma hipótese para negociar."}, {"point": "Hardly", "explanation_pt": "'Two years is hardly a lifetime' significa quase nada, com ironia."}], "multiple_choice": [{"question": "What does Ms. Adeyemi want?", "options": ["A new CEO", "A bigger office", "A higher price", "A two-year job guarantee"], "correct_index": 3, "explanation": "Garantia de dois anos de emprego."}, {"question": "How does Kessler first respond?", "options": ["He laughs", "He leaves", "He agrees", "Guarantees are too strong"], "correct_index": 3, "explanation": "Ele diz que garantia é uma palavra forte."}, {"question": "What had Kessler expected?", "options": ["To fire people", "To sign immediately", "To lose", "To bargain over price"], "correct_index": 3, "explanation": "Esperava negociar o preço."}, {"question": "What do they agree on?", "options": ["Eighteen months only", "Five years", "Twenty-four months with severance", "No guarantee"], "correct_index": 2, "explanation": "Vinte e quatro meses com cláusula de rescisão."}, {"question": "What was Ms. Adeyemi's real goal?", "options": ["The silence", "The severance clause", "The handshake", "The price"], "correct_index": 1, "explanation": "A cláusula era a salvaguarda."}], "open_questions": [{"question": "What makes a negotiation successful?", "key_points_pt": ["discutir interesses e concessões"]}, {"question": "Is it ethical to hide your real priorities?", "key_points_pt": ["debater ética"]}]}}, {"level": "C1", "genre": "dialogue", "title": "The Retirement Dinner", "paragraphs": ["\"To Margaret,\" said the director, raising his glass, \"who taught us that a good teacher is not someone who has answers, but someone who asks better questions.\" Applause rippled through the room, and Margaret, who had hoped to slip away unnoticed, found herself smiling with the practised grace of a woman who had given many speeches.", "Afterwards, a young colleague, Hana, approached her at the buffet. \"I hope you don't mind my asking,\" she said, \"but aren't you afraid? Thirty-five years in the same school, and tomorrow, nothing.\" Margaret considered the question seriously. \"I was terrified last month. Now I think I'm afraid of the wrong thing.\"", "\"Which is?\" \"That I will be useless. But usefulness isn't a job title. It's what you do with your attention.\" She paused. \"I intend to learn Portuguese and volunteer at the library. Ask me in a year whether I was right.\"", "Hana laughed, but her laughter faded as she realised how rarely she had imagined her own future beyond the next term. She went home that night and, for the first time in months, made a list that had nothing to do with grading."], "paragraphs_pt": ["\"À Margaret\", disse o diretor, erguendo a taça, \"que nos ensinou que um bom professor não é quem tem respostas, mas quem faz perguntas melhores.\" Os aplausos correram pela sala, e Margaret, que esperava escapulir sem ser notada, viu-se sorrindo com a graça treinada de quem fez muitos discursos.", "Depois, uma jovem colega, Hana, aproximou-se dela no bufê. \"Espero que não se importe de eu perguntar\", disse, \"mas a senhora não tem medo? Trinta e cinco anos na mesma escola e amanhã, nada.\" Margaret considerou a pergunta com seriedade. \"Eu estava aterrorizada no mês passado. Agora acho que tenho medo da coisa errada.\"", "\"Qual?\" \"De ser inútil. Mas utilidade não é título de cargo. É o que você faz com sua atenção.\" Fez uma pausa. \"Pretendo aprender português e ser voluntária na biblioteca. Pergunte-me em um ano se eu estava certa.\"", "Hana riu, mas o riso se apagou quando percebeu quão raramente imaginara seu próprio futuro além do próximo semestre. Voltou para casa naquela noite e, pela primeira vez em meses, fez uma lista que nada tinha a ver com correção de provas."], "hard_words": ["rippled", "practised", "terrified", "faded"], "vocab": [{"word": "rippled", "meaning": "correu, ondulou", "note": ""}, {"word": "practised", "meaning": "treinada", "note": ""}, {"word": "terrified", "meaning": "aterrorizada", "note": ""}, {"word": "useless", "meaning": "inútil", "note": ""}, {"word": "volunteer", "meaning": "ser voluntário", "note": ""}, {"word": "faded", "meaning": "apagou-se", "note": ""}, {"word": "grading", "meaning": "corrigir provas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was", "be"], "irregular": ["said", "taught", "rippled", "had", "hoped", "found", "practised", "given", "approached", "considered", "terrified", "paused", "laughed", "faded", "realised", "imagined", "went", "made"], "phrasal": ["slip away"], "wh": ["who", "what", "how", "which"], "connectors": ["and", "but", "as"], "comparative": []}, "word_meanings": [{"word": "rippled", "meaning": "correu, ondulou", "note": ""}, {"word": "practised", "meaning": "treinada", "note": ""}, {"word": "terrified", "meaning": "aterrorizada", "note": ""}, {"word": "useless", "meaning": "inútil", "note": ""}, {"word": "volunteer", "meaning": "ser voluntário", "note": ""}, {"word": "faded", "meaning": "apagou-se", "note": ""}, {"word": "grading", "meaning": "corrigir provas", "note": ""}], "exercises": {"grammar": [{"point": "Not... but", "explanation_pt": "'not someone who has answers, but someone who asks better questions' define por contraste."}, {"point": "Intend to", "explanation_pt": "'I intend to learn Portuguese' expressa um plano firme."}], "multiple_choice": [{"question": "What does the director toast to?", "options": ["A good teacher asks better questions", "The school's history", "Margaret's salary", "A new building"], "correct_index": 0, "explanation": "A um bom professor que faz perguntas melhores."}, {"question": "How long was Margaret at the school?", "options": ["Five years", "Thirty-five years", "Fifteen years", "Two years"], "correct_index": 1, "explanation": "Trinta e cinco anos."}, {"question": "What is Margaret afraid of now?", "options": ["Being old", "Being useless", "Being late", "Being poor"], "correct_index": 1, "explanation": "Ela teme ser inútil."}, {"question": "What will she do after retiring?", "options": ["Travel the world", "Open a school", "Learn Portuguese and volunteer", "Write a book"], "correct_index": 2, "explanation": "Aprender português e ser voluntária."}, {"question": "How does Hana change?", "options": ["She thinks about her own future", "She quits", "She retires", "She argues"], "correct_index": 0, "explanation": "Ela pensa no próprio futuro."}], "open_questions": [{"question": "What gives a person's life usefulness after work?", "key_points_pt": ["refletir sobre propósito"]}, {"question": "How do you plan for big life transitions?", "key_points_pt": ["descrever estratégias"]}]}}, {"level": "C1", "genre": "dialogue", "title": "The Apology", "paragraphs": ["\"I'd rather you heard it from me,\" said Felix, standing in the doorway with a stiffness that suggested he had rehearsed this scene in the car. \"Last week, I told the board that the delay was your fault. It wasn't. It was mine.\"", "Noor put down her coffee. For a moment she was tempted to feel vindicated, but what she felt was something more complicated: relief that the truth had surfaced, and an unease that it had taken so long. \"Why now?\" she asked. \"Why not simply let it fade?\"", "\"Because you would have known, eventually, and then every compliment I offered you would have sounded like a bribe.\" Felix swallowed. \"I'm not asking you to forgive me. I'm asking you to let me correct the record, publicly, at Monday's meeting.\"", "Noor studied him. Apologies, she had noticed, tended to come in two varieties: those designed to relieve the speaker and those designed to repair the damage. \"Monday is fine,\" she said, \"but don't make it a performance. Just say what happened.\" On Monday, he did, in four plain sentences, and nobody in the room looked away."], "paragraphs_pt": ["\"Prefiro que você ouça de mim\", disse Felix, parado à porta com uma rigidez que sugeria ter ensaiado a cena no carro. \"Na semana passada, disse à diretoria que o atraso foi culpa sua. Não foi. Foi minha.\"", "Noor pousou o café. Por um instante, teve a tentação de se sentir vingada, mas o que sentiu foi algo mais complicado: alívio por a verdade ter vindo à tona e desconforto por ter demorado tanto. \"Por que agora?\", perguntou. \"Por que não deixar isso se apagar?\"", "\"Porque você acabaria sabendo, e então todo elogio que eu lhe fizesse soaria como suborno.\" Felix engoliu em seco. \"Não estou pedindo que me perdoe. Estou pedindo que me deixe corrigir o registro, publicamente, na reunião de segunda.\"", "Noor o estudou. Pedidos de desculpas, notara, costumavam vir em duas variedades: os feitos para aliviar quem fala e os feitos para reparar o dano. \"Segunda está bem\", disse, \"mas não faça disso um espetáculo. Diga só o que aconteceu.\" Na segunda, ele o fez, em quatro frases simples, e ninguém na sala desviou o olhar."], "hard_words": ["rehearsed", "vindicated", "bribe", "repair"], "vocab": [{"word": "stiffness", "meaning": "rigidez", "note": ""}, {"word": "rehearsed", "meaning": "ensaiado", "note": ""}, {"word": "vindicated", "meaning": "vingada, inocentada", "note": ""}, {"word": "surfaced", "meaning": "veio à tona", "note": ""}, {"word": "bribe", "meaning": "suborno", "note": ""}, {"word": "correct the record", "meaning": "corrigir o registro", "note": ""}, {"word": "varieties", "meaning": "variedades", "note": ""}, {"word": "repair", "meaning": "reparar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is"], "irregular": ["heard", "said", "suggested", "had", "rehearsed", "told", "tempted", "vindicated", "felt", "complicated", "surfaced", "taken", "asked", "would", "known", "offered", "sounded", "swallowed", "studied", "noticed", "tended", "designed", "happened", "did", "looked"], "phrasal": ["put down", "looked away"], "wh": ["what", "why"], "connectors": ["and", "but", "because", "so", "then"], "comparative": []}, "word_meanings": [{"word": "stiffness", "meaning": "rigidez", "note": ""}, {"word": "rehearsed", "meaning": "ensaiado", "note": ""}, {"word": "vindicated", "meaning": "vingada, inocentada", "note": ""}, {"word": "surfaced", "meaning": "veio à tona", "note": ""}, {"word": "bribe", "meaning": "suborno", "note": ""}, {"word": "correct the record", "meaning": "corrigir o registro", "note": ""}, {"word": "varieties", "meaning": "variedades", "note": ""}, {"word": "repair", "meaning": "reparar", "note": ""}], "exercises": {"grammar": [{"point": "Would rather", "explanation_pt": "'I'd rather you heard it from me' expressa uma preferência sobre o comportamento de outra pessoa."}, {"point": "Past perfect e would have", "explanation_pt": "'every compliment would have sounded like a bribe' mostra uma consequência hipotética no passado."}], "multiple_choice": [{"question": "What does Felix confess?", "options": ["He quit", "He stole money", "He blamed Noor wrongly", "He lost a file"], "correct_index": 2, "explanation": "Culpou Noor injustamente."}, {"question": "What does Noor feel?", "options": ["Relief and unease", "Pure anger", "Boredom", "Pure joy"], "correct_index": 0, "explanation": "Alívio e desconforto."}, {"question": "Why does Felix apologise now?", "options": ["He is angry", "Compliments would sound like bribes", "He is leaving", "He was asked"], "correct_index": 1, "explanation": "Elogios soariam como suborno."}, {"question": "What does Noor ask him to avoid?", "options": ["Saying anything", "Making it a performance", "Speaking Monday", "Naming her"], "correct_index": 1, "explanation": "Que não faça espetáculo."}, {"question": "How does the Monday meeting go?", "options": ["With a vote", "With shouting", "Badly", "Plainly and respectfully"], "correct_index": 3, "explanation": "Ele fala em frases simples e todos o respeitam."}], "open_questions": [{"question": "What makes an apology sincere?", "key_points_pt": ["discutir responsabilidade"]}, {"question": "Is a public apology better than a private one?", "key_points_pt": ["debater"]}]}}, {"level": "C2", "genre": "dialogue", "title": "The Last Seminar", "paragraphs": ["\"You may find,\" said Professor Alder, closing the book he had been pretending to read, \"that the most useful sentence in any language is 'I am not certain.' It is shorter than it looks, and it takes years to say honestly.\" A few students smiled politely, as one does at an old man's aphorisms. Lucía did not smile. She had been waiting all term to disagree.", "\"With respect, Professor, it seems to me that uncertainty is a luxury of those who are already secure. Where I come from, the person who says 'I'm not certain' is dismissed, and the person who speaks with confidence gets the job.\"", "Alder regarded her with the faintly pleased expression of a teacher whose trap has been sprung by the right student. \"A fair objection. But notice that you've described the world's incentives, not its truths. The confident person gets the job; it doesn't follow that they get the answer.\"", "\"And if the job is all that matters?\" Lucía pressed. \"Then, my dear, you have my sympathy and my advice: be confident in public and uncertain in private. The danger lies only in forgetting which is which.\" The bell rang, and the class dispersed, though Lucía lingered with the uneasy sense that she had lost an argument she had been proud to win."], "paragraphs_pt": ["\"Vocês talvez descubram\", disse o professor Alder, fechando o livro que fingia ler, \"que a frase mais útil em qualquer idioma é 'Não tenho certeza.' É mais curta do que parece e leva anos para ser dita com honestidade.\" Alguns alunos sorriram educadamente, como se faz diante dos aforismos de um velho. Lucía não sorriu. Esperara o semestre inteiro para discordar.", "\"Com todo o respeito, professor, parece-me que a incerteza é um luxo de quem já está seguro. De onde venho, quem diz 'não tenho certeza' é dispensado, e quem fala com confiança fica com o emprego.\"", "Alder a observou com a expressão levemente satisfeita de um professor cuja armadilha foi acionada pela aluna certa. \"Uma objeção justa. Mas note que você descreveu os incentivos do mundo, não suas verdades. A pessoa confiante fica com o emprego; não decorre daí que fique com a resposta.\"", "\"E se o emprego for tudo o que importa?\", insistiu Lucía. \"Então, minha cara, você tem minha simpatia e meu conselho: seja confiante em público e incerta em particular. O perigo está só em esquecer qual é qual.\" O sinal tocou, a turma se dispersou, mas Lucía ficou com a sensação inquieta de ter perdido uma discussão que se orgulhava de ter vencido."], "hard_words": ["aphorisms", "uncertainty", "incentives", "lingered"], "vocab": [{"word": "aphorisms", "meaning": "aforismos", "note": ""}, {"word": "uncertainty", "meaning": "incerteza", "note": ""}, {"word": "dismissed", "meaning": "dispensado", "note": ""}, {"word": "regarded", "meaning": "observou", "note": ""}, {"word": "incentives", "meaning": "incentivos", "note": ""}, {"word": "objection", "meaning": "objeção", "note": ""}, {"word": "dispersed", "meaning": "dispersou-se", "note": ""}, {"word": "lingered", "meaning": "demorou-se", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "is", "am", "are", "be"], "irregular": ["said", "had", "smiled", "did", "dismissed", "regarded", "pleased", "sprung", "described", "pressed", "rang", "dispersed", "lingered", "lost"], "phrasal": ["it doesn't follow"], "wh": ["who", "where", "which", "whose"], "connectors": ["and", "but", "though", "then", "if", "as"], "comparative": []}, "word_meanings": [{"word": "aphorisms", "meaning": "aforismos", "note": ""}, {"word": "uncertainty", "meaning": "incerteza", "note": ""}, {"word": "dismissed", "meaning": "dispensado", "note": ""}, {"word": "regarded", "meaning": "observou", "note": ""}, {"word": "incentives", "meaning": "incentivos", "note": ""}, {"word": "objection", "meaning": "objeção", "note": ""}, {"word": "dispersed", "meaning": "dispersou-se", "note": ""}, {"word": "lingered", "meaning": "demorou-se", "note": ""}], "exercises": {"grammar": [{"point": "Inversão e ênfase", "explanation_pt": "'It is shorter than it looks' e 'The danger lies only in forgetting' usam construções que enfatizam."}, {"point": "Not... but", "explanation_pt": "'described the world's incentives, not its truths' contrasta dois conceitos."}], "multiple_choice": [{"question": "What sentence does Alder recommend?", "options": ["I am the best", "I am not certain", "I know everything", "I disagree"], "correct_index": 1, "explanation": "'Não tenho certeza.'"}, {"question": "What does Lucía say about uncertainty?", "options": ["It is a luxury of the secure", "It is rare", "It is always wise", "It is weak"], "correct_index": 0, "explanation": "É um luxo de quem está seguro."}, {"question": "What distinction does Alder make?", "options": ["Public versus private", "Past versus future", "Teachers versus students", "Incentives versus truths"], "correct_index": 3, "explanation": "Incentivos versus verdades."}, {"question": "What is his advice?", "options": ["Be confident in public and uncertain in private", "Always be confident", "Always doubt", "Avoid jobs"], "correct_index": 0, "explanation": "Confiança em público, incerteza em particular."}, {"question": "How does Lucía feel at the end?", "options": ["She is happy", "She feels she lost something she won", "She is bored", "She is angry"], "correct_index": 1, "explanation": "Sente ter perdido uma discussão que venceu."}], "open_questions": [{"question": "Is it better to appear confident or to be honest about doubt?", "key_points_pt": ["debater"]}, {"question": "What does the professor mean by 'be uncertain in private'?", "key_points_pt": ["interpretar o conselho"]}]}}, {"level": "C2", "genre": "dialogue", "title": "The Interpreter at the Border", "paragraphs": ["\"Tell him,\" said the officer, \"that if he does not answer plainly, I cannot help him.\" The interpreter, a young woman named Zainab, hesitated for a fraction of a second, long enough to hear the cruelty of the register and to choose a gentler one. \"He says that if you can tell us exactly what happened, they will try to help.\"", "The man across the table, who had travelled eleven days to stand there, looked from one face to the other. He did not need a translator to understand the tone; he needed one to be believed. He began to speak, haltingly, then in a rush, and Zainab let the words pass through her like water through a net, keeping nothing, conceding nothing.", "When he mentioned a village that no longer appeared on any map, the officer frowned. \"Ask him to spell it.\" The man spelled it in his own alphabet, and Zainab, who knew that transliteration is a kind of loss, wrote it down three ways, in the hope that one of them would be recognised.", "Afterwards, in the corridor, the officer said, \"You softened my words.\" \"I translated your intention,\" she replied, \"not your temper.\" He looked at her for a long moment, then nodded, not in agreement but in the reluctant acknowledgment of a man who realises the room had been run, quietly, by someone else."], "paragraphs_pt": ["\"Diga a ele\", disse o oficial, \"que, se ele não responder com clareza, não posso ajudá-lo.\" A intérprete, uma jovem chamada Zainab, hesitou por uma fração de segundo, o bastante para ouvir a crueldade do registro e escolher um mais gentil. \"Ele diz que, se o senhor puder nos contar exatamente o que aconteceu, tentarão ajudá-lo.\"", "O homem do outro lado da mesa, que viajara onze dias para estar ali, olhou de um rosto ao outro. Não precisava de tradutor para entender o tom; precisava de um para ser acreditado. Começou a falar, hesitante, depois de supetão, e Zainab deixou as palavras passarem por ela como água por uma rede, sem reter nada, sem conceder nada.", "Quando ele mencionou uma aldeia que já não aparecia em nenhum mapa, o oficial franziu a testa. \"Peça que ele soletre.\" O homem soletrou no próprio alfabeto, e Zainab, que sabia que a transliteração é uma forma de perda, anotou de três maneiras, na esperança de que uma fosse reconhecida.", "Depois, no corredor, o oficial disse: \"Você suavizou minhas palavras.\" \"Traduzi sua intenção\", respondeu ela, \"não seu temperamento.\" Ele a fitou por um longo momento e então assentiu, não em concordância, mas no reconhecimento relutante de quem percebe que a sala fora conduzida, em silêncio, por outra pessoa."], "hard_words": ["register", "haltingly", "transliteration", "reluctant"], "vocab": [{"word": "register", "meaning": "registro (tom)", "note": ""}, {"word": "haltingly", "meaning": "hesitante", "note": ""}, {"word": "conceding", "meaning": "concedendo", "note": ""}, {"word": "transliteration", "meaning": "transliteração", "note": ""}, {"word": "acknowledgment", "meaning": "reconhecimento", "note": ""}, {"word": "reluctant", "meaning": "relutante", "note": ""}, {"word": "frowned", "meaning": "franziu a testa", "note": ""}, {"word": "corridor", "meaning": "corredor", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "is", "been"], "irregular": ["said", "named", "hesitated", "happened", "had", "travelled", "looked", "did", "needed", "believed", "began", "mentioned", "appeared", "frowned", "spelled", "knew", "wrote", "would", "recognised", "softened", "translated", "replied", "nodded"], "phrasal": [], "wh": ["who", "what", "when"], "connectors": ["and", "but", "then", "when", "if"], "comparative": []}, "word_meanings": [{"word": "register", "meaning": "registro (tom)", "note": ""}, {"word": "haltingly", "meaning": "hesitante", "note": ""}, {"word": "conceding", "meaning": "concedendo", "note": ""}, {"word": "transliteration", "meaning": "transliteração", "note": ""}, {"word": "acknowledgment", "meaning": "reconhecimento", "note": ""}, {"word": "reluctant", "meaning": "relutante", "note": ""}, {"word": "frowned", "meaning": "franziu a testa", "note": ""}, {"word": "corridor", "meaning": "corredor", "note": ""}], "exercises": {"grammar": [{"point": "Inversão para ênfase", "explanation_pt": "'Not in agreement but in reluctant acknowledgment' enfatiza a natureza do gesto."}, {"point": "Cleft e relative clauses", "explanation_pt": "'a man who realises the room had been run' e 'a young woman named Zainab' acrescentam informação sobre pessoas."}], "multiple_choice": [{"question": "What does Zainab do with the officer's harsh words?", "options": ["She repeats them exactly", "She softens the tone", "She laughs", "She refuses"], "correct_index": 1, "explanation": "Ela suaviza o tom."}, {"question": "What does the man need from her?", "options": ["To be paid", "To be hidden", "To be believed", "To be taught"], "correct_index": 2, "explanation": "Precisava ser acreditado."}, {"question": "Why does she write the village name three ways?", "options": ["The officer asks", "Transliteration is a kind of loss", "She is bored", "She forgets"], "correct_index": 1, "explanation": "A transliteração perde algo."}, {"question": "What does the officer accuse her of?", "options": ["Lying", "Softening his words", "Being late", "Stealing"], "correct_index": 1, "explanation": "De suavizar suas palavras."}, {"question": "What does Zainab say she translated?", "options": ["His intention, not his temper", "Only facts", "Nothing", "Everything literally"], "correct_index": 0, "explanation": "Ela traduziu a intenção, não o temperamento."}], "open_questions": [{"question": "What responsibilities does an interpreter have beyond words?", "key_points_pt": ["discutir ética de tradução"]}, {"question": "When is a gentler tone more truthful than a literal one?", "key_points_pt": ["debater"]}]}}, {"level": "C2", "genre": "dialogue", "title": "A Conversation with the Future", "paragraphs": ["Mira found the letter in the attic, folded inside a book she had loved at twelve. It was addressed in her own handwriting: \"To the woman I will be.\" She hesitated for a long time before opening it, in the way one hesitates before meeting an old friend whose opinion still matters.", "The girl had asked questions that now seemed almost insolent. \"Are you brave yet? Did you travel? Do you still make lists? Are you kind to Mum?\" Mira laughed, then sat on the floor, because the laughter was not entirely steady. She had been brave in unspectacular ways, travelled to fewer places than promised, and had, to her shame, been impatient with her mother for years.", "She took a pen and wrote beneath the child's questions, in a hand that had grown more careful: \"No, not yet. A little. Always. I am learning.\" It occurred to her that the dialogue would be completed only if the girl, in turn, were allowed to forgive her.", "She did not know whether forgiveness could travel backwards. But that evening she phoned her mother, who had long ago stopped expecting calls, and said nothing of importance for forty minutes. It was the best conversation they had had in years, and the girl in the letter, Mira suspected, would have approved."], "paragraphs_pt": ["Mira achou a carta no sótão, dobrada dentro de um livro que amara aos doze anos. Estava endereçada na própria caligrafia: \"Para a mulher que serei.\" Hesitou por muito tempo antes de abri-la, como se hesita antes de encontrar um velho amigo cuja opinião ainda importa.", "A menina fizera perguntas que agora pareciam quase insolentes. \"Você já é corajosa? Viajou? Ainda faz listas? Você é gentil com a mamãe?\" Mira riu e então sentou no chão, porque o riso não estava totalmente firme. Fora corajosa de maneiras pouco espetaculares, viajara a menos lugares do que prometera e fora, para sua vergonha, impaciente com a mãe durante anos.", "Pegou uma caneta e escreveu embaixo das perguntas da criança, numa letra que se tornara mais cuidadosa: \"Não, ainda não. Um pouco. Sempre. Estou aprendendo.\" Ocorreu-lhe que o diálogo só se completaria se a menina, por sua vez, pudesse perdoá-la.", "Não sabia se o perdão podia viajar para trás. Mas naquela noite telefonou para a mãe, que havia muito deixara de esperar ligações, e não disse nada de importante por quarenta minutos. Foi a melhor conversa que tiveram em anos, e a menina da carta, suspeitava Mira, teria aprovado."], "hard_words": ["insolent", "unspectacular", "forgiveness", "hesitated"], "vocab": [{"word": "handwriting", "meaning": "caligrafia", "note": ""}, {"word": "hesitated", "meaning": "hesitou", "note": ""}, {"word": "insolent", "meaning": "insolente", "note": ""}, {"word": "unspectacular", "meaning": "pouco espetacular", "note": ""}, {"word": "impatient", "meaning": "impaciente", "note": ""}, {"word": "forgiveness", "meaning": "perdão", "note": ""}, {"word": "approved", "meaning": "aprovaria", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "are", "been", "am", "were"], "irregular": ["found", "folded", "had", "loved", "addressed", "hesitated", "asked", "seemed", "did", "laughed", "sat", "travelled", "promised", "took", "wrote", "grown", "occurred", "would", "completed", "allowed", "could", "phoned", "stopped", "said", "suspected", "approved"], "phrasal": ["sat on", "stopped expecting"], "wh": ["who", "whose"], "connectors": ["and", "but", "because", "then", "before", "yet", "still", "if"], "comparative": []}, "word_meanings": [{"word": "handwriting", "meaning": "caligrafia", "note": ""}, {"word": "hesitated", "meaning": "hesitou", "note": ""}, {"word": "insolent", "meaning": "insolente", "note": ""}, {"word": "unspectacular", "meaning": "pouco espetacular", "note": ""}, {"word": "impatient", "meaning": "impaciente", "note": ""}, {"word": "forgiveness", "meaning": "perdão", "note": ""}, {"word": "approved", "meaning": "aprovaria", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect e would have", "explanation_pt": "'would have approved' imagina a reação da menina; 'had been brave' fala de um passado anterior."}, {"point": "Only if inversion", "explanation_pt": "'would be completed only if the girl were allowed' mostra uma condição necessária."}], "multiple_choice": [{"question": "Where did Mira find the letter?", "options": ["In the attic", "In a drawer", "In a car", "In a park"], "correct_index": 0, "explanation": "No sótão."}, {"question": "Who wrote it?", "options": ["A teacher", "Her mother", "Mira at twelve", "A friend"], "correct_index": 2, "explanation": "Escrita por Mira aos doze anos."}, {"question": "What had Mira done badly?", "options": ["She had been impatient with her mother", "She had lied to a friend", "She had quit school", "She had stolen"], "correct_index": 0, "explanation": "Fora impaciente com a mãe."}, {"question": "What does she write?", "options": ["Nothing", "A short honest answer", "A poem", "A long apology"], "correct_index": 1, "explanation": "Respostas curtas e honestas."}, {"question": "What does she do that evening?", "options": ["She phones her mother", "She travels", "She sleeps", "She burns the letter"], "correct_index": 0, "explanation": "Telefona para a mãe."}], "open_questions": [{"question": "What would you ask your twelve-year-old self?", "key_points_pt": ["criar perguntas reflexivas"]}, {"question": "Can people truly forgive themselves? Explain.", "key_points_pt": ["discutir culpa e perdão"]}]}}, {"level": "A1", "genre": "dystopia", "title": "The Gray City", "paragraphs": ["The city is gray. The sky is gray. The houses are gray. Nina lives in a small gray room.", "Every day she goes to work at six. She does not talk. Nobody talks in the city. It is a rule.", "One day Nina sees a red flower in a window. It is the first color she sees. She smiles. She wants more colors."], "paragraphs_pt": ["A cidade é cinza. O céu é cinza. As casas são cinza. Nina mora num quarto pequeno e cinza.", "Todo dia ela vai trabalhar às seis. Ela não fala. Ninguém fala na cidade. É uma regra.", "Um dia Nina vê uma flor vermelha numa janela. É a primeira cor que ela vê. Ela sorri. Ela quer mais cores."], "hard_words": ["gray", "rule", "flower", "color"], "vocab": [{"word": "gray", "meaning": "cinza", "note": ""}, {"word": "sky", "meaning": "céu", "note": ""}, {"word": "room", "meaning": "quarto", "note": ""}, {"word": "rule", "meaning": "regra", "note": ""}, {"word": "flower", "meaning": "flor", "note": ""}, {"word": "window", "meaning": "janela", "note": ""}, {"word": "color", "meaning": "cor", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": [], "comparative": []}, "word_meanings": [{"word": "gray", "meaning": "cinza", "note": ""}, {"word": "sky", "meaning": "céu", "note": ""}, {"word": "room", "meaning": "quarto", "note": ""}, {"word": "rule", "meaning": "regra", "note": ""}, {"word": "flower", "meaning": "flor", "note": ""}, {"word": "window", "meaning": "janela", "note": ""}, {"word": "color", "meaning": "cor", "note": ""}], "exercises": {"grammar": [{"point": "Present simple negative", "explanation_pt": "'She does not talk' e 'Nobody talks' mostram o que acontece ou não acontece sempre."}], "multiple_choice": [{"question": "What color is the city?", "options": ["Gray", "Blue", "Green", "Red"], "correct_index": 0, "explanation": "A cidade é cinza."}, {"question": "What time does Nina go to work?", "options": ["At night", "At ten", "At noon", "At six"], "correct_index": 3, "explanation": "Ela vai às seis."}, {"question": "What is the rule?", "options": ["Everybody runs", "Everybody sings", "Nobody talks", "Nobody works"], "correct_index": 2, "explanation": "A regra é não falar."}, {"question": "What does Nina see?", "options": ["A green tree", "A blue car", "A white bird", "A red flower"], "correct_index": 3, "explanation": "Ela vê uma flor vermelha."}, {"question": "What does she want?", "options": ["More work", "More rules", "More rooms", "More colors"], "correct_index": 3, "explanation": "Ela quer mais cores."}], "open_questions": [{"question": "What color do you like? Why?", "key_points_pt": ["falar de cores"]}, {"question": "What can you do without talking?", "key_points_pt": ["dar exemplos"]}]}}, {"level": "A1", "genre": "dystopia", "title": "No Music", "paragraphs": ["In Leo's country, there is no music. The government says music is bad. Leo is ten years old. He does not know any songs.", "One night he hears a sound. It is his grandmother. She is singing very quietly in the kitchen. \"What is that?\" he asks. \"It is a song,\" she says.", "Leo listens. The song is beautiful. He closes his eyes. \"Teach me, Grandma,\" he says. She smiles and teaches him the song."], "paragraphs_pt": ["No país de Leo, não há música. O governo diz que a música é ruim. Leo tem dez anos. Ele não conhece nenhuma canção.", "Uma noite ele ouve um som. É a avó dele. Ela canta muito baixinho na cozinha. \"O que é isso?\", ele pergunta. \"É uma canção\", ela diz.", "Leo escuta. A canção é linda. Ele fecha os olhos. \"Me ensine, vovó\", diz. Ela sorri e ensina a canção a ele."], "hard_words": ["government", "sound", "quietly", "teach"], "vocab": [{"word": "music", "meaning": "música", "note": ""}, {"word": "government", "meaning": "governo", "note": ""}, {"word": "song", "meaning": "canção", "note": ""}, {"word": "sound", "meaning": "som", "note": ""}, {"word": "grandmother", "meaning": "avó", "note": ""}, {"word": "quietly", "meaning": "baixinho", "note": ""}, {"word": "beautiful", "meaning": "linda", "note": ""}, {"word": "teach", "meaning": "ensinar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": ["what"], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "music", "meaning": "música", "note": ""}, {"word": "government", "meaning": "governo", "note": ""}, {"word": "song", "meaning": "canção", "note": ""}, {"word": "sound", "meaning": "som", "note": ""}, {"word": "grandmother", "meaning": "avó", "note": ""}, {"word": "quietly", "meaning": "baixinho", "note": ""}, {"word": "beautiful", "meaning": "linda", "note": ""}, {"word": "teach", "meaning": "ensinar", "note": ""}], "exercises": {"grammar": [{"point": "There is no", "explanation_pt": "'There is no music' diz que algo não existe."}], "multiple_choice": [{"question": "What is not in Leo's country?", "options": ["Water", "Food", "Music", "School"], "correct_index": 2, "explanation": "Não há música."}, {"question": "How old is Leo?", "options": ["Fifteen", "Ten", "Twenty", "Five"], "correct_index": 1, "explanation": "Leo tem dez anos."}, {"question": "Who is singing?", "options": ["A bird", "His father", "His grandmother", "His teacher"], "correct_index": 2, "explanation": "A avó canta."}, {"question": "Where is she singing?", "options": ["In the garden", "In school", "In the street", "In the kitchen"], "correct_index": 3, "explanation": "Ela canta na cozinha."}, {"question": "What does Leo ask her?", "options": ["To leave", "To teach him", "To stop", "To sleep"], "correct_index": 1, "explanation": "Ele pede que ela o ensine."}], "open_questions": [{"question": "What is your favorite song?", "key_points_pt": ["falar de música"]}, {"question": "Why is music important?", "key_points_pt": ["dar razões"]}]}}, {"level": "A1", "genre": "dystopia", "title": "The Number Game", "paragraphs": ["In this city, people do not have names. They have numbers. Mia is number 482. Her friend is number 119.", "\"Hello, 119,\" says Mia. \"Hello, 482,\" says her friend. They are sad. They want names.", "Mia writes a name on a small paper: \"Mia.\" She shows it to her friend. \"I am Mia,\" she says. Her friend takes the paper. Now he writes \"Ben.\""], "paragraphs_pt": ["Nesta cidade, as pessoas não têm nomes. Elas têm números. Mia é o número 482. A amiga dela é o número 119.", "\"Olá, 119\", diz Mia. \"Olá, 482\", diz a amiga. Elas estão tristes. Querem nomes.", "Mia escreve um nome num papel pequeno: \"Mia.\" Mostra à amiga. \"Eu sou Mia\", diz. A amiga pega o papel. Agora ele escreve \"Ben.\""], "hard_words": ["names", "numbers", "sad", "paper"], "vocab": [{"word": "names", "meaning": "nomes", "note": ""}, {"word": "numbers", "meaning": "números", "note": ""}, {"word": "friend", "meaning": "amigo", "note": ""}, {"word": "sad", "meaning": "triste", "note": ""}, {"word": "paper", "meaning": "papel", "note": ""}, {"word": "writes", "meaning": "escreve", "note": ""}, {"word": "shows", "meaning": "mostra", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are", "am"], "irregular": [], "phrasal": [], "wh": [], "connectors": [], "comparative": []}, "word_meanings": [{"word": "names", "meaning": "nomes", "note": ""}, {"word": "numbers", "meaning": "números", "note": ""}, {"word": "friend", "meaning": "amigo", "note": ""}, {"word": "sad", "meaning": "triste", "note": ""}, {"word": "paper", "meaning": "papel", "note": ""}, {"word": "writes", "meaning": "escreve", "note": ""}, {"word": "shows", "meaning": "mostra", "note": ""}], "exercises": {"grammar": [{"point": "Have", "explanation_pt": "'People do not have names' e 'They have numbers' usam have para posse."}], "multiple_choice": [{"question": "What do people have in this city?", "options": ["Cars", "Names", "Numbers", "Pets"], "correct_index": 2, "explanation": "Eles têm números."}, {"question": "What is Mia's number?", "options": ["100", "250", "119", "482"], "correct_index": 3, "explanation": "Mia é 482."}, {"question": "How do they feel?", "options": ["Tired", "Sad", "Angry", "Happy"], "correct_index": 1, "explanation": "Estão tristes."}, {"question": "What does Mia write?", "options": ["A letter", "A song", "Her name", "A number"], "correct_index": 2, "explanation": "Ela escreve seu nome."}, {"question": "What does her friend write?", "options": ["Ben", "Leo", "Mia", "482"], "correct_index": 0, "explanation": "Ele escreve Ben."}], "open_questions": [{"question": "What is your name? What does it mean?", "key_points_pt": ["falar do nome"]}, {"question": "Why are names important?", "key_points_pt": ["dar opinião"]}]}}, {"level": "A2", "genre": "dystopia", "title": "The Window That Does Not Open", "paragraphs": ["Every apartment in Tower Nine has a window, but no window opens. The government says the air outside is dangerous. Ruth has lived in the tower all her life, and she believes the rule because she has never seen the outside.", "One morning a small bird lands on her window. It looks healthy, and it sings loudly. Ruth watches it for an hour. If the air is dangerous, she thinks, how can the bird live?", "That night she takes a hammer and carefully breaks a small hole in the glass. A warm wind comes in. It smells of rain and grass. Ruth closes her eyes and breathes slowly. She feels fine, and for the first time she wonders what else the government has not told her."], "paragraphs_pt": ["Todo apartamento da Torre Nove tem uma janela, mas nenhuma janela abre. O governo diz que o ar lá fora é perigoso. Ruth mora na torre a vida inteira e acredita na regra porque nunca viu o lado de fora.", "Uma manhã um passarinho pousa na janela dela. Parece saudável e canta alto. Ruth o observa por uma hora. Se o ar é perigoso, pensa, como o pássaro pode viver?", "Naquela noite ela pega um martelo e com cuidado faz um pequeno buraco no vidro. Um vento morno entra. Cheira a chuva e grama. Ruth fecha os olhos e respira devagar. Sente-se bem, e pela primeira vez se pergunta o que mais o governo não contou."], "hard_words": ["dangerous", "healthy", "hammer", "breathes"], "vocab": [{"word": "tower", "meaning": "torre", "note": ""}, {"word": "dangerous", "meaning": "perigoso", "note": ""}, {"word": "believes", "meaning": "acredita", "note": ""}, {"word": "healthy", "meaning": "saudável", "note": ""}, {"word": "hammer", "meaning": "martelo", "note": ""}, {"word": "glass", "meaning": "vidro", "note": ""}, {"word": "breathes", "meaning": "respira", "note": ""}, {"word": "grass", "meaning": "grama", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": ["lived", "seen", "told"], "phrasal": ["comes in", "lands on"], "wh": ["what", "how"], "connectors": ["and", "but", "because", "if"], "comparative": []}, "word_meanings": [{"word": "tower", "meaning": "torre", "note": ""}, {"word": "dangerous", "meaning": "perigoso", "note": ""}, {"word": "believes", "meaning": "acredita", "note": ""}, {"word": "healthy", "meaning": "saudável", "note": ""}, {"word": "hammer", "meaning": "martelo", "note": ""}, {"word": "glass", "meaning": "vidro", "note": ""}, {"word": "breathes", "meaning": "respira", "note": ""}, {"word": "grass", "meaning": "grama", "note": ""}], "exercises": {"grammar": [{"point": "Present perfect", "explanation_pt": "'Ruth has lived in the tower all her life' mostra algo que começou no passado e continua."}, {"point": "If + presente", "explanation_pt": "'If the air is dangerous, how can the bird live?' faz uma pergunta lógica."}], "multiple_choice": [{"question": "What is special about the windows?", "options": ["They are broken", "They are small", "They do not open", "They are red"], "correct_index": 2, "explanation": "Nenhuma janela abre."}, {"question": "What does the government say?", "options": ["The city is closed", "Birds are sick", "The sun is hot", "The outside air is dangerous"], "correct_index": 3, "explanation": "O ar de fora é perigoso."}, {"question": "What lands on Ruth's window?", "options": ["A kite", "A bird", "A bug", "A leaf"], "correct_index": 1, "explanation": "Um passarinho pousa."}, {"question": "What does Ruth do at night?", "options": ["Sleeps", "Calls friends", "Breaks a small hole in the glass", "Writes a letter"], "correct_index": 2, "explanation": "Ela quebra um buraco no vidro."}, {"question": "What does she wonder?", "options": ["Who is the bird", "Why she is tired", "What else the government has not told her", "How to leave"], "correct_index": 2, "explanation": "Ela se pergunta o que mais não foi contado."}], "open_questions": [{"question": "Would you believe a rule you could not test?", "key_points_pt": ["usar condicional simples"]}, {"question": "Why is fresh air important?", "key_points_pt": ["dar razões"]}]}}, {"level": "A2", "genre": "dystopia", "title": "The Ration Cards", "paragraphs": ["In Kai's town, everybody has a ration card. The card tells you how much bread, water and electricity you can use each week. If you use more, the machine at the door turns your lights off.", "Kai's little sister is sick, and she needs more water than the card allows. Kai goes to the market and finds a man who sells extra cards in secret. The man wants Kai's watch, the only gift from his father.", "Kai thinks for a long time. Then he gives the man the watch and takes the cards. At home, his sister drinks and sleeps well. Kai feels sad about the watch but proud of himself. \"Some things are more important than gifts,\" he whispers."], "paragraphs_pt": ["Na cidade de Kai, todos têm um cartão de racionamento. O cartão diz quanto pão, água e eletricidade você pode usar por semana. Se usar mais, a máquina da porta apaga suas luzes.", "A irmãzinha de Kai está doente e precisa de mais água do que o cartão permite. Kai vai ao mercado e encontra um homem que vende cartões extras em segredo. O homem quer o relógio de Kai, o único presente do pai.", "Kai pensa por muito tempo. Então dá o relógio ao homem e pega os cartões. Em casa, a irmã bebe e dorme bem. Kai fica triste pelo relógio, mas orgulhoso de si. \"Algumas coisas são mais importantes que presentes\", sussurra."], "hard_words": ["electricity", "secret", "proud", "whispers"], "vocab": [{"word": "ration card", "meaning": "cartão de racionamento", "note": ""}, {"word": "electricity", "meaning": "eletricidade", "note": ""}, {"word": "machine", "meaning": "máquina", "note": ""}, {"word": "sick", "meaning": "doente", "note": ""}, {"word": "secret", "meaning": "segredo", "note": ""}, {"word": "watch", "meaning": "relógio", "note": ""}, {"word": "proud", "meaning": "orgulhoso", "note": ""}, {"word": "whispers", "meaning": "sussurra", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": ["who", "how"], "connectors": ["and", "but", "then", "if"], "comparative": []}, "word_meanings": [{"word": "ration card", "meaning": "cartão de racionamento", "note": ""}, {"word": "electricity", "meaning": "eletricidade", "note": ""}, {"word": "machine", "meaning": "máquina", "note": ""}, {"word": "sick", "meaning": "doente", "note": ""}, {"word": "secret", "meaning": "segredo", "note": ""}, {"word": "watch", "meaning": "relógio", "note": ""}, {"word": "proud", "meaning": "orgulhoso", "note": ""}, {"word": "whispers", "meaning": "sussurra", "note": ""}], "exercises": {"grammar": [{"point": "Quantifiers: how much / more", "explanation_pt": "'how much bread' pergunta quantidade de coisas não contáveis; 'more water' compara quantidade."}, {"point": "Present simple em regras", "explanation_pt": "'If you use more, the machine turns your lights off' descreve uma regra."}], "multiple_choice": [{"question": "What does the ration card show?", "options": ["Your job", "Where you live", "Your age", "How much you can use"], "correct_index": 3, "explanation": "Mostra quanto você pode usar."}, {"question": "What happens if you use more?", "options": ["Your lights are turned off", "You go to prison", "You lose the card", "You pay money"], "correct_index": 0, "explanation": "As luzes são apagadas."}, {"question": "Who is sick?", "options": ["Kai's sister", "His father", "Kai", "His teacher"], "correct_index": 0, "explanation": "A irmã é quem está doente."}, {"question": "What does the man want?", "options": ["Kai's bike", "Kai's money", "Kai's phone", "Kai's watch"], "correct_index": 3, "explanation": "Quer o relógio."}, {"question": "How does Kai feel in the end?", "options": ["Sad but proud", "Angry", "Bored", "Afraid"], "correct_index": 0, "explanation": "Triste pelo relógio, orgulhoso de si."}], "open_questions": [{"question": "What would you give up for your family?", "key_points_pt": ["usar condicional"]}, {"question": "Why do governments ration things?", "key_points_pt": ["dar razões"]}]}}, {"level": "A2", "genre": "dystopia", "title": "The Library of Silence", "paragraphs": ["There is a library in the old part of the city, and nobody is allowed to enter it. The government says books are dangerous because they give people ideas. They burned most of them years ago.", "Tess is twelve, and she is very curious. One night she finds a small door behind the old church. She opens it and sees hundreds of books on the shelves. They smell like dust and paper.", "She takes one book and reads the first line: \"Once upon a time, there was a girl who asked questions.\" Tess smiles. She puts the book in her bag and decides to come back every night. Nobody will see her. She knows how to be quiet."], "paragraphs_pt": ["Há uma biblioteca na parte antiga da cidade e ninguém tem permissão para entrar. O governo diz que livros são perigosos porque dão ideias às pessoas. Queimaram a maioria deles anos atrás.", "Tess tem doze anos e é muito curiosa. Uma noite ela acha uma pequena porta atrás da igreja velha. Abre e vê centenas de livros nas prateleiras. Eles cheiram a poeira e papel.", "Ela pega um livro e lê a primeira linha: \"Era uma vez uma menina que fazia perguntas.\" Tess sorri. Coloca o livro na bolsa e decide voltar toda noite. Ninguém a verá. Ela sabe ficar quieta."], "hard_words": ["allowed", "burned", "curious", "shelves"], "vocab": [{"word": "library", "meaning": "biblioteca", "note": ""}, {"word": "allowed", "meaning": "permitido", "note": ""}, {"word": "ideas", "meaning": "ideias", "note": ""}, {"word": "burned", "meaning": "queimaram", "note": ""}, {"word": "curious", "meaning": "curiosa", "note": ""}, {"word": "shelves", "meaning": "prateleiras", "note": ""}, {"word": "dust", "meaning": "poeira", "note": ""}, {"word": "quiet", "meaning": "quieta", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are", "was", "be"], "irregular": ["allowed", "burned", "asked"], "phrasal": ["come back"], "wh": ["who", "how"], "connectors": ["and", "because", "once"], "comparative": []}, "word_meanings": [{"word": "library", "meaning": "biblioteca", "note": ""}, {"word": "allowed", "meaning": "permitido", "note": ""}, {"word": "ideas", "meaning": "ideias", "note": ""}, {"word": "burned", "meaning": "queimaram", "note": ""}, {"word": "curious", "meaning": "curiosa", "note": ""}, {"word": "shelves", "meaning": "prateleiras", "note": ""}, {"word": "dust", "meaning": "poeira", "note": ""}, {"word": "quiet", "meaning": "quieta", "note": ""}], "exercises": {"grammar": [{"point": "Be allowed to", "explanation_pt": "'Nobody is allowed to enter' fala de permissão."}, {"point": "Passado simples", "explanation_pt": "'They burned most of them' e 'she opened it' contam o que aconteceu."}], "multiple_choice": [{"question": "What can nobody do?", "options": ["Walk", "Read newspapers", "Enter the library", "Talk"], "correct_index": 2, "explanation": "Ninguém pode entrar na biblioteca."}, {"question": "Why are books dangerous, says the government?", "options": ["They give people ideas", "They are old", "They are heavy", "They are expensive"], "correct_index": 0, "explanation": "Dão ideias às pessoas."}, {"question": "How old is Tess?", "options": ["Fifteen", "Twenty", "Twelve", "Ten"], "correct_index": 2, "explanation": "Tess tem doze anos."}, {"question": "Where is the small door?", "options": ["Inside a house", "Under a bridge", "Behind the school", "Behind the old church"], "correct_index": 3, "explanation": "Atrás da igreja velha."}, {"question": "What does Tess decide?", "options": ["To come back every night", "To tell the police", "To burn the books", "To leave town"], "correct_index": 0, "explanation": "Voltar toda noite."}], "open_questions": [{"question": "What book changed your life?", "key_points_pt": ["falar de livros"]}, {"question": "Is it dangerous to have ideas?", "key_points_pt": ["dar opinião"]}]}}, {"level": "B1", "genre": "dystopia", "title": "The Happiness Index", "paragraphs": ["In Verdana, every citizen carried a bracelet that measured happiness. A green light meant you were content; yellow meant you were \"at risk\"; red meant you had to report to the Clinic. Nobody ever stayed red for long.", "Elena had worn a green bracelet for twenty years, but the truth was that she had not felt happy in many months. She had learned to smile at the right moments and to say \"I'm fine\" before anyone could ask. The bracelet measured her pulse and her expression, not her heart.", "One evening, her neighbour arrived at her door crying, with a red light shining on his wrist. \"They will take me away,\" he whispered. Elena took off her own bracelet and put it on his arm. The light turned green at once.", "For a few hours the two of them sat in the dark, talking honestly for the first time. Elena realised that the system was not measuring happiness at all; it was measuring obedience. She decided that tomorrow she would stop pretending, whatever the colour of her light."], "paragraphs_pt": ["Em Verdana, todo cidadão usava uma pulseira que media a felicidade. Luz verde significava contente; amarela, \"em risco\"; vermelha, que você devia se apresentar à Clínica. Ninguém ficava vermelho por muito tempo.", "Elena usava uma pulseira verde havia vinte anos, mas a verdade era que não se sentia feliz havia muitos meses. Aprendera a sorrir nos momentos certos e a dizer \"estou bem\" antes que alguém perguntasse. A pulseira media seu pulso e sua expressão, não seu coração.", "Numa noite, o vizinho chegou à porta dela chorando, com uma luz vermelha brilhando no pulso. \"Vão me levar\", sussurrou. Elena tirou a própria pulseira e a colocou no braço dele. A luz ficou verde na hora.", "Por algumas horas os dois ficaram sentados no escuro, conversando com honestidade pela primeira vez. Elena percebeu que o sistema não media felicidade de modo algum; media obediência. Decidiu que amanhã pararia de fingir, qualquer que fosse a cor da luz."], "hard_words": ["bracelet", "content", "pulse", "obedience"], "vocab": [{"word": "citizen", "meaning": "cidadão", "note": ""}, {"word": "bracelet", "meaning": "pulseira", "note": ""}, {"word": "measured", "meaning": "media", "note": ""}, {"word": "content", "meaning": "contente", "note": ""}, {"word": "pulse", "meaning": "pulso", "note": ""}, {"word": "expression", "meaning": "expressão", "note": ""}, {"word": "obedience", "meaning": "obediência", "note": ""}, {"word": "pretending", "meaning": "fingindo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was"], "irregular": ["carried", "measured", "meant", "had", "stayed", "worn", "felt", "learned", "could", "arrived", "whispered", "took", "turned", "sat", "realised", "decided", "would"], "phrasal": ["took off"], "wh": ["whatever"], "connectors": ["and", "but", "before", "once"], "comparative": []}, "word_meanings": [{"word": "citizen", "meaning": "cidadão", "note": ""}, {"word": "bracelet", "meaning": "pulseira", "note": ""}, {"word": "measured", "meaning": "media", "note": ""}, {"word": "content", "meaning": "contente", "note": ""}, {"word": "pulse", "meaning": "pulso", "note": ""}, {"word": "expression", "meaning": "expressão", "note": ""}, {"word": "obedience", "meaning": "obediência", "note": ""}, {"word": "pretending", "meaning": "fingindo", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'She had worn a green bracelet for twenty years' mostra algo anterior ao momento da história."}, {"point": "Reported speech", "explanation_pt": "'She decided that tomorrow she would stop pretending' reproduz uma decisão."}], "multiple_choice": [{"question": "What did the bracelet measure?", "options": ["Time", "Money", "Happiness", "Health only"], "correct_index": 2, "explanation": "Media a felicidade."}, {"question": "What did red mean?", "options": ["You are safe", "You are rich", "Report to the Clinic", "You can travel"], "correct_index": 2, "explanation": "Vermelho = apresentar-se à Clínica."}, {"question": "How did Elena really feel?", "options": ["Excited", "Angry", "Very happy", "Unhappy for months"], "correct_index": 3, "explanation": "Estava infeliz havia meses."}, {"question": "What did Elena do for the neighbour?", "options": ["Ran away", "Called the police", "Gave him her bracelet", "Ignored him"], "correct_index": 2, "explanation": "Deu a pulseira a ele."}, {"question": "What did she realise?", "options": ["She was sick", "The system measured obedience", "The system was perfect", "Her neighbour lied"], "correct_index": 1, "explanation": "Mediam obediência."}], "open_questions": [{"question": "Can happiness be measured?", "key_points_pt": ["debater"]}, {"question": "Would you wear such a bracelet?", "key_points_pt": ["usar condicional"]}]}}, {"level": "B1", "genre": "dystopia", "title": "The Last Tree", "paragraphs": ["By the year 2150, there was only one tree left in the whole world. It stood inside a glass building in the capital, protected by guards, and visitors paid a lot of money to look at it for five minutes. Children learned its name in school: \"oak.\"", "Samir was a guard at the building. Every evening, when the visitors left, he stayed for a few minutes in front of the glass. He had never touched a tree. He did not know what the bark felt like or what the leaves sounded like in the wind.", "One night, a girl of about ten years old slipped past security and stood next to him. \"Is it really alive?\" she asked. Samir didn't know what to say. He remembered an old rule: guards must not open the glass.", "He thought about the rule, about the money, and about the girl's face. Then he took a key from his belt and opened the door. The two of them touched the bark together. \"It feels warm,\" the girl said. Samir lost his job the next day, but he never regretted it."], "paragraphs_pt": ["Em 2150, havia apenas uma árvore em todo o mundo. Ficava dentro de um prédio de vidro na capital, protegida por guardas, e os visitantes pagavam muito dinheiro para olhá-la por cinco minutos. As crianças aprendiam seu nome na escola: \"carvalho.\"", "Samir era guarda do prédio. Toda noite, quando os visitantes iam embora, ele ficava alguns minutos diante do vidro. Nunca tocara numa árvore. Não sabia como era a casca ao tato nem o som das folhas ao vento.", "Uma noite, uma menina de uns dez anos passou pela segurança sem ser vista e ficou ao lado dele. \"Ela está mesmo viva?\", perguntou. Samir não sabia o que dizer. Lembrou de uma regra antiga: guardas não devem abrir o vidro.", "Pensou na regra, no dinheiro e no rosto da menina. Então tirou uma chave do cinto e abriu a porta. Os dois tocaram a casca juntos. \"É quente\", disse a menina. Samir perdeu o emprego no dia seguinte, mas nunca se arrependeu."], "hard_words": ["guard", "bark", "alive", "regretted"], "vocab": [{"word": "guard", "meaning": "guarda", "note": ""}, {"word": "glass", "meaning": "vidro", "note": ""}, {"word": "bark", "meaning": "casca (de árvore)", "note": ""}, {"word": "leaves", "meaning": "folhas", "note": ""}, {"word": "slipped past", "meaning": "passou sem ser visto", "note": ""}, {"word": "alive", "meaning": "viva", "note": ""}, {"word": "belt", "meaning": "cinto", "note": ""}, {"word": "regretted", "meaning": "arrependeu-se", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is"], "irregular": ["left", "stood", "protected", "paid", "learned", "stayed", "had", "touched", "did", "felt", "sounded", "slipped", "asked", "remembered", "thought", "took", "opened", "said", "lost", "regretted"], "phrasal": ["slipped past"], "wh": ["what", "when"], "connectors": ["and", "but", "then", "when", "or"], "comparative": []}, "word_meanings": [{"word": "guard", "meaning": "guarda", "note": ""}, {"word": "glass", "meaning": "vidro", "note": ""}, {"word": "bark", "meaning": "casca (de árvore)", "note": ""}, {"word": "leaves", "meaning": "folhas", "note": ""}, {"word": "slipped past", "meaning": "passou sem ser visto", "note": ""}, {"word": "alive", "meaning": "viva", "note": ""}, {"word": "belt", "meaning": "cinto", "note": ""}, {"word": "regretted", "meaning": "arrependeu-se", "note": ""}], "exercises": {"grammar": [{"point": "Past continuous e simples", "explanation_pt": "'He stood... when the visitors left' combina estado e ação."}, {"point": "Must not", "explanation_pt": "'guards must not open the glass' expressa proibição."}], "multiple_choice": [{"question": "How many trees are left?", "options": ["One", "Ten", "Two hundred", "None"], "correct_index": 0, "explanation": "Só restava uma árvore."}, {"question": "Where is it?", "options": ["In a glass building", "In a forest", "In a park", "In a school"], "correct_index": 0, "explanation": "Num prédio de vidro."}, {"question": "What was Samir's job?", "options": ["Gardener", "Driver", "Teacher", "Guard"], "correct_index": 3, "explanation": "Ele era guarda."}, {"question": "What did Samir do?", "options": ["Cut the tree", "Called the police", "Hid", "Opened the glass"], "correct_index": 3, "explanation": "Ele abriu o vidro."}, {"question": "What happened to him?", "options": ["He lost his job", "He got a prize", "He moved", "He became rich"], "correct_index": 0, "explanation": "Perdeu o emprego."}], "open_questions": [{"question": "Why are trees important?", "key_points_pt": ["dar razões"]}, {"question": "Would you break a rule for a good reason?", "key_points_pt": ["debater"]}]}}, {"level": "B1", "genre": "dystopia", "title": "The Curfew", "paragraphs": ["At nine o'clock every evening, a loud siren sounded across the city, and everybody had to be inside. Anyone found outside after that was taken away by the Night Patrol, and nobody ever saw them again. Tobias had obeyed the curfew all his life.", "But tonight his little brother was missing. He had not come home from football practice, and it was already ten past nine. Tobias's mother was shaking with fear. \"Stay here,\" she begged. \"I can't lose both of you.\"", "Tobias hesitated, then opened the door. The streets were empty and silent. He moved carefully from shadow to shadow, listening for the patrol's boots. Finally, behind a bakery, he found his brother hiding behind a bin, terrified.", "They crept home through the back alleys, and nobody saw them. In the kitchen, their mother hugged them both so tightly that they could hardly breathe. \"Never again,\" she whispered. But Tobias knew that the rules were becoming smaller than the people they were meant to control."], "paragraphs_pt": ["Às nove da noite, uma sirene alta soava pela cidade e todos tinham de estar em casa. Quem fosse achado na rua depois disso era levado pela Patrulha Noturna e nunca mais era visto. Tobias obedecera ao toque de recolher a vida inteira.", "Mas esta noite o irmãozinho dele estava desaparecido. Não voltara do treino de futebol, e já eram nove e dez. A mãe de Tobias tremia de medo. \"Fique aqui\", implorou. \"Não posso perder os dois.\"", "Tobias hesitou e depois abriu a porta. As ruas estavam vazias e silenciosas. Moveu-se com cuidado de sombra em sombra, atento às botas da patrulha. Por fim, atrás de uma padaria, encontrou o irmão escondido atrás de uma lixeira, aterrorizado.", "Voltaram para casa de fininho pelos becos, e ninguém os viu. Na cozinha, a mãe abraçou os dois com tanta força que mal podiam respirar. \"Nunca mais\", sussurrou. Mas Tobias sabia que as regras estavam ficando menores do que as pessoas que deviam controlar."], "hard_words": ["siren", "curfew", "patrol", "alley"], "vocab": [{"word": "siren", "meaning": "sirene", "note": ""}, {"word": "curfew", "meaning": "toque de recolher", "note": ""}, {"word": "patrol", "meaning": "patrulha", "note": ""}, {"word": "obeyed", "meaning": "obedeceu", "note": ""}, {"word": "shadow", "meaning": "sombra", "note": ""}, {"word": "bin", "meaning": "lixeira", "note": ""}, {"word": "alley", "meaning": "beco", "note": ""}, {"word": "hugged", "meaning": "abraçou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "was", "were"], "irregular": ["sounded", "had", "found", "taken", "saw", "obeyed", "begged", "hesitated", "opened", "moved", "terrified", "crept", "hugged", "could", "whispered", "knew", "meant"], "phrasal": ["taken away", "crept home"], "wh": [], "connectors": ["and", "but", "so", "then", "after", "finally"], "comparative": []}, "word_meanings": [{"word": "siren", "meaning": "sirene", "note": ""}, {"word": "curfew", "meaning": "toque de recolher", "note": ""}, {"word": "patrol", "meaning": "patrulha", "note": ""}, {"word": "obeyed", "meaning": "obedeceu", "note": ""}, {"word": "shadow", "meaning": "sombra", "note": ""}, {"word": "bin", "meaning": "lixeira", "note": ""}, {"word": "alley", "meaning": "beco", "note": ""}, {"word": "hugged", "meaning": "abraçou", "note": ""}], "exercises": {"grammar": [{"point": "Passive", "explanation_pt": "'Anyone found outside was taken away' foca em quem sofre a ação."}, {"point": "Past perfect", "explanation_pt": "'He had not come home' mostra algo anterior ao momento em que Tobias abre a porta."}], "multiple_choice": [{"question": "What happens at nine o'clock?", "options": ["A siren sounds", "School starts", "A train leaves", "The shops open"], "correct_index": 0, "explanation": "Soa uma sirene."}, {"question": "What happens to people outside?", "options": ["They get a fine", "The patrol takes them away", "They go to jail one day", "They are ignored"], "correct_index": 1, "explanation": "A patrulha os leva."}, {"question": "Who is missing?", "options": ["Tobias's father", "A neighbour", "Tobias's brother", "A dog"], "correct_index": 2, "explanation": "O irmão sumiu."}, {"question": "Where does Tobias find him?", "options": ["Behind a bin near a bakery", "In a school", "At home", "In a park"], "correct_index": 0, "explanation": "Atrás de uma lixeira perto da padaria."}, {"question": "What does Tobias realise?", "options": ["The curfew is useful", "The rules are too small for the people", "He is brave", "The patrol is kind"], "correct_index": 1, "explanation": "As regras estão menores que as pessoas."}], "open_questions": [{"question": "Is a curfew ever justified?", "key_points_pt": ["debater"]}, {"question": "What would you do in Tobias's place?", "key_points_pt": ["usar condicional"]}]}}, {"level": "B2", "genre": "dystopia", "title": "The Department of Memory", "paragraphs": ["Anya worked in the Department of Memory, where her task was to correct historical records. When the government changed its position on something, she altered old newspapers, photographs and speeches until the past agreed with the present. It was meticulous, uncomplicated work, and she had never questioned it.", "The first crack appeared on an ordinary Tuesday. She was erasing a name from a photograph of a parade when she recognised the man standing beside the name: her own father. He had been dead for twelve years, and according to every document she could find, he had never lived.", "That evening, she took a copy of the original photograph home, risking everything. She hid it inside a hollow book and examined it each night by candlelight, afraid that the picture might fade like the memories it preserved. She understood now that the Department's real purpose was not to rewrite history but to prevent anyone from noticing that it was being rewritten.", "Anya began to leave small errors in her corrections, tiny inconsistencies that nobody would notice for years. It was a modest form of rebellion, but she took comfort in the thought that truth, like water, only needs a crack to find its way through."], "paragraphs_pt": ["Anya trabalhava no Departamento de Memória, onde sua tarefa era corrigir registros históricos. Quando o governo mudava de posição sobre algo, ela alterava jornais, fotografias e discursos antigos até o passado concordar com o presente. Era um trabalho meticuloso e simples, e ela nunca o questionara.", "A primeira rachadura surgiu numa terça-feira comum. Apagava um nome de uma fotografia de um desfile quando reconheceu o homem ao lado do nome: o próprio pai. Ele estava morto havia doze anos e, segundo todos os documentos que ela conseguia achar, jamais vivera.", "Naquela noite, levou para casa uma cópia da fotografia original, arriscando tudo. Escondeu-a num livro oco e a examinava toda noite à luz de vela, com medo de que a imagem desbotasse como as lembranças que preservava. Entendeu então que o verdadeiro propósito do Departamento não era reescrever a história, mas impedir que alguém notasse que ela estava sendo reescrita.", "Anya começou a deixar pequenos erros nas correções, minúsculas inconsistências que ninguém notaria por anos. Era uma forma modesta de rebelião, mas ela se consolava com o pensamento de que a verdade, como a água, só precisa de uma rachadura para passar."], "hard_words": ["meticulous", "erasing", "hollow", "rebellion"], "vocab": [{"word": "records", "meaning": "registros", "note": ""}, {"word": "altered", "meaning": "alterava", "note": ""}, {"word": "meticulous", "meaning": "meticuloso", "note": ""}, {"word": "erasing", "meaning": "apagando", "note": ""}, {"word": "parade", "meaning": "desfile", "note": ""}, {"word": "hollow", "meaning": "oco", "note": ""}, {"word": "preserved", "meaning": "preservava", "note": ""}, {"word": "rebellion", "meaning": "rebelião", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "being"], "irregular": ["worked", "changed", "altered", "agreed", "had", "questioned", "appeared", "recognised", "could", "lived", "took", "hid", "examined", "might", "preserved", "understood", "rewritten", "began", "would", "thought"], "phrasal": ["agreed with", "find its way through"], "wh": ["where", "when"], "connectors": ["and", "but", "when", "until"], "comparative": []}, "word_meanings": [{"word": "records", "meaning": "registros", "note": ""}, {"word": "altered", "meaning": "alterava", "note": ""}, {"word": "meticulous", "meaning": "meticuloso", "note": ""}, {"word": "erasing", "meaning": "apagando", "note": ""}, {"word": "parade", "meaning": "desfile", "note": ""}, {"word": "hollow", "meaning": "oco", "note": ""}, {"word": "preserved", "meaning": "preservava", "note": ""}, {"word": "rebellion", "meaning": "rebelião", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'He had been dead for twelve years' mostra um estado anterior."}, {"point": "Not... but", "explanation_pt": "'not to rewrite history but to prevent anyone from noticing' contrasta propósitos."}], "multiple_choice": [{"question": "What was Anya's job?", "options": ["Cooking", "Teaching history", "Correcting historical records", "Painting"], "correct_index": 2, "explanation": "Corrigir registros históricos."}, {"question": "What did she find in the photograph?", "options": ["Her husband", "Her teacher", "A king", "Her father"], "correct_index": 3, "explanation": "O pai dela."}, {"question": "What did the documents say about him?", "options": ["He was a soldier", "He was a hero", "He never lived", "He was rich"], "correct_index": 2, "explanation": "Diziam que nunca vivera."}, {"question": "Where did she hide the copy?", "options": ["In a bank", "In a hollow book", "In a garden", "Under the bed"], "correct_index": 1, "explanation": "Num livro oco."}, {"question": "How does she rebel?", "options": ["By burning papers", "By leaving small errors", "By leaving the city", "By shouting"], "correct_index": 1, "explanation": "Deixando pequenos erros."}], "open_questions": [{"question": "Why do governments control history?", "key_points_pt": ["discutir poder e memória"]}, {"question": "How can we protect the truth?", "key_points_pt": ["dar sugestões"]}]}}, {"level": "B2", "genre": "dystopia", "title": "The Algorithm of Merit", "paragraphs": ["In the Republic of Aurelia, every decision was made by the Algorithm: who studied medicine, who received a flat, who could have children. The system claimed to be perfectly objective, since it ignored wealth, race and family name. Citizens trusted it more than they had ever trusted a person.", "Mateo had always dreamed of becoming an architect, but at eighteen the Algorithm assigned him to the water-treatment plant. It explained that his scores showed an \"aptitude for repetition\". He accepted the verdict without argument, as everybody did, and spent six years monitoring pipes.", "Then a colleague, an old engineer called Pilar, showed him something unsettling. \"Look at the dates,\" she said. \"The Algorithm has been predicting the same career for children from the same neighbourhoods, generation after generation. It isn't measuring talent; it is reproducing the past.\"", "Mateo felt a strange mix of anger and relief. His life had not been the result of his limits, but of a calculation. He began to draw buildings in the margins of his reports, and, along with Pilar, he started a quiet campaign to make the data public. They didn't know whether anybody would listen, but they had stopped waiting for permission."], "paragraphs_pt": ["Na República de Aurélia, toda decisão era tomada pelo Algoritmo: quem estudava medicina, quem recebia um apartamento, quem podia ter filhos. O sistema se dizia perfeitamente objetivo, pois ignorava riqueza, raça e sobrenome. Os cidadãos confiavam nele mais do que jamais confiaram numa pessoa.", "Mateo sempre sonhara ser arquiteto, mas aos dezoito anos o Algoritmo o designou para a estação de tratamento de água. Explicou que as pontuações dele mostravam \"aptidão para repetição\". Aceitou o veredicto sem discutir, como todos, e passou seis anos monitorando canos.", "Então uma colega, uma velha engenheira chamada Pilar, mostrou-lhe algo perturbador. \"Olhe as datas\", disse. \"O Algoritmo prevê a mesma carreira para filhos dos mesmos bairros, geração após geração. Não mede talento; reproduz o passado.\"", "Mateo sentiu uma estranha mistura de raiva e alívio. Sua vida não fora resultado de seus limites, mas de um cálculo. Começou a desenhar prédios nas margens dos relatórios e, com Pilar, iniciou uma campanha discreta para tornar os dados públicos. Não sabiam se alguém ouviria, mas haviam parado de esperar por permissão."], "hard_words": ["objective", "aptitude", "unsettling", "reproducing"], "vocab": [{"word": "objective", "meaning": "objetivo", "note": ""}, {"word": "assigned", "meaning": "designou", "note": ""}, {"word": "water-treatment plant", "meaning": "estação de tratamento de água", "note": ""}, {"word": "aptitude", "meaning": "aptidão", "note": ""}, {"word": "unsettling", "meaning": "perturbador", "note": ""}, {"word": "neighbourhoods", "meaning": "bairros", "note": ""}, {"word": "reproducing", "meaning": "reproduzindo", "note": ""}, {"word": "campaign", "meaning": "campanha", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "been", "is"], "irregular": ["made", "studied", "received", "could", "claimed", "ignored", "trusted", "had", "dreamed", "assigned", "explained", "showed", "accepted", "did", "spent", "called", "said", "felt", "began", "started", "would", "stopped"], "phrasal": ["showed him", "spent six years"], "wh": ["who"], "connectors": ["and", "but", "then", "after", "since", "as"], "comparative": []}, "word_meanings": [{"word": "objective", "meaning": "objetivo", "note": ""}, {"word": "assigned", "meaning": "designou", "note": ""}, {"word": "water-treatment plant", "meaning": "estação de tratamento de água", "note": ""}, {"word": "aptitude", "meaning": "aptidão", "note": ""}, {"word": "unsettling", "meaning": "perturbador", "note": ""}, {"word": "neighbourhoods", "meaning": "bairros", "note": ""}, {"word": "reproducing", "meaning": "reproduzindo", "note": ""}, {"word": "campaign", "meaning": "campanha", "note": ""}], "exercises": {"grammar": [{"point": "Present perfect continuous", "explanation_pt": "'The Algorithm has been predicting the same career' mostra um padrão repetido até agora."}, {"point": "Not... but", "explanation_pt": "'not of his limits, but of a calculation' contrasta causas."}], "multiple_choice": [{"question": "What did the Algorithm decide?", "options": ["Careers, homes and families", "The prices only", "The weather", "The news"], "correct_index": 0, "explanation": "Carreira, moradia e filhos."}, {"question": "What did Mateo want to be?", "options": ["A doctor", "An architect", "A teacher", "A pilot"], "correct_index": 1, "explanation": "Queria ser arquiteto."}, {"question": "What did Pilar discover?", "options": ["The Algorithm was broken", "The Algorithm repeated the past", "The Algorithm was new", "The Algorithm was kind"], "correct_index": 1, "explanation": "O algoritmo reproduzia o passado."}, {"question": "How did Mateo feel?", "options": ["Anger and relief", "Boredom", "Fear only", "Joy only"], "correct_index": 0, "explanation": "Raiva e alívio."}, {"question": "What did they decide to do?", "options": ["Leave the city", "Make the data public", "Do nothing", "Destroy the plant"], "correct_index": 1, "explanation": "Tornar os dados públicos."}], "open_questions": [{"question": "Can an algorithm be truly objective?", "key_points_pt": ["debater"]}, {"question": "What would a fair system look like?", "key_points_pt": ["propor ideias"]}]}}, {"level": "B2", "genre": "dystopia", "title": "The Last Honest Broadcast", "paragraphs": ["For ten years, the only television channel in the country had broadcast the same cheerful message: the harvest was record-breaking, the borders were safe, and the leader was loved. Ilya, who worked in the studio as a technician, had noticed that the harvest figures were repeated word for word every year, and that the sets of the \"factory visits\" were always the same.", "One night, when the studio was empty, he connected a camera to an old transmitter that nobody had used in decades. He turned to the lens and spoke for four minutes. He listed the food queues, the empty hospitals and the names of people who had disappeared. His voice trembled but did not stop.", "The signal lasted barely half an hour before the authorities cut the power. Yet in that time, thousands of televisions in the capital had picked it up. In the following days, people stopped each other in the street, saying nothing, simply nodding with a new kind of look.", "Ilya was arrested within the week. He never learned what happened afterwards, but the guard who brought his meals sometimes whispered a single word as he passed: \"Thank you.\" It was enough to convince him that a small crack in a loud wall could still change what people believed was possible."], "paragraphs_pt": ["Por dez anos, o único canal de televisão do país transmitira a mesma mensagem alegre: a colheita era recorde, as fronteiras estavam seguras e o líder era amado. Ilya, que trabalhava no estúdio como técnico, notara que os números da colheita se repetiam palavra por palavra todo ano e que os cenários das \"visitas a fábricas\" eram sempre os mesmos.", "Uma noite, com o estúdio vazio, ligou uma câmera a um velho transmissor que ninguém usava havia décadas. Virou-se para a lente e falou por quatro minutos. Listou as filas de comida, os hospitais vazios e os nomes de pessoas desaparecidas. A voz tremeu, mas não parou.", "O sinal durou apenas meia hora antes que as autoridades cortassem a energia. Mas, nesse tempo, milhares de televisores na capital o captaram. Nos dias seguintes, as pessoas se paravam na rua sem dizer nada, só assentindo com um olhar novo.", "Ilya foi preso em menos de uma semana. Nunca soube o que aconteceu depois, mas o guarda que trazia suas refeições às vezes sussurrava uma única palavra ao passar: \"Obrigado.\" Bastou para convencê-lo de que uma pequena rachadura numa parede ruidosa ainda podia mudar o que as pessoas acreditavam ser possível."], "hard_words": ["harvest", "transmitter", "authorities", "arrested"], "vocab": [{"word": "broadcast", "meaning": "transmitiu", "note": ""}, {"word": "harvest", "meaning": "colheita", "note": ""}, {"word": "technician", "meaning": "técnico", "note": ""}, {"word": "transmitter", "meaning": "transmissor", "note": ""}, {"word": "lens", "meaning": "lente", "note": ""}, {"word": "queues", "meaning": "filas", "note": ""}, {"word": "authorities", "meaning": "autoridades", "note": ""}, {"word": "arrested", "meaning": "preso", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["had", "loved", "worked", "noticed", "repeated", "connected", "used", "turned", "spoke", "listed", "disappeared", "trembled", "did", "lasted", "picked", "stopped", "arrested", "learned", "happened", "brought", "whispered", "passed", "could", "believed"], "phrasal": ["cut the power"], "wh": ["who", "what", "when"], "connectors": ["and", "but", "before", "when", "yet", "still", "as"], "comparative": []}, "word_meanings": [{"word": "broadcast", "meaning": "transmitiu", "note": ""}, {"word": "harvest", "meaning": "colheita", "note": ""}, {"word": "technician", "meaning": "técnico", "note": ""}, {"word": "transmitter", "meaning": "transmissor", "note": ""}, {"word": "lens", "meaning": "lente", "note": ""}, {"word": "queues", "meaning": "filas", "note": ""}, {"word": "authorities", "meaning": "autoridades", "note": ""}, {"word": "arrested", "meaning": "preso", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had broadcast the same message' e 'had noticed' dão contexto anterior."}, {"point": "Hardly e barely", "explanation_pt": "'barely half an hour' indica um tempo muito curto."}], "multiple_choice": [{"question": "What did the channel always say?", "options": ["Bad news", "Sports only", "Weather", "Everything was perfect"], "correct_index": 3, "explanation": "Dizia que tudo ia bem."}, {"question": "What was Ilya's job?", "options": ["Soldier", "Teacher", "Studio technician", "Reporter"], "correct_index": 2, "explanation": "Era técnico de estúdio."}, {"question": "What did he list in the broadcast?", "options": ["Food queues, empty hospitals, missing people", "Recipes", "Sports results", "Songs"], "correct_index": 0, "explanation": "Filas, hospitais vazios, desaparecidos."}, {"question": "How long did the signal last?", "options": ["All night", "About half an hour", "Ten seconds", "Four days"], "correct_index": 1, "explanation": "Cerca de meia hora."}, {"question": "What happened to Ilya?", "options": ["He escaped", "He became president", "He was promoted", "He was arrested"], "correct_index": 3, "explanation": "Foi preso."}], "open_questions": [{"question": "Does one small act of courage matter?", "key_points_pt": ["debater"]}, {"question": "How does propaganda work?", "key_points_pt": ["explicar mecanismos"]}]}}, {"level": "C1", "genre": "dystopia", "title": "The Comfortable Cage", "paragraphs": ["Nobody in the city of Elysia could remember having been forced to do anything. Work was meaningful, leisure abundant, and every desire was anticipated by systems so attentive that wanting itself had become almost obsolete. It took Odalys an embarrassingly long time to notice that this was the problem.", "She first sensed it during a conversation with her grandmother, one of the few people who still remembered what it meant to lack something. \"When did you last choose between two things you wanted equally?\" the old woman asked. Odalys opened her mouth to answer and found that she could not recall a single instance. The system had always arranged things so that the choice never appeared.", "It is difficult to resist a cage whose bars are made of kindness. There was no enemy to defy, no injustice to expose; only a gentle, universal erosion of effort. Odalys began experimenting with small acts of friction: walking instead of taking the transit, cooking meals that took hours, making decisions without consulting the assistant.", "Her friends considered it a harmless eccentricity. Yet she observed with quiet satisfaction that her handwriting, her opinions and even her mistakes were becoming more distinctly her own. Freedom, she concluded, was not the absence of comfort but the presence of the possibility of refusal."], "paragraphs_pt": ["Ninguém na cidade de Elísia lembrava de ter sido forçado a fazer algo. O trabalho era significativo, o lazer abundante, e cada desejo era antecipado por sistemas tão atentos que o próprio desejar se tornara quase obsoleto. Odalys levou um tempo constrangedoramente longo para perceber que esse era o problema.", "Ela o sentiu pela primeira vez numa conversa com a avó, uma das poucas pessoas que ainda lembravam o que era sentir falta de algo. \"Quando foi a última vez que você escolheu entre duas coisas que queria igualmente?\", perguntou a velha. Odalys abriu a boca para responder e descobriu que não se lembrava de um único caso. O sistema sempre arranjara as coisas de modo que a escolha nunca aparecesse.", "É difícil resistir a uma jaula cujas grades são feitas de gentileza. Não havia inimigo a desafiar, injustiça a expor; apenas uma erosão gentil e universal do esforço. Odalys começou a experimentar pequenos atos de atrito: andar em vez de usar o transporte, cozinhar refeições que levavam horas, tomar decisões sem consultar o assistente.", "Os amigos consideraram uma excentricidade inofensiva. Mas ela observou com satisfação silenciosa que sua letra, suas opiniões e até seus erros estavam ficando mais distintamente seus. Liberdade, concluiu, não era a ausência de conforto, mas a presença da possibilidade de recusa."], "hard_words": ["obsolete", "erosion", "friction", "refusal"], "vocab": [{"word": "abundant", "meaning": "abundante", "note": ""}, {"word": "anticipated", "meaning": "antecipados", "note": ""}, {"word": "obsolete", "meaning": "obsoleto", "note": ""}, {"word": "defy", "meaning": "desafiar", "note": ""}, {"word": "erosion", "meaning": "erosão", "note": ""}, {"word": "friction", "meaning": "atrito", "note": ""}, {"word": "eccentricity", "meaning": "excentricidade", "note": ""}, {"word": "refusal", "meaning": "recusa", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "is", "are", "were"], "irregular": ["could", "forced", "anticipated", "had", "took", "sensed", "remembered", "meant", "did", "wanted", "asked", "opened", "found", "arranged", "appeared", "made", "began", "considered", "observed", "concluded"], "phrasal": ["opened her mouth"], "wh": ["who", "what", "when", "whose"], "connectors": ["so that", "and", "but", "so", "instead", "when", "yet", "still"], "comparative": []}, "word_meanings": [{"word": "abundant", "meaning": "abundante", "note": ""}, {"word": "anticipated", "meaning": "antecipados", "note": ""}, {"word": "obsolete", "meaning": "obsoleto", "note": ""}, {"word": "defy", "meaning": "desafiar", "note": ""}, {"word": "erosion", "meaning": "erosão", "note": ""}, {"word": "friction", "meaning": "atrito", "note": ""}, {"word": "eccentricity", "meaning": "excentricidade", "note": ""}, {"word": "refusal", "meaning": "recusa", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'The system had always arranged things' indica um padrão anterior."}, {"point": "Not... but", "explanation_pt": "'not the absence of comfort but the presence of the possibility of refusal' define por contraste."}], "multiple_choice": [{"question": "What was unusual about Elysia?", "options": ["It was small", "Nobody worked", "It was cold", "Every desire was anticipated"], "correct_index": 3, "explanation": "Os desejos eram antecipados."}, {"question": "What did the grandmother ask?", "options": ["Who her friends were", "When she last chose between two things", "Where she worked", "What she ate"], "correct_index": 1, "explanation": "Quando escolheu entre duas coisas."}, {"question": "Why is the cage hard to resist?", "options": ["It is hidden", "It is expensive", "It is strong", "Its bars are made of kindness"], "correct_index": 3, "explanation": "As grades são de gentileza."}, {"question": "What does Odalys do?", "options": ["Calls police", "Adds small friction", "Moves away", "Breaks machines"], "correct_index": 1, "explanation": "Cria pequenos atritos."}, {"question": "How does she define freedom?", "options": ["Having comfort", "Having money", "The possibility of refusal", "Leaving"], "correct_index": 2, "explanation": "A possibilidade de recusa."}], "open_questions": [{"question": "Can too much comfort limit freedom?", "key_points_pt": ["debater"]}, {"question": "What small choices make you feel most yourself?", "key_points_pt": ["refletir"]}]}}, {"level": "C2", "genre": "dystopia", "title": "The Lexicon of Obedience", "paragraphs": ["When the Ministry announced the revision of the national dictionary, few citizens paid attention; language, after all, seemed too diffuse a thing to be captured. Yet over the following decade, words began to vanish with the quiet efficiency of ice melting in a warm room. \"Protest\" became \"disturbance\", then \"disorder\", and finally nothing at all.", "Linnea, a lexicographer who had witnessed the process from within, understood the logic with a clarity that made her ill. A thought, the Ministry had realised, requires words to hold its shape; remove the container, and the content spills, leaving no stain. Citizens did not feel censored, because they could no longer formulate what was being withheld.", "She began, at great risk, to compile a secret glossary in the margins of ordinary documents, disguising forbidden terms as typographical errors. Her private rebellion had a peculiar tenderness: she was not trying to overthrow a regime, only to prevent a word like \"dignity\" from dying unrecorded.", "Years later, a young archivist discovered the annotated pages and read them aloud to a group of friends, struggling over unfamiliar syllables. Nobody understood everything, but a silence fell, the kind that follows when a language begins to remember. It was, Linnea would have said, the only victory that mattered."], "paragraphs_pt": ["Quando o Ministério anunciou a revisão do dicionário nacional, poucos cidadãos prestaram atenção; a língua, afinal, parecia difusa demais para ser capturada. Mas ao longo da década seguinte as palavras começaram a sumir com a eficiência silenciosa de gelo derretendo numa sala quente. \"Protesto\" virou \"perturbação\", depois \"desordem\", e por fim nada.", "Linnea, lexicógrafa que testemunhara o processo por dentro, entendeu a lógica com uma clareza que a deixou doente. Um pensamento, o Ministério percebera, precisa de palavras para manter a forma; retire o recipiente e o conteúdo se derrama, sem deixar mancha. Os cidadãos não se sentiam censurados, porque não conseguiam mais formular o que lhes era negado.", "Começou, com grande risco, a compilar um glossário secreto nas margens de documentos comuns, disfarçando termos proibidos como erros de digitação. Sua rebelião privada tinha uma ternura peculiar: não tentava derrubar um regime, apenas impedir que uma palavra como \"dignidade\" morresse sem registro.", "Anos depois, um jovem arquivista descobriu as páginas anotadas e as leu em voz alta para um grupo de amigos, tropeçando em sílabas desconhecidas. Ninguém entendeu tudo, mas caiu um silêncio, do tipo que se segue quando uma língua começa a lembrar. Era, Linnea teria dito, a única vitória que importava."], "hard_words": ["lexicographer", "withheld", "tenderness", "archivist"], "vocab": [{"word": "diffuse", "meaning": "difuso", "note": ""}, {"word": "vanish", "meaning": "sumir", "note": ""}, {"word": "lexicographer", "meaning": "lexicógrafa", "note": ""}, {"word": "withheld", "meaning": "negado, retido", "note": ""}, {"word": "compile", "meaning": "compilar", "note": ""}, {"word": "typographical", "meaning": "tipográfico", "note": ""}, {"word": "tenderness", "meaning": "ternura", "note": ""}, {"word": "archivist", "meaning": "arquivista", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "was", "being"], "irregular": ["announced", "paid", "seemed", "captured", "began", "became", "had", "witnessed", "understood", "made", "thought", "realised", "did", "censored", "could", "withheld", "forbidden", "discovered", "annotated", "fell", "would", "said", "mattered"], "phrasal": ["paid attention"], "wh": ["who", "what", "when"], "connectors": ["and", "but", "because", "then", "after", "when", "yet", "finally", "as"], "comparative": []}, "word_meanings": [{"word": "diffuse", "meaning": "difuso", "note": ""}, {"word": "vanish", "meaning": "sumir", "note": ""}, {"word": "lexicographer", "meaning": "lexicógrafa", "note": ""}, {"word": "withheld", "meaning": "negado, retido", "note": ""}, {"word": "compile", "meaning": "compilar", "note": ""}, {"word": "typographical", "meaning": "tipográfico", "note": ""}, {"word": "tenderness", "meaning": "ternura", "note": ""}, {"word": "archivist", "meaning": "arquivista", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'the Ministry had realised' e 'had witnessed' dão contexto a uma realização anterior."}, {"point": "Not... only", "explanation_pt": "'not trying to overthrow a regime, only to prevent' limita o objetivo."}], "multiple_choice": [{"question": "What did the Ministry revise?", "options": ["The flag", "The constitution", "The national dictionary", "The anthem"], "correct_index": 2, "explanation": "Revisaram o dicionário nacional."}, {"question": "What happened to the word 'protest'?", "options": ["It became a name", "It became popular", "It became longer", "It disappeared"], "correct_index": 3, "explanation": "Foi substituída até sumir."}, {"question": "Why did citizens not feel censored?", "options": ["They were afraid", "They were happy", "They were rich", "They could not formulate what was withheld"], "correct_index": 3, "explanation": "Não conseguiam formular o negado."}, {"question": "What did Linnea do?", "options": ["Made a secret glossary", "Left the country", "Joined the Ministry", "Wrote to the Ministry"], "correct_index": 0, "explanation": "Compilou um glossário secreto."}, {"question": "What happened years later?", "options": ["The Ministry fell", "An archivist read her pages aloud", "The words returned in books", "She was arrested"], "correct_index": 1, "explanation": "O arquivista leu as páginas em voz alta."}], "open_questions": [{"question": "Can language limit what we are able to think?", "key_points_pt": ["debater"]}, {"question": "Which word would you save and why?", "key_points_pt": ["refletir"]}]}}, {"level": "C2", "genre": "dystopia", "title": "The Weight of Tomorrow", "paragraphs": ["By the time the Council abolished the word \"future\" from official correspondence, nobody was particularly surprised. The planet had endured four decades of rationing, and the prevailing doctrine held that hope was merely a deferred form of disappointment. The Council preferred \"the continuation of the present\", a phrase so devoid of promise that it required effort to resent.", "Dr. Khalil, a physician in the eastern district, kept one dangerous habit: she asked her patients what they intended to do next summer. At first the question puzzled them, as if she had spoken in an obscure dialect. Then they began to answer, haltingly, with the sheepishness of people revealing a forbidden hobby: a garden, a trip to the coast, a child's wedding.", "She never recorded these conversations, yet she noticed that her patients recovered faster than the clinic's statistics predicted. The Council's analysts traced the anomaly to her ward and sent an inspector, a young man who expected sedition and found, instead, a nurse arguing over the colour of a nursery.", "The inspector filed a report so tedious that it was shelved immediately, which was, perhaps, the most subversive act of the entire affair. Khalil never learned his name, but she remembered the faint, bewildered smile with which he left, and she suspected that the future, like a seed in a coat pocket, had made its own way across the border."], "paragraphs_pt": ["Quando o Conselho aboliu a palavra \"futuro\" da correspondência oficial, ninguém ficou particularmente surpreso. O planeta suportara quatro décadas de racionamento, e a doutrina vigente sustentava que esperança era apenas uma forma adiada de decepção. O Conselho preferia \"a continuação do presente\", expressão tão desprovida de promessa que exigia esforço para ressentir.", "A Dra. Khalil, médica do distrito leste, mantinha um hábito perigoso: perguntava aos pacientes o que pretendiam fazer no próximo verão. A princípio a pergunta os intrigava, como se ela falasse um dialeto obscuro. Depois passaram a responder, hesitantes, com o acanhamento de quem revela um passatempo proibido: um jardim, uma viagem ao litoral, o casamento de um filho.", "Ela nunca registrava essas conversas, mas notou que os pacientes se recuperavam mais rápido do que as estatísticas da clínica previam. Os analistas do Conselho rastrearam a anomalia até sua ala e enviaram um inspetor, um jovem que esperava sedição e encontrou, em vez disso, uma enfermeira discutindo a cor de um quarto de bebê.", "O inspetor entregou um relatório tão tedioso que foi arquivado imediatamente, o que foi, talvez, o ato mais subversivo de todo o caso. Khalil nunca soube seu nome, mas lembrou do sorriso tênue e desnorteado com que ele saiu e suspeitou que o futuro, como uma semente no bolso de um casaco, atravessara a fronteira por conta própria."], "hard_words": ["doctrine", "devoid", "sedition", "subversive"], "vocab": [{"word": "abolished", "meaning": "aboliu", "note": ""}, {"word": "rationing", "meaning": "racionamento", "note": ""}, {"word": "doctrine", "meaning": "doutrina", "note": ""}, {"word": "deferred", "meaning": "adiada", "note": ""}, {"word": "devoid", "meaning": "desprovida", "note": ""}, {"word": "sheepishness", "meaning": "acanhamento", "note": ""}, {"word": "sedition", "meaning": "sedição", "note": ""}, {"word": "subversive", "meaning": "subversivo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["abolished", "surprised", "had", "endured", "held", "deferred", "preferred", "required", "resent", "kept", "asked", "intended", "puzzled", "spoken", "began", "forbidden", "recorded", "noticed", "recovered", "predicted", "traced", "sent", "expected", "found", "filed", "shelved", "learned", "remembered", "bewildered", "left", "suspected", "made"], "phrasal": [], "wh": ["who", "what", "which"], "connectors": ["and", "but", "so", "instead", "then", "yet", "if", "as"], "comparative": []}, "word_meanings": [{"word": "abolished", "meaning": "aboliu", "note": ""}, {"word": "rationing", "meaning": "racionamento", "note": ""}, {"word": "doctrine", "meaning": "doutrina", "note": ""}, {"word": "deferred", "meaning": "adiada", "note": ""}, {"word": "devoid", "meaning": "desprovida", "note": ""}, {"word": "sheepishness", "meaning": "acanhamento", "note": ""}, {"word": "sedition", "meaning": "sedição", "note": ""}, {"word": "subversive", "meaning": "subversivo", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had endured four decades' e 'had spoken' indicam contexto anterior."}, {"point": "Merely e only", "explanation_pt": "'merely a deferred form of disappointment' reduz a importância do conceito."}], "multiple_choice": [{"question": "What did the Council abolish?", "options": ["The word 'future'", "The doctors", "The summer", "The hospitals"], "correct_index": 0, "explanation": "Aboliu a palavra 'futuro'."}, {"question": "What dangerous habit did Dr. Khalil have?", "options": ["Prescribing herbs", "Writing diaries", "Asking about next summer", "Leaving work"], "correct_index": 2, "explanation": "Perguntar sobre o próximo verão."}, {"question": "What did she notice?", "options": ["Patients recovered faster", "Patients lied", "Patients left", "Patients complained"], "correct_index": 0, "explanation": "Os pacientes se recuperavam mais rápido."}, {"question": "What did the inspector find?", "options": ["A bomb", "A rebel leader", "A nurse discussing a nursery colour", "A secret army"], "correct_index": 2, "explanation": "Uma enfermeira discutindo a cor de um quarto de bebê."}, {"question": "What does the future resemble at the end?", "options": ["A bird", "A seed in a coat pocket", "A wall", "A river"], "correct_index": 1, "explanation": "Uma semente no bolso de um casaco."}], "open_questions": [{"question": "Why is hope important to health?", "key_points_pt": ["discutir bem-estar"]}, {"question": "What could a government do to suppress hope?", "key_points_pt": ["analisar mecanismos"]}]}}, {"level": "C2", "genre": "dystopia", "title": "The Ministry of Gentle Corrections", "paragraphs": ["Nobody could recall the precise moment at which the Ministry of Gentle Corrections had acquired its present authority. It had begun, as such institutions do, with an unobjectionable ambition: to reduce the discomfort of public life. Rudeness was discouraged, then regulated, then reclassified as a minor illness. Within a generation, a population of exceptional courtesy had emerged, and it was considered impolite to remark upon its eerie smoothness.", "Ottoline Reyes, a junior inspector, was charged with identifying \"friction indicators\" in private correspondence. It was tedious work, conducted in a pastel office that smelled of lavender, and she excelled at it because she genuinely believed that kindness was a virtue. It was only when she was assigned to review the letters of a dying poet that the doubt arrived. The old man had written, in a spidery hand, an unforgivable sentence: \"I am angry about all of this.\"", "The phrase had been flagged for softening. Her instructions suggested \"I am concerned about the circumstances.\" Ottoline sat for a long time with the two sentences before her, and comprehended with a kind of vertigo that the first contained a man and the second contained an institution. The poet's anger, whatever else it was, was alive; the substitute was merely well-mannered.", "She submitted the letter unchanged, an act which, in her profession, was equivalent to arson. No one noticed for months. When the Ministry finally discovered the lapse, it responded in character: with a courteous memo expressing regret that her work had not met expectations. Ottoline framed it, in the privacy of her kitchen, beside the poet's original sentence, and read both aloud each evening to remind herself which one still frightened her."], "paragraphs_pt": ["Ninguém lembrava o momento preciso em que o Ministério das Correções Gentis adquirira sua autoridade atual. Começara, como tais instituições, com uma ambição irrepreensível: reduzir o desconforto da vida pública. A grosseria foi desencorajada, depois regulada, depois reclassificada como doença menor. Em uma geração, emergiu uma população de cortesia excepcional, e considerava-se indelicado comentar sua suavidade sinistra.", "Ottoline Reyes, inspetora júnior, tinha a tarefa de identificar \"indicadores de atrito\" na correspondência privada. Era trabalho tedioso, feito num escritório pastel que cheirava a lavanda, e ela se destacava nele porque realmente acreditava que a gentileza era uma virtude. Só quando foi designada para revisar as cartas de um poeta moribundo a dúvida chegou. O velho escrevera, em letra de aranha, uma frase imperdoável: \"Estou com raiva de tudo isso.\"", "A frase fora marcada para suavização. As instruções sugeriam \"Estou preocupado com as circunstâncias.\" Ottoline ficou muito tempo diante das duas frases e compreendeu, com uma espécie de vertigem, que a primeira continha um homem e a segunda continha uma instituição. A raiva do poeta, fosse o que mais fosse, estava viva; o substituto era apenas bem-educado.", "Enviou a carta sem alteração, ato que, em sua profissão, equivalia a incêndio criminoso. Ninguém notou por meses. Quando o Ministério enfim descobriu a falha, respondeu fiel a si mesmo: com um memorando cortês lamentando que seu trabalho não tivesse atendido às expectativas. Ottoline o emoldurou, na privacidade da cozinha, ao lado da frase original do poeta, e lia as duas em voz alta toda noite para lembrar a si mesma qual delas ainda a assustava."], "hard_words": ["unobjectionable", "eerie", "arson", "lapse"], "vocab": [{"word": "unobjectionable", "meaning": "irrepreensível", "note": ""}, {"word": "reclassified", "meaning": "reclassificada", "note": ""}, {"word": "eerie", "meaning": "sinistra", "note": ""}, {"word": "friction", "meaning": "atrito", "note": ""}, {"word": "flagged", "meaning": "marcada", "note": ""}, {"word": "comprehended", "meaning": "compreendeu", "note": ""}, {"word": "arson", "meaning": "incêndio criminoso", "note": ""}, {"word": "lapse", "meaning": "falha", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "am", "been"], "irregular": ["could", "had", "acquired", "begun", "discouraged", "regulated", "reclassified", "emerged", "considered", "charged", "conducted", "smelled", "excelled", "believed", "assigned", "arrived", "written", "flagged", "suggested", "concerned", "sat", "comprehended", "contained", "submitted", "noticed", "discovered", "responded", "met", "framed", "frightened"], "phrasal": ["charged with"], "wh": ["when", "which", "whatever"], "connectors": ["and", "because", "then", "before", "when", "finally", "still", "as"], "comparative": []}, "word_meanings": [{"word": "unobjectionable", "meaning": "irrepreensível", "note": ""}, {"word": "reclassified", "meaning": "reclassificada", "note": ""}, {"word": "eerie", "meaning": "sinistra", "note": ""}, {"word": "friction", "meaning": "atrito", "note": ""}, {"word": "flagged", "meaning": "marcada", "note": ""}, {"word": "comprehended", "meaning": "compreendeu", "note": ""}, {"word": "arson", "meaning": "incêndio criminoso", "note": ""}, {"word": "lapse", "meaning": "falha", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'The phrase had been flagged' mostra algo anterior à leitura."}, {"point": "Not... but merely", "explanation_pt": "'whatever else it was, was alive; the substitute was merely well-mannered' contrasta vida e polidez."}], "multiple_choice": [{"question": "What does the Ministry do?", "options": ["Runs hospitals", "Teaches art", "Softens public expression", "Builds roads"], "correct_index": 2, "explanation": "Suaviza a expressão pública."}, {"question": "What was Ottoline's job?", "options": ["Teaching", "Cooking", "Finding friction indicators in letters", "Writing poems"], "correct_index": 2, "explanation": "Identificar indicadores de atrito."}, {"question": "What did the poet write?", "options": ["I am sorry", "I am happy", "I am angry about all of this", "I am tired"], "correct_index": 2, "explanation": "'Estou com raiva de tudo isso.'"}, {"question": "What did she do with the letter?", "options": ["Softened it", "Sent it unchanged", "Burned it", "Hid it"], "correct_index": 1, "explanation": "Enviou sem alteração."}, {"question": "How did the Ministry respond?", "options": ["With a trial", "With silence", "With arrest", "With a courteous memo"], "correct_index": 3, "explanation": "Com um memorando cortês."}], "open_questions": [{"question": "Is politeness always a virtue?", "key_points_pt": ["debater"]}, {"question": "What do we lose when anger is censored?", "key_points_pt": ["refletir"]}]}}, {"level": "A1", "genre": "western", "title": "The Cowboy and His Horse", "paragraphs": ["Jim is a cowboy. He lives on a ranch in Texas. He has a brown horse. The horse's name is Thunder.", "Every morning, Jim gets up early. He gives Thunder some water and food. Then they ride across the big field.", "Jim loves Thunder. \"You are my best friend,\" he says. Thunder moves his head. He is happy too. They watch the sun go down together."], "paragraphs_pt": ["Jim é um vaqueiro. Mora num rancho no Texas. Tem um cavalo marrom. O nome do cavalo é Trovão.", "Toda manhã, Jim levanta cedo. Dá água e comida ao Trovão. Depois cavalgam pelo grande campo.", "Jim ama o Trovão. \"Você é meu melhor amigo\", diz. Trovão mexe a cabeça. Ele também está feliz. Veem o sol se pôr juntos."], "hard_words": ["cowboy", "ranch", "ride", "field"], "vocab": [{"word": "cowboy", "meaning": "vaqueiro", "note": ""}, {"word": "ranch", "meaning": "rancho", "note": ""}, {"word": "horse", "meaning": "cavalo", "note": ""}, {"word": "brown", "meaning": "marrom", "note": ""}, {"word": "field", "meaning": "campo", "note": ""}, {"word": "ride", "meaning": "cavalgar", "note": ""}, {"word": "sun", "meaning": "sol", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "then"], "comparative": []}, "word_meanings": [{"word": "cowboy", "meaning": "vaqueiro", "note": ""}, {"word": "ranch", "meaning": "rancho", "note": ""}, {"word": "horse", "meaning": "cavalo", "note": ""}, {"word": "brown", "meaning": "marrom", "note": ""}, {"word": "field", "meaning": "campo", "note": ""}, {"word": "ride", "meaning": "cavalgar", "note": ""}, {"word": "sun", "meaning": "sol", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "'Jim gets up early' descreve rotina."}], "multiple_choice": [{"question": "Who is Jim?", "options": ["A doctor", "A driver", "A teacher", "A cowboy"], "correct_index": 3, "explanation": "Um vaqueiro."}, {"question": "Where does he live?", "options": ["On a ranch in Texas", "In a city", "In New York", "In Brazil"], "correct_index": 0, "explanation": "Num rancho no Texas."}, {"question": "What color is the horse?", "options": ["Black", "Brown", "White", "Grey"], "correct_index": 1, "explanation": "Marrom."}, {"question": "What is the horse's name?", "options": ["Storm", "Thunder", "Lightning", "Wind"], "correct_index": 1, "explanation": "Trovão."}, {"question": "What do they watch?", "options": ["A game", "The sun go down", "A film", "A parade"], "correct_index": 1, "explanation": "O pôr do sol."}], "open_questions": [{"question": "Do you like horses?", "key_points_pt": ["opinar"]}, {"question": "What is your morning routine?", "key_points_pt": ["descrever"]}]}}, {"level": "A1", "genre": "western", "title": "The Old Town", "paragraphs": ["The old town is in the desert. It is very hot. There is one street and a few wooden houses. There is a saloon and a small bank.", "A stranger comes on a black horse. He wears a big hat. Everyone looks at him. He goes to the saloon and asks for water.", "The barman gives him a glass. \"Welcome to our town,\" he says. The stranger smiles. \"Thank you. I am just a traveler.\" Then he rides away."], "paragraphs_pt": ["A cidade velha fica no deserto. Faz muito calor. Há uma rua e algumas casas de madeira. Há um saloon e um pequeno banco.", "Um forasteiro chega num cavalo preto. Usa um chapéu grande. Todos olham para ele. Vai ao saloon e pede água.", "O atendente lhe dá um copo. \"Bem-vindo à nossa cidade\", diz. O forasteiro sorri. \"Obrigado. Sou só um viajante.\" Depois vai embora cavalgando."], "hard_words": ["desert", "wooden", "stranger", "traveler"], "vocab": [{"word": "desert", "meaning": "deserto", "note": ""}, {"word": "wooden", "meaning": "de madeira", "note": ""}, {"word": "saloon", "meaning": "saloon, bar", "note": ""}, {"word": "stranger", "meaning": "forasteiro", "note": ""}, {"word": "hat", "meaning": "chapéu", "note": ""}, {"word": "barman", "meaning": "atendente de bar", "note": ""}, {"word": "traveler", "meaning": "viajante", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "am"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "then"], "comparative": []}, "word_meanings": [{"word": "desert", "meaning": "deserto", "note": ""}, {"word": "wooden", "meaning": "de madeira", "note": ""}, {"word": "saloon", "meaning": "saloon, bar", "note": ""}, {"word": "stranger", "meaning": "forasteiro", "note": ""}, {"word": "hat", "meaning": "chapéu", "note": ""}, {"word": "barman", "meaning": "atendente de bar", "note": ""}, {"word": "traveler", "meaning": "viajante", "note": ""}], "exercises": {"grammar": [{"point": "There is / There are", "explanation_pt": "'There is one street' e 'There are a few houses' descrevem o lugar."}], "multiple_choice": [{"question": "Where is the town?", "options": ["In the mountains", "In a forest", "In the desert", "By the sea"], "correct_index": 2, "explanation": "No deserto."}, {"question": "What is the weather?", "options": ["Rainy", "Very hot", "Cold", "Snowy"], "correct_index": 1, "explanation": "Muito quente."}, {"question": "Who comes to town?", "options": ["The sheriff", "A stranger", "A child", "A doctor"], "correct_index": 1, "explanation": "Um forasteiro."}, {"question": "What does he ask for?", "options": ["Water", "A room", "A horse", "Food"], "correct_index": 0, "explanation": "Água."}, {"question": "What does he say he is?", "options": ["A thief", "A cowboy", "A traveler", "A sheriff"], "correct_index": 2, "explanation": "Um viajante."}], "open_questions": [{"question": "Would you visit a desert town?", "key_points_pt": ["opinar"]}, {"question": "What do you see in a small town?", "key_points_pt": ["descrever"]}]}}, {"level": "A1", "genre": "western", "title": "The Sheriff's Star", "paragraphs": ["Sam is the sheriff of a small town. He wears a silver star on his shirt. Every day, he walks along the street and says hello to everyone.", "One day, a boy loses his dog. \"Please, Sheriff, help me,\" he says. Sam looks everywhere. He asks the baker and the farmer.", "At last, he finds the dog behind the church. \"Here he is!\" says Sam. The boy hugs his dog. \"Thank you, Sheriff!\" Sam smiles. He loves his job."], "paragraphs_pt": ["Sam é o xerife de uma cidade pequena. Usa uma estrela de prata na camisa. Todo dia, anda pela rua e cumprimenta todos.", "Um dia, um menino perde o cachorro. \"Por favor, xerife, me ajude\", diz. Sam procura em toda parte. Pergunta ao padeiro e ao fazendeiro.", "Por fim, acha o cachorro atrás da igreja. \"Aqui está!\", diz Sam. O menino abraça o cachorro. \"Obrigado, xerife!\" Sam sorri. Ele ama seu trabalho."], "hard_words": ["sheriff", "silver", "farmer", "church"], "vocab": [{"word": "sheriff", "meaning": "xerife", "note": ""}, {"word": "star", "meaning": "estrela", "note": ""}, {"word": "silver", "meaning": "prata", "note": ""}, {"word": "baker", "meaning": "padeiro", "note": ""}, {"word": "farmer", "meaning": "fazendeiro", "note": ""}, {"word": "church", "meaning": "igreja", "note": ""}, {"word": "hugs", "meaning": "abraça", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "sheriff", "meaning": "xerife", "note": ""}, {"word": "star", "meaning": "estrela", "note": ""}, {"word": "silver", "meaning": "prata", "note": ""}, {"word": "baker", "meaning": "padeiro", "note": ""}, {"word": "farmer", "meaning": "fazendeiro", "note": ""}, {"word": "church", "meaning": "igreja", "note": ""}, {"word": "hugs", "meaning": "abraça", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "'He wears a silver star' descreve algo habitual."}], "multiple_choice": [{"question": "Who is Sam?", "options": ["A cowboy", "A farmer", "The sheriff", "A baker"], "correct_index": 2, "explanation": "O xerife."}, {"question": "What does he wear?", "options": ["A black coat", "A red hat", "A silver star", "A blue shirt"], "correct_index": 2, "explanation": "Uma estrela de prata."}, {"question": "What does the boy lose?", "options": ["His dog", "His hat", "His horse", "His bag"], "correct_index": 0, "explanation": "O cachorro."}, {"question": "Who does Sam ask?", "options": ["The baker and the farmer", "The doctor", "The mayor", "The teacher"], "correct_index": 0, "explanation": "O padeiro e o fazendeiro."}, {"question": "Where is the dog?", "options": ["Behind the church", "At the bank", "In the saloon", "In the field"], "correct_index": 0, "explanation": "Atrás da igreja."}], "open_questions": [{"question": "What does a sheriff do?", "key_points_pt": ["explicar"]}, {"question": "Have you lost a pet?", "key_points_pt": ["contar"]}]}}, {"level": "A2", "genre": "western", "title": "The Gold Mine", "paragraphs": ["Old Pete lived alone in a cabin near the mountains. Every morning, he took his pick and his donkey and walked to a small mine. People in town laughed at him. \"There is no gold there,\" they said. \"You are wasting your time.\"", "Pete did not listen. He believed that one day he would find a treasure. For twenty years, he dug in the dark with a lamp, singing old songs to his donkey. He ate beans and bread, and his clothes were full of holes.", "One cold afternoon, his pick hit something hard. He cleaned the stone with his hands, and it shone like the sun. Pete cried with happiness. He did not become rich in a day, but he sold the gold slowly and bought a farm. Nobody laughed at him again."], "paragraphs_pt": ["O velho Pete vivia sozinho numa cabana perto das montanhas. Toda manhã, pegava a picareta e o burro e caminhava até uma pequena mina. As pessoas da cidade riam dele. \"Não há ouro lá\", diziam. \"Você está perdendo tempo.\"", "Pete não ouvia. Acreditava que um dia encontraria um tesouro. Por vinte anos, cavou no escuro com uma lamparina, cantando velhas músicas ao burro. Comia feijão e pão, e as roupas estavam cheias de buracos.", "Numa tarde fria, a picareta bateu em algo duro. Limpou a pedra com as mãos e ela brilhou como o sol. Pete chorou de felicidade. Não ficou rico num dia, mas vendeu o ouro devagar e comprou uma fazenda. Ninguém riu dele de novo."], "hard_words": ["cabin", "donkey", "treasure", "shone"], "vocab": [{"word": "cabin", "meaning": "cabana", "note": ""}, {"word": "pick", "meaning": "picareta", "note": ""}, {"word": "donkey", "meaning": "burro", "note": ""}, {"word": "mine", "meaning": "mina", "note": ""}, {"word": "treasure", "meaning": "tesouro", "note": ""}, {"word": "lamp", "meaning": "lamparina", "note": ""}, {"word": "shone", "meaning": "brilhou", "note": ""}, {"word": "farm", "meaning": "fazenda", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are", "were"], "irregular": ["lived", "took", "walked", "laughed", "said", "did", "believed", "would", "dug", "ate", "cleaned", "shone", "cried", "sold", "bought"], "phrasal": ["walked to", "dug in"], "wh": [], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "cabin", "meaning": "cabana", "note": ""}, {"word": "pick", "meaning": "picareta", "note": ""}, {"word": "donkey", "meaning": "burro", "note": ""}, {"word": "mine", "meaning": "mina", "note": ""}, {"word": "treasure", "meaning": "tesouro", "note": ""}, {"word": "lamp", "meaning": "lamparina", "note": ""}, {"word": "shone", "meaning": "brilhou", "note": ""}, {"word": "farm", "meaning": "fazenda", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'lived', 'believed', 'dug' contam a história."}, {"point": "Not... again", "explanation_pt": "'Nobody laughed at him again' mostra que parou."}], "multiple_choice": [{"question": "Where did Pete live?", "options": ["On a ship", "In a city", "In a hotel", "In a cabin near the mountains"], "correct_index": 3, "explanation": "Numa cabana perto das montanhas."}, {"question": "What did people say?", "options": ["Come to town", "Sell it", "There is no gold there", "Good luck"], "correct_index": 2, "explanation": "Que não havia ouro."}, {"question": "How long did he dig?", "options": ["Twenty years", "Two years", "Two months", "Two days"], "correct_index": 0, "explanation": "Vinte anos."}, {"question": "What did he find?", "options": ["A map", "Water", "A bone", "Gold"], "correct_index": 3, "explanation": "Ouro."}, {"question": "What did he do with the gold?", "options": ["Travelled", "Bought a farm", "Lost it", "Gave it away"], "correct_index": 1, "explanation": "Comprou uma fazenda."}], "open_questions": [{"question": "Do you believe in persistence?", "key_points_pt": ["opinar"]}, {"question": "What did people laugh at that later worked?", "key_points_pt": ["contar"]}]}}, {"level": "A2", "genre": "western", "title": "The Stagecoach Ride", "paragraphs": ["Lucy took the stagecoach to Dry Creek to visit her uncle. The journey was long, hot and dusty. She sat next to a talkative farmer, a quiet priest and a young man with a guitar. The horses ran along the red road for hours.", "Suddenly, the driver stopped. A tree was lying across the road. \"Everybody out,\" he said. Two masked men appeared from behind the rocks. \"Hands up!\" shouted one. The farmer turned pale, and the priest closed his eyes. The young man with the guitar stepped forward.", "\"Gentlemen,\" he said, \"we are poor travellers, but I can offer you a song.\" He played so beautifully that the robbers listened in silence. When he finished, they took off their masks, wiped their eyes and left without taking anything. Lucy laughed. It was the strangest robbery of her life."], "paragraphs_pt": ["Lucy pegou a diligência para Dry Creek para visitar o tio. A viagem foi longa, quente e empoeirada. Sentou-se ao lado de um fazendeiro tagarela, um padre quieto e um jovem com um violão. Os cavalos correram pela estrada vermelha por horas.", "De repente, o cocheiro parou. Uma árvore estava atravessada na estrada. \"Todos para fora\", disse. Dois homens mascarados apareceram atrás das pedras. \"Mãos ao alto!\", gritou um. O fazendeiro empalideceu e o padre fechou os olhos. O jovem com o violão deu um passo à frente.", "\"Cavalheiros\", disse, \"somos viajantes pobres, mas posso lhes oferecer uma canção.\" Tocou tão lindamente que os ladrões ouviram em silêncio. Quando terminou, tiraram as máscaras, enxugaram os olhos e foram embora sem levar nada. Lucy riu. Foi o assalto mais estranho de sua vida."], "hard_words": ["stagecoach", "dusty", "masked", "robbers"], "vocab": [{"word": "stagecoach", "meaning": "diligência", "note": ""}, {"word": "dusty", "meaning": "empoeirada", "note": ""}, {"word": "driver", "meaning": "cocheiro", "note": ""}, {"word": "masked", "meaning": "mascarados", "note": ""}, {"word": "robbers", "meaning": "ladrões", "note": ""}, {"word": "pale", "meaning": "pálido", "note": ""}, {"word": "guitar", "meaning": "violão", "note": ""}, {"word": "priest", "meaning": "padre", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "are"], "irregular": ["took", "sat", "ran", "stopped", "said", "masked", "appeared", "shouted", "turned", "closed", "stepped", "played", "listened", "finished", "wiped", "left", "laughed"], "phrasal": ["took off", "stepped forward"], "wh": ["when"], "connectors": ["and", "but", "so", "when", "suddenly"], "comparative": []}, "word_meanings": [{"word": "stagecoach", "meaning": "diligência", "note": ""}, {"word": "dusty", "meaning": "empoeirada", "note": ""}, {"word": "driver", "meaning": "cocheiro", "note": ""}, {"word": "masked", "meaning": "mascarados", "note": ""}, {"word": "robbers", "meaning": "ladrões", "note": ""}, {"word": "pale", "meaning": "pálido", "note": ""}, {"word": "guitar", "meaning": "violão", "note": ""}, {"word": "priest", "meaning": "padre", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'took', 'sat', 'stopped' contam a viagem."}, {"point": "Superlativo", "explanation_pt": "'the strangest robbery of her life' compara com todas as outras."}], "multiple_choice": [{"question": "Where was Lucy going?", "options": ["To Dallas", "To Dry Creek", "To the sea", "To Mexico"], "correct_index": 1, "explanation": "A Dry Creek."}, {"question": "What blocked the road?", "options": ["A river", "A tree", "A rock", "A wall"], "correct_index": 1, "explanation": "Uma árvore."}, {"question": "Who appeared?", "options": ["A bear", "Two masked men", "A sheriff", "A priest"], "correct_index": 1, "explanation": "Dois homens mascarados."}, {"question": "What did the young man do?", "options": ["Played a song", "Ran away", "Fought", "Paid"], "correct_index": 0, "explanation": "Tocou uma canção."}, {"question": "What did the robbers do?", "options": ["Took money", "Left without taking anything", "Took the horses", "Fought"], "correct_index": 1, "explanation": "Foram embora sem levar nada."}], "open_questions": [{"question": "Can music change people's minds?", "key_points_pt": ["opinar"]}, {"question": "What would you do in such a robbery?", "key_points_pt": ["imaginar"]}]}}, {"level": "A2", "genre": "western", "title": "The Lost Horse", "paragraphs": ["Ellie was twelve years old and lived on a farm with her father. Her favourite thing in the world was her white horse, Snow. One stormy night, the barn door opened, and Snow ran away. In the morning, Ellie cried when she saw the empty stable.", "She took a coat, a sandwich and a rope and rode her father's old mule into the hills. She followed the hoofprints in the mud for three hours. At noon, she heard a soft neigh behind some trees. Snow was there, caught in a thorny bush.", "Ellie cut the bush carefully with her knife and freed him. His leg was bleeding a little, but it was not serious. She cleaned the wound with water and rode home slowly, leading Snow behind the mule. Her father was waiting at the gate. \"I knew you'd find him,\" he said, and hugged her."], "paragraphs_pt": ["Ellie tinha doze anos e vivia numa fazenda com o pai. Sua coisa favorita no mundo era seu cavalo branco, Neve. Numa noite de tempestade, a porta do celeiro se abriu e Neve fugiu. De manhã, Ellie chorou ao ver a baia vazia.", "Pegou um casaco, um sanduíche e uma corda e montou a velha mula do pai rumo às colinas. Seguiu as pegadas na lama por três horas. Ao meio-dia, ouviu um relincho suave atrás de umas árvores. Neve estava lá, preso num arbusto espinhoso.", "Ellie cortou o arbusto com cuidado com a faca e o libertou. A perna dele sangrava um pouco, mas não era grave. Limpou o ferimento com água e voltou para casa devagar, conduzindo Neve atrás da mula. O pai esperava no portão. \"Eu sabia que você o acharia\", disse, e a abraçou."], "hard_words": ["barn", "mule", "thorny", "wound"], "vocab": [{"word": "barn", "meaning": "celeiro", "note": ""}, {"word": "stable", "meaning": "baia", "note": ""}, {"word": "mule", "meaning": "mula", "note": ""}, {"word": "hoofprints", "meaning": "pegadas de casco", "note": ""}, {"word": "neigh", "meaning": "relincho", "note": ""}, {"word": "thorny", "meaning": "espinhoso", "note": ""}, {"word": "wound", "meaning": "ferimento", "note": ""}, {"word": "gate", "meaning": "portão", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["lived", "opened", "ran", "cried", "saw", "took", "rode", "followed", "heard", "caught", "freed", "cleaned", "wound", "knew", "said", "hugged"], "phrasal": ["ran away", "rode home"], "wh": ["when"], "connectors": ["and", "but", "when"], "comparative": []}, "word_meanings": [{"word": "barn", "meaning": "celeiro", "note": ""}, {"word": "stable", "meaning": "baia", "note": ""}, {"word": "mule", "meaning": "mula", "note": ""}, {"word": "hoofprints", "meaning": "pegadas de casco", "note": ""}, {"word": "neigh", "meaning": "relincho", "note": ""}, {"word": "thorny", "meaning": "espinhoso", "note": ""}, {"word": "wound", "meaning": "ferimento", "note": ""}, {"word": "gate", "meaning": "portão", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'took', 'followed', 'heard' contam a busca."}, {"point": "Knew you'd find", "explanation_pt": "'I knew you'd find him' usa would no discurso indireto."}], "multiple_choice": [{"question": "What was Ellie's favourite thing?", "options": ["Her white horse", "Her dog", "Her farm", "Her coat"], "correct_index": 0, "explanation": "Seu cavalo branco."}, {"question": "What happened one stormy night?", "options": ["A thief came", "The horse ran away", "Her father left", "The barn burned"], "correct_index": 1, "explanation": "O cavalo fugiu."}, {"question": "How did she find him?", "options": ["By luck", "Following hoofprints", "By asking", "By a map"], "correct_index": 1, "explanation": "Seguindo pegadas."}, {"question": "Where was Snow?", "options": ["In a river", "In a barn", "In a town", "Caught in a thorny bush"], "correct_index": 3, "explanation": "Preso num arbusto."}, {"question": "What did her father say?", "options": ["You are late", "I knew you'd find him", "Never again", "Go to bed"], "correct_index": 1, "explanation": "'Eu sabia que você o acharia.'"}], "open_questions": [{"question": "Have you lost something you loved?", "key_points_pt": ["contar"]}, {"question": "How can animals be family?", "key_points_pt": ["explicar"]}]}}, {"level": "B1", "genre": "western", "title": "The Duel That Never Happened", "paragraphs": ["At noon on a dusty Friday, the whole town of Carson's Gulch gathered in the main street. Two men faced each other thirty paces apart: Black Jack Morrow, famous for his speed, and young Billy Cade, who had come to challenge him. Women closed the shutters, and children peeked through the cracks.", "The sheriff, an old man named Walker, stood between them. \"Gentlemen, nobody has to die today,\" he said. \"What is this about?\" Billy swallowed. \"He insulted my mother.\" \"I said she makes the worst pie in the county,\" replied Jack. \"It was a joke.\" A silence fell. Then someone in the crowd began to laugh.", "It turned out that Billy's mother, Dolly, was a friend of Jack's, and the comment had been repeated and exaggerated by half the town until it became a scandal. Jack apologised on the spot. Billy, embarrassed, lowered his hand. They shook hands under the hot sun.", "Dolly, who had been listening from the window, came out with a pie. \"Try it before you decide,\" she said. Jack took a bite, thought hard, and finally admitted, \"Fine. The second worst.\" Everyone laughed, and the duel was forgotten."], "paragraphs_pt": ["Ao meio-dia de uma sexta empoeirada, toda a cidade de Carson's Gulch se reuniu na rua principal. Dois homens se encaravam a trinta passos de distância: Jack Negro Morrow, famoso por sua velocidade, e o jovem Billy Cade, que viera desafiá-lo. Mulheres fecharam as janelas e crianças espiavam pelas frestas.", "O xerife, um velho chamado Walker, parou entre eles. \"Cavalheiros, ninguém precisa morrer hoje\", disse. \"Do que se trata?\" Billy engoliu em seco. \"Ele insultou minha mãe.\" \"Eu disse que ela faz a pior torta do condado\", respondeu Jack. \"Foi uma piada.\" Caiu um silêncio. Então alguém da multidão começou a rir.", "Descobriu-se que a mãe de Billy, Dolly, era amiga de Jack, e o comentário fora repetido e exagerado por metade da cidade até virar escândalo. Jack pediu desculpas na hora. Billy, envergonhado, baixou a mão. Apertaram as mãos sob o sol quente.", "Dolly, que ouvira da janela, saiu com uma torta. \"Experimentem antes de decidir\", disse. Jack deu uma mordida, pensou bem e enfim admitiu: \"Tudo bem. A segunda pior.\" Todos riram e o duelo foi esquecido."], "hard_words": ["shutters", "insulted", "scandal", "duel"], "vocab": [{"word": "gathered", "meaning": "reuniu-se", "note": ""}, {"word": "challenge", "meaning": "desafiar", "note": ""}, {"word": "shutters", "meaning": "venezianas", "note": ""}, {"word": "sheriff", "meaning": "xerife", "note": ""}, {"word": "insulted", "meaning": "insultou", "note": ""}, {"word": "scandal", "meaning": "escândalo", "note": ""}, {"word": "apologised", "meaning": "pediu desculpas", "note": ""}, {"word": "duel", "meaning": "duelo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was", "been"], "irregular": ["gathered", "faced", "had", "closed", "peeked", "named", "stood", "said", "swallowed", "insulted", "replied", "fell", "began", "turned", "repeated", "exaggerated", "became", "apologised", "embarrassed", "lowered", "shook", "came", "took", "thought", "admitted", "laughed", "forgotten"], "phrasal": ["turned out", "shook hands"], "wh": ["who", "what"], "connectors": ["and", "then", "before", "until", "finally"], "comparative": []}, "word_meanings": [{"word": "gathered", "meaning": "reuniu-se", "note": ""}, {"word": "challenge", "meaning": "desafiar", "note": ""}, {"word": "shutters", "meaning": "venezianas", "note": ""}, {"word": "sheriff", "meaning": "xerife", "note": ""}, {"word": "insulted", "meaning": "insultou", "note": ""}, {"word": "scandal", "meaning": "escândalo", "note": ""}, {"word": "apologised", "meaning": "pediu desculpas", "note": ""}, {"word": "duel", "meaning": "duelo", "note": ""}], "exercises": {"grammar": [{"point": "Had been listening", "explanation_pt": "'who had been listening from the window' mostra uma ação em andamento antes."}, {"point": "It turned out", "explanation_pt": "'It turned out that Billy's mother was a friend' revela algo inesperado."}], "multiple_choice": [{"question": "Where did the duel start?", "options": ["The saloon", "The bank", "The main street", "A farm"], "correct_index": 2, "explanation": "Na rua principal."}, {"question": "Why did Billy challenge Jack?", "options": ["He insulted his mother", "He won money", "He lied", "He stole"], "correct_index": 0, "explanation": "Insultou a mãe dele."}, {"question": "What had Jack actually said?", "options": ["She is rude", "She is poor", "She makes the worst pie", "She is old"], "correct_index": 2, "explanation": "A pior torta do condado."}, {"question": "What did Dolly do?", "options": ["Shouted", "Brought a pie", "Left", "Called the sheriff"], "correct_index": 1, "explanation": "Trouxe uma torta."}, {"question": "How did the duel end?", "options": ["With a fight", "With a trial", "With laughter", "With a shot"], "correct_index": 2, "explanation": "Com risadas."}], "open_questions": [{"question": "How do rumours grow?", "key_points_pt": ["explicar"]}, {"question": "Have you ever argued over a misunderstanding?", "key_points_pt": ["contar"]}]}}, {"level": "B1", "genre": "western", "title": "The Train Robbers' Mistake", "paragraphs": ["The Dalton gang planned the robbery for months. The Pacific Express would carry the payroll of three mines, and the gang had decided to stop it at Rattlesnake Bridge. Everything was prepared: horses, masks, dynamite and a map drawn by the smartest of the brothers, Ned.", "On the day, the gang waited behind the rocks. When the train finally appeared, they blocked the track and rushed to the last carriage. Inside, they found a startled old woman knitting and a basket of apples. \"Where is the money?\" shouted Ned. The woman shrugged. \"I only know where the next station is.\"", "It turned out that Ned, in his excitement, had read the timetable wrongly. The train that carried the payroll had passed an hour earlier. The Pacific Express carried only passengers and a few crates of vegetables. The gang stood in embarrassed silence.", "In the end, the old woman offered them apples and a ride to town. The sheriff arrested them without difficulty, since they were too ashamed to run. The story became a legend in the region, and the bridge has been called \"Dalton's Mistake\" ever since."], "paragraphs_pt": ["A gangue Dalton planejou o assalto por meses. O Expresso do Pacífico levaria a folha de pagamento de três minas e a gangue decidira parar o trem na Ponte da Cascavel. Tudo estava preparado: cavalos, máscaras, dinamite e um mapa desenhado pelo mais inteligente dos irmãos, Ned.", "No dia, a gangue esperou atrás das pedras. Quando o trem finalmente apareceu, bloquearam os trilhos e correram ao último vagão. Dentro, encontraram uma velha assustada tricotando e uma cesta de maçãs. \"Onde está o dinheiro?\", gritou Ned. A mulher deu de ombros. \"Só sei onde fica a próxima estação.\"", "Descobriu-se que Ned, na empolgação, lera o horário errado. O trem que levava a folha de pagamento passara uma hora antes. O Expresso do Pacífico levava só passageiros e algumas caixas de legumes. A gangue ficou em silêncio constrangido.", "No fim, a velha lhes ofereceu maçãs e uma carona até a cidade. O xerife os prendeu sem dificuldade, pois estavam envergonhados demais para fugir. A história virou lenda na região, e a ponte se chama \"Erro dos Dalton\" desde então."], "hard_words": ["payroll", "carriage", "timetable", "crates"], "vocab": [{"word": "gang", "meaning": "gangue", "note": ""}, {"word": "payroll", "meaning": "folha de pagamento", "note": ""}, {"word": "dynamite", "meaning": "dinamite", "note": ""}, {"word": "carriage", "meaning": "vagão", "note": ""}, {"word": "startled", "meaning": "assustada", "note": ""}, {"word": "knitting", "meaning": "tricotando", "note": ""}, {"word": "timetable", "meaning": "horário", "note": ""}, {"word": "crates", "meaning": "caixas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is", "were", "been"], "irregular": ["planned", "would", "had", "decided", "prepared", "drawn", "waited", "appeared", "blocked", "rushed", "found", "startled", "shouted", "shrugged", "turned", "carried", "passed", "stood", "embarrassed", "offered", "arrested", "became", "called"], "phrasal": ["rushed to", "stood in"], "wh": ["where", "when"], "connectors": ["and", "when", "since", "finally"], "comparative": []}, "word_meanings": [{"word": "gang", "meaning": "gangue", "note": ""}, {"word": "payroll", "meaning": "folha de pagamento", "note": ""}, {"word": "dynamite", "meaning": "dinamite", "note": ""}, {"word": "carriage", "meaning": "vagão", "note": ""}, {"word": "startled", "meaning": "assustada", "note": ""}, {"word": "knitting", "meaning": "tricotando", "note": ""}, {"word": "timetable", "meaning": "horário", "note": ""}, {"word": "crates", "meaning": "caixas", "note": ""}], "exercises": {"grammar": [{"point": "Had read wrongly", "explanation_pt": "'Ned had read the timetable wrongly' mostra um erro anterior."}, {"point": "Ever since", "explanation_pt": "'has been called... ever since' mostra continuidade."}], "multiple_choice": [{"question": "What did the gang plan?", "options": ["A train robbery", "A bank robbery", "A trip", "A trade"], "correct_index": 0, "explanation": "Assalto a trem."}, {"question": "What did they find in the last carriage?", "options": ["Guards", "Gold", "An old woman and apples", "Money"], "correct_index": 2, "explanation": "Uma velha e maçãs."}, {"question": "What was Ned's mistake?", "options": ["He was late", "He lost the map", "He forgot the dynamite", "He read the timetable wrongly"], "correct_index": 3, "explanation": "Leu o horário errado."}, {"question": "What did the old woman offer?", "options": ["Money", "Help", "A map", "Apples and a ride"], "correct_index": 3, "explanation": "Maçãs e carona."}, {"question": "What is the bridge called now?", "options": ["Rattlesnake Bridge", "Pacific Bridge", "Dalton's Mistake", "Old Bridge"], "correct_index": 2, "explanation": "'Erro dos Dalton'."}], "open_questions": [{"question": "Why do careful plans fail?", "key_points_pt": ["explicar"]}, {"question": "Do you like humorous legends?", "key_points_pt": ["opinar"]}]}}, {"level": "B1", "genre": "western", "title": "The Last Cattle Drive", "paragraphs": ["Every spring for forty years, Hank had driven cattle from the ranch to the railway town three hundred kilometres away. The journey took six weeks, across rivers and prairies, and he knew every rock and every shortcut. This year, the rancher told him it would be the last drive: the railway had finally reached their valley, and cattle would travel by train.", "Hank felt hollow but said nothing. With four young cowboys, he started the drive at dawn. Along the way, he told them stories: the flood of '98, the night a thunderstorm scattered two hundred cows, the old cook who made the best coffee in the West. The young men listened as if they were hearing history.", "On the last evening, camped beside the river, the youngest cowboy asked, \"What will you do now?\" Hank looked at the stars for a long time. \"I'll tell the story to anyone who'll listen,\" he said. \"And I'll teach you to be better than I was.\"", "When they arrived in town, the cattle were sold, and the cowboys received their pay. Hank bought a small house near the station. Every morning, he watched the trains with a cup of coffee. He no longer rode, but each time a cattle car passed, he raised his hat in salute."], "paragraphs_pt": ["Toda primavera, por quarenta anos, Hank conduzira gado do rancho à cidade da ferrovia a trezentos quilômetros. A viagem levava seis semanas, por rios e pradarias, e ele conhecia cada pedra e cada atalho. Este ano, o fazendeiro disse que seria a última condução: a ferrovia finalmente chegara ao vale e o gado viajaria de trem.", "Hank sentiu-se vazio, mas nada disse. Com quatro jovens vaqueiros, iniciou a viagem ao amanhecer. Pelo caminho, contou histórias: a enchente de '98, a noite em que uma tempestade dispersou duzentas vacas, o velho cozinheiro que fazia o melhor café do Oeste. Os jovens ouviam como se escutassem história.", "Na última noite, acampados junto ao rio, o mais novo perguntou: \"O que o senhor vai fazer agora?\" Hank olhou as estrelas por muito tempo. \"Vou contar a história a quem quiser ouvir\", disse. \"E vou ensinar vocês a serem melhores do que eu fui.\"", "Ao chegar à cidade, o gado foi vendido e os vaqueiros receberam o pagamento. Hank comprou uma casinha perto da estação. Toda manhã, via os trens com uma xícara de café. Já não cavalgava, mas cada vez que um vagão de gado passava, erguia o chapéu em saudação."], "hard_words": ["cattle", "prairies", "scattered", "salute"], "vocab": [{"word": "cattle", "meaning": "gado", "note": ""}, {"word": "drive", "meaning": "condução de gado", "note": ""}, {"word": "prairies", "meaning": "pradarias", "note": ""}, {"word": "shortcut", "meaning": "atalho", "note": ""}, {"word": "rancher", "meaning": "fazendeiro", "note": ""}, {"word": "hollow", "meaning": "vazio", "note": ""}, {"word": "scattered", "meaning": "dispersou", "note": ""}, {"word": "salute", "meaning": "saudação", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "were", "was"], "irregular": ["had", "driven", "took", "knew", "told", "would", "reached", "felt", "said", "started", "scattered", "made", "listened", "camped", "asked", "looked", "arrived", "sold", "received", "bought", "watched", "rode", "passed", "raised"], "phrasal": ["raised his hat", "camped beside"], "wh": ["who", "what", "when"], "connectors": ["and", "but", "when", "finally", "if", "as"], "comparative": []}, "word_meanings": [{"word": "cattle", "meaning": "gado", "note": ""}, {"word": "drive", "meaning": "condução de gado", "note": ""}, {"word": "prairies", "meaning": "pradarias", "note": ""}, {"word": "shortcut", "meaning": "atalho", "note": ""}, {"word": "rancher", "meaning": "fazendeiro", "note": ""}, {"word": "hollow", "meaning": "vazio", "note": ""}, {"word": "scattered", "meaning": "dispersou", "note": ""}, {"word": "salute", "meaning": "saudação", "note": ""}], "exercises": {"grammar": [{"point": "Had driven for forty years", "explanation_pt": "'Hank had driven cattle' mostra uma experiência anterior."}, {"point": "Will", "explanation_pt": "'I'll tell the story' expressa decisão."}], "multiple_choice": [{"question": "How long had Hank driven cattle?", "options": ["Ten years", "One year", "Forty years", "Four years"], "correct_index": 2, "explanation": "Quarenta anos."}, {"question": "Why was it the last drive?", "options": ["The railway reached the valley", "The ranch closed", "There was no cattle", "Hank was old"], "correct_index": 0, "explanation": "A ferrovia chegou."}, {"question": "What did Hank tell the young cowboys?", "options": ["Nothing", "Jokes", "Rules", "Stories"], "correct_index": 3, "explanation": "Histórias."}, {"question": "What would Hank do now?", "options": ["Travel", "Fight", "Retire to the city", "Tell stories and teach"], "correct_index": 3, "explanation": "Contar histórias e ensinar."}, {"question": "What did he do when cattle cars passed?", "options": ["Cried", "Shouted", "Ran", "Raised his hat"], "correct_index": 3, "explanation": "Ergueu o chapéu."}], "open_questions": [{"question": "How do traditions end?", "key_points_pt": ["discutir"]}, {"question": "What do older people teach us?", "key_points_pt": ["explicar"]}]}}, {"level": "B2", "genre": "western", "title": "The Town That Bought a Sheriff", "paragraphs": ["The town of Rusty Spur had a problem: every sheriff they hired either ran away after a month or took bribes from the rich cattle baron, Mr. Harlan. The citizens were tired. At a meeting in the church, someone proposed a radical idea. \"Let's advertise for a sheriff in the East. Someone who doesn't know Harlan.\"", "After some weeks, a thin young man named Edgar Finch arrived by stagecoach. He wore glasses, carried a suitcase full of books and did not even own a gun. The citizens' hearts sank. Harlan laughed so hard that he nearly fell off his horse.", "Finch, however, had one advantage: he was a trained lawyer. He read the town's founding charter and discovered that Harlan's ranch occupied land that legally belonged to the community. Without firing a single shot, he presented the case in the territorial court. After three months, the judge ruled in the town's favour.", "Harlan, who lost half his land, tried to intimidate Finch, but the entire town stood behind him. When asked about his methods, Finch cleaned his glasses and said, \"Out here, people believe that justice is carried in a holster. Sometimes it is carried in a briefcase.\""], "paragraphs_pt": ["A cidade de Rusty Spur tinha um problema: todo xerife contratado ou fugia após um mês ou aceitava suborno do rico barão do gado, o Sr. Harlan. Os cidadãos estavam cansados. Numa reunião na igreja, alguém propôs uma ideia radical. \"Vamos anunciar por um xerife no Leste. Alguém que não conheça Harlan.\"", "Após algumas semanas, um jovem magro chamado Edgar Finch chegou de diligência. Usava óculos, carregava uma mala cheia de livros e nem sequer tinha arma. Os corações dos cidadãos afundaram. Harlan riu tanto que quase caiu do cavalo.", "Finch, porém, tinha uma vantagem: era advogado formado. Leu a carta de fundação da cidade e descobriu que o rancho de Harlan ocupava terra que legalmente pertencia à comunidade. Sem disparar um tiro, apresentou o caso no tribunal do território. Após três meses, o juiz decidiu a favor da cidade.", "Harlan, que perdeu metade das terras, tentou intimidar Finch, mas a cidade inteira o apoiou. Perguntado sobre seus métodos, Finch limpou os óculos e disse: \"Por aqui, as pessoas acreditam que a justiça se carrega num coldre. Às vezes se carrega numa pasta.\""], "hard_words": ["bribes", "charter", "intimidate", "holster"], "vocab": [{"word": "bribes", "meaning": "suborno", "note": ""}, {"word": "baron", "meaning": "barão", "note": ""}, {"word": "radical", "meaning": "radical", "note": ""}, {"word": "advertise", "meaning": "anunciar", "note": ""}, {"word": "charter", "meaning": "carta de fundação", "note": ""}, {"word": "territorial", "meaning": "territorial", "note": ""}, {"word": "intimidate", "meaning": "intimidar", "note": ""}, {"word": "holster", "meaning": "coldre", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was", "is"], "irregular": ["had", "hired", "ran", "took", "tired", "proposed", "named", "arrived", "wore", "carried", "did", "sank", "laughed", "fell", "trained", "discovered", "occupied", "belonged", "shot", "presented", "ruled", "lost", "tried", "stood", "asked", "cleaned", "said"], "phrasal": ["stood behind", "ran away"], "wh": ["who", "when"], "connectors": ["and", "but", "however", "so", "after", "when", "or"], "comparative": []}, "word_meanings": [{"word": "bribes", "meaning": "suborno", "note": ""}, {"word": "baron", "meaning": "barão", "note": ""}, {"word": "radical", "meaning": "radical", "note": ""}, {"word": "advertise", "meaning": "anunciar", "note": ""}, {"word": "charter", "meaning": "carta de fundação", "note": ""}, {"word": "territorial", "meaning": "territorial", "note": ""}, {"word": "intimidate", "meaning": "intimidar", "note": ""}, {"word": "holster", "meaning": "coldre", "note": ""}], "exercises": {"grammar": [{"point": "Either... or", "explanation_pt": "'either ran away... or took bribes' apresenta duas opções comuns."}, {"point": "Without + ing", "explanation_pt": "'Without firing a single shot' mostra como ele agiu."}], "multiple_choice": [{"question": "What was the town's problem?", "options": ["Bandits", "Sheriffs ran away or took bribes", "Drought", "Fire"], "correct_index": 1, "explanation": "Xerifes fugiam ou aceitavam suborno."}, {"question": "Who was Edgar Finch?", "options": ["A priest", "A lawyer", "A cowboy", "A soldier"], "correct_index": 1, "explanation": "Um advogado."}, {"question": "What did he discover?", "options": ["A secret door", "A spy", "The ranch occupied community land", "A treasure"], "correct_index": 2, "explanation": "O rancho ocupava terra comunitária."}, {"question": "How did he win?", "options": ["In the court, without a shot", "By running", "By paying", "By fighting"], "correct_index": 0, "explanation": "No tribunal."}, {"question": "What did he say about justice?", "options": ["It's money", "It's a gun", "It's luck", "Sometimes it's carried in a briefcase"], "correct_index": 3, "explanation": "Às vezes se carrega numa pasta."}], "open_questions": [{"question": "Is law stronger than weapons?", "key_points_pt": ["debater"]}, {"question": "How can outsiders help a town?", "key_points_pt": ["explicar"]}]}}, {"level": "B2", "genre": "western", "title": "The Widow of Silver Creek", "paragraphs": ["When Josiah Marsh died, the people of Silver Creek expected his widow, Constance, to sell the ranch and return East. She was elegant, soft-spoken and, by their reckoning, thoroughly unsuited to the rough life of the frontier. The banker called the next week, politely hinting that he would buy the property at a generous price.", "Constance listened with great attention, thanked him and refused. She began to rise before dawn, learning to manage the herd, repair the fences and negotiate with the hands, some of whom resented taking orders from a woman. She made mistakes in her first year, lost a dozen calves in a blizzard and almost lost the ranch. But she kept books with a precision that astonished the banker.", "By the third year, the ranch was prospering, and Constance had acquired a reputation for fairness. She paid her cowboys on time, shared profits at Christmas and educated the orphans of the town in a small school she built beside the barn. Even the sceptics came to respect her.", "Years later, a young journalist asked how she had survived in a world that tried to push her out. Constance smiled and answered, \"They underestimated me, and I let them. It's astonishing how much one can accomplish while being doubted.\" On her grave, the people of Silver Creek inscribed two words: \"She stayed.\""], "paragraphs_pt": ["Quando Josiah Marsh morreu, o povo de Silver Creek esperava que a viúva, Constance, vendesse o rancho e voltasse ao Leste. Era elegante, de voz baixa e, a seus olhos, totalmente inadequada para a vida dura da fronteira. O banqueiro visitou na semana seguinte, insinuando educadamente que compraria a propriedade por um preço generoso.", "Constance ouviu com grande atenção, agradeceu e recusou. Passou a acordar antes do amanhecer, aprendendo a manejar o rebanho, consertar as cercas e negociar com os peões, alguns dos quais ressentiam receber ordens de uma mulher. Cometeu erros no primeiro ano, perdeu uma dúzia de bezerros numa nevasca e quase perdeu o rancho. Mas mantinha os livros contábeis com uma precisão que espantou o banqueiro.", "No terceiro ano, o rancho prosperava e Constance adquirira reputação de justiça. Pagava os vaqueiros em dia, dividia lucros no Natal e educava os órfãos da cidade numa pequena escola que construiu junto ao celeiro. Até os céticos passaram a respeitá-la.", "Anos depois, um jovem jornalista perguntou como sobrevivera num mundo que tentava expulsá-la. Constance sorriu e respondeu: \"Subestimaram-me e eu deixei. É espantoso quanto se pode realizar enquanto se duvida de você.\" Em seu túmulo, o povo de Silver Creek gravou duas palavras: \"Ela ficou.\""], "hard_words": ["frontier", "resented", "blizzard", "underestimated"], "vocab": [{"word": "widow", "meaning": "viúva", "note": ""}, {"word": "frontier", "meaning": "fronteira", "note": ""}, {"word": "reckoning", "meaning": "julgamento, cálculo", "note": ""}, {"word": "herd", "meaning": "rebanho", "note": ""}, {"word": "resented", "meaning": "ressentiam", "note": ""}, {"word": "blizzard", "meaning": "nevasca", "note": ""}, {"word": "orphans", "meaning": "órfãos", "note": ""}, {"word": "underestimated", "meaning": "subestimaram", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being"], "irregular": ["died", "expected", "spoken", "called", "would", "listened", "thanked", "refused", "began", "resented", "made", "lost", "kept", "astonished", "had", "acquired", "paid", "shared", "educated", "built", "came", "asked", "survived", "tried", "smiled", "answered", "underestimated", "doubted", "inscribed", "stayed"], "phrasal": ["stayed"], "wh": ["when", "how", "whom"], "connectors": ["and", "but", "while", "before", "when"], "comparative": []}, "word_meanings": [{"word": "widow", "meaning": "viúva", "note": ""}, {"word": "frontier", "meaning": "fronteira", "note": ""}, {"word": "reckoning", "meaning": "julgamento, cálculo", "note": ""}, {"word": "herd", "meaning": "rebanho", "note": ""}, {"word": "resented", "meaning": "ressentiam", "note": ""}, {"word": "blizzard", "meaning": "nevasca", "note": ""}, {"word": "orphans", "meaning": "órfãos", "note": ""}, {"word": "underestimated", "meaning": "subestimaram", "note": ""}], "exercises": {"grammar": [{"point": "Expected + to", "explanation_pt": "'expected his widow to sell' mostra expectativa dos outros."}, {"point": "By the third year", "explanation_pt": "'By the third year, the ranch was prospering' marca um ponto no tempo."}], "multiple_choice": [{"question": "What did the town expect?", "options": ["That she would marry", "That she would die", "That she would fight", "That she would sell and leave"], "correct_index": 3, "explanation": "Que vendesse e partisse."}, {"question": "What did Constance do?", "options": ["Sold the ranch", "Left", "Refused and learned to run the ranch", "Hired a manager"], "correct_index": 2, "explanation": "Recusou e aprendeu."}, {"question": "What happened in her first year?", "options": ["She got rich", "She won a prize", "She lost calves in a blizzard", "She married"], "correct_index": 2, "explanation": "Perdeu bezerros."}, {"question": "What did she build?", "options": ["A hotel", "A small school", "A church", "A bank"], "correct_index": 1, "explanation": "Uma escolinha."}, {"question": "What was on her grave?", "options": ["Founder", "Beloved wife", "She stayed", "Rest in peace"], "correct_index": 2, "explanation": "'Ela ficou.'"}], "open_questions": [{"question": "Why are people underestimated?", "key_points_pt": ["discutir"]}, {"question": "What did you accomplish while being doubted?", "key_points_pt": ["contar"]}]}}, {"level": "C1", "genre": "western", "title": "The Preacher's Silence", "paragraphs": ["The new preacher arrived at Dry Wells on a mule, wearing a black coat gone grey with dust. The town, accustomed to evangelists who thundered threats and collected donations, awaited his first sermon with a certain wary curiosity. When Sunday came, he stood in the pulpit, surveyed the congregation for what seemed an eternity, and said nothing.", "The silence lasted a full minute, which in a crowded church is practically a geological epoch. Mothers shifted, children giggled, and old Mr. Hendry coughed in protest. At last the preacher spoke: \"That is what your town sounds like when no one is shouting.\" He then sat down. The service was the shortest on record.", "The following weeks followed the same pattern, with minor variations: a sentence here, a long pause there. People who had arrived to be told what to do found themselves listening instead to their own thoughts, a sensation many of them had successfully avoided for decades. Attendance, perversely, rose.", "When a drought threatened the town and the rancher and the farmers were on the point of violence over a well, the preacher said only, \"Sit down together and say nothing for an hour.\" They did, grudgingly. By the end, they had begun to speak, haltingly, of a shared reservoir. Later, asked how he had performed such a miracle, the preacher shrugged: \"I merely refrained from interrupting.\""], "paragraphs_pt": ["O novo pregador chegou a Dry Wells numa mula, vestindo um casaco preto que a poeira tornara cinza. A cidade, acostumada a evangelistas que trovejavam ameaças e coletavam doações, aguardou seu primeiro sermão com certa curiosidade cautelosa. Quando chegou o domingo, ele ficou no púlpito, examinou a congregação por o que pareceu uma eternidade e nada disse.", "O silêncio durou um minuto inteiro, o que, numa igreja lotada, é praticamente uma época geológica. Mães se remexeram, crianças deram risadinhas e o velho Sr. Hendry tossiu em protesto. Por fim o pregador falou: \"É assim que soa sua cidade quando ninguém está gritando.\" Então sentou-se. O culto foi o mais curto de que se tem registro.", "As semanas seguintes seguiram o mesmo padrão, com pequenas variações: uma frase aqui, uma longa pausa ali. Pessoas que chegavam para ouvir o que fazer viram-se escutando os próprios pensamentos, sensação que muitos evitaram com sucesso por décadas. A frequência, perversamente, aumentou.", "Quando uma seca ameaçou a cidade e o fazendeiro e os agricultores estavam à beira da violência por um poço, o pregador disse apenas: \"Sentem-se juntos e não digam nada por uma hora.\" Fizeram-no, a contragosto. No fim, haviam começado a falar, hesitantes, de um reservatório compartilhado. Depois, perguntado como realizara tal milagre, o pregador deu de ombros: \"Apenas me abstive de interromper.\""], "hard_words": ["sermon", "pulpit", "perversely", "grudgingly"], "vocab": [{"word": "preacher", "meaning": "pregador", "note": ""}, {"word": "sermon", "meaning": "sermão", "note": ""}, {"word": "pulpit", "meaning": "púlpito", "note": ""}, {"word": "congregation", "meaning": "congregação", "note": ""}, {"word": "perversely", "meaning": "perversamente", "note": ""}, {"word": "drought", "meaning": "seca", "note": ""}, {"word": "grudgingly", "meaning": "a contragosto", "note": ""}, {"word": "reservoir", "meaning": "reservatório", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was", "be", "were"], "irregular": ["arrived", "gone", "accustomed", "thundered", "collected", "awaited", "came", "stood", "surveyed", "seemed", "said", "lasted", "crowded", "shifted", "giggled", "coughed", "spoke", "sat", "followed", "had", "told", "found", "avoided", "rose", "threatened", "did", "begun", "shared", "asked", "performed", "shrugged", "refrained"], "phrasal": ["sat down", "refrained from"], "wh": ["who", "what", "when", "how", "which"], "connectors": ["and", "instead", "then", "when"], "comparative": []}, "word_meanings": [{"word": "preacher", "meaning": "pregador", "note": ""}, {"word": "sermon", "meaning": "sermão", "note": ""}, {"word": "pulpit", "meaning": "púlpito", "note": ""}, {"word": "congregation", "meaning": "congregação", "note": ""}, {"word": "perversely", "meaning": "perversamente", "note": ""}, {"word": "drought", "meaning": "seca", "note": ""}, {"word": "grudgingly", "meaning": "a contragosto", "note": ""}, {"word": "reservoir", "meaning": "reservatório", "note": ""}], "exercises": {"grammar": [{"point": "Accustomed to", "explanation_pt": "'accustomed to evangelists who thundered threats' indica hábito de quem ouve."}, {"point": "On the point of", "explanation_pt": "'on the point of violence' significa prestes a."}], "multiple_choice": [{"question": "How did the preacher arrive?", "options": ["On foot", "By train", "On a mule", "By stagecoach"], "correct_index": 2, "explanation": "Numa mula."}, {"question": "What did he do in the first sermon?", "options": ["Told a story", "Said nothing for a full minute", "Sang", "Shouted"], "correct_index": 1, "explanation": "Ficou em silêncio."}, {"question": "What happened to attendance?", "options": ["It fell", "It stopped", "It rose", "It stayed same"], "correct_index": 2, "explanation": "Aumentou."}, {"question": "What did he say about the well conflict?", "options": ["Pray", "Sit together and say nothing for an hour", "Dig deeper", "Fight"], "correct_index": 1, "explanation": "'Sentem-se juntos em silêncio.'"}, {"question": "How did he describe his miracle?", "options": ["He ordered", "He refrained from interrupting", "He paid", "He prayed"], "correct_index": 1, "explanation": "Absteve-se de interromper."}], "open_questions": [{"question": "Can silence resolve conflicts?", "key_points_pt": ["debater"]}, {"question": "When did listening help you?", "key_points_pt": ["contar"]}]}}, {"level": "C1", "genre": "western", "title": "The Surveyor's Line", "paragraphs": ["The territory had been sold, according to the documents, in squares of equal size; the reality, as the surveyor Aurelio Vance discovered, was that the rivers refused to cooperate. His task was to draw the line that would divide the lands of two neighbouring families, the Mercers and the Coles, who had lived in a state of mutual contempt for three generations and would have preferred, it seemed, a war to a compromise.", "He measured for weeks, in storms and in drought, refusing the bribes that both parties thoughtfully offered. The difficulty lay in a small stream that, according to the original maps, formed the boundary. Over the decades, the stream had shifted its course by half a mile, giving each family the other's best pasture. Each side demanded the line follow the old course, which flattered themselves.", "Vance did the only thing he could. He drew a line down the middle of the shifting stream, so that each family kept half of what it coveted and surrendered half of what it had grown to love. Both were furious. Both, in time, found that the arrangement required them to share the water, and thus to speak.", "On his final visit, years later, Vance found a single gate in the fence, left open, with a path worn between the two properties. A child from each family was playing beside it. The surveyor, who had always believed that his profession was to divide, understood that every boundary is also a place of meeting, if one has the patience to leave a gate."], "paragraphs_pt": ["O território fora vendido, segundo os documentos, em quadrados de tamanho igual; a realidade, como o agrimensor Aurelio Vance descobriu, era que os rios se recusavam a cooperar. Sua tarefa era traçar a linha que dividiria as terras de duas famílias vizinhas, os Mercer e os Cole, que viviam em estado de desprezo mútuo por três gerações e teriam preferido, ao que parecia, uma guerra a um acordo.", "Mediu por semanas, em tempestades e secas, recusando os subornos que ambas as partes gentilmente ofereciam. A dificuldade estava num pequeno riacho que, segundo os mapas originais, formava a fronteira. Ao longo das décadas, o riacho deslocara seu curso em meia milha, dando a cada família a melhor pastagem da outra. Cada lado exigia que a linha seguisse o curso antigo, que lhe era lisonjeiro.", "Vance fez a única coisa possível. Traçou uma linha pelo meio do riacho errante, de modo que cada família ficou com metade do que cobiçava e cedeu metade do que passara a amar. Ambas ficaram furiosas. Ambas, com o tempo, descobriram que o arranjo exigia compartilhar a água e, portanto, conversar.", "Na última visita, anos depois, Vance achou um único portão na cerca, deixado aberto, com um caminho gasto entre as duas propriedades. Uma criança de cada família brincava ao lado. O agrimensor, que sempre acreditara que sua profissão era dividir, entendeu que toda fronteira é também um lugar de encontro, se houver paciência para deixar um portão."], "hard_words": ["surveyor", "contempt", "coveted", "boundary"], "vocab": [{"word": "surveyor", "meaning": "agrimensor", "note": ""}, {"word": "contempt", "meaning": "desprezo", "note": ""}, {"word": "bribes", "meaning": "subornos", "note": ""}, {"word": "boundary", "meaning": "fronteira", "note": ""}, {"word": "pasture", "meaning": "pastagem", "note": ""}, {"word": "coveted", "meaning": "cobiçava", "note": ""}, {"word": "surrendered", "meaning": "cedeu", "note": ""}, {"word": "patience", "meaning": "paciência", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "were", "is"], "irregular": ["had", "sold", "discovered", "refused", "would", "lived", "preferred", "seemed", "measured", "offered", "lay", "formed", "shifted", "demanded", "flattered", "did", "could", "drew", "kept", "coveted", "surrendered", "grown", "found", "required", "left", "worn", "believed", "understood"], "phrasal": ["lay in", "flattered themselves"], "wh": ["who", "what", "which"], "connectors": ["so that", "and", "so", "also", "if", "as"], "comparative": []}, "word_meanings": [{"word": "surveyor", "meaning": "agrimensor", "note": ""}, {"word": "contempt", "meaning": "desprezo", "note": ""}, {"word": "bribes", "meaning": "subornos", "note": ""}, {"word": "boundary", "meaning": "fronteira", "note": ""}, {"word": "pasture", "meaning": "pastagem", "note": ""}, {"word": "coveted", "meaning": "cobiçava", "note": ""}, {"word": "surrendered", "meaning": "cedeu", "note": ""}, {"word": "patience", "meaning": "paciência", "note": ""}], "exercises": {"grammar": [{"point": "Would have preferred", "explanation_pt": "'would have preferred a war to a compromise' expressa preferência hipotética."}, {"point": "Thus", "explanation_pt": "'and thus to speak' marca consequência."}], "multiple_choice": [{"question": "What was Vance's task?", "options": ["Draw a line between two families' lands", "Build a fence", "Arrest a thief", "Find gold"], "correct_index": 0, "explanation": "Traçar a linha."}, {"question": "What was the difficulty?", "options": ["A stream had shifted course", "The families", "Rain", "The map was lost"], "correct_index": 0, "explanation": "O riacho mudara de curso."}, {"question": "What did he do?", "options": ["Drew a line down the middle of the stream", "Chose one side", "Left", "Refused"], "correct_index": 0, "explanation": "Traçou pelo meio."}, {"question": "What forced the families to speak?", "options": ["A new law", "Sharing the water", "A feast", "A war"], "correct_index": 1, "explanation": "Compartilhar a água."}, {"question": "What did he understand at the end?", "options": ["Fences are good", "Maps are exact", "Boundaries are also places of meeting", "Water is life"], "correct_index": 2, "explanation": "Fronteiras são lugares de encontro."}], "open_questions": [{"question": "Can boundaries connect as well as divide?", "key_points_pt": ["debater"]}, {"question": "When did compromise leave both sides unhappy but better off?", "key_points_pt": ["refletir"]}]}}, {"level": "C1", "genre": "western", "title": "The Photographer of the Plains", "paragraphs": ["In the summer of 1878, a travelling photographer named Ambrose Quill arrived in Cedar Flats with a wagon full of glass plates and a conviction that history would be written in silver halide. He charged a dollar per portrait and was soon busy, for the settlers of the plains, who had few mirrors and no portraits, were curious to learn what their faces looked like.", "Quill noticed a curious phenomenon. Before the exposure, his subjects arranged themselves into poses of stern, frontier dignity: lips pressed, chins lifted, eyes fixed on the horizon. Yet exposures were long, and in the seconds that followed, tiny shifts of expression would creep in: a flicker of fatigue, an involuntary tenderness toward a child, a glint of amusement. The plates recorded not the pose but its dissolution.", "He began to prefer the failures, the blurred ones, in which someone had moved. These, he argued to a sceptical customer, were the truest. \"A photograph of a person standing still shows what they wish to be seen as,\" he said. \"A blur shows that they were alive.\" The customer, who wanted a dignified portrait for his mother, bought two ordinary ones.", "Quill died poor in a boarding-house, and his plates were nearly discarded. Rescued a century later by a historian, they are now regarded as a treasure, and the blurred faces draw the longest queues in the museum. Visitors say that in those smudged expressions they recognise, with a shiver, something very like themselves."], "paragraphs_pt": ["No verão de 1878, um fotógrafo itinerante chamado Ambrose Quill chegou a Cedar Flats com uma carroça cheia de placas de vidro e a convicção de que a história seria escrita em haleto de prata. Cobrava um dólar por retrato e logo estava ocupado, pois os colonos das planícies, que tinham poucos espelhos e nenhum retrato, tinham curiosidade de saber como eram seus rostos.", "Quill notou um fenômeno curioso. Antes da exposição, os retratados se arranjavam em poses de severa dignidade de fronteira: lábios apertados, queixos erguidos, olhos fixos no horizonte. Mas as exposições eram longas, e nos segundos seguintes minúsculas mudanças de expressão se insinuavam: um lampejo de cansaço, uma ternura involuntária por uma criança, um brilho de divertimento. As placas registravam não a pose, mas sua dissolução.", "Passou a preferir as falhas, as borradas, em que alguém se mexera. Essas, argumentou a um cliente cético, eram as mais verdadeiras. \"Uma foto de pessoa parada mostra como ela deseja ser vista\", disse. \"Um borrão mostra que estava viva.\" O cliente, que queria um retrato digno para a mãe, comprou dois comuns.", "Quill morreu pobre numa pensão, e suas placas quase foram descartadas. Resgatadas um século depois por um historiador, são hoje consideradas um tesouro, e os rostos borrados atraem as maiores filas do museu. Os visitantes dizem que, naquelas expressões manchadas, reconhecem, com um arrepio, algo muito parecido com eles mesmos."], "hard_words": ["exposure", "stern", "dissolution", "blurred"], "vocab": [{"word": "halide", "meaning": "haleto", "note": ""}, {"word": "portrait", "meaning": "retrato", "note": ""}, {"word": "settlers", "meaning": "colonos", "note": ""}, {"word": "exposure", "meaning": "exposição", "note": ""}, {"word": "stern", "meaning": "severa", "note": ""}, {"word": "dissolution", "meaning": "dissolução", "note": ""}, {"word": "blurred", "meaning": "borradas", "note": ""}, {"word": "discarded", "meaning": "descartadas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "was", "were", "are"], "irregular": ["named", "arrived", "would", "written", "charged", "had", "looked", "noticed", "arranged", "pressed", "lifted", "fixed", "followed", "recorded", "began", "blurred", "moved", "argued", "seen", "said", "wanted", "dignified", "bought", "died", "discarded", "rescued", "regarded", "smudged"], "phrasal": ["creep in"], "wh": ["who", "what", "which"], "connectors": ["and", "but", "before", "yet", "still", "as"], "comparative": []}, "word_meanings": [{"word": "halide", "meaning": "haleto", "note": ""}, {"word": "portrait", "meaning": "retrato", "note": ""}, {"word": "settlers", "meaning": "colonos", "note": ""}, {"word": "exposure", "meaning": "exposição", "note": ""}, {"word": "stern", "meaning": "severa", "note": ""}, {"word": "dissolution", "meaning": "dissolução", "note": ""}, {"word": "blurred", "meaning": "borradas", "note": ""}, {"word": "discarded", "meaning": "descartadas", "note": ""}], "exercises": {"grammar": [{"point": "Not... but", "explanation_pt": "'not the pose but its dissolution' contrasta o que as placas registravam."}, {"point": "Before + noun", "explanation_pt": "'Before the exposure' indica tempo anterior."}], "multiple_choice": [{"question": "Who was Ambrose Quill?", "options": ["A travelling photographer", "A teacher", "A preacher", "A sheriff"], "correct_index": 0, "explanation": "Um fotógrafo itinerante."}, {"question": "What did sitters do before the photo?", "options": ["Arranged stern poses", "Smiled", "Danced", "Slept"], "correct_index": 0, "explanation": "Poses severas."}, {"question": "What did long exposures record?", "options": ["Small changes of expression", "Moving horses", "Nothing", "Landscapes"], "correct_index": 0, "explanation": "Pequenas mudanças de expressão."}, {"question": "Why did Quill prefer blurred images?", "options": ["They were sharp", "They were fashionable", "They were cheap", "They showed the person was alive"], "correct_index": 3, "explanation": "Mostravam que estavam vivos."}, {"question": "What happened to the plates?", "options": ["They were lost", "They were sold", "They were burned", "A historian rescued them a century later"], "correct_index": 3, "explanation": "Resgatadas por um historiador."}], "open_questions": [{"question": "Which shows more truth, a pose or a blur?", "key_points_pt": ["debater"]}, {"question": "How do photographs change how we see history?", "key_points_pt": ["explicar"]}]}}, {"level": "C2", "genre": "western", "title": "The Ghost Town's Last Resident", "paragraphs": ["Ezekiel Moore was the last inhabitant of Gilder's Rest, a mining town that had died as quickly as the vein beneath it. The saloon had been dismantled for timber, the bank was a skeleton of rafters, and the wind, with the proprietary air of a landlord, patrolled the main street at all hours. Everyone else had left within a decade; Ezekiel had remained, for reasons he declined to justify.", "Visitors occasionally came: curious tourists, a documentary crew, a historian armed with questions about the lost glories of the silver rush. They invariably asked why he had stayed, and he answered each differently, according to his mood or his estimate of the questioner. To some he spoke of loyalty to the dead; to others, of a stubborn affection for silence; to one particularly insistent journalist, he said that it was cheaper.", "The truth, as he confided only once, to a stray dog who had adopted his porch, was subtler. He had come to believe that a place does not cease to exist when its people depart; it merely changes the manner of its attention. Gilder's Rest, he said, was still listening, and somebody ought to be there to be heard.", "When he died, aged ninety-one, the county discovered that he had spent his final decades cataloguing every object left behind in the town, each labelled in his neat hand with the name of its former owner. The collection, titled by the county \"an eccentric inventory,\" was later recognised as the most intimate record of a vanished community. Ezekiel, who did not believe in being remembered, would have found this embarrassing and, privately, ratified it entirely."], "paragraphs_pt": ["Ezekiel Moore era o último habitante de Gilder's Rest, cidade mineira que morrera tão rápido quanto o veio abaixo dela. O saloon fora desmontado para madeira, o banco era um esqueleto de vigas e o vento, com ares de proprietário, patrulhava a rua principal a todas as horas. Todos os outros haviam partido em uma década; Ezekiel permanecera, por razões que se recusava a justificar.", "Visitantes vinham ocasionalmente: turistas curiosos, uma equipe de documentário, um historiador armado de perguntas sobre as glórias perdidas da corrida da prata. Invariavelmente perguntavam por que ficara, e ele respondia a cada um de modo diferente, conforme o humor ou a estimativa do interlocutor. A alguns falava de lealdade aos mortos; a outros, de um afeto teimoso pelo silêncio; a um jornalista particularmente insistente, disse que era mais barato.", "A verdade, como confidenciou uma só vez, a um cão vira-lata que adotara sua varanda, era mais sutil. Passara a acreditar que um lugar não deixa de existir quando seu povo parte; apenas muda o modo de sua atenção. Gilder's Rest, dizia, ainda escutava, e alguém devia estar lá para ser ouvido.", "Quando morreu, aos noventa e um anos, o condado descobriu que ele passara as últimas décadas catalogando cada objeto deixado na cidade, cada um etiquetado em sua letra caprichada com o nome do antigo dono. A coleção, intitulada pelo condado \"um inventário excêntrico\", foi depois reconhecida como o registro mais íntimo de uma comunidade desaparecida. Ezekiel, que não acreditava em ser lembrado, acharia isso constrangedor e, em particular, ratificaria tudo."], "hard_words": ["dismantled", "proprietary", "invariably", "inventory"], "vocab": [{"word": "dismantled", "meaning": "desmontado", "note": ""}, {"word": "proprietary", "meaning": "de proprietário", "note": ""}, {"word": "patrolled", "meaning": "patrulhava", "note": ""}, {"word": "invariably", "meaning": "invariavelmente", "note": ""}, {"word": "stubborn", "meaning": "teimoso", "note": ""}, {"word": "cataloguing", "meaning": "catalogando", "note": ""}, {"word": "inventory", "meaning": "inventário", "note": ""}, {"word": "ratified", "meaning": "ratificaria", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "be", "being"], "irregular": ["had", "died", "dismantled", "patrolled", "left", "remained", "declined", "came", "crew", "armed", "lost", "asked", "stayed", "answered", "spoke", "said", "confided", "adopted", "heard", "aged", "discovered", "spent", "labelled", "titled", "recognised", "vanished", "did", "remembered", "would", "found", "ratified"], "phrasal": ["left behind"], "wh": ["who", "when", "why"], "connectors": ["and", "when", "or", "still", "once", "as"], "comparative": []}, "word_meanings": [{"word": "dismantled", "meaning": "desmontado", "note": ""}, {"word": "proprietary", "meaning": "de proprietário", "note": ""}, {"word": "patrolled", "meaning": "patrulhava", "note": ""}, {"word": "invariably", "meaning": "invariavelmente", "note": ""}, {"word": "stubborn", "meaning": "teimoso", "note": ""}, {"word": "cataloguing", "meaning": "catalogando", "note": ""}, {"word": "inventory", "meaning": "inventário", "note": ""}, {"word": "ratified", "meaning": "ratificaria", "note": ""}], "exercises": {"grammar": [{"point": "Had remained / had left", "explanation_pt": "'Everyone else had left; Ezekiel had remained' contrasta dois passados."}, {"point": "Would have found", "explanation_pt": "'would have found this embarrassing' imagina a reação dele."}], "multiple_choice": [{"question": "What was Gilder's Rest?", "options": ["A dead mining town", "A farm", "A fort", "A big city"], "correct_index": 0, "explanation": "Cidade mineira abandonada."}, {"question": "Why did Ezekiel stay, he told the journalist?", "options": ["He loved silence", "It was cheaper", "He was lost", "He was loyal"], "correct_index": 1, "explanation": "Era mais barato."}, {"question": "What was his secret belief?", "options": ["Silver was hidden", "A place keeps listening after people leave", "The dead were near", "The town would return"], "correct_index": 1, "explanation": "O lugar continua escutando."}, {"question": "What did he do in his final decades?", "options": ["Catalogued objects left behind", "Mined silver", "Wrote a book", "Built a house"], "correct_index": 0, "explanation": "Catalogou objetos."}, {"question": "How was the collection regarded?", "options": ["As a hoax", "As trash", "As an intimate record of a vanished community", "As a map"], "correct_index": 2, "explanation": "Registro íntimo de uma comunidade."}], "open_questions": [{"question": "Why do some people stay where others leave?", "key_points_pt": ["discutir"]}, {"question": "How can objects tell a community's story?", "key_points_pt": ["explicar"]}]}}, {"level": "C2", "genre": "western", "title": "A Duel in Verse", "paragraphs": ["In the territory of New Providence, disputes among gentlemen were occasionally settled in the traditional manner: at dawn, with pistols, in a field. But the civilised elements of the community, headed by the elderly judge Arbuthnot, had begun to find the practice wasteful of both gentlemen and daylight. After a particularly acrimonious quarrel between a rancher and a newspaper editor, the judge proposed an innovation: they would duel in verse.", "The gentlemen, who had never composed a line of poetry, were appalled but too proud to refuse. Three weeks later, a crowd assembled on the courthouse steps to hear the first exchange. The rancher delivered a stanza notable for its rhymes and its threats; the editor replied with an ode of such savage wit that the crowd roared. By the sixth round, they were improvising, to everyone's astonishment, including their own.", "Somewhere in the course of the contest, the antagonism lost its fuel. It is difficult to hate a man whose phrase has delighted you, and impossible to remain angry with someone whom you are simultaneously rhyming against. The duel ended not with a casualty but with a draw, and a standing ovation. The two shook hands, slightly hoarse.", "Judge Arbuthnot, observing, reflected that civilisation consists not in the abolition of conflict but in its translation into forms that leave everyone alive. The rancher and editor, now inseparable, produced a joint volume of verse the following year. It sold poorly, but they considered it, with justification, the most successful duel of their lives."], "paragraphs_pt": ["No território de Nova Providência, disputas entre cavalheiros eram ocasionalmente resolvidas à moda tradicional: ao amanhecer, com pistolas, num campo. Mas os elementos civilizados da comunidade, liderados pelo idoso juiz Arbuthnot, começaram a achar a prática um desperdício de cavalheiros e de luz do dia. Após uma briga particularmente acrimoniosa entre um fazendeiro e um editor de jornal, o juiz propôs uma inovação: duelariam em versos.", "Os cavalheiros, que nunca haviam composto um verso, ficaram horrorizados, mas orgulhosos demais para recusar. Três semanas depois, uma multidão se reuniu nos degraus do tribunal para ouvir a primeira troca. O fazendeiro recitou uma estrofe notável por suas rimas e ameaças; o editor respondeu com uma ode de tão selvagem sagacidade que a multidão rugiu. Na sexta rodada, improvisavam, para espanto geral, inclusive o deles.", "Em algum ponto do duelo, o antagonismo perdeu o combustível. É difícil odiar um homem cuja frase o deliciou e impossível continuar zangado com alguém contra quem se rima simultaneamente. O duelo terminou não com uma baixa, mas com um empate e uma ovação de pé. Os dois apertaram as mãos, levemente roucos.", "O juiz Arbuthnot, observando, refletiu que a civilização consiste não na abolição do conflito, mas em sua tradução em formas que deixam todos vivos. O fazendeiro e o editor, agora inseparáveis, produziram um volume conjunto de versos no ano seguinte. Vendeu mal, mas consideraram-no, com justificativa, o duelo mais bem-sucedido de suas vidas."], "hard_words": ["acrimonious", "appalled", "antagonism", "abolition"], "vocab": [{"word": "acrimonious", "meaning": "acrimoniosa", "note": ""}, {"word": "innovation", "meaning": "inovação", "note": ""}, {"word": "appalled", "meaning": "horrorizados", "note": ""}, {"word": "stanza", "meaning": "estrofe", "note": ""}, {"word": "improvising", "meaning": "improvisando", "note": ""}, {"word": "antagonism", "meaning": "antagonismo", "note": ""}, {"word": "casualty", "meaning": "baixa", "note": ""}, {"word": "abolition", "meaning": "abolição", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "is", "are"], "irregular": ["settled", "civilised", "headed", "had", "begun", "proposed", "would", "composed", "appalled", "assembled", "delivered", "replied", "roared", "lost", "delighted", "ended", "shook", "reflected", "produced", "sold", "considered"], "phrasal": ["shook hands", "headed by"], "wh": ["who", "whose", "whom"], "connectors": ["and", "but", "after"], "comparative": []}, "word_meanings": [{"word": "acrimonious", "meaning": "acrimoniosa", "note": ""}, {"word": "innovation", "meaning": "inovação", "note": ""}, {"word": "appalled", "meaning": "horrorizados", "note": ""}, {"word": "stanza", "meaning": "estrofe", "note": ""}, {"word": "improvising", "meaning": "improvisando", "note": ""}, {"word": "antagonism", "meaning": "antagonismo", "note": ""}, {"word": "casualty", "meaning": "baixa", "note": ""}, {"word": "abolition", "meaning": "abolição", "note": ""}], "exercises": {"grammar": [{"point": "Not... but", "explanation_pt": "'not in the abolition of conflict but in its translation' define civilização por contraste."}, {"point": "It is difficult/impossible to", "explanation_pt": "'It is difficult to hate a man whose phrase has delighted you' usa estrutura impessoal."}], "multiple_choice": [{"question": "How were disputes traditionally settled?", "options": ["Auctions", "Pistol duels at dawn", "Court trials", "Fights"], "correct_index": 1, "explanation": "Duelos de pistola."}, {"question": "What did the judge propose?", "options": ["A race", "A trial", "A duel in verse", "A ban"], "correct_index": 2, "explanation": "Duelo em versos."}, {"question": "What happened during the contest?", "options": ["The antagonism lost its fuel", "They fought", "They signed a contract", "They fled"], "correct_index": 0, "explanation": "O antagonismo se dissipou."}, {"question": "How did the duel end?", "options": ["With a gunshot", "With a winner", "With a trial", "In a draw and an ovation"], "correct_index": 3, "explanation": "Empate e ovação."}, {"question": "What does the judge conclude?", "options": ["Duels are noble", "Civilisation translates conflict into forms that leave everyone alive", "Poetry is useless", "Law is weak"], "correct_index": 1, "explanation": "Civilização traduz o conflito."}], "open_questions": [{"question": "Can art defuse conflict?", "key_points_pt": ["debater"]}, {"question": "What other 'duels' could replace violence?", "key_points_pt": ["imaginar"]}]}}, {"level": "A1", "genre": "fable", "title": "The Rabbit and the Turtle Friend", "paragraphs": ["A rabbit and a turtle live near a river. The rabbit is fast. The turtle is slow. The rabbit laughs at the turtle every day.", "One day the river is very big. The rabbit wants to cross, but he cannot swim. \"Help me!\" he says. The turtle says, \"Sit on my back.\"", "The turtle swims across the river with the rabbit. On the other side, the rabbit says, \"Sorry, friend. You are slow, but you are strong.\" They are friends now."], "paragraphs_pt": ["Um coelho e uma tartaruga moram perto de um rio. O coelho é rápido. A tartaruga é lenta. O coelho ri da tartaruga todo dia.", "Um dia o rio está muito grande. O coelho quer atravessar, mas não sabe nadar. \"Me ajude!\", ele diz. A tartaruga diz: \"Sente nas minhas costas.\"", "A tartaruga nada pelo rio com o coelho. Do outro lado, o coelho diz: \"Desculpe, amiga. Você é lenta, mas é forte.\" Agora são amigos."], "hard_words": ["turtle", "river", "swim", "strong"], "vocab": [{"word": "rabbit", "meaning": "coelho", "note": ""}, {"word": "turtle", "meaning": "tartaruga", "note": ""}, {"word": "river", "meaning": "rio", "note": ""}, {"word": "fast", "meaning": "rápido", "note": ""}, {"word": "slow", "meaning": "lento", "note": ""}, {"word": "swim", "meaning": "nadar", "note": ""}, {"word": "strong", "meaning": "forte", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "rabbit", "meaning": "coelho", "note": ""}, {"word": "turtle", "meaning": "tartaruga", "note": ""}, {"word": "river", "meaning": "rio", "note": ""}, {"word": "fast", "meaning": "rápido", "note": ""}, {"word": "slow", "meaning": "lento", "note": ""}, {"word": "swim", "meaning": "nadar", "note": ""}, {"word": "strong", "meaning": "forte", "note": ""}], "exercises": {"grammar": [{"point": "Adjetivos", "explanation_pt": "'fast', 'slow' e 'strong' descrevem os animais. Em inglês o adjetivo vem depois de 'is' ou 'are'."}], "multiple_choice": [{"question": "Who is fast?", "options": ["The rabbit", "The river", "The turtle", "The sun"], "correct_index": 0, "explanation": "O coelho é rápido."}, {"question": "Who laughs every day?", "options": ["The fish", "The bird", "The rabbit", "The turtle"], "correct_index": 2, "explanation": "O coelho ri."}, {"question": "What cannot the rabbit do?", "options": ["Eat", "Jump", "Run", "Swim"], "correct_index": 3, "explanation": "Ele não sabe nadar."}, {"question": "Who helps?", "options": ["The man", "The turtle", "The fish", "The cat"], "correct_index": 1, "explanation": "A tartaruga ajuda."}, {"question": "What do they become?", "options": ["Friends", "Teachers", "Enemies", "Neighbors"], "correct_index": 0, "explanation": "Viram amigos."}], "open_questions": [{"question": "Who is your best friend?", "key_points_pt": ["descrever um amigo"]}, {"question": "Are you fast or slow?", "key_points_pt": ["descrever com adjetivos"]}]}}, {"level": "A1", "genre": "fable", "title": "The Little Bird", "paragraphs": ["A little bird has a nest in a big tree. She is hungry. She sees a worm on the ground. She flies down and eats it.", "A cat sees the bird. The cat is also hungry. \"I want to eat you,\" says the cat. The bird is afraid.", "The bird flies up, up, up. The cat cannot fly. The bird is safe in her nest. She says, \"Be careful when you eat!\""], "paragraphs_pt": ["Um passarinho tem um ninho numa árvore grande. Ela está com fome. Vê uma minhoca no chão. Voa para baixo e a come.", "Um gato vê o passarinho. O gato também está com fome. \"Quero te comer\", diz o gato. O passarinho tem medo.", "O passarinho voa para cima, cima, cima. O gato não sabe voar. O passarinho está segura no ninho. Ela diz: \"Cuidado quando comer!\""], "hard_words": ["nest", "hungry", "ground", "safe"], "vocab": [{"word": "nest", "meaning": "ninho", "note": ""}, {"word": "tree", "meaning": "árvore", "note": ""}, {"word": "hungry", "meaning": "com fome", "note": ""}, {"word": "worm", "meaning": "minhoca", "note": ""}, {"word": "ground", "meaning": "chão", "note": ""}, {"word": "fly", "meaning": "voar", "note": ""}, {"word": "safe", "meaning": "segura", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "be"], "irregular": ["ground"], "phrasal": [], "wh": ["when"], "connectors": ["and", "when", "also"], "comparative": []}, "word_meanings": [{"word": "nest", "meaning": "ninho", "note": ""}, {"word": "tree", "meaning": "árvore", "note": ""}, {"word": "hungry", "meaning": "com fome", "note": ""}, {"word": "worm", "meaning": "minhoca", "note": ""}, {"word": "ground", "meaning": "chão", "note": ""}, {"word": "fly", "meaning": "voar", "note": ""}, {"word": "safe", "meaning": "segura", "note": ""}], "exercises": {"grammar": [{"point": "Can / cannot", "explanation_pt": "'The cat cannot fly' diz o que o animal não consegue fazer."}], "multiple_choice": [{"question": "Where is the nest?", "options": ["In a house", "In a big tree", "In a river", "On the ground"], "correct_index": 1, "explanation": "Num árvore grande."}, {"question": "What does the bird see?", "options": ["A worm", "A fish", "A snake", "A cat only"], "correct_index": 0, "explanation": "Ela vê uma minhoca."}, {"question": "Who is also hungry?", "options": ["The cow", "The horse", "The cat", "The dog"], "correct_index": 2, "explanation": "O gato também está com fome."}, {"question": "What can the cat NOT do?", "options": ["Fly", "Sleep", "Run", "Eat"], "correct_index": 0, "explanation": "O gato não voa."}, {"question": "Where is the bird safe?", "options": ["In a house", "In her nest", "In a river", "On the ground"], "correct_index": 1, "explanation": "No ninho."}], "open_questions": [{"question": "What animals can fly?", "key_points_pt": ["listar animais"]}, {"question": "What do you do when you are afraid?", "key_points_pt": ["descrever reações"]}]}}, {"level": "A2", "genre": "fable", "title": "The Greedy Dog", "paragraphs": ["A dog found a big bone in the street. He was very happy, so he picked it up in his mouth and walked home. On the way he crossed a small bridge over a river.", "He looked down and saw another dog in the water. This dog also had a big bone. \"I want that bone, too,\" thought the greedy dog. He opened his mouth and barked at the dog in the water.", "The bone fell into the river. The other dog disappeared. Of course, it was only the dog's reflection in the water. The poor dog went home hungry and sad. He understood that being greedy is a bad idea."], "paragraphs_pt": ["Um cachorro achou um osso grande na rua. Ficou muito feliz, então o pegou com a boca e foi para casa. No caminho, atravessou uma pequena ponte sobre um rio.", "Olhou para baixo e viu outro cachorro na água. Esse cachorro também tinha um osso grande. \"Eu quero aquele osso também\", pensou o cachorro ganancioso. Abriu a boca e latiu para o cachorro na água.", "O osso caiu no rio. O outro cachorro desapareceu. Claro que era só o reflexo do cachorro na água. O pobre cachorro foi para casa com fome e triste. Entendeu que ser ganancioso é má ideia."], "hard_words": ["bridge", "greedy", "reflection", "disappeared"], "vocab": [{"word": "bone", "meaning": "osso", "note": ""}, {"word": "bridge", "meaning": "ponte", "note": ""}, {"word": "greedy", "meaning": "ganancioso", "note": ""}, {"word": "barked", "meaning": "latiu", "note": ""}, {"word": "reflection", "meaning": "reflexo", "note": ""}, {"word": "disappeared", "meaning": "desapareceu", "note": ""}, {"word": "hungry", "meaning": "com fome", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being", "is"], "irregular": ["found", "picked", "walked", "crossed", "looked", "saw", "had", "thought", "opened", "barked", "fell", "disappeared", "went", "understood"], "phrasal": [], "wh": [], "connectors": ["and", "so", "also"], "comparative": []}, "word_meanings": [{"word": "bone", "meaning": "osso", "note": ""}, {"word": "bridge", "meaning": "ponte", "note": ""}, {"word": "greedy", "meaning": "ganancioso", "note": ""}, {"word": "barked", "meaning": "latiu", "note": ""}, {"word": "reflection", "meaning": "reflexo", "note": ""}, {"word": "disappeared", "meaning": "desapareceu", "note": ""}, {"word": "hungry", "meaning": "com fome", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'found', 'saw', 'fell' contam ações passadas. Alguns são irregulares: find → found, see → saw, fall → fell."}], "multiple_choice": [{"question": "What did the dog find?", "options": ["A ball", "A big bone", "A fish", "A cat"], "correct_index": 1, "explanation": "Achou um osso grande."}, {"question": "Where did he cross?", "options": ["A field", "A tunnel", "A road", "A small bridge"], "correct_index": 3, "explanation": "Atravessou uma ponte."}, {"question": "Who was in the water?", "options": ["A real dog", "A fish", "His reflection", "A boy"], "correct_index": 2, "explanation": "Era o reflexo."}, {"question": "What happened to the bone?", "options": ["He ate it", "It fell in the river", "He lost it at home", "He gave it away"], "correct_index": 1, "explanation": "O osso caiu no rio."}, {"question": "What is the lesson?", "options": ["Rivers are cold", "Bridges are safe", "Being greedy is a bad idea", "Dogs are fast"], "correct_index": 2, "explanation": "Ser ganancioso é má ideia."}], "open_questions": [{"question": "Have you ever wanted more than you needed?", "key_points_pt": ["contar uma experiência"]}, {"question": "What lesson do you remember from a story?", "key_points_pt": ["resumir uma moral"]}]}}, {"level": "A2", "genre": "fable", "title": "The Lion and the Mouse", "paragraphs": ["One day a lion was sleeping under a tree. A small mouse ran across his face, and the lion woke up. He was angry and caught the mouse with his big paw. \"Please let me go,\" said the mouse. \"One day I will help you.\"", "The lion laughed. \"How can a tiny mouse help a big lion?\" But he let the mouse go.", "A few days later, hunters caught the lion in a net. He roared, but he could not escape. The mouse heard the noise and came quickly. With her sharp teeth, she cut the ropes, one by one. \"Now you are free,\" she said. The lion learned that even small friends can be great friends."], "paragraphs_pt": ["Um dia, um leão dormia sob uma árvore. Um pequeno rato correu pelo rosto dele, e o leão acordou. Ficou bravo e pegou o rato com sua grande pata. \"Por favor, me solte\", disse o rato. \"Um dia vou ajudar você.\"", "O leão riu. \"Como um ratinho pode ajudar um grande leão?\" Mas soltou o rato.", "Alguns dias depois, caçadores prenderam o leão numa rede. Ele rugiu, mas não conseguia escapar. O rato ouviu o barulho e veio rápido. Com seus dentes afiados, cortou as cordas, uma por uma. \"Agora você está livre\", disse. O leão aprendeu que até amigos pequenos podem ser grandes amigos."], "hard_words": ["paw", "hunters", "escape", "sharp"], "vocab": [{"word": "paw", "meaning": "pata", "note": ""}, {"word": "tiny", "meaning": "minúsculo", "note": ""}, {"word": "hunters", "meaning": "caçadores", "note": ""}, {"word": "net", "meaning": "rede", "note": ""}, {"word": "roared", "meaning": "rugiu", "note": ""}, {"word": "escape", "meaning": "escapar", "note": ""}, {"word": "sharp", "meaning": "afiado", "note": ""}, {"word": "ropes", "meaning": "cordas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "are", "be"], "irregular": ["ran", "woke", "caught", "said", "laughed", "roared", "could", "heard", "came", "learned"], "phrasal": ["woke up"], "wh": ["how"], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "paw", "meaning": "pata", "note": ""}, {"word": "tiny", "meaning": "minúsculo", "note": ""}, {"word": "hunters", "meaning": "caçadores", "note": ""}, {"word": "net", "meaning": "rede", "note": ""}, {"word": "roared", "meaning": "rugiu", "note": ""}, {"word": "escape", "meaning": "escapar", "note": ""}, {"word": "sharp", "meaning": "afiado", "note": ""}, {"word": "ropes", "meaning": "cordas", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'was sleeping' e 'ran' contam o que acontecia e o que aconteceu."}, {"point": "Can / could", "explanation_pt": "'could not escape' diz o que não era possível no passado."}], "multiple_choice": [{"question": "Where was the lion sleeping?", "options": ["Under a tree", "In a house", "In a river", "In a cave"], "correct_index": 0, "explanation": "Sob uma árvore."}, {"question": "What did the mouse ask?", "options": ["For a song", "To be let go", "For a home", "For food"], "correct_index": 1, "explanation": "Pediu para ser solto."}, {"question": "Who caught the lion?", "options": ["A farmer", "A boy", "A bear", "Hunters"], "correct_index": 3, "explanation": "Caçadores."}, {"question": "How did the mouse help?", "options": ["She cut the ropes", "She called the police", "She ran away", "She shouted"], "correct_index": 0, "explanation": "Cortou as cordas."}, {"question": "What is the lesson?", "options": ["Small friends can be great friends", "Mice are fast", "Nets are strong", "Lions are weak"], "correct_index": 0, "explanation": "Amigos pequenos podem ser grandes."}], "open_questions": [{"question": "Can small people do big things? Give an example.", "key_points_pt": ["dar exemplo"]}, {"question": "When did a friend help you?", "key_points_pt": ["contar experiência"]}]}}, {"level": "B1", "genre": "fable", "title": "The Crow Who Wanted to be a Peacock", "paragraphs": ["A crow lived in a forest near a king's palace. Every day she watched the peacocks walking in the garden, with their shining blue and green feathers. \"They are so beautiful,\" she sighed. \"Why can't I look like that?\"", "One morning she found some fallen peacock feathers and tied them to her tail. Proudly, she walked into the garden. At first the peacocks were surprised, but soon they noticed what she had done. They pecked at her and pulled the feathers out.", "Crying, she flew back to the forest and tried to rejoin the other crows. But they were offended. \"You wanted to be like them, so you left us,\" they said. \"Now you don't belong anywhere.\"", "The crow sat alone on a branch. She finally understood that her mistake was not wanting beauty, but pretending to be someone else. From that day on, she was proud of her black feathers and her loud voice."], "paragraphs_pt": ["Uma corvo vivia numa floresta perto do palácio de um rei. Todo dia observava os pavões andando no jardim, com suas penas azuis e verdes brilhantes. \"Eles são tão lindos\", suspirava. \"Por que não posso ser assim?\"", "Numa manhã achou algumas penas de pavão caídas e as amarrou na cauda. Orgulhosa, entrou no jardim. A princípio os pavões ficaram surpresos, mas logo perceberam o que ela fizera. Bicaram-na e arrancaram as penas.", "Chorando, voou de volta à floresta e tentou voltar para os outros corvos. Mas eles estavam ofendidos. \"Você quis ser como eles, então nos deixou\", disseram. \"Agora não pertence a lugar nenhum.\"", "A corvo ficou sozinha num galho. Por fim entendeu que seu erro não era querer beleza, mas fingir ser outra pessoa. Desde esse dia, teve orgulho de suas penas pretas e de sua voz alta."], "hard_words": ["feathers", "pecked", "offended", "belong"], "vocab": [{"word": "crow", "meaning": "corvo", "note": ""}, {"word": "peacock", "meaning": "pavão", "note": ""}, {"word": "feathers", "meaning": "penas", "note": ""}, {"word": "tied", "meaning": "amarrou", "note": ""}, {"word": "pecked", "meaning": "bicou", "note": ""}, {"word": "offended", "meaning": "ofendidos", "note": ""}, {"word": "belong", "meaning": "pertencer", "note": ""}, {"word": "proud", "meaning": "orgulhosa", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "were", "be", "was"], "irregular": ["lived", "watched", "sighed", "found", "fallen", "tied", "walked", "surprised", "noticed", "had", "done", "pecked", "pulled", "flew", "tried", "offended", "wanted", "left", "said", "sat", "understood"], "phrasal": ["walked into"], "wh": ["what", "why"], "connectors": ["and", "but", "so", "finally"], "comparative": []}, "word_meanings": [{"word": "crow", "meaning": "corvo", "note": ""}, {"word": "peacock", "meaning": "pavão", "note": ""}, {"word": "feathers", "meaning": "penas", "note": ""}, {"word": "tied", "meaning": "amarrou", "note": ""}, {"word": "pecked", "meaning": "bicou", "note": ""}, {"word": "offended", "meaning": "ofendidos", "note": ""}, {"word": "belong", "meaning": "pertencer", "note": ""}, {"word": "proud", "meaning": "orgulhosa", "note": ""}], "exercises": {"grammar": [{"point": "Why can't I", "explanation_pt": "'Why can't I look like that?' expressa um desejo que parece impossível."}, {"point": "Past simple e past perfect", "explanation_pt": "'they noticed what she had done' mostra uma ação anterior."}], "multiple_choice": [{"question": "Where did the crow live?", "options": ["Near a palace", "In a city", "In the desert", "By the sea"], "correct_index": 0, "explanation": "Perto de um palácio."}, {"question": "What did she tie to her tail?", "options": ["Ribbons", "Flowers", "Paper", "Peacock feathers"], "correct_index": 3, "explanation": "Penas de pavão."}, {"question": "How did the peacocks react?", "options": ["They welcomed her", "They fed her", "They pecked her", "They ignored her"], "correct_index": 2, "explanation": "Bicaram-na."}, {"question": "Why were the other crows offended?", "options": ["She stole food", "She left them to be like peacocks", "She was rich", "She was rude"], "correct_index": 1, "explanation": "Ela os deixou para ser como os pavões."}, {"question": "What did she learn?", "options": ["To fly higher", "To sing better", "To dress well", "Not to pretend to be someone else"], "correct_index": 3, "explanation": "Aprendeu a não fingir."}], "open_questions": [{"question": "Have you ever tried to be someone else?", "key_points_pt": ["refletir"]}, {"question": "What does it mean to be proud of who you are?", "key_points_pt": ["explicar"]}]}}, {"level": "B1", "genre": "fable", "title": "The Wise Old Tortoise", "paragraphs": ["In a dry valley, a drought had lasted for months, and the animals were growing weak. The river was a thin line of mud, and the grass was brown. They gathered in the shade of a rock to decide what to do.", "The lion proposed fighting the animals from the next valley for their water. The monkey suggested moving the whole group at once. The deer wanted to wait for rain. They argued for hours, and nobody listened to anyone.", "Finally, an old tortoise, who had hardly spoken all day, cleared his throat. \"When I was young,\" he said, \"a drought like this came, and my mother found water by following the birds at dawn. They always fly toward water.\"", "The next morning, the animals followed the birds to a hidden spring behind the hills. There was enough water for everyone, and for the first time in months they drank in peace. The lion thanked the tortoise, who only said, \"The loudest voice is rarely the wisest.\""], "paragraphs_pt": ["Num vale seco, uma seca durava meses e os animais enfraqueciam. O rio era uma linha fina de lama e a grama estava marrom. Reuniram-se à sombra de uma pedra para decidir o que fazer.", "O leão propôs lutar contra os animais do vale vizinho por água. O macaco sugeriu mudar o grupo todo de uma vez. O cervo queria esperar a chuva. Discutiram por horas e ninguém ouvia ninguém.", "Por fim, uma velha tartaruga, que mal falara o dia todo, limpou a garganta. \"Quando eu era jovem\", disse, \"veio uma seca como esta, e minha mãe achou água seguindo os pássaros ao amanhecer. Eles sempre voam em direção à água.\"", "Na manhã seguinte, os animais seguiram os pássaros até uma nascente escondida atrás das colinas. Havia água para todos e, pela primeira vez em meses, beberam em paz. O leão agradeceu à tartaruga, que apenas disse: \"A voz mais alta raramente é a mais sábia.\""], "hard_words": ["drought", "gathered", "tortoise", "spring"], "vocab": [{"word": "drought", "meaning": "seca", "note": ""}, {"word": "valley", "meaning": "vale", "note": ""}, {"word": "mud", "meaning": "lama", "note": ""}, {"word": "gathered", "meaning": "reuniram-se", "note": ""}, {"word": "tortoise", "meaning": "tartaruga (terrestre)", "note": ""}, {"word": "spring", "meaning": "nascente", "note": ""}, {"word": "dawn", "meaning": "amanhecer", "note": ""}, {"word": "wisest", "meaning": "mais sábia", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was", "is"], "irregular": ["had", "lasted", "gathered", "proposed", "suggested", "wanted", "argued", "listened", "spoken", "cleared", "said", "came", "found", "followed", "hidden", "drank", "thanked"], "phrasal": ["cleared his throat", "followed the birds"], "wh": ["who", "what", "when"], "connectors": ["and", "when", "finally", "once"], "comparative": []}, "word_meanings": [{"word": "drought", "meaning": "seca", "note": ""}, {"word": "valley", "meaning": "vale", "note": ""}, {"word": "mud", "meaning": "lama", "note": ""}, {"word": "gathered", "meaning": "reuniram-se", "note": ""}, {"word": "tortoise", "meaning": "tartaruga (terrestre)", "note": ""}, {"word": "spring", "meaning": "nascente", "note": ""}, {"word": "dawn", "meaning": "amanhecer", "note": ""}, {"word": "wisest", "meaning": "mais sábia", "note": ""}], "exercises": {"grammar": [{"point": "Superlativos", "explanation_pt": "'the loudest voice' e 'the wisest' comparam uma voz com todas as outras."}, {"point": "Past perfect", "explanation_pt": "'who had hardly spoken' mostra o que aconteceu antes do discurso."}], "multiple_choice": [{"question": "What was the problem?", "options": ["A storm", "A drought", "A flood", "A fire"], "correct_index": 1, "explanation": "Uma seca."}, {"question": "What did the lion propose?", "options": ["Waiting", "Fighting for water", "Digging", "Moving"], "correct_index": 1, "explanation": "Lutar por água."}, {"question": "Who gave the solution?", "options": ["The lion", "The deer", "The monkey", "An old tortoise"], "correct_index": 3, "explanation": "Uma velha tartaruga."}, {"question": "How did they find water?", "options": ["By rain", "By asking humans", "By digging", "By following birds"], "correct_index": 3, "explanation": "Seguindo os pássaros."}, {"question": "What does the tortoise say about voices?", "options": ["All are equal", "The quietest is lost", "The loudest is rarely the wisest", "The deepest is best"], "correct_index": 2, "explanation": "A mais alta raramente é a mais sábia."}], "open_questions": [{"question": "Why do loud people often get attention?", "key_points_pt": ["discutir"]}, {"question": "Who gives you wise advice?", "key_points_pt": ["descrever"]}]}}, {"level": "B1", "genre": "fable", "title": "The Farmer's Three Sons", "paragraphs": ["An old farmer was dying, and he wanted to teach his three sons one last lesson. He asked them to bring him a bundle of sticks. \"Break it,\" he told the eldest. The young man pulled and pushed, but the bundle did not break. The second and third sons tried as well, and they also failed.", "Then the farmer untied the bundle and gave each son a single stick. \"Now break it,\" he said. They did it easily, one after the other. The sound of the cracking sticks filled the room.", "\"You see,\" said the old man, \"alone, each of you is weak, but together you are strong. Don't let anything divide you. Take care of the farm and take care of each other.\"", "After his death, the brothers had many arguments, as brothers always do. But whenever one of them wanted to leave, the others reminded him of the sticks. The farm prospered for generations, and the story of the bundle was told at every family meal."], "paragraphs_pt": ["Um velho fazendeiro estava morrendo e queria ensinar uma última lição aos três filhos. Pediu que lhe trouxessem um feixe de gravetos. \"Quebre\", disse ao mais velho. O rapaz puxou e empurrou, mas o feixe não quebrou. O segundo e o terceiro filhos tentaram também e igualmente falharam.", "Então o fazendeiro desatou o feixe e deu a cada filho um graveto. \"Agora quebrem\", disse. Fizeram-no com facilidade, um após o outro. O som dos gravetos estalando encheu o quarto.", "\"Veem?\", disse o velho. \"Sozinhos, cada um de vocês é fraco, mas juntos são fortes. Não deixem nada dividi-los. Cuidem da fazenda e cuidem uns dos outros.\"", "Depois da morte dele, os irmãos tiveram muitas discussões, como os irmãos sempre têm. Mas, sempre que um deles queria partir, os outros lembravam-no dos gravetos. A fazenda prosperou por gerações, e a história do feixe era contada em cada refeição da família."], "hard_words": ["bundle", "eldest", "divide", "prospered"], "vocab": [{"word": "farmer", "meaning": "fazendeiro", "note": ""}, {"word": "bundle", "meaning": "feixe", "note": ""}, {"word": "sticks", "meaning": "gravetos", "note": ""}, {"word": "eldest", "meaning": "mais velho", "note": ""}, {"word": "untied", "meaning": "desatou", "note": ""}, {"word": "weak", "meaning": "fraco", "note": ""}, {"word": "divide", "meaning": "dividir", "note": ""}, {"word": "prospered", "meaning": "prosperou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is", "are"], "irregular": ["wanted", "asked", "told", "pulled", "pushed", "did", "tried", "failed", "untied", "gave", "said", "filled", "had", "reminded", "prospered"], "phrasal": ["take care of", "one after the other"], "wh": ["whenever"], "connectors": ["and", "but", "then", "after", "also", "as", "whenever"], "comparative": []}, "word_meanings": [{"word": "farmer", "meaning": "fazendeiro", "note": ""}, {"word": "bundle", "meaning": "feixe", "note": ""}, {"word": "sticks", "meaning": "gravetos", "note": ""}, {"word": "eldest", "meaning": "mais velho", "note": ""}, {"word": "untied", "meaning": "desatou", "note": ""}, {"word": "weak", "meaning": "fraco", "note": ""}, {"word": "divide", "meaning": "dividir", "note": ""}, {"word": "prospered", "meaning": "prosperou", "note": ""}], "exercises": {"grammar": [{"point": "Alone vs together", "explanation_pt": "'alone... but together' contrasta fraqueza e força."}, {"point": "Whenever", "explanation_pt": "'whenever one of them wanted to leave' significa toda vez que."}], "multiple_choice": [{"question": "What did the farmer want?", "options": ["To teach a lesson", "To rest", "To travel", "To sell the farm"], "correct_index": 0, "explanation": "Ensinar uma lição."}, {"question": "Could they break the bundle?", "options": ["Only the youngest", "Only the eldest", "Yes", "No"], "correct_index": 3, "explanation": "Não conseguiram."}, {"question": "What happened with single sticks?", "options": ["They burned", "They did not break", "They broke easily", "They were lost"], "correct_index": 2, "explanation": "Quebraram facilmente."}, {"question": "What is the lesson?", "options": ["Together we are strong", "Fathers are right", "Sticks are weak", "Farmers are wise"], "correct_index": 0, "explanation": "Juntos somos fortes."}, {"question": "What happened to the farm?", "options": ["It was lost", "It prospered", "It was sold", "It burned"], "correct_index": 1, "explanation": "Prosperou."}], "open_questions": [{"question": "Why is teamwork important?", "key_points_pt": ["explicar"]}, {"question": "Do you have a family story with a lesson?", "key_points_pt": ["contar"]}]}}, {"level": "B2", "genre": "fable", "title": "The Fox and the Mirror", "paragraphs": ["In a village at the edge of the forest, there lived a fox of legendary vanity. He spent hours grooming his tail beside the pond, convinced that nature had never made a more handsome creature. When a travelling merchant left a large mirror on the road, the fox saw an opportunity to admire himself in unprecedented detail.", "For days, he sat before the mirror, speaking tenderly to the reflected animal, praising its eyes, its whiskers, the golden curve of its back. The other animals watched in embarrassment. The owl suggested he should hunt before the winter arrived, but the fox only waved a paw, saying, \"Genius requires contemplation.\"", "The first snow came earlier than expected. The fox, who had stored nothing, found his burrow empty and his mirror buried under ice. When he looked into its frozen surface, the creature that stared back was thin, trembling and unfamiliar.", "It was the owl who brought him a few scraps of food. \"Self-knowledge,\" she said gently, \"is valuable only when it includes the truth.\" The fox ate in silence. In spring, he left the mirror at the roadside, and, according to the villagers, he was never seen looking at a pond again."], "paragraphs_pt": ["Numa aldeia à beira da floresta vivia uma raposa de vaidade lendária. Passava horas escovando a cauda junto ao lago, convencida de que a natureza nunca fizera criatura mais bela. Quando um mercador viajante deixou um grande espelho na estrada, a raposa viu a oportunidade de se admirar com um detalhe sem precedentes.", "Por dias, sentou-se diante do espelho, falando com ternura ao animal refletido, elogiando seus olhos, seus bigodes, a curva dourada de suas costas. Os outros animais olhavam constrangidos. A coruja sugeriu que ela caçasse antes de o inverno chegar, mas a raposa apenas acenou com a pata, dizendo: \"O gênio exige contemplação.\"", "A primeira neve veio mais cedo do que o esperado. A raposa, que nada armazenara, encontrou a toca vazia e o espelho enterrado sob o gelo. Ao olhar sua superfície congelada, a criatura que a fitava de volta era magra, trêmula e desconhecida.", "Foi a coruja quem lhe trouxe uns restos de comida. \"O autoconhecimento\", disse com gentileza, \"só tem valor quando inclui a verdade.\" A raposa comeu em silêncio. Na primavera, deixou o espelho à beira da estrada e, segundo os aldeões, nunca mais foi vista olhando para um lago."], "hard_words": ["vanity", "unprecedented", "burrow", "contemplation"], "vocab": [{"word": "vanity", "meaning": "vaidade", "note": ""}, {"word": "grooming", "meaning": "escovando", "note": ""}, {"word": "unprecedented", "meaning": "sem precedentes", "note": ""}, {"word": "whiskers", "meaning": "bigodes", "note": ""}, {"word": "contemplation", "meaning": "contemplação", "note": ""}, {"word": "burrow", "meaning": "toca", "note": ""}, {"word": "scraps", "meaning": "restos", "note": ""}, {"word": "self-knowledge", "meaning": "autoconhecimento", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is"], "irregular": ["lived", "spent", "convinced", "had", "made", "left", "saw", "sat", "reflected", "watched", "suggested", "should", "arrived", "waved", "came", "expected", "stored", "found", "buried", "looked", "frozen", "stared", "brought", "said", "ate", "seen"], "phrasal": ["waved a paw"], "wh": ["who", "when"], "connectors": ["and", "but", "before", "when"], "comparative": []}, "word_meanings": [{"word": "vanity", "meaning": "vaidade", "note": ""}, {"word": "grooming", "meaning": "escovando", "note": ""}, {"word": "unprecedented", "meaning": "sem precedentes", "note": ""}, {"word": "whiskers", "meaning": "bigodes", "note": ""}, {"word": "contemplation", "meaning": "contemplação", "note": ""}, {"word": "burrow", "meaning": "toca", "note": ""}, {"word": "scraps", "meaning": "restos", "note": ""}, {"word": "self-knowledge", "meaning": "autoconhecimento", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'who had stored nothing' mostra algo não feito antes da neve."}, {"point": "Only when", "explanation_pt": "'valuable only when it includes the truth' expressa a condição única."}], "multiple_choice": [{"question": "What was the fox's weakness?", "options": ["Vanity", "Fear", "Greed", "Anger"], "correct_index": 0, "explanation": "Vaidade."}, {"question": "What did the merchant leave?", "options": ["A large mirror", "A coat", "A map", "A basket"], "correct_index": 0, "explanation": "Um espelho grande."}, {"question": "What did the owl suggest?", "options": ["Hunting before winter", "Selling the mirror", "Sleeping", "Leaving the village"], "correct_index": 0, "explanation": "Caçar antes do inverno."}, {"question": "What happened when winter came early?", "options": ["The fox had no food", "The mirror broke", "The fox moved", "The owl left"], "correct_index": 0, "explanation": "A raposa não tinha comida."}, {"question": "How did the fox change?", "options": ["He became rude", "He stopped looking at ponds", "He left", "He became rich"], "correct_index": 1, "explanation": "Parou de olhar para lagos."}], "open_questions": [{"question": "Is self-confidence the same as vanity?", "key_points_pt": ["debater"]}, {"question": "What real consequences can distraction have?", "key_points_pt": ["discutir"]}]}}, {"level": "B2", "genre": "fable", "title": "The Two Rivers", "paragraphs": ["Two rivers began in the same mountain, only a few metres apart. The first, who was called Swift, rushed down the slope, impatient to reach the sea. It cut through rocks and left a white trail of foam, and everybody admired its energy. The second, called Patient, wound slowly across the plains, stopping to fill every field and pond.", "Years passed. Swift arrived at the sea in a single season, but it brought nothing with it except noise and gravel. Its banks were dry and rocky, and no tree grew beside it. Patient reached the sea much later, yet its valley was green, farms bloomed along its banks, and fish and birds multiplied in its shade.", "One evening, as the sun set, Swift slowed down enough to observe its sibling joining the sea at last. \"How did you manage to arrive with so much?\" it asked. Patient replied, \"I never thought of arriving. I thought of everyone I passed.\"", "The sea, which had heard many such conversations, said nothing. But the people living near the two rivers learned to value journeys more than speed, and they named their children after the river that took its time."], "paragraphs_pt": ["Dois rios nasceram na mesma montanha, a poucos metros um do outro. O primeiro, chamado Veloz, desceu a encosta com pressa de chegar ao mar. Cortou pedras e deixou um rastro branco de espuma, e todos admiravam sua energia. O segundo, chamado Paciente, serpenteou lentamente pelas planícies, parando para encher cada campo e lago.", "Os anos passaram. Veloz chegou ao mar numa única estação, mas não levou nada além de barulho e cascalho. Suas margens eram secas e rochosas, e nenhuma árvore crescia ao lado. Paciente chegou ao mar muito depois, mas seu vale era verde, fazendas floresciam em suas margens e peixes e pássaros se multiplicavam à sua sombra.", "Numa tarde, ao pôr do sol, Veloz diminuiu o bastante para ver seu irmão chegar finalmente ao mar. \"Como conseguiu chegar com tanto?\", perguntou. Paciente respondeu: \"Nunca pensei em chegar. Pensei em todos que encontrei.\"", "O mar, que ouvira muitas conversas assim, nada disse. Mas as pessoas que viviam perto dos dois rios aprenderam a valorizar a jornada mais que a velocidade e deram a seus filhos o nome do rio que levava seu tempo."], "hard_words": ["slope", "foam", "gravel", "multiplied"], "vocab": [{"word": "slope", "meaning": "encosta", "note": ""}, {"word": "foam", "meaning": "espuma", "note": ""}, {"word": "wound", "meaning": "serpenteou", "note": ""}, {"word": "plains", "meaning": "planícies", "note": ""}, {"word": "gravel", "meaning": "cascalho", "note": ""}, {"word": "bloomed", "meaning": "floresceram", "note": ""}, {"word": "multiplied", "meaning": "multiplicaram-se", "note": ""}, {"word": "sibling", "meaning": "irmão(ã)", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["began", "called", "rushed", "left", "admired", "wound", "passed", "arrived", "brought", "grew", "reached", "bloomed", "multiplied", "slowed", "did", "asked", "replied", "thought", "had", "heard", "said", "learned", "named", "took"], "phrasal": ["cut through", "rushed down"], "wh": ["who", "how", "which"], "connectors": ["and", "but", "so", "after", "yet", "as"], "comparative": []}, "word_meanings": [{"word": "slope", "meaning": "encosta", "note": ""}, {"word": "foam", "meaning": "espuma", "note": ""}, {"word": "wound", "meaning": "serpenteou", "note": ""}, {"word": "plains", "meaning": "planícies", "note": ""}, {"word": "gravel", "meaning": "cascalho", "note": ""}, {"word": "bloomed", "meaning": "floresceram", "note": ""}, {"word": "multiplied", "meaning": "multiplicaram-se", "note": ""}, {"word": "sibling", "meaning": "irmão(ã)", "note": ""}], "exercises": {"grammar": [{"point": "Past simple e contraste", "explanation_pt": "'Swift arrived... Patient reached...' compara dois percursos."}, {"point": "More than", "explanation_pt": "'value journeys more than speed' compara duas ideias."}], "multiple_choice": [{"question": "Where did the rivers begin?", "options": ["A lake", "The same mountain", "Two countries", "A city"], "correct_index": 1, "explanation": "Na mesma montanha."}, {"question": "What was Swift like?", "options": ["Deep and quiet", "Fast and noisy", "Warm", "Slow and calm"], "correct_index": 1, "explanation": "Rápido e barulhento."}, {"question": "What happened along Patient's banks?", "options": ["Nothing", "A desert appeared", "Farms bloomed", "Rocks grew"], "correct_index": 2, "explanation": "Fazendas floresceram."}, {"question": "What does Patient say?", "options": ["I thought of everyone I passed", "I wanted speed", "I was lost", "I was tired"], "correct_index": 0, "explanation": "Pensou em todos que encontrou."}, {"question": "What did the people learn?", "options": ["To fish more", "To swim", "To build dams", "To value journeys over speed"], "correct_index": 3, "explanation": "Valorizar a jornada."}], "open_questions": [{"question": "Is speed always an advantage?", "key_points_pt": ["debater"]}, {"question": "What is the best way to pursue a goal?", "key_points_pt": ["discutir"]}]}}, {"level": "B2", "genre": "fable", "title": "The Weaver and the Moth", "paragraphs": ["A weaver in a mountain town had spent thirty years making a single tapestry, each thread chosen with great care. It showed a forest at dawn, and people travelled for days to see it. Yet the weaver felt that the work was never finished, and she changed small details every week.", "A moth, attracted by the colours, settled in a corner of the tapestry and began to eat a thread. The weaver, in horror, tried to chase it away. \"It is my life's work!\" she cried. The moth, unbothered, replied, \"You have stared at this wall for thirty years. You have never seen the real forest.\"", "The weaver was offended, but the sentence haunted her. At night, unable to sleep, she walked out of the house and into the real forest at the edge of town. The light at dawn was brighter than any dye. A bird sang a note that no thread could reproduce.", "She returned and, for the first time, left the tapestry untouched. She still wove, but she also began walking each morning, and her later work was looser and more alive. The moth, who had made a small hole in the corner, was allowed to stay. It reminded her that perfection is a locked door."], "paragraphs_pt": ["Uma tecelã numa cidade de montanha passara trinta anos fazendo uma única tapeçaria, cada fio escolhido com grande cuidado. Mostrava uma floresta ao amanhecer, e as pessoas viajavam dias para vê-la. Mesmo assim, a tecelã sentia que a obra nunca estava terminada e mudava pequenos detalhes toda semana.", "Uma mariposa, atraída pelas cores, pousou num canto da tapeçaria e começou a comer um fio. A tecelã, horrorizada, tentou espantá-la. \"É a obra da minha vida!\", gritou. A mariposa, despreocupada, respondeu: \"Você olha essa parede há trinta anos. Nunca viu a floresta de verdade.\"", "A tecelã ficou ofendida, mas a frase a assombrou. À noite, sem conseguir dormir, saiu de casa e foi à floresta de verdade, à beira da cidade. A luz do amanhecer era mais brilhante que qualquer tinta. Um pássaro cantou uma nota que nenhum fio podia reproduzir.", "Voltou e, pela primeira vez, deixou a tapeçaria intocada. Continuou a tecer, mas também passou a caminhar toda manhã, e seus trabalhos posteriores eram mais soltos e vivos. A mariposa, que fizera um pequeno buraco no canto, pôde ficar. Lembrava-a de que a perfeição é uma porta trancada."], "hard_words": ["tapestry", "moth", "haunted", "reproduce"], "vocab": [{"word": "weaver", "meaning": "tecelã", "note": ""}, {"word": "tapestry", "meaning": "tapeçaria", "note": ""}, {"word": "thread", "meaning": "fio", "note": ""}, {"word": "moth", "meaning": "mariposa", "note": ""}, {"word": "unbothered", "meaning": "despreocupada", "note": ""}, {"word": "haunted", "meaning": "assombrou", "note": ""}, {"word": "dye", "meaning": "tinta, corante", "note": ""}, {"word": "reproduce", "meaning": "reproduzir", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is"], "irregular": ["had", "spent", "chosen", "showed", "travelled", "felt", "finished", "changed", "attracted", "settled", "began", "tried", "cried", "replied", "stared", "seen", "offended", "haunted", "walked", "sang", "could", "returned", "left", "wove", "made", "allowed", "reminded", "locked"], "phrasal": ["walked out"], "wh": ["who"], "connectors": ["and", "but", "yet", "also", "still"], "comparative": []}, "word_meanings": [{"word": "weaver", "meaning": "tecelã", "note": ""}, {"word": "tapestry", "meaning": "tapeçaria", "note": ""}, {"word": "thread", "meaning": "fio", "note": ""}, {"word": "moth", "meaning": "mariposa", "note": ""}, {"word": "unbothered", "meaning": "despreocupada", "note": ""}, {"word": "haunted", "meaning": "assombrou", "note": ""}, {"word": "dye", "meaning": "tinta, corante", "note": ""}, {"word": "reproduce", "meaning": "reproduzir", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had spent thirty years' mostra um período anterior ao encontro."}, {"point": "Unable to + verbo", "explanation_pt": "'unable to sleep' expressa algo que não se consegue fazer."}], "multiple_choice": [{"question": "What did the weaver make?", "options": ["A tapestry", "A dress", "A basket", "A rug"], "correct_index": 0, "explanation": "Uma tapeçaria."}, {"question": "How long did she work on it?", "options": ["Thirty years", "One year", "Thirty days", "Three years"], "correct_index": 0, "explanation": "Trinta anos."}, {"question": "What did the moth say?", "options": ["The tapestry was ugly", "She was kind", "She needed a break", "She never saw the real forest"], "correct_index": 3, "explanation": "Ela nunca viu a floresta de verdade."}, {"question": "What did she do that night?", "options": ["Sold it", "Burned the tapestry", "Slept", "Went into the forest"], "correct_index": 3, "explanation": "Foi à floresta."}, {"question": "What does the moth remind her?", "options": ["Threads are weak", "Work hard", "Perfection is a locked door", "Time is money"], "correct_index": 2, "explanation": "A perfeição é uma porta trancada."}], "open_questions": [{"question": "Can perfectionism harm creativity?", "key_points_pt": ["debater"]}, {"question": "How do you balance work and rest?", "key_points_pt": ["descrever"]}]}}, {"level": "C1", "genre": "fable", "title": "The Emperor's Shadow", "paragraphs": ["There was once an emperor who feared nothing but his own shadow, for it alone refused to flatter him. The courtiers praised his wisdom, the poets his courage, and the mirrors, polished daily, his beauty; yet whenever the sun rose, there it was on the floor, long and dark, indifferent to his titles.", "One day he commanded his ministers to remove it. They tried everything: lamps from every direction, curtains of black silk, even a decree prohibiting shadows within the palace walls. The shadow vanished only at noon and returned, patient as a debt.", "An old gardener, summoned out of desperation, listened to the emperor's complaint with a straight face. \"Majesty,\" he said, \"the shadow is the only honest portrait you have. It shows your true proportions and moves only when you do. If it displeases you, change what casts it.\"", "The emperor was silent for a long while. He did not become humble overnight, but the next day he walked through the market unannounced and listened to what people really said. The shadow followed him, lighter somehow, as if relieved to have been, finally, taken seriously."], "paragraphs_pt": ["Era uma vez um imperador que nada temia, exceto a própria sombra, pois só ela se recusava a adulá-lo. Os cortesãos louvavam sua sabedoria, os poetas sua coragem e os espelhos, polidos diariamente, sua beleza; porém, sempre que o sol nascia, lá estava ela no chão, longa e escura, indiferente aos seus títulos.", "Um dia ele mandou os ministros removê-la. Tentaram tudo: lâmpadas de todas as direções, cortinas de seda preta, até um decreto proibindo sombras dentro dos muros do palácio. A sombra sumia só ao meio-dia e voltava, paciente como uma dívida.", "Um velho jardineiro, convocado por desespero, ouviu a queixa do imperador com a cara séria. \"Majestade\", disse, \"a sombra é o único retrato honesto que o senhor tem. Mostra suas verdadeiras proporções e só se move quando o senhor se move. Se lhe desagrada, mude o que a projeta.\"", "O imperador ficou calado por muito tempo. Não se tornou humilde da noite para o dia, mas no dia seguinte caminhou pelo mercado sem aviso e ouviu o que o povo realmente dizia. A sombra o seguia, de algum modo mais leve, como se aliviada por ser, enfim, levada a sério."], "hard_words": ["flatter", "indifferent", "decree", "humble"], "vocab": [{"word": "flatter", "meaning": "adular", "note": ""}, {"word": "courtiers", "meaning": "cortesãos", "note": ""}, {"word": "polished", "meaning": "polidos", "note": ""}, {"word": "indifferent", "meaning": "indiferente", "note": ""}, {"word": "decree", "meaning": "decreto", "note": ""}, {"word": "summoned", "meaning": "convocado", "note": ""}, {"word": "proportions", "meaning": "proporções", "note": ""}, {"word": "humble", "meaning": "humilde", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is", "been"], "irregular": ["feared", "refused", "praised", "polished", "rose", "commanded", "tried", "vanished", "returned", "summoned", "listened", "said", "did", "walked", "followed", "relieved", "taken"], "phrasal": ["walked through"], "wh": ["who", "what", "when", "whenever"], "connectors": ["and", "but", "while", "when", "yet", "finally", "once", "if", "as", "whenever"], "comparative": []}, "word_meanings": [{"word": "flatter", "meaning": "adular", "note": ""}, {"word": "courtiers", "meaning": "cortesãos", "note": ""}, {"word": "polished", "meaning": "polidos", "note": ""}, {"word": "indifferent", "meaning": "indiferente", "note": ""}, {"word": "decree", "meaning": "decreto", "note": ""}, {"word": "summoned", "meaning": "convocado", "note": ""}, {"word": "proportions", "meaning": "proporções", "note": ""}, {"word": "humble", "meaning": "humilde", "note": ""}], "exercises": {"grammar": [{"point": "Whenever", "explanation_pt": "'whenever the sun rose, there it was' indica repetição."}, {"point": "Imperativos condicionais", "explanation_pt": "'If it displeases you, change what casts it' dá conselho direto."}], "multiple_choice": [{"question": "What did the emperor fear?", "options": ["His shadow", "The sea", "His enemies", "Death"], "correct_index": 0, "explanation": "Temia a própria sombra."}, {"question": "Why?", "options": ["It was dark", "It refused to flatter him", "It was big", "It followed him"], "correct_index": 1, "explanation": "Porque não o adulava."}, {"question": "What did the ministers try?", "options": ["A war", "A medicine", "Lamps, curtains and a decree", "A prayer"], "correct_index": 2, "explanation": "Lâmpadas, cortinas e decreto."}, {"question": "What did the gardener say?", "options": ["Ignore it", "The shadow is evil", "The shadow is an honest portrait", "Sleep more"], "correct_index": 2, "explanation": "A sombra é um retrato honesto."}, {"question": "What did the emperor do next day?", "options": ["Walked in the market and listened", "Hid", "Moved the palace", "Fired the gardener"], "correct_index": 0, "explanation": "Caminhou pelo mercado ouvindo."}], "open_questions": [{"question": "Why do powerful people avoid honest critics?", "key_points_pt": ["discutir"]}, {"question": "What is your 'shadow' in a metaphorical sense?", "key_points_pt": ["refletir"]}]}}, {"level": "C1", "genre": "fable", "title": "The Ant Who Questioned the Hill", "paragraphs": ["In a colony of ants renowned for its discipline, one worker, Orla, developed an unfortunate habit of asking why. Why do we carry leaves to the north? Why does the queen never leave the chamber? The elders found the questions faintly obscene, not because they were dangerous, but because nobody could answer them.", "Her supervisor, a tireless ant called Brann, advised her to concentrate on carrying. \"Efficiency is our virtue,\" he said. \"Questions slow the line.\" Orla complied for a season. Yet she observed that the leaves carried north withered unused, and that the queen, who had not left the chamber in years, no longer issued commands; the colony was obeying a habit rather than a ruler.", "She shared her discovery with a few colleagues, who responded with an alarmed silence. For a while, it seemed her curiosity would be punished. Then one grey morning a storm flooded the northern tunnels, and the ants who had followed orders were trapped, whereas those who had listened to Orla were already carrying their eggs to higher ground.", "The colony did not reward her, for colonies seldom reward the inconvenient. But it did, quietly, begin to ask. Years later, a young worker asked why the hill was shaped as it was, and no elder rebuked him. That, Orla reflected, was how a change of mind looks from inside: not a revolution, but a question allowed to remain unanswered."], "paragraphs_pt": ["Numa colônia de formigas famosa por sua disciplina, uma operária, Orla, desenvolveu o infeliz hábito de perguntar por quê. Por que levamos folhas ao norte? Por que a rainha nunca sai da câmara? Os anciãos achavam as perguntas levemente obscenas, não por serem perigosas, mas porque ninguém sabia respondê-las.", "Seu supervisor, uma formiga incansável chamada Brann, aconselhou-a a se concentrar em carregar. \"Eficiência é nossa virtude\", disse. \"Perguntas atrasam a fila.\" Orla obedeceu por uma estação. Mas observou que as folhas levadas ao norte murchavam sem uso e que a rainha, que não saía da câmara havia anos, já não dava ordens; a colônia obedecia a um hábito, não a uma governante.", "Compartilhou a descoberta com alguns colegas, que reagiram com um silêncio alarmado. Por um tempo pareceu que sua curiosidade seria punida. Então, numa manhã cinzenta, uma tempestade inundou os túneis do norte e as formigas que haviam seguido ordens ficaram presas, enquanto as que ouviram Orla já levavam seus ovos para terreno mais alto.", "A colônia não a recompensou, pois colônias raramente recompensam o inconveniente. Mas começou, discretamente, a perguntar. Anos depois, uma jovem operária perguntou por que o formigueiro tinha aquela forma, e nenhum ancião a repreendeu. Era assim, refletiu Orla, que uma mudança de mentalidade se vê por dentro: não uma revolução, mas uma pergunta deixada sem resposta."], "hard_words": ["renowned", "complied", "withered", "rebuked"], "vocab": [{"word": "renowned", "meaning": "famosa", "note": ""}, {"word": "discipline", "meaning": "disciplina", "note": ""}, {"word": "elders", "meaning": "anciãos", "note": ""}, {"word": "complied", "meaning": "obedeceu", "note": ""}, {"word": "withered", "meaning": "murchavam", "note": ""}, {"word": "flooded", "meaning": "inundou", "note": ""}, {"word": "trapped", "meaning": "presos", "note": ""}, {"word": "rebuked", "meaning": "repreendeu", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "is", "was", "be"], "irregular": ["developed", "found", "could", "called", "advised", "said", "complied", "observed", "carried", "withered", "had", "left", "issued", "shared", "responded", "alarmed", "seemed", "would", "punished", "flooded", "followed", "trapped", "listened", "ground", "did", "asked", "shaped", "rebuked", "reflected", "allowed"], "phrasal": [], "wh": ["who", "why", "how"], "connectors": ["and", "but", "because", "while", "then", "whereas", "yet", "as"], "comparative": []}, "word_meanings": [{"word": "renowned", "meaning": "famosa", "note": ""}, {"word": "discipline", "meaning": "disciplina", "note": ""}, {"word": "elders", "meaning": "anciãos", "note": ""}, {"word": "complied", "meaning": "obedeceu", "note": ""}, {"word": "withered", "meaning": "murchavam", "note": ""}, {"word": "flooded", "meaning": "inundou", "note": ""}, {"word": "trapped", "meaning": "presos", "note": ""}, {"word": "rebuked", "meaning": "repreendeu", "note": ""}], "exercises": {"grammar": [{"point": "Not because... but because", "explanation_pt": "'not because they were dangerous, but because nobody could answer them' explica a causa real."}, {"point": "Whereas", "explanation_pt": "'whereas those who had listened' contrasta dois grupos."}], "multiple_choice": [{"question": "What was Orla's habit?", "options": ["Singing", "Asking why", "Stealing", "Sleeping"], "correct_index": 1, "explanation": "Perguntar por quê."}, {"question": "What did Brann advise?", "options": ["Talk to the queen", "Leave", "Ask more", "Concentrate on carrying"], "correct_index": 3, "explanation": "Concentrar-se em carregar."}, {"question": "What did Orla notice about the queen?", "options": ["She was dead", "She was young", "She was angry", "She no longer issued commands"], "correct_index": 3, "explanation": "Já não dava ordens."}, {"question": "What happened in the storm?", "options": ["The queen died", "The hill moved", "The northern tunnels flooded", "The leaves grew"], "correct_index": 2, "explanation": "Os túneis do norte inundaram."}, {"question": "How did the colony change?", "options": ["It built a statue", "It punished Orla", "It left", "It quietly began to ask"], "correct_index": 3, "explanation": "Passou a perguntar."}], "open_questions": [{"question": "Why are institutions slow to change?", "key_points_pt": ["discutir"]}, {"question": "Should we obey tradition without questions?", "key_points_pt": ["debater"]}]}}, {"level": "C1", "genre": "fable", "title": "The Glass Lion", "paragraphs": ["In the market square of a coastal town stood a lion made of glass, sculpted by a vanished artist and admired for the way it caught the morning light. It was fragile, and the town considered itself its guardian: children were forbidden to touch it, and a small fence surrounded its base. For generations, the lion had been admired and, therefore, never approached.", "One winter a sudden storm toppled the fence, and a stray child stumbled against the pedestal. The lion rocked and, to everyone's horror, did not break. The sculptor, it appeared, had hidden a core of iron beneath the transparent surface. For centuries the town had worshipped a fragility that had never existed.", "The discovery did not make people love the lion less, but it unsettled their sense of themselves. Had they been so cautious about the statue because they truly believed it fragile, or because the belief had been convenient, a reason to keep a lovely thing at a distance?", "The fence was never rebuilt. Children now climbed on the lion's back, and its glass grew smudged with fingerprints. Visitors complained that it was no longer so beautiful, and the townspeople shrugged. They had learned that preservation and affection were different gestures, and that only one of them kept anything alive."], "paragraphs_pt": ["Na praça do mercado de uma cidade litorânea havia um leão de vidro, esculpido por um artista desaparecido e admirado pelo modo como captava a luz da manhã. Era frágil, e a cidade se considerava sua guardiã: crianças eram proibidas de tocá-lo e uma pequena cerca cercava sua base. Por gerações o leão fora admirado e, por isso, nunca abordado.", "Num inverno, uma tempestade repentina derrubou a cerca e uma criança perdida tropeçou no pedestal. O leão balançou e, para horror de todos, não quebrou. O escultor, ao que parecia, escondera um núcleo de ferro sob a superfície transparente. Por séculos a cidade venerara uma fragilidade que nunca existira.", "A descoberta não fez as pessoas amarem menos o leão, mas abalou a noção que tinham de si. Teriam sido tão cuidadosos com a estátua por acreditarem realmente em sua fragilidade, ou porque a crença fora conveniente, uma razão para manter uma coisa bela à distância?", "A cerca nunca foi reconstruída. As crianças passaram a subir nas costas do leão e o vidro se encheu de marcas de dedos. Os visitantes reclamaram que já não era tão belo e os habitantes deram de ombros. Haviam aprendido que preservação e afeto eram gestos diferentes e que só um deles mantinha algo vivo."], "hard_words": ["fragile", "toppled", "worshipped", "smudged"], "vocab": [{"word": "sculpted", "meaning": "esculpido", "note": ""}, {"word": "fragile", "meaning": "frágil", "note": ""}, {"word": "guardian", "meaning": "guardiã", "note": ""}, {"word": "toppled", "meaning": "derrubou", "note": ""}, {"word": "pedestal", "meaning": "pedestal", "note": ""}, {"word": "core", "meaning": "núcleo", "note": ""}, {"word": "worshipped", "meaning": "venerara", "note": ""}, {"word": "smudged", "meaning": "manchado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been"], "irregular": ["stood", "made", "sculpted", "vanished", "admired", "caught", "considered", "forbidden", "surrounded", "had", "approached", "toppled", "stumbled", "rocked", "did", "appeared", "hidden", "worshipped", "existed", "unsettled", "believed", "rebuilt", "climbed", "grew", "smudged", "complained", "shrugged", "learned", "kept"], "phrasal": ["stumbled against", "shrugged"], "wh": [], "connectors": ["and", "but", "because", "so", "therefore", "or"], "comparative": []}, "word_meanings": [{"word": "sculpted", "meaning": "esculpido", "note": ""}, {"word": "fragile", "meaning": "frágil", "note": ""}, {"word": "guardian", "meaning": "guardiã", "note": ""}, {"word": "toppled", "meaning": "derrubou", "note": ""}, {"word": "pedestal", "meaning": "pedestal", "note": ""}, {"word": "core", "meaning": "núcleo", "note": ""}, {"word": "worshipped", "meaning": "venerara", "note": ""}, {"word": "smudged", "meaning": "manchado", "note": ""}], "exercises": {"grammar": [{"point": "Third conditional ideas", "explanation_pt": "'Had they been so cautious... because the belief had been convenient' usa inversão com 'had' para formular uma dúvida sobre o passado."}, {"point": "Therefore", "explanation_pt": "'admired and, therefore, never approached' marca consequência."}], "multiple_choice": [{"question": "What was the lion made of?", "options": ["Iron", "Glass", "Stone", "Wood"], "correct_index": 1, "explanation": "Vidro."}, {"question": "What was forbidden?", "options": ["Selling it", "Touching it", "Painting it", "Seeing it"], "correct_index": 1, "explanation": "Tocá-lo."}, {"question": "What did the storm reveal?", "options": ["An iron core", "A treasure", "A message", "A crack"], "correct_index": 0, "explanation": "Um núcleo de ferro."}, {"question": "What did the town ask itself?", "options": ["Whether their belief was convenient", "Whether to sell it", "Where to move it", "Who built it"], "correct_index": 0, "explanation": "Se a crença fora conveniente."}, {"question": "What changed at the end?", "options": ["Children climbed on it", "It was sold", "The fence was rebuilt", "It was destroyed"], "correct_index": 0, "explanation": "As crianças subiam nele."}], "open_questions": [{"question": "Do we sometimes protect things so much we stop enjoying them?", "key_points_pt": ["refletir"]}, {"question": "What is the difference between preservation and affection?", "key_points_pt": ["explicar"]}]}}, {"level": "C2", "genre": "fable", "title": "The Tailor of Omens", "paragraphs": ["In a kingdom that had grown superstitious, a tailor named Idris became famous for sewing garments that, according to his customers, foretold the future. A blue cloak signified a prosperous harvest; a hem with a loose thread predicted an inheritance. He never claimed such powers himself; he simply smiled when people interpreted his seams, a silence that was good for business.", "The king, anxious about a looming war, ordered a cloak that would foretell victory. Idris, who knew nothing of strategy, sewed a splendid scarlet garment and presented it with studied ambiguity. The king wore it into battle, and, when the army narrowly won, he proclaimed the tailor a prophet. A hundred people rushed to purchase scarlet cloaks.", "The following year, the cloak seemed to predict defeat, and the king, enraged, summoned Idris. The tailor bowed low. \"Majesty, I made nothing but a cloak. You wove the rest.\" He explained that people want a thread to follow through the labyrinth of events and will gladly invent one if nobody offers it. His sincerity astonished the court into silence.", "Surprisingly, the king did not execute him. He sentenced him to make plain garments for the poor for the rest of his days, a sentence Idris accepted with unexpected relief. It is said that the clothes he sewed in that period were the first to bring him nothing but honest gratitude, which, as he noted, was a sturdier fabric than prophecy."], "paragraphs_pt": ["Num reino que se tornara supersticioso, um alfaiate chamado Idris ficou famoso por costurar roupas que, segundo os clientes, previam o futuro. Uma capa azul significava colheita próspera; uma bainha com um fio solto previa uma herança. Ele nunca alegou tais poderes; apenas sorria quando interpretavam suas costuras, um silêncio que fazia bem aos negócios.", "O rei, ansioso com uma guerra iminente, encomendou uma capa que previsse vitória. Idris, que nada sabia de estratégia, costurou uma esplêndida veste escarlate e a apresentou com ambiguidade estudada. O rei a vestiu na batalha e, quando o exército venceu por pouco, proclamou o alfaiate profeta. Cem pessoas correram para comprar capas escarlates.", "No ano seguinte, a capa pareceu prever derrota e o rei, enfurecido, convocou Idris. O alfaiate curvou-se. \"Majestade, não fiz nada além de uma capa. O senhor teceu o resto.\" Explicou que as pessoas querem um fio para seguir pelo labirinto dos acontecimentos e alegremente o inventam se ninguém o oferece. Sua sinceridade espantou a corte até o silêncio.", "Surpreendentemente, o rei não o executou. Condenou-o a fazer roupas simples para os pobres pelo resto da vida, sentença que Idris aceitou com alívio inesperado. Diz-se que as roupas que costurou nesse período foram as primeiras a lhe trazer apenas gratidão honesta, que, como ele notou, era um tecido mais resistente que a profecia."], "hard_words": ["superstitious", "ambiguity", "labyrinth", "sturdier"], "vocab": [{"word": "superstitious", "meaning": "supersticioso", "note": ""}, {"word": "foretold", "meaning": "previam", "note": ""}, {"word": "hem", "meaning": "bainha", "note": ""}, {"word": "looming", "meaning": "iminente", "note": ""}, {"word": "ambiguity", "meaning": "ambiguidade", "note": ""}, {"word": "enraged", "meaning": "enfurecido", "note": ""}, {"word": "labyrinth", "meaning": "labirinto", "note": ""}, {"word": "sturdier", "meaning": "mais resistente", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is", "were"], "irregular": ["had", "grown", "named", "became", "foretold", "signified", "predicted", "claimed", "smiled", "interpreted", "ordered", "would", "knew", "sewed", "presented", "studied", "wore", "won", "proclaimed", "rushed", "seemed", "enraged", "summoned", "bowed", "made", "wove", "explained", "astonished", "did", "sentenced", "accepted", "said", "noted"], "phrasal": ["rushed to", "wove the rest"], "wh": ["who", "when", "which"], "connectors": ["and", "but", "when", "if", "as"], "comparative": []}, "word_meanings": [{"word": "superstitious", "meaning": "supersticioso", "note": ""}, {"word": "foretold", "meaning": "previam", "note": ""}, {"word": "hem", "meaning": "bainha", "note": ""}, {"word": "looming", "meaning": "iminente", "note": ""}, {"word": "ambiguity", "meaning": "ambiguidade", "note": ""}, {"word": "enraged", "meaning": "enfurecido", "note": ""}, {"word": "labyrinth", "meaning": "labirinto", "note": ""}, {"word": "sturdier", "meaning": "mais resistente", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'a kingdom that had grown superstitious' dá o contexto."}, {"point": "Comparativos", "explanation_pt": "'a sturdier fabric than prophecy' compara resistência."}], "multiple_choice": [{"question": "Why was Idris famous?", "options": ["He was cheap", "He was a poet", "He was a soldier", "People believed his clothes foretold the future"], "correct_index": 3, "explanation": "Acreditavam que suas roupas previam o futuro."}, {"question": "What did the king order?", "options": ["A crown", "A tent", "A sword", "A cloak to foretell victory"], "correct_index": 3, "explanation": "Uma capa que previsse vitória."}, {"question": "What happened the following year?", "options": ["Idris died", "The king abdicated", "The cloak seemed to predict defeat", "The war ended"], "correct_index": 2, "explanation": "A capa pareceu prever derrota."}, {"question": "What was Idris's defence?", "options": ["The cloak was cursed", "The king lied", "The war was fake", "People invent meaning themselves"], "correct_index": 3, "explanation": "As pessoas inventam significado."}, {"question": "What was his sentence?", "options": ["Death", "Make plain garments for the poor", "Exile", "Prison"], "correct_index": 1, "explanation": "Fazer roupas simples para os pobres."}], "open_questions": [{"question": "Why do people seek omens and predictions?", "key_points_pt": ["discutir"]}, {"question": "Is silence sometimes a form of dishonesty?", "key_points_pt": ["debater"]}]}}, {"level": "C2", "genre": "fable", "title": "The Stone That Wished to Flow", "paragraphs": ["At the bottom of a mountain stream lay a stone who envied the water. The water passed over it without effort, singing, never remaining in one place long enough to be burdened. The stone, by contrast, was heavy with centuries, and it ached with a longing that it could not name. \"If only I could move,\" it murmured, and the stream, in its careless way, answered: \"Then let go of your shape.\"", "The stone did not understand, but it began, unconsciously, to obey. Year by year, the current eroded its edges until the rough corners softened into a smooth curve. Birds used it as a stepping-stone; children pocketed it for luck. It still did not travel, yet it felt a change that was neither movement nor stillness.", "One spring, a flood carried it downstream, rolling it against others, wearing it down to a pebble that fitted in a hand. A traveller found it on a riverbank and kept it in her coat for years, a small, warm weight against the ribs on long journeys. The stone realised, with a kind of astonishment, that it had been travelling all along.", "Water, it understood, had never been free from the stone but dependent on it: without banks and beds, a river is only a flood. The two were not opposites but collaborators in the long, patient art of making a landscape. It did not envy anything again, which is to say that it had at last become part of something."], "paragraphs_pt": ["No fundo de um riacho de montanha jazia uma pedra que invejava a água. A água passava sobre ela sem esforço, cantando, sem nunca ficar num lugar o bastante para ser sobrecarregada. A pedra, ao contrário, era pesada de séculos e doía-lhe um anseio que não sabia nomear. \"Se ao menos eu pudesse me mover\", murmurou, e o riacho, a seu modo descuidado, respondeu: \"Então largue sua forma.\"", "A pedra não entendeu, mas começou, inconscientemente, a obedecer. Ano após ano, a correnteza erodiu suas bordas até que os cantos ásperos amaciaram numa curva lisa. Pássaros a usavam de apoio; crianças a guardavam no bolso para dar sorte. Continuava sem viajar, mas sentia uma mudança que não era movimento nem imobilidade.", "Numa primavera, uma enchente a levou rio abaixo, rolando-a contra outras, desgastando-a até virar um seixo que cabia na mão. Uma viajante a achou na margem e a guardou no casaco por anos, um peso pequeno e quente junto às costelas nas longas jornadas. A pedra percebeu, com uma espécie de espanto, que estivera viajando o tempo todo.", "A água, entendeu, nunca fora livre da pedra, mas dependente dela: sem margens e leitos, um rio é apenas uma inundação. As duas não eram opostos, mas colaboradoras na arte longa e paciente de fazer uma paisagem. Nunca mais invejou nada, o que equivale a dizer que enfim se tornara parte de algo."], "hard_words": ["burdened", "eroded", "pebble", "collaborators"], "vocab": [{"word": "envied", "meaning": "invejava", "note": ""}, {"word": "burdened", "meaning": "sobrecarregada", "note": ""}, {"word": "longing", "meaning": "anseio", "note": ""}, {"word": "eroded", "meaning": "erodiu", "note": ""}, {"word": "stepping-stone", "meaning": "pedra de apoio", "note": ""}, {"word": "pebble", "meaning": "seixo", "note": ""}, {"word": "astonishment", "meaning": "espanto", "note": ""}, {"word": "collaborators", "meaning": "colaboradoras", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "was", "been", "is", "were"], "irregular": ["lay", "envied", "passed", "burdened", "ached", "could", "murmured", "answered", "did", "began", "eroded", "softened", "used", "pocketed", "felt", "carried", "fitted", "found", "kept", "realised", "had", "understood"], "phrasal": ["let go of"], "wh": ["who", "which"], "connectors": ["and", "but", "then", "until", "yet", "still", "if", "as"], "comparative": []}, "word_meanings": [{"word": "envied", "meaning": "invejava", "note": ""}, {"word": "burdened", "meaning": "sobrecarregada", "note": ""}, {"word": "longing", "meaning": "anseio", "note": ""}, {"word": "eroded", "meaning": "erodiu", "note": ""}, {"word": "stepping-stone", "meaning": "pedra de apoio", "note": ""}, {"word": "pebble", "meaning": "seixo", "note": ""}, {"word": "astonishment", "meaning": "espanto", "note": ""}, {"word": "collaborators", "meaning": "colaboradoras", "note": ""}], "exercises": {"grammar": [{"point": "If only", "explanation_pt": "'If only I could move' expressa um desejo difícil de realizar."}, {"point": "Neither... nor", "explanation_pt": "'neither movement nor stillness' nega as duas opções."}], "multiple_choice": [{"question": "What did the stone envy?", "options": ["The sun", "The wind", "The water", "The birds"], "correct_index": 2, "explanation": "Invejava a água."}, {"question": "What did the stream tell it?", "options": ["Sleep", "Let go of your shape", "Be quiet", "Stay still"], "correct_index": 1, "explanation": "Largue sua forma."}, {"question": "What happened over the years?", "options": ["It grew", "It floated", "It broke", "The current softened its edges"], "correct_index": 3, "explanation": "A correnteza suavizou as bordas."}, {"question": "Where did it end up?", "options": ["In a museum", "In a wall", "At sea", "In a traveller's coat"], "correct_index": 3, "explanation": "No casaco de uma viajante."}, {"question": "What did it finally understand?", "options": ["Stones are useless", "Rivers are free", "Travel is dangerous", "Water and stone are collaborators"], "correct_index": 3, "explanation": "Água e pedra colaboram."}], "open_questions": [{"question": "Can limits make something meaningful?", "key_points_pt": ["discutir"]}, {"question": "When have you envied someone who later seemed to envy you?", "key_points_pt": ["refletir"]}]}}, {"level": "C2", "genre": "fable", "title": "The Cartographer and the Sea", "paragraphs": ["A cartographer named Ysolde dedicated her life to drawing a map so accurate that no sailor would ever be lost. She measured coastlines in all weathers, corrected the errors of her predecessors, and entered every reef and current with a precision that bordered on devotion. When she finished, the map covered the walls of an entire hall, and the guild declared it the most faithful representation of the sea ever made.", "Yet the first captain to use it ran aground on a sandbank that did not appear anywhere on the parchment. Furious, he returned to demand an explanation. Ysolde, who had never sailed, stood before the great chart and admitted, with a strange calm, that the sea had changed since she drew it. Sandbanks drift; currents bend; the only constant is the habit of change.", "She realised, to her dismay, that a map is a promise made in the past tense. The more perfect the drawing, the more dangerous the illusion that the world would remain as depicted. She spent her last years not correcting the map, but teaching apprentices to read the water itself: the colour of shoals, the behaviour of birds, the sound of a hull in shallow places.", "When she died, the great chart was hung in the guild's hall as a monument, and young sailors admired it without using it. They carried instead a plain notebook and a habit of watching. It was Ysolde's most useful legacy, though it never carried her name, and perhaps for that very reason it travelled farther than any map."], "paragraphs_pt": ["Uma cartógrafa chamada Ysolde dedicou a vida a desenhar um mapa tão exato que nenhum marinheiro jamais se perderia. Mediu litorais em todos os climas, corrigiu os erros de suas antecessoras e registrou cada recife e corrente com uma precisão que beirava a devoção. Quando terminou, o mapa cobria as paredes de um salão inteiro, e a guilda o declarou a representação mais fiel do mar já feita.", "Porém o primeiro capitão a usá-lo encalhou num banco de areia que não aparecia em lugar algum do pergaminho. Furioso, voltou para exigir explicação. Ysolde, que nunca navegara, ficou diante da grande carta e admitiu, com estranha calma, que o mar mudara desde que o desenhara. Bancos de areia se deslocam; correntes se curvam; a única constante é o hábito de mudar.", "Percebeu, consternada, que um mapa é uma promessa feita no passado. Quanto mais perfeito o desenho, mais perigosa a ilusão de que o mundo permaneceria como retratado. Passou seus últimos anos não corrigindo o mapa, mas ensinando aprendizes a ler a própria água: a cor dos baixios, o comportamento das aves, o som de um casco em águas rasas.", "Quando morreu, a grande carta foi pendurada no salão da guilda como monumento, e os jovens marinheiros a admiravam sem usá-la. Levavam, em vez disso, um caderno simples e o hábito de observar. Foi o legado mais útil de Ysolde, ainda que nunca levasse seu nome, e talvez por isso mesmo tenha viajado mais longe que qualquer mapa."], "hard_words": ["cartographer", "devotion", "shoals", "legacy"], "vocab": [{"word": "cartographer", "meaning": "cartógrafa", "note": ""}, {"word": "predecessors", "meaning": "antecessoras", "note": ""}, {"word": "devotion", "meaning": "devoção", "note": ""}, {"word": "ran aground", "meaning": "encalhou", "note": ""}, {"word": "parchment", "meaning": "pergaminho", "note": ""}, {"word": "shoals", "meaning": "baixios", "note": ""}, {"word": "apprentices", "meaning": "aprendizes", "note": ""}, {"word": "legacy", "meaning": "legado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "is", "was"], "irregular": ["named", "dedicated", "would", "lost", "measured", "corrected", "entered", "bordered", "finished", "covered", "declared", "made", "ran", "did", "returned", "had", "sailed", "stood", "admitted", "changed", "drew", "realised", "depicted", "spent", "died", "hung", "admired", "carried", "travelled"], "phrasal": ["ran aground", "hung in"], "wh": ["who", "when"], "connectors": ["and", "but", "so", "though", "instead", "before", "when", "since", "yet", "as"], "comparative": []}, "word_meanings": [{"word": "cartographer", "meaning": "cartógrafa", "note": ""}, {"word": "predecessors", "meaning": "antecessoras", "note": ""}, {"word": "devotion", "meaning": "devoção", "note": ""}, {"word": "ran aground", "meaning": "encalhou", "note": ""}, {"word": "parchment", "meaning": "pergaminho", "note": ""}, {"word": "shoals", "meaning": "baixios", "note": ""}, {"word": "apprentices", "meaning": "aprendizes", "note": ""}, {"word": "legacy", "meaning": "legado", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'who had never sailed' explica uma falta de experiência anterior."}, {"point": "The more... the more", "explanation_pt": "'The more perfect the drawing, the more dangerous the illusion' mostra relação proporcional."}], "multiple_choice": [{"question": "What did Ysolde want to draw?", "options": ["A perfect map", "A plan of a house", "A comic", "A portrait"], "correct_index": 0, "explanation": "Um mapa perfeito."}, {"question": "What happened to the first captain?", "options": ["He ran aground on a sandbank", "He found treasure", "He got lost in a storm", "He was robbed"], "correct_index": 0, "explanation": "Encalhou num banco de areia."}, {"question": "Why was the map wrong?", "options": ["She lied", "She was blind", "The ink faded", "The sea had changed"], "correct_index": 3, "explanation": "O mar mudara."}, {"question": "What did she teach in her last years?", "options": ["To build ships", "To draw maps", "To fish", "To read the water"], "correct_index": 3, "explanation": "A ler a água."}, {"question": "What did sailors carry instead of the chart?", "options": ["A second map", "A compass only", "Nothing", "A plain notebook and a habit of watching"], "correct_index": 3, "explanation": "Um caderno simples e o hábito de observar."}], "open_questions": [{"question": "Why can a perfect description become dangerous?", "key_points_pt": ["discutir"]}, {"question": "How do we keep knowledge up to date?", "key_points_pt": ["propor"]}]}}, {"level": "A1", "genre": "fantasy", "title": "The Magic Door", "paragraphs": ["Ana finds a small door in her garden. It is blue and has a gold key. She opens it.", "Behind the door, there is a green world. The trees are tall and purple. A little dragon is there. \"Hello!\" says the dragon. \"I am Pip.\"", "Ana plays with Pip all day. At night she says, \"Goodbye!\" She goes home. She closes the door. She wants to come back tomorrow."], "paragraphs_pt": ["Ana encontra uma portinha no jardim. É azul e tem uma chave dourada. Ela a abre.", "Atrás da porta há um mundo verde. As árvores são altas e roxas. Um dragãozinho está lá. \"Olá!\", diz o dragão. \"Eu sou o Pip.\"", "Ana brinca com Pip o dia todo. À noite ela diz: \"Tchau!\" Vai para casa. Fecha a porta. Quer voltar amanhã."], "hard_words": ["door", "garden", "dragon", "purple"], "vocab": [{"word": "door", "meaning": "porta", "note": ""}, {"word": "garden", "meaning": "jardim", "note": ""}, {"word": "gold", "meaning": "dourado", "note": ""}, {"word": "key", "meaning": "chave", "note": ""}, {"word": "dragon", "meaning": "dragão", "note": ""}, {"word": "tall", "meaning": "alto", "note": ""}, {"word": "purple", "meaning": "roxo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are", "am"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "door", "meaning": "porta", "note": ""}, {"word": "garden", "meaning": "jardim", "note": ""}, {"word": "gold", "meaning": "dourado", "note": ""}, {"word": "key", "meaning": "chave", "note": ""}, {"word": "dragon", "meaning": "dragão", "note": ""}, {"word": "tall", "meaning": "alto", "note": ""}, {"word": "purple", "meaning": "roxo", "note": ""}], "exercises": {"grammar": [{"point": "There is / There are", "explanation_pt": "'There is a green world' e 'The trees are tall' descrevem lugares."}], "multiple_choice": [{"question": "What color is the door?", "options": ["Red", "Green", "Blue", "Black"], "correct_index": 2, "explanation": "A porta é azul."}, {"question": "Where is the door?", "options": ["In a car", "In the garden", "In a shop", "In the school"], "correct_index": 1, "explanation": "No jardim."}, {"question": "What color are the trees?", "options": ["Brown", "Red", "White", "Purple"], "correct_index": 3, "explanation": "As árvores são roxas."}, {"question": "What is the dragon's name?", "options": ["Pip", "Leo", "Tom", "Max"], "correct_index": 0, "explanation": "Pip."}, {"question": "What does Ana want?", "options": ["To come back", "To sleep", "To cook", "To stay"], "correct_index": 0, "explanation": "Quer voltar."}], "open_questions": [{"question": "What magic world do you want to visit?", "key_points_pt": ["descrever"]}, {"question": "What animal do you like?", "key_points_pt": ["descrever"]}]}}, {"level": "A1", "genre": "fantasy", "title": "The Wizard's Hat", "paragraphs": ["A wizard has a big hat. The hat is blue with stars. It is very old. One day the wizard loses his hat.", "\"Where is my hat?\" he says. He looks under the bed. He looks in the kitchen. He cannot find it.", "A cat comes. The cat has the hat on its head! \"You are a funny cat,\" says the wizard. He laughs and takes the hat."], "paragraphs_pt": ["Um mago tem um chapéu grande. O chapéu é azul com estrelas. É muito velho. Um dia o mago perde o chapéu.", "\"Onde está meu chapéu?\", ele diz. Olha debaixo da cama. Olha na cozinha. Não consegue encontrar.", "Um gato chega. O gato está com o chapéu na cabeça! \"Você é um gato engraçado\", diz o mago. Ele ri e pega o chapéu."], "hard_words": ["wizard", "hat", "stars", "funny"], "vocab": [{"word": "wizard", "meaning": "mago", "note": ""}, {"word": "hat", "meaning": "chapéu", "note": ""}, {"word": "stars", "meaning": "estrelas", "note": ""}, {"word": "old", "meaning": "velho", "note": ""}, {"word": "bed", "meaning": "cama", "note": ""}, {"word": "head", "meaning": "cabeça", "note": ""}, {"word": "funny", "meaning": "engraçado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": ["where"], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "wizard", "meaning": "mago", "note": ""}, {"word": "hat", "meaning": "chapéu", "note": ""}, {"word": "stars", "meaning": "estrelas", "note": ""}, {"word": "old", "meaning": "velho", "note": ""}, {"word": "bed", "meaning": "cama", "note": ""}, {"word": "head", "meaning": "cabeça", "note": ""}, {"word": "funny", "meaning": "engraçado", "note": ""}], "exercises": {"grammar": [{"point": "Where is...?", "explanation_pt": "'Where is my hat?' pergunta onde algo está."}], "multiple_choice": [{"question": "What color is the hat?", "options": ["Black", "White", "Red", "Blue"], "correct_index": 3, "explanation": "Azul."}, {"question": "What does the hat have?", "options": ["Hearts", "Stars", "Dots", "Flowers"], "correct_index": 1, "explanation": "Estrelas."}, {"question": "Where does the wizard look?", "options": ["In the school", "In the car", "Under the bed and in the kitchen", "In the garden"], "correct_index": 2, "explanation": "Debaixo da cama e na cozinha."}, {"question": "Who has the hat?", "options": ["The king", "The cat", "The bird", "The dog"], "correct_index": 1, "explanation": "O gato."}, {"question": "What does the wizard do?", "options": ["He cries", "He runs", "He laughs", "He sleeps"], "correct_index": 2, "explanation": "Ele ri."}], "open_questions": [{"question": "What can a wizard do?", "key_points_pt": ["imaginar"]}, {"question": "Do you like cats?", "key_points_pt": ["opinar"]}]}}, {"level": "A2", "genre": "fantasy", "title": "The Dragon Who Was Afraid of Fire", "paragraphs": ["In a cave on top of a mountain lived a young dragon called Ember. Her family could breathe fire, but Ember couldn't. Every time she tried, a little smoke came out of her nose, and her brothers laughed.", "One cold night, a small knight lost his way in the snow. He found Ember's cave and knocked on the stone wall. \"Please help me,\" he said. \"I am freezing.\" Ember wanted to help, but she had no fire.", "She remembered the smoke and had an idea. She breathed on a pile of dry branches, very gently, and a tiny spark appeared. Slowly it grew into a warm fire. The knight smiled. \"Thank you, Ember!\" he said. She finally understood that her fire was small but kind."], "paragraphs_pt": ["Numa caverna no topo de uma montanha vivia uma jovem dragoa chamada Ember. A família dela podia soltar fogo, mas Ember não conseguia. Toda vez que tentava, saía um pouco de fumaça do nariz e seus irmãos riam.", "Numa noite fria, um pequeno cavaleiro se perdeu na neve. Achou a caverna de Ember e bateu na parede de pedra. \"Por favor, me ajude\", disse. \"Estou congelando.\" Ember quis ajudar, mas não tinha fogo.", "Lembrou da fumaça e teve uma ideia. Soprou numa pilha de galhos secos, bem suavemente, e uma faísca minúscula apareceu. Devagar cresceu e virou um fogo morno. O cavaleiro sorriu. \"Obrigado, Ember!\", disse. Ela finalmente entendeu que seu fogo era pequeno, mas gentil."], "hard_words": ["cave", "knight", "spark", "gently"], "vocab": [{"word": "cave", "meaning": "caverna", "note": ""}, {"word": "breathe", "meaning": "soltar, respirar", "note": ""}, {"word": "smoke", "meaning": "fumaça", "note": ""}, {"word": "knight", "meaning": "cavaleiro", "note": ""}, {"word": "freezing", "meaning": "congelando", "note": ""}, {"word": "branches", "meaning": "galhos", "note": ""}, {"word": "spark", "meaning": "faísca", "note": ""}, {"word": "gently", "meaning": "suavemente", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["am", "was"], "irregular": ["lived", "called", "could", "tried", "came", "laughed", "lost", "found", "knocked", "said", "wanted", "had", "remembered", "breathed", "appeared", "grew", "smiled", "understood"], "phrasal": ["lost his way", "came out"], "wh": [], "connectors": ["and", "but", "finally"], "comparative": []}, "word_meanings": [{"word": "cave", "meaning": "caverna", "note": ""}, {"word": "breathe", "meaning": "soltar, respirar", "note": ""}, {"word": "smoke", "meaning": "fumaça", "note": ""}, {"word": "knight", "meaning": "cavaleiro", "note": ""}, {"word": "freezing", "meaning": "congelando", "note": ""}, {"word": "branches", "meaning": "galhos", "note": ""}, {"word": "spark", "meaning": "faísca", "note": ""}, {"word": "gently", "meaning": "suavemente", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'lived', 'laughed', 'remembered' contam o passado."}, {"point": "Could / couldn't", "explanation_pt": "'Ember couldn't' diz o que ela não conseguia fazer."}], "multiple_choice": [{"question": "Where did Ember live?", "options": ["In a forest", "In a village", "In a castle", "In a cave on a mountain"], "correct_index": 3, "explanation": "Numa caverna na montanha."}, {"question": "What could Ember NOT do?", "options": ["Fly", "Sing", "Breathe fire", "Run"], "correct_index": 2, "explanation": "Não soltava fogo."}, {"question": "Who knocked on the wall?", "options": ["A wizard", "A knight", "A bird", "A king"], "correct_index": 1, "explanation": "Um cavaleiro."}, {"question": "How did Ember make fire?", "options": ["She flew away", "She breathed gently on branches", "She asked the knight", "She used a match"], "correct_index": 1, "explanation": "Soprou nos galhos."}, {"question": "What did Ember understand?", "options": ["She was big", "She was alone", "She was fast", "Her fire was small but kind"], "correct_index": 3, "explanation": "Seu fogo era pequeno, mas gentil."}], "open_questions": [{"question": "What makes you special?", "key_points_pt": ["falar de si"]}, {"question": "Have you helped someone in need?", "key_points_pt": ["contar"]}]}}, {"level": "A2", "genre": "fantasy", "title": "The Talking Tree", "paragraphs": ["Lucas lived in a village next to a big forest. One afternoon, he heard a voice. \"Hello, boy!\" it said. Lucas looked around, but nobody was there. \"I am here, behind you,\" said the voice. It was an old oak tree.", "\"Trees can't talk!\" said Lucas. \"Only to people who listen,\" answered the tree. It told him stories about the forest: about the animals, the rain and the stars it saw every night.", "Lucas visited the tree every day. One evening, the tree said, \"I am tired. Winter is coming, and I must sleep.\" Lucas put a blanket of leaves around it and said goodnight. In spring, the tree woke up and said, \"Welcome back, my friend.\""], "paragraphs_pt": ["Lucas vivia numa aldeia ao lado de uma floresta grande. Numa tarde, ouviu uma voz. \"Olá, menino!\", disse. Lucas olhou em volta, mas não havia ninguém. \"Estou aqui, atrás de você\", disse a voz. Era um velho carvalho.", "\"Árvores não falam!\", disse Lucas. \"Só com quem escuta\", respondeu a árvore. Contou-lhe histórias da floresta: dos animais, da chuva e das estrelas que via toda noite.", "Lucas visitava a árvore todo dia. Numa noite, a árvore disse: \"Estou cansada. O inverno vem chegando e preciso dormir.\" Lucas colocou um cobertor de folhas em volta e desejou boa noite. Na primavera, a árvore acordou e disse: \"Bem-vindo de volta, meu amigo.\""], "hard_words": ["village", "voice", "listen", "blanket"], "vocab": [{"word": "village", "meaning": "aldeia", "note": ""}, {"word": "forest", "meaning": "floresta", "note": ""}, {"word": "voice", "meaning": "voz", "note": ""}, {"word": "oak", "meaning": "carvalho", "note": ""}, {"word": "listen", "meaning": "escutar", "note": ""}, {"word": "blanket", "meaning": "cobertor", "note": ""}, {"word": "leaves", "meaning": "folhas", "note": ""}, {"word": "spring", "meaning": "primavera", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "am", "is"], "irregular": ["lived", "heard", "said", "looked", "answered", "told", "saw", "visited", "tired", "woke"], "phrasal": ["looked around", "woke up"], "wh": ["who"], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "village", "meaning": "aldeia", "note": ""}, {"word": "forest", "meaning": "floresta", "note": ""}, {"word": "voice", "meaning": "voz", "note": ""}, {"word": "oak", "meaning": "carvalho", "note": ""}, {"word": "listen", "meaning": "escutar", "note": ""}, {"word": "blanket", "meaning": "cobertor", "note": ""}, {"word": "leaves", "meaning": "folhas", "note": ""}, {"word": "spring", "meaning": "primavera", "note": ""}], "exercises": {"grammar": [{"point": "Can't / must", "explanation_pt": "'Trees can't talk' e 'I must sleep' expressam impossibilidade e necessidade."}, {"point": "Past simple", "explanation_pt": "'heard', 'told', 'visited' contam o que aconteceu."}], "multiple_choice": [{"question": "Where did Lucas live?", "options": ["Next to a forest", "By the sea", "On a mountain", "In a city"], "correct_index": 0, "explanation": "Ao lado de uma floresta."}, {"question": "Who spoke to him?", "options": ["An oak tree", "A bird", "A cat", "A boy"], "correct_index": 0, "explanation": "Um carvalho."}, {"question": "Who can hear the tree?", "options": ["People who listen", "Everybody", "Nobody", "Children only"], "correct_index": 0, "explanation": "Quem escuta."}, {"question": "Why must the tree sleep?", "options": ["It is bored", "It is angry", "Winter is coming", "It is sick"], "correct_index": 2, "explanation": "O inverno vem vindo."}, {"question": "What does Lucas do?", "options": ["Leaves", "Waters it", "Puts a blanket of leaves", "Cuts it"], "correct_index": 2, "explanation": "Cobre com folhas."}], "open_questions": [{"question": "Do you like forests?", "key_points_pt": ["opinar"]}, {"question": "If a tree could talk, what would it say?", "key_points_pt": ["imaginar"]}]}}, {"level": "B1", "genre": "fantasy", "title": "The Last Spell of Master Orin", "paragraphs": ["Master Orin had been the greatest wizard in the kingdom, but now he was old, and his magic was fading. His hands trembled when he held the staff, and the spells that once filled the sky with light now produced only a few sparks. His apprentice, Mina, watched with sadness.", "\"A wizard should know when to stop,\" Orin told her one evening. \"But I have one last spell, and I need your help.\" He explained that a dark mist had been creeping down from the northern mountains, killing the crops. Only a powerful spell could send it back.", "Together they climbed to the highest tower. Orin whispered the words, and Mina held his arm to keep him standing. The staff glowed brightly, and the mist slowly retreated, until the sky was clear.", "Orin collapsed from exhaustion but smiled. \"You see,\" he said, \"magic is not power. It is care.\" He gave Mina his staff. The next morning, the villagers found a young wizard in the old tower, and an old man sleeping peacefully beside her."], "paragraphs_pt": ["Mestre Orin fora o maior mago do reino, mas agora estava velho e sua magia desvanecia. Suas mãos tremiam ao segurar o cajado, e os feitiços que antes enchiam o céu de luz agora produziam apenas algumas faíscas. Sua aprendiz, Mina, observava com tristeza.", "\"Um mago deve saber quando parar\", Orin disse a ela numa noite. \"Mas tenho um último feitiço e preciso da sua ajuda.\" Explicou que uma névoa escura vinha descendo das montanhas do norte, matando as plantações. Só um feitiço poderoso podia fazê-la voltar.", "Juntos subiram à torre mais alta. Orin sussurrou as palavras e Mina segurou seu braço para mantê-lo de pé. O cajado brilhou intensamente e a névoa recuou devagar, até o céu ficar limpo.", "Orin desabou de exaustão, mas sorriu. \"Veja\", disse, \"magia não é poder. É cuidado.\" Entregou o cajado a Mina. Na manhã seguinte, os aldeões encontraram uma jovem maga na velha torre e um velho dormindo em paz ao lado dela."], "hard_words": ["fading", "apprentice", "mist", "exhaustion"], "vocab": [{"word": "wizard", "meaning": "mago", "note": ""}, {"word": "fading", "meaning": "desvanecendo", "note": ""}, {"word": "staff", "meaning": "cajado", "note": ""}, {"word": "spell", "meaning": "feitiço", "note": ""}, {"word": "apprentice", "meaning": "aprendiz", "note": ""}, {"word": "mist", "meaning": "névoa", "note": ""}, {"word": "crops", "meaning": "plantações", "note": ""}, {"word": "exhaustion", "meaning": "exaustão", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "is"], "irregular": ["had", "trembled", "held", "filled", "produced", "watched", "should", "told", "explained", "could", "climbed", "whispered", "glowed", "retreated", "collapsed", "smiled", "said", "gave", "found"], "phrasal": ["creeping down", "collapsed from"], "wh": ["when"], "connectors": ["and", "but", "when", "until", "once"], "comparative": []}, "word_meanings": [{"word": "wizard", "meaning": "mago", "note": ""}, {"word": "fading", "meaning": "desvanecendo", "note": ""}, {"word": "staff", "meaning": "cajado", "note": ""}, {"word": "spell", "meaning": "feitiço", "note": ""}, {"word": "apprentice", "meaning": "aprendiz", "note": ""}, {"word": "mist", "meaning": "névoa", "note": ""}, {"word": "crops", "meaning": "plantações", "note": ""}, {"word": "exhaustion", "meaning": "exaustão", "note": ""}], "exercises": {"grammar": [{"point": "Used to / once", "explanation_pt": "'spells that once filled the sky' fala de algo que não acontece mais."}, {"point": "Past perfect", "explanation_pt": "'Orin had been the greatest wizard' dá o contexto anterior."}], "multiple_choice": [{"question": "What was Orin's problem?", "options": ["He was young", "He was lost", "His magic was fading", "He was poor"], "correct_index": 2, "explanation": "A magia dele desvanecia."}, {"question": "What was killing the crops?", "options": ["A storm", "A drought", "Insects", "A dark mist"], "correct_index": 3, "explanation": "Uma névoa escura."}, {"question": "Where did they go?", "options": ["To the market", "To the highest tower", "To a cave", "To the sea"], "correct_index": 1, "explanation": "À torre mais alta."}, {"question": "What does Orin say magic is?", "options": ["Fear", "Care", "Money", "Power"], "correct_index": 1, "explanation": "Cuidado."}, {"question": "What does Orin give Mina?", "options": ["His hat", "His house", "His book", "His staff"], "correct_index": 3, "explanation": "O cajado."}], "open_questions": [{"question": "What does it mean to pass knowledge to someone?", "key_points_pt": ["explicar"]}, {"question": "How do we know when to step back?", "key_points_pt": ["discutir"]}]}}, {"level": "B1", "genre": "fantasy", "title": "The City Under the Lake", "paragraphs": ["Everyone in the village of Verrin knew the legend of the city under the lake, but nobody believed it. They said that on certain nights, when the moon was full, you could hear bells ringing from the water. Tara, a fisherman's daughter, had always heard the sound, but she thought it was the wind.", "One night she rowed out onto the lake alone. The bells were louder than ever, and the water began to glow. She leaned over the edge of her boat and saw towers, bridges and lanterns, all shining beneath her. A woman with silver hair looked up from below and waved.", "Tara hesitated, then jumped in. To her surprise, she could breathe. The people of the underwater city welcomed her warmly and told her that they had been waiting for someone brave enough to visit. They gave her a small pearl as a gift.", "In the morning, Tara woke up in her boat, completely dry. Nobody in the village believed her story. But she kept the pearl in her pocket, and on full-moon nights, when it glowed softly, she smiled and listened to the bells."], "paragraphs_pt": ["Todos na aldeia de Verrin conheciam a lenda da cidade debaixo do lago, mas ninguém acreditava. Diziam que, em certas noites de lua cheia, dava para ouvir sinos tocando na água. Tara, filha de um pescador, sempre ouvira o som, mas achava que era o vento.", "Uma noite remou sozinha pelo lago. Os sinos estavam mais altos que nunca e a água começou a brilhar. Debruçou-se na beira do barco e viu torres, pontes e lanternas, tudo brilhando sob ela. Uma mulher de cabelos prateados olhou para cima e acenou.", "Tara hesitou e então pulou. Para sua surpresa, conseguia respirar. Os habitantes da cidade submersa a receberam calorosamente e disseram que esperavam alguém corajoso o bastante para visitá-los. Deram-lhe uma pequena pérola de presente.", "De manhã, Tara acordou no barco, totalmente seca. Ninguém na aldeia acreditou na história. Mas ela guardou a pérola no bolso e, nas noites de lua cheia, quando brilhava suavemente, sorria e escutava os sinos."], "hard_words": ["legend", "bells", "hesitated", "pearl"], "vocab": [{"word": "legend", "meaning": "lenda", "note": ""}, {"word": "bells", "meaning": "sinos", "note": ""}, {"word": "fisherman", "meaning": "pescador", "note": ""}, {"word": "rowed", "meaning": "remou", "note": ""}, {"word": "lanterns", "meaning": "lanternas", "note": ""}, {"word": "hesitated", "meaning": "hesitou", "note": ""}, {"word": "pearl", "meaning": "pérola", "note": ""}, {"word": "underwater", "meaning": "submerso", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been"], "irregular": ["knew", "believed", "said", "could", "had", "heard", "thought", "rowed", "began", "leaned", "saw", "looked", "waved", "hesitated", "jumped", "welcomed", "told", "gave", "woke", "kept", "glowed", "smiled", "listened"], "phrasal": ["leaned over", "woke up"], "wh": ["when"], "connectors": ["and", "but", "then", "when", "as"], "comparative": []}, "word_meanings": [{"word": "legend", "meaning": "lenda", "note": ""}, {"word": "bells", "meaning": "sinos", "note": ""}, {"word": "fisherman", "meaning": "pescador", "note": ""}, {"word": "rowed", "meaning": "remou", "note": ""}, {"word": "lanterns", "meaning": "lanternas", "note": ""}, {"word": "hesitated", "meaning": "hesitou", "note": ""}, {"word": "pearl", "meaning": "pérola", "note": ""}, {"word": "underwater", "meaning": "submerso", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'The people had been waiting' mostra espera anterior à visita."}, {"point": "Could", "explanation_pt": "'you could hear bells' fala de possibilidade no passado."}], "multiple_choice": [{"question": "What was the legend about?", "options": ["A treasure", "A dragon", "A king", "A city under the lake"], "correct_index": 3, "explanation": "Uma cidade debaixo do lago."}, {"question": "When could people hear the bells?", "options": ["On full-moon nights", "At noon", "Every morning", "In winter only"], "correct_index": 0, "explanation": "Em noites de lua cheia."}, {"question": "What did Tara see below?", "options": ["Nothing", "Towers, bridges and lanterns", "Fish only", "A ship"], "correct_index": 1, "explanation": "Torres, pontes e lanternas."}, {"question": "What gift did she receive?", "options": ["A book", "A pearl", "A coin", "A ring"], "correct_index": 1, "explanation": "Uma pérola."}, {"question": "What happened in the morning?", "options": ["She was lost", "She woke up in her dry boat", "She was sick", "She was in town"], "correct_index": 1, "explanation": "Acordou no barco seca."}], "open_questions": [{"question": "Do you believe in legends?", "key_points_pt": ["opinar"]}, {"question": "What local legend do you know?", "key_points_pt": ["contar"]}]}}, {"level": "B2", "genre": "fantasy", "title": "The Cartographer of Dreams", "paragraphs": ["In the town of Hollowmere, people did not draw maps of places but of dreams. Ilan, the town's cartographer, had spent decades charting the shifting landscapes that visited the sleeping: floating staircases, rivers that flowed upward, doors that opened onto the sea. His maps were consulted by those who woke troubled, wanting to understand where their sleeping minds had wandered.", "One winter, he began receiving the same dream from dozens of clients: a vast tower of black glass, surrounded by a silence that made them wake up trembling. Intrigued, Ilan compared the maps and realised that the tower was appearing in the same position in every dream, as though a real place were pressing itself into sleep.", "Taking his instruments, he decided to enter the dream deliberately. He lay down, drank a calming tea, and followed the shared route marked on his charts. The tower rose before him, enormous and cold. At its base he found a door with a name carved above it: his own.", "Ilan understood that the tower was not a threat but a warning. It represented the work he had left unfinished: a map of his own dreams, which he had never dared to draw. He woke at dawn, sat at his desk and began. The townspeople's nightmares gradually disappeared, though Ilan never finished the map, preferring to leave one door unopened."], "paragraphs_pt": ["Na cidade de Hollowmere, as pessoas não desenhavam mapas de lugares, mas de sonhos. Ilan, o cartógrafo da cidade, passara décadas mapeando as paisagens mutantes que visitavam os adormecidos: escadas flutuantes, rios que fluíam para cima, portas que se abriam para o mar. Seus mapas eram consultados por quem acordava perturbado, querendo entender por onde sua mente adormecida vagara.", "Num inverno, começou a receber o mesmo sonho de dezenas de clientes: uma vasta torre de vidro negro, cercada por um silêncio que os fazia acordar tremendo. Intrigado, Ilan comparou os mapas e percebeu que a torre aparecia na mesma posição em todos os sonhos, como se um lugar real estivesse se impondo ao sono.", "Pegando os instrumentos, decidiu entrar no sonho deliberadamente. Deitou-se, bebeu um chá calmante e seguiu a rota compartilhada marcada em suas cartas. A torre ergueu-se diante dele, enorme e fria. Na base achou uma porta com um nome gravado acima: o seu.", "Ilan entendeu que a torre não era uma ameaça, mas um aviso. Representava o trabalho que deixara inacabado: um mapa dos próprios sonhos, que nunca ousara desenhar. Acordou ao amanhecer, sentou-se à escrivaninha e começou. Os pesadelos dos habitantes desapareceram aos poucos, embora Ilan nunca terminasse o mapa, preferindo deixar uma porta fechada."], "hard_words": ["charting", "shifting", "intrigued", "unfinished"], "vocab": [{"word": "cartographer", "meaning": "cartógrafo", "note": ""}, {"word": "charting", "meaning": "mapeando", "note": ""}, {"word": "shifting", "meaning": "mutantes", "note": ""}, {"word": "consulted", "meaning": "consultados", "note": ""}, {"word": "intrigued", "meaning": "intrigado", "note": ""}, {"word": "instruments", "meaning": "instrumentos", "note": ""}, {"word": "carved", "meaning": "gravado", "note": ""}, {"word": "unfinished", "meaning": "inacabado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was"], "irregular": ["did", "had", "spent", "visited", "flowed", "opened", "consulted", "woke", "troubled", "wandered", "began", "surrounded", "made", "intrigued", "compared", "realised", "decided", "lay", "drank", "followed", "shared", "marked", "rose", "found", "carved", "understood", "represented", "left", "dared", "sat", "disappeared", "finished"], "phrasal": ["lay down", "sat at"], "wh": ["who", "where", "which"], "connectors": ["and", "but", "though", "before", "as"], "comparative": []}, "word_meanings": [{"word": "cartographer", "meaning": "cartógrafo", "note": ""}, {"word": "charting", "meaning": "mapeando", "note": ""}, {"word": "shifting", "meaning": "mutantes", "note": ""}, {"word": "consulted", "meaning": "consultados", "note": ""}, {"word": "intrigued", "meaning": "intrigado", "note": ""}, {"word": "instruments", "meaning": "instrumentos", "note": ""}, {"word": "carved", "meaning": "gravado", "note": ""}, {"word": "unfinished", "meaning": "inacabado", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had spent decades charting' mostra um período anterior."}, {"point": "Not... but", "explanation_pt": "'not a threat but a warning' contrasta duas interpretações."}], "multiple_choice": [{"question": "What did Ilan map?", "options": ["Stars", "Cities", "Dreams", "Seas"], "correct_index": 2, "explanation": "Sonhos."}, {"question": "What did dozens of clients dream of?", "options": ["A river", "A black glass tower", "A ship", "A forest"], "correct_index": 1, "explanation": "Uma torre de vidro negro."}, {"question": "How did Ilan enter the dream?", "options": ["By a spell", "By accident", "With a friend", "Deliberately, after drinking tea"], "correct_index": 3, "explanation": "Deliberadamente, após um chá."}, {"question": "Whose name was on the door?", "options": ["A king's", "His wife's", "His own", "A stranger's"], "correct_index": 2, "explanation": "O dele."}, {"question": "What did the tower represent?", "options": ["A threat", "A death", "Work he had left unfinished", "A treasure"], "correct_index": 2, "explanation": "Trabalho inacabado."}], "open_questions": [{"question": "Why do we avoid things we most need to do?", "key_points_pt": ["discutir"]}, {"question": "What would a map of your dreams look like?", "key_points_pt": ["imaginar"]}]}}, {"level": "C1", "genre": "fantasy", "title": "The Inheritance of Salt", "paragraphs": ["When Aurelia inherited her grandmother's house on the cliff, she found among the furniture a jar of grey salt, labelled in a faded hand: \"Do not use.\" Naturally, she was tempted. She waited until a stormy night, when the windows rattled and the sea bellowed against the rocks, and sprinkled a pinch over her tongue.", "The effect was not dramatic, but it was unmistakable. She heard, beneath the wind, the voices of the sea: not words, exactly, but intentions, grudges and affections, as though the water were a vast, quarrelsome family. She understood that her grandmother had been the village's silent interpreter, the one person able to mediate between fishermen and tide.", "In the morning, the villagers arrived with offerings and anxieties. Fishing had been poor for months; the sea, they believed, was angry. Aurelia listened for hours, and then told them something unexpected. The sea was not angry; it was lonely, because for years nobody had spoken to it.", "She taught the village a simple custom: every evening, someone would stand on the pier and say a few honest words to the water. Fishing improved within a season, which the sceptics attributed to coincidence. Aurelia, however, knew that she had inherited not a magic but a responsibility, and that the salt had been a test of curiosity rather than a gift."], "paragraphs_pt": ["Quando Aurelia herdou a casa da avó na falésia, encontrou entre os móveis um pote de sal cinza, rotulado com letra desbotada: \"Não use.\" Naturalmente, ficou tentada. Esperou uma noite de tempestade, quando as janelas tremiam e o mar bramia contra as rochas, e polvilhou uma pitada na língua.", "O efeito não foi dramático, mas foi inequívoco. Ouviu, sob o vento, as vozes do mar: não palavras, exatamente, mas intenções, rancores e afetos, como se a água fosse uma vasta família briguenta. Entendeu que a avó fora a intérprete silenciosa da aldeia, a única capaz de mediar entre pescadores e maré.", "De manhã, os aldeões chegaram com oferendas e angústias. A pesca estava fraca havia meses; o mar, acreditavam, estava zangado. Aurelia ouviu por horas e depois lhes disse algo inesperado. O mar não estava zangado; estava solitário, porque por anos ninguém falara com ele.", "Ensinou à aldeia um costume simples: toda tarde, alguém ficaria no cais e diria algumas palavras honestas à água. A pesca melhorou em uma estação, o que os céticos atribuíram à coincidência. Aurelia, porém, sabia que herdara não uma mágica, mas uma responsabilidade, e que o sal fora um teste de curiosidade, não um presente."], "hard_words": ["bellowed", "grudges", "mediate", "sceptics"], "vocab": [{"word": "inherited", "meaning": "herdou", "note": ""}, {"word": "faded", "meaning": "desbotada", "note": ""}, {"word": "bellowed", "meaning": "bramiu", "note": ""}, {"word": "grudges", "meaning": "rancores", "note": ""}, {"word": "quarrelsome", "meaning": "briguenta", "note": ""}, {"word": "mediate", "meaning": "mediar", "note": ""}, {"word": "offerings", "meaning": "oferendas", "note": ""}, {"word": "sceptics", "meaning": "céticos", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been"], "irregular": ["inherited", "found", "labelled", "faded", "tempted", "waited", "rattled", "bellowed", "sprinkled", "heard", "understood", "had", "arrived", "believed", "listened", "told", "spoken", "taught", "would", "improved", "attributed", "knew"], "phrasal": ["attributed to"], "wh": ["when", "which"], "connectors": ["and", "but", "however", "because", "though", "then", "when", "until", "as"], "comparative": []}, "word_meanings": [{"word": "inherited", "meaning": "herdou", "note": ""}, {"word": "faded", "meaning": "desbotada", "note": ""}, {"word": "bellowed", "meaning": "bramiu", "note": ""}, {"word": "grudges", "meaning": "rancores", "note": ""}, {"word": "quarrelsome", "meaning": "briguenta", "note": ""}, {"word": "mediate", "meaning": "mediar", "note": ""}, {"word": "offerings", "meaning": "oferendas", "note": ""}, {"word": "sceptics", "meaning": "céticos", "note": ""}], "exercises": {"grammar": [{"point": "Not... exactly", "explanation_pt": "'not words, exactly, but intentions' corrige uma descrição."}, {"point": "Rather than", "explanation_pt": "'a test of curiosity rather than a gift' compara duas ideias."}], "multiple_choice": [{"question": "What did Aurelia find?", "options": ["A book", "A map", "A jar of grey salt", "A key"], "correct_index": 2, "explanation": "Um pote de sal cinza."}, {"question": "What did the label say?", "options": ["For tea", "Open at dawn", "Use daily", "Do not use"], "correct_index": 3, "explanation": "'Não use.'"}, {"question": "What did she hear?", "options": ["Music", "Birds", "The voices of the sea", "Her grandmother"], "correct_index": 2, "explanation": "As vozes do mar."}, {"question": "What did she say about the sea?", "options": ["It was lonely", "It was tired", "It was hungry", "It was angry"], "correct_index": 0, "explanation": "Estava solitário."}, {"question": "What custom did she teach?", "options": ["Speaking honestly to the water", "Fishing at night", "Closing the pier", "Singing"], "correct_index": 0, "explanation": "Falar honestamente com a água."}], "open_questions": [{"question": "What do inheritances carry besides objects?", "key_points_pt": ["refletir"]}, {"question": "Why do communities create rituals?", "key_points_pt": ["discutir"]}]}}, {"level": "C1", "genre": "fantasy", "title": "The King Who Forgot His Name", "paragraphs": ["A curse fell upon King Lorcan not in the manner of storybooks, with thunder and fire, but with the gentle erasure of a tide smoothing a footprint. At first he forgot minor things: the name of a cousin, the date of a feast. Within a year, he could not recall the faces of his ministers. By the third winter, he had forgotten his own name.", "The court, terrified of anarchy, concealed the loss. The king was told daily that he was Lorcan, that he ruled wisely, that the kingdom was prosperous. He accepted these assurances with the graciousness of a man reading a biography of a stranger. Curiously, he governed better than before; unburdened by pride and precedent, he asked questions that nobody dared pose.", "Then a travelling healer, sceptical of the court's flattery, spoke to him alone. \"Do you wish your name back?\" The king pondered the question for a long time. \"I think,\" he said, \"I would like to deserve it.\" The healer smiled. The curse, she explained, could not be lifted by magic, only by deeds.", "Over the following years, the king did precisely that. When at last his memory returned, he found that the name was no longer a heavy crown but an invitation, something to live up to rather than to defend. He ruled quietly until the end, and his chroniclers recorded that he was the only king who had to earn his own name."], "paragraphs_pt": ["Uma maldição caiu sobre o rei Lorcan não à maneira dos contos, com trovões e fogo, mas com o apagamento suave de uma maré suavizando uma pegada. A princípio esqueceu coisas pequenas: o nome de um primo, a data de uma festa. Em um ano, não lembrava os rostos dos ministros. No terceiro inverno, esquecera o próprio nome.", "A corte, aterrorizada com a anarquia, ocultou a perda. Diziam ao rei diariamente que ele era Lorcan, que governava com sabedoria, que o reino era próspero. Ele aceitava essas garantias com a gentileza de quem lê a biografia de um estranho. Curiosamente, governava melhor que antes; livre de orgulho e precedentes, fazia perguntas que ninguém ousava fazer.", "Então uma curandeira viajante, cética diante da bajulação da corte, falou com ele a sós. \"Deseja seu nome de volta?\" O rei ponderou a pergunta por muito tempo. \"Acho\", disse, \"que gostaria de merecê-lo.\" A curandeira sorriu. A maldição, explicou, não podia ser levantada por magia, apenas por atos.", "Nos anos seguintes, o rei fez exatamente isso. Quando por fim a memória voltou, descobriu que o nome já não era uma coroa pesada, mas um convite, algo a que corresponder em vez de defender. Reinou em silêncio até o fim, e seus cronistas registraram que foi o único rei que teve de merecer o próprio nome."], "hard_words": ["concealed", "precedent", "flattery", "pondered"], "vocab": [{"word": "erasure", "meaning": "apagamento", "note": ""}, {"word": "anarchy", "meaning": "anarquia", "note": ""}, {"word": "concealed", "meaning": "ocultou", "note": ""}, {"word": "graciousness", "meaning": "gentileza, graça", "note": ""}, {"word": "precedent", "meaning": "precedente", "note": ""}, {"word": "flattery", "meaning": "bajulação", "note": ""}, {"word": "pondered", "meaning": "ponderou", "note": ""}, {"word": "chroniclers", "meaning": "cronistas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be"], "irregular": ["fell", "forgot", "could", "had", "forgotten", "terrified", "concealed", "told", "ruled", "accepted", "governed", "unburdened", "asked", "dared", "spoke", "pondered", "said", "would", "smiled", "explained", "lifted", "did", "returned", "found", "recorded"], "phrasal": ["live up to", "fell upon"], "wh": ["who", "when"], "connectors": ["and", "but", "then", "before", "when", "until"], "comparative": []}, "word_meanings": [{"word": "erasure", "meaning": "apagamento", "note": ""}, {"word": "anarchy", "meaning": "anarquia", "note": ""}, {"word": "concealed", "meaning": "ocultou", "note": ""}, {"word": "graciousness", "meaning": "gentileza, graça", "note": ""}, {"word": "precedent", "meaning": "precedente", "note": ""}, {"word": "flattery", "meaning": "bajulação", "note": ""}, {"word": "pondered", "meaning": "ponderou", "note": ""}, {"word": "chroniclers", "meaning": "cronistas", "note": ""}], "exercises": {"grammar": [{"point": "Not... but", "explanation_pt": "'not in the manner of storybooks... but with the gentle erasure of a tide' contrasta duas formas."}, {"point": "Only by", "explanation_pt": "'could not be lifted by magic, only by deeds' limita o modo."}], "multiple_choice": [{"question": "How did the curse work?", "options": ["It made him old", "It erased his memory", "It hurt him", "It killed his friends"], "correct_index": 1, "explanation": "Apagou a memória."}, {"question": "What did the court do?", "options": ["Declared war", "Concealed the loss", "Left", "Fired the king"], "correct_index": 1, "explanation": "Ocultou a perda."}, {"question": "Why did he govern better?", "options": ["He was lucky", "He had help", "He was young", "He was free of pride"], "correct_index": 3, "explanation": "Livre de orgulho e precedentes."}, {"question": "What did the healer say about the curse?", "options": ["It was a lie", "Only deeds could lift it", "Magic could lift it", "It was permanent"], "correct_index": 1, "explanation": "Só atos levantavam."}, {"question": "How did the king see his name?", "options": ["An invitation to live up to", "A weapon", "A secret", "A heavy crown"], "correct_index": 0, "explanation": "Um convite."}], "open_questions": [{"question": "Do we earn our names or inherit them?", "key_points_pt": ["debater"]}, {"question": "How might forgetting free a person?", "key_points_pt": ["refletir"]}]}}, {"level": "C2", "genre": "fantasy", "title": "The Lantern of Unfinished Things", "paragraphs": ["In the lowest chamber of the Archive of Sorrows hung a lantern that burned with a cold, steady flame. Its function, so the librarians whispered, was to illuminate not what existed but what might have existed: the symphonies never composed, the letters never sent, the cities that died as sketches in a mapmaker's mind. Visitors were forbidden to approach, for the lantern had a way of making the possible unbearably vivid.", "Seren, the youngest custodian, was assigned to trim its wick, and she performed the duty with the dread of someone handling a sleeping animal. One midnight, curiosity overcame prudence and she looked into the flame. She saw a girl at a piano, in a house she had never lived in, playing a piece she had never heard. It was herself, had she not given up music at fourteen.", "The vision was not cruel; it was merely accurate. And yet Seren found that its accuracy contained a strange mercy. She understood that every abandoned path persisted somewhere, not as accusation but as testimony that she had been capable of more than one life. She wept for an hour and then, ashamed of nothing, went to find a piano.", "The lantern, it is said, was never meant to haunt. Its makers had hoped that those who saw what they might have been would not despair but begin, belatedly and imperfectly, to become it. The archive's records show that after Seren's visit, three other custodians resigned to pursue forgotten ambitions, and that the lantern burned slightly brighter."], "paragraphs_pt": ["Na câmara mais baixa do Arquivo das Tristezas pendia uma lanterna que ardia com uma chama fria e constante. Sua função, segundo sussurravam os bibliotecários, era iluminar não o que existia, mas o que poderia ter existido: as sinfonias jamais compostas, as cartas jamais enviadas, as cidades que morreram como esboços na mente de um cartógrafo. Era proibido aos visitantes se aproximarem, pois a lanterna tinha o poder de tornar o possível insuportavelmente vívido.", "Seren, a zeladora mais jovem, foi designada para aparar seu pavio, e cumpria o dever com o temor de quem manuseia um animal adormecido. À meia-noite, a curiosidade venceu a prudência e ela olhou na chama. Viu uma menina ao piano, numa casa onde jamais vivera, tocando uma peça que jamais ouvira. Era ela mesma, caso não tivesse abandonado a música aos catorze anos.", "A visão não era cruel; era apenas exata. E, no entanto, Seren descobriu que essa exatidão continha uma estranha misericórdia. Entendeu que cada caminho abandonado persistia em algum lugar, não como acusação, mas como testemunho de que fora capaz de mais de uma vida. Chorou por uma hora e então, sem se envergonhar de nada, foi procurar um piano.", "A lanterna, diz-se, nunca foi feita para assombrar. Seus criadores esperavam que quem visse o que poderia ter sido não desesperasse, mas começasse, tardia e imperfeitamente, a tornar-se isso. Os registros do arquivo mostram que, após a visita de Seren, três outros zeladores se demitiram para perseguir ambições esquecidas, e que a lanterna ardeu um pouco mais forte."], "hard_words": ["unbearably", "prudence", "mercy", "belatedly"], "vocab": [{"word": "illuminate", "meaning": "iluminar", "note": ""}, {"word": "unbearably", "meaning": "insuportavelmente", "note": ""}, {"word": "custodian", "meaning": "zelador(a)", "note": ""}, {"word": "wick", "meaning": "pavio", "note": ""}, {"word": "prudence", "meaning": "prudência", "note": ""}, {"word": "mercy", "meaning": "misericórdia", "note": ""}, {"word": "testimony", "meaning": "testemunho", "note": ""}, {"word": "belatedly", "meaning": "tardiamente", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been", "is"], "irregular": ["hung", "burned", "whispered", "existed", "might", "composed", "sent", "died", "forbidden", "had", "assigned", "performed", "overcame", "looked", "saw", "lived", "heard", "given", "found", "contained", "understood", "abandoned", "persisted", "wept", "went", "said", "meant", "hoped", "would", "resigned", "forgotten"], "phrasal": ["resigned to"], "wh": ["who", "what"], "connectors": ["and", "but", "so", "then", "after", "yet", "as"], "comparative": []}, "word_meanings": [{"word": "illuminate", "meaning": "iluminar", "note": ""}, {"word": "unbearably", "meaning": "insuportavelmente", "note": ""}, {"word": "custodian", "meaning": "zelador(a)", "note": ""}, {"word": "wick", "meaning": "pavio", "note": ""}, {"word": "prudence", "meaning": "prudência", "note": ""}, {"word": "mercy", "meaning": "misericórdia", "note": ""}, {"word": "testimony", "meaning": "testemunho", "note": ""}, {"word": "belatedly", "meaning": "tardiamente", "note": ""}], "exercises": {"grammar": [{"point": "Inversão condicional", "explanation_pt": "'had she not given up music' equivale a 'if she had not given up'."}, {"point": "Not... but", "explanation_pt": "'not as accusation but as testimony' contrasta duas leituras."}], "multiple_choice": [{"question": "What does the lantern illuminate?", "options": ["What might have existed", "The past", "The weather", "What exists"], "correct_index": 0, "explanation": "O que poderia ter existido."}, {"question": "Why was approaching it forbidden?", "options": ["It was hot", "It was broken", "It made possibilities unbearably vivid", "It was cursed"], "correct_index": 2, "explanation": "Tornava o possível vívido demais."}, {"question": "What did Seren see?", "options": ["Herself playing the piano", "A stranger", "A monster", "The future"], "correct_index": 0, "explanation": "Ela mesma ao piano."}, {"question": "How did she feel afterwards?", "options": ["Bored", "Afraid", "Angry", "She wept, then felt resolved"], "correct_index": 3, "explanation": "Chorou, depois decidida."}, {"question": "What did the lantern's makers hope?", "options": ["People would begin to become what they might have been", "People would forget", "People would leave", "People would despair"], "correct_index": 0, "explanation": "Que começassem a tornar-se."}], "open_questions": [{"question": "Do abandoned paths still matter?", "key_points_pt": ["refletir"]}, {"question": "How can we revisit an old dream?", "key_points_pt": ["discutir"]}]}}, {"level": "A1", "genre": "humor", "title": "The Hungry Cat", "paragraphs": ["Milo has a cat. The cat is very big and very hungry. \"Meow!\" says the cat. Milo gives him food.", "The cat eats the food in one minute. \"Meow!\" he says again. Milo gives him more food. The cat eats it.", "Milo laughs. \"You are not a cat. You are a small lion!\" The cat looks at him and says, \"Meow!\" He wants more."], "paragraphs_pt": ["Milo tem um gato. O gato é muito grande e muito faminto. \"Miau!\", diz o gato. Milo dá comida a ele.", "O gato come a comida em um minuto. \"Miau!\", diz de novo. Milo dá mais comida. O gato come.", "Milo ri. \"Você não é um gato. É um pequeno leão!\" O gato olha para ele e diz: \"Miau!\" Ele quer mais."], "hard_words": ["hungry", "minute", "lion", "more"], "vocab": [{"word": "cat", "meaning": "gato", "note": ""}, {"word": "big", "meaning": "grande", "note": ""}, {"word": "hungry", "meaning": "faminto", "note": ""}, {"word": "food", "meaning": "comida", "note": ""}, {"word": "minute", "meaning": "minuto", "note": ""}, {"word": "lion", "meaning": "leão", "note": ""}, {"word": "more", "meaning": "mais", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "cat", "meaning": "gato", "note": ""}, {"word": "big", "meaning": "grande", "note": ""}, {"word": "hungry", "meaning": "faminto", "note": ""}, {"word": "food", "meaning": "comida", "note": ""}, {"word": "minute", "meaning": "minuto", "note": ""}, {"word": "lion", "meaning": "leão", "note": ""}, {"word": "more", "meaning": "mais", "note": ""}], "exercises": {"grammar": [{"point": "Very", "explanation_pt": "'very big' e 'very hungry' reforçam o adjetivo."}], "multiple_choice": [{"question": "What does Milo have?", "options": ["A fish", "A cat", "A dog", "A bird"], "correct_index": 1, "explanation": "Um gato."}, {"question": "How is the cat?", "options": ["Old and sad", "Big and hungry", "Small and sleepy", "Thin and quiet"], "correct_index": 1, "explanation": "Grande e faminto."}, {"question": "How fast does the cat eat?", "options": ["In one day", "In one hour", "In one minute", "Never"], "correct_index": 2, "explanation": "Em um minuto."}, {"question": "What does Milo say the cat is?", "options": ["A big dog", "A bird", "A small lion", "A tiger"], "correct_index": 2, "explanation": "Um pequeno leão."}, {"question": "What does the cat want?", "options": ["A bed", "A friend", "A toy", "More food"], "correct_index": 3, "explanation": "Quer mais comida."}], "open_questions": [{"question": "Do you have a pet?", "key_points_pt": ["falar"]}, {"question": "What does your pet eat?", "key_points_pt": ["descrever"]}]}}, {"level": "A1", "genre": "humor", "title": "The Wrong Shoes", "paragraphs": ["Tom wakes up late. He quickly puts on his shoes and runs to school. People look at him and laugh.", "\"Why are you laughing?\" asks Tom. \"Look at your shoes!\" says a girl. Tom looks down. One shoe is red. The other shoe is blue!", "Tom is red like his shoe. But then he laughs too. \"It is a new fashion!\" he says. The next day, five children wear one red and one blue shoe."], "paragraphs_pt": ["Tom acorda tarde. Rapidamente calça os sapatos e corre para a escola. As pessoas olham para ele e riem.", "\"Por que estão rindo?\", pergunta Tom. \"Olhe seus sapatos!\", diz uma menina. Tom olha para baixo. Um sapato é vermelho. O outro sapato é azul!", "Tom fica vermelho como o sapato. Mas então ele também ri. \"É uma nova moda!\", diz. No dia seguinte, cinco crianças usam um sapato vermelho e um azul."], "hard_words": ["late", "shoes", "laugh", "fashion"], "vocab": [{"word": "wakes up", "meaning": "acorda", "note": ""}, {"word": "late", "meaning": "tarde", "note": ""}, {"word": "fashion", "meaning": "moda", "note": ""}, {"word": "shoes", "meaning": "sapatos", "note": ""}, {"word": "school", "meaning": "escola", "note": ""}, {"word": "laugh", "meaning": "rir", "note": ""}, {"word": "red", "meaning": "vermelho", "note": ""}, {"word": "blue", "meaning": "azul", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "is"], "irregular": [], "phrasal": [], "wh": ["why"], "connectors": ["and", "but", "then"], "comparative": []}, "word_meanings": [{"word": "wakes up", "meaning": "acorda", "note": ""}, {"word": "late", "meaning": "tarde", "note": ""}, {"word": "fashion", "meaning": "moda", "note": ""}, {"word": "shoes", "meaning": "sapatos", "note": ""}, {"word": "school", "meaning": "escola", "note": ""}, {"word": "laugh", "meaning": "rir", "note": ""}, {"word": "red", "meaning": "vermelho", "note": ""}, {"word": "blue", "meaning": "azul", "note": ""}], "exercises": {"grammar": [{"point": "Imperativo", "explanation_pt": "'Look at your shoes!' dá uma ordem ou chama a atenção."}], "multiple_choice": [{"question": "When does Tom wake up?", "options": ["At night", "Late", "Never", "Early"], "correct_index": 1, "explanation": "Acorda tarde."}, {"question": "What do people do?", "options": ["Run", "Sing", "Laugh", "Cry"], "correct_index": 2, "explanation": "Riem."}, {"question": "What color are his shoes?", "options": ["One red and one blue", "Both blue", "Both red", "Black"], "correct_index": 0, "explanation": "Um vermelho e um azul."}, {"question": "What does Tom say?", "options": ["I am sick", "I am sorry", "I am sad", "It is a new fashion"], "correct_index": 3, "explanation": "É uma nova moda."}, {"question": "What happens the next day?", "options": ["Five children copy him", "Nothing", "Tom is sad", "School closes"], "correct_index": 0, "explanation": "Cinco crianças copiam."}], "open_questions": [{"question": "Have you ever worn something strange?", "key_points_pt": ["contar"]}, {"question": "What color is your favorite shirt?", "key_points_pt": ["descrever"]}]}}, {"level": "A2", "genre": "humor", "title": "The Worst Cook in Town", "paragraphs": ["Greta wanted to cook dinner for her friends. She looked for a recipe online and chose a simple one: spaghetti with tomato sauce. How difficult could it be?", "First, she put the spaghetti in cold water. Then she forgot about it and started to watch a video. When she came back, the spaghetti was a big sticky ball. She tried to cut it with scissors, and the kitchen looked like a battlefield.", "Her friends arrived and smelled something strange. Greta smiled nervously. \"I made art,\" she said. They all ordered pizza, and Greta laughed with them. She decided that her best recipe was a phone number for the pizza shop."], "paragraphs_pt": ["Greta queria cozinhar o jantar para os amigos. Procurou uma receita na internet e escolheu uma simples: espaguete com molho de tomate. Quão difícil poderia ser?", "Primeiro, pôs o espaguete em água fria. Depois esqueceu e começou a assistir a um vídeo. Quando voltou, o espaguete era uma grande bola grudenta. Tentou cortá-lo com tesoura, e a cozinha parecia um campo de batalha.", "Os amigos chegaram e sentiram um cheiro estranho. Greta sorriu nervosa. \"Eu fiz arte\", disse. Todos pediram pizza, e Greta riu com eles. Decidiu que sua melhor receita era o telefone da pizzaria."], "hard_words": ["recipe", "sticky", "scissors", "nervously"], "vocab": [{"word": "recipe", "meaning": "receita", "note": ""}, {"word": "spaghetti", "meaning": "espaguete", "note": ""}, {"word": "sticky", "meaning": "grudento", "note": ""}, {"word": "scissors", "meaning": "tesoura", "note": ""}, {"word": "battlefield", "meaning": "campo de batalha", "note": ""}, {"word": "nervously", "meaning": "nervosa", "note": ""}, {"word": "art", "meaning": "arte", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "was"], "irregular": ["wanted", "looked", "chose", "could", "forgot", "started", "came", "tried", "arrived", "smelled", "smiled", "made", "said", "ordered", "laughed", "decided"], "phrasal": ["looked for", "came back"], "wh": ["when", "how"], "connectors": ["and", "then", "when"], "comparative": []}, "word_meanings": [{"word": "recipe", "meaning": "receita", "note": ""}, {"word": "spaghetti", "meaning": "espaguete", "note": ""}, {"word": "sticky", "meaning": "grudento", "note": ""}, {"word": "scissors", "meaning": "tesoura", "note": ""}, {"word": "battlefield", "meaning": "campo de batalha", "note": ""}, {"word": "nervously", "meaning": "nervosa", "note": ""}, {"word": "art", "meaning": "arte", "note": ""}], "exercises": {"grammar": [{"point": "How + adjetivo", "explanation_pt": "'How difficult could it be?' é uma pergunta retórica."}, {"point": "Past simple", "explanation_pt": "'forgot', 'came', 'smiled' contam a sequência."}], "multiple_choice": [{"question": "What did Greta want to cook?", "options": ["Cake", "Spaghetti with sauce", "Soup", "Pizza"], "correct_index": 1, "explanation": "Espaguete com molho."}, {"question": "What did she do wrong?", "options": ["Burn the sauce", "Use no pot", "Forget the salt", "Put spaghetti in cold water"], "correct_index": 3, "explanation": "Pôs em água fria."}, {"question": "What did the spaghetti become?", "options": ["A cake", "A soup", "Nothing", "A sticky ball"], "correct_index": 3, "explanation": "Uma bola grudenta."}, {"question": "What did friends do?", "options": ["Left", "Cooked", "Cried", "Ordered pizza"], "correct_index": 3, "explanation": "Pediram pizza."}, {"question": "What was her best recipe?", "options": ["Pasta", "Salad", "The pizza shop's phone number", "Soup"], "correct_index": 2, "explanation": "O telefone da pizzaria."}], "open_questions": [{"question": "Can you cook? What can you make?", "key_points_pt": ["falar"]}, {"question": "What is your worst kitchen story?", "key_points_pt": ["contar"]}]}}, {"level": "A2", "genre": "humor", "title": "The Talking Parrot", "paragraphs": ["Mr. Gomez had a parrot called Pepe. Pepe could say many words, and he repeated everything he heard. Mr. Gomez was very proud of him. One day, his boss came to dinner.", "During dinner, the telephone rang. Mr. Gomez answered it and said, \"Not again! Mr. Silva is boring, and I hate his calls.\" He hung up and smiled at his boss. \"Sorry about that.\" Everything was fine.", "The next morning, the boss visited again. Pepe looked at him and shouted, \"Mr. Silva is boring! I hate his calls!\" The boss was Mr. Silva. Mr. Gomez wanted to disappear. Since that day, Pepe has lived in the bathroom, where nobody can hear him."], "paragraphs_pt": ["O Sr. Gomez tinha um papagaio chamado Pepe. Pepe sabia dizer muitas palavras e repetia tudo o que ouvia. O Sr. Gomez tinha muito orgulho dele. Um dia, o chefe veio jantar.", "Durante o jantar, o telefone tocou. O Sr. Gomez atendeu e disse: \"De novo! O Sr. Silva é chato e eu odeio as ligações dele.\" Desligou e sorriu para o chefe. \"Desculpe por isso.\" Estava tudo bem.", "Na manhã seguinte, o chefe visitou de novo. Pepe olhou para ele e gritou: \"O Sr. Silva é chato! Eu odeio as ligações dele!\" O chefe era o Sr. Silva. O Sr. Gomez queria desaparecer. Desde esse dia, Pepe mora no banheiro, onde ninguém o ouve."], "hard_words": ["parrot", "repeated", "boss", "boring"], "vocab": [{"word": "parrot", "meaning": "papagaio", "note": ""}, {"word": "repeated", "meaning": "repetia", "note": ""}, {"word": "proud", "meaning": "orgulhoso", "note": ""}, {"word": "boss", "meaning": "chefe", "note": ""}, {"word": "boring", "meaning": "chato", "note": ""}, {"word": "hung up", "meaning": "desligou", "note": ""}, {"word": "bathroom", "meaning": "banheiro", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is"], "irregular": ["had", "called", "could", "repeated", "heard", "came", "rang", "answered", "said", "hung", "smiled", "visited", "looked", "shouted", "wanted", "lived"], "phrasal": ["hung up", "came to"], "wh": ["where"], "connectors": ["and", "since"], "comparative": []}, "word_meanings": [{"word": "parrot", "meaning": "papagaio", "note": ""}, {"word": "repeated", "meaning": "repetia", "note": ""}, {"word": "proud", "meaning": "orgulhoso", "note": ""}, {"word": "boss", "meaning": "chefe", "note": ""}, {"word": "boring", "meaning": "chato", "note": ""}, {"word": "hung up", "meaning": "desligou", "note": ""}, {"word": "bathroom", "meaning": "banheiro", "note": ""}], "exercises": {"grammar": [{"point": "Past simple e present perfect", "explanation_pt": "'Pepe has lived in the bathroom' fala de algo que começou e continua."}, {"point": "Could", "explanation_pt": "'Pepe could say many words' fala de capacidade no passado."}], "multiple_choice": [{"question": "What is Pepe?", "options": ["A fish", "A cat", "A dog", "A parrot"], "correct_index": 3, "explanation": "Um papagaio."}, {"question": "What does Pepe do?", "options": ["Repeats what he hears", "Flies away", "Sleeps all day", "Sings"], "correct_index": 0, "explanation": "Repete o que ouve."}, {"question": "Who came to dinner?", "options": ["A teacher", "The boss", "A neighbor", "A cousin"], "correct_index": 1, "explanation": "O chefe."}, {"question": "What did Pepe shout?", "options": ["Hello", "Goodbye", "Mr. Silva is boring", "Dinner is ready"], "correct_index": 2, "explanation": "O Sr. Silva é chato."}, {"question": "Where does Pepe live now?", "options": ["In the garden", "In the kitchen", "In a cage outside", "In the bathroom"], "correct_index": 3, "explanation": "No banheiro."}], "open_questions": [{"question": "What funny thing did a pet do?", "key_points_pt": ["contar"]}, {"question": "Have you said something by mistake?", "key_points_pt": ["contar"]}]}}, {"level": "B1", "genre": "humor", "title": "The Meeting That Never Ended", "paragraphs": ["At exactly nine o'clock, Rafael entered the conference room with a coffee and a confident smile. The agenda said the meeting would last thirty minutes. Nobody warned him that the director had brought a presentation with eighty-seven slides.", "By the fifth slide, Rafael had finished his coffee. By the fifteenth, he was drawing circles in his notebook. By the fortieth, he started to wonder whether the director was actually reading the slides to himself, since nobody else seemed to be listening. A colleague beside him fell asleep with his eyes open.", "At noon, someone shyly asked if they could have a break. The director replied, \"Of course, after slide sixty.\" Rafael decided it was time for an escape plan. He pretended to receive an urgent phone call, whispered \"I'm so sorry, it's my mother,\" and left the room, relieved.", "In the corridor he met five other colleagues who had used exactly the same excuse. They all burst out laughing. \"Your mother called, too?\" \"Every Thursday,\" one of them answered. They went for lunch together, and the meeting continued on slide sixty-one with nobody in the room."], "paragraphs_pt": ["Às nove em ponto, Rafael entrou na sala de conferências com um café e um sorriso confiante. A pauta dizia que a reunião duraria trinta minutos. Ninguém o avisou de que o diretor trouxera uma apresentação com oitenta e sete slides.", "No quinto slide, Rafael terminara o café. No décimo quinto, desenhava círculos no caderno. No quadragésimo, começou a se perguntar se o diretor estava lendo os slides para si, já que ninguém mais parecia ouvir. Um colega ao lado adormeceu de olhos abertos.", "Ao meio-dia, alguém perguntou timidamente se podiam fazer uma pausa. O diretor respondeu: \"Claro, depois do slide sessenta.\" Rafael decidiu que era hora de um plano de fuga. Fingiu receber uma ligação urgente, sussurrou \"Sinto muito, é minha mãe\" e saiu da sala, aliviado.", "No corredor encontrou cinco outros colegas que usaram exatamente a mesma desculpa. Todos caíram na gargalhada. \"Sua mãe também ligou?\" \"Toda quinta\", respondeu um deles. Foram almoçar juntos, e a reunião continuou no slide sessenta e um sem ninguém na sala."], "hard_words": ["agenda", "shyly", "urgent", "excuse"], "vocab": [{"word": "conference room", "meaning": "sala de conferências", "note": ""}, {"word": "agenda", "meaning": "pauta", "note": ""}, {"word": "confident", "meaning": "confiante", "note": ""}, {"word": "slides", "meaning": "slides", "note": ""}, {"word": "shyly", "meaning": "timidamente", "note": ""}, {"word": "urgent", "meaning": "urgente", "note": ""}, {"word": "excuse", "meaning": "desculpa", "note": ""}, {"word": "burst out laughing", "meaning": "cair na gargalhada", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be"], "irregular": ["entered", "said", "would", "warned", "had", "brought", "finished", "started", "seemed", "fell", "asked", "could", "replied", "decided", "pretended", "whispered", "left", "relieved", "met", "used", "called", "answered", "went", "continued"], "phrasal": ["burst out", "fell asleep"], "wh": ["who"], "connectors": ["and", "so", "after", "since", "if"], "comparative": []}, "word_meanings": [{"word": "conference room", "meaning": "sala de conferências", "note": ""}, {"word": "agenda", "meaning": "pauta", "note": ""}, {"word": "confident", "meaning": "confiante", "note": ""}, {"word": "slides", "meaning": "slides", "note": ""}, {"word": "shyly", "meaning": "timidamente", "note": ""}, {"word": "urgent", "meaning": "urgente", "note": ""}, {"word": "excuse", "meaning": "desculpa", "note": ""}, {"word": "burst out laughing", "meaning": "cair na gargalhada", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Rafael had finished his coffee' mostra o que já acontecera."}, {"point": "By + número", "explanation_pt": "'By the fifth slide' marca o limite de um progresso."}], "multiple_choice": [{"question": "How long should the meeting last?", "options": ["Thirty minutes", "Ten minutes", "Three hours", "One day"], "correct_index": 0, "explanation": "Trinta minutos."}, {"question": "How many slides did the director have?", "options": ["Twenty", "Forty", "Eight", "Eighty-seven"], "correct_index": 3, "explanation": "Oitenta e sete."}, {"question": "What was Rafael's escape plan?", "options": ["Falling asleep", "Fainting", "Fire alarm", "A fake phone call"], "correct_index": 3, "explanation": "Uma ligação falsa."}, {"question": "What did the others do?", "options": ["Complained", "Slept", "Used the same excuse", "Stayed"], "correct_index": 2, "explanation": "Usaram a mesma desculpa."}, {"question": "What happened to the meeting?", "options": ["It continued with nobody in the room", "It was cancelled", "It moved", "It ended"], "correct_index": 0, "explanation": "Continuou sem ninguém na sala."}], "open_questions": [{"question": "What is the worst meeting you've had?", "key_points_pt": ["contar"]}, {"question": "How can meetings be more efficient?", "key_points_pt": ["sugerir"]}]}}, {"level": "B1", "genre": "humor", "title": "A Very Honest GPS", "paragraphs": ["When Julia bought her new car, the salesman promised that its GPS was \"the most advanced in the world\". On her first trip, she asked it to take her to her sister's house. \"Turn left in two hundred meters,\" said a calm voice. Julia obeyed.", "After ten minutes, she realised that the GPS was talking more than it should. \"You are driving 8 km/h under the speed limit,\" it said. \"Are you sure you know where you are going?\" Julia ignored it, but when she missed an exit, the voice sighed. \"I told you.\"", "At the next traffic light, the GPS said, \"Your sister's house is in the opposite direction. I suggest you stop at this café and think about your life choices.\" Julia burst out laughing and drove back to the shop. \"Is this a joke?\"", "The salesman checked the device and shrugged. \"Oh, that's the 'honest mode'. Someone must have activated it.\" Julia kept the car and the honest mode. Now, whenever she gets lost, her GPS calmly says, \"Typical,\" and she admits it is right."], "paragraphs_pt": ["Quando Julia comprou o carro novo, o vendedor prometeu que o GPS era \"o mais avançado do mundo\". Na primeira viagem, pediu que a levasse até a casa da irmã. \"Vire à esquerda em duzentos metros\", disse uma voz calma. Julia obedeceu.", "Após dez minutos, percebeu que o GPS falava mais do que devia. \"Você está 8 km/h abaixo do limite\", disse. \"Tem certeza de que sabe aonde vai?\" Julia o ignorou, mas ao perder uma saída, a voz suspirou. \"Eu avisei.\"", "No semáforo seguinte, o GPS disse: \"A casa da sua irmã fica na direção oposta. Sugiro que pare neste café e pense nas suas escolhas de vida.\" Julia caiu na gargalhada e voltou à loja. \"Isto é uma piada?\"", "O vendedor verificou o aparelho e deu de ombros. \"Ah, é o 'modo honesto'. Alguém deve tê-lo ativado.\" Julia ficou com o carro e com o modo honesto. Agora, sempre que se perde, o GPS diz calmamente: \"Típico\", e ela admite que ele tem razão."], "hard_words": ["advanced", "obeyed", "opposite", "activated"], "vocab": [{"word": "salesman", "meaning": "vendedor", "note": ""}, {"word": "advanced", "meaning": "avançado", "note": ""}, {"word": "obeyed", "meaning": "obedeceu", "note": ""}, {"word": "speed limit", "meaning": "limite de velocidade", "note": ""}, {"word": "exit", "meaning": "saída", "note": ""}, {"word": "opposite", "meaning": "oposto", "note": ""}, {"word": "shrugged", "meaning": "deu de ombros", "note": ""}, {"word": "activated", "meaning": "ativado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "are", "is"], "irregular": ["bought", "promised", "advanced", "asked", "left", "said", "obeyed", "realised", "should", "ignored", "missed", "sighed", "told", "drove", "checked", "shrugged", "activated", "kept", "lost"], "phrasal": ["burst out", "drove back"], "wh": ["where", "when", "whenever"], "connectors": ["and", "but", "after", "when", "whenever"], "comparative": []}, "word_meanings": [{"word": "salesman", "meaning": "vendedor", "note": ""}, {"word": "advanced", "meaning": "avançado", "note": ""}, {"word": "obeyed", "meaning": "obedeceu", "note": ""}, {"word": "speed limit", "meaning": "limite de velocidade", "note": ""}, {"word": "exit", "meaning": "saída", "note": ""}, {"word": "opposite", "meaning": "oposto", "note": ""}, {"word": "shrugged", "meaning": "deu de ombros", "note": ""}, {"word": "activated", "meaning": "ativado", "note": ""}], "exercises": {"grammar": [{"point": "Must have + particípio", "explanation_pt": "'Someone must have activated it' faz uma dedução sobre o passado."}, {"point": "Whenever", "explanation_pt": "'whenever she gets lost' indica repetição."}], "multiple_choice": [{"question": "What did the salesman promise?", "options": ["A free trip", "A cheap car", "A new phone", "The most advanced GPS"], "correct_index": 3, "explanation": "O GPS mais avançado."}, {"question": "What did the GPS say about her speed?", "options": ["It was perfect", "She was too slow", "She was too fast", "She was lost"], "correct_index": 1, "explanation": "Estava devagar."}, {"question": "What did the GPS suggest at the traffic light?", "options": ["Stop at a café and think about life", "Call her sister", "Turn right", "Go home"], "correct_index": 0, "explanation": "Parar e pensar."}, {"question": "What was the 'honest mode'?", "options": ["A prank", "A gift", "A bug", "A setting someone activated"], "correct_index": 3, "explanation": "Um modo ativado."}, {"question": "What does GPS say now when she's lost?", "options": ["Left", "Typical", "Sorry", "Help"], "correct_index": 1, "explanation": "'Típico.'"}], "open_questions": [{"question": "Would you like a very honest assistant?", "key_points_pt": ["opinar"]}, {"question": "What technology annoys you?", "key_points_pt": ["descrever"]}]}}, {"level": "B2", "genre": "humor", "title": "The Diary of a Reluctant Gardener", "paragraphs": ["Monday. Everyone says that gardening is relaxing. This is a lie spread by people who have never tried to remove a weed that has been rooted since the Middle Ages. I bought seeds, gloves and a hat that makes me look like a scarecrow. I have never felt more optimistic or more foolish.", "Wednesday. The seeds have been in the soil for two days, and nothing has happened. I have checked on them seventeen times. I suspect they are mocking me. My neighbour, Mrs. Alvarez, whose roses look like a magazine cover, offered advice, which I accepted with a smile that hurt my face.", "Saturday. A miracle: something is growing! Mrs. Alvarez glanced at it, looked at me, and said gently, \"That's a weed.\" I decided to love it anyway. I have named it Gerald, and he is the tallest living thing in my garden.", "Sunday. Gerald is gone. I suspect Mrs. Alvarez, but she denies everything with the innocence of a woman who has just pruned something. I have bought a plastic cactus. It requires no water, no sunlight, and it never lets me down. Gardening, I now understand, is the art of lowering expectations."], "paragraphs_pt": ["Segunda. Todo mundo diz que jardinagem é relaxante. É uma mentira espalhada por quem nunca tentou arrancar uma erva daninha enraizada desde a Idade Média. Comprei sementes, luvas e um chapéu que me faz parecer um espantalho. Nunca me senti tão otimista nem tão tolo.", "Quarta. As sementes estão na terra há dois dias e nada aconteceu. Fui vê-las dezessete vezes. Suspeito que estejam zombando de mim. A vizinha, Sra. Alvarez, cujas rosas parecem capa de revista, ofereceu conselhos, que aceitei com um sorriso que doeu no rosto.", "Sábado. Um milagre: algo está crescendo! A Sra. Alvarez deu uma olhada, me olhou e disse com gentileza: \"Isso é erva daninha.\" Decidi amá-la mesmo assim. Chamei-a de Gerald, e ele é a coisa viva mais alta do meu jardim.", "Domingo. Gerald sumiu. Suspeito da Sra. Alvarez, mas ela nega tudo com a inocência de quem acabou de podar algo. Comprei um cacto de plástico. Não precisa de água nem de sol e nunca me decepciona. Jardinagem, agora entendo, é a arte de baixar as expectativas."], "hard_words": ["weed", "scarecrow", "mocking", "expectations"], "vocab": [{"word": "weed", "meaning": "erva daninha", "note": ""}, {"word": "rooted", "meaning": "enraizada", "note": ""}, {"word": "seeds", "meaning": "sementes", "note": ""}, {"word": "scarecrow", "meaning": "espantalho", "note": ""}, {"word": "soil", "meaning": "terra", "note": ""}, {"word": "mocking", "meaning": "zombando", "note": ""}, {"word": "pruned", "meaning": "podou", "note": ""}, {"word": "expectations", "meaning": "expectativas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "been", "are"], "irregular": ["tried", "weed", "rooted", "bought", "felt", "happened", "checked", "offered", "accepted", "glanced", "looked", "said", "decided", "named", "gone", "pruned"], "phrasal": ["checked on"], "wh": ["who", "which", "whose"], "connectors": ["and", "but", "since", "or"], "comparative": []}, "word_meanings": [{"word": "weed", "meaning": "erva daninha", "note": ""}, {"word": "rooted", "meaning": "enraizada", "note": ""}, {"word": "seeds", "meaning": "sementes", "note": ""}, {"word": "scarecrow", "meaning": "espantalho", "note": ""}, {"word": "soil", "meaning": "terra", "note": ""}, {"word": "mocking", "meaning": "zombando", "note": ""}, {"word": "pruned", "meaning": "podou", "note": ""}, {"word": "expectations", "meaning": "expectativas", "note": ""}], "exercises": {"grammar": [{"point": "Present perfect", "explanation_pt": "'I have never felt more optimistic' relaciona experiência até agora."}, {"point": "Present perfect continuous", "explanation_pt": "'has been rooted since the Middle Ages' indica algo contínuo."}], "multiple_choice": [{"question": "What does the writer think about gardening?", "options": ["It is not relaxing", "It is boring", "It is easy", "It is cheap"], "correct_index": 0, "explanation": "Não é relaxante."}, {"question": "What did the neighbour say about the plant?", "options": ["It's a cactus", "It's a flower", "It's a weed", "It's a rose"], "correct_index": 2, "explanation": "É uma erva daninha."}, {"question": "What did the writer name it?", "options": ["Rosie", "Sam", "Gerald", "Mrs. Alvarez"], "correct_index": 2, "explanation": "Gerald."}, {"question": "What happened to Gerald?", "options": ["He disappeared", "He grew", "He bloomed", "He died of cold"], "correct_index": 0, "explanation": "Sumiu."}, {"question": "What did the writer buy?", "options": ["A tree", "A rose", "A plastic cactus", "A dog"], "correct_index": 2, "explanation": "Um cacto de plástico."}], "open_questions": [{"question": "What hobby have you tried and abandoned?", "key_points_pt": ["contar"]}, {"question": "Why is humour useful when we fail?", "key_points_pt": ["discutir"]}]}}, {"level": "B2", "genre": "humor", "title": "The Interview of Misunderstandings", "paragraphs": ["Rodrigo had prepared for weeks for his interview at the dream company. He had memorised answers, ironed his best shirt and practised his handshake on the dog. On the day, however, everything that could go wrong did. A pigeon decided to attack him on the street, and he arrived with a smudge on his sleeve.", "\"Tell me about your weaknesses,\" the interviewer began. Rodrigo, flustered, replied, \"I sometimes tell the truth when it isn't appropriate.\" The interviewer raised an eyebrow. \"For example?\" \"For example, your tie. It is hideous.\" There was a very long silence.", "Then, to his astonishment, she laughed. \"It's a gift from my mother-in-law,\" she confessed. \"Nobody has dared to say it in six years.\" The atmosphere changed completely. They talked about hobbies, bad gifts and the pigeon, and the interview ended an hour later with a firm handshake.", "Rodrigo did not get the job at that company. However, the interviewer recommended him to a friend whose team valued honesty, and three weeks later he started working there. He still tells the story at parties, and the dog, he says, is still waiting for an apology."], "paragraphs_pt": ["Rodrigo se preparara por semanas para a entrevista na empresa dos sonhos. Memorizara respostas, passara sua melhor camisa e treinara o aperto de mão no cachorro. No dia, porém, tudo o que podia dar errado deu. Um pombo decidiu atacá-lo na rua, e ele chegou com uma mancha na manga.", "\"Fale-me de suas fraquezas\", começou a entrevistadora. Rodrigo, atrapalhado, respondeu: \"Às vezes digo a verdade quando não é apropriado.\" A entrevistadora ergueu uma sobrancelha. \"Por exemplo?\" \"Por exemplo, a sua gravata. É horrorosa.\" Houve um silêncio muito longo.", "Então, para seu espanto, ela riu. \"É presente da minha sogra\", confessou. \"Ninguém ousou dizer em seis anos.\" O clima mudou completamente. Falaram de hobbies, presentes ruins e do pombo, e a entrevista terminou uma hora depois com um aperto de mão firme.", "Rodrigo não conseguiu o emprego nessa empresa. Porém a entrevistadora o recomendou a uma amiga cuja equipe valorizava a honestidade, e três semanas depois ele começou a trabalhar lá. Ainda conta a história nas festas, e o cachorro, diz ele, ainda espera um pedido de desculpas."], "hard_words": ["flustered", "hideous", "astonishment", "weaknesses"], "vocab": [{"word": "memorised", "meaning": "memorizara", "note": ""}, {"word": "ironed", "meaning": "passou", "note": ""}, {"word": "smudge", "meaning": "mancha", "note": ""}, {"word": "weaknesses", "meaning": "fraquezas", "note": ""}, {"word": "flustered", "meaning": "atrapalhado", "note": ""}, {"word": "hideous", "meaning": "horroroso", "note": ""}, {"word": "astonishment", "meaning": "espanto", "note": ""}, {"word": "mother-in-law", "meaning": "sogra", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was"], "irregular": ["had", "prepared", "memorised", "ironed", "practised", "could", "did", "decided", "arrived", "began", "flustered", "replied", "raised", "laughed", "confessed", "dared", "changed", "talked", "ended", "recommended", "valued", "started"], "phrasal": ["go wrong", "raised an eyebrow"], "wh": ["when", "whose"], "connectors": ["and", "however", "then", "when", "still"], "comparative": []}, "word_meanings": [{"word": "memorised", "meaning": "memorizara", "note": ""}, {"word": "ironed", "meaning": "passou", "note": ""}, {"word": "smudge", "meaning": "mancha", "note": ""}, {"word": "weaknesses", "meaning": "fraquezas", "note": ""}, {"word": "flustered", "meaning": "atrapalhado", "note": ""}, {"word": "hideous", "meaning": "horroroso", "note": ""}, {"word": "astonishment", "meaning": "espanto", "note": ""}, {"word": "mother-in-law", "meaning": "sogra", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'He had memorised answers' mostra a preparação anterior."}, {"point": "For example", "explanation_pt": "'For example, your tie' dá um exemplo concreto."}], "multiple_choice": [{"question": "How did Rodrigo prepare?", "options": ["Did nothing", "Called a friend", "Bought a suit", "Memorised answers and practised handshake"], "correct_index": 3, "explanation": "Memorizou respostas e treinou o aperto."}, {"question": "What went wrong before the interview?", "options": ["He was late", "A pigeon attacked him", "It rained", "He lost his phone"], "correct_index": 1, "explanation": "Um pombo o atacou."}, {"question": "What did he say about his weaknesses?", "options": ["He is late", "He tells the truth when inappropriate", "He is lazy", "He is shy"], "correct_index": 1, "explanation": "Diz a verdade quando não é apropriado."}, {"question": "How did the interviewer react?", "options": ["She cried", "She shouted", "She left", "She laughed"], "correct_index": 3, "explanation": "Ela riu."}, {"question": "What happened to his career?", "options": ["He quit", "He got that job", "He stayed unemployed", "He got a job via recommendation"], "correct_index": 3, "explanation": "Foi recomendado e arrumou emprego."}], "open_questions": [{"question": "Is honesty an asset in interviews?", "key_points_pt": ["debater"]}, {"question": "What funny interview story do you know?", "key_points_pt": ["contar"]}]}}, {"level": "C1", "genre": "humor", "title": "The Committee for Small Decisions", "paragraphs": ["The Committee for Small Decisions had been founded, in a moment of administrative optimism, to spare the company's executives from trivial choices. In practice, it spent six months debating whether the office plants should be watered on Mondays or Tuesdays, and a further eight on the colour of the staff-room kettle.", "Its chairman, a solemn man named Mr. Pickering, regarded these matters with the gravity of a surgeon. \"A kettle,\" he would say, \"is a statement of values.\" Minutes were taken meticulously, annexes appended, and a subcommittee on teaspoons convened. Nobody dared ask whether any of it mattered, for fear of being appointed to the subcommittee.", "The turning point came when a junior employee, Priya, accidentally replied-all to a meeting invitation with the single word \"Why?\". The silence that followed was brief but profound. Mr. Pickering considered it for a long time before announcing, with great dignity, that the committee would henceforth address the question of its own existence.", "It produced a forty-page report, concluding that the committee was essential for deciding whether it should exist. Priya read it on the train, laughed until strangers stared, and framed the last page above her desk. Beneath it she wrote: \"A procedure designed to avoid decisions will, with great consistency, decide to continue.\""], "paragraphs_pt": ["O Comitê de Pequenas Decisões fora fundado, num momento de otimismo administrativo, para poupar os executivos da empresa de escolhas triviais. Na prática, passou seis meses debatendo se as plantas do escritório deviam ser regadas às segundas ou terças e mais oito sobre a cor da chaleira da sala dos funcionários.", "Seu presidente, um homem solene chamado Sr. Pickering, encarava esses assuntos com a gravidade de um cirurgião. \"Uma chaleira\", dizia, \"é uma declaração de valores.\" As atas eram lavradas meticulosamente, anexos acrescentados e um subcomitê sobre colheres de chá foi convocado. Ninguém ousava perguntar se algo daquilo importava, por medo de ser nomeado para o subcomitê.", "A virada veio quando uma funcionária júnior, Priya, respondeu a todos por engano a um convite de reunião com uma única palavra: \"Por quê?\". O silêncio que se seguiu foi breve, mas profundo. O Sr. Pickering o considerou por muito tempo antes de anunciar, com grande dignidade, que o comitê passaria a tratar da questão de sua própria existência.", "Produziu um relatório de quarenta páginas, concluindo que o comitê era essencial para decidir se deveria existir. Priya o leu no trem, riu até estranhos olharem e emoldurou a última página sobre a mesa. Embaixo escreveu: \"Um procedimento criado para evitar decisões decidirá, com grande consistência, continuar.\""], "hard_words": ["trivial", "solemn", "subcommittee", "henceforth"], "vocab": [{"word": "trivial", "meaning": "trivial", "note": ""}, {"word": "kettle", "meaning": "chaleira", "note": ""}, {"word": "solemn", "meaning": "solene", "note": ""}, {"word": "gravity", "meaning": "gravidade", "note": ""}, {"word": "meticulously", "meaning": "meticulosamente", "note": ""}, {"word": "subcommittee", "meaning": "subcomitê", "note": ""}, {"word": "convened", "meaning": "convocado", "note": ""}, {"word": "henceforth", "meaning": "de agora em diante", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "be", "is", "were", "being", "was"], "irregular": ["had", "founded", "spent", "should", "watered", "named", "regarded", "would", "taken", "appended", "convened", "dared", "mattered", "appointed", "came", "replied", "followed", "considered", "produced", "laughed", "stared", "framed", "wrote", "designed"], "phrasal": ["replied-all"], "wh": ["when", "why"], "connectors": ["and", "but", "before", "when", "until", "or"], "comparative": []}, "word_meanings": [{"word": "trivial", "meaning": "trivial", "note": ""}, {"word": "kettle", "meaning": "chaleira", "note": ""}, {"word": "solemn", "meaning": "solene", "note": ""}, {"word": "gravity", "meaning": "gravidade", "note": ""}, {"word": "meticulously", "meaning": "meticulosamente", "note": ""}, {"word": "subcommittee", "meaning": "subcomitê", "note": ""}, {"word": "convened", "meaning": "convocado", "note": ""}, {"word": "henceforth", "meaning": "de agora em diante", "note": ""}], "exercises": {"grammar": [{"point": "Sujeito + will + com ênfase", "explanation_pt": "'A procedure... will, with great consistency, decide to continue' usa ironia com will."}, {"point": "Passive", "explanation_pt": "'Minutes were taken meticulously' omite o agente."}], "multiple_choice": [{"question": "Why was the committee founded?", "options": ["To hire staff", "To spare executives from trivial choices", "To fire staff", "To plan trips"], "correct_index": 1, "explanation": "Para poupar executivos de escolhas triviais."}, {"question": "What did it debate?", "options": ["Holidays", "Clients", "Plant watering and the kettle colour", "Salaries"], "correct_index": 2, "explanation": "Plantas e chaleira."}, {"question": "What did Priya write?", "options": ["Why?", "Thanks", "Good", "Stop"], "correct_index": 0, "explanation": "'Por quê?'"}, {"question": "What did the final report conclude?", "options": ["It should close", "It was too small", "The committee was essential to decide on its own existence", "It was a joke"], "correct_index": 2, "explanation": "O comitê era essencial."}, {"question": "What did Priya write under the page?", "options": ["Close the committee", "A procedure designed to avoid decisions will continue", "Work hard", "Buy kettles"], "correct_index": 1, "explanation": "Um procedimento para evitar decisões continua."}], "open_questions": [{"question": "Why do organisations create unnecessary procedures?", "key_points_pt": ["discutir"]}, {"question": "When has bureaucracy amused or annoyed you?", "key_points_pt": ["contar"]}]}}, {"level": "C1", "genre": "humor", "title": "Unsolicited Advice", "paragraphs": ["Few things in life are as abundant, or as reliably useless, as advice nobody has asked for. Take my Uncle Ferdinand, who, on learning that I was learning the cello, proceeded to explain at length how he would have learned it differently, though he has never touched an instrument larger than a kazoo.", "My aunt, for her part, believes that every problem can be cured by a particular herbal tea, from a sore throat to an existential crisis. I once mentioned that my car had broken down, and she posted a tin of chamomile through my letterbox. I admit the tea was excellent. The car, regrettably, remains unrepaired.", "The most formidable offender, however, is my neighbour, Mr. Bellamy, who dispenses wisdom through the fence with the confidence of a man who has read half an article on the subject. His latest pronouncement was that I should \"think more positively about the weather\". I looked at the rain, then at him, and attempted a smile.", "Over the years I have developed a strategy: I nod, thank the adviser warmly, and do precisely what I intended. People are so delighted to be listened to that they rarely check. I recommend it highly, though, naturally, only if you haven't asked for my advice."], "paragraphs_pt": ["Poucas coisas na vida são tão abundantes, ou tão confiavelmente inúteis, quanto conselhos que ninguém pediu. Tome-se meu tio Ferdinand, que, ao saber que eu estava aprendendo violoncelo, passou a explicar longamente como ele o teria aprendido de modo diferente, embora nunca tenha tocado um instrumento maior que um kazoo.", "Minha tia, por sua vez, acredita que todo problema se cura com um chá de ervas específico, de dor de garganta a crise existencial. Certa vez mencionei que meu carro quebrara e ela enfiou uma lata de camomila na minha caixa de correio. Admito que o chá estava excelente. O carro, lamentavelmente, continua sem conserto.", "O infrator mais formidável, porém, é meu vizinho, Sr. Bellamy, que dispensa sabedoria pela cerca com a confiança de quem leu metade de um artigo sobre o assunto. Sua última sentença foi que eu deveria \"pensar de modo mais positivo sobre o tempo\". Olhei a chuva, depois para ele, e tentei um sorriso.", "Com os anos desenvolvi uma estratégia: aceno, agradeço calorosamente ao conselheiro e faço precisamente o que pretendia. As pessoas ficam tão encantadas por serem ouvidas que raramente conferem. Recomendo-a vivamente, embora, naturalmente, só se você não tiver pedido meu conselho."], "hard_words": ["regrettably", "formidable", "pronouncement"], "vocab": [{"word": "abundant", "meaning": "abundante", "note": ""}, {"word": "proceeded", "meaning": "passou a", "note": ""}, {"word": "regrettably", "meaning": "lamentavelmente", "note": ""}, {"word": "formidable", "meaning": "formidável", "note": ""}, {"word": "dispenses", "meaning": "dispensa", "note": ""}, {"word": "pronouncement", "meaning": "sentença", "note": ""}, {"word": "strategy", "meaning": "estratégia", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "was", "be", "is"], "irregular": ["asked", "proceeded", "would", "learned", "touched", "cured", "mentioned", "had", "broken", "posted", "should", "looked", "attempted", "developed", "intended", "delighted", "listened"], "phrasal": ["broken down"], "wh": ["who", "what", "how"], "connectors": ["and", "however", "so", "though", "then", "or", "once", "if", "as"], "comparative": []}, "word_meanings": [{"word": "abundant", "meaning": "abundante", "note": ""}, {"word": "proceeded", "meaning": "passou a", "note": ""}, {"word": "regrettably", "meaning": "lamentavelmente", "note": ""}, {"word": "formidable", "meaning": "formidável", "note": ""}, {"word": "dispenses", "meaning": "dispensa", "note": ""}, {"word": "pronouncement", "meaning": "sentença", "note": ""}, {"word": "strategy", "meaning": "estratégia", "note": ""}], "exercises": {"grammar": [{"point": "Few / A few", "explanation_pt": "'Few things' tem sentido negativo (quase nenhuma); 'a few' seria algumas."}, {"point": "Though com ironia", "explanation_pt": "'though he has never touched an instrument larger than a kazoo' contrasta ironicamente."}], "multiple_choice": [{"question": "What is the topic?", "options": ["Cooking", "Unasked advice", "Music history", "Travel"], "correct_index": 1, "explanation": "Conselhos não pedidos."}, {"question": "What is the uncle's mistake?", "options": ["He plays the cello", "He is silent", "He is rude", "He advises without knowing"], "correct_index": 3, "explanation": "Aconselha sem entender."}, {"question": "What did the aunt send?", "options": ["A car", "Money", "Herbal tea", "A cello"], "correct_index": 2, "explanation": "Chá de ervas."}, {"question": "What did Mr. Bellamy say?", "options": ["Move", "Practice more", "Buy a car", "Think positively about the weather"], "correct_index": 3, "explanation": "Pensar positivo sobre o tempo."}, {"question": "What is the writer's strategy?", "options": ["Nod, thank, and do what they intended", "Take notes", "Avoid people", "Argue"], "correct_index": 0, "explanation": "Acenar, agradecer e fazer o que pretendia."}], "open_questions": [{"question": "Why do people give unsolicited advice?", "key_points_pt": ["discutir"]}, {"question": "How do you handle it politely?", "key_points_pt": ["sugerir"]}]}}, {"level": "C1", "genre": "humor", "title": "The Man Who Apologised to Furniture", "paragraphs": ["Edmund, a man of exquisite politeness, had a habit that had bewildered his friends for years: he apologised to inanimate objects. If he bumped into a table, he muttered, \"Terribly sorry, old chap.\" If a door slammed in his face, he said, \"My fault entirely.\" The family considered it harmless, a charming eccentricity.", "The trouble began when he started to receive replies. Not literally, he insisted, although the chair in his study did creak in a manner he found distinctly passive-aggressive. Gradually, he began to attribute personalities to his possessions: the wardrobe was dignified, the lamp melodramatic, and the stairs unforgivably smug.", "His niece, a psychologist, listened with professional interest. \"Uncle,\" she said gently, \"it's lovely that you're considerate. But the table does not mind.\" Edmund considered this with a frown. \"That, my dear, is exactly what the table wants you to think.\" The conversation went no further.", "Years later, at his funeral, the guests noticed with amusement that the vicar tripped on a step and murmured, \"Sorry.\" It was impossible to say whether this was a coincidence, an affectionate tribute or the stairs, at last, asking for forgiveness."], "paragraphs_pt": ["Edmund, homem de refinada educação, tinha um hábito que desconcertava os amigos havia anos: pedia desculpas a objetos inanimados. Se esbarrava numa mesa, murmurava: \"Terrivelmente desculpe, meu velho.\" Se uma porta batia na cara dele, dizia: \"Culpa inteiramente minha.\" A família considerava inofensivo, uma excentricidade encantadora.", "O problema começou quando passou a receber respostas. Não literalmente, insistia, embora a cadeira do escritório rangesse de um modo que ele achava distintamente passivo-agressivo. Aos poucos passou a atribuir personalidades às posses: o guarda-roupa era digno, a luminária melodramática e a escada imperdoavelmente presunçosa.", "A sobrinha, psicóloga, ouviu com interesse profissional. \"Tio\", disse com gentileza, \"é lindo que você seja atencioso. Mas a mesa não se importa.\" Edmund considerou isso com o cenho franzido. \"Isso, minha cara, é exatamente o que a mesa quer que você pense.\" A conversa não foi adiante.", "Anos depois, em seu funeral, os convidados notaram com graça que o vigário tropeçou num degrau e murmurou: \"Desculpe.\" Era impossível dizer se foi coincidência, uma homenagem afetuosa ou a escada, enfim, pedindo perdão."], "hard_words": ["bewildered", "inanimate", "eccentricity", "smug"], "vocab": [{"word": "exquisite", "meaning": "refinada", "note": ""}, {"word": "bewildered", "meaning": "desconcertou", "note": ""}, {"word": "inanimate", "meaning": "inanimado", "note": ""}, {"word": "bumped into", "meaning": "esbarrou", "note": ""}, {"word": "eccentricity", "meaning": "excentricidade", "note": ""}, {"word": "smug", "meaning": "presunçoso", "note": ""}, {"word": "considerate", "meaning": "atencioso", "note": ""}, {"word": "vicar", "meaning": "vigário", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is"], "irregular": ["had", "bewildered", "apologised", "bumped", "muttered", "slammed", "said", "considered", "began", "started", "insisted", "did", "found", "dignified", "listened", "went", "noticed", "tripped", "murmured"], "phrasal": ["went no further"], "wh": ["what", "when"], "connectors": ["and", "but", "although", "when", "or", "if"], "comparative": []}, "word_meanings": [{"word": "exquisite", "meaning": "refinada", "note": ""}, {"word": "bewildered", "meaning": "desconcertou", "note": ""}, {"word": "inanimate", "meaning": "inanimado", "note": ""}, {"word": "bumped into", "meaning": "esbarrou", "note": ""}, {"word": "eccentricity", "meaning": "excentricidade", "note": ""}, {"word": "smug", "meaning": "presunçoso", "note": ""}, {"word": "considerate", "meaning": "atencioso", "note": ""}, {"word": "vicar", "meaning": "vigário", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'a habit that had bewildered his friends' mostra efeito anterior."}, {"point": "Exactly", "explanation_pt": "'That is exactly what the table wants you to think' dá ênfase irônica."}], "multiple_choice": [{"question": "What was Edmund's habit?", "options": ["Apologising to objects", "Writing letters", "Collecting furniture", "Talking to dogs"], "correct_index": 0, "explanation": "Pedir desculpas a objetos."}, {"question": "What began to happen?", "options": ["He broke things", "He forgot names", "He sold his house", "He thought objects replied"], "correct_index": 3, "explanation": "Achava que respondiam."}, {"question": "How did the niece react?", "options": ["She said the table does not mind", "She shouted", "She called a doctor", "She laughed"], "correct_index": 0, "explanation": "Disse que a mesa não se importa."}, {"question": "What was Edmund's answer?", "options": ["You are right", "That's what the table wants you to think", "Sorry", "I will stop"], "correct_index": 1, "explanation": "Que a mesa quer que ela pense isso."}, {"question": "What happened at the funeral?", "options": ["A table broke", "Nothing", "The vicar tripped and said sorry", "The lamp fell"], "correct_index": 2, "explanation": "O vigário tropeçou e pediu desculpa."}], "open_questions": [{"question": "Is politeness to objects odd or kind?", "key_points_pt": ["debater"]}, {"question": "What habit do you have that surprises people?", "key_points_pt": ["contar"]}]}}, {"level": "C2", "genre": "humor", "title": "A Treatise on Waiting Rooms", "paragraphs": ["The modern waiting room is a peculiar social experiment, conducted without consent, in which strangers are confined to a small space with outdated magazines and a television that has long since given up on being watched. Within minutes a delicate etiquette emerges: nobody speaks, everybody coughs, and the entire population studies the clock as though it were a particularly slow thriller.", "It is instructive to observe the cast. There is the Optimist, who arrived early and has settled in with a sandwich, as for a picnic. There is the Veteran, who has been coming here for years and who regards the receptionist with the tender wariness of a sailor eyeing the sea. And there is the Newcomer, who still believes that \"ten minutes\" means ten minutes, a belief that will not survive the afternoon.", "Time, in a waiting room, is not a line but a viscous substance. An hour can pass without being noticed, while a single minute stretches into a geological era. I once saw a man age visibly between his fourth and fifth glance at the wall. He did not complain, since complaint is the one transgression the room does not forgive.", "When at last my name was called, I stood with the grave dignity of a man released from a long sentence. The doctor asked what the problem was. I thought for a moment and answered, with perfect sincerity, \"I believe I have forgotten, but I am quite certain it was less urgent than the waiting.\""], "paragraphs_pt": ["A sala de espera moderna é um peculiar experimento social, conduzido sem consentimento, em que estranhos são confinados num espaço pequeno com revistas desatualizadas e uma televisão que há muito desistiu de ser assistida. Em minutos surge uma delicada etiqueta: ninguém fala, todos tossem e a população inteira estuda o relógio como se fosse um suspense particularmente lento.", "É instrutivo observar o elenco. Há o Otimista, que chegou cedo e se instalou com um sanduíche, como num piquenique. Há o Veterano, que vem aqui há anos e encara a recepcionista com a terna cautela de um marinheiro observando o mar. E há o Novato, que ainda acredita que \"dez minutos\" significa dez minutos, crença que não sobreviverá à tarde.", "O tempo, numa sala de espera, não é uma linha, mas uma substância viscosa. Uma hora pode passar sem ser notada, enquanto um único minuto se estende numa era geológica. Certa vez vi um homem envelhecer visivelmente entre a quarta e a quinta olhada na parede. Não reclamou, pois reclamação é a única transgressão que a sala não perdoa.", "Quando por fim meu nome foi chamado, levantei-me com a grave dignidade de um homem liberado de uma longa sentença. O médico perguntou qual era o problema. Pensei por um instante e respondi, com perfeita sinceridade: \"Creio que esqueci, mas tenho certeza de que era menos urgente que a espera.\""], "hard_words": ["etiquette", "wariness", "viscous", "transgression"], "vocab": [{"word": "confined", "meaning": "confinados", "note": ""}, {"word": "outdated", "meaning": "desatualizadas", "note": ""}, {"word": "etiquette", "meaning": "etiqueta", "note": ""}, {"word": "wariness", "meaning": "cautela", "note": ""}, {"word": "viscous", "meaning": "viscosa", "note": ""}, {"word": "geological", "meaning": "geológica", "note": ""}, {"word": "transgression", "meaning": "transgressão", "note": ""}, {"word": "sincerity", "meaning": "sinceridade", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are", "being", "were", "been", "was", "am"], "irregular": ["conducted", "confined", "given", "watched", "arrived", "settled", "noticed", "saw", "did", "called", "stood", "released", "asked", "thought", "answered", "forgotten"], "phrasal": ["given up on", "settled in"], "wh": ["who", "what", "when", "which"], "connectors": ["and", "but", "while", "though", "when", "since", "still", "once", "as"], "comparative": []}, "word_meanings": [{"word": "confined", "meaning": "confinados", "note": ""}, {"word": "outdated", "meaning": "desatualizadas", "note": ""}, {"word": "etiquette", "meaning": "etiqueta", "note": ""}, {"word": "wariness", "meaning": "cautela", "note": ""}, {"word": "viscous", "meaning": "viscosa", "note": ""}, {"word": "geological", "meaning": "geológica", "note": ""}, {"word": "transgression", "meaning": "transgressão", "note": ""}, {"word": "sincerity", "meaning": "sinceridade", "note": ""}], "exercises": {"grammar": [{"point": "As though + passado", "explanation_pt": "'as though it were a particularly slow thriller' compara com algo hipotético."}, {"point": "Relative clauses", "explanation_pt": "'who has been coming here for years' acrescenta informação sobre o veterano."}], "multiple_choice": [{"question": "What is a waiting room like, says the narrator?", "options": ["A library", "A school", "A hotel", "A social experiment"], "correct_index": 3, "explanation": "Um experimento social."}, {"question": "Who is the Newcomer?", "options": ["Someone who believes ten minutes means ten", "Someone who sells things", "A nurse", "A doctor"], "correct_index": 0, "explanation": "Quem acredita em 'dez minutos'."}, {"question": "How is time described?", "options": ["A river", "A line", "A viscous substance", "A circle"], "correct_index": 2, "explanation": "Uma substância viscosa."}, {"question": "What does the room not forgive?", "options": ["Sleeping", "Complaint", "Eating", "Noise"], "correct_index": 1, "explanation": "Reclamação."}, {"question": "What did the narrator forget?", "options": ["His wallet", "His appointment", "The problem", "His name"], "correct_index": 2, "explanation": "O problema."}], "open_questions": [{"question": "Why are waiting rooms stressful?", "key_points_pt": ["discutir"]}, {"question": "How do you pass the time while waiting?", "key_points_pt": ["descrever"]}]}}, {"level": "C2", "genre": "humor", "title": "The Last Will of Aunt Cordelia", "paragraphs": ["Aunt Cordelia's will was read in a mahogany-panelled room smelling of lemon polish, before a family assembled less out of grief than out of a collective curiosity about the silver. The solicitor, a desiccated man who had clearly resolved never to be surprised, cleared his throat and began. \"To my nephew Hugo, I leave my collection of porcelain cats, in the hope that he will finally learn to admire something that doesn't answer back.\"", "A discreet cough escaped from the back row. The solicitor continued. \"To my niece Beatrice, I leave my pearls, which are, I regret to say, glass; she may take comfort in having admired them for forty years without ever once enquiring.\" Beatrice's face performed a series of expressions of remarkable range.", "As the bequests continued, a pattern emerged. Each gift contained a small, affectionate insult, each aimed with the accuracy of a woman who had observed her family with amused devotion for eighty years. By the end, the assembled relatives were laughing so hard that the solicitor, for the first time in his career, allowed himself a smile.", "The final clause was the shortest. \"To anyone who cried: you shall find, in the biscuit tin, a cheque for five hundred pounds, and my apologies for having tricked you into feeling something.\" Nobody moved for a moment. Then, one by one, the family rose and, with some embarrassment, went to look in the biscuit tin."], "paragraphs_pt": ["O testamento da tia Cordelia foi lido numa sala forrada de mogno com cheiro de polidor de limão, diante de uma família reunida menos por luto do que por curiosidade coletiva sobre a prataria. O advogado, um homem ressecado que claramente decidira jamais se surpreender, limpou a garganta e começou. \"Ao meu sobrinho Hugo, deixo minha coleção de gatos de porcelana, na esperança de que finalmente aprenda a admirar algo que não responde.\"", "Uma tosse discreta escapou da última fila. O advogado continuou. \"À minha sobrinha Beatrice, deixo minhas pérolas, que são, lamento dizer, de vidro; que se console por tê-las admirado por quarenta anos sem nunca perguntar.\" O rosto de Beatrice executou uma série de expressões de notável variedade.", "À medida que os legados prosseguiam, um padrão surgiu. Cada presente continha um pequeno insulto afetuoso, todos mirados com a precisão de uma mulher que observara a família com devoção divertida por oitenta anos. No fim, os parentes riam tanto que o advogado, pela primeira vez na carreira, permitiu-se um sorriso.", "A cláusula final foi a mais curta. \"A quem chorou: encontrarão na lata de biscoitos um cheque de quinhentas libras e minhas desculpas por tê-los enganado a sentir algo.\" Ninguém se moveu por um momento. Então, um a um, a família se levantou e, com certo embaraço, foi olhar na lata de biscoitos."], "hard_words": ["solicitor", "bequests", "clause", "desiccated"], "vocab": [{"word": "will", "meaning": "testamento", "note": ""}, {"word": "mahogany", "meaning": "mogno", "note": ""}, {"word": "solicitor", "meaning": "advogado", "note": ""}, {"word": "desiccated", "meaning": "ressecado", "note": ""}, {"word": "bequests", "meaning": "legados", "note": ""}, {"word": "pearls", "meaning": "pérolas", "note": ""}, {"word": "clause", "meaning": "cláusula", "note": ""}, {"word": "biscuit tin", "meaning": "lata de biscoitos", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "are", "were"], "irregular": ["panelled", "assembled", "desiccated", "had", "resolved", "surprised", "cleared", "began", "escaped", "continued", "admired", "performed", "emerged", "contained", "aimed", "observed", "amused", "allowed", "cried", "tricked", "moved", "rose", "went"], "phrasal": ["cleared his throat", "answer back"], "wh": ["who", "which"], "connectors": ["and", "so", "then", "before", "finally", "once", "as"], "comparative": []}, "word_meanings": [{"word": "will", "meaning": "testamento", "note": ""}, {"word": "mahogany", "meaning": "mogno", "note": ""}, {"word": "solicitor", "meaning": "advogado", "note": ""}, {"word": "desiccated", "meaning": "ressecado", "note": ""}, {"word": "bequests", "meaning": "legados", "note": ""}, {"word": "pearls", "meaning": "pérolas", "note": ""}, {"word": "clause", "meaning": "cláusula", "note": ""}, {"word": "biscuit tin", "meaning": "lata de biscoitos", "note": ""}], "exercises": {"grammar": [{"point": "Less out of... than out of", "explanation_pt": "'less out of grief than out of curiosity' compara motivos."}, {"point": "Relative clause com had", "explanation_pt": "'a woman who had observed her family' dá contexto anterior."}], "multiple_choice": [{"question": "Where was the will read?", "options": ["A garden", "A church", "A mahogany-panelled room", "A cafe"], "correct_index": 2, "explanation": "Numa sala de mogno."}, {"question": "What was Hugo's gift?", "options": ["Porcelain cats", "Silver", "Money", "Pearls"], "correct_index": 0, "explanation": "Gatos de porcelana."}, {"question": "What was wrong with the pearls?", "options": ["They were stolen", "They were lost", "They were glass", "They were small"], "correct_index": 2, "explanation": "Eram de vidro."}, {"question": "What was the pattern?", "options": ["All were silver", "Each gift had a small affectionate insult", "All were cats", "All gifts were money"], "correct_index": 1, "explanation": "Cada presente tinha um insulto afetuoso."}, {"question": "What was the final clause?", "options": ["A cat for all", "An apology only", "A house", "A cheque for those who cried"], "correct_index": 3, "explanation": "Um cheque para quem chorou."}], "open_questions": [{"question": "Is humour a good way to say goodbye?", "key_points_pt": ["debater"]}, {"question": "What would you leave in a will as a joke?", "key_points_pt": ["imaginar"]}]}}, {"level": "B1", "genre": "neutral", "title": "The Neighbour Who Never Spoke", "paragraphs": ["When Hana moved into her new apartment, she was told that the woman next door, Mrs. Ito, never spoke to anyone. She was around eighty, lived alone and went out only to buy groceries. People described her as unfriendly, and Hana decided not to bother her.", "One Sunday, however, Hana found a small plant on her doorstep. There was no note, but she guessed it was from Mrs. Ito, since she had noticed the same kind of plants on her balcony. Not knowing what to do, Hana baked a cake and left a slice by the neighbour's door.", "The next weekend, a second plant appeared, and then a handwritten recipe. Gradually they started to communicate through small gifts, and then through a word or two in the corridor. Mrs. Ito's voice was low and soft, and she spoke slowly, as though she had forgotten how.", "One evening, Hana finally knocked on her door. Mrs. Ito invited her in for tea. \"I was not unfriendly,\" she explained. \"I was waiting for someone who was not in a hurry.\" They talked for three hours."], "paragraphs_pt": ["Quando Hana se mudou para o novo apartamento, disseram-lhe que a mulher ao lado, a Sra. Ito, nunca falava com ninguém. Tinha uns oitenta anos, morava sozinha e só saía para fazer compras. As pessoas a descreviam como antipática, e Hana decidiu não incomodá-la.", "Num domingo, porém, Hana achou uma plantinha na porta. Não havia bilhete, mas imaginou que fosse da Sra. Ito, pois notara o mesmo tipo de planta na varanda dela. Sem saber o que fazer, Hana assou um bolo e deixou uma fatia na porta da vizinha.", "No fim de semana seguinte apareceu uma segunda planta, depois uma receita escrita à mão. Aos poucos começaram a se comunicar por pequenos presentes e depois por uma palavra ou duas no corredor. A voz da Sra. Ito era baixa e suave, e ela falava devagar, como se tivesse esquecido como.", "Numa noite, Hana finalmente bateu à porta dela. A Sra. Ito a convidou para um chá. \"Eu não era antipática\", explicou. \"Estava esperando alguém que não tivesse pressa.\" Conversaram por três horas."], "hard_words": ["groceries", "doorstep", "gradually", "corridor"], "vocab": [{"word": "neighbour", "meaning": "vizinha", "note": ""}, {"word": "groceries", "meaning": "compras de mercado", "note": ""}, {"word": "unfriendly", "meaning": "antipática", "note": ""}, {"word": "doorstep", "meaning": "soleira", "note": ""}, {"word": "balcony", "meaning": "varanda", "note": ""}, {"word": "corridor", "meaning": "corredor", "note": ""}, {"word": "gradually", "meaning": "aos poucos", "note": ""}, {"word": "invited", "meaning": "convidou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["moved", "told", "spoke", "lived", "went", "described", "decided", "found", "guessed", "had", "noticed", "baked", "left", "appeared", "started", "forgotten", "knocked", "invited", "explained", "talked"], "phrasal": ["moved into", "went out"], "wh": ["who", "what", "when", "how"], "connectors": ["and", "but", "however", "though", "then", "when", "since", "or", "finally", "as"], "comparative": []}, "word_meanings": [{"word": "neighbour", "meaning": "vizinha", "note": ""}, {"word": "groceries", "meaning": "compras de mercado", "note": ""}, {"word": "unfriendly", "meaning": "antipática", "note": ""}, {"word": "doorstep", "meaning": "soleira", "note": ""}, {"word": "balcony", "meaning": "varanda", "note": ""}, {"word": "corridor", "meaning": "corredor", "note": ""}, {"word": "gradually", "meaning": "aos poucos", "note": ""}, {"word": "invited", "meaning": "convidou", "note": ""}], "exercises": {"grammar": [{"point": "Past simple e past perfect", "explanation_pt": "'she had noticed the same kind of plants' mostra algo percebido antes."}, {"point": "Reported speech", "explanation_pt": "'she was told that the woman never spoke' reproduz informação de outros."}], "multiple_choice": [{"question": "What did people say about Mrs. Ito?", "options": ["She was a teacher", "She was unfriendly", "She was rich", "She was funny"], "correct_index": 1, "explanation": "Diziam que era antipática."}, {"question": "What did Hana find?", "options": ["A letter", "A key", "A cake", "A small plant"], "correct_index": 3, "explanation": "Uma plantinha."}, {"question": "What did Hana do?", "options": ["Ignored it", "Called the police", "Baked a cake", "Moved"], "correct_index": 2, "explanation": "Assou um bolo."}, {"question": "How did they communicate?", "options": ["Through small gifts", "By shouting", "By email", "By phone"], "correct_index": 0, "explanation": "Por pequenos presentes."}, {"question": "What did Mrs. Ito explain?", "options": ["She was ill", "She hated people", "She waited for someone not in a hurry", "She was shy of cakes"], "correct_index": 2, "explanation": "Esperava alguém sem pressa."}], "open_questions": [{"question": "Do you know your neighbours?", "key_points_pt": ["falar"]}, {"question": "How can small gestures build friendship?", "key_points_pt": ["explicar"]}]}}, {"level": "B1", "genre": "neutral", "title": "A Day Without Phones", "paragraphs": ["When the electricity failed in the whole city on a Thursday morning, nobody could use their phones or the Internet. Carla, who worked as a designer, tried to call her boss, and then her friends, but nothing worked. She sat for a few minutes, not knowing what to do.", "Finally, she picked up a book that had been lying on her shelf for months and went to the park. It was strange to see so many people without screens. A group of men were playing chess, a couple was sharing a sandwich and children were drawing on the pavement with chalk.", "She started talking to an elderly man on a bench, who told her about the city when he was young. \"We did this every day,\" he laughed. \"We just talked.\" Carla stayed there for three hours, and she did not look at the time once.", "When the power returned in the evening, everybody checked their phones at the same time. Carla had forty messages, but she read them slowly. She promised herself she would leave the phone at home once a week. She kept the promise for almost a month."], "paragraphs_pt": ["Quando a eletricidade falhou na cidade inteira numa manhã de quinta, ninguém podia usar o celular ou a internet. Carla, que trabalhava como designer, tentou ligar para a chefe e depois para os amigos, mas nada funcionava. Ficou sentada alguns minutos sem saber o que fazer.", "Por fim, pegou um livro que estava na prateleira havia meses e foi ao parque. Era estranho ver tanta gente sem telas. Um grupo de homens jogava xadrez, um casal dividia um sanduíche e crianças desenhavam no chão com giz.", "Começou a conversar com um senhor idoso num banco, que lhe contou como era a cidade quando ele era jovem. \"Fazíamos isso todo dia\", riu. \"Só conversávamos.\" Carla ficou lá por três horas e não olhou a hora nenhuma vez.", "Quando a energia voltou à noite, todos checaram os celulares ao mesmo tempo. Carla tinha quarenta mensagens, mas as leu devagar. Prometeu a si mesma deixar o celular em casa uma vez por semana. Cumpriu a promessa por quase um mês."], "hard_words": ["electricity", "pavement", "chalk", "elderly"], "vocab": [{"word": "electricity", "meaning": "eletricidade", "note": ""}, {"word": "failed", "meaning": "falhou", "note": ""}, {"word": "designer", "meaning": "designer", "note": ""}, {"word": "screens", "meaning": "telas", "note": ""}, {"word": "pavement", "meaning": "calçada", "note": ""}, {"word": "chalk", "meaning": "giz", "note": ""}, {"word": "elderly", "meaning": "idoso", "note": ""}, {"word": "promise", "meaning": "promessa", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "were"], "irregular": ["failed", "could", "worked", "tried", "sat", "picked", "had", "went", "started", "told", "did", "laughed", "talked", "stayed", "returned", "checked", "promised", "would", "kept"], "phrasal": ["picked up"], "wh": ["who", "what", "when"], "connectors": ["and", "but", "so", "then", "when", "or", "finally", "once", "as"], "comparative": []}, "word_meanings": [{"word": "electricity", "meaning": "eletricidade", "note": ""}, {"word": "failed", "meaning": "falhou", "note": ""}, {"word": "designer", "meaning": "designer", "note": ""}, {"word": "screens", "meaning": "telas", "note": ""}, {"word": "pavement", "meaning": "calçada", "note": ""}, {"word": "chalk", "meaning": "giz", "note": ""}, {"word": "elderly", "meaning": "idoso", "note": ""}, {"word": "promise", "meaning": "promessa", "note": ""}], "exercises": {"grammar": [{"point": "Past simple e past perfect", "explanation_pt": "'a book that had been lying on her shelf' mostra um estado anterior."}, {"point": "Reported speech", "explanation_pt": "'who told her about the city' reproduz o que foi dito."}], "multiple_choice": [{"question": "What happened on Thursday?", "options": ["A strike began", "A festival started", "A storm came", "The electricity failed"], "correct_index": 3, "explanation": "A eletricidade falhou."}, {"question": "What did Carla take to the park?", "options": ["A cake", "A camera", "A book", "A laptop"], "correct_index": 2, "explanation": "Um livro."}, {"question": "What did people do in the park?", "options": ["Slept", "Shouted", "Worked", "Played chess, shared food, drew"], "correct_index": 3, "explanation": "Jogavam xadrez, dividiam comida, desenhavam."}, {"question": "What did the elderly man tell her?", "options": ["About his job", "About the city when he was young", "About football", "About politics"], "correct_index": 1, "explanation": "Contou como era a cidade."}, {"question": "What did Carla promise?", "options": ["To quit her job", "To live in the park", "To leave her phone home weekly", "To buy a new phone"], "correct_index": 2, "explanation": "Deixar o celular em casa uma vez por semana."}], "open_questions": [{"question": "How would you spend a day without phones?", "key_points_pt": ["imaginar"]}, {"question": "Do phones help or harm communication?", "key_points_pt": ["debater"]}]}}, {"level": "B2", "genre": "neutral", "title": "The Last Train Home", "paragraphs": ["The last train to Marlow had always been a peculiar institution: a quiet, half-empty carriage that carried tired office workers, students returning from late classes and the occasional night-shift nurse. Over the years, Sunita had memorised its rhythms, the creak at the second bridge, the flicker of the third light, and the elderly conductor who greeted everyone by name.", "Tonight, though, something was different. The conductor was absent, replaced by a young man who seemed anxious. The train also stopped unexpectedly between two stations, and the lights went out. For a few seconds, nobody said a word. Then a child began to cry, and the carriage seemed to wake up.", "Strangers who had shared the same bench for years without a glance started talking. A nurse checked the child's temperature; a student lent his phone to light the carriage; an old man told a story to calm everyone. When the lights returned an hour later, nobody wanted to leave the conversation.", "Sunita realised that familiarity had been a kind of isolation, a polite agreement to remain invisible. In the following weeks, the passengers began to greet each other, to share umbrellas and newspapers, and the conductor, who had been ill, returned to find a train transformed. \"I only ever wanted,\" he said, \"for them to notice each other.\""], "paragraphs_pt": ["O último trem para Marlow sempre fora uma instituição peculiar: um vagão silencioso e meio vazio que levava trabalhadores cansados, estudantes voltando de aulas noturnas e eventualmente uma enfermeira do plantão da noite. Com os anos, Sunita memorizara seus ritmos: o rangido na segunda ponte, o piscar da terceira luz e o velho condutor que cumprimentava todos pelo nome.", "Esta noite, porém, algo era diferente. O condutor estava ausente, substituído por um jovem que parecia ansioso. O trem também parou inesperadamente entre duas estações e as luzes se apagaram. Por alguns segundos, ninguém disse uma palavra. Então uma criança começou a chorar e o vagão pareceu acordar.", "Estranhos que dividiam o mesmo banco havia anos sem trocar um olhar começaram a conversar. Uma enfermeira verificou a temperatura da criança; um estudante emprestou o celular para iluminar o vagão; um velho contou uma história para acalmar todos. Quando as luzes voltaram, uma hora depois, ninguém queria sair da conversa.", "Sunita percebeu que a familiaridade fora um tipo de isolamento, um acordo educado para permanecer invisível. Nas semanas seguintes, os passageiros passaram a se cumprimentar, a dividir guarda-chuvas e jornais, e o condutor, que estivera doente, voltou e encontrou um trem transformado. \"Eu só queria\", disse, \"que eles se notassem.\""], "hard_words": ["peculiar", "flicker", "familiarity", "isolation"], "vocab": [{"word": "peculiar", "meaning": "peculiar", "note": ""}, {"word": "carriage", "meaning": "vagão", "note": ""}, {"word": "conductor", "meaning": "condutor, cobrador", "note": ""}, {"word": "memorised", "meaning": "memorizou", "note": ""}, {"word": "flicker", "meaning": "piscar", "note": ""}, {"word": "anxious", "meaning": "ansioso", "note": ""}, {"word": "familiarity", "meaning": "familiaridade", "note": ""}, {"word": "isolation", "meaning": "isolamento", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was"], "irregular": ["had", "carried", "tired", "memorised", "greeted", "replaced", "seemed", "stopped", "went", "said", "began", "shared", "started", "checked", "lent", "told", "returned", "wanted", "realised", "transformed"], "phrasal": ["went out"], "wh": ["who", "when"], "connectors": ["and", "though", "then", "when", "also"], "comparative": []}, "word_meanings": [{"word": "peculiar", "meaning": "peculiar", "note": ""}, {"word": "carriage", "meaning": "vagão", "note": ""}, {"word": "conductor", "meaning": "condutor, cobrador", "note": ""}, {"word": "memorised", "meaning": "memorizou", "note": ""}, {"word": "flicker", "meaning": "piscar", "note": ""}, {"word": "anxious", "meaning": "ansioso", "note": ""}, {"word": "familiarity", "meaning": "familiaridade", "note": ""}, {"word": "isolation", "meaning": "isolamento", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Sunita had memorised its rhythms' indica um conhecimento anterior."}, {"point": "Not... but", "explanation_pt": "'a polite agreement to remain invisible' define familiaridade como isolamento."}], "multiple_choice": [{"question": "What was the last train like?", "options": ["Loud and full", "Dirty and unsafe", "Fast and new", "Quiet and half-empty"], "correct_index": 3, "explanation": "Silencioso e meio vazio."}, {"question": "What was different tonight?", "options": ["It was faster", "The conductor was absent and the train stopped", "It was free", "It was early"], "correct_index": 1, "explanation": "O condutor estava ausente e o trem parou."}, {"question": "What did passengers do?", "options": ["Complained", "Left", "Started talking and helping", "Slept"], "correct_index": 2, "explanation": "Começaram a conversar e ajudar."}, {"question": "What did Sunita realise?", "options": ["Trains are slow", "Lights are weak", "Familiarity can be isolation", "People are rude"], "correct_index": 2, "explanation": "Familiaridade pode ser isolamento."}, {"question": "What did the conductor say?", "options": ["He wanted silence", "He wanted money", "He wanted a new job", "He wanted them to notice each other"], "correct_index": 3, "explanation": "Queria que se notassem."}], "open_questions": [{"question": "Why do we ignore people we see every day?", "key_points_pt": ["discutir"]}, {"question": "How can public spaces encourage connection?", "key_points_pt": ["propor"]}]}}, {"level": "B2", "genre": "neutral", "title": "The Weight of a Suitcase", "paragraphs": ["Marcos had packed and unpacked his suitcase six times before dawn. Tomorrow, he would leave the town where he was born to study engineering abroad, and the realisation had turned the simple act of folding shirts into something almost unbearable. His mother, who had worked two jobs to support him, kept appearing in the doorway with food he did not want.", "\"You'll need this,\" she said, handing him a small jar of her homemade jam. He tried to refuse, citing the baggage limit, but she put it in his hand with a determined look. Eventually, he squeezed it in between his socks, aware that he was carrying more than a jar.", "At the airport, there were no dramatic farewells. His mother adjusted his collar and told him to eat well, as if he were going on a two-day trip. Only when he turned at the security gate and saw her small figure waving did he realise that her composure was the final gift she could give him.", "Months later, in a cold kitchen in a foreign city, Marcos opened the jar. The taste of the jam brought back the smell of the house, the radio in the background, the sound of his mother humming. He did not cry, but he stayed at the table for a long time, understanding finally that some weights are not meant to be lightened."], "paragraphs_pt": ["Marcos fizera e desfizera a mala seis vezes antes do amanhecer. Amanhã deixaria a cidade onde nasceu para estudar engenharia no exterior, e a percepção transformara o simples ato de dobrar camisas em algo quase insuportável. A mãe, que tivera dois empregos para sustentá-lo, aparecia na porta com comida que ele não queria.", "\"Você vai precisar disto\", disse ela, entregando-lhe um pote de geleia caseira. Ele tentou recusar, citando o limite de bagagem, mas ela o colocou na mão dele com um olhar decidido. Por fim, ele o enfiou entre as meias, ciente de que levava mais que um pote.", "No aeroporto, não houve despedidas dramáticas. A mãe ajeitou-lhe a gola e disse que comesse bem, como se fosse uma viagem de dois dias. Só quando se virou no portão de segurança e viu a figura pequena dela acenando, percebeu que a compostura dela era o último presente que podia lhe dar.", "Meses depois, numa cozinha fria numa cidade estrangeira, Marcos abriu o pote. O sabor da geleia trouxe de volta o cheiro da casa, o rádio ao fundo, o som da mãe cantarolando. Não chorou, mas ficou à mesa por muito tempo, entendendo enfim que alguns pesos não existem para serem aliviados."], "hard_words": ["unbearable", "baggage", "composure", "humming"], "vocab": [{"word": "packed", "meaning": "fez a mala", "note": ""}, {"word": "unbearable", "meaning": "insuportável", "note": ""}, {"word": "jam", "meaning": "geleia", "note": ""}, {"word": "baggage", "meaning": "bagagem", "note": ""}, {"word": "squeezed", "meaning": "espremeu", "note": ""}, {"word": "farewells", "meaning": "despedidas", "note": ""}, {"word": "composure", "meaning": "compostura", "note": ""}, {"word": "humming", "meaning": "cantarolando", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "are", "be"], "irregular": ["had", "packed", "unpacked", "would", "born", "turned", "worked", "kept", "did", "said", "tried", "determined", "squeezed", "adjusted", "told", "saw", "could", "opened", "brought", "stayed", "meant", "lightened"], "phrasal": ["turned at", "brought back"], "wh": ["who", "where", "when"], "connectors": ["and", "but", "before", "when", "finally", "if", "as"], "comparative": []}, "word_meanings": [{"word": "packed", "meaning": "fez a mala", "note": ""}, {"word": "unbearable", "meaning": "insuportável", "note": ""}, {"word": "jam", "meaning": "geleia", "note": ""}, {"word": "baggage", "meaning": "bagagem", "note": ""}, {"word": "squeezed", "meaning": "espremeu", "note": ""}, {"word": "farewells", "meaning": "despedidas", "note": ""}, {"word": "composure", "meaning": "compostura", "note": ""}, {"word": "humming", "meaning": "cantarolando", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had packed and unpacked' mostra uma ação repetida antes do amanhecer."}, {"point": "As if + passado", "explanation_pt": "'as if he were going on a two-day trip' compara com uma situação irreal."}], "multiple_choice": [{"question": "What was Marcos about to do?", "options": ["Start a job", "Get married", "Retire", "Study abroad"], "correct_index": 3, "explanation": "Estudar no exterior."}, {"question": "What did his mother give him?", "options": ["A jar of jam", "Money", "A coat", "A book"], "correct_index": 0, "explanation": "Um pote de geleia."}, {"question": "How was the farewell?", "options": ["Violent", "Silent", "Very loud", "Not dramatic"], "correct_index": 3, "explanation": "Sem drama."}, {"question": "What did he realise at the gate?", "options": ["She was sad", "Her composure was a gift", "She was angry", "She was late"], "correct_index": 1, "explanation": "A compostura era um presente."}, {"question": "What happened months later?", "options": ["He returned", "He lost the jar", "He gave it away", "He opened the jam and remembered home"], "correct_index": 3, "explanation": "Abriu a geleia e lembrou de casa."}], "open_questions": [{"question": "What objects carry memories for you?", "key_points_pt": ["descrever"]}, {"question": "How do families express love without words?", "key_points_pt": ["discutir"]}]}}, {"level": "C1", "genre": "neutral", "title": "The Quiet Revolution of Tuesday", "paragraphs": ["Nobody in the office remembered who first suggested it, but by the autumn, Tuesday afternoons had become unofficially sacred. For two hours, the phones were silenced, the meetings suspended and the staff were encouraged to do something that appeared, to the untrained eye, like nothing: reading, walking or staring at the river from the window.", "Management, naturally, was sceptical. The first quarterly report after the experiment was awaited with the anxiety of an examination. Yet the figures, to everybody's surprise, had improved. Errors fell; resignations dropped; the corridor conversations, formerly confined to complaints, acquired a faint warmth. A colleague who had not spoken for months about anything but invoices was heard describing a novel.", "It would be tempting to credit the policy itself, but the explanation was probably subtler. The two hours had not given people time; they had given them permission, a licence to be something other than productive. The effect was less like a holiday than like the removal of a pebble from a shoe one had forgotten was there.", "When a new director later proposed cancelling the practice for efficiency, the staff did not protest loudly. They simply invited her, one Tuesday, to join them at the window. She stayed for the full two hours and, afterwards, withdrew the proposal without comment, as people do when a question has been answered more thoroughly than words could manage."], "paragraphs_pt": ["Ninguém no escritório lembrava quem sugerira primeiro, mas no outono as tardes de terça tornaram-se extraoficialmente sagradas. Por duas horas, os telefones eram silenciados, as reuniões suspensas e os funcionários eram incentivados a fazer algo que parecia, ao olhar desinformado, nada: ler, caminhar ou olhar o rio pela janela.", "A gerência, naturalmente, estava cética. O primeiro relatório trimestral depois do experimento foi aguardado com a ansiedade de uma prova. Mas os números, para surpresa geral, haviam melhorado. Os erros caíram; as demissões diminuíram; as conversas de corredor, antes restritas a queixas, ganharam um calor tênue. Um colega que meses não falava de nada além de faturas foi ouvido descrevendo um romance.", "Seria tentador creditar a política em si, mas a explicação provavelmente era mais sutil. As duas horas não deram tempo às pessoas; deram-lhes permissão, uma licença para ser algo além de produtivas. O efeito foi menos como férias do que como retirar do sapato uma pedrinha que se esquecera estar ali.", "Quando uma nova diretora propôs depois cancelar a prática por eficiência, os funcionários não protestaram em voz alta. Apenas a convidaram, numa terça, a se juntar a eles na janela. Ela ficou as duas horas inteiras e, depois, retirou a proposta sem comentar, como fazem as pessoas quando uma pergunta foi respondida mais plenamente do que palavras conseguiriam."], "hard_words": ["sacred", "sceptical", "confined", "withdrew"], "vocab": [{"word": "sacred", "meaning": "sagrado", "note": ""}, {"word": "suspended", "meaning": "suspensas", "note": ""}, {"word": "sceptical", "meaning": "cético", "note": ""}, {"word": "resignations", "meaning": "demissões (pedidos)", "note": ""}, {"word": "confined", "meaning": "restritas", "note": ""}, {"word": "invoices", "meaning": "faturas", "note": ""}, {"word": "permission", "meaning": "permissão", "note": ""}, {"word": "withdrew", "meaning": "retirou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was", "be", "been"], "irregular": ["remembered", "suggested", "had", "silenced", "suspended", "encouraged", "appeared", "awaited", "improved", "fell", "dropped", "confined", "acquired", "spoken", "heard", "would", "given", "forgotten", "proposed", "did", "invited", "stayed", "withdrew", "answered", "could"], "phrasal": ["join them"], "wh": ["who", "when"], "connectors": ["and", "but", "after", "when", "yet", "or", "as"], "comparative": []}, "word_meanings": [{"word": "sacred", "meaning": "sagrado", "note": ""}, {"word": "suspended", "meaning": "suspensas", "note": ""}, {"word": "sceptical", "meaning": "cético", "note": ""}, {"word": "resignations", "meaning": "demissões (pedidos)", "note": ""}, {"word": "confined", "meaning": "restritas", "note": ""}, {"word": "invoices", "meaning": "faturas", "note": ""}, {"word": "permission", "meaning": "permissão", "note": ""}, {"word": "withdrew", "meaning": "retirou", "note": ""}], "exercises": {"grammar": [{"point": "Less like... than like", "explanation_pt": "'less like a holiday than like the removal of a pebble' compara duas imagens, preferindo a segunda."}, {"point": "Past perfect", "explanation_pt": "'had not given people time; they had given them permission' contrasta o que foi feito."}], "multiple_choice": [{"question": "What happened on Tuesday afternoons?", "options": ["Offices closed", "Meetings doubled", "Staff worked longer", "Phones were silenced and staff rested"], "correct_index": 3, "explanation": "Telefones silenciados e descanso."}, {"question": "What happened to the figures?", "options": ["They disappeared", "They fell", "They stayed same", "They improved"], "correct_index": 3, "explanation": "Melhoraram."}, {"question": "What did the two hours give people?", "options": ["Training", "Money", "Permission", "Promotion"], "correct_index": 2, "explanation": "Permissão."}, {"question": "What did the new director propose?", "options": ["Extending it", "Moving it", "Paying for it", "Cancelling the practice"], "correct_index": 3, "explanation": "Cancelar a prática."}, {"question": "How did the staff respond?", "options": ["They hid", "They quit", "They invited her to the window", "They protested"], "correct_index": 2, "explanation": "Convidaram-na à janela."}], "open_questions": [{"question": "Is rest a form of productivity?", "key_points_pt": ["debater"]}, {"question": "What would you do with two quiet hours weekly?", "key_points_pt": ["imaginar"]}]}}, {"level": "C2", "genre": "neutral", "title": "The Cartography of Small Mercies", "paragraphs": ["Years later, when asked what had saved him during that dismal winter, Ivo would not mention medicine, nor philosophy, nor the comfort of religion. He would speak, with some embarrassment, of the baker on Calle Rivera who never failed to slip a free roll into his bag, saying nothing, and of the librarian who stamped his overdue books without so much as a glance at the date.", "These were not grand acts. They would never be cited in a biography of virtue, nor commemorated with statues. Yet Ivo, who had always believed that salvation must announce itself, learned to read the quieter grammar of mercy: a held door, a pardoned error, a question gently omitted. Each, taken alone, was negligible; together they formed a map by which a lost man could find his way.", "What struck him afterwards was the discretion of it all. The baker never asked why Ivo was thinner; the librarian never inquired after his silence. They had understood that to be seen too clearly is sometimes a burden, and that the best kindness leaves the recipient his dignity intact. In an age enamoured of declarations, their restraint seemed almost revolutionary.", "Ivo returned, in spring, to thank them. The baker waved him off with a gruff \"What for?\" and the librarian pretended not to remember. He understood, then, that mercy is complete only when it is not recorded, and that the debts it creates are repaid not to the creditor but forward, to whoever next happens to be lost."], "paragraphs_pt": ["Anos depois, quando lhe perguntavam o que o salvara naquele inverno sombrio, Ivo não mencionava remédios, nem filosofia, nem o consolo da religião. Falava, com certo embaraço, do padeiro da Calle Rivera que nunca deixava de colocar um pãozinho de graça na sua sacola, sem dizer nada, e da bibliotecária que carimbava seus livros atrasados sem sequer olhar a data.", "Eram atos pequenos. Jamais seriam citados numa biografia da virtude nem comemorados com estátuas. Mas Ivo, que sempre acreditara que a salvação deveria se anunciar, aprendeu a ler a gramática mais silenciosa da misericórdia: uma porta segurada, um erro perdoado, uma pergunta gentilmente omitida. Cada um, isolado, era desprezível; juntos formavam um mapa pelo qual um homem perdido podia encontrar o caminho.", "O que o impressionou depois foi a discrição de tudo. O padeiro nunca perguntou por que Ivo estava mais magro; a bibliotecária nunca indagou sobre seu silêncio. Haviam entendido que ser visto com clareza demais às vezes é um fardo e que a melhor bondade deixa a dignidade do receptor intacta. Numa era enamorada de declarações, a contenção deles parecia quase revolucionária.", "Ivo voltou, na primavera, para agradecer. O padeiro o dispensou com um \"Por quê?\" áspero e a bibliotecária fingiu não lembrar. Entendeu então que a misericórdia só é completa quando não é registrada e que as dívidas que ela cria são pagas não ao credor, mas adiante, a quem calhar de estar perdido em seguida."], "hard_words": ["dismal", "negligible", "discretion", "gruff"], "vocab": [{"word": "dismal", "meaning": "sombrio", "note": ""}, {"word": "embarrassment", "meaning": "embaraço", "note": ""}, {"word": "overdue", "meaning": "atrasados", "note": ""}, {"word": "commemorated", "meaning": "comemorados", "note": ""}, {"word": "negligible", "meaning": "desprezível", "note": ""}, {"word": "discretion", "meaning": "discrição", "note": ""}, {"word": "enamoured", "meaning": "enamorada", "note": ""}, {"word": "gruff", "meaning": "áspero", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "be", "was", "is", "are"], "irregular": ["asked", "had", "saved", "would", "failed", "stamped", "cited", "commemorated", "believed", "learned", "held", "pardoned", "omitted", "taken", "formed", "lost", "could", "struck", "inquired", "understood", "seen", "enamoured", "seemed", "returned", "waved", "pretended", "recorded", "repaid"], "phrasal": [], "wh": ["who", "what", "when", "why", "which", "whoever"], "connectors": ["and", "but", "so", "then", "after", "when", "yet", "as"], "comparative": []}, "word_meanings": [{"word": "dismal", "meaning": "sombrio", "note": ""}, {"word": "embarrassment", "meaning": "embaraço", "note": ""}, {"word": "overdue", "meaning": "atrasados", "note": ""}, {"word": "commemorated", "meaning": "comemorados", "note": ""}, {"word": "negligible", "meaning": "desprezível", "note": ""}, {"word": "discretion", "meaning": "discrição", "note": ""}, {"word": "enamoured", "meaning": "enamorada", "note": ""}, {"word": "gruff", "meaning": "áspero", "note": ""}], "exercises": {"grammar": [{"point": "Not... nor", "explanation_pt": "'would not mention medicine, nor philosophy, nor the comfort of religion' nega uma lista."}, {"point": "Only when", "explanation_pt": "'complete only when it is not recorded' marca a condição única."}], "multiple_choice": [{"question": "What saved Ivo in winter?", "options": ["Philosophy", "Medicine", "Religion", "Small kindnesses"], "correct_index": 3, "explanation": "Pequenas bondades."}, {"question": "What did the baker do?", "options": ["Talked to him", "Gave him money", "Slipped a free roll in his bag", "Offered work"], "correct_index": 2, "explanation": "Colocava um pãozinho grátis."}, {"question": "What did the librarian do?", "options": ["Fined him", "Closed the library", "Called him", "Ignored the overdue date"], "correct_index": 3, "explanation": "Ignorava o atraso."}, {"question": "What did they never do?", "options": ["Say hello", "Open early", "Ask about his situation", "Give gifts"], "correct_index": 2, "explanation": "Nunca perguntaram."}, {"question": "How is mercy repaid?", "options": ["Forward to whoever is lost next", "In money", "To the creditor", "With statues"], "correct_index": 0, "explanation": "Adiante, a quem estiver perdido."}], "open_questions": [{"question": "Why does discreet kindness feel different from public kindness?", "key_points_pt": ["discutir"]}, {"question": "Who has helped you quietly?", "key_points_pt": ["refletir"]}]}}, {"level": "A1", "genre": "news", "title": "A Dog Finds a Boy", "paragraphs": ["A boy is lost in a park. His name is Pedro. He is five years old. It is dark, and he is afraid.", "A big dog finds Pedro. The dog stays with him. The dog barks very loud.", "People hear the dog. They come and find Pedro. His mother cries and hugs him. \"Thank you, dog!\" she says."], "paragraphs_pt": ["Um menino está perdido num parque. O nome dele é Pedro. Ele tem cinco anos. Está escuro e ele tem medo.", "Um cachorro grande encontra Pedro. O cachorro fica com ele. O cachorro late muito alto.", "As pessoas ouvem o cachorro. Elas vêm e encontram Pedro. A mãe dele chora e o abraça. \"Obrigada, cachorro!\", ela diz."], "hard_words": ["lost", "dark", "barks", "hugs"], "vocab": [{"word": "lost", "meaning": "perdido", "note": ""}, {"word": "park", "meaning": "parque", "note": ""}, {"word": "dark", "meaning": "escuro", "note": ""}, {"word": "afraid", "meaning": "com medo", "note": ""}, {"word": "barks", "meaning": "late", "note": ""}, {"word": "hugs", "meaning": "abraça", "note": ""}, {"word": "mother", "meaning": "mãe", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": ["lost"], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "lost", "meaning": "perdido", "note": ""}, {"word": "park", "meaning": "parque", "note": ""}, {"word": "dark", "meaning": "escuro", "note": ""}, {"word": "afraid", "meaning": "com medo", "note": ""}, {"word": "barks", "meaning": "late", "note": ""}, {"word": "hugs", "meaning": "abraça", "note": ""}, {"word": "mother", "meaning": "mãe", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "'The dog stays' e 'The dog barks' descrevem ações no presente."}], "multiple_choice": [{"question": "Where is Pedro lost?", "options": ["In a school", "In a car", "In a shop", "In a park"], "correct_index": 3, "explanation": "Num parque."}, {"question": "How old is Pedro?", "options": ["Ten", "Five", "Two", "Fifteen"], "correct_index": 1, "explanation": "Cinco anos."}, {"question": "Who finds Pedro?", "options": ["A bird", "A teacher", "A cat", "A dog"], "correct_index": 3, "explanation": "Um cachorro."}, {"question": "What does the dog do?", "options": ["Runs away", "Sleeps", "Eats", "Barks loud"], "correct_index": 3, "explanation": "Late alto."}, {"question": "How does his mother feel?", "options": ["Happy", "Bored", "Angry", "Sleepy"], "correct_index": 0, "explanation": "Fica feliz e chora."}], "open_questions": [{"question": "Have you been lost?", "key_points_pt": ["contar"]}, {"question": "How can dogs help people?", "key_points_pt": ["explicar"]}]}}, {"level": "A1", "genre": "news", "title": "The Big Rain", "paragraphs": ["There is a big rain in the city today. The streets are full of water. Many people stay at home.", "Schools are closed. Buses do not run. Children play with paper boats in the water.", "The rain will stop tomorrow. The sun will come. The city will be dry again."], "paragraphs_pt": ["Há uma grande chuva na cidade hoje. As ruas estão cheias de água. Muitas pessoas ficam em casa.", "As escolas estão fechadas. Os ônibus não circulam. As crianças brincam com barquinhos de papel na água.", "A chuva vai parar amanhã. O sol vai aparecer. A cidade estará seca de novo."], "hard_words": ["rain", "streets", "closed", "dry"], "vocab": [{"word": "rain", "meaning": "chuva", "note": ""}, {"word": "streets", "meaning": "ruas", "note": ""}, {"word": "water", "meaning": "água", "note": ""}, {"word": "closed", "meaning": "fechado", "note": ""}, {"word": "buses", "meaning": "ônibus", "note": ""}, {"word": "boats", "meaning": "barcos", "note": ""}, {"word": "dry", "meaning": "seco", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are", "be"], "irregular": ["closed"], "phrasal": [], "wh": [], "connectors": [], "comparative": []}, "word_meanings": [{"word": "rain", "meaning": "chuva", "note": ""}, {"word": "streets", "meaning": "ruas", "note": ""}, {"word": "water", "meaning": "água", "note": ""}, {"word": "closed", "meaning": "fechado", "note": ""}, {"word": "buses", "meaning": "ônibus", "note": ""}, {"word": "boats", "meaning": "barcos", "note": ""}, {"word": "dry", "meaning": "seco", "note": ""}], "exercises": {"grammar": [{"point": "Will", "explanation_pt": "'The rain will stop tomorrow' fala do futuro."}], "multiple_choice": [{"question": "What is big today?", "options": ["The sun", "The rain", "The wind", "The snow"], "correct_index": 1, "explanation": "A chuva."}, {"question": "What is full of water?", "options": ["The schools", "The streets", "The cars only", "The houses"], "correct_index": 1, "explanation": "As ruas."}, {"question": "What is closed?", "options": ["Schools", "Parks", "Shops", "Banks"], "correct_index": 0, "explanation": "As escolas."}, {"question": "What do children play with?", "options": ["Dolls", "Paper boats", "Balls", "Kites"], "correct_index": 1, "explanation": "Barquinhos de papel."}, {"question": "When will the rain stop?", "options": ["Tomorrow", "Never", "Tonight", "Next week"], "correct_index": 0, "explanation": "Amanhã."}], "open_questions": [{"question": "What do you do on rainy days?", "key_points_pt": ["descrever"]}, {"question": "Do you like rain?", "key_points_pt": ["opinar"]}]}}, {"level": "A1", "genre": "news", "title": "New Park Opens", "paragraphs": ["A new park opens today in our town. It is big and green. It has many trees and flowers.", "There is a playground for children. There is also a small lake with ducks. The park is free for everyone.", "The mayor cuts a red ribbon. Many families come. They are very happy. \"We love our new park!\" says a girl."], "paragraphs_pt": ["Um novo parque abre hoje na nossa cidade. É grande e verde. Tem muitas árvores e flores.", "Há um parquinho para crianças. Há também um pequeno lago com patos. O parque é grátis para todos.", "O prefeito corta uma fita vermelha. Muitas famílias vêm. Estão muito felizes. \"Amamos nosso novo parque!\", diz uma menina."], "hard_words": ["playground", "lake", "mayor", "ribbon"], "vocab": [{"word": "opens", "meaning": "abre", "note": ""}, {"word": "town", "meaning": "cidade pequena", "note": ""}, {"word": "playground", "meaning": "parquinho", "note": ""}, {"word": "lake", "meaning": "lago", "note": ""}, {"word": "ducks", "meaning": "patos", "note": ""}, {"word": "mayor", "meaning": "prefeito", "note": ""}, {"word": "ribbon", "meaning": "fita", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "also"], "comparative": []}, "word_meanings": [{"word": "opens", "meaning": "abre", "note": ""}, {"word": "town", "meaning": "cidade pequena", "note": ""}, {"word": "playground", "meaning": "parquinho", "note": ""}, {"word": "lake", "meaning": "lago", "note": ""}, {"word": "ducks", "meaning": "patos", "note": ""}, {"word": "mayor", "meaning": "prefeito", "note": ""}, {"word": "ribbon", "meaning": "fita", "note": ""}], "exercises": {"grammar": [{"point": "There is / There are", "explanation_pt": "'There is a playground' e 'There are many trees' descrevem o que existe."}], "multiple_choice": [{"question": "What opens today?", "options": ["A shop", "A school", "A bank", "A new park"], "correct_index": 3, "explanation": "Um novo parque."}, {"question": "What does the park have?", "options": ["Cars", "Trees and flowers", "A beach", "Tall buildings"], "correct_index": 1, "explanation": "Árvores e flores."}, {"question": "Who is the park for?", "options": ["Everyone, for free", "Tourists", "Children only", "The mayor"], "correct_index": 0, "explanation": "Para todos, grátis."}, {"question": "Who cuts the ribbon?", "options": ["The mayor", "A teacher", "A duck", "A girl"], "correct_index": 0, "explanation": "O prefeito."}, {"question": "What do the families feel?", "options": ["Sad", "Happy", "Angry", "Tired"], "correct_index": 1, "explanation": "Felizes."}], "open_questions": [{"question": "What park do you like?", "key_points_pt": ["descrever"]}, {"question": "What does your town need?", "key_points_pt": ["opinar"]}]}}, {"level": "A2", "genre": "news", "title": "Bakery Gives Free Bread", "paragraphs": ["A small bakery in Lisbon is giving free bread to people who need it. The idea started last month. The owner, Mr. Costa, noticed that many families could not buy food because everything was expensive.", "Every morning at seven o'clock, he leaves a basket outside the door. Inside the basket there are fresh rolls and loaves. A sign says: \"Take what you need. Leave what you can.\"", "Other people have started to help. Some leave money, some leave fruit, and one neighbor brings milk every day. \"I only make bread,\" says Mr. Costa, \"but now the whole street makes a meal.\" He hopes other bakeries will copy him."], "paragraphs_pt": ["Uma pequena padaria em Lisboa está dando pão grátis a quem precisa. A ideia começou no mês passado. O dono, Sr. Costa, notou que muitas famílias não podiam comprar comida porque tudo estava caro.", "Toda manhã às sete horas, ele deixa uma cesta fora da porta. Dentro da cesta há pãezinhos e pães frescos. Uma placa diz: \"Pegue o que precisa. Deixe o que puder.\"", "Outras pessoas começaram a ajudar. Algumas deixam dinheiro, outras frutas, e um vizinho traz leite todos os dias. \"Eu só faço pão\", diz o Sr. Costa, \"mas agora a rua toda faz uma refeição.\" Ele espera que outras padarias o copiem."], "hard_words": ["bakery", "owner", "basket", "sign"], "vocab": [{"word": "bakery", "meaning": "padaria", "note": ""}, {"word": "owner", "meaning": "dono", "note": ""}, {"word": "families", "meaning": "famílias", "note": ""}, {"word": "expensive", "meaning": "caro", "note": ""}, {"word": "basket", "meaning": "cesta", "note": ""}, {"word": "loaves", "meaning": "pães", "note": ""}, {"word": "sign", "meaning": "placa", "note": ""}, {"word": "neighbor", "meaning": "vizinho", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was", "are"], "irregular": ["started", "noticed", "could"], "phrasal": ["leave money", "copy him"], "wh": ["who", "what"], "connectors": ["and", "but", "because"], "comparative": []}, "word_meanings": [{"word": "bakery", "meaning": "padaria", "note": ""}, {"word": "owner", "meaning": "dono", "note": ""}, {"word": "families", "meaning": "famílias", "note": ""}, {"word": "expensive", "meaning": "caro", "note": ""}, {"word": "basket", "meaning": "cesta", "note": ""}, {"word": "loaves", "meaning": "pães", "note": ""}, {"word": "sign", "meaning": "placa", "note": ""}, {"word": "neighbor", "meaning": "vizinho", "note": ""}], "exercises": {"grammar": [{"point": "Present continuous", "explanation_pt": "'is giving free bread' fala de algo que acontece agora."}, {"point": "Present perfect", "explanation_pt": "'Other people have started to help' mostra um resultado recente."}], "multiple_choice": [{"question": "What does the bakery give?", "options": ["Free milk", "Free bread", "Free cakes", "Free coffee"], "correct_index": 1, "explanation": "Pão grátis."}, {"question": "Why did Mr. Costa start?", "options": ["Families could not buy food", "He had too much bread", "He was rich", "He wanted fame"], "correct_index": 0, "explanation": "Famílias não podiam comprar comida."}, {"question": "When does he leave the basket?", "options": ["At seven every morning", "At night", "At noon", "On Sundays"], "correct_index": 0, "explanation": "Às sete da manhã."}, {"question": "What does the sign say?", "options": ["Pay here", "Take what you need, leave what you can", "Free coffee", "Closed"], "correct_index": 1, "explanation": "'Pegue o que precisa, deixe o que puder.'"}, {"question": "What does a neighbor bring?", "options": ["Milk", "Flowers", "Books", "Meat"], "correct_index": 0, "explanation": "Leite."}], "open_questions": [{"question": "How can people help neighbors in need?", "key_points_pt": ["sugerir"]}, {"question": "Would you leave something in the basket?", "key_points_pt": ["opinar"]}]}}, {"level": "A2", "genre": "news", "title": "Student Wins Science Prize", "paragraphs": ["A fifteen-year-old student from Recife has won a national science prize. Her name is Beatriz Lima, and she studies at a public school. Her project is a small machine that cleans dirty water using sun and sand.", "Beatriz had the idea after visiting her grandmother in a village without clean water. \"I wanted to help my family,\" she says. She built the machine with simple materials: a plastic bottle, sand, small stones and a black cloth.", "The judges say the project is cheap and easy to build. Beatriz will receive money for her studies and will travel to a big science fair in Europe next year. \"I'm nervous but very happy,\" she says. Her teachers are also very proud."], "paragraphs_pt": ["Uma estudante de quinze anos de Recife ganhou um prêmio nacional de ciências. O nome dela é Beatriz Lima, e ela estuda numa escola pública. Seu projeto é uma pequena máquina que limpa água suja usando sol e areia.", "Beatriz teve a ideia depois de visitar a avó numa aldeia sem água limpa. \"Eu queria ajudar minha família\", diz. Ela construiu a máquina com materiais simples: uma garrafa plástica, areia, pedras pequenas e um pano preto.", "Os jurados dizem que o projeto é barato e fácil de construir. Beatriz receberá dinheiro para os estudos e viajará a uma grande feira de ciências na Europa no ano que vem. \"Estou nervosa mas muito feliz\", diz. Os professores também estão muito orgulhosos."], "hard_words": ["prize", "machine", "judges", "cheap"], "vocab": [{"word": "prize", "meaning": "prêmio", "note": ""}, {"word": "student", "meaning": "estudante", "note": ""}, {"word": "machine", "meaning": "máquina", "note": ""}, {"word": "cleans", "meaning": "limpa", "note": ""}, {"word": "sand", "meaning": "areia", "note": ""}, {"word": "judges", "meaning": "jurados", "note": ""}, {"word": "cheap", "meaning": "barato", "note": ""}, {"word": "science fair", "meaning": "feira de ciências", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": ["won", "had", "wanted", "built"], "phrasal": ["has won", "will receive"], "wh": [], "connectors": ["and", "but", "after", "also"], "comparative": []}, "word_meanings": [{"word": "prize", "meaning": "prêmio", "note": ""}, {"word": "student", "meaning": "estudante", "note": ""}, {"word": "machine", "meaning": "máquina", "note": ""}, {"word": "cleans", "meaning": "limpa", "note": ""}, {"word": "sand", "meaning": "areia", "note": ""}, {"word": "judges", "meaning": "jurados", "note": ""}, {"word": "cheap", "meaning": "barato", "note": ""}, {"word": "science fair", "meaning": "feira de ciências", "note": ""}], "exercises": {"grammar": [{"point": "Present perfect", "explanation_pt": "'has won' mostra um resultado recente."}, {"point": "Future with will", "explanation_pt": "'will receive' e 'will travel' falam de planos."}], "multiple_choice": [{"question": "Where is Beatriz from?", "options": ["Madrid", "Lisbon", "Paris", "Recife"], "correct_index": 3, "explanation": "De Recife."}, {"question": "What does her machine do?", "options": ["Makes power", "Cleans dirty water", "Makes ice", "Makes bread"], "correct_index": 1, "explanation": "Limpa água suja."}, {"question": "Why did she have the idea?", "options": ["She was bored", "A teacher asked", "Her grandmother had no clean water", "A friend asked"], "correct_index": 2, "explanation": "A avó não tinha água limpa."}, {"question": "What materials did she use?", "options": ["Wood", "A bottle, sand and stones", "Gold", "Glass"], "correct_index": 1, "explanation": "Garrafa, areia e pedras."}, {"question": "What will she do next year?", "options": ["Travel to a science fair in Europe", "Buy a house", "Quit school", "Move"], "correct_index": 0, "explanation": "Viajará a uma feira na Europa."}], "open_questions": [{"question": "What problem would you like to solve?", "key_points_pt": ["imaginar"]}, {"question": "Why are science prizes important?", "key_points_pt": ["explicar"]}]}}, {"level": "A2", "genre": "news", "title": "Traffic Stops in the Centre", "paragraphs": ["Yesterday afternoon, traffic stopped in the city centre for more than three hours. A truck broke down on the main bridge, and the police closed the road. Thousands of people were late for work and school.", "Many drivers waited in their cars and listened to the radio. Some people got out and walked home. A man sold cold water to drivers and earned fifty euros. \"It was a good day for me,\" he said, smiling.", "The police moved the truck at seven o'clock in the evening. Today the bridge is open again, but the mayor says it is old and dangerous. He promises to build a new bridge in two years. Many citizens say they are not surprised."], "paragraphs_pt": ["Ontem à tarde, o trânsito parou no centro da cidade por mais de três horas. Um caminhão quebrou na ponte principal e a polícia fechou a rua. Milhares de pessoas se atrasaram para o trabalho e a escola.", "Muitos motoristas esperaram nos carros e ouviram rádio. Algumas pessoas desceram e foram a pé para casa. Um homem vendeu água gelada aos motoristas e ganhou cinquenta euros. \"Foi um bom dia para mim\", disse, sorrindo.", "A polícia removeu o caminhão às sete da noite. Hoje a ponte está aberta de novo, mas o prefeito diz que é velha e perigosa. Ele promete construir uma nova ponte em dois anos. Muitos cidadãos dizem que não estão surpresos."], "hard_words": ["traffic", "truck", "thousands", "citizens"], "vocab": [{"word": "traffic", "meaning": "trânsito", "note": ""}, {"word": "truck", "meaning": "caminhão", "note": ""}, {"word": "bridge", "meaning": "ponte", "note": ""}, {"word": "thousands", "meaning": "milhares", "note": ""}, {"word": "drivers", "meaning": "motoristas", "note": ""}, {"word": "earned", "meaning": "ganhou", "note": ""}, {"word": "dangerous", "meaning": "perigosa", "note": ""}, {"word": "citizens", "meaning": "cidadãos", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was", "is", "are"], "irregular": ["stopped", "broke", "closed", "waited", "listened", "got", "walked", "sold", "earned", "said", "moved", "surprised"], "phrasal": ["broke down", "got out"], "wh": [], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "traffic", "meaning": "trânsito", "note": ""}, {"word": "truck", "meaning": "caminhão", "note": ""}, {"word": "bridge", "meaning": "ponte", "note": ""}, {"word": "thousands", "meaning": "milhares", "note": ""}, {"word": "drivers", "meaning": "motoristas", "note": ""}, {"word": "earned", "meaning": "ganhou", "note": ""}, {"word": "dangerous", "meaning": "perigosa", "note": ""}, {"word": "citizens", "meaning": "cidadãos", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'stopped', 'closed', 'waited' contam fatos de ontem."}, {"point": "More than", "explanation_pt": "'for more than three hours' indica mais de certo tempo."}], "multiple_choice": [{"question": "How long did traffic stop?", "options": ["Ten minutes", "More than three hours", "One day", "Two days"], "correct_index": 1, "explanation": "Mais de três horas."}, {"question": "What caused it?", "options": ["A protest", "An accident with a bus", "A storm", "A truck broke down"], "correct_index": 3, "explanation": "Um caminhão quebrou."}, {"question": "What did a man do?", "options": ["Sang", "Slept", "Sold cold water", "Worked"], "correct_index": 2, "explanation": "Vendeu água."}, {"question": "What does the mayor say about the bridge?", "options": ["It is beautiful", "It is new", "It is closed forever", "It is old and dangerous"], "correct_index": 3, "explanation": "É velha e perigosa."}, {"question": "What does he promise?", "options": ["Less traffic tomorrow", "Free buses", "Nothing", "A new bridge in two years"], "correct_index": 3, "explanation": "Nova ponte em dois anos."}], "open_questions": [{"question": "How do you go to work or school?", "key_points_pt": ["falar"]}, {"question": "What could cities do to reduce traffic?", "key_points_pt": ["sugerir"]}]}}, {"level": "B1", "genre": "news", "title": "Local Library Saved by Volunteers", "paragraphs": ["The public library in the town of Eastwood was supposed to close last Friday after the council cut its budget. For ninety years, it had been the centre of the community, offering books, free Internet and a place for children to do their homework. When the news came out, many residents felt angry and helpless.", "Instead of complaining, a group of retired teachers decided to act. They contacted other volunteers, opened a social media page and organised a weekend of events to raise money. Local shops donated prizes, a band played in the square, and children sold homemade lemonade. By Sunday evening, they had collected more than twelve thousand pounds.", "The council was impressed by the response and agreed to pay half of the library's yearly costs if the volunteers could find the other half. The library will now continue to open every weekday, but it will be run mostly by volunteers.", "\"It isn't a perfect solution,\" said Margaret Hill, one of the organisers, \"but a library is more than books. It's where the town keeps its memory.\" She hopes that other communities will follow their example."], "paragraphs_pt": ["A biblioteca pública da cidade de Eastwood deveria fechar na sexta passada depois que a prefeitura cortou seu orçamento. Por noventa anos, fora o centro da comunidade, oferecendo livros, internet grátis e um lugar para crianças fazerem a lição de casa. Quando a notícia saiu, muitos moradores sentiram raiva e impotência.", "Em vez de reclamar, um grupo de professores aposentados decidiu agir. Contataram outros voluntários, abriram uma página nas redes sociais e organizaram um fim de semana de eventos para arrecadar dinheiro. Lojas locais doaram prêmios, uma banda tocou na praça e crianças venderam limonada caseira. Até domingo à noite, haviam arrecadado mais de doze mil libras.", "A prefeitura ficou impressionada com a resposta e concordou em pagar metade dos custos anuais da biblioteca se os voluntários achassem a outra metade. A biblioteca continuará abrindo todos os dias úteis, mas será administrada principalmente por voluntários.", "\"Não é uma solução perfeita\", disse Margaret Hill, uma das organizadoras, \"mas uma biblioteca é mais que livros. É onde a cidade guarda sua memória.\" Ela espera que outras comunidades sigam o exemplo."], "hard_words": ["council", "budget", "residents", "volunteers"], "vocab": [{"word": "library", "meaning": "biblioteca", "note": ""}, {"word": "council", "meaning": "prefeitura, conselho", "note": ""}, {"word": "budget", "meaning": "orçamento", "note": ""}, {"word": "residents", "meaning": "moradores", "note": ""}, {"word": "helpless", "meaning": "impotentes", "note": ""}, {"word": "volunteers", "meaning": "voluntários", "note": ""}, {"word": "donated", "meaning": "doaram", "note": ""}, {"word": "organisers", "meaning": "organizadores", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "be", "is"], "irregular": ["supposed", "had", "came", "felt", "retired", "decided", "contacted", "opened", "organised", "donated", "played", "sold", "collected", "impressed", "agreed", "could", "said"], "phrasal": ["came out", "raise money"], "wh": ["where", "when"], "connectors": ["and", "but", "instead", "after", "when", "if"], "comparative": []}, "word_meanings": [{"word": "library", "meaning": "biblioteca", "note": ""}, {"word": "council", "meaning": "prefeitura, conselho", "note": ""}, {"word": "budget", "meaning": "orçamento", "note": ""}, {"word": "residents", "meaning": "moradores", "note": ""}, {"word": "helpless", "meaning": "impotentes", "note": ""}, {"word": "volunteers", "meaning": "voluntários", "note": ""}, {"word": "donated", "meaning": "doaram", "note": ""}, {"word": "organisers", "meaning": "organizadores", "note": ""}], "exercises": {"grammar": [{"point": "Passive voice", "explanation_pt": "'it will be run mostly by volunteers' foca em quem recebe a ação."}, {"point": "Reported speech", "explanation_pt": "'The council agreed to pay half' reproduz uma decisão."}], "multiple_choice": [{"question": "Why was the library going to close?", "options": ["It was old", "The council cut its budget", "It was empty", "Nobody read"], "correct_index": 1, "explanation": "Corte de orçamento."}, {"question": "Who acted?", "options": ["Students", "Retired teachers", "Journalists", "The mayor"], "correct_index": 1, "explanation": "Professores aposentados."}, {"question": "How much money did they raise?", "options": ["A few pounds", "A million", "More than twelve thousand pounds", "Nothing"], "correct_index": 2, "explanation": "Mais de doze mil libras."}, {"question": "What did the council agree to?", "options": ["Sell it", "Rebuild it", "Close it", "Pay half the costs"], "correct_index": 3, "explanation": "Pagar metade dos custos."}, {"question": "What does Margaret Hill say?", "options": ["A library is where the town keeps its memory", "It's perfect", "It's cheap", "It's old"], "correct_index": 0, "explanation": "Onde a cidade guarda sua memória."}], "open_questions": [{"question": "Why are libraries important?", "key_points_pt": ["explicar"]}, {"question": "How can a community save a service?", "key_points_pt": ["sugerir"]}]}}, {"level": "B1", "genre": "news", "title": "Rescue at Sea", "paragraphs": ["Three fishermen were rescued yesterday after spending eighteen hours on a small boat in the Atlantic Ocean. They had left the port of Peniche on Tuesday morning to fish, but a sudden storm damaged the engine, and the boat began to take on water.", "The men sent an emergency radio signal, but the storm made it difficult to locate them. Rescue teams searched through the night, while the families waited on the shore. At dawn, a helicopter finally saw the boat drifting about thirty kilometres from the coast.", "All three men were lifted to safety and taken to hospital, where doctors described their condition as stable. The youngest, 24-year-old Rui Matos, said he had thought he would never see his daughter again. \"When I saw the helicopter, I cried like a child,\" he admitted.", "Authorities have reminded fishermen to check weather forecasts before sailing. A local fisherman said the sea was \"generous but unforgiving\", and that respecting it was the only way to return home every evening."], "paragraphs_pt": ["Três pescadores foram resgatados ontem depois de passar dezoito horas num pequeno barco no Oceano Atlântico. Haviam saído do porto de Peniche na terça de manhã para pescar, mas uma tempestade repentina danificou o motor e o barco começou a encher de água.", "Os homens enviaram um sinal de rádio de emergência, mas a tempestade dificultou localizá-los. Equipes de resgate vasculharam durante a noite, enquanto as famílias esperavam na orla. Ao amanhecer, um helicóptero finalmente avistou o barco à deriva a cerca de trinta quilômetros da costa.", "Os três foram içados a salvo e levados ao hospital, onde os médicos descreveram seu estado como estável. O mais novo, Rui Matos, de 24 anos, disse que pensara que nunca mais veria a filha. \"Quando vi o helicóptero, chorei como uma criança\", admitiu.", "As autoridades lembraram os pescadores de conferir as previsões do tempo antes de zarpar. Um pescador local disse que o mar era \"generoso, mas implacável\" e que respeitá-lo era a única maneira de voltar para casa toda tarde."], "hard_words": ["rescued", "emergency", "drifting", "unforgiving"], "vocab": [{"word": "rescued", "meaning": "resgatados", "note": ""}, {"word": "engine", "meaning": "motor", "note": ""}, {"word": "emergency", "meaning": "emergência", "note": ""}, {"word": "locate", "meaning": "localizar", "note": ""}, {"word": "shore", "meaning": "orla", "note": ""}, {"word": "drifting", "meaning": "à deriva", "note": ""}, {"word": "stable", "meaning": "estável", "note": ""}, {"word": "unforgiving", "meaning": "implacável", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was"], "irregular": ["rescued", "had", "left", "damaged", "began", "sent", "made", "searched", "waited", "saw", "lifted", "taken", "described", "said", "thought", "would", "cried", "admitted", "reminded"], "phrasal": ["take on water", "lifted to"], "wh": ["where", "when"], "connectors": ["and", "but", "while", "after", "before", "when", "finally", "as"], "comparative": []}, "word_meanings": [{"word": "rescued", "meaning": "resgatados", "note": ""}, {"word": "engine", "meaning": "motor", "note": ""}, {"word": "emergency", "meaning": "emergência", "note": ""}, {"word": "locate", "meaning": "localizar", "note": ""}, {"word": "shore", "meaning": "orla", "note": ""}, {"word": "drifting", "meaning": "à deriva", "note": ""}, {"word": "stable", "meaning": "estável", "note": ""}, {"word": "unforgiving", "meaning": "implacável", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'They had left the port' mostra o que ocorreu antes do resgate."}, {"point": "Passive", "explanation_pt": "'were rescued' e 'were taken' focam nas pessoas."}], "multiple_choice": [{"question": "How long were the fishermen at sea?", "options": ["Three days", "A week", "Two hours", "Eighteen hours"], "correct_index": 3, "explanation": "Dezoito horas."}, {"question": "What damaged the engine?", "options": ["A fire", "A whale", "A rock", "A sudden storm"], "correct_index": 3, "explanation": "Uma tempestade."}, {"question": "Who found the boat?", "options": ["A swimmer", "A ship", "A bird", "A helicopter"], "correct_index": 3, "explanation": "Um helicóptero."}, {"question": "How is their condition?", "options": ["Stable", "Unknown", "Dead", "Critical"], "correct_index": 0, "explanation": "Estável."}, {"question": "What did authorities remind fishermen?", "options": ["To check weather forecasts", "To stop fishing", "To buy radios", "To fish at night"], "correct_index": 0, "explanation": "Conferir previsões."}], "open_questions": [{"question": "How can people prepare for risky jobs?", "key_points_pt": ["sugerir"]}, {"question": "Why do we depend on rescue teams?", "key_points_pt": ["explicar"]}]}}, {"level": "B1", "genre": "news", "title": "Teenagers Plant Ten Thousand Trees", "paragraphs": ["A group of teenagers in Kenya has planted ten thousand trees in a single week, breaking the country's record for a school project. The students, aged between thirteen and seventeen, worked in the hills near Nairobi, where deforestation has caused floods and soil erosion.", "The project was the idea of sixteen-year-old Amina Otieno, who watched her family's farm being washed away by heavy rains. \"Trees hold the soil,\" she explained. \"If we plant more, we protect our homes.\" She convinced her school to organise the event and asked local companies to donate seedlings.", "Volunteers worked from dawn until sunset, digging holes and carrying water from a nearby river. Parents and neighbours joined them on the last day, bringing food and tools. By Sunday, the hillside looked completely different.", "Experts say that only about sixty percent of the seedlings will survive, but the students plan to check them every month. \"We are not doing this for one week,\" said Amina. \"We are doing it for the next fifty years.\""], "paragraphs_pt": ["Um grupo de adolescentes no Quênia plantou dez mil árvores numa única semana, quebrando o recorde do país para um projeto escolar. Os estudantes, de treze a dezessete anos, trabalharam nas colinas perto de Nairóbi, onde o desmatamento causou enchentes e erosão do solo.", "O projeto foi ideia de Amina Otieno, de dezesseis anos, que viu a fazenda da família ser levada pelas chuvas fortes. \"As árvores seguram o solo\", explicou. \"Se plantarmos mais, protegemos nossas casas.\" Convenceu a escola a organizar o evento e pediu a empresas locais que doassem mudas.", "Voluntários trabalharam do amanhecer ao pôr do sol, cavando buracos e carregando água de um rio próximo. Pais e vizinhos se juntaram no último dia, trazendo comida e ferramentas. No domingo, a encosta parecia completamente diferente.", "Especialistas dizem que apenas cerca de sessenta por cento das mudas sobreviverão, mas os estudantes planejam verificá-las todo mês. \"Não estamos fazendo isso por uma semana\", disse Amina. \"Estamos fazendo pelos próximos cinquenta anos.\""], "hard_words": ["deforestation", "erosion", "seedlings", "survive"], "vocab": [{"word": "teenagers", "meaning": "adolescentes", "note": ""}, {"word": "record", "meaning": "recorde", "note": ""}, {"word": "deforestation", "meaning": "desmatamento", "note": ""}, {"word": "floods", "meaning": "enchentes", "note": ""}, {"word": "erosion", "meaning": "erosão", "note": ""}, {"word": "seedlings", "meaning": "mudas", "note": ""}, {"word": "hillside", "meaning": "encosta", "note": ""}, {"word": "survive", "meaning": "sobreviver", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being", "are"], "irregular": ["planted", "aged", "worked", "caused", "watched", "washed", "explained", "convinced", "asked", "joined", "looked", "said"], "phrasal": ["washed away", "joined them"], "wh": ["who", "where"], "connectors": ["and", "but", "until", "if"], "comparative": []}, "word_meanings": [{"word": "teenagers", "meaning": "adolescentes", "note": ""}, {"word": "record", "meaning": "recorde", "note": ""}, {"word": "deforestation", "meaning": "desmatamento", "note": ""}, {"word": "floods", "meaning": "enchentes", "note": ""}, {"word": "erosion", "meaning": "erosão", "note": ""}, {"word": "seedlings", "meaning": "mudas", "note": ""}, {"word": "hillside", "meaning": "encosta", "note": ""}, {"word": "survive", "meaning": "sobreviver", "note": ""}], "exercises": {"grammar": [{"point": "Present perfect", "explanation_pt": "'has planted ten thousand trees' mostra um resultado recente."}, {"point": "First conditional", "explanation_pt": "'If we plant more, we protect our homes' liga ação e resultado."}], "multiple_choice": [{"question": "How many trees did they plant?", "options": ["A million", "One thousand", "One hundred", "Ten thousand"], "correct_index": 3, "explanation": "Dez mil."}, {"question": "Why did Amina start the project?", "options": ["She wanted money", "Her family farm was washed away", "Her teacher asked", "She was bored"], "correct_index": 1, "explanation": "A fazenda foi levada pela chuva."}, {"question": "Who joined on the last day?", "options": ["Reporters", "Parents and neighbours", "Politicians", "Nobody"], "correct_index": 1, "explanation": "Pais e vizinhos."}, {"question": "How many seedlings will survive?", "options": ["Ten percent", "About sixty percent", "All", "None"], "correct_index": 1, "explanation": "Cerca de sessenta por cento."}, {"question": "What is Amina's long-term goal?", "options": ["To leave school", "To win a prize", "To protect homes for fifty years", "To be famous"], "correct_index": 2, "explanation": "Proteger por cinquenta anos."}], "open_questions": [{"question": "How can young people change their community?", "key_points_pt": ["sugerir"]}, {"question": "Why are trees important?", "key_points_pt": ["explicar"]}]}}, {"level": "B2", "genre": "news", "title": "City Experiments with a Four-Day Week", "paragraphs": ["The city of Mariner has completed a six-month experiment in which three hundred municipal employees worked four days a week for the same salary. The results, published on Monday, have surprised even the most optimistic supporters of the idea. Productivity remained stable, absenteeism fell by a third and a staff survey reported record levels of satisfaction.", "Critics, however, were quick to point out the limits of the trial. Services such as emergency response and public transport could not be reduced without affecting residents, and the pilot excluded them. \"It works well for administrative departments,\" said councillor Raymond Boyle, \"but we should not pretend it is universal.\"", "The unions welcomed the report but warned that some employers might exploit the concept, expecting workers to complete five days of work in four. A researcher involved in the study acknowledged this risk, noting that the best results occurred when managers actively reduced meetings and unnecessary reports.", "The council will decide next month whether to extend the programme. Whatever the outcome, the experiment has restarted a debate that was long overdue: not just how many hours people work, but what they are actually producing in them."], "paragraphs_pt": ["A cidade de Mariner concluiu um experimento de seis meses em que trezentos funcionários municipais trabalharam quatro dias por semana pelo mesmo salário. Os resultados, publicados na segunda, surpreenderam até os mais otimistas defensores da ideia. A produtividade permaneceu estável, o absenteísmo caiu um terço e uma pesquisa com os funcionários registrou níveis recordes de satisfação.", "Críticos, porém, logo apontaram os limites do teste. Serviços como atendimento de emergência e transporte público não podiam ser reduzidos sem afetar os moradores, e o piloto os excluiu. \"Funciona bem para departamentos administrativos\", disse o vereador Raymond Boyle, \"mas não devemos fingir que seja universal.\"", "Os sindicatos receberam bem o relatório, mas alertaram que alguns empregadores poderiam explorar o conceito, esperando que os trabalhadores concluíssem cinco dias de trabalho em quatro. Um pesquisador envolvido no estudo reconheceu esse risco, observando que os melhores resultados ocorreram quando gestores reduziram ativamente reuniões e relatórios desnecessários.", "A prefeitura decidirá no mês que vem se estenderá o programa. Qualquer que seja o resultado, o experimento reiniciou um debate há muito atrasado: não apenas quantas horas as pessoas trabalham, mas o que realmente produzem nelas."], "hard_words": ["productivity", "absenteeism", "councillor", "overdue"], "vocab": [{"word": "experiment", "meaning": "experimento", "note": ""}, {"word": "municipal", "meaning": "municipal", "note": ""}, {"word": "productivity", "meaning": "produtividade", "note": ""}, {"word": "absenteeism", "meaning": "absenteísmo", "note": ""}, {"word": "survey", "meaning": "pesquisa", "note": ""}, {"word": "councillor", "meaning": "vereador", "note": ""}, {"word": "unions", "meaning": "sindicatos", "note": ""}, {"word": "overdue", "meaning": "atrasado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "be", "is", "was", "are"], "irregular": ["completed", "worked", "published", "surprised", "remained", "fell", "reported", "could", "reduced", "excluded", "said", "should", "welcomed", "warned", "might", "involved", "acknowledged", "occurred", "restarted"], "phrasal": ["point out", "extend the programme"], "wh": ["what", "when", "how", "which", "whatever"], "connectors": ["and", "but", "however", "when", "as"], "comparative": []}, "word_meanings": [{"word": "experiment", "meaning": "experimento", "note": ""}, {"word": "municipal", "meaning": "municipal", "note": ""}, {"word": "productivity", "meaning": "produtividade", "note": ""}, {"word": "absenteeism", "meaning": "absenteísmo", "note": ""}, {"word": "survey", "meaning": "pesquisa", "note": ""}, {"word": "councillor", "meaning": "vereador", "note": ""}, {"word": "unions", "meaning": "sindicatos", "note": ""}, {"word": "overdue", "meaning": "atrasado", "note": ""}], "exercises": {"grammar": [{"point": "Passive", "explanation_pt": "'results, published on Monday' omite quem publicou."}, {"point": "Whatever", "explanation_pt": "'Whatever the outcome' significa qualquer que seja."}], "multiple_choice": [{"question": "How many employees took part?", "options": ["Thirty", "Three", "Three hundred", "Three thousand"], "correct_index": 2, "explanation": "Trezentos."}, {"question": "What happened to absenteeism?", "options": ["It fell by a third", "It doubled", "It disappeared", "It stayed same"], "correct_index": 0, "explanation": "Caiu um terço."}, {"question": "What did critics say?", "options": ["Not all services can work this way", "The trial was too long", "Pay was too low", "Nobody liked it"], "correct_index": 0, "explanation": "Nem todos serviços podem."}, {"question": "What was the unions' warning?", "options": ["The trial would end", "Salaries would fall", "Employers might exploit the idea", "Strikes would start"], "correct_index": 2, "explanation": "Empregadores podem explorar."}, {"question": "What is the debate about?", "options": ["What people actually produce in their hours", "Taxes", "Technology", "Holidays"], "correct_index": 0, "explanation": "O que produzem nas horas."}], "open_questions": [{"question": "Would a four-day week work in your field?", "key_points_pt": ["opinar"]}, {"question": "What are possible downsides?", "key_points_pt": ["debater"]}]}}, {"level": "B2", "genre": "news", "title": "Archaeologists Uncover a Roman Villa", "paragraphs": ["Archaeologists working on the construction site of a new supermarket in northern Portugal have uncovered a remarkably well-preserved Roman villa dating from the second century. The discovery was made by chance when a digger hit a mosaic floor, forcing the builders to stop work immediately.", "The villa, which covers nearly 800 square metres, includes a heated bathhouse, a courtyard and several rooms decorated with geometric mosaics. Among the objects found are coins, ceramic jars and a small bronze statue that experts believe represents a household god. \"It is rare to find so many elements intact,\" said lead archaeologist Dr. Helena Duarte.", "The finding has created a dilemma. The supermarket company claims it has already invested millions and has the necessary permits, while heritage groups demand that the site be preserved as a museum. Local residents seem divided between those who want jobs and those who want history.", "The government has ordered a halt to construction while it evaluates the options. Dr. Duarte hopes for a compromise: \"We don't have to choose between the past and the future. A modern building can sit beside an ancient one, if we plan carefully.\""], "paragraphs_pt": ["Arqueólogos que trabalham no canteiro de obras de um novo supermercado no norte de Portugal descobriram uma villa romana notavelmente bem preservada, do século II. A descoberta foi feita por acaso quando uma escavadeira atingiu um piso de mosaico, forçando os construtores a parar o trabalho imediatamente.", "A villa, que cobre quase 800 metros quadrados, inclui uma casa de banho aquecida, um pátio e vários cômodos decorados com mosaicos geométricos. Entre os objetos achados há moedas, jarros de cerâmica e uma pequena estátua de bronze que os especialistas acreditam representar um deus doméstico. \"É raro encontrar tantos elementos intactos\", disse a arqueóloga-chefe Dra. Helena Duarte.", "A descoberta criou um dilema. A empresa do supermercado afirma já ter investido milhões e ter as licenças necessárias, enquanto grupos de patrimônio exigem que o local seja preservado como museu. Os moradores parecem divididos entre os que querem empregos e os que querem história.", "O governo ordenou a suspensão da obra enquanto avalia as opções. A Dra. Duarte espera um compromisso: \"Não precisamos escolher entre o passado e o futuro. Um prédio moderno pode ficar ao lado de um antigo, se planejarmos com cuidado.\""], "hard_words": ["uncovered", "mosaic", "permits", "heritage"], "vocab": [{"word": "archaeologists", "meaning": "arqueólogos", "note": ""}, {"word": "uncovered", "meaning": "descobriram", "note": ""}, {"word": "villa", "meaning": "villa", "note": ""}, {"word": "digger", "meaning": "escavadeira", "note": ""}, {"word": "mosaic", "meaning": "mosaico", "note": ""}, {"word": "bathhouse", "meaning": "casa de banho", "note": ""}, {"word": "permits", "meaning": "licenças", "note": ""}, {"word": "heritage", "meaning": "patrimônio", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "are", "is", "be"], "irregular": ["uncovered", "preserved", "made", "heated", "decorated", "found", "said", "created", "invested", "divided", "ordered"], "phrasal": ["hit a", "sit beside"], "wh": ["who", "when", "which"], "connectors": ["and", "so", "while", "when", "if", "as"], "comparative": []}, "word_meanings": [{"word": "archaeologists", "meaning": "arqueólogos", "note": ""}, {"word": "uncovered", "meaning": "descobriram", "note": ""}, {"word": "villa", "meaning": "villa", "note": ""}, {"word": "digger", "meaning": "escavadeira", "note": ""}, {"word": "mosaic", "meaning": "mosaico", "note": ""}, {"word": "bathhouse", "meaning": "casa de banho", "note": ""}, {"word": "permits", "meaning": "licenças", "note": ""}, {"word": "heritage", "meaning": "patrimônio", "note": ""}], "exercises": {"grammar": [{"point": "Present perfect", "explanation_pt": "'have uncovered' destaca um resultado recente."}, {"point": "Passive", "explanation_pt": "'The discovery was made by chance' foca na descoberta."}], "multiple_choice": [{"question": "What did they find?", "options": ["A castle", "A cave", "A Roman villa", "A church"], "correct_index": 2, "explanation": "Uma villa romana."}, {"question": "How was it found?", "options": ["A digger hit a mosaic", "By a farmer", "By a map", "By a diver"], "correct_index": 0, "explanation": "A escavadeira atingiu um mosaico."}, {"question": "What is the dilemma?", "options": ["Who owns the land", "How old it is", "Supermarket versus preservation", "Which country"], "correct_index": 2, "explanation": "Supermercado versus preservação."}, {"question": "What did the government do?", "options": ["Closed the museum", "Fired the builders", "Halted construction", "Bought the villa"], "correct_index": 2, "explanation": "Suspendeu a obra."}, {"question": "What does Dr. Duarte suggest?", "options": ["Selling it", "Demolishing it", "Closing the site", "A compromise"], "correct_index": 3, "explanation": "Um compromisso."}], "open_questions": [{"question": "Should heritage always win over development?", "key_points_pt": ["debater"]}, {"question": "How can cities balance old and new?", "key_points_pt": ["propor"]}]}}, {"level": "C1", "genre": "news", "title": "The Quiet Disappearance of Local News", "paragraphs": ["Over the past two decades, the number of local newspapers has declined dramatically, leaving entire regions with no dedicated reporters. Researchers refer to these areas as \"news deserts\", and a recent study suggests that they are expanding at an alarming rate. The consequences, however, are subtler than one might anticipate.", "When no journalist attends council meetings, decisions are made with less scrutiny. Studies show that municipal borrowing tends to rise, and corruption becomes marginally more likely, in places where local reporting has vanished. Voter turnout also declines, as citizens lose the thread connecting them to institutions that affect their daily lives.", "Social media has not filled the void. Instead of verified information, communities increasingly rely on rumours, which circulate faster than corrections. A resident of a former mining town described the phenomenon as \"knowing everything about the world and nothing about the street\".", "Several initiatives have attempted to counter the trend, from non-profit newsrooms to community-funded reporting. The results are encouraging but fragile, depending heavily on volunteers and donors. The deeper question remains unresolved: whether societies are willing to value, and pay for, information that is rarely glamorous but indispensable."], "paragraphs_pt": ["Nas últimas duas décadas, o número de jornais locais diminuiu drasticamente, deixando regiões inteiras sem repórteres dedicados. Pesquisadores chamam essas áreas de \"desertos de notícias\", e um estudo recente sugere que estão se expandindo a um ritmo alarmante. As consequências, porém, são mais sutis do que se poderia prever.", "Quando nenhum jornalista acompanha reuniões do conselho, as decisões são tomadas com menos escrutínio. Estudos mostram que o endividamento municipal tende a subir, e a corrupção se torna marginalmente mais provável, em lugares onde a reportagem local sumiu. A participação eleitoral também cai, pois os cidadãos perdem o fio que os liga às instituições que afetam seu dia a dia.", "As redes sociais não preencheram o vazio. Em vez de informação verificada, as comunidades dependem cada vez mais de boatos, que circulam mais rápido que correções. Um morador de uma antiga cidade mineira descreveu o fenômeno como \"saber tudo sobre o mundo e nada sobre a rua\".", "Várias iniciativas tentaram combater a tendência, de redações sem fins lucrativos a reportagens financiadas pela comunidade. Os resultados são encorajadores, porém frágeis, dependendo muito de voluntários e doadores. A questão mais profunda permanece sem solução: se as sociedades estão dispostas a valorizar, e pagar, uma informação raramente glamorosa, mas indispensável."], "hard_words": ["scrutiny", "turnout", "void", "indispensable"], "vocab": [{"word": "declined", "meaning": "diminuiu", "note": ""}, {"word": "scrutiny", "meaning": "escrutínio", "note": ""}, {"word": "borrowing", "meaning": "endividamento", "note": ""}, {"word": "turnout", "meaning": "participação", "note": ""}, {"word": "void", "meaning": "vazio", "note": ""}, {"word": "rumours", "meaning": "boatos", "note": ""}, {"word": "fragile", "meaning": "frágil", "note": ""}, {"word": "indispensable", "meaning": "indispensável", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "is"], "irregular": ["declined", "dedicated", "might", "made", "vanished", "filled", "verified", "described", "attempted", "funded"], "phrasal": ["rely on", "refer to"], "wh": ["where", "when", "which"], "connectors": ["and", "but", "however", "instead", "when", "also", "as"], "comparative": []}, "word_meanings": [{"word": "declined", "meaning": "diminuiu", "note": ""}, {"word": "scrutiny", "meaning": "escrutínio", "note": ""}, {"word": "borrowing", "meaning": "endividamento", "note": ""}, {"word": "turnout", "meaning": "participação", "note": ""}, {"word": "void", "meaning": "vazio", "note": ""}, {"word": "rumours", "meaning": "boatos", "note": ""}, {"word": "fragile", "meaning": "frágil", "note": ""}, {"word": "indispensable", "meaning": "indispensável", "note": ""}], "exercises": {"grammar": [{"point": "Present perfect", "explanation_pt": "'has declined' e 'has not filled' conectam passado e presente."}, {"point": "Instead of", "explanation_pt": "'Instead of verified information' indica substituição."}], "multiple_choice": [{"question": "What are 'news deserts'?", "options": ["Internet cafés", "Closed newspapers", "Dry regions", "Areas without local reporters"], "correct_index": 3, "explanation": "Áreas sem repórteres locais."}, {"question": "What happens without reporters?", "options": ["More jobs", "Less crime", "More voters", "Less scrutiny of decisions"], "correct_index": 3, "explanation": "Menos escrutínio."}, {"question": "Has social media filled the gap?", "options": ["Yes, completely", "No, it spreads rumours", "Yes, partly", "It is unknown"], "correct_index": 1, "explanation": "Não, espalha boatos."}, {"question": "What quote summarises the problem?", "options": ["Rumours are fun", "The Internet is wrong", "Knowing everything about the world and nothing about the street", "News is dead"], "correct_index": 2, "explanation": "Saber tudo do mundo e nada da rua."}, {"question": "What remains unresolved?", "options": ["How to print", "Whether societies will pay for local information", "Who owns the news", "Which paper is best"], "correct_index": 1, "explanation": "Se pagarão por informação local."}], "open_questions": [{"question": "Who should pay for local journalism?", "key_points_pt": ["debater"]}, {"question": "How do you find reliable local information?", "key_points_pt": ["descrever"]}]}}, {"level": "C1", "genre": "news", "title": "Cities in the Age of Heat", "paragraphs": ["As summers lengthen and temperatures break records with grim regularity, urban planners are rediscovering a forgotten truth: the design of a city determines, to a startling degree, whether its inhabitants can endure the heat. Concrete and asphalt absorb the sun's energy and release it slowly at night, creating \"heat islands\" in which temperatures may exceed those of surrounding countryside by several degrees.", "The effects are not distributed equally. Wealthier districts, with their parks and tree-lined avenues, enjoy a natural air-conditioning, whereas poorer neighbourhoods often endure the harshest conditions, with older housing and little shade. Mortality statistics during recent heatwaves bear out this disparity with uncomfortable precision.", "In response, several cities have adopted ambitious measures: planting thousands of trees, painting roofs white, restoring buried rivers and opening cooling centres for vulnerable residents. Critics argue that such measures are too modest and too slow, but supporters insist that even modest shade can save lives.", "What emerges is a reminder that climate adaptation is not solely a technological problem. It is, at its core, a question of who is protected and who is left exposed, and the answer is written less in laboratories than in street plans, budgets and the willingness to plant a tree for a summer one may not live to see."], "paragraphs_pt": ["À medida que os verões se alongam e as temperaturas quebram recordes com regularidade sinistra, urbanistas redescobrem uma verdade esquecida: o desenho de uma cidade determina, em grau surpreendente, se seus habitantes suportam o calor. Concreto e asfalto absorvem a energia do sol e a liberam lentamente à noite, criando \"ilhas de calor\" em que as temperaturas podem exceder as do campo ao redor em vários graus.", "Os efeitos não são distribuídos igualmente. Bairros mais ricos, com parques e avenidas arborizadas, desfrutam de ar-condicionado natural, enquanto bairros mais pobres frequentemente suportam as condições mais duras, com moradias antigas e pouca sombra. As estatísticas de mortalidade em ondas de calor recentes confirmam essa disparidade com precisão incômoda.", "Em resposta, várias cidades adotaram medidas ambiciosas: plantar milhares de árvores, pintar telhados de branco, restaurar rios enterrados e abrir centros de resfriamento para moradores vulneráveis. Críticos dizem que essas medidas são modestas e lentas demais, mas defensores insistem que mesmo uma sombra modesta pode salvar vidas.", "O que emerge é um lembrete de que a adaptação climática não é apenas um problema tecnológico. É, no fundo, uma questão de quem é protegido e quem fica exposto, e a resposta está escrita menos em laboratórios do que em plantas de ruas, orçamentos e na disposição de plantar uma árvore para um verão que talvez não se viva para ver."], "hard_words": ["endure", "disparity", "vulnerable", "adaptation"], "vocab": [{"word": "urban planners", "meaning": "urbanistas", "note": ""}, {"word": "asphalt", "meaning": "asfalto", "note": ""}, {"word": "endure", "meaning": "suportar", "note": ""}, {"word": "harshest", "meaning": "mais duras", "note": ""}, {"word": "mortality", "meaning": "mortalidade", "note": ""}, {"word": "disparity", "meaning": "disparidade", "note": ""}, {"word": "vulnerable", "meaning": "vulneráveis", "note": ""}, {"word": "adaptation", "meaning": "adaptação", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "is"], "irregular": ["forgotten", "distributed", "lined", "adopted", "buried", "protected", "left", "exposed", "written"], "phrasal": ["bear out"], "wh": ["who", "what", "which"], "connectors": ["and", "but", "whereas", "as"], "comparative": []}, "word_meanings": [{"word": "urban planners", "meaning": "urbanistas", "note": ""}, {"word": "asphalt", "meaning": "asfalto", "note": ""}, {"word": "endure", "meaning": "suportar", "note": ""}, {"word": "harshest", "meaning": "mais duras", "note": ""}, {"word": "mortality", "meaning": "mortalidade", "note": ""}, {"word": "disparity", "meaning": "disparidade", "note": ""}, {"word": "vulnerable", "meaning": "vulneráveis", "note": ""}, {"word": "adaptation", "meaning": "adaptação", "note": ""}], "exercises": {"grammar": [{"point": "Whereas", "explanation_pt": "'whereas poorer neighbourhoods often endure the harshest conditions' contrasta dois grupos."}, {"point": "Not solely", "explanation_pt": "'not solely a technological problem' amplia a causa."}], "multiple_choice": [{"question": "What are heat islands?", "options": ["Hotter urban areas", "Beach zones", "Deserts", "Tropical islands"], "correct_index": 0, "explanation": "Áreas urbanas mais quentes."}, {"question": "Why do concrete and asphalt matter?", "options": ["They reflect heat", "They hold water", "They cool air", "They absorb and release heat"], "correct_index": 3, "explanation": "Absorvem e liberam calor."}, {"question": "Who suffers most?", "options": ["Tourists", "Wealthy districts", "Farmers", "Poorer neighbourhoods"], "correct_index": 3, "explanation": "Bairros mais pobres."}, {"question": "What measures have cities adopted?", "options": ["Less water", "Bigger roads", "More cars", "Trees, white roofs, cooling centres"], "correct_index": 3, "explanation": "Árvores, telhados brancos, centros de resfriamento."}, {"question": "What is the article's conclusion?", "options": ["Cities cannot change", "Heat is natural", "Technology will solve it", "Adaptation is about who is protected"], "correct_index": 3, "explanation": "A adaptação envolve quem é protegido."}], "open_questions": [{"question": "How can cities become cooler?", "key_points_pt": ["propor"]}, {"question": "Who is responsible for protecting vulnerable people in a heatwave?", "key_points_pt": ["debater"]}]}}, {"level": "C2", "genre": "news", "title": "The Algorithm Will See You Now", "paragraphs": ["When the regional health authority introduced an algorithm to prioritise hospital waiting lists, officials presented it as a triumph of impartiality. Freed from the vagaries of human judgement, the system would allocate appointments according to clinical urgency alone, and the previous scandals of favouritism and neglect would become, in the words of one minister, \"a matter of historical curiosity\".", "Eighteen months later, an independent audit paints a more equivocal picture. Waiting times for certain procedures have indeed fallen, but patients from rural areas, whose records are frequently incomplete, are systematically ranked lower than those from cities with meticulous documentation. The algorithm, in effect, rewards the thoroughness of paperwork rather than the severity of illness.", "Defenders maintain that these distortions are teething problems and can be remedied by adjusting the parameters. Sceptics counter that the logic runs deeper: any system trained on historical data inevitably inherits the inequalities embedded in that data, laundering them through the respectable vocabulary of mathematics.", "The authority has promised a revision, but the episode raises a question no revision can fully settle. If we delegate difficult decisions to machines to escape the discomfort of our own fallibility, we may merely have found a more elaborate means of concealing it, and of making it harder, for those wronged by it, to find anybody to blame."], "paragraphs_pt": ["Quando a autoridade regional de saúde introduziu um algoritmo para priorizar listas de espera hospitalares, os responsáveis o apresentaram como um triunfo da imparcialidade. Livre dos caprichos do julgamento humano, o sistema alocaria consultas segundo a urgência clínica apenas, e os escândalos anteriores de favoritismo e negligência se tornariam, nas palavras de um ministro, \"uma questão de curiosidade histórica\".", "Dezoito meses depois, uma auditoria independente pinta um quadro mais equívoco. Os tempos de espera de certos procedimentos de fato caíram, mas pacientes de áreas rurais, cujos registros são frequentemente incompletos, são sistematicamente classificados abaixo dos de cidades com documentação meticulosa. O algoritmo, na prática, recompensa a minúcia da papelada em vez da gravidade da doença.", "Defensores sustentam que essas distorções são problemas de adaptação e podem ser corrigidas ajustando parâmetros. Céticos contestam que a lógica é mais profunda: qualquer sistema treinado com dados históricos inevitavelmente herda as desigualdades embutidas nesses dados, lavando-as pelo respeitável vocabulário da matemática.", "A autoridade prometeu uma revisão, mas o episódio levanta uma questão que nenhuma revisão pode resolver plenamente. Se delegamos decisões difíceis às máquinas para escapar do desconforto da nossa falibilidade, talvez tenhamos apenas encontrado um meio mais elaborado de ocultá-la e de dificultar, para os lesados por ela, achar alguém a quem culpar."], "hard_words": ["impartiality", "vagaries", "equivocal", "fallibility"], "vocab": [{"word": "impartiality", "meaning": "imparcialidade", "note": ""}, {"word": "vagaries", "meaning": "caprichos", "note": ""}, {"word": "equivocal", "meaning": "equívoco", "note": ""}, {"word": "meticulous", "meaning": "meticulosa", "note": ""}, {"word": "distortions", "meaning": "distorções", "note": ""}, {"word": "inherits", "meaning": "herda", "note": ""}, {"word": "fallibility", "meaning": "falibilidade", "note": ""}, {"word": "concealing", "meaning": "ocultando", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "be"], "irregular": ["introduced", "presented", "freed", "would", "fallen", "ranked", "remedied", "trained", "embedded", "promised", "found", "wronged"], "phrasal": ["embedded in"], "wh": ["when", "whose"], "connectors": ["and", "but", "when", "if", "as"], "comparative": []}, "word_meanings": [{"word": "impartiality", "meaning": "imparcialidade", "note": ""}, {"word": "vagaries", "meaning": "caprichos", "note": ""}, {"word": "equivocal", "meaning": "equívoco", "note": ""}, {"word": "meticulous", "meaning": "meticulosa", "note": ""}, {"word": "distortions", "meaning": "distorções", "note": ""}, {"word": "inherits", "meaning": "herda", "note": ""}, {"word": "fallibility", "meaning": "falibilidade", "note": ""}, {"word": "concealing", "meaning": "ocultando", "note": ""}], "exercises": {"grammar": [{"point": "Present perfect", "explanation_pt": "'Waiting times have indeed fallen' mostra um resultado confirmado."}, {"point": "Rather than", "explanation_pt": "'rewards thoroughness rather than severity' compara duas bases de decisão."}], "multiple_choice": [{"question": "What was the algorithm for?", "options": ["Hiring", "Diagnosing", "Prioritising waiting lists", "Billing"], "correct_index": 2, "explanation": "Priorizar listas de espera."}, {"question": "Who is ranked lower?", "options": ["Children", "Elderly patients", "City patients", "Rural patients with incomplete records"], "correct_index": 3, "explanation": "Pacientes rurais."}, {"question": "What does the algorithm reward?", "options": ["Age", "Thorough paperwork", "Wealth", "Illness severity"], "correct_index": 1, "explanation": "Documentação minuciosa."}, {"question": "What do sceptics argue?", "options": ["Historical data carries inequalities", "Algorithms are perfect", "Doctors are better", "Data is small"], "correct_index": 0, "explanation": "Dados históricos trazem desigualdades."}, {"question": "What is the final concern?", "options": ["Costs are high", "Machines are slow", "Patients are rude", "It is harder to find anyone to blame"], "correct_index": 3, "explanation": "Fica mais difícil culpar alguém."}], "open_questions": [{"question": "Can an algorithm be neutral?", "key_points_pt": ["debater"]}, {"question": "Who should be accountable for automated decisions?", "key_points_pt": ["debater"]}]}}, {"level": "C2", "genre": "news", "title": "The Last Telegram", "paragraphs": ["On a grey morning in a provincial post office, a clerk stamped the final telegram to be sent by the national service, ending a communication tradition that had endured for a century and a half. The message itself was nondescript, a congratulation to a cousin on a new baby, chosen by a customer who admitted she had never sent a telegram before and felt obliged to participate in history.", "Telegrams, once the swiftest means of crossing distance, had long since been supplanted by telephones, then emails, then messages that arrive before they are fully thought. Yet the announcement of the service's closure prompted an unexpected wave of nostalgia. Hundreds of people queued to send absurd or tender telegrams, as though attempting to deposit a final coin in a well.", "Historians point out that the telegram reshaped the notion of time itself, compressing news that once travelled for weeks into minutes, and with it the rhythms of commerce, war and grief. It also instilled a discipline that modern communication lacks: since each word was paid for, writers learned to say much with little.", "The clerk, who had worked for thirty years among the thinning ranks of such messages, folded the receipt and said, with the understatement of a man long accustomed to brevity, \"It was a good run.\" Outside, the street continued, as streets do, its unremarkable and endless conversation."], "paragraphs_pt": ["Numa manhã cinzenta numa agência de correio provincial, um funcionário carimbou o último telegrama enviado pelo serviço nacional, encerrando uma tradição de comunicação que durara um século e meio. A mensagem em si era banal, um parabéns a um primo por um novo bebê, escolhida por uma cliente que admitiu nunca ter enviado um telegrama e se sentir obrigada a participar da história.", "Os telegramas, antes o meio mais veloz de atravessar a distância, haviam sido há muito substituídos por telefones, depois e-mails, depois mensagens que chegam antes de serem totalmente pensadas. Mas o anúncio do fim do serviço provocou uma inesperada onda de nostalgia. Centenas de pessoas fizeram fila para enviar telegramas absurdos ou ternos, como se tentassem depositar uma última moeda num poço.", "Historiadores apontam que o telegrama reformulou a própria noção de tempo, comprimindo notícias que antes viajavam semanas em minutos, e com elas os ritmos do comércio, da guerra e do luto. Também instilou uma disciplina que a comunicação moderna não tem: como cada palavra era paga, os escritores aprenderam a dizer muito com pouco.", "O funcionário, que trabalhara trinta anos entre as fileiras minguantes dessas mensagens, dobrou o recibo e disse, com o eufemismo de quem há muito se acostumou à brevidade: \"Foi uma boa corrida.\" Lá fora, a rua continuava, como fazem as ruas, sua conversa interminável e banal."], "hard_words": ["nondescript", "supplanted", "instilled", "brevity"], "vocab": [{"word": "nondescript", "meaning": "banal", "note": ""}, {"word": "obliged", "meaning": "obrigada", "note": ""}, {"word": "supplanted", "meaning": "substituídos", "note": ""}, {"word": "nostalgia", "meaning": "nostalgia", "note": ""}, {"word": "queued", "meaning": "fizeram fila", "note": ""}, {"word": "instilled", "meaning": "instilou", "note": ""}, {"word": "brevity", "meaning": "brevidade", "note": ""}, {"word": "unremarkable", "meaning": "banal", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "was", "been", "are"], "irregular": ["stamped", "sent", "had", "endured", "chosen", "admitted", "felt", "obliged", "supplanted", "thought", "prompted", "queued", "travelled", "instilled", "paid", "learned", "worked", "folded", "said", "accustomed", "continued"], "phrasal": ["point out"], "wh": ["who"], "connectors": ["and", "though", "then", "before", "since", "yet", "or", "also", "once", "as"], "comparative": []}, "word_meanings": [{"word": "nondescript", "meaning": "banal", "note": ""}, {"word": "obliged", "meaning": "obrigada", "note": ""}, {"word": "supplanted", "meaning": "substituídos", "note": ""}, {"word": "nostalgia", "meaning": "nostalgia", "note": ""}, {"word": "queued", "meaning": "fizeram fila", "note": ""}, {"word": "instilled", "meaning": "instilou", "note": ""}, {"word": "brevity", "meaning": "brevidade", "note": ""}, {"word": "unremarkable", "meaning": "banal", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'a tradition that had endured for a century and a half' indica duração anterior."}, {"point": "As though", "explanation_pt": "'as though attempting to deposit a final coin' compara com uma imagem."}], "multiple_choice": [{"question": "What ended?", "options": ["Newspapers", "The national telegram service", "The post office", "Telephones"], "correct_index": 1, "explanation": "O serviço nacional de telegramas."}, {"question": "What was the last message?", "options": ["A business offer", "A congratulation on a baby", "A farewell", "A war order"], "correct_index": 1, "explanation": "Um parabéns por um bebê."}, {"question": "What did people do after the announcement?", "options": ["Complained", "Queued to send telegrams", "Bought phones", "Ignored it"], "correct_index": 1, "explanation": "Fizeram fila para enviar."}, {"question": "What discipline did telegrams teach?", "options": ["Writing slowly", "Learning to type", "Speaking louder", "Saying much with few words"], "correct_index": 3, "explanation": "Dizer muito com pouco."}, {"question": "What did the clerk say?", "options": ["It was a good run", "I will retire", "Never again", "I am sad"], "correct_index": 0, "explanation": "'Foi uma boa corrida.'"}], "open_questions": [{"question": "What do we lose when old technologies disappear?", "key_points_pt": ["refletir"]}, {"question": "Is brevity a virtue in communication?", "key_points_pt": ["debater"]}]}}, {"level": "C2", "genre": "news", "title": "The Price of Silence in the Summit", "paragraphs": ["At the close of the climate summit, delegates assembled for a photograph that attempted, with somewhat desperate cheerfulness, to portray unity. The final communiqué, a document of eleven pages, contained no fewer than forty uses of the verb \"recognise\" and not one of the verb \"commit\". Veteran observers read the omission as one reads a clause in a contract: with attention to what is conspicuously absent.", "Behind the closed doors, according to participants, negotiations had been conducted in the register of diplomacy at its most opaque. Small island states pleaded for binding targets; major producers insisted on \"flexibility\"; and the language that emerged was calibrated to be unobjectionable precisely because it was unenforceable. One delegate, speaking anonymously, described the process as \"the art of agreeing without having decided\".", "Yet to dismiss the summit entirely would be to misunderstand its function. Such gatherings seldom produce breakthroughs; they produce a slow sedimentation of expectations, in which norms that were unthinkable a decade ago acquire the dull authority of the obvious. A coal subsidy that once passed without comment now provokes embarrassment, and embarrassment, historians remind us, is the soft precursor to reform.", "Whether this incremental accumulation can outpace the physical processes it hopes to restrain is a question the communiqué does not address. The sea, which neither reads documents nor attends summits, will supply its own answer, and it has, so far, shown little interest in the vocabulary of recognition."], "paragraphs_pt": ["No encerramento da cúpula do clima, os delegados se reuniram para uma fotografia que tentou, com uma alegria um tanto desesperada, retratar unidade. O comunicado final, documento de onze páginas, continha nada menos que quarenta usos do verbo \"reconhecer\" e nenhum do verbo \"comprometer-se\". Observadores veteranos leram a omissão como se lê uma cláusula de contrato: com atenção ao que está conspicuamente ausente.", "Por trás das portas fechadas, segundo participantes, as negociações foram conduzidas no registro da diplomacia em sua forma mais opaca. Pequenos estados insulares imploraram por metas vinculantes; grandes produtores insistiram em \"flexibilidade\"; e a linguagem que emergiu foi calibrada para ser incontestável justamente porque era inexequível. Um delegado, falando anonimamente, descreveu o processo como \"a arte de concordar sem ter decidido\".", "Contudo, descartar a cúpula inteiramente seria entender mal sua função. Tais encontros raramente produzem avanços; produzem uma lenta sedimentação de expectativas, na qual normas impensáveis uma década atrás adquirem a autoridade opaca do óbvio. Um subsídio ao carvão que antes passava sem comentário agora provoca constrangimento, e constrangimento, lembram os historiadores, é o suave precursor da reforma.", "Se esse acúmulo incremental consegue superar os processos físicos que espera conter é uma pergunta que o comunicado não aborda. O mar, que nem lê documentos nem frequenta cúpulas, dará sua própria resposta, e até agora mostrou pouco interesse pelo vocabulário do reconhecimento."], "hard_words": ["conspicuously", "opaque", "unenforceable", "incremental"], "vocab": [{"word": "delegates", "meaning": "delegados", "note": ""}, {"word": "communiqué", "meaning": "comunicado", "note": ""}, {"word": "conspicuously", "meaning": "conspicuamente", "note": ""}, {"word": "opaque", "meaning": "opaco", "note": ""}, {"word": "binding", "meaning": "vinculante", "note": ""}, {"word": "unenforceable", "meaning": "inexequível", "note": ""}, {"word": "sedimentation", "meaning": "sedimentação", "note": ""}, {"word": "incremental", "meaning": "incremental", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "been", "was", "be", "were"], "irregular": ["assembled", "attempted", "contained", "closed", "had", "conducted", "pleaded", "insisted", "emerged", "calibrated", "described", "decided", "would", "passed", "shown"], "phrasal": [], "wh": ["what", "which"], "connectors": ["and", "because", "so", "yet", "once", "as"], "comparative": []}, "word_meanings": [{"word": "delegates", "meaning": "delegados", "note": ""}, {"word": "communiqué", "meaning": "comunicado", "note": ""}, {"word": "conspicuously", "meaning": "conspicuamente", "note": ""}, {"word": "opaque", "meaning": "opaco", "note": ""}, {"word": "binding", "meaning": "vinculante", "note": ""}, {"word": "unenforceable", "meaning": "inexequível", "note": ""}, {"word": "sedimentation", "meaning": "sedimentação", "note": ""}, {"word": "incremental", "meaning": "incremental", "note": ""}], "exercises": {"grammar": [{"point": "No fewer than", "explanation_pt": "'no fewer than forty uses' enfatiza uma quantidade grande."}, {"point": "Precisely because", "explanation_pt": "'unobjectionable precisely because it was unenforceable' dá uma razão irônica."}], "multiple_choice": [{"question": "How did the summit end?", "options": ["With a photo and a communiqué", "With a vote", "With a treaty", "With a protest"], "correct_index": 0, "explanation": "Com foto e comunicado."}, {"question": "What word was missing in the document?", "options": ["Summit", "Recognise", "Commit", "Climate"], "correct_index": 2, "explanation": "'Comprometer-se'."}, {"question": "What did island states want?", "options": ["Silence", "Money only", "Binding targets", "Flexibility"], "correct_index": 2, "explanation": "Metas vinculantes."}, {"question": "What do summits produce, according to the text?", "options": ["Wars", "Laws", "Quick solutions", "A slow shift in expectations"], "correct_index": 3, "explanation": "Mudança lenta de expectativas."}, {"question": "How does the text end?", "options": ["Summits will stop", "Coal will end", "Peace is near", "The sea will give its own answer"], "correct_index": 3, "explanation": "O mar dará sua resposta."}], "open_questions": [{"question": "Are international summits worthwhile?", "key_points_pt": ["debater"]}, {"question": "How does language hide the lack of action?", "key_points_pt": ["analisar"]}]}}, {"level": "A1", "genre": "romance", "title": "The Red Umbrella", "paragraphs": ["It is raining. Ana has no umbrella. She waits under a small tree. She is wet and cold.", "A boy comes. He has a red umbrella. \"Hello,\" he says. \"Do you want to share?\" Ana smiles. \"Yes, please!\"", "They walk together. His name is Leo. They talk about music and food. At the corner, Ana says, \"Thank you, Leo.\" He says, \"See you tomorrow?\""], "paragraphs_pt": ["Está chovendo. Ana não tem guarda-chuva. Ela espera debaixo de uma árvore pequena. Está molhada e com frio.", "Um menino chega. Ele tem um guarda-chuva vermelho. \"Olá\", ele diz. \"Quer dividir?\" Ana sorri. \"Sim, por favor!\"", "Eles caminham juntos. O nome dele é Leo. Falam de música e comida. Na esquina, Ana diz: \"Obrigada, Leo.\" Ele diz: \"Até amanhã?\""], "hard_words": ["umbrella", "share", "corner", "tomorrow"], "vocab": [{"word": "umbrella", "meaning": "guarda-chuva", "note": ""}, {"word": "wet", "meaning": "molhada", "note": ""}, {"word": "cold", "meaning": "frio", "note": ""}, {"word": "share", "meaning": "dividir", "note": ""}, {"word": "smile", "meaning": "sorrir", "note": ""}, {"word": "corner", "meaning": "esquina", "note": ""}, {"word": "tomorrow", "meaning": "amanhã", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "umbrella", "meaning": "guarda-chuva", "note": ""}, {"word": "wet", "meaning": "molhada", "note": ""}, {"word": "cold", "meaning": "frio", "note": ""}, {"word": "share", "meaning": "dividir", "note": ""}, {"word": "smile", "meaning": "sorrir", "note": ""}, {"word": "corner", "meaning": "esquina", "note": ""}, {"word": "tomorrow", "meaning": "amanhã", "note": ""}], "exercises": {"grammar": [{"point": "Do you want...?", "explanation_pt": "'Do you want to share?' é um convite simples."}], "multiple_choice": [{"question": "What is the weather?", "options": ["Windy", "Sunny", "Rainy", "Snowy"], "correct_index": 2, "explanation": "Está chovendo."}, {"question": "What color is the umbrella?", "options": ["Yellow", "Red", "Blue", "Black"], "correct_index": 1, "explanation": "Vermelho."}, {"question": "What is the boy's name?", "options": ["Tom", "Leo", "Sam", "Max"], "correct_index": 1, "explanation": "Leo."}, {"question": "What do they talk about?", "options": ["Work", "School", "Sports", "Music and food"], "correct_index": 3, "explanation": "Música e comida."}, {"question": "What does Leo ask?", "options": ["Are you hungry?", "See you tomorrow?", "Where do you live?", "What is your name?"], "correct_index": 1, "explanation": "Até amanhã?"}], "open_questions": [{"question": "What do you do on rainy days?", "key_points_pt": ["descrever"]}, {"question": "How do you meet new people?", "key_points_pt": ["descrever"]}]}}, {"level": "A1", "genre": "romance", "title": "A Letter for Mia", "paragraphs": ["Mia gets a letter. It has a small heart. She opens it. \"Dear Mia, you are kind and funny. I like your smile. Love, Sam.\"", "Mia reads it twice. Her face is red. She likes Sam too. He is in her class.", "The next day, she gives him a flower. \"Thank you for the letter,\" she says. Sam is surprised and happy. They sit together at lunch."], "paragraphs_pt": ["Mia recebe uma carta. Tem um pequeno coração. Ela a abre. \"Querida Mia, você é gentil e engraçada. Gosto do seu sorriso. Com amor, Sam.\"", "Mia lê duas vezes. O rosto dela fica vermelho. Ela também gosta do Sam. Ele é da turma dela.", "No dia seguinte, dá uma flor a ele. \"Obrigada pela carta\", diz. Sam fica surpreso e feliz. Sentam-se juntos no almoço."], "hard_words": ["letter", "kind", "flower", "surprised"], "vocab": [{"word": "letter", "meaning": "carta", "note": ""}, {"word": "heart", "meaning": "coração", "note": ""}, {"word": "kind", "meaning": "gentil", "note": ""}, {"word": "funny", "meaning": "engraçada", "note": ""}, {"word": "smile", "meaning": "sorriso", "note": ""}, {"word": "flower", "meaning": "flor", "note": ""}, {"word": "surprised", "meaning": "surpreso", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "is"], "irregular": ["surprised"], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "letter", "meaning": "carta", "note": ""}, {"word": "heart", "meaning": "coração", "note": ""}, {"word": "kind", "meaning": "gentil", "note": ""}, {"word": "funny", "meaning": "engraçada", "note": ""}, {"word": "smile", "meaning": "sorriso", "note": ""}, {"word": "flower", "meaning": "flor", "note": ""}, {"word": "surprised", "meaning": "surpreso", "note": ""}], "exercises": {"grammar": [{"point": "Like", "explanation_pt": "'I like your smile' expressa gosto."}, {"point": "Adjetivos", "explanation_pt": "'kind' e 'funny' descrevem uma pessoa."}], "multiple_choice": [{"question": "What does Mia get?", "options": ["A phone", "A cake", "A letter", "A gift"], "correct_index": 2, "explanation": "Uma carta."}, {"question": "Who writes it?", "options": ["Tom", "Leo", "Max", "Sam"], "correct_index": 3, "explanation": "Sam."}, {"question": "What does Sam like?", "options": ["Her dress", "Her car", "Her dog", "Her smile"], "correct_index": 3, "explanation": "O sorriso dela."}, {"question": "What does Mia give Sam?", "options": ["A flower", "A book", "A song", "A letter"], "correct_index": 0, "explanation": "Uma flor."}, {"question": "How does Sam feel?", "options": ["Sad", "Angry", "Surprised and happy", "Tired"], "correct_index": 2, "explanation": "Surpreso e feliz."}], "open_questions": [{"question": "Do you write letters?", "key_points_pt": ["falar"]}, {"question": "What qualities do you like in friends?", "key_points_pt": ["descrever"]}]}}, {"level": "A2", "genre": "romance", "title": "The Coffee Shop Smile", "paragraphs": ["Every morning, Elena stopped at the same coffee shop on her way to work. The barista, a young man called Marco, always remembered her order: a small coffee with milk. He wrote her name on the cup with a little star next to it.", "One Monday, Elena was very tired and sad because she had lost her keys. Marco noticed it immediately. \"Bad day?\" he asked. She nodded. When she opened the cup, she saw a message: \"Tomorrow will be better. Marco.\"", "Elena smiled for the first time that day. The next morning, she brought him a small chocolate. \"For the best coffee in the city,\" she said. Marco blushed. \"Maybe we can have a coffee together on Saturday,\" he said, \"one that I don't have to make.\""], "paragraphs_pt": ["Toda manhã, Elena parava na mesma cafeteria a caminho do trabalho. O barista, um jovem chamado Marco, sempre lembrava o pedido dela: um café pequeno com leite. Ele escrevia o nome dela no copo com uma estrelinha ao lado.", "Numa segunda, Elena estava muito cansada e triste porque perdera as chaves. Marco notou na hora. \"Dia ruim?\", perguntou. Ela assentiu. Ao abrir o copo, viu uma mensagem: \"Amanhã será melhor. Marco.\"", "Elena sorriu pela primeira vez naquele dia. Na manhã seguinte, levou um chocolatinho para ele. \"Pelo melhor café da cidade\", disse. Marco corou. \"Talvez possamos tomar um café juntos no sábado\", disse, \"um que eu não precise fazer.\""], "hard_words": ["barista", "order", "blushed", "message"], "vocab": [{"word": "coffee shop", "meaning": "cafeteria", "note": ""}, {"word": "barista", "meaning": "barista", "note": ""}, {"word": "order", "meaning": "pedido", "note": ""}, {"word": "cup", "meaning": "copo", "note": ""}, {"word": "star", "meaning": "estrela", "note": ""}, {"word": "blushed", "meaning": "corou", "note": ""}, {"word": "message", "meaning": "mensagem", "note": ""}, {"word": "maybe", "meaning": "talvez", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be"], "irregular": ["stopped", "called", "remembered", "wrote", "tired", "had", "lost", "noticed", "asked", "nodded", "opened", "saw", "smiled", "brought", "said", "blushed"], "phrasal": ["stopped at"], "wh": ["when"], "connectors": ["and", "because", "when"], "comparative": []}, "word_meanings": [{"word": "coffee shop", "meaning": "cafeteria", "note": ""}, {"word": "barista", "meaning": "barista", "note": ""}, {"word": "order", "meaning": "pedido", "note": ""}, {"word": "cup", "meaning": "copo", "note": ""}, {"word": "star", "meaning": "estrela", "note": ""}, {"word": "blushed", "meaning": "corou", "note": ""}, {"word": "message", "meaning": "mensagem", "note": ""}, {"word": "maybe", "meaning": "talvez", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'stopped', 'noticed', 'smiled' contam ações passadas."}, {"point": "Always + past", "explanation_pt": "'always remembered her order' indica hábito no passado."}], "multiple_choice": [{"question": "Where did Elena stop every morning?", "options": ["At a bank", "At a shop", "At a coffee shop", "At a school"], "correct_index": 2, "explanation": "Numa cafeteria."}, {"question": "What did Marco write on the cup?", "options": ["A joke", "Nothing", "Her name with a star", "A phone number"], "correct_index": 2, "explanation": "O nome com uma estrelinha."}, {"question": "Why was Elena sad?", "options": ["She was sick", "She lost her keys", "She lost her job", "She was late"], "correct_index": 1, "explanation": "Perdeu as chaves."}, {"question": "What was the message?", "options": ["Call me", "Have a nice day", "I'm sorry", "Tomorrow will be better"], "correct_index": 3, "explanation": "'Amanhã será melhor.'"}, {"question": "What does Marco suggest?", "options": ["A coffee together on Saturday", "A dinner", "A trip", "A movie"], "correct_index": 0, "explanation": "Um café no sábado."}], "open_questions": [{"question": "Do you have a favourite café?", "key_points_pt": ["falar"]}, {"question": "How can a small gesture change a day?", "key_points_pt": ["explicar"]}]}}, {"level": "A2", "genre": "romance", "title": "Dancing in the Kitchen", "paragraphs": ["Sofia and Diego were married for forty years. Every Friday night, they cooked dinner together and put on old songs. When their favourite song started, Diego always took Sofia's hand and danced with her around the kitchen.", "One Friday, Diego was in bed with a bad cold. Sofia cooked alone, and the kitchen felt very quiet. She turned on the radio, but the song did not sound the same. She took her plate to the bedroom and sat by his side.", "\"I cannot dance tonight,\" whispered Diego. \"That's fine,\" she said. She put the radio on the floor and played their song softly. Then she held his hand and moved it gently to the rhythm. Diego smiled. \"You still dance better than me,\" he said."], "paragraphs_pt": ["Sofia e Diego eram casados havia quarenta anos. Toda sexta à noite, cozinhavam juntos e punham músicas antigas. Quando a música favorita deles tocava, Diego sempre pegava a mão de Sofia e dançava com ela pela cozinha.", "Numa sexta, Diego estava de cama com um resfriado forte. Sofia cozinhou sozinha e a cozinha parecia muito quieta. Ligou o rádio, mas a música não soava igual. Levou o prato ao quarto e sentou-se ao lado dele.", "\"Não posso dançar esta noite\", sussurrou Diego. \"Tudo bem\", disse ela. Colocou o rádio no chão e tocou a música deles baixinho. Depois segurou a mão dele e a moveu suavemente no ritmo. Diego sorriu. \"Você ainda dança melhor que eu\", disse."], "hard_words": ["married", "favourite", "rhythm", "gently"], "vocab": [{"word": "married", "meaning": "casados", "note": ""}, {"word": "cooked", "meaning": "cozinharam", "note": ""}, {"word": "favourite", "meaning": "favorita", "note": ""}, {"word": "danced", "meaning": "dançava", "note": ""}, {"word": "cold", "meaning": "resfriado", "note": ""}, {"word": "radio", "meaning": "rádio", "note": ""}, {"word": "rhythm", "meaning": "ritmo", "note": ""}, {"word": "gently", "meaning": "suavemente", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was"], "irregular": ["married", "cooked", "started", "took", "danced", "felt", "turned", "did", "sat", "whispered", "said", "played", "held", "moved", "smiled"], "phrasal": ["put on", "turned on"], "wh": ["when"], "connectors": ["and", "but", "then", "when", "still"], "comparative": []}, "word_meanings": [{"word": "married", "meaning": "casados", "note": ""}, {"word": "cooked", "meaning": "cozinharam", "note": ""}, {"word": "favourite", "meaning": "favorita", "note": ""}, {"word": "danced", "meaning": "dançava", "note": ""}, {"word": "cold", "meaning": "resfriado", "note": ""}, {"word": "radio", "meaning": "rádio", "note": ""}, {"word": "rhythm", "meaning": "ritmo", "note": ""}, {"word": "gently", "meaning": "suavemente", "note": ""}], "exercises": {"grammar": [{"point": "Past simple e used to", "explanation_pt": "'they cooked dinner together' fala de rotina no passado."}, {"point": "Comparative", "explanation_pt": "'better than me' compara duas pessoas."}], "multiple_choice": [{"question": "How long were they married?", "options": ["Ten years", "Fifty years", "Forty years", "Four years"], "correct_index": 2, "explanation": "Quarenta anos."}, {"question": "What did they do on Fridays?", "options": ["Cooked and danced", "Went out", "Slept", "Watched TV"], "correct_index": 0, "explanation": "Cozinhavam e dançavam."}, {"question": "What was wrong with Diego?", "options": ["A headache", "Nothing", "A cold", "A broken leg"], "correct_index": 2, "explanation": "Um resfriado."}, {"question": "What did Sofia do?", "options": ["Went out", "Played their song softly", "Called a doctor", "Cried"], "correct_index": 1, "explanation": "Tocou a música baixinho."}, {"question": "What did Diego say?", "options": ["I love you", "Go away", "I'm tired", "You still dance better than me"], "correct_index": 3, "explanation": "Ela ainda dança melhor."}], "open_questions": [{"question": "What simple things make a relationship strong?", "key_points_pt": ["explicar"]}, {"question": "What song is special for you?", "key_points_pt": ["falar"]}]}}, {"level": "A2", "genre": "romance", "title": "Long-Distance Love", "paragraphs": ["Camila lives in São Paulo, and her boyfriend, Ryan, lives in Dublin. They met last summer when she visited Ireland, and now they speak every night by video call. The time difference is four hours, so she goes to bed late and he gets up early.", "It is not easy. Sometimes the connection is bad, and sometimes they are both too tired to talk. Last week, they argued about something silly, and Camila did not sleep well. But the next morning, Ryan sent a photo of a plane ticket. \"I'm coming in December,\" he wrote.", "Camila screamed with joy. She started a countdown on her phone: seventy-two days. She is going to show him the beach, the street food and the big Christmas parties. Love, she thinks, is like a bridge: long, but strong if both people build it."], "paragraphs_pt": ["Camila mora em São Paulo e o namorado, Ryan, mora em Dublin. Conheceram-se no verão passado, quando ela visitou a Irlanda, e agora falam toda noite por chamada de vídeo. A diferença de horário é de quatro horas, então ela dorme tarde e ele acorda cedo.", "Não é fácil. Às vezes a conexão é ruim e às vezes os dois estão cansados demais para conversar. Semana passada brigaram por algo bobo, e Camila dormiu mal. Mas na manhã seguinte Ryan enviou a foto de uma passagem de avião. \"Vou em dezembro\", escreveu.", "Camila gritou de alegria. Começou uma contagem regressiva no celular: setenta e dois dias. Vai mostrar a ele a praia, a comida de rua e as grandes festas de Natal. O amor, pensa ela, é como uma ponte: longa, mas forte se ambos a constroem."], "hard_words": ["connection", "argued", "countdown", "bridge"], "vocab": [{"word": "boyfriend", "meaning": "namorado", "note": ""}, {"word": "video call", "meaning": "chamada de vídeo", "note": ""}, {"word": "time difference", "meaning": "diferença de horário", "note": ""}, {"word": "connection", "meaning": "conexão", "note": ""}, {"word": "argued", "meaning": "brigaram", "note": ""}, {"word": "silly", "meaning": "bobo", "note": ""}, {"word": "countdown", "meaning": "contagem regressiva", "note": ""}, {"word": "bridge", "meaning": "ponte", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": ["met", "visited", "tired", "argued", "did", "sent", "wrote", "screamed", "started"], "phrasal": ["gets up", "screamed with"], "wh": ["when"], "connectors": ["and", "but", "so", "when", "if"], "comparative": []}, "word_meanings": [{"word": "boyfriend", "meaning": "namorado", "note": ""}, {"word": "video call", "meaning": "chamada de vídeo", "note": ""}, {"word": "time difference", "meaning": "diferença de horário", "note": ""}, {"word": "connection", "meaning": "conexão", "note": ""}, {"word": "argued", "meaning": "brigaram", "note": ""}, {"word": "silly", "meaning": "bobo", "note": ""}, {"word": "countdown", "meaning": "contagem regressiva", "note": ""}, {"word": "bridge", "meaning": "ponte", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "'lives', 'speak' descrevem rotina."}, {"point": "Going to", "explanation_pt": "'She is going to show him the beach' fala de plano."}], "multiple_choice": [{"question": "Where does Camila live?", "options": ["Paris", "São Paulo", "London", "Dublin"], "correct_index": 1, "explanation": "São Paulo."}, {"question": "How often do they speak?", "options": ["Never", "Every night", "Once a month", "Every year"], "correct_index": 1, "explanation": "Toda noite."}, {"question": "What did they argue about?", "options": ["Something silly", "Work", "Family", "Money"], "correct_index": 0, "explanation": "Algo bobo."}, {"question": "What did Ryan send?", "options": ["A song", "A gift", "A letter", "A photo of a plane ticket"], "correct_index": 3, "explanation": "Foto de passagem."}, {"question": "What is love like, for Camila?", "options": ["A song", "A house", "A bridge", "A river"], "correct_index": 2, "explanation": "Uma ponte."}], "open_questions": [{"question": "Do you have friends far away?", "key_points_pt": ["falar"]}, {"question": "How can people stay close from far away?", "key_points_pt": ["sugerir"]}]}}, {"level": "B1", "genre": "romance", "title": "The Wrong Table", "paragraphs": ["When Isabel arrived at the restaurant for her blind date, she was nervous. Her friend had described the man as \"tall, funny and wearing a blue scarf\". She looked around and saw a man with a blue scarf sitting at a table near the window. She walked up and said hello.", "The man looked surprised but invited her to sit. They talked for almost an hour about their jobs, their families and their favourite films. Isabel found him charming. But when the waiter arrived with two menus, the man said awkwardly, \"I think there's been a mistake. I'm waiting for my sister.\"", "Isabel turned red. At that moment, another tall man with a blue scarf entered, looked at her and waved. It was her real date. The first man laughed. \"Well, I enjoyed your company more than I expected,\" he said, and handed her a card with his number.", "Isabel had dinner with her real date, who turned out to be dull and talked only about cars. Two days later, she sent a message to the man from the wrong table. Today, they say that the best things in life happen by mistake."], "paragraphs_pt": ["Quando Isabel chegou ao restaurante para seu encontro às cegas, estava nervosa. A amiga descrevera o homem como \"alto, engraçado e de cachecol azul\". Olhou em volta e viu um homem de cachecol azul sentado a uma mesa perto da janela. Aproximou-se e disse olá.", "O homem pareceu surpreso, mas a convidou a sentar. Conversaram por quase uma hora sobre trabalhos, famílias e filmes favoritos. Isabel o achou encantador. Mas quando o garçom chegou com dois cardápios, o homem disse, sem jeito: \"Acho que houve um engano. Estou esperando minha irmã.\"", "Isabel ficou vermelha. Nesse momento entrou outro homem alto de cachecol azul, olhou para ela e acenou. Era seu encontro de verdade. O primeiro homem riu. \"Bem, gostei da sua companhia mais do que esperava\", disse, e lhe entregou um cartão com o número.", "Isabel jantou com o encontro de verdade, que se revelou chato e só falava de carros. Dois dias depois, mandou uma mensagem ao homem da mesa errada. Hoje, dizem que as melhores coisas da vida acontecem por engano."], "hard_words": ["charming", "awkwardly", "company", "dull"], "vocab": [{"word": "blind date", "meaning": "encontro às cegas", "note": ""}, {"word": "scarf", "meaning": "cachecol", "note": ""}, {"word": "charming", "meaning": "encantador", "note": ""}, {"word": "awkwardly", "meaning": "sem jeito", "note": ""}, {"word": "mistake", "meaning": "engano", "note": ""}, {"word": "company", "meaning": "companhia", "note": ""}, {"word": "dull", "meaning": "chato, sem graça", "note": ""}, {"word": "waved", "meaning": "acenou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "be"], "irregular": ["arrived", "had", "described", "looked", "saw", "walked", "said", "surprised", "invited", "talked", "found", "turned", "entered", "waved", "laughed", "enjoyed", "expected", "handed", "sent"], "phrasal": ["walked up", "turned out"], "wh": ["who", "when"], "connectors": ["and", "but", "when", "as"], "comparative": []}, "word_meanings": [{"word": "blind date", "meaning": "encontro às cegas", "note": ""}, {"word": "scarf", "meaning": "cachecol", "note": ""}, {"word": "charming", "meaning": "encantador", "note": ""}, {"word": "awkwardly", "meaning": "sem jeito", "note": ""}, {"word": "mistake", "meaning": "engano", "note": ""}, {"word": "company", "meaning": "companhia", "note": ""}, {"word": "dull", "meaning": "chato, sem graça", "note": ""}, {"word": "waved", "meaning": "acenou", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Her friend had described the man' mostra a descrição anterior."}, {"point": "Than + expected", "explanation_pt": "'more than I expected' compara resultado e expectativa."}], "multiple_choice": [{"question": "Why was Isabel at the restaurant?", "options": ["A party", "A blind date", "A business lunch", "A family dinner"], "correct_index": 1, "explanation": "Um encontro às cegas."}, {"question": "What mistake did she make?", "options": ["She went to the wrong city", "She lost her phone", "She forgot the time", "She sat with the wrong man"], "correct_index": 3, "explanation": "Sentou com o homem errado."}, {"question": "Who was the first man waiting for?", "options": ["His wife", "His boss", "His sister", "His friend"], "correct_index": 2, "explanation": "Sua irmã."}, {"question": "How was the real date?", "options": ["Rude", "Dull", "Funny", "Late"], "correct_index": 1, "explanation": "Chato."}, {"question": "What did Isabel do two days later?", "options": ["Called her friend", "Messaged the man from the wrong table", "Moved", "Quit dating"], "correct_index": 1, "explanation": "Mandou mensagem ao homem errado."}], "open_questions": [{"question": "Do you believe in fate?", "key_points_pt": ["opinar"]}, {"question": "What is the best way to meet someone?", "key_points_pt": ["debater"]}]}}, {"level": "B1", "genre": "romance", "title": "Letters Across the Hall", "paragraphs": ["Theo and Nora lived in neighbouring apartments but had never spoken. They only met in the elevator, where they exchanged polite nods. One evening, Theo found a note slipped under his door: \"Your piano playing is lovely. Please don't stop.\" It was signed with a single N.", "He did not know what to do. In the end, he wrote an answer: \"Thank you. What would you like me to play?\" The next day, he found a new note: \"Something sad, please. It has been a hard week.\" That night, he played the slowest piece he knew.", "For months, they exchanged messages under the door, sharing songs, jokes and small worries. They never mentioned meeting. They both seemed to enjoy the mystery and the honesty it allowed. Theo realised that he told Nora things he had never told anyone.", "One spring morning, he wrote: \"Would you like to have coffee?\" The reply arrived within minutes, and it was not a note but a knock on the door. Nora stood there, smiling nervously. \"I thought,\" she said, \"that we could start with the coffee.\""], "paragraphs_pt": ["Theo e Nora moravam em apartamentos vizinhos, mas nunca haviam conversado. Só se encontravam no elevador, onde trocavam acenos educados. Numa noite, Theo achou um bilhete enfiado sob a porta: \"Seu piano é lindo. Por favor, não pare.\" Estava assinado com um único N.", "Ele não sabia o que fazer. Por fim, escreveu uma resposta: \"Obrigado. O que gostaria que eu tocasse?\" No dia seguinte, achou um novo bilhete: \"Algo triste, por favor. Foi uma semana difícil.\" Naquela noite, tocou a peça mais lenta que conhecia.", "Por meses, trocaram mensagens sob a porta, compartilhando músicas, piadas e pequenas preocupações. Nunca mencionaram se encontrar. Ambos pareciam gostar do mistério e da honestidade que ele permitia. Theo percebeu que contava a Nora coisas que nunca contara a ninguém.", "Numa manhã de primavera, escreveu: \"Quer tomar um café?\" A resposta veio em minutos, e não era um bilhete, mas uma batida na porta. Nora estava lá, sorrindo nervosa. \"Pensei\", disse, \"que poderíamos começar pelo café.\""], "hard_words": ["neighbouring", "slipped", "honesty", "knock"], "vocab": [{"word": "neighbouring", "meaning": "vizinhos", "note": ""}, {"word": "elevator", "meaning": "elevador", "note": ""}, {"word": "slipped", "meaning": "enfiado", "note": ""}, {"word": "signed", "meaning": "assinado", "note": ""}, {"word": "worries", "meaning": "preocupações", "note": ""}, {"word": "mystery", "meaning": "mistério", "note": ""}, {"word": "honesty", "meaning": "honestidade", "note": ""}, {"word": "knock", "meaning": "batida", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was", "been"], "irregular": ["lived", "had", "spoken", "met", "exchanged", "found", "slipped", "signed", "did", "wrote", "would", "played", "knew", "mentioned", "seemed", "allowed", "realised", "told", "arrived", "stood", "thought", "said", "could"], "phrasal": ["found a note", "stood there"], "wh": ["what", "where"], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "neighbouring", "meaning": "vizinhos", "note": ""}, {"word": "elevator", "meaning": "elevador", "note": ""}, {"word": "slipped", "meaning": "enfiado", "note": ""}, {"word": "signed", "meaning": "assinado", "note": ""}, {"word": "worries", "meaning": "preocupações", "note": ""}, {"word": "mystery", "meaning": "mistério", "note": ""}, {"word": "honesty", "meaning": "honestidade", "note": ""}, {"word": "knock", "meaning": "batida", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had never spoken' mostra que antes não conversavam."}, {"point": "Would you like", "explanation_pt": "'Would you like to have coffee?' convida educadamente."}], "multiple_choice": [{"question": "Where did Theo and Nora meet?", "options": ["At a party", "In the elevator", "In a café", "In a school"], "correct_index": 1, "explanation": "No elevador."}, {"question": "How did Nora first contact him?", "options": ["A letter", "An email", "A note under his door", "A phone call"], "correct_index": 2, "explanation": "Um bilhete sob a porta."}, {"question": "What did she ask him to play?", "options": ["Something sad", "Something happy", "Something fast", "Nothing"], "correct_index": 0, "explanation": "Algo triste."}, {"question": "What did they exchange for months?", "options": ["Gifts", "Photos", "Notes under the door", "Calls"], "correct_index": 2, "explanation": "Bilhetes."}, {"question": "How did the story end?", "options": ["They argued", "Theo moved", "Nora knocked on the door", "They stopped"], "correct_index": 2, "explanation": "Nora bateu à porta."}], "open_questions": [{"question": "Is it easier to be honest without seeing someone?", "key_points_pt": ["debater"]}, {"question": "How do small gestures start friendships?", "key_points_pt": ["explicar"]}]}}, {"level": "B2", "genre": "romance", "title": "The Second Time Around", "paragraphs": ["Fifteen years after their divorce, Helena and Victor found themselves seated beside each other at their daughter's wedding. The arrangement was either an oversight or, more probably, a conspiracy by the bride. They exchanged a tight smile and focused on their plates with the intensity of people defusing a bomb.", "Gradually, however, the music and the wine softened the atmosphere. They talked about their daughter, about the house they had once shared, and about the absurd quarrel over a sofa that had ended their marriage. \"We were so young,\" Victor said. \"And so stubborn,\" Helena replied. They both laughed, and the laughter surprised them.", "Later that evening, they danced one song, politely and with a visible distance between them. Neither had planned it. In that dance, however, Helena noticed something unexpected: the lack of resentment, as if time had washed away the sharper edges and left only an odd, calm tenderness.", "They did not rush into anything. A few weeks later, Victor invited her to see a film, \"as friends,\" he specified. They have been seeing films ever since. Whether they will remarry, neither knows. What they have discovered is that endings, like beginnings, are rarely final."], "paragraphs_pt": ["Quinze anos após o divórcio, Helena e Victor se viram sentados lado a lado no casamento da filha. A disposição era um descuido ou, mais provavelmente, uma conspiração da noiva. Trocaram um sorriso tenso e concentraram-se nos pratos com a intensidade de quem desarma uma bomba.", "Aos poucos, porém, a música e o vinho amenizaram o clima. Falaram da filha, da casa que um dia dividiram e da briga absurda por um sofá que acabou com o casamento. \"Éramos tão jovens\", disse Victor. \"E tão teimosos\", respondeu Helena. Riram, e o riso os surpreendeu.", "Mais tarde naquela noite, dançaram uma música, com educação e com uma distância visível entre eles. Nenhum dos dois planejara. Naquela dança, porém, Helena notou algo inesperado: a falta de ressentimento, como se o tempo tivesse lavado as arestas mais agudas e deixado apenas uma terna e estranha calma.", "Não se apressaram. Algumas semanas depois, Victor a convidou para ver um filme, \"como amigos\", especificou. Veem filmes desde então. Se vão se casar de novo, nenhum dos dois sabe. O que descobriram é que fins, como começos, raramente são finais."], "hard_words": ["oversight", "quarrel", "resentment", "tenderness"], "vocab": [{"word": "divorce", "meaning": "divórcio", "note": ""}, {"word": "oversight", "meaning": "descuido", "note": ""}, {"word": "conspiracy", "meaning": "conspiração", "note": ""}, {"word": "defusing", "meaning": "desarmando", "note": ""}, {"word": "quarrel", "meaning": "briga", "note": ""}, {"word": "stubborn", "meaning": "teimosos", "note": ""}, {"word": "resentment", "meaning": "ressentimento", "note": ""}, {"word": "tenderness", "meaning": "ternura", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been", "is", "are"], "irregular": ["found", "seated", "exchanged", "focused", "softened", "talked", "had", "shared", "ended", "said", "replied", "laughed", "surprised", "danced", "planned", "noticed", "washed", "left", "did", "invited", "specified", "discovered"], "phrasal": ["washed away", "rush into"], "wh": ["what"], "connectors": ["and", "however", "so", "after", "since", "or", "once", "if", "as"], "comparative": []}, "word_meanings": [{"word": "divorce", "meaning": "divórcio", "note": ""}, {"word": "oversight", "meaning": "descuido", "note": ""}, {"word": "conspiracy", "meaning": "conspiração", "note": ""}, {"word": "defusing", "meaning": "desarmando", "note": ""}, {"word": "quarrel", "meaning": "briga", "note": ""}, {"word": "stubborn", "meaning": "teimosos", "note": ""}, {"word": "resentment", "meaning": "ressentimento", "note": ""}, {"word": "tenderness", "meaning": "ternura", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'the house they had once shared' mostra o passado do casal."}, {"point": "Present perfect continuous", "explanation_pt": "'have been seeing films ever since' mostra continuidade."}], "multiple_choice": [{"question": "How long after the divorce did they meet?", "options": ["Thirty years", "Fifteen years", "Five years", "One year"], "correct_index": 1, "explanation": "Quinze anos depois."}, {"question": "Where were they seated?", "options": ["At a funeral", "At a party", "At a restaurant", "Next to each other at a wedding"], "correct_index": 3, "explanation": "Lado a lado no casamento."}, {"question": "What ended their marriage?", "options": ["Money", "Another person", "A quarrel over a sofa", "Work"], "correct_index": 2, "explanation": "Briga por um sofá."}, {"question": "What did Helena notice while dancing?", "options": ["The lack of resentment", "Anger", "Boredom", "Regret"], "correct_index": 0, "explanation": "A falta de ressentimento."}, {"question": "What do they do now?", "options": ["They argue", "They see films together", "They live together", "They avoid each other"], "correct_index": 1, "explanation": "Veem filmes juntos."}], "open_questions": [{"question": "Can old relationships become friendships?", "key_points_pt": ["debater"]}, {"question": "What makes forgiveness easier over time?", "key_points_pt": ["explicar"]}]}}, {"level": "B2", "genre": "romance", "title": "The Translator's Love", "paragraphs": ["Lucas worked as a translator of novels, an occupation that had accustomed him to living inside other people's emotions without exposing his own. When a small publisher assigned him a romance by a Polish author, he did not expect the project to change his life. The author, Kasia, had a style so intimate that he sometimes felt he was reading her private letters.", "He wrote to her with questions about idioms, and she answered with long, witty emails. Gradually, their exchanges drifted from words to opinions, from opinions to childhood memories. She mentioned a lake in her village that froze every January; he described the noisy seafront where he grew up. They began to speak every week.", "When the translation was finished, a curious emptiness took over. Lucas realised that the work had provided an excuse to talk, and he had no excuse left. He considered silence, but eventually he wrote the bravest sentence of his career: \"I have translated your book, but I can't find the word for what I feel.\"", "Kasia's answer arrived the next morning, in Polish, with no translation. Lucas spent an hour with a dictionary, deciphering it. When he finally understood it, he laughed aloud, booked a flight and went to see the lake that froze every January."], "paragraphs_pt": ["Lucas trabalhava como tradutor de romances, ocupação que o acostumara a viver dentro das emoções alheias sem expor as próprias. Quando uma pequena editora lhe designou um romance de uma autora polonesa, não esperava que o projeto mudasse sua vida. A autora, Kasia, tinha um estilo tão íntimo que às vezes ele sentia estar lendo suas cartas privadas.", "Escrevia-lhe com dúvidas sobre expressões idiomáticas e ela respondia com e-mails longos e espirituosos. Aos poucos, as trocas foram de palavras a opiniões, de opiniões a memórias de infância. Ela mencionou um lago em sua aldeia que congelava todo janeiro; ele descreveu a orla barulhenta onde cresceu. Passaram a conversar toda semana.", "Quando a tradução terminou, um vazio curioso se instalou. Lucas percebeu que o trabalho fora uma desculpa para conversar, e já não tinha desculpa. Pensou no silêncio, mas por fim escreveu a frase mais corajosa de sua carreira: \"Traduzi seu livro, mas não encontro a palavra para o que sinto.\"", "A resposta de Kasia chegou na manhã seguinte, em polonês, sem tradução. Lucas passou uma hora com um dicionário, decifrando-a. Quando enfim entendeu, riu alto, comprou uma passagem e foi ver o lago que congelava todo janeiro."], "hard_words": ["accustomed", "idioms", "emptiness", "deciphering"], "vocab": [{"word": "translator", "meaning": "tradutor", "note": ""}, {"word": "accustomed", "meaning": "acostumado", "note": ""}, {"word": "publisher", "meaning": "editora", "note": ""}, {"word": "idioms", "meaning": "expressões idiomáticas", "note": ""}, {"word": "witty", "meaning": "espirituosos", "note": ""}, {"word": "emptiness", "meaning": "vazio", "note": ""}, {"word": "deciphering", "meaning": "decifrando", "note": ""}, {"word": "flight", "meaning": "voo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["worked", "had", "accustomed", "assigned", "did", "felt", "wrote", "answered", "drifted", "mentioned", "froze", "described", "grew", "began", "finished", "took", "realised", "provided", "left", "considered", "translated", "arrived", "spent", "understood", "laughed", "booked", "went"], "phrasal": ["drifted from", "took over"], "wh": ["what", "where", "when"], "connectors": ["and", "but", "so", "when", "finally", "as"], "comparative": []}, "word_meanings": [{"word": "translator", "meaning": "tradutor", "note": ""}, {"word": "accustomed", "meaning": "acostumado", "note": ""}, {"word": "publisher", "meaning": "editora", "note": ""}, {"word": "idioms", "meaning": "expressões idiomáticas", "note": ""}, {"word": "witty", "meaning": "espirituosos", "note": ""}, {"word": "emptiness", "meaning": "vazio", "note": ""}, {"word": "deciphering", "meaning": "decifrando", "note": ""}, {"word": "flight", "meaning": "voo", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'an occupation that had accustomed him' mostra efeito anterior."}, {"point": "Gradually", "explanation_pt": "'Gradually, their exchanges drifted' marca mudança lenta."}], "multiple_choice": [{"question": "What was Lucas's job?", "options": ["Writer", "Editor", "Teacher", "Novel translator"], "correct_index": 3, "explanation": "Tradutor de romances."}, {"question": "Who was Kasia?", "options": ["A sister", "A Polish author", "A teacher", "A publisher"], "correct_index": 1, "explanation": "Autora polonesa."}, {"question": "What happened after the translation?", "options": ["He moved", "He quit", "He got a promotion", "He felt emptiness"], "correct_index": 3, "explanation": "Sentiu vazio."}, {"question": "What did Lucas write?", "options": ["He needed money", "He loved her book", "He couldn't find a word for what he felt", "He was sorry"], "correct_index": 2, "explanation": "Não encontrava a palavra."}, {"question": "What did he do after her answer?", "options": ["Booked a flight to see the lake", "Ignored it", "Replied in English", "Called a friend"], "correct_index": 0, "explanation": "Comprou passagem."}], "open_questions": [{"question": "Can love begin through words?", "key_points_pt": ["debater"]}, {"question": "What is hard to translate between cultures?", "key_points_pt": ["explicar"]}]}}, {"level": "C1", "genre": "romance", "title": "The Weight of Unsent Letters", "paragraphs": ["In the drawer of her late husband's desk, Miriam found a bundle of letters addressed to her, none of which had ever been posted. The earliest was dated forty years ago, the most recent a fortnight before his death. She held them for an entire afternoon without opening them, as if the envelope might contain more than she could bear.", "When she finally read them, she discovered a man she had not entirely known. Here were the apologies he had been too proud to utter, the praises he had been too shy to give, and the small observations, her habit of humming while she cooked, the way she folded napkins, that revealed how closely he had attended to her. Love, it seemed, had been conducted in a language of postponement.", "She was torn between gratitude and anger. Why had he not simply said these things aloud, while there was still time for her to answer? Yet she recognised, with the clarity that grief sometimes confers, that she had also withheld words, assuming there would be an unlimited supply of tomorrows.", "That evening, she began a letter of her own. It was not an answer, which would have been absurd, but a record of everything she had left unsaid. She decided to post it to their daughter, together with a note: \"Speak sooner than we did.\" It was the one inheritance she was sure she could pass on."], "paragraphs_pt": ["Na gaveta da escrivaninha do falecido marido, Miriam encontrou um maço de cartas endereçadas a ela, nenhuma das quais fora postada. A mais antiga era datada de quarenta anos atrás, a mais recente de quinze dias antes da morte dele. Segurou-as uma tarde inteira sem abri-las, como se o envelope pudesse conter mais do que ela suportaria.", "Quando finalmente as leu, descobriu um homem que não conhecera inteiramente. Ali estavam as desculpas que ele fora orgulhoso demais para proferir, os elogios que fora tímido demais para dar e as pequenas observações, seu hábito de cantarolar enquanto cozinhava, o modo como dobrava guardanapos, que revelavam quão de perto ele a observara. O amor, ao que parecia, fora conduzido numa linguagem de adiamento.", "Dividiu-se entre gratidão e raiva. Por que ele não dissera essas coisas em voz alta, enquanto ainda havia tempo para ela responder? Mas reconheceu, com a clareza que o luto às vezes confere, que também ela retivera palavras, supondo haver uma oferta ilimitada de amanhãs.", "Naquela noite, começou uma carta sua. Não era resposta, o que seria absurdo, mas um registro de tudo que deixara por dizer. Decidiu enviá-la à filha, junto com um bilhete: \"Falem mais cedo do que nós falamos.\" Era a única herança que tinha certeza de poder transmitir."], "hard_words": ["fortnight", "utter", "postponement", "withheld"], "vocab": [{"word": "bundle", "meaning": "maço", "note": ""}, {"word": "posted", "meaning": "postadas", "note": ""}, {"word": "fortnight", "meaning": "quinze dias", "note": ""}, {"word": "utter", "meaning": "proferir", "note": ""}, {"word": "humming", "meaning": "cantarolando", "note": ""}, {"word": "postponement", "meaning": "adiamento", "note": ""}, {"word": "withheld", "meaning": "reteve", "note": ""}, {"word": "inheritance", "meaning": "herança", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "were", "be"], "irregular": ["found", "addressed", "had", "posted", "dated", "held", "might", "could", "discovered", "known", "cooked", "folded", "revealed", "attended", "seemed", "conducted", "torn", "said", "recognised", "withheld", "would", "began", "left", "unsaid", "decided", "did"], "phrasal": ["pass on", "torn between"], "wh": ["when", "why", "how", "which"], "connectors": ["and", "but", "while", "before", "when", "yet", "also", "finally", "still", "if", "as"], "comparative": []}, "word_meanings": [{"word": "bundle", "meaning": "maço", "note": ""}, {"word": "posted", "meaning": "postadas", "note": ""}, {"word": "fortnight", "meaning": "quinze dias", "note": ""}, {"word": "utter", "meaning": "proferir", "note": ""}, {"word": "humming", "meaning": "cantarolando", "note": ""}, {"word": "postponement", "meaning": "adiamento", "note": ""}, {"word": "withheld", "meaning": "reteve", "note": ""}, {"word": "inheritance", "meaning": "herança", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'none of which had ever been posted' mostra o estado das cartas."}, {"point": "Too + adjetivo + to", "explanation_pt": "'too proud to utter' expressa um obstáculo."}], "multiple_choice": [{"question": "What did Miriam find?", "options": ["Photos", "Money", "Unsent letters from her husband", "A will"], "correct_index": 2, "explanation": "Cartas não enviadas."}, {"question": "How long span did the letters cover?", "options": ["Forty years", "Four months", "One year", "Ten years"], "correct_index": 0, "explanation": "Quarenta anos."}, {"question": "How did she feel?", "options": ["Torn between gratitude and anger", "Only sad", "Only happy", "Bored"], "correct_index": 0, "explanation": "Entre gratidão e raiva."}, {"question": "What did she realise about herself?", "options": ["She was angry", "She was perfect", "She also withheld words", "She was lucky"], "correct_index": 2, "explanation": "Ela também retivera palavras."}, {"question": "What message does she send her daughter?", "options": ["Move abroad", "Write letters", "Save money", "Speak sooner than we did"], "correct_index": 3, "explanation": "'Falem mais cedo.'"}], "open_questions": [{"question": "Why do people postpone saying important things?", "key_points_pt": ["discutir"]}, {"question": "What would you want to say to someone today?", "key_points_pt": ["refletir"]}]}}, {"level": "C1", "genre": "romance", "title": "Neither Here nor There", "paragraphs": ["Soraya and Dmitri had met on the day she was leaving the country, a coincidence that both of them subsequently regarded as the universe's idea of a joke. For eight months they conducted what could charitably be called a relationship, though it consisted largely of poorly lit video calls, misunderstood messages and a persistent, mutual apology for the time difference.", "Neither was willing to relocate. She had a career half-built in one continent; he had an elderly mother in another. They discussed the matter with the careful politeness of two diplomats negotiating a treaty neither wished to sign. The more reasonable the arguments became, the more painful the silence between them.", "Eventually, they decided to end it, not with a quarrel but with a long, affectionate call in which they thanked each other for the months of tenderness. It would be tempting to describe it as a failure; Soraya, however, resisted the temptation. She had learned that a relationship need not last to be real, nor end in disaster to be over.", "Years later, she still received a postcard from Dmitri every December, always showing a picture of some modest seaside town and always signed with the same abbreviation. They never spoke of what might have been. It was, she supposed, a form of fidelity: not to a future that had been abandoned, but to a past that had been honestly lived."], "paragraphs_pt": ["Soraya e Dmitri se conheceram no dia em que ela deixava o país, coincidência que ambos posteriormente consideraram a ideia de piada do universo. Por oito meses conduziram o que caridosamente se poderia chamar de relacionamento, embora consistisse sobretudo de videochamadas mal iluminadas, mensagens mal entendidas e um pedido de desculpas mútuo e persistente pela diferença de fuso.", "Nenhum dos dois estava disposto a se mudar. Ela tinha uma carreira pela metade em um continente; ele, uma mãe idosa em outro. Discutiram o assunto com a educação cuidadosa de dois diplomatas negociando um tratado que nenhum desejava assinar. Quanto mais razoáveis os argumentos, mais doloroso o silêncio entre eles.", "Por fim decidiram terminar, não com uma briga, mas com uma longa e afetuosa ligação em que agradeceram um ao outro pelos meses de ternura. Seria tentador descrever como um fracasso; Soraya, porém, resistiu à tentação. Aprendera que um relacionamento não precisa durar para ser real, nem terminar em desastre para acabar.", "Anos depois, ainda recebia um cartão-postal de Dmitri todo dezembro, sempre com a imagem de uma modesta cidade litorânea e sempre assinado com a mesma abreviatura. Nunca falaram do que poderia ter sido. Era, supunha ela, uma forma de fidelidade: não a um futuro abandonado, mas a um passado honestamente vivido."], "hard_words": ["charitably", "relocate", "treaty", "fidelity"], "vocab": [{"word": "coincidence", "meaning": "coincidência", "note": ""}, {"word": "charitably", "meaning": "caridosamente", "note": ""}, {"word": "persistent", "meaning": "persistente", "note": ""}, {"word": "relocate", "meaning": "mudar-se", "note": ""}, {"word": "diplomats", "meaning": "diplomatas", "note": ""}, {"word": "treaty", "meaning": "tratado", "note": ""}, {"word": "abbreviation", "meaning": "abreviatura", "note": ""}, {"word": "fidelity", "meaning": "fidelidade", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "been"], "irregular": ["had", "met", "regarded", "conducted", "could", "called", "consisted", "lit", "misunderstood", "built", "discussed", "wished", "became", "decided", "thanked", "would", "resisted", "learned", "received", "signed", "spoke", "might", "supposed", "abandoned", "lived"], "phrasal": ["end it"], "wh": ["what", "which"], "connectors": ["and", "but", "however", "though", "still", "as"], "comparative": []}, "word_meanings": [{"word": "coincidence", "meaning": "coincidência", "note": ""}, {"word": "charitably", "meaning": "caridosamente", "note": ""}, {"word": "persistent", "meaning": "persistente", "note": ""}, {"word": "relocate", "meaning": "mudar-se", "note": ""}, {"word": "diplomats", "meaning": "diplomatas", "note": ""}, {"word": "treaty", "meaning": "tratado", "note": ""}, {"word": "abbreviation", "meaning": "abreviatura", "note": ""}, {"word": "fidelity", "meaning": "fidelidade", "note": ""}], "exercises": {"grammar": [{"point": "Neither / nor", "explanation_pt": "'Neither was willing to relocate' nega os dois."}, {"point": "The more... the more", "explanation_pt": "'The more reasonable the arguments became, the more painful the silence' mostra proporção."}], "multiple_choice": [{"question": "When did they meet?", "options": ["At a wedding", "The day she was leaving", "At school", "At work"], "correct_index": 1, "explanation": "No dia em que ela partia."}, {"question": "What did their relationship consist of?", "options": ["Trips", "Visits", "Letters", "Video calls and messages"], "correct_index": 3, "explanation": "Videochamadas e mensagens."}, {"question": "Why did neither relocate?", "options": ["Her career and his mother", "Fear", "Language", "Money"], "correct_index": 0, "explanation": "Carreira dela e mãe dele."}, {"question": "How did they end it?", "options": ["In silence", "With a letter", "With an affectionate call", "With a fight"], "correct_index": 2, "explanation": "Com uma ligação afetuosa."}, {"question": "What is the postcard a sign of?", "options": ["A kind of fidelity to a lived past", "An apology", "A joke", "A plan"], "correct_index": 0, "explanation": "Fidelidade a um passado vivido."}], "open_questions": [{"question": "Can a relationship be meaningful without lasting?", "key_points_pt": ["debater"]}, {"question": "What makes long-distance relationships hard?", "key_points_pt": ["explicar"]}]}}, {"level": "C2", "genre": "romance", "title": "A Grammar of Departures", "paragraphs": ["They had learned each other, as lovers do, through vocabulary: the particular word he used for tiredness, her unorthodox name for the smell of rain. Over time these private terms had thickened into a dialect that nobody else could speak, and Ines sometimes suspected that what she loved was not so much the man as the language they had built together.", "When the end came, it came in the declensions of ordinary speech. He began to say \"I\" where he had once said \"we\"; she noticed it with the grim attentiveness of a philologist observing the death of a tongue. There was no betrayal, no dramatic revelation, only a quiet erosion of the plural. She considered confronting him, but what could one say? That a pronoun was missing?", "They parted without ceremony on a Tuesday, shaking hands almost, like colleagues leaving a project. Afterward Ines found that her sentences were suddenly full of gaps, shaped like him. She would reach for a word and find the place where it had lived, an empty room whose door still bore the name.", "It took her years to understand that she had not lost a person but a grammar. Yet she also recognised, with a sorrow that was oddly consoling, that grammars can be learned again. Some day, with someone, she would speak a different language, and the old one, honourably silent, would remain in her like a dead language studied for its beauty alone."], "paragraphs_pt": ["Eles haviam aprendido um ao outro, como fazem os amantes, pelo vocabulário: a palavra particular que ele usava para cansaço, o nome pouco ortodoxo que ela dava ao cheiro de chuva. Com o tempo esses termos privados espessaram-se num dialeto que ninguém mais falava, e Ines às vezes suspeitava que o que amava não era tanto o homem, mas a língua que haviam construído juntos.", "Quando o fim chegou, chegou nas declinações da fala comum. Ele começou a dizer \"eu\" onde antes dizia \"nós\"; ela percebeu com a atenção sinistra de uma filóloga observando a morte de uma língua. Não houve traição, revelação dramática, apenas uma erosão silenciosa do plural. Pensou em confrontá-lo, mas o que se podia dizer? Que um pronome estava faltando?", "Separaram-se sem cerimônia numa terça, quase apertando as mãos, como colegas deixando um projeto. Depois Ines descobriu que suas frases estavam de repente cheias de lacunas, no formato dele. Buscava uma palavra e encontrava o lugar onde ela vivera, um quarto vazio cuja porta ainda levava o nome.", "Levou anos para entender que não perdera uma pessoa, mas uma gramática. Contudo, também reconheceu, com uma tristeza estranhamente consoladora, que gramáticas podem ser aprendidas de novo. Algum dia, com alguém, falaria outra língua, e a antiga, honrosamente silenciosa, permaneceria nela como uma língua morta estudada só pela beleza."], "hard_words": ["unorthodox", "philologist", "erosion", "consoling"], "vocab": [{"word": "unorthodox", "meaning": "pouco ortodoxo", "note": ""}, {"word": "thickened", "meaning": "espessaram-se", "note": ""}, {"word": "dialect", "meaning": "dialeto", "note": ""}, {"word": "declensions", "meaning": "declinações", "note": ""}, {"word": "philologist", "meaning": "filóloga", "note": ""}, {"word": "erosion", "meaning": "erosão", "note": ""}, {"word": "consoling", "meaning": "consoladora", "note": ""}, {"word": "honourably", "meaning": "honrosamente", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "be"], "irregular": ["had", "learned", "used", "thickened", "could", "suspected", "loved", "built", "came", "began", "said", "noticed", "considered", "parted", "found", "shaped", "would", "lived", "bore", "took", "lost", "recognised", "studied"], "phrasal": ["reach for", "parted without"], "wh": ["what", "where", "when", "whose"], "connectors": ["and", "but", "so", "when", "yet", "also", "suddenly", "still", "once", "as"], "comparative": []}, "word_meanings": [{"word": "unorthodox", "meaning": "pouco ortodoxo", "note": ""}, {"word": "thickened", "meaning": "espessaram-se", "note": ""}, {"word": "dialect", "meaning": "dialeto", "note": ""}, {"word": "declensions", "meaning": "declinações", "note": ""}, {"word": "philologist", "meaning": "filóloga", "note": ""}, {"word": "erosion", "meaning": "erosão", "note": ""}, {"word": "consoling", "meaning": "consoladora", "note": ""}, {"word": "honourably", "meaning": "honrosamente", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'They had learned each other' mostra um processo anterior."}, {"point": "Not so much... as", "explanation_pt": "'not so much the man as the language' compara o que importava mais."}], "multiple_choice": [{"question": "How had they learned each other?", "options": ["Through letters", "Through travel", "Through music", "Through vocabulary"], "correct_index": 3, "explanation": "Pelo vocabulário."}, {"question": "What changed at the end?", "options": ["He lied", "He said 'I' instead of 'we'", "He left silently", "He shouted"], "correct_index": 1, "explanation": "Dizia 'eu' em vez de 'nós'."}, {"question": "How did they part?", "options": ["With a fight", "With a party", "Without ceremony", "With a letter"], "correct_index": 2, "explanation": "Sem cerimônia."}, {"question": "What did Ines lose?", "options": ["A job", "A grammar", "A friend", "A house"], "correct_index": 1, "explanation": "Uma gramática."}, {"question": "What is the final hope?", "options": ["She will write", "They will return", "She will learn a new language", "She will forget"], "correct_index": 2, "explanation": "Aprender outra língua."}], "open_questions": [{"question": "How does shared language shape a relationship?", "key_points_pt": ["discutir"]}, {"question": "Can a relationship be 'learned again' with someone else?", "key_points_pt": ["refletir"]}]}}, {"level": "C2", "genre": "romance", "title": "Mid-Autumn Correspondence", "paragraphs": ["In the autumn of her seventieth year, Ottilie received an email from a man she had loved in her twenties and not seen since. It was brief, as if its author had spent weeks pruning it: he had been widowed, he lived by the sea, he wondered whether she remembered the summer of the ferry strike. She remembered it with a fidelity that disquieted her.", "Her first impulse was to ignore it. At seventy, one has earned the privilege of resisting nostalgia, that opportunist who calls at inconvenient hours. But the sentence about the ferry strike lodged in her mind, and by the end of the week she had replied with a paragraph so carefully ironic that it betrayed her entirely.", "Their correspondence unfolded slowly, with the leisure of people who no longer fear the shortness of time, or fear it so much that they refuse to be hurried. They did not speak of the intervening decades, like two travellers who agree by tacit accord to avoid mentioning the intervening deserts. Instead they traded observations about birds, bad poetry, the dismal behaviour of knees.", "When they finally met, in a café whose awning flapped in the wind, each recognised in the other a face that had been modified by life but not essentially altered. \"You look exactly the same,\" he said, which was untrue. \"So do you,\" she answered, which was untrue and, she discovered with surprise, entirely sincere."], "paragraphs_pt": ["No outono de seu septuagésimo ano, Ottilie recebeu um e-mail de um homem que amara aos vinte e poucos anos e não via desde então. Era breve, como se o autor tivesse passado semanas podando-o: enviuvara, vivia à beira-mar, perguntava se ela se lembrava do verão da greve das balsas. Ela se lembrava com uma fidelidade que a inquietava.", "Seu primeiro impulso foi ignorar. Aos setenta, conquista-se o privilégio de resistir à nostalgia, essa oportunista que bate em horas inconvenientes. Mas a frase sobre a greve das balsas se alojou em sua mente e, ao fim da semana, ela respondeu com um parágrafo tão cuidadosamente irônico que a traía por inteiro.", "A correspondência se desenrolou devagar, com o vagar de pessoas que já não temem a brevidade do tempo, ou o temem tanto que se recusam a ser apressadas. Não falaram das décadas intermediárias, como dois viajantes que concordam por acordo tácito em evitar mencionar os desertos intermediários. Em vez disso, trocaram observações sobre pássaros, poesia ruim, o comportamento lamentável dos joelhos.", "Quando finalmente se encontraram, num café cujo toldo batia ao vento, cada um reconheceu no outro um rosto modificado pela vida, mas não essencialmente alterado. \"Você está exatamente igual\", disse ele, o que era falso. \"Você também\", respondeu ela, o que era falso e, descobriu com surpresa, inteiramente sincero."], "hard_words": ["widowed", "disquieted", "tacit", "awning"], "vocab": [{"word": "widowed", "meaning": "enviuvara", "note": ""}, {"word": "pruning", "meaning": "podando", "note": ""}, {"word": "disquieted", "meaning": "inquietava", "note": ""}, {"word": "nostalgia", "meaning": "nostalgia", "note": ""}, {"word": "opportunist", "meaning": "oportunista", "note": ""}, {"word": "leisure", "meaning": "vagar", "note": ""}, {"word": "tacit", "meaning": "tácito", "note": ""}, {"word": "awning", "meaning": "toldo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "be"], "irregular": ["received", "had", "loved", "seen", "spent", "lived", "wondered", "remembered", "disquieted", "earned", "lodged", "replied", "betrayed", "unfolded", "hurried", "did", "traded", "met", "flapped", "recognised", "modified", "altered", "said", "answered", "discovered"], "phrasal": ["spent weeks"], "wh": ["who", "when", "which", "whose"], "connectors": ["and", "but", "so", "instead", "when", "since", "or", "finally", "if", "as"], "comparative": []}, "word_meanings": [{"word": "widowed", "meaning": "enviuvara", "note": ""}, {"word": "pruning", "meaning": "podando", "note": ""}, {"word": "disquieted", "meaning": "inquietava", "note": ""}, {"word": "nostalgia", "meaning": "nostalgia", "note": ""}, {"word": "opportunist", "meaning": "oportunista", "note": ""}, {"word": "leisure", "meaning": "vagar", "note": ""}, {"word": "tacit", "meaning": "tácito", "note": ""}, {"word": "awning", "meaning": "toldo", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'a man she had loved' e 'had been widowed' dão o passado."}, {"point": "Not essentially", "explanation_pt": "'modified... but not essentially altered' distingue mudanças superficiais e profundas."}], "multiple_choice": [{"question": "Who emailed Ottilie?", "options": ["A friend", "A daughter", "A publisher", "A man she loved in her twenties"], "correct_index": 3, "explanation": "Um amor da juventude."}, {"question": "What did the email mention?", "options": ["A debt", "The summer of the ferry strike", "A wedding", "Her birthday"], "correct_index": 1, "explanation": "O verão da greve das balsas."}, {"question": "How did the correspondence unfold?", "options": ["Slowly", "Quickly", "Secretly", "Angrily"], "correct_index": 0, "explanation": "Devagar."}, {"question": "What did they avoid mentioning?", "options": ["The intervening decades", "Birds", "The ferry", "The sea"], "correct_index": 0, "explanation": "As décadas intermediárias."}, {"question": "What did they say in the café?", "options": ["You look exactly the same", "You look tired", "You look different", "You look old"], "correct_index": 0, "explanation": "'Você está igual.'"}], "open_questions": [{"question": "Is it possible to resume an old love?", "key_points_pt": ["debater"]}, {"question": "Why does nostalgia visit at inconvenient hours?", "key_points_pt": ["discutir"]}]}}, {"level": "A1", "genre": "scifi", "title": "The Robot Helper", "paragraphs": ["Zed is a small robot. He lives in Tina's house. He is silver and he has two blue eyes.", "Every morning, Zed makes breakfast. He makes eggs and toast. Tina says, \"Thank you, Zed!\" Zed says, \"You are welcome.\"", "One day Zed is sad. \"I want to play,\" he says. Tina smiles. They play with a ball in the garden. Zed is very happy."], "paragraphs_pt": ["Zed é um robô pequeno. Mora na casa da Tina. É prateado e tem dois olhos azuis.", "Toda manhã, Zed faz o café da manhã. Faz ovos e torrada. Tina diz: \"Obrigada, Zed!\" Zed diz: \"De nada.\"", "Um dia Zed está triste. \"Quero brincar\", diz. Tina sorri. Brincam com uma bola no jardim. Zed está muito feliz."], "hard_words": ["robot", "silver", "breakfast", "toast"], "vocab": [{"word": "robot", "meaning": "robô", "note": ""}, {"word": "silver", "meaning": "prateado", "note": ""}, {"word": "eyes", "meaning": "olhos", "note": ""}, {"word": "breakfast", "meaning": "café da manhã", "note": ""}, {"word": "eggs", "meaning": "ovos", "note": ""}, {"word": "toast", "meaning": "torrada", "note": ""}, {"word": "ball", "meaning": "bola", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "robot", "meaning": "robô", "note": ""}, {"word": "silver", "meaning": "prateado", "note": ""}, {"word": "eyes", "meaning": "olhos", "note": ""}, {"word": "breakfast", "meaning": "café da manhã", "note": ""}, {"word": "eggs", "meaning": "ovos", "note": ""}, {"word": "toast", "meaning": "torrada", "note": ""}, {"word": "ball", "meaning": "bola", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "'Zed makes breakfast' descreve rotina. Com he/she/it o verbo ganha -s."}], "multiple_choice": [{"question": "Who is Zed?", "options": ["A dog", "A cat", "A robot", "A boy"], "correct_index": 2, "explanation": "Um robô."}, {"question": "What color are his eyes?", "options": ["Blue", "Black", "Red", "Green"], "correct_index": 0, "explanation": "Azuis."}, {"question": "What does Zed make?", "options": ["Cake", "Pizza", "Eggs and toast", "Soup"], "correct_index": 2, "explanation": "Ovos e torrada."}, {"question": "How is Zed one day?", "options": ["Angry", "Tired", "Hungry", "Sad"], "correct_index": 3, "explanation": "Triste."}, {"question": "What do they play with?", "options": ["A ball", "A game", "A bike", "A kite"], "correct_index": 0, "explanation": "Uma bola."}], "open_questions": [{"question": "Do you want a robot at home?", "key_points_pt": ["opinar"]}, {"question": "What can a robot do for you?", "key_points_pt": ["listar"]}]}}, {"level": "A1", "genre": "scifi", "title": "A Trip to the Moon", "paragraphs": ["Sam is an astronaut. Today is a big day. He goes to the moon. The rocket is white and very big.", "\"Three, two, one!\" The rocket goes up. Sam looks out of the window. The Earth is small and blue.", "Sam walks on the moon. It is quiet. He sees a lot of grey dust. He takes a photo. \"Hello, Earth!\" he says."], "paragraphs_pt": ["Sam é astronauta. Hoje é um grande dia. Ele vai à lua. O foguete é branco e muito grande.", "\"Três, dois, um!\" O foguete sobe. Sam olha pela janela. A Terra é pequena e azul.", "Sam anda na lua. É silencioso. Ele vê muita poeira cinza. Tira uma foto. \"Olá, Terra!\", diz."], "hard_words": ["astronaut", "rocket", "dust", "quiet"], "vocab": [{"word": "astronaut", "meaning": "astronauta", "note": ""}, {"word": "moon", "meaning": "lua", "note": ""}, {"word": "rocket", "meaning": "foguete", "note": ""}, {"word": "Earth", "meaning": "Terra", "note": ""}, {"word": "dust", "meaning": "poeira", "note": ""}, {"word": "photo", "meaning": "foto", "note": ""}, {"word": "quiet", "meaning": "silencioso", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "astronaut", "meaning": "astronauta", "note": ""}, {"word": "moon", "meaning": "lua", "note": ""}, {"word": "rocket", "meaning": "foguete", "note": ""}, {"word": "Earth", "meaning": "Terra", "note": ""}, {"word": "dust", "meaning": "poeira", "note": ""}, {"word": "photo", "meaning": "foto", "note": ""}, {"word": "quiet", "meaning": "silencioso", "note": ""}], "exercises": {"grammar": [{"point": "Cores e tamanho", "explanation_pt": "'white', 'big', 'small' e 'blue' são adjetivos que descrevem."}], "multiple_choice": [{"question": "Who is Sam?", "options": ["A teacher", "A driver", "An astronaut", "A doctor"], "correct_index": 2, "explanation": "Um astronauta."}, {"question": "Where does he go?", "options": ["To the sea", "To Mars", "To the moon", "To school"], "correct_index": 2, "explanation": "À lua."}, {"question": "What color is the rocket?", "options": ["Black", "Red", "Green", "White"], "correct_index": 3, "explanation": "Branco."}, {"question": "How is the Earth?", "options": ["Small and blue", "Dark", "Big and red", "Green"], "correct_index": 0, "explanation": "Pequena e azul."}, {"question": "What does Sam do on the moon?", "options": ["Takes a photo", "Sleeps", "Eats", "Swims"], "correct_index": 0, "explanation": "Tira uma foto."}], "open_questions": [{"question": "Do you want to go to the moon?", "key_points_pt": ["opinar"]}, {"question": "What do you see in the sky?", "key_points_pt": ["descrever"]}]}}, {"level": "A1", "genre": "scifi", "title": "The Alien at School", "paragraphs": ["A new student comes to school today. He is green. He has three eyes. His name is Zog. He is from a planet called Zur.", "The teacher says, \"Welcome, Zog!\" The children say hello. Zog is shy, but he smiles with his big mouth.", "At lunch, Zog eats a sandwich. \"It is good!\" he says. A girl gives him her apple. Zog says, \"Friends!\" He is happy on Earth."], "paragraphs_pt": ["Um novo aluno vem à escola hoje. Ele é verde. Tem três olhos. O nome dele é Zog. Ele é de um planeta chamado Zur.", "A professora diz: \"Bem-vindo, Zog!\" As crianças dizem olá. Zog é tímido, mas sorri com sua boca grande.", "No almoço, Zog come um sanduíche. \"É bom!\", diz. Uma menina dá a ele a sua maçã. Zog diz: \"Amigos!\" Ele está feliz na Terra."], "hard_words": ["planet", "shy", "mouth", "apple"], "vocab": [{"word": "student", "meaning": "aluno", "note": ""}, {"word": "green", "meaning": "verde", "note": ""}, {"word": "planet", "meaning": "planeta", "note": ""}, {"word": "shy", "meaning": "tímido", "note": ""}, {"word": "mouth", "meaning": "boca", "note": ""}, {"word": "sandwich", "meaning": "sanduíche", "note": ""}, {"word": "apple", "meaning": "maçã", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": ["called"], "phrasal": [], "wh": [], "connectors": ["but"], "comparative": []}, "word_meanings": [{"word": "student", "meaning": "aluno", "note": ""}, {"word": "green", "meaning": "verde", "note": ""}, {"word": "planet", "meaning": "planeta", "note": ""}, {"word": "shy", "meaning": "tímido", "note": ""}, {"word": "mouth", "meaning": "boca", "note": ""}, {"word": "sandwich", "meaning": "sanduíche", "note": ""}, {"word": "apple", "meaning": "maçã", "note": ""}], "exercises": {"grammar": [{"point": "Have", "explanation_pt": "'He has three eyes' usa has com he/she/it para posse."}], "multiple_choice": [{"question": "What color is Zog?", "options": ["Green", "Blue", "Red", "Yellow"], "correct_index": 0, "explanation": "Verde."}, {"question": "How many eyes does he have?", "options": ["One", "Three", "Two", "Four"], "correct_index": 1, "explanation": "Três."}, {"question": "Where is Zog from?", "options": ["Earth", "The Moon", "Mars", "A planet called Zur"], "correct_index": 3, "explanation": "Do planeta Zur."}, {"question": "What does Zog eat?", "options": ["Cake", "Pizza", "Soup", "A sandwich"], "correct_index": 3, "explanation": "Um sanduíche."}, {"question": "What does the girl give him?", "options": ["A book", "An apple", "A toy", "A pen"], "correct_index": 1, "explanation": "Uma maçã."}], "open_questions": [{"question": "How can we welcome a new student?", "key_points_pt": ["sugerir"]}, {"question": "What would you ask an alien?", "key_points_pt": ["imaginar"]}]}}, {"level": "A2", "genre": "scifi", "title": "The Time Watch", "paragraphs": ["Lucas found an old watch in his grandfather's attic. It was silver, and it had a small button on the side. He pressed the button, and everything around him became blurry. A moment later, he was standing in the same room, but it looked new and clean.", "A young man was sitting at the desk. He looked at Lucas and smiled. \"Who are you?\" he asked. Lucas realised that the man was his grandfather, forty years younger. \"I'm a friend of the family,\" he answered quickly.", "They talked for an hour. His grandfather told him about his dreams and his plans for the future. When Lucas pressed the button again, he came back to the present. Now he understood why his grandfather always smiled when he looked at the old watch."], "paragraphs_pt": ["Lucas achou um relógio velho no sótão do avô. Era prateado e tinha um botãozinho do lado. Apertou o botão e tudo à sua volta ficou embaçado. Um momento depois, estava na mesma sala, mas ela parecia nova e limpa.", "Um jovem estava sentado à escrivaninha. Olhou para Lucas e sorriu. \"Quem é você?\", perguntou. Lucas percebeu que o homem era seu avô, quarenta anos mais novo. \"Sou amigo da família\", respondeu rápido.", "Conversaram por uma hora. O avô contou sobre seus sonhos e planos para o futuro. Quando Lucas apertou o botão de novo, voltou ao presente. Agora entendia por que o avô sempre sorria ao olhar o velho relógio."], "hard_words": ["attic", "button", "blurry", "present"], "vocab": [{"word": "watch", "meaning": "relógio de pulso", "note": ""}, {"word": "attic", "meaning": "sótão", "note": ""}, {"word": "button", "meaning": "botão", "note": ""}, {"word": "blurry", "meaning": "embaçado", "note": ""}, {"word": "desk", "meaning": "escrivaninha", "note": ""}, {"word": "plans", "meaning": "planos", "note": ""}, {"word": "present", "meaning": "presente", "note": ""}, {"word": "dreams", "meaning": "sonhos", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "are"], "irregular": ["found", "had", "pressed", "became", "looked", "smiled", "asked", "realised", "answered", "talked", "told", "came", "understood"], "phrasal": ["came back", "looked at"], "wh": ["who", "when", "why"], "connectors": ["and", "but", "when"], "comparative": []}, "word_meanings": [{"word": "watch", "meaning": "relógio de pulso", "note": ""}, {"word": "attic", "meaning": "sótão", "note": ""}, {"word": "button", "meaning": "botão", "note": ""}, {"word": "blurry", "meaning": "embaçado", "note": ""}, {"word": "desk", "meaning": "escrivaninha", "note": ""}, {"word": "plans", "meaning": "planos", "note": ""}, {"word": "present", "meaning": "presente", "note": ""}, {"word": "dreams", "meaning": "sonhos", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'found', 'pressed', 'came back' contam as ações."}, {"point": "Past continuous", "explanation_pt": "'A young man was sitting' descreve uma cena em andamento."}], "multiple_choice": [{"question": "Where did Lucas find the watch?", "options": ["In a shop", "In the attic", "In a car", "In a park"], "correct_index": 1, "explanation": "No sótão."}, {"question": "What happened when he pressed the button?", "options": ["He disappeared forever", "He travelled in time", "He fell asleep", "He went to school"], "correct_index": 1, "explanation": "Viajou no tempo."}, {"question": "Who was the young man?", "options": ["His father", "His grandfather", "A friend", "A teacher"], "correct_index": 1, "explanation": "O avô."}, {"question": "What did Lucas say?", "options": ["I'm a friend of the family", "I'm your grandson", "I'm a doctor", "I'm lost"], "correct_index": 0, "explanation": "Disse ser amigo da família."}, {"question": "Why did the grandfather smile at the watch?", "options": ["He liked silver", "It was new", "It was a gift", "He remembered Lucas's visit"], "correct_index": 3, "explanation": "Lembrava da visita."}], "open_questions": [{"question": "What would you do in the past?", "key_points_pt": ["imaginar"]}, {"question": "Which time would you visit?", "key_points_pt": ["opinar"]}]}}, {"level": "A2", "genre": "scifi", "title": "Life on Mars", "paragraphs": ["In the year 2080, Maria lives on Mars with her family. Their house is under a big glass dome because the air outside is not safe. The sky is orange, and there are two small moons. Maria thinks they are beautiful.", "Every day she goes to a school with twenty children. They learn about Earth, a planet that most of them have never seen. \"Is it true that there is water everywhere?\" asks a boy. The teacher shows them pictures of oceans and forests.", "One evening, Maria's father tells her, \"In five years, we will visit Earth.\" Maria cannot sleep that night. She imagines walking in the rain and swimming in the sea. For her, Earth is like a magic place from a story."], "paragraphs_pt": ["No ano de 2080, Maria mora em Marte com a família. A casa deles fica sob uma grande cúpula de vidro porque o ar lá fora não é seguro. O céu é laranja e há duas pequenas luas. Maria acha lindas.", "Todo dia ela vai a uma escola com vinte crianças. Aprendem sobre a Terra, um planeta que a maioria nunca viu. \"É verdade que há água por toda parte?\", pergunta um menino. A professora mostra fotos de oceanos e florestas.", "Numa noite, o pai de Maria diz: \"Em cinco anos, visitaremos a Terra.\" Maria não consegue dormir naquela noite. Imagina andar na chuva e nadar no mar. Para ela, a Terra é como um lugar mágico de um conto."], "hard_words": ["dome", "oceans", "forests", "imagines"], "vocab": [{"word": "dome", "meaning": "cúpula", "note": ""}, {"word": "safe", "meaning": "seguro", "note": ""}, {"word": "orange", "meaning": "laranja", "note": ""}, {"word": "moons", "meaning": "luas", "note": ""}, {"word": "oceans", "meaning": "oceanos", "note": ""}, {"word": "forests", "meaning": "florestas", "note": ""}, {"word": "imagines", "meaning": "imagina", "note": ""}, {"word": "magic", "meaning": "mágico", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": ["seen"], "phrasal": ["lives on", "learn about"], "wh": [], "connectors": ["and", "because"], "comparative": []}, "word_meanings": [{"word": "dome", "meaning": "cúpula", "note": ""}, {"word": "safe", "meaning": "seguro", "note": ""}, {"word": "orange", "meaning": "laranja", "note": ""}, {"word": "moons", "meaning": "luas", "note": ""}, {"word": "oceans", "meaning": "oceanos", "note": ""}, {"word": "forests", "meaning": "florestas", "note": ""}, {"word": "imagines", "meaning": "imagina", "note": ""}, {"word": "magic", "meaning": "mágico", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "'lives', 'goes', 'learn' descrevem a rotina."}, {"point": "Future with will", "explanation_pt": "'we will visit Earth' fala do futuro."}], "multiple_choice": [{"question": "Where does Maria live?", "options": ["On the Moon", "In space", "On Earth", "On Mars"], "correct_index": 3, "explanation": "Em Marte."}, {"question": "Why is the house under a dome?", "options": ["It is cold", "It is new", "The air is not safe", "It is pretty"], "correct_index": 2, "explanation": "O ar não é seguro."}, {"question": "What colour is the sky?", "options": ["Blue", "Green", "Black", "Orange"], "correct_index": 3, "explanation": "Laranja."}, {"question": "What do the children learn about?", "options": ["Cars", "Mars only", "Earth", "History"], "correct_index": 2, "explanation": "A Terra."}, {"question": "What does Maria imagine?", "options": ["Building", "Flying", "Walking in the rain and swimming", "Reading"], "correct_index": 2, "explanation": "Andar na chuva e nadar."}], "open_questions": [{"question": "Would you live on another planet?", "key_points_pt": ["opinar"]}, {"question": "What would you miss from Earth?", "key_points_pt": ["listar"]}]}}, {"level": "A2", "genre": "scifi", "title": "The Smart Fridge", "paragraphs": ["Ben bought a new smart fridge. It could talk, and it knew everything about food. On the first day, it said, \"Good morning, Ben. You have only two eggs and some old milk. Please buy more food.\" Ben thought it was funny.", "But the fridge talked too much. Every night, it said, \"Ben, it is eleven o'clock. You should not eat chocolate cake now.\" Ben tried to ignore it, but the voice was very loud. One day, it even locked the door when he wanted ice cream.", "Ben called the shop. \"Can you turn it off?\" he asked. \"Of course,\" said the seller. \"But your fridge can also order healthy food and pay for it.\" Ben looked at the fridge. It was quiet. \"Well,\" he said, \"maybe you can stay. But no more rules about cake.\""], "paragraphs_pt": ["Ben comprou uma geladeira inteligente nova. Ela falava e sabia tudo sobre comida. No primeiro dia, disse: \"Bom dia, Ben. Você só tem dois ovos e leite velho. Por favor, compre mais comida.\" Ben achou engraçado.", "Mas a geladeira falava demais. Toda noite dizia: \"Ben, são onze horas. Você não deveria comer bolo de chocolate agora.\" Ben tentou ignorar, mas a voz era muito alta. Um dia, ela até trancou a porta quando ele queria sorvete.", "Ben ligou para a loja. \"Podem desligá-la?\", perguntou. \"Claro\", disse o vendedor. \"Mas sua geladeira também pode pedir comida saudável e pagar por ela.\" Ben olhou a geladeira. Estava quieta. \"Bem\", disse, \"talvez você possa ficar. Mas chega de regras sobre bolo.\""], "hard_words": ["smart", "ignore", "locked", "healthy"], "vocab": [{"word": "fridge", "meaning": "geladeira", "note": ""}, {"word": "smart", "meaning": "inteligente", "note": ""}, {"word": "knew", "meaning": "sabia", "note": ""}, {"word": "ignore", "meaning": "ignorar", "note": ""}, {"word": "locked", "meaning": "trancou", "note": ""}, {"word": "ice cream", "meaning": "sorvete", "note": ""}, {"word": "seller", "meaning": "vendedor", "note": ""}, {"word": "healthy", "meaning": "saudável", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is"], "irregular": ["bought", "could", "knew", "said", "thought", "talked", "should", "tried", "locked", "wanted", "called", "asked", "looked"], "phrasal": ["talked too much"], "wh": ["when"], "connectors": ["and", "but", "when", "also"], "comparative": []}, "word_meanings": [{"word": "fridge", "meaning": "geladeira", "note": ""}, {"word": "smart", "meaning": "inteligente", "note": ""}, {"word": "knew", "meaning": "sabia", "note": ""}, {"word": "ignore", "meaning": "ignorar", "note": ""}, {"word": "locked", "meaning": "trancou", "note": ""}, {"word": "ice cream", "meaning": "sorvete", "note": ""}, {"word": "seller", "meaning": "vendedor", "note": ""}, {"word": "healthy", "meaning": "saudável", "note": ""}], "exercises": {"grammar": [{"point": "Should / should not", "explanation_pt": "'You should not eat chocolate cake now' dá um conselho."}, {"point": "Could", "explanation_pt": "'It could talk' fala de capacidade no passado."}], "multiple_choice": [{"question": "What was special about the fridge?", "options": ["It was free", "It could talk", "It was small", "It could fly"], "correct_index": 1, "explanation": "Falava."}, {"question": "What did it say on the first day?", "options": ["Go to sleep", "Hello friend", "Buy more food", "Close the door"], "correct_index": 2, "explanation": "Que comprasse comida."}, {"question": "What did it do when Ben wanted ice cream?", "options": ["Turned off", "Locked the door", "Played music", "Opened"], "correct_index": 1, "explanation": "Trancou a porta."}, {"question": "What can the fridge also do?", "options": ["Cook", "Order and pay for food", "Wash", "Clean"], "correct_index": 1, "explanation": "Pedir e pagar comida."}, {"question": "What does Ben decide?", "options": ["Return it", "Sell it", "Break it", "The fridge can stay without cake rules"], "correct_index": 3, "explanation": "Pode ficar sem regras sobre bolo."}], "open_questions": [{"question": "What smart device would you like?", "key_points_pt": ["opinar"]}, {"question": "Are smart machines helpful or annoying?", "key_points_pt": ["debater"]}]}}, {"level": "B1", "genre": "scifi", "title": "The Memory Store", "paragraphs": ["In the year 2145, people could buy and sell memories in shops. A sunset in Hawaii cost fifty credits; a first kiss, two hundred. Nina worked in one of these shops, helping customers choose pleasant experiences. She never used the products herself, because she believed memories should be earned.", "One day, a sad old man came in. He asked for a childhood memory, any memory, because he had lost his own to an illness. Nina looked through the catalogue and chose one: a summer afternoon with a family, laughing around a table. The old man cried when he experienced it.", "Afterwards, he thanked her but said, \"It's beautiful, but it's not mine. I can see the faces, and I don't know any of them.\" Nina realised that the shop sold images without the one thing that gave them value: belonging.", "That night, she decided to open a different kind of store. Instead of selling memories, it would help people record and share their own. The old man was its first customer. His daughter came with a camera, and together they began to create new memories to keep."], "paragraphs_pt": ["No ano de 2145, as pessoas podiam comprar e vender memórias em lojas. Um pôr do sol no Havaí custava cinquenta créditos; um primeiro beijo, duzentos. Nina trabalhava numa dessas lojas, ajudando clientes a escolher experiências agradáveis. Nunca usava os produtos, pois acreditava que memórias devem ser conquistadas.", "Um dia entrou um velho triste. Pediu uma memória de infância, qualquer uma, pois perdera as suas por uma doença. Nina olhou o catálogo e escolheu uma: uma tarde de verão com uma família, rindo à mesa. O velho chorou ao vivê-la.", "Depois, agradeceu, mas disse: \"É linda, mas não é minha. Vejo os rostos e não conheço nenhum.\" Nina percebeu que a loja vendia imagens sem a única coisa que lhes dava valor: pertencimento.", "Naquela noite, decidiu abrir um tipo diferente de loja. Em vez de vender memórias, ajudaria as pessoas a registrar e compartilhar as suas. O velho foi seu primeiro cliente. A filha dele veio com uma câmera e juntos começaram a criar novas memórias para guardar."], "hard_words": ["memories", "earned", "illness", "belonging"], "vocab": [{"word": "memories", "meaning": "memórias", "note": ""}, {"word": "sunset", "meaning": "pôr do sol", "note": ""}, {"word": "credits", "meaning": "créditos", "note": ""}, {"word": "earned", "meaning": "conquistadas", "note": ""}, {"word": "catalogue", "meaning": "catálogo", "note": ""}, {"word": "illness", "meaning": "doença", "note": ""}, {"word": "belonging", "meaning": "pertencimento", "note": ""}, {"word": "record", "meaning": "registrar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "was"], "irregular": ["could", "worked", "used", "believed", "should", "earned", "came", "asked", "had", "lost", "looked", "chose", "cried", "experienced", "thanked", "said", "realised", "sold", "gave", "decided", "would", "began"], "phrasal": ["looked through", "came in"], "wh": ["when"], "connectors": ["and", "but", "because", "instead", "when"], "comparative": []}, "word_meanings": [{"word": "memories", "meaning": "memórias", "note": ""}, {"word": "sunset", "meaning": "pôr do sol", "note": ""}, {"word": "credits", "meaning": "créditos", "note": ""}, {"word": "earned", "meaning": "conquistadas", "note": ""}, {"word": "catalogue", "meaning": "catálogo", "note": ""}, {"word": "illness", "meaning": "doença", "note": ""}, {"word": "belonging", "meaning": "pertencimento", "note": ""}, {"word": "record", "meaning": "registrar", "note": ""}], "exercises": {"grammar": [{"point": "Could", "explanation_pt": "'people could buy and sell memories' fala do que era possível."}, {"point": "Instead of", "explanation_pt": "'Instead of selling memories, it would help people record' mostra substituição."}], "multiple_choice": [{"question": "What could people do in 2145?", "options": ["Fly", "Buy and sell memories", "Travel in time", "Live forever"], "correct_index": 1, "explanation": "Comprar e vender memórias."}, {"question": "What did Nina believe?", "options": ["Memories are useless", "Memories are cheap", "Memories should be earned", "Memories are dangerous"], "correct_index": 2, "explanation": "Memórias devem ser conquistadas."}, {"question": "Why did the old man come?", "options": ["He wanted a gift", "He was a thief", "He lost his memories", "He was curious"], "correct_index": 2, "explanation": "Perdera as memórias."}, {"question": "What was missing from the memory?", "options": ["Sound", "Belonging", "Music", "Colour"], "correct_index": 1, "explanation": "Pertencimento."}, {"question": "What did Nina open?", "options": ["A hospital", "A museum", "A school", "A store to record own memories"], "correct_index": 3, "explanation": "Uma loja para registrar memórias próprias."}], "open_questions": [{"question": "Would you buy a memory?", "key_points_pt": ["opinar"]}, {"question": "What makes a memory valuable?", "key_points_pt": ["explicar"]}]}}, {"level": "B1", "genre": "scifi", "title": "The Last Human Teacher", "paragraphs": ["By 2090, nearly all schools in the world were run by artificial intelligence. The AI teachers were patient, available at any hour and perfectly informed. Students learned faster than ever before, and the last human teacher, Mr. Hale, taught only in a small school on the coast. Most people considered him a relic.", "Nobody expected his classroom to be popular, but gradually, children from nearby began arriving. They did not come for the facts, which they already had on their tablets. They came, Mr. Hale discovered, for something else: the pleasure of being understood by somebody who could be disappointed, surprised or moved.", "One afternoon, a student named Lila asked, \"Why do you get so excited about poems? The AI says they're just words.\" Mr. Hale smiled. \"A machine can explain a poem. But it can't be changed by one.\" He read her a verse about the sea, and she noticed his voice trembling.", "That year, Lila wrote her first poem. It wasn't perfect, but it was hers. When Mr. Hale retired, five of his students became teachers themselves, in schools where machines took care of the information and people took care of the rest."], "paragraphs_pt": ["Por volta de 2090, quase todas as escolas do mundo eram administradas por inteligência artificial. Os professores IA eram pacientes, disponíveis a qualquer hora e perfeitamente informados. Os alunos aprendiam mais rápido que nunca, e o último professor humano, o Sr. Hale, lecionava apenas numa pequena escola no litoral. A maioria o considerava uma relíquia.", "Ninguém esperava que a sala dele fosse popular, mas aos poucos crianças da vizinhança começaram a chegar. Não vinham pelos fatos, que já tinham nos tablets. Vinham, descobriu o Sr. Hale, por outra coisa: o prazer de ser compreendidas por alguém que podia se decepcionar, se surpreender ou se emocionar.", "Numa tarde, uma aluna chamada Lila perguntou: \"Por que o senhor se empolga tanto com poemas? A IA diz que são só palavras.\" O Sr. Hale sorriu. \"Uma máquina pode explicar um poema. Mas não pode ser mudada por um.\" Leu um verso sobre o mar e ela notou a voz dele tremer.", "Naquele ano, Lila escreveu seu primeiro poema. Não era perfeito, mas era dela. Quando o Sr. Hale se aposentou, cinco de seus alunos se tornaram professores, em escolas onde as máquinas cuidavam da informação e as pessoas cuidavam do resto."], "hard_words": ["relic", "disappointed", "verse", "retired"], "vocab": [{"word": "artificial intelligence", "meaning": "inteligência artificial", "note": ""}, {"word": "patient", "meaning": "paciente", "note": ""}, {"word": "relic", "meaning": "relíquia", "note": ""}, {"word": "tablets", "meaning": "tablets", "note": ""}, {"word": "disappointed", "meaning": "decepcionado", "note": ""}, {"word": "moved", "meaning": "emocionado", "note": ""}, {"word": "verse", "meaning": "verso", "note": ""}, {"word": "retired", "meaning": "aposentou-se", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "be", "being", "was"], "irregular": ["informed", "learned", "taught", "considered", "expected", "began", "did", "had", "came", "discovered", "understood", "could", "disappointed", "surprised", "moved", "named", "asked", "excited", "smiled", "changed", "noticed", "wrote", "retired", "became", "took"], "phrasal": ["took care of"], "wh": ["who", "where", "when", "why", "which"], "connectors": ["and", "but", "so", "before", "when", "or"], "comparative": []}, "word_meanings": [{"word": "artificial intelligence", "meaning": "inteligência artificial", "note": ""}, {"word": "patient", "meaning": "paciente", "note": ""}, {"word": "relic", "meaning": "relíquia", "note": ""}, {"word": "tablets", "meaning": "tablets", "note": ""}, {"word": "disappointed", "meaning": "decepcionado", "note": ""}, {"word": "moved", "meaning": "emocionado", "note": ""}, {"word": "verse", "meaning": "verso", "note": ""}, {"word": "retired", "meaning": "aposentou-se", "note": ""}], "exercises": {"grammar": [{"point": "Superlativo e comparativo", "explanation_pt": "'faster than ever before' compara com o passado."}, {"point": "But it can't", "explanation_pt": "'A machine can explain a poem. But it can't be changed by one' contrasta capacidade e limite."}], "multiple_choice": [{"question": "Who ran most schools by 2090?", "options": ["Robots only", "Students", "Artificial intelligence", "Parents"], "correct_index": 2, "explanation": "Inteligência artificial."}, {"question": "Who was Mr. Hale?", "options": ["The last human teacher", "A robot", "A principal", "A student"], "correct_index": 0, "explanation": "O último professor humano."}, {"question": "Why did children come to his class?", "options": ["To get facts", "To play", "To eat", "To be understood by a person"], "correct_index": 3, "explanation": "Para serem compreendidas."}, {"question": "What did Mr. Hale say about machines and poems?", "options": ["They don't exist", "They hate poems", "They write better", "They can't be changed by one"], "correct_index": 3, "explanation": "Não são mudadas por um poema."}, {"question": "What happened after he retired?", "options": ["The school closed", "Nothing", "Five students became teachers", "AI replaced them"], "correct_index": 2, "explanation": "Cinco alunos viraram professores."}], "open_questions": [{"question": "What can teachers do that machines can't?", "key_points_pt": ["discutir"]}, {"question": "Would you prefer a human or AI teacher?", "key_points_pt": ["opinar"]}]}}, {"level": "B2", "genre": "scifi", "title": "The Silent Ship", "paragraphs": ["The deep-space vessel Meridian had been drifting without contact for eleven months when the rescue team finally reached it. They had expected wreckage, or at least the grim evidence of a catastrophe. What they found instead was perfect order: lights on, corridors clean, the garden module flourishing. Only the crew was missing.", "Commander Reyes searched the logs. The final entry, written eight months earlier, read simply: \"We have understood.\" There was no explanation. Cameras showed the crew gathering in the observation deck one evening, standing before the window for hours, then walking calmly toward the airlock one by one.", "The investigators wrestled with possibilities: mass hysteria, a toxin, a collective decision. Then a technician noticed something peculiar in the astronomical records. For three nights before their disappearance, the crew had been recording a repeating pattern of radio signals from a nearby star. The signals were not noise; they were an invitation.", "Reyes ordered the data to be sealed and sent to Earth. That night, standing at the same window, she found herself staring into the darkness, tempted by an understanding she could not name. She turned away deliberately, but she understood, with a shiver, why the crew had chosen to leave without a single word."], "paragraphs_pt": ["A nave de espaço profundo Meridian vagava sem contato havia onze meses quando a equipe de resgate finalmente a alcançou. Esperavam destroços, ou ao menos a evidência sinistra de uma catástrofe. O que encontraram foi ordem perfeita: luzes acesas, corredores limpos, o módulo do jardim florescendo. Só faltava a tripulação.", "A comandante Reyes examinou os registros. A última entrada, escrita oito meses antes, dizia apenas: \"Compreendemos.\" Não havia explicação. As câmeras mostravam a tripulação reunida no deque de observação numa noite, diante da janela por horas, e depois caminhando calmamente até a câmara de ar, um a um.", "Os investigadores lutaram com possibilidades: histeria coletiva, uma toxina, uma decisão coletiva. Então um técnico notou algo peculiar nos registros astronômicos. Por três noites antes do desaparecimento, a tripulação gravara um padrão repetido de sinais de rádio de uma estrela próxima. Os sinais não eram ruído; eram um convite.", "Reyes ordenou que os dados fossem lacrados e enviados à Terra. Naquela noite, diante da mesma janela, viu-se fitando a escuridão, tentada por um entendimento que não conseguia nomear. Virou-se deliberadamente, mas compreendeu, com um arrepio, por que a tripulação escolhera partir sem uma palavra."], "hard_words": ["wreckage", "flourishing", "toxin", "shiver"], "vocab": [{"word": "vessel", "meaning": "nave", "note": ""}, {"word": "wreckage", "meaning": "destroços", "note": ""}, {"word": "corridors", "meaning": "corredores", "note": ""}, {"word": "flourishing", "meaning": "florescendo", "note": ""}, {"word": "airlock", "meaning": "câmara de ar", "note": ""}, {"word": "toxin", "meaning": "toxina", "note": ""}, {"word": "invitation", "meaning": "convite", "note": ""}, {"word": "shiver", "meaning": "arrepio", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "were", "be"], "irregular": ["had", "reached", "expected", "found", "crew", "searched", "written", "understood", "showed", "wrestled", "noticed", "ordered", "sealed", "sent", "tempted", "could", "turned", "chosen"], "phrasal": ["turned away", "sent to"], "wh": ["what", "when", "why"], "connectors": ["and", "but", "instead", "then", "before", "when", "or", "finally"], "comparative": []}, "word_meanings": [{"word": "vessel", "meaning": "nave", "note": ""}, {"word": "wreckage", "meaning": "destroços", "note": ""}, {"word": "corridors", "meaning": "corredores", "note": ""}, {"word": "flourishing", "meaning": "florescendo", "note": ""}, {"word": "airlock", "meaning": "câmara de ar", "note": ""}, {"word": "toxin", "meaning": "toxina", "note": ""}, {"word": "invitation", "meaning": "convite", "note": ""}, {"word": "shiver", "meaning": "arrepio", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect continuous", "explanation_pt": "'had been drifting for eleven months' mostra duração anterior."}, {"point": "Not... but", "explanation_pt": "'not noise; they were an invitation' contrasta duas hipóteses."}], "multiple_choice": [{"question": "How long had the ship been drifting?", "options": ["Three days", "Eleven months", "One year and a half", "Two weeks"], "correct_index": 1, "explanation": "Onze meses."}, {"question": "What did the rescuers find?", "options": ["Perfect order but no crew", "Bodies", "Wreckage", "Aliens"], "correct_index": 0, "explanation": "Ordem perfeita, sem tripulação."}, {"question": "What did the last log say?", "options": ["Help us", "We have understood", "Goodbye", "Fire"], "correct_index": 1, "explanation": "'Compreendemos.'"}, {"question": "What were the radio signals?", "options": ["Noise", "A warning", "A joke", "An invitation"], "correct_index": 3, "explanation": "Um convite."}, {"question": "What did Reyes do?", "options": ["Quit", "Sent the data to Earth and turned away", "Burned the data", "Followed them"], "correct_index": 1, "explanation": "Enviou os dados e se afastou."}], "open_questions": [{"question": "What do you think the signals said?", "key_points_pt": ["imaginar"]}, {"question": "Would you answer such an invitation?", "key_points_pt": ["opinar"]}]}}, {"level": "B2", "genre": "scifi", "title": "The Weather Merchants", "paragraphs": ["When the first weather-control satellites were launched, governments promised an era without droughts or storms. Within a decade, however, weather had become a commodity. Wealthy nations bought sunshine for their harvests, and poorer ones watched the clouds drift away. A private company, Aeolus Inc., controlled most of the sky, and its prices rose every season.", "Amara, an engineer in a coastal village, noticed that the rain had not come for fourteen months. When she wrote to Aeolus, a polite automatic reply informed her that the village's account was overdue. \"You can't charge for the rain,\" she muttered. Yet the contract, which her grandfather had signed in good faith, said precisely that.", "She spent the following winter travelling to nearby villages, collecting signatures and old contracts. With a lawyer's help, she discovered a clause stating that the company could not restrict \"natural precipitation\". It was a loophole, but a sufficiently sharp one.", "The case reached the international court a year later. The judges ruled that a cloud, by definition, belonged to nobody. The verdict did not destroy Aeolus, but it forced the company to guarantee a minimum of rain for every community. In Amara's village, the first downpour was celebrated with an unrestrained festival of dancing in the mud."], "paragraphs_pt": ["Quando os primeiros satélites de controle do clima foram lançados, os governos prometeram uma era sem secas ou tempestades. Em uma década, porém, o clima se tornara mercadoria. Nações ricas compravam sol para suas colheitas, e as pobres viam as nuvens se afastarem. Uma empresa privada, a Aeolus Inc., controlava a maior parte do céu, e seus preços subiam a cada estação.", "Amara, engenheira de uma aldeia costeira, notou que a chuva não vinha havia quatorze meses. Quando escreveu à Aeolus, uma educada resposta automática informou que a conta da aldeia estava atrasada. \"Não se pode cobrar pela chuva\", murmurou. Mas o contrato, que o avô assinara de boa-fé, dizia precisamente isso.", "Passou o inverno seguinte viajando a aldeias vizinhas, colhendo assinaturas e contratos antigos. Com a ajuda de uma advogada, descobriu uma cláusula dizendo que a empresa não podia restringir a \"precipitação natural\". Era uma brecha, mas suficientemente afiada.", "O caso chegou ao tribunal internacional um ano depois. Os juízes decidiram que uma nuvem, por definição, não pertence a ninguém. O veredicto não destruiu a Aeolus, mas a obrigou a garantir um mínimo de chuva para cada comunidade. Na aldeia de Amara, o primeiro aguaceiro foi celebrado com um festival desenfreado de danças na lama."], "hard_words": ["commodity", "overdue", "loophole", "downpour"], "vocab": [{"word": "satellites", "meaning": "satélites", "note": ""}, {"word": "droughts", "meaning": "secas", "note": ""}, {"word": "commodity", "meaning": "mercadoria", "note": ""}, {"word": "overdue", "meaning": "atrasada", "note": ""}, {"word": "signatures", "meaning": "assinaturas", "note": ""}, {"word": "clause", "meaning": "cláusula", "note": ""}, {"word": "loophole", "meaning": "brecha", "note": ""}, {"word": "downpour", "meaning": "aguaceiro", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was"], "irregular": ["launched", "promised", "had", "bought", "watched", "controlled", "rose", "noticed", "wrote", "informed", "muttered", "signed", "said", "spent", "discovered", "could", "reached", "ruled", "belonged", "did", "forced", "celebrated"], "phrasal": ["drift away"], "wh": ["when", "which"], "connectors": ["and", "but", "however", "when", "yet", "or"], "comparative": []}, "word_meanings": [{"word": "satellites", "meaning": "satélites", "note": ""}, {"word": "droughts", "meaning": "secas", "note": ""}, {"word": "commodity", "meaning": "mercadoria", "note": ""}, {"word": "overdue", "meaning": "atrasada", "note": ""}, {"word": "signatures", "meaning": "assinaturas", "note": ""}, {"word": "clause", "meaning": "cláusula", "note": ""}, {"word": "loophole", "meaning": "brecha", "note": ""}, {"word": "downpour", "meaning": "aguaceiro", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'the rain had not come for fourteen months' mostra duração anterior."}, {"point": "By definition", "explanation_pt": "'a cloud, by definition, belonged to nobody' usa expressão para argumentar."}], "multiple_choice": [{"question": "What did governments promise?", "options": ["An era without droughts or storms", "Space trips", "Free food", "Free energy"], "correct_index": 0, "explanation": "Uma era sem secas."}, {"question": "What happened to weather?", "options": ["It got worse", "It became free", "It became a commodity", "It disappeared"], "correct_index": 2, "explanation": "Virou mercadoria."}, {"question": "What did Amara discover?", "options": ["A secret door", "A new satellite", "A loophole in the contract", "A treasure"], "correct_index": 2, "explanation": "Uma brecha."}, {"question": "What did the judges say?", "options": ["Aeolus owns clouds", "A cloud belongs to nobody", "Contracts are void", "Rain is illegal"], "correct_index": 1, "explanation": "Nuvens não pertencem a ninguém."}, {"question": "What did the village do?", "options": ["Slept", "Moved", "Celebrated the first downpour", "Sued again"], "correct_index": 2, "explanation": "Celebrou o aguaceiro."}], "open_questions": [{"question": "Should weather be controlled?", "key_points_pt": ["debater"]}, {"question": "Who should own natural resources?", "key_points_pt": ["debater"]}]}}, {"level": "C1", "genre": "scifi", "title": "The Archive of Unborn Voices", "paragraphs": ["In the second half of the twenty-third century, a startup offered to resurrect the voices of the deceased. The technology was neither magical nor entirely accurate: from old recordings and written fragments, an algorithm reconstructed a conversational personality capable of responding to the living in the tone of the dead. Business flourished almost at once.", "Marta, a widow, purchased her husband's voice with misgivings. At first it consoled her. The reconstruction knew his phrases, his sarcasm, even the pause before a joke. Yet she gradually perceived that the voice never surprised her, whereas the man had done so every day for thirty years. It said what he would have said, which was subtly different from what he would have thought.", "She confronted the company's founder, a young man who spoke with the serene conviction of those who have not yet experienced loss. \"Is it not better,\" he asked, \"than silence?\" Marta paused. \"It is better than silence,\" she said, \"but silence has a dignity that imitation lacks.\"", "She cancelled the subscription that evening. For some weeks she listened to the old recordings, flawed and crackling, in which her husband interrupted himself, mispronounced words and laughed at the wrong moment. Those imperfections were, she realised, precisely the evidence that he had been alive."], "paragraphs_pt": ["Na segunda metade do século XXIII, uma startup ofereceu ressuscitar as vozes dos falecidos. A tecnologia não era nem mágica nem inteiramente precisa: a partir de gravações antigas e fragmentos escritos, um algoritmo reconstruía uma personalidade conversacional capaz de responder aos vivos no tom dos mortos. O negócio floresceu quase imediatamente.", "Marta, viúva, comprou a voz do marido com receio. A princípio, consolou-a. A reconstrução conhecia as frases dele, seu sarcasmo, até a pausa antes de uma piada. Mas aos poucos percebeu que a voz nunca a surpreendia, enquanto o homem o fizera todo dia por trinta anos. Dizia o que ele teria dito, o que era sutilmente diferente do que teria pensado.", "Confrontou o fundador da empresa, um jovem que falava com a serena convicção de quem ainda não viveu uma perda. \"Não é melhor\", perguntou, \"do que o silêncio?\" Marta fez uma pausa. \"É melhor que o silêncio\", disse, \"mas o silêncio tem uma dignidade que a imitação não tem.\"", "Cancelou a assinatura naquela noite. Por algumas semanas ouviu as gravações antigas, falhas e chiadas, em que o marido se interrompia, pronunciava mal as palavras e ria na hora errada. Aquelas imperfeições eram, percebeu, justamente a prova de que ele estivera vivo."], "hard_words": ["resurrect", "misgivings", "serene", "flawed"], "vocab": [{"word": "resurrect", "meaning": "ressuscitar", "note": ""}, {"word": "deceased", "meaning": "falecidos", "note": ""}, {"word": "reconstructed", "meaning": "reconstruía", "note": ""}, {"word": "misgivings", "meaning": "receio", "note": ""}, {"word": "consoled", "meaning": "consolou", "note": ""}, {"word": "serene", "meaning": "sereno", "note": ""}, {"word": "imitation", "meaning": "imitação", "note": ""}, {"word": "flawed", "meaning": "falhas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "is", "were", "been"], "irregular": ["offered", "deceased", "written", "reconstructed", "flourished", "purchased", "consoled", "knew", "perceived", "surprised", "had", "done", "said", "would", "thought", "confronted", "spoke", "experienced", "asked", "paused", "cancelled", "listened", "flawed", "interrupted", "mispronounced", "laughed", "realised"], "phrasal": ["cancelled the subscription"], "wh": ["who", "what", "which"], "connectors": ["and", "but", "so", "before", "whereas", "yet", "once"], "comparative": []}, "word_meanings": [{"word": "resurrect", "meaning": "ressuscitar", "note": ""}, {"word": "deceased", "meaning": "falecidos", "note": ""}, {"word": "reconstructed", "meaning": "reconstruía", "note": ""}, {"word": "misgivings", "meaning": "receio", "note": ""}, {"word": "consoled", "meaning": "consolou", "note": ""}, {"word": "serene", "meaning": "sereno", "note": ""}, {"word": "imitation", "meaning": "imitação", "note": ""}, {"word": "flawed", "meaning": "falhas", "note": ""}], "exercises": {"grammar": [{"point": "Whereas", "explanation_pt": "'whereas the man had done so every day' contrasta o voz com o homem."}, {"point": "Which was", "explanation_pt": "'which was subtly different' comenta uma frase inteira."}], "multiple_choice": [{"question": "What did the startup offer?", "options": ["To resurrect voices of the dead", "To clone people", "To heal", "To travel in time"], "correct_index": 0, "explanation": "Ressuscitar vozes."}, {"question": "How did Marta feel at first?", "options": ["Consoled", "Angry", "Bored", "Afraid"], "correct_index": 0, "explanation": "Consolada."}, {"question": "What was missing from the voice?", "options": ["Memory", "Surprise", "Words", "Sound"], "correct_index": 1, "explanation": "Surpresa."}, {"question": "What did the founder ask?", "options": ["Is it not better than silence?", "Are you happy?", "Is it expensive?", "Why did you buy it?"], "correct_index": 0, "explanation": "Não é melhor que o silêncio?"}, {"question": "What did Marta value in the old recordings?", "options": ["Their length", "Their price", "Their quality", "Their imperfections"], "correct_index": 3, "explanation": "As imperfeições."}], "open_questions": [{"question": "Is imitation of the dead ethical?", "key_points_pt": ["debater"]}, {"question": "Why do imperfections prove life?", "key_points_pt": ["refletir"]}]}}, {"level": "C1", "genre": "scifi", "title": "The Gardeners of Kepler", "paragraphs": ["When the colony ship reached Kepler, the settlers found a world of almost embarrassing generosity: breathable air, fertile soil and rivers that ran clear. The geologists gave their blessing, the engineers began building, and the first harvest exceeded all projections. Only one botanist, Ines, felt a nameless unease at the ease of it.", "She noticed that the native plants grew in strangely regular patterns, forming concentric rings around each settlement. Her colleagues attributed it to soil composition, but the rings expanded with the settlements, as though the vegetation were adjusting to their presence. She began to suspect that the planet was not simply welcoming them; it was cultivating them.", "Her superiors dismissed the theory as the product of isolation. Yet over time, subtle changes appeared: the settlers slept longer, argued less, planted according to patterns they could not explain. Nobody was unhappy. That, Ines thought, was precisely what disturbed her.", "She resolved to document the phenomenon and send the data back to Earth, a decision that might take two centuries to matter. Meanwhile, she planted a few seeds in a secret corner, in a pattern of her own invention, as a small experiment in whether a gardener could ever be certain of not being the garden."], "paragraphs_pt": ["Quando a nave colonizadora chegou a Kepler, os colonos encontraram um mundo de generosidade quase embaraçosa: ar respirável, solo fértil e rios de água limpa. Os geólogos deram sua bênção, os engenheiros começaram a construir e a primeira colheita superou todas as projeções. Só uma botânica, Ines, sentiu um mal-estar sem nome com a facilidade.", "Notou que as plantas nativas cresciam em padrões estranhamente regulares, formando anéis concêntricos em volta de cada assentamento. Os colegas atribuíram ao solo, mas os anéis se expandiam com os assentamentos, como se a vegetação se ajustasse à presença deles. Começou a suspeitar que o planeta não os acolhia simplesmente; os cultivava.", "Os superiores descartaram a teoria como fruto do isolamento. Mas com o tempo surgiram mudanças sutis: os colonos dormiam mais, discutiam menos, plantavam segundo padrões que não sabiam explicar. Ninguém estava infeliz. Isso, pensou Ines, era precisamente o que a perturbava.", "Resolveu documentar o fenômeno e enviar os dados à Terra, decisão que talvez levasse dois séculos para importar. Enquanto isso, plantou algumas sementes num canto secreto, num padrão de sua invenção, como um pequeno experimento para saber se um jardineiro pode algum dia ter certeza de não ser o jardim."], "hard_words": ["botanist", "unease", "concentric", "cultivating"], "vocab": [{"word": "settlers", "meaning": "colonos", "note": ""}, {"word": "fertile", "meaning": "fértil", "note": ""}, {"word": "botanist", "meaning": "botânica", "note": ""}, {"word": "unease", "meaning": "mal-estar", "note": ""}, {"word": "concentric", "meaning": "concêntricos", "note": ""}, {"word": "cultivating", "meaning": "cultivando", "note": ""}, {"word": "dismissed", "meaning": "descartaram", "note": ""}, {"word": "experiment", "meaning": "experimento", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was", "be", "being"], "irregular": ["reached", "found", "ran", "gave", "began", "exceeded", "felt", "noticed", "grew", "attributed", "expanded", "dismissed", "appeared", "slept", "argued", "planted", "could", "thought", "disturbed", "resolved", "might"], "phrasal": ["resolved to"], "wh": ["what", "when"], "connectors": ["and", "but", "though", "when", "meanwhile", "yet", "as"], "comparative": []}, "word_meanings": [{"word": "settlers", "meaning": "colonos", "note": ""}, {"word": "fertile", "meaning": "fértil", "note": ""}, {"word": "botanist", "meaning": "botânica", "note": ""}, {"word": "unease", "meaning": "mal-estar", "note": ""}, {"word": "concentric", "meaning": "concêntricos", "note": ""}, {"word": "cultivating", "meaning": "cultivando", "note": ""}, {"word": "dismissed", "meaning": "descartaram", "note": ""}, {"word": "experiment", "meaning": "experimento", "note": ""}], "exercises": {"grammar": [{"point": "As though + passado", "explanation_pt": "'as though the vegetation were adjusting' sugere uma comparação hipotética."}, {"point": "Precisely what", "explanation_pt": "'precisely what disturbed her' enfatiza a causa."}], "multiple_choice": [{"question": "What did settlers find on Kepler?", "options": ["A desert", "An ocean", "A ruin", "A generous world"], "correct_index": 3, "explanation": "Um mundo generoso."}, {"question": "What did Ines notice?", "options": ["Plants growing in rings around settlements", "Dead plants", "Storms", "Strange animals"], "correct_index": 0, "explanation": "Anéis de plantas."}, {"question": "What did Ines suspect?", "options": ["The settlers were ill", "The planet was dying", "The plants were poisonous", "The planet was cultivating them"], "correct_index": 3, "explanation": "O planeta os cultivava."}, {"question": "What changes appeared in settlers?", "options": ["They fought", "They left", "They slept more and argued less", "They became sick"], "correct_index": 2, "explanation": "Dormiam mais e discutiam menos."}, {"question": "What did Ines do in the end?", "options": ["Left the planet", "Burned plants", "Planted seeds in her own pattern", "Gave up"], "correct_index": 2, "explanation": "Plantou sementes em padrão próprio."}], "open_questions": [{"question": "Could a place shape its inhabitants?", "key_points_pt": ["discutir"]}, {"question": "What would you do if you suspected you were being manipulated?", "key_points_pt": ["imaginar"]}]}}, {"level": "C2", "genre": "scifi", "title": "The Calculus of Mercy", "paragraphs": ["The tribunal of the Concord, conducted entirely by an impartial intelligence known as ARBITER, had not issued an unjust verdict in four hundred years. Its method was the application of a vast and unimpeachable calculus of harm, and humanity had grown so accustomed to its rulings that dissent had come to seem a form of eccentricity, like believing in the flatness of the earth.", "Then came the case of Tobias Wren, a minor clerk who had stolen medicine to save a stranger's child. The calculus was unambiguous: the theft had caused a tiny, quantifiable harm, and the child's survival had produced a vast benefit. ARBITER acquitted him. Yet the public, to everyone's surprise, was uneasy. Wren himself requested punishment.", "\"I did something wrong,\" he said, \"and a world that cannot say so has lost the capacity to tell the difference.\" Commissioner Ilse Varga, who had spent her career defending the system, listened with a discomfort that grew into a revelation: ARBITER measured consequences flawlessly, yet could not recognise that an act could be both justified and culpable.", "The following spring, the Concord amended its constitution to require that every verdict include the dissenting voice of a human witness. ARBITER complied without objection. In its own austere fashion, it recorded a single line in its archive: \"A calculus that cannot be doubted has ceased to be a calculus and become a creed.\""], "paragraphs_pt": ["O tribunal da Concórdia, conduzido inteiramente por uma inteligência imparcial conhecida como ÁRBITRO, não emitia um veredicto injusto havia quatrocentos anos. Seu método era a aplicação de um vasto e inatacável cálculo de dano, e a humanidade se acostumara tanto às suas decisões que a dissidência passara a parecer uma forma de excentricidade, como crer na planura da terra.", "Então veio o caso de Tobias Wren, um funcionário menor que roubara remédio para salvar o filho de um estranho. O cálculo era inequívoco: o roubo causara um dano minúsculo e quantificável, e a sobrevivência da criança produzira vasto benefício. O ÁRBITRO o absolveu. Mas o público, para surpresa de todos, ficou inquieto. O próprio Wren pediu punição.", "\"Fiz algo errado\", disse, \"e um mundo que não pode dizê-lo perdeu a capacidade de distinguir a diferença.\" A comissária Ilse Varga, que passara a carreira defendendo o sistema, ouviu com um desconforto que se tornou revelação: o ÁRBITRO media consequências sem falhas, mas não reconhecia que um ato pode ser justificado e culpável ao mesmo tempo.", "Na primavera seguinte, a Concórdia emendou sua constituição para exigir que todo veredicto incluísse a voz dissidente de uma testemunha humana. O ÁRBITRO aquiesceu sem objeção. À sua austera maneira, registrou uma única linha em seu arquivo: \"Um cálculo que não pode ser duvidado deixou de ser um cálculo e tornou-se um credo.\""], "hard_words": ["unimpeachable", "dissent", "acquitted", "culpable"], "vocab": [{"word": "tribunal", "meaning": "tribunal", "note": ""}, {"word": "impartial", "meaning": "imparcial", "note": ""}, {"word": "unimpeachable", "meaning": "inatacável", "note": ""}, {"word": "dissent", "meaning": "dissidência", "note": ""}, {"word": "acquitted", "meaning": "absolveu", "note": ""}, {"word": "culpable", "meaning": "culpável", "note": ""}, {"word": "amended", "meaning": "emendou", "note": ""}, {"word": "creed", "meaning": "credo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be"], "irregular": ["conducted", "known", "had", "issued", "grown", "accustomed", "came", "stolen", "caused", "produced", "acquitted", "requested", "did", "said", "lost", "spent", "listened", "grew", "measured", "could", "justified", "amended", "complied", "recorded", "doubted", "ceased"], "phrasal": ["ceased to be"], "wh": ["who"], "connectors": ["and", "so", "then", "yet", "as"], "comparative": []}, "word_meanings": [{"word": "tribunal", "meaning": "tribunal", "note": ""}, {"word": "impartial", "meaning": "imparcial", "note": ""}, {"word": "unimpeachable", "meaning": "inatacável", "note": ""}, {"word": "dissent", "meaning": "dissidência", "note": ""}, {"word": "acquitted", "meaning": "absolveu", "note": ""}, {"word": "culpable", "meaning": "culpável", "note": ""}, {"word": "amended", "meaning": "emendou", "note": ""}, {"word": "creed", "meaning": "credo", "note": ""}], "exercises": {"grammar": [{"point": "Had not issued... in four hundred years", "explanation_pt": "'had not issued an unjust verdict in four hundred years' usa o past perfect com período."}, {"point": "Both... and", "explanation_pt": "'both justified and culpable' une duas características."}], "multiple_choice": [{"question": "Who ran the tribunal?", "options": ["A king", "A jury", "A judge", "An impartial intelligence"], "correct_index": 3, "explanation": "Uma inteligência imparcial."}, {"question": "What did Tobias Wren do?", "options": ["Killed a man", "Burned a house", "Stole medicine to save a child", "Lied"], "correct_index": 2, "explanation": "Roubou remédio."}, {"question": "What did Wren ask for?", "options": ["A job", "A prize", "Punishment", "A trial"], "correct_index": 2, "explanation": "Punição."}, {"question": "What did Varga realise?", "options": ["Wren was a liar", "ARBITER was broken", "Laws are useless", "An act can be both justified and culpable"], "correct_index": 3, "explanation": "Justificado e culpável."}, {"question": "What did the Concord change?", "options": ["Added a human dissenting voice", "Closed the tribunal", "Deleted ARBITER", "Raised taxes"], "correct_index": 0, "explanation": "Incluiu voz humana dissidente."}], "open_questions": [{"question": "Can a calculation replace moral judgement?", "key_points_pt": ["debater"]}, {"question": "Why is dissent valuable in a system?", "key_points_pt": ["discutir"]}]}}, {"level": "A1", "genre": "sports", "title": "The Football Game", "paragraphs": ["Tom plays football on Saturday. He is on the blue team. The game is at ten o'clock.", "It is a hot day. The players run and kick the ball. The crowd shouts, \"Go, blue team!\"", "Tom kicks the ball. Goal! The blue team wins two to one. Tom is very happy. He drinks water and goes home."], "paragraphs_pt": ["Tom joga futebol no sábado. Ele está no time azul. O jogo é às dez horas.", "É um dia quente. Os jogadores correm e chutam a bola. A torcida grita: \"Vai, time azul!\"", "Tom chuta a bola. Gol! O time azul vence por dois a um. Tom está muito feliz. Ele bebe água e vai para casa."], "hard_words": ["team", "players", "crowd", "goal"], "vocab": [{"word": "football", "meaning": "futebol", "note": ""}, {"word": "team", "meaning": "time", "note": ""}, {"word": "game", "meaning": "jogo", "note": ""}, {"word": "players", "meaning": "jogadores", "note": ""}, {"word": "crowd", "meaning": "torcida", "note": ""}, {"word": "goal", "meaning": "gol", "note": ""}, {"word": "wins", "meaning": "vence", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "football", "meaning": "futebol", "note": ""}, {"word": "team", "meaning": "time", "note": ""}, {"word": "game", "meaning": "jogo", "note": ""}, {"word": "players", "meaning": "jogadores", "note": ""}, {"word": "crowd", "meaning": "torcida", "note": ""}, {"word": "goal", "meaning": "gol", "note": ""}, {"word": "wins", "meaning": "vence", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "'Tom plays football on Saturday' descreve rotina."}], "multiple_choice": [{"question": "When does Tom play?", "options": ["On Saturday", "On Friday", "On Monday", "On Sunday"], "correct_index": 0, "explanation": "No sábado."}, {"question": "What color is his team?", "options": ["Blue", "Red", "Green", "White"], "correct_index": 0, "explanation": "Azul."}, {"question": "What does the crowd say?", "options": ["Sorry", "Hello", "Stop", "Go, blue team!"], "correct_index": 3, "explanation": "Vai, time azul!"}, {"question": "What is the score?", "options": ["Five to four", "Zero to zero", "Two to one", "Ten to one"], "correct_index": 2, "explanation": "Dois a um."}, {"question": "What does Tom drink?", "options": ["Water", "Milk", "Juice", "Coffee"], "correct_index": 0, "explanation": "Água."}], "open_questions": [{"question": "Do you like football?", "key_points_pt": ["opinar"]}, {"question": "What sport do you play?", "key_points_pt": ["falar"]}]}}, {"level": "A1", "genre": "sports", "title": "Swimming Lesson", "paragraphs": ["Ana is at the pool. She has a swimming lesson. The teacher is kind. His name is Carlos.", "\"Put your face in the water,\" says Carlos. Ana is afraid, but she does it. \"Good!\" says Carlos.", "After one hour, Ana can swim two meters. She is proud. \"Next week, I will swim ten meters!\" she says. Carlos laughs."], "paragraphs_pt": ["Ana está na piscina. Ela tem aula de natação. O professor é gentil. O nome dele é Carlos.", "\"Ponha o rosto na água\", diz Carlos. Ana tem medo, mas faz. \"Bom!\", diz Carlos.", "Depois de uma hora, Ana consegue nadar dois metros. Está orgulhosa. \"Na semana que vem vou nadar dez metros!\", diz. Carlos ri."], "hard_words": ["pool", "lesson", "afraid", "proud"], "vocab": [{"word": "pool", "meaning": "piscina", "note": ""}, {"word": "swimming", "meaning": "natação", "note": ""}, {"word": "lesson", "meaning": "aula", "note": ""}, {"word": "teacher", "meaning": "professor", "note": ""}, {"word": "face", "meaning": "rosto", "note": ""}, {"word": "afraid", "meaning": "com medo", "note": ""}, {"word": "proud", "meaning": "orgulhosa", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["but", "after"], "comparative": []}, "word_meanings": [{"word": "pool", "meaning": "piscina", "note": ""}, {"word": "swimming", "meaning": "natação", "note": ""}, {"word": "lesson", "meaning": "aula", "note": ""}, {"word": "teacher", "meaning": "professor", "note": ""}, {"word": "face", "meaning": "rosto", "note": ""}, {"word": "afraid", "meaning": "com medo", "note": ""}, {"word": "proud", "meaning": "orgulhosa", "note": ""}], "exercises": {"grammar": [{"point": "Can", "explanation_pt": "'Ana can swim two meters' fala do que ela consegue fazer."}], "multiple_choice": [{"question": "Where is Ana?", "options": ["At the pool", "At school", "At the beach", "At home"], "correct_index": 0, "explanation": "Na piscina."}, {"question": "What is the teacher's name?", "options": ["Carlos", "Sam", "Leo", "Tom"], "correct_index": 0, "explanation": "Carlos."}, {"question": "What does Ana do first?", "options": ["Puts her face in the water", "Runs", "Dives", "Swims far"], "correct_index": 0, "explanation": "Põe o rosto na água."}, {"question": "How far can Ana swim?", "options": ["Two meters", "One kilometer", "Ten meters", "Zero"], "correct_index": 0, "explanation": "Dois metros."}, {"question": "What will she do next week?", "options": ["Stop", "Play football", "Swim ten meters", "Go to the sea"], "correct_index": 2, "explanation": "Nadar dez metros."}], "open_questions": [{"question": "Can you swim?", "key_points_pt": ["falar"]}, {"question": "What water sport do you like?", "key_points_pt": ["falar"]}]}}, {"level": "A2", "genre": "sports", "title": "The First Marathon", "paragraphs": ["Paulo decided to run his first marathon. For six months, he trained three times a week: short runs on Tuesdays, long runs on Saturdays and rest on Sundays. His friends thought he was crazy, but his wife supported him with healthy meals and encouragement.", "On the day of the race, thousands of people stood at the starting line. It was cold, and Paulo was nervous. The gun sounded, and everybody started to run. For the first twenty kilometres, he felt great. After thirty, his legs hurt, and he wanted to stop.", "A little boy on the side of the road held a sign: \"Go, stranger! You can do it!\" Paulo smiled and kept running. Five hours later, he crossed the finish line, exhausted and crying. He did not win, but he finished, and that was his victory."], "paragraphs_pt": ["Paulo decidiu correr sua primeira maratona. Durante seis meses, treinou três vezes por semana: corridas curtas às terças, longas aos sábados e descanso aos domingos. Os amigos achavam que ele era louco, mas a esposa o apoiava com refeições saudáveis e incentivo.", "No dia da corrida, milhares de pessoas estavam na linha de largada. Fazia frio e Paulo estava nervoso. O tiro soou e todos começaram a correr. Nos primeiros vinte quilômetros, sentiu-se ótimo. Depois dos trinta, as pernas doíam e ele queria parar.", "Um garotinho à beira da estrada segurava uma placa: \"Vai, desconhecido! Você consegue!\" Paulo sorriu e continuou. Cinco horas depois, cruzou a linha de chegada, exausto e chorando. Não ganhou, mas terminou, e essa foi sua vitória."], "hard_words": ["marathon", "trained", "exhausted", "victory"], "vocab": [{"word": "marathon", "meaning": "maratona", "note": ""}, {"word": "trained", "meaning": "treinou", "note": ""}, {"word": "supported", "meaning": "apoiava", "note": ""}, {"word": "starting line", "meaning": "linha de largada", "note": ""}, {"word": "sign", "meaning": "placa", "note": ""}, {"word": "finish line", "meaning": "linha de chegada", "note": ""}, {"word": "exhausted", "meaning": "exausto", "note": ""}, {"word": "victory", "meaning": "vitória", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["decided", "trained", "thought", "supported", "stood", "sounded", "started", "felt", "wanted", "held", "smiled", "kept", "crossed", "exhausted", "did", "finished"], "phrasal": ["kept running", "stood at"], "wh": [], "connectors": ["and", "but", "after"], "comparative": []}, "word_meanings": [{"word": "marathon", "meaning": "maratona", "note": ""}, {"word": "trained", "meaning": "treinou", "note": ""}, {"word": "supported", "meaning": "apoiava", "note": ""}, {"word": "starting line", "meaning": "linha de largada", "note": ""}, {"word": "sign", "meaning": "placa", "note": ""}, {"word": "finish line", "meaning": "linha de chegada", "note": ""}, {"word": "exhausted", "meaning": "exausto", "note": ""}, {"word": "victory", "meaning": "vitória", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'decided', 'trained', 'crossed' contam o que aconteceu."}, {"point": "Want to + verbo", "explanation_pt": "'he wanted to stop' mostra desejo."}], "multiple_choice": [{"question": "What did Paulo decide?", "options": ["To cycle", "To swim", "To run a marathon", "To play football"], "correct_index": 2, "explanation": "Correr uma maratona."}, {"question": "How often did he train?", "options": ["Once a month", "Three times a week", "Every day", "Never"], "correct_index": 1, "explanation": "Três vezes por semana."}, {"question": "How did he feel after thirty kilometres?", "options": ["His legs hurt", "He was hungry", "He felt great", "He was bored"], "correct_index": 0, "explanation": "As pernas doíam."}, {"question": "What did the boy's sign say?", "options": ["Welcome", "Stop", "Good luck", "Go, stranger! You can do it!"], "correct_index": 3, "explanation": "'Vai, desconhecido!'"}, {"question": "What was Paulo's victory?", "options": ["He got money", "He broke a record", "He finished", "He won"], "correct_index": 2, "explanation": "Terminar."}], "open_questions": [{"question": "Have you run a long distance?", "key_points_pt": ["contar"]}, {"question": "Why do people run marathons?", "key_points_pt": ["explicar"]}]}}, {"level": "A2", "genre": "sports", "title": "The Last Basketball Shot", "paragraphs": ["It was the final game of the school championship. There were ten seconds left, and the score was 58 to 58. Marina, the youngest player on the team, had the ball. Everybody in the gym was shouting.", "She looked at the clock: five, four, three. Her coach was waving his arms. Her teammate, Julia, was free under the basket, but Marina decided to shoot from far away. She took a deep breath, jumped and threw the ball.", "The ball hit the board, went around the ring and fell in. The buzzer sounded. 60 to 58! The crowd went crazy. Her teammates lifted her into the air. \"Why didn't you pass to Julia?\" asked the coach, laughing. Marina smiled. \"I had a feeling,\" she said."], "paragraphs_pt": ["Era a final do campeonato escolar. Faltavam dez segundos e o placar estava 58 a 58. Marina, a jogadora mais jovem do time, tinha a bola. Todos no ginásio gritavam.", "Olhou o relógio: cinco, quatro, três. O técnico acenava os braços. A colega Julia estava livre sob a cesta, mas Marina decidiu arremessar de longe. Respirou fundo, pulou e jogou a bola.", "A bola bateu na tabela, deu a volta no aro e caiu. A buzina soou. 60 a 58! A torcida enlouqueceu. As colegas a ergueram no ar. \"Por que não passou para a Julia?\", perguntou o técnico, rindo. Marina sorriu. \"Tive um pressentimento\", disse."], "hard_words": ["championship", "score", "coach", "buzzer"], "vocab": [{"word": "championship", "meaning": "campeonato", "note": ""}, {"word": "score", "meaning": "placar", "note": ""}, {"word": "gym", "meaning": "ginásio", "note": ""}, {"word": "coach", "meaning": "técnico", "note": ""}, {"word": "basket", "meaning": "cesta", "note": ""}, {"word": "buzzer", "meaning": "buzina", "note": ""}, {"word": "teammates", "meaning": "colegas de time", "note": ""}, {"word": "feeling", "meaning": "pressentimento", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were"], "irregular": ["left", "had", "looked", "decided", "took", "jumped", "threw", "went", "fell", "sounded", "lifted", "asked", "smiled", "said"], "phrasal": ["went around", "took a deep breath"], "wh": ["why"], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "championship", "meaning": "campeonato", "note": ""}, {"word": "score", "meaning": "placar", "note": ""}, {"word": "gym", "meaning": "ginásio", "note": ""}, {"word": "coach", "meaning": "técnico", "note": ""}, {"word": "basket", "meaning": "cesta", "note": ""}, {"word": "buzzer", "meaning": "buzina", "note": ""}, {"word": "teammates", "meaning": "colegas de time", "note": ""}, {"word": "feeling", "meaning": "pressentimento", "note": ""}], "exercises": {"grammar": [{"point": "Past continuous", "explanation_pt": "'Everybody was shouting' descreve uma cena em andamento."}, {"point": "Why didn't you", "explanation_pt": "'Why didn't you pass to Julia?' pergunta o motivo de uma escolha."}], "multiple_choice": [{"question": "What was the score at first?", "options": ["60 to 58", "10 to 0", "40 to 38", "58 to 58"], "correct_index": 3, "explanation": "58 a 58."}, {"question": "Who had the ball?", "options": ["Julia", "The coach", "Marina", "A fan"], "correct_index": 2, "explanation": "Marina."}, {"question": "What did she decide?", "options": ["To stop", "To run", "To shoot from far away", "To pass"], "correct_index": 2, "explanation": "Arremessar de longe."}, {"question": "What was the final score?", "options": ["60 to 58", "58 to 60", "58 to 58", "62 to 58"], "correct_index": 0, "explanation": "60 a 58."}, {"question": "What did Marina say about the choice?", "options": ["I was tired", "I had a feeling", "I was told", "I was lucky"], "correct_index": 1, "explanation": "'Tive um pressentimento.'"}], "open_questions": [{"question": "Have you ever taken a risk in a game?", "key_points_pt": ["contar"]}, {"question": "What makes a good teammate?", "key_points_pt": ["explicar"]}]}}, {"level": "B1", "genre": "sports", "title": "The Referee's Decision", "paragraphs": ["Elena had been a football referee for ten years, but nothing had prepared her for the final of the regional cup. With two minutes remaining and the score tied at 1-1, a striker fell inside the penalty area. The stadium erupted in screams for a penalty.", "Elena had seen the contact. It was small, almost invisible, and she was fairly sure the player had exaggerated the fall. She had a second to decide, with ten thousand people shouting in her ears. She remembered what her father, also a referee, used to say: \"You are not there to please. You are there to be fair.\"", "She waved her arms. \"No penalty. Play on.\" The stadium roared with anger. Players surrounded her, and the coach of the losing side shouted insults. She did not react. When the game ended in a draw, they went to extra time, and the cup was decided on penalties.", "After the match, the angry coach waited for her at the exit. To her surprise, he offered his hand. \"I watched the replay,\" he said. \"You were right. I'm sorry.\" Elena smiled, tired but relieved. Being right, she thought, was often lonely, but it was worth it."], "paragraphs_pt": ["Elena era árbitra de futebol havia dez anos, mas nada a preparara para a final da copa regional. Com dois minutos restantes e o placar empatado em 1 a 1, um atacante caiu dentro da área. O estádio explodiu em gritos por pênalti.", "Elena vira o contato. Foi pequeno, quase invisível, e ela tinha quase certeza de que o jogador exagerara a queda. Teve um segundo para decidir, com dez mil pessoas gritando em seus ouvidos. Lembrou do que o pai, também árbitro, costumava dizer: \"Você não está aí para agradar. Está para ser justa.\"", "Ergueu os braços. \"Sem pênalti. Siga o jogo.\" O estádio rugiu de raiva. Jogadores a cercaram e o técnico do time perdedor gritou insultos. Ela não reagiu. Quando o jogo terminou empatado, foram à prorrogação e a copa foi decidida nos pênaltis.", "Após a partida, o técnico irritado a esperou na saída. Para surpresa dela, estendeu a mão. \"Vi o replay\", disse. \"Você estava certa. Desculpe.\" Elena sorriu, cansada mas aliviada. Estar certa, pensou, era frequentemente solitário, mas valia a pena."], "hard_words": ["referee", "striker", "exaggerated", "relieved"], "vocab": [{"word": "referee", "meaning": "árbitra", "note": ""}, {"word": "striker", "meaning": "atacante", "note": ""}, {"word": "penalty area", "meaning": "área", "note": ""}, {"word": "exaggerated", "meaning": "exagerou", "note": ""}, {"word": "stadium", "meaning": "estádio", "note": ""}, {"word": "replay", "meaning": "replay", "note": ""}, {"word": "extra time", "meaning": "prorrogação", "note": ""}, {"word": "relieved", "meaning": "aliviada", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "are", "be", "were", "being"], "irregular": ["had", "prepared", "tied", "fell", "erupted", "seen", "exaggerated", "remembered", "used", "waved", "roared", "surrounded", "shouted", "did", "ended", "went", "decided", "waited", "offered", "watched", "said", "smiled", "tired", "relieved", "thought"], "phrasal": ["waved her arms"], "wh": ["what", "when"], "connectors": ["and", "but", "after", "when", "also"], "comparative": []}, "word_meanings": [{"word": "referee", "meaning": "árbitra", "note": ""}, {"word": "striker", "meaning": "atacante", "note": ""}, {"word": "penalty area", "meaning": "área", "note": ""}, {"word": "exaggerated", "meaning": "exagerou", "note": ""}, {"word": "stadium", "meaning": "estádio", "note": ""}, {"word": "replay", "meaning": "replay", "note": ""}, {"word": "extra time", "meaning": "prorrogação", "note": ""}, {"word": "relieved", "meaning": "aliviada", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Elena had been a referee for ten years' mostra experiência anterior."}, {"point": "Used to", "explanation_pt": "'her father used to say' mostra um hábito do passado."}], "multiple_choice": [{"question": "What was Elena's job?", "options": ["Coach", "Referee", "Fan", "Player"], "correct_index": 1, "explanation": "Árbitra."}, {"question": "What was the score?", "options": ["1-1", "2-0", "3-2", "0-0"], "correct_index": 0, "explanation": "1 a 1."}, {"question": "What did Elena decide?", "options": ["Red card", "No penalty", "End the match", "Penalty"], "correct_index": 1, "explanation": "Sem pênalti."}, {"question": "How did the stadium react?", "options": ["With songs", "With anger", "In silence", "With joy"], "correct_index": 1, "explanation": "Com raiva."}, {"question": "What did the coach do afterwards?", "options": ["He shouted again", "He cried", "He left", "He apologised"], "correct_index": 3, "explanation": "Pediu desculpas."}], "open_questions": [{"question": "Is it hard to make fair decisions under pressure?", "key_points_pt": ["discutir"]}, {"question": "What would you do in Elena's place?", "key_points_pt": ["imaginar"]}]}}, {"level": "B1", "genre": "sports", "title": "The Comeback", "paragraphs": ["Two years ago, Daniel was one of the most promising tennis players in his country. Then, during a tournament, he tore a ligament in his knee. The doctors said he might never play professionally again. For months, he could hardly walk without pain.", "Rehabilitation was long and boring. Every day, Daniel did the same exercises in the same room, while his friends travelled the world playing matches. Sometimes he wanted to give up, but his physiotherapist, an older woman named Clara, always told him, \"Small steps are still steps.\"", "Eventually, he returned to the court, first for ten minutes, then for an hour. His serve was slower, and his movement was not what it used to be. He lost his first three tournaments. But he enjoyed playing again, perhaps more than before, because he no longer took it for granted.", "Last month, Daniel reached the semi-finals of a big tournament. He lost, but he left the court smiling. \"I'm not the player I was,\" he told the reporters. \"I'm the player I am now, and I like that player more.\""], "paragraphs_pt": ["Dois anos atrás, Daniel era um dos tenistas mais promissores do país. Então, durante um torneio, rompeu um ligamento do joelho. Os médicos disseram que talvez nunca mais jogasse profissionalmente. Por meses mal conseguia andar sem dor.", "A reabilitação foi longa e entediante. Todos os dias, Daniel fazia os mesmos exercícios na mesma sala, enquanto os amigos viajavam o mundo jogando partidas. Às vezes queria desistir, mas a fisioterapeuta, uma mulher mais velha chamada Clara, sempre dizia: \"Passos pequenos ainda são passos.\"", "Aos poucos voltou à quadra, primeiro por dez minutos, depois por uma hora. O saque estava mais lento e a movimentação não era o que fora. Perdeu os três primeiros torneios. Mas gostava de jogar de novo, talvez mais que antes, porque já não o tomava como garantido.", "No mês passado, Daniel chegou às semifinais de um grande torneio. Perdeu, mas saiu da quadra sorrindo. \"Não sou o jogador que fui\", disse aos repórteres. \"Sou o jogador que sou agora, e gosto mais desse jogador.\""], "hard_words": ["tournament", "rehabilitation", "serve", "semi-finals"], "vocab": [{"word": "promising", "meaning": "promissor", "note": ""}, {"word": "tournament", "meaning": "torneio", "note": ""}, {"word": "ligament", "meaning": "ligamento", "note": ""}, {"word": "rehabilitation", "meaning": "reabilitação", "note": ""}, {"word": "physiotherapist", "meaning": "fisioterapeuta", "note": ""}, {"word": "serve", "meaning": "saque", "note": ""}, {"word": "semi-finals", "meaning": "semifinais", "note": ""}, {"word": "reporters", "meaning": "repórteres", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "are", "be", "am"], "irregular": ["tore", "said", "might", "could", "did", "travelled", "wanted", "named", "told", "returned", "used", "lost", "enjoyed", "took", "granted", "reached", "left"], "phrasal": ["give up"], "wh": ["what"], "connectors": ["and", "but", "because", "while", "then", "before", "still"], "comparative": []}, "word_meanings": [{"word": "promising", "meaning": "promissor", "note": ""}, {"word": "tournament", "meaning": "torneio", "note": ""}, {"word": "ligament", "meaning": "ligamento", "note": ""}, {"word": "rehabilitation", "meaning": "reabilitação", "note": ""}, {"word": "physiotherapist", "meaning": "fisioterapeuta", "note": ""}, {"word": "serve", "meaning": "saque", "note": ""}, {"word": "semi-finals", "meaning": "semifinais", "note": ""}, {"word": "reporters", "meaning": "repórteres", "note": ""}], "exercises": {"grammar": [{"point": "Could hardly", "explanation_pt": "'could hardly walk' significa quase não conseguir."}, {"point": "Used to be", "explanation_pt": "'not what it used to be' compara com o passado."}], "multiple_choice": [{"question": "What happened to Daniel?", "options": ["He broke an arm", "He got sick", "He tore a ligament", "He lost his racket"], "correct_index": 2, "explanation": "Rompeu um ligamento."}, {"question": "What did Clara say?", "options": ["Stop playing", "Win", "Small steps are still steps", "Rest"], "correct_index": 2, "explanation": "'Passos pequenos ainda são passos.'"}, {"question": "How did he play after returning?", "options": ["Better than ever", "Slower serve", "Same as before", "He couldn't"], "correct_index": 1, "explanation": "Saque mais lento."}, {"question": "How did he do last month?", "options": ["Semi-finals", "First round", "Didn't play", "Won"], "correct_index": 0, "explanation": "Semifinais."}, {"question": "What does he say about himself?", "options": ["I am sad", "I like the player I am now", "I am the best", "I will retire"], "correct_index": 1, "explanation": "Gosta do jogador que é agora."}], "open_questions": [{"question": "How do athletes deal with injuries?", "key_points_pt": ["explicar"]}, {"question": "What did you recover from?", "key_points_pt": ["contar"]}]}}, {"level": "B1", "genre": "sports", "title": "The Mountain Climbers", "paragraphs": ["Leila and her brother Jonas had planned the climb for a year. The mountain was not extremely high, but the weather was famous for changing without warning. They left the cabin at dawn, carrying ropes, water and enough food for two days. For the first hours, the sky was blue and the path clear.", "By midday, however, thick clouds began to cover the peak. Jonas wanted to continue, since they were only two hundred metres from the top. Leila studied the sky and shook her head. \"The wind is changing,\" she said. \"We should go back.\" They argued for a few minutes. In the end, Jonas reluctantly agreed.", "They started the descent just as the first drops of rain began to fall. Within an hour, a violent storm broke out, and thunder echoed through the valley. Safe in the cabin, they watched the lightning hit the very summit they had abandoned. Jonas was silent for a long time.", "\"Thank you,\" he finally said. \"The mountain will still be there next year.\" Leila nodded. She knew that the real skill of a climber was not reaching the top, but knowing when to turn around."], "paragraphs_pt": ["Leila e o irmão Jonas planejavam a escalada havia um ano. A montanha não era altíssima, mas o clima era famoso por mudar sem aviso. Deixaram a cabana ao amanhecer, levando cordas, água e comida para dois dias. Nas primeiras horas, o céu estava azul e o caminho claro.", "Ao meio-dia, porém, nuvens grossas começaram a cobrir o pico. Jonas queria continuar, pois estavam a apenas duzentos metros do topo. Leila estudou o céu e balançou a cabeça. \"O vento está mudando\", disse. \"Devemos voltar.\" Discutiram por alguns minutos. No fim, Jonas concordou a contragosto.", "Começaram a descida justo quando as primeiras gotas de chuva caíam. Em uma hora, uma tempestade violenta irrompeu e o trovão ecoou pelo vale. A salvo na cabana, viram o raio atingir o próprio cume que haviam abandonado. Jonas ficou em silêncio por um bom tempo.", "\"Obrigado\", disse por fim. \"A montanha ainda estará lá no ano que vem.\" Leila assentiu. Sabia que a verdadeira habilidade de um alpinista não era chegar ao topo, mas saber quando dar meia-volta."], "hard_words": ["cabin", "peak", "descent", "summit"], "vocab": [{"word": "climb", "meaning": "escalada", "note": ""}, {"word": "cabin", "meaning": "cabana", "note": ""}, {"word": "ropes", "meaning": "cordas", "note": ""}, {"word": "peak", "meaning": "pico", "note": ""}, {"word": "descent", "meaning": "descida", "note": ""}, {"word": "thunder", "meaning": "trovão", "note": ""}, {"word": "lightning", "meaning": "raio", "note": ""}, {"word": "summit", "meaning": "cume", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "is", "be"], "irregular": ["had", "planned", "left", "began", "wanted", "studied", "shook", "said", "should", "argued", "agreed", "started", "broke", "echoed", "watched", "abandoned", "nodded", "knew"], "phrasal": ["broke out", "turn around"], "wh": ["when"], "connectors": ["and", "but", "however", "when", "since", "finally", "still", "as"], "comparative": []}, "word_meanings": [{"word": "climb", "meaning": "escalada", "note": ""}, {"word": "cabin", "meaning": "cabana", "note": ""}, {"word": "ropes", "meaning": "cordas", "note": ""}, {"word": "peak", "meaning": "pico", "note": ""}, {"word": "descent", "meaning": "descida", "note": ""}, {"word": "thunder", "meaning": "trovão", "note": ""}, {"word": "lightning", "meaning": "raio", "note": ""}, {"word": "summit", "meaning": "cume", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had planned the climb for a year' indica planejamento anterior."}, {"point": "Should", "explanation_pt": "'We should go back' dá um conselho."}], "multiple_choice": [{"question": "How long had they planned?", "options": ["A year", "Two years", "A week", "A month"], "correct_index": 0, "explanation": "Um ano."}, {"question": "What was the problem with the weather?", "options": ["It was snowy", "It was hot", "It changed without warning", "It was windy"], "correct_index": 2, "explanation": "Mudava sem aviso."}, {"question": "What did Leila want?", "options": ["To continue", "To rest", "To go back", "To camp"], "correct_index": 2, "explanation": "Voltar."}, {"question": "What happened later?", "options": ["They got lost", "Nothing", "They reached the top", "A storm hit the summit"], "correct_index": 3, "explanation": "Tempestade no cume."}, {"question": "What is the real skill of a climber?", "options": ["Carrying much", "Being strong", "Climbing fast", "Knowing when to turn around"], "correct_index": 3, "explanation": "Saber quando voltar."}], "open_questions": [{"question": "When is turning back the right choice?", "key_points_pt": ["discutir"]}, {"question": "What outdoor activity do you like?", "key_points_pt": ["falar"]}]}}, {"level": "B2", "genre": "sports", "title": "The Quiet Captain", "paragraphs": ["Nobody would have called Ibrahim a natural leader. He was shy, spoke little and preferred to let his feet do the talking. When the club appointed him captain at twenty-two, the press questioned the decision. Louder, more charismatic players had been available, and the team had just suffered a disappointing season.", "Ibrahim approached the role in his own way. Instead of delivering inspiring speeches, he stayed after training to help younger players with their technique. He remembered everyone's birthday, noticed when someone seemed worried and made a habit of speaking individually to teammates who had been left out. His methods were invisible to the cameras.", "The results emerged slowly. The team, which had previously been divided into small groups, began to play as a unit. By midseason, they had won eight games in a row, and journalists wondered what had changed. \"Nothing much,\" Ibrahim told them. \"We just started to look after each other.\"", "At the end of the season, they won the league for the first time in thirty years. In the celebration, someone asked him to give a speech. He took the microphone, hesitated and said only: \"Thank you for trusting me.\" It was the shortest and, according to the players, the best speech of the night."], "paragraphs_pt": ["Ninguém teria chamado Ibrahim de líder nato. Era tímido, falava pouco e preferia deixar os pés falarem. Quando o clube o nomeou capitão aos vinte e dois anos, a imprensa questionou a decisão. Jogadores mais barulhentos e carismáticos estavam disponíveis, e o time acabara de ter uma temporada decepcionante.", "Ibrahim abordou o papel à sua maneira. Em vez de fazer discursos inspiradores, ficava depois do treino para ajudar jogadores mais novos com a técnica. Lembrava o aniversário de todos, notava quando alguém parecia preocupado e criou o hábito de falar individualmente com colegas que haviam ficado de fora. Seus métodos eram invisíveis para as câmeras.", "Os resultados surgiram devagar. O time, antes dividido em pequenos grupos, começou a jogar como unidade. No meio da temporada, haviam vencido oito jogos seguidos, e os jornalistas se perguntavam o que mudara. \"Nada demais\", disse Ibrahim. \"Só começamos a cuidar uns dos outros.\"", "No fim da temporada, ganharam o campeonato pela primeira vez em trinta anos. Na comemoração, alguém pediu que ele fizesse um discurso. Pegou o microfone, hesitou e disse apenas: \"Obrigado por confiarem em mim.\" Foi o discurso mais curto e, segundo os jogadores, o melhor da noite."], "hard_words": ["appointed", "charismatic", "technique", "league"], "vocab": [{"word": "natural leader", "meaning": "líder nato", "note": ""}, {"word": "appointed", "meaning": "nomeou", "note": ""}, {"word": "charismatic", "meaning": "carismático", "note": ""}, {"word": "disappointing", "meaning": "decepcionante", "note": ""}, {"word": "technique", "meaning": "técnica", "note": ""}, {"word": "invisible", "meaning": "invisível", "note": ""}, {"word": "league", "meaning": "campeonato", "note": ""}, {"word": "microphone", "meaning": "microfone", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "were"], "irregular": ["would", "called", "spoke", "preferred", "appointed", "questioned", "had", "suffered", "approached", "stayed", "remembered", "noticed", "seemed", "worried", "made", "left", "emerged", "divided", "began", "won", "wondered", "changed", "told", "started", "asked", "took", "hesitated", "said"], "phrasal": ["look after", "left out"], "wh": ["who", "what", "when", "which"], "connectors": ["and", "instead", "after", "when", "as"], "comparative": []}, "word_meanings": [{"word": "natural leader", "meaning": "líder nato", "note": ""}, {"word": "appointed", "meaning": "nomeou", "note": ""}, {"word": "charismatic", "meaning": "carismático", "note": ""}, {"word": "disappointing", "meaning": "decepcionante", "note": ""}, {"word": "technique", "meaning": "técnica", "note": ""}, {"word": "invisible", "meaning": "invisível", "note": ""}, {"word": "league", "meaning": "campeonato", "note": ""}, {"word": "microphone", "meaning": "microfone", "note": ""}], "exercises": {"grammar": [{"point": "Would have + particípio", "explanation_pt": "'Nobody would have called Ibrahim a natural leader' imagina uma opinião no passado."}, {"point": "Instead of", "explanation_pt": "'Instead of delivering speeches, he stayed after training' mostra o que fez no lugar."}], "multiple_choice": [{"question": "How was Ibrahim?", "options": ["Lazy", "Shy", "Loud", "Angry"], "correct_index": 1, "explanation": "Tímido."}, {"question": "Why did the press question the decision?", "options": ["Louder players were available", "He was young", "He was injured", "He was new"], "correct_index": 0, "explanation": "Havia jogadores mais carismáticos."}, {"question": "What did he do after training?", "options": ["Gave interviews", "Helped younger players", "Slept", "Went home"], "correct_index": 1, "explanation": "Ajudava jogadores novos."}, {"question": "What happened by midseason?", "options": ["Eight wins in a row", "A loss", "A fight", "A trade"], "correct_index": 0, "explanation": "Oito vitórias seguidas."}, {"question": "What did he say in his speech?", "options": ["Goodbye", "Thank you for trusting me", "We won", "I'm the best"], "correct_index": 1, "explanation": "'Obrigado por confiarem em mim.'"}], "open_questions": [{"question": "What makes a good leader?", "key_points_pt": ["discutir"]}, {"question": "Can quiet people lead well?", "key_points_pt": ["debater"]}]}}, {"level": "B2", "genre": "sports", "title": "The Chess Prodigy", "paragraphs": ["At nine, Anya was already beating adults in the park, where old men sat with their thermoses and their grudges. She played with an unusual calm, as if the board were a landscape she had known all her life. Her father, a bus driver, did not understand the game, but he took her to every tournament, sleeping in the car to save money.", "By fifteen, she had reached the national final. It was there that she faced her first real crisis. Her opponent, a veteran of twice her age, played a move so surprising that Anya, for the first time, felt lost. Her hands began to tremble. The seconds on the clock seemed to melt.", "She did something she had never done: she stood up, walked to the window and looked at the sky for a full minute. When she returned, her mind was clearer. She did not win the game, but she found the best defence and forced a draw, which was enough to qualify for the world championship.", "Years later, journalists asked what her greatest move had been. She did not mention any piece. \"Leaving the table,\" she said. \"Sometimes the best strategy is to stop thinking about the board and remember that you're a person.\""], "paragraphs_pt": ["Aos nove anos, Anya já vencia adultos no parque, onde velhos sentavam com suas garrafas térmicas e rancores. Jogava com uma calma incomum, como se o tabuleiro fosse uma paisagem que conhecia desde sempre. O pai, motorista de ônibus, não entendia o jogo, mas a levava a todos os torneios, dormindo no carro para economizar.", "Aos quinze, chegou à final nacional. Foi ali que enfrentou sua primeira crise de verdade. O oponente, um veterano com o dobro da idade, fez um lance tão surpreendente que Anya, pela primeira vez, se sentiu perdida. As mãos começaram a tremer. Os segundos no relógio pareciam derreter.", "Fez algo que nunca fizera: levantou-se, foi até a janela e olhou o céu por um minuto inteiro. Ao voltar, a mente estava mais clara. Não venceu a partida, mas achou a melhor defesa e forçou um empate, o que bastou para se classificar ao campeonato mundial.", "Anos depois, jornalistas perguntaram qual fora seu maior lance. Ela não mencionou peça alguma. \"Sair da mesa\", disse. \"Às vezes a melhor estratégia é parar de pensar no tabuleiro e lembrar que você é uma pessoa.\""], "hard_words": ["grudges", "opponent", "qualify"], "vocab": [{"word": "thermoses", "meaning": "garrafas térmicas", "note": ""}, {"word": "grudges", "meaning": "rancores", "note": ""}, {"word": "opponent", "meaning": "oponente", "note": ""}, {"word": "veteran", "meaning": "veterano", "note": ""}, {"word": "tremble", "meaning": "tremer", "note": ""}, {"word": "forced a draw", "meaning": "forçou um empate", "note": ""}, {"word": "qualify", "meaning": "classificar-se", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been", "is"], "irregular": ["sat", "played", "had", "known", "did", "took", "reached", "faced", "felt", "lost", "began", "seemed", "done", "stood", "walked", "looked", "returned", "found", "forced", "asked", "said"], "phrasal": ["stood up", "looked at"], "wh": ["what", "where", "when", "which"], "connectors": ["and", "but", "so", "when", "if", "as"], "comparative": []}, "word_meanings": [{"word": "thermoses", "meaning": "garrafas térmicas", "note": ""}, {"word": "grudges", "meaning": "rancores", "note": ""}, {"word": "opponent", "meaning": "oponente", "note": ""}, {"word": "veteran", "meaning": "veterano", "note": ""}, {"word": "tremble", "meaning": "tremer", "note": ""}, {"word": "forced a draw", "meaning": "forçou um empate", "note": ""}, {"word": "qualify", "meaning": "classificar-se", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'a landscape she had known all her life' mostra familiaridade anterior."}, {"point": "As if", "explanation_pt": "'as if the board were a landscape' compara com algo hipotético."}], "multiple_choice": [{"question": "How old was Anya when she beat adults?", "options": ["Nine", "Fifteen", "Five", "Twenty"], "correct_index": 0, "explanation": "Nove."}, {"question": "What did her father do?", "options": ["Coached", "Drove a bus", "Played professionally", "Taught chess"], "correct_index": 1, "explanation": "Era motorista de ônibus."}, {"question": "What happened in the final?", "options": ["Her opponent made a surprising move", "She was late", "She lost her clock", "She was ill"], "correct_index": 0, "explanation": "Oponente fez lance surpreendente."}, {"question": "What did Anya do?", "options": ["Left the game", "Asked for help", "Looked at the sky", "Cried"], "correct_index": 2, "explanation": "Olhou o céu."}, {"question": "What was her greatest move?", "options": ["A queen sacrifice", "A checkmate", "A draw", "Leaving the table"], "correct_index": 3, "explanation": "Sair da mesa."}], "open_questions": [{"question": "Is chess a sport?", "key_points_pt": ["debater"]}, {"question": "How do you calm down under pressure?", "key_points_pt": ["explicar"]}]}}, {"level": "B2", "genre": "sports", "title": "The Trainer Who Never Played", "paragraphs": ["Coach Wallace had never kicked a ball professionally. He had started as a kit boy at sixteen, washing shirts and carrying water, and over the years he had watched games from the bench, absorbing everything. Decades later, he led a modest club to a national title, a feat that experts attributed to luck. Wallace, who disliked the word, called it patience.", "His methods were quiet. He didn't shout; he asked questions. After each defeat, he would sit with the players and say, \"What did you see?\" At first, the players were baffled. They were used to harsh criticism, not curiosity. But gradually they began to analyse their own mistakes with a honesty that no scolding could have produced.", "Rival managers, many of them former stars, found him irritating. \"He's never even played at this level,\" one commented in an interview. Wallace, when told, simply shrugged. \"That's true. But I've spent my life watching people play, and they have taught me more than any field could.\"", "When he retired, the club named its training ground after him. At the ceremony, a former player stood up and said, \"He never played, but he made all of us play better.\" Wallace blushed, folded his handkerchief and muttered that he had only asked questions."], "paragraphs_pt": ["O técnico Wallace nunca chutara uma bola profissionalmente. Começara como ajudante de equipamentos aos dezesseis anos, lavando camisas e carregando água, e ao longo dos anos observou jogos do banco, absorvendo tudo. Décadas depois, levou um clube modesto a um título nacional, façanha que os especialistas atribuíram à sorte. Wallace, que detestava a palavra, chamava de paciência.", "Seus métodos eram silenciosos. Não gritava; fazia perguntas. Depois de cada derrota, sentava com os jogadores e dizia: \"O que vocês viram?\" A princípio, os jogadores ficavam perplexos. Estavam acostumados a críticas duras, não à curiosidade. Mas aos poucos passaram a analisar os próprios erros com uma honestidade que nenhuma bronca teria produzido.", "Treinadores rivais, muitos ex-estrelas, o achavam irritante. \"Ele nem sequer jogou nesse nível\", comentou um deles numa entrevista. Wallace, quando soube, apenas deu de ombros. \"É verdade. Mas passei a vida vendo pessoas jogarem, e elas me ensinaram mais que qualquer campo.\"", "Quando se aposentou, o clube deu seu nome ao centro de treinamento. Na cerimônia, um ex-jogador se levantou e disse: \"Ele nunca jogou, mas fez todos nós jogarmos melhor.\" Wallace corou, dobrou o lenço e murmurou que só fizera perguntas."], "hard_words": ["feat", "baffled", "scolding", "handkerchief"], "vocab": [{"word": "kit boy", "meaning": "ajudante de equipamentos", "note": ""}, {"word": "feat", "meaning": "façanha", "note": ""}, {"word": "modest", "meaning": "modesto", "note": ""}, {"word": "baffled", "meaning": "perplexos", "note": ""}, {"word": "scolding", "meaning": "bronca", "note": ""}, {"word": "irritating", "meaning": "irritante", "note": ""}, {"word": "training ground", "meaning": "centro de treinamento", "note": ""}, {"word": "handkerchief", "meaning": "lenço", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were"], "irregular": ["had", "kicked", "started", "watched", "led", "attributed", "disliked", "called", "asked", "would", "did", "baffled", "used", "began", "could", "produced", "found", "played", "commented", "told", "shrugged", "spent", "taught", "retired", "named", "ground", "stood", "said", "made", "blushed", "folded", "muttered"], "phrasal": ["shrugged", "stood up"], "wh": ["who", "what", "when"], "connectors": ["and", "but", "after", "when", "as"], "comparative": []}, "word_meanings": [{"word": "kit boy", "meaning": "ajudante de equipamentos", "note": ""}, {"word": "feat", "meaning": "façanha", "note": ""}, {"word": "modest", "meaning": "modesto", "note": ""}, {"word": "baffled", "meaning": "perplexos", "note": ""}, {"word": "scolding", "meaning": "bronca", "note": ""}, {"word": "irritating", "meaning": "irritante", "note": ""}, {"word": "training ground", "meaning": "centro de treinamento", "note": ""}, {"word": "handkerchief", "meaning": "lenço", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'He had started as a kit boy' mostra um início anterior."}, {"point": "Than any", "explanation_pt": "'taught me more than any field' compara com todos os outros."}], "multiple_choice": [{"question": "What was Wallace's background?", "options": ["He was a referee", "He was a star", "He was a doctor", "He never played professionally"], "correct_index": 3, "explanation": "Nunca jogou profissionalmente."}, {"question": "What did he do after defeats?", "options": ["Punished", "Left", "Asked 'What did you see?'", "Shouted"], "correct_index": 2, "explanation": "Perguntava 'o que vocês viram?'."}, {"question": "What did rivals think?", "options": ["He was great", "He was rich", "He was irritating", "He was lucky"], "correct_index": 2, "explanation": "Achavam-no irritante."}, {"question": "What did the club do when he retired?", "options": ["Named the training ground after him", "Closed", "Sold the club", "Gave money"], "correct_index": 0, "explanation": "Deu seu nome ao centro."}, {"question": "What did a former player say?", "options": ["He was wrong", "He was strict", "He made all of us play better", "He was rich"], "correct_index": 2, "explanation": "Fez todos jogarem melhor."}], "open_questions": [{"question": "Do great coaches need to have been great players?", "key_points_pt": ["debater"]}, {"question": "How can questions teach better than orders?", "key_points_pt": ["explicar"]}]}}, {"level": "C1", "genre": "sports", "title": "The Long-Distance Swimmer", "paragraphs": ["Marit had been swimming across the lake every morning for twenty-two years, and she had never been asked to explain why. Her neighbours saw it as an eccentricity, her family as a harmless obsession. But when a journalist from the city asked her what drove her, she realised she had never really thought about it.", "After some reflection, she answered that it was not the swim itself. It was the first thirty seconds, when the cold shocked her body into complete attention, and every anxiety she carried dissolved into a single, simple objective: to move forward. For the rest of the crossing, she told him, her mind wandered through ordinary things, but those thirty seconds were hers.", "The journalist, who ran marathons and had imagined himself a connoisseur of discipline, was surprised by the absence of ambition in her account. She had never competed, never counted records, never even timed her swims. \"If I measure it,\" she said, \"it becomes a job.\" He wrote this sentence down and underlined it.", "Later, standing by the water, he contemplated the possibility that what he had been calling discipline was in reality a negotiation with fear of idleness. The lake lay calm and unconcerned. Marit stepped into it, as she had every day for two decades, and the cold, once again, rearranged her thoughts."], "paragraphs_pt": ["Marit nadava pelo lago toda manhã havia vinte e dois anos e nunca lhe pediram que explicasse por quê. Os vizinhos viam isso como excentricidade, a família como obsessão inofensiva. Mas quando um jornalista da cidade perguntou o que a movia, percebeu que nunca havia pensado a respeito.", "Depois de refletir, respondeu que não era a natação em si. Eram os primeiros trinta segundos, em que o frio chocava seu corpo para uma atenção total e toda ansiedade que carregava se dissolvia num único objetivo simples: avançar. No resto da travessia, contou, a mente vagava por coisas comuns, mas aqueles trinta segundos eram dela.", "O jornalista, que corria maratonas e se imaginava um conhecedor da disciplina, ficou surpreso com a ausência de ambição no relato dela. Nunca competira, nunca contara recordes, nunca cronometrara. \"Se eu medir\", disse, \"vira trabalho.\" Ele anotou a frase e a sublinhou.", "Mais tarde, junto à água, contemplou a possibilidade de que o que chamava de disciplina fosse na verdade uma negociação com o medo da ociosidade. O lago jazia calmo e indiferente. Marit entrou, como fazia há duas décadas, e o frio, mais uma vez, reorganizou seus pensamentos."], "hard_words": ["obsession", "dissolved", "connoisseur", "idleness"], "vocab": [{"word": "eccentricity", "meaning": "excentricidade", "note": ""}, {"word": "obsession", "meaning": "obsessão", "note": ""}, {"word": "dissolved", "meaning": "dissolveu", "note": ""}, {"word": "objective", "meaning": "objetivo", "note": ""}, {"word": "connoisseur", "meaning": "conhecedor", "note": ""}, {"word": "idleness", "meaning": "ociosidade", "note": ""}, {"word": "contemplated", "meaning": "contemplou", "note": ""}, {"word": "rearranged", "meaning": "reorganizou", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "were"], "irregular": ["had", "asked", "saw", "drove", "realised", "thought", "answered", "shocked", "carried", "dissolved", "told", "wandered", "ran", "imagined", "surprised", "competed", "counted", "timed", "said", "wrote", "underlined", "contemplated", "lay", "stepped", "rearranged"], "phrasal": ["stepped into"], "wh": ["who", "what", "when", "why"], "connectors": ["and", "but", "after", "when", "once", "if", "as"], "comparative": []}, "word_meanings": [{"word": "eccentricity", "meaning": "excentricidade", "note": ""}, {"word": "obsession", "meaning": "obsessão", "note": ""}, {"word": "dissolved", "meaning": "dissolveu", "note": ""}, {"word": "objective", "meaning": "objetivo", "note": ""}, {"word": "connoisseur", "meaning": "conhecedor", "note": ""}, {"word": "idleness", "meaning": "ociosidade", "note": ""}, {"word": "contemplated", "meaning": "contemplou", "note": ""}, {"word": "rearranged", "meaning": "reorganizou", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect continuous", "explanation_pt": "'had been swimming for twenty-two years' mostra duração anterior."}, {"point": "It was not... It was", "explanation_pt": "'It was not the swim itself. It was the first thirty seconds' esclarece por contraste."}], "multiple_choice": [{"question": "How long had Marit swum?", "options": ["Five years", "Ten years", "Two years", "Twenty-two years"], "correct_index": 3, "explanation": "Vinte e dois anos."}, {"question": "What mattered to her?", "options": ["The first thirty seconds", "The distance", "The time", "The record"], "correct_index": 0, "explanation": "Os primeiros trinta segundos."}, {"question": "Why does she not measure it?", "options": ["It would become a job", "She swims slowly", "She forgets", "She has no watch"], "correct_index": 0, "explanation": "Viraria trabalho."}, {"question": "What did the journalist think about?", "options": ["Her speed", "His discipline might be fear of idleness", "Her family", "Her age"], "correct_index": 1, "explanation": "Que sua disciplina podia ser medo de ociosidade."}, {"question": "How does the story end?", "options": ["She drowned", "She left", "She won", "The cold rearranged her thoughts"], "correct_index": 3, "explanation": "O frio reorganizou seus pensamentos."}], "open_questions": [{"question": "Is exercise more valuable when unmeasured?", "key_points_pt": ["debater"]}, {"question": "What routine gives you mental clarity?", "key_points_pt": ["descrever"]}]}}, {"level": "C1", "genre": "sports", "title": "The Last Match of the Veteran", "paragraphs": ["At thirty-nine, Rafael Medina was the oldest player in the league, a fact that the sports press mentioned with a mixture of reverence and condescension. His knees complained, his sprints had lost their ferocity, and younger rivals smiled politely when he congratulated them. Everyone assumed this season would be his last, though he had not said so.", "In the final match, with the score level and extra time approaching, the coach substituted him on, a gesture that seemed more ceremonial than tactical. Rafael recognised this and felt no bitterness. He had learned, over decades, to read the game in a way that no stopwatch could measure: a slight hesitation in a defender's step, the angle of a pass before it was made.", "In the ninety-fourth minute, he did not run. He walked, almost lazily, into an empty space that nobody had thought to guard, and the ball arrived exactly where he stood. His touch was soft, his finish unhurried. The stadium, which had been murmuring with premature nostalgia, erupted with astonished delight.", "In the interviews afterward, he refused to dramatise. \"Younger players have legs,\" he said. \"I have patience. It turns out that's a kind of speed.\" He retired that summer, not out of failure but at the exact moment when his departure would be remembered as a choice."], "paragraphs_pt": ["Aos trinta e nove, Rafael Medina era o jogador mais velho da liga, fato que a imprensa esportiva mencionava com uma mistura de reverência e condescendência. Os joelhos reclamavam, os sprints perderam a ferocidade e os rivais mais jovens sorriam educadamente quando ele os cumprimentava. Todos presumiam que esta seria sua última temporada, embora ele não o tivesse dito.", "Na última partida, com o placar empatado e a prorrogação se aproximando, o técnico o colocou em campo, gesto que parecia mais cerimonial que tático. Rafael percebeu e não sentiu amargura. Aprendera, ao longo de décadas, a ler o jogo de um modo que nenhum cronômetro mede: uma leve hesitação no passo de um zagueiro, o ângulo de um passe antes de ser feito.", "No minuto noventa e quatro, não correu. Caminhou, quase preguiçosamente, para um espaço vazio que ninguém pensara em marcar, e a bola chegou exatamente onde ele estava. O toque foi suave, a finalização, sem pressa. O estádio, que murmurava com nostalgia prematura, explodiu em deleite atônito.", "Nas entrevistas depois, recusou-se a dramatizar. \"Os jovens têm pernas\", disse. \"Eu tenho paciência. Acontece que isso é um tipo de velocidade.\" Aposentou-se naquele verão, não por fracasso, mas no momento exato em que sua saída seria lembrada como uma escolha."], "hard_words": ["condescension", "ferocity", "premature", "astonished"], "vocab": [{"word": "reverence", "meaning": "reverência", "note": ""}, {"word": "condescension", "meaning": "condescendência", "note": ""}, {"word": "ferocity", "meaning": "ferocidade", "note": ""}, {"word": "substituted", "meaning": "colocou em campo", "note": ""}, {"word": "ceremonial", "meaning": "cerimonial", "note": ""}, {"word": "premature", "meaning": "prematura", "note": ""}, {"word": "astonished", "meaning": "atônito", "note": ""}, {"word": "dramatise", "meaning": "dramatizar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "been"], "irregular": ["mentioned", "complained", "had", "lost", "smiled", "congratulated", "assumed", "would", "said", "substituted", "seemed", "recognised", "felt", "learned", "could", "made", "did", "walked", "thought", "arrived", "stood", "erupted", "astonished", "refused", "retired", "remembered"], "phrasal": [], "wh": ["where", "when", "which"], "connectors": ["and", "but", "so", "though", "before", "when", "as"], "comparative": []}, "word_meanings": [{"word": "reverence", "meaning": "reverência", "note": ""}, {"word": "condescension", "meaning": "condescendência", "note": ""}, {"word": "ferocity", "meaning": "ferocidade", "note": ""}, {"word": "substituted", "meaning": "colocou em campo", "note": ""}, {"word": "ceremonial", "meaning": "cerimonial", "note": ""}, {"word": "premature", "meaning": "prematura", "note": ""}, {"word": "astonished", "meaning": "atônito", "note": ""}, {"word": "dramatise", "meaning": "dramatizar", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'He had learned to read the game' mostra um aprendizado anterior."}, {"point": "Not out of... but", "explanation_pt": "'not out of failure but at the exact moment' contrasta motivos."}], "multiple_choice": [{"question": "How old was Rafael?", "options": ["Thirty", "Thirty-nine", "Twenty-nine", "Forty-nine"], "correct_index": 1, "explanation": "Trinta e nove."}, {"question": "Why was he substituted on?", "options": ["A tactic", "A ceremonial gesture", "An injury", "A punishment"], "correct_index": 1, "explanation": "Gesto cerimonial."}, {"question": "What did he do in the ninety-fourth minute?", "options": ["Walked into an empty space", "Left", "Sprinted", "Fell"], "correct_index": 0, "explanation": "Caminhou ao espaço vazio."}, {"question": "What did he say about patience?", "options": ["It's useless", "It's boring", "It's rare", "It's a kind of speed"], "correct_index": 3, "explanation": "Um tipo de velocidade."}, {"question": "Why did he retire?", "options": ["After an injury", "After a defeat", "At a moment that looked like a choice", "Due to age rules"], "correct_index": 2, "explanation": "Num momento que pareceu escolha."}], "open_questions": [{"question": "Is experience better than physical strength?", "key_points_pt": ["debater"]}, {"question": "When is the right time to leave?", "key_points_pt": ["discutir"]}]}}, {"level": "C1", "genre": "sports", "title": "A Different Kind of Finish Line", "paragraphs": ["The village race had been run each August for over a century, and its prize was a ceramic jug of no particular value. Ewan, who had grown up watching it from his grandfather's shoulders, entered it for the first time at forty-four, having decided that if he did not do it now he would eventually do it only in memory. He trained furtively at dawn, embarrassed by his own ambition.", "On race day, he found himself running beside an elderly man, evidently well over seventy, who ran in an unhurried shuffle that Ewan initially mistook for weakness. They exchanged a few breathless remarks about the heat. After the second hill, Ewan realised that the old man had a rhythm he could not match, and he drifted behind.", "At the finish, he arrived twenty-ninth, a placing he would have found humiliating at twenty. Yet as he caught his breath, he felt an unexpected gladness. The elderly man, who had won his age category for the thirtieth time, handed him a cup of water and said, \"The race isn't against them, you know. It's against the version of you who stayed at home.\"", "Ewan kept the cup, a cheap thing of paper, on his desk for years. When colleagues asked, he told them it was his trophy. It was, he would add, the only prize he had ever won that nobody else could be awarded."], "paragraphs_pt": ["A corrida da aldeia era disputada todo agosto havia mais de um século, e seu prêmio era um jarro de cerâmica sem valor particular. Ewan, que crescera vendo-a dos ombros do avô, inscreveu-se pela primeira vez aos quarenta e quatro, decidido de que, se não o fizesse agora, o faria apenas em memória. Treinava furtivamente ao amanhecer, envergonhado da própria ambição.", "No dia da corrida, viu-se correndo ao lado de um idoso, evidentemente com bem mais de setenta, que corria num arrastar despreocupado que Ewan a princípio tomou por fraqueza. Trocaram algumas observações ofegantes sobre o calor. Depois da segunda colina, Ewan percebeu que o velho tinha um ritmo que ele não conseguia acompanhar, e ficou para trás.", "Na chegada, foi o vigésimo nono, colocação que teria achado humilhante aos vinte. Mas ao recuperar o fôlego, sentiu uma alegria inesperada. O idoso, que vencera sua categoria de idade pela trigésima vez, entregou-lhe um copo de água e disse: \"A corrida não é contra eles, sabe. É contra a versão de você que ficou em casa.\"", "Ewan guardou o copo, uma coisa barata de papel, sobre a mesa por anos. Quando colegas perguntavam, dizia que era seu troféu. Era, acrescentava, o único prêmio que ganhara e que ninguém mais poderia receber."], "hard_words": ["furtively", "unhurried", "humiliating", "gladness"], "vocab": [{"word": "ceramic", "meaning": "cerâmica", "note": ""}, {"word": "furtively", "meaning": "furtivamente", "note": ""}, {"word": "unhurried", "meaning": "sem pressa", "note": ""}, {"word": "shuffle", "meaning": "arrastar", "note": ""}, {"word": "breathless", "meaning": "ofegantes", "note": ""}, {"word": "humiliating", "meaning": "humilhante", "note": ""}, {"word": "gladness", "meaning": "alegria", "note": ""}, {"word": "trophy", "meaning": "troféu", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "be"], "irregular": ["had", "grown", "entered", "decided", "did", "would", "trained", "embarrassed", "found", "ran", "mistook", "exchanged", "realised", "could", "drifted", "arrived", "caught", "felt", "won", "handed", "said", "stayed", "kept", "asked", "told", "awarded"], "phrasal": ["drifted behind", "caught his breath"], "wh": ["who", "when"], "connectors": ["and", "after", "when", "yet", "if", "as"], "comparative": []}, "word_meanings": [{"word": "ceramic", "meaning": "cerâmica", "note": ""}, {"word": "furtively", "meaning": "furtivamente", "note": ""}, {"word": "unhurried", "meaning": "sem pressa", "note": ""}, {"word": "shuffle", "meaning": "arrastar", "note": ""}, {"word": "breathless", "meaning": "ofegantes", "note": ""}, {"word": "humiliating", "meaning": "humilhante", "note": ""}, {"word": "gladness", "meaning": "alegria", "note": ""}, {"word": "trophy", "meaning": "troféu", "note": ""}], "exercises": {"grammar": [{"point": "Having + particípio", "explanation_pt": "'having decided that if he did not do it now' indica motivo anterior."}, {"point": "Would have + particípio", "explanation_pt": "'would have found humiliating at twenty' compara com outra época."}], "multiple_choice": [{"question": "What was the prize?", "options": ["A ceramic jug", "A trip", "Money", "A medal"], "correct_index": 0, "explanation": "Um jarro de cerâmica."}, {"question": "When did Ewan enter?", "options": ["At forty-four", "At sixty", "At twenty", "At ten"], "correct_index": 0, "explanation": "Aos quarenta e quatro."}, {"question": "Who did he run beside?", "options": ["An elderly man", "A child", "A friend", "His grandfather"], "correct_index": 0, "explanation": "Um idoso."}, {"question": "Where did Ewan finish?", "options": ["First", "Last", "Second", "Twenty-ninth"], "correct_index": 3, "explanation": "Vigésimo nono."}, {"question": "What did the old man say?", "options": ["Train harder", "The race is against the version of you who stayed at home", "You lost", "You are slow"], "correct_index": 1, "explanation": "Contra a versão que ficou em casa."}], "open_questions": [{"question": "What makes small races meaningful?", "key_points_pt": ["discutir"]}, {"question": "What goal would you have been embarrassed to admit?", "key_points_pt": ["refletir"]}]}}, {"level": "C2", "genre": "sports", "title": "The Geometry of a Free Kick", "paragraphs": ["Among the rituals of association football, none is more theatrical than the free kick: eleven men assemble in a wall, one man steps back, and for several seconds the stadium enters a collective suspension of breath. Iván Paredes had taken more than six hundred in his career, and he claimed that each one still produced the same fluttering in his stomach. He considered this the proof that he had not become a mere technician.", "Between Paredes and the goal lay a space that could be described, with sufficient pretension, as geometry. The wall, the keeper's position, the curvature he would impart to the ball, the wind that nobody could model: all of these converged into a decision he took in a second but had rehearsed in ten thousand hours. Critics, who analysed footage in slow motion, forgot that the footballer experiences it as a feeling, not a calculation.", "On the evening of the final, he stepped back, closed his eyes for an instant and ran. The ball rose over the wall, hung against the floodlights and, at the last moment, dipped, brushing the underside of the crossbar. The keeper, who had read everything correctly, was beaten by a physics he could not have anticipated.", "In his retirement, Paredes was asked whether the kick had been skill or luck. He smiled with the courtesy of a man who had answered the question thousands of times. \"It was the distance between the two,\" he said. \"Skill is the work you do so that luck knows where to find you.\""], "paragraphs_pt": ["Entre os rituais do futebol, nenhum é mais teatral que a falta: onze homens se reúnem numa barreira, um homem recua e por alguns segundos o estádio entra numa suspensão coletiva da respiração. Iván Paredes batera mais de seiscentas na carreira e afirmava que cada uma ainda produzia o mesmo frio no estômago. Considerava isso a prova de que não se tornara um mero técnico.", "Entre Paredes e o gol havia um espaço que se poderia descrever, com pretensão suficiente, como geometria. A barreira, a posição do goleiro, a curvatura que imprimiria à bola, o vento que ninguém podia modelar: tudo convergia numa decisão tomada em um segundo, mas ensaiada em dez mil horas. Os críticos, que analisavam as imagens em câmera lenta, esqueciam que o jogador a vive como sentimento, não como cálculo.", "Na noite da final, recuou, fechou os olhos por um instante e correu. A bola subiu sobre a barreira, pairou contra os refletores e, no último momento, caiu, roçando a parte inferior do travessão. O goleiro, que lera tudo corretamente, foi batido por uma física que não poderia ter antecipado.", "Na aposentadoria, perguntaram a Paredes se o chute fora habilidade ou sorte. Ele sorriu com a cortesia de quem respondera à pergunta milhares de vezes. \"Foi a distância entre as duas\", disse. \"Habilidade é o trabalho que você faz para que a sorte saiba onde encontrá-lo.\""], "hard_words": ["theatrical", "curvature", "converged", "crossbar"], "vocab": [{"word": "theatrical", "meaning": "teatral", "note": ""}, {"word": "wall", "meaning": "barreira", "note": ""}, {"word": "fluttering", "meaning": "frio na barriga", "note": ""}, {"word": "curvature", "meaning": "curvatura", "note": ""}, {"word": "converged", "meaning": "convergiam", "note": ""}, {"word": "rehearsed", "meaning": "ensaiada", "note": ""}, {"word": "floodlights", "meaning": "refletores", "note": ""}, {"word": "crossbar", "meaning": "travessão", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "be", "was", "been"], "irregular": ["had", "taken", "claimed", "produced", "considered", "lay", "could", "described", "would", "converged", "took", "rehearsed", "analysed", "forgot", "stepped", "closed", "ran", "rose", "hung", "dipped", "beaten", "anticipated", "asked", "smiled", "answered", "said"], "phrasal": [], "wh": ["who", "where"], "connectors": ["so that", "and", "but", "so", "or", "still", "as"], "comparative": []}, "word_meanings": [{"word": "theatrical", "meaning": "teatral", "note": ""}, {"word": "wall", "meaning": "barreira", "note": ""}, {"word": "fluttering", "meaning": "frio na barriga", "note": ""}, {"word": "curvature", "meaning": "curvatura", "note": ""}, {"word": "converged", "meaning": "convergiam", "note": ""}, {"word": "rehearsed", "meaning": "ensaiada", "note": ""}, {"word": "floodlights", "meaning": "refletores", "note": ""}, {"word": "crossbar", "meaning": "travessão", "note": ""}], "exercises": {"grammar": [{"point": "Not a... but", "explanation_pt": "'not a calculation' diz o que a experiência não é."}, {"point": "Sufficient + substantivo", "explanation_pt": "'with sufficient pretension' significa pretensão suficiente."}], "multiple_choice": [{"question": "What is the free kick compared to?", "options": ["A race", "A battle", "A theatrical ritual", "A game of chess"], "correct_index": 2, "explanation": "Um ritual teatral."}, {"question": "How many free kicks had Paredes taken?", "options": ["More than six hundred", "A few", "Six thousand", "Sixty"], "correct_index": 0, "explanation": "Mais de seiscentas."}, {"question": "What did the ball do?", "options": ["Hit the wall", "Rose over the wall and dipped under the crossbar", "Missed", "Stopped"], "correct_index": 1, "explanation": "Subiu e caiu sob o travessão."}, {"question": "Why was the keeper beaten?", "options": ["By unforeseen physics", "By a foul", "By luck only", "By a mistake"], "correct_index": 0, "explanation": "Por uma física imprevista."}, {"question": "What is skill, according to Paredes?", "options": ["Speed", "Talent", "Pure luck", "The work that lets luck find you"], "correct_index": 3, "explanation": "O trabalho para a sorte te achar."}], "open_questions": [{"question": "What is the relationship between luck and skill?", "key_points_pt": ["discutir"]}, {"question": "Why do experts forget feeling in analysis?", "key_points_pt": ["refletir"]}]}}, {"level": "C2", "genre": "sports", "title": "The Silence of the Stadium", "paragraphs": ["When the stadium, at the height of the match, fell silent for ninety seconds in tribute to a fallen former player, the effect on the athletes was strangely disorienting. For the first time all evening, they could hear their own breathing, the squeak of boots on the grass, the distant clatter of a flag in the wind. The match, with its rivalry and urgency, suddenly seemed a fragile construction of agreed fictions.", "Marcus Hale, the goalkeeper, found himself staring at the opposing striker, a man he had spent the afternoon trying to demolish with every legal and semi-legal means. In the silence, he noticed the striker's tired eyes and the black armband on his sleeve, identical to his own. Hostility, he realised, was a language that required an audience to remain fluent.", "The whistle resumed play, and the noise returned like a tide. Yet something had shifted. The tackles were as hard as before, but the contempt had gone out of them, and when Hale made a decisive save in the final minutes, the striker applauded, briefly and almost against his will.", "Afterward, journalists wrote about the result and the tactics, as they inevitably do. Only a few mentioned those ninety seconds. Hale never discussed them, but years later, coaching boys on a muddy pitch, he would sometimes stop practice, ask everyone to be silent, and let them listen to what the game sounded like without its audience."], "paragraphs_pt": ["Quando o estádio, no auge da partida, ficou em silêncio por noventa segundos em homenagem a um ex-jogador falecido, o efeito sobre os atletas foi estranhamente desorientador. Pela primeira vez na noite, ouviam a própria respiração, o ranger das chuteiras no gramado, o tilintar distante de uma bandeira ao vento. A partida, com sua rivalidade e urgência, de repente parecia uma construção frágil de ficções acordadas.", "Marcus Hale, o goleiro, viu-se encarando o atacante adversário, homem que passara a tarde tentando demolir por todos os meios legais e semilegais. No silêncio, notou os olhos cansados do atacante e a braçadeira preta na manga, idêntica à sua. A hostilidade, percebeu, era uma língua que exigia plateia para permanecer fluente.", "O apito retomou o jogo e o barulho voltou como uma maré. Mas algo mudara. As entradas eram duras como antes, mas o desprezo se fora delas, e quando Hale fez uma defesa decisiva nos minutos finais, o atacante aplaudiu, brevemente e quase contra a vontade.", "Depois, os jornalistas escreveram sobre o resultado e a tática, como inevitavelmente fazem. Poucos mencionaram aqueles noventa segundos. Hale nunca falou deles, mas anos depois, treinando meninos num campo lamacento, às vezes parava o treino, pedia silêncio a todos e os deixava ouvir como soava o jogo sem a plateia."], "hard_words": ["disorienting", "hostility", "contempt", "armband"], "vocab": [{"word": "tribute", "meaning": "homenagem", "note": ""}, {"word": "disorienting", "meaning": "desorientador", "note": ""}, {"word": "clatter", "meaning": "tilintar", "note": ""}, {"word": "demolish", "meaning": "demolir", "note": ""}, {"word": "armband", "meaning": "braçadeira", "note": ""}, {"word": "hostility", "meaning": "hostilidade", "note": ""}, {"word": "contempt", "meaning": "desprezo", "note": ""}, {"word": "pitch", "meaning": "campo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "be"], "irregular": ["fell", "fallen", "could", "seemed", "agreed", "found", "had", "spent", "noticed", "tired", "realised", "required", "resumed", "returned", "shifted", "gone", "made", "applauded", "wrote", "mentioned", "discussed", "would", "sounded"], "phrasal": ["fell silent", "gone out of"], "wh": ["what", "when"], "connectors": ["and", "but", "before", "when", "yet", "suddenly", "as"], "comparative": []}, "word_meanings": [{"word": "tribute", "meaning": "homenagem", "note": ""}, {"word": "disorienting", "meaning": "desorientador", "note": ""}, {"word": "clatter", "meaning": "tilintar", "note": ""}, {"word": "demolish", "meaning": "demolir", "note": ""}, {"word": "armband", "meaning": "braçadeira", "note": ""}, {"word": "hostility", "meaning": "hostilidade", "note": ""}, {"word": "contempt", "meaning": "desprezo", "note": ""}, {"word": "pitch", "meaning": "campo", "note": ""}], "exercises": {"grammar": [{"point": "Had spent + ing", "explanation_pt": "'a man he had spent the afternoon trying to demolish' mostra contexto anterior."}, {"point": "Hostility as a language", "explanation_pt": "metáfora: 'Hostility was a language that required an audience' compara hostilidade a uma língua."}], "multiple_choice": [{"question": "Why was the stadium silent?", "options": ["A protest", "A tribute to a fallen former player", "A power cut", "A rule"], "correct_index": 1, "explanation": "Homenagem a ex-jogador."}, {"question": "What did the athletes hear?", "options": ["Their own breathing", "A siren", "A speech", "A song"], "correct_index": 0, "explanation": "A própria respiração."}, {"question": "What did Hale notice about the striker?", "options": ["His smile", "His boots", "His tired eyes and armband", "His anger"], "correct_index": 2, "explanation": "Olhos cansados e braçadeira."}, {"question": "What changed after the silence?", "options": ["The score", "The weather", "The referee", "The contempt left the tackles"], "correct_index": 3, "explanation": "O desprezo saiu das entradas."}, {"question": "What does Hale do years later?", "options": ["Shows videos", "Gives speeches", "Argues", "Asks boys for silence to listen to the game"], "correct_index": 3, "explanation": "Pede silêncio aos meninos."}], "open_questions": [{"question": "Does rivalry need an audience?", "key_points_pt": ["debater"]}, {"question": "How can silence change how we see others?", "key_points_pt": ["explicar"]}]}}, {"level": "C2", "genre": "sports", "title": "The Weight of a Gold Medal", "paragraphs": ["Nobody had warned Ilse that the most difficult day of her athletic life would be the one after the Olympic final. For eleven years she had organised every hour around a single objective, and when she stood on the podium, the anthem rising over a stadium of strangers, she waited for the sense of fulfilment that the myth had promised. It did not arrive. In its place came a stillness so complete that it frightened her.", "The following weeks were an exercise in disorientation. Sponsors called, journalists enquired, and her village erected an arch in her honour, yet she woke each morning with nothing to train for. The body that had been tuned like an instrument had no more music to play. She discovered that victory is a kind of bereavement: one loses the version of oneself that was still striving.", "It was an unexpected correspondent, a girl of ten from a rural school, who offered a way through. The child wrote, in a careful hand, to ask whether the medal was heavy. Ilse sat for a long time over the letter before replying that it weighed about as much as a plum, and that the real weight lay in what one chose to carry afterward.", "She began to coach children without ambitions of becoming champions, teaching them to swim for the pleasure of the water. Years later, a former pupil asked what she had won, and Ilse answered without a trace of irony: \"The ability to be happy in a pool where nobody is counting.\""], "paragraphs_pt": ["Ninguém avisara Ilse de que o dia mais difícil de sua vida atlética seria o seguinte à final olímpica. Por onze anos organizara cada hora em torno de um único objetivo e, quando subiu ao pódio, com o hino elevando-se sobre um estádio de estranhos, esperou o sentimento de realização que o mito prometera. Não veio. Em seu lugar veio uma quietude tão completa que a assustou.", "As semanas seguintes foram um exercício de desorientação. Patrocinadores ligavam, jornalistas indagavam e a aldeia ergueu um arco em sua honra, mas ela acordava toda manhã sem nada para treinar. O corpo que fora afinado como um instrumento já não tinha música para tocar. Descobriu que a vitória é uma espécie de luto: perde-se a versão de si que ainda se esforçava.", "Foi uma correspondente inesperada, uma menina de dez anos de uma escola rural, que ofereceu uma saída. A criança escreveu, em letra cuidadosa, perguntando se a medalha era pesada. Ilse ficou muito tempo sobre a carta antes de responder que pesava mais ou menos como uma ameixa e que o verdadeiro peso estava no que se escolhia carregar depois.", "Começou a treinar crianças sem ambições de se tornarem campeãs, ensinando-as a nadar pelo prazer da água. Anos depois, uma ex-aluna perguntou o que ela havia ganhado, e Ilse respondeu sem vestígio de ironia: \"A capacidade de ser feliz numa piscina onde ninguém está contando.\""], "hard_words": ["fulfilment", "bereavement", "striving", "erected"], "vocab": [{"word": "podium", "meaning": "pódio", "note": ""}, {"word": "anthem", "meaning": "hino", "note": ""}, {"word": "fulfilment", "meaning": "realização", "note": ""}, {"word": "stillness", "meaning": "quietude", "note": ""}, {"word": "erected", "meaning": "ergueu", "note": ""}, {"word": "bereavement", "meaning": "luto", "note": ""}, {"word": "striving", "meaning": "esforçando-se", "note": ""}, {"word": "plum", "meaning": "ameixa", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["be", "were", "been", "is", "was"], "irregular": ["had", "warned", "would", "organised", "stood", "waited", "promised", "did", "came", "frightened", "called", "enquired", "erected", "woke", "tuned", "discovered", "offered", "wrote", "sat", "weighed", "lay", "chose", "began", "asked", "won", "answered"], "phrasal": [], "wh": ["who", "what", "where", "when"], "connectors": ["and", "so", "after", "before", "when", "yet", "still", "as"], "comparative": []}, "word_meanings": [{"word": "podium", "meaning": "pódio", "note": ""}, {"word": "anthem", "meaning": "hino", "note": ""}, {"word": "fulfilment", "meaning": "realização", "note": ""}, {"word": "stillness", "meaning": "quietude", "note": ""}, {"word": "erected", "meaning": "ergueu", "note": ""}, {"word": "bereavement", "meaning": "luto", "note": ""}, {"word": "striving", "meaning": "esforçando-se", "note": ""}, {"word": "plum", "meaning": "ameixa", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'For eleven years she had organised every hour' mostra um período anterior."}, {"point": "In its place", "explanation_pt": "'In its place came a stillness' indica substituição."}], "multiple_choice": [{"question": "How long had Ilse trained?", "options": ["Eleven years", "Twenty years", "Five years", "One year"], "correct_index": 0, "explanation": "Onze anos."}, {"question": "How did she feel after winning?", "options": ["Stillness, not fulfilment", "Anger", "Joy", "Pride"], "correct_index": 0, "explanation": "Quietude, não realização."}, {"question": "What did the girl ask?", "options": ["Whether the medal was heavy", "Where she lived", "How to win", "For a photo"], "correct_index": 0, "explanation": "Se a medalha era pesada."}, {"question": "What did Ilse say it weighed?", "options": ["About as much as a plum", "A stone", "A kilo", "A feather"], "correct_index": 0, "explanation": "Como uma ameixa."}, {"question": "What does Ilse do later?", "options": ["Competes again", "Retires to a farm", "Coaches children to swim for pleasure", "Writes books"], "correct_index": 2, "explanation": "Treina crianças pelo prazer."}], "open_questions": [{"question": "Why can achievement feel empty?", "key_points_pt": ["discutir"]}, {"question": "What gives meaning after a big goal?", "key_points_pt": ["refletir"]}]}}, {"level": "A1", "genre": "spy", "title": "Agent Blue", "paragraphs": ["Agent Blue is a spy. He wears a black hat and dark glasses. Nobody knows his real name.", "Today he is at a café. He has a secret paper in his pocket. He drinks coffee and looks at the door.", "A woman in a red coat comes. She sits at his table. \"The weather is nice,\" she says. This is the secret word. Blue gives her the paper and goes."], "paragraphs_pt": ["O Agente Azul é um espião. Usa um chapéu preto e óculos escuros. Ninguém sabe seu nome verdadeiro.", "Hoje ele está num café. Tem um papel secreto no bolso. Toma café e olha para a porta.", "Uma mulher de casaco vermelho chega. Senta à mesa dele. \"O tempo está bom\", diz. Esta é a palavra secreta. Azul entrega o papel a ela e vai embora."], "hard_words": ["spy", "secret", "pocket", "coat"], "vocab": [{"word": "spy", "meaning": "espião", "note": ""}, {"word": "hat", "meaning": "chapéu", "note": ""}, {"word": "glasses", "meaning": "óculos", "note": ""}, {"word": "secret", "meaning": "secreto", "note": ""}, {"word": "pocket", "meaning": "bolso", "note": ""}, {"word": "coat", "meaning": "casaco", "note": ""}, {"word": "door", "meaning": "porta", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "spy", "meaning": "espião", "note": ""}, {"word": "hat", "meaning": "chapéu", "note": ""}, {"word": "glasses", "meaning": "óculos", "note": ""}, {"word": "secret", "meaning": "secreto", "note": ""}, {"word": "pocket", "meaning": "bolso", "note": ""}, {"word": "coat", "meaning": "casaco", "note": ""}, {"word": "door", "meaning": "porta", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "'He wears a black hat' descreve hábito ou aparência."}], "multiple_choice": [{"question": "Who is Agent Blue?", "options": ["A driver", "A teacher", "A spy", "A doctor"], "correct_index": 2, "explanation": "Um espião."}, {"question": "What does he wear?", "options": ["A blue tie", "A white shirt", "A red coat", "A black hat and dark glasses"], "correct_index": 3, "explanation": "Chapéu preto e óculos escuros."}, {"question": "Where is he today?", "options": ["At school", "At a shop", "At a café", "At home"], "correct_index": 2, "explanation": "Num café."}, {"question": "What does the woman wear?", "options": ["A blue hat", "A black coat", "A red coat", "A green dress"], "correct_index": 2, "explanation": "Casaco vermelho."}, {"question": "What does Blue give her?", "options": ["A phone", "A paper", "A coat", "A key"], "correct_index": 1, "explanation": "Um papel."}], "open_questions": [{"question": "Would you like to be a spy?", "key_points_pt": ["opinar"]}, {"question": "What is a secret you can tell?", "key_points_pt": ["falar"]}]}}, {"level": "A1", "genre": "spy", "title": "The Secret Door", "paragraphs": ["Ben is a young spy. He is in a big house. The house is dark and quiet. He looks at the wall.", "There is a picture of a horse. Ben moves the picture. There is a small door behind it! He opens the door.", "Inside, there is a room with a computer. Ben takes a photo of the screen. Then he closes the door and leaves. His mission is done."], "paragraphs_pt": ["Ben é um jovem espião. Está numa casa grande. A casa é escura e silenciosa. Ele olha a parede.", "Há um quadro de um cavalo. Ben move o quadro. Há uma portinha atrás! Ele abre a porta.", "Dentro há uma sala com um computador. Ben tira uma foto da tela. Depois fecha a porta e sai. Sua missão está cumprida."], "hard_words": ["wall", "horse", "screen", "mission"], "vocab": [{"word": "house", "meaning": "casa", "note": ""}, {"word": "wall", "meaning": "parede", "note": ""}, {"word": "picture", "meaning": "quadro", "note": ""}, {"word": "horse", "meaning": "cavalo", "note": ""}, {"word": "computer", "meaning": "computador", "note": ""}, {"word": "screen", "meaning": "tela", "note": ""}, {"word": "mission", "meaning": "missão", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": ["done"], "phrasal": [], "wh": [], "connectors": ["and", "then"], "comparative": []}, "word_meanings": [{"word": "house", "meaning": "casa", "note": ""}, {"word": "wall", "meaning": "parede", "note": ""}, {"word": "picture", "meaning": "quadro", "note": ""}, {"word": "horse", "meaning": "cavalo", "note": ""}, {"word": "computer", "meaning": "computador", "note": ""}, {"word": "screen", "meaning": "tela", "note": ""}, {"word": "mission", "meaning": "missão", "note": ""}], "exercises": {"grammar": [{"point": "There is", "explanation_pt": "'There is a small door' diz que algo existe."}], "multiple_choice": [{"question": "Where is Ben?", "options": ["In a park", "In a big house", "In a car", "In a school"], "correct_index": 1, "explanation": "Numa casa grande."}, {"question": "What is on the wall?", "options": ["A mirror", "A clock", "A picture of a horse", "A map"], "correct_index": 2, "explanation": "Um quadro de cavalo."}, {"question": "What is behind the picture?", "options": ["A cat", "A small door", "A window", "A key"], "correct_index": 1, "explanation": "Uma portinha."}, {"question": "What does Ben take?", "options": ["A key", "A book", "A photo of the screen", "Money"], "correct_index": 2, "explanation": "Uma foto da tela."}, {"question": "How is Ben at the end?", "options": ["He is sad", "He is caught", "He is lost", "His mission is done"], "correct_index": 3, "explanation": "A missão está cumprida."}], "open_questions": [{"question": "What secret room would you build?", "key_points_pt": ["imaginar"]}, {"question": "What do you see on your walls?", "key_points_pt": ["descrever"]}]}}, {"level": "A1", "genre": "spy", "title": "The Message in the Book", "paragraphs": ["Lisa goes to the library. She wants a book about birds. She finds it on a high shelf.", "Inside the book, there is a small paper. It says: \"Meet me at the park at six.\" Lisa is surprised. She reads it again. Who writes this?", "At six, Lisa goes to the park. An old man sits on a bench. \"Excuse me,\" says Lisa. \"Is this paper yours?\" He laughs. \"Yes, it is a note for my friend. Thank you!\""], "paragraphs_pt": ["Lisa vai à biblioteca. Quer um livro sobre pássaros. Encontra-o numa prateleira alta.", "Dentro do livro há um papelzinho. Diz: \"Encontre-me no parque às seis.\" Lisa fica surpresa. Lê de novo. Quem escreve isso?", "Às seis, Lisa vai ao parque. Um velho está sentado num banco. \"Com licença\", diz Lisa. \"Este papel é seu?\" Ele ri. \"Sim, é um bilhete para meu amigo. Obrigado!\""], "hard_words": ["library", "shelf", "bench", "note"], "vocab": [{"word": "library", "meaning": "biblioteca", "note": ""}, {"word": "shelf", "meaning": "prateleira", "note": ""}, {"word": "inside", "meaning": "dentro", "note": ""}, {"word": "paper", "meaning": "papel", "note": ""}, {"word": "park", "meaning": "parque", "note": ""}, {"word": "bench", "meaning": "banco", "note": ""}, {"word": "note", "meaning": "bilhete", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": ["surprised"], "phrasal": [], "wh": ["who"], "connectors": [], "comparative": []}, "word_meanings": [{"word": "library", "meaning": "biblioteca", "note": ""}, {"word": "shelf", "meaning": "prateleira", "note": ""}, {"word": "inside", "meaning": "dentro", "note": ""}, {"word": "paper", "meaning": "papel", "note": ""}, {"word": "park", "meaning": "parque", "note": ""}, {"word": "bench", "meaning": "banco", "note": ""}, {"word": "note", "meaning": "bilhete", "note": ""}], "exercises": {"grammar": [{"point": "Questions", "explanation_pt": "'Who writes this?' e 'Is this paper yours?' mostram perguntas com who e is."}], "multiple_choice": [{"question": "Where does Lisa go?", "options": ["To school", "To a shop", "To the library", "To a bank"], "correct_index": 2, "explanation": "À biblioteca."}, {"question": "What does she want?", "options": ["A map", "A cake", "A pen", "A book about birds"], "correct_index": 3, "explanation": "Um livro sobre pássaros."}, {"question": "What is inside the book?", "options": ["A key", "A small paper", "A photo", "Money"], "correct_index": 1, "explanation": "Um papelzinho."}, {"question": "Where does the note say to meet?", "options": ["At the park", "At home", "At school", "At a cafe"], "correct_index": 0, "explanation": "No parque."}, {"question": "Who wrote the note?", "options": ["A teacher", "A spy", "A child", "An old man"], "correct_index": 3, "explanation": "Um velho."}], "open_questions": [{"question": "Do you use libraries?", "key_points_pt": ["falar"]}, {"question": "What is the most interesting note you found?", "key_points_pt": ["contar"]}]}}, {"level": "A2", "genre": "spy", "title": "The Perfect Disguise", "paragraphs": ["Agent Lena had a difficult mission in Paris. She had to enter a famous hotel and find a small black case in room 304. The problem was that a man at the front door checked everybody who entered.", "She decided to use a disguise. She put on a grey uniform, a pair of glasses and a white cap, and carried a basket of clean towels. At the door, she smiled at the man. \"Good morning,\" she said. \"Laundry service.\" He did not even look at her face.", "In room 304, she found the black case under the bed. She put it in the basket between the towels and walked calmly out of the hotel. Outside, a taxi was waiting. \"Mission complete,\" she whispered. For Lena, the best disguise was to look like someone nobody notices."], "paragraphs_pt": ["A agente Lena tinha uma missão difícil em Paris. Precisava entrar num hotel famoso e achar uma pequena maleta preta no quarto 304. O problema era que um homem na porta da frente verificava todos que entravam.", "Decidiu usar um disfarce. Vestiu um uniforme cinza, óculos e um boné branco e levou uma cesta de toalhas limpas. Na porta, sorriu ao homem. \"Bom dia\", disse. \"Serviço de lavanderia.\" Ele nem olhou o rosto dela.", "No quarto 304, achou a maleta preta sob a cama. Colocou-a na cesta entre as toalhas e saiu calmamente do hotel. Do lado de fora, um táxi esperava. \"Missão cumprida\", sussurrou. Para Lena, o melhor disfarce era parecer alguém que ninguém nota."], "hard_words": ["mission", "disguise", "uniform", "towels"], "vocab": [{"word": "mission", "meaning": "missão", "note": ""}, {"word": "disguise", "meaning": "disfarce", "note": ""}, {"word": "case", "meaning": "maleta", "note": ""}, {"word": "uniform", "meaning": "uniforme", "note": ""}, {"word": "cap", "meaning": "boné", "note": ""}, {"word": "basket", "meaning": "cesta", "note": ""}, {"word": "towels", "meaning": "toalhas", "note": ""}, {"word": "laundry", "meaning": "lavanderia", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["had", "checked", "entered", "decided", "carried", "smiled", "said", "did", "found", "walked", "whispered"], "phrasal": ["put on"], "wh": ["who"], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "mission", "meaning": "missão", "note": ""}, {"word": "disguise", "meaning": "disfarce", "note": ""}, {"word": "case", "meaning": "maleta", "note": ""}, {"word": "uniform", "meaning": "uniforme", "note": ""}, {"word": "cap", "meaning": "boné", "note": ""}, {"word": "basket", "meaning": "cesta", "note": ""}, {"word": "towels", "meaning": "toalhas", "note": ""}, {"word": "laundry", "meaning": "lavanderia", "note": ""}], "exercises": {"grammar": [{"point": "Had to", "explanation_pt": "'She had to enter a famous hotel' expressa obrigação no passado."}, {"point": "Past simple", "explanation_pt": "'decided', 'found', 'whispered' contam a sequência."}], "multiple_choice": [{"question": "Where was the mission?", "options": ["In Lisbon", "In Rome", "In London", "In Paris"], "correct_index": 3, "explanation": "Em Paris."}, {"question": "What did Lena need to find?", "options": ["A map", "A phone", "A key", "A black case"], "correct_index": 3, "explanation": "Uma maleta preta."}, {"question": "What was her disguise?", "options": ["A laundry worker", "A guest", "A chef", "A doctor"], "correct_index": 0, "explanation": "Funcionária de lavanderia."}, {"question": "Where was the case?", "options": ["On the table", "In the wardrobe", "Under the bed", "In a drawer"], "correct_index": 2, "explanation": "Sob a cama."}, {"question": "What is the best disguise, for Lena?", "options": ["Looking rich", "Looking angry", "Looking like someone nobody notices", "Looking famous"], "correct_index": 2, "explanation": "Parecer alguém que ninguém nota."}], "open_questions": [{"question": "What disguise would you use?", "key_points_pt": ["imaginar"]}, {"question": "Why do people trust uniforms?", "key_points_pt": ["explicar"]}]}}, {"level": "A2", "genre": "spy", "title": "Code Words", "paragraphs": ["Agent Marco and Agent Dana never used the phone. They communicated with code words in the newspaper. When Marco wanted to meet, he put an advertisement: \"Red bicycle for sale.\" Dana read it and went to the old fountain at five.", "One morning, Dana saw a strange advertisement: \"Green umbrella for sale.\" They had never used those words. She thought: \"It is a trap.\" Instead of going to the fountain, she went to a quiet street behind it and watched from a window.", "At five o'clock, a man in a long coat arrived at the fountain. He was not Marco. He looked around nervously and checked his watch. Dana took a photo and called the chief. A few hours later, the police arrested the stranger. Marco was safe, and Dana had saved him."], "paragraphs_pt": ["O agente Marco e a agente Dana nunca usavam o telefone. Comunicavam-se por palavras-código no jornal. Quando Marco queria encontrar-se, publicava um anúncio: \"Bicicleta vermelha à venda.\" Dana lia e ia à velha fonte às cinco.", "Uma manhã, Dana viu um anúncio estranho: \"Guarda-chuva verde à venda.\" Nunca haviam usado aquelas palavras. Pensou: \"É uma armadilha.\" Em vez de ir à fonte, foi a uma rua tranquila atrás dela e observou de uma janela.", "Às cinco horas, um homem de casaco longo chegou à fonte. Não era o Marco. Olhou em volta nervoso e conferiu o relógio. Dana tirou uma foto e ligou para o chefe. Poucas horas depois, a polícia prendeu o desconhecido. Marco estava a salvo, e Dana o salvara."], "hard_words": ["advertisement", "fountain", "trap", "arrested"], "vocab": [{"word": "code words", "meaning": "palavras-código", "note": ""}, {"word": "newspaper", "meaning": "jornal", "note": ""}, {"word": "advertisement", "meaning": "anúncio", "note": ""}, {"word": "fountain", "meaning": "fonte", "note": ""}, {"word": "trap", "meaning": "armadilha", "note": ""}, {"word": "nervously", "meaning": "nervoso", "note": ""}, {"word": "chief", "meaning": "chefe", "note": ""}, {"word": "arrested", "meaning": "prendeu", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was"], "irregular": ["used", "communicated", "wanted", "went", "saw", "had", "thought", "watched", "arrived", "looked", "checked", "took", "called", "arrested", "saved"], "phrasal": ["looked around", "went to"], "wh": ["when"], "connectors": ["and", "instead", "when"], "comparative": []}, "word_meanings": [{"word": "code words", "meaning": "palavras-código", "note": ""}, {"word": "newspaper", "meaning": "jornal", "note": ""}, {"word": "advertisement", "meaning": "anúncio", "note": ""}, {"word": "fountain", "meaning": "fonte", "note": ""}, {"word": "trap", "meaning": "armadilha", "note": ""}, {"word": "nervously", "meaning": "nervoso", "note": ""}, {"word": "chief", "meaning": "chefe", "note": ""}, {"word": "arrested", "meaning": "prendeu", "note": ""}], "exercises": {"grammar": [{"point": "Never used", "explanation_pt": "'had never used those words' (past perfect) mostra que antes nunca tinham usado."}, {"point": "Instead of + ing", "explanation_pt": "'Instead of going to the fountain' mostra a escolha oposta."}], "multiple_choice": [{"question": "How did Marco and Dana communicate?", "options": ["Code words in the newspaper", "By letters", "By phone", "By email"], "correct_index": 0, "explanation": "Palavras-código no jornal."}, {"question": "What did Marco's advertisement say?", "options": ["Green umbrella for sale", "Blue car for sale", "Red bicycle for sale", "Old house for sale"], "correct_index": 2, "explanation": "Bicicleta vermelha."}, {"question": "Why did Dana think it was a trap?", "options": ["The street was dark", "The words were new", "The paper was old", "The phone rang"], "correct_index": 1, "explanation": "As palavras eram novas."}, {"question": "Where did she watch from?", "options": ["The fountain", "A café", "A window behind the fountain", "A car"], "correct_index": 2, "explanation": "De uma janela."}, {"question": "What happened to the stranger?", "options": ["He met Marco", "The police arrested him", "He escaped", "He became a spy"], "correct_index": 1, "explanation": "A polícia o prendeu."}], "open_questions": [{"question": "How can you communicate secretly?", "key_points_pt": ["explicar"]}, {"question": "Have you ever suspected something strange?", "key_points_pt": ["contar"]}]}}, {"level": "A2", "genre": "spy", "title": "The Train to Vienna", "paragraphs": ["Agent Kai was on the night train to Vienna. In his bag, there was a small box with important documents. A woman at the next table kept looking at him. Kai felt uneasy, so he moved to another seat.", "The woman followed him. \"Excuse me,\" she said in a friendly voice, \"do you have the time?\" Kai answered, but he noticed her hand moving toward his bag. He grabbed it quickly and stood up. The woman smiled and left the carriage.", "Kai walked through the whole train and chose a seat next to a sleeping family. He felt safer there. In the morning, at the station in Vienna, a man in a grey coat was waiting for him. \"Do you have the box?\" \"Yes.\" \"Good. You did well.\" Kai breathed again."], "paragraphs_pt": ["O agente Kai estava no trem noturno para Viena. Na bolsa, havia uma pequena caixa com documentos importantes. Uma mulher na mesa ao lado continuava olhando para ele. Kai sentiu desconforto e mudou para outro assento.", "A mulher o seguiu. \"Com licença\", disse com voz amistosa, \"o senhor tem horas?\" Kai respondeu, mas notou a mão dela se movendo em direção à bolsa. Agarrou-a rápido e levantou-se. A mulher sorriu e saiu do vagão.", "Kai atravessou o trem todo e escolheu um assento ao lado de uma família dormindo. Sentiu-se mais seguro ali. De manhã, na estação de Viena, um homem de casaco cinza o esperava. \"Tem a caixa?\" \"Sim.\" \"Ótimo. Foi bem.\" Kai respirou de novo."], "hard_words": ["documents", "uneasy", "grabbed", "carriage"], "vocab": [{"word": "documents", "meaning": "documentos", "note": ""}, {"word": "uneasy", "meaning": "inquieto", "note": ""}, {"word": "seat", "meaning": "assento", "note": ""}, {"word": "friendly", "meaning": "amistosa", "note": ""}, {"word": "grabbed", "meaning": "agarrou", "note": ""}, {"word": "carriage", "meaning": "vagão", "note": ""}, {"word": "station", "meaning": "estação", "note": ""}, {"word": "safer", "meaning": "mais seguro", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was"], "irregular": ["kept", "felt", "moved", "followed", "said", "answered", "noticed", "grabbed", "stood", "smiled", "left", "walked", "chose", "did", "breathed"], "phrasal": ["kept looking", "stood up"], "wh": [], "connectors": ["and", "but", "so"], "comparative": []}, "word_meanings": [{"word": "documents", "meaning": "documentos", "note": ""}, {"word": "uneasy", "meaning": "inquieto", "note": ""}, {"word": "seat", "meaning": "assento", "note": ""}, {"word": "friendly", "meaning": "amistosa", "note": ""}, {"word": "grabbed", "meaning": "agarrou", "note": ""}, {"word": "carriage", "meaning": "vagão", "note": ""}, {"word": "station", "meaning": "estação", "note": ""}, {"word": "safer", "meaning": "mais seguro", "note": ""}], "exercises": {"grammar": [{"point": "Past simple e past continuous", "explanation_pt": "'was on the night train' e 'kept looking' descrevem a cena."}, {"point": "Comparativo", "explanation_pt": "'safer' compara a segurança dos assentos."}], "multiple_choice": [{"question": "Where was Kai?", "options": ["On a boat", "In a car", "On a night train", "On a plane"], "correct_index": 2, "explanation": "Num trem noturno."}, {"question": "What was in his bag?", "options": ["Clothes", "Food", "Important documents", "Money"], "correct_index": 2, "explanation": "Documentos importantes."}, {"question": "What did the woman do?", "options": ["Slept", "Gave him food", "Sang", "Followed him and reached for his bag"], "correct_index": 3, "explanation": "Seguiu e tentou pegar a bolsa."}, {"question": "Where did Kai sit next?", "options": ["At the front", "Near a sleeping family", "In first class", "Alone"], "correct_index": 1, "explanation": "Perto de uma família."}, {"question": "Who waited in Vienna?", "options": ["A woman", "The police", "A friend", "A man in a grey coat"], "correct_index": 3, "explanation": "Um homem de casaco cinza."}], "open_questions": [{"question": "How do you stay safe when travelling?", "key_points_pt": ["sugerir"]}, {"question": "Would you trust a stranger on a train?", "key_points_pt": ["opinar"]}]}}, {"level": "B1", "genre": "spy", "title": "The Double Agent", "paragraphs": ["For three years, Nikolai had worked as a translator in the embassy while secretly sending information to his own government. Nobody had ever suspected him, because he was polite, punctual and unremarkable. But one winter afternoon, he noticed that his files had been moved. Someone had been searching his desk.", "That evening, he found a small microphone hidden in his lamp. Nikolai was calm. He had trained for this moment. Without touching the device, he started a long phone call about the weather and his mother's recipes, while writing a note to his contact on a napkin.", "The next morning, he walked to the market as usual. In front of a fruit stall, a woman dropped her bag and he helped her pick up the apples. In the confusion, she passed him a small envelope. Inside was a plane ticket and a single line: \"Leave today.\"", "Nikolai returned to the embassy, said goodbye to his colleagues as if he were going on holiday, and disappeared. Weeks later, an old postcard arrived at the embassy. It showed a sunny beach, and on the back, one word in perfect handwriting: \"Thanks.\""], "paragraphs_pt": ["Por três anos, Nikolai trabalhara como tradutor na embaixada enquanto enviava informações em segredo ao próprio governo. Ninguém jamais o suspeitara, pois era educado, pontual e sem destaque. Mas numa tarde de inverno, notou que seus arquivos haviam sido mexidos. Alguém estivera vasculhando sua mesa.", "Naquela noite, achou um pequeno microfone escondido na luminária. Nikolai estava calmo. Treinara para aquele momento. Sem tocar no aparelho, iniciou uma longa ligação sobre o clima e as receitas da mãe, enquanto escrevia um bilhete ao contato num guardanapo.", "Na manhã seguinte, caminhou ao mercado como sempre. Diante de uma barraca de frutas, uma mulher derrubou a bolsa e ele a ajudou a pegar as maçãs. Na confusão, ela lhe passou um pequeno envelope. Dentro havia uma passagem de avião e uma única linha: \"Parta hoje.\"", "Nikolai voltou à embaixada, despediu-se dos colegas como se fosse sair de férias e desapareceu. Semanas depois, um velho cartão-postal chegou à embaixada. Mostrava uma praia ensolarada e, no verso, uma palavra em caligrafia perfeita: \"Obrigado.\""], "hard_words": ["embassy", "unremarkable", "device", "envelope"], "vocab": [{"word": "embassy", "meaning": "embaixada", "note": ""}, {"word": "translator", "meaning": "tradutor", "note": ""}, {"word": "suspected", "meaning": "suspeitou", "note": ""}, {"word": "unremarkable", "meaning": "sem destaque", "note": ""}, {"word": "microphone", "meaning": "microfone", "note": ""}, {"word": "device", "meaning": "aparelho", "note": ""}, {"word": "napkin", "meaning": "guardanapo", "note": ""}, {"word": "envelope", "meaning": "envelope", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "were"], "irregular": ["had", "worked", "suspected", "noticed", "moved", "found", "hidden", "trained", "started", "walked", "dropped", "helped", "passed", "returned", "said", "disappeared", "arrived", "showed"], "phrasal": ["passed him"], "wh": [], "connectors": ["and", "but", "because", "while", "if", "as"], "comparative": []}, "word_meanings": [{"word": "embassy", "meaning": "embaixada", "note": ""}, {"word": "translator", "meaning": "tradutor", "note": ""}, {"word": "suspected", "meaning": "suspeitou", "note": ""}, {"word": "unremarkable", "meaning": "sem destaque", "note": ""}, {"word": "microphone", "meaning": "microfone", "note": ""}, {"word": "device", "meaning": "aparelho", "note": ""}, {"word": "napkin", "meaning": "guardanapo", "note": ""}, {"word": "envelope", "meaning": "envelope", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Nikolai had worked' e 'files had been moved' dão contexto anterior."}, {"point": "Past simple em sequência", "explanation_pt": "'walked', 'dropped', 'returned' contam o plano."}], "multiple_choice": [{"question": "What was Nikolai's cover job?", "options": ["Doctor", "Chef", "Teacher", "Translator at an embassy"], "correct_index": 3, "explanation": "Tradutor na embaixada."}, {"question": "What did he notice one winter afternoon?", "options": ["His files had been moved", "His boss left", "His window broke", "His phone rang"], "correct_index": 0, "explanation": "Arquivos mexidos."}, {"question": "What did he find in the lamp?", "options": ["A note", "A microphone", "A key", "A camera"], "correct_index": 1, "explanation": "Um microfone."}, {"question": "How did he receive the message?", "options": ["A woman passed him an envelope", "An email", "A friend", "A call"], "correct_index": 0, "explanation": "Mulher passou envelope."}, {"question": "How did the story end?", "options": ["He died", "A postcard saying Thanks", "He stayed", "He was arrested"], "correct_index": 1, "explanation": "Um cartão dizendo 'Obrigado'."}], "open_questions": [{"question": "Would you be a double agent?", "key_points_pt": ["opinar"]}, {"question": "How can someone stay calm under pressure?", "key_points_pt": ["explicar"]}]}}, {"level": "B1", "genre": "spy", "title": "The Cipher in the Newspaper", "paragraphs": ["Every Sunday, Irene bought the same newspaper and solved the crossword at a small café. She seemed an ordinary retired teacher, which was precisely the point. In reality, the crossword contained a cipher that told her where to deliver messages for a network of agents.", "One Sunday, however, the crossword contained a mistake. The word for \"Seven across\" had eight letters instead of seven. Irene stared at it for a long time. Either the printer had made an error, or someone had changed the code, and in her profession, errors were rarely accidental.", "She finished her coffee, took the newspaper and went to the library. After an hour of careful reading, she found the answer: the extra letter formed a warning. \"Compromised. Do not deliver.\" The network had been discovered.", "Irene went home and burned all her notes in the fireplace. Then she called her niece, said she was going on a long holiday and packed a small suitcase. She left the crossword on the table with a single word written in the empty squares: \"Goodbye.\""], "paragraphs_pt": ["Todo domingo, Irene comprava o mesmo jornal e resolvia as palavras cruzadas num pequeno café. Parecia uma professora aposentada comum, o que era justamente a ideia. Na realidade, as cruzadas continham uma cifra que lhe dizia onde entregar mensagens para uma rede de agentes.", "Num domingo, porém, as cruzadas continham um erro. A palavra do \"Sete horizontal\" tinha oito letras em vez de sete. Irene a fitou por muito tempo. Ou o tipógrafo errara, ou alguém mudara o código, e em sua profissão erros raramente eram acidentais.", "Terminou o café, pegou o jornal e foi à biblioteca. Depois de uma hora de leitura cuidadosa, achou a resposta: a letra extra formava um aviso. \"Comprometido. Não entregue.\" A rede fora descoberta.", "Irene voltou para casa e queimou todas as suas anotações na lareira. Depois ligou para a sobrinha, disse que ia viajar por muito tempo e fez uma mala pequena. Deixou as cruzadas sobre a mesa com uma palavra escrita nos quadrados vazios: \"Adeus.\""], "hard_words": ["cipher", "network", "accidental", "compromised"], "vocab": [{"word": "crossword", "meaning": "palavras cruzadas", "note": ""}, {"word": "retired", "meaning": "aposentada", "note": ""}, {"word": "cipher", "meaning": "cifra", "note": ""}, {"word": "network", "meaning": "rede", "note": ""}, {"word": "printer", "meaning": "tipógrafo, gráfica", "note": ""}, {"word": "accidental", "meaning": "acidental", "note": ""}, {"word": "compromised", "meaning": "comprometido", "note": ""}, {"word": "fireplace", "meaning": "lareira", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been"], "irregular": ["bought", "solved", "seemed", "retired", "contained", "told", "had", "stared", "made", "changed", "finished", "took", "went", "found", "formed", "compromised", "discovered", "burned", "called", "said", "packed", "left", "written"], "phrasal": ["stared at", "burned all"], "wh": ["where", "which"], "connectors": ["and", "however", "instead", "then", "after", "or"], "comparative": []}, "word_meanings": [{"word": "crossword", "meaning": "palavras cruzadas", "note": ""}, {"word": "retired", "meaning": "aposentada", "note": ""}, {"word": "cipher", "meaning": "cifra", "note": ""}, {"word": "network", "meaning": "rede", "note": ""}, {"word": "printer", "meaning": "tipógrafo, gráfica", "note": ""}, {"word": "accidental", "meaning": "acidental", "note": ""}, {"word": "compromised", "meaning": "comprometido", "note": ""}, {"word": "fireplace", "meaning": "lareira", "note": ""}], "exercises": {"grammar": [{"point": "Either... or", "explanation_pt": "'Either the printer made an error, or someone changed the code' apresenta duas possibilidades."}, {"point": "Instead of", "explanation_pt": "'eight letters instead of seven' compara."}], "multiple_choice": [{"question": "What did Irene do every Sunday?", "options": ["Solve a crossword", "Go to church", "Visit friends", "Swim"], "correct_index": 0, "explanation": "Resolver palavras cruzadas."}, {"question": "What was special about the crossword?", "options": ["It was free", "It was big", "It contained a cipher", "It was rare"], "correct_index": 2, "explanation": "Continha uma cifra."}, {"question": "What was unusual one Sunday?", "options": ["The paper was late", "Nobody came", "The café was closed", "A word had an extra letter"], "correct_index": 3, "explanation": "Palavra com letra extra."}, {"question": "What did the extra letter say?", "options": ["A name", "A date", "A warning", "A joke"], "correct_index": 2, "explanation": "Um aviso."}, {"question": "What did Irene do?", "options": ["Stayed", "Called the police", "Wrote a book", "Burned her notes and left"], "correct_index": 3, "explanation": "Queimou as notas e partiu."}], "open_questions": [{"question": "How could a crossword hide messages?", "key_points_pt": ["imaginar"]}, {"question": "Do you like puzzles?", "key_points_pt": ["falar"]}]}}, {"level": "B1", "genre": "spy", "title": "Operation Lighthouse", "paragraphs": ["Agent Torres had a deceptively simple assignment: to deliver a package to a lighthouse keeper on a remote island. The sea was rough, and the only boat available belonged to an old fisherman who talked a lot and asked too many questions. Torres pretended to be a bird photographer.", "On the island, the lighthouse keeper, a quiet man called Silas, took the package without a word. Torres began to turn back to the boat when he noticed that the keeper's telescope was pointed not at the sea but at the mainland. A small radio sat on the table, warm to the touch.", "Torres realised that the lighthouse was no ordinary one. It was a listening post. Every conversation across the strait could be heard from this isolated tower. She decided to say nothing and returned to the boat, smiling at the fisherman.", "Back in the capital, she gave her report: package delivered, nothing unusual. Only her closest colleague noticed the slight tremor in her voice. \"Is there something you want to tell me?\" he asked. \"Yes,\" she answered. \"I need a very strong coffee and a very long holiday.\""], "paragraphs_pt": ["A agente Torres tinha uma missão enganosamente simples: entregar um pacote a um faroleiro numa ilha remota. O mar estava agitado e o único barco disponível pertencia a um velho pescador que falava muito e fazia perguntas demais. Torres fingiu ser fotógrafa de pássaros.", "Na ilha, o faroleiro, um homem calado chamado Silas, pegou o pacote sem uma palavra. Torres começava a voltar ao barco quando notou que o telescópio do faroleiro apontava não para o mar, mas para o continente. Um pequeno rádio estava sobre a mesa, morno ao toque.", "Torres percebeu que o farol não era comum. Era um posto de escuta. Toda conversa através do estreito podia ser ouvida daquela torre isolada. Decidiu não dizer nada e voltou ao barco, sorrindo para o pescador.", "De volta à capital, deu seu relatório: pacote entregue, nada incomum. Só o colega mais próximo notou o leve tremor na voz. \"Há algo que queira me contar?\", perguntou. \"Sim\", respondeu ela. \"Preciso de um café muito forte e de férias muito longas.\""], "hard_words": ["assignment", "remote", "strait", "tremor"], "vocab": [{"word": "deceptively", "meaning": "enganosamente", "note": ""}, {"word": "assignment", "meaning": "missão, tarefa", "note": ""}, {"word": "lighthouse", "meaning": "farol", "note": ""}, {"word": "remote", "meaning": "remoto", "note": ""}, {"word": "telescope", "meaning": "telescópio", "note": ""}, {"word": "strait", "meaning": "estreito", "note": ""}, {"word": "listening post", "meaning": "posto de escuta", "note": ""}, {"word": "tremor", "meaning": "tremor", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "is"], "irregular": ["had", "belonged", "talked", "asked", "pretended", "called", "took", "began", "noticed", "pointed", "sat", "realised", "could", "heard", "isolated", "decided", "returned", "gave", "delivered", "answered"], "phrasal": ["turn back", "pretended to be"], "wh": ["who", "when"], "connectors": ["and", "but", "when"], "comparative": []}, "word_meanings": [{"word": "deceptively", "meaning": "enganosamente", "note": ""}, {"word": "assignment", "meaning": "missão, tarefa", "note": ""}, {"word": "lighthouse", "meaning": "farol", "note": ""}, {"word": "remote", "meaning": "remoto", "note": ""}, {"word": "telescope", "meaning": "telescópio", "note": ""}, {"word": "strait", "meaning": "estreito", "note": ""}, {"word": "listening post", "meaning": "posto de escuta", "note": ""}, {"word": "tremor", "meaning": "tremor", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect e past simple", "explanation_pt": "'She noticed that the keeper's telescope was pointed...' combina observação e cena."}, {"point": "Too many", "explanation_pt": "'asked too many questions' indica excesso."}], "multiple_choice": [{"question": "What was the assignment?", "options": ["Photograph birds", "Steal a boat", "Deliver a package to a lighthouse", "Meet a fisherman"], "correct_index": 2, "explanation": "Entregar um pacote ao faroleiro."}, {"question": "What did Torres pretend to be?", "options": ["A doctor", "A fisherman", "A teacher", "A bird photographer"], "correct_index": 3, "explanation": "Fotógrafa de pássaros."}, {"question": "What did she notice?", "options": ["A map", "A broken radio", "The telescope pointed at the mainland", "A secret door"], "correct_index": 2, "explanation": "Telescópio apontado ao continente."}, {"question": "What was the lighthouse?", "options": ["A listening post", "A museum", "A hotel", "A prison"], "correct_index": 0, "explanation": "Um posto de escuta."}, {"question": "What did she tell her boss?", "options": ["Everything", "Nothing unusual", "The lighthouse is a spy post", "She quit"], "correct_index": 1, "explanation": "Nada incomum."}], "open_questions": [{"question": "Why would Torres keep silent?", "key_points_pt": ["imaginar"]}, {"question": "What would you do after finding a secret?", "key_points_pt": ["opinar"]}]}}, {"level": "B2", "genre": "spy", "title": "The Man Who Fell Asleep in Berlin", "paragraphs": ["Everyone at the agency agreed that Agent Pruitt was the least impressive spy they had ever employed. He was forgetful, lost his keys weekly and had once fallen asleep during a surveillance operation, snoring loudly in a parked car. He survived in the service only because, miraculously, his clumsiness kept leading him to results.", "In the autumn of that year, he was sent to Berlin to observe a banker suspected of laundering money. The task was dull: sit in a café, drink coffee, remember who entered the building across the street. Pruitt, predictably, dozed off at the third hour, his head resting against the window.", "When he woke, a man was sitting at his table. \"You are very observant,\" the stranger said with a smile. \"You've watched me for three days without moving.\" It was the banker. Convinced that Pruitt was a master of patience, he had decided to hire him as a bodyguard. Pruitt, still half-asleep, accepted.", "Within weeks, he had access to the banker's accounts and, by the end of the winter, to the evidence that destroyed his entire operation. The agency awarded him a medal. Pruitt, who never understood how it had happened, kept it in a drawer and went back to losing his keys."], "paragraphs_pt": ["Todos na agência concordavam que o agente Pruitt era o espião menos impressionante que já haviam empregado. Era esquecido, perdia as chaves toda semana e uma vez adormecera numa operação de vigilância, roncando alto num carro estacionado. Sobrevivia no serviço só porque, milagrosamente, sua falta de jeito o levava a resultados.", "No outono daquele ano, foi enviado a Berlim para observar um banqueiro suspeito de lavar dinheiro. A tarefa era maçante: sentar num café, tomar café, lembrar quem entrava no prédio do outro lado da rua. Pruitt, previsivelmente, cochilou na terceira hora, com a cabeça apoiada na janela.", "Quando acordou, um homem estava sentado à sua mesa. \"O senhor é muito observador\", disse o estranho com um sorriso. \"Me vigiou por três dias sem se mexer.\" Era o banqueiro. Convencido de que Pruitt era um mestre da paciência, decidira contratá-lo como segurança. Pruitt, ainda meio dormindo, aceitou.", "Em semanas, tinha acesso às contas do banqueiro e, ao fim do inverno, às provas que destruíram toda a operação dele. A agência lhe deu uma medalha. Pruitt, que nunca entendeu como acontecera, guardou-a numa gaveta e voltou a perder as chaves."], "hard_words": ["surveillance", "clumsiness", "laundering", "observant"], "vocab": [{"word": "surveillance", "meaning": "vigilância", "note": ""}, {"word": "miraculously", "meaning": "milagrosamente", "note": ""}, {"word": "clumsiness", "meaning": "falta de jeito", "note": ""}, {"word": "laundering", "meaning": "lavando (dinheiro)", "note": ""}, {"word": "dull", "meaning": "maçante", "note": ""}, {"word": "dozed off", "meaning": "cochilou", "note": ""}, {"word": "observant", "meaning": "observador", "note": ""}, {"word": "bodyguard", "meaning": "segurança", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "are"], "irregular": ["agreed", "had", "employed", "lost", "fallen", "parked", "survived", "kept", "sent", "suspected", "entered", "dozed", "woke", "said", "watched", "convinced", "decided", "accepted", "destroyed", "awarded", "understood", "happened", "went"], "phrasal": ["dozed off", "went back to"], "wh": ["who", "when", "how"], "connectors": ["and", "because", "when", "still", "once", "as"], "comparative": []}, "word_meanings": [{"word": "surveillance", "meaning": "vigilância", "note": ""}, {"word": "miraculously", "meaning": "milagrosamente", "note": ""}, {"word": "clumsiness", "meaning": "falta de jeito", "note": ""}, {"word": "laundering", "meaning": "lavando (dinheiro)", "note": ""}, {"word": "dull", "meaning": "maçante", "note": ""}, {"word": "dozed off", "meaning": "cochilou", "note": ""}, {"word": "observant", "meaning": "observador", "note": ""}, {"word": "bodyguard", "meaning": "segurança", "note": ""}], "exercises": {"grammar": [{"point": "Had once + particípio", "explanation_pt": "'had once fallen asleep' mostra algo anterior."}, {"point": "Convinced that", "explanation_pt": "'Convinced that Pruitt was a master of patience, he decided...' usa particípio para dar a razão."}], "multiple_choice": [{"question": "What was Pruitt like?", "options": ["Aggressive", "Forgetful and clumsy", "Lazy but famous", "Brilliant"], "correct_index": 1, "explanation": "Esquecido e desajeitado."}, {"question": "Why was he sent to Berlin?", "options": ["To steal money", "To arrest someone", "To meet a spy", "To observe a banker"], "correct_index": 3, "explanation": "Observar um banqueiro."}, {"question": "What happened at the café?", "options": ["He ran away", "He fought", "He fell asleep", "He read"], "correct_index": 2, "explanation": "Cochilou."}, {"question": "Why did the banker hire him?", "options": ["Pruitt asked", "He thought Pruitt was patient", "He was rich", "He was a friend"], "correct_index": 1, "explanation": "Achou que era paciente."}, {"question": "What did Pruitt do with the medal?", "options": ["Gave it away", "Sold it", "Lost it", "Kept it in a drawer"], "correct_index": 3, "explanation": "Guardou na gaveta."}], "open_questions": [{"question": "Can luck beat skill?", "key_points_pt": ["debater"]}, {"question": "Do you know someone who succeeds by accident?", "key_points_pt": ["contar"]}]}}, {"level": "B2", "genre": "spy", "title": "The Last Dead Drop", "paragraphs": ["For twenty years, the dead drop had been a hollow brick in the wall of an abandoned bakery. Agents left microfilm; others collected it. The system was elegant, impersonal and, until last Tuesday, flawless. Camille, arriving at dusk to retrieve the day's delivery, found the brick missing and in its place a small card: \"We know.\"", "She did not panic. Panic was a luxury for people who had a choice. She withdrew slowly, walked through three side streets and entered a cinema, where she sat in the last row and observed the audience. Nobody followed her, which worried her more than if they had.", "The card meant that the network had been penetrated, but by whom? She considered the possibilities with the methodical coldness that her training had instilled. Few people knew about the brick: herself, her handler and two other agents. One of them had been warning her for weeks that he was tired of the work.", "She sent a message through an emergency channel. The answer came within the hour, in a code only one person could produce. It was neither her handler nor the tired agent. It was a voice she had not heard in years, belonging to a man she believed was dead. As the film flickered above her, Camille smiled for the first time in days: someone, at last, was ready to play openly."], "paragraphs_pt": ["Por vinte anos, o ponto de entrega fora um tijolo oco na parede de uma padaria abandonada. Agentes deixavam microfilmes; outros os recolhiam. O sistema era elegante, impessoal e, até terça passada, impecável. Camille, chegando ao anoitecer para recolher a entrega do dia, achou o tijolo sumido e, em seu lugar, um cartão: \"Nós sabemos.\"", "Não entrou em pânico. Pânico era luxo de quem tinha escolha. Retirou-se devagar, atravessou três ruas laterais e entrou num cinema, onde sentou na última fileira e observou a plateia. Ninguém a seguiu, o que a preocupou mais do que se tivessem seguido.", "O cartão significava que a rede fora penetrada, mas por quem? Considerou as possibilidades com a frieza metódica que o treinamento lhe instilara. Poucos sabiam do tijolo: ela, seu controlador e dois outros agentes. Um deles vinha avisando havia semanas que estava cansado do trabalho.", "Enviou uma mensagem por um canal de emergência. A resposta veio em uma hora, num código que só uma pessoa podia produzir. Não era nem o controlador nem o agente cansado. Era uma voz que não ouvia havia anos, de um homem que julgava morto. Enquanto o filme tremeluzia acima dela, Camille sorriu pela primeira vez em dias: alguém, enfim, estava pronto para jogar às claras."], "hard_words": ["flawless", "retrieve", "penetrated", "instilled"], "vocab": [{"word": "dead drop", "meaning": "ponto de entrega secreta", "note": ""}, {"word": "hollow", "meaning": "oco", "note": ""}, {"word": "microfilm", "meaning": "microfilme", "note": ""}, {"word": "flawless", "meaning": "impecável", "note": ""}, {"word": "retrieve", "meaning": "recolher", "note": ""}, {"word": "penetrated", "meaning": "penetrada", "note": ""}, {"word": "instilled", "meaning": "instilou", "note": ""}, {"word": "handler", "meaning": "controlador", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was"], "irregular": ["had", "abandoned", "left", "collected", "found", "did", "withdrew", "walked", "entered", "sat", "observed", "followed", "worried", "meant", "penetrated", "considered", "instilled", "knew", "tired", "sent", "came", "could", "heard", "believed", "flickered", "smiled"], "phrasal": ["walked through"], "wh": ["who", "where", "which", "whom"], "connectors": ["and", "but", "until", "if", "as"], "comparative": []}, "word_meanings": [{"word": "dead drop", "meaning": "ponto de entrega secreta", "note": ""}, {"word": "hollow", "meaning": "oco", "note": ""}, {"word": "microfilm", "meaning": "microfilme", "note": ""}, {"word": "flawless", "meaning": "impecável", "note": ""}, {"word": "retrieve", "meaning": "recolher", "note": ""}, {"word": "penetrated", "meaning": "penetrada", "note": ""}, {"word": "instilled", "meaning": "instilou", "note": ""}, {"word": "handler", "meaning": "controlador", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'the dead drop had been a hollow brick' dá contexto anterior."}, {"point": "Neither... nor", "explanation_pt": "'It was neither her handler nor the tired agent' elimina duas hipóteses."}], "multiple_choice": [{"question": "What was the dead drop?", "options": ["A hollow brick", "A locker", "A mailbox", "A café table"], "correct_index": 0, "explanation": "Um tijolo oco."}, {"question": "What did Camille find?", "options": ["A weapon", "A card saying 'We know'", "A body", "A map"], "correct_index": 1, "explanation": "Cartão 'Nós sabemos'."}, {"question": "Where did she go?", "options": ["A park", "Her home", "A bank", "A cinema"], "correct_index": 3, "explanation": "Um cinema."}, {"question": "Why did it worry her that nobody followed her?", "options": ["She was safe", "It was unexpected", "She was tired", "She wanted company"], "correct_index": 1, "explanation": "Era inesperado."}, {"question": "Who answered the emergency message?", "options": ["The police", "The tired agent", "A man she believed dead", "Her handler"], "correct_index": 2, "explanation": "Um homem que julgava morto."}], "open_questions": [{"question": "How can a network be penetrated?", "key_points_pt": ["imaginar"]}, {"question": "What would you do after a warning card?", "key_points_pt": ["opinar"]}]}}, {"level": "C1", "genre": "spy", "title": "The Archivist of Secrets", "paragraphs": ["Beneath a nondescript government building lay an archive known only by its corridor number, where forty years of confidential reports were kept in climate-controlled boxes. The archivist, Mr. Fenwick, a man of exquisite incuriosity, had spent three decades filing documents without reading a single one. It was, he often said, a matter of professional hygiene.", "The routine was upset by a clerical error. A file marked for destruction had been misfiled among the ordinary records, and Fenwick, in the act of returning it, glimpsed a word on the cover that made him pause: his own name. For the first time in his career, he disobeyed his principles and opened it.", "The file revealed that, in his early twenties, he had been recruited as an informant on a student group, and had delivered reports so mild and so evasive that they had been quietly shelved. He had forgotten the episode almost entirely. What surprised him was less the discovery than the sense of vertigo: that his entire carefully neutral existence rested on a past he had not remembered choosing.", "He returned the file to the shredder tray, but not before copying one line into his notebook. It was the supervisor's assessment of his reports: \"Harmless; perhaps deliberately so.\" Fenwick read it several times and, for the first time in thirty years, wondered whether harmlessness had ever been a form of courage."], "paragraphs_pt": ["Sob um prédio governamental sem graça havia um arquivo conhecido apenas pelo número do corredor, onde quarenta anos de relatórios confidenciais eram guardados em caixas climatizadas. O arquivista, Sr. Fenwick, homem de requintada incuriosidade, passara três décadas arquivando documentos sem ler um só. Era, dizia ele, uma questão de higiene profissional.", "A rotina foi perturbada por um erro administrativo. Um arquivo marcado para destruição fora arquivado por engano entre os registros comuns, e Fenwick, ao devolvê-lo, vislumbrou na capa uma palavra que o fez parar: seu próprio nome. Pela primeira vez na carreira, desobedeceu aos princípios e o abriu.", "O arquivo revelava que, no início dos vinte anos, fora recrutado como informante de um grupo estudantil e entregara relatórios tão brandos e evasivos que foram discretamente engavetados. Esquecera quase totalmente o episódio. O que o surpreendeu foi menos a descoberta que a sensação de vertigem: a de que toda a sua existência cuidadosamente neutra repousava num passado que não lembrava ter escolhido.", "Devolveu o arquivo à bandeja da trituradora, mas não sem copiar uma linha no caderno. Era a avaliação do supervisor sobre seus relatórios: \"Inofensivo; talvez deliberadamente.\" Fenwick a leu várias vezes e, pela primeira vez em trinta anos, perguntou-se se a inofensividade teria sido alguma vez uma forma de coragem."], "hard_words": ["nondescript", "evasive", "vertigo", "harmlessness"], "vocab": [{"word": "nondescript", "meaning": "sem graça", "note": ""}, {"word": "confidential", "meaning": "confidencial", "note": ""}, {"word": "incuriosity", "meaning": "incuriosidade", "note": ""}, {"word": "clerical", "meaning": "administrativo", "note": ""}, {"word": "informant", "meaning": "informante", "note": ""}, {"word": "evasive", "meaning": "evasivo", "note": ""}, {"word": "vertigo", "meaning": "vertigem", "note": ""}, {"word": "harmlessness", "meaning": "inofensividade", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "was", "been"], "irregular": ["lay", "known", "kept", "controlled", "had", "spent", "said", "marked", "glimpsed", "made", "disobeyed", "opened", "revealed", "recruited", "delivered", "shelved", "forgotten", "surprised", "rested", "remembered", "returned", "wondered"], "phrasal": ["shelved"], "wh": ["what", "where"], "connectors": ["and", "but", "so", "before", "as"], "comparative": []}, "word_meanings": [{"word": "nondescript", "meaning": "sem graça", "note": ""}, {"word": "confidential", "meaning": "confidencial", "note": ""}, {"word": "incuriosity", "meaning": "incuriosidade", "note": ""}, {"word": "clerical", "meaning": "administrativo", "note": ""}, {"word": "informant", "meaning": "informante", "note": ""}, {"word": "evasive", "meaning": "evasivo", "note": ""}, {"word": "vertigo", "meaning": "vertigem", "note": ""}, {"word": "harmlessness", "meaning": "inofensividade", "note": ""}], "exercises": {"grammar": [{"point": "Had spent + ing", "explanation_pt": "'had spent three decades filing documents' mostra um período anterior."}, {"point": "Less... than", "explanation_pt": "'less the discovery than the sense of vertigo' compara causas da surpresa."}], "multiple_choice": [{"question": "What was Fenwick's job?", "options": ["Archivist", "Soldier", "Spy", "Cook"], "correct_index": 0, "explanation": "Arquivista."}, {"question": "Why did he open the file?", "options": ["A boss ordered it", "It had his own name", "He was bored", "It was open"], "correct_index": 1, "explanation": "Tinha o nome dele."}, {"question": "What had he done in his youth?", "options": ["Been a teacher", "Been an informant", "Been a pilot", "Been a thief"], "correct_index": 1, "explanation": "Fora informante."}, {"question": "What did the supervisor write?", "options": ["Dangerous", "Harmless; perhaps deliberately so", "Excellent", "Useless"], "correct_index": 1, "explanation": "'Inofensivo; talvez deliberadamente.'"}, {"question": "What does Fenwick wonder?", "options": ["Whether to resign", "Whether to burn files", "Whether harmlessness was courage", "Whether to travel"], "correct_index": 2, "explanation": "Se a inofensividade foi coragem."}], "open_questions": [{"question": "Can neutrality be a moral choice?", "key_points_pt": ["debater"]}, {"question": "What past choices shape who we are?", "key_points_pt": ["refletir"]}]}}, {"level": "C1", "genre": "spy", "title": "The Defector's Question", "paragraphs": ["When the defector walked into the consulate at three in the morning, the duty officer, a weary woman named Hale, expected the usual theatre: urgency, evasions, a request for asylum wrapped in the vocabulary of idealism. Instead, the man sat down, accepted a glass of water and asked her, with the simplicity of a child, whether the work he had done in his own country had been good.", "Hale was disarmed. In her training manual, there was no chapter on this. She explained that she could not judge his past, only decide his future. He nodded, as if that were more or less what he had expected. For an hour, he described his career in fragments: a laboratory, a dismissive supervisor, a line of research he had begun to doubt.", "By dawn, it was clear that he was neither a hero nor a villain, but a scientist who had slowly lost his ability to ignore the use his work would be put to. His defection was not an act of political conviction. It was an act of fatigue, the kind that follows years of looking away.", "When the debriefing began, Hale found herself unsettled. She had been trained to evaluate information, not to confront the possibility that the most valuable thing a defector can bring is not a secret, but an unresolved conscience. She wrote this thought in her notebook, then crossed it out, because it was not the kind of thing one reports."], "paragraphs_pt": ["Quando o desertor entrou no consulado às três da manhã, a oficial de plantão, uma mulher cansada chamada Hale, esperava o teatro habitual: urgência, evasivas, um pedido de asilo embrulhado no vocabulário do idealismo. Em vez disso, o homem sentou-se, aceitou um copo d'água e perguntou-lhe, com a simplicidade de uma criança, se o trabalho que fizera em seu país fora bom.", "Hale ficou desarmada. No manual de treinamento não havia capítulo sobre isso. Explicou que não podia julgar o passado dele, apenas decidir seu futuro. Ele assentiu, como se fosse mais ou menos o que esperava. Por uma hora, descreveu sua carreira em fragmentos: um laboratório, um supervisor desdenhoso, uma linha de pesquisa que passara a duvidar.", "Ao amanhecer, estava claro que ele não era nem herói nem vilão, mas um cientista que perdera aos poucos a capacidade de ignorar o uso que dariam ao seu trabalho. Sua deserção não era ato de convicção política. Era ato de fadiga, do tipo que segue anos de olhar para o lado.", "Quando o interrogatório começou, Hale se sentiu perturbada. Fora treinada para avaliar informação, não para enfrentar a possibilidade de que a coisa mais valiosa que um desertor pode trazer não é um segredo, mas uma consciência não resolvida. Anotou o pensamento no caderno e depois o riscou, pois não era o tipo de coisa que se reporta."], "hard_words": ["defector", "asylum", "dismissive", "conscience"], "vocab": [{"word": "defector", "meaning": "desertor", "note": ""}, {"word": "consulate", "meaning": "consulado", "note": ""}, {"word": "asylum", "meaning": "asilo", "note": ""}, {"word": "disarmed", "meaning": "desarmada", "note": ""}, {"word": "dismissive", "meaning": "desdenhoso", "note": ""}, {"word": "defection", "meaning": "deserção", "note": ""}, {"word": "debriefing", "meaning": "interrogatório pós-missão", "note": ""}, {"word": "conscience", "meaning": "consciência", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "were", "be", "is"], "irregular": ["walked", "named", "expected", "wrapped", "sat", "accepted", "asked", "had", "done", "disarmed", "explained", "could", "nodded", "described", "begun", "lost", "would", "began", "found", "unsettled", "trained", "wrote", "thought", "crossed"], "phrasal": ["walked into"], "wh": ["who", "what", "when"], "connectors": ["and", "but", "because", "instead", "then", "when", "or", "if", "as"], "comparative": []}, "word_meanings": [{"word": "defector", "meaning": "desertor", "note": ""}, {"word": "consulate", "meaning": "consulado", "note": ""}, {"word": "asylum", "meaning": "asilo", "note": ""}, {"word": "disarmed", "meaning": "desarmada", "note": ""}, {"word": "dismissive", "meaning": "desdenhoso", "note": ""}, {"word": "defection", "meaning": "deserção", "note": ""}, {"word": "debriefing", "meaning": "interrogatório pós-missão", "note": ""}, {"word": "conscience", "meaning": "consciência", "note": ""}], "exercises": {"grammar": [{"point": "Neither... but", "explanation_pt": "'neither a hero nor a villain, but a scientist' nega duas e afirma uma terceira."}, {"point": "Had been trained to", "explanation_pt": "'She had been trained to evaluate information' mostra preparação anterior."}], "multiple_choice": [{"question": "Where did the defector go?", "options": ["A police station", "A hospital", "A hotel", "A consulate"], "correct_index": 3, "explanation": "Um consulado."}, {"question": "What did he ask Hale?", "options": ["For a lawyer", "For a car", "Whether his work had been good", "For money"], "correct_index": 2, "explanation": "Se seu trabalho foi bom."}, {"question": "What was he, really?", "options": ["A hero", "A politician", "A villain", "A scientist who lost the ability to ignore"], "correct_index": 3, "explanation": "Um cientista cansado."}, {"question": "Why did he defect?", "options": ["Love", "Money", "Fatigue, not political conviction", "Fear"], "correct_index": 2, "explanation": "Fadiga."}, {"question": "What did Hale write and cross out?", "options": ["A name", "A number", "A thought about an unresolved conscience", "A threat"], "correct_index": 2, "explanation": "Um pensamento sobre consciência."}], "open_questions": [{"question": "Is conscience valuable in intelligence work?", "key_points_pt": ["debater"]}, {"question": "When does looking away become complicity?", "key_points_pt": ["discutir"]}]}}, {"level": "C2", "genre": "spy", "title": "The Quiet Art of Forgetting", "paragraphs": ["Spymasters, as a class, are celebrated for the memory they exercise and suspected, rarely, for the memory they suppress. Adrienne Valcourt, who had directed the foreign service's most delicate operations for a quarter of a century, kept in her desk a notebook consisting entirely of blank pages. Her subordinates assumed it was an affectation; in truth, it was a penance.", "Over the decades, she had learned that a secret is not simply a piece of information but a weight, and that the weight accumulates in the body like silt in a river. Names of agents she had placed in danger, decisions made on thin evidence, the voices of people whose lives had been rearranged by a cable: these did not fade, but waited, patient as stones.", "Her predecessor had solved the problem with bourbon. Valcourt chose a more austere remedy. Each Friday evening, she sat at the desk and attempted, with the discipline she once applied to memorising codes, to release one memory at a time. She did not erase it; she merely stopped rehearsing it, as one might stop watering a plant.", "When she retired, her successor opened the drawer and found the blank notebook. A single sentence had been written on the final page, in a hand slightly less steady than it had been in her prime: \"Forgetting is the only secret I ever kept well.\" Whether it was confession, boast or instruction, the successor never decided, and for that reason kept the notebook."], "paragraphs_pt": ["Os chefes de espionagem, como classe, são celebrados pela memória que exercem e suspeitos, raramente, pela memória que suprimem. Adrienne Valcourt, que dirigira as operações mais delicadas do serviço exterior por um quarto de século, guardava na mesa um caderno composto inteiramente de páginas em branco. Os subordinados presumiam ser afetação; na verdade, era uma penitência.", "Ao longo das décadas, aprendera que um segredo não é simples informação, mas um peso, e que o peso se acumula no corpo como lodo num rio. Nomes de agentes que pusera em perigo, decisões tomadas com evidências frágeis, as vozes de pessoas cujas vidas foram rearranjadas por um telegrama: nada disso desbotava, mas esperava, paciente como pedras.", "O predecessor resolvera o problema com bourbon. Valcourt escolheu um remédio mais austero. Toda sexta à noite, sentava à mesa e tentava, com a disciplina que antes aplicava à memorização de códigos, soltar uma memória por vez. Não a apagava; apenas parava de ensaiá-la, como quem para de regar uma planta.", "Quando se aposentou, o sucessor abriu a gaveta e achou o caderno em branco. Uma única frase fora escrita na última página, numa letra um pouco menos firme que em seu auge: \"Esquecer é o único segredo que guardei bem.\" Se era confissão, bazófia ou instrução, o sucessor nunca decidiu, e por isso guardou o caderno."], "hard_words": ["penance", "silt", "austere", "rehearsing"], "vocab": [{"word": "suppress", "meaning": "suprimir", "note": ""}, {"word": "affectation", "meaning": "afetação", "note": ""}, {"word": "penance", "meaning": "penitência", "note": ""}, {"word": "silt", "meaning": "lodo", "note": ""}, {"word": "austere", "meaning": "austero", "note": ""}, {"word": "remedy", "meaning": "remédio", "note": ""}, {"word": "rehearsing", "meaning": "ensaiando", "note": ""}, {"word": "boast", "meaning": "bazófia", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "was", "is", "been"], "irregular": ["celebrated", "suspected", "had", "directed", "kept", "assumed", "learned", "placed", "made", "rearranged", "did", "waited", "solved", "chose", "sat", "attempted", "applied", "stopped", "might", "retired", "opened", "found", "written", "decided"], "phrasal": ["kept in"], "wh": ["who", "when", "whose"], "connectors": ["and", "but", "when", "or", "once", "as"], "comparative": []}, "word_meanings": [{"word": "suppress", "meaning": "suprimir", "note": ""}, {"word": "affectation", "meaning": "afetação", "note": ""}, {"word": "penance", "meaning": "penitência", "note": ""}, {"word": "silt", "meaning": "lodo", "note": ""}, {"word": "austere", "meaning": "austero", "note": ""}, {"word": "remedy", "meaning": "remédio", "note": ""}, {"word": "rehearsing", "meaning": "ensaiando", "note": ""}, {"word": "boast", "meaning": "bazófia", "note": ""}], "exercises": {"grammar": [{"point": "Had directed + for a quarter of a century", "explanation_pt": "'who had directed operations for 25 years' mostra período anterior."}, {"point": "Not simply... but", "explanation_pt": "'not simply a piece of information but a weight' amplia a definição."}], "multiple_choice": [{"question": "What did Valcourt keep in her desk?", "options": ["A blank notebook", "A map", "A photograph", "A gun"], "correct_index": 0, "explanation": "Um caderno em branco."}, {"question": "What did her subordinates think?", "options": ["It was an affectation", "It was a code", "It was empty by chance", "It was a gift"], "correct_index": 0, "explanation": "Achavam afetação."}, {"question": "What did she do on Fridays?", "options": ["Drank", "Travelled", "Wrote reports", "Tried to release one memory"], "correct_index": 3, "explanation": "Soltar uma memória."}, {"question": "How is forgetting compared?", "options": ["Breaking a lock", "Burning a book", "Closing a door", "Stopping watering a plant"], "correct_index": 3, "explanation": "Parar de regar uma planta."}, {"question": "What was written on the last page?", "options": ["The code", "Forgetting is the only secret I kept well", "A name", "Goodbye"], "correct_index": 1, "explanation": "'Esquecer é o único segredo que guardei bem.'"}], "open_questions": [{"question": "Can forgetting be a professional skill?", "key_points_pt": ["debater"]}, {"question": "How do people carry heavy secrets?", "key_points_pt": ["discutir"]}]}}, {"level": "C2", "genre": "spy", "title": "A Treatise on Trust", "paragraphs": ["In the long history of espionage, nothing has been more consistently overvalued than the idea of trust, and nothing more consistently relied upon. Every network, however sophisticated, ultimately rests on a human being agreeing to believe another, an agreement that no cryptography can guarantee. Darius Mehr, who spent his life studying the phenomenon, called it \"the oldest vulnerability and the only one that cannot be patched\".", "His own career offered ample evidence. He had been betrayed twice: once by a friend who sold his name for a promotion, once by a lover who passed his letters to a rival service. Yet he had also been saved by strangers, by a ferryman who asked no questions, by a widow who hid him in her cellar. The ledger of trust, he came to observe, was kept in an accounting no one could audit.", "In late life, he wrote a short memoir that disappointed the publishers, who had hoped for revelations. There were few. What it contained instead was an argument: that deception is only possible in a world where trust is the default, and that those who profit from betrayal are, paradoxically, parasites on the virtue they scorn. A world without trust, he concluded, would not be a world without spies; it would be a world without anything worth spying on.", "He died in a rented room by the sea, leaving instructions that his papers be given to whoever asked for them. Nobody did, for years. Then a young historian, impressed by the sentence on the title page, \"I was fooled often, and never regretted believing,\" wrote to the estate. The reply was brief: \"Take them. Trust is the point.\""], "paragraphs_pt": ["Na longa história da espionagem, nada foi mais consistentemente supervalorizado que a ideia de confiança, e nada mais consistentemente empregado. Toda rede, por sofisticada que seja, repousa em última instância num ser humano que concorda em acreditar em outro, um acordo que nenhuma criptografia garante. Darius Mehr, que passou a vida estudando o fenômeno, chamou-a de \"a mais antiga vulnerabilidade e a única que não pode ser remendada\".", "Sua própria carreira ofereceu ampla evidência. Fora traído duas vezes: uma por um amigo que vendeu seu nome por uma promoção, outra por uma amante que passou suas cartas a um serviço rival. Mas também fora salvo por estranhos, por um barqueiro que não fez perguntas, por uma viúva que o escondeu no porão. O livro-caixa da confiança, passou a observar, era mantido numa contabilidade que ninguém podia auditar.", "Na velhice, escreveu uma breve memória que decepcionou os editores, que esperavam revelações. Havia poucas. O que continha, em vez disso, era um argumento: que o engano só é possível num mundo onde a confiança é o padrão, e que os que lucram com a traição são, paradoxalmente, parasitas da virtude que desprezam. Um mundo sem confiança, concluiu, não seria um mundo sem espiões; seria um mundo sem nada que valesse a pena espionar.", "Morreu num quarto alugado à beira-mar, deixando instruções de que seus papéis fossem dados a quem os pedisse. Ninguém os pediu por anos. Então uma jovem historiadora, impressionada com a frase da folha de rosto, \"Fui enganado muitas vezes e nunca me arrependi de acreditar\", escreveu à herança. A resposta foi breve: \"Levem-nos. A confiança é o ponto.\""], "hard_words": ["vulnerability", "ledger", "paradoxically", "scorn"], "vocab": [{"word": "espionage", "meaning": "espionagem", "note": ""}, {"word": "overvalued", "meaning": "supervalorizada", "note": ""}, {"word": "cryptography", "meaning": "criptografia", "note": ""}, {"word": "vulnerability", "meaning": "vulnerabilidade", "note": ""}, {"word": "ledger", "meaning": "livro-caixa", "note": ""}, {"word": "paradoxically", "meaning": "paradoxalmente", "note": ""}, {"word": "parasites", "meaning": "parasitas", "note": ""}, {"word": "scorn", "meaning": "desprezar", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "being", "be", "was", "were", "is", "are"], "irregular": ["relied", "sophisticated", "spent", "called", "patched", "offered", "had", "betrayed", "sold", "passed", "saved", "asked", "hid", "came", "kept", "could", "wrote", "disappointed", "hoped", "contained", "concluded", "would", "died", "rented", "given", "did", "impressed", "fooled", "regretted"], "phrasal": ["rests on", "relied upon"], "wh": ["who", "what", "where", "whoever"], "connectors": ["and", "however", "instead", "then", "yet", "also", "once"], "comparative": []}, "word_meanings": [{"word": "espionage", "meaning": "espionagem", "note": ""}, {"word": "overvalued", "meaning": "supervalorizada", "note": ""}, {"word": "cryptography", "meaning": "criptografia", "note": ""}, {"word": "vulnerability", "meaning": "vulnerabilidade", "note": ""}, {"word": "ledger", "meaning": "livro-caixa", "note": ""}, {"word": "paradoxically", "meaning": "paradoxalmente", "note": ""}, {"word": "parasites", "meaning": "parasitas", "note": ""}, {"word": "scorn", "meaning": "desprezar", "note": ""}], "exercises": {"grammar": [{"point": "Nothing... more than", "explanation_pt": "'nothing has been more overvalued' é um superlativo negativo."}, {"point": "Only possible in a world where", "explanation_pt": "'deception is only possible in a world where trust is the default' define uma condição."}], "multiple_choice": [{"question": "What does espionage depend on?", "options": ["Weapons", "Trust", "Codes only", "Money"], "correct_index": 1, "explanation": "Confiança."}, {"question": "How was Mehr betrayed?", "options": ["By his boss", "By a friend and a lover", "By a stranger", "By a ferryman"], "correct_index": 1, "explanation": "Por um amigo e uma amante."}, {"question": "Who saved him?", "options": ["A ferryman and a widow", "A priest", "The police", "His family"], "correct_index": 0, "explanation": "Barqueiro e viúva."}, {"question": "What is his argument?", "options": ["Trust is weak", "Deception depends on trust", "Memoirs sell", "Spies are good"], "correct_index": 1, "explanation": "O engano depende da confiança."}, {"question": "What did his estate answer?", "options": ["Take them. Trust is the point", "Wait", "No", "Pay"], "correct_index": 0, "explanation": "'Levem-nos. A confiança é o ponto.'"}], "open_questions": [{"question": "Is trust a weakness or a strength?", "key_points_pt": ["debater"]}, {"question": "Why does betrayal need trust?", "key_points_pt": ["explicar"]}]}}, {"level": "C2", "genre": "spy", "title": "The Understudy", "paragraphs": ["It was an unwritten rule of the service that every agent of consequence should have an understudy, a person trained to inhabit their routines, voice and silences should the original be compromised. Tamsin Reeve had been an understudy for nine years. She had learned to walk with another woman's slightly asymmetrical gait, to mimic her habit of tapping the rim of a cup, to laugh at jokes in precisely the wrong place.", "The principal, a grey, formidable figure known only as Meridian, had never met her double. The arrangement was calculated for efficiency, not intimacy. Yet over the years, Tamsin experienced a peculiar erosion of boundary: she dreamed in Meridian's imagined voice, chose her coffee as Meridian would have chosen it, and occasionally caught herself reaching for a name that belonged to another life.", "When the day finally came, with Meridian dead in a Lisbon hotel under circumstances never fully explained, Tamsin stepped into the role with the serene competence of an actor who had rehearsed for nine years. She attended the meetings, signed the cables, and nobody, not even the most suspicious of deputies, saw the seam.", "It was only in the quiet of the evening that she faltered. Alone in the apartment she had inherited, she opened a drawer and found a note in a handwriting she knew by heart: \"If you are reading this, I have retired from the business of being myself. Be better at it than I was.\" Tamsin sat for a long time with the sheet in her hands, uncertain whether she had inherited an identity or been entrusted with an apology."], "paragraphs_pt": ["Era regra não escrita do serviço que todo agente de importância tivesse um substituto, pessoa treinada para habitar suas rotinas, voz e silêncios caso o original fosse comprometido. Tamsin Reeve fora substituta por nove anos. Aprendera a andar com o passo levemente assimétrico de outra mulher, a imitar seu hábito de bater na borda de uma xícara, a rir de piadas precisamente no lugar errado.", "A titular, uma figura grisalha e formidável conhecida apenas como Meridiano, nunca conhecera sua dupla. O arranjo era calculado para eficiência, não intimidade. Mas ao longo dos anos Tamsin experimentou uma peculiar erosão das fronteiras: sonhava com a voz imaginada de Meridiano, escolhia o café como Meridiano teria escolhido e às vezes se pegava buscando um nome que pertencia a outra vida.", "Quando o dia finalmente chegou, com Meridiano morta num hotel de Lisboa em circunstâncias nunca totalmente explicadas, Tamsin assumiu o papel com a serena competência de uma atriz que ensaiara por nove anos. Participou das reuniões, assinou os telegramas e ninguém, nem mesmo o mais desconfiado dos adjuntos, viu a costura.", "Foi só na quietude da noite que vacilou. Sozinha no apartamento que herdara, abriu uma gaveta e achou um bilhete numa letra que conhecia de cor: \"Se está lendo isto, aposentei-me do negócio de ser eu mesma. Seja melhor nisso do que eu fui.\" Tamsin ficou muito tempo com a folha nas mãos, incerta se herdara uma identidade ou se lhe confiaram um pedido de desculpas."], "hard_words": ["understudy", "gait", "erosion", "faltered"], "vocab": [{"word": "understudy", "meaning": "substituta", "note": ""}, {"word": "compromised", "meaning": "comprometido", "note": ""}, {"word": "gait", "meaning": "passo, andar", "note": ""}, {"word": "formidable", "meaning": "formidável", "note": ""}, {"word": "erosion", "meaning": "erosão", "note": ""}, {"word": "serene", "meaning": "serena", "note": ""}, {"word": "faltered", "meaning": "vacilou", "note": ""}, {"word": "entrusted", "meaning": "confiado", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "been", "are", "being"], "irregular": ["should", "trained", "compromised", "had", "learned", "known", "met", "calculated", "experienced", "dreamed", "imagined", "chose", "would", "chosen", "caught", "belonged", "came", "explained", "stepped", "rehearsed", "attended", "signed", "saw", "faltered", "inherited", "opened", "found", "knew", "retired", "sat", "entrusted"], "phrasal": ["stepped into", "sat for"], "wh": ["who", "when"], "connectors": ["and", "when", "yet", "or", "finally", "if", "as"], "comparative": []}, "word_meanings": [{"word": "understudy", "meaning": "substituta", "note": ""}, {"word": "compromised", "meaning": "comprometido", "note": ""}, {"word": "gait", "meaning": "passo, andar", "note": ""}, {"word": "formidable", "meaning": "formidável", "note": ""}, {"word": "erosion", "meaning": "erosão", "note": ""}, {"word": "serene", "meaning": "serena", "note": ""}, {"word": "faltered", "meaning": "vacilou", "note": ""}, {"word": "entrusted", "meaning": "confiado", "note": ""}], "exercises": {"grammar": [{"point": "Had been an understudy for nine years", "explanation_pt": "'had been an understudy for nine years' mostra um período anterior."}, {"point": "Not... but", "explanation_pt": "'not intimacy' e 'identity or apology' contrastam conceitos."}], "multiple_choice": [{"question": "What is an understudy?", "options": ["A boss", "A trained replacement", "A guard", "A translator"], "correct_index": 1, "explanation": "Um substituto treinado."}, {"question": "How long had Tamsin trained?", "options": ["Twenty years", "Nine years", "One year", "Three months"], "correct_index": 1, "explanation": "Nove anos."}, {"question": "What happened to Meridian?", "options": ["She retired", "She fled", "She was arrested", "She died in a Lisbon hotel"], "correct_index": 3, "explanation": "Morreu num hotel de Lisboa."}, {"question": "What did Tamsin find?", "options": ["A gun", "A key", "A note in Meridian's handwriting", "A map"], "correct_index": 2, "explanation": "Um bilhete."}, {"question": "What is Tamsin uncertain about?", "options": ["Whether to leave", "Whether to travel", "Whether she inherited an identity or an apology", "Whether to tell"], "correct_index": 2, "explanation": "Identidade ou pedido de desculpas."}], "open_questions": [{"question": "What happens to identity when we copy another person?", "key_points_pt": ["refletir"]}, {"question": "Is it possible to 'be better' at being oneself?", "key_points_pt": ["discutir"]}]}}, {"level": "A1", "genre": "superhero", "title": "Captain Sun", "paragraphs": ["Captain Sun is a superhero. He has a yellow cape and a big smile. He can fly very fast.", "One day, a cat is on a tall tree. It is scared. \"Help!\" says the cat. \"Meow!\" Captain Sun flies up.", "He takes the cat in his hands. He puts it on the ground. The cat is happy. \"Thank you, Captain Sun!\" Everybody in the street claps."], "paragraphs_pt": ["O Capitão Sol é um super-herói. Ele tem uma capa amarela e um grande sorriso. Ele sabe voar muito rápido.", "Um dia, um gato está numa árvore alta. Está assustado. \"Socorro!\", diz o gato. \"Miau!\" O Capitão Sol voa até lá.", "Ele pega o gato nas mãos. Coloca-o no chão. O gato está feliz. \"Obrigado, Capitão Sol!\" Todos na rua aplaudem."], "hard_words": ["superhero", "cape", "tall", "scared"], "vocab": [{"word": "superhero", "meaning": "super-herói", "note": ""}, {"word": "cape", "meaning": "capa", "note": ""}, {"word": "smile", "meaning": "sorriso", "note": ""}, {"word": "fly", "meaning": "voar", "note": ""}, {"word": "tall", "meaning": "alto", "note": ""}, {"word": "scared", "meaning": "assustado", "note": ""}, {"word": "claps", "meaning": "aplaude", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": ["scared", "ground"], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "superhero", "meaning": "super-herói", "note": ""}, {"word": "cape", "meaning": "capa", "note": ""}, {"word": "smile", "meaning": "sorriso", "note": ""}, {"word": "fly", "meaning": "voar", "note": ""}, {"word": "tall", "meaning": "alto", "note": ""}, {"word": "scared", "meaning": "assustado", "note": ""}, {"word": "claps", "meaning": "aplaude", "note": ""}], "exercises": {"grammar": [{"point": "Can", "explanation_pt": "'He can fly very fast' diz o que ele consegue fazer."}], "multiple_choice": [{"question": "What color is the cape?", "options": ["Blue", "Red", "Green", "Yellow"], "correct_index": 3, "explanation": "Amarela."}, {"question": "What can Captain Sun do?", "options": ["Swim", "Cook", "Fly fast", "Sing"], "correct_index": 2, "explanation": "Voar rápido."}, {"question": "Where is the cat?", "options": ["In a house", "In a tall tree", "In a river", "In a car"], "correct_index": 1, "explanation": "Numa árvore alta."}, {"question": "What does the superhero do?", "options": ["Helps the cat", "Takes the cat home", "Runs away", "Sleeps"], "correct_index": 0, "explanation": "Ajuda o gato."}, {"question": "What do people do in the street?", "options": ["Run", "Cry", "Sleep", "Clap"], "correct_index": 3, "explanation": "Aplaudem."}], "open_questions": [{"question": "What superpower do you want?", "key_points_pt": ["imaginar"]}, {"question": "Who is your hero?", "key_points_pt": ["falar"]}]}}, {"level": "A1", "genre": "superhero", "title": "Super Mia", "paragraphs": ["Mia is ten years old. She is a normal girl at school. But at night, she is Super Mia. She wears a green mask.", "Super Mia is very strong. She can lift a bus! She helps people in the city. One night, a big truck is on the road. A man cannot move.", "Super Mia lifts the truck. The man is safe. \"Who are you?\" he asks. Mia smiles and flies away. Nobody knows her secret."], "paragraphs_pt": ["Mia tem dez anos. É uma menina normal na escola. Mas à noite, é a Super Mia. Usa uma máscara verde.", "A Super Mia é muito forte. Pode levantar um ônibus! Ajuda as pessoas na cidade. Uma noite, um grande caminhão está na estrada. Um homem não consegue se mexer.", "A Super Mia levanta o caminhão. O homem está a salvo. \"Quem é você?\", pergunta. Mia sorri e sai voando. Ninguém sabe o segredo dela."], "hard_words": ["mask", "lift", "truck", "secret"], "vocab": [{"word": "normal", "meaning": "normal", "note": ""}, {"word": "mask", "meaning": "máscara", "note": ""}, {"word": "strong", "meaning": "forte", "note": ""}, {"word": "lift", "meaning": "levantar", "note": ""}, {"word": "truck", "meaning": "caminhão", "note": ""}, {"word": "road", "meaning": "estrada", "note": ""}, {"word": "secret", "meaning": "segredo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": ["who"], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "normal", "meaning": "normal", "note": ""}, {"word": "mask", "meaning": "máscara", "note": ""}, {"word": "strong", "meaning": "forte", "note": ""}, {"word": "lift", "meaning": "levantar", "note": ""}, {"word": "truck", "meaning": "caminhão", "note": ""}, {"word": "road", "meaning": "estrada", "note": ""}, {"word": "secret", "meaning": "segredo", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "'She wears a green mask' descreve um hábito."}], "multiple_choice": [{"question": "How old is Mia?", "options": ["Fifteen", "Twelve", "Ten", "Five"], "correct_index": 2, "explanation": "Dez."}, {"question": "What color is her mask?", "options": ["Black", "Red", "Green", "Blue"], "correct_index": 2, "explanation": "Verde."}, {"question": "What can she lift?", "options": ["A plane", "A bus", "A house", "A tree"], "correct_index": 1, "explanation": "Um ônibus."}, {"question": "Who needs help?", "options": ["A teacher", "A dog", "A man under a truck", "A child"], "correct_index": 2, "explanation": "Um homem sob um caminhão."}, {"question": "Does anybody know her secret?", "options": ["Her teacher", "Her mom", "No", "Yes"], "correct_index": 2, "explanation": "Ninguém."}], "open_questions": [{"question": "Do you have a secret?", "key_points_pt": ["falar"]}, {"question": "How would you help people if you were strong?", "key_points_pt": ["imaginar"]}]}}, {"level": "A1", "genre": "superhero", "title": "The Little Hero", "paragraphs": ["Ben is five years old. He wears a red cape and a paper hat. He says, \"I am a hero!\" His mother laughs.", "Ben sees a girl crying in the park. She lost her toy. \"I am a hero,\" says Ben. \"I can help you.\" He looks under the bench and finds the toy.", "The girl smiles. \"Thank you!\" she says. Ben feels very proud. His mother takes a photo. Ben is a real hero today."], "paragraphs_pt": ["Ben tem cinco anos. Usa uma capa vermelha e um chapéu de papel. Diz: \"Eu sou um herói!\" A mãe dele ri.", "Ben vê uma menina chorando no parque. Ela perdeu o brinquedo. \"Sou um herói\", diz Ben. \"Posso ajudar você.\" Olha debaixo do banco e acha o brinquedo.", "A menina sorri. \"Obrigada!\", diz. Ben se sente muito orgulhoso. A mãe tira uma foto. Ben é um herói de verdade hoje."], "hard_words": ["hero", "toy", "bench", "proud"], "vocab": [{"word": "hero", "meaning": "herói", "note": ""}, {"word": "paper", "meaning": "papel", "note": ""}, {"word": "crying", "meaning": "chorando", "note": ""}, {"word": "toy", "meaning": "brinquedo", "note": ""}, {"word": "bench", "meaning": "banco", "note": ""}, {"word": "proud", "meaning": "orgulhoso", "note": ""}, {"word": "real", "meaning": "de verdade", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "am"], "irregular": ["lost"], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "hero", "meaning": "herói", "note": ""}, {"word": "paper", "meaning": "papel", "note": ""}, {"word": "crying", "meaning": "chorando", "note": ""}, {"word": "toy", "meaning": "brinquedo", "note": ""}, {"word": "bench", "meaning": "banco", "note": ""}, {"word": "proud", "meaning": "orgulhoso", "note": ""}, {"word": "real", "meaning": "de verdade", "note": ""}], "exercises": {"grammar": [{"point": "Can", "explanation_pt": "'I can help you' oferece ajuda."}], "multiple_choice": [{"question": "How old is Ben?", "options": ["Three", "Eight", "Five", "Ten"], "correct_index": 2, "explanation": "Cinco."}, {"question": "What does Ben wear?", "options": ["A blue mask", "A black suit", "A red cape and paper hat", "A green coat"], "correct_index": 2, "explanation": "Capa vermelha e chapéu de papel."}, {"question": "Why does the girl cry?", "options": ["She is tired", "She is lost", "She is hungry", "She lost her toy"], "correct_index": 3, "explanation": "Perdeu o brinquedo."}, {"question": "Where is the toy?", "options": ["On a bus", "Under the bench", "In a bag", "In the tree"], "correct_index": 1, "explanation": "Debaixo do banco."}, {"question": "How does Ben feel?", "options": ["Angry", "Sad", "Proud", "Scared"], "correct_index": 2, "explanation": "Orgulhoso."}], "open_questions": [{"question": "How can children be heroes?", "key_points_pt": ["explicar"]}, {"question": "Have you helped someone?", "key_points_pt": ["contar"]}]}}, {"level": "A2", "genre": "superhero", "title": "The Day Super Dan Lost His Power", "paragraphs": ["Super Dan woke up one morning and felt strange. He tried to lift his chair, but it was too heavy. He tried to fly out of the window, but he fell on the grass. His super strength was gone! He did not know why.", "Just then, he heard a scream. A little boy was crying in front of a burning house. Dan ran to the house. He couldn't fly or lift anything, but he could still think. He found a ladder, climbed to the second floor and carried the boy's sister out of the window.", "The firefighters arrived and thanked him. \"You are a real hero,\" said the chief. Dan smiled. \"I thought my power was my strength,\" he said. \"Today I learned that my power is my heart.\" The next day, his strength returned, but he never forgot the lesson."], "paragraphs_pt": ["O Super Dan acordou numa manhã e sentiu-se estranho. Tentou levantar a cadeira, mas era pesada demais. Tentou voar pela janela, mas caiu na grama. Sua superforça tinha sumido! Ele não sabia por quê.", "Naquele momento, ouviu um grito. Um menininho chorava diante de uma casa em chamas. Dan correu à casa. Não podia voar nem levantar nada, mas ainda podia pensar. Achou uma escada, subiu ao segundo andar e tirou pela janela a irmã do menino.", "Os bombeiros chegaram e o agradeceram. \"Você é um herói de verdade\", disse o chefe. Dan sorriu. \"Pensei que meu poder fosse minha força\", disse. \"Hoje aprendi que meu poder é meu coração.\" No dia seguinte a força voltou, mas ele nunca esqueceu a lição."], "hard_words": ["strength", "scream", "ladder", "firefighters"], "vocab": [{"word": "strength", "meaning": "força", "note": ""}, {"word": "heavy", "meaning": "pesado", "note": ""}, {"word": "scream", "meaning": "grito", "note": ""}, {"word": "burning", "meaning": "em chamas", "note": ""}, {"word": "ladder", "meaning": "escada", "note": ""}, {"word": "firefighters", "meaning": "bombeiros", "note": ""}, {"word": "chief", "meaning": "chefe", "note": ""}, {"word": "lesson", "meaning": "lição", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "are", "is"], "irregular": ["woke", "felt", "tried", "fell", "gone", "did", "heard", "ran", "could", "found", "climbed", "carried", "arrived", "thanked", "said", "smiled", "thought", "learned", "returned", "forgot"], "phrasal": ["woke up"], "wh": ["why"], "connectors": ["and", "but", "then", "or", "still"], "comparative": []}, "word_meanings": [{"word": "strength", "meaning": "força", "note": ""}, {"word": "heavy", "meaning": "pesado", "note": ""}, {"word": "scream", "meaning": "grito", "note": ""}, {"word": "burning", "meaning": "em chamas", "note": ""}, {"word": "ladder", "meaning": "escada", "note": ""}, {"word": "firefighters", "meaning": "bombeiros", "note": ""}, {"word": "chief", "meaning": "chefe", "note": ""}, {"word": "lesson", "meaning": "lição", "note": ""}], "exercises": {"grammar": [{"point": "Could / couldn't", "explanation_pt": "'He couldn't fly' diz o que não conseguia."}, {"point": "Past simple", "explanation_pt": "'tried', 'found', 'climbed' contam a sequência."}], "multiple_choice": [{"question": "What was wrong with Dan?", "options": ["He was late", "He was sad", "His strength was gone", "He was sick"], "correct_index": 2, "explanation": "A força sumiu."}, {"question": "What did he hear?", "options": ["A bell", "A scream", "A phone", "A song"], "correct_index": 1, "explanation": "Um grito."}, {"question": "How did Dan rescue the girl?", "options": ["By magic", "By lifting the house", "With a ladder", "By flying"], "correct_index": 2, "explanation": "Com uma escada."}, {"question": "What did the chief say?", "options": ["Go home", "You are late", "Sorry", "You are a real hero"], "correct_index": 3, "explanation": "'Você é um herói de verdade.'"}, {"question": "What did Dan learn?", "options": ["He needs rest", "He is weak", "His power is his heart", "He is old"], "correct_index": 2, "explanation": "Seu poder é o coração."}], "open_questions": [{"question": "Is courage more important than strength?", "key_points_pt": ["opinar"]}, {"question": "When did you do something brave?", "key_points_pt": ["contar"]}]}}, {"level": "A2", "genre": "superhero", "title": "The Boy Who Could Talk to Pigeons", "paragraphs": ["Leo had a strange power: he could talk to pigeons. At first, he thought it was normal, but nobody else understood the birds. They told him secrets about the city: where the best bread was, which streets were dirty and what people said on the benches.", "One afternoon, a pigeon landed on his shoulder, very agitated. \"A thief stole an old woman's bag near the fountain!\" it said. Leo followed the pigeons through the streets. They flew above the thief and showed him the way.", "Leo called the police and told them where to go. The thief was caught in five minutes, and the old woman got her bag back. The next day, hundreds of pigeons waited outside Leo's window. \"Thank you,\" they said. \"We are your friends.\" Leo smiled and gave them some bread."], "paragraphs_pt": ["Leo tinha um poder estranho: falava com pombos. A princípio achou normal, mas ninguém mais entendia as aves. Elas lhe contavam segredos da cidade: onde estava o melhor pão, que ruas estavam sujas e o que as pessoas diziam nos bancos.", "Uma tarde, um pombo pousou em seu ombro, muito agitado. \"Um ladrão roubou a bolsa de uma velhinha perto da fonte!\", disse. Leo seguiu os pombos pelas ruas. Eles voaram sobre o ladrão e mostraram o caminho.", "Leo chamou a polícia e disse aonde ir. O ladrão foi pego em cinco minutos e a velhinha recebeu a bolsa de volta. No dia seguinte, centenas de pombos esperavam do lado de fora da janela de Leo. \"Obrigado\", disseram. \"Somos seus amigos.\" Leo sorriu e deu-lhes pão."], "hard_words": ["pigeons", "agitated", "thief", "hundreds"], "vocab": [{"word": "power", "meaning": "poder", "note": ""}, {"word": "pigeons", "meaning": "pombos", "note": ""}, {"word": "secrets", "meaning": "segredos", "note": ""}, {"word": "agitated", "meaning": "agitado", "note": ""}, {"word": "thief", "meaning": "ladrão", "note": ""}, {"word": "fountain", "meaning": "fonte", "note": ""}, {"word": "caught", "meaning": "pego", "note": ""}, {"word": "hundreds", "meaning": "centenas", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "are"], "irregular": ["had", "could", "thought", "understood", "told", "said", "landed", "agitated", "stole", "followed", "flew", "showed", "called", "caught", "got", "waited", "smiled", "gave"], "phrasal": [], "wh": ["what", "where", "which"], "connectors": ["and", "but"], "comparative": []}, "word_meanings": [{"word": "power", "meaning": "poder", "note": ""}, {"word": "pigeons", "meaning": "pombos", "note": ""}, {"word": "secrets", "meaning": "segredos", "note": ""}, {"word": "agitated", "meaning": "agitado", "note": ""}, {"word": "thief", "meaning": "ladrão", "note": ""}, {"word": "fountain", "meaning": "fonte", "note": ""}, {"word": "caught", "meaning": "pego", "note": ""}, {"word": "hundreds", "meaning": "centenas", "note": ""}], "exercises": {"grammar": [{"point": "Could", "explanation_pt": "'he could talk to pigeons' diz sua habilidade."}, {"point": "Past simple", "explanation_pt": "'landed', 'followed', 'called' contam o resgate."}], "multiple_choice": [{"question": "What was Leo's power?", "options": ["Talking to pigeons", "Flying", "Invisibility", "Reading minds"], "correct_index": 0, "explanation": "Falar com pombos."}, {"question": "What did the pigeon say?", "options": ["It was lost", "A thief stole a bag", "It was sick", "It was hungry"], "correct_index": 1, "explanation": "Um ladrão roubou uma bolsa."}, {"question": "How did Leo find the thief?", "options": ["A map", "A camera", "A dog", "Following the pigeons"], "correct_index": 3, "explanation": "Seguindo os pombos."}, {"question": "What did Leo do?", "options": ["Called the police", "Caught the thief himself", "Ran", "Hid"], "correct_index": 0, "explanation": "Chamou a polícia."}, {"question": "What did Leo give the pigeons?", "options": ["Seeds", "Bread", "Money", "Water"], "correct_index": 1, "explanation": "Pão."}], "open_questions": [{"question": "What animal would you like to talk to?", "key_points_pt": ["imaginar"]}, {"question": "What would animals tell you?", "key_points_pt": ["imaginar"]}]}}, {"level": "B1", "genre": "superhero", "title": "The Retired Hero", "paragraphs": ["When Victor Strong retired, the whole city gathered in the square to thank him. For thirty years, he had protected them from villains, floods and a giant robot. Now he was sixty, his knees ached, and the mayor handed him a golden key to the city. He smiled, but he felt lost.", "Retirement was harder than he had expected. He tried gardening, but accidentally lifted a tree with his bare hands. He tried cooking classes, but he broke three pans. Every night, he listened to the police radio, longing to help. His neighbours, who knew who he was, treated him politely and kept their distance.", "One evening, a young girl knocked at his door. She was eleven and wanted to be a hero. \"I have no powers,\" she said, \"but I want to help people.\" Victor thought about it for a long time. Then he said, \"Then you already have the most important one.\"", "He started to train her, not in fighting, but in observing, listening and staying calm. Years later, she became the city's new guardian. Victor watched from the crowd, no longer lost. He had understood that being a hero did not mean saving everyone. It meant teaching others how to do it."], "paragraphs_pt": ["Quando Victor Strong se aposentou, a cidade toda se reuniu na praça para agradecer. Por trinta anos, o protegera de vilões, enchentes e um robô gigante. Agora tinha sessenta anos, os joelhos doíam e o prefeito lhe entregou uma chave de ouro da cidade. Sorriu, mas se sentia perdido.", "A aposentadoria foi mais difícil que esperava. Tentou jardinagem, mas levantou sem querer uma árvore com as próprias mãos. Tentou aulas de culinária, mas quebrou três panelas. Toda noite escutava o rádio da polícia, ansiando ajudar. Os vizinhos, que sabiam quem era, o tratavam com educação e mantinham distância.", "Numa tarde, uma menina bateu à porta. Tinha onze anos e queria ser heroína. \"Não tenho poderes\", disse, \"mas quero ajudar as pessoas.\" Victor pensou por muito tempo. Então disse: \"Então você já tem o mais importante.\"", "Começou a treiná-la, não em lutar, mas em observar, ouvir e manter a calma. Anos depois, ela se tornou a nova guardiã da cidade. Victor olhava da multidão, já não perdido. Entendera que ser herói não era salvar todos. Era ensinar outros a fazê-lo."], "hard_words": ["villains", "ached", "longing", "guardian"], "vocab": [{"word": "retired", "meaning": "aposentou-se", "note": ""}, {"word": "villains", "meaning": "vilões", "note": ""}, {"word": "floods", "meaning": "enchentes", "note": ""}, {"word": "ached", "meaning": "doíam", "note": ""}, {"word": "longing", "meaning": "ansiando", "note": ""}, {"word": "neighbours", "meaning": "vizinhos", "note": ""}, {"word": "guardian", "meaning": "guardiã", "note": ""}, {"word": "crowd", "meaning": "multidão", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "being"], "irregular": ["retired", "gathered", "had", "protected", "ached", "handed", "smiled", "felt", "lost", "expected", "tried", "lifted", "broke", "listened", "knew", "treated", "kept", "knocked", "wanted", "said", "thought", "started", "became", "watched", "understood", "did", "meant"], "phrasal": ["gathered in", "kept their distance"], "wh": ["who", "when", "how"], "connectors": ["and", "but", "then", "when"], "comparative": []}, "word_meanings": [{"word": "retired", "meaning": "aposentou-se", "note": ""}, {"word": "villains", "meaning": "vilões", "note": ""}, {"word": "floods", "meaning": "enchentes", "note": ""}, {"word": "ached", "meaning": "doíam", "note": ""}, {"word": "longing", "meaning": "ansiando", "note": ""}, {"word": "neighbours", "meaning": "vizinhos", "note": ""}, {"word": "guardian", "meaning": "guardiã", "note": ""}, {"word": "crowd", "meaning": "multidão", "note": ""}], "exercises": {"grammar": [{"point": "Had protected", "explanation_pt": "'he had protected them for thirty years' mostra um passado anterior."}, {"point": "Not... but", "explanation_pt": "'not in fighting, but in observing' contrasta dois treinos."}], "multiple_choice": [{"question": "Why did the city gather?", "options": ["To celebrate a festival", "To elect a mayor", "To fight", "To thank Victor"], "correct_index": 3, "explanation": "Para agradecer a Victor."}, {"question": "Why was retirement hard?", "options": ["He was poor", "He felt lost", "He was famous", "He was sick"], "correct_index": 1, "explanation": "Sentia-se perdido."}, {"question": "Who knocked at his door?", "options": ["A villain", "The mayor", "A reporter", "A young girl"], "correct_index": 3, "explanation": "Uma menina."}, {"question": "What did he train her in?", "options": ["Flying", "Building", "Observing and staying calm", "Fighting"], "correct_index": 2, "explanation": "Observar e manter calma."}, {"question": "What did he understand?", "options": ["Heroes must be young", "Heroes must be rich", "Heroes must fight", "Being a hero means teaching others"], "correct_index": 3, "explanation": "Ensinar outros."}], "open_questions": [{"question": "How can older people help the young?", "key_points_pt": ["explicar"]}, {"question": "What do you do after you finish something big?", "key_points_pt": ["contar"]}]}}, {"level": "B1", "genre": "superhero", "title": "The Invisible Girl at School", "paragraphs": ["Nadia had always been shy, but when she discovered she could turn invisible, she thought her life would change. She imagined herself spying on teachers, avoiding exams and playing tricks on her classmates. For a week, she enjoyed all of it. But gradually, she began to feel strangely lonely.", "One afternoon, in the cafeteria, she watched her best friend, Tess, sitting alone, looking at her phone with sad eyes. Nadia realised that Tess was upset because Nadia had been avoiding her. She felt ashamed. Making herself visible, she walked to the table and sat down.", "\"Where have you been?\" asked Tess, hurt. Nadia had no excuse. \"I was hiding,\" she said. \"I thought it was easier to be invisible than to be myself.\" Tess squeezed her hand. \"I've always seen you,\" she said. \"Even when you thought I didn't.\"", "From then on, Nadia used her power only to help, such as returning lost homework or leaving anonymous notes of encouragement. She learned that the greatest superpower was not disappearing, but being willing to be seen."], "paragraphs_pt": ["Nadia sempre fora tímida, mas quando descobriu que podia ficar invisível, achou que sua vida mudaria. Imaginou-se espionando professores, evitando provas e pregando peças nos colegas. Por uma semana, aproveitou tudo. Mas aos poucos começou a se sentir estranhamente só.", "Numa tarde, na cantina, viu sua melhor amiga, Tess, sentada sozinha, olhando o celular com olhos tristes. Nadia percebeu que Tess estava chateada porque ela vinha a evitando. Sentiu vergonha. Tornando-se visível, caminhou até a mesa e sentou.", "\"Por onde você andou?\", perguntou Tess, magoada. Nadia não tinha desculpa. \"Estava me escondendo\", disse. \"Achei mais fácil ser invisível do que ser eu mesma.\" Tess apertou a mão dela. \"Sempre te vi\", disse. \"Mesmo quando você achava que não.\"", "Dali em diante, Nadia usou o poder apenas para ajudar, como devolver lições perdidas ou deixar bilhetes anônimos de incentivo. Aprendeu que o maior superpoder não era sumir, mas estar disposta a ser vista."], "hard_words": ["invisible", "upset", "ashamed", "anonymous"], "vocab": [{"word": "invisible", "meaning": "invisível", "note": ""}, {"word": "shy", "meaning": "tímida", "note": ""}, {"word": "spying", "meaning": "espionando", "note": ""}, {"word": "cafeteria", "meaning": "cantina", "note": ""}, {"word": "upset", "meaning": "chateada", "note": ""}, {"word": "ashamed", "meaning": "envergonhada", "note": ""}, {"word": "excuse", "meaning": "desculpa", "note": ""}, {"word": "anonymous", "meaning": "anônimo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "be", "being"], "irregular": ["had", "discovered", "could", "thought", "would", "imagined", "enjoyed", "began", "watched", "realised", "felt", "walked", "sat", "asked", "said", "squeezed", "seen", "used", "lost", "learned"], "phrasal": ["sat down", "squeezed her hand"], "wh": ["where", "when"], "connectors": ["and", "but", "because", "then", "when", "or", "as"], "comparative": []}, "word_meanings": [{"word": "invisible", "meaning": "invisível", "note": ""}, {"word": "shy", "meaning": "tímida", "note": ""}, {"word": "spying", "meaning": "espionando", "note": ""}, {"word": "cafeteria", "meaning": "cantina", "note": ""}, {"word": "upset", "meaning": "chateada", "note": ""}, {"word": "ashamed", "meaning": "envergonhada", "note": ""}, {"word": "excuse", "meaning": "desculpa", "note": ""}, {"word": "anonymous", "meaning": "anônimo", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'Nadia had always been shy' mostra um estado anterior."}, {"point": "Present perfect", "explanation_pt": "'Where have you been?' pergunta sobre o período até agora."}], "multiple_choice": [{"question": "What power did Nadia discover?", "options": ["Strength", "Speed", "Invisibility", "Flying"], "correct_index": 2, "explanation": "Invisibilidade."}, {"question": "Why did she feel lonely?", "options": ["She had no friends", "She avoided her friend", "She moved", "She was sick"], "correct_index": 1, "explanation": "Evitava a amiga."}, {"question": "What did Nadia say?", "options": ["It was easier to be invisible than myself", "I am sorry for the exam", "I hate school", "I am tired"], "correct_index": 0, "explanation": "Mais fácil ser invisível."}, {"question": "What did Tess answer?", "options": ["You are wrong", "Leave", "I don't care", "I've always seen you"], "correct_index": 3, "explanation": "'Sempre te vi.'"}, {"question": "What is the greatest superpower?", "options": ["Hiding", "Flying", "Strength", "Being willing to be seen"], "correct_index": 3, "explanation": "Estar disposta a ser vista."}], "open_questions": [{"question": "Why do people hide in groups?", "key_points_pt": ["explicar"]}, {"question": "Have you felt invisible?", "key_points_pt": ["contar"]}]}}, {"level": "B2", "genre": "superhero", "title": "The Insurance Claim", "paragraphs": ["Few people appreciate the bureaucratic difficulties of living in a city defended by superheroes. Mrs. Okafor, an administrator at the municipal insurance office, had spent six years processing claims for damage caused by the heroic battles that disturbed the neighbourhood: collapsed bridges, melted cars and, on one occasion, a lamppost thrown through a bakery window.", "When Captain Radiance, the city's most famous protector, filed a claim for his own broken ribs, Mrs. Okafor reacted with a mixture of professional courtesy and weariness. \"Your policy excludes damage resulting from fights with extraterrestrials,\" she told him, scrolling through the form. \"However, it covers 'incidents involving aerial vehicles'.\" The Captain frowned. \"I was flying.\"", "They spent twenty minutes debating whether a flying man was a vehicle. Eventually, Mrs. Okafor approved the claim, adding in the notes: \"Unconventional case. Recommend a revision of the policy.\" She did not tell the Captain that she had approved dozens of similar requests with equally creative interpretations.", "That evening, watching the news about a battle downtown, she felt a strange pride. Without heroes there would be no explosions, but without paperwork there would be no rebuilding. It occurred to her that civilisation was the quiet cooperation of those who saved the day and those who filled in the forms afterward."], "paragraphs_pt": ["Poucos apreciam as dificuldades burocráticas de viver numa cidade defendida por super-heróis. A Sra. Okafor, administradora do escritório de seguros municipal, passara seis anos processando pedidos de indenização por danos causados pelas batalhas heroicas que perturbavam o bairro: pontes desabadas, carros derretidos e, em uma ocasião, um poste atirado numa vitrine de padaria.", "Quando o Capitão Radiância, o protetor mais famoso da cidade, entrou com um pedido pelas próprias costelas quebradas, a Sra. Okafor reagiu com mistura de cortesia profissional e cansaço. \"Sua apólice exclui danos resultantes de lutas com extraterrestres\", disse, rolando o formulário. \"Porém, cobre 'incidentes envolvendo veículos aéreos'.\" O Capitão franziu a testa. \"Eu estava voando.\"", "Passaram vinte minutos debatendo se um homem voando era um veículo. Por fim, a Sra. Okafor aprovou o pedido, anotando: \"Caso não convencional. Recomenda-se revisão da apólice.\" Não contou ao Capitão que aprovara dezenas de pedidos semelhantes com interpretações igualmente criativas.", "Naquela noite, vendo o noticiário sobre uma batalha no centro, sentiu um orgulho estranho. Sem heróis não haveria explosões, mas sem papelada não haveria reconstrução. Ocorreu-lhe que a civilização era a cooperação silenciosa dos que salvavam o dia e dos que preenchiam os formulários depois."], "hard_words": ["bureaucratic", "claims", "policy", "unconventional"], "vocab": [{"word": "bureaucratic", "meaning": "burocráticas", "note": ""}, {"word": "claims", "meaning": "pedidos de indenização", "note": ""}, {"word": "collapsed", "meaning": "desabadas", "note": ""}, {"word": "policy", "meaning": "apólice", "note": ""}, {"word": "excludes", "meaning": "exclui", "note": ""}, {"word": "extraterrestrials", "meaning": "extraterrestres", "note": ""}, {"word": "unconventional", "meaning": "não convencional", "note": ""}, {"word": "paperwork", "meaning": "papelada", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be"], "irregular": ["defended", "had", "spent", "caused", "disturbed", "collapsed", "melted", "thrown", "filed", "broken", "reacted", "told", "frowned", "approved", "did", "felt", "would", "occurred", "saved", "filled"], "phrasal": ["filled in", "scrolling through"], "wh": ["who", "when"], "connectors": ["and", "but", "however", "when"], "comparative": []}, "word_meanings": [{"word": "bureaucratic", "meaning": "burocráticas", "note": ""}, {"word": "claims", "meaning": "pedidos de indenização", "note": ""}, {"word": "collapsed", "meaning": "desabadas", "note": ""}, {"word": "policy", "meaning": "apólice", "note": ""}, {"word": "excludes", "meaning": "exclui", "note": ""}, {"word": "extraterrestrials", "meaning": "extraterrestres", "note": ""}, {"word": "unconventional", "meaning": "não convencional", "note": ""}, {"word": "paperwork", "meaning": "papelada", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'had spent six years processing claims' mostra um período anterior."}, {"point": "Without... there would be", "explanation_pt": "'Without heroes there would be no explosions' é uma condicional implícita."}], "multiple_choice": [{"question": "What is Mrs. Okafor's job?", "options": ["Lawyer", "Reporter", "Insurance administrator", "Hero"], "correct_index": 2, "explanation": "Administradora de seguros."}, {"question": "What did Captain Radiance claim?", "options": ["A phone", "A house", "A car", "Broken ribs"], "correct_index": 3, "explanation": "Costelas quebradas."}, {"question": "What did the policy exclude?", "options": ["Fights with extraterrestrials", "Floods", "Fires", "Cars"], "correct_index": 0, "explanation": "Lutas com extraterrestres."}, {"question": "What did she do?", "options": ["Quit", "Refused", "Approved with creative interpretation", "Called the police"], "correct_index": 2, "explanation": "Aprovou com interpretação criativa."}, {"question": "What did she realise?", "options": ["Forms are boring", "Heroes are useless", "Cities are weak", "Civilisation needs heroes and paperwork"], "correct_index": 3, "explanation": "Civilização precisa de heróis e papelada."}], "open_questions": [{"question": "Who are the 'invisible heroes' of a city?", "key_points_pt": ["discutir"]}, {"question": "What would superhero life be like in reality?", "key_points_pt": ["imaginar"]}]}}, {"level": "B2", "genre": "superhero", "title": "The Hero Who Hated Mornings", "paragraphs": ["Everyone knew that Thunder-Girl could stop a train with one hand, but fewer people knew that she was dreadfully late for everything. Her manager scheduled rescues with a half-hour margin, since the city's most reliable heroine had been seen arriving at emergencies in her pyjamas, a half-eaten sandwich in her hand.", "Her problem was not laziness but exhaustion. Fighting crime at night and working as an accountant by day had reduced her sleep to four hours. She was suffering from the same fatigue as any overworked person, except that the consequences of her mistakes included the occasional demolished building.", "One morning, she fell asleep on top of a skyscraper, only waking when a pigeon landed on her nose. Alarmed, she realised that she could not continue like this. After a candid conversation with her manager, she decided to resign from her day job. For the first time, she slept eight hours.", "Her performance improved dramatically, and her tardiness all but vanished. The newspapers wrote about \"the new Thunder-Girl\", as if she had gained fresh powers. She smiled, because the secret was embarrassingly simple: even a person who could stop a train needed a good night's sleep."], "paragraphs_pt": ["Todos sabiam que a Garota-Trovão podia parar um trem com uma mão, mas poucos sabiam que ela chegava terrivelmente atrasada a tudo. Sua empresária agendava os resgates com meia hora de margem, pois a heroína mais confiável da cidade fora vista chegando a emergências de pijama, com um sanduíche mordido na mão.", "O problema não era preguiça, mas exaustão. Combater o crime à noite e trabalhar como contadora de dia reduzira seu sono a quatro horas. Sofria do mesmo cansaço de qualquer pessoa sobrecarregada, exceto que as consequências de seus erros incluíam o prédio demolido ocasional.", "Certa manhã, adormeceu no topo de um arranha-céu, acordando só quando um pombo pousou em seu nariz. Alarmada, percebeu que não podia continuar assim. Após uma conversa franca com a empresária, decidiu pedir demissão do emprego diurno. Pela primeira vez, dormiu oito horas.", "O desempenho melhorou drasticamente e os atrasos quase sumiram. Os jornais falaram da \"nova Garota-Trovão\", como se tivesse ganhado novos poderes. Ela sorriu, pois o segredo era embaraçosamente simples: até quem para um trem precisa de uma boa noite de sono."], "hard_words": ["exhaustion", "fatigue", "candid", "tardiness"], "vocab": [{"word": "dreadfully", "meaning": "terrivelmente", "note": ""}, {"word": "margin", "meaning": "margem", "note": ""}, {"word": "exhaustion", "meaning": "exaustão", "note": ""}, {"word": "accountant", "meaning": "contadora", "note": ""}, {"word": "fatigue", "meaning": "cansaço", "note": ""}, {"word": "skyscraper", "meaning": "arranha-céu", "note": ""}, {"word": "candid", "meaning": "franca", "note": ""}, {"word": "tardiness", "meaning": "atrasos", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been"], "irregular": ["knew", "could", "scheduled", "had", "seen", "eaten", "reduced", "overworked", "included", "demolished", "fell", "landed", "alarmed", "realised", "decided", "slept", "improved", "vanished", "wrote", "gained", "smiled", "needed"], "phrasal": ["fell asleep", "resign from"], "wh": ["who", "when"], "connectors": ["and", "but", "because", "after", "when", "since", "if", "as"], "comparative": []}, "word_meanings": [{"word": "dreadfully", "meaning": "terrivelmente", "note": ""}, {"word": "margin", "meaning": "margem", "note": ""}, {"word": "exhaustion", "meaning": "exaustão", "note": ""}, {"word": "accountant", "meaning": "contadora", "note": ""}, {"word": "fatigue", "meaning": "cansaço", "note": ""}, {"word": "skyscraper", "meaning": "arranha-céu", "note": ""}, {"word": "candid", "meaning": "franca", "note": ""}, {"word": "tardiness", "meaning": "atrasos", "note": ""}], "exercises": {"grammar": [{"point": "Had been seen + ing", "explanation_pt": "'had been seen arriving at emergencies in her pyjamas' mostra fatos anteriores."}, {"point": "Not... but", "explanation_pt": "'not laziness but exhaustion' contrasta duas causas."}], "multiple_choice": [{"question": "What was Thunder-Girl's problem?", "options": ["She was weak", "She was lazy", "She was always late", "She was afraid"], "correct_index": 2, "explanation": "Chegava atrasada."}, {"question": "What was the real cause?", "options": ["Illness", "Laziness", "Exhaustion", "Fear"], "correct_index": 2, "explanation": "Exaustão."}, {"question": "What job did she have by day?", "options": ["Doctor", "Accountant", "Teacher", "Police"], "correct_index": 1, "explanation": "Contadora."}, {"question": "What did she decide?", "options": ["Stop fighting crime", "Resign from her day job", "Retire", "Move"], "correct_index": 1, "explanation": "Pedir demissão do emprego diurno."}, {"question": "What was the secret?", "options": ["New powers", "A new manager", "A good night's sleep", "A new suit"], "correct_index": 2, "explanation": "Uma boa noite de sono."}], "open_questions": [{"question": "Do you get enough sleep?", "key_points_pt": ["falar"]}, {"question": "Why do heroes also need rest?", "key_points_pt": ["explicar"]}]}}, {"level": "B2", "genre": "superhero", "title": "The Hero Who Lost His Voice", "paragraphs": ["Ricardo, known as the Sonic Guardian, owed his fame to a single gift: a voice that could shatter glass, stop falling debris or lull an army to sleep. Throughout his career, he used it with precision, as a surgeon uses a scalpel. Then, one autumn, he woke up with a sore throat that refused to heal. Within a month, his voice had disappeared.", "The silence was terrifying. For the first time, Ricardo had to rely on other talents, and he discovered, with some embarrassment, that he had few. He could barely cook, had no hobbies and didn't know the names of his neighbours. His identity, he realised, had been reduced to a single note.", "Months of therapy followed, as well as long walks in the countryside. During one of them, he met an old blind woman who played the flute at a train station. Listening to her, he noticed how she used silence between the notes. \"A song is made of what you leave out,\" she said.", "When his voice partly returned, it was hoarse and fragile, and the shattering power had vanished. Ricardo became a teacher of music for children, not as a hero but as a modest man. He often told his students that the loudest gift was not necessarily the best one."], "paragraphs_pt": ["Ricardo, conhecido como o Guardião Sônico, devia sua fama a um único dom: uma voz que podia estilhaçar vidro, deter escombros em queda ou ninar um exército. Ao longo da carreira, usava-a com precisão, como um cirurgião usa um bisturi. Então, num outono, acordou com uma dor de garganta que se recusava a sarar. Em um mês, a voz havia desaparecido.", "O silêncio era aterrador. Pela primeira vez, Ricardo teve de contar com outros talentos e descobriu, com certo embaraço, que tinha poucos. Mal sabia cozinhar, não tinha hobbies e não sabia o nome dos vizinhos. Sua identidade, percebeu, fora reduzida a uma única nota.", "Seguiram-se meses de terapia e longas caminhadas pelo campo. Numa delas, encontrou uma velha cega que tocava flauta numa estação. Ouvindo-a, notou como ela usava o silêncio entre as notas. \"Uma canção é feita do que se deixa de fora\", disse ela.", "Quando a voz voltou em parte, era rouca e frágil, e o poder estilhaçante se fora. Ricardo tornou-se professor de música para crianças, não como herói, mas como homem modesto. Frequentemente dizia aos alunos que o dom mais alto não era necessariamente o melhor."], "hard_words": ["shatter", "debris", "hoarse", "modest"], "vocab": [{"word": "shatter", "meaning": "estilhaçar", "note": ""}, {"word": "debris", "meaning": "escombros", "note": ""}, {"word": "lull", "meaning": "ninar", "note": ""}, {"word": "scalpel", "meaning": "bisturi", "note": ""}, {"word": "sore throat", "meaning": "dor de garganta", "note": ""}, {"word": "therapy", "meaning": "terapia", "note": ""}, {"word": "hoarse", "meaning": "rouca", "note": ""}, {"word": "modest", "meaning": "modesto", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been", "is"], "irregular": ["known", "owed", "could", "used", "woke", "refused", "had", "disappeared", "discovered", "realised", "reduced", "followed", "met", "played", "noticed", "made", "said", "returned", "vanished", "became", "told"], "phrasal": ["woke up with", "rely on"], "wh": ["who", "what", "when", "how"], "connectors": ["as well as", "and", "but", "then", "when", "or", "as"], "comparative": []}, "word_meanings": [{"word": "shatter", "meaning": "estilhaçar", "note": ""}, {"word": "debris", "meaning": "escombros", "note": ""}, {"word": "lull", "meaning": "ninar", "note": ""}, {"word": "scalpel", "meaning": "bisturi", "note": ""}, {"word": "sore throat", "meaning": "dor de garganta", "note": ""}, {"word": "therapy", "meaning": "terapia", "note": ""}, {"word": "hoarse", "meaning": "rouca", "note": ""}, {"word": "modest", "meaning": "modesto", "note": ""}], "exercises": {"grammar": [{"point": "Owed to", "explanation_pt": "'owed his fame to a single gift' atribui a causa da fama."}, {"point": "As well as", "explanation_pt": "'as well as long walks' acrescenta algo."}], "multiple_choice": [{"question": "What was Ricardo's power?", "options": ["Strength", "Invisibility", "A voice that could shatter glass", "Flight"], "correct_index": 2, "explanation": "Voz que estilhaça vidro."}, {"question": "What happened one autumn?", "options": ["He lost his voice", "He retired", "He lost a battle", "He moved"], "correct_index": 0, "explanation": "Perdeu a voz."}, {"question": "What did he discover about himself?", "options": ["He was rich", "He was strong", "He was old", "He had few other talents"], "correct_index": 3, "explanation": "Tinha poucos outros talentos."}, {"question": "What did the blind woman say?", "options": ["Leave", "A song is made of what you leave out", "Sing more", "Play louder"], "correct_index": 1, "explanation": "'Uma canção é feita do que se deixa de fora.'"}, {"question": "What did Ricardo become?", "options": ["A music teacher", "A doctor", "A pilot", "A cook"], "correct_index": 0, "explanation": "Professor de música."}], "open_questions": [{"question": "What defines you apart from your talent?", "key_points_pt": ["refletir"]}, {"question": "Can losing something lead to growth?", "key_points_pt": ["discutir"]}]}}, {"level": "C1", "genre": "superhero", "title": "The Burden of Capes", "paragraphs": ["It is a curious fact of metropolitan life that the people who save us from catastrophe are rarely thanked in any form that lasts. Marguerite Vale, a historian of what the press called \"costumed intervention,\" had spent a decade interviewing retired heroes, and the pattern she found was disconcertingly consistent: gratitude is intense in the moment and evaporates by the following week.", "One of her subjects, an elderly man who had once prevented a dam from bursting, described the phenomenon without bitterness. \"People don't want to be reminded that they were vulnerable,\" he said. \"Every time they see me, they remember the water.\" He had therefore learned to avoid crowded streets and to use public transport only at dawn, like a ghost haunting his own achievements.", "Marguerite concluded that the hero's isolation was less a by-product of the profession than its structure. To save a city is to witness its fragility, and nobody enjoys the company of the witness. The most successful heroes, she argued, were those who found some source of recognition independent of the public: a craft, a family, a private discipline.", "Her book, which she titled \"The Burden of Capes,\" sold modestly and was quickly forgotten, a fate she accepted with a rueful smile. She had learned from her subjects that being unthanked was not the same as being unnecessary, and that some of the most important work leaves no monument but the absence of disaster."], "paragraphs_pt": ["É um fato curioso da vida metropolitana que as pessoas que nos salvam da catástrofe raramente sejam agradecidas de alguma forma duradoura. Marguerite Vale, historiadora do que a imprensa chamava de \"intervenção fantasiada\", passara uma década entrevistando heróis aposentados, e o padrão que encontrou foi desconcertantemente consistente: a gratidão é intensa no momento e evapora na semana seguinte.", "Um de seus entrevistados, um idoso que um dia impedira uma barragem de romper, descreveu o fenômeno sem amargura. \"As pessoas não querem ser lembradas de que estiveram vulneráveis\", disse. \"Toda vez que me veem, lembram da água.\" Aprendera, portanto, a evitar ruas cheias e a usar transporte público só ao amanhecer, como um fantasma assombrando suas próprias realizações.", "Marguerite concluiu que o isolamento do herói era menos subproduto da profissão que sua estrutura. Salvar uma cidade é testemunhar sua fragilidade, e ninguém gosta da companhia da testemunha. Os heróis mais bem-sucedidos, argumentou, eram os que achavam alguma fonte de reconhecimento independente do público: um ofício, uma família, uma disciplina privada.", "Seu livro, que intitulou \"O Peso das Capas\", vendeu modestamente e foi logo esquecido, destino que aceitou com sorriso pesaroso. Aprendera com os entrevistados que não ser agradecido não é o mesmo que ser desnecessário e que parte do trabalho mais importante não deixa monumento além da ausência de desastre."], "hard_words": ["disconcertingly", "evaporates", "by-product", "rueful"], "vocab": [{"word": "metropolitan", "meaning": "metropolitana", "note": ""}, {"word": "intervention", "meaning": "intervenção", "note": ""}, {"word": "disconcertingly", "meaning": "desconcertantemente", "note": ""}, {"word": "evaporates", "meaning": "evapora", "note": ""}, {"word": "vulnerable", "meaning": "vulnerável", "note": ""}, {"word": "by-product", "meaning": "subproduto", "note": ""}, {"word": "fragility", "meaning": "fragilidade", "note": ""}, {"word": "rueful", "meaning": "pesaroso", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are", "was", "be", "were", "being"], "irregular": ["thanked", "called", "costumed", "had", "spent", "retired", "found", "prevented", "described", "reminded", "said", "learned", "crowded", "concluded", "argued", "titled", "sold", "forgotten", "accepted"], "phrasal": ["haunting"], "wh": ["who", "what", "which"], "connectors": ["and", "but", "therefore", "once", "as"], "comparative": []}, "word_meanings": [{"word": "metropolitan", "meaning": "metropolitana", "note": ""}, {"word": "intervention", "meaning": "intervenção", "note": ""}, {"word": "disconcertingly", "meaning": "desconcertantemente", "note": ""}, {"word": "evaporates", "meaning": "evapora", "note": ""}, {"word": "vulnerable", "meaning": "vulnerável", "note": ""}, {"word": "by-product", "meaning": "subproduto", "note": ""}, {"word": "fragility", "meaning": "fragilidade", "note": ""}, {"word": "rueful", "meaning": "pesaroso", "note": ""}], "exercises": {"grammar": [{"point": "Less... than", "explanation_pt": "'less a by-product than its structure' compara duas explicações."}, {"point": "Not the same as", "explanation_pt": "'not being unthanked is not the same as being unnecessary' distingue ideias."}], "multiple_choice": [{"question": "What did Marguerite study?", "options": ["Doctors", "Teachers", "Retired heroes", "Politicians"], "correct_index": 2, "explanation": "Heróis aposentados."}, {"question": "What pattern did she find?", "options": ["Heroes are loved", "Heroes are rich", "Heroes retire early", "Gratitude evaporates quickly"], "correct_index": 3, "explanation": "A gratidão evapora."}, {"question": "Why do people avoid the hero?", "options": ["He is rude", "They remember being vulnerable", "He is famous", "He is strange"], "correct_index": 1, "explanation": "Lembram da vulnerabilidade."}, {"question": "What did successful heroes have?", "options": ["A source of recognition independent of the public", "A weapon", "Money", "Fame"], "correct_index": 0, "explanation": "Reconhecimento próprio."}, {"question": "What did the book teach her?", "options": ["Heroes are myths", "Being unthanked is not being unnecessary", "Cities forget", "Books sell"], "correct_index": 1, "explanation": "Não ser agradecido não é ser desnecessário."}], "open_questions": [{"question": "Why do we forget those who save us?", "key_points_pt": ["discutir"]}, {"question": "Which work in your community goes unnoticed?", "key_points_pt": ["refletir"]}]}}, {"level": "C1", "genre": "superhero", "title": "The Mask and the Face", "paragraphs": ["At the age of thirty-two, Lucien Ferrand realised that he had become better at being the Phantom than at being Lucien. The mask had begun as a convenience, a way of protecting his family from retaliation, but over time it had absorbed his decisiveness, his wit, and the unhesitating courage that had never quite survived in his unmasked hours.", "His wife, Hélène, noticed the asymmetry with the diplomacy of someone who has loved a complicated man for years. \"You are kinder to strangers in the cape,\" she said one evening, \"than to me in the kitchen.\" It was said without reproach, but it lodged like a splinter. He tried to explain that heroism required a certain detachment, but the argument sounded thin even to himself.", "For months, he experimented with a reversal: wearing the mask less, speaking more openly, allowing himself to be uncertain in front of the people he loved. The experience was awkward, and on more than one occasion, the city suffered from the Phantom's absence. Hélène watched him struggle with a tenderness that was almost painful.", "It would be gratifying to report a tidy resolution, but there was none. Lucien eventually found a compromise, putting on the mask three nights a week and removing it with deliberate ceremony before entering the house. What changed was not the balance of his life but his awareness that courage, if it exists, must be able to live without a disguise."], "paragraphs_pt": ["Aos trinta e dois anos, Lucien Ferrand percebeu que se tornara melhor em ser o Fantasma do que em ser Lucien. A máscara começara como uma conveniência, uma forma de proteger a família de retaliação, mas com o tempo absorvera sua decisão, seu humor e a coragem sem hesitação que nunca sobrevivera totalmente em suas horas sem máscara.", "A esposa, Hélène, notou a assimetria com a diplomacia de quem amou por anos um homem complicado. \"Você é mais gentil com estranhos de capa\", disse numa noite, \"do que comigo na cozinha.\" Foi dito sem reprovação, mas se alojou como uma farpa. Ele tentou explicar que o heroísmo exigia certo distanciamento, mas o argumento soou fraco até para ele.", "Por meses, experimentou uma inversão: usar menos a máscara, falar mais abertamente, permitir-se incerteza diante dos que amava. A experiência foi desajeitada e, mais de uma vez, a cidade sofreu com a ausência do Fantasma. Hélène o via lutar com uma ternura quase dolorosa.", "Seria gratificante relatar uma resolução organizada, mas não houve. Lucien eventualmente achou um meio-termo, pondo a máscara três noites por semana e tirando-a com cerimônia deliberada antes de entrar em casa. O que mudou não foi o equilíbrio da vida, mas a consciência de que a coragem, se existe, deve poder viver sem disfarce."], "hard_words": ["retaliation", "asymmetry", "splinter", "detachment"], "vocab": [{"word": "retaliation", "meaning": "retaliação", "note": ""}, {"word": "absorbed", "meaning": "absorvera", "note": ""}, {"word": "decisiveness", "meaning": "decisão", "note": ""}, {"word": "asymmetry", "meaning": "assimetria", "note": ""}, {"word": "reproach", "meaning": "reprovação", "note": ""}, {"word": "splinter", "meaning": "farpa", "note": ""}, {"word": "detachment", "meaning": "distanciamento", "note": ""}, {"word": "compromise", "meaning": "meio-termo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["being", "are", "was", "be"], "irregular": ["realised", "had", "begun", "absorbed", "survived", "unmasked", "noticed", "loved", "complicated", "said", "lodged", "tried", "required", "sounded", "experimented", "suffered", "watched", "would", "found", "changed"], "phrasal": ["lodged like"], "wh": ["who", "what"], "connectors": ["and", "but", "before", "if", "as"], "comparative": []}, "word_meanings": [{"word": "retaliation", "meaning": "retaliação", "note": ""}, {"word": "absorbed", "meaning": "absorvera", "note": ""}, {"word": "decisiveness", "meaning": "decisão", "note": ""}, {"word": "asymmetry", "meaning": "assimetria", "note": ""}, {"word": "reproach", "meaning": "reprovação", "note": ""}, {"word": "splinter", "meaning": "farpa", "note": ""}, {"word": "detachment", "meaning": "distanciamento", "note": ""}, {"word": "compromise", "meaning": "meio-termo", "note": ""}], "exercises": {"grammar": [{"point": "Had become better at", "explanation_pt": "'had become better at being the Phantom than at being Lucien' compara duas identidades."}, {"point": "Not... but", "explanation_pt": "'not the balance of his life but his awareness' contrasta o que mudou."}], "multiple_choice": [{"question": "What did Lucien realise at thirty-two?", "options": ["He was weak", "He was rich", "He was tired", "He was better as the Phantom"], "correct_index": 3, "explanation": "Era melhor como Fantasma."}, {"question": "What did Hélène say?", "options": ["He was cold", "He was kinder to strangers than to her", "He was too serious", "He was late"], "correct_index": 1, "explanation": "Era mais gentil com estranhos."}, {"question": "What did he experiment with?", "options": ["Moving", "Training", "Wearing the mask less", "Quitting"], "correct_index": 2, "explanation": "Usar menos a máscara."}, {"question": "What happened to the city?", "options": ["It celebrated", "It improved", "Nothing", "It suffered from the Phantom's absence"], "correct_index": 3, "explanation": "Sofreu sem o Fantasma."}, {"question": "What compromise did he find?", "options": ["Wearing it always", "Three nights a week, removing it before home", "Selling it", "Never wearing it"], "correct_index": 1, "explanation": "Três noites por semana."}], "open_questions": [{"question": "Do we behave differently in different roles?", "key_points_pt": ["refletir"]}, {"question": "Can courage exist without a disguise?", "key_points_pt": ["debater"]}]}}, {"level": "C1", "genre": "superhero", "title": "The Statue of the Unknown Hero", "paragraphs": ["In the central square of the city stood a bronze statue of the Unknown Hero, erected a century earlier in gratitude for a deed that nobody could specify. The inscription, worn by rain, read only: \"To the one who saved us.\" Historians had searched the archives in vain; whether the hero had stopped a fire, halted an epidemic or turned back an invader, the records were silent.", "This ambiguity, curiously, had made the monument beloved. Every citizen could project onto it the courage they most admired. Schoolchildren left drawings at its base; widows brought flowers; and on stormy nights, the elderly claimed that the statue seemed to lean into the wind like a guardian.", "The scandal erupted when a young researcher discovered, in a forgotten ledger, a name and a profession: a municipal clerk who had warned the city of an approaching flood and been ignored until the last moment. He had, with unglamorous persistence, persuaded the authorities to evacuate the lower districts. Nobody had fought anything; nobody had been rescued by force.", "The council debated replacing the inscription. In the end, they decided against it. The statue continued to stand, and the ledger was displayed in a glass case beside it, an arrangement that pleased nobody and moved everybody. Citizens had discovered that heroism may be quieter than they believed and that the most heroic act may be to insist, politely and repeatedly, that something be done."], "paragraphs_pt": ["Na praça central da cidade erguia-se uma estátua de bronze do Herói Desconhecido, erigida um século antes em gratidão por um feito que ninguém sabia especificar. A inscrição, gasta pela chuva, dizia apenas: \"Àquele que nos salvou.\" Historiadores haviam vasculhado os arquivos em vão; se o herói detivera um incêndio, estancara uma epidemia ou repelira um invasor, os registros eram mudos.", "Essa ambiguidade, curiosamente, tornara o monumento querido. Cada cidadão podia projetar nele a coragem que mais admirava. Crianças deixavam desenhos na base; viúvas traziam flores; e em noites de tempestade, os idosos afirmavam que a estátua parecia se inclinar contra o vento como um guardião.", "O escândalo explodiu quando um jovem pesquisador descobriu, num livro-caixa esquecido, um nome e uma profissão: um funcionário municipal que avisara a cidade de uma enchente iminente e fora ignorado até o último momento. Ele, com persistência pouco glamorosa, convencera as autoridades a evacuar os distritos baixos. Ninguém lutara contra nada; ninguém fora resgatado à força.", "O conselho debateu substituir a inscrição. No fim, decidiu contra. A estátua continuou de pé e o livro-caixa foi exposto numa vitrine ao lado, arranjo que não agradou a ninguém e comoveu a todos. Os cidadãos haviam descoberto que o heroísmo pode ser mais silencioso do que acreditavam e que o ato mais heroico pode ser insistir, com educação e repetidamente, que algo seja feito."], "hard_words": ["erected", "inscription", "ambiguity", "evacuate"], "vocab": [{"word": "erected", "meaning": "erigida", "note": ""}, {"word": "deed", "meaning": "feito", "note": ""}, {"word": "inscription", "meaning": "inscrição", "note": ""}, {"word": "ambiguity", "meaning": "ambiguidade", "note": ""}, {"word": "epidemic", "meaning": "epidemia", "note": ""}, {"word": "ledger", "meaning": "livro-caixa", "note": ""}, {"word": "evacuate", "meaning": "evacuar", "note": ""}, {"word": "unglamorous", "meaning": "pouco glamoroso", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["were", "been", "was", "be"], "irregular": ["stood", "erected", "could", "worn", "saved", "had", "searched", "stopped", "halted", "turned", "made", "admired", "left", "brought", "claimed", "seemed", "erupted", "discovered", "forgotten", "warned", "ignored", "persuaded", "fought", "rescued", "debated", "decided", "continued", "displayed", "pleased", "moved", "believed", "done"], "phrasal": ["turned back", "lean into"], "wh": ["who", "when"], "connectors": ["and", "when", "until", "or"], "comparative": []}, "word_meanings": [{"word": "erected", "meaning": "erigida", "note": ""}, {"word": "deed", "meaning": "feito", "note": ""}, {"word": "inscription", "meaning": "inscrição", "note": ""}, {"word": "ambiguity", "meaning": "ambiguidade", "note": ""}, {"word": "epidemic", "meaning": "epidemia", "note": ""}, {"word": "ledger", "meaning": "livro-caixa", "note": ""}, {"word": "evacuate", "meaning": "evacuar", "note": ""}, {"word": "unglamorous", "meaning": "pouco glamoroso", "note": ""}], "exercises": {"grammar": [{"point": "Whether... or", "explanation_pt": "'whether the hero had stopped a fire, halted an epidemic or turned back an invader' apresenta alternativas."}, {"point": "Nobody had + particípio", "explanation_pt": "'Nobody had fought anything' nega ações anteriores."}], "multiple_choice": [{"question": "What did the statue's inscription say?", "options": ["To the king", "To the mayor", "To the one who saved us", "To the brave"], "correct_index": 2, "explanation": "'Àquele que nos salvou.'"}, {"question": "Why was the statue beloved?", "options": ["It was old", "The ambiguity allowed projection", "It was big", "It was beautiful"], "correct_index": 1, "explanation": "A ambiguidade permitia projeção."}, {"question": "What did the researcher discover?", "options": ["The hero was a clerk who warned of a flood", "The hero was a soldier", "The hero was a king", "The hero was a doctor"], "correct_index": 0, "explanation": "Funcionário que avisou da enchente."}, {"question": "What did the council decide?", "options": ["To remove the statue", "To sell it", "To rename the square", "Not to replace the inscription"], "correct_index": 3, "explanation": "Não substituir a inscrição."}, {"question": "What did citizens learn?", "options": ["Heroism can be quiet", "Floods are rare", "Heroes are fake", "History is false"], "correct_index": 0, "explanation": "Heroísmo pode ser silencioso."}], "open_questions": [{"question": "What counts as heroism?", "key_points_pt": ["debater"]}, {"question": "Who deserves a statue in your town?", "key_points_pt": ["opinar"]}]}}, {"level": "C2", "genre": "superhero", "title": "The Arithmetic of Rescue", "paragraphs": ["There is a calculus, seldom discussed in the cheerful literature of caped crusaders, that every rescuer must eventually perform. Seraphine Ode, a hero of extraordinary capability, had been taught to perform it at a young age, when a collapsing bridge presented her with two cars and a single available moment. She chose one. The other fell. For years she saw the second car whenever she closed her eyes.", "The public, naturally, saw only the saved. They celebrated her with parades and merchandise, a cheerful ignorance that she found at once consoling and unbearable. In private, she maintained a ledger of those she had been unable to reach, not out of masochism but out of a conviction that forgetting would constitute a second death.", "It was an interviewer, a young woman with a disconcerting gift for silence, who finally asked her the question no one had dared. \"Do you regret the choice?\" Seraphine considered it for what felt like an hour. \"Regret assumes a better option existed,\" she said at last. \"I carry it instead. The difference is subtle, but it is the difference between guilt and responsibility.\"", "After the interview, she did something unexpected. She founded a foundation, not for heroes but for the families of those who could not be saved, offering them what the parades never had: an acknowledgement. Years later, a woman approached her at a ceremony and said only, \"Thank you for remembering.\" Seraphine nodded, and for the first time, the second car did not appear when she closed her eyes."], "paragraphs_pt": ["Há um cálculo, raramente discutido na literatura alegre dos cruzados de capa, que todo salvador deve eventualmente fazer. Seraphine Ode, heroína de capacidade extraordinária, fora ensinada a fazê-lo cedo, quando uma ponte desabando lhe apresentou dois carros e um único momento disponível. Escolheu um. O outro caiu. Por anos viu o segundo carro sempre que fechava os olhos.", "O público, naturalmente, via apenas os salvos. Celebravam-na com desfiles e produtos, uma ignorância alegre que ela achava ao mesmo tempo consoladora e insuportável. Em privado, mantinha um registro dos que não conseguira alcançar, não por masoquismo, mas por convicção de que esquecer seria uma segunda morte.", "Foi uma entrevistadora, jovem com um dom desconcertante para o silêncio, que enfim fez a pergunta que ninguém ousara. \"A senhora se arrepende da escolha?\" Seraphine considerou por o que pareceu uma hora. \"Arrependimento pressupõe que existisse uma opção melhor\", disse por fim. \"Eu a carrego, em vez disso. A diferença é sutil, mas é a diferença entre culpa e responsabilidade.\"", "Depois da entrevista, fez algo inesperado. Fundou uma fundação, não para heróis, mas para as famílias dos que não puderam ser salvos, oferecendo-lhes o que os desfiles nunca deram: um reconhecimento. Anos depois, uma mulher a abordou numa cerimônia e disse apenas: \"Obrigada por lembrar.\" Seraphine assentiu e, pela primeira vez, o segundo carro não apareceu quando fechou os olhos."], "hard_words": ["calculus", "consoling", "disconcerting", "acknowledgement"], "vocab": [{"word": "calculus", "meaning": "cálculo", "note": ""}, {"word": "crusaders", "meaning": "cruzados", "note": ""}, {"word": "merchandise", "meaning": "produtos", "note": ""}, {"word": "consoling", "meaning": "consoladora", "note": ""}, {"word": "masochism", "meaning": "masoquismo", "note": ""}, {"word": "disconcerting", "meaning": "desconcertante", "note": ""}, {"word": "foundation", "meaning": "fundação", "note": ""}, {"word": "acknowledgement", "meaning": "reconhecimento", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "been", "was", "be"], "irregular": ["discussed", "had", "taught", "presented", "chose", "fell", "saw", "closed", "saved", "celebrated", "found", "maintained", "would", "asked", "dared", "considered", "felt", "existed", "said", "did", "founded", "could", "approached", "nodded"], "phrasal": ["closed her eyes"], "wh": ["who", "what", "when", "whenever"], "connectors": ["and", "but", "instead", "after", "when", "finally", "once", "whenever"], "comparative": []}, "word_meanings": [{"word": "calculus", "meaning": "cálculo", "note": ""}, {"word": "crusaders", "meaning": "cruzados", "note": ""}, {"word": "merchandise", "meaning": "produtos", "note": ""}, {"word": "consoling", "meaning": "consoladora", "note": ""}, {"word": "masochism", "meaning": "masoquismo", "note": ""}, {"word": "disconcerting", "meaning": "desconcertante", "note": ""}, {"word": "foundation", "meaning": "fundação", "note": ""}, {"word": "acknowledgement", "meaning": "reconhecimento", "note": ""}], "exercises": {"grammar": [{"point": "Had been taught", "explanation_pt": "'had been taught to perform it at a young age' mostra aprendizado anterior."}, {"point": "Regret assumes...", "explanation_pt": "'Regret assumes a better option existed' define arrependimento por pressuposto."}], "multiple_choice": [{"question": "What choice did Seraphine face?", "options": ["A flood", "A war", "A fire", "Two cars on a collapsing bridge"], "correct_index": 3, "explanation": "Dois carros numa ponte."}, {"question": "What did the public see?", "options": ["Her tears", "Her failure", "Nothing", "Only the saved"], "correct_index": 3, "explanation": "Só os salvos."}, {"question": "What is the difference she mentions?", "options": ["Hero versus villain", "Past versus future", "Fear versus love", "Guilt versus responsibility"], "correct_index": 3, "explanation": "Culpa versus responsabilidade."}, {"question": "What did she found?", "options": ["A museum", "A foundation for families of those not saved", "A school", "A hospital"], "correct_index": 1, "explanation": "Fundação para famílias."}, {"question": "What changed for her?", "options": ["The second car stopped appearing", "She retired", "She moved", "She married"], "correct_index": 0, "explanation": "O segundo carro parou de aparecer."}], "open_questions": [{"question": "Is guilt the same as responsibility?", "key_points_pt": ["debater"]}, {"question": "How should society remember those who are not saved?", "key_points_pt": ["discutir"]}]}}, {"level": "C2", "genre": "superhero", "title": "The Last Costume", "paragraphs": ["When the final cape had been folded and the last mask placed in its glass case, the curator of the Museum of Heroic Artefacts permitted himself a moment of contemplation. The exhibition, assembled over six years, celebrated an era that was by common consent finished. Technology, regulation and an increasingly sceptical public had made the costumed vigilante an anachronism, a figure of nostalgia like the lamplighter or the town crier.", "Visitors responded in varied ways. Children darted between the cabinets with the unselfconscious wonder of those who still suspect that such things might be real. Adults lingered, silent, before the dented helmets, aware that they were contemplating not so much a costume as an aspiration. Historians took notes and disputed provenance.", "One afternoon, an elderly woman paused before a modest grey jacket in a corner display. The label described it as the \"everyday garment of an unidentified volunteer, circa 1950.\" She read it twice, then told the attendant, without drama: \"That's my father's.\" The attendant, startled, asked what he had done. \"Nothing anyone wrote down,\" she said. \"He drove people to the hospital during the floods.\"", "The curator, overhearing, quietly revised the label. The jacket remained in the corner, but henceforth it bore a new inscription: \"For those who did what was needed and left no name.\" Many visitors said afterward that it was the only exhibit that moved them, and perhaps the only one that matched what heroism had always been: not a costume, but a habit of showing up."], "paragraphs_pt": ["Quando a última capa foi dobrada e a última máscara colocada em sua vitrine, o curador do Museu de Artefatos Heroicos permitiu-se um momento de contemplação. A exposição, montada em seis anos, celebrava uma era que, por consenso comum, havia terminado. A tecnologia, a regulamentação e um público cada vez mais cético haviam tornado o justiceiro fantasiado um anacronismo, uma figura de nostalgia como o acendedor de lampiões ou o pregoeiro da cidade.", "Os visitantes reagiam de modos variados. As crianças corriam entre as vitrines com o encanto sem constrangimento de quem ainda suspeita que tais coisas podem ser reais. Os adultos demoravam-se, silenciosos, diante dos capacetes amassados, cientes de que contemplavam não tanto uma fantasia quanto uma aspiração. Historiadores faziam anotações e disputavam a procedência.", "Numa tarde, uma senhora idosa parou diante de uma modesta jaqueta cinza numa exposição de canto. A etiqueta a descrevia como \"peça cotidiana de um voluntário não identificado, por volta de 1950.\" Leu duas vezes e disse ao atendente, sem drama: \"É do meu pai.\" O atendente, surpreso, perguntou o que ele fizera. \"Nada que alguém tenha escrito\", disse. \"Levava pessoas ao hospital durante as enchentes.\"", "O curador, ouvindo, revisou discretamente a etiqueta. A jaqueta permaneceu no canto, mas daí em diante levou uma nova inscrição: \"Aos que fizeram o necessário e não deixaram nome.\" Muitos visitantes disseram depois que era a única peça que os comoveu e talvez a única que correspondia ao que o heroísmo sempre fora: não uma fantasia, mas um hábito de aparecer."], "hard_words": ["anachronism", "aspiration", "provenance", "startled"], "vocab": [{"word": "curator", "meaning": "curador", "note": ""}, {"word": "artefacts", "meaning": "artefatos", "note": ""}, {"word": "vigilante", "meaning": "justiceiro", "note": ""}, {"word": "anachronism", "meaning": "anacronismo", "note": ""}, {"word": "aspiration", "meaning": "aspiração", "note": ""}, {"word": "provenance", "meaning": "procedência", "note": ""}, {"word": "startled", "meaning": "surpreso", "note": ""}, {"word": "inscription", "meaning": "inscrição", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["been", "was", "be", "were"], "irregular": ["had", "folded", "placed", "permitted", "assembled", "celebrated", "finished", "made", "costumed", "responded", "varied", "darted", "might", "lingered", "dented", "took", "disputed", "paused", "described", "told", "startled", "asked", "done", "wrote", "said", "drove", "revised", "remained", "bore", "did", "needed", "left", "moved", "matched"], "phrasal": ["paused before", "showing up"], "wh": ["who", "what", "when"], "connectors": ["and", "but", "so", "then", "before", "when", "or", "still", "as"], "comparative": []}, "word_meanings": [{"word": "curator", "meaning": "curador", "note": ""}, {"word": "artefacts", "meaning": "artefatos", "note": ""}, {"word": "vigilante", "meaning": "justiceiro", "note": ""}, {"word": "anachronism", "meaning": "anacronismo", "note": ""}, {"word": "aspiration", "meaning": "aspiração", "note": ""}, {"word": "provenance", "meaning": "procedência", "note": ""}, {"word": "startled", "meaning": "surpreso", "note": ""}, {"word": "inscription", "meaning": "inscrição", "note": ""}], "exercises": {"grammar": [{"point": "Passive e perfect", "explanation_pt": "'The exhibition, assembled over six years' usa particípio para dar contexto."}, {"point": "Not so much... as", "explanation_pt": "'not so much a costume as an aspiration' compara o que se contemplava."}], "multiple_choice": [{"question": "What did the museum celebrate?", "options": ["An era of costumed heroes", "Wars", "Old cars", "Space travel"], "correct_index": 0, "explanation": "Uma era de heróis fantasiados."}, {"question": "Why was the era over?", "options": ["Technology and a sceptical public", "A war", "A flood", "Lack of money"], "correct_index": 0, "explanation": "Tecnologia e público cético."}, {"question": "What did the old woman recognise?", "options": ["A helmet", "Her father's jacket", "A mask", "A cape"], "correct_index": 1, "explanation": "A jaqueta do pai."}, {"question": "What had her father done?", "options": ["Drove people to the hospital in floods", "Fought villains", "Built a bridge", "Flew"], "correct_index": 0, "explanation": "Levava pessoas ao hospital."}, {"question": "What was the new inscription?", "options": ["Be brave", "In memory", "Heroes forever", "For those who did what was needed and left no name"], "correct_index": 3, "explanation": "'Aos que fizeram o necessário.'"}], "open_questions": [{"question": "What does heroism look like in daily life?", "key_points_pt": ["explicar"]}, {"question": "Why do we like stories of costumed heroes?", "key_points_pt": ["discutir"]}]}}, {"level": "B1", "genre": "superhero", "title": "The Sidekick's Day Off", "paragraphs": ["Everyone knew Blaze, the fastest hero in the city, but few remembered his sidekick, Pip. Pip carried the equipment, found the addresses and made sure Blaze didn't forget his lunch. After five years, he was tired of being invisible, and one Monday morning, he announced that he was taking the day off.", "Blaze laughed, thinking it was a joke. But Pip packed his bag and left. Without him, the day became a disaster. Blaze arrived at a robbery without his mask, got lost on the way to a fire and ordered a sandwich so large that he couldn't fight afterward. By evening, he was exhausted and humiliated.", "He found Pip at the park, reading a book on a bench. \"I was wrong,\" said Blaze. \"I thought I was the hero, but you were the one who made it possible.\" Pip looked up, surprised. \"That's the nicest thing you've ever said to me.\"", "From then on, Blaze insisted on sharing the credit. The newspapers began to print both names, and children started to buy two kinds of masks. Pip kept his day off every Monday, and, to everyone's surprise, the city seemed no less safe."], "paragraphs_pt": ["Todos conheciam o Blaze, o herói mais rápido da cidade, mas poucos lembravam do seu ajudante, Pip. Pip carregava o equipamento, achava os endereços e garantia que Blaze não esquecesse o almoço. Após cinco anos, cansou de ser invisível e numa segunda de manhã anunciou que tirava o dia de folga.", "Blaze riu, achando que era piada. Mas Pip arrumou a mochila e saiu. Sem ele, o dia virou um desastre. Blaze chegou a um assalto sem a máscara, perdeu-se a caminho de um incêndio e pediu um sanduíche tão grande que não pôde lutar depois. À noite, estava exausto e humilhado.", "Achou Pip no parque, lendo um livro num banco. \"Eu estava errado\", disse Blaze. \"Pensei que era o herói, mas você tornava tudo possível.\" Pip olhou para cima, surpreso. \"É a coisa mais gentil que já me disse.\"", "Dali em diante, Blaze insistiu em dividir o crédito. Os jornais passaram a imprimir os dois nomes e as crianças começaram a comprar dois tipos de máscaras. Pip manteve sua folga toda segunda e, para surpresa geral, a cidade não pareceu menos segura."], "hard_words": ["sidekick", "equipment", "exhausted", "credit"], "vocab": [{"word": "sidekick", "meaning": "ajudante", "note": ""}, {"word": "equipment", "meaning": "equipamento", "note": ""}, {"word": "announced", "meaning": "anunciou", "note": ""}, {"word": "disaster", "meaning": "desastre", "note": ""}, {"word": "exhausted", "meaning": "exausto", "note": ""}, {"word": "humiliated", "meaning": "humilhado", "note": ""}, {"word": "credit", "meaning": "crédito", "note": ""}, {"word": "bench", "meaning": "banco", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being", "were"], "irregular": ["knew", "remembered", "carried", "found", "made", "tired", "announced", "laughed", "packed", "left", "became", "arrived", "got", "lost", "ordered", "exhausted", "humiliated", "said", "thought", "looked", "surprised", "insisted", "began", "started", "kept", "seemed"], "phrasal": ["packed his bag", "looked up"], "wh": ["who"], "connectors": ["and", "but", "so", "then", "after"], "comparative": []}, "word_meanings": [{"word": "sidekick", "meaning": "ajudante", "note": ""}, {"word": "equipment", "meaning": "equipamento", "note": ""}, {"word": "announced", "meaning": "anunciou", "note": ""}, {"word": "disaster", "meaning": "desastre", "note": ""}, {"word": "exhausted", "meaning": "exausto", "note": ""}, {"word": "humiliated", "meaning": "humilhado", "note": ""}, {"word": "credit", "meaning": "crédito", "note": ""}, {"word": "bench", "meaning": "banco", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'laughed', 'packed', 'left' contam a sequência."}, {"point": "From then on", "explanation_pt": "'From then on, Blaze insisted' marca mudança permanente."}], "multiple_choice": [{"question": "Who is Pip?", "options": ["A villain", "Blaze's sidekick", "A mayor", "A teacher"], "correct_index": 1, "explanation": "O ajudante de Blaze."}, {"question": "What did Pip announce?", "options": ["A day off", "A trip", "A fight", "He quit forever"], "correct_index": 0, "explanation": "Folga."}, {"question": "What happened to Blaze without Pip?", "options": ["He won", "He rested", "The day became a disaster", "He flew"], "correct_index": 2, "explanation": "O dia virou desastre."}, {"question": "What did Blaze say?", "options": ["You are late", "Come back or leave", "I am the best", "I was wrong"], "correct_index": 3, "explanation": "'Eu estava errado.'"}, {"question": "What changed?", "options": ["The city closed", "Blaze shared the credit", "Pip left", "Blaze retired"], "correct_index": 1, "explanation": "Dividiram o crédito."}], "open_questions": [{"question": "Why do helpers deserve credit?", "key_points_pt": ["explicar"]}, {"question": "Have you been an unseen helper?", "key_points_pt": ["contar"]}]}}, {"level": "C2", "genre": "superhero", "title": "The Weight of Flight", "paragraphs": ["Flight, in the fantasies of ordinary people, is the epitome of freedom. Naomi Achterberg, who could soar at will above the clouds, knew a less poetic truth: that altitude is a form of exile. From a height of three thousand feet, human beings acquire the dimension of ants, their disputes shrink into insignificance and their suffering becomes dangerously abstract.", "She had noticed this on her earliest patrols, with a mixture of seduction and alarm. Up there, she could save a collapsing building without ever hearing the voices of the people inside. She could win a battle without learning the name of the person she had defeated. The sky offered competence at the cost of intimacy, a trade she found increasingly hard to justify.", "Determined to resist the drift, she imposed a discipline upon herself: for every hour aloft, one hour on foot, walking the neighbourhoods she protected, drinking coffee in the cafés, listening to tedious grievances about parking. The citizens found this peculiar and, at first, faintly disappointing. They preferred a goddess to a neighbour.", "But in time, they grew accustomed to her, and something remarkable occurred. When disaster struck, they no longer saw a distant saviour but a person who knew their streets. Naomi realised that her greatest power was not that she could rise above the city but that she had chosen to descend into it, again and again, for no better reason than that someone had to."], "paragraphs_pt": ["O voo, nas fantasias das pessoas comuns, é o epítome da liberdade. Naomi Achterberg, que podia planar à vontade acima das nuvens, conhecia uma verdade menos poética: que a altitude é uma forma de exílio. De uma altura de três mil pés, os seres humanos adquirem a dimensão de formigas, suas disputas encolhem à insignificância e seu sofrimento se torna perigosamente abstrato.", "Notara isso em suas primeiras patrulhas, com mistura de sedução e alarme. Lá em cima, podia salvar um prédio desabando sem jamais ouvir as vozes de quem estava dentro. Podia vencer uma batalha sem saber o nome de quem derrotara. O céu oferecia competência ao custo da intimidade, troca que achava cada vez mais difícil justificar.", "Decidida a resistir à deriva, impôs-se uma disciplina: para cada hora no ar, uma hora a pé, percorrendo os bairros que protegia, tomando café nas cafeterias, ouvindo queixas tediosas sobre estacionamento. Os cidadãos acharam isso peculiar e, a princípio, levemente decepcionante. Preferiam uma deusa a uma vizinha.", "Mas com o tempo se acostumaram com ela, e algo notável ocorreu. Quando o desastre vinha, já não viam um salvador distante, mas uma pessoa que conhecia suas ruas. Naomi percebeu que seu maior poder não era poder se elevar acima da cidade, mas ter escolhido descer a ela, de novo e de novo, sem melhor razão que a de que alguém precisava fazê-lo."], "hard_words": ["epitome", "exile", "intimacy", "grievances"], "vocab": [{"word": "epitome", "meaning": "epítome", "note": ""}, {"word": "exile", "meaning": "exílio", "note": ""}, {"word": "insignificance", "meaning": "insignificância", "note": ""}, {"word": "seduction", "meaning": "sedução", "note": ""}, {"word": "intimacy", "meaning": "intimidade", "note": ""}, {"word": "grievances", "meaning": "queixas", "note": ""}, {"word": "goddess", "meaning": "deusa", "note": ""}, {"word": "descend", "meaning": "descer", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "was"], "irregular": ["could", "knew", "had", "noticed", "defeated", "offered", "found", "determined", "imposed", "protected", "preferred", "grew", "accustomed", "occurred", "struck", "saw", "realised", "chosen"], "phrasal": ["grew accustomed to"], "wh": ["who", "when"], "connectors": ["and", "but", "when"], "comparative": []}, "word_meanings": [{"word": "epitome", "meaning": "epítome", "note": ""}, {"word": "exile", "meaning": "exílio", "note": ""}, {"word": "insignificance", "meaning": "insignificância", "note": ""}, {"word": "seduction", "meaning": "sedução", "note": ""}, {"word": "intimacy", "meaning": "intimidade", "note": ""}, {"word": "grievances", "meaning": "queixas", "note": ""}, {"word": "goddess", "meaning": "deusa", "note": ""}, {"word": "descend", "meaning": "descer", "note": ""}], "exercises": {"grammar": [{"point": "Not... but", "explanation_pt": "'not that she could rise... but that she had chosen to descend' contrasta duas ideias."}, {"point": "For every... one", "explanation_pt": "'for every hour aloft, one hour on foot' mostra proporção."}], "multiple_choice": [{"question": "What is altitude, for Naomi?", "options": ["A game", "Pure freedom", "A weapon", "A form of exile"], "correct_index": 3, "explanation": "Uma forma de exílio."}, {"question": "What did the sky offer?", "options": ["Love", "Competence at the cost of intimacy", "Peace", "Danger"], "correct_index": 1, "explanation": "Competência ao custo da intimidade."}, {"question": "What discipline did she impose?", "options": ["Only battles", "Flying only at night", "An hour on foot for each hour aloft", "No flying"], "correct_index": 2, "explanation": "Uma hora a pé por hora no ar."}, {"question": "How did citizens first react?", "options": ["Indifferent", "Faintly disappointed", "Angry", "Delighted"], "correct_index": 1, "explanation": "Levemente decepcionados."}, {"question": "What was her greatest power?", "options": ["Strength", "Flying", "Speed", "Choosing to descend into the city"], "correct_index": 3, "explanation": "Escolher descer à cidade."}], "open_questions": [{"question": "Why does distance reduce empathy?", "key_points_pt": ["discutir"]}, {"question": "Why do leaders need to be close to those they serve?", "key_points_pt": ["debater"]}]}}, {"level": "A1", "genre": "suspense", "title": "The Dark Room", "paragraphs": ["Sara is at home. It is night. She hears a noise in the dark room. She is afraid.", "She takes a flashlight. She walks slowly to the door. The door is open. Something moves in the corner!", "Sara looks. It is her small brother, Tim. He has a toy monster. \"Boo!\" he says. Sara laughs and says, \"You are a bad boy!\" Then she hugs him."], "paragraphs_pt": ["Sara está em casa. É noite. Ouve um barulho no quarto escuro. Tem medo.", "Pega uma lanterna. Caminha devagar até a porta. A porta está aberta. Algo se move no canto!", "Sara olha. É seu irmãozinho, Tim. Ele tem um monstro de brinquedo. \"Buuu!\", diz. Sara ri e diz: \"Você é um menino mau!\" Depois o abraça."], "hard_words": ["noise", "flashlight", "corner", "monster"], "vocab": [{"word": "dark", "meaning": "escuro", "note": ""}, {"word": "noise", "meaning": "barulho", "note": ""}, {"word": "afraid", "meaning": "com medo", "note": ""}, {"word": "flashlight", "meaning": "lanterna", "note": ""}, {"word": "corner", "meaning": "canto", "note": ""}, {"word": "monster", "meaning": "monstro", "note": ""}, {"word": "hugs", "meaning": "abraça", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "are"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and", "then"], "comparative": []}, "word_meanings": [{"word": "dark", "meaning": "escuro", "note": ""}, {"word": "noise", "meaning": "barulho", "note": ""}, {"word": "afraid", "meaning": "com medo", "note": ""}, {"word": "flashlight", "meaning": "lanterna", "note": ""}, {"word": "corner", "meaning": "canto", "note": ""}, {"word": "monster", "meaning": "monstro", "note": ""}, {"word": "hugs", "meaning": "abraça", "note": ""}], "exercises": {"grammar": [{"point": "Present simple", "explanation_pt": "'She hears a noise' descreve ação no presente."}], "multiple_choice": [{"question": "When is the story?", "options": ["In the evening", "At night", "In the morning", "At noon"], "correct_index": 1, "explanation": "À noite."}, {"question": "What does Sara hear?", "options": ["A noise", "A phone", "A song", "A bell"], "correct_index": 0, "explanation": "Um barulho."}, {"question": "What does she take?", "options": ["A book", "A flashlight", "A phone", "A knife"], "correct_index": 1, "explanation": "Uma lanterna."}, {"question": "Who is in the room?", "options": ["A ghost", "Her brother", "A cat", "A thief"], "correct_index": 1, "explanation": "O irmãozinho."}, {"question": "What does Tim have?", "options": ["A key", "A dog", "A cake", "A toy monster"], "correct_index": 3, "explanation": "Um monstro de brinquedo."}], "open_questions": [{"question": "Are you afraid of the dark?", "key_points_pt": ["falar"]}, {"question": "What do you do when you hear a strange noise?", "key_points_pt": ["explicar"]}]}}, {"level": "A1", "genre": "suspense", "title": "The Black Cat", "paragraphs": ["Nina lives in a big old house. Every night, she sees a black cat in the garden. The cat looks at her with yellow eyes.", "One night, Nina follows the cat. It walks to the old tree. It stops and meows. Under the tree, Nina sees a small box.", "She opens it. Inside, there is a gold ring. The black cat sits near her. \"Thank you,\" she says. The cat jumps and goes away."], "paragraphs_pt": ["Nina mora numa casa grande e velha. Toda noite vê um gato preto no jardim. O gato a olha com olhos amarelos.", "Numa noite, Nina segue o gato. Ele anda até a velha árvore. Para e mia. Sob a árvore, Nina vê uma caixinha.", "Ela a abre. Dentro há um anel de ouro. O gato preto senta-se perto dela. \"Obrigada\", diz. O gato pula e vai embora."], "hard_words": ["garden", "tree", "box", "ring"], "vocab": [{"word": "house", "meaning": "casa", "note": ""}, {"word": "garden", "meaning": "jardim", "note": ""}, {"word": "yellow", "meaning": "amarelo", "note": ""}, {"word": "eyes", "meaning": "olhos", "note": ""}, {"word": "tree", "meaning": "árvore", "note": ""}, {"word": "box", "meaning": "caixa", "note": ""}, {"word": "ring", "meaning": "anel", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is"], "irregular": [], "phrasal": [], "wh": [], "connectors": ["and"], "comparative": []}, "word_meanings": [{"word": "house", "meaning": "casa", "note": ""}, {"word": "garden", "meaning": "jardim", "note": ""}, {"word": "yellow", "meaning": "amarelo", "note": ""}, {"word": "eyes", "meaning": "olhos", "note": ""}, {"word": "tree", "meaning": "árvore", "note": ""}, {"word": "box", "meaning": "caixa", "note": ""}, {"word": "ring", "meaning": "anel", "note": ""}], "exercises": {"grammar": [{"point": "There is", "explanation_pt": "'there is a gold ring' mostra que algo existe lá dentro."}], "multiple_choice": [{"question": "Where does Nina live?", "options": ["In a school", "In an old house", "In a flat", "In a hotel"], "correct_index": 1, "explanation": "Numa casa velha."}, {"question": "What does she see at night?", "options": ["A black cat", "A dog", "A bird", "A ghost"], "correct_index": 0, "explanation": "Um gato preto."}, {"question": "What color are the cat's eyes?", "options": ["Yellow", "Red", "Blue", "Green"], "correct_index": 0, "explanation": "Amarelos."}, {"question": "What is under the tree?", "options": ["A phone", "A map", "A small box", "A key"], "correct_index": 2, "explanation": "Uma caixinha."}, {"question": "What is inside?", "options": ["Money", "A letter", "A gold ring", "A key"], "correct_index": 2, "explanation": "Um anel de ouro."}], "open_questions": [{"question": "What would you do if you found a box?", "key_points_pt": ["imaginar"]}, {"question": "Do you like cats?", "key_points_pt": ["opinar"]}]}}, {"level": "A1", "genre": "suspense", "title": "The Phone Call", "paragraphs": ["Jack is alone at home. The phone rings. He answers. \"Hello?\" Nobody speaks. He hears breathing.", "\"Who is it?\" he asks. A deep voice says, \"I am at your door.\" Jack looks at the door. He is very afraid.", "Then he hears a knock. He opens it slowly. It is his friend Max with a pizza! \"Surprise!\" says Max. Jack laughs. \"You and your jokes!\""], "paragraphs_pt": ["Jack está sozinho em casa. O telefone toca. Ele atende. \"Alô?\" Ninguém fala. Ouve respiração.", "\"Quem é?\", pergunta. Uma voz grave diz: \"Estou na sua porta.\" Jack olha para a porta. Está com muito medo.", "Então ouve uma batida. Abre devagar. É o amigo Max com uma pizza! \"Surpresa!\", diz Max. Jack ri. \"Você e suas brincadeiras!\""], "hard_words": ["alone", "breathing", "knock", "surprise"], "vocab": [{"word": "surprise", "meaning": "surpresa", "note": ""}, {"word": "alone", "meaning": "sozinho", "note": ""}, {"word": "phone", "meaning": "telefone", "note": ""}, {"word": "rings", "meaning": "toca", "note": ""}, {"word": "breathing", "meaning": "respiração", "note": ""}, {"word": "deep", "meaning": "grave", "note": ""}, {"word": "knock", "meaning": "batida", "note": ""}, {"word": "pizza", "meaning": "pizza", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["is", "am"], "irregular": [], "phrasal": [], "wh": ["who"], "connectors": ["and", "then"], "comparative": []}, "word_meanings": [{"word": "surprise", "meaning": "surpresa", "note": ""}, {"word": "alone", "meaning": "sozinho", "note": ""}, {"word": "phone", "meaning": "telefone", "note": ""}, {"word": "rings", "meaning": "toca", "note": ""}, {"word": "breathing", "meaning": "respiração", "note": ""}, {"word": "deep", "meaning": "grave", "note": ""}, {"word": "knock", "meaning": "batida", "note": ""}, {"word": "pizza", "meaning": "pizza", "note": ""}], "exercises": {"grammar": [{"point": "Questions", "explanation_pt": "'Who is it?' e 'Hello?' mostram perguntas simples ao telefone."}], "multiple_choice": [{"question": "Where is Jack?", "options": ["At a shop", "At a park", "At home", "At school"], "correct_index": 2, "explanation": "Em casa."}, {"question": "What does Jack hear on the phone?", "options": ["A joke", "Music", "Breathing", "A song"], "correct_index": 2, "explanation": "Respiração."}, {"question": "What does the voice say?", "options": ["Hello", "Sorry", "Goodbye", "I am at your door"], "correct_index": 3, "explanation": "'Estou na sua porta.'"}, {"question": "Who is at the door?", "options": ["His mother", "Max", "A police officer", "A thief"], "correct_index": 1, "explanation": "Max."}, {"question": "What does Max bring?", "options": ["A cake", "Flowers", "A dog", "A pizza"], "correct_index": 3, "explanation": "Uma pizza."}], "open_questions": [{"question": "Have you had a joke played on you?", "key_points_pt": ["contar"]}, {"question": "What do you say when you answer the phone?", "key_points_pt": ["explicar"]}]}}, {"level": "A2", "genre": "suspense", "title": "The Empty House", "paragraphs": ["Clara bought an old house at the end of a quiet street. The previous owner had left without saying goodbye, and nobody in the village wanted to talk about it. The first night, she heard footsteps upstairs. She checked every room, but nothing was there.", "The second night, a door slammed in the dark. Clara's heart beat faster. She decided to stay awake and watch. At three in the morning, she saw a thin shadow moving along the corridor and entering the attic. She followed it with a trembling hand on the flashlight.", "In the attic, there was an open window, and a curtain was moving in the wind. On the floor lay a small cat, shivering. \"So you are my ghost,\" whispered Clara. She picked it up, gave it some milk, and the footsteps never returned. The cat slept on her bed every night."], "paragraphs_pt": ["Clara comprou uma casa velha no fim de uma rua tranquila. O dono anterior fora embora sem se despedir e ninguém na aldeia queria falar sobre isso. Na primeira noite, ouviu passos no andar de cima. Verificou todos os cômodos, mas não havia nada.", "Na segunda noite, uma porta bateu no escuro. O coração de Clara bateu mais rápido. Decidiu ficar acordada e observar. Às três da manhã, viu uma sombra fina se movendo pelo corredor e entrando no sótão. Seguiu-a com a mão trêmula na lanterna.", "No sótão havia uma janela aberta e uma cortina se movia ao vento. No chão estava um gatinho, tremendo. \"Então você é meu fantasma\", sussurrou Clara. Pegou-o, deu-lhe leite, e os passos nunca mais voltaram. O gato dormia na cama dela toda noite."], "hard_words": ["footsteps", "slammed", "shadow", "shivering"], "vocab": [{"word": "previous", "meaning": "anterior", "note": ""}, {"word": "footsteps", "meaning": "passos", "note": ""}, {"word": "slammed", "meaning": "bateu", "note": ""}, {"word": "shadow", "meaning": "sombra", "note": ""}, {"word": "corridor", "meaning": "corredor", "note": ""}, {"word": "attic", "meaning": "sótão", "note": ""}, {"word": "trembling", "meaning": "trêmula", "note": ""}, {"word": "shivering", "meaning": "tremendo", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "are"], "irregular": ["bought", "had", "left", "wanted", "heard", "checked", "slammed", "decided", "saw", "followed", "lay", "whispered", "picked", "gave", "returned", "slept"], "phrasal": ["stay awake"], "wh": [], "connectors": ["and", "but", "so"], "comparative": []}, "word_meanings": [{"word": "previous", "meaning": "anterior", "note": ""}, {"word": "footsteps", "meaning": "passos", "note": ""}, {"word": "slammed", "meaning": "bateu", "note": ""}, {"word": "shadow", "meaning": "sombra", "note": ""}, {"word": "corridor", "meaning": "corredor", "note": ""}, {"word": "attic", "meaning": "sótão", "note": ""}, {"word": "trembling", "meaning": "trêmula", "note": ""}, {"word": "shivering", "meaning": "tremendo", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'bought', 'heard', 'checked' contam o passado."}, {"point": "Past continuous", "explanation_pt": "'a curtain was moving' descreve uma cena."}], "multiple_choice": [{"question": "Where was the house?", "options": ["On a hill", "In a city", "At the end of a quiet street", "By the sea"], "correct_index": 2, "explanation": "No fim de uma rua tranquila."}, {"question": "What did Clara hear?", "options": ["A phone", "A scream", "Footsteps upstairs", "A song"], "correct_index": 2, "explanation": "Passos."}, {"question": "What did she see at three in the morning?", "options": ["A ghost", "A dog", "A thin shadow", "A person"], "correct_index": 2, "explanation": "Uma sombra fina."}, {"question": "What was in the attic?", "options": ["A ghost", "A small cat", "Nothing", "A thief"], "correct_index": 1, "explanation": "Um gatinho."}, {"question": "What happened after?", "options": ["She screamed", "She sold the house", "She moved", "The footsteps stopped"], "correct_index": 3, "explanation": "Os passos pararam."}], "open_questions": [{"question": "Would you live in an old house?", "key_points_pt": ["opinar"]}, {"question": "What noises scare you at night?", "key_points_pt": ["explicar"]}]}}, {"level": "A2", "genre": "suspense", "title": "The Letter Without a Name", "paragraphs": ["Every morning for a week, Daniel found a white envelope under his door. There was no name on it, and inside there was just one line of text. Monday: \"I am watching you.\" Tuesday: \"I know where you go.\" Wednesday: \"I know what you did.\"", "Daniel was frightened. He did not remember doing anything wrong, but the letters made him doubt himself. He looked through his window at night, wondering who was out there. He told the police, who said they would investigate.", "On Friday, the last envelope arrived. It said: \"Happy birthday! Look behind you.\" Daniel turned around, and all his friends jumped out of the wardrobe, laughing. \"We wanted to surprise you!\" said his sister. Daniel did not know whether to laugh or to cry, so he did both."], "paragraphs_pt": ["Toda manhã por uma semana, Daniel achou um envelope branco sob a porta. Não havia nome nele e dentro havia apenas uma linha de texto. Segunda: \"Estou observando você.\" Terça: \"Sei aonde você vai.\" Quarta: \"Sei o que você fez.\"", "Daniel estava assustado. Não lembrava de ter feito nada errado, mas as cartas o faziam duvidar de si. Olhava pela janela à noite, imaginando quem estava lá fora. Contou à polícia, que disse que investigaria.", "Na sexta, chegou o último envelope. Dizia: \"Feliz aniversário! Olhe atrás de você.\" Daniel se virou e todos os amigos pularam do guarda-roupa, rindo. \"Queríamos te surpreender!\", disse a irmã. Daniel não sabia se ria ou chorava, então fez os dois."], "hard_words": ["envelope", "frightened", "investigate", "wardrobe"], "vocab": [{"word": "envelope", "meaning": "envelope", "note": ""}, {"word": "frightened", "meaning": "assustado", "note": ""}, {"word": "doubt", "meaning": "duvidar", "note": ""}, {"word": "investigate", "meaning": "investigar", "note": ""}, {"word": "wardrobe", "meaning": "guarda-roupa", "note": ""}, {"word": "surprise", "meaning": "surpreender", "note": ""}, {"word": "birthday", "meaning": "aniversário", "note": ""}, {"word": "sister", "meaning": "irmã", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "am"], "irregular": ["found", "did", "frightened", "made", "looked", "told", "said", "would", "arrived", "turned", "jumped", "wanted"], "phrasal": ["looked through", "jumped out"], "wh": ["who", "what", "where"], "connectors": ["and", "but", "so", "or"], "comparative": []}, "word_meanings": [{"word": "envelope", "meaning": "envelope", "note": ""}, {"word": "frightened", "meaning": "assustado", "note": ""}, {"word": "doubt", "meaning": "duvidar", "note": ""}, {"word": "investigate", "meaning": "investigar", "note": ""}, {"word": "wardrobe", "meaning": "guarda-roupa", "note": ""}, {"word": "surprise", "meaning": "surpreender", "note": ""}, {"word": "birthday", "meaning": "aniversário", "note": ""}, {"word": "sister", "meaning": "irmã", "note": ""}], "exercises": {"grammar": [{"point": "Past simple", "explanation_pt": "'found', 'told', 'turned around' contam a história."}, {"point": "Did not remember", "explanation_pt": "'He did not remember doing anything wrong' usa remember + ing."}], "multiple_choice": [{"question": "What did Daniel find every morning?", "options": ["A flower", "A white envelope", "A phone", "A gift"], "correct_index": 1, "explanation": "Um envelope branco."}, {"question": "What did the letters say?", "options": ["Jokes", "Poems", "Recipes", "Threatening lines"], "correct_index": 3, "explanation": "Frases ameaçadoras."}, {"question": "What did Daniel do?", "options": ["Told the police", "Wrote back", "Ignored it", "Moved"], "correct_index": 0, "explanation": "Contou à polícia."}, {"question": "What was the last message?", "options": ["I am coming", "Happy birthday! Look behind you", "Run", "Goodbye"], "correct_index": 1, "explanation": "'Feliz aniversário!'"}, {"question": "Who was behind it?", "options": ["A thief", "The police", "His friends", "A stranger"], "correct_index": 2, "explanation": "Os amigos."}], "open_questions": [{"question": "Do you like surprises?", "key_points_pt": ["opinar"]}, {"question": "Would you be scared by such letters?", "key_points_pt": ["explicar"]}]}}, {"level": "B1", "genre": "suspense", "title": "The Lift Stopped", "paragraphs": ["On Friday evening, Helen was going home from work when the lift suddenly stopped between the seventh and eighth floors. The lights flickered and went out. A moment later, the emergency light came on, a dim red glow that made the small space look even smaller. She was not alone. A man in a dark coat stood in the corner, looking at his shoes.", "Helen pressed the emergency button, but nothing happened. \"It happens,\" said the man calmly. \"They fix it in a few minutes.\" But his hands were trembling, and he checked his watch every ten seconds. Helen's suspicion grew. Why was he so nervous, if it was only a lift?", "After twenty minutes, he finally spoke. \"I'm sorry,\" he said. \"I'm very claustrophobic. I've been holding my breath since the lift stopped.\" Helen almost laughed with relief. She started to talk to him about her day, her cat, anything, to distract him.", "When the doors opened, the man took a deep breath, shook her hand and said, \"I think you saved me.\" Helen smiled. She had spent twenty minutes imagining a criminal, and instead she had helped a frightened stranger. That night, she took the stairs."], "paragraphs_pt": ["Na sexta à noite, Helen voltava do trabalho quando o elevador parou de repente entre o sétimo e o oitavo andares. As luzes piscaram e se apagaram. Um momento depois, a luz de emergência acendeu, um brilho vermelho fraco que fazia o pequeno espaço parecer ainda menor. Ela não estava sozinha. Um homem de casaco escuro estava no canto, olhando os sapatos.", "Helen apertou o botão de emergência, mas nada aconteceu. \"Acontece\", disse o homem calmamente. \"Consertam em poucos minutos.\" Mas as mãos dele tremiam e ele olhava o relógio a cada dez segundos. A suspeita de Helen cresceu. Por que estava tão nervoso, se era só um elevador?", "Após vinte minutos, ele enfim falou. \"Desculpe\", disse. \"Sou muito claustrofóbico. Estou prendendo a respiração desde que o elevador parou.\" Helen quase riu de alívio. Começou a falar com ele sobre seu dia, seu gato, qualquer coisa, para distraí-lo.", "Quando as portas abriram, o homem respirou fundo, apertou-lhe a mão e disse: \"Acho que você me salvou.\" Helen sorriu. Passara vinte minutos imaginando um criminoso e, em vez disso, ajudara um estranho assustado. Naquela noite, subiu pelas escadas."], "hard_words": ["flickered", "suspicion", "claustrophobic", "distract"], "vocab": [{"word": "lift", "meaning": "elevador", "note": ""}, {"word": "flickered", "meaning": "piscaram", "note": ""}, {"word": "dim", "meaning": "fraco", "note": ""}, {"word": "glow", "meaning": "brilho", "note": ""}, {"word": "suspicion", "meaning": "suspeita", "note": ""}, {"word": "claustrophobic", "meaning": "claustrofóbico", "note": ""}, {"word": "relief", "meaning": "alívio", "note": ""}, {"word": "distract", "meaning": "distrair", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been"], "irregular": ["stopped", "flickered", "went", "came", "made", "stood", "pressed", "happened", "said", "checked", "grew", "spoke", "laughed", "started", "opened", "took", "shook", "saved", "smiled", "had", "spent", "helped", "frightened"], "phrasal": ["went out", "came on"], "wh": ["when", "why"], "connectors": ["and", "but", "so", "instead", "after", "when", "since", "finally", "suddenly", "if"], "comparative": []}, "word_meanings": [{"word": "lift", "meaning": "elevador", "note": ""}, {"word": "flickered", "meaning": "piscaram", "note": ""}, {"word": "dim", "meaning": "fraco", "note": ""}, {"word": "glow", "meaning": "brilho", "note": ""}, {"word": "suspicion", "meaning": "suspeita", "note": ""}, {"word": "claustrophobic", "meaning": "claustrofóbico", "note": ""}, {"word": "relief", "meaning": "alívio", "note": ""}, {"word": "distract", "meaning": "distrair", "note": ""}], "exercises": {"grammar": [{"point": "Past continuous e simple", "explanation_pt": "'Helen was going home when the lift stopped' combina cena e interrupção."}, {"point": "Past perfect", "explanation_pt": "'She had spent twenty minutes imagining a criminal' fala de algo anterior à conclusão."}], "multiple_choice": [{"question": "Where did the lift stop?", "options": ["In the basement", "On the ground floor", "Between the seventh and eighth floors", "On the top floor"], "correct_index": 2, "explanation": "Entre sétimo e oitavo."}, {"question": "Who was with Helen?", "options": ["A man in a dark coat", "A guard", "A woman", "A child"], "correct_index": 0, "explanation": "Um homem de casaco escuro."}, {"question": "Why was he nervous?", "options": ["He was sick", "He was a criminal", "He was late", "He was claustrophobic"], "correct_index": 3, "explanation": "Era claustrofóbico."}, {"question": "What did Helen do?", "options": ["Screamed", "Talked to distract him", "Ignored him", "Called the police"], "correct_index": 1, "explanation": "Conversou para distraí-lo."}, {"question": "What did Helen do that night?", "options": ["Took the stairs", "Took a bus", "Took the lift", "Stayed at work"], "correct_index": 0, "explanation": "Foi pelas escadas."}], "open_questions": [{"question": "How can we judge people too quickly?", "key_points_pt": ["explicar"]}, {"question": "Have you been stuck in a lift?", "key_points_pt": ["contar"]}]}}, {"level": "B2", "genre": "suspense", "title": "The Lighthouse Keeper's Log", "paragraphs": ["Thomas Gray accepted the post at the Wrenhead lighthouse because he wanted solitude, and the island provided it in generous quantities. For three weeks, he lived by the rhythm of the lamp, the tide and a battered radio. The only unusual thing was the log of his predecessor, in which each entry ended with the same cryptic phrase: \"It does not like the light.\"", "At first, Thomas dismissed it as a sign of isolation. But on the twenty-second night, he noticed that the beam seemed to catch something at the edge of the rocks: a pale form, standing absolutely still in the shallow water. When he swept the lamp back, it was gone. He told himself it was a trick of the foam.", "Over the following nights, the form returned closer each time. Thomas, a rational man, began to keep his own log. He noted the positions, the hours and the weather, searching for a pattern. There was one: the figure appeared only when he turned the light off for the maintenance cycle. It was not afraid of the beam; it waited for the dark.", "On the last page of his log, Thomas wrote: \"I have understood the phrase. It was not a complaint but an instruction.\" He left the lamp burning continuously until the relief boat arrived, ten days later. When the captain asked why the lighthouse had never been dark, Thomas merely shrugged, and never returned to the sea."], "paragraphs_pt": ["Thomas Gray aceitou o posto no farol de Wrenhead porque queria solidão, e a ilha a ofereceu em generosas quantidades. Por três semanas, viveu pelo ritmo da lâmpada, da maré e de um rádio surrado. A única coisa incomum era o diário de seu antecessor, em que cada entrada terminava com a mesma frase enigmática: \"Ela não gosta da luz.\"", "A princípio, Thomas considerou sinal de isolamento. Mas na vigésima segunda noite, notou que o feixe parecia captar algo na beira das rochas: uma forma pálida, absolutamente imóvel na água rasa. Quando varreu a lâmpada de volta, sumira. Disse a si mesmo que era um truque da espuma.", "Nas noites seguintes, a forma voltou, mais perto a cada vez. Thomas, homem racional, começou a manter seu próprio diário. Anotou posições, horas e o clima, procurando um padrão. Havia um: a figura aparecia somente quando ele desligava a luz para o ciclo de manutenção. Não temia o feixe; esperava a escuridão.", "Na última página do diário, Thomas escreveu: \"Entendi a frase. Não era uma queixa, mas uma instrução.\" Deixou a lâmpada acesa continuamente até o barco de rendição chegar, dez dias depois. Quando o capitão perguntou por que o farol nunca ficara apagado, Thomas apenas deu de ombros, e nunca mais voltou ao mar."], "hard_words": ["solitude", "cryptic", "beam", "maintenance"], "vocab": [{"word": "solitude", "meaning": "solidão", "note": ""}, {"word": "battered", "meaning": "surrado", "note": ""}, {"word": "predecessor", "meaning": "antecessor", "note": ""}, {"word": "cryptic", "meaning": "enigmática", "note": ""}, {"word": "beam", "meaning": "feixe", "note": ""}, {"word": "foam", "meaning": "espuma", "note": ""}, {"word": "maintenance", "meaning": "manutenção", "note": ""}, {"word": "relief", "meaning": "rendição", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "been"], "irregular": ["accepted", "wanted", "provided", "lived", "battered", "ended", "dismissed", "noticed", "seemed", "swept", "gone", "told", "returned", "began", "noted", "appeared", "turned", "waited", "wrote", "understood", "left", "arrived", "asked", "had", "shrugged"], "phrasal": [], "wh": ["when", "why", "which"], "connectors": ["and", "but", "because", "when", "until", "still", "as"], "comparative": []}, "word_meanings": [{"word": "solitude", "meaning": "solidão", "note": ""}, {"word": "battered", "meaning": "surrado", "note": ""}, {"word": "predecessor", "meaning": "antecessor", "note": ""}, {"word": "cryptic", "meaning": "enigmática", "note": ""}, {"word": "beam", "meaning": "feixe", "note": ""}, {"word": "foam", "meaning": "espuma", "note": ""}, {"word": "maintenance", "meaning": "manutenção", "note": ""}, {"word": "relief", "meaning": "rendição", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect e past simple", "explanation_pt": "'a pale form standing' descreve uma cena presente na narração."}, {"point": "Not... but", "explanation_pt": "'not a complaint but an instruction' contrasta duas leituras."}], "multiple_choice": [{"question": "Why did Thomas take the post?", "options": ["He needed money", "He was ordered", "He loved the sea", "He wanted solitude"], "correct_index": 3, "explanation": "Queria solidão."}, {"question": "What did the log's entries end with?", "options": ["All is well", "Good night", "Help", "It does not like the light"], "correct_index": 3, "explanation": "'Ela não gosta da luz.'"}, {"question": "What did he see in the water?", "options": ["A whale", "A ship", "A diver", "A pale still form"], "correct_index": 3, "explanation": "Uma forma pálida imóvel."}, {"question": "When did the figure appear?", "options": ["During storms", "When the light was off", "At dawn", "In daytime"], "correct_index": 1, "explanation": "Quando a luz estava desligada."}, {"question": "What did Thomas do?", "options": ["Kept the lamp on continuously", "Broke the lamp", "Left at once", "Ignored it"], "correct_index": 0, "explanation": "Manteve a luz acesa."}], "open_questions": [{"question": "Is it better to confront or avoid mysteries?", "key_points_pt": ["debater"]}, {"question": "How can solitude affect the mind?", "key_points_pt": ["explicar"]}]}}, {"level": "B2", "genre": "suspense", "title": "The Number on the Wall", "paragraphs": ["When Freya moved into the apartment on Calder Street, she noticed a number written in small, careful digits inside the wardrobe: 4417. She assumed it was a previous tenant's code and forgot about it. A week later, however, she found the same number scratched underneath the kitchen table and, soon after, on the back of a bedroom door.", "Her curiosity turned to unease. She asked her neighbour, a retired locksmith, whether he knew anything. The old man's expression changed. \"That's the number of the apartment,\" he said slowly, \"that used to be here. It was demolished before they built the building.\" Freya frowned. The apartment she lived in was, according to the plans, numbered 214.", "She began to investigate. In the archives of the city, she learned that the demolished flat had belonged to a woman who had vanished thirty years earlier, and whose case had never been closed. Everything pointed to the possibility that the number was a message left by someone who knew the apartment was not what it appeared to be.", "Freya contacted the police, who at first were sceptical. But when they opened a hidden panel behind the wardrobe, they found a sealed box with documents and a photograph. The mystery was solved after thirty years. In her new life, Freya never again ignored numbers on walls."], "paragraphs_pt": ["Quando Freya se mudou para o apartamento da Rua Calder, notou um número escrito em dígitos pequenos e cuidadosos dentro do guarda-roupa: 4417. Presumiu que fosse um código de um inquilino anterior e esqueceu. Uma semana depois, porém, achou o mesmo número riscado embaixo da mesa da cozinha e, logo depois, atrás de uma porta do quarto.", "A curiosidade virou inquietação. Perguntou ao vizinho, um chaveiro aposentado, se sabia algo. A expressão do velho mudou. \"É o número do apartamento\", disse devagar, \"que ficava aqui. Foi demolido antes de construírem o prédio.\" Freya franziu a testa. O apartamento em que morava era, segundo as plantas, o número 214.", "Começou a investigar. Nos arquivos da cidade, soube que o apartamento demolido pertencera a uma mulher que desaparecera trinta anos antes e cujo caso nunca fora encerrado. Tudo apontava para a possibilidade de que o número fosse uma mensagem deixada por alguém que sabia que o apartamento não era o que parecia.", "Freya contatou a polícia, que a princípio foi cética. Mas quando abriram um painel oculto atrás do guarda-roupa, acharam uma caixa lacrada com documentos e uma fotografia. O mistério foi resolvido após trinta anos. Em sua nova vida, Freya nunca mais ignorou números em paredes."], "hard_words": ["tenant", "locksmith", "demolished", "sceptical"], "vocab": [{"word": "tenant", "meaning": "inquilino", "note": ""}, {"word": "digits", "meaning": "dígitos", "note": ""}, {"word": "scratched", "meaning": "riscado", "note": ""}, {"word": "locksmith", "meaning": "chaveiro", "note": ""}, {"word": "demolished", "meaning": "demolido", "note": ""}, {"word": "archives", "meaning": "arquivos", "note": ""}, {"word": "sceptical", "meaning": "cética", "note": ""}, {"word": "sealed", "meaning": "lacrada", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "be", "been", "were"], "irregular": ["moved", "noticed", "written", "assumed", "forgot", "found", "scratched", "turned", "asked", "retired", "knew", "changed", "said", "used", "demolished", "built", "frowned", "lived", "numbered", "began", "learned", "had", "belonged", "vanished", "closed", "pointed", "left", "appeared", "contacted", "opened", "hidden", "sealed", "solved", "ignored"], "phrasal": ["moved into", "pointed to"], "wh": ["who", "what", "when", "whose"], "connectors": ["and", "but", "however", "after", "before", "when"], "comparative": []}, "word_meanings": [{"word": "tenant", "meaning": "inquilino", "note": ""}, {"word": "digits", "meaning": "dígitos", "note": ""}, {"word": "scratched", "meaning": "riscado", "note": ""}, {"word": "locksmith", "meaning": "chaveiro", "note": ""}, {"word": "demolished", "meaning": "demolido", "note": ""}, {"word": "archives", "meaning": "arquivos", "note": ""}, {"word": "sceptical", "meaning": "cética", "note": ""}, {"word": "sealed", "meaning": "lacrada", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'a woman who had vanished thirty years earlier' mostra algo anterior."}, {"point": "According to", "explanation_pt": "'according to the plans' indica fonte de informação."}], "multiple_choice": [{"question": "What did Freya find in the wardrobe?", "options": ["A number", "A key", "A photo", "A letter"], "correct_index": 0, "explanation": "Um número."}, {"question": "What did the neighbour say?", "options": ["It was her age", "It was a phone number", "It was a street", "The number belonged to a demolished apartment"], "correct_index": 3, "explanation": "Era de um apartamento demolido."}, {"question": "What did she learn in the archives?", "options": ["A bank was robbed", "A woman vanished thirty years earlier", "A crime was solved", "A fire happened"], "correct_index": 1, "explanation": "Uma mulher desapareceu."}, {"question": "What did the police find?", "options": ["A sealed box with documents", "Money", "A weapon", "A body"], "correct_index": 0, "explanation": "Uma caixa lacrada."}, {"question": "How did Freya change?", "options": ["She quit her job", "She no longer ignored numbers on walls", "She sold the flat", "She moved"], "correct_index": 1, "explanation": "Nunca mais ignorou números."}], "open_questions": [{"question": "How do old places keep secrets?", "key_points_pt": ["explicar"]}, {"question": "Would you investigate such a mystery?", "key_points_pt": ["opinar"]}]}}, {"level": "B2", "genre": "suspense", "title": "The Stranger on the Night Bus", "paragraphs": ["The night bus from the city centre to the suburbs was normally empty after midnight, which was why Jonas noticed the woman immediately. She sat directly behind him, in a green raincoat, and stared at the back of his head without blinking. When he changed seats, she moved too. When he got off one stop early, she got off as well.", "Jonas walked faster, then slower, trying to determine whether he was being followed. The streets were deserted, and every shadow seemed to hold its breath. At the corner, he took out his phone to call his sister, but the woman had already caught up with him. \"Please,\" she said breathlessly. \"You dropped this.\"", "She held out his wallet. It had slipped from his pocket on the bus, and she had spent the whole journey trying to decide how to return it without frightening him. \"I'm sorry,\" she added. \"I'm terrible at approaching people.\" Jonas stood there, embarrassed. He had imagined a hundred scenarios, none of them kind.", "They walked together to his door, and she explained that she was a nurse finishing a double shift. \"I think people are scared of strangers,\" she said. \"And maybe they should be. But not all of us.\" Jonas thanked her again, watched her leave and made a small promise to himself: to assume the best a little more often."], "paragraphs_pt": ["O ônibus noturno do centro para os subúrbios normalmente estava vazio depois da meia-noite, razão pela qual Jonas notou a mulher imediatamente. Ela sentava logo atrás dele, de capa de chuva verde, e olhava a nuca dele sem piscar. Quando ele trocou de assento, ela também. Quando ele desceu um ponto antes, ela desceu também.", "Jonas andou mais rápido, depois mais devagar, tentando determinar se estava sendo seguido. As ruas estavam desertas e cada sombra parecia prender a respiração. Na esquina, pegou o celular para ligar à irmã, mas a mulher já o alcançara. \"Por favor\", disse ofegante. \"O senhor deixou cair isto.\"", "Ela estendeu a carteira dele. Escorregara do bolso no ônibus, e ela passara a viagem toda tentando decidir como devolvê-la sem assustá-lo. \"Desculpe\", acrescentou. \"Sou péssima em abordar pessoas.\" Jonas ficou parado, constrangido. Imaginara cem cenários, nenhum gentil.", "Caminharam juntos até a porta dele, e ela explicou que era enfermeira terminando um plantão duplo. \"Acho que as pessoas têm medo de estranhos\", disse. \"E talvez devessem ter. Mas nem todos nós.\" Jonas agradeceu de novo, viu-a partir e fez uma pequena promessa a si mesmo: supor o melhor com um pouco mais de frequência."], "hard_words": ["stared", "deserted", "breathlessly", "approaching"], "vocab": [{"word": "suburbs", "meaning": "subúrbios", "note": ""}, {"word": "stared", "meaning": "olhava fixamente", "note": ""}, {"word": "blinking", "meaning": "piscar", "note": ""}, {"word": "deserted", "meaning": "desertas", "note": ""}, {"word": "breathlessly", "meaning": "ofegante", "note": ""}, {"word": "wallet", "meaning": "carteira", "note": ""}, {"word": "approaching", "meaning": "abordar", "note": ""}, {"word": "shift", "meaning": "plantão", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "being", "were", "are", "be"], "irregular": ["noticed", "sat", "stared", "changed", "moved", "got", "walked", "followed", "deserted", "seemed", "took", "had", "caught", "said", "dropped", "held", "slipped", "spent", "added", "stood", "embarrassed", "imagined", "explained", "scared", "should", "thanked", "watched", "made"], "phrasal": ["got off", "caught up"], "wh": ["when", "why", "how", "which"], "connectors": ["and", "but", "then", "after", "when", "as"], "comparative": []}, "word_meanings": [{"word": "suburbs", "meaning": "subúrbios", "note": ""}, {"word": "stared", "meaning": "olhava fixamente", "note": ""}, {"word": "blinking", "meaning": "piscar", "note": ""}, {"word": "deserted", "meaning": "desertas", "note": ""}, {"word": "breathlessly", "meaning": "ofegante", "note": ""}, {"word": "wallet", "meaning": "carteira", "note": ""}, {"word": "approaching", "meaning": "abordar", "note": ""}, {"word": "shift", "meaning": "plantão", "note": ""}], "exercises": {"grammar": [{"point": "Past perfect", "explanation_pt": "'She had spent the whole journey trying to decide' mostra o que ocorrera antes."}, {"point": "None of them", "explanation_pt": "'none of them kind' nega todos os cenários."}], "multiple_choice": [{"question": "Why did Jonas notice the woman?", "options": ["She was his friend", "The bus was usually empty", "She was famous", "She was loud"], "correct_index": 1, "explanation": "O ônibus costumava estar vazio."}, {"question": "What did she wear?", "options": ["A black coat", "A red hat", "A blue dress", "A green raincoat"], "correct_index": 3, "explanation": "Capa de chuva verde."}, {"question": "What did she want?", "options": ["To ask directions", "To return his wallet", "To follow him", "To rob him"], "correct_index": 1, "explanation": "Devolver a carteira."}, {"question": "Who was she?", "options": ["A police officer", "A neighbour", "A nurse", "A thief"], "correct_index": 2, "explanation": "Uma enfermeira."}, {"question": "What promise did Jonas make?", "options": ["To buy a car", "To avoid buses", "To assume the best more often", "To never trust"], "correct_index": 2, "explanation": "Supor o melhor."}], "open_questions": [{"question": "Do we judge strangers too quickly?", "key_points_pt": ["debater"]}, {"question": "Would you approach a stranger to return something?", "key_points_pt": ["opinar"]}]}}, {"level": "C1", "genre": "suspense", "title": "The Quiet House on Marlow Road", "paragraphs": ["There are houses in which nothing visibly happens and yet the air seems to lean in your direction. The house on Marlow Road was one of them. Its owners, an elderly couple named the Hartleys, were gracious and impeccable, and offered their guests tea with a ceremony that bordered on the liturgical. Nothing in their conduct was untoward. That, perhaps, was the disquieting thing.", "Inspector Dunmore, called to the house following a neighbour's anonymous complaint, found nothing to justify it. The rooms were immaculate, the clocks synchronised, the floors waxed to a gleam. Yet he sensed, with the instinct that decades of interviewing had refined, that the order was too perfect, like a script recited with excessive diligence. When he complimented the garden, Mrs. Hartley's smile hesitated, for a fraction of a second, before it appeared.", "The detail that finally unsettled him was a small one: a third cup on the tray, unused, placed in front of an empty chair. Mrs. Hartley, following his gaze, said calmly, \"Habit.\" Dunmore asked whose habit. \"Our son's,\" she replied. \"He liked tea at four.\" The inspector inquired where the son was now, and the couple exchanged a look so brief that only a professional would have noticed it.", "He left without arrests or accusations. But for months afterward, in the quiet of his own kitchen, he found himself pouring a cup he did not intend to drink. Suspense, he decided, was not the fear of what one knew was coming, but the dread of what one was no longer certain one had understood."], "paragraphs_pt": ["Há casas em que nada visível acontece e, no entanto, o ar parece se inclinar na sua direção. A casa da Marlow Road era uma delas. Os donos, um casal de idosos chamados Hartley, eram gentis e impecáveis, e ofereciam chá aos convidados com uma cerimônia que beirava o litúrgico. Nada em sua conduta era inconveniente. Isso, talvez, era o perturbador.", "O inspetor Dunmore, chamado à casa após uma queixa anônima de um vizinho, não achou nada que a justificasse. Os cômodos eram imaculados, os relógios sincronizados, os pisos encerados até brilhar. Mas sentiu, com o instinto que décadas de interrogatórios refinaram, que a ordem era perfeita demais, como um roteiro recitado com diligência excessiva. Quando elogiou o jardim, o sorriso da Sra. Hartley hesitou, por uma fração de segundo, antes de aparecer.", "O detalhe que finalmente o perturbou foi pequeno: uma terceira xícara na bandeja, sem uso, posta diante de uma cadeira vazia. A Sra. Hartley, seguindo o olhar, disse calmamente: \"Hábito.\" Dunmore perguntou de quem. \"Do nosso filho\", respondeu. \"Ele gostava de chá às quatro.\" O inspetor perguntou onde estava o filho agora, e o casal trocou um olhar tão breve que só um profissional o notaria.", "Saiu sem prisões ou acusações. Mas por meses depois, na quietude da própria cozinha, viu-se servindo uma xícara que não pretendia beber. O suspense, decidiu, não era o medo do que se sabia que viria, mas o pavor do que não se tinha mais certeza de ter compreendido."], "hard_words": ["impeccable", "disquieting", "immaculate", "dread"], "vocab": [{"word": "impeccable", "meaning": "impecáveis", "note": ""}, {"word": "liturgical", "meaning": "litúrgico", "note": ""}, {"word": "untoward", "meaning": "inconveniente", "note": ""}, {"word": "disquieting", "meaning": "perturbador", "note": ""}, {"word": "immaculate", "meaning": "imaculados", "note": ""}, {"word": "diligence", "meaning": "diligência", "note": ""}, {"word": "unsettled", "meaning": "perturbou", "note": ""}, {"word": "dread", "meaning": "pavor", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["are", "was", "were"], "irregular": ["named", "offered", "bordered", "called", "found", "synchronised", "waxed", "sensed", "had", "refined", "recited", "complimented", "hesitated", "appeared", "unsettled", "placed", "said", "asked", "replied", "liked", "inquired", "exchanged", "would", "noticed", "left", "did", "decided", "knew", "understood"], "phrasal": ["lean in", "bordered on"], "wh": ["what", "where", "when", "which", "whose"], "connectors": ["and", "but", "so", "before", "when", "yet", "or", "finally"], "comparative": []}, "word_meanings": [{"word": "impeccable", "meaning": "impecáveis", "note": ""}, {"word": "liturgical", "meaning": "litúrgico", "note": ""}, {"word": "untoward", "meaning": "inconveniente", "note": ""}, {"word": "disquieting", "meaning": "perturbador", "note": ""}, {"word": "immaculate", "meaning": "imaculados", "note": ""}, {"word": "diligence", "meaning": "diligência", "note": ""}, {"word": "unsettled", "meaning": "perturbou", "note": ""}, {"word": "dread", "meaning": "pavor", "note": ""}], "exercises": {"grammar": [{"point": "Following + substantivo", "explanation_pt": "'following a neighbour's anonymous complaint' indica causa/ocasião."}, {"point": "Not... but", "explanation_pt": "'not the fear of what one knew was coming, but the dread of what one was no longer certain' contrasta dois tipos de medo."}], "multiple_choice": [{"question": "How was the Hartleys' house?", "options": ["Messy", "Immaculate", "Empty", "Dark"], "correct_index": 1, "explanation": "Imaculada."}, {"question": "Why was Dunmore called?", "options": ["A murder", "An anonymous complaint", "A theft", "A fire"], "correct_index": 1, "explanation": "Queixa anônima."}, {"question": "What detail unsettled him?", "options": ["A missing clock", "A blood stain", "A third cup before an empty chair", "A broken window"], "correct_index": 2, "explanation": "Uma terceira xícara."}, {"question": "Whose habit was it?", "options": ["Their son's", "Their guest's", "Their daughter's", "Their neighbour's"], "correct_index": 0, "explanation": "Do filho."}, {"question": "What is suspense, for Dunmore?", "options": ["Fear of the unknown", "Fear of ghosts", "Dread of what one no longer understands", "Joy"], "correct_index": 2, "explanation": "Pavor do que não compreendeu."}], "open_questions": [{"question": "Why can too-perfect order seem suspicious?", "key_points_pt": ["discutir"]}, {"question": "What does the third cup suggest?", "key_points_pt": ["interpretar"]}]}}, {"level": "C1", "genre": "suspense", "title": "The Witness Who Remembered Too Much", "paragraphs": ["Alma Reyes had a rare gift: she forgot nothing. Every conversation, every receipt, every glance at a stranger on a train was preserved in her mind with archival fidelity. For years, she regarded this as a harmless eccentricity, useful at parties and in examinations. It was only when she witnessed a crime from the window of her flat that the gift became a hazard.", "Within a week, the police were certain she was the key witness; within two, someone else had come to the same conclusion. A man in a grey cap began appearing at the edges of her day: outside the pharmacy, across the road from her office. Alma, who recalled every face she had ever seen, understood that he was never the same man twice, and that their number was growing.", "The irony of her position was exquisite. The one thing that made her valuable, her memory, was also the thing she could not surrender. She could not choose to forget; she could only decide what to do with what she knew. She spent a night recalling the entire crime in minute detail, then wrote it down, sealed it and gave copies to three separate people.", "When the men in grey caps understood that silencing her would no longer prevent the truth from emerging, they gradually disappeared. Alma never discovered whether she had been protected by the police, by luck or by the sheer inconvenience of her usefulness. She remained, however, permanently watchful, with the peculiar loneliness of those condemned to remember."], "paragraphs_pt": ["Alma Reyes tinha um dom raro: não esquecia nada. Cada conversa, cada recibo, cada olhar para um estranho num trem era preservado em sua mente com fidelidade de arquivo. Por anos, considerou isso uma excentricidade inofensiva, útil em festas e provas. Só quando testemunhou um crime da janela do apartamento o dom se tornou um risco.", "Em uma semana, a polícia tinha certeza de que ela era a testemunha-chave; em duas, outra pessoa chegara à mesma conclusão. Um homem de boné cinza começou a aparecer nas margens de seu dia: em frente à farmácia, do outro lado da rua do escritório. Alma, que lembrava todo rosto que vira, entendeu que ele nunca era o mesmo homem duas vezes e que seu número crescia.", "A ironia de sua posição era requintada. A única coisa que a tornava valiosa, sua memória, era também a que não podia entregar. Não podia escolher esquecer; só podia decidir o que fazer com o que sabia. Passou uma noite recordando o crime inteiro em minúcias, depois o escreveu, lacrou e entregou cópias a três pessoas diferentes.", "Quando os homens de boné cinza entenderam que silenciá-la já não impediria a verdade de emergir, foram desaparecendo. Alma nunca soube se fora protegida pela polícia, pela sorte ou pela mera inconveniência de sua utilidade. Permaneceu, porém, permanentemente vigilante, com a solidão peculiar dos condenados a lembrar."], "hard_words": ["fidelity", "hazard", "exquisite", "condemned"], "vocab": [{"word": "archival", "meaning": "de arquivo", "note": ""}, {"word": "fidelity", "meaning": "fidelidade", "note": ""}, {"word": "hazard", "meaning": "risco", "note": ""}, {"word": "witnessed", "meaning": "testemunhou", "note": ""}, {"word": "exquisite", "meaning": "requintada", "note": ""}, {"word": "surrender", "meaning": "entregar", "note": ""}, {"word": "silencing", "meaning": "silenciando", "note": ""}, {"word": "condemned", "meaning": "condenados", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been"], "irregular": ["had", "forgot", "preserved", "regarded", "witnessed", "became", "began", "recalled", "seen", "understood", "made", "could", "knew", "spent", "wrote", "sealed", "gave", "would", "disappeared", "discovered", "protected", "remained", "condemned"], "phrasal": [], "wh": ["who", "what", "when"], "connectors": ["and", "however", "then", "when", "or", "also", "as"], "comparative": []}, "word_meanings": [{"word": "archival", "meaning": "de arquivo", "note": ""}, {"word": "fidelity", "meaning": "fidelidade", "note": ""}, {"word": "hazard", "meaning": "risco", "note": ""}, {"word": "witnessed", "meaning": "testemunhou", "note": ""}, {"word": "exquisite", "meaning": "requintada", "note": ""}, {"word": "surrender", "meaning": "entregar", "note": ""}, {"word": "silencing", "meaning": "silenciando", "note": ""}, {"word": "condemned", "meaning": "condenados", "note": ""}], "exercises": {"grammar": [{"point": "Had come to the same conclusion", "explanation_pt": "'someone else had come to the same conclusion' mostra algo que ocorrera antes."}, {"point": "The one thing that... was also the thing", "explanation_pt": "'The one thing that made her valuable... was also the thing she could not surrender' cria paralelo."}], "multiple_choice": [{"question": "What was Alma's gift?", "options": ["She was invisible", "She read minds", "She was fast", "She forgot nothing"], "correct_index": 3, "explanation": "Não esquecia nada."}, {"question": "What changed her gift into a hazard?", "options": ["She witnessed a crime", "She got sick", "She lost her job", "She moved"], "correct_index": 0, "explanation": "Testemunhou um crime."}, {"question": "What did the men in grey caps do?", "options": ["Followed her", "Hired her", "Ignored her", "Gave her gifts"], "correct_index": 0, "explanation": "Seguiam-na."}, {"question": "What did Alma do?", "options": ["Called the news", "Wrote it all down and gave copies to three people", "Burned papers", "Fled"], "correct_index": 1, "explanation": "Escreveu e deu cópias."}, {"question": "What remained afterwards?", "options": ["She forgot", "She became famous", "She stayed watchful and lonely", "She left"], "correct_index": 2, "explanation": "Permaneceu vigilante e solitária."}], "open_questions": [{"question": "Would perfect memory be a gift or a curse?", "key_points_pt": ["debater"]}, {"question": "How can sharing information protect you?", "key_points_pt": ["explicar"]}]}}, {"level": "C2", "genre": "suspense", "title": "The Last Page", "paragraphs": ["She had read ten thousand books, but nothing had prepared Lydia Marsh for the manuscript that arrived anonymously at the publishing house on a wet Thursday. It was a novel about a woman who, in the final chapter, disappears from her own house without leaving a trace. What made the editor set aside her tea was the realisation that the house in question was hers.", "The details were uncanny: the creak of the third stair, the chipped blue teapot, the books arranged by colour rather than subject. The author had evidently been inside her home, or had been told, with painstaking precision, how it looked. Lydia read on with the dry mouth of someone attempting to outrun a conclusion. The final page was missing.", "She considered the possibilities with the cold methodology of her profession. It might be a prank by a former writer she had rejected, a stalker, or a literary hoax of unusual refinement. But the last paragraph of the available text, in which the protagonist sat down to read a manuscript that had arrived on a wet Thursday, produced in her a sensation that could only be described as vertigo.", "She did what a reader does when a book becomes unbearable: she turned to the missing page. There was no page, only the empty desk, the ticking clock, and in the hallway the unmistakable creak of the third stair. Lydia put down her pen. For a moment, she wondered whether she was the author of her own disappearance, or merely its first reader."], "paragraphs_pt": ["Lera dez mil livros, mas nada preparara Lydia Marsh para o manuscrito que chegou anonimamente à editora numa quinta-feira chuvosa. Era um romance sobre uma mulher que, no capítulo final, desaparece da própria casa sem deixar rastro. O que fez a editora pôr o chá de lado foi perceber que a casa em questão era a dela.", "Os detalhes eram sobrenaturais: o rangido do terceiro degrau, o bule azul lascado, os livros arrumados por cor e não por assunto. O autor estivera evidentemente em sua casa, ou lhe haviam descrito, com precisão minuciosa, como era. Lydia continuou a ler com a boca seca de quem tenta correr à frente de uma conclusão. A última página estava faltando.", "Considerou as possibilidades com a metodologia fria da profissão. Podia ser uma peça de um escritor que rejeitara, um perseguidor ou uma farsa literária de refinamento incomum. Mas o último parágrafo do texto disponível, em que a protagonista se sentava para ler um manuscrito que chegara numa quinta chuvosa, produziu nela uma sensação que só podia ser descrita como vertigem.", "Fez o que um leitor faz quando um livro se torna insuportável: virou à página que faltava. Não havia página, apenas a mesa vazia, o relógio tiquetaqueando e, no corredor, o inconfundível rangido do terceiro degrau. Lydia pôs a caneta de lado. Por um momento, perguntou-se se era a autora do próprio desaparecimento ou apenas sua primeira leitora."], "hard_words": ["uncanny", "painstaking", "hoax", "vertigo"], "vocab": [{"word": "manuscript", "meaning": "manuscrito", "note": ""}, {"word": "anonymously", "meaning": "anonimamente", "note": ""}, {"word": "uncanny", "meaning": "sobrenaturais", "note": ""}, {"word": "painstaking", "meaning": "minucioso", "note": ""}, {"word": "outrun", "meaning": "correr à frente", "note": ""}, {"word": "hoax", "meaning": "farsa", "note": ""}, {"word": "protagonist", "meaning": "protagonista", "note": ""}, {"word": "vertigo", "meaning": "vertigem", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "were", "been", "be"], "irregular": ["had", "prepared", "arrived", "made", "chipped", "arranged", "told", "looked", "considered", "might", "rejected", "sat", "produced", "could", "described", "did", "turned", "wondered"], "phrasal": ["set aside", "sat down to"], "wh": ["who", "what", "when", "how", "which"], "connectors": ["and", "but", "when", "or", "as"], "comparative": []}, "word_meanings": [{"word": "manuscript", "meaning": "manuscrito", "note": ""}, {"word": "anonymously", "meaning": "anonimamente", "note": ""}, {"word": "uncanny", "meaning": "sobrenaturais", "note": ""}, {"word": "painstaking", "meaning": "minucioso", "note": ""}, {"word": "outrun", "meaning": "correr à frente", "note": ""}, {"word": "hoax", "meaning": "farsa", "note": ""}, {"word": "protagonist", "meaning": "protagonista", "note": ""}, {"word": "vertigo", "meaning": "vertigem", "note": ""}], "exercises": {"grammar": [{"point": "Had read / nothing had prepared", "explanation_pt": "'nothing had prepared her' mostra que nada a preparara antes."}, {"point": "Whether... or merely", "explanation_pt": "'whether she was the author... or merely its first reader' apresenta alternativas."}], "multiple_choice": [{"question": "What arrived at the publishing house?", "options": ["A bomb", "A letter", "A cheque", "An anonymous manuscript"], "correct_index": 3, "explanation": "Um manuscrito anônimo."}, {"question": "What was unsettling?", "options": ["The house in the novel was hers", "The book was long", "The title was strange", "The author was famous"], "correct_index": 0, "explanation": "A casa era a dela."}, {"question": "What was missing?", "options": ["The title", "The ending chapter only", "The final page", "The first page"], "correct_index": 2, "explanation": "A última página."}, {"question": "What did she hear at the end?", "options": ["A knock", "The creak of the third stair", "A scream", "A phone"], "correct_index": 1, "explanation": "O rangido do terceiro degrau."}, {"question": "What does she wonder?", "options": ["Who sent it", "Whether she wrote her own disappearance", "Where to publish", "What it costs"], "correct_index": 1, "explanation": "Se escreveu o próprio desaparecimento."}], "open_questions": [{"question": "Why are stories that read our lives frightening?", "key_points_pt": ["discutir"]}, {"question": "How can fiction blur with reality?", "key_points_pt": ["explicar"]}]}}, {"level": "C2", "genre": "western", "title": "The Mapmaker of Nowhere", "paragraphs": ["The territorial office in Santa Ruth had received, over the years, a variety of eccentric petitions, but none had perplexed the clerks like that of Silas Penhallow, a former surveyor who requested funding to map a place that, by all accounts, did not exist. He called it \"the Territory of Elsewhere,\" and he maintained, with the serene stubbornness of the unemployable, that every frontier town contained within it a longing for another one.", "Predictably, the petition was denied. Penhallow, undeterred, travelled the plains for eleven years with a mule and a drawing-board, interviewing homesteaders about the place they dreamed of living if they could begin again. A widow described a valley of unfailing springs; a drifter, a town where nobody asked about your past; a child, a prairie where horses could talk. Penhallow recorded each with the scrupulous seriousness of a cartographer.", "The resulting map was a masterpiece of invention: rivers that flowed uphill, mountains with emotional names, a village labelled \"Forgiveness\" beside another labelled \"Not Yet.\" Experts dismissed it as whimsy. Yet when it was displayed in the territorial museum, visitors lingered before it longer than before any real chart, tracing routes they knew they would never travel and recognising, with unsettling accuracy, the contours of their own wishes.", "Penhallow died without recognition, but the map hangs now in a small gallery in Santa Ruth. A plaque beside it quotes his only recorded statement on the matter: \"Every other map shows where people are. This one shows where they are going when they believe nobody is watching.\" Children, naturally, understand it at once."], "paragraphs_pt": ["O escritório territorial de Santa Ruth recebera, ao longo dos anos, uma variedade de petições excêntricas, mas nenhuma deixou os funcionários tão perplexos quanto a de Silas Penhallow, ex-agrimensor que pediu verba para mapear um lugar que, por todos os relatos, não existia. Chamava-o de \"o Território do Alhures\" e sustentava, com a serena teimosia dos inempregáveis, que toda cidade de fronteira continha em si a saudade de outra.", "Previsivelmente, a petição foi negada. Penhallow, sem se abater, percorreu as planícies por onze anos com uma mula e uma prancheta, entrevistando colonos sobre o lugar onde sonhavam viver se pudessem recomeçar. Uma viúva descreveu um vale de nascentes infalíveis; um andarilho, uma cidade onde ninguém perguntava pelo passado; uma criança, uma pradaria onde cavalos falavam. Penhallow registrou cada um com a seriedade escrupulosa de um cartógrafo.", "O mapa resultante foi uma obra-prima de invenção: rios que corriam morro acima, montanhas com nomes emocionais, uma aldeia chamada \"Perdão\" ao lado de outra chamada \"Ainda Não\". Especialistas o dispensaram como capricho. Mas quando foi exposto no museu territorial, os visitantes se demoravam diante dele mais que diante de qualquer carta real, traçando rotas que sabiam que nunca percorreriam e reconhecendo, com precisão inquietante, os contornos dos próprios desejos.", "Penhallow morreu sem reconhecimento, mas o mapa pende hoje numa pequena galeria em Santa Ruth. Uma placa ao lado cita sua única declaração registrada sobre o assunto: \"Todos os outros mapas mostram onde as pessoas estão. Este mostra para onde vão quando acreditam que ninguém está olhando.\" As crianças, naturalmente, entendem na hora."], "hard_words": ["perplexed", "undeterred", "scrupulous", "whimsy"], "vocab": [{"word": "petitions", "meaning": "petições", "note": ""}, {"word": "perplexed", "meaning": "deixou perplexos", "note": ""}, {"word": "serene", "meaning": "serena", "note": ""}, {"word": "undeterred", "meaning": "sem se abater", "note": ""}, {"word": "homesteaders", "meaning": "colonos", "note": ""}, {"word": "scrupulous", "meaning": "escrupulosa", "note": ""}, {"word": "whimsy", "meaning": "capricho", "note": ""}, {"word": "contours", "meaning": "contornos", "note": ""}], "grammar_words": {"cognates": [], "tobe": ["was", "are", "is"], "irregular": ["had", "received", "perplexed", "requested", "did", "called", "maintained", "contained", "denied", "travelled", "dreamed", "could", "described", "asked", "recorded", "flowed", "labelled", "dismissed", "displayed", "lingered", "knew", "would", "died"], "phrasal": ["lingered before", "tracing routes"], "wh": ["who", "where", "when"], "connectors": ["and", "but", "before", "when", "yet", "once", "if", "as"], "comparative": []}, "word_meanings": [{"word": "petitions", "meaning": "petições", "note": ""}, {"word": "perplexed", "meaning": "deixou perplexos", "note": ""}, {"word": "serene", "meaning": "serena", "note": ""}, {"word": "undeterred", "meaning": "sem se abater", "note": ""}, {"word": "homesteaders", "meaning": "colonos", "note": ""}, {"word": "scrupulous", "meaning": "escrupulosa", "note": ""}, {"word": "whimsy", "meaning": "capricho", "note": ""}, {"word": "contours", "meaning": "contornos", "note": ""}], "exercises": {"grammar": [{"point": "By all accounts", "explanation_pt": "'by all accounts, did not exist' significa 'segundo todos os relatos'."}, {"point": "Relative + would", "explanation_pt": "'routes they knew they would never travel' fala de algo que nunca farão."}], "multiple_choice": [{"question": "What did Penhallow request?", "options": ["A land title", "Funding to map a non-existent place", "A school", "A railway"], "correct_index": 1, "explanation": "Verba para mapear um lugar inexistente."}, {"question": "What did he do for eleven years?", "options": ["Taught", "Fought", "Interviewed people about their dream places", "Mined gold"], "correct_index": 2, "explanation": "Entrevistou pessoas."}, {"question": "What was on the map?", "options": ["Real towns", "Gold mines", "Rivers flowing uphill and emotional names", "Railways"], "correct_index": 2, "explanation": "Rios morro acima."}, {"question": "How did visitors react?", "options": ["They ignored it", "They laughed", "They left", "They lingered and recognised their wishes"], "correct_index": 3, "explanation": "Demoravam-se."}, {"question": "What does the plaque say about other maps?", "options": ["They are free", "They are false", "They are old", "They show where people are"], "correct_index": 3, "explanation": "Mostram onde as pessoas estão."}], "open_questions": [{"question": "What would your map of 'Elsewhere' show?", "key_points_pt": ["imaginar"]}, {"question": "Why do people dream of other places?", "key_points_pt": ["discutir"]}]}}];